<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-no-browser-storage">
/* ═══════════════════════════════════════════════════════════════════════
   NO BROWSER STORAGE — SERVER-ONLY (MySQL via api.php)
   Replaces the old "ayan-server-only-storage" partial guard.

   * localStorage and sessionStorage are replaced by NON-CONFIGURABLE
     in-memory shims: every existing read/write in this 60k-line file keeps
     working, but NOTHING is ever written to disk and nothing survives a
     refresh. Because the property descriptors are non-configurable, the
     real storage cannot be restored from DevTools either.
   * IndexedDB is wiped and every further open() is refused, so the old
     mirrors ('AyanERP_IDB', 'ayan_erp_store', 'erp_shards', 'ayan_safety')
     can never resurrect stale data.
   * The MySQL database behind api.php is therefore the single source of
     truth, and the app is online-only by design.
   ═══════════════════════════════════════════════════════════════════════ */
(function () {
  'use strict';
  var W = window;

  /* ── wipe whatever previous builds left on disk ───────────────────── */
  try { W.localStorage && W.localStorage.clear(); } catch (e) {}
  try { W.sessionStorage && W.sessionStorage.clear(); } catch (e) {}

  function memoryStorage(label) {
    var mem = Object.create(null);
    var api = {
      getItem: function (k) { k = String(k); return (k in mem) ? mem[k] : null; },
      setItem: function (k, v) { mem[String(k)] = String(v); },
      removeItem: function (k) { delete mem[String(k)]; },
      clear: function () { mem = Object.create(null); },
      key: function (i) { var ks = Object.keys(mem); return (i >= 0 && i < ks.length) ? ks[i] : null; },
      __memoryOnly: true,
      __label: label
    };
    Object.defineProperty(api, 'length', { get: function () { return Object.keys(mem).length; } });
    return api;
  }

  var lsShim = memoryStorage('localStorage');
  var ssShim = memoryStorage('sessionStorage');

  function lock(name, shim) {
    try {
      Object.defineProperty(W, name, {
        configurable: false,           // DevTools cannot put the real one back
        enumerable: true,
        get: function () { return shim; },
        set: function () { /* assignments are ignored */ }
      });
    } catch (e) {
      try { W[name] = shim; } catch (e2) {}
    }
  }
  lock('localStorage', lsShim);
  lock('sessionStorage', ssShim);

  /* ── IndexedDB: delete the app databases and refuse further opens ─── */
  try {
    var idb = W.indexedDB;
    if (idb) {
      ['AyanERP_IDB', 'ayan_erp_store', 'erp_shards', 'ayan_safety'].forEach(function (n) {
        try { idb.deleteDatabase(n); } catch (e) {}
      });
      var blocked = {
        open: function () {
          var req = { result: null, error: new Error('IndexedDB is disabled (server-only storage)'),
                      onsuccess: null, onerror: null, onupgradeneeded: null, onblocked: null,
                      readyState: 'done', addEventListener: function () {}, removeEventListener: function () {} };
          setTimeout(function () { try { if (typeof req.onerror === 'function') req.onerror({ target: req }); } catch (e) {} }, 0);
          return req;
        },
        deleteDatabase: function () {
          var req = { onsuccess: null, onerror: null };
          setTimeout(function () { try { if (typeof req.onsuccess === 'function') req.onsuccess({ target: req }); } catch (e) {} }, 0);
          return req;
        },
        databases: function () { return Promise.resolve([]); },
        cmp: function (a, b) { return a === b ? 0 : (a > b ? 1 : -1); }
      };
      Object.defineProperty(W, 'indexedDB', { configurable: false, get: function () { return blocked; }, set: function () {} });
    }
  } catch (e) {}

  /* ── online-only: no service-worker/offline caching ───────────────── */
  try {
    if (navigator.serviceWorker && navigator.serviceWorker.getRegistrations) {
      navigator.serviceWorker.getRegistrations().then(function (rs) {
        rs.forEach(function (r) { try { r.unregister(); } catch (e) {} });
      }).catch(function () {});
    }
  } catch (e) {}
  try { if (W.caches && W.caches.keys) W.caches.keys().then(function (ks) { ks.forEach(function (k) { try { W.caches.delete(k); } catch (e) {} }); }).catch(function () {}); } catch (e) {}

  /* ── hard-lock the server configuration (before any other script) ─── */
  var CFG = { USE_SERVER: true, API_URL: 'api.php', DEFAULT_API_URL: 'api.php',
              LOGIN_URL: 'login.php', LOGOUT_URL: 'logout.php', USE_CLOUD: false };
  function lockCfg(o) {
    ['USE_SERVER', 'API_URL', 'DEFAULT_API_URL', 'LOGIN_URL', 'LOGOUT_URL', 'USE_CLOUD'].forEach(function (k) {
      try {
        Object.defineProperty(o, k, { configurable: false, enumerable: true,
          get: function () { return CFG[k]; }, set: function () { /* frozen */ } });
      } catch (e) {}
    });
    return o;
  }
  var cfgObj = lockCfg({});
  try {
    Object.defineProperty(W, 'ERP_CONFIG', {
      configurable: false, enumerable: true,
      get: function () { return cfgObj; },
      set: function () { /* later layers cannot switch the backend off */ }
    });
  } catch (e) { W.ERP_CONFIG = cfgObj; }
  W.ERP_SERVER_MODE = true;
  W.setErpApiUrl = function () { return cfgObj; };   // endpoint is fixed to api.php

  console.info('[server-only] browser storage disabled — all data lives in MySQL via api.php');
})();
</script>
<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-handler-dispatch">
/* ═══════════════════════════════════════════════════════════════════════
   PATCH VULN-03-followup: inline-handler migration, phase 1
   ───────────────────────────────────────────────────────────────────────
   Native onclick/onchange/data-x-input="..." HTML attributes execute under
   script-src-attr, which this app still allows as 'unsafe-inline' (see the
   CSP header comment). To let that be tightened toward 'none', the 1,261
   handler attributes that are plain literal function calls — optionally
   using this/this.value/this.checked — have been renamed in the source
   from on(click|change|input)="fn(args)" to data-x-(click|change|input),
   which the browser never executes automatically. This module replays
   them via one delegated listener per event type, dispatching to the real
   function object (no eval, no new Function — same approach as VULN-10's
   bulk-delete replay, generalized here).

   140 handler attributes were deliberately LEFT AS NATIVE onclick/onchange
   (untouched, still executing the old way) because they are multi-statement
   snippets, reference `event`, or are otherwise not safely representable as
   a single literal call — migrating those requires reading each one
   individually rather than a mechanical rename, so script-src-attr must
   stay 'unsafe-inline' until that follow-up pass is done. Search this file
   for `data-x-click`/`data-x-change`/`data-x-input` vs. plain
   `data-x-click="/"onchange=` to see the split.
   ═══════════════════════════════════════════════════════════════════════ */
(function () {
  'use strict';

  function parseLiteral(tok, el) {
    tok = tok.trim();
    if (tok === '') throw new Error('empty argument');
    if (tok === 'this') return el;
    if (tok === 'this.value') return el.value;
    if (tok === 'this.checked') return el.checked;
    if (tok === 'true') return true;
    if (tok === 'false') return false;
    if (tok === 'null') return null;
    if (tok === 'undefined') return undefined;
    if (/^-?\d+(?:\.\d+)?(?:e-?\d+)?$/i.test(tok)) return Number(tok);
    if ((tok[0] === '"' && tok[tok.length - 1] === '"') ||
        (tok[0] === "'" && tok[tok.length - 1] === "'")) {
      var q = tok[0], body = tok.slice(1, -1), out = '';
      for (var i = 0; i < body.length; i++) {
        if (body[i] === '\\' && i + 1 < body.length) {
          var n = body[++i];
          out += (n === 'n') ? '\n' : (n === 't') ? '\t' :
                 (n === q || n === '\\') ? n : n;
        } else out += body[i];
      }
      return out;
    }
    if ((tok[0] === '[' && tok[tok.length - 1] === ']') ||
        (tok[0] === '{' && tok[tok.length - 1] === '}')) {
      try { return JSON.parse(tok.replace(/'/g, '"')); } catch (e) { /* fall through */ }
    }
    throw new Error('unsupported literal in handler args: ' + tok);
  }
  function parseArgList(src, el) {
    src = src.trim();
    if (!src) return [];
    var args = [], depth = 0, cur = '', inStr = null;
    for (var i = 0; i < src.length; i++) {
      var c = src[i];
      if (inStr) {
        cur += c;
        if (c === '\\' && i + 1 < src.length) { cur += src[++i]; continue; }
        if (c === inStr) inStr = null;
        continue;
      }
      if (c === '"' || c === "'") { inStr = c; cur += c; continue; }
      if (c === '(' || c === '[' || c === '{') { depth++; cur += c; continue; }
      if (c === ')' || c === ']' || c === '}') { depth--; cur += c; continue; }
      if (c === ',' && depth === 0) { args.push(cur); cur = ''; continue; }
      cur += c;
    }
    if (cur.trim() !== '') args.push(cur);
    return args.map(function (t) { return parseLiteral(t, el); });
  }
  function callExprSafely(expr, el) {
    var s = String(expr).trim().replace(/^return\s+/, '').replace(/;+\s*$/, '');
    var m = /^([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\s*\(([\s\S]*)\)$/.exec(s);
    if (!m) throw new Error('unrecognized handler expression: ' + expr);
    var path = m[1].split('.');
    var args = parseArgList(m[2], el);
    var ctx = window, fn = window;
    for (var i = 0; i < path.length; i++) {
      if (fn == null) throw new Error('handler not found: ' + m[1]);
      if (i > 0) ctx = ctx[path[i - 1]];
      fn = fn[path[i]];
    }
    if (typeof fn !== 'function') throw new Error('not a function: ' + m[1]);
    return fn.apply(path.length > 1 ? ctx : window, args);
  }
  window.AyanDispatch = { call: callExprSafely };

  function bind(eventName, attr) {
    document.addEventListener(eventName, function (e) {
      var el = e.target.closest('[' + attr + ']');
      if (!el) return;
      var expr = el.getAttribute(attr);
      try { callExprSafely(expr, el); }
      catch (err) { console.error('[handler-dispatch] ' + eventName + ' failed:', expr, err); }
    }, false);
  }
  bind('click', 'data-x-click');
  bind('change', 'data-x-change');
  bind('input', 'data-x-input');

  console.info('[ayan-handler-dispatch] active — 1,261 inline handlers migrated off script-src-attr.');
})();
</script>
<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-handler-dispatch-repairs">
/* ═══════════════════════════════════════════════════════════════════════
   PATCH 2026-09-13 (session): button-repair pass.
   The VULN-11 migration above only understands a single plain fn(...) call
   with literal/this arguments. A handful of onclick/onchange handlers were
   multi-statement, chained (.then()), nested (document.getElementById(...)
   .value as an argument), or used a ternary — the dispatcher throws
   "unrecognized handler expression" for these and the button silently does
   nothing. Each is wrapped here as one plain function so data-x-click /
   data-x-change can call it directly.
   ═══════════════════════════════════════════════════════════════════════ */
window.btnPrintAgentLedger = function(){ if (window._currentAgentId) printAgentLedger(window._currentAgentId); };
window.applyBrandColorPrimary = function(val){ var acc=document.getElementById('br-accent-color'); applyBrandColor(val, acc?acc.value:''); };
window.applyBrandColorAccent = function(val){ var pri=document.getElementById('br-primary-color'); applyBrandColor(pri?pri.value:'', val); };
window.printStatementModalBtn = function(){ var t=document.getElementById('stmt-title'); printPageViaLetterhead('stmt-body', (t && t.textContent) || 'Statement of Account'); };
window.printPLReportBtn = function(){ var f=document.getElementById('plt-from'), t=document.getElementById('plt-to'); printProfitLossStatement(f?f.value:'', t?t.value:''); };
window.printMonthlyStatementBtn = function(){ var m=document.getElementById('stmt-month'); printMonthlyStatement(m?m.value:''); };
window.requestPushPermissionBtn = function(){ requestPushPermission().then(function(){ renderPushNotificationSettings(); }); };
window.openAddCustomerModalBtn = function(){ var e=document.getElementById('c-edit-id'); if(e) e.value=0; openModal('mCust'); };
window.openAddPartnerModalBtn = function(){ var e=document.getElementById('p-edit-id'); if(e) e.value=0; openModal('mPart'); };
window.printOrdersReportBtn = function(){ printPageViaLetterhead(document.getElementById('pg-orders') ? 'pg-orders' : 'pg-ordermanagement', 'Order Management Report'); };
window.toggleAllPbRows = function(checked){ document.querySelectorAll('#pbm-body .pb-ck').forEach(function(c){ if (c.closest('tr').style.display !== 'none') c.checked = checked; }); };
window.safeCalcDue = function(){ if (typeof calcDue === 'function') calcDue(); };
console.info('[ayan-handler-dispatch-repairs] active — restored buttons broken by the literal-only dispatcher.');

/* ═══════════════════════════════════════════════════════════════════════
   PATCH 2026-09-13 (session, cont'd): second repair pass.
   These handlers used invented data-x-* attributes (data-x-setvar,
   data-x-then, data-x-stop-prop, data-x-overlay-close, data-x-overlay-
   close-fn, data-x-change-native) that the real dispatcher above never
   binds to — so they silently did nothing. Wrapped as flat calls / small
   delegated listeners following the same pattern as the block above.
   ═══════════════════════════════════════════════════════════════════════ */
window.xHubSearchInput = function(val){ window._hubQ = val; renderMenuHub(true); };
window.xBudgetMonthChange = function(val){ window.BUDGET_MONTH = val; renderBudgetVsActual(); };
window.xImportFileChange = function(inp){ handleImportFile({ target: inp }); };
window.xBatchTrackingToggle = function(name, cb){ claudeToggleBatchTracking(name, cb.checked); };
window.xNotifAction = function(el, actionExpr){
  try { window.AyanDispatch.call(actionExpr, el); }
  catch (err) { console.error('[xNotifAction]', err); }
  var box = el.closest('div[style]'); if (box) box.remove();
};
window.xPbmFilter = function(inp){
  var q = (inp.value || '').toLowerCase();
  var tb = document.querySelector('#pbm-body table.pbm-table tbody');
  if (!tb) return;
  Array.prototype.forEach.call(tb.querySelectorAll('tr'), function(r){
    r.style.display = r.textContent.toLowerCase().indexOf(q) !== -1 ? '' : 'none';
  });
};

/* data-x-stop-prop: replacement for onclick="event.stopPropagation()" on
   modal content, which can't be a flat call (the dispatcher never passes
   `event`). Runs in the capture phase so it suppresses the click before it
   can bubble back up to the overlay-close listeners below. */
document.addEventListener('click', function (e) {
  if (e.target.closest('[data-x-stop-prop]')) e.stopPropagation();
}, true);

/* data-x-overlay-close="fnName" data-target="id": click directly on the
   backdrop (not a descendant) calls window[fnName](target). Target-equality
   check makes this safe even without a data-x-stop-prop child. */
document.addEventListener('click', function (e) {
  var el = e.target.closest('[data-x-overlay-close]');
  if (!el || e.target !== el) return;
  var fn = window[el.getAttribute('data-x-overlay-close')];
  if (typeof fn === 'function') fn(el.dataset.target);
}, false);

/* data-x-overlay-close-fn="path.to.fn": same idea, but the function path
   may be dotted (e.g. "PB.close"), so route it through the existing safe
   call helper instead of a plain window[] lookup. */
document.addEventListener('click', function (e) {
  var el = e.target.closest('[data-x-overlay-close-fn]');
  if (!el || e.target !== el) return;
  try { window.AyanDispatch.call(el.getAttribute('data-x-overlay-close-fn') + '()', el); }
  catch (err) { console.error('[overlay-close-fn]', err); }
}, false);
console.info('[ayan-handler-dispatch-repairs] overlay-close / stop-prop / filter handlers bound.');
</script>
<script id="ayan-config" nonce="<?php echo $cspNonceAttr; ?>">
/* CSP/compat helper: base64-encode a UTF-8 string without the legacy unescape API */
function utf8ToBase64(s){ const b=new TextEncoder().encode(String(s)); return btoa(Array.from(b,function(x){return String.fromCharCode(x);}).join('')); }
/* ═══════════════════════════════════════════════════════════════════════
   CONFIG: Centralized Constants (2026-08-28)

   Replaces magic numbers scattered throughout the code with named constants.
   Makes thresholds, timeouts, and colors configurable in one place.
   ═══════════════════════════════════════════════════════════════════ */
window.CONFIG = window.CONFIG || {
  // Business logic thresholds
  APPROVAL_THRESHOLD: 500000,      // ৳5,00,000 high-value transaction limit

  // Timing (in milliseconds)
  POLL_INTERVAL: 10000,             // 10 seconds - polling frequency
  SAVE_DEBOUNCE: 400,               // 400ms - save coalescing window
  APPROVAL_UNLOAD_CHECK: 100,       // Safety net polling
  PRINT_DELAY: 500,                 // Print document delay
  RENDER_BATCH_DELAY: 150,          // requestAnimationFrame delay

  // Colors (used in rendering)
  COLORS: {
    pending: '#f59e0b',    // Amber
    error: '#dc2626',      // Red
    success: '#16a34a',    // Green
    info: '#2563eb',       // Blue
    warning: '#ea580c'     // Orange
  },

  // String constants
  TX_STATUS: {
    PENDING: 'Pending',
    APPROVED: 'Approved',
    REJECTED: 'Rejected'
  }
};

/* ═══════════════════════════════════════════════════════════════════════
   BATCH RENDER: requestAnimationFrame Queue (2026-08-28)

   Replaces multiple setTimeout calls with batched requestAnimationFrame.
   Benefits: Single paint operation, smooth 60fps, better mobile battery life.
   ═══════════════════════════════════════════════════════════════════ */
/* PATCH REC-04: BatchRender queue depth cap added.
   If a render function throws and inadvertently re-queues itself, the old
   implementation would grow the queue without bound. The cap (200 items)
   drops excess work and logs a warning rather than hanging the browser. */
window.BatchRender = window.BatchRender || {
  queue: [],
  scheduled: false,
  MAX_QUEUE: 200,   // REC-04: cap prevents unbounded growth on error loops

  /**
   * Queue rendering functions to execute in next animation frame.
   * Multiple calls coalesce into a single paint cycle.
   * @param {...Function} fns - Functions to call on next frame
   */
  add(...fns) {
    // REC-04: enforce depth cap
    if (this.queue.length + fns.length > this.MAX_QUEUE) {
      console.warn('[BatchRender] Queue depth cap reached (' + this.MAX_QUEUE + ') — dropping ' + fns.length + ' item(s). Check for render loops.');
      return;
    }
    this.queue.push(...fns);
    if (!this.scheduled) {
      this.scheduled = true;
      requestAnimationFrame(() => this.flush());
    }
  },

  /**
   * Execute all queued functions and clear the queue.
   */
  flush() {
    try {
      this.queue.forEach(fn => {
        try { if (typeof fn === 'function') fn(); } catch(e) {
          console.error('[BatchRender Error]', e);
        }
      });
    } finally {
      this.queue = [];
      this.scheduled = false;
    }
  }
};

/* ═══════════════════════════════════════════════════════════════════════
   INPUT VALIDATION HELPERS (2026-08-28)

   Centralized validation for common fields: phone, amount, date.
   Bangladeshi phone format: 11 digits (01XXXXXXXXX).
   ═══════════════════════════════════════════════════════════════════ */
window.Validators = window.Validators || {
  /**
   * Validates a Bangladeshi phone number.
   * Accepts: 01712345678, +8801712345678, 8801712345678
   * @param {string} phone - Phone number to validate
   * @returns {boolean} True if valid Bangladesh phone
   */
  validatePhone(phone) {
    if (!phone) return false;
    const bdPhone = /^(?:\+880|880|0)?1[0-9]{9}$/;
    const cleaned = String(phone).replace(/\D/g, '');
    return bdPhone.test(cleaned) || /^1[0-9]{9}$/.test(cleaned);
  },

  /**
   * Formats a phone number to standard format: 01XXXXXXXXX
   * @param {string} phone - Phone number to format
   * @returns {string} Formatted phone number
   */
  formatPhone(phone) {
    if (!phone) return '';
    const cleaned = String(phone).replace(/\D/g, '');
    if (cleaned.length === 10) return '0' + cleaned;
    if (cleaned.length === 11) return cleaned;
    if (cleaned.length === 12 && cleaned.startsWith('88')) {
      return '0' + cleaned.slice(2);
    }
    return phone;
  },

  /**
   * Validates transaction amount.
   * @param {number} amount - Amount to validate
   * @returns {boolean} True if valid amount (positive, not too large)
   */
  validateAmount(amount) {
    const num = Number(amount);
    return !isNaN(num) && num > 0 && num < 9999999999;
  },

  /**
   * Validates date in YYYY-MM-DD format.
   * PATCH REC-06: previous version accepted invalid dates like 2023-02-29
   * because new Date('2023-02-29') silently rolls over to 2023-03-01 and
   * returns a valid Date object. Now the parsed date is round-tripped back
   * to its UTC components and compared against the original string to catch
   * any month/day overflow (including leap-year violations).
   * @param {string} dateStr - Date string to validate
   * @returns {boolean} True if valid calendar date
   */
  validateDate(dateStr) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) return false;
    // Parse as UTC midnight to avoid timezone-induced day shifts
    const date = new Date(dateStr + 'T00:00:00Z');
    if (isNaN(date)) return false;
    // Round-trip check: if the date rolled over, the UTC components won't match
    const [y, m, d] = dateStr.split('-').map(Number);
    return date.getUTCFullYear() === y
        && (date.getUTCMonth() + 1) === m
        && date.getUTCDate()        === d;
  }
};

/* ═══════════════════════════════════════════════════════════════════════
   DOM SAFETY HELPERS (2026-08-28)

   Safe wrappers for DOM operations to prevent null reference crashes.
   ═══════════════════════════════════════════════════════════════════ */
window.DOMUtils = window.DOMUtils || {
  /**
   * Safely set innerHTML on an element.
   * @param {string|Element} selector - Element ID or DOM element
   * @param {string} html - HTML to set
   * @returns {boolean} True if successful
   */
  safeSetHTML(selector, html) {
    try {
      const el = typeof selector === 'string'
        ? document.getElementById(selector)
        : selector;
      if (!el) {
        console.warn('[DOMUtils] Element not found:', selector);
        return false;
      }
      el.innerHTML = html;
      return true;
    } catch (err) {
      console.error('[DOMUtils] Failed to set HTML:', err);
      return false;
    }
  },

  /**
   * Safely set text content on an element.
   * @param {string|Element} selector - Element ID or DOM element
   * @param {string} text - Text to set
   * @returns {boolean} True if successful
   */
  safeSetText(selector, text) {
    try {
      const el = typeof selector === 'string'
        ? document.getElementById(selector)
        : selector;
      if (!el) {
        console.warn('[DOMUtils] Element not found:', selector);
        return false;
      }
      el.textContent = text;
      return true;
    } catch (err) {
      console.error('[DOMUtils] Failed to set text:', err);
      return false;
    }
  },

  /**
   * Safely add/remove a CSS class.
   * @param {string|Element} selector - Element ID or DOM element
   * @param {string} className - Class name to toggle
   * @param {boolean} add - True to add, false to remove, undefined to toggle
   * @returns {boolean} True if successful
   */
  toggleClass(selector, className, add) {
    try {
      const el = typeof selector === 'string'
        ? document.getElementById(selector)
        : selector;
      if (!el) return false;

      if (add === undefined) {
        el.classList.toggle(className);
      } else if (add) {
        el.classList.add(className);
      } else {
        el.classList.remove(className);
      }
      return true;
    } catch (err) {
      console.error('[DOMUtils] Failed to toggle class:', err);
      return false;
    }
  }
};

/* ═══════════════════════════════════════════════════════════════════════
   CENTRALIZED ERROR HANDLER (2026-08-28)

   Unified error handling for consistent user feedback and logging.
   ═══════════════════════════════════════════════════════════════════ */
window.ErrorHandler = window.ErrorHandler || {
  USER_ERRORS: {
    NOT_FOUND: 'Record not found',
    PERMISSION_DENIED: 'You do not have permission for this action',
    INVALID_INPUT: 'Please check your input',
    SAVE_FAILED: 'Save failed. Check your connection and try again.',
    VALIDATION_FAILED: 'Please fix the errors below',
    OPERATION_FAILED: 'Operation failed. Please try again.'
  },

  /**
   * Handle an error with logging and user notification.
   * @param {Error|Object|string} error - Error object or message
   * @param {string} context - Operation context for logging
   */
  handle(error, context = '') {
    const message = typeof error === 'string'
      ? error
      : error?.message || error?.code;

    // Log for debugging
    console.error('[ERROR]', context, error);

    // Show to user
    if (error?.code === 'PERMISSION_DENIED') {
      if (typeof toast === 'function') {
        toast(this.USER_ERRORS.PERMISSION_DENIED, 'e');
      }
    } else if (error?.code === 'NOT_FOUND') {
      if (typeof toast === 'function') {
        toast(this.USER_ERRORS.NOT_FOUND, 'e');
      }
    } else if (error?.code === 'VALIDATION_FAILED') {
      if (typeof toast === 'function') {
        toast(this.USER_ERRORS.VALIDATION_FAILED, 'e');
      }
    } else {
      if (typeof toast === 'function') {
        toast(message || this.USER_ERRORS.OPERATION_FAILED, 'e');
      }
    }
  }
};
</script>

<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-maker-checker">
/* ═══════════════════════════════════════════════════════════════════════
   MAKER-CHECKER: separation of duties (2026-08-29)

   Rule: the person who ENTERS a transaction/order/expense may not be the
   person who APPROVES it. Approval authority itself is unchanged — it is
   still Admin-only, via isTopApprover().

   Because this deployment has a single Admin account, a strict block would
   deadlock the ledger: an Admin's own entries could never be posted. So a
   self-approval is not forbidden outright — it is BREAK-GLASS. It requires
   an explicit confirmation plus a written reason, and it leaves three
   permanent traces: a flag on the record itself (selfApproved), an entry in
   DB.approvalLog, and a SELF_APPROVE_OVERRIDE row in the audit log.

   The point is that a self-approval can no longer happen silently. Before
   this, an Admin's entry was stamped 'Approved' at save time and posted to
   the balance with nothing recorded anywhere.

   ⚠ THIS IS CLIENT-SIDE ONLY. The browser is not a trust boundary — anyone
   who can open devtools can bypass every check in this file. The same rule
   MUST be enforced in api.php against the server-side session before it can
   be called an actual control. See _serverGuardContract() at the bottom for
   the exact shape the backend needs to reject.
   ═══════════════════════════════════════════════════════════════════ */
window.MakerChecker = (function(){
  'use strict';

  function norm(v){ return String(v == null ? '' : v).trim().toLowerCase(); }

  /* Who is acting right now. Read fresh every call — currentUser is
     replaced wholesale on login/logout/user-edit. */
  function actor(){
    var u = window.currentUser || {};
    return {
      id:       u.id != null ? String(u.id) : '',
      username: u.username || '',
      name:     u.name || '',
      role:     u.role || ''
    };
  }

  /* Stamp maker identity onto a new record. Called at every creation site.
     Records the id and username as well as the display name: names are
     editable in User Management, so a name-only match would break the
     moment somebody is renamed. enteredBy/enteredRole keep their existing
     meaning so nothing that already reads them changes behaviour. */
  function stamp(rec){
    if(!rec) return rec;
    var a = actor();
    if(!rec.enteredBy)       rec.enteredBy       = a.name;
    if(!rec.enteredRole)     rec.enteredRole     = a.role;
    if(!rec.makerUserId)     rec.makerUserId     = a.id;
    if(!rec.makerUsername)   rec.makerUsername   = a.username;
    if(!rec.makerAt)         rec.makerAt         = new Date().toISOString();
    return rec;
  }

  /* Does this record's maker resolve to the current user?

     Matched most-reliable-first. Falls back to display name so that rows
     created BEFORE this patch — which carry enteredBy and nothing else —
     are still caught rather than sailing through unchecked. */
  function isSelf(rec){
    if(!rec) return false;
    var a = actor();
    var mname = rec.enteredBy || rec.submittedBy;
    /* ANY field matching means self — deliberately not first-field-wins.
       There are three user-id namespaces in this deployment: MySQL users.id
       (1787197831995...), the DB.users list in the blob ('u-admin'), and the
       legacy erp_appdata copy. Which one lands in currentUser.id depends on
       the login path — aclLoginAs() and the offline login both assign a
       DB.users record wholesale, while a normal server login assigns the
       MySQL row. First-field-wins would compare 'u-admin' against
       '1787197831995', conclude 'not the same person', and wave a
       self-approval straight through — failing silently, in the unsafe
       direction. Usernames agree across all three stores, so checking every
       field catches it. The cost of a false match is one extra override
       prompt; the cost of a false miss is the rule not existing. */
    if(rec.makerUserId && a.id       && String(rec.makerUserId) === a.id)      return true;
    if(rec.makerUsername && a.username && norm(rec.makerUsername) === norm(a.username)) return true;
    if(mname && a.name && norm(mname) === norm(a.name))                        return true;
    return false; /* unattributed legacy row — cannot prove self-approval */
  }

  function makerLabel(rec){
    if(!rec) return 'someone unknown';
    return rec.enteredBy || rec.makerUsername || rec.submittedBy || 'someone unknown';
  }

  /* ── PATCH VULN-03: AyanModal — Promise-based confirm + prompt replacement ──
     Eliminates native browser prompt()/confirm() which:
       1. Are synchronous and block the JS thread.
       2. Cannot be themed or pre-validated.
       3. Bypass CSP (OS-level dialogs, not DOM injections).
       4. Made the `await confirm(msg)` call a no-op (awaiting a boolean).
     AyanModal is installed as window.__confirm and window.__prompt so that
     any other call site in the application using those overrides also
     benefits automatically. All user-supplied strings are set via .textContent
     — never via innerHTML — so AyanModal itself introduces no XSS surface. */
  (function installAyanModal() {
    'use strict';

    /* Inject keyframe animations once */
    if (!document.getElementById('ayan-modal-styles')) {
      var styleEl = document.createElement('style');
      styleEl.id = 'ayan-modal-styles';
      styleEl.textContent = [
        '@keyframes ayan-fade-in  { from{opacity:0} to{opacity:1} }',
        '@keyframes ayan-slide-up { from{opacity:0;transform:translateY(14px)} to{opacity:1;transform:translateY(0)} }',
        '#ayan-modal-root *:focus { outline:2px solid #2563eb; outline-offset:2px; }'
      ].join('\n');
      (document.head || document.documentElement).appendChild(styleEl);
    }

    function getRoot() {
      var r = document.getElementById('ayan-modal-root');
      if (!r) {
        r = document.createElement('div');
        r.id = 'ayan-modal-root';
        r.setAttribute('aria-live', 'assertive');
        document.body.appendChild(r);
      }
      return r;
    }

    function makeOverlay() {
      var o = document.createElement('div');
      o.style.cssText = [
        'position:fixed;inset:0;z-index:99999',
        'background:rgba(15,23,42,0.65)',
        'display:flex;align-items:center;justify-content:center',
        'backdrop-filter:blur(2px)',
        'animation:ayan-fade-in 130ms ease'
      ].join(';');
      o.setAttribute('role', 'dialog');
      o.setAttribute('aria-modal', 'true');
      return o;
    }

    function makeCard() {
      var c = document.createElement('div');
      c.style.cssText = [
        'background:#fff;border-radius:12px;padding:28px 30px 24px',
        'max-width:490px;width:90vw',
        'box-shadow:0 20px 60px rgba(0,0,0,.28)',
        'font-family:system-ui,-apple-system,sans-serif',
        'animation:ayan-slide-up 160ms ease'
      ].join(';');
      return c;
    }

    function makeBtn(label, primary) {
      var b = document.createElement('button');
      b.type = 'button';
      b.textContent = label;
      b.style.cssText = primary
        ? 'padding:9px 22px;border:none;border-radius:7px;background:#b45309;color:#fff;font-size:14px;font-weight:600;cursor:pointer;min-width:80px'
        : 'padding:9px 22px;border:1.5px solid #cbd5e1;border-radius:7px;background:#f8fafc;color:#475569;font-size:14px;font-weight:600;cursor:pointer;min-width:80px';
      return b;
    }

    /* confirm(message) → Promise<boolean> */
    function ayanConfirm(message) {
      return new Promise(function(resolve) {
        var overlay = makeOverlay();
        var card    = makeCard();

        var icon = document.createElement('div');
        icon.textContent = '\u26a0\ufe0f';
        icon.style.cssText = 'font-size:30px;margin-bottom:10px';

        var msg = document.createElement('p');
        msg.style.cssText = 'margin:0 0 22px;font-size:15px;line-height:1.55;color:#1e293b;white-space:pre-wrap';
        msg.textContent = message; // SAFE: textContent, never innerHTML

        var row = document.createElement('div');
        row.style.cssText = 'display:flex;gap:10px;justify-content:flex-end';

        var cancel = makeBtn('Cancel',  false);
        var ok     = makeBtn('Proceed with Override', true);
        ok.style.background = '#b45309';

        row.appendChild(cancel);
        row.appendChild(ok);
        card.appendChild(icon);
        card.appendChild(msg);
        card.appendChild(row);
        overlay.appendChild(card);
        getRoot().appendChild(overlay);

        function done(result) { overlay.remove(); resolve(result); }
        cancel.addEventListener('click', function() { done(false); });
        ok.addEventListener('click',     function() { done(true);  });
        overlay.addEventListener('keydown', function(e) {
          if (e.key === 'Escape') { e.preventDefault(); done(false); }
          if (e.key === 'Enter')  { e.preventDefault(); done(true);  }
        });
        overlay.setAttribute('tabindex', '-1');
        setTimeout(function() { try { overlay.focus(); } catch(e) {} }, 30);
      });
    }

    /* prompt(message, placeholder?) → Promise<string|null> */
    function ayanPrompt(message, placeholder) {
      return new Promise(function(resolve) {
        var overlay = makeOverlay();
        var card    = makeCard();
        overlay.setAttribute('aria-label', 'Enter reason');

        var msg = document.createElement('p');
        msg.style.cssText = 'margin:0 0 12px;font-size:15px;line-height:1.55;color:#1e293b;white-space:pre-wrap';
        msg.textContent = message; // SAFE

        var textarea = document.createElement('textarea');
        textarea.rows = 3;
        textarea.maxLength = 500;
        textarea.style.cssText = [
          'width:100%;box-sizing:border-box;padding:10px 12px',
          'border:1.5px solid #cbd5e1;border-radius:7px',
          'font-size:14px;resize:vertical;font-family:inherit'
        ].join(';');
        if (placeholder) textarea.placeholder = placeholder;

        var errEl = document.createElement('div');
        errEl.style.cssText = 'color:#dc2626;font-size:12px;margin-top:4px;min-height:16px';
        errEl.setAttribute('role', 'alert');

        var charCount = document.createElement('div');
        charCount.style.cssText = 'font-size:11px;color:#94a3b8;text-align:right;margin-top:2px';
        charCount.textContent = '0 / 500';
        textarea.addEventListener('input', function() {
          charCount.textContent = textarea.value.length + ' / 500';
        });

        var row = document.createElement('div');
        row.style.cssText = 'display:flex;gap:10px;justify-content:flex-end;margin-top:16px';

        var cancel = makeBtn('Cancel', false);
        var submit = makeBtn('Submit Reason', true);
        submit.style.background = '#16a34a';

        row.appendChild(cancel);
        row.appendChild(submit);
        card.appendChild(msg);
        card.appendChild(textarea);
        card.appendChild(errEl);
        card.appendChild(charCount);
        card.appendChild(row);
        overlay.appendChild(card);
        getRoot().appendChild(overlay);

        function done(value) { overlay.remove(); resolve(value); }

        cancel.addEventListener('click', function() { done(null); });
        submit.addEventListener('click', function() {
          var val = textarea.value.trim();
          if (!val) {
            errEl.textContent = 'A written reason is required before you can proceed.';
            textarea.focus();
            return;
          }
          done(val);
        });
        overlay.addEventListener('keydown', function(e) {
          if (e.key === 'Escape') { e.preventDefault(); done(null); }
        });
        setTimeout(function() { try { textarea.focus(); } catch(e) {} }, 30);
      });
    }

    window.AyanModal    = { confirm: ayanConfirm, prompt: ayanPrompt };
    window.__confirm    = ayanConfirm;   // gate() and any other call site uses this
    window.__prompt     = ayanPrompt;

    console.info('[AyanModal] installed — native prompt()/confirm() replaced');
  })();

  /* ── ONE-CLICK SELF-APPROVAL ─────────────────────────────────────────────
     Single-admin businesses: if only one Admin account is active, the owner
     IS the only approver, so every transaction he enters must be self-approved.
     One-click mode keeps the full audit trail (selfApproved, selfApprovalReason,
     approvalLog, SELF_APPROVE_OVERRIDE) but removes the repeated typing.
     A second Admin account automatically restores the full confirm+reason flow.
     Force either mode by setting DB.settings.selfApproveOneClick = true/false. */
  function soleApprover() {
    try {
      var users  = (window.DB && window.DB.users) || [];
      var admins = users.filter(function(u) {
        return u && String(u.role  || '').toLowerCase() === 'admin'
                 && String(u.status || 'Active').toLowerCase() !== 'inactive';
      });
      return admins.length <= 1;
    } catch(e) { return true; }
  }

  function oneClickAllowed() {
    try {
      var s = (window.DB && window.DB.settings) || {};
      if (s.selfApproveOneClick === true)  return true;
      if (s.selfApproveOneClick === false) return false;
    } catch(e) {}
    return soleApprover();
  }
  window.__mcOneClickAllowed = oneClickAllowed;

  /* gate(rec, label) → Promise<{ok, override, reason}>
     PATCH VULN-03: fully async — both confirm and prompt are now true
     Promises (AyanModal), so the await calls are meaningful and the
     function correctly suspends while the modal is open. */
  async function gate(rec, label) {
    label = label || 'record';
    if (!rec) return { ok: false };
    if (!isSelf(rec)) return { ok: true, override: false, reason: '' };

    if (oneClickAllowed()) {
      return {
        ok: true, override: true,
        reason: 'Single-approver business \u2014 the owner is the only Admin, '
               + 'so entry and approval are the same person by necessity. '
               + 'One-click self-approval is enabled (DB.settings.selfApproveOneClick).'
      };
    }

    var msg = '\u26a0\ufe0f SELF-AUTHORIZATION\n\n'
      + 'This ' + label + ' was entered by ' + makerLabel(rec) + ' \u2014 that is you.\n\n'
      + 'Separation of duties means someone else should approve it. You can '
      + 'override that, but the override is written permanently into the audit '
      + 'log and stays flagged on the record.\n\n'
      + 'Continue with an override?';

    /* PATCH VULN-03: always use AyanModal.confirm — never fall back to the
       native confirm() which is synchronous and OS-styled. */
    var confirmed = false;
    try {
      confirmed = await window.AyanModal.confirm(msg);
    } catch(e) { confirmed = false; }
    if (!confirmed) return { ok: false };

    /* PATCH VULN-03: always use AyanModal.prompt — never fall back to the
       native prompt() which cannot carry validation or custom styling. */
    var reason = null;
    try {
      reason = await window.AyanModal.prompt(
        'Reason for the self-authorization override (required):',
        'e.g. Only Admin on duty; no other approver available today'
      );
    } catch(e) { reason = null; }
    if (reason === null) return { ok: false };
    reason = String(reason).trim();
    if (!reason) {
      try { window.toast('An override needs a written reason \u2014 nothing was approved', 'e'); } catch(e) {}
      return { ok: false };
    }
    return { ok: true, override: true, reason: reason };
  }

  /* Write the three traces. Called only after gate() returned override:true. */
  function recordOverride(rec, label, reason){
    var a = actor();
    var stampObj = {
      selfApproved: true,
      selfApprovalReason: reason,
      selfApprovedBy: a.name || a.username,
      selfApprovedAt: new Date().toISOString()
    };
    if(rec) for(var k in stampObj) rec[k] = stampObj[k];

    try {
      if(!window.DB.approvalLog) window.DB.approvalLog = [];
      window.DB.approvalLog.unshift({
        id: rec && rec.id,
        action: 'Self-approved (override)',
        reason: reason,
        maker: makerLabel(rec),
        approver: a.name || a.username,
        date: new Date().toISOString().split('T')[0],
        ts: Date.now()
      });
    } catch(e){}

    try {
      if(typeof window.logAudit === 'function'){
        window.logAudit(
          'SELF_APPROVE_OVERRIDE',
          label,
          'Approved own ' + label + ' #' + (rec && rec.id) +
          ' (' + ((rec && rec.type) || (rec && rec.customerName) || '') + ') \u2014 reason: ' + reason,
          { recordId: rec && rec.id, maker: makerLabel(rec), reason: reason }
        );
      }
    } catch(e){}
  }

  /* Badge for any list/table that wants to show the maker.
     PATCH VULN-02: returns a real DOM <span> node instead of an HTML string so
     that username/maker values are always set via .title and .textContent —
     never via string concatenation into innerHTML — eliminating the title-
     attribute XSS vector.
     Call sites:
       • el.appendChild(MakerChecker.makerBadge(rec))       ← preferred
       • el.insertBefore(MakerChecker.makerBadge(rec), ref)  ← also fine
     Sites that previously did  el.innerHTML += makerBadge(rec)  must switch to
     appendChild. The old string path is preserved as makerBadgeHTML() for any
     site that cannot be migrated immediately — it is clearly marked unsafe. */
  function makerBadge(rec) {
    if (!rec) return document.createTextNode('');
    var who  = makerLabel(rec);
    var self = isSelf(rec);
    var span = document.createElement('span');
    // .title assignment: browser handles all escaping automatically
    span.title = self
      ? 'You entered this \u2014 approving it needs an override'
      : 'Entered by ' + who;
    span.style.cssText =
      'font-size:10px;padding:1px 6px;border-radius:6px;font-weight:700;' +
      (self ? 'background:#fef3c7;color:#b45309;' : 'background:#f3f4f6;color:#6b7280;');
    // .textContent assignment: XSS-safe by definition
    span.textContent = self ? '\u26a0\ufe0f you' : who;
    return span;
  }

  /* makerBadgeHTML: legacy string form for call sites not yet migrated to DOM.
     UNSAFE — caller must ensure the return value lands in a trusted innerHTML
     context, never in a context that re-encodes or evaluates the string. */
  function makerBadgeHTML(rec) {
    if (!rec) return '';
    var who  = makerLabel(rec);
    var esc  = (typeof window.escHTML === 'function') ? window.escHTML : function(x) { return String(x); };
    var self = isSelf(rec);
    return '<span title="' + esc(self
        ? 'You entered this \u2014 approving it needs an override'
        : 'Entered by ' + who) + '" '
      + 'style="font-size:10px;padding:1px 6px;border-radius:6px;font-weight:700;'
      + (self ? 'background:#fef3c7;color:#b45309;' : 'background:#f3f4f6;color:#6b7280;') + '">'
      + (self ? '\u26a0\ufe0f you' : esc(who)) + '</span>';
  }

  /* ── PATCH VULN-04: _serverGuardContract — now verified at login ────────────
     Previously this function returned a plain object that was never consumed
     programmatically — pure documentation with no runtime enforcement.

     Now:
       1. The contract object is the same shape (api.php can validate the
          fields/rules it receives).
       2. verifyMCContract() POSTs it to api.php?action=mc_contract_check
          immediately after the admin session is confirmed. If api.php has not
          implemented the corresponding check it should return {ok:false} and
          the client will log a visible warning so the divergence is caught
          during QA, not silently in production.
       3. verifyMCContract() is exported and should be called from the login
          success handler:
            window.MakerChecker.verifyMCContract();

     api.php contract (to be implemented server-side):
       POST api.php?action=mc_contract_check
       Body: { makerFields, approverSource, rejectWhen, mustPersist }
       → { ok: true }                    — server confirms it enforces the rule
       → { ok: false, reason: string }   — mismatch; client logs a warning
     ─────────────────────────────────────────────────────────────────────── */
  function _serverGuardContract() {
    return {
      version:        1,
      makerFields:    ['makerUserId', 'makerUsername', 'enteredBy'],
      approverSource: 'PHP session user (never a client-supplied field)',
      rejectWhen:     'maker === session user && no overrideReason supplied',
      mustPersist:    ['selfApproved', 'selfApprovalReason', 'selfApprovedBy', 'selfApprovedAt']
    };
  }

  /* Call once after login — non-blocking, never throws into the app. */
  async function verifyMCContract() {
    try {
      var contract = _serverGuardContract();
      var apiBase  = (window.ERP_CONFIG && window.ERP_CONFIG.API_URL) || 'api.php';
      var headers = { 'Content-Type': 'application/json', 'Accept': 'application/json' };

      var res  = await fetch(apiBase + '?action=mc_contract_check', {
        method: 'POST', credentials: 'include',
        headers: headers,
        body: JSON.stringify({ contract: contract })
      });
      var data = await res.json().catch(function() { return {}; });

      if (!data.ok) {
        var reason = data.reason || 'no reason returned';
        console.error('[MakerChecker] Server contract mismatch:', reason, contract);
        try {
          window.toast && window.toast(
            '\u26a0\ufe0f Approval policy mismatch with server \u2014 contact administrator. (' + reason + ')',
            'e'
          );
        } catch(e) {}
      } else {
        console.info('[MakerChecker] Server contract verified \u2714');
      }
    } catch(e) {
      // Non-blocking: network error or endpoint not yet deployed
      console.warn('[MakerChecker] Contract check could not reach server:', e.message);
    }
  }

  return {
    actor:               actor,
    stamp:               stamp,
    isSelf:              isSelf,
    makerLabel:          makerLabel,
    makerBadge:          makerBadge,          // returns DOM node (VULN-02 fix)
    makerBadgeHTML:      makerBadgeHTML,      // legacy string form — marked unsafe
    gate:                gate,
    recordOverride:      recordOverride,
    _serverGuardContract: _serverGuardContract,
    verifyMCContract:    verifyMCContract     // VULN-04: call after login
  };
})();
</script>
<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-xss-guard">
/* ── PATCH VULN-08 + VULN-07: hardened escaping helpers ─────────────────────
   VULN-08: escHTML now escapes single-quote (&#x27;) in addition to the
   original four entities. The previous version was safe for double-quoted
   HTML attributes but would break out of single-quoted ones and CSS
   content: properties. The fix is additive and backward-compatible.

   VULN-07: safeSetHTML is renamed unsafeSetHTML to make the risk visible at
   every call site. A new safeSetHTML wrapper uses the browser Sanitizer API
   (Chrome 105+, Firefox 135+) with a DOMParser strip-tags fallback.
   Call sites that genuinely need raw trusted HTML should call unsafeSetHTML
   explicitly; those that accept user data must use safeSetHTML.
   ─────────────────────────────────────────────────────────────────────────── */

/* escHTML: escape plain text for interpolation into innerHTML strings.
   NEVER apply to variables that already hold pre-built HTML fragments. */
window.escHTML = function(s) {
  return String(s == null ? '' : s)
    .replace(/&/g,  '&amp;')
    .replace(/</g,  '&lt;')
    .replace(/>/g,  '&gt;')
    .replace(/"/g,  '&quot;')
    .replace(/'/g,  '&#x27;');  // VULN-08 fix: single-quote now escaped
};

/* escJSAttr: for values placed inside an inline event handler attribute as a
   single-quoted JS string literal, e.g. data-x-click="fn('${escJSAttr(x.name)}')".
   Order is critical: JS-string escape first (\ then '), THEN HTML-escape so
   the result survives sitting inside the double-quoted attribute. */
window.escJSAttr = function(s) {
  return window.escHTML(
    String(s == null ? '' : s)
      .replace(/\\/g, '\\\\')
      .replace(/'/g,  "\\'")
  );
};

/* safeSetHTML: sanitizes HTML before insertion. Uses browser Sanitizer API
   where available, falls back to DOMParser script-strip. Use for any HTML
   that may contain user-derived content. */
window.safeSetHTML = function(el, html) {
  var node = typeof el === 'string' ? document.getElementById(el) : el;
  if (!node) { console.warn('[safeSetHTML] element not found:', el); return false; }
  try {
    if (typeof window.Sanitizer === 'function') {
      // Sanitizer API — Chrome 105+, Firefox 135+
      node.setHTML(html, new Sanitizer());
    } else {
      // Fallback: DOMParser strip dangerous tags
      var doc = new DOMParser().parseFromString(html, 'text/html');
      doc.querySelectorAll(
        'script,iframe,object,embed,link[rel="import"],base,meta,form'
      ).forEach(function(n) { n.remove(); });
      // Strip all on* event-handler attributes
      doc.querySelectorAll('*').forEach(function(n) {
        Array.from(n.attributes).forEach(function(attr) {
          if (/^on/i.test(attr.name)) n.removeAttribute(attr.name);
        });
      });
      node.innerHTML = doc.body.innerHTML;
    }
    return true;
  } catch(err) {
    console.error('[safeSetHTML] failed:', err);
    return false;
  }
};

/* unsafeSetHTML: raw innerHTML assignment — use ONLY for author-controlled
   HTML (pre-built table rows, layout templates). Never pass user data here. */
window.unsafeSetHTML = function(el, html) {
  var node = typeof el === 'string' ? document.getElementById(el) : el;
  if (!node) { console.warn('[unsafeSetHTML] element not found:', el); return false; }
  try { node.innerHTML = html; return true; } catch(err) { return false; }
};

/* Patch DOMUtils to use the hardened versions */
if (window.DOMUtils) {
  window.DOMUtils.safeSetHTML    = function(sel, html) { return window.safeSetHTML(sel, html); };
  window.DOMUtils.unsafeSetHTML  = function(sel, html) { return window.unsafeSetHTML(sel, html); };
}
</script>
<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-money-direction">
/* ═══════════════════════════════════════════════════════════════════════
   SHARED MONEY DIRECTION  (fix pack, 2026-08-22)

   Several independent parts of the app had to answer the same question —
   "does this transaction put money INTO the bank or take it OUT?" — and
   each kept its own private list. Anything missing from a list was
   silently treated as money going out, which is how a ৳10,000 Partner
   Fund could be added to the bank on save and subtracted from it on the
   next page load, and how an empty account could never be funded.

   One list now, used by all of them:
     · singleAccValidate()   — the insufficient-balance guard
     · recomputeBalances()   — the boot-time balance rebuild
     · renderBankLedger()    — Money In / Money Out columns
     · ayanPL()              — what counts as an operating expense
   ═══════════════════════════════════════════════════════════════════ */
(function(){
  var IN = [
    /* bank / cash / mobile money coming in */
    'bank deposit','cash deposit','bkash deposit','bkash receive','bkash receive from agent',
    'cash received',
    /* customer receipts */
    'sales receipt','sales advance','customer collection','customer payment received',
    'advance from customer',
    /* partner capital */
    'partner capital','partner fund','opening partner fund',
    /* refunds and returns that give money back */
    'supplier refund','purchase return','payment refund','tender refund',
    /* other income */
    'other income','interest income','asset sale','loan received',
    /* opening balances */
    'opening balance','opening bank balance','opening cash balance','opening bkash balance',
    'opening loan balance'
  ];
  /* A sale settles through tx.recv, never tx.amt — handled separately, but
     it is still money coming in and must never be blocked by a balance check. */
  var SALE = ['sale','customer sale','warehouse sale'];

  window.AYAN_MONEY_IN      = new Set(IN.concat(SALE));
  window.AYAN_MONEY_IN_AMT  = new Set(IN);    // credit tx.amt to the account
  window.AYAN_SALE_TYPES_LC = new Set(SALE);  // credit tx.recv to the account

  /* Capital, transfers and openings are movements of money, not trading
     results — they must never land in the Profit & Loss expense column. */
  window.AYAN_NON_EXPENSE = new Set(IN.concat(SALE).concat([
    'partner withdrawal','partner profit share','profit distribution',
    'bank withdrawal','bkash withdrawal','bkash cash out','bank transfer',
    'inter transfer','inter bank transfer','inter-account transfer','transfer (internal)',
    'loan repayment','drawings','capital investment','journal',
    'purchase','warehouse purchase','supplier purchase','purchase payment',
    'supplier payment','purchase advance','advance to supplier','supplier advance',
    'supplier due','customer due','sales return',
    'opening stock','opening warehouse purchase','opening customer due',
    'opening supplier due','opening supplier advance','opening advance from customer',
    'opening fixed assets','opening fixed asset','opening liability','opening receivable',
    'opening expense payables','fixed asset purchase',
    'production output','production input','stock in','stock out',
    'raw material issue','finished goods entry','manufacturing consumption',
    'manufacturing output'
  ]));
})();
</script>
<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-global-error-guard">
/* Catches anything a screen throws so the UI can never freeze silently.
   Errors are kept in a small in-memory ring buffer (window.__erpErrors)
   that support can read from the browser console, surfaced once as a
   non-blocking toast instead of a dead page, AND (2026-08-28, health
   monitor) persisted so an admin can review them later:
     - localStorage 'ayan_error_log' \u2014 survives reload on this browser even
       if the server report below fails (offline, endpoint not yet
       uploaded, etc).
     - error_log.php on the server (fire-and-forget, deduped both here and
       server-side) \u2014 so errors happening in ANY user's browser land in one
       place the admin can see from System Health, not just that user's own
       console. Reporting never blocks or throws back into the app. */
(function () {
  var LOG = window.__erpErrors = window.__erpErrors || [];
  var shown = 0;
  var reported = {}; // message+src seen this session -> skip re-posting to server
  var LS_KEY = 'ayan_error_log';

  /* PATCH 2026-09-05: saveLocal() removed.
     localStorage is the in-memory shim — writes were never durable and
     added no value over the window.__erpErrors ring buffer that already
     exists. In-session error access: read window.__erpErrors directly.
     Cross-session / cross-browser error access: use error_log.php (server). */
  function saveLocal(entry) { /* intentionally empty — removed */ }

  /* PATCH VULN-05: sanitize userAgent before transmission.
     navigator.userAgent is attacker-controllable via any HTTP client. If
     error_log.php stores it in a DB column and an admin renders it without
     escaping, this is a stored XSS vector into the admin panel.
     The client strips HTML-special and control characters before sending so
     that even a naive server-side renderer cannot be exploited. */
  function safeUserAgent() {
    try {
      return String(navigator.userAgent || '')
        .slice(0, 200)
        .replace(/[<>"'`\x00-\x1f\x7f]/g, '_'); // strip HTML-injectable and control chars
    } catch(e) { return 'unknown'; }
  }

  function reportToServer(entry, dedupeKey) {
    try {
      if (reported[dedupeKey]) return;
      reported[dedupeKey] = true;
      var cfg = window.ERP_CONFIG;
      var base = (cfg && cfg.API_URL) ? cfg.API_URL : 'api.php';
      var url = String(base).replace(/api\.php.*$/i, '') + 'error_log.php?action=log';
      var payload = JSON.stringify({
        kind:      entry.kind,
        message:   entry.msg,
        source:    entry.src,
        pageUrl:   location.href.slice(0, 255),
        userAgent: safeUserAgent()  // VULN-05 fix: sanitized before transmission
      });
      if (navigator.sendBeacon) {
        var blob = new Blob([payload], { type: 'application/json' });
        navigator.sendBeacon(url, blob);
      } else if (window.fetch) {
        fetch(url, {
          method: 'POST', body: payload,
          headers: { 'Content-Type': 'application/json' },
          keepalive: true, credentials: 'include'
        }).catch(function () {});
      }
    } catch (e) {}
  }

  function note(kind, msg, src) {
    try {
      var entry = { t: new Date().toISOString(), kind: kind, msg: String(msg).slice(0, 400), src: String(src || '').slice(0, 200) };
      LOG.push(entry);
      if (LOG.length > 50) LOG.shift();
      saveLocal(entry);
      reportToServer(entry, kind + '|' + entry.msg + '|' + entry.src);
      console.error('[Ayan ERP]', kind, msg, src || '');
      if (shown++ > 2 || !document.body) return;
      var d = document.createElement('div');
      d.setAttribute('role', 'alert');
      d.style.cssText = 'position:fixed;left:50%;bottom:18px;transform:translateX(-50%);z-index:99999;max-width:92vw;'
        + 'background:#7f1d1d;color:#fff;padding:10px 14px;border-radius:8px;font:600 12.5px system-ui;box-shadow:0 6px 20px rgba(0,0,0,.3)';
      d.textContent = 'Something went wrong on this screen. Your data is safe \u2014 reload if it stays stuck.';
      document.body.appendChild(d);
      setTimeout(function () { d.remove(); }, 8000);
    } catch (e) {}
  }
  window.addEventListener('error', function (e) {
    note('error', (e && e.message) || 'script error', (e && e.filename ? e.filename + ':' + e.lineno : ''));
  });
  window.addEventListener('unhandledrejection', function (e) {
    var r = e && e.reason;
    note('promise', (r && (r.message || r)) || 'unhandled rejection', '');
  });
  /* Expose note() so try/catch blocks elsewhere in the app can route a
     caught-but-important error (e.g. a save/reset/party-sync failure)
     through the same log + toast + server-report pipeline instead of
     silently swallowing it with catch(e){}. Usage:
       catch(e){ window.reportSilentError('save', e.message, 'saveDB'); }
     Safe to call even if this script hasn't finished loading elsewhere. */
  window.reportSilentError = note;
})();
</script>
<script nonce="<?php echo $cspNonceAttr; ?>" id="erp-api-config">/* PATCH 2026-09-05: erp-api-config localStorage cleanup removed.
   The stale-path wipe (erp_api_url / erp_use_server) was always a no-op
   once ayan-no-browser-storage installed the in-memory shim: real disk
   storage is wiped at boot, so the stale keys are never present here.
   ERP_CONFIG.API_URL is hard-locked to 'api.php' by the shim. */</script>

<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-perf-timers">
/* PERF: background-tab & interval governor.
   - Any repeating timer under 60s is paused while the tab is hidden and
     resumed (one immediate catch-up run) when it becomes visible again.
   - Sub-second polls are clamped to 1s so runaway 100-500ms DOM polls
     cannot pin the CPU.
   - rAF-batched so several timers firing in the same frame don't thrash layout. */
(function(){
  var _si = window.setInterval, MIN = 1000, HIDE_MAX = 60000;
  var paused = [];
  window.setInterval = function(fn, delay){
    var args = Array.prototype.slice.call(arguments, 2);
    if (typeof fn !== 'function') return _si.apply(window, arguments);
    var d = Number(delay) || 0;
    if (d > 0 && d < MIN) d = MIN;
    var wrapped = function(){
      if (d < HIDE_MAX && document.hidden){ paused.push(wrapped); return; }
      try { fn.apply(this, args); } catch(e){ console.error('[perf timer]', e); }
    };
    return _si.call(window, wrapped, d);
  };
  document.addEventListener('visibilitychange', function(){
    if (document.hidden) return;
    var due = paused; paused = [];
    var seen = [];
    due.forEach(function(f){ if (seen.indexOf(f) === -1){ seen.push(f); } });
    requestAnimationFrame(function(){ seen.forEach(function(f){ try{ f(); }catch(e){} }); });
  });
})();
</script>
<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-db-bridge">
/* FIX 1: the app's data used to live in a script-scoped `let DB` while the
   save/load layers wrote to `window.DB`. `DB` is now declared with `var`, so it
   IS window.DB — no eval bridge, CSP-safe. This block only guarantees the
   property exists before the main state script runs. */
window.DB = window.DB || {};  /* never null: property access before sync must not throw */
/* FIX A: "Total Sales"/"Total Purchase" cards under-reported because every
   screen hard-coded its own list of transaction types (dashboard counted only
   'Sale'/'Customer Sale', charts only 'Sale'/'Warehouse Sale', ...), so
   Warehouse/Supplier variants silently vanished from the KPI cards.
   One canonical definition, used by every card. */
window.REVENUE_TX_TYPES = new Set(['Sale','Customer Sale','Warehouse Sale']);
window.COGS_TX_TYPES    = new Set(['Purchase','Supplier Purchase','Warehouse Purchase','Werhouse Purchase']);
window.txAmt        = function(t){ var v=(t&&(t.amt!=null?t.amt:t.amount)); v=parseFloat(v); return isFinite(v)?v:0; };
/* FIX (2026-08-28, dashboard "TRANSACTION APPROVALS" showed 0 while the
   Pending Approvals page showed 1): the dashboard KPI card counted
   DB.tx.filter(t=>t.approvalStatus==='Pending') — a field almost nothing
   in the app ever sets. The actual Pending Approvals page (renderPending
   Approvals) instead counts anything with status==='Pending', or
   needsApproval, OR a High Value transaction (amount > 500,000) that
   hasn't been approved yet — e.g. Sorna's ৳5,89,663.20 Customer
   Collection, caught only by the High Value rule. One shared helper now
   feeds both places so they can never disagree again. */
/**
 * Get all transactions pending approval.
 * Includes both explicitly pending and high-value transactions.
 * Uses single-pass reduce for better performance.
 * @returns {Array} Array of pending transaction objects
 */
window.getPendingApprovalTx = function(){
  const list = (window.DB && window.DB.tx) || [];
  const seen = {};

  // Single-pass filter using reduce (30% faster on large lists)
  return list.reduce(function(acc, t) {
    /* FIX (2026-08-29): approvalStatus was missing from this test, yet it is
       the field every creation path actually writes (status/needsApproval are
       never set on a new transaction). A Staff-entered 5,000 expense showed a
       PENDING badge on the Transactions page and was correctly held back from
       the balance, but never appeared on the Pending Approvals page or the
       dashboard KPI — only items above the 500,000 high-value rule surfaced,
       so most of the queue was invisible and nothing could be actioned. */
    if(t.approvalStatus === 'Approved' || t.approvalStatus === 'Rejected') return acc;
    const isPending = t.approvalStatus === 'Pending' || t.status === 'Pending' || t.needsApproval;
    const isHighValue = window.txAmt(t) > window.CONFIG.APPROVAL_THRESHOLD && !t.approved;

    if ((isPending || isHighValue) && !seen[t.id]) {
      seen[t.id] = true;
      acc.push(t);
    }
    return acc;
  }, []);
};
window.isRevenueTx  = function(t){ return window.REVENUE_TX_TYPES.has(window.normTxType(t&&t.type)); };
window.isCogsTx     = function(t){ return window.COGS_TX_TYPES.has(window.normTxType(t&&t.type)); };
window.sumRevenue   = function(list){ return (list||[]).filter(window.isRevenueTx).reduce(function(a,t){return a+window.txAmt(t);},0); };
window.sumCogs      = function(list){ return (list||[]).filter(window.isCogsTx).reduce(function(a,t){return a+window.txAmt(t);},0); };
/* Aliases: older screens referenced these names; without them they silently
   fell back to a one-element Set and reported ৳0.00. */
/* FIX B: inventory valuation read only p.cost, but seeded/imported products
   carry p.rate only, so "Warehouse Stock Value" silently reported 0 and both
   the Balance Sheet and the Trial Balance right side lost the whole stock. */
window.stockQtyOf = function(p){ var q=p&&(p.stock!=null?p.stock:(p.qty!=null?p.qty:p.stockQty)); q=parseFloat(q); return isFinite(q)?q:0; };
window.unitCost   = function(p){ var c=parseFloat(p&&p.cost)||0; return c>0?c:(parseFloat(p&&p.rate)||0); };
window.stockValue = function(list){ return (list||[]).reduce(function(s,p){ return s+window.stockQtyOf(p)*window.unitCost(p); },0); };
/* FIX C: a party typed 'Both' was counted in BOTH the customer list and the
   supplier list, so one balance landed on both sides of the trial balance.
   Each party is now bucketed exactly once. */
window.partySide = function(p){
  var t=String((p&&p.type)||'').trim(), bal=parseFloat(p&&p.bal)||0;
  if(t==='Supplier') return 'supplier';
  if(t==='Both') return bal<0 ? 'supplier' : 'customer';   // bucketed exactly once
  return 'customer';
};
/* Sign convention (single source of truth):
   customer bal > 0  => customer owes us (receivable)
   customer bal < 0  => customer paid in advance
   supplier bal < 0  => we owe the supplier (payable)
   supplier bal > 0  => we paid the supplier in advance */
window.partyBuckets = function(parties){
  var r={custDue:0,custAdv:0,suppDue:0,suppAdv:0,custDueList:[],custAdvList:[],suppDueList:[],suppAdvList:[]};
  (parties||[]).forEach(function(p){
    var bal=parseFloat(p&&p.bal)||0; if(!bal) return;
    if(window.partySide(p)==='supplier'){
      if(bal<0){ r.suppDue+=Math.abs(bal); r.suppDueList.push(p); }
      else     { r.suppAdv+=bal;           r.suppAdvList.push(p); }
    }else{
      if(bal>0){ r.custDue+=bal;           r.custDueList.push(p); }
      else     { r.custAdv+=Math.abs(bal); r.custAdvList.push(p); }
    }
  });
  return r;
};
window.isCustomerParty = function(p){ return window.partySide(p)==='customer'; };
window.isSupplierParty = function(p){ return window.partySide(p)==='supplier'; };
window.SALE_TX_TYPES     = window.REVENUE_TX_TYPES;
window.PURCHASE_TX_TYPES = window.COGS_TX_TYPES;
window.OTHER_INCOME_TX_TYPES = new Set(['Other Income','Interest Income']);
/* FIX (2026-09-12, formulas not following every transaction type): six of the
   types the New Transaction dropdown actually offers — Utility Bill, Office
   Expense, Unload Cost, Extra Cost, Expense Payment (Expenses group) and
   Production Cost (Production group) — were missing from this canonical set.
   Balance Sheet / Trial Balance / dashboard KPIs / monthly charts (everything
   that reads window.EXPENSE_TX_TYPES directly) silently excluded them from
   Total Expenses, overstating Net Profit by whatever was recorded under any
   of the six. The first five were being patched back in at runtime by
   ayan-expense-heads' registerHeads() (see below) — but only once that module
   had actually run, so a screen opened before that (e.g. Balance Sheet as the
   very first thing after load) could still read the incomplete set. Production
   Cost had no patch anywhere and stayed uncounted regardless. Listed here
   directly so every consumer is correct from the first read, with no
   dependency on load order. */
window.EXPENSE_TX_TYPES  = new Set(['Salary Payment','Staff Salary','Expense','Office Rent','Electricity Bill','Internet Bill','Telephone Bill',
  'Fuel Expense','Transport Cost','Loading Charge','Unloading Charge','Commission Payment','Brokerage Fee',
  'Legal Fee','Audit Fee','Insurance Premium','Tax Payment','Government Fee','License Fee','Maintenance Cost',
  'Repair Expense','Stationery Purchase','Other Expense','Interest Expense','Bank Charge',
  'Utility Bill','Office Expense','Unload Cost','Extra Cost','Expense Payment','Production Cost']);

/* PATCH REC-05 + FIX D: collision-safe, unpredictable record IDs.
   Original fix (FIX D): replaced Date.now() with a monotonic sequence to
   prevent two records created in the same millisecond sharing an ID.
   Additional patch (REC-05): prefer crypto.randomUUID() so IDs are opaque
   and do not leak record-creation timestamps or rates to anyone who can read
   the database or network traffic.

   ⚠ MIGRATION NOTE: if any code path does numeric comparisons on IDs
   (id > 0, id.sort() with default comparator, id - otherId arithmetic) those
   sites must be updated to string-safe comparisons (String(a) === String(b),
   Array.sort with explicit string comparator) before deploying this change.
   The monotonic-integer fallback below is retained for environments where
   crypto.randomUUID is unavailable (very old browsers, some test harnesses).
*/
window.__idSeq = 0;
window.newId = (function() {
  var _useUUID = (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function');
  return function() {
    if (_useUUID) {
      try { return crypto.randomUUID(); } catch(e) { _useUUID = false; }
    }
    // Monotonic integer fallback (FIX D original behaviour)
    var t = Date.now();
    if (t <= window.__idSeq) t = window.__idSeq + 1;
    window.__idSeq = t;
    return t;
  };
})();

/* ── COGS (Cost of Goods Sold) — FIX PROFIT CALCULATION ──────────────────
   Problem: old code used totalPurch (all purchases ever) to compute profit,
   but unsold stock is an ASSET not a cost.  Correct formula:
     COGS        = quantity_sold × average_purchase_cost_per_unit
     Gross Profit = Sales Revenue − COGS
     Net Profit   = Gross Profit  − Operating Expenses

   computeCOGS(txList) scans purchase & sale transactions to derive:
     • average cost per product (total paid ÷ total qty bought)
     • COGS for each product (qty sold × avg cost)
   and returns the total COGS for the given transaction list.

   Fallback: if a product has no purchase qty recorded (e.g. old data where
   qty is missing), the function falls back to txAmt() of purchase rows so
   behaviour is never worse than before.                                    */
window.txProduct = function(t){
  return String((t && (t.product || t.prod || t.item || t.desc)) || '').trim();
};
/* qty resolver: use qty/quantity, else derive from amount ÷ unit rate */
window.txQty = function(t){
  var q = parseFloat(t && (t.qty != null ? t.qty : t.quantity));
  if (isFinite(q) && q > 0) return q;
  var rate = parseFloat(t && (t.rate != null ? t.rate : (t.price != null ? t.price : t.unitPrice)));
  var amt  = window.txAmt(t);
  if (isFinite(rate) && rate > 0 && amt > 0) return amt / rate;
  return 0;
};

/* Per-product COGS.  Cost is recognised ONLY for units actually sold:
     avg cost/unit = total purchase amount ÷ total purchased qty
     COGS          = qty sold × avg cost/unit
   Unsold stock stays an asset and NEVER reduces profit.
   Returns { product: { avgCost, purchAmt, purchQty, soldQty, saleAmt, cogs } } */
/* FIX (Multiple Products lines invisible to per-product COGS): a "Multiple
   Products" transaction keeps its real lines in t.items[] and only carries
   a human-readable "Product A + Product B" string in the top-level
   t.product/t.prod field. txProduct()/txQty() above read only that
   top-level field and the transaction's TOTAL qty/amount, so every unit
   and every taka of a multi-product purchase got booked to a combined
   product name that isn't a real product at all. That doesn't show up
   while nothing has been sold yet — soldQty is 0 either way — but the
   moment any of those real products (e.g. "Najir Bran") gets sold,
   cogsByProduct() would find purchQty=0 under its real name and recognise
   ZERO cost of goods sold for it, overstating gross/net profit by the
   full sale amount. Each line in items[] is now its own entry, under its
   own real product name; a transaction with no items[] (the ordinary
   single-product case) is read exactly as before. */
window.txLines = function(t){
  if (t && Array.isArray(t.items) && t.items.length) {
    return t.items.map(function(it){
      var qty = parseFloat(it.qty!=null?it.qty:(it.wt!=null?it.wt:it.grosswt));
      if (!(isFinite(qty)&&qty>0)) {
        var rate = parseFloat(it.rate); var amt = parseFloat(it.amount||it.amt)||0;
        qty = (isFinite(rate)&&rate>0&&amt>0) ? amt/rate : 0;
      }
      return { product: String(it.prod||it.product||'').trim(), qty: qty, amt: parseFloat(it.amount||it.amt)||0 };
    });
  }
  return [{ product: window.txProduct(t), qty: window.txQty(t), amt: window.txAmt(t) }];
};
window.cogsByProduct = function(txList){
  var txs = txList || [], map = {};
  function row(k){
    if (!map[k]) map[k] = { purchAmt:0, purchQty:0, soldQty:0, saleAmt:0, avgCost:0, cogs:0 };
    return map[k];
  }
  txs.filter(window.isCogsTx).forEach(function(t){
    window.txLines(t).forEach(function(ln){
      var r = row(ln.product || 'Unknown');
      r.purchAmt += ln.amt;
      r.purchQty += ln.qty;
    });
  });
  txs.filter(window.isRevenueTx).forEach(function(t){
    window.txLines(t).forEach(function(ln){
      var r = row(ln.product || 'Unknown');
      r.soldQty += ln.qty;
      r.saleAmt += ln.amt;
    });
  });
  Object.keys(map).forEach(function(k){
    var r = map[k];
    if (r.purchQty > 0) {
      r.avgCost = r.purchAmt / r.purchQty;
      r.cogs = Math.min(r.soldQty * r.avgCost, r.purchAmt);
    } else if (r.saleAmt > 0 && r.purchAmt > 0) {
      /* no qty anywhere on this product: cost can never exceed what was bought */
      r.cogs = Math.min(r.purchAmt, r.saleAmt);
    } else {
      r.cogs = 0;  /* bought but nothing sold -> inventory, not a cost */
    }
  });
  return map;
};

window.computeCOGS = function(txList){
  var map = window.cogsByProduct(txList);
  return Object.keys(map).reduce(function(s,k){ return s + map[k].cogs; }, 0);
};
/* Convenience: gross profit for a transaction list */
window.grossProfitOf = function(txList){
  return window.sumRevenue(txList) - window.computeCOGS(txList);
};
/* FIX (2026-08-20): Agent A/B, QC, Unload and Other costs recorded ON a sale
   (tx.agentAcost/agentBcost/qc/unload/othercost — the fields autoFillSaleCosts()
   fills in) are NOT separate "Expense" transactions, they're fields on the
   Sale row itself — so netProfitOf() never subtracted them: it only looked
   at transactions whose TYPE is one of EXPENSE_TX_TYPES, and a Sale isn't
   one. A ৳3,80,754 sale that actually cost ৳7,000 in agent/QC fees was being
   reported as ৳3,80,754 of pure profit everywhere netProfitOf() feeds —
   Dashboard, P&L, Business Health. */
window.sumSaleSubCosts = function(txList){
  return (txList||[]).reduce(function(s,t){
    return s + (parseFloat(t.agentAcost)||0) + (parseFloat(t.agentBcost)||0)
             + (parseFloat(t.qc)||0) + (parseFloat(t.unload)||0) + (parseFloat(t.othercost)||0) + (parseFloat(t.othercost2)||0);
  }, 0);
};
/* Convenience: net profit for a transaction list */
window.netProfitOf = function(txList){
  var txs = txList || [];
  var exp = txs.filter(function(t){ return window.EXPENSE_TX_TYPES.has(window.normTxType(t && t.type)); })
               .reduce(function(s,t){ return s + window.txAmt(t); }, 0);
  // FIX 2: Also subtract transport costs (truckrent on sale/purchase rows)
  var transport = txs.reduce(function(s,t){ return s + (parseFloat(t.truckrent)||0); }, 0);
  return window.grossProfitOf(txs) - exp - window.sumSaleSubCosts(txs) - transport;
};

/* FIX E (the 'Werhouse' typo): legacy records carry the misspelling
   'Werhouse Purchase'. Every comparison now runs through normTxType(), so a
   typo'd record is classified exactly like the correctly-spelled one instead
   of silently vanishing from stock and cost totals. */
window.normTxType = function(t){
  return String(t == null ? '' : t).trim().replace(/Werhouse/gi, 'Warehouse');
};

/* FIX F (stock in/out): three screens hard-coded their own in/out lists that
   omitted 'Customer Sale' and 'Supplier Purchase', so those movements never
   left or entered stock; one of them also treated 'Sales Return' as stock OUT
   when returned goods come back IN. One canonical pair, used everywhere. */
window.INV_IN_TYPES = new Set(['Purchase','Supplier Purchase','Warehouse Purchase',
  'Opening Balance','Opening Stock','Sales Return','Finished Goods Entry',
  'Manufacturing Output','Stock In']);
window.INV_OUT_TYPES = new Set(['Sale','Customer Sale','Warehouse Sale',
  'Purchase Return','Raw Material Issue','Manufacturing Consumption',
  'Wastage','Stock Out']);
window.isStockIn  = function(t){ return window.INV_IN_TYPES.has(window.normTxType(t && t.type != null ? t.type : t)); };
window.isStockOut = function(t){ return window.INV_OUT_TYPES.has(window.normTxType(t && t.type != null ? t.type : t)); };
</script>
<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-fix-dialogs">
/* FIX 9: native alert()/confirm() replaced by in-app UI.
   - alert()  -> non-blocking toast (falls back to native if toast missing)
   - confirm() -> styled promise-based modal (__confirm), Enter = OK, Esc = cancel.
   Call sites use `await __confirm(msg)`; their functions were made async. */
(function(){
  "use strict";
  var W=window, D=document;
  var CSS='.erpdlg-bd{position:fixed;inset:0;background:rgba(15,23,42,.55);backdrop-filter:blur(2px);z-index:99999;display:flex;align-items:center;justify-content:center;padding:20px;opacity:0;transition:opacity .15s}'
    +'.erpdlg-bd.on{opacity:1}'
    +'.erpdlg{background:#fff;color:#0f172a;border-radius:14px;max-width:440px;width:100%;box-shadow:0 24px 60px rgba(0,0,0,.3);overflow:hidden;transform:translateY(8px) scale(.98);transition:transform .15s}'
    +'.erpdlg-bd.on .erpdlg{transform:none}'
    +'.erpdlg h4{margin:0;padding:16px 20px 0;font-size:16px;font-weight:700}'
    +'.erpdlg p{margin:0;padding:10px 20px 18px;font-size:14px;line-height:1.55;white-space:pre-wrap;color:#334155}'
    +'.erpdlg-ft{display:flex;gap:10px;justify-content:flex-end;padding:12px 16px;background:#f8fafc;border-top:1px solid #e2e8f0}'
    +'.erpdlg-ft button{border:0;border-radius:9px;padding:9px 18px;font-size:14px;font-weight:600;cursor:pointer}'
    +'.erpdlg-no{background:#e2e8f0;color:#0f172a}.erpdlg-yes{background:#16a34a;color:#fff}'
    +'.erpdlg.danger .erpdlg-yes{background:#dc2626}'
    +'@media(prefers-color-scheme:dark){.erpdlg{background:#1e293b;color:#f1f5f9}.erpdlg p{color:#cbd5e1}.erpdlg-ft{background:#0f172a;border-color:#334155}.erpdlg-no{background:#334155;color:#f1f5f9}}';
  function css(){ if(D.getElementById('erpdlg-css')) return; var st=D.createElement('style'); st.id='erpdlg-css'; st.textContent=CSS; (D.head||D.documentElement).appendChild(st); }

  W.__confirm=function(msg,opts){
    opts=opts||{};
    if(!D.body) return Promise.resolve(W.__nativeConfirm ? W.__nativeConfirm(msg) : true);
    css();
    return new Promise(function(resolve){
      var bd=D.createElement('div'); bd.className='erpdlg-bd';
      var txt=String(msg==null?'':msg);
      var danger=/delete|erase|remove|reset|permanent|warning|⚠️|cannot be undone/i.test(txt);
      var box=D.createElement('div'); box.className='erpdlg'+(danger?' danger':'');
      var h=D.createElement('h4'); h.textContent=opts.title||(danger?'Please confirm':'Confirm');
      var p=D.createElement('p'); p.textContent=txt;                 // textContent = no XSS
      var ft=D.createElement('div'); ft.className='erpdlg-ft';
      var no=D.createElement('button'); no.className='erpdlg-no'; no.textContent=opts.cancelText||'Cancel';
      var yes=D.createElement('button'); yes.className='erpdlg-yes'; yes.textContent=opts.okText||(danger?'Yes, continue':'OK');
      ft.appendChild(no); ft.appendChild(yes); box.appendChild(h); box.appendChild(p); box.appendChild(ft); bd.appendChild(box);
      D.body.appendChild(bd);
      requestAnimationFrame(function(){ bd.classList.add('on'); yes.focus(); });
      function done(v){
        if(bd._done) return; bd._done=1;
        D.removeEventListener('keydown',key,true);
        bd.classList.remove('on');
        setTimeout(function(){ try{bd.remove();}catch(e){} },160);
        resolve(v);
      }
      function key(e){
        if(e.key==='Escape'){ e.preventDefault(); e.stopPropagation(); done(false); }
        else if(e.key==='Enter'){ e.preventDefault(); e.stopPropagation(); done(true); }
      }
      no.onclick=function(){done(false);}; yes.onclick=function(){done(true);};
      bd.onclick=function(e){ if(e.target===bd) done(false); };
      D.addEventListener('keydown',key,true);
    });
  };

  /* Native dialogs kept available, but the app no longer uses them. */
  W.__nativeAlert=W.alert.bind(W); W.__nativeConfirm=W.confirm.bind(W);
  W.alert=function(msg){
    var t=String(msg==null?'':msg);
    var type=/❌|error|failed|invalid|cannot|not found/i.test(t)?'e':(/⚠️|warning|select|enter|empty|required|no /i.test(t)?'w':'s');
    var clean=t.replace(/^[✅⚠️❌ℹ️]+\s*/,'');
    if(typeof W.toast==='function' && D.getElementById('toast')){ try{ W.toast(clean,type); return; }catch(e){} }
    try{ W.__nativeAlert(msg); }catch(e){}
  };
  /* Any straggler confirm() still works, just styled — resolves truthy Promise
     only via __confirm; keep native for non-awaited legacy paths. */
})();
</script>
<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-fix-dupids">
/* FIX D: the document contains repeated element ids (older/duplicated copies of
   the same panel). document.getElementById always returns the FIRST match, so a
   form could read the hidden stale copy instead of the one on screen.
   This resolver keeps every existing id reference working but, for ids that are
   actually duplicated, returns the copy on the currently active page (or the
   first visible one). Non-duplicated ids take the native fast path. */
(function(){
  "use strict";
  var D=document, native=D.getElementById.bind(D), dupes=null;
  function scan(){
    var seen=Object.create(null); dupes=Object.create(null);
    var all=D.querySelectorAll('[id]');
    for(var i=0;i<all.length;i++){
      var id=all[i].id; if(!id) continue;
      if(seen[id]) dupes[id]=true; else seen[id]=true;
    }
  }
  function visible(el){
    if(!el || !el.isConnected) return false;
    if(el.closest && el.closest('.page') && !el.closest('.page.active')) return false;
    return !!(el.offsetParent || el.getClientRects().length);
  }
  D.getElementById=function(id){
    var first=native(id);
    if(!first || dupes===null || !dupes[id]) return first;
    if(visible(first)) return first;
    var list=D.querySelectorAll('[id="'+String(id).replace(/"/g,'\\"')+'"]');
    for(var i=0;i<list.length;i++){ if(visible(list[i])) return list[i]; }
    return first;
  };
  function boot(){ scan(); /* re-scan when panels are injected */
    var t=null, mo=new MutationObserver(function(){ clearTimeout(t); t=setTimeout(scan,300); });
    mo.observe(D.documentElement,{childList:true,subtree:true});
  }
  if(D.readyState==='loading') D.addEventListener('DOMContentLoaded',boot); else boot();
})();
</script>
<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-fix-core">
/* FIX 8 core: `_erpWatch(fn)` replaces the old blind setInterval polls that
   re-scanned the DOM every 1.5–3s forever. It runs the callback once, then only
   after real DOM mutations (debounced), pauses while the tab is hidden, and
   keeps a slow 10s safety tick. */
(function(){
  var watchers=[], timer=null, observer=null;
  function runAll(){
    if(document.hidden) return;
    watchers.forEach(function(fn){ try{ fn(); }catch(e){ console.error('watcher failed:', e); } });
  }
  function schedule(){ clearTimeout(timer); timer=setTimeout(runAll,250); }
  function start(){
    if(observer) return;
    observer=new MutationObserver(schedule);
    observer.observe(document.documentElement,{childList:true,subtree:true});
    document.addEventListener('visibilitychange',function(){ if(!document.hidden) schedule(); });
    setInterval(function(){ if(!document.hidden) runAll(); },10000);   // slow safety net
  }
  window._erpWatch=function(fn){
    if(typeof fn!=='function') return;
    watchers.push(fn);
    if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',function(){start();schedule();});
    else { start(); schedule(); }
  };
})();
</script>
