<script nonce="<?php echo $cspNonceAttr; ?>">
// ── Permanent Server Sync Configuration ──
/* FIX 2: server sync is only used when api.php is really deployed; the app
   auto-falls back to offline/local storage otherwise (see _erpLocalSave). */
/* No sync backend is deployed with this build, so the probe request only produced
   a failing /api/public/erp call on every load. Sync stays off until a real
   endpoint exists (flip USE_SERVER back to true then). */
/* ── PERMANENT SERVER / MySQL SYNC CONFIGURATION (v2) ─────────────────────
   The API endpoint is now user-configurable and persisted in localStorage so
   the same build works on cPanel hosting (api.php next to erp.html), in a
   subfolder, or on a different origin. Change it at runtime from
   Settings -> "Server Sync" (window.openServerSyncSettings()).            */
(function(){
  /* SERVER-ONLY (hard-locked): the endpoint is always api.php next to this
     file and USE_SERVER is always true. Both live on the non-configurable
     window.ERP_CONFIG installed by #ayan-no-browser-storage at the top of
     <head>, so nothing here (or in Settings, or in DevTools) can change
     them. This block is kept only so window.ERP_CONFIG is guaranteed to
     exist for the layers below. */
  window.ERP_SERVER_MODE = true;
  if(!window.ERP_CONFIG){
    window.ERP_CONFIG = { USE_SERVER:true, API_URL:'api.php', DEFAULT_API_URL:'api.php',
                          LOGIN_URL:'login.php', LOGOUT_URL:'logout.php', USE_CLOUD:false };
  }
  window.setErpApiUrl = function(){ return window.ERP_CONFIG; };
})();
/* Robust date-key helper: ledger/report filters compare date strings, which only
   works when both sides are ISO YYYY-MM-DD. _dk() normalises Date objects,
   ISO-with-time, single-digit month/day and dd/mm/yyyy input to a comparable key. */
window._dk = function(v){
  if(v===null||v===undefined||v==='') return '';
  if(v instanceof Date) return isNaN(v)?'':v.getFullYear()+'-'+String(v.getMonth()+1).padStart(2,'0')+'-'+String(v.getDate()).padStart(2,'0');
  var s = String(v).trim();
  if(!s) return '';
  var m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if(m) return m[1]+'-'+m[2].padStart(2,'0')+'-'+m[3].padStart(2,'0');
  m = s.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{4})/);
  if(m) return m[3]+'-'+m[2].padStart(2,'0')+'-'+m[1].padStart(2,'0');
  var d = new Date(s);
  if(!isNaN(d)) return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
  return s;
};
function _dk(v){ return window._dk(v); }

/* Console polyfill — some embedded viewers ship a partial console object */
(function(){
  if(typeof window.console==='undefined') window.console={};
  var base=(typeof console.log==='function')?function(){try{console.log.apply(console,arguments);}catch(e){}}:function(){};
  ['log','info','warn','error','debug','trace','table','group','groupEnd'].forEach(function(m){
    if(typeof console[m]!=='function') console[m]=base;
  });
})();

/* Duplicate-ID guard: this document reuses many element ids (modal fields, page
   selects). Native getElementById always returns the FIRST match, which can be a
   hidden twin on another page — so reads/writes silently hit the wrong element.
   When an id is duplicated, prefer the element that is actually rendered. */
(function(){
  var native = Document.prototype.getElementById;
  document.getElementById = function(id){
    var first = native.call(document, id);
    if(!first) return null;
    var esc = (window.CSS && CSS.escape) ? CSS.escape(id) : id.replace(/([^a-zA-Z0-9_-])/g,'\\$1');
    var all;
    try{ all = document.querySelectorAll('#'+esc); }catch(e){ return first; }
    if(all.length <= 1) return first;
    for(var i=0;i<all.length;i++){
      if(all[i].getClientRects().length > 0) return all[i]; // visible one wins
    }
    return first; // nothing visible yet (e.g. filling a modal before opening it)
  };
})();

/* Page print mode: if no letterhead document (#print-area) is being shown,
   print the current page content instead of a blank sheet. */
(function(){
  function letterheadActive(){
    var pm = document.querySelector('#print-modal');
    var pa = document.querySelector('#print-area');
    var vis = function(el){ return el && el.getClientRects && el.getClientRects().length > 0; };
    return vis(pm) || vis(pa);
  }
  window.addEventListener('beforeprint', function(){
    if(!letterheadActive()) document.body.classList.add('print-page-mode');
  });
  window.addEventListener('afterprint', function(){
    document.body.classList.remove('print-page-mode');
  });
})();
</script>
