<script nonce="<?php echo $cspNonceAttr; ?>">
/* Chart.js reuse guard: v4 throws "Canvas is already in use" if a chart is
   created on a canvas that still holds one. Several render functions here
   re-create charts without destroying the old instance first, so re-visiting
   those pages crashed their charts. Destroy-before-create, globally. */
(function(){
  var Orig = window.Chart;
  if(!Orig || typeof Proxy === 'undefined') return;
  window.Chart = new Proxy(Orig, {
    construct: function(target, args){
      try{
        var existing = Orig.getChart && Orig.getChart(args[0]);
        if(existing) existing.destroy();
      }catch(e){}
      return Reflect.construct(target, args);
    }
  });
})();
</script>
<script nonce="<?php echo $cspNonceAttr; ?>">
// ══════════════════════════════════════════════════════════════
// FEATURE 2: Invoice Type Switcher
// ══════════════════════════════════════════════════════════════
let _currentPrintTx = null;

function switchInvoiceType(type){
  if(type === 'general'){ printCurrentPage(); return; }
  if(!_currentPrintTx){ toast && toast('This document type needs a transaction. Use "General Report" for pages.','e'); return; }
  const tx = _currentPrintTx;
  let html = '';
  const titles = {voucher:'Transaction Voucher',invoice:'Sales Invoice',challan:'Delivery Challan',receipt:'Money Receipt'};
  document.getElementById('print-doc-title').textContent = titles[type] || 'Document';

  if(type === 'invoice'){
    html = buildSalesInvoice(tx);
  } else if(type === 'challan'){
    html = buildDeliveryChallan(tx);
  } else if(type === 'receipt'){
    html = buildMoneyReceipt(tx);
  } else {
    html = buildVoucher(tx);
  }
  document.getElementById('print-content').innerHTML = html;
}

// Shared helper: normalizes any transaction to an items array.
// Real multi-product transactions already carry tx.items (see the
// Multi-Product purchase rows feature). Older/simple transactions
// only have flat tx.prod/tx.qty/tx.rate fields — those get wrapped
// into a single-row array so every print function can just .map().
function txItemRows(tx){
  if(tx.items && tx.items.length) return tx.items;
  return [{
    prod: tx.prod||'Rice Bran Oil', bagtype: tx.bagtype||'', bagqty: tx.bagqty||0,
    qty: tx.qty||0, wt: tx.wt||tx.qty||0, rate: tx.rate||(tx.qty?0:tx.amount)||0,
    amount: tx.amount||0, oilPct: tx.oilPct||0, totalOil: tx.totalOil||0
  }];
}

function printLetterhead(){
  return `
    <div style="text-align:center;border-bottom:3px solid #0f3d26;padding-bottom:10px;margin-bottom:14px;">
      <div style="font-size:19px;font-weight:900;color:#0f3d26;letter-spacing:.5px;">AYAN AGRO INTERNATIONAL LIMITED</div>
      <div style="font-size:11px;color:#6b7280;font-style:italic;margin-top:2px;">Sister concern of M/S Karima Enterprise</div>
      <div style="font-size:9px;color:#9ca3af;margin-top:4px;">www.ayanagro.store &nbsp;|&nbsp; Barishal, Bangladesh</div>
    </div>
    <div style="position:fixed;top:38%;left:0;width:100%;text-align:center;transform:rotate(-32deg);
                font-size:64px;font-weight:900;color:rgba(15,61,38,.06);letter-spacing:6px;
                pointer-events:none;z-index:0;user-select:none;">AYAN AGRO</div>
  `;
}

function buildVoucher(tx){
  const items = txItemRows(tx);
  const isMulti = items.length > 1;
  const rows = [
    ['Transaction Type', `<span style="background:#0f3d26;color:#fff;padding:2px 8px;border-radius:4px;font-size:11px;">${tx.type}</span>`],
    ['Date', tx.date||'—'],['Invoice No', tx.inv||'—'],
    ['Party Name', `<strong>${escHTML(tx.party ||'—')}</strong>`],['Party Type', tx.ptype||'—'],
    // Single-product line stays for simple transactions; multi-product
    // transactions get their own itemized table instead (below).
    ...(isMulti ? [] : [['Product / Purpose', tx.prod||'—']]),
    ['Location', tx.loc||'—'],
    ...(isMulti ? [] : [
      ['Bag Type / Qty', tx.bagtype ? `${tx.bagtype} × ${tx.bagqty||0}` : '—'],
      ['Quantity (KG/Ltr)', tx.qty ? pn(tx.qty) : '—'],
      ['Rate (৳)', tx.rate ? pf(tx.rate) : '—'],
    ]),
    ['Gross Amount (৳)', `<strong>${pf(tx.amount)}</strong>`],
    ['Paid (৳)', tx.paid ? pf(tx.paid) : '—'],
    ['Received (৳)', tx.recv ? pf(tx.recv) : '—'],
    ['Due (৳)', tx.due ? `<strong style="color:#dc2626;">${pf(tx.due)}</strong>` : '—'],
    ['Payment Mode', tx.mode||'—'],['Bank Account', tx.acc ? bankNameToDisplay(tx.acc) : '—'],
    ['Truck ID', tx.truck||'—'],
    ['Truck Rent (৳)', tx.truckrent ? pf(tx.truckrent) : '—'],
    ['Total Cost (৳)', tx.totalcost ? `<strong>${pf(tx.totalcost)}</strong>` : '—'],
    ['Notes / Remarks', tx.rem||'—'],
  ].filter(r => r[1] !== '—');

  const itemsTable = isMulti ? `
    <table class="print-table" style="margin-bottom:10px;">
      <thead><tr><th style="width:6%">#</th><th>Product</th><th>Bag</th><th class="td-num">Qty</th><th class="td-num">Rate (৳)</th><th class="td-num">Amount (৳)</th></tr></thead>
      <tbody>${items.map((it,i)=>`<tr><td>${i+1}</td><td>${it.prod||'—'}</td><td>${it.bagtype?`${it.bagtype} × ${it.bagqty||0}`:'—'}</td><td class="td-num">${pn(it.qty||it.wt||0)}</td><td class="td-num">${pf(it.rate||0)}</td><td class="td-num">${pf(it.amount||0)}</td></tr>`).join('')}</tbody>
    </table>` : '';

  return printLetterhead() + `
    <div class="sum-boxes">
      <div class="sum-box"><div class="sb-label">Amount</div><div class="sb-val">৳${pf(tx.amount)}</div></div>
      <div class="sum-box"><div class="sb-label">Paid</div><div class="sb-val">৳${pf(tx.paid||0)}</div></div>
      <div class="sum-box"><div class="sb-label">Due</div><div class="sb-val" style="color:#dc2626;">৳${pf(tx.due||0)}</div></div>
      <div class="sum-box"><div class="sb-label">Total Cost</div><div class="sb-val">৳${pf(tx.totalcost||0)}</div></div>
    </div>
    ${itemsTable}
    <table class="print-table">
      <thead><tr><th style="width:35%">Field</th><th>Details</th></tr></thead>
      <tbody>${rows.map(r=>`<tr><td style="font-weight:600;color:#0f3d26;">${r[0]}</td><td>${r[1]}</td></tr>`).join('')}</tbody>
    </table>`;
}

function buildSalesInvoice(tx){
  const items = txItemRows(tx);
  const itemRowsHTML = items.map((it,i)=>{
    const qty = it.qty||it.wt||1, rate = it.rate||it.amount||0, amt = it.amount||(qty*rate)||0;
    return `<tr><td>${i+1}</td><td>${escHTML(it.prod ||'Rice Bran Oil')}</td><td>${pn(qty)}</td><td>${pf(rate)}</td><td>${pf(amt)}</td></tr>`;
  }).join('');
  const itemsSubtotal = items.reduce((s,it)=>s+(it.amount||((it.qty||it.wt||0)*(it.rate||0))||0), 0);
  const grandTotal = itemsSubtotal + (tx.truckrent||0);
  const nextRowNum = items.length + 1;

  return printLetterhead() + `
    <div class="inv-party-box">
      <div>
        <div class="inv-party-label">Bill To</div>
        <div class="inv-party-name">${escHTML(tx.party ||'—')}</div>
        <div style="font-size:10px;color:#6b7280;margin-top:2px;">${tx.ptype||''} | ${tx.loc||''}</div>
      </div>
      <div style="text-align:right;">
        <div class="inv-party-label">Invoice Details</div>
        <div style="font-size:11px;color:#374151;">Invoice: <strong>${tx.inv||'—'}</strong></div>
        <div style="font-size:11px;color:#374151;">Date: <strong>${tx.date||'—'}</strong></div>
        <div style="font-size:11px;color:#374151;">Mode: <strong>${tx.mode||'—'}</strong></div>
      </div>
    </div>
    <table class="inv-items-table">
      <thead><tr><th>#</th><th>Product / Description</th><th>Qty</th><th>Rate (৳)</th><th>Amount (৳)</th></tr></thead>
      <tbody>
        ${itemRowsHTML}
        ${tx.truckrent ? `<tr><td>${nextRowNum}</td><td>Truck Rent (${tx.truck||''})</td><td>1</td><td>${pf(tx.truckrent)}</td><td>${pf(tx.truckrent)}</td></tr>` : ''}
        <tr class="inv-total-row"><td colspan="4" style="text-align:right;padding-right:16px;">Total Amount</td><td><strong>৳${pf(grandTotal)}</strong></td></tr>
        <tr class="inv-total-row"><td colspan="4" style="text-align:right;padding-right:16px;">Paid</td><td style="color:#16a34a;"><strong>৳${pf(tx.paid||0)}</strong></td></tr>
        <tr class="inv-total-row"><td colspan="4" style="text-align:right;padding-right:16px;">Balance Due</td><td style="color:#dc2626;"><strong>৳${pf(tx.due||0)}</strong></td></tr>
      </tbody>
    </table>
    <div style="margin-top:10px;padding:8px 12px;background:#fef9c3;border-radius:6px;font-size:10px;color:#92400e;">
      <strong>Payment Terms:</strong> Due within 30 days. Late payment may incur charges.
    </div>`;
}

function buildDeliveryChallan(tx){
  const items = txItemRows(tx);
  const itemRowsHTML = items.map((it,i)=>
    `<tr><td>${i+1}</td><td>${escHTML(it.prod ||'—')}</td><td>${it.bagtype||'—'}</td><td>${it.bagqty||'—'}</td><td>${pn(it.qty||0)}</td><td>${pn(it.wt||0)}</td></tr>`
  ).join('');

  return printLetterhead() + `
    <div class="inv-party-box">
      <div>
        <div class="inv-party-label">Deliver To</div>
        <div class="inv-party-name">${escHTML(tx.party ||'—')}</div>
        <div style="font-size:10px;color:#6b7280;margin-top:2px;">Location: ${tx.loc||'—'}</div>
      </div>
      <div style="text-align:right;">
        <div class="inv-party-label">Challan Details</div>
        <div style="font-size:11px;">Challan No: <strong>${tx.inv||'—'}</strong></div>
        <div style="font-size:11px;">Date: <strong>${tx.date||'—'}</strong></div>
        <div style="font-size:11px;">Truck: <strong>${escHTML(tx.truck ||'—')}</strong></div>
      </div>
    </div>
    <table class="inv-items-table">
      <thead><tr><th>#</th><th>Product</th><th>Bag Type</th><th>Bags</th><th>Qty (KG/Ltr)</th><th>Weight</th></tr></thead>
      <tbody>
        ${itemRowsHTML}
      </tbody>
    </table>
    <div style="margin-top:16px;display:flex;gap:20px;">
      <div style="flex:1;border:1px solid #e5e7eb;border-radius:6px;padding:10px;">
        <div style="font-size:10px;font-weight:700;color:#0f3d26;margin-bottom:6px;">Driver / Vehicle</div>
        <div style="font-size:10px;">Truck ID: ${escHTML(tx.truck ||'___________')}</div>
        <div style="font-size:10px;margin-top:4px;">Driver Name: ___________________</div>
        <div style="font-size:10px;margin-top:4px;">Driver Sign: ___________________</div>
      </div>
      <div style="flex:1;border:1px solid #e5e7eb;border-radius:6px;padding:10px;">
        <div style="font-size:10px;font-weight:700;color:#0f3d26;margin-bottom:6px;">Receiver</div>
        <div style="font-size:10px;">Name: ___________________</div>
        <div style="font-size:10px;margin-top:4px;">Date: ___________________</div>
        <div style="font-size:10px;margin-top:4px;">Signature: ___________________</div>
      </div>
    </div>`;
}

function buildMoneyReceipt(tx){
  const amt = tx.recv || tx.paid || tx.amount || 0;
  return printLetterhead() + `
    <div style="text-align:center;margin:10px 0 16px;">
      <div style="font-size:13px;color:#15803d;font-weight:700;">MONEY RECEIPT</div>
      <div style="font-size:10px;color:#6b7280;">Receipt No: ${tx.inv||'—'} | Date: ${tx.date||'—'}</div>
    </div>
    <div style="border:2px solid #16a34a;border-radius:8px;padding:16px;margin-bottom:12px;">
      <p style="font-size:12px;line-height:2;">
        Received with thanks from <strong>${escHTML(tx.party ||'___________')}</strong> the sum of
        <strong style="color:#0f3d26;font-size:14px;">৳ ${pf(amt)}</strong>
        (${numberToWords(amt)} Taka only) by <strong>${tx.mode||'Cash'}</strong>
        ${tx.acc ? `via <strong>${bankNameToDisplay(tx.acc)}</strong>` : ''}
        being payment for <strong>${tx.prod||tx.type||'goods/services'}</strong>.
      </p>
    </div>
    <div style="display:flex;justify-content:space-between;margin-top:20px;">
      <div style="text-align:center;">
        <div style="border-top:1px solid #374151;padding-top:4px;font-size:10px;width:140px;">Payer's Signature</div>
      </div>
      <div style="text-align:center;">
        <div style="border-top:1px solid #374151;padding-top:4px;font-size:10px;width:140px;">Receiver's Signature</div>
      </div>
    </div>`;
}

function numberToWords(n){
  if(!n || n===0) return 'Zero';
  const ones=['','One','Two','Three','Four','Five','Six','Seven','Eight','Nine','Ten','Eleven','Twelve','Thirteen','Fourteen','Fifteen','Sixteen','Seventeen','Eighteen','Nineteen'];
  const tens=['','','Twenty','Thirty','Forty','Fifty','Sixty','Seventy','Eighty','Ninety'];
  function convert(num){
    if(num===0) return '';
    if(num<20) return ones[num]+' ';
    if(num<100) return tens[Math.floor(num/10)]+' '+(num%10?ones[num%10]+' ':'');
    if(num<1000) return ones[Math.floor(num/100)]+' Hundred '+(num%100?convert(num%100):'');
    if(num<100000) return convert(Math.floor(num/1000))+' Thousand '+(num%1000?convert(num%1000):'');
    if(num<10000000) return convert(Math.floor(num/100000))+' Lakh '+(num%100000?convert(num%100000):'');
    return convert(Math.floor(num/10000000))+' Crore '+(num%10000000?convert(num%10000000):'');
  }
  return convert(Math.floor(n)).trim();
}


