// Auto-fill party type when party name is typed/selected
function smartPartyAutoFill(){
  const partyName = document.getElementById('tx-party').value.trim();
  if(!partyName) return;
  const ptypeEl = document.getElementById('tx-ptype');

  // Check in customers
  const cust = (DB.customers||[]).find(c => c.name.toLowerCase() === partyName.toLowerCase());
  if(cust){
    if(ptypeEl) ptypeEl.value = cust.type || 'Customer';
    showSmartHint('tx-party', `✅ ${cust.name} — Balance: ৳${pf(cust.bal||0)}`);
    populateSupplierBankDropdown();
    return;
  }
  // Check in partners
  const part = (DB.partners||[]).find(p => p.name.toLowerCase() === partyName.toLowerCase());
  if(part){
    if(ptypeEl) ptypeEl.value = 'Partner';
    showSmartHint('tx-party', `✅ ${part.name} — Capital: ৳${pf(part.cap||0)}`);
    populateSupplierBankDropdown();
    return;
  }
  // Check in banks
  const bank = (DB.banks||[]).find(b => b.name.toLowerCase() === partyName.toLowerCase());
  if(bank){
    if(ptypeEl) ptypeEl.value = 'Other';
    showSmartHint('tx-party', `🏦 Bank Account: ৳${pf(bank.bal||0)}`);
    populateSupplierBankDropdown();
    return;
  }
  // No match yet (still typing) — keep the bank dropdown in sync anyway,
  // in case the party field was cleared.
  populateSupplierBankDropdown();
}

/* ── SUPPLIER BANK INFO DROPDOWN ──────────────────────────────────────────
   Reads the saved bank account(s) for whichever party is selected in the
   transaction form (primary bankName/bankAcc/bankBranch plus any extra
   accounts added via "Add Another Bank Account" on the party form) and
   offers them as a dropdown instead of requiring the account to be typed
   out from memory every time. An "Other / Type manually" option is kept
   for one-off accounts that were never saved against the party. ────────── */
function getPartyBankAccounts(name){
  if(!name) return [];
  const n = name.trim().toLowerCase();
  const c = (DB.customers||[]).find(x => (x.name||'').toLowerCase() === n);
  if(!c) return [];
  const accounts = [];
  if(c.bankName || c.bankAcc) accounts.push({bank:c.bankName||'', acc:c.bankAcc||'', branch:c.bankBranch||''});
  (c.bankAccounts||[]).forEach(b => accounts.push({
    bank: b.bankName || b.bank || '', acc: b.bankAcc || b.acc || '', branch: b.bankBranch || b.branch || ''
  }));
  return accounts;
}
/* FIX (2026-08-27): show the account's own unique ID (its real account
   number) rather than "Bank Name - Account No - Branch" — per explicit
   request to identify a recipient's account by its ID, not by name. Falls
   back to branch/bank only for old records saved with no account number,
   so a party's saved account never shows up blank in the picker. */
function fmtPartyBankAcc(a){
  const id = (a.acc||'').toString().trim();
  if(id) return id;
  return (a.branch || a.bank || '').toString().trim();
}
function populateSupplierBankDropdown(selected){
  const sel = document.getElementById('tx-supplierbank');
  const custom = document.getElementById('tx-supplierbank-custom');
  if(!sel) return;
  const partyName = (document.getElementById('tx-party')||{}).value || '';
  const accounts = getPartyBankAccounts(partyName);
  let html = '<option value="">-- Select Bank Account --</option>';
  accounts.forEach(a=>{
    const label = fmtPartyBankAcc(a);
    if(!label) return;
    html += `<option value="${label.replace(/"/g,'&quot;')}">🏦 ${label}</option>`;
  });
  html += '<option value="__other__">✏️ Other / Type manually</option>';
  sel.innerHTML = html;
  if(selected){
    const match = accounts.some(a => fmtPartyBankAcc(a) === selected);
    if(match){ sel.value = selected; if(custom){ custom.style.display='none'; custom.value=''; } }
    else { sel.value = '__other__'; if(custom){ custom.style.display=''; custom.value = selected; } }
  } else {
    sel.value = '';
    if(custom){ custom.style.display='none'; custom.value=''; }
  }
}
function onSupplierBankSelect(){
  const sel = document.getElementById('tx-supplierbank');
  const custom = document.getElementById('tx-supplierbank-custom');
  if(!sel || !custom) return;
  if(sel.value === '__other__'){ custom.style.display=''; custom.focus(); }
  else { custom.style.display='none'; custom.value=''; }
}
function syncSupplierBankCustom(){ /* value read directly by getSupplierBankValue() on save */ }
function getSupplierBankValue(){
  const sel = document.getElementById('tx-supplierbank');
  const custom = document.getElementById('tx-supplierbank-custom');
  if(!sel) return '';
  if(sel.value === '__other__') return (custom && custom.value || '').trim();
  return sel.value || '';
}
window.populateSupplierBankDropdown = populateSupplierBankDropdown;
window.getSupplierBankValue = getSupplierBankValue;

/* FIX (2026-08-27): the "recipient's bank account when money is paid /
   our own bank account when money is received" feature above only existed
   on the main Transaction form (as "Supplier Bank Info", tx-supplierbank).
   Orders and Delivery Challan both carry a Truck/Vehicle ID for transport
   tracking already, but had no equivalent bank-account field at all, so
   there was nowhere to record which account the payment for that
   order/challan belongs to. These generic helpers reuse the same
   getPartyBankAccounts()/fmtPartyBankAcc() lookup so any party-name field
   (tx-party, ord-customer, ch-party, chfa-party, ...) can drive a
   select+custom-input bank-account picker without duplicating the lookup
   logic per form. */
function populatePartyBankPicker(partyElId, selectId, customId, selected){
  const sel = document.getElementById(selectId);
  const custom = document.getElementById(customId);
  if(!sel) return;
  const partyEl = document.getElementById(partyElId);
  const partyName = partyEl ? (partyEl.value || '') : '';
  const accounts = getPartyBankAccounts(partyName);
  let html = '<option value="">-- Select Bank Account --</option>';
  accounts.forEach(a=>{
    const label = fmtPartyBankAcc(a);
    if(!label) return;
    html += `<option value="${label.replace(/"/g,'&quot;')}">🏦 ${label}</option>`;
  });
  html += '<option value="__other__">✏️ Other / Type manually</option>';
  sel.innerHTML = html;
  if(selected){
    const match = accounts.some(a => fmtPartyBankAcc(a) === selected);
    if(match){ sel.value = selected; if(custom){ custom.style.display='none'; custom.value=''; } }
    else { sel.value = '__other__'; if(custom){ custom.style.display=''; custom.value = selected; } }
  } else {
    sel.value = '';
    if(custom){ custom.style.display='none'; custom.value=''; }
  }
}
function onPartyNameFieldChanged(partyElId, selectId, customId){
  populatePartyBankPicker(partyElId, selectId, customId);
}
function onPartyBankPickerChange(selectId, customId){
  const sel = document.getElementById(selectId);
  const custom = document.getElementById(customId);
  if(!sel || !custom) return;
  if(sel.value === '__other__'){ custom.style.display=''; custom.focus(); }
  else { custom.style.display='none'; custom.value=''; }
}
function getPartyBankPickerValue(selectId, customId){
  const sel = document.getElementById(selectId);
  const custom = document.getElementById(customId);
  if(!sel) return '';
  if(sel.value === '__other__') return (custom && custom.value || '').trim();
  return sel.value || '';
}
window.populatePartyBankPicker = populatePartyBankPicker;
window.onPartyNameFieldChanged = onPartyNameFieldChanged;
window.onPartyBankPickerChange = onPartyBankPickerChange;
window.getPartyBankPickerValue = getPartyBankPickerValue;

/* FIX (2026-08-28): reverted per explicit request — show the bank/cash
   account's NAME everywhere an account is picked or shown (dropdowns,
   ledger, receipts/vouchers/statements), not its internal BNK-#### code or
   raw account number. The 2026-08-27 change above had flipped this to show
   the code/account-number instead; that is now undone because it made
   every account picker across the app (transactions, orders, challans,
   payroll, ledger) show an unreadable "BNK-0007" instead of the account's
   actual name, with no way to tell accounts apart at a glance.
   IMPORTANT: this only changes what is DISPLAYED. Every transaction still
   stores tx.acc / tx.acc2 as the bank's *name* internally (the option VALUE
   was never changed) — that field is matched by name in dozens of places
   across the balance engine, bank statements and reports
   (t.acc===bank.name, t.acc===account, etc.), so this label-only change is
   safe and cannot affect any balance calculation. */
function bankDisplayId(b){
  if(!b) return '';
  if(b.name) return b.name;
  const accNo = (b.accno || b.accountNo || b.acc || '').toString().trim();
  if(accNo) return accNo;
  return b.code || '';
}
function bankNameToDisplay(name){
  const n = (name||'').toString().trim();
  if(!n) return '';
  const b = (DB.banks||[]).find(x => (x.name||'').trim() === n);
  return b ? (bankDisplayId(b) || n) : n;
}
window.bankDisplayId = bankDisplayId;
window.bankNameToDisplay = bankNameToDisplay;

// Auto-fill party type based on transaction type
// ── Rule #7: type-specific invoice prefixes (PHP ERP parity) ──
const TX_INV_PREFIX={
  'Sale':'SALE','Customer Sale':'SALE','Warehouse Sale':'WHS','Sales Return':'SRET',
  'Sales Receipt':'RCPT','Customer Collection':'RCPT','Customer Payment Received':'RCPT',
  'Purchase':'PUR','Supplier Purchase':'PUR','Warehouse Purchase':'WHP','Purchase Return':'PRET',
  'Purchase Payment':'PAY','Supplier Payment':'PAY','Supplier Refund':'SREF',
  'Bank Deposit':'DEP','Bank Withdrawal':'WDR','Inter Bank Transfer':'TRF','Inter-Account Transfer':'TRF','Transfer (Internal)':'TRF',
  'Partner Fund':'PFND','Partner Withdrawal':'PWDR','Journal':'JRN',
  'Staff Salary':'SAL','Expense':'EXP','Office Expense':'EXP','Expense Payment':'EXP',
  'Utility Bill':'EXP','Transport Cost':'EXP','Unload Cost':'EXP','Extra Cost':'EXP',
  'Fixed Asset Purchase':'FAP','Asset Sale':'ASL','Production Cost':'PRD',
  'Raw Material Issue':'RMI','Finished Goods Entry':'FGE','Warehouse Transfer':'WHT'
};
function txInvPrefix(type){
  if(TX_INV_PREFIX[type]) return TX_INV_PREFIX[type];
  const t=(type||'').toLowerCase();
  if(t.includes('expense')||t.includes('salary')||t.includes('rent')||t.includes('bill')) return 'EXP';
  return 'INV';
}
function nextInvNo(type){
  const pre=txInvPrefix(type);
  let mx=0;
  (DB.tx||[]).forEach(t=>{
    const m=String(t.inv||'').match(new RegExp('^'+pre+'-(\\d+)$'));
    if(m) mx=Math.max(mx,parseInt(m[1]));
  });
  return pre+'-'+String(mx+1).padStart(4,'0');
}
function txAutoInvoice(type){
  const inv=document.getElementById('tx-inv');
  if(!inv || !type) return;
  const cur=(inv.value||'').trim();
  // Fill when empty, or regenerate our own auto number on type change.
  // Manual entries clear the autoGen flag (input listener) and are never touched.
  if(cur!=='' && inv.dataset.autoGen!=='1') return;
  inv.value=nextInvNo(type);
  inv.dataset.autoGen='1';
}
// ── Rule #4: type-based section relevance ──
const QTY_TYPES=['Sale','Customer Sale','Warehouse Sale','Sales Return','Purchase','Supplier Purchase','Warehouse Purchase','Werhouse Purchase','Purchase Return','Opening Stock','Opening Werhouse Purchase','Warehouse Transfer','Raw Material Issue','Finished Goods Entry','Manufacturing Consumption','Manufacturing Output','Stock Adjustment'];
const TRUCK_TYPES=['Sale','Customer Sale','Warehouse Sale','Purchase','Supplier Purchase','Warehouse Purchase','Werhouse Purchase','Warehouse Transfer'];
// Product Nutrition & Quality: manual collapsible toggle, closed by default.
// Independent of transaction type — see txSectionsForType() below, which
// only shows/hides the outer wrapper's *availability*, never forces it open.
function toggleNutritionSection(){
  const body=document.getElementById('tx-nutrition-body');
  const chevron=document.getElementById('tx-nutrition-chevron');
  if(!body) return;
  const isOpen=body.style.display!=='none';
  body.style.display=isOpen?'none':'';
  if(chevron) chevron.style.transform=isOpen?'':'rotate(180deg)';
}
function txSectionsForType(type){
  const prod=document.getElementById('txsec-product');
  const nutrition=document.getElementById('txsec-nutrition');
  const trans=document.getElementById('txsec-transport');
  const costs=document.getElementById('txsec-costs');
  try{ if(typeof autoSetPurchasePaymentType==='function') autoSetPurchasePaymentType(type||''); }catch(e){}
  if(!type){ if(prod)prod.style.display=''; if(nutrition)nutrition.style.display=''; if(trans)trans.style.display=''; if(costs)costs.style.display='none'; return; }
  const isGoods=QTY_TYPES.includes(type);
  if(prod) prod.style.display = isGoods ? '' : 'none';
  // Nutrition section itself stays visible whenever goods are involved (its
  // body still respects the manual open/close toggle above); fully hidden
  // otherwise since it makes no sense for non-goods transactions.
  if(nutrition) nutrition.style.display = isGoods ? '' : 'none';
  if(trans) trans.style.display = TRUCK_TYPES.includes(type) ? '' : 'none';
  /* Agent A/B, QC, Unload & Other Cost section removed from the New
     Transaction form per Ayan's request (2026-09-12) — always hidden now,
     regardless of type. Fields stay in the DOM so calcTotalCost()/cost-line
     ledger/dashboard KPIs/CSV exports keep working off historical data. */
  if(costs) costs.style.display = 'none';
}
// ── Rule #6 (light): average purchase cost + estimated profit hint on sales ──
function avgPurchaseCost(product){
  let qty=0,val=0;
  (DB.tx||[]).forEach(t=>{
    if(!isCogsTx(t)) return;
    if(product && (t.prod||t.product)!==product) return;
    const q=parseFloat(t.wt||t.qty||0), a=parseFloat(txAmt(t));
    if(q>0&&a>0){qty+=q;val+=a;}
  });
  return qty>0? val/qty : 0;
}
function txProfitHint(){
  const type=document.getElementById('tx-type')?.value;
  if(!['Sale','Customer Sale','Warehouse Sale'].includes(type)) return;
  const prod=document.getElementById('tx-prod')?.value||'';
  const rate=parseFloat(document.getElementById('tx-rate')?.value)||0;
  const w=parseFloat(document.getElementById('tx-wt')?.value)||parseFloat(document.getElementById('tx-grosswt')?.value)||parseFloat(document.getElementById('tx-qty')?.value)||0;
  const avg=avgPurchaseCost(prod)||avgPurchaseCost('');
  if(avg>0 && rate>0 && w>0 && typeof showSmartHint==='function'){
    const profit=(rate-avg)*w;
    showSmartHint('tx-rate', (profit>=0?'📈 Est. profit ':'📉 Est. loss ')+f(Math.abs(profit))+' (avg purchase cost ৳'+avg.toFixed(2)+'/kg)');
  }
}
function smartTypeToPartyType(){
  calcSalesTax();
  const type = document.getElementById('tx-type').value;
  const ptype = document.getElementById('tx-ptype');
  const partyInput = document.getElementById('tx-party');
  txSectionsForType(type);

  const typeMap = {
    'Sale':'Customer','Sales Return':'Customer','Customer Sale':'Customer',
    'Customer Collection':'Customer','Customer Payment Received':'Customer',
    'Advance from Customer':'Customer','Customer Due':'Customer',
    'Purchase':'Supplier','Purchase Return':'Supplier','Supplier Purchase':'Supplier',
    'Supplier Payment':'Supplier','Advance to Supplier':'Supplier','Supplier Refund':'Supplier',
    'Supplier Due':'Supplier','Supplier Advance':'Supplier',
    'Partner Fund':'Partner','Partner Withdrawal':'Partner',
    'Staff Salary':'Employee',
    'Bank Deposit':'Other','Bank Withdrawal':'Other',
    'Inter Bank Transfer':'Other','Bkash Payment Paid':'Other','Bkash Receive':'Other',
  };

  if(typeMap[type]){
    ptype.value = typeMap[type];
    // Filter party datalist by type
    smartFilterPartyList(typeMap[type]);
  }

  // Auto-generate invoice number
  autoGenInvoice(type);

  // Show/hide relevant sections
  smartShowSections(type);

  // Call existing toggleSalesCost
  toggleSalesCost();
}

function smartFilterPartyList(ptype){
  const dl = document.getElementById('dl-party');
  if(!dl) return;
  dl.innerHTML = '';

  let parties = [];
  if(ptype === 'Customer'){
    parties = (DB.customers||[]).filter(c => c.type === 'Customer' || c.type === 'Both' || !c.type);
  } else if(ptype === 'Supplier'){
    parties = (DB.customers||[]).filter(c => c.type === 'Supplier' || c.type === 'Both');
  } else if(ptype === 'Partner'){
    parties = DB.partners;
  } else {
    // All parties
    parties = [...DB.customers, ...DB.partners];
  }

  parties.forEach(p => {
    const opt = document.createElement('option');
    opt.value = p.name;
    dl.appendChild(opt);
  });
}

function autoGenInvoice(type){
  const invField = document.getElementById('tx-inv');
  if(invField.value && !invField.dataset.autoGen) return; // Don't overwrite manual entry

  const prefixMap = {
    'Sale':'SL','Sales Return':'SR','Purchase':'PO','Purchase Return':'PR',
    'Customer Collection':'RC','Supplier Payment':'PY','Supplier Refund':'SRF','Bank Deposit':'BD',
    'Bank Withdrawal':'BW','Partner Fund':'PF','Partner Withdrawal':'PW',
    'Staff Salary':'SAL','Expense':'EXP','Journal':'JV',
    'Warehouse Purchase':'WP','Warehouse Sale':'WS',
  };
  // Delegates to the per-type sequential generator (PHP ERP parity: SALE-0001, PUR-0001…)
  void prefixMap;
  invField.value = nextInvNo(type);
  invField.dataset.autoGen = '1';
}

function smartCalcAmount(){
  const qty = parseFloat(document.getElementById('tx-qty')?.value) || 0;
  const rate = parseFloat(document.getElementById('tx-rate')?.value) || 0;
  const netWt = parseFloat(document.getElementById('tx-wt')?.value) || 0;
  const grossWt = parseFloat(document.getElementById('tx-grosswt')?.value) || 0;
  if(rate <= 0) return;
  // Priority rule: Net Weight × Rate; if Net blank → Gross Weight × Rate; else Qty × Rate
  let base = 0, label = '';
  if(netWt > 0){ base = netWt; label = 'Net Wt'; }
  else if(grossWt > 0){ base = grossWt; label = 'Gross Wt'; }
  else if(qty > 0){ base = qty; label = 'Qty'; }
  if(base > 0){
    // FIX 3: Bag Weight Deduction — 150g (0.15 kg) per bag for Sale transactions
    // Formula: Billable Weight = Total Weight − (bagqty × 0.15)
    //          Net Sale Amount = Billable Weight × Rate (tax applied separately)
    const _txType = (document.getElementById('tx-type')?.value || '').toLowerCase();
    const _isSaleTx = (typeof isSaleType === 'function') ? isSaleType(_txType)
      : ['sale','customer sale','warehouse sale'].includes(_txType);
    const bagqty = parseFloat(document.getElementById('tx-bagqty')?.value) || 0;
    let billableBase = base;
    let bagDeductKg = 0;
    /* BUSINESS RULE: the 150 g tare is the weight of the sack itself, so it
       is deducted only where there IS a sack of that kind. It used to be
       taken off every sale regardless of bag type — including Bulk, which is
       sold loose and has no sack at all. Which types carry a tare, and how
       much, is set in Cost Calculation (default: Plastic 150 g). */
    const _bagtypeVal = document.getElementById('tx-bagtype')?.value || '';
    /* Grams per bag typed on the entry win over the bag type's standard
       figure — one sack in a load can weigh differently and the deduction is
       agreed with the buyer there and then. */
    var _gramsEl = document.getElementById('tx-tare-grams');
    var _gramsTyped = _gramsEl && String(_gramsEl.value||'').trim()!=='' ? (parseFloat(_gramsEl.value)||0) : null;
    if(_isSaleTx && bagqty > 0){
      var _tareKg = (_gramsTyped!=null) ? (_gramsTyped/1000)
                  : (typeof ayanBagTareKg === 'function' ? ayanBagTareKg(_bagtypeVal) : 0);
      bagDeductKg = bagqty * _tareKg;
      billableBase = Math.max(0, base - bagDeductKg);
    }
    /* PURCHASE DEDUCTIONS — what comes off the weighbridge figure when goods
       arrive: the sacks' own weight, and a moisture or quality cut. A rate
       cut takes the money off the price per KG instead of off the weight.
       All three are settings and all three start at zero, so nothing is
       deducted until your own rule is entered in Business Rules. */
    const _isPurchTx = ['purchase','warehouse purchase','supplier purchase'].includes(_txType);
    let purchDeductKg = 0, effRate = rate;
    if(_isPurchTx && typeof ayanPurchaseRules === 'function'){
      var _pr = ayanPurchaseRules();
      if(_pr.applyBagTare && bagqty > 0 && typeof ayanBagTareKg === 'function')
        purchDeductKg += bagqty * ayanBagTareKg(_bagtypeVal);
      if(_pr.moisturePct > 0) purchDeductKg += base * _pr.moisturePct / 100;
      if(purchDeductKg > 0) billableBase = Math.max(0, base - purchDeductKg);
      if(_pr.rateCutPerKg > 0) effRate = Math.max(0, rate - _pr.rateCutPerKg);
    }
    const amt = billableBase * effRate;
    document.getElementById('tx-amt').value = amt.toFixed(2);
    // Store bag deduction values for saveTx() to capture
    const _bdKgEl = document.getElementById('tx-bagdeduct-kg');
    if(_bdKgEl) _bdKgEl.value = bagDeductKg.toFixed(3);
    const _bdAmtEl = document.getElementById('tx-bagdeduct-amt');
    if(_bdAmtEl) _bdAmtEl.value = (bagDeductKg * rate).toFixed(2);
    const _pdKgEl = document.getElementById('tx-purchdeduct-kg');
    if(_pdKgEl) _pdKgEl.value = purchDeductKg.toFixed(3);
    const _pdAmtEl = document.getElementById('tx-purchdeduct-amt');
    if(_pdAmtEl) _pdAmtEl.value = (purchDeductKg * rate + (rate - effRate) * billableBase).toFixed(2);
    if(_isSaleTx && bagDeductKg > 0){
      showSmartHint('tx-amt', `✅ Auto (${label}): ${pn(base)}−${pn(bagDeductKg)}kg bag-tare=${pn(billableBase)} × ৳${pf(rate)} = ৳${pf(amt)}`);
    } else if(_isPurchTx && (purchDeductKg > 0 || effRate !== rate)){
      showSmartHint('tx-amt', `✅ Auto (${label}): ${pn(base)}${purchDeductKg>0?('−'+pn(purchDeductKg)+'kg deduction'):''}=${pn(billableBase)} × ৳${pf(effRate)}${effRate!==rate?(' (rate −৳'+pf(rate-effRate)+')'):''} = ৳${pf(amt)}`);
    } else {
      showSmartHint('tx-amt', `✅ Auto (${label}): ${pn(base)} × ৳${pf(rate)} = ৳${pf(amt)}`);
    }
    /* FIX (2026-08-20): tx-amt only had VAT/sales-tax recalculated on its own
       oninput handler, but every real sale sets the amount HERE (weight ×
       rate) by writing .value directly — that never fires a native 'input'
       event, so calcSalesTax() never ran and tax silently stayed ৳0 on every
       sale, no matter the configured rate. Call it directly whenever the
       amount is (re)computed, from whichever field drove it. */
    try{ calcSalesTax(); }catch(e){}
    try{ calcWeightLoss(); }catch(e){}
    try{ calcAdvanceControl(); }catch(e){}
  }
}

/**
 * Universal Bag Calculation, Standard Weight (50kg/bag).
 * QTY, GROSS WEIGHT, and NET WEIGHT all auto-fill to BAG QTY × 50.00 the
 * moment Bag Qty is entered. All three stay fully EDITABLE — the same
 * "protection flag" pattern already used elsewhere in this file (an
 * auto-fill only ever writes into a field that is still empty or was itself
 * still flagged as auto-filled; the instant the user types their own number
 * into any of the three, that field's flag flips off and this logic will
 * never again overwrite it, even on the next bag-qty keystroke).
 * Any physical weight loss (e.g. bag tare weight) is deliberately NOT
 * subtracted automatically here — that is now the explicit, visible
 * Weight Loss / Deduction mechanism (see calcWeightLoss()) so the user
 * always sees exactly what was deducted and why, instead of it silently
 * lowering Net Weight before they even look at the form.
 */
function initUniversalBagAndWeightLogic() {
  const bagQtyInput = document.getElementById('tx-bagqty');
  const txTypeSelect = document.getElementById('tx-type');
  const qtyInput = document.getElementById('tx-qty');
  const netWtInput = document.getElementById('tx-wt') || document.getElementById('tx-netwt');
  const grossWtInput = document.getElementById('tx-grosswt');

  if (!bagQtyInput) return;

  function calculateWeights() {
    const bags = parseFloat(bagQtyInput.value) || 0;
    if (bags <= 0) return;

    /* FIX: this was hardcoded to 50 kg a bag while Business Rules carries a
       Standard bag weight setting that nothing read. */
    let standardWeightPerBag = 50;
    try{ if(typeof ayanRules==='function'){ const _r=ayanRules(); if(_r && +_r.bagWeightKg>0) standardWeightPerBag=+_r.bagWeightKg; } }catch(e){}
    const total = bags * standardWeightPerBag;

    [qtyInput, grossWtInput, netWtInput].forEach(input => {
      if (input && (!input.value || input.dataset.autoFilled === 'true')) {
        input.value = total.toFixed(2);
        input.dataset.autoFilled = 'true';
      }
    });

    if (typeof smartCalcAmount === 'function') {
      smartCalcAmount();
    }
    if (typeof calcWeightLoss === 'function') {
      calcWeightLoss();
    }
  }

  bagQtyInput.addEventListener('input', calculateWeights);
  if (txTypeSelect) txTypeSelect.addEventListener('change', calculateWeights);

  [qtyInput, netWtInput, grossWtInput].forEach(input => {
    if (input) {
      input.addEventListener('input', function() {
        this.dataset.autoFilled = 'false';
      });
    }
  });
}

document.addEventListener('DOMContentLoaded', function() {
  initUniversalBagAndWeightLogic();
});

/**
 * Sales Deduction / Weight Loss Handling (Tax-Formula Style).
 * Mirrors calcSalesTax()'s pattern exactly, but for physical weight loss on
 * Sale / Warehouse Sale transactions:
 *   Weight Loss (KG)      = Gross Weight − Net Weight   (only when positive)
 *   Deduction/Loss Amount = Weight Loss (KG) × Rate
 * This amount is purely informational/display here — it is what gets
 * carried into the saved transaction as weightLossKg/weightLossAmt and
 * posted to the ledger as a Sales Expense/Deduction (see saveTx() and
 * syncWeightLossExpense()). It never touches tx-amt directly: tx-amt is
 * already Net Weight × Rate via smartCalcAmount()'s existing priority rule,
 * which is exactly "Final Payable = Net Weight × Rate" — so Customer
 * Receivable already reflects the post-deduction figure with no double
 * counting; this section only makes the loss/deduction itself visible and
 * capturable as its own ledger line.
 */
function calcWeightLoss(){
  try{
    const typeEl = document.getElementById('tx-type');
    const type = typeEl ? typeEl.value : '';
    const section = document.getElementById('tx-wloss-section');
    const amtSection = document.getElementById('tx-wlossamt-section');
    const kgEl = document.getElementById('tx-wloss-kg');
    const amtEl = document.getElementById('tx-wloss-amt');
    const pctDisplay = document.getElementById('tx-wloss-pct-display');

    const isSale = typeof isSaleType === 'function' && isSaleType(type);
    if(!isSale){
      if(section) section.style.display='none';
      if(amtSection) amtSection.style.display='none';
      if(kgEl) kgEl.value='';
      if(amtEl) amtEl.value='';
      return;
    }

    const gross = parseFloat(document.getElementById('tx-grosswt')?.value) || 0;
    const net   = parseFloat(document.getElementById('tx-wt')?.value) || 0;
    const rate  = parseFloat(document.getElementById('tx-rate')?.value) || 0;
    const lossKg = gross>0 && net>0 ? Math.max(0, gross - net) : 0;

    if(lossKg<=0){
      if(section) section.style.display='none';
      if(amtSection) amtSection.style.display='none';
      if(kgEl) kgEl.value='';
      if(amtEl) amtEl.value='';
      return;
    }

    const lossPct = gross>0 ? (lossKg/gross*100) : 0;
    const lossAmt = lossKg * rate;

    if(pctDisplay) pctDisplay.textContent = lossPct.toFixed(2);
    if(kgEl) kgEl.value = lossKg.toFixed(2);
    if(section) section.style.display='grid';

    if(rate>0){
      if(amtEl) amtEl.value = lossAmt.toFixed(2);
      if(amtSection) amtSection.style.display='grid';
    } else {
      if(amtEl) amtEl.value='';
      if(amtSection) amtSection.style.display='none';
    }
  }catch(e){ console.warn('calcWeightLoss', e); }
}
window.calcWeightLoss = calcWeightLoss;

/* FIX (2026-08-20): Agent/QC/Unload/Other sale costs were meant to
   auto-calculate from DB.costRates the moment weight/bags were entered, but
   nothing actually called that math from the real data-entry fields —
   calcTxCost()/onTxQtyChange() (the functions that did it) were never wired
   to any input, and the one path that WAS wired (the "Rates" override panel)
   only recalculated when the RATE fields themselves were edited by hand, and
   priced Unload the same as everything else — per KG — instead of per BAG.
   This is now the one live path: weight-based costs (Agent A/B, QC, Other)
   use KG; Unload uses bag count, matching "৳3 per bag" not "৳3 per kg".
   QC's rate can additionally vary by location (see DB.locationRates[].qcRate,
   set on the Location Rates screen) since QC cost is paid per location, not
   at one flat company-wide rate — falls back to the global rate when a
   location has none configured. Only applies to Sale-side transactions
   (isSaleType) — purchases don't carry these costs.
   Every auto-filled cell keeps the same "protection flag" used for weight
   above: an auto-fill is only written while the field is empty or still
   flagged as auto-filled, so typing your own number always wins and sticks,
   exactly as before. */
/* Confirmed with the owner (2026-08-20): raw bran bought under Warehouse
   Purchase — whatever grade/name it's bought as — should pool into ONE
   sellable stock item, "Parboiled Rice Bran High Fat", costed at the
   weighted-average purchase price. That averaging already happens for free
   in stockPosition()'s existing weighted-average-cost engine (confirmed
   already correct — nothing to change there); the only gap was that nothing
   made Warehouse Purchases actually land in that one stock bucket, so a
   purchase entered as e.g. "BRAN 18% FAT" built up stock under a totally
   different product than the one being sold ("Parboiled Rice Bran High
   Fat"), which is exactly why that product showed negative stock. This is a
   DEFAULT, not a lock — same protection-flag pattern as the weight fields —
   so an occasional purchase of a genuinely different, separately-tracked
   product can still be typed in by hand. */
function autoFillWarehousePurchaseProduct(){
  try{
    const typeEl=document.getElementById('tx-type');
    if(!typeEl || typeEl.value!=='Warehouse Purchase') return;
    const prodEl=document.getElementById('tx-prod');
    if(!prodEl) return;
    if(!prodEl.value || prodEl.dataset.autoFilled==='true'){
      prodEl.value='Parboiled Rice Bran High Fat';
      prodEl.dataset.autoFilled='true';
    }
  }catch(e){ console.warn('autoFillWarehousePurchaseProduct', e); }
}
/* ── BAG TYPE RULES ───────────────────────────────────────────────────
   Two things depend on how the goods leave the yard:

     Plastic  · 150 g tare per bag deducted from the billable weight
     Jute     · 700 g tare per bag deducted from the billable weight
     Bulk     · no sacks, so no tare — and unloading is charged by weight,
                ৳50 per 1000 kg, not per bag

   Both figures are settings, not constants, so they can be changed without
   touching the code: DB.costRates.tare (kg per bag, by type) and
   DB.costRates.unloadBulk (৳ per 1000 kg). */
function ayanBagRules(){
  if(!DB.costRates) DB.costRates={};
  var c=DB.costRates;
  if(!c.tare || typeof c.tare!=='object') c.tare={Plastic:0.15, Jute:0.7, Bulk:0};
  if(c.tare.Plastic==null) c.tare.Plastic=0.15;
  if(c.tare.Jute==null)    c.tare.Jute=0.7;
  c.tare.Bulk=0;                                     // bulk never has a sack
  if(c.unloadBulk==null)   c.unloadBulk=50;          // ৳ per 1000 kg
  return c;
}
function ayanIsBulk(bagtype){ return String(bagtype||'').trim().toLowerCase()==='bulk'; }
function ayanBagTareKg(bagtype){
  var c=ayanBagRules(), t=String(bagtype||'').trim();
  if(!t) return 0;                                   // no type chosen = no tare
  var key=Object.keys(c.tare).find(function(k){return k.toLowerCase()===t.toLowerCase();});
  return key ? (parseFloat(c.tare[key])||0) : 0;
}
/* Unloading: per 1000 kg when sold in bulk, per bag otherwise. */
function ayanUnloadCost(bagtype, bags, kg){
  var c=ayanBagRules();
  if(ayanIsBulk(bagtype)) return (parseFloat(kg)||0)/1000 * (parseFloat(c.unloadBulk)||0);
  return (parseFloat(bags)||0) * (parseFloat(c.unload)||0);
}
function ayanUnloadLabel(bagtype){
  return ayanIsBulk(bagtype) ? ('1000KG×'+(ayanBagRules().unloadBulk||0))
                             : ('Bag×'+(ayanBagRules().unload||0));
}

/* ── Mirrored weight fields stay in step ──────────────────────────────
   Bag Qty fills Qty, Gross Weight and Net Weight with the same figure, so a
   normal entry has all three equal. Reopen it to edit, change Gross Weight,
   and only Gross moved — Net kept the old figure and, being the one that
   counts, quietly held the amount and the stock at the old weight. When the
   three were in step, they stay in step; a Net Weight you have deliberately
   made different is never touched. */
(function(){
  function sync(e){
    var el=e.target;
    if(!el||!el.id) return;
    if(el.id!=='tx-grosswt' && el.id!=='tx-qty') return;
    var prev=el.dataset.ayanPrev;
    var now=String(el.value||'');
    if(prev===undefined){ el.dataset.ayanPrev=now; return; }
    var others=(el.id==='tx-grosswt')?['tx-wt','tx-qty']:['tx-wt','tx-grosswt'];
    others.forEach(function(id){
      var o=document.getElementById(id);
      if(!o) return;
      if(String(o.value||'')===prev || String(o.value||'')===''){ o.value=now; }
    });
    el.dataset.ayanPrev=now;
    try{ if(typeof smartCalcAmount==='function') smartCalcAmount(); }catch(_){}
    try{ if(typeof calcDue==='function') calcDue(); }catch(_){}
    try{ if(typeof autoFillSaleCosts==='function') autoFillSaleCosts(); }catch(_){}
    try{ if(typeof autoFillPurchaseCosts==='function') autoFillPurchaseCosts(); }catch(_){}
  }
  document.addEventListener('focusin',function(e){
    if(e.target&&(e.target.id==='tx-grosswt'||e.target.id==='tx-qty')) e.target.dataset.ayanPrev=String(e.target.value||'');
  },true);
  document.addEventListener('input',sync,true);
})();

/* Purchase costs: unloading (from the bag type), labour and commission per
   KG. Nothing is filled in unless a rate has been set in Business Rules, and
   a figure typed in by hand is never overwritten. */
function autoFillPurchaseCosts(){
  try{
    if(typeof ayanIsPurchaseType!=='function' || typeof ayanPurchaseRules!=='function') return;
    const type=document.getElementById('tx-type')?.value||'';
    if(!ayanIsPurchaseType(type)) return;
    const pr=ayanPurchaseRules();
    const kg=parseFloat(document.getElementById('tx-wt')?.value)
          || parseFloat(document.getElementById('tx-grosswt')?.value)
          || parseFloat(document.getElementById('tx-qty')?.value) || 0;
    const bags=parseFloat(document.getElementById('tx-bagqty')?.value)||0;
    const bagtype=document.getElementById('tx-bagtype')?.value||'';
    const put=(id,val,tagId,tagTxt)=>{
      const el=document.getElementById(id);
      if(!el || !(val>0)) return;
      if(!el.value || el.dataset.autoFilled==='true'){
        el.value=val.toFixed(2);
        el.dataset.autoFilled='true';
        const tag=document.getElementById(tagId);
        if(tag) tag.textContent=tagTxt||'';
      }
    };
    if(pr.autoUnload) put('tx-unload', ayanUnloadCost(bagtype,bags,kg), 'tag-unload', ayanUnloadLabel(bagtype));
    if(pr.labourPerKg>0)     put('tx-qc',        kg*pr.labourPerKg,     'tag-qc',     'KG\u00d7'+pr.labourPerKg);
    if(pr.commissionPerKg>0) put('tx-othercost', kg*pr.commissionPerKg, 'tag-other',  'KG\u00d7'+pr.commissionPerKg);
    if(typeof calcTotalCost==='function') calcTotalCost();
  }catch(e){ console.warn('autoFillPurchaseCosts', e); }
}

function qcRateForLocation(locName){
  const loc=(DB.locationRates||[]).find(l=>String(l.name||'').trim().toLowerCase()===String(locName||'').trim().toLowerCase());
  const locRate=loc&&loc.qcRate!=null&&loc.qcRate!=='' ? parseFloat(loc.qcRate) : NaN;
  return isFinite(locRate) ? locRate : (parseFloat(DB.costRates?.qc)||0.10);
}
function autoFillSaleCosts(){
  try{
    const typeEl=document.getElementById('tx-type');
    if(!typeEl || !(typeof isSaleType==='function' && isSaleType(typeEl.value))) return;
    const kg = parseFloat(document.getElementById('tx-wt')?.value)
            || parseFloat(document.getElementById('tx-grosswt')?.value)
            || parseFloat(document.getElementById('tx-qty')?.value) || 0;
    const bags = parseFloat(document.getElementById('tx-bagqty')?.value) || 0;
    const loc = document.getElementById('tx-loc')?.value || '';
    const rA = parseFloat(DB.costRates?.agentA)||0.25;
    const rB = parseFloat(DB.costRates?.agentB)||0.30;
    const rQ = qcRateForLocation(loc);
    const rU = parseFloat(DB.costRates?.unload)||3.00;
    /* FIX (2026-09-12): "Other (৳/KG)" and the new "Another 2 (৳/KG)" rate
       were editable in Business Rules and dutifully saved into
       DB.costRates, but nothing ever read them back — Other Cost and
       Another 2 Cost stayed manual-entry-only on every Sale no matter what
       rate was set. They now auto-fill exactly like Agent A/B and QC. */
    const rO  = parseFloat(DB.costRates?.other)||0;
    const rO2 = parseFloat(DB.costRates?.other2)||0;
    /* Sale-time costs calculate themselves from the rates in Cost
       Calculation: agent A and B and QC per KG, unloading per bag. A figure
       you type in yourself is never overwritten (dataset.autoFilled). Set a
       rate to 0 in Cost Calculation to stop that cost being charged. */
    const bagtype = document.getElementById('tx-bagtype')?.value || '';
    const unloadCost = ayanUnloadCost(bagtype, bags, kg);
    const fields=[
      ['tx-agentAcost', kg>0   ? kg*rA    : null, 'tag-agentA', kg>0?('KG×'+rA):''],
      ['tx-agentBcost', kg>0   ? kg*rB    : null, 'tag-agentB', kg>0?('KG×'+rB):''],
      ['tx-qc',         kg>0   ? kg*rQ    : null, 'tag-qc',     kg>0?('KG×'+rQ):''],
      ['tx-unload',     unloadCost>0 ? unloadCost : null, 'tag-unload', unloadCost>0?ayanUnloadLabel(bagtype):''],
      ['tx-othercost',  kg>0 && rO>0  ? kg*rO  : null, 'tag-other', kg>0&&rO>0?('KG×'+rO):''],
      ['tx-othercost2', kg>0 && rO2>0 ? kg*rO2 : null, 'tag-other2', kg>0&&rO2>0?('KG×'+rO2):'']
    ];
    fields.forEach(([id,val,tagId,tagTxt])=>{
      const el=document.getElementById(id);
      if(!el || val==null) return;
      if(!el.value || el.dataset.autoFilled==='true'){
        el.value=val.toFixed(2);
        el.dataset.autoFilled='true';
        const tag=document.getElementById(tagId);
        if(tag) tag.textContent=tagTxt;
      }
    });
    ['tx-agentAcost','tx-agentBcost','tx-qc','tx-unload','tx-othercost','tx-othercost2'].forEach(id=>{
      const el=document.getElementById(id);
      if(el && !el.dataset._autoProtectBound){
        el.dataset._autoProtectBound='1';
        el.addEventListener('input',function(){ this.dataset.autoFilled='false'; });
      }
    });
    if(typeof calcTotalCost==='function') calcTotalCost();
  }catch(e){ console.warn('autoFillSaleCosts', e); }
}

function smartCalcDue(){
  const amt = parseFloat(document.getElementById('tx-amt')?.value) || 0;
  const due = calcDue();
  if(amt > 0){
    if(due > 0) showSmartHint('tx-due', `⚠️ Due: ৳${pf(due)}`);
    else if(due < 0) showSmartHint('tx-due', `✅ Overpaid: ৳${pf(Math.abs(due))}`);
    else showSmartHint('tx-due', `✅ Fully settled`);
  }
}

function smartShowSections(type){
  const salesTypes = ['Sale','Sales Return','Customer Sale','Customer Collection'];
  const purchaseTypes = ['Purchase','Purchase Return','Supplier Purchase'];
  const bankTypes = ['Bank Deposit','Bank Withdrawal','Inter Bank Transfer','Bkash Payment Paid','Bkash Receive'];
  const expenseTypes = ['Staff Salary','Utility Bill','Office Expense','Transport Cost','Expense'];

  const isSale = salesTypes.includes(type);
  const isPurchase = purchaseTypes.includes(type);
  const isBank = bankTypes.includes(type);

  // Highlight form title with type color
  const titleEl = document.getElementById('mTx-title');
  if(titleEl){
    const colors = {
      sale:'#16a34a', purchase:'#2563eb', bank:'#7c3aed',
      expense:'#dc2626', other:'#0f3d26'
    };
    const cat = isSale?'sale':isPurchase?'purchase':isBank?'bank':expenseTypes.includes(type)?'expense':'other';
    const icons = {sale:'🛒',purchase:'📦',bank:'🏦',expense:'💸',other:'📋'};
    titleEl.innerHTML = `${icons[cat]} ${type} — Transaction Entry`;
    titleEl.style.color = colors[cat];
  }
}

function showSmartHint(fieldId, msg){
  const field = document.getElementById(fieldId);
  if(!field) return;
  let hint = field.parentElement.querySelector('.smart-hint');
  if(!hint){
    hint = document.createElement('div');
    hint.className = 'smart-hint';
    field.parentElement.appendChild(hint);
  }
  hint.textContent = msg;
  hint.style.opacity = '1';
  setTimeout(() => { hint.style.opacity = '0'; }, 3000);
}

// Clear auto-gen flag when user manually edits invoice
document.addEventListener('DOMContentLoaded', function(){
  const invField = document.getElementById('tx-inv');
  if(invField){
    invField.addEventListener('input', function(){
      delete this.dataset.autoGen;
    });
  }
});


