// FEATURE 4: Tenders Management
// ══════════════════════════════════════════════════════════════

// Ensure DB has tenders array



function calcTenderPL(){
  const val = parseFloat(document.getElementById('td-value').value) || 0;
  const adv = parseFloat(document.getElementById('td-advance').value) || 0;
  const cost = parseFloat(document.getElementById('td-cost').value) || 0;
  const transport = parseFloat(document.getElementById('td-transport').value) || 0;
  const other = parseFloat(document.getElementById('td-other-cost').value) || 0;
  const refund = parseFloat(document.getElementById('td-refund').value) || 0;

  const totalCost = adv + cost + transport + other;
  const net = val + refund - totalCost;

  document.getElementById('td-pl-value').textContent = '৳' + pf(val);
  document.getElementById('td-pl-cost').textContent = '৳' + pf(totalCost);
  document.getElementById('td-pl-refund').textContent = '৳' + pf(refund);
  const netEl = document.getElementById('td-pl-net');
  netEl.textContent = '৳' + pf(net);
  netEl.style.color = net >= 0 ? '#16a34a' : '#dc2626';
}







function updateTenderSummary(){
  const tenders = DB.tenders || [];
  const totalCount = tenders.length;
  const totalValue = tenders.reduce((s,t) => s+(t.value||0), 0);
  const totalAdv = tenders.reduce((s,t) => s+(t.advance||0), 0);
  const totalCost = tenders.reduce((s,t) => s+(t.totalCost||0), 0);
  const netProfit = tenders.reduce((s,t) => s+(t.net||0), 0);

  const el = (id, val) => { const e = document.getElementById(id); if(e) e.textContent = val; };
  el('td-total-count', totalCount);
  el('td-total-value', '৳'+pf(totalValue));
  el('td-total-advance', '৳'+pf(totalAdv));
  el('td-total-cost', '৳'+pf(totalCost));
  el('td-net-profit', '৳'+pf(netProfit));
}

function exportTenders(){
  const tenders = DB.tenders || [];
  if(!tenders.length){ alert('No tenders to export'); return; }
  const rows = [['Tender No','Title','Party','Type','Value','Advance','Total Cost','Refund','Net P&L','Status','Submit Date','Notes']];
  tenders.forEach(t => rows.push([
    t.no||'', t.title||'', t.party||'', t.type||'',
    t.value||0, t.advance||0, t.totalCost||0, t.refund||0, t.net||0,
    t.status||'', t.submitDate||'', t.notes||''
  ]));
  const csv = rows.map(r => r.map(c => __csvCell(c)).join(',')).join('\n');
  const blob = new Blob([csv], {type:'text/csv'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = 'tenders_export.csv'; a.click();
}


