// ── Payroll Tab Switcher ──
// Clipboard that also works on file:// and older browsers (falls back to execCommand)
function copyTextSafe(text){
  if(navigator.clipboard && navigator.clipboard.writeText){
    return navigator.clipboard.writeText(text).catch(()=>copyTextSafe._fallback(text));
  }
  return copyTextSafe._fallback(text);
}
copyTextSafe._fallback=function(text){
  return new Promise((res,rej)=>{
    try{
      const ta=document.createElement('textarea');
      ta.value=text; ta.style.position='fixed'; ta.style.opacity='0';
      document.body.appendChild(ta); ta.focus(); ta.select();
      const ok=document.execCommand('copy');
      document.body.removeChild(ta);
      ok?res():rej(new Error('copy failed'));
    }catch(e){rej(e);}
  });
};

function switchPayrollTab(tab){
  ['employees','salary-history','advances'].forEach(t => {
    const panel = document.getElementById('pr-panel-'+t);
    const btn = document.getElementById('pr-tab-'+t);
    if(panel) panel.style.display = t === tab ? 'block' : 'none';
    if(btn){
      btn.style.color = t === tab ? '#16a34a' : '#6b7280';
      btn.style.borderBottom = t === tab ? '3px solid #16a34a' : 'none';
      btn.style.fontWeight = t === tab ? '700' : '600';
    }
  });
  if(tab === 'salary-history') renderSalaryHistory();
  if(tab === 'advances') renderAdvances();
}

// ── Employee Modal ──


function calcEmpNet(){
  const basic = parseFloat(document.getElementById('emp-basic').value)||0;
  const house = parseFloat(document.getElementById('emp-house').value)||0;
  const transport = parseFloat(document.getElementById('emp-transport').value)||0;
  const other = parseFloat(document.getElementById('emp-other-allow').value)||0;
  const tax = parseFloat(document.getElementById('emp-tax').value)||0;
  const deduct = parseFloat(document.getElementById('emp-deduct').value)||0;
  const net = basic + house + transport + other - tax - deduct;
  const el = document.getElementById('emp-net-display');
  if(el){ el.textContent = '৳'+pf(net); el.style.color = net>=0?'#16a34a':'#dc2626'; }
}





function renderPayrollEmployees(){
  const tbody = document.getElementById('pr-emp-tbody');
