    return;
  }
  if(tbody) tbody.innerHTML = (DB.employees||[]).map(e => {
    const advDue = (DB.empAdvances||[]).filter(a => a.empId===e.id)
      .reduce((s,a) => s+(a.amount||0)-(a.recovered||0), 0);
    const sc = e.status==='Active'?'#16a34a':e.status==='On Leave'?'#d97706':'#6b7280';
    return `<tr style="border-bottom:1px solid #f3f4f6;" data-hover-bg="#f9fafb">
      <td style="padding:10px 12px;">
        <div style="font-weight:700;color:#111827;">${escHTML(e.name)}</div>
