      <td style="padding:10px 12px;text-align:right;font-weight:600;">৳${pf(e.basic||0)}</td>
      <td style="padding:10px 12px;text-align:right;color:#2563eb;">৳${pf((e.house||0)+(e.transport||0)+(e.otherAllow||0))}</td>
      <td style="padding:10px 12px;text-align:right;font-weight:800;color:#16a34a;">৳${pf(e.net||0)}</td>
      <td style="padding:10px 12px;text-align:right;color:${advDue>0?'#dc2626':'#6b7280'};">৳${pf(advDue)}</td>
