        <button data-x-click="deleteEmployee(${e.id})" style="background:#fef2f2;border:1px solid #fecaca;color:#dc2626;padding:4px 10px;border-radius:5px;font-size:11px;cursor:pointer;">🗑️</button>
        <button data-x-click="openSalarySlipModal(${e.id})" style="background:#eff6ff;border:1px solid #bfdbfe;color:#2563eb;padding:4px 10px;border-radius:5px;font-size:11px;cursor:pointer;margin-left:4px;">🧾 Slip</button>
