// ── Salary Payment Modal ──
function openSalaryModal(){
  const modal = document.getElementById('mSalary');
  const empSel = document.getElementById('sal-emp');
  empSel.innerHTML = '<option value="">-- Select Employee --</option>';
  (DB.employees||[]).filter(e=>e.status==='Active').forEach(e => {
    const opt = document.createElement('option');
    opt.value = e.id; opt.textContent = e.name;
    empSel.appendChild(opt);
  });

  const bankSel = document.getElementById('sal-bank');
  bankSel.innerHTML = '<option value="">-- Select Account --</option>';
  (DB.banks||[]).forEach(b => {
    const opt = document.createElement('option');
    opt.value = b.name; opt.textContent = b.name;
    bankSel.appendChild(opt);
  });

  const today = new Date();
  document.getElementById('sal-date').value = today.toISOString().split('T')[0];
  document.getElementById('sal-month').value = today.toISOString().slice(0,7);
  ['sal-basic','sal-allow','sal-deduct','sal-adv-recovery'].forEach(id => {
    document.getElementById(id).value = '';
  });
  document.getElementById('sal-notes').value = '';
  calcSalaryNet();
  modal.style.display = 'flex';
}

function autoFillSalary(){
  const empId = document.getElementById('sal-emp').value; /* FIX O: was parseInt() — employee ids are UUID strings post-Supabase-migration, so coercing to a number always failed the === comparison below. */
  if(!empId) return;
  const emp = (DB.employees||[]).find(e => e.id === empId);
  if(!emp) return;
  document.getElementById('sal-basic').value = emp.basic||0;
  const allow = (emp.house||0)+(emp.transport||0)+(emp.otherAllow||0);
  document.getElementById('sal-allow').value = allow;
  const deduct = (emp.tax||0)+(emp.deduct||0);
  document.getElementById('sal-deduct').value = deduct;
  calcSalaryNet();
}

function calcSalaryNet(){
  const basic = parseFloat(document.getElementById('sal-basic').value)||0;
  const allow = parseFloat(document.getElementById('sal-allow').value)||0;
  const deduct = parseFloat(document.getElementById('sal-deduct').value)||0;
  const recovery = parseFloat(document.getElementById('sal-adv-recovery').value)||0;
  const net = basic + allow - deduct - recovery;
  const el = document.getElementById('sal-net-display');
  if(el){ el.textContent = '৳'+pf(net); el.style.color = net>=0?'#2563eb':'#dc2626'; }
}

function saveSalaryPayment(){
  const empId = document.getElementById('sal-emp').value; /* FIX O: was parseInt() — employee ids are UUID strings post-Supabase-migration, so coercing to a number always failed the === comparison below. */
  if(!empId){ alert('⚠️ Select an employee'); return; }
  const month = document.getElementById('sal-month').value;
  if(!month){ alert('⚠️ Select a month'); return; }

  const emp = (DB.employees||[]).find(e => e.id === empId);
  const basic = parseFloat(document.getElementById('sal-basic').value)||0;
  const allow = parseFloat(document.getElementById('sal-allow').value)||0;
  const deduct = parseFloat(document.getElementById('sal-deduct').value)||0;
  const recovery = parseFloat(document.getElementById('sal-adv-recovery').value)||0;
  const net = basic + allow - deduct - recovery;

  const record = {
    id: newId(),
    empId, empName: emp?emp.name:'Unknown',
    month, date: document.getElementById('sal-date').value,
    basic, allow, deduct, recovery, net,
    mode: document.getElementById('sal-mode').value,
    bank: document.getElementById('sal-bank').value,
    notes: document.getElementById('sal-notes').value.trim()
  };

    DB.salaryHistory.unshift(record);

  // Reduce advance balance if recovery > 0
  if(recovery > 0){
    let remaining = recovery;
    (DB.empAdvances||[]).filter(a => a.empId===empId && (a.amount-(a.recovered||0))>0)
      .forEach(a => {
        if(remaining <= 0) return;
        const due = a.amount - (a.recovered||0);
        const reduce = Math.min(due, remaining);
        a.recovered = (a.recovered||0) + reduce;
        remaining -= reduce;
      });
  }

  saveDB();
  closeModal('mSalary');
  renderSalaryHistory();
  updatePayrollSummary();
}



async function deleteSalaryRecord(id){
  if(!await __confirm('Delete this salary record?')) return;
  DB.salaryHistory = (DB.salaryHistory||[]).filter(s => s.id !== id);
  saveDB();
  renderSalaryHistory();
  updatePayrollSummary();
}

