function updatePayrollSummary(){
  const emps = DB.employees||[];
  const hist = DB.salaryHistory||[];
  const advances = DB.empAdvances||[];

  const today = new Date();
  const thisMonth = today.toISOString().slice(0,7);

  const monthlyTotal = emps.filter(e=>e.status==='Active').reduce((s,e)=>s+(e.net||0),0);
  const totalAdv = advances.reduce((s,a)=>s+(a.amount||0)-(a.recovered||0),0);
  const totalLoan = advances.filter(a=>a.type==='Loan').reduce((s,a)=>s+(a.amount||0)-(a.recovered||0),0);
  const paidMonth = hist.filter(s=>s.month===thisMonth).reduce((s,r)=>s+(r.net||0),0);

  const el = (id,v) => { const e=document.getElementById(id); if(e) e.textContent=v; };
  el('pr-emp-count', emps.length);
  el('pr-monthly-total', '৳'+pf(monthlyTotal));
  el('pr-total-advance', '৳'+pf(totalAdv));
  el('pr-total-loan', '৳'+pf(totalLoan));
  el('pr-paid-month', '৳'+pf(paidMonth));
}

function exportPayroll(){
  const hist = DB.salaryHistory||[];
  if(!hist.length){ alert('No salary records to export'); return; }
  const rows = [['Month','Employee','Basic','Allowances','Deductions','Advance Recovery','Net Paid','Mode','Account','Notes']];
  hist.forEach(s => rows.push([s.month,s.empName,s.basic||0,s.allow||0,s.deduct||0,s.recovery||0,s.net||0,s.mode||'',s.bank||'',s.notes||'']));
  const csv = rows.map(r => r.map(c => __csvCell(c)).join(',')).join('\n');
  const blob = new Blob([csv], {type:'text/csv'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = 'payroll_export.csv'; a.click();
}


