let _charts = {};

// Human-friendly date label for the payment-cycle KPI sub-line, e.g. "Tue, 12 Aug".
function fmtCycleDate(dateKey){
  if(!dateKey) return '—';
  const d = new Date(dateKey+'T00:00:00');
  if(isNaN(d)) return dateKey;
  return d.toLocaleDateString('en-GB',{weekday:'short',day:'2-digit',month:'short'});
}

// Detail popup for the "NEXT PAYMENT" KPI card: shows the total amount
// currently owed to suppliers, plus the exact amount that matures for
// payment next under the Mon/Wed advice → Tue/Thu payout cycle.
function openNextPaymentDetail(){
  const existing = document.getElementById('next-payment-detail-modal');
  if(existing) existing.remove();

  const _pb = partyBuckets(DB.customers||[]);
  const supplierDueTotal = _pb.suppDue;
  const cyc = (typeof window.computeNextPaymentByCycle==='function') ? window.computeNextPaymentByCycle() : null;

  const upcomingRowsHtml = (cyc && cyc.allDates && cyc.allDates.length)
    ? cyc.allDates.slice(0,6).map(row=>`
      <tr style="${row.date===cyc.date?'background:#fdf2f8;':''}">
        <td style="padding:7px 10px;font-weight:${row.date===cyc.date?'800':'600'};color:${row.date<new Date().toISOString().slice(0,10)?'#dc2626':'#0f3d26'};">
          ${fmtCycleDate(row.date)}${row.date===cyc.date?' <span style="font-size:10px;color:#9d174d;">(next)</span>':''}
        </td>
        <td style="padding:7px 10px;text-align:center;color:#6b7280;">${row.count}</td>
        <td style="padding:7px 10px;text-align:right;font-weight:700;">৳${pf(row.amount)}</td>
      </tr>`).join('')
    : `<tr><td colspan="3" style="padding:14px;text-align:center;color:#9ca3af;">No outstanding purchase payments scheduled.</td></tr>`;

  const modal = document.createElement('div');
  modal.id = 'next-payment-detail-modal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(15,23,42,.55);z-index:99999;display:flex;align-items:center;justify-content:center;padding:20px;';
  modal.innerHTML = `
    <div style="background:#fff;border-radius:14px;max-width:520px;width:100%;box-shadow:0 24px 60px rgba(0,0,0,.3);overflow:hidden;">
      <div style="background:linear-gradient(90deg,#9d174d,#1a3a6b);color:#fff;padding:16px 20px;display:flex;align-items:center;justify-content:space-between;">
        <div style="font-size:15px;font-weight:800;">📅 Next Payment — Details</div>
        <button data-x-click="document.getElementById('next-payment-detail-modal').remove()" style="background:rgba(255,255,255,.15);border:0;color:#fff;border-radius:8px;padding:4px 10px;cursor:pointer;font-size:14px;">✕</button>
      </div>
      <div style="padding:18px 20px;">
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:16px;">
          <div style="background:#fef2f2;border:1px solid #fecaca;border-radius:10px;padding:12px;">
            <div style="font-size:10px;font-weight:700;color:#991b1b;text-transform:uppercase;">Total Supplier Due</div>
            <div style="font-size:20px;font-weight:900;color:#dc2626;margin-top:4px;">৳${pf(supplierDueTotal)}</div>
            <div style="font-size:10px;color:#6b7280;margin-top:2px;">Currently owed, all suppliers</div>
          </div>
          <div style="background:#fdf2f8;border:1px solid #fbcfe8;border-radius:10px;padding:12px;">
            <div style="font-size:10px;font-weight:700;color:#9d174d;text-transform:uppercase;">Next Payment Amount</div>
            <div style="font-size:20px;font-weight:900;color:#9d174d;margin-top:4px;">৳${cyc?pf(cyc.amount):'0.00'}</div>
            <div style="font-size:10px;color:#6b7280;margin-top:2px;">${cyc?(cyc.overdue?'⚠️ Overdue — pay ASAP':'Due '+fmtCycleDate(cyc.date)):'None scheduled'}</div>
          </div>
        </div>
        <div style="font-size:11px;color:#6b7280;margin-bottom:8px;">
          Payment cycle: amounts maturing up to <strong>Monday</strong> are paid <strong>Tuesday</strong>; amounts maturing up to <strong>Wednesday</strong> are paid <strong>Thursday</strong>.
        </div>
        <table style="width:100%;border-collapse:collapse;font-size:12px;border:1px solid #e5e7eb;border-radius:8px;overflow:hidden;">
          <thead><tr style="background:#f8fafc;color:#374151;">
            <th style="padding:7px 10px;text-align:left;">Payment Date</th>
