        </table>
        <div style="display:flex;gap:10px;margin-top:16px;">
          <button data-x-click="document.getElementById('next-payment-detail-modal').remove();nav('suppliers')" style="flex:1;padding:10px;background:#f3f4f6;color:#374151;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:13px;">View Suppliers</button>
          <button data-x-click="document.getElementById('next-payment-detail-modal').remove()" style="flex:1;padding:10px;background:#1a3a6b;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:13px;">Close</button>
        </div>
