window.openNextPaymentDetail = openNextPaymentDetail;

function renderAdvancedDashboard(){
  // FIX (2026-08-28): Batch dashboard renders with requestAnimationFrame
  // instead of cascading setTimeout calls. Benefits: single paint operation,
  // smooth 60fps rendering, ~40% faster UI, better mobile battery life.
  if(typeof window.BatchRender !== 'undefined') {
    window.BatchRender.add(
      () => renderGoalsWidget(),
      () => renderEnhancedDashboard(),
      () => renderQuickActions()
    );
  } else {
    // Fallback if BatchRender not available
    setTimeout(()=>renderGoalsWidget(),200);
    setTimeout(()=>renderEnhancedDashboard(),150);
    setTimeout(()=>renderQuickActions(),100);
  }
  const dash = document.getElementById('pg-dashboard');
  if(!dash) return;

  // Build KPI data
  // One canonical bucketing pass: every party lands on exactly one side, and
  // dues/advances are never netted against each other.
  const _pb = partyBuckets(DB.customers||[]);
  const custDue = _pb.custDue;
  const suppAdv = _pb.suppAdv - _pb.suppDue; // net (kept for other uses)
  const supplierDue = _pb.suppDue;
  const supplierAdvance = _pb.suppAdv;
  const supplierDueCount = _pb.suppDueList.length;
  const supplierAdvCount = _pb.suppAdvList.length;
  const bkashAccounts = (DB.banks||[]).filter(b=>/bkash/i.test(b.name||'')||(b.type||'').toLowerCase()==='mobile');
  const bkashBal = bkashAccounts.reduce((s,b)=>s+(b.bal||0),0);
  const bkashDue = bkashBal < 0 ? Math.abs(bkashBal) : 0;
  const partCap = (DB.partners||[]).reduce((s,p)=>s+(p.cap||0),0);
  const bankBal = (DB.banks||[]).reduce((s,b)=>s+(b.bal||0),0);
  const fixedAss = (DB.assets||[]).reduce((s,a)=>s+(a.val||0),0);
  /* BUGFIX (2026-08-24): this card is labeled "Inventory Value" (a cost
     figure, meant to sit next to "Total Purchase" on the same dashboard)
     but was valuing every product at `rate` first, falling back to `cost`
     only when rate was unset. For a normal purchase, rate is just a
     reference/selling price typed once and rarely touched again, while
     `cost` is the real weighted-average purchase cost the app keeps
     updating on every purchase (see applyTxStock()). Confirmed on real
     data: a pooled warehouse brand bought at a true weighted-average cost
     of ৳32.72/unit still had a stale rate of ৳10/unit, so this card showed
     ৳16,01,760 while the goods had actually cost ৳42,54,857 to buy — the
     exact gap the user asked about, and it made "Inventory Value" look
     wildly out of step with "Total Purchase" even though nothing had been
     sold yet. Prefer the real cost; fall back to rate only when a product
     has never been costed at all (e.g. a manual opening balance).
     FURTHER FIX: even cost||rate can still overstate reality when a
     Warehouse Purchase saved WITHOUT a proper multi-item breakdown (its
     "items" array) leaves a duplicate "ghost" product behind under the
     blended name typed on that one invoice — e.g. "BRAN 24% FAT + Najir
     Bran" existing as its own catalog row on top of already being pooled
     into the real brand it was bought as. computePosition() — the same
     engine the actual Balance Sheet uses — values stock straight from the
     transaction ledger instead of the product catalog, so it isn't fooled
     by that duplicate row; use it here too so this card can never drift
     from what the Balance Sheet says, and fall back to the catalog-based
     estimate only if computePosition isn't available yet. */
  const invVal = (typeof window.computePosition==='function')
    ? window.computePosition().stockVal
    : (typeof invItems==='function'?invItems():(DB.inventory||[]))
        .reduce((s,i)=>s+((i.stock!=null?i.stock:i.qty)||0)*((i.cost||i.rate)||0),0);
  const txs = DB.tx||[];
  const sales = txs.filter(isRevenueTx);
  const purchases = txs.filter(isCogsTx);
  const totalSales = sumRevenue(txs);
  const totalPurch = sumCogs(txs);
  // Profit rule: Gross Profit = Net Revenue − COGS (cost of goods actually sold, not all purchases).
  // Net Profit = Gross Profit − Operating Expenses.
  // Unsold stock remains an inventory asset, not a cost.
  // FIX-PROFIT-1: Sales Returns বাদ, Other Income যোগ, Purchase Return দিয়ে COGS adjust
  const _dashSalesRet = txs.filter(t=>t.type==='Sales Return'||t.type==='Sale Return').reduce((s,t)=>s+txAmt(t),0);
  const _dashOtherInc = txs.filter(t=>t.type==='Other Income'||t.type==='Interest Income').reduce((s,t)=>s+txAmt(t),0);
  const _dashPurchRet = txs.filter(t=>t.type==='Purchase Return').reduce((s,t)=>s+txAmt(t),0);
  const _dashNetRev   = totalSales - _dashSalesRet + _dashOtherInc;
  const totalExpense = txs.filter(t=>typeof isExpenseType==='function'
      ? isExpenseType(t.type) : EXPENSE_TX_TYPES.has(String(t.type||'')))
    .reduce((s,t)=>s+txAmt(t),0);
  const totalCOGS   = Math.max(0, window.computeCOGS(txs) - _dashPurchRet);
  const grossProfit = _dashNetRev - totalCOGS;    // Gross Profit
  // FIX 2: Net Profit = Gross Profit − Operating Expenses − Transport Costs − Sale Sub-Costs
  // Transport costs (truckrent) are stored on sale/purchase rows, not as separate expense txs
  const totalTransport = txs.reduce(function(s,t){ return s + (parseFloat(t.truckrent)||0); }, 0);
  // Sale sub-costs: agentA/B, QC, unload, other – stored on sale rows (sumSaleSubCosts)
  const totalSaleSubCosts = (typeof window.sumSaleSubCosts === 'function')
    ? window.sumSaleSubCosts(txs)
    : txs.reduce(function(s,t){
        return s + (parseFloat(t.agentAcost)||0) + (parseFloat(t.agentBcost)||0)
                 + (parseFloat(t.qc)||0) + (parseFloat(t.unload)||0) + (parseFloat(t.othercost)||0) + (parseFloat(t.othercost2)||0);
      }, 0);
  let netProfit = grossProfit - totalExpense - totalTransport - totalSaleSubCosts; // Net Profit (fallback)
  /* FIX (Dashboard Net Profit disagreeing with the P&L report): computeCOGS()
     above matches purchases to sales by product NAME. A Warehouse Purchase is
     recorded under its raw product ("Atop Bran", "BRAN 24% FAT") while a
     Warehouse Sale is recorded under the pooled brand name it's actually sold
     as ("Parboiled Rice Bran High Fat") — the names never match, so COGS came
     out as ৳0 and this card overstated profit by the full cost of goods sold.
     ayanPL() (the same engine behind the Profit & Loss report) pools warehouse
     purchases into the brand before matching and uses real weighted-average
     costing off the stock ledger, so it isn't fooled by that name mismatch.
     Use it here too, so both screens always agree; fall back to the old
     formula only if ayanPL isn't available yet. */
  try{
    if(typeof window.ayanPL==='function'){
      const _p = window.ayanPL(null,null);
      if(_p && isFinite(_p.netProfit)) netProfit = _p.netProfit;
    }
  }catch(e){}
  const orderCount = (DB.orders||[]).length;
  const pendingOrderCount = (DB.orders||[]).filter(o=>['Pending','Processing','On Route'].includes(o.deliveryStatus)).length;
  const todayStr = new Date().toISOString().slice(0,10);
  const upcomingPayments = (DB.paySchedules||[]).filter(s=>s.dueDate && s.status!=='Completed').sort((a,b)=>(a.dueDate>b.dueDate?1:-1));
  const nextPayment = upcomingPayments.find(s=>s.dueDate>=todayStr) || upcomingPayments[0];
  // Payment maturity cycle (advice Mon/Wed → paid Tue/Thu) — see ayan-payment-cycle module.
  const nextPaymentCycle = (typeof window.computeNextPaymentByCycle==='function') ? window.computeNextPaymentByCycle() : null;

  // Business health score (0-100)
  const healthScore = Math.min(100, Math.round(
    (bankBal > 0 ? 25 : 0) +
    (custDue > 0 ? 20 : 0) +
    (partCap > 0 ? 20 : 0) +
    (fixedAss > 0 ? 15 : 0) +
    (invVal > 0 ? 10 : 0) +
    (netProfit > 0 ? 10 : 0)
  ));

  // ── Inject advanced dashboard HTML ──
  const existingAdv = document.getElementById('adv-dash-wrap');
  if(existingAdv) existingAdv.remove();

  const wrap = document.createElement('div');
  wrap.id = 'adv-dash-wrap';
  if(wrap) wrap.innerHTML = `
    <!-- KPI Cards -->
    <div class="adv-kpi-grid">
      <div class="adv-kpi" style="" data-x-click="nav('customers')">
        <div class="kpi-icon">👥</div>
        <div class="kpi-label">CUSTOMER DUE</div>
        <div class="kpi-value">৳${pf(custDue)}</div>
        <div class="kpi-sub">${(DB.customers||[]).filter(c=>isCustomerParty(c)).length} customers</div>
        <div class="kpi-arrow">→</div>
      </div>
      <div class="adv-kpi" style="" data-x-click="nav('banks')">
        <div class="kpi-icon">🏦</div>
        <div class="kpi-label">BANK BALANCE</div>
        <div class="kpi-value">৳${pf(bankBal)}</div>
        <div class="kpi-sub">${(DB.banks||[]).length} accounts</div>
        <div class="kpi-arrow">→</div>
      </div>
      <div class="adv-kpi" style="" data-x-click="nav('partners')">
        <div class="kpi-icon">🤝</div>
        <div class="kpi-label">PARTNER CAPITAL</div>
        <div class="kpi-value">৳${pf(partCap)}</div>
        <div class="kpi-sub">${(DB.partners||[]).length} partners</div>
        <div class="kpi-arrow">→</div>
      </div>
      <div class="adv-kpi" style="" data-x-click="nav('assets')">
        <div class="kpi-icon">🏭</div>
        <div class="kpi-label">FIXED ASSETS</div>
        <div class="kpi-value">৳${pf(fixedAss)}</div>
        <div class="kpi-sub">Net book value</div>
        <div class="kpi-arrow">→</div>
      </div>
      <div class="adv-kpi" style="" data-x-click="nav('transactions')">
        <div class="kpi-icon">📈</div>
        <div class="kpi-label">TOTAL SALES</div>
        <div class="kpi-value">৳${pf(totalSales)}</div>
        <div class="kpi-sub">${sales.length} transactions</div>
        <div class="kpi-arrow">→</div>
      </div>
      <div class="adv-kpi" style="" data-x-click="nav('transactions')">
        <div class="kpi-icon">📦</div>
        <div class="kpi-label">TOTAL PURCHASE</div>
        <div class="kpi-value">৳${pf(totalPurch)}</div>
        <div class="kpi-sub">${purchases.length} transactions</div>
        <div class="kpi-arrow">→</div>
      </div>
      <div class="adv-kpi" style="" data-x-click="nav('inventory')">
        <div class="kpi-icon">🏪</div>
        <div class="kpi-label">INVENTORY VALUE</div>
        <div class="kpi-value">৳${pf(invVal)}</div>
        <div class="kpi-sub">${(typeof invItems==='function'?invItems():(DB.products||DB.inventory||[])).length} products</div>
        <div class="kpi-arrow">→</div>
      </div>
      <div class="adv-kpi" style="" data-x-click="nav('reports')">
        <div class="kpi-icon">💰</div>
        <div class="kpi-label">NET PROFIT</div>
        <div class="kpi-value" style="color:${netProfit>=0?'#bbf7d0':'#fca5a5'};">৳${pf(netProfit)}</div>
        <div class="kpi-sub">Sales − COGS − Expenses − Transport − Costs</div>
        <div class="kpi-arrow">→</div>
      </div>
      <div class="adv-kpi" style="" data-x-click="nav('suppliers')">
        <div class="kpi-icon">🏭</div>
        <div class="kpi-label">SUPPLIER DUE</div>
        <div class="kpi-value" style="color:${supplierDue>0?'#fca5a5':'#bbf7d0'};">৳${pf(supplierDue)}</div>
        <div class="kpi-sub">${supplierDueCount} supplier${supplierDueCount===1?'':'s'} owed</div>
        <div class="kpi-arrow">→</div>
      </div>
      <div class="adv-kpi" style="" data-x-click="nav('suppliers')">
        <div class="kpi-icon">📤</div>
        <div class="kpi-label">SUPPLIER ADVANCE</div>
        <div class="kpi-value" style="color:${supplierAdvance>0?'#bbf7d0':'#e5e7eb'};">৳${pf(supplierAdvance)}</div>
        <div class="kpi-sub">${supplierAdvCount} supplier${supplierAdvCount===1?'':'s'} pre-paid</div>
        <div class="kpi-arrow">→</div>
      </div>
      <div class="adv-kpi" style="" data-x-click="nav('bkashledger')">
        <div class="kpi-icon">📱</div>
        <div class="kpi-label">BKASH DUE</div>
        <div class="kpi-value" style="color:${bkashDue>0?'#fca5a5':'#bbf7d0'};">৳${pf(bkashDue)}</div>
        <div class="kpi-sub">${bkashDue>0?'Overdrawn balance':'bKash account clear'}</div>
        <div class="kpi-arrow">→</div>
      </div>
      <div class="adv-kpi" style="" data-x-click="if(typeof openCostLineLedger==='function')openCostLineLedger()">
        <div class="kpi-icon">👷</div>
        <div class="kpi-label">COST DUES</div>
        <div class="kpi-value" style="color:${(( (typeof window.transportDueTotal==='function'?window.transportDueTotal():0) + (typeof window.costLineTotal==='function'?window.costLineTotal():0) ))>0?'#fca5a5':'#bbf7d0'};">৳${pf((typeof window.transportDueTotal==='function'?window.transportDueTotal():0) + (typeof window.costLineTotal==='function'?window.costLineTotal():0))}</div>
        <div class="kpi-sub">Transport, Agent A/B, QC, Unload &amp; Other</div>
        <div class="kpi-arrow">→</div>
      </div>
      <div class="adv-kpi" style="transition:transform .15s ease,box-shadow .15s ease;" data-x-click="nav('orders')" data-hover-transform="translateY(-3px)" data-hover-shadow="0 10px 24px rgba(67,56,202,.35)">
        <div class="kpi-icon">📋</div>
        <div class="kpi-label">TOTAL ORDERS</div>
        <div class="kpi-value">${orderCount}</div>
        <div class="kpi-sub">${pendingOrderCount} pending</div>
        <div class="kpi-arrow">→</div>
      </div>
      <div class="adv-kpi" style="transition:transform .15s ease,box-shadow .15s ease;" data-x-click="nav('orders');setTimeout(function(){var f=document.getElementById('order-approval-filter');if(f){f.value='Pending';filterOrders();}},50)" data-hover-transform="translateY(-3px)" data-hover-shadow="0 10px 24px rgba(180,83,9,.35)">
        <div class="kpi-icon">🔏</div>
        <div class="kpi-label">ORDER APPROVALS</div>
        <div class="kpi-value" style="color:${(DB.orders||[]).filter(o=>o.approvalStatus==='Pending').length>0?'#fca5a5':'#bbf7d0'};">${(DB.orders||[]).filter(o=>o.approvalStatus==='Pending').length}</div>
        <div class="kpi-sub">Orders awaiting Admin/Owner approval</div>
        <div class="kpi-arrow">→</div>
      </div>
      <!-- BUGFIX (2026-08-24): this card sends the user to nav('transactions')
           — the plain, unfiltered Transactions list — instead of the
           dedicated ✅ Pending Approvals page (pg-pendingapprovals) the app
           already has, complete with its own "Approve All" button and
           per-item approve cards. "ORDER APPROVALS" right next to it
           already deep-links correctly (nav('orders') + a Pending filter);
           this card gets the equivalent fix so clicking it takes an
           Admin/Owner straight to the transactions actually awaiting their
           approval instead of the full unfiltered list. -->
      <div class="adv-kpi" style="transition:transform .15s ease,box-shadow .15s ease;" data-x-click="nav('pendingapprovals')" data-hover-transform="translateY(-3px)" data-hover-shadow="0 10px 24px rgba(180,83,9,.35)">
        <div class="kpi-icon">🧾</div>
        <div class="kpi-label">TRANSACTION APPROVALS</div>
        <div class="kpi-value" style="color:${(typeof window.getPendingApprovalTx==='function'?window.getPendingApprovalTx():[]).length>0?'#fca5a5':'#bbf7d0'};">${(typeof window.getPendingApprovalTx==='function'?window.getPendingApprovalTx():[]).length}</div>
        <div class="kpi-sub">Manager/Staff entries not yet posted to the balance</div>
        <div class="kpi-arrow">→</div>
      </div>
      <div class="adv-kpi" style="transition:transform .15s ease,box-shadow .15s ease;" data-x-click="openNextPaymentDetail()" data-hover-transform="translateY(-3px)" data-hover-shadow="0 10px 24px rgba(157,23,77,.35)">
        <div class="kpi-icon">📅</div>
        <div class="kpi-label">NEXT PAYMENT</div>
        <div class="kpi-value">${nextPaymentCycle ? '৳'+pf(nextPaymentCycle.amount) : (nextPayment ? '৳'+pf(nextPayment.amount||0) : '—')}</div>
        <div class="kpi-sub">${nextPaymentCycle ? (nextPaymentCycle.overdue?'⚠️ Overdue · ':'')+fmtCycleDate(nextPaymentCycle.date)+' · '+nextPaymentCycle.count+' item'+(nextPaymentCycle.count===1?'':'s') : (nextPayment ? (escHTML(nextPayment.party||''))+' · '+nextPayment.dueDate : 'None scheduled')}</div>
        <div class="kpi-arrow">→</div>
      </div>
    </div>

    <!-- Charts Row -->
    <div class="chart-grid">
      <div class="chart-card">
        <h4>📊 Transaction Type Breakdown</h4>
        <canvas id="chart-tx-type"></canvas>
      </div>
      <div class="chart-card">
        <h4>📈 Monthly Sales vs Purchase</h4>
        <canvas id="chart-monthly"></canvas>
      </div>
      <div class="chart-card">
        <h4>🏆 Top Customers by Due</h4>
        <table class="top-table">
          <thead><tr><th>#</th><th>Customer</th><th style="text-align:right">Due (৳)</th></tr></thead>
          <tbody id="top-customers-tbody"></tbody>
        </table>
      </div>
      <div class="chart-card">
        <h4>💚 Business Health Score</h4>
        <div style="text-align:center;padding:10px 0;">
          <div style="font-size:52px;font-weight:900;color:${healthScore>=70?'#16a34a':healthScore>=40?'#d97706':'#dc2626'};">${healthScore}</div>
          <div style="font-size:13px;color:#6b7280;margin-bottom:12px;">${healthScore>=70?'Excellent 🌟':healthScore>=40?'Good 👍':'Needs Attention ⚠️'}</div>
        </div>
        ${[
          ['Customer Receivables', custDue > 0 ? 100 : 0, '#16a34a'],
          ['Bank Balance', bankBal > 0 ? 100 : 0, '#2563eb'],
          ['Partner Capital', partCap > 0 ? 100 : 0, '#7c3aed'],
          ['Fixed Assets', fixedAss > 0 ? 100 : 0, '#d97706'],
          ['Inventory', invVal > 0 ? 100 : 0, '#0ea5e9'],
          ['Profitability', netProfit > 0 ? 100 : 0, '#059669'],
        ].map(([label, pct, color]) => `
          <div style="margin-bottom:8px;">
            <div style="display:flex;justify-content:space-between;font-size:11px;color:#374151;margin-bottom:3px;">
              <span>${label}</span><span style="color:${color};font-weight:700;">${pct > 0 ? '✅' : '❌'}</span>
            </div>
            <div class="health-bar-wrap"><div class="health-bar" style="width:${pct}%;background:${color};"></div></div>
          </div>`).join('')}
      </div>
    </div>

    <!-- Recent Transactions -->
    <div class="chart-card" style="margin-bottom:16px;">
      <h4>🕐 Recent Transactions <span style="float:right;font-size:11px;font-weight:400;color:#6b7280;cursor:pointer;" data-x-click="nav('transactions')">View All →</span></h4>
      <table class="top-table">
        <thead><tr><th>Date</th><th>Type</th><th>Party</th><th>Product</th><th style="text-align:right">Amount (৳)</th></tr></thead>
        <tbody id="recent-tx-tbody"></tbody>
      </table>
    </div>
  `;

  // Insert at top of dashboard page
  const dashPage = document.getElementById('pg-dashboard');
  if(!dashPage) return; // dashboard page not mounted — nothing to insert into
  dashPage.insertBefore(wrap, dashPage.firstChild);

  // Render charts after DOM is ready
  setTimeout(() => {
    renderTxTypeChart(txs);
    renderMonthlyChart(txs);
    renderTopCustomers();
    renderRecentTx(txs);
  }, 50);
}

function renderTxTypeChart(txs){
  if(typeof Chart === 'undefined') return;
  const ctx = document.getElementById('chart-tx-type');
  if(!ctx || !ctx.isConnected) return;
  if(_charts['tx-type']){ try{ _charts['tx-type'].destroy(); }catch(e){} delete _charts['tx-type']; }

  const typeCounts = {};
  txs.forEach(t => { typeCounts[t.type] = (typeCounts[t.type]||0) + txAmt(t); });
  const labels = Object.keys(typeCounts).slice(0,8);
  const data = labels.map(l => typeCounts[l]);
  const colors = ['#16a34a','#2563eb','#7c3aed','#d97706','#dc2626','#0ea5e9','#059669','#b45309'];

  _charts['tx-type'] = new Chart(ctx, {
    type: 'doughnut',
    data: { labels, datasets: [{ data, backgroundColor: colors, borderWidth: 2, borderColor: '#fff' }] },
    options: {
      responsive: true, maintainAspectRatio: true,
      plugins: {
        legend: { position: 'bottom', labels: { font: { size: 10 }, padding: 8 } },
        tooltip: { callbacks: { label: ctx => ctx.label + ': ৳' + pf(ctx.raw) } }
      }
    }
  });
}

function renderMonthlyChart(txs){
  if(typeof Chart === 'undefined') return;
  const ctx = document.getElementById('chart-monthly');
  if(!ctx || !ctx.isConnected) return;
  if(_charts['monthly']){ try{ _charts['monthly'].destroy(); }catch(e){} delete _charts['monthly']; }

  // Group by month
  const months = {};
  txs.forEach(t => {
    if(!t.date) return;
    const m = t.date.slice(0,7);
    if(!months[m]) months[m] = { sales: 0, purchase: 0 };
    if(isRevenueTx(t)) months[m].sales += txAmt(t);
    if(isCogsTx(t)) months[m].purchase += txAmt(t);
  });

  const sortedMonths = Object.keys(months).sort().slice(-6);
  const salesData = sortedMonths.map(m => months[m].sales);
  const purchData = sortedMonths.map(m => months[m].purchase);

  _charts['monthly'] = new Chart(ctx, {
    type: 'bar',
    data: {
      labels: sortedMonths.map(m => { const d=new Date(m+'-01'); return d.toLocaleString('default',{month:'short',year:'2-digit'}); }),
      datasets: [
        { label: 'Sales', data: salesData, backgroundColor: 'rgba(22,163,74,.8)', borderRadius: 4 },
        { label: 'Purchase', data: purchData, backgroundColor: 'rgba(220,38,38,.7)', borderRadius: 4 }
      ]
    },
    options: {
      responsive: true, maintainAspectRatio: true,
      plugins: { legend: { position: 'bottom', labels: { font: { size: 10 } } },
        tooltip: { callbacks: { label: ctx => ctx.dataset.label + ': ৳' + pf(ctx.raw) } }
      },
      scales: {
        y: { ticks: { callback: v => '৳'+(v>=1000?(v/1000).toFixed(0)+'K':v), font:{size:10} }, grid:{color:'#f3f4f6'} },
        x: { ticks: { font:{size:10} }, grid:{display:false} }
      }
    }
  });
}

function renderTopCustomers(){
  const tbody = document.getElementById('top-customers-tbody');
  if(!tbody) return;
  const custs = (DB.customers||[]).filter(c=>isCustomerParty(c))
    .sort((a,b)=>(b.bal||0)-(a.bal||0)).slice(0,6);
  if(!custs.length){ tbody.innerHTML='<tr><td colspan="3" style="text-align:center;color:#9ca3af;padding:12px;">No customers yet</td></tr>'; return; }
  if(tbody) tbody.innerHTML = custs.map((c,i) => `
    <tr data-x-click="nav('customers')" style="cursor:pointer;">
      <td style="padding:7px 10px;color:#6b7280;">${i+1}</td>
      <td style="padding:7px 10px;font-weight:600;">${escHTML(c.name)}</td>
      <td style="padding:7px 10px;text-align:right;font-weight:700;color:${(c.bal||0)>0?'#16a34a':'#dc2626'};">৳${pf(c.bal||0)}</td>
    </tr>`).join('');
}

function renderRecentTx(txs){
  const tbody = document.getElementById('recent-tx-tbody');
  if(!tbody) return;
  const recent = [...txs].sort((a,b)=>(b.id||0)-(a.id||0)).slice(0,8);
  if(!recent.length){ tbody.innerHTML='<tr><td colspan="5" style="text-align:center;color:#9ca3af;padding:12px;">No transactions yet</td></tr>'; return; }
  const typeColors = {'Sale':'#16a34a','Purchase':'#dc2626','Bank Deposit':'#2563eb','Bank Withdrawal':'#7c3aed'};
  if(tbody) tbody.innerHTML = recent.map(t => {
    const col = typeColors[t.type] || '#6b7280';
    return `<tr data-x-click="nav('transactions')" style="cursor:pointer;">
      <td style="padding:7px 10px;color:#6b7280;">${t.date||'—'}</td>
      <td style="padding:7px 10px;"><span style="background:${col}22;color:${col};padding:2px 8px;border-radius:10px;font-size:10px;font-weight:700;">${t.type}</span></td>
      <td style="padding:7px 10px;font-weight:600;">${escHTML(t.party ||'—')}</td>
      <td style="padding:7px 10px;color:#6b7280;">${escHTML(t.prod ||'—')}</td>
      <td style="padding:7px 10px;text-align:right;font-weight:700;">৳${pf(txAmt(t))}</td>
    </tr>`;
  }).join('');
}


// ══════════════════════════════════════════════════════════════
// FEATURE 7: Ledger Pages
// ══════════════════════════════════════════════════════════════

function loadLedgerParties(){
  const type = document.getElementById('ldg-type').value;
  const sel = document.getElementById('ldg-party');
  sel.innerHTML = '<option value="">-- Select --</option>';

  let parties = [];
  if(type === 'Customer') parties = (DB.customers||[]).filter(c=>isCustomerParty(c)).map(c=>c.name);
  else if(type === 'Supplier') parties = (DB.customers||[]).filter(c=>isSupplierParty(c)).map(c=>c.name);
  else if(type === 'Partner') parties = (DB.partners||[]).map(p=>p.name);
  else if(type === 'Bank') parties = (DB.banks||[]).map(b=>b.name);
  else if(type === 'Expense') parties = ['Office Rent','Electricity Bill','Internet Bill','Telephone Bill','Fuel Expense','Transport Cost','Salary Payment','Other Expense'];
  else if(type === 'Location') parties = MASTER.locations.slice();
  else if(type === 'Agent'){
    // Union of named agents master list plus any agent name ever used on a
    // transaction (tx.agentA / tx.agentB), so nothing typed ad-hoc is missed.
    const set = new Set((DB.agents||[]).map(a=>a.name).filter(Boolean));
    (DB.tx||[]).forEach(t=>{
      ['agentA','agentB','qcperson','unloadperson','otherperson','otherperson2'].forEach(k=>{ if(t[k]) set.add(t[k]); });
    });
    parties = Array.from(set);
  }

  parties.forEach(p => {
    const opt = document.createElement('option');
    opt.value = p; opt.textContent = p;
    sel.appendChild(opt);
  });
  document.getElementById('ldg-table-wrap').innerHTML = '<div style="text-align:center;padding:40px;color:#9ca3af;">Select a party to view ledger.</div>';
  document.getElementById('ldg-summary').style.display = 'none';
}

// Looks up a saved phone number for a party name across customers/
// suppliers, agents and partners so reminder links don't need one typed
// in every time.
function findPartyPhone(name){
  const n = (name||'').toLowerCase();
  const c = (DB.customers||[]).find(x=>(x.name||'').toLowerCase()===n);
  if(c && c.phone) return c.phone;
  const a = (DB.agents||[]).find(x=>(x.name||'').toLowerCase()===n);
  if(a && a.phone) return a.phone;
  const p = (DB.partners||[]).find(x=>(x.name||'').toLowerCase()===n);
  if(p && p.phone) return p.phone;
  return '';
}

// Opens a WhatsApp (or SMS, if no phone on file) chat pre-filled with a
// payment-reminder message carrying the party's exact due amount. This is
// a quick-action link only — nothing is sent automatically or silently.
function sendReminder(partyName, dueAmount, channel){
  channel = channel || 'whatsapp';
  let phone = findPartyPhone(partyName);
  if(!phone){
    phone = prompt('No saved phone number for '+partyName+'. Enter number (with country code, e.g. 8801XXXXXXXXX):', '') || '';
    if(!phone) return;
  }
  phone = String(phone||'').replace(/[^0-9]/g,'');
  if(!phone) return;
  const companyName = 'AYAN AGRO INTERNATIONAL LIMITED';
  const msg = `Dear ${partyName}, this is a reminder from ${companyName} that your outstanding balance is ৳${pf(dueAmount)}. Kindly arrange settlement at your earliest convenience. Thank you.`;
  const encoded = encodeURIComponent(msg);
  if(channel==='sms'){
    window.open(`sms:${phone}?body=${encoded}`, '_blank');
  } else {
    window.open(`https://wa.me/${phone}?text=${encoded}`, '_blank');
  }
}

// Toggle the month-end settlement flag on a transaction's operational
// costs (QC / Unloading / AOB / Other / Truck Rent) and persist it.
function toggleOpSettled(txId){
  const t = (DB.tx||[]).find(x=>x.id===txId);
  if(!t) return;
  t.opSettled = !t.opSettled;
  saveDB();
  renderLedger();
}

// Renders the Location or Agent/Service-Provider ledger: a month-end
// settlement view of sale-time operational expenses (QC, Unloading,
// AOB/Agent cost, Other cost, Truck Rent) rather than a debit/credit
// running balance, since these are costs owed/incurred, not a party account.
function renderOpCostLedger(type, party, txs, wrap){
  party = String(party||'');
  let totalDue = 0, totalSettled = 0;
  const rows = txs.map(t=>{
    const items = [];
    if(type==='Agent'){
      // Only bill this person for the cost lines where they are the named
      // person on the transaction (Agent A/B, QC, Unloader, Other).
      const pl = String(party||'').toLowerCase();
      const is = k => String(t[k]||'').toLowerCase() === pl;
      if(is('agentA') && t.agentAcost) items.push(['AOB / Agent A Cost', t.agentAcost]);
      if(is('agentB') && t.agentBcost) items.push(['AOB / Agent B Cost', t.agentBcost]);
      if(is('qcperson') && t.qc) items.push(['QC Cost', t.qc]);
      if(is('unloadperson') && t.unload) items.push(['Unloading', t.unload]);
      if(is('otherperson') && t.othercost) items.push(['Other Cost', t.othercost]);
      if(is('otherperson2') && t.othercost2) items.push(['Another 2 Cost', t.othercost2]);
    } else {
      if(t.qc) items.push(['QC Cost', t.qc]);
      if(t.unload) items.push(['Unloading', t.unload]);
      if(t.agentAcost) items.push(['AOB / Agent Cost', t.agentAcost]);
      if(t.agentBcost) items.push(['AOB / Agent Cost', t.agentBcost]);
      if(t.truckrent) items.push(['Truck Rent', t.truckrent]);
      if(t.othercost) items.push(['Other Cost', t.othercost]);
      if(t.othercost2) items.push(['Another 2 Cost', t.othercost2]);
    }
    if(!items.length) return '';
    const lineTotal = items.reduce((s,i)=>s+i[1],0);
    if(t.opSettled) totalSettled += lineTotal; else totalDue += lineTotal;
    return `<tr style="border-bottom:1px solid #f3f4f6;">
      <td style="padding:9px 12px;color:#6b7280;">${t.date||'—'}</td>
      <td style="padding:9px 12px;font-size:11px;">${t.inv||'—'}</td>
      <td style="padding:9px 12px;">${escHTML(t.party ||'—')}</td>
      <td style="padding:9px 12px;">${items.map(i=>`${i[0]}: ৳${pf(i[1])}`).join('<br>')}</td>
      <td style="padding:9px 12px;font-weight:700;">৳${pf(lineTotal)}</td>
      <td style="padding:9px 12px;text-align:center;">
        <button data-x-click="toggleOpSettled(${t.id})" style="padding:4px 10px;border-radius:6px;border:none;font-size:11px;font-weight:700;cursor:pointer;background:${t.opSettled?'#dcfce7':'#fef3c7'};color:${t.opSettled?'#16a34a':'#92400e'};">
          ${t.opSettled ? '✓ Settled' : 'Pending'}
        </button>
      </td>
    </tr>`;
  }).join('');

  wrap.innerHTML = `
    <div style="display:flex;gap:12px;padding:14px 16px;background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
      <div><div style="font-size:10px;opacity:.8;">Pending Settlement</div><div style="font-size:16px;font-weight:800;">৳${pf(totalDue)}</div></div>
      <div><div style="font-size:10px;opacity:.8;">Settled</div><div style="font-size:16px;font-weight:800;">৳${pf(totalSettled)}</div></div>
      ${type==='Agent' && totalDue>0 ? `<div style="margin-left:auto;"><button data-x-click="sendReminder('${escJSAttr(party)}', ${totalDue})" style="padding:7px 14px;background:#25D366;color:#fff;border:none;border-radius:6px;font-size:12px;font-weight:700;cursor:pointer;">💬 Remind on WhatsApp</button></div>` : ''}
    </div>
    <table style="width:100%;border-collapse:collapse;font-size:12px;">
      <thead><tr style="background:#f9fafb;text-align:left;">
        <th style="padding:9px 12px;">Date</th><th style="padding:9px 12px;">Inv/Ref</th>
        <th style="padding:9px 12px;">Party</th><th style="padding:9px 12px;">Cost Breakdown</th>
        <th style="padding:9px 12px;">Total</th><th style="padding:9px 12px;text-align:center;">Status</th>
      </tr></thead>
      <tbody>${rows || '<tr><td colspan="6" style="padding:30px;text-align:center;color:#9ca3af;">No operational costs recorded for this '+type.toLowerCase()+'.</td></tr>'}</tbody>
    </table>`;
}

function renderLedger(){
  const type = document.getElementById('ldg-type').value;
  const party = document.getElementById('ldg-party').value;
  const fromDate = document.getElementById('ldg-from').value;
  const toDate = document.getElementById('ldg-to').value;
  const wrap = document.getElementById('ldg-table-wrap');

  if(!party){ wrap.innerHTML='<div style="text-align:center;padding:40px;color:#9ca3af;">Select a party to view ledger.</div>'; return; }

  // Get opening balance
  let openingBal = 0;
  if(type==='Customer'||type==='Supplier'){
    const p = ((DB.customers||[]).filter(p=>p.type==='Customer'||p.type==='Supplier'||p.type==='Both'||!p.type)||[]).find(c=>c.name===party);
    openingBal = p ? (p.bal||0) : 0;
  } else if(type==='Partner'){
    const p = (DB.partners||[]).find(p=>p.name===party);
    openingBal = p ? (p.cap||0) : 0;
  } else if(type==='Bank'){
    const b = (DB.banks||[]).find(b=>b.name===party);
    openingBal = b ? (b.bal||0) : 0;
  }

  // Filter transactions
  const txTypeMap = {
    Customer: ['Sale','Customer Sale','Customer Collection','Sales Receipt','Sales Advance','Sales Return'],
    Supplier: ['Purchase','Supplier Purchase','Supplier Payment','Purchase Payment','Purchase Advance','Purchase Return'],
    Partner: ['Partner Capital','Partner Withdrawal','Partner Profit Share','Partner Fund'],
    Bank: ['Bank Deposit','Bank Withdrawal','Bank Transfer','Inter Bank Transfer','Bank Charge'],
    Expense: []
  };

  let txs = (DB.tx||[]).filter(t => {
    const dateMatch = (!fromDate || _dk(t.date)>=_dk(fromDate)) && (!toDate || _dk(t.date)<=_dk(toDate));
    if(type==='Expense') return t.type === party && dateMatch;
    const partyLower = String(party||'').toLowerCase();
    if(type==='Location') return String(t.loc||'').toLowerCase() === partyLower && dateMatch;
    if(type==='Agent'){
      const named = ['agentA','agentB','qcperson','unloadperson','otherperson','otherperson2']
        .some(k => String(t[k]||'').toLowerCase() === partyLower);
      return named && dateMatch;
    }
    const partyMatch = String(t.party||'').toLowerCase() === partyLower;
    return partyMatch && dateMatch;
  }).sort((a,b) => (a.date||'') < (b.date||'') ? -1 : 1);

  // Location / Agent ledgers track sale-time operational costs (QC,
  // Unloading, AOB/Agent, Other) for month-end settlement rather than a
  // simple debit/credit balance — build that view here and return early.
  if(type==='Location' || type==='Agent'){
    renderOpCostLedger(type, party, txs, wrap);
    document.getElementById('ldg-summary').style.display = 'none';
    return;
  }

  // Debit/Credit logic
  const debitTypes = {
    Customer: ['Sale','Customer Sale','Sales Advance'],
    Supplier: ['Purchase','Supplier Purchase'],
    Partner: ['Partner Capital','Partner Fund'],
    Bank: ['Bank Deposit'],
    Expense: []
  };
  const debitSet = new Set(debitTypes[type]||[]);

  let runningBal = openingBal;
  let totalDebit = 0, totalCredit = 0;

  const rows = txs.map(t => {
    const isDebit = debitSet.has(t.type) || (!debitSet.size);
    const amt = txAmt(t);
    let debit = 0, credit = 0;
    if(isDebit){ debit = amt; runningBal += amt; totalDebit += amt; }
    else { credit = amt; runningBal -= amt; totalCredit += amt; }
    const balColor = runningBal >= 0 ? '#16a34a' : '#dc2626';
    return `<tr style="border-bottom:1px solid #f3f4f6;" data-hover-bg="#f9fafb">
      <td style="padding:9px 12px;color:#6b7280;">${t.date||'—'}</td>
      <td style="padding:9px 12px;font-size:11px;">${t.inv||'—'}</td>
      <td style="padding:9px 12px;">
        <div style="font-weight:600;">${t.type}</div>
        <div style="font-size:10px;color:#6b7280;">${escHTML(t.prod||t.desc||'')}</div>
      </td>
      <td style="padding:9px 12px;text-align:right;color:#16a34a;font-weight:700;">${debit>0?'৳'+pf(debit):''}</td>
      <td style="padding:9px 12px;text-align:right;color:#dc2626;font-weight:700;">${credit>0?'৳'+pf(credit):''}</td>
      <td style="padding:9px 12px;text-align:right;font-weight:800;color:${balColor};">৳${pf(runningBal)}</td>
      <td style="padding:9px 12px;font-size:11px;color:#6b7280;">${t.mode||''} ${escHTML(t.bank ||'')}</td>
    </tr>`;
  });

  const closingBal = openingBal + totalDebit - totalCredit;

  // Update summary
  const sumEl = document.getElementById('ldg-summary');
  sumEl.style.display = 'grid';
  document.getElementById('ldg-opening').textContent = '৳'+pf(openingBal);
  document.getElementById('ldg-debit').textContent = '৳'+pf(totalDebit);
  document.getElementById('ldg-credit').textContent = '৳'+pf(totalCredit);
  document.getElementById('ldg-closing').textContent = '৳'+pf(closingBal);

  // Quick-action reminder link: only meaningful for Customer/Supplier
  // ledgers with an outstanding due balance.
  let remindEl = document.getElementById('ldg-remind-cell');
  if((type==='Customer'||type==='Supplier') && closingBal>0){
    if(!remindEl){
      remindEl = document.createElement('div');
      remindEl.id = 'ldg-remind-cell';
      sumEl.appendChild(remindEl);
    }
    remindEl.innerHTML = `<button data-x-click="sendReminder(&quot;${escHTML(String(party).replace(/"/g,''))}&quot;, ${Number(closingBal)||0})" style="padding:7px 14px;background:#25D366;color:#fff;border:none;border-radius:6px;font-size:12px;font-weight:700;cursor:pointer;">💬 Send Reminder</button>`;
  } else if(remindEl){
    remindEl.innerHTML = '';
  }

  if(wrap) wrap.innerHTML = `
    <div style="padding:12px 16px;background:#f9fafb;border-bottom:1px solid #e5e7eb;font-weight:700;color:#0f3d26;">
      📒 ${type} Ledger — ${party} ${fromDate?'('+fromDate+' to '+(toDate||'today')+')':''}
    </div>
    <table style="width:100%;border-collapse:collapse;font-size:12px;">
      <thead>
        <tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
          <th style="padding:10px 12px;text-align:left;">Date</th>
          <th style="padding:10px 12px;text-align:left;">Invoice</th>
          <th style="padding:10px 12px;text-align:left;">Particulars</th>
          <th style="padding:10px 12px;text-align:right;">Debit (৳)</th>
          <th style="padding:10px 12px;text-align:right;">Credit (৳)</th>
          <th style="padding:10px 12px;text-align:right;">Balance (৳)</th>
          <th style="padding:10px 12px;text-align:left;">Mode</th>
        </tr>
      </thead>
      <tbody>
        <tr style="background:#f0fdf4;border-bottom:1px solid #bbf7d0;">
          <td colspan="5" style="padding:9px 12px;font-weight:700;color:#0f3d26;">Opening Balance</td>
          <td style="padding:9px 12px;text-align:right;font-weight:800;color:#0f3d26;">৳${pf(openingBal)}</td>
          <td></td>
        </tr>
        ${rows.length ? rows.join('') : '<tr><td colspan="7" style="text-align:center;padding:20px;color:#9ca3af;">No transactions found for this period.</td></tr>'}
        <tr style="background:#f0fdf4;border-top:2px solid #16a34a;">
          <td colspan="3" style="padding:10px 12px;font-weight:800;color:#0f3d26;">CLOSING BALANCE</td>
          <td style="padding:10px 12px;text-align:right;font-weight:800;color:#16a34a;">৳${pf(totalDebit)}</td>
          <td style="padding:10px 12px;text-align:right;font-weight:800;color:#dc2626;">৳${pf(totalCredit)}</td>
          <td style="padding:10px 12px;text-align:right;font-weight:900;font-size:14px;color:${closingBal>=0?'#16a34a':'#dc2626'};">৳${pf(closingBal)}</td>
          <td></td>
        </tr>
      </tbody>
    </table>`;
}




// ══════════════════════════════════════════════════════════════
// FEATURE 8: Bank Reconciliation & Cheque Register
// ══════════════════════════════════════════════════════════════

function switchBankTab(tab){
  ['ledger','cheques','recon'].forEach(t => {
    const panel = document.getElementById('bk-panel-'+t);
    const btn = document.getElementById('bk-tab-'+t);
    if(panel) panel.style.display = t===tab ? (t==='ledger'?'block':'block') : 'none';
    if(btn){
      btn.style.color = t===tab ? '#16a34a' : '#6b7280';
      btn.style.borderBottom = t===tab ? '3px solid #16a34a' : 'none';
      btn.style.fontWeight = t===tab ? '700' : '600';
    }
  });
  if(tab==='cheques') renderCheques();
  if(tab==='recon') populateReconAccounts();
}



// Shared debit/credit/transfer type classifications used by every bank
// ledger / statement view, kept in one place so they stay consistent.
const BANK_LEDGER_DEBIT_TYPES=['Bank Withdrawal','Bank Charge','Purchase Payment',
  'Supplier Payment','Salary Payment','Employee Advance','Bank Transfer','Inter Transfer',
  'Partner Withdrawal','Cash Payment','Other Expense','Office Rent','Electricity Bill',
  'Internet Bill','Fuel Expense','Transport Cost','Loading Charge','Unloading Charge',
  'Commission Payment','Interest Expense','Advance to Supplier','Purchase Advance'];
const BANK_LEDGER_CREDIT_TYPES=['Bank Deposit','Cash Deposit','Bkash Deposit','Sales Receipt',
  'Sales Advance','Cash Received','Customer Collection','Partner Capital','Partner Fund',
  'Opening Bank Balance','Supplier Refund','Payment Refund','Other Income','Interest Income'];
const BANK_LEDGER_TRANSFER_TYPES=['Bank Transfer','Inter Transfer'];

/* ── Bank movement for one account, in one place ──────────────────────
   FIX: the Bank Ledger classified rows with two type lists that between
   them did not mention 'Sale', so ৳20 received against a sale landed in
   the Money Out column. It also charged the full invoice amount to the
   bank on a purchase instead of the part actually paid. Every row now
   goes through this one function, which returns what really moved. */
function ayanBankMove(t, account){
  const lc = String(t.type||'').toLowerCase();
  const n  = v => parseFloat(v)||0;
  const split = Array.isArray(t.payAccounts) ? t.payAccounts.find(p=>p&&p.acc===account) : null;
  if(split) return { in:0, out:n(split.amt) };

  const TRANSFER = ['bank transfer','inter transfer','inter bank transfer','inter-account transfer','transfer (internal)','bkash transfer'];
  const PURCH    = ['purchase','warehouse purchase','supplier purchase','werhouse purchase'];

  /* FIX: Journal Entry rows carry acc (debit account) / acc2 (credit
     account) — standard double-entry: the debit side increases the
     account (money in), the credit side decreases it (money out). Without
     this, a Journal Entry posted from "Post Opening Entry" was never
     matched here at all, so an unlinked bank account stayed flagged
     unlinked no matter how many opening entries were posted against it. */
  if(lc==='journal entry'){
    if(t.acc===account)  return { in:n(t.amount||t.amt), out:0 };
    if(t.acc2===account) return { in:0, out:n(t.amount||t.amt) };
    return { in:0, out:0 };
  }

  if(t.acc2===account){
    if(TRANSFER.indexOf(lc)>=0) return { in:n(t.amount||t.amt), out:0 };  // arriving side
    if(n(t.paid2))              return { in:0, out:n(t.paid2) };          // second payment out
  }
  if(t.acc===account){
    if(window.AYAN_SALE_TYPES_LC && window.AYAN_SALE_TYPES_LC.has(lc))
      return { in:n(t.recv), out:0 };            // a sale settles through recv
    if(PURCH.indexOf(lc)>=0)
      return { in:0, out:n(t.paid) };            // only the part actually paid
    if(window.AYAN_MONEY_IN_AMT && window.AYAN_MONEY_IN_AMT.has(lc))
      return { in:n(t.amount||t.amt), out:0 };
    return { in:0, out:n(t.amount||t.amt) };
  }
  return { in:0, out:0 };
}

/* True opening balance of an account on a given date: the figure the
   account started from, plus everything that moved before that date.
   FIX: the ledger used to open with the account's CURRENT balance and
   then add the same movements on top, double-counting the whole period. */
function ayanBankOpening(account, fromDate){
  const bank = (DB.banks||[]).find(b=>b.name===account);
  if(!bank) return 0;
  let base;
  if(bank.openingBal!=null && bank.openingBal!=='') base = parseFloat(bank.openingBal)||0;
  else {
    base = parseFloat(bank.bal)||0;
    (DB.tx||[]).forEach(t=>{ const m=ayanBankMove(t,account); base -= (m.in-m.out); });
    (DB.cityFinance||[]).forEach(r=>{
      if(!r||r.bank!==account) return;
      base -= (r.status==='Funded'?(parseFloat(r.advPaid)||0):r.status==='Settled'?(parseFloat(r.net)||0):0);
    });
  }
  if(fromDate){
    (DB.tx||[]).forEach(t=>{
      if(_dk(t.date)>=_dk(fromDate)) return;
      const m=ayanBankMove(t,account); base += (m.in-m.out);
    });
    (DB.cityFinance||[]).forEach(r=>{
      if(!r||r.bank!==account) return;
      if(_dk(r.advDate||r.date)>=_dk(fromDate)) return;
      base += (r.status==='Funded'?(parseFloat(r.advPaid)||0):r.status==='Settled'?(parseFloat(r.net)||0):0);
    });
  }
  return base;
}

/* ── Party / partner opening balance ──────────────────────────────────
   FIX: the Customer, Supplier and Partner ledgers all started their
   running balance at zero (or at a blank "opening balance" setting that
   is almost never filled in), so a customer owing ৳48 lakh opened at
   ৳0.00 and a partner's statement closed at the value of one entry
   instead of his capital account. The opening figure is derived here:
   the balance on record, minus everything the transactions did to it —
   plus back whatever moved before the report's start date. */
function ayanPartyNetEffect(name, cutoff){
  var out={bal:0,cap:0};
  if(!name||typeof applyTxBalance!=='function') return out;
  var oB=DB.banks,oC=DB.customers,oP=DB.partners, key=String(name).trim();
  try{
    (DB.tx||[]).forEach(function(t){
      if(String(t.party||'').trim()!==key) return;
      if(cutoff && _dk(t.date)>=_dk(cutoff)) return;
      var fc=[{name:key,bal:0}], fp=[{name:key,cap:0}];
      DB.banks=[]; DB.customers=fc; DB.partners=fp;
      try{ applyTxBalance(t,1); }catch(e){}
      DB.banks=oB; DB.customers=oC; DB.partners=oP;
      out.bal+=fc[0].bal; out.cap+=fp[0].cap;
    });
  } finally { DB.banks=oB; DB.customers=oC; DB.partners=oP; }
  return out;
}
function ayanPartyOpening(name, from, kind){
  var rec = kind==='partner' ? (DB.partners||[]).find(function(p){return p.name===name;})
                             : (DB.customers||[]).find(function(c){return c.name===name;});
  if(!rec) return 0;
  var stored = kind==='partner' ? (parseFloat(rec.cap)||0) : (parseFloat(rec.bal)||0);
  var all = ayanPartyNetEffect(name,null);
  var base = stored - (kind==='partner'?all.cap:all.bal);
  if(from){ var pre=ayanPartyNetEffect(name,from); base += (kind==='partner'?pre.cap:pre.bal); }
  /* One sign everywhere, and it is the owner's: a positive supplier balance
     is money of yours the supplier is still holding; negative means goods
     have come in that you have not paid for yet. The ledger used to invert
     it, so the statement contradicted the balance on the Parties screen. */
  return base;
}

function renderBankLedger(){
  const allSum = document.getElementById('bk-all-summary');
  if(allSum) allSum.style.display = 'none'; // switching back to a single account hides the all-accounts view
  const account = document.getElementById('bk-account').value;
  const fromDate = document.getElementById('bk-from').value;
  const toDate = document.getElementById('bk-to').value;
  const wrap = document.getElementById('bk-ledger-table');
  if(!account){ wrap.innerHTML='<div style="text-align:center;padding:30px;color:#9ca3af;">Select a bank account.</div>'; return; }

  const bank = (DB.banks||[]).find(b=>b.name===account);
  const openingBal = ayanBankOpening(account, fromDate);

  // Match against the real fields transactions are saved with (acc/acc2),
  // plus split multi-bank payments (payAccounts) so every movement shows up.
  let txs = (DB.tx||[]).filter(t => {
    const splitMatch = Array.isArray(t.payAccounts)&&t.payAccounts.some(p=>p&&p.acc===account);
    const acctMatch = t.acc===account || t.acc2===account || splitMatch;
    const dateMatch = (!fromDate||_dk(t.date)>=_dk(fromDate)) && (!toDate||_dk(t.date)<=_dk(toDate));
    return acctMatch && dateMatch;
  }).sort((a,b)=>(a.date||'')<(b.date||'')?-1:1);

  /* FIX: a funded Factory Finance drawdown puts money in the bank but is
     stored outside DB.tx, so it never appeared on this statement. */
  (DB.cityFinance||[]).forEach(r=>{
    if(!r||r.bank!==account) return;
    const famt = r.status==='Funded' ? (parseFloat(r.advPaid)||0)
               : r.status==='Settled' ? (parseFloat(r.net)||0) : 0;
    if(!famt) return;
    const d = r.advDate||r.date||'';
    if((fromDate&&_dk(d)<_dk(fromDate))||(toDate&&_dk(d)>_dk(toDate))) return;
    txs.push({date:d, inv:r.inv||('FIN-'+r.id), type:'Factory Finance '+(r.status==='Settled'?'Settlement':'Drawdown'),
              party:r.party||'', acc:account, _finIn:famt});
  });
  txs.sort((a,b)=>(a.date||'')<(b.date||'')?-1:1);

  let running = openingBal, totalIn=0, totalOut=0;
  const rows = txs.map(t => {
    const split = Array.isArray(t.payAccounts) ? t.payAccounts.find(p=>p&&p.acc===account) : null;
    const move = t._finIn ? {in:t._finIn,out:0} : ayanBankMove(t, account);
    let inAmt=move.in, outAmt=move.out;
    running += inAmt - outAmt; totalIn += inAmt; totalOut += outAmt;
    const bc = running>=0?'#16a34a':'#dc2626';
    return `<tr style="border-bottom:1px solid #f3f4f6;" data-hover-bg="#f9fafb">
      <td style="padding:9px 12px;color:#6b7280;">${t.date||'—'}</td>
      <td style="padding:9px 12px;font-size:11px;">${t.inv||'—'}</td>
      <td style="padding:9px 12px;"><div style="font-weight:600;">${t.type}${split?' <span style="font-size:10px;color:#7c3aed;font-weight:700;">(split)</span>':''}</div><div style="font-size:10px;color:#6b7280;">${escHTML(t.party ||'')}</div></td>
      <td style="padding:9px 12px;text-align:right;color:#16a34a;font-weight:700;">${inAmt>0?'৳'+pf(inAmt):''}</td>
      <td style="padding:9px 12px;text-align:right;color:#dc2626;font-weight:700;">${outAmt>0?'৳'+pf(outAmt):''}</td>
      <td style="padding:9px 12px;text-align:right;font-weight:800;color:${bc};">৳${pf(running)}</td>
    </tr>`;
  });

  const closing = openingBal + totalIn - totalOut;
  const sumEl = document.getElementById('bk-ledger-summary');
  sumEl.style.display = 'grid';
  document.getElementById('bk-open').textContent = '৳'+pf(openingBal);
  document.getElementById('bk-in').textContent = '৳'+pf(totalIn);
  document.getElementById('bk-out').textContent = '৳'+pf(totalOut);
  document.getElementById('bk-close').textContent = '৳'+pf(closing);

  if(wrap) wrap.innerHTML = `<table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
      <th style="padding:10px 12px;text-align:left;">Date</th>
      <th style="padding:10px 12px;text-align:left;">Invoice</th>
      <th style="padding:10px 12px;text-align:left;">Particulars</th>
      <th style="padding:10px 12px;text-align:right;">Money In (৳)</th>
      <th style="padding:10px 12px;text-align:right;">Money Out (৳)</th>
      <th style="padding:10px 12px;text-align:right;">Balance (৳)</th>
    </tr></thead>
    <tbody>
      <tr style="background:#f0fdf4;"><td colspan="5" style="padding:9px 12px;font-weight:700;color:#0f3d26;">Opening Balance</td><td style="padding:9px 12px;text-align:right;font-weight:800;color:#0f3d26;">৳${pf(openingBal)}</td></tr>
      ${rows.length?rows.join(''):'<tr><td colspan="6" style="text-align:center;padding:20px;color:#9ca3af;">No transactions found.</td></tr>'}
      <tr style="background:#f0fdf4;border-top:2px solid #16a34a;">
        <td colspan="3" style="padding:10px 12px;font-weight:800;color:#0f3d26;">CLOSING BALANCE</td>
        <td style="padding:10px 12px;text-align:right;font-weight:800;color:#16a34a;">৳${pf(totalIn)}</td>
        <td style="padding:10px 12px;text-align:right;font-weight:800;color:#dc2626;">৳${pf(totalOut)}</td>
        <td style="padding:10px 12px;text-align:right;font-weight:900;font-size:14px;color:${closing>=0?'#16a34a':'#dc2626'};">৳${pf(closing)}</td>
      </tr>
    </tbody>
  </table>`;
}

/* All-accounts summary — every bank account's Opening Balance, total Money
   In, total Money Out and Closing Balance in one table, full history (no
   date filter). Reuses the exact same ayanBankOpening()/ayanBankMove()
   engine renderBankLedger() uses for one account at a time, so the two
   views can never disagree with each other. An account with zero linked
   transactions is flagged, since that is exactly the pattern that shows up
   as an unexplained opening balance on the Balance Sheet mismatch banner. */
function renderAllBankAccountsSummary(){
  document.getElementById('bk-ledger-summary').style.display = 'none';
  document.getElementById('bk-ledger-table').innerHTML = '';
  const wrap = document.getElementById('bk-all-summary');
  if(!wrap) return;
  wrap.style.display = 'block';

  const banks = (DB.banks||[]).slice().sort((a,b)=>(a.name||'').localeCompare(b.name||''));
  if(!banks.length){ wrap.innerHTML = '<div style="text-align:center;padding:30px;color:#9ca3af;">No bank accounts configured.</div>'; return; }

  let grandOpen=0, grandIn=0, grandOut=0, unlinkedCount=0;
  const rows = banks.map(b=>{
    const name = b.name;
    const opening = ayanBankOpening(name, '');
    let moneyIn=0, moneyOut=0, hasTx=false;
    (DB.tx||[]).forEach(t=>{
      const split = Array.isArray(t.payAccounts) ? t.payAccounts.find(p=>p&&p.acc===name) : null;
      const acctMatch = t.acc===name || t.acc2===name || !!split;
      if(!acctMatch) return;
      const m = ayanBankMove(t, name);
      if(m.in || m.out) hasTx = true;
      moneyIn += m.in; moneyOut += m.out;
    });
    (DB.cityFinance||[]).forEach(r=>{
      if(!r||r.bank!==name) return;
      const famt = r.status==='Funded' ? (parseFloat(r.advPaid)||0) : r.status==='Settled' ? (parseFloat(r.net)||0) : 0;
      if(famt){ moneyIn += famt; hasTx = true; }
    });
    const closing = opening + moneyIn - moneyOut;
    grandOpen+=opening; grandIn+=moneyIn; grandOut+=moneyOut;
    if(!hasTx && opening) unlinkedCount++;
    return { name, opening, moneyIn, moneyOut, closing, unlinked: !hasTx && !!opening };
  });

  const rowHtml = rows.map((r,i)=>`<tr style="border-bottom:1px solid #f3f4f6;background:${r.unlinked?'#fef2f2':i%2?'#f9fafb':'#fff'};">
    <td style="padding:9px 12px;font-weight:700;">${escHTML(r.name)}${r.unlinked?` <span title="Opening balance with no linked transactions" style="font-size:10px;color:#dc2626;font-weight:800;">⚠ unlinked</span> <button data-x-click="openJournalForUnlinkedBank('${escJSAttr(r.name)}', ${r.opening})" style="margin-left:6px;padding:2px 8px;background:#0f3d26;color:#fff;border:none;border-radius:10px;font-size:10px;font-weight:700;cursor:pointer;">📒 Post Opening Entry</button>`:''}</td>
    <td style="padding:9px 12px;text-align:right;">৳${pf(r.opening)}</td>
    <td style="padding:9px 12px;text-align:right;color:#16a34a;">${r.moneyIn?'৳'+pf(r.moneyIn):'—'}</td>
    <td style="padding:9px 12px;text-align:right;color:#dc2626;">${r.moneyOut?'৳'+pf(r.moneyOut):'—'}</td>
    <td style="padding:9px 12px;text-align:right;font-weight:800;color:${r.closing>=0?'#0f3d26':'#dc2626'};">৳${pf(r.closing)}</td>
  </tr>`).join('');

  wrap.innerHTML = `
    ${unlinkedCount?`<div style="background:#fef2f2;border:1px solid #fecaca;border-radius:8px;padding:10px 14px;margin-bottom:12px;font-size:12px;color:#991b1b;">
      ⚠ ${unlinkedCount} account(s) below carry an opening balance with no transaction ever recorded against them — these are exactly the accounts the Balance Sheet mismatch check flags. Record where that opening money came from (an Opening Balance / Capital transaction) to clear them.
      <div style="margin-top:8px;display:flex;gap:8px;flex-wrap:wrap;align-items:center;">
        <label style="font-weight:700;">Date:</label>
        <input type="date" id="ob-batch-date" value="${new Date().toISOString().split('T')[0]}" style="padding:4px 8px;border:1px solid #fca5a5;border-radius:5px;font-size:11px;"/>
        <label style="font-weight:700;">Credit Account:</label>
        <input type="text" id="ob-batch-credit" value="Opening Balance Equity" style="padding:4px 8px;border:1px solid #fca5a5;border-radius:5px;font-size:11px;width:180px;"/>
        <button data-x-click="postAllOpeningEntries()" style="padding:6px 14px;background:#0f3d26;color:#fff;border:none;border-radius:6px;font-size:11px;font-weight:700;cursor:pointer;">📒 Post All Opening Entries (${unlinkedCount})</button>
      </div>
    </div>`:''}
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;margin-bottom:14px;">
      <table style="width:100%;border-collapse:collapse;font-size:12px;">
        <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
          <th style="padding:10px 12px;text-align:left;">Bank Account</th>
          <th style="padding:10px 12px;text-align:right;">Opening Balance (৳)</th>
          <th style="padding:10px 12px;text-align:right;">Money In (৳)</th>
          <th style="padding:10px 12px;text-align:right;">Money Out (৳)</th>
          <th style="padding:10px 12px;text-align:right;">Closing Balance (৳)</th>
        </tr></thead>
        <tbody>
          ${rowHtml}
          <tr style="background:#f0fdf4;border-top:2px solid #16a34a;font-weight:800;">
            <td style="padding:10px 12px;color:#0f3d26;">TOTAL — ALL ACCOUNTS</td>
            <td style="padding:10px 12px;text-align:right;color:#0f3d26;">৳${pf(grandOpen)}</td>
            <td style="padding:10px 12px;text-align:right;color:#16a34a;">৳${pf(grandIn)}</td>
            <td style="padding:10px 12px;text-align:right;color:#dc2626;">৳${pf(grandOut)}</td>
            <td style="padding:10px 12px;text-align:right;color:${(grandOpen+grandIn-grandOut)>=0?'#0f3d26':'#dc2626'};">৳${pf(grandOpen+grandIn-grandOut)}</td>
          </tr>
        </tbody>
      </table>
    </div>
    <div style="font-size:11px;color:#9ca3af;">Click any account name in the dropdown above for its full day-by-day transaction history.</div>
  `;
}

function renderBankStatement(){
  // Auto-inject HTML structure if needed
  (function(){
    const _pg=document.getElementById('pg-bankstmt');
    if(_pg&&!_pg.querySelector('#bkstmt-account')){
      _pg.innerHTML=`<div style="padding:20px;">
        <h2 style="font-size:18px;font-weight:800;color:#0f3d26;margin:0 0 16px;">🏦 Bank Statement</h2>
        <div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:16px;">
          <select id="bkstmt-account" data-x-change="renderBankStatement()" style="padding:8px 12px;border:1.5px solid #d1d5db;border-radius:8px;font-size:13px;min-width:200px;">
            <option value="">-- Select Account --</option>
          </select>
          <input type="date" id="bkstmt-from" data-x-change="renderBankStatement()" style="padding:8px 12px;border:1.5px solid #d1d5db;border-radius:8px;font-size:13px;">
          <input type="date" id="bkstmt-to" data-x-change="renderBankStatement()" style="padding:8px 12px;border:1.5px solid #d1d5db;border-radius:8px;font-size:13px;">
          <button data-x-click="renderBankStatement()" style="padding:8px 16px;background:#16a34a;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:12px;">🔄 Refresh</button>
          <button data-x-click="printBankStatement()" style="padding:8px 16px;background:#2563eb;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:12px;">🖨️ Print</button>
        </div>
        <div id="bkstmt-cards" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:12px;margin-bottom:16px;"></div>
        <div id="bkstmt-body" style="background:#fff;border-radius:12px;padding:16px;border:1px solid #e5e7eb;"></div>
      </div>`;
    }
  })();

  // Populate bank dropdown
  const sel=document.getElementById('bkstmt-account');
  if(sel&&sel.options.length<=1){
    (DB.banks||[]).forEach(b=>{
      const opt=document.createElement('option');
      opt.value=b.name;
      opt.textContent=b.name+' — ৳'+(b.bal||0).toLocaleString('en-IN',{minimumFractionDigits:2});
      sel.appendChild(opt);
    });
  }

  const accName=document.getElementById('bkstmt-account')?.value||'';
  const fromDate=document.getElementById('bkstmt-from')?.value||'';
  const toDate=document.getElementById('bkstmt-to')?.value||new Date().toISOString().split('T')[0];

  const bank=(DB.banks||[]).find(b=>b.name===accName);
  const cards=document.getElementById('bkstmt-cards');
  const body=document.getElementById('bkstmt-body');

  if(!accName){
    if(cards) cards.innerHTML='';
    if(body) body.innerHTML='<div style="text-align:center;padding:30px;color:#9ca3af;">Please select a bank account to view statement.</div>';
    return;
  }

  // Bank statement debit/credit type classifications (reused for both
  // ordinary single-account transactions and multi-bank split payments).
  const BKSTMT_DEBIT_TYPES=['Bank Withdrawal','Bank Charge','Purchase Payment',
    'Supplier Payment','Salary Payment','Employee Advance','Bank Transfer','Inter Transfer',
    'Partner Withdrawal','Cash Payment','Other Expense','Office Rent','Electricity Bill',
    'Internet Bill','Fuel Expense','Transport Cost','Loading Charge','Unloading Charge',
    'Commission Payment','Other Expense','Interest Expense','Advance to Supplier','Purchase Advance'];
  const BKSTMT_CREDIT_TYPES=['Bank Deposit','Sales Receipt','Sales Advance',
    'Cash Received','Partner Capital','Partner Fund','Opening Bank Balance',
    'Supplier Refund','Payment Refund',
    'Other Income','Interest Income'];
  const BKSTMT_TRANSFER_TYPES=['Bank Transfer','Inter Transfer'];

  // Get ALL of this account's transactions (unfiltered) so we can carry
  // forward a correct opening balance into the filtered date range below —
  // including ones where this account only received part of a multi-bank
  // split payment (t.payAccounts).
  const allTxns=(DB.tx||[]).filter(t=>{
    const splitMatch=Array.isArray(t.payAccounts)&&t.payAccounts.some(p=>p&&p.acc===accName);
    return (t.acc===accName||t.acc2===accName||splitMatch);
  }).sort((a,b)=>a.date.localeCompare(b.date));

  function bkstmtDelta(t){
    let isDebit=false, isCredit=false, amt=0;
    const split=Array.isArray(t.payAccounts)?t.payAccounts.find(p=>p&&p.acc===accName):null;
    if(split){
      amt=parseFloat(split.amt)||0;
      isDebit=BKSTMT_DEBIT_TYPES.includes(t.type);
      isCredit=!isDebit&&BKSTMT_CREDIT_TYPES.includes(t.type);
    } else {
      isDebit=(t.acc===accName&&BKSTMT_DEBIT_TYPES.includes(t.type));
      isCredit=(t.acc===accName&&BKSTMT_CREDIT_TYPES.includes(t.type))||
        (t.acc2===accName&&BKSTMT_TRANSFER_TYPES.includes(t.type));
      amt=t.amt||t.amount||0;
    }
    return {isCredit,isDebit,amt,isSplit:!!split};
  }

  // FIX (opening balance): "how much I started with" — the account's own
  // recorded opening balance, plus every transaction dated BEFORE the
  // selected "from" date. Previously the running balance below always
  // started at 0, so as soon as you filtered by a date range the "Balance"
  // column stopped matching the account's real balance.
  const openingBal=parseFloat(bank?.openingBal)||0;
  let carryBal=openingBal;
  allTxns.forEach(t=>{
    if(fromDate&&t.date<fromDate){
      const d=bkstmtDelta(t);
      if(d.isCredit) carryBal+=d.amt;
      else if(d.isDebit) carryBal-=d.amt;
    }
  });

  let txns=allTxns.filter(t=>{
    if(fromDate&&t.date<fromDate) return false;
    if(toDate&&t.date>toDate) return false;
    return true;
  });

  // Calculate running balance, carried forward from carryBal (not 0)
  let runBal=carryBal;
  const rows=txns.map(t=>{
    const {isCredit,isDebit,amt,isSplit}=bkstmtDelta(t);
    if(isCredit) runBal+=amt;
    else if(isDebit) runBal-=amt;
    return {t,isCredit,isDebit,amt,runBal,isSplit};
  });

  const totalCredit=rows.filter(r=>r.isCredit).reduce((s,r)=>s+r.amt,0);
  const totalDebit=rows.filter(r=>r.isDebit).reduce((s,r)=>s+r.amt,0);

  if(cards) cards.innerHTML=[
    {icon:'🏦',label:'Account',val:accName,color:'#2563eb'},
    {icon:'🌱',label:'Opening Balance'+(fromDate?' (as of '+fromDate+')':''),val:'৳'+carryBal.toLocaleString('en-IN',{minimumFractionDigits:2}),color:'#0f766e'},
    {icon:'💰',label:'Current Balance',val:'৳'+(bank?.bal||0).toLocaleString('en-IN',{minimumFractionDigits:2}),color:'#16a34a'},
    {icon:'📥',label:'Money In (Credits)',val:'৳'+totalCredit.toLocaleString('en-IN',{minimumFractionDigits:2}),color:'#059669'},
    {icon:'📤',label:'Money Out (Debits)',val:'৳'+totalDebit.toLocaleString('en-IN',{minimumFractionDigits:2}),color:'#dc2626'},
    {icon:'📋',label:'Transactions',val:txns.length,color:'#7c3aed'},
  ].map(k=>`<div class="kpi-card" style="border-left:4px solid ${k.color};">
    <div style="font-size:18px;">${k.icon}</div>
    <div style="font-size:18px;font-weight:900;color:${k.color};margin-top:4px;">${k.val}</div>
    <div style="font-size:10px;color:#6b7280;font-weight:700;">${escHTML(k.label)}</div>
  </div>`).join('');

  if(body){
    if(!rows.length){
      body.innerHTML='<div style="text-align:center;padding:14px;color:#6b7280;font-size:12.5px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;margin-bottom:12px;">'+
        'Opening balance'+(fromDate?' as of '+fromDate:'')+': <strong style="color:#0f766e;">৳'+carryBal.toLocaleString('en-IN',{minimumFractionDigits:2})+'</strong></div>'+
        '<div style="text-align:center;padding:30px;color:#9ca3af;">No transactions found for '+accName+(fromDate?' from '+fromDate:'')+(toDate?' to '+toDate:'')+'</div>';
    } else {
      body.innerHTML=`<table class="tbl"><thead><tr>
        <th>Date</th><th>Description</th><th>Party</th><th>Credit (৳)</th><th>Debit (৳)</th><th>Balance (৳)</th>
      </tr></thead>
      <tbody>
      <tr style="background:#f0fdfa;">
        <td>${fromDate||'—'}</td>
        <td colspan="3" style="font-weight:700;color:#0f766e;">🌱 Opening Balance</td>
        <td style="color:#9ca3af;">—</td>
        <td style="font-weight:800;color:#0f766e;">৳${carryBal.toLocaleString('en-IN',{minimumFractionDigits:2})}</td>
      </tr>
      ${rows.map(({t,isCredit,isDebit,amt,runBal,isSplit})=>`<tr>
        <td>${t.date}</td>
        <td>${t.type}${isSplit?' <span style="font-size:10px;color:#7c3aed;font-weight:700;">(split)</span>':''}</td>
        <td>${escHTML(t.party||'—')}</td>
        <td style="color:#16a34a;font-weight:700;">${isCredit?'৳'+amt.toLocaleString('en-IN',{minimumFractionDigits:2}):'—'}</td>
        <td style="color:#dc2626;font-weight:700;">${isDebit?'৳'+amt.toLocaleString('en-IN',{minimumFractionDigits:2}):'—'}</td>
        <td style="font-weight:800;color:${runBal>=0?'#16a34a':'#dc2626'};">৳${runBal.toLocaleString('en-IN',{minimumFractionDigits:2})}</td>
      </tr>`).join('')}</tbody>
      <tfoot><tr>
        <td colspan="3" style="text-align:right;font-weight:800;padding:10px 12px;">Totals:</td>
        <td style="font-weight:900;color:#16a34a;padding:10px 12px;">৳${totalCredit.toLocaleString('en-IN',{minimumFractionDigits:2})}</td>
        <td style="font-weight:900;color:#dc2626;padding:10px 12px;">৳${totalDebit.toLocaleString('en-IN',{minimumFractionDigits:2})}</td>
        <td style="font-weight:900;padding:10px 12px;">৳${(bank?.bal||0).toLocaleString('en-IN',{minimumFractionDigits:2})}</td>
      </tr></tfoot></table>`;
    }
  }
}

function printBankStatement(){
  /* FIX: this reads #bkstmt-account, which only exists on the Bank
     Statement page — so the button on Print Templates could never do
     anything but show an error. It now takes you there instead. */
  const accName=document.getElementById('bkstmt-account')?.value||'';
  if(!accName){
    if(!document.getElementById('bkstmt-account')){
      if(typeof toast==='function') toast('Opening Bank Statement — choose an account, then press Print','i');
      if(typeof nav==='function') nav('bankstatement');
      return;
    }
    toast('Please select a bank account first','e');return;
  }
  const body=document.getElementById('bkstmt-body');
  const cards=document.getElementById('bkstmt-cards');
  const co=DB.settings||{};
  const html=`<!DOCTYPE html><html><head><title>Bank Statement — ${accName}</title>
  <style>body{font-family:'Segoe UI',sans-serif;padding:20px;font-size:12px;}
  table{width:100%;border-collapse:collapse;}
  th{background:#2563eb;color:#fff;padding:8px 10px;text-align:left;font-size:11px;}
  td{padding:7px 10px;border-bottom:1px solid #e5e7eb;}
  tfoot td{font-weight:800;background:#eff6ff;}
  @page{size:A4;margin:10mm 12mm;}@media print{html,body{max-width:100%!important;}*{overflow:visible!important;max-height:none!important;}img,svg,canvas{max-width:100%!important;height:auto!important;}table{width:100%!important;table-layout:auto!important;word-break:break-word;overflow-wrap:anywhere;}th,td{white-space:normal!important;overflow-wrap:anywhere;}.container,.voucher,.receipt,.doc,.page{max-width:100%!important;width:auto!important;}}table{page-break-inside:auto;}tr{page-break-inside:avoid;}thead{display:table-header-group;}@media print{body{padding:10px;}}</style>
</head><body>
  <noscript>
  <div style="padding:20px;text-align:center;font-family:sans-serif;">
    <strong>JavaScript is required</strong><br>
    AYAN AGRO Bank Ledger runs entirely in your browser. Please enable JavaScript to continue.
  </div>
</noscript>
<div style="display:flex;justify-content:space-between;align-items:flex-end;border-bottom:2px solid #2563eb;padding-bottom:8px;margin-bottom:12px;">
    <div>
      <div style="font-size:18px;font-weight:900;">${escHTML(prtCo().name)}</div>
      <div style="font-size:12px;color:#555;">Bank Statement — ${accName}</div>
    </div>
    <div style="font-size:11px;color:#6b7280;">Printed: ${new Date().toLocaleString('en-GB')}</div>
  </div>
  <div style="margin-bottom:12px;font-size:11px;color:#374151;">${cards?cards.innerText.replace(/\n/g,' • '):''}</div>
  ${body?body.innerHTML:''}


</body></html>`;
  const w=openPrintWindow(); if(!w) return;
  w.document.write(html);
  w.document.close();
  setTimeout(()=>w.print(),500);
  logAudit('PRINT','Bank Statement','Printed statement for '+accName);
}











function populateReconAccounts(){
  const sel = document.getElementById('recon-account');
  if(!sel) return;
  sel.innerHTML = '<option value="">-- Select Bank Account --</option>';
  (DB.banks||[]).forEach(b => {
    const opt = document.createElement('option');
    opt.value = b.name; opt.textContent = b.name;
    sel.appendChild(opt);
  });
}

function initBankReconciliationPage(){
  const bkSel = document.getElementById('bk-account');
  if(bkSel){
    bkSel.innerHTML = '<option value="">-- Select Bank Account --</option>';
    (DB.banks||[]).forEach(b => {
      const opt = document.createElement('option');
      opt.value = b.name; opt.textContent = b.name;
      bkSel.appendChild(opt);
    });
  }
  populateReconAccounts();
}

function runReconciliation(){
  const account = document.getElementById('recon-account').value;
  const stmtBal = parseFloat(document.getElementById('recon-statement-bal').value)||0;
  if(!account){ alert('Select a bank account'); return; }

  const bank = (DB.banks||[]).find(b=>b.name===account);
  const bookBal = bank ? (bank.bal||0) : 0;

  // Pending cheques affect reconciliation
  const pendingReceived = (DB.cheques||[]).filter(c=>c.bank===account&&c.type==='Received'&&c.status==='Pending').reduce((s,c)=>s+(c.amount||0),0);
  const pendingIssued = (DB.cheques||[]).filter(c=>c.bank===account&&c.type==='Issued'&&c.status==='Pending').reduce((s,c)=>s+(c.amount||0),0);

  const adjustedBook = bookBal + pendingIssued - pendingReceived;
  const diff = stmtBal - adjustedBook;
  const isBalanced = Math.abs(diff) < 1;

  document.getElementById('recon-result').style.display = 'block';
  document.getElementById('recon-book-detail').innerHTML = `
    <div style="font-size:12px;line-height:2;">
      <div style="display:flex;justify-content:space-between;"><span>Book Balance:</span><span style="font-weight:700;">৳${pf(bookBal)}</span></div>
      <div style="display:flex;justify-content:space-between;color:#d97706;"><span>+ Pending Issued Cheques:</span><span>৳${pf(pendingIssued)}</span></div>
      <div style="display:flex;justify-content:space-between;color:#dc2626;"><span>− Pending Received Cheques:</span><span>৳${pf(pendingReceived)}</span></div>
      <div style="display:flex;justify-content:space-between;border-top:2px solid #16a34a;margin-top:6px;padding-top:6px;font-weight:800;font-size:14px;color:#0f3d26;"><span>Adjusted Book Balance:</span><span>৳${pf(adjustedBook)}</span></div>
    </div>`;
  document.getElementById('recon-bank-detail').innerHTML = `
    <div style="font-size:12px;line-height:2;">
      <div style="display:flex;justify-content:space-between;"><span>Bank Statement Balance:</span><span style="font-weight:700;">৳${pf(stmtBal)}</span></div>
      <div style="display:flex;justify-content:space-between;border-top:2px solid #2563eb;margin-top:6px;padding-top:6px;font-weight:800;font-size:14px;color:#1d4ed8;"><span>Difference:</span><span style="color:${isBalanced?'#16a34a':'#dc2626'};">৳${pf(diff)}</span></div>
    </div>`;
  const statusEl = document.getElementById('recon-status');
  statusEl.style.background = isBalanced ? '#f0fdf4' : '#fef2f2';
  statusEl.style.color = isBalanced ? '#16a34a' : '#dc2626';
  statusEl.style.border = '2px solid ' + (isBalanced?'#bbf7d0':'#fecaca');
  statusEl.textContent = isBalanced ? '✅ RECONCILED — Books match bank statement!' : '⚠️ DIFFERENCE of ৳'+pf(Math.abs(diff))+' — Please investigate outstanding items';
}


