function drawReportCharts(){
  if(typeof Chart === 'undefined') return; // Chart.js unavailable — skip silently
  const txs = DB.tx||[];
  // Chart 1: Transaction volume by type
  const c1 = document.getElementById('cRep1');
  if(c1 && window.Chart){
    const typeCounts = {};
    txs.forEach(t=>{ typeCounts[t.type]=(typeCounts[t.type]||0)+1; });
    const sorted = Object.entries(typeCounts).sort((a,b)=>b[1]-a[1]).slice(0,10);
    if(window._chartRep1){ try{ window._chartRep1.destroy(); }catch(e){} window._chartRep1=null; }
    window._chartRep1 = new Chart(c1, {
      type:'bar',
      data:{
        labels: sorted.map(e=>e[0]),
        datasets:[{label:'Count',data:sorted.map(e=>e[1]),
          backgroundColor:'rgba(22,163,74,0.7)',borderColor:'#16a34a',borderWidth:1}]
      },
      options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},
        scales:{y:{beginAtZero:true},x:{ticks:{font:{size:10}}}}}
    });
  }
  // Chart 2: Transaction count by mode
  const c2 = document.getElementById('cRep2');
  if(c2 && window.Chart){
    const modeCounts = {};
    txs.forEach(t=>{ const m=t.mode||'Unknown'; modeCounts[m]=(modeCounts[m]||0)+1; });
    const entries = Object.entries(modeCounts);
    if(window._chartRep2){ try{ window._chartRep2.destroy(); }catch(e){} window._chartRep2=null; }
    window._chartRep2 = new Chart(c2, {
      type:'doughnut',
      data:{
        labels: entries.map(e=>e[0]),
        datasets:[{data:entries.map(e=>e[1]),
          backgroundColor:['#16a34a','#2563eb','#f59e0b','#dc2626','#7c3aed','#0891b2']}]
      },
      options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom',labels:{font:{size:10}}}}}
    });
  }
}

function renderPLReport(){
  const wrap = document.getElementById('pl-report-body-v2');
  if(!wrap) return;
  const txs = DB.tx||[];
  const saleTypes = window.SALE_TX_TYPES || new Set(['Sale']);
  const purchTypes = window.PURCHASE_TX_TYPES || new Set(['Purchase']);
  const expTypes = window.EXPENSE_TX_TYPES || new Set(['Salary Payment','Office Rent','Electricity Bill','Internet Bill','Telephone Bill','Fuel Expense','Transport Cost','Loading Charge','Unloading Charge','Commission Payment','Brokerage Fee','Legal Fee','Audit Fee','Insurance Premium','Tax Payment','Government Fee','License Fee','Maintenance Cost','Repair Expense','Stationery Purchase','Other Expense','Interest Expense','Bank Charge']);

  const totalSales = sumRevenue(txs);
  const totalPurch = sumCogs(txs);  // total purchases (shown for info)
  // FIX-PROFIT-1: Sales Returns বাদ, Other Income যোগ, Purchase Return দিয়ে COGS adjust
  const salesRet2  = txs.filter(t=>t.type==='Sales Return'||t.type==='Sale Return').reduce((s,t)=>s+txAmt(t),0);
  const otherInc2  = txs.filter(t=>t.type==='Other Income'||t.type==='Interest Income').reduce((s,t)=>s+txAmt(t),0);
  const purchRet2  = txs.filter(t=>t.type==='Purchase Return').reduce((s,t)=>s+txAmt(t),0);
  const netRevenue2 = totalSales - salesRet2 + otherInc2;
  const totalCOGS  = Math.max(0, window.computeCOGS(txs) - purchRet2); // cost of goods actually SOLD, adjusted for returns
  const totalExp = txs.filter(t=>expTypes.has(String(t.type||'').trim())).reduce((s,t)=>s+txAmt(t),0);
  const grossProfit = netRevenue2 - totalCOGS;  // Gross Profit = Net Revenue − COGS
  // Net Profit = Gross Profit − Expenses − Transport − Sale Sub-Costs
  const _totalTransport2 = txs.reduce(function(s,t){ return s + (parseFloat(t.truckrent)||0); }, 0);
  const _totalSubCosts2 = (typeof window.sumSaleSubCosts === 'function')
    ? window.sumSaleSubCosts(txs)
    : txs.reduce(function(s,t){
        return s + (parseFloat(t.agentAcost)||0) + (parseFloat(t.agentBcost)||0)
                 + (parseFloat(t.qc)||0) + (parseFloat(t.unload)||0) + (parseFloat(t.othercost)||0) + (parseFloat(t.othercost2)||0);
      }, 0);
  const netProfit   = grossProfit - totalExp - _totalTransport2 - _totalSubCosts2;  // Net Profit = Gross − Expenses − Transport − Costs

  if(wrap) wrap.innerHTML = `
    <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:18px;">
      <div style="background:linear-gradient(135deg,#16a34a,#15803d);color:#fff;border-radius:10px;padding:14px;">
        <div style="font-size:11px;opacity:.8;">Total Revenue</div>
        <div style="font-size:20px;font-weight:800;">৳${pf(totalSales)}</div>
      </div>
      <div style="background:linear-gradient(135deg,#dc2626,#b91c1c);color:#fff;border-radius:10px;padding:14px;">
        <div style="font-size:11px;opacity:.8;">COGS (Sold Only)</div>
        <div style="font-size:20px;font-weight:800;">৳${pf(totalCOGS)}</div>
      </div>
      <div style="background:linear-gradient(135deg,#2563eb,#1d4ed8);color:#fff;border-radius:10px;padding:14px;">
        <div style="font-size:11px;opacity:.8;">Total Expenses</div>
        <div style="font-size:20px;font-weight:800;">৳${pf(totalExp)}</div>
      </div>
      <div style="background:linear-gradient(135deg,${netProfit>=0?'#065f46,#059669':'#7f1d1d,#991b1b'});color:#fff;border-radius:10px;padding:14px;">
        <div style="font-size:11px;opacity:.8;">Net Profit</div>
        <div style="font-size:20px;font-weight:800;">৳${pf(netProfit)}</div>
      </div>
    </div>
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
      <table style="width:100%;border-collapse:collapse;font-size:12px;">
        <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
          <th style="padding:10px 16px;text-align:left;">Particulars</th>
          <th style="padding:10px 16px;text-align:right;">Amount (৳)</th>
        </tr></thead>
        <tbody>
          <tr style="background:#f0fdf4;"><td colspan="2" style="padding:8px 16px;font-weight:800;color:#0f3d26;">INCOME</td></tr>
          <tr><td style="padding:8px 16px 8px 28px;">Sales Revenue</td><td style="padding:8px 16px;text-align:right;font-weight:700;color:#16a34a;">৳${pf(totalSales)}</td></tr>
          ${salesRet2>0?`<tr><td style="padding:8px 16px 8px 28px;color:#dc2626;">Less: Sales Returns</td><td style="padding:8px 16px;text-align:right;font-weight:700;color:#dc2626;">(৳${pf(salesRet2)})</td></tr>`:''}
          ${otherInc2>0?`<tr><td style="padding:8px 16px 8px 28px;color:#0369a1;">Other Income</td><td style="padding:8px 16px;text-align:right;font-weight:700;color:#0369a1;">৳${pf(otherInc2)}</td></tr>`:''}
          <tr style="background:#fff3cd;"><td colspan="2" style="padding:8px 16px;font-weight:800;color:#92400e;">COST OF GOODS SOLD</td></tr>
          <tr><td style="padding:8px 16px 8px 28px;">COGS (qty sold × avg purchase cost)</td><td style="padding:8px 16px;text-align:right;font-weight:700;color:#b45309;">৳${pf(window.computeCOGS(txs))}</td></tr>
          ${purchRet2>0?`<tr><td style="padding:8px 16px 8px 28px;color:#16a34a;">Less: Purchase Returns</td><td style="padding:8px 16px;text-align:right;font-weight:700;color:#16a34a;">(৳${pf(purchRet2)})</td></tr>`:''}
          <tr style="background:#ecfdf5;font-weight:700;"><td style="padding:8px 16px;">Gross Profit <span style="font-weight:400;font-size:10px;color:#6b7280;">(Net Revenue − COGS)</span></td><td style="padding:8px 16px;text-align:right;color:${grossProfit>=0?'#16a34a':'#dc2626'};">৳${pf(grossProfit)}</td></tr>
          <tr style="background:#fef2f2;"><td colspan="2" style="padding:8px 16px;font-weight:800;color:#dc2626;">OPERATING EXPENSES</td></tr>
          <tr><td style="padding:8px 16px 8px 28px;">Operating Expenses</td><td style="padding:8px 16px;text-align:right;font-weight:700;color:#dc2626;">৳${pf(totalExp)}</td></tr>
          <tr><td style="padding:8px 16px 8px 28px;font-size:10px;color:#9ca3af;">Total Purchases (for reference)</td><td style="padding:8px 16px;text-align:right;font-size:10px;color:#9ca3af;">৳${pf(totalPurch)}</td></tr>
          <tr style="background:#f0fdf4;border-top:2px solid #16a34a;"><td style="padding:10px 16px;font-weight:900;font-size:14px;color:#0f3d26;">NET PROFIT / (LOSS)</td><td style="padding:10px 16px;text-align:right;font-weight:900;font-size:16px;color:${netProfit>=0?'#16a34a':'#dc2626'};">৳${pf(netProfit)}</td></tr>
        </tbody>
      </table>
    </div>`;
}

function renderDailySalesReport(){
  const wrap = document.getElementById('rpt-daily-body');
  if(!wrap) return;
  const dateFilter = document.getElementById('rpt-daily-date')?.value || new Date().toISOString().split('T')[0];
  const txs = (DB.tx||[]).filter(t=>t.date===dateFilter && (isRevenueTx(t)||String(t.type||'').trim()==='Sales Receipt'));
  const total = txs.reduce((s,t)=>s+txAmt(t),0);
  if(!txs.length){
    wrap.innerHTML=`<div style="text-align:center;padding:30px;color:#9ca3af;">No sales on ${dateFilter}.</div>`;
    return;
  }
  if(wrap) wrap.innerHTML = `
    <div style="background:linear-gradient(135deg,#16a34a,#15803d);color:#fff;border-radius:10px;padding:14px;margin-bottom:14px;display:flex;justify-content:space-between;align-items:center;">
      <div><div style="font-size:11px;opacity:.8;">Total Sales — ${dateFilter}</div><div style="font-size:22px;font-weight:800;">৳${pf(total)}</div></div>
      <div style="font-size:28px;">📊</div>
    </div>
    <table style="width:100%;border-collapse:collapse;font-size:12px;background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
      <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
        <th style="padding:10px 12px;text-align:left;">Invoice</th>
        <th style="padding:10px 12px;text-align:left;">Party</th>
        <th style="padding:10px 12px;text-align:left;">Product</th>
        <th style="padding:10px 12px;text-align:right;">Qty</th>
        <th style="padding:10px 12px;text-align:right;">Rate</th>
        <th style="padding:10px 12px;text-align:right;">Amount (৳)</th>
      </tr></thead>
      <tbody>${txs.map(t=>`<tr style="border-bottom:1px solid #f3f4f6;">
        <td style="padding:9px 12px;font-weight:700;color:#0f3d26;">${t.inv||'—'}</td>
        <td style="padding:9px 12px;">${escHTML(t.party||'—')}</td>
        <td style="padding:9px 12px;color:#6b7280;">${t.prod||'—'}</td>
        <td style="padding:9px 12px;text-align:right;">${t.qty||'—'}</td>
        <td style="padding:9px 12px;text-align:right;">${t.rate?'৳'+pf(t.rate):'—'}</td>
        <td style="padding:9px 12px;text-align:right;font-weight:800;color:#16a34a;">৳${pf(txAmt(t))}</td>
      </tr>`).join('')}</tbody>
    </table>`;
}





function switchRptTab(tab){
  ['pl','daily','product','aging'].forEach(t=>{
    const panel = document.getElementById('rpt-panel-'+t);
    const btn = document.getElementById('rpt-tab-'+t);
    if(panel) panel.style.display = t===tab?'block':'none';
    if(btn){
      btn.style.color = t===tab?'#16a34a':'#6b7280';
      btn.style.borderBottom = t===tab?'3px solid #16a34a':'none';
      btn.style.fontWeight = t===tab?'700':'600';
    }
  });
  if(tab==='pl') renderPLReport();
  if(tab==='daily'){ document.getElementById('rpt-daily-date').value=new Date().toISOString().split('T')[0]; renderDailySalesReport(); }
  if(tab==='product') renderProductPL();
  if(tab==='aging') renderAgingReport();
}


