function openSalarySlipModal(){
  const empName=prompt('Enter employee name:');
  if(!empName) return;
  const month=prompt('Enter month (YYYY-MM):',new Date().toISOString().substring(0,7));
  if(!month) return;
  printSalarySlipFor(empName,month);
}

function buildSalarySlipModal(emp, lastPay){
  const month = lastPay ? new Date(lastPay.date).toLocaleString('default',{month:'long',year:'numeric'}) : new Date().toLocaleString('default',{month:'long',year:'numeric'});
  const gross = emp.salary||0;
  const advance = (DB.payroll||[]).filter(p=>p.empId===emp.id&&p.type==='Employee Advance'&&(lastPay?p.date.slice(0,7)===lastPay.date.slice(0,7):true)).reduce((s,p)=>s+(p.amount||0),0);
  const net = gross - advance;

  return `<div class="modal" style="max-width:600px;">
    <div class="modal-header" style="background:linear-gradient(135deg,#0f3d26,#16a34a);color:#fff;padding:14px 18px;border-radius:10px 10px 0 0;display:flex;justify-content:space-between;align-items:center;">
      <h3 style="margin:0;font-size:16px;font-weight:800;">🧾 Salary Slip</h3>
      <div style="display:flex;gap:8px;">
        <button data-x-click="printSalarySlip()" style="background:rgba(255,255,255,.2);border:none;color:#fff;padding:5px 12px;border-radius:5px;cursor:pointer;font-size:12px;">🖨️ Print</button>
        <button data-x-click="closeModal('mSalarySlip')" style="background:rgba(255,255,255,.2);border:none;color:#fff;width:28px;height:28px;border-radius:50%;cursor:pointer;font-size:16px;">✕</button>
      </div>
    </div>
    <div id="salary-slip-content" style="padding:20px 24px;font-family:Arial,sans-serif;">
      <!-- Letterhead -->
      <div style="text-align:center;border-bottom:2px solid #0f3d26;padding-bottom:12px;margin-bottom:16px;">
        <div style="font-size:20px;font-weight:900;color:#0f3d26;">🌿 AYAN AGRO ERP International Limited</div>
        <div style="font-size:11px;color:#6b7280;margin-top:2px;">Rice Bran Oil Processing & Trading | Bangladesh</div>
        <div style="font-size:13px;font-weight:700;color:#16a34a;margin-top:6px;letter-spacing:2px;">SALARY SLIP</div>
      </div>
      <!-- Employee Info -->
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:16px;font-size:12px;">
        <div><span style="color:#6b7280;">Employee Name:</span> <strong>${escHTML(emp.name)}</strong></div>
        <div><span style="color:#6b7280;">Month:</span> <strong>${month}</strong></div>
        <div><span style="color:#6b7280;">Designation:</span> <strong>${escHTML(emp.role ||'—')}</strong></div>
        <div><span style="color:#6b7280;">Department:</span> <strong>${escHTML(emp.dept ||'—')}</strong></div>
        <div><span style="color:#6b7280;">Join Date:</span> <strong>${emp.joinDate||'—'}</strong></div>
        <div><span style="color:#6b7280;">Payment Mode:</span> <strong>${lastPay?lastPay.mode:'—'}</strong></div>
      </div>
      <!-- Earnings & Deductions -->
      <table style="width:100%;border-collapse:collapse;font-size:12px;margin-bottom:16px;">
        <thead>
          <tr style="background:#0f3d26;color:#fff;">
            <th style="padding:8px 12px;text-align:left;">Earnings</th>
            <th style="padding:8px 12px;text-align:right;">Amount (৳)</th>
            <th style="padding:8px 12px;text-align:left;">Deductions</th>
            <th style="padding:8px 12px;text-align:right;">Amount (৳)</th>
          </tr>
        </thead>
        <tbody>
          <tr style="border-bottom:1px solid #e5e7eb;">
            <td style="padding:8px 12px;">Basic Salary</td>
            <td style="padding:8px 12px;text-align:right;font-weight:700;">৳${pf(gross)}</td>
            <td style="padding:8px 12px;">Advance Deduction</td>
            <td style="padding:8px 12px;text-align:right;font-weight:700;color:#dc2626;">৳${pf(advance)}</td>
          </tr>
          <tr style="background:#f9fafb;">
            <td style="padding:8px 12px;font-weight:800;color:#0f3d26;">GROSS TOTAL</td>
            <td style="padding:8px 12px;text-align:right;font-weight:800;color:#16a34a;">৳${pf(gross)}</td>
            <td style="padding:8px 12px;font-weight:800;color:#dc2626;">TOTAL DEDUCTIONS</td>
            <td style="padding:8px 12px;text-align:right;font-weight:800;color:#dc2626;">৳${pf(advance)}</td>
          </tr>
        </tbody>
      </table>
      <!-- Net Pay -->
      <div style="background:linear-gradient(135deg,#0f3d26,#16a34a);color:#fff;border-radius:8px;padding:14px;text-align:center;margin-bottom:16px;">
        <div style="font-size:12px;opacity:.8;">NET PAY</div>
        <div style="font-size:28px;font-weight:900;">৳${pf(net)}</div>
        <div style="font-size:11px;opacity:.8;margin-top:4px;">${numberToWords?numberToWords(net)+' Taka Only':'—'}</div>
      </div>
      <!-- Signature -->
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:20px;font-size:11px;text-align:center;">
        <div style="border-top:1px solid #d1d5db;padding-top:6px;color:#6b7280;">Employee Signature</div>
        <div style="border-top:1px solid #d1d5db;padding-top:6px;color:#6b7280;">Authorized Signature</div>
      </div>
      <div style="text-align:center;margin-top:12px;font-size:10px;color:#9ca3af;">Generated by Ayan Agro ERP International Limited | ${new Date().toLocaleDateString()}</div>
    </div>
  </div>`;
}

function printSalarySlip(){
  const content = document.getElementById('salary-slip-content');
  if(!content) return;
  // Print on official company letterhead
  const html = '<style>#print-content table{width:100%;border-collapse:collapse;}#print-content th,#print-content td{padding:8px 12px;border:1px solid #e5e7eb;font-size:12px;}#print-content th{background:#0f3d26;color:#fff;}</style>' + content.innerHTML;
  openPrintModal('Salary Slip', 'SAL-'+Date.now().toString().slice(-6), html, 'HR & Payroll');
}


