function switchStockTab(tab){
  ['movement','alerts','summary'].forEach(t=>{
    const panel = document.getElementById('stk-panel-'+t);
    const btn = document.getElementById('stk-tab-'+t);
    if(panel) panel.style.display = t===tab?'block':'none';
    if(btn){
      btn.style.color = t===tab?'#16a34a':'#6b7280';
      btn.style.borderBottom = t===tab?'3px solid #16a34a':'none';
      btn.style.fontWeight = t===tab?'700':'600';
    }
  });
  if(tab==='movement') renderStockMovement();
  if(tab==='alerts') renderLowStockAlerts();
  if(tab==='summary') renderStockSummary();
}



function renderLowStockAlerts(){
  const threshold = parseFloat(document.getElementById('stk-threshold')?.value)||100;
  const wrap = document.getElementById('stk-alerts-body');
  if(!wrap) return;

  // Calculate stock per product from transactions
  const stockMap = {};
  const inTypes = window.INV_IN_TYPES;   // FIX F: was missing Supplier Purchase / Sales Return
  const outTypes = window.INV_OUT_TYPES; // FIX F: was missing Customer Sale
  (DB.tx||[]).forEach(t=>{
    if(!t.prod||!t.qty) return;
    if(!stockMap[t.prod]) stockMap[t.prod]=0;
    const qty = parseFloat(t.qty)||0;
    if(inTypes.has(normTxType(t.type))) stockMap[t.prod]+=qty;
    if(outTypes.has(normTxType(t.type))) stockMap[t.prod]-=qty;
  });

  // Also include inventory items
  (DB.inventory||[]).forEach(item=>{
    if(!stockMap[item.name]) stockMap[item.name]=0;
    stockMap[item.name]+=(item.qty||0);
  });

  const alerts = Object.entries(stockMap).filter(([,qty])=>qty<=threshold).sort((a,b)=>a[1]-b[1]);

  if(!alerts.length){
    wrap.innerHTML=`<div style="background:#f0fdf4;border:1px solid #bbf7d0;border-radius:10px;padding:20px;text-align:center;color:#16a34a;font-weight:700;">✅ All products are above the threshold of ${threshold} units. No alerts!</div>`;
    return;
  }

  if(wrap) wrap.innerHTML = `
    <div style="background:#fef2f2;border:1px solid #fecaca;border-radius:8px;padding:10px 14px;margin-bottom:12px;font-size:12px;color:#dc2626;font-weight:700;">
      ⚠️ ${alerts.length} product(s) below threshold of ${threshold} units
    </div>
    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:10px;">
      ${alerts.map(([prod,qty])=>{
        const level = qty<=0?'Critical':qty<=threshold*0.3?'Very Low':'Low';
        const bc = qty<=0?'#dc2626':qty<=threshold*0.3?'#ea580c':'#d97706';
        return `<div style="background:#fff;border:2px solid ${bc};border-radius:10px;padding:14px;">
          <div style="font-size:11px;font-weight:700;color:${bc};margin-bottom:4px;">${level.toUpperCase()}</div>
          <div style="font-size:13px;font-weight:800;color:#111827;margin-bottom:6px;">${prod}</div>
          <div style="font-size:22px;font-weight:900;color:${bc};">${pf(qty)}</div>
          <div style="font-size:10px;color:#6b7280;">units remaining</div>
          <div style="margin-top:8px;background:${bc}22;border-radius:4px;height:6px;">
            <div style="background:${bc};height:6px;border-radius:4px;width:${Math.max(0,Math.min(100,(qty/threshold)*100))}%;"></div>
          </div>
        </div>`;
      }).join('')}
    </div>`;
}

function renderStockSummary(){
  const wrap = document.getElementById('stk-summary-body');
  if(!wrap) return;

  const stockMap = {};
  const inTypes = window.INV_IN_TYPES;   // FIX F: was missing Supplier Purchase / Sales Return
  const outTypes = window.INV_OUT_TYPES; // FIX F: was missing Customer Sale
  (DB.tx||[]).forEach(t=>{
    if(!t.prod) return;
    if(!stockMap[t.prod]) stockMap[t.prod]={in:0,out:0,value:0};
    const qty = parseFloat(t.qty)||0;
    if(inTypes.has(normTxType(t.type))){ stockMap[t.prod].in+=qty; stockMap[t.prod].value+=txAmt(t); }
    if(outTypes.has(normTxType(t.type))) stockMap[t.prod].out+=qty;
  });

  const rows = Object.entries(stockMap).map(([prod,d])=>{
    const net = d.in-d.out;
    const bc = net<=0?'#dc2626':net<=100?'#d97706':'#16a34a';
    return `<tr style="border-bottom:1px solid #f3f4f6;">
      <td style="padding:9px 12px;font-weight:700;">${prod}</td>
      <td style="padding:9px 12px;text-align:right;color:#16a34a;font-weight:700;">${pf(d.in)}</td>
      <td style="padding:9px 12px;text-align:right;color:#dc2626;font-weight:700;">${pf(d.out)}</td>
      <td style="padding:9px 12px;text-align:right;font-weight:800;color:${bc};">${pf(net)}</td>
      <td style="padding:9px 12px;text-align:right;">৳${pf(d.value)}</td>
    </tr>`;
  });

  if(wrap) wrap.innerHTML = `<table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
      <th style="padding:10px 12px;text-align:left;">Product</th>
      <th style="padding:10px 12px;text-align:right;">Total In</th>
      <th style="padding:10px 12px;text-align:right;">Total Out</th>
      <th style="padding:10px 12px;text-align:right;">Net Stock</th>
      <th style="padding:10px 12px;text-align:right;">Purchase Value (৳)</th>
    </tr></thead>
    <tbody>${rows.length?rows.join(''):'<tr><td colspan="5" style="text-align:center;padding:20px;color:#9ca3af;">No stock data.</td></tr>'}</tbody>
  </table>`;
}


