var currentUser = null; /* PATCH: var so it IS window.currentUser (cloud layer writes window.currentUser) */
// ── Role helpers ──
function currentRole(){
  return (currentUser?.role||'Viewer').toLowerCase();
}
function isAdminOrOwner(){
  const r=currentRole();
  return r==='admin'||r==='owner'||r==='manager';
}
/* Transaction/order approval authority: restricted to the Admin role only,
   per explicit business rule — Owner, Manager and Staff can all ENTER
   transactions/orders, but only Admin may approve them. (Previously this
   also allowed 'owner'; tightened to admin-only so every approval control
   in the app — approveTx, approveOrder, approveAll, the Pending Approvals
   page, and the auto-approve-on-save logic below — shares one single
   choke point.) */
function isTopApprover(){
  const r=currentRole();
  return r==='admin';
}
window.isTopApprover = isTopApprover;
function canEditOrder(){
  return isAdminOrOwner();
}
function canSubmitOrder(){
  return true; // all logged-in users can submit
}
function canViewBalance(){
  return true; // all can view balance
}
function canMakeBkashPayment(){
  return true; // all can receive bKash
}
function canMakeExpense(){
  return true; // all can log expenses
}
function canMakePurchase(){
  return isAdminOrOwner();
}

// ══════════════════════════════════════════════════════════════
// LOGIN SYSTEM v14 — Enhanced with lockout, caps-lock, remember-me
// ══════════════════════════════════════════════════════════════
let _loginAttempts = 0;
const _MAX_ATTEMPTS = 5;
const _LOCKOUT_MS   = 5 * 60 * 1000;
let   _lockoutUntil = 0;

function lsTogglePass(){
  const f=document.getElementById('login-pass');
  const e=document.getElementById('ls-eye-btn');
  if(!f) return;
  f.type=f.type==='password'?'text':'password';
  if(e) e.textContent=f.type==='password'?'👁':'🙈';
}
function lsCheckCaps(ev){
  const w=document.getElementById('ls-caps-warn');
  if(w) w.style.display=ev.getModifierState&&ev.getModifierState('CapsLock')?'block':'none';
}
function lsShowHint(){
  const h=document.getElementById('ls-hint-box');
  if(h) h.style.display=h.style.display==='none'?'block':'none';
}
function lsSetLoading(on){
  const btn=document.getElementById('ls-login-btn');
  if(!btn) return;
  btn.disabled=on;
  btn.innerHTML=on?'<span class="ls-spinner"></span>Signing in…':'🔐 Sign In';
}
function lsShowError(msg){
  const el=document.getElementById('login-error');
  if(el){
    el.textContent=msg;
    el.style.display='block';
    // LOGIN FIX 2: scroll error into view on mobile
    try{ el.scrollIntoView({behavior:'smooth',block:'nearest'}); }catch(e){}
  }
}
function lsHideError(){
  const el=document.getElementById('login-error');
  if(el) el.style.display='none';
}

/* FIX (2026-08-27, final pass): the login screen's "Create an account" link
   called erpSignUp() — but that name only exists inside a completely
   separate, permanently-disabled cloud/Supabase login module (it early-
   returns unless window.ERP_CONFIG.USE_CLOUD===true, which is never set
   anywhere in this app — see the near-identical dead-end already fixed for
   the 2FA panel's old "Change my password" button). So every real visitor
   who clicked "Create an account" got nothing: no error, no signup, just a
   dead link with erpSignUp undefined. This app doesn't actually have
   self-service signup — accounts are created by an Admin/Owner in User
   Management (by design, per the permission fix earlier this session) — so
   the honest fix is to say that plainly instead of silently doing nothing. */
function erpSignUp(){
  lsShowError('This system doesn\'t support creating your own account. Ask your Admin or Owner to create one for you from User Management, then sign in above with those details.');
}
window.erpSignUp = erpSignUp;


function showLoginScreen(){
  // Server-backed auth: always show the login screen when there is no session.
  const ls=document.getElementById('login-screen');
  if(ls) ls.style.display='flex';
  const sidebar=document.querySelector('.sidebar');
  const topbar=document.querySelector('.topbar');
  const main=document.querySelector('.main');
  if(sidebar) sidebar.style.display='none';
  if(topbar)  topbar.style.display='none';
  if(main)    main.style.display='none';
  const savedUser=localStorage.getItem('ayan_last_user');
  if(savedUser){
    const uf=document.getElementById('login-user');
    if(uf){uf.value=savedUser;const rb=document.getElementById('ls-remember');if(rb)rb.checked=true;}
  }
}

function showApp(){
  const ls=document.getElementById('login-screen');
  if(ls) ls.style.display='none';
  const sidebar=document.querySelector('.sidebar');
  const topbar=document.querySelector('.topbar');
  const main=document.querySelector('.main');
  if(sidebar) sidebar.style.display='';
  if(topbar)  topbar.style.display='';
  if(main)    main.style.display='';
  const userEl=document.getElementById('topbar-user-display')||{textContent:'',style:{}}||{textContent:'',style:{}};
  if(userEl&&currentUser){
    const ico={Admin:'👑',Manager:'💼',Operator:'⚙️',Viewer:'👁'};
    userEl.textContent=(ico[currentUser.role]||'👤')+' '+currentUser.name+' ('+currentUser.role+')';
  }
  // Route to appropriate dashboard based on role
  const userRole=(currentUser?.role||'').toLowerCase();
  if(userRole==='staff'||userRole==='operator') nav('staffdash');
  else nav('dashboard');
  updateStaffDashNavLabel();
}


function updateStaffDashNavLabel(){
  const label=(currentUser?.name||'Staff')+'\'s Dashboard';
  document.querySelectorAll('.nav-item').forEach(el=>{
    const onclick=el.getAttribute('data-x-click')||el.getAttribute('onclick')||'';
    if(onclick.includes("nav('staffdash')")){
      const span=el.querySelector('span:nth-child(2)');
      const tip=el.querySelector('.nav-tooltip');
      if(span) span.textContent=label;
      if(tip) tip.textContent=label;
    }
  });
}


function hasPermission(action){
  if(!currentUser) return false;
  if(currentUser.permissions==='all') return true;
  if(typeof currentUser.permissions==='object') return currentUser.permissions[action]===true;
  return (currentUser.permissions||'').split(',').includes(action);
}

// ══════════════════════════════════════════════════════════════
// USER MANAGEMENT v14 — Full CRUD + Smart Search + Filter + Print
// ══════════════════════════════════════════════════════════════
const UM_MODULES=['dashboard','transactions','reports','parties','inventory','finance','payroll','admin','export','import','communications','tender','assets','banks'];
const UM_ACTIONS=['view','add','edit','delete','print','approve','export'];
/* FIX (two roles the app used but never defined): the menu access layer and
   the cloud sign-in both recognise 'Owner' and 'Staff', but this table — the
   one that decides what a user may DO once inside a screen — listed neither.
   An Owner or a Staff user therefore got an empty permission set and was
   refused every add / edit / delete, while their menu looked normal. */
const UM_ROLE_PERMS={
  Owner:    {modules:UM_MODULES,actions:UM_ACTIONS},
  Admin:    {modules:UM_MODULES,actions:UM_ACTIONS},
  Manager:  {modules:['dashboard','transactions','reports','parties','inventory','finance','tender','assets','banks'],actions:['view','add','edit','print','export']},
  Staff:    {modules:['dashboard','transactions','parties','inventory'],actions:['view','add','edit','print']},
  Operator: {modules:['dashboard','transactions','parties','inventory'],actions:['view','add','edit']},
  Viewer:   {modules:['dashboard','reports'],actions:['view']}
};
/* FIX: declared with `const`, so it never appeared on `window` — every later
   fix-pack that looked it up as window.UM_ROLE_PERMS found nothing and quietly
   fell back to full access. */
try{ window.UM_ROLE_PERMS = UM_ROLE_PERMS; window.UM_MODULES = UM_MODULES; window.UM_ACTIONS = UM_ACTIONS; }catch(e){}
let _umEditId=null,_umPage=1,_umSel=new Set();

function renderUserManagement(){
  umRender();
}


/* FIX (editing a user could not be saved at all): this filled the form and
   then called umOpenModal() with no argument — and umOpenModal(id) is what
   sets _umEditId. With it left null, Save treated a plain edit as a brand new
   account: it demanded a password, and if one was typed it then refused with
   "Username already exists". There was no way to change anyone's role, phone
   or status once created. Opening the modal now happens FIRST (it rebuilds
   the permission grids and clears the fields), and the record is filled in
   after, so nothing that is filled gets wiped a moment later. */
function editUser(id){
  const u=(DB.users||[]).find(u=>u.id===id);
  if(!u) return;
  umOpenModal(id);
  const keyMap={'um-f-name':'name','um-f-username':'username','um-f-email':'email',
    'um-f-role':'role','um-f-phone':'phone','um-f-dept':'dept','um-f-status':'status',
    'um-f-empid':'empid','um-f-notes':'notes'};
  Object.keys(keyMap).forEach(fid=>{
    const el=document.getElementById(fid);
    if(el) el.value=u[keyMap[fid]]||'';
  });
  /* Show the rights the user actually has. Without this the permission tab
     came up blank and saving wrote those blanks over their real access. */
  const p=u.permissions, full=(p==='all');
  const rp=UM_ROLE_PERMS[u.role]||{};
  UM_MODULES.forEach(m=>{
    const el=document.getElementById('ump-'+m); if(!el) return;
    el.checked = full ? true : (p&&typeof p==='object' ? !!p[m] : (rp.modules||[]).indexOf(m)>=0);
  });
  UM_ACTIONS.forEach(a=>{
    const el=document.getElementById('upa-'+a); if(!el) return;
    el.checked = full ? true : (p&&typeof p==='object' ? !!p[a] : (rp.actions||[]).indexOf(a)>=0);
  });
  const cp=document.getElementById('um-f-can-print'); if(cp) cp.checked=u.canPrint!==false;
  const to=document.getElementById('um-f-timeout'); if(to) to.value=u.timeout||60;
  const fp=document.getElementById('um-f-force-pwd'); if(fp) fp.checked=!!u.forcePwd;
  ['um-f-password','um-f-confirm'].forEach(i=>{const e=document.getElementById(i); if(e) e.value='';});
  const eid=document.getElementById('um-f-edit-id'); if(eid) eid.value=id;
  const title=document.querySelector('#um-modal .modal-title');
  if(title) title.innerHTML='\u270f\ufe0f Edit User <span class="modal-close" data-x-click="umCloseModal()">\u2715</span>';
  const hint=document.getElementById('um-pwd-hint');
  if(hint) hint.textContent='Leave the password boxes empty to keep the current password.';
}

function umRender(){
  _umRenderStats();
  const q=(document.getElementById('um-search')?.value||'').toLowerCase();
  const roleF=document.getElementById('um-role-filter')?.value||'';
  const statusF=document.getElementById('um-status-filter')?.value||'';
  const users=DB.users||[];
  const filtered=users.filter(u=>{
    const mq=!q||u.name?.toLowerCase().includes(q)||u.email?.toLowerCase().includes(q)||u.username?.toLowerCase().includes(q);
    const mr=!roleF||u.role===roleF;
    const ms=!statusF||u.status===statusF;
    return mq&&mr&&ms;
  });
  const badge=document.getElementById('um-user-count-badge');
  if(badge) badge.textContent=(q||roleF||statusF)?`${filtered.length} of ${users.length}`:`${users.length}`;
  const PAGE=8;
  const pages=Math.ceil(filtered.length/PAGE)||1;
  if(_umPage>pages)_umPage=pages;
  const slice=filtered.slice((_umPage-1)*PAGE,_umPage*PAGE);
  const wrap=document.getElementById('um-list-wrap');
  if(!wrap)return;
  const roleColor={Admin:'#dc2626',Manager:'#7c3aed',Operator:'#2563eb',Viewer:'#6b7280'};
  const avatarBg=['#7c3aed','#1d4ed8','#16a34a','#dc2626','#d97706','#0891b2'];
  if(!filtered.length){
    wrap.innerHTML='<div style="text-align:center;padding:40px;color:#9ca3af;">No users found.</div>';
    _umRenderPagination(0);
    return;
  }
  wrap.innerHTML=`<div style="font-size:11px;color:#6b7280;margin-bottom:8px;">Showing ${(_umPage-1)*PAGE+1}–${Math.min(_umPage*PAGE,filtered.length)} of ${filtered.length} users</div>
  <table class="tbl"><thead><tr><th>User</th><th>Username</th><th>Role</th><th>Department</th><th>Status</th><th>Actions</th></tr></thead>
  <tbody>${slice.map((u)=>{
    const realIdx=users.indexOf(u);
    const initials=(u.name||'U').split(' ').map(n=>n[0]).join('').substring(0,2).toUpperCase();
    const bg=avatarBg[realIdx%avatarBg.length];
    const rc=roleColor[u.role]||'#6b7280';
    return `<tr>
      <td><div style="display:flex;align-items:center;gap:10px;">
        <div style="width:34px;height:34px;border-radius:50%;background:${bg};display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:800;color:#fff;flex-shrink:0;">${initials}</div>
        <div><div style="font-weight:700;">${escHTML(u.name||'—')}</div><div style="font-size:10.5px;color:#6b7280;">${escHTML(u.email||'—')}</div></div>
      </div></td>
      <td><code style="background:#f3f4f6;padding:2px 6px;border-radius:4px;font-size:11px;">${u.username||'—'}</code></td>
      <td><span style="padding:3px 10px;border-radius:10px;font-size:10.5px;font-weight:700;background:${rc}22;color:${rc};">${u.role||'Viewer'}</span></td>
      <td>${u.dept||u.department||'—'}</td>
      <td><span style="padding:3px 10px;border-radius:10px;font-size:10.5px;font-weight:700;background:${u.status==='Active'?'#dcfce7':'#fee2e2'};color:${u.status==='Active'?'#16a34a':'#dc2626'};">${u.status||'Active'}</span></td>
      <td style="display:flex;gap:6px;flex-wrap:wrap;">
        <button class="btn" style="padding:4px 10px;font-size:11px;background:#7c3aed;color:#fff;" data-x-click="editUser(${realIdx})">✏️</button>
        <button class="btn" style="padding:4px 10px;font-size:11px;background:${u.status==='Active'?'#fef9c3':'#dcfce7'};color:${u.status==='Active'?'#b45309':'#16a34a'};" data-x-click="toggleUserStatus(${realIdx})">${u.status==='Active'?'🔒':'🔓'}</button>
        <button class="btn" style="padding:4px 10px;font-size:11px;background:#fee2e2;color:#dc2626;" data-x-click="deleteUser(${realIdx})">🗑️</button>
      </td>
    </tr>`;
  }).join('')}</tbody></table>`;
  _umRenderPagination(pages);
}

function _umFiltered(){
  const q=(document.getElementById('um-search')?.value||'').toLowerCase();
  const role=document.getElementById('um-filter-role')?.value||'';
  const stat=document.getElementById('um-filter-status')?.value||'';
  const dept=document.getElementById('um-filter-dept')?.value||'';
  const sort=document.getElementById('um-sort')?.value||'name';
  let users=(DB.users||[]).filter(u=>{
    const text=[u.name,u.username,u.email,u.phone,u.dept,u.empid,u.notes].join(' ').toLowerCase();
    return(!q||text.includes(q))&&(!role||u.role===role)&&(!stat||u.status===stat)&&(!dept||u.dept===dept);
  });
  if(sort==='name')users.sort((a,b)=>(a.name||'').localeCompare(b.name||''));
  else if(sort==='name-desc')users.sort((a,b)=>(b.name||'').localeCompare(a.name||''));
  else if(sort==='role')users.sort((a,b)=>(a.role||'').localeCompare(b.role||''));
  else if(sort==='recent')users.sort((a,b)=>new Date(b.createdAt||0)-new Date(a.createdAt||0));
  else if(sort==='login')users.sort((a,b)=>new Date(b.lastLogin||0)-new Date(a.lastLogin||0));
  return users;
}

function _umRenderStats(){
  const users=DB.users||[];
  const statsEl=document.getElementById('um-stats');
  if(!statsEl)return;
  const active=users.filter(u=>u.status==='Active').length;
  const admins=users.filter(u=>u.role==='Admin').length;
  const operators=users.filter(u=>u.role==='Operator').length;
  if(statsEl) statsEl.innerHTML=[
    {label:'Total Users',val:users.length,color:'#7c3aed',icon:'👥'},
    {label:'Active',val:active,color:'#16a34a',icon:'✅'},
    {label:'Admins',val:admins,color:'#dc2626',icon:'👑'},
    {label:'Operators',val:operators,color:'#2563eb',icon:'⚙️'}
  ].map(s=>`<div style="background:#fff;border:2px solid ${s.color}22;border-radius:10px;padding:14px;text-align:center;">
    <div style="font-size:20px;">${s.icon}</div>
    <div style="font-size:22px;font-weight:900;color:${s.color};margin-top:4px;">${s.val}</div>
    <div style="font-size:10px;color:#6b7280;font-weight:700;">${escHTML(s.label)}</div>
  </div>`).join('');
}

function _umRenderPagination(pages){
  const el=document.getElementById('um-pagination');
  if(!el)return;
  if(pages<=1){el.innerHTML='';return;}
  let html='<div style="display:flex;gap:6px;align-items:center;justify-content:center;margin-top:14px;flex-wrap:wrap;">';
  if(_umPage>1) html+=`<button class="btn" style="padding:5px 12px;font-size:12px;background:#f3f4f6;color:#374151;" data-x-click="_umPage=${_umPage-1};umRender()">‹ Prev</button>`;
  for(let i=1;i<=pages;i++){
    html+=`<button class="btn" style="padding:5px 12px;font-size:12px;background:${i===_umPage?'#7c3aed':'#f3f4f6'};color:${i===_umPage?'#fff':'#374151'};" data-x-click="_umPage=${i};umRender()">${i}</button>`;
  }
  if(_umPage<pages) html+=`<button class="btn" style="padding:5px 12px;font-size:12px;background:#f3f4f6;color:#374151;" data-x-click="_umPage=${_umPage+1};umRender()">Next ›</button>`;
  html+='</div>';
  el.innerHTML=html;
}
function umGoPage(p){_umPage=p;umRender();}

function _umRoleColor(role){return {Admin:'#dc2626',Manager:'#7c3aed',Operator:'#2563eb',Viewer:'#6b7280'}[role]||'#9ca3af';}
function _umTimeAgo(iso){
  if(!iso) return 'Never';
  const diff=Date.now()-new Date(iso).getTime();
  const mins=Math.floor(diff/60000),hrs=Math.floor(diff/3600000),days=Math.floor(diff/86400000);
  if(diff<60000)return '<span style="color:#16a34a;">Just now</span>';
  if(mins<60)return '<span style="color:#2563eb;">'+mins+'m ago</span>';
  if(hrs<24)return hrs+'h ago';
  if(days<7)return days+'d ago';
  return new Date(iso).toLocaleDateString('en-BD');
}

function umClearFilters(){
  ['um-search','um-filter-role','um-filter-status','um-filter-dept'].forEach(id=>{const el=document.getElementById(id);if(el)el.value='';});
  const s=document.getElementById('um-sort');if(s)s.value='name';
  _umPage=1;umRender();
}

function umToggleAll(cb){
  const users=_umFiltered();
  if(cb.checked)users.forEach(u=>_umSel.add(u.id));else _umSel.clear();
  umRender();
}
function umToggleSel(id,cb){
  if(cb.checked)_umSel.add(id);else _umSel.delete(id);
  const si=document.getElementById('um-selected-info'),bb=document.getElementById('um-bulk-actions');
  if(si)si.textContent=_umSel.size>0?_umSel.size+' selected':'';
  if(bb)bb.style.display=_umSel.size>0?'flex':'none';
}
function umBulkStatus(status){
  if(!_umSel.size){toast('No users selected','w');return;}
  (DB.users||[]).forEach(u=>{if(_umSel.has(u.id))u.status=status;});
  saveDB();toast('✅ '+_umSel.size+' users set to '+status,'s');_umSel.clear();umRender();
}
async function umBulkDelete(){
  if(!_umSel.size){toast('No users selected','w');return;}
  if(!await __confirm('Delete '+_umSel.size+' selected users?'))return;
  DB.users=(DB.users||[]).filter(u=>!_umSel.has(u.id));
  saveDB();toast('🗑️ '+_umSel.size+' users deleted','s');_umSel.clear();umRender();
}

/* FIX (the 2FA panel's "Change my password" button did nothing): it called
   erpChangePassword(), which is part of a completely separate, currently
   INACTIVE cloud-login system (Supabase) — gated behind ERP_CONFIG.USE_CLOUD,
   which is never turned on anywhere in this app. Clicking the button called
   sb.auth.updateUser() on a null client and silently failed (or threw a raw
   console error), leaving a real user with no way to change their own
   password from this screen. This app's actual, working password-change
   flow already exists — the same User Management "Edit User" form an admin
   uses, which validates and saves through the real save pipeline (saveDB())
   to this server. This routes the button there instead, pre-filled to the
   signed-in user's own account, so it now genuinely changes something. */
function ayanChangeMyPassword(){
  const me = (typeof currentUser!=='undefined' && currentUser) ? currentUser : null;
  const rec = me ? (DB.users||[]).find(u=>u.id===me.id || u.username===me.username) : null;
  if(!rec){
    toast('Your account isn\'t in User Management yet — ask an administrator to set or reset your password there.','e');
    return;
  }
  editUser(rec.id);
  try{ umSwitchTab('security'); }catch(e){}
  toast('Enter a new password below and save.','i');
}
window.ayanChangeMyPassword = ayanChangeMyPassword;

function umOpenModal(id){
  _umEditId=id||null;
  const modal=document.getElementById('um-modal');if(!modal)return;
  const mpg=document.getElementById('um-perms-grid'),apg=document.getElementById('um-action-perms-grid');
  if(mpg)mpg.innerHTML=UM_MODULES.map(m=>'<label class="um-perm-item"><input type="checkbox" id="ump-'+m+'" style="accent-color:#16a34a;"><span class="um-perm-label">📦 '+m.charAt(0).toUpperCase()+m.slice(1)+'</span></label>').join('');
  if(apg){const icons={view:'👁 View',add:'➕ Add',edit:'✏️ Edit',delete:'🗑️ Delete',print:'🖨️ Print',approve:'✅ Approve',export:'📤 Export'};apg.innerHTML=UM_ACTIONS.map(a=>'<label class="um-perm-item"><input type="checkbox" id="upa-'+a+'" style="accent-color:#16a34a;"><span class="um-perm-label">'+(icons[a]||a)+'</span></label>').join('');}
  if(id){
    const u=(DB.users||[]).find(x=>x.id===id);if(!u)return;
    document.getElementById('um-modal-title').textContent='✏️ Edit User: '+u.name;
    const flds={name:u.name,username:u.username,empid:u.empid||'',dept:u.dept||'',email:u.email||'',phone:u.phone||'',notes:u.notes||''};
    Object.keys(flds).forEach(k=>{const el=document.getElementById('um-f-'+k);if(el)el.value=flds[k];});
    const r=document.getElementById('um-f-role');if(r)r.value=u.role||'';
    const st=document.getElementById('um-f-status');if(st)st.value=u.status||'Active';
    ['um-f-password','um-f-confirm'].forEach(id2=>{const el=document.getElementById(id2);if(el)el.value='';});
    const pin=document.getElementById('um-f-pin');if(pin)pin.value=u.pin||'';
    const to=document.getElementById('um-f-timeout');if(to)to.value=u.timeout||60;
    const fp=document.getElementById('um-f-force-pwd');if(fp)fp.checked=u.forcePwd||false;
    const cp=document.getElementById('um-f-can-print');if(cp)cp.checked=u.canPrint!==false;
    const perms=u.permissions||{};
    if(perms==='all'){UM_MODULES.forEach(m=>{const el=document.getElementById('ump-'+m);if(el)el.checked=true;});UM_ACTIONS.forEach(a=>{const el=document.getElementById('upa-'+a);if(el)el.checked=true;});}
    else if(typeof perms==='object'){Object.keys(perms).forEach(k=>{const el=document.getElementById('ump-'+k)||document.getElementById('upa-'+k);if(el)el.checked=!!perms[k];});}
    else{const pa=(perms||'').split(',');UM_ACTIONS.forEach(a=>{const el=document.getElementById('upa-'+a);if(el)el.checked=pa.includes(a);});}
  } else {
    document.getElementById('um-modal-title').textContent='➕ Add New User';
    ['name','username','empid','email','phone','notes','password','confirm','pin'].forEach(k=>{const el=document.getElementById('um-f-'+k);if(el)el.value='';});
    const r=document.getElementById('um-f-role');if(r)r.value='';
    const d=document.getElementById('um-f-dept');if(d)d.value='';
    const st=document.getElementById('um-f-status');if(st)st.value='Active';
    const to=document.getElementById('um-f-timeout');if(to)to.value=60;
    const fp=document.getElementById('um-f-force-pwd');if(fp)fp.checked=false;
    const cp=document.getElementById('um-f-can-print');if(cp)cp.checked=true;
  }
  umSwitchTab('info');
  modal.classList.add('open');
}
function umCloseModal(){const m=document.getElementById('um-modal');if(m)m.classList.remove('open');_umEditId=null;}
/* FIX (Permissions & Security tabs in the Add/Edit User modal did nothing):
   this function is shared by two completely different tab strips — the
   outer User Management page (tabs: users/roles/activity/settings) and the
   Add/Edit User modal (tabs: info/perms/security) — but only ever knew
   about the first group. Clicking "Permissions" or "Security" inside the
   modal called umSwitchTab('perms')/umSwitchTab('security'), neither of
   which is in that hardcoded list, so nothing happened: both panels stayed
   at their default display:none forever. Concretely, that meant no admin
   could ever reach the Password field to set one on a NEW user (even
   though saving one without a password is refused), or view/edit anyone's
   module permissions, through this modal's UI — the tabs were purely
   decorative. Toggling whichever group the requested tab actually belongs
   to (instead of one fixed list) fixes both tab strips with the one
   function, since their ids never overlap. */
function umSwitchTab(tab){
  const groups=[['users','roles','activity','settings'],['info','perms','security']];
  const group=groups.find(g=>g.includes(tab))||[tab];
  group.forEach(t=>{
    const p=document.getElementById('um-panel-'+t);
    const b=document.getElementById('um-tab-'+t);
    if(p) p.style.display=t===tab?'block':'none';
    if(b) b.classList.toggle('active',t===tab);
  });
  if(tab==='users') umRender();
  if(tab==='roles') renderUserRoles();
  /* 'activity' tab removed 2026-08-27 — it had no um-panel-activity/um-tab-activity
     markup and no button ever selected it (see the Activity Log removal note
     near the old renderActivityLog()); calling the now-removed function here
     was dead code left over from the same duplicate. */
}

function umRoleAutofill(){
  const role=document.getElementById('um-f-role')?.value||'';if(!role)return;
  const rp=UM_ROLE_PERMS[role]||{};
  UM_MODULES.forEach(m=>{const el=document.getElementById('ump-'+m);if(el)el.checked=(rp.modules||[]).includes(m);});
  UM_ACTIONS.forEach(a=>{const el=document.getElementById('upa-'+a);if(el)el.checked=(rp.actions||[]).includes(a);});
}

function umCheckStrength(){
  const pwd=document.getElementById('um-f-password')?.value||'';
  const bar=document.getElementById('um-pwd-strength-bar');
  const lbl=document.getElementById('um-pwd-strength-label');
  let score=0;
  if(pwd.length>=6)score++;if(pwd.length>=10)score++;if(/[A-Z]/.test(pwd))score++;if(/[0-9]/.test(pwd))score++;if(/[^A-Za-z0-9]/.test(pwd))score++;
  const lv=[{c:'#e5e7eb',w:'0%',t:''},{c:'#ef4444',w:'25%',t:'Weak'},{c:'#f59e0b',w:'50%',t:'Fair'},{c:'#3b82f6',w:'75%',t:'Good'},{c:'#16a34a',w:'90%',t:'Strong'},{c:'#15803d',w:'100%',t:'Very Strong'}][Math.min(score,5)];
  if(bar){bar.style.width=lv.w;bar.style.background=lv.c;}
  if(lbl){lbl.textContent=lv.t;lbl.style.color=lv.c;}
}
function umCheckMatch(){
  const p=document.getElementById('um-f-password')?.value||'',c=document.getElementById('um-f-confirm')?.value||'',ml=document.getElementById('um-pwd-match-label');
  if(!c){if(ml)ml.textContent='';return;}
  if(ml){ml.textContent=p===c?'✅ Passwords match':'❌ Passwords do not match';ml.style.color=p===c?'#16a34a':'#dc2626';}
}
function umTogglePwd(fieldId,btn){
  const f=document.getElementById(fieldId);if(!f)return;
  f.type=f.type==='password'?'text':'password';
  btn.textContent=f.type==='password'?'👁':'🙈';
}

function umSaveUser(printAfter){
  /* FIX (2026-08-25, same access-control gap as renderUserRoles()/deleteUser
     below): unguarded, any logged-in account could create a brand-new user
     with the Admin or Owner role — full permissions, per line ~4208 — or
     rewrite an existing user's role/permissions, entirely unrestricted. */
  if(typeof isAdminOrOwner!=='function'||!isAdminOrOwner()){toast('Only Admin/Owner can create or edit user accounts','e');return;}
  const gv=id=>document.getElementById(id)?.value?.trim()||'';
  const gc=id=>document.getElementById(id)?.checked||false;
  const name=gv('um-f-name'),username=gv('um-f-username'),role=gv('um-f-role');
  const password=document.getElementById('um-f-password')?.value||'';
  const confirm2=document.getElementById('um-f-confirm')?.value||'';
  if(!name||!username){toast('Name and username are required.','e');umSwitchTab('info');return;}
  if(!role){toast('Please select a role.','e');umSwitchTab('info');return;}
  if((DB.users||[]).some(u=>u.username===username&&u.id!==_umEditId)){toast('Username already exists.','e');return;}
  if(!_umEditId){
    if(!password){toast('Password is required.','e');umSwitchTab('security');return;}
    if(password.length<6){toast('Password must be at least 6 characters.','e');umSwitchTab('security');return;}
    if(password!==confirm2){toast('Passwords do not match.','e');umSwitchTab('security');return;}
  } else if(password){
    if(password.length<6){toast('Password must be at least 6 chars.','e');umSwitchTab('security');return;}
    if(password!==confirm2){toast('Passwords do not match.','e');umSwitchTab('security');return;}
  }
  const perms={};
  UM_MODULES.forEach(m=>{perms[m]=document.getElementById('ump-'+m)?.checked||false;});
  UM_ACTIONS.forEach(a=>{perms[a]=document.getElementById('upa-'+a)?.checked||false;});
  /* FIX: Owner is the most senior role in this app — the menu layer treats it
     as unrestricted — but only 'Admin' was given full rights here, so an Owner
     created on this screen came out with whatever boxes happened to be ticked
     and was refused actions their own role is meant to allow. */
  if(role==='Admin'||role==='Owner')Object.keys(perms).forEach(k=>perms[k]=true);
  if(!DB.users)DB.users=[];
  if(_umEditId){
    const u=(DB.users||[]).find(x=>x.id===_umEditId);if(!u){toast('User not found.','e');return;}
    Object.assign(u,{name,username,role,empid:gv('um-f-empid'),dept:gv('um-f-dept'),email:gv('um-f-email'),phone:gv('um-f-phone'),status:gv('um-f-status')||'Active',notes:gv('um-f-notes'),pin:gv('um-f-pin'),timeout:parseInt(document.getElementById('um-f-timeout')?.value||60),forcePwd:gc('um-f-force-pwd'),canPrint:gc('um-f-can-print'),permissions:(role==='Admin'||role==='Owner')?'all':perms});
    /* FIX (an edit could silently strip a user's access): the permission
       checkboxes are not filled in when a user is opened for editing, so
       saving after changing a phone number rewrote their rights from whatever
       the boxes happened to show — usually nothing. Opening a user now ticks
       the boxes to match what they actually have (see editUser), and a role
       that carries full access keeps it. */
    if(role==='Admin'||role==='Owner') u.pages='all'; 
    if(password)u.password=password;
    if(typeof addAuditEntry==='function')addAuditEntry('UPDATE','Users','Edited: '+name);
    toast('✅ User updated: '+name,'s');
    if(currentUser&&currentUser.id===_umEditId){currentUser=u;sessionStorage.setItem('ayan_session',JSON.stringify(u));}
  } else {
    const newUser={id:newId(),name,username,password,role,empid:gv('um-f-empid'),dept:gv('um-f-dept'),email:gv('um-f-email'),phone:gv('um-f-phone'),status:gv('um-f-status')||'Active',notes:gv('um-f-notes'),pin:gv('um-f-pin'),timeout:parseInt(document.getElementById('um-f-timeout')?.value||60),forcePwd:gc('um-f-force-pwd'),canPrint:gc('um-f-can-print'),permissions:(role==='Admin'||role==='Owner')?'all':perms,pages:(role==='Admin'||role==='Owner')?'all':undefined,createdAt:new Date().toISOString(),lastLogin:null,loginCount:0};
    DB.users.push(newUser);
    if(typeof addAuditEntry==='function')addAuditEntry('CREATE','Users','Added: '+name+' ('+role+')');
    toast('✅ User created: '+name,'s');
    if(printAfter){saveDB();umCloseModal();umPrintProfile(newUser.id);return;}
  }
  saveDB();umCloseModal();umRender();
}
function umSaveAndPrint(){umSaveUser(true);}

async function umDelete(id){
  const u=(DB.users||[]).find(x=>x.id===id);if(!u)return;
  if(currentUser&&currentUser.id===id){toast('Cannot delete your own account.', 'e');return;}
  /* FIX: unguarded, any logged-in account could delete any OTHER account
     (including the real Admin's) — the only check was against deleting
     yourself. */
  if(typeof isAdminOrOwner!=='function'||!isAdminOrOwner()){toast('Only Admin/Owner can delete user accounts','e');return;}
  if(!await __confirm('Delete user "'+u.name+'"?\n\nThis cannot be undone.'))return;
  DB.users=(DB.users||[]).filter(x=>x.id!==id);
  saveDB();if(typeof addAuditEntry==='function')addAuditEntry('DELETE','Users','Deleted: '+u.name);
  toast('🗑️ User deleted: '+u.name,'s');umRender();
}

function umToggleStatus(id){
  const u=(DB.users||[]).find(x=>x.id===id);if(!u)return;
  if(currentUser&&currentUser.id===id){toast('Cannot change your own status.', 'e');return;}
  u.status={Active:'Inactive',Inactive:'Active',Suspended:'Active'}[u.status]||'Active';
  saveDB();toast('Status → '+u.status+' for '+u.name,'s');umRender();
}

function umResetPwd(id){
  const u=(DB.users||[]).find(x=>x.id===id);if(!u)return;
  const np=prompt('Reset password for "'+u.name+'"\n\nEnter new password (min 6 chars):');
  if(!np)return;
  if(np.length<6){toast('Password too short.','e');return;}
  u.password=np;u.forcePwd=true;saveDB();
  if(typeof addAuditEntry==='function')addAuditEntry('SECURITY','Users','Password reset: '+u.name);
  toast('🔑 Password reset for '+u.name,'s');
}

function umView(id){
  const u=(DB.users||[]).find(x=>x.id===id);if(!u)return;
  const modal=document.getElementById('um-view-modal'),body=document.getElementById('um-view-body');
  if(!modal||!body)return;
  const rc3=_umRoleColor(u.role);
  const perms=u.permissions==='all'?'Full Access (All Modules)':typeof u.permissions==='object'?Object.keys(u.permissions).filter(k=>u.permissions[k]).join(', '):u.permissions||'—';
  const init=(u.name||'?')[0].toUpperCase();
  body.innerHTML='<div style="text-align:center;padding:20px 0 10px;">'
    +'<div style="width:72px;height:72px;border-radius:50%;background:'+rc3+';color:#fff;display:flex;align-items:center;justify-content:center;font-size:30px;font-weight:900;margin:0 auto 12px;">'+init+'</div>'
    +'<div style="font-size:18px;font-weight:900;color:#0f3d26;">'+u.name+'</div>'
    +'<div style="font-size:12px;color:#6b7280;">@'+u.username+(u.empid?' · '+u.empid:'')+'</div>'
    +'<span style="display:inline-block;margin-top:6px;padding:4px 14px;border-radius:20px;font-size:11px;font-weight:800;background:'+rc3+'22;color:'+rc3+';">'+u.role+'</span>'
    +'<span style="display:inline-block;margin-top:6px;margin-left:6px;padding:4px 14px;border-radius:20px;font-size:11px;font-weight:800;background:'+(u.status==='Active'?'#dcfce7':'#fee2e2')+';color:'+(u.status==='Active'?'#16a34a':'#dc2626')+';">'+(u.status||'Active')+'</span></div>'
    +'<table style="width:100%;font-size:12px;border-collapse:collapse;">'
    +[['🏢 Department',u.dept||'—'],['✉️ Email',u.email||'—'],['📞 Phone',u.phone||'—'],['🔑 Permissions',perms],['🕐 Last Login',u.lastLogin?new Date(u.lastLogin).toLocaleString('en-BD'):'Never'],['📊 Total Logins',u.loginCount||0],['📅 Joined',u.createdAt?new Date(u.createdAt).toLocaleDateString('en-BD'):'—'],['🖨️ Can Print',u.canPrint!==false?'Yes':'No'],['📝 Notes',u.notes||'—']].map(([l,v])=>'<tr style="border-bottom:1px solid #f3f4f6;"><td style="padding:8px 12px;font-weight:700;color:#374151;width:40%;">'+l+'</td><td style="padding:8px 12px;color:#6b7280;">'+v+'</td></tr>').join('')
    +'</table>';
  document.getElementById('um-view-edit-btn').onclick=()=>{modal.classList.remove('open');umOpenModal(id);};
  document.getElementById('um-view-print-btn').onclick=()=>umPrintProfile(id);
  modal.classList.add('open');
}

function umPrintProfile(id){
  const u=(DB.users||[]).find(x=>x.id===id);if(!u)return;
  const rc4=_umRoleColor(u.role);
  const perms=u.permissions==='all'?'Full Access — All Modules & Actions':
    typeof u.permissions==='object'?
      'Modules: '+UM_MODULES.filter(m=>u.permissions[m]).join(', ')+'\nActions: '+UM_ACTIONS.filter(a=>u.permissions[a]).join(', ')
    :u.permissions||'—';
  const init=(u.name||'?')[0].toUpperCase();
  const html='<div style="display:flex;gap:20px;align-items:flex-start;">'
    +'<div style="width:80px;height:80px;border-radius:50%;background:'+rc4+';color:#fff;display:flex;align-items:center;justify-content:center;font-size:36px;font-weight:900;flex-shrink:0;">'+init+'</div>'
    +'<div><div style="font-size:20px;font-weight:900;color:#0f3d26;">'+u.name+'</div>'
    +'<div style="font-size:13px;color:#6b7280;margin-top:2px;">@'+u.username+(u.empid?' &nbsp;|&nbsp; Employee ID: '+u.empid:'')+'</div>'
    +'<div style="margin-top:8px;display:flex;gap:8px;flex-wrap:wrap;">'
    +'<span style="padding:4px 14px;border-radius:20px;font-size:11px;font-weight:800;background:'+rc4+'22;color:'+rc4+';border:1px solid '+rc4+'44;">'+u.role+'</span>'
    +'<span style="padding:4px 14px;border-radius:20px;font-size:11px;font-weight:800;background:'+(u.status==='Active'?'#dcfce7':'#fee2e2')+';color:'+(u.status==='Active'?'#16a34a':'#dc2626')+';">'+(u.status||'Active')+'</span>'
    +'</div></div></div>'
    +'<table style="width:100%;border-collapse:collapse;font-size:12px;margin-top:16px;">'
    +'<tr style="background:#f0fdf4;"><td colspan="2" style="padding:8px 12px;font-weight:800;color:#0f3d26;font-size:13px;">📋 User Information</td></tr>'
    +[['Department',u.dept||'—'],['Email',u.email||'—'],['Phone',u.phone||'—'],['Session Timeout',(u.timeout||60)+' minutes'],['Can Print on Letterhead',u.canPrint!==false?'✅ Yes':'❌ No'],['Force Pwd Change',u.forcePwd?'⚠️ Yes':'No'],['Joined',u.createdAt?new Date(u.createdAt).toLocaleDateString('en-BD'):'—'],['Total Logins',u.loginCount||0],['Last Login',u.lastLogin?new Date(u.lastLogin).toLocaleString('en-BD'):'Never'],['Notes',u.notes||'—']].map(([l,v])=>'<tr style="border-bottom:1px solid #f3f4f6;"><td style="padding:8px 12px;font-weight:700;color:#374151;width:35%;">'+l+'</td><td style="padding:8px 12px;color:#6b7280;">'+v+'</td></tr>').join('')
    +'<tr style="background:#f0fdf4;"><td colspan="2" style="padding:8px 12px;font-weight:800;color:#0f3d26;font-size:13px;">🔑 Access Permissions</td></tr>'
    +'<tr><td colspan="2" style="padding:10px 12px;font-size:11px;color:#374151;white-space:pre-line;">'+perms+'</td></tr></table>';
  if(typeof openPrintModal==='function')openPrintModal('User Profile — '+u.name,'USR-'+u.id,html,u.dept||'Administration');
}

function umPrintUserList(){
  const users=DB.users||[];
  const rows=users.map((u,i)=>'<tr style="background:'+(i%2?'#f9fafb':'#fff')+';border-bottom:1px solid #f3f4f6;">'
    +'<td style="padding:7px 10px;">'+(i+1)+'</td>'
    +'<td style="padding:7px 10px;font-weight:700;">'+u.name+'</td>'
    +'<td style="padding:7px 10px;font-family:monospace;color:#6b7280;">@'+u.username+'</td>'
    +'<td style="padding:7px 10px;"><span style="padding:2px 8px;border-radius:10px;font-size:10px;font-weight:700;background:'+_umRoleColor(u.role)+'22;color:'+_umRoleColor(u.role)+';">'+u.role+'</span></td>'
    +'<td style="padding:7px 10px;color:#6b7280;">'+(u.dept||'—')+'</td>'
    +'<td style="padding:7px 10px;"><span style="padding:2px 8px;border-radius:10px;font-size:10px;font-weight:700;background:'+(u.status==='Active'?'#dcfce7':'#fee2e2')+';color:'+(u.status==='Active'?'#16a34a':'#dc2626')+';">'+(u.status||'Active')+'</span></td>'
    +'<td style="padding:7px 10px;font-size:11px;color:#6b7280;">'+(u.email||'—')+'</td>'
    +'<td style="padding:7px 10px;font-size:11px;color:#6b7280;">'+(u.lastLogin?new Date(u.lastLogin).toLocaleDateString('en-BD'):'Never')+'</td>'
    +'</tr>').join('');
  const html='<div style="display:flex;justify-content:space-between;margin-bottom:12px;flex-wrap:wrap;gap:8px;">'
    +'<span style="background:#f0fdf4;border:1px solid #bbf7d0;border-radius:7px;padding:5px 12px;font-size:12px;font-weight:700;color:#0f3d26;">👥 Total: '+users.length+' users</span>'
    +'<span style="font-size:11px;color:#6b7280;">Printed: '+new Date().toLocaleString('en-BD')+'</span></div>'
    +'<table style="width:100%;border-collapse:collapse;font-size:11px;">'
    +'<thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">'
    +'<th style="padding:8px 10px;">#</th><th style="padding:8px 10px;">Name</th><th style="padding:8px 10px;">Username</th><th style="padding:8px 10px;">Role</th><th style="padding:8px 10px;">Department</th><th style="padding:8px 10px;">Status</th><th style="padding:8px 10px;">Email</th><th style="padding:8px 10px;">Last Login</th>'
    +'</tr></thead><tbody>'+rows+'</tbody></table>';
  if(typeof openPrintModal==='function')openPrintModal('User List','USRLIST-'+Date.now().toString().slice(-6),html,'Administration');
}

function umExportCSV(){
  const users=DB.users||[];
  const cols=['id','name','username','role','dept','email','phone','status','loginCount','lastLogin','createdAt','notes'];
  const rows=users.map(u=>cols.map(c=>String(u[c]||'').replace(/,/g,'')).join(','));
  const csv='data:text/csv;charset=utf-8,'+cols.join(',')+'\n'+rows.join('\n');
  const link=document.createElement('a');link.href=encodeURI(csv);link.download='users_'+new Date().toISOString().slice(0,10)+'.csv';link.click();
  toast('📤 Users exported to CSV','s');
}
function umImportCSV(){document.getElementById('um-import-input')?.click();}
function umHandleImport(inp){
  const file=inp.files[0];if(!file)return;
  const reader=new FileReader();
  reader.onload=e=>{
    const lines=e.target.result.split('\n').filter(Boolean);
    const headers=lines[0].split(',').map(h=>h.trim().toLowerCase());
    let added=0,skipped=0;
    lines.slice(1).forEach(line=>{
      const vals=line.split(','),obj={};
      headers.forEach((h,i)=>obj[h]=(vals[i]||'').trim());
      if(!obj.name||!obj.username||!obj.password){skipped++;return;}
      if((DB.users||[]).some(u=>u.username===obj.username)){skipped++;return;}
      if(!DB.users)DB.users=[];
      DB.users.push({id:newId(),name:obj.name,username:obj.username,password:obj.password,role:obj.role||'Viewer',dept:obj.dept||'',email:obj.email||'',phone:obj.phone||'',status:obj.status||'Active',permissions:UM_ROLE_PERMS[obj.role||'Viewer']||{},createdAt:new Date().toISOString(),lastLogin:null,loginCount:0,notes:obj.notes||'',canPrint:true});
      added++;
    });
    saveDB();inp.value='';toast('📥 Import: '+added+' added, '+skipped+' skipped','s');umRender();
  };
  reader.readAsText(file);
}

