}

function openCustomTemplateModal(){
  ['ct-name','ct-message'].forEach(id=>{ document.getElementById(id).value=''; });
  document.getElementById('mCustomTemplate').style.display='flex';
}

function saveCustomTemplate(){
  const name = document.getElementById('ct-name').value.trim();
  const message = document.getElementById('ct-message').value.trim();
  const category = document.getElementById('ct-category')?.value || 'WhatsApp';
  if(!name||!message){ alert('Name and message required'); return; }
    DB.customTemplates.unshift({id:newId(),name,message,category});
  saveDB(); closeModal('mCustomTemplate'); renderCustomTemplates();
}

function renderCustomTemplates(){
  const wrap = document.getElementById('custom-templates-body');
  if(!wrap) return;
  const templates = DB.customTemplates||[];
  if(!templates.length){
    wrap.innerHTML='<div style="text-align:center;padding:30px;color:#9ca3af;">No custom templates yet. Click ➕ Custom Template to add one.</div>';
    return;
  }
  if(wrap) wrap.innerHTML = templates.map(t=>`
    <div style="background:#f9fafb;border:1px solid #e5e7eb;border-radius:10px;padding:14px;margin-bottom:10px;">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">
        <div>
          <span style="font-size:13px;font-weight:800;color:#0f3d26;">${escHTML(t.name)}</span>
          <span style="background:#f0fdf4;color:#16a34a;padding:2px 8px;border-radius:10px;font-size:10px;font-weight:700;margin-left:8px;">${escHTML(t.category)}</span>
        </div>
        <button data-x-click="deleteCustomTemplate(${t.id})" style="background:#fef2f2;border:1px solid #fecaca;color:#dc2626;padding:4px 10px;border-radius:5px;font-size:11px;cursor:pointer;">🗑️</button>
      </div>
      <div style="font-size:12px;color:#374151;white-space:pre-wrap;background:#fff;border:1px solid #e5e7eb;border-radius:6px;padding:10px;">${t.message}</div>
      <button data-x-click="copyTemplateText(${t.id})" style="margin-top:8px;padding:5px 12px;background:#f3f4f6;border:1px solid #d1d5db;border-radius:5px;font-size:11px;cursor:pointer;">📋 Copy</button>
    </div>`).join('');
}

async function deleteCustomTemplate(id){
  if(!await __confirm('Delete this template?')) return;
  DB.customTemplates = (DB.customTemplates||[]).filter(t=>t.id!==id);
  saveDB(); renderCustomTemplates();
}

function copyTemplateText(id){
  const t = (DB.customTemplates||[]).find(t=>t.id===id);
  if(!t) return;
  copyTextSafe(t.message).then(()=>alert('✅ Copied!')).catch(()=>alert(t.message));
}


