// FEATURE 16: Tender Management
// ══════════════════════════════════════════════════════════════
let editingTenderId = null;



function calcTenderNet(){
  const value = parseFloat(document.getElementById('td-value')?.value)||0;
  const advance = parseFloat(document.getElementById('td-advance')?.value)||0;
  const cost = parseFloat(document.getElementById('td-cost')?.value)||0;
  const refund = parseFloat(document.getElementById('td-refund')?.value)||0;
  const netExposure = advance - refund;
  const refundPending = advance - refund;
  const netPL = value - cost - netExposure;
  const el1 = document.getElementById('td-net-exposure');
  const el2 = document.getElementById('td-refund-pending');
  const el3 = document.getElementById('td-net-pl');
  if(el1) el1.textContent = '৳'+pf(netExposure);
  if(el2) el2.textContent = '৳'+pf(refundPending);
  if(el3){ el3.textContent = '৳'+pf(netPL); el3.style.color = netPL>=0?'#16a34a':'#dc2626'; }
}



function editTender(id){
  const t = (DB.tenders||[]).find(t=>t.id===id);
  if(!t) return;
  editingTenderId = id;
  document.getElementById('tender-modal-title').textContent = '✏️ Edit Tender';
  document.getElementById('td-title').value = t.title||'';
  document.getElementById('td-no').value = t.no||'';
  document.getElementById('td-party').value = t.party||'';
  document.getElementById('td-status').value = t.status||'Active';
  document.getElementById('td-submit-date').value = t.submitDate||'';
  document.getElementById('td-deadline').value = t.deadline||'';
  document.getElementById('td-value').value = t.value||'';
  document.getElementById('td-advance').value = t.advance||'';
  document.getElementById('td-cost').value = t.cost||'';
  document.getElementById('td-refund').value = t.refund||'';
  document.getElementById('td-mode').value = t.mode||'Cash';
  document.getElementById('td-notes').value = t.notes||'';
  const bankSel = document.getElementById('td-bank');
  if(bankSel){
    bankSel.innerHTML='<option value="">-- Select --</option>';
    (DB.banks||[]).forEach(b=>{ const o=document.createElement('option'); o.value=b.name; o.textContent=b.name; if(b.name===t.bank) o.selected=true; bankSel.appendChild(o); });
  }
  calcTenderNet();
  document.getElementById('mAddTender').style.display='flex';
}






