const _chartInstances = {};

function destroyChart(id){
  // A stale instance can point at a canvas that was removed when the page
  // re-rendered; destroy() on that throws, so guard and always drop the ref.
  var inst = _chartInstances[id];
  if(inst){
    try{ inst.destroy(); }catch(e){ /* canvas already detached */ }
    delete _chartInstances[id];
  }
  if(typeof Chart !== 'undefined' && Chart.getChart){
    var el = document.getElementById(id);
    if(el){
      var live = null;
      try{ live = Chart.getChart(el); }catch(e){ live = null; }
      if(live){ try{ live.destroy(); }catch(e){} }
    }
  }
}

function renderChartsDashboard(){
  const el=document.getElementById('pg-chartsdash');
  if(!el)return;
  const txs=DB.tx||[];
  const months={};
  const types={};
  txs.forEach(t=>{
    const m=(t.date||'').substring(0,7);
    if(m){
      if(!months[m]) months[m]={sales:0,purch:0,exp:0};
      if(isRevenueTx(t)) months[m].sales+=txAmt(t);
      else if(isCogsTx(t)) months[m].purch+=txAmt(t);
      else months[m].exp+=txAmt(t);
    }
    types[t.type]=(types[t.type]||0)+txAmt(t);
  });
  const sortedMonths=Object.keys(months).sort().slice(-12);
  const topTypes=Object.entries(types).sort((a,b)=>b[1]-a[1]).slice(0,8);
  const totalSales=sumRevenue(txs);
  const totalPurch=sumCogs(txs);
  const totalExp=txs.filter(t=>!isRevenueTx(t)&&!isCogsTx(t)).reduce((s,t)=>s+txAmt(t),0);
  el.innerHTML=`<div class="page-header"><h2>📊 Charts Dashboard</h2><p>Visual analytics for your business data</p></div>
  <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:12px;margin-bottom:20px;">
    <div class="kpi-card" data-x-click="nav('txsheet')" style="cursor:pointer;" title="Click to open Transaction Sheet"><div class="kpi-icon">💰</div><div class="kpi-val">${f(totalSales)}</div><div class="kpi-label">Total Sales →</div></div>
    <div class="kpi-card" data-x-click="nav('txsheet')" style="cursor:pointer;" title="Click to open Transaction Sheet"><div class="kpi-icon">📦</div><div class="kpi-val">${f(totalPurch)}</div><div class="kpi-label">Total Purchases →</div></div>
    <div class="kpi-card" data-x-click="nav('txsheet')" style="cursor:pointer;" title="Click to open Transaction Sheet"><div class="kpi-icon">💸</div><div class="kpi-val">${f(totalExp)}</div><div class="kpi-label">Total Expenses →</div></div>
    <div class="kpi-card" data-x-click="nav('txsheet')" style="cursor:pointer;" title="Click to open Transaction Sheet"><div class="kpi-icon">📋</div><div class="kpi-val">${txs.length}</div><div class="kpi-label">Transactions →</div></div>
  </div>
  <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:20px;">
    <div class="card"><h3 style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:12px;">📈 Monthly Sales vs Purchases</h3>
      ${sortedMonths.length?`<table class="tbl"><thead><tr><th>Month</th><th>Sales</th><th>Purchases</th><th>Profit</th></tr></thead>
      <tbody>${sortedMonths.map(m=>`<tr data-x-click="openPLDrill('${m}-01','${m}-31')" style="cursor:pointer;" title="Click to see this month's transactions">
        <td><strong>${m} →</strong></td>
        <td style="color:#16a34a;">${f(months[m].sales)}</td>
        <td style="color:#dc2626;">${f(months[m].purch)}</td>
        <td style="color:${months[m].sales-months[m].purch>=0?'#059669':'#dc2626'};font-weight:700;">${f(months[m].sales-months[m].purch)}</td>
      </tr>`).join('')}</tbody></table>`
      :'<div style="text-align:center;padding:20px;color:#9ca3af;">No transaction data yet.</div>'}
    </div>
    <div class="card"><h3 style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:12px;">🏷️ Top Transaction Types</h3>
      ${topTypes.length?`<table class="tbl"><thead><tr><th>Type</th><th>Total Amount</th><th>Share</th></tr></thead>
      <tbody>${topTypes.map(([type,amt])=>{
        const grandTotal=Object.values(types).reduce((s,v)=>s+v,0);
        const pct=grandTotal>0?(amt/grandTotal*100).toFixed(1):0;
        return `<tr data-x-click="openCOALine(${JSON.stringify([type])})" style="cursor:pointer;" title="Click to see these transactions">
          <td><strong>${type} →</strong></td>
          <td>${f(amt)}</td>
          <td><div style="display:flex;align-items:center;gap:6px;">
            <div style="flex:1;background:#e5e7eb;border-radius:4px;height:8px;">
              <div style="width:${pct}%;background:#16a34a;border-radius:4px;height:8px;"></div>
            </div>
            <span style="font-size:10px;color:#6b7280;">${pct}%</span>
          </div></td>
        </tr>`;
      }).join('')}</tbody></table>`
      :'<div style="text-align:center;padding:20px;color:#9ca3af;">No data yet.</div>'}
    </div>
  </div>
  <div class="card"><h3 style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:12px;">📅 Monthly Trend Summary</h3>
    ${sortedMonths.length?`<div style="overflow-x:auto;">
      <div style="display:flex;gap:8px;min-width:${sortedMonths.length*100}px;align-items:flex-end;height:120px;padding:0 8px;">
        ${sortedMonths.map(m=>{
          const maxVal=Math.max(...sortedMonths.map(mm=>months[mm].sales));
          const h=maxVal>0?Math.round(months[m].sales/maxVal*100):0;
          return `<div style="flex:1;display:flex;flex-direction:column;align-items:center;gap:4px;">
            <div style="font-size:9px;color:#6b7280;">${f(months[m].sales)}</div>
            <div style="width:100%;background:#16a34a;border-radius:4px 4px 0 0;height:${h}px;min-height:4px;"></div>
            <div style="font-size:9px;color:#374151;transform:rotate(-45deg);white-space:nowrap;">${m}</div>
          </div>`;
        }).join('')}
      </div>
    </div>`:'<div style="text-align:center;padding:20px;color:#9ca3af;">No monthly data available.</div>'}
  </div>`;
}

function _buildAllCharts(){
  if(typeof Chart === 'undefined') return; // Chart.js unavailable — skip silently
  const txs = DB.tx||[];
  const COLORS = ['#16a34a','#2563eb','#dc2626','#d97706','#7c3aed','#0891b2','#db2777','#65a30d'];

  // ── Chart 1: Monthly Revenue vs Expenses ──
  destroyChart('chart-monthly');
  const months = {};
  /* FIX F: was missing 'Customer Sale' from revenue entirely, while wrongly
     counting 'Sales Receipt'/'Sales Advance' (cash movements, not revenue) —
     and rebuilt both Sets on every transaction inside the loop. Now uses the
     canonical isRevenueTx/EXPENSE_TX_TYPES defined once at the top of file. */
  txs.forEach(t=>{
    if(!t.date) return;
    const m = t.date.substring(0,7);
    if(!months[m]) months[m]={rev:0,exp:0};
    if(window.isRevenueTx(t)) months[m].rev+=txAmt(t);
    if(window.EXPENSE_TX_TYPES.has(t.type)) months[m].exp+=txAmt(t);
  });
  const mLabels = Object.keys(months).sort().slice(-12);
  const ctx1 = document.getElementById('chart-monthly');
  if(ctx1){
    _chartInstances['chart-monthly'] = new Chart(ctx1,{
      type:'bar',
      data:{
        labels: mLabels.length?mLabels:['No Data'],
        datasets:[
          {label:'Revenue',data:mLabels.map(m=>months[m]?.rev||0),backgroundColor:'rgba(22,163,74,.7)',borderRadius:4},
          {label:'Expenses',data:mLabels.map(m=>months[m]?.exp||0),backgroundColor:'rgba(220,38,38,.7)',borderRadius:4}
        ]
      },
      options:{responsive:true,plugins:{legend:{position:'top'}},scales:{y:{beginAtZero:true,ticks:{callback:v=>'৳'+pf(v)}}}}
    });
  }

  // ── Chart 2: Transaction Type Pie ──
  destroyChart('chart-txtype');
  const typeCount = {};
  txs.forEach(t=>{ typeCount[t.type]=(typeCount[t.type]||0)+1; });
  const topTypes = Object.entries(typeCount).sort((a,b)=>b[1]-a[1]).slice(0,8);
  const ctx2 = document.getElementById('chart-txtype');
  if(ctx2){
    _chartInstances['chart-txtype'] = new Chart(ctx2,{
      type:'doughnut',
      data:{
        labels: topTypes.length?topTypes.map(t=>t[0]):['No Data'],
        datasets:[{data:topTypes.length?topTypes.map(t=>t[1]):[1],backgroundColor:COLORS}]
      },
      options:{responsive:true,plugins:{legend:{position:'bottom',labels:{font:{size:10}}}}}
    });
  }

  // ── Chart 3: Top Customers ──
  destroyChart('chart-topcust');
  const custSales = {};
  txs.filter(t=>isRevenueTx(t)&&t.party).forEach(t=>{ custSales[t.party]=(custSales[t.party]||0)+txAmt(t); });
  const topCust = Object.entries(custSales).sort((a,b)=>b[1]-a[1]).slice(0,8);
  const ctx3 = document.getElementById('chart-topcust');
  if(ctx3){
    _chartInstances['chart-topcust'] = new Chart(ctx3,{
      type:'bar',
      data:{
        labels: topCust.length?topCust.map(c=>c[0].substring(0,15)):['No Data'],
        datasets:[{label:'Sales (৳)',data:topCust.length?topCust.map(c=>c[1]):[0],backgroundColor:COLORS,borderRadius:4}]
      },
      options:{indexAxis:'y',responsive:true,plugins:{legend:{display:false}},scales:{x:{beginAtZero:true,ticks:{callback:v=>'৳'+pf(v)}}}}
    });
  }

  // ── Chart 4: Product Sales ──
  destroyChart('chart-products');
  const prodSales = {};
  txs.filter(t=>isRevenueTx(t)&&t.product).forEach(t=>{ prodSales[t.product]=(prodSales[t.product]||0)+txAmt(t); });
  const topProd = Object.entries(prodSales).sort((a,b)=>b[1]-a[1]).slice(0,8);
  const ctx4 = document.getElementById('chart-products');
  if(ctx4){
    _chartInstances['chart-products'] = new Chart(ctx4,{
      type:'pie',
      data:{
        labels: topProd.length?topProd.map(p=>p[0]):['No Data'],
        datasets:[{data:topProd.length?topProd.map(p=>p[1]):[1],backgroundColor:COLORS}]
      },
      options:{responsive:true,plugins:{legend:{position:'bottom',labels:{font:{size:10}}}}}
    });
  }

  // ── Chart 5: Cumulative Cash Flow ──
  destroyChart('chart-cashflow');
  const cashTxs = txs.filter(t=>t.date).sort((a,b)=>a.date>b.date?1:-1);
  let cumulative = 0;
  const cfLabels=[], cfData=[];
  const cashIn = new Set(['Sale','Sales Receipt','Cash Received','Bank Withdrawal','Bkash Withdrawal','Partner Capital','Other Income','Interest Income']);
  const cashOut = new Set(['Purchase','Purchase Payment','Cash Payment','Bank Deposit','Bkash Deposit','Salary Payment','Office Rent','Electricity Bill','Transport Cost','Other Expense','Interest Expense']);
  cashTxs.slice(-30).forEach(t=>{
    if(cashIn.has(t.type)) cumulative+=txAmt(t);
    if(cashOut.has(t.type)) cumulative-=txAmt(t);
    cfLabels.push(t.date);
    cfData.push(cumulative);
  });
  const ctx5 = document.getElementById('chart-cashflow');
  if(ctx5){
    _chartInstances['chart-cashflow'] = new Chart(ctx5,{
      type:'line',
      data:{
        labels: cfLabels.length?cfLabels:['No Data'],
        datasets:[{label:'Cumulative Cash Flow',data:cfLabels.length?cfData:[0],borderColor:'#16a34a',backgroundColor:'rgba(22,163,74,.1)',fill:true,tension:.4,pointRadius:2}]
      },
      options:{responsive:true,plugins:{legend:{display:false}},scales:{y:{ticks:{callback:v=>'৳'+pf(v)}}}}
    });
  }

  // ── Chart 6: Bank Balance Doughnut ──
  destroyChart('chart-banks');
  const banks = (DB.banks||[]).filter(b=>(b.balance||0)>0);
  const ctx6 = document.getElementById('chart-banks');
  if(ctx6){
    _chartInstances['chart-banks'] = new Chart(ctx6,{
      type:'doughnut',
      data:{
        labels: banks.length?banks.map(b=>b.name.substring(0,20)):['No Banks'],
        datasets:[{data:banks.length?banks.map(b=>b.balance||0):[1],backgroundColor:COLORS}]
      },
      options:{responsive:true,plugins:{legend:{position:'bottom',labels:{font:{size:9}}}}}
    });
  }

  // ── Chart 7: Expense Breakdown ──
  destroyChart('chart-expenses');
  const expCats = {};
  const expTypesList = ['Salary Payment','Office Rent','Electricity Bill','Internet Bill','Telephone Bill','Fuel Expense','Transport Cost','Loading Charge','Unloading Charge','Commission Payment','Brokerage Fee','Legal Fee','Audit Fee','Insurance Premium','Tax Payment','Government Fee','License Fee','Maintenance Cost','Repair Expense','Stationery Purchase','Other Expense','Interest Expense','Bank Charge'];
  txs.filter(t=>expTypesList.includes(t.type)).forEach(t=>{ expCats[t.type]=(expCats[t.type]||0)+txAmt(t); });
  const topExp = Object.entries(expCats).sort((a,b)=>b[1]-a[1]).slice(0,8);
  const ctx7 = document.getElementById('chart-expenses');
  if(ctx7){
    _chartInstances['chart-expenses'] = new Chart(ctx7,{
      type:'bar',
      data:{
        labels: topExp.length?topExp.map(e=>e[0]):['No Expenses'],
        datasets:[{label:'Amount (৳)',data:topExp.length?topExp.map(e=>e[1]):[0],backgroundColor:'rgba(220,38,38,.7)',borderRadius:4}]
      },
      options:{responsive:true,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,ticks:{callback:v=>'৳'+pf(v)}}}}
    });
  }
}


// ══════════════════════════════════════════════════════════════
// FEATURE 18: Business Health
// ══════════════════════════════════════════════════════════════
function bhArr(v){ return Array.isArray(v) ? v : (v && typeof v==='object' ? Object.values(v) : []); }

function renderBizHealth(){
  if(!window.DB || typeof window.DB!=='object') return;
  const txs = bhArr(DB.tx);
  const customers = bhArr(DB.customers);
  const banks = bhArr(DB.banks);
  const partners = bhArr(DB.partners);
  // keep collections normalised so downstream modules never hit `.filter of undefined`
  ['tx','customers','banks','partners','inventory','tenders','employees','users'].forEach(function(k){
    if(!Array.isArray(DB[k])) DB[k] = bhArr(DB[k]);
  });

  // ── Compute KPIs ──
  const saleTypes = window.SALE_TX_TYPES;
  const purchTypes = window.PURCHASE_TX_TYPES;
  const expTypes = window.EXPENSE_TX_TYPES;

  const totalSales = txs.filter(t=>saleTypes.has(t.type)).reduce((s,t)=>s+txAmt(t),0);
  const totalPurch = txs.filter(t=>purchTypes.has(t.type)).reduce((s,t)=>s+txAmt(t),0);
  const totalExp = txs.filter(t=>expTypes.has(t.type)).reduce((s,t)=>s+txAmt(t),0);
  // Use COGS (cost of goods actually sold) not totalPurch (all purchases incl. unsold stock)
  const totalCOGS  = window.computeCOGS(txs);
  const grossProfit = totalSales - totalCOGS;
  const netProfit = grossProfit - totalExp;
  const totalReceivables = customers.reduce((s,c)=>s+(c.bal||0),0);
  const totalBankBalance = banks.reduce((s,b)=>s+(b.bal||0),0);
  const totalPartnerFunds = partners.reduce((s,p)=>s+(p.cap||0),0);

  const grossMargin = totalSales>0?(grossProfit/totalSales*100):0;
  const netMargin = totalSales>0?(netProfit/totalSales*100):0;
  const receivablesTurnover = totalSales>0?(totalReceivables/totalSales*100):0;
  const liquidityRatio = totalReceivables>0?(totalBankBalance/totalReceivables*100):100;

  // ── Score Calculation (0-100) ──
  let score = 50;
  if(netMargin>15) score+=15; else if(netMargin>5) score+=8; else if(netMargin<0) score-=20;
  if(grossMargin>30) score+=10; else if(grossMargin>15) score+=5; else if(grossMargin<0) score-=15;
  if(liquidityRatio>50) score+=10; else if(liquidityRatio>20) score+=5; else score-=10;
  if(totalBankBalance>500000) score+=10; else if(totalBankBalance>100000) score+=5; else score-=5;
  if(receivablesTurnover<30) score+=5; else if(receivablesTurnover>80) score-=10;
  score = Math.max(0, Math.min(100, score));

  const scoreLabel = score>=80?'Excellent 🌟':score>=65?'Good 👍':score>=50?'Fair ⚠️':score>=35?'Poor 🔴':'Critical 🚨';
  const scoreColor = score>=80?'#4ade80':score>=65?'#86efac':score>=50?'#fbbf24':score>=35?'#f97316':'#f87171';

  // Update score display
  const scoreEl = document.getElementById('bh-score-display');
  const labelEl = document.getElementById('bh-score-label');
  const barEl = document.getElementById('bh-score-bar');
  if(scoreEl) scoreEl.textContent = score;
  if(labelEl) labelEl.textContent = scoreLabel;
  if(barEl){ barEl.style.width=score+'%'; barEl.style.background=scoreColor; }

  // Quick stats
  const qsEl = document.getElementById('bh-quick-stats');
  if(qsEl) qsEl.innerHTML = [
    {label:'Net Margin',val:netMargin.toFixed(1)+'%'},
    {label:'Gross Margin',val:grossMargin.toFixed(1)+'%'},
    {label:'Liquidity',val:liquidityRatio.toFixed(0)+'%'}
  ].map(s=>`<div style="background:rgba(255,255,255,.15);border-radius:8px;padding:10px;text-align:center;">
    <div style="font-size:16px;font-weight:800;">${s.val}</div>
    <div style="font-size:10px;opacity:.8;">${escHTML(s.label)}</div>
  </div>`).join('');

  // ── Health Indicators ──
  const indicators = [
    {label:'Total Revenue',val:'৳'+pf(totalSales),icon:'💰',status:totalSales>0?'good':'warn',note:totalSales>0?'Revenue recorded':'No sales yet',page:'dailysales'},
    {label:'Gross Profit',val:'৳'+pf(grossProfit),icon:'📈',status:grossProfit>0?'good':'bad',note:grossProfit>0?'Positive gross profit':'Negative gross profit',page:'reports'},
    {label:'Net Profit',val:'৳'+pf(netProfit),icon:'🏆',status:netProfit>0?'good':netProfit>-50000?'warn':'bad',note:netProfit>0?'Profitable':'Loss-making',page:'reports'},
    {label:'Bank Balance',val:'৳'+pf(totalBankBalance),icon:'🏦',status:totalBankBalance>500000?'good':totalBankBalance>100000?'warn':'bad',note:totalBankBalance>500000?'Healthy liquidity':'Low bank balance',page:'banks'},
    {label:'Receivables',val:'৳'+pf(totalReceivables),icon:'📋',status:receivablesTurnover<50?'good':receivablesTurnover<80?'warn':'bad',note:receivablesTurnover<50?'Manageable':'High receivables ratio',page:'customeraging'},
    {label:'Partner Funds',val:'৳'+pf(totalPartnerFunds),icon:'🤝',status:totalPartnerFunds>0?'good':'warn',note:totalPartnerFunds>0?'Capital available':'No partner funds',page:'partners'}
  ];

  const statusStyles = {
    good:{bg:'#f0fdf4',border:'#bbf7d0',color:'#16a34a',dot:'#16a34a'},
    warn:{bg:'#fffbeb',border:'#fde68a',color:'#d97706',dot:'#d97706'},
    bad:{bg:'#fef2f2',border:'#fecaca',color:'#dc2626',dot:'#dc2626'}
  };

  const indEl = document.getElementById('bh-indicators');
  if(indEl) indEl.innerHTML = indicators.map(ind=>{
    const st = statusStyles[ind.status];
    return `<div class="bh-ind" data-page="${ind.page||''}" title="Open related ledger" style="cursor:pointer;background:${st.bg};border:1px solid ${st.border};border-radius:10px;padding:14px;">
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;">
        <span style="font-size:20px;">${ind.icon}</span>
        <span style="font-size:12px;font-weight:700;color:#374151;">${escHTML(ind.label)}</span>
        <span style="width:8px;height:8px;border-radius:50%;background:${st.dot};margin-left:auto;"></span>
      </div>
      <div style="font-size:18px;font-weight:900;color:${st.color};">${ind.val}</div>
      <div style="font-size:10px;color:#6b7280;margin-top:4px;">${escHTML(ind.note)}</div>
    </div>`;
  }).join('');

  // ── Risk Alerts ──
  const alerts = [];
  if(netProfit<0) alerts.push({level:'critical',msg:'Business is operating at a loss of ৳'+pf(Math.abs(netProfit))});
  if(totalBankBalance<100000) alerts.push({level:'high',msg:'Bank balance is critically low: ৳'+pf(totalBankBalance)});
  if(receivablesTurnover>80) alerts.push({level:'high',msg:'Receivables are very high relative to sales ('+receivablesTurnover.toFixed(0)+'%)'});
  if(grossMargin<10) alerts.push({level:'medium',msg:'Gross margin is thin ('+grossMargin.toFixed(1)+'%) — review pricing'});
  const overdueCustomers = customers.filter(c=>(c.bal||0)>500000);
  if(overdueCustomers.length) alerts.push({level:'medium',msg:overdueCustomers.length+' customer(s) have dues over ৳5 lakh'});
  if(!alerts.length) alerts.push({level:'ok',msg:'No critical risks detected. Business is healthy!'});

  const alertColors = {critical:'#dc2626',high:'#ea580c',medium:'#d97706',ok:'#16a34a'};
  const alertIcons = {critical:'🚨',high:'🔴',medium:'⚠️',ok:'✅'};
  const alertsEl = document.getElementById('bh-alerts');
  if(alertsEl) alertsEl.innerHTML = alerts.map(a=>`
    <div style="display:flex;align-items:center;gap:10px;padding:10px 14px;background:${alertColors[a.level]}11;border-left:4px solid ${alertColors[a.level]};border-radius:0 8px 8px 0;margin-bottom:8px;">
      <span style="font-size:16px;">${alertIcons[a.level]}</span>
      <span style="font-size:12px;color:#374151;">${a.msg}</span>
    </div>`).join('');

  // ── Recommendations ──
  const recs = [];
  if(totalReceivables>totalBankBalance*2) recs.push('📞 Follow up on outstanding receivables — they exceed 2x your bank balance');
  if(netMargin<10&&netMargin>=0) recs.push('💡 Net margin is below 10% — consider reducing operating expenses');
  if(totalExp>totalSales*0.3) recs.push('✂️ Expenses are over 30% of revenue — review and cut non-essential costs');
  if(totalBankBalance<200000) recs.push('🏦 Maintain a minimum bank balance of ৳2 lakh for operational safety');
  if(totalSales===0) recs.push('🚀 No sales recorded yet — start entering transactions to see analytics');
  if(!recs.length) recs.push('🌟 Business is performing well! Keep monitoring key metrics regularly.');

  const recsEl = document.getElementById('bh-recommendations');
  if(recsEl) recsEl.innerHTML = recs.map((r,i)=>`
    <div style="display:flex;align-items:flex-start;gap:10px;padding:10px 14px;background:#f9fafb;border:1px solid #e5e7eb;border-radius:8px;margin-bottom:8px;">
      <span style="background:#16a34a;color:#fff;width:20px;height:20px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:10px;font-weight:800;flex-shrink:0;">${i+1}</span>
      <span style="font-size:12px;color:#374151;">${r}</span>
    </div>`).join('');

  bhBindEvents();
  bhRenderTrend(txs, saleTypes, purchTypes, expTypes);
}

// Ledger routing + toolbar listeners. Rebound on every render, but always
// de-duplicated so repeated nav() calls never stack handlers.
function bhBindEvents(){
  const page = document.getElementById('pg-bizhealth');
  if(!page || page.dataset.bhBound === '1') return;
  page.dataset.bhBound = '1';
  page.addEventListener('click', function(e){
    const card = e.target.closest ? e.target.closest('.bh-ind') : null;
    if(card && card.dataset.page && typeof nav === 'function'){ nav(card.dataset.page); return; }
    const btn = e.target.closest ? e.target.closest('[data-bh-action]') : null;
    if(!btn) return;
    const act = btn.getAttribute('data-bh-action');
    if(act === 'refresh') renderBizHealth();
    else if(act === 'print') window.print();
    else if(act === 'ledger' && typeof nav === 'function') nav('ledgers');
  });
}

// 6-month profit trend. destroyChart() guards against a stale instance that
// still points at the canvas replaced by the previous page render.
function bhRenderTrend(txs, saleTypes, purchTypes, expTypes){
  const cv = document.getElementById('bh-trend');
  if(!cv || typeof Chart === 'undefined') return;
  destroyChart('bh-trend');
  const labels = [], sales = [], profit = [];
  const now = new Date();
  for(let i=5;i>=0;i--){
    const d = new Date(now.getFullYear(), now.getMonth()-i, 1);
    labels.push(d.toLocaleString('en-US',{month:'short'}));
    const inMonth = txs.filter(function(t){
      const td = new Date(t.date);
      return !isNaN(td) && td.getFullYear()===d.getFullYear() && td.getMonth()===d.getMonth();
    });
    const sum = function(set){ return inMonth.filter(t=>set.has(t.type)).reduce((s,t)=>s+txAmt(t),0); };
    const sv = sum(saleTypes);
    sales.push(sv);
    // FIX-PROFIT-2: COGS ব্যবহার করো (total purchases নয়) — unsold stock profit কমায় না
    const _mCOGS = (typeof window.computeCOGS==='function') ? window.computeCOGS(inMonth) : sum(purchTypes);
    const _mPurchRet = inMonth.filter(t=>t.type==='Purchase Return').reduce((s,t)=>s+txAmt(t),0);
    const _mSalesRet = inMonth.filter(t=>t.type==='Sales Return'||t.type==='Sale Return').reduce((s,t)=>s+txAmt(t),0);
    const _mOtherInc = inMonth.filter(t=>t.type==='Other Income'||t.type==='Interest Income').reduce((s,t)=>s+txAmt(t),0);
    profit.push((sv - _mSalesRet + _mOtherInc) - Math.max(0,_mCOGS-_mPurchRet) - sum(expTypes));
  }
  try{
    _chartInstances['bh-trend'] = new Chart(cv, {
      type:'bar',
      data:{labels:labels,datasets:[
        {label:'Revenue',data:sales,backgroundColor:'rgba(22,163,74,.7)',borderRadius:6},
        {type:'line',label:'Net Profit',data:profit,borderColor:'#0f3d26',backgroundColor:'rgba(15,61,38,.15)',tension:.35,fill:true}
      ]},
      options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'top'}}}
    });
  }catch(err){ console.warn('bizhealth trend chart skipped:', err); }
}


// ══════════════════════════════════════════════════════════════
// FEATURE 19: VAT Management
// ══════════════════════════════════════════════════════════════
function renderVATReport(){
  const salesRate = parseFloat(document.getElementById('vat-rate-sales')?.value||15)/100;
  const purchRate = parseFloat(document.getElementById('vat-rate-purch')?.value||15)/100;
  const period = document.getElementById('vat-period-filter')?.value||'all';

  const now = new Date();
  const thisMonth = now.toISOString().substring(0,7);
  const lastMonth = new Date(now.getFullYear(), now.getMonth()-1, 1).toISOString().substring(0,7);
  const thisYear = now.getFullYear().toString();

  let txs = DB.tx||[];
  if(period==='thismonth') txs = txs.filter(t=>(t.date||'').startsWith(thisMonth));
  else if(period==='lastmonth') txs = txs.filter(t=>(t.date||'').startsWith(lastMonth));
  else if(period==='thisyear') txs = txs.filter(t=>(t.date||'').startsWith(thisYear));

  /* FIX G: VAT was being computed on 'Sales Receipt'/'Sales Advance' (cash
     against a receivable) as well as the original sale invoice — that double-
     counts output VAT on the same sale and was also missing 'Customer Sale'
     and 'Supplier Purchase'/'Werhouse Purchase' entirely. VAT must be based on
     the actual invoice event, so this now uses the same canonical
     isRevenueTx/isCogsTx that the Ledger and Trial Balance use. */
  const salesTxs = txs.filter(t=>window.isRevenueTx(t));
  const purchTxs = txs.filter(t=>window.isCogsTx(t));

  const totalSales = salesTxs.reduce((s,t)=>s+txAmt(t),0);
  const totalPurch = purchTxs.reduce((s,t)=>s+txAmt(t),0);
  const outputVAT = totalSales * salesRate;
  const inputVAT = totalPurch * purchRate;
  const netVAT = outputVAT - inputVAT;

  // Summary Cards
  const cardsEl = document.getElementById('vat-summary-cards');
  if(cardsEl){
    if(cardsEl) cardsEl.innerHTML = [
      {label:'Output VAT (Sales)',val:outputVAT,icon:'📤',color:'#dc2626'},
      {label:'Input VAT (Purchases)',val:inputVAT,icon:'📥',color:'#16a34a'},
      {label:'Net VAT Payable',val:netVAT,icon:'🏛️',color:netVAT>=0?'#d97706':'#16a34a'},
      {label:'VAT Refundable',val:netVAT<0?Math.abs(netVAT):0,icon:'💚',color:'#16a34a'}
    ].map(c=>`<div style="background:linear-gradient(135deg,${c.color},${c.color}cc);color:#fff;border-radius:10px;padding:14px;">
      <div style="font-size:18px;">${c.icon}</div>
      <div style="font-size:18px;font-weight:900;">৳${pf(c.val)}</div>
      <div style="font-size:10px;opacity:.8;">${escHTML(c.label)}</div>
    </div>`).join('');
  }

  // VAT Table
  const wrap = document.getElementById('vat-table-wrap');
  if(!wrap) return;

  const allVATRows = [
    ...salesTxs.map(t=>({...t,vatType:'Output',vatAmt:txAmt(t)*salesRate,txType:'Sale'})),
    ...purchTxs.map(t=>({...t,vatType:'Input',vatAmt:txAmt(t)*purchRate,txType:'Purchase'}))
  ].sort((a,b)=>a.date>b.date?-1:1);

  if(!allVATRows.length){
    wrap.innerHTML='<div style="text-align:center;padding:30px;color:#9ca3af;">No transactions found for selected period.</div>';
    return;
  }

  if(wrap) wrap.innerHTML = `<table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
      <th style="padding:10px 12px;text-align:left;">Date</th>
      <th style="padding:10px 12px;text-align:left;">Type</th>
      <th style="padding:10px 12px;text-align:left;">Party</th>
      <th style="padding:10px 12px;text-align:left;">Product</th>
      <th style="padding:10px 12px;text-align:right;">Amount (৳)</th>
      <th style="padding:10px 12px;text-align:center;">VAT Type</th>
      <th style="padding:10px 12px;text-align:right;">VAT Amount (৳)</th>
    </tr></thead>
    <tbody>${allVATRows.map((t,i)=>{
      const isOutput = t.vatType==='Output';
      return `<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
        <td style="padding:9px 12px;color:#6b7280;">${t.date||'—'}</td>
        <td style="padding:9px 12px;">${t.type||'—'}</td>
        <td style="padding:9px 12px;font-weight:600;">${escHTML(t.party||'—')}</td>
        <td style="padding:9px 12px;color:#6b7280;">${t.prod||'—'}</td>
        <td style="padding:9px 12px;text-align:right;font-weight:700;">৳${pf(txAmt(t))}</td>
        <td style="padding:9px 12px;text-align:center;"><span style="background:${isOutput?'#fef2f2':'#f0fdf4'};color:${isOutput?'#dc2626':'#16a34a'};padding:2px 10px;border-radius:10px;font-size:10px;font-weight:700;">${t.vatType}</span></td>
        <td style="padding:9px 12px;text-align:right;font-weight:800;color:${isOutput?'#dc2626':'#16a34a'};">৳${pf(t.vatAmt)}</td>
      </tr>`;
    }).join('')}
    <tr style="background:#f0fdf4;border-top:2px solid #16a34a;">
      <td colspan="4" style="padding:10px 12px;font-weight:900;color:#0f3d26;">NET VAT ${netVAT>=0?'PAYABLE':'REFUNDABLE'}</td>
      <td colspan="3" style="padding:10px 12px;text-align:right;font-weight:900;font-size:15px;color:${netVAT>=0?'#dc2626':'#16a34a'};">৳${pf(Math.abs(netVAT))}</td>
    </tr>
    </tbody>
  </table>`;
}

function printVATReport(){
  const content = document.getElementById('vat-table-wrap')?.innerHTML||'';
  if(!content){ toast && toast('Nothing to print yet','e'); return; }
  const html = '<style>#print-content table{width:100%;border-collapse:collapse;}#print-content th,#print-content td{padding:8px 12px;border:1px solid #ddd;font-size:12px;}#print-content th{background:#0f3d26;color:#fff;}</style>'
    + '<h2 style="text-align:center;margin:0 0 12px;color:#0f3d26;">VAT Report</h2>' + content;
  openPrintModal('VAT Report', 'VAT-'+Date.now().toString().slice(-6), html, 'Value Added Tax');
}


