// FEATURE 20: Data Management (Import / Export)
// ══════════════════════════════════════════════════════════════
let _importBuffer = null;

function renderDataMgmt(){
  const statsEl = document.getElementById('db-stats');
  if(!statsEl) return;
  const txCount = (DB.tx||[]).length;
  const custCount = (DB.customers||[]).length;
  const partnerCount = (DB.partners||[]).length;
  const bankCount = (DB.banks||[]).length;
  const dbSize = JSON.stringify(DB).length;
  if(statsEl) statsEl.innerHTML = [
    {label:'Transactions',val:txCount,icon:'📊'},
    {label:'Customers',val:custCount,icon:'👥'},
    {label:'Partners',val:partnerCount,icon:'🤝'},
    {label:'DB Size',val:(dbSize/1024).toFixed(1)+' KB',icon:'💾'}
  ].map(s=>`<div style="background:#f9fafb;border:1px solid #e5e7eb;border-radius:8px;padding:12px;text-align:center;">
    <div style="font-size:20px;">${s.icon}</div>
    <div style="font-size:18px;font-weight:800;color:#0f3d26;">${s.val}</div>
    <div style="font-size:10px;color:#6b7280;">${escHTML(s.label)}</div>
  </div>`).join('');
}

function exportCSV(type){
  let rows=[], headers=[], data=[];
  if(type==='transactions'){
    headers=['Date','Type','Party','Party Type','Product','Amount','Qty','Rate','Mode','Account','Invoice','Notes'];
    data=(DB.tx||[]).map(t=>[t.date||'',t.type||'',t.party||'',t.partyType||'',t.product||'',txAmt(t),t.qty||'',t.rate||'',t.mode||'',t.account||'',t.inv||'',t.notes||'']);
  } else if(type==='customers'){
    headers=['Name','Type','Due','Phone','Email','Address'];
    data=(DB.customers||[]).map(c=>[c.name||'',c.type||'Customer',c.bal||0,c.phone||'',c.email||'',c.address||'']);
  } else if(type==='partners'){
    headers=['Name','Capital','Share %','Phone'];
    data=(DB.partners||[]).map(p=>[p.name||'',p.cap||0,p.share||0,p.contact||'']);
  } else if(type==='banks'){
    headers=['Name','Balance','Type','Account No'];
    data=(DB.banks||[]).map(b=>[b.name||'',b.bal||0,b.type||'',b.accno||'']);
  }
  rows=[headers,...data];
  const csv=rows.map(r=>r.map(v=>__csvCell(v)).join(',')).join('\n');
  const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');
  a.href=url; a.download=type+'_'+new Date().toISOString().split('T')[0]+'.csv';
  a.click(); URL.revokeObjectURL(url);
  logAudit('EXPORT','Data Management','Exported '+type+' to CSV');
}



function downloadImportTemplate(){
  const headers=['Date','Type','Party','Party Type','Product','Amount','Qty','Rate','Mode','Account','Invoice','Notes'];
  const sample=['2025-01-15','Sale','Corn Enterprise','Customer','Rice Bran Oil','50000','500','100','Bank','IBBL MESARS KARIMA ENTERPRISE','INV-001','Sample transaction'];
  const csv=[headers,sample].map(r=>r.map(v=>'"'+v+'"').join(',')).join('\n');
  const blob=new Blob([csv],{type:'text/csv'});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');
  a.href=url; a.download='import_template.csv'; a.click(); URL.revokeObjectURL(url);
}

function handleImportDrop(e){
  e.preventDefault();
  document.getElementById('import-drop-zone').style.borderColor='#d1d5db';
  const file=e.dataTransfer.files[0];
  if(file) processImportFile(file);
}

function handleImportFile(e){
  const file=e.target.files[0];
  if(file) processImportFile(file);
}

function processImportFile(file){
  const reader=new FileReader();
  reader.onload=async function(e){
    const text=e.target.result;
    if(file.name.endsWith('.json')){
      try{
        const data=JSON.parse(text);
        if(await __confirm('This will REPLACE all current data with the backup. Continue?')){
          Object.assign(DB,data); try{ repairTxIds(); }catch(e){} saveDB();
          alert('✅ Backup restored successfully!');
          logAudit('CREATE','Data Management','Restored full backup from JSON');
          render(currentPage);
        }
      }catch(err){ alert('❌ Invalid JSON file'); }
    } else {
      // CSV import
      const lines=text.split('\n').filter(l=>l.trim());
      const headers=lines[0].split(',').map(h=>h.replace(/"/g,'').trim());
      const rows=lines.slice(1).map(line=>{
        const vals=line.match(/(".*?"|[^,]+)(?=,|$)/g)||[];
        const obj={};
        headers.forEach((h,i)=>{ obj[h]=(vals[i]||'').replace(/"/g,'').trim(); });
        return obj;
      }).filter(r=>r.Date||r.date);
      _importBuffer=rows;
      showImportPreview(rows);
    }
  };
  reader.readAsText(file);
}

function showImportPreview(rows){
  const wrap=document.getElementById('import-preview-wrap');
  const body=document.getElementById('import-preview-body');
  if(!wrap||!body) return;
  wrap.style.display='block';
  const preview=rows.slice(0,20);
  body.innerHTML=`<div style="font-size:12px;color:#6b7280;margin-bottom:8px;">${rows.length} rows found (showing first 20)</div>
  <table style="width:100%;border-collapse:collapse;font-size:11px;">
    <thead><tr style="background:#0f3d26;color:#fff;">${Object.keys(preview[0]||{}).map(h=>'<th style="padding:6px 10px;text-align:left;">'+h+'</th>').join('')}</tr></thead>
    <tbody>${preview.map((r,i)=>`<tr style="background:${i%2?'#f9fafb':'#fff'};border-bottom:1px solid #f3f4f6;">${Object.values(r).map(v=>'<td style="padding:6px 10px;">'+v+'</td>').join('')}</tr>`).join('')}</tbody>
  </table>`;
}

function confirmImport(){
  if(!_importBuffer||!_importBuffer.length){ alert('No data to import'); return; }
  let imported=0;
  _importBuffer.forEach(row=>{
    const tx={
      id: newId(),
      date: row.Date||row.date||'',
      type: row.Type||row.type||'Sale',
      party: row.Party||row.party||'',
      partyType: row['Party Type']||row.partyType||'Customer',
      product: row.Product||row.product||'',
      amt: parseFloat(row.Amount||row.amount||0),
      qty: parseFloat(row.Qty||row.qty||0)||null,
      rate: parseFloat(row.Rate||row.rate||0)||null,
      mode: row.Mode||row.mode||'Cash',
      account: row.Account||row.account||'',
      inv: row.Invoice||row.invoice||'',
      notes: row.Notes||row.notes||''
    };
    if(!DB.tx) DB.tx=[];
    DB.tx.unshift(tx);
    imported++;
  });
  saveDB(); cancelImport();
  alert('✅ '+imported+' transactions imported successfully!');
  logAudit('CREATE','Data Management','Imported '+imported+' transactions from CSV');
  _importBuffer=null;
}

function cancelImport(){
  const wrap=document.getElementById('import-preview-wrap');
  if(wrap) wrap.style.display='none';
  _importBuffer=null;
  const inp=document.getElementById('import-file-input');
  if(inp) inp.value='';
}



async function clearAllData(){
  if(!await __confirm('⚠️ This will DELETE ALL transactions. Are you sure?')) return;
  if(!await __confirm('This action CANNOT be undone. Type OK to confirm.')) return;
  DB.tx=[];
  saveDB(); renderDataMgmt();
  alert('✅ All transaction data cleared.');
  logAudit('DELETE','Data Management','All transaction data cleared');
}


