function renderCheques(){
  const cheques = DB.cheques||[];
  // KPIs
  const kpiEl = document.getElementById('cheque-kpis');
  if(kpiEl){
    const pending = cheques.filter(c=>c.status==='Pending');
    const cleared = cheques.filter(c=>c.status==='Cleared');
    const bounced = cheques.filter(c=>c.status==='Bounced');
    const pendingAmt = pending.reduce((s,c)=>s+(c.amount||0),0);
    kpiEl.innerHTML = [
      {label:'Pending',val:pending.length,sub:'৳'+pf(pendingAmt),icon:'⏳',color:'#d97706'},
      {label:'Cleared',val:cleared.length,sub:'',icon:'✅',color:'#16a34a'},
      {label:'Bounced',val:bounced.length,sub:'',icon:'❌',color:'#dc2626'},
      {label:'Total',val:cheques.length,sub:'',icon:'🏷️',color:'#2563eb'}
    ].map(k=>`<div style="background:linear-gradient(135deg,${k.color},${k.color}cc);color:#fff;border-radius:10px;padding:14px;">
      <div style="font-size:18px;">${k.icon}</div>
      <div style="font-size:22px;font-weight:900;">${k.val}</div>
      ${k.sub?'<div style="font-size:11px;opacity:.9;">'+k.sub+'</div>':''}
      <div style="font-size:10px;opacity:.7;">${escHTML(k.label)}</div>
    </div>`).join('');
  }

  // Filter
  const statusF = document.getElementById('cheque-filter-status')?.value||'';
  const typeF = document.getElementById('cheque-filter-type')?.value||'';
  const search = (document.getElementById('cheque-search')?.value||'').toLowerCase();
  let filtered = cheques;
  if(statusF) filtered = filtered.filter(c=>c.status===statusF);
  if(typeF) filtered = filtered.filter(c=>c.type===typeF);
  if(search) filtered = filtered.filter(c=>
    (c.no||'').toLowerCase().includes(search)||
    (c.party||'').toLowerCase().includes(search)||
    (c.bank||'').toLowerCase().includes(search)
  );

  const wrap = document.getElementById('cheque-table-body');
  if(!wrap) return;
  if(!filtered.length){
    wrap.innerHTML='<div style="text-align:center;padding:30px;color:#9ca3af;">No cheques found. Click ➕ Add Cheque to start.</div>';
    return;
  }

  const today = new Date().toISOString().split('T')[0];
  const statusColors = {Pending:'#d97706',Cleared:'#16a34a',Bounced:'#dc2626',Cancelled:'#6b7280'};

  if(wrap) wrap.innerHTML = `<table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
      <th style="padding:10px 12px;text-align:left;">Cheque No</th>
      <th style="padding:10px 12px;text-align:left;">Type</th>
      <th style="padding:10px 12px;text-align:left;">Party</th>
      <th style="padding:10px 12px;text-align:left;">Bank</th>
      <th style="padding:10px 12px;text-align:right;">Amount (৳)</th>
      <th style="padding:10px 12px;text-align:left;">Cheque Date</th>
      <th style="padding:10px 12px;text-align:left;">Due Date</th>
      <th style="padding:10px 12px;text-align:center;">Status</th>
      <th style="padding:10px 12px;text-align:center;">Actions</th>
    </tr></thead>
    <tbody>${filtered.map((c,i)=>{
      const sc = statusColors[c.status]||'#6b7280';
      /* FIX (2026-08-24): saveCheque() stores the field as c.dueDate; this
         read c.due, which is never set, so the Due Date column always
         showed "—" and a genuinely overdue pending cheque never got
         flagged, no matter how far past its due date it was. */
      const isOverdue = c.status==='Pending' && c.dueDate && c.dueDate < today;
      return `<tr style="border-bottom:1px solid #f3f4f6;background:${isOverdue?'#fff7ed':i%2?'#f9fafb':'#fff'};">
        <td style="padding:9px 12px;font-weight:800;color:#0f3d26;">${c.no||'—'}</td>
        <td style="padding:9px 12px;"><span style="background:${c.type==='Received'?'#f0fdf4':'#fef2f2'};color:${c.type==='Received'?'#16a34a':'#dc2626'};padding:2px 8px;border-radius:8px;font-size:10px;font-weight:700;">${c.type}</span></td>
        <td style="padding:9px 12px;">${escHTML(c.party||'—')}</td>
        <td style="padding:9px 12px;color:#6b7280;">${escHTML(c.bank||'—')}</td>
        <td style="padding:9px 12px;text-align:right;font-weight:800;color:#0f3d26;">৳${pf(c.amount||0)}</td>
        <td style="padding:9px 12px;color:#6b7280;">${c.date||'—'}</td>
        <td style="padding:9px 12px;color:${isOverdue?'#dc2626':'#6b7280'};font-weight:${isOverdue?'700':'400'};">${c.dueDate||'—'}${isOverdue?' ⚠️':''}</td>
        <td style="padding:9px 12px;text-align:center;"><span style="background:${sc}22;color:${sc};padding:2px 10px;border-radius:10px;font-size:10px;font-weight:700;">${c.status}</span></td>
        <td style="padding:9px 12px;text-align:center;">
          <select data-x-change="updateChequeStatus(${c.id},this.value)" style="padding:3px 6px;border:1px solid #d1d5db;border-radius:4px;font-size:10px;cursor:pointer;">
            <option value="">Change...</option>
            <option value="Pending">Pending</option>
            <option value="Cleared">Cleared</option>
            <option value="Bounced">Bounced</option>
            <option value="Cancelled">Cancelled</option>
          </select>
          <button data-x-click="deleteCheque(${c.id})" style="background:#fef2f2;border:1px solid #fecaca;color:#dc2626;padding:3px 8px;border-radius:4px;font-size:10px;cursor:pointer;margin-left:4px;">🗑️</button>
        </td>
      </tr>`;
    }).join('')}</tbody>
  </table>`;
}










