// ══════════════════════════════════════════════════════════════
let _payrollTab = 'employees';

function setPayrollTab(tab){
  _payrollTab = tab;
  /* BUGFIX: the actual buttons in the page are #pr-tab-employees /
     #pr-tab-salary / #pr-tab-history / #pr-tab-advances — this looked for
     #ptab-* (no such elements exist), so the active-tab highlight never
     updated. Purely cosmetic, but fixed while in here. */
  ['employees','salary','history','advances'].forEach(t=>{
    const btn = document.getElementById('pr-tab-'+t);
    if(btn){
      btn.style.background = t===tab?'linear-gradient(135deg,#16a34a,#15803d)':'#f3f4f6';
      btn.style.color = t===tab?'#fff':'#374151';
    }
    /* BUGFIX: #pr-panel-employees/-salary/-history/-advances are four
       separate divs in the page (only #pr-panel-employees starts visible);
       nothing ever toggled which one was shown, so clicking "💰 Pay
       Salary" / "📋 History" / "🏦 Advances" left the Employees panel on
       screen forever regardless of which tab was selected. */
    const panel = document.getElementById('pr-panel-'+t);
    if(panel) panel.style.display = (t===tab) ? '' : 'none';
  });
  renderPayrollTabContent();
}



function renderPayrollTabContent(){
  const wrap=document.getElementById('payroll-tab-content');
  if(!wrap)return;
  /* BUGFIX: this read window._payrollTab, but _payrollTab is declared with
     `let` at the top of this script block, which does NOT create a
     window.* property — window._payrollTab was always undefined, so this
     always fell back to 'employees' no matter which tab was actually
     clicked. The "💰 Pay Salary" and "📋 History" tabs could never be
     reached from the UI. Read the actual (module-scope) variable instead. */
  const tab=_payrollTab||'employees';
  if(tab==='employees') renderPayrollEmployees();
  else if(tab==='salary') renderPaySalaryForm(wrap);
  else if(tab==='history') renderSalaryHistory();
  else if(tab==='advances') renderPayrollAdvancesWrap();
}

function renderEmployeeList(wrap){
  const emps = DB.employees||[];
  if(!emps.length){
    wrap.innerHTML='<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;text-align:center;padding:40px;color:#9ca3af;">No employees added yet. Click ➕ Add Employee to start.</div>';
    return;
  }
  wrap.innerHTML=`<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
    <table style="width:100%;border-collapse:collapse;font-size:12px;">
      <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
        <th style="padding:10px 12px;text-align:left;">Name</th>
        <th style="padding:10px 12px;text-align:left;">Role</th>
        <th style="padding:10px 12px;text-align:right;">Salary (৳)</th>
        <th style="padding:10px 12px;text-align:left;">Join Date</th>
        <th style="padding:10px 12px;text-align:left;">Phone</th>
        <th style="padding:10px 12px;text-align:center;">Status</th>
        <th style="padding:10px 12px;text-align:center;">Actions</th>
      </tr></thead>
      <tbody>${emps.map((e,i)=>`<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
        <td style="padding:9px 12px;font-weight:700;color:#0f3d26;">${escHTML(e.name)}</td>
        <td style="padding:9px 12px;color:#6b7280;">${e.role||'—'}</td>
        <td style="padding:9px 12px;text-align:right;font-weight:800;color:#16a34a;">৳${pf(e.salary||0)}</td>
        <td style="padding:9px 12px;color:#6b7280;">${e.join||'—'}</td>
        <td style="padding:9px 12px;color:#6b7280;">${escHTML(e.phone||'—')}</td>
        <td style="padding:9px 12px;text-align:center;"><span style="background:${e.status==='Active'?'#f0fdf4':'#f9fafb'};color:${e.status==='Active'?'#16a34a':'#6b7280'};padding:2px 10px;border-radius:10px;font-size:10px;font-weight:700;">${e.status}</span></td>
        <td style="padding:9px 12px;text-align:center;">
          <button data-x-click="openPaySalaryFor(${e.id})" style="background:#f0fdf4;border:1px solid #bbf7d0;color:#16a34a;padding:3px 8px;border-radius:4px;font-size:10px;cursor:pointer;margin-right:4px;">💰 Pay</button>
          <button data-x-click="deleteEmployee(${e.id})" style="background:#fef2f2;border:1px solid #fecaca;color:#dc2626;padding:3px 8px;border-radius:4px;font-size:10px;cursor:pointer;">🗑️</button>
        </td>
      </tr>`).join('')}</tbody>
    </table>
  </div>`;
}

/* ═══════════════════════════════════════════════════════════════════════
   UNIFIED "pay/receive from bank account(s)" widget.
   Previously every payment screen (New Transaction, Salary Payment tab,
   Salary Payment modal, Suppliers quick-pay) had its own bespoke UI: the
   New Transaction form had a real account dropdown + working multi-bank
   split; the Salary Payment screens only had a "Payment Mode" *label*
   (Cash/Bank/Bkash) with no real account tied to it, so paying salary
   never actually moved money out of any bank; and the Suppliers quick-pay
   button was a bare prompt() with a free-text "mode" — no account field
   at all. None of the three routed through applyTxBalance(), so none of
   them (other than the main form) ever touched DB.banks.
   This factory renders ONE consistent widget (single-account dropdown by
   default, with a "split across multiple accounts" option identical to
   the New Transaction form's), and every payment screen below now mounts
   this same widget and saves through the same _executeSaveTx() pipeline
   that New Transaction uses — so a plain transaction, a salary payment,
   and a supplier quick-pay all move real bank balances the same way.
   ═══════════════════════════════════════════════════════════════════════ */
function createPayAccountWidget(container, requiredAmountFn){
  if(!container) return {isSplit:function(){return false;},validate:function(){return {ok:false,msg:'Payment widget failed to load.'};},recalc:function(){}};
  var rows=[{acc:'',amt:0}];
  var splitOn=false;
  var uid='payw'+Math.random().toString(36).slice(2,9);

  function bankBalOf(name){
    var b=(DB.banks||[]).filter(function(x){return x.name===name;})[0];
    return b?(parseFloat(b.bal)||0):0;
  }
  function accOptionsLocal(sel){
    return '<option value="">-- Select Account --</option>'+(DB.banks||[]).map(function(b){
      return '<option value="'+b.name+'"'+(sel===b.name?' selected':'')+'>'+b.name+' (৳'+pf(b.bal||0)+')</option>';
    }).join('');
  }
  function render(){
    container.innerHTML=
      '<div class="fg"><label class="lbl">Bank / Cash Account *</label>'+
      '<select class="fc" id="'+uid+'-single"'+(splitOn?' disabled style="background:#f3f4f6;"':'')+'>'+accOptionsLocal(rows[0]&&rows[0].acc)+'</select></div>'+
      '<label style="display:flex;align-items:center;gap:8px;font-size:12px;font-weight:700;color:#1e3a8a;cursor:pointer;margin:6px 0;">'+
      '<input type="checkbox" id="'+uid+'-toggle"'+(splitOn?' checked':'')+'> 🏦 Split across multiple accounts</label>'+
      '<div id="'+uid+'-rows" style="display:'+(splitOn?'block':'none')+';"></div>'+
      (splitOn?('<button type="button" id="'+uid+'-add" style="margin-top:6px;background:#2563eb;color:#fff;border:0;border-radius:6px;padding:6px 12px;font-size:11px;font-weight:700;cursor:pointer;">+ Add Account Line</button>'+
       '<div id="'+uid+'-sum" style="margin-top:8px;font-size:11px;font-weight:700;"></div>'):'');
    var toggle=document.getElementById(uid+'-toggle');
    toggle.addEventListener('change',function(){
      splitOn=this.checked;
      if(splitOn&&(!rows.length||(rows.length===1&&!rows[0].acc))) rows=[{acc:'',amt:0},{acc:'',amt:0}];
      render();
    });
    if(splitOn){
      renderRows();
      document.getElementById(uid+'-add').addEventListener('click',function(){rows.push({acc:'',amt:0});renderRows();});
    }else{
      document.getElementById(uid+'-single').addEventListener('change',function(){rows=[{acc:this.value,amt:0}];});
    }
  }
  function renderRows(){
    var host=document.getElementById(uid+'-rows'); if(!host) return;
    host.innerHTML=rows.map(function(r,i){
      var avail=bankBalOf(r.acc), short=r.acc&&(parseFloat(r.amt)||0)>avail;
      return '<div style="display:flex;gap:8px;align-items:center;margin-bottom:6px;flex-wrap:wrap;">'+
        '<select data-i="'+i+'" data-k="acc" style="flex:1;min-width:160px;padding:6px 8px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;">'+accOptionsLocal(r.acc)+'</select>'+
        '<input type="number" step="0.01" min="0" data-i="'+i+'" data-k="amt" value="'+((r.amt)?r.amt:'')+'" placeholder="Amount ৳" style="width:120px;padding:6px 8px;border:1px solid '+(short?'#dc2626':'#d1d5db')+';border-radius:6px;font-size:12px;">'+
        '<span style="font-size:11px;font-weight:700;color:'+(short?'#dc2626':'#16a34a')+';">'+(r.acc?(short?'⛔ Only ৳'+pf(avail)+' available':'✔ Available ৳'+pf(avail)):'')+'</span>'+
        '<button type="button" data-del="'+i+'" style="background:#fee2e2;color:#b91c1c;border:0;border-radius:4px;padding:4px 8px;cursor:pointer;">✕</button>'+
      '</div>';
    }).join('');
    Array.prototype.forEach.call(host.querySelectorAll('[data-i]'),function(el){
      el.addEventListener('input',onRowInput); el.addEventListener('change',onRowInput);
    });
    Array.prototype.forEach.call(host.querySelectorAll('[data-del]'),function(b){
      b.addEventListener('click',function(){rows.splice(+b.getAttribute('data-del'),1);renderRows();});
    });
    updateSum();
  }
  function onRowInput(e){
    var i=+e.target.getAttribute('data-i'), k=e.target.getAttribute('data-k');
    if(!rows[i]) return;
    rows[i][k]=(k==='acc')?e.target.value:(parseFloat(e.target.value)||0);
    renderRows();
  }
  function updateSum(){
    var need=parseFloat(requiredAmountFn())||0;
    var got=rows.reduce(function(s,r){return s+(parseFloat(r.amt)||0);},0);
    var sumEl=document.getElementById(uid+'-sum');
    if(sumEl) sumEl.innerHTML='Split total: <span style="color:'+(Math.abs(got-need)<0.01?'#16a34a':'#dc2626')+';">৳'+pf(got)+
      '</span> / Amount to pay: ৳'+pf(need)+(Math.abs(got-need)<0.01?' ✔ matched':' — must match before saving');
  }
  render();
  return {
    isSplit:function(){return splitOn;},
    recalc:function(){ if(splitOn) updateSum(); },
    validate:function(){
      var need=parseFloat(requiredAmountFn())||0;
      if(!splitOn){
        var sel=document.getElementById(uid+'-single');
        var acc=sel?sel.value:'';
        if(!acc) return {ok:false,msg:'Select a bank/cash account.'};
        if(need>0){
          var avail=bankBalOf(acc);
          if(avail<need) return {ok:false,msg:'⛔ "'+acc+'" has only ৳'+pf(avail)+' — cannot pay ৳'+pf(need)+' from it.'};
        }
        return {ok:true,acc:acc};
      }
      var total=0, byAcc={};
      for(var i=0;i<rows.length;i++){
        var r=rows[i], a=parseFloat(r.amt)||0;
        if(!r.acc&&!a) continue;
        if(!r.acc) return {ok:false,msg:'Select an account for every payment line.'};
        if(a<=0) return {ok:false,msg:'Enter an amount for account "'+r.acc+'".'};
        byAcc[r.acc]=(byAcc[r.acc]||0)+a; total+=a;
      }
      if(!total) return {ok:false,msg:'Add at least one account with an amount.'};
      for(var k in byAcc){
        if(byAcc[k]>bankBalOf(k)+0.001) return {ok:false,msg:'⛔ "'+k+'" has only ৳'+pf(bankBalOf(k))+' — cannot pay ৳'+pf(byAcc[k])+' from it.'};
      }
      if(need>0&&Math.abs(total-need)>0.01) return {ok:false,msg:'Split total ৳'+pf(total)+' does not match the amount ৳'+pf(need)+'.'};
      return {ok:true,payAccounts:rows.filter(function(r){return r.acc&&(parseFloat(r.amt)||0)>0;}).map(function(r){return {acc:r.acc,amt:parseFloat(r.amt)||0};})};
    }
  };
}


function submitSalaryPayment(){
  /* BUGFIX: this form's employee dropdown is #pay-emp-sel (this screen has
     its own IDs, separate from the #mPaySalary modal's #pay-emp), but this
     function read #pay-emp — an element that only exists in the OTHER,
     hidden modal. empIdx was therefore always empty and "Please select an
     employee" fired unconditionally; this form could never actually save a
     salary payment. */
  const empIdx=document.getElementById('pay-emp-sel')?.value;
  const month=document.getElementById('pay-month-sel')?.value;
  const date=document.getElementById('pay-date-sel')?.value;
  const basic=parseFloat(document.getElementById('pay-basic-amt')?.value)||0;
  const bonus=parseFloat(document.getElementById('pay-bonus-amt')?.value)||0;
  const deduct=parseFloat(document.getElementById('pay-deduct-amt')?.value)||0;
  const net=basic+bonus-deduct;
  const notes=document.getElementById('pay-notes-txt')?.value||'';
  if(empIdx===''||empIdx===undefined){toast('Please select an employee','w');return;}
  const emp=(DB.employees||[])[parseInt(empIdx)];
  if(!emp){toast('Employee not found','w');return;}
  if(!month){toast('Please select a month','w');return;}
  if(!date){toast('Please select a date','w');return;}
  if(net<=0){toast('Net payable must be greater than 0','w');return;}
  if(!window._paySalaryTabWidget){toast('Payment account widget not ready — reopen the Salary tab.','e');return;}
  const v=window._paySalaryTabWidget.validate();
  if(!v.ok){toast(v.msg,'e');return;}
  const tx={id:newId(),date,type:'Salary Payment',party:emp.name,ptype:'Employee',
    amount:net,amt:net,salaryMonth:month,note:notes||'Salary for '+month,desc:'Salary for '+month};
  if(v.payAccounts){tx.payAccounts=v.payAccounts;tx.acc=v.payAccounts[0].acc;tx.splitPayment=true;}
  else tx.acc=v.acc;
  if(!DB.salaryHistory) DB.salaryHistory=[];
  DB.salaryHistory.push({id:newId(),empId:emp.id,empName:emp.name,month,basic,bonus,deduct,net,
    mode:tx.payAccounts?'Split':'Bank/Cash',account:tx.acc,payAccounts:tx.payAccounts||null});
  _executeSaveTx(tx,0);
  logAudit('SALARY','Payroll','Paid ৳'+net+' to '+emp.name+' for '+month);
  toast('✅ Salary of ৳'+net.toLocaleString('en-IN')+' paid to '+emp.name,'s');
  renderPayroll();
}
function renderPaySalaryForm(wrap){
  if(!wrap) wrap=document.getElementById('payroll-tab-content');
  if(!wrap) return;
  const employees=(DB.employees||[]).filter(e=>e.status==='Active');
  const today=new Date().toISOString().split('T')[0];
  const thisMonth=today.substring(0,7);
  wrap.innerHTML=`<div style="background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:20px;max-width:600px;">
    <h3 style="font-size:15px;font-weight:800;color:#7c3aed;margin-bottom:16px;">💰 Process Salary Payment</h3>
    <div style="display:grid;gap:12px;">
      <div><label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Employee *</label>
        <select id="pay-emp-sel" data-x-change="fillSalaryAmountTab()" style="width:100%;padding:9px 12px;border:1.5px solid #d1d5db;border-radius:8px;font-size:13px;">
          <option value="">-- Select Employee --</option>
          ${employees.map((e,i)=>`<option value="${i}" data-salary="${e.salary||0}">${escHTML(e.name)} — ৳${(e.salary||0).toLocaleString('en-IN')}/month</option>`).join('')}
        </select></div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;">
        <div><label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Month *</label>
          <input type="month" id="pay-month-sel" value="${thisMonth}" style="width:100%;padding:9px 12px;border:1.5px solid #d1d5db;border-radius:8px;font-size:13px;"></div>
        <div><label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Payment Date *</label>
          <input type="date" id="pay-date-sel" value="${today}" style="width:100%;padding:9px 12px;border:1.5px solid #d1d5db;border-radius:8px;font-size:13px;"></div>
      </div>
      <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px;">
        <div><label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Basic Salary (৳)</label>
          <input type="number" id="pay-basic-amt" placeholder="0" data-x-input="calcNetPayAmt()" style="width:100%;padding:9px 12px;border:1.5px solid #d1d5db;border-radius:8px;font-size:13px;"></div>
        <div><label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Bonus (৳)</label>
          <input type="number" id="pay-bonus-amt" value="0" data-x-input="calcNetPayAmt()" style="width:100%;padding:9px 12px;border:1.5px solid #d1d5db;border-radius:8px;font-size:13px;"></div>
        <div><label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Deductions (৳)</label>
          <input type="number" id="pay-deduct-amt" value="0" data-x-input="calcNetPayAmt()" style="width:100%;padding:9px 12px;border:1.5px solid #d1d5db;border-radius:8px;font-size:13px;"></div>
      </div>
      <div><label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Net Payable (৳)</label>
        <input type="number" id="pay-net-amt" readonly style="width:100%;padding:9px 12px;border:1.5px solid #bbf7d0;border-radius:8px;font-size:14px;font-weight:800;background:#f0fdf4;color:#16a34a;"></div>
      <div id="pay-acc-widget-tab" style="border-top:2px dashed #7c3aed;padding-top:10px;"></div>
      <div><label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Notes</label>
        <input id="pay-notes-txt" placeholder="Optional notes..." style="width:100%;padding:9px 12px;border:1.5px solid #d1d5db;border-radius:8px;font-size:13px;"></div>
      <button class="btn" style="background:#16a34a;color:#fff;padding:12px;font-size:14px;font-weight:700;width:100%;" data-x-click="submitSalaryPayment()">✅ Process Payment</button>
    </div>
  </div>`;
  window._paySalaryTabWidget=createPayAccountWidget(document.getElementById('pay-acc-widget-tab'),function(){
    return parseFloat(document.getElementById('pay-net-amt')?.value)||0;
  });
}
/* This tab's own employee-select / net-pay handlers — kept separate from
   fillSalaryAmount()/calcNetPay() below, which belong to the #mPaySalary
   modal and read that modal's #pay-emp/#pay-basic/etc IDs. Reusing those
   here previously meant this form's inputs silently updated the OTHER
   (hidden) form instead of this one, and Net Payable never changed. */
function fillSalaryAmountTab(){
  const idx=document.getElementById('pay-emp-sel')?.value;
  const employees=(DB.employees||[]).filter(e=>e.status==='Active');
  const emp=(idx!==''&&idx!==undefined)?employees[parseInt(idx)]:null;
  if(emp){
    const el=document.getElementById('pay-basic-amt');
    if(el) el.value=emp.salary||0;
    calcNetPayAmt();
  }
}
function calcNetPayAmt(){
  const basic=parseFloat(document.getElementById('pay-basic-amt')?.value)||0;
  const bonus=parseFloat(document.getElementById('pay-bonus-amt')?.value)||0;
  const deduct=parseFloat(document.getElementById('pay-deduct-amt')?.value)||0;
  const net=basic+bonus-deduct;
  const netEl=document.getElementById('pay-net-amt');
  if(netEl) netEl.value=net;
  if(window._paySalaryTabWidget&&window._paySalaryTabWidget.recalc) window._paySalaryTabWidget.recalc();
}

function renderSalaryHistory(wrap){
  wrap = wrap || document.getElementById('pr-panel-salary-history');
  if(!wrap) return;
  const hist = (DB.salaryHistory||[]).slice().reverse();
  if(!hist.length){
    wrap.innerHTML='<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;text-align:center;padding:40px;color:#9ca3af;">No salary payments recorded yet.</div>';
    return;
  }
  wrap.innerHTML=`<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
    <table style="width:100%;border-collapse:collapse;font-size:12px;">
      <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
        <th style="padding:10px 12px;text-align:left;">Month</th>
        <th style="padding:10px 12px;text-align:left;">Employee</th>
        <th style="padding:10px 12px;text-align:right;">Basic</th>
        <th style="padding:10px 12px;text-align:right;">Bonus</th>
        <th style="padding:10px 12px;text-align:right;">Deduction</th>
        <th style="padding:10px 12px;text-align:right;">Net Pay</th>
        <th style="padding:10px 12px;text-align:left;">Mode</th>
      </tr></thead>
      <tbody>${hist.map((h,i)=>`<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
        <td style="padding:9px 12px;font-weight:700;">${h.month||'—'}</td>
        <td style="padding:9px 12px;">${h.empName||'—'}</td>
        <td style="padding:9px 12px;text-align:right;">৳${pf(h.basic||0)}</td>
        <td style="padding:9px 12px;text-align:right;color:#16a34a;">৳${pf(h.bonus||0)}</td>
        <td style="padding:9px 12px;text-align:right;color:#dc2626;">৳${pf(h.deduct||0)}</td>
        <td style="padding:9px 12px;text-align:right;font-weight:800;color:#0f3d26;">৳${pf(h.net||0)}</td>
        <td style="padding:9px 12px;color:#6b7280;">${h.mode||'—'}</td>
      </tr>`).join('')}</tbody>
    </table>
  </div>`;
}







function openPaySalaryModal(){
  const empSel = document.getElementById('pay-emp');
  if(empSel){
    empSel.innerHTML='<option value="">-- Select --</option>';
    (DB.employees||[]).filter(e=>e.status==='Active').forEach(e=>{
      const o=document.createElement('option'); o.value=e.id; o.textContent=e.name+' (৳'+pf(e.salary)+')'; empSel.appendChild(o);
    });
  }
  const now = new Date();
  document.getElementById('pay-month').value=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`;
  document.getElementById('pay-basic').value='';
  document.getElementById('pay-bonus').value='0';
  document.getElementById('pay-deduct').value='0';
  document.getElementById('pay-net').value='';
  /* BUGFIX: the old "Account" dropdown here (#pay-account) was populated
     from DB.masterData.banks — a name-only lookup list — not DB.banks (the
     array with real .bal balances that applyTxBalance() actually reads).
     And nothing on this modal ever called applyTxBalance() at all, so
     picking an account never moved money out of it. Mount the same
     account(+split) widget the New Transaction form uses, and read #pay-net
     live so its "amount to pay" always matches Net Payable. */
  window._paySalaryModalWidget=createPayAccountWidget(document.getElementById('pay-acc-widget-modal'),function(){
    return parseFloat(document.getElementById('pay-net')?.value)||0;
  });
  document.getElementById('mPaySalary').style.display='flex';
}

function openPaySalaryFor(empId){
  openPaySalaryModal();
  setTimeout(()=>{
    const sel = document.getElementById('pay-emp');
    if(sel){ sel.value=empId; fillSalaryAmount(); }
  },100);
}

function fillSalaryAmount(){
  const empId = document.getElementById('pay-emp')?.value; /* FIX O: was parseInt() — see note on autoFillSalary(). */
  /* BUGFIX: FIX O's own note says employee ids became UUID strings after a
     migration, but this codebase's actual saveEmployee() still generates
     ids with newId() (a Date.now()-based NUMBER) — so e.id is a number for
     any employee added through this app, while empId (a <select> value) is
     always a string. Bare `===` matched neither case reliably; comparing
     e.id===empId failed for every numeric-id employee, so this never
     actually found anyone and the Basic Salary field never auto-filled.
     String() on both sides matches regardless of which id style is in use. */
  const emp = (DB.employees||[]).find(e=>String(e.id)===String(empId));
  if(emp){
    document.getElementById('pay-basic').value=emp.salary||0;
    calcNetPay();
  }
}

function calcNetPay(){
  const basic = parseFloat(document.getElementById('pay-basic')?.value)||0;
  const bonus = parseFloat(document.getElementById('pay-bonus')?.value)||0;
  const deduct = parseFloat(document.getElementById('pay-deduct')?.value)||0;
  const net = basic+bonus-deduct;
  const netEl = document.getElementById('pay-net');
  if(netEl) netEl.value=net;
  if(window._paySalaryModalWidget&&window._paySalaryModalWidget.recalc) window._paySalaryModalWidget.recalc();
}

// Auto-calc net pay on input
['pay-basic','pay-bonus','pay-deduct'].forEach(id=>{
  setTimeout(()=>{
    const el=document.getElementById(id);
    if(el) el.addEventListener('input',calcNetPay);
  },500);
});

function processSalaryPayment(){
  const empId = document.getElementById('pay-emp')?.value; /* FIX O: was parseInt() — see note on autoFillSalary(). */
  // Same id-type mismatch as fillSalaryAmount() above — see BUGFIX note there.
  const emp = (DB.employees||[]).find(e=>String(e.id)===String(empId));
  if(!emp){ alert('Select an employee'); return; }
  const basic = parseFloat(document.getElementById('pay-basic').value)||0;
  const bonus = parseFloat(document.getElementById('pay-bonus').value)||0;
  const deduct = parseFloat(document.getElementById('pay-deduct').value)||0;
  const net = basic+bonus-deduct;
  const month = document.getElementById('pay-month').value;
  if(!net){ alert('Net pay cannot be zero'); return; }
  if(!window._paySalaryModalWidget){ alert('Payment account widget not ready — reopen this dialog.'); return; }
  const v=window._paySalaryModalWidget.validate();
  if(!v.ok){ alert(v.msg); return; }
  const tx={
    id:newId(), date:new Date().toISOString().split('T')[0],
    type:'Salary Payment', party:emp.name, ptype:'Employee', partyType:'Employee',
    amount:net, amt:net, desc:'Salary for '+month
  };
  if(v.payAccounts){ tx.payAccounts=v.payAccounts; tx.acc=v.payAccounts[0].acc; tx.splitPayment=true; }
  else tx.acc=v.acc;
  if(!DB.salaryHistory) DB.salaryHistory=[];
  DB.salaryHistory.push({ id:newId(), empId, empName:emp.name, month, basic, bonus, deduct, net,
    mode:tx.payAccounts?'Split':'Bank/Cash', account:tx.acc, payAccounts:tx.payAccounts||null });
  logAudit('CREATE','Payroll','Salary paid to '+emp.name+' for '+month+': ৳'+pf(net));
  _executeSaveTx(tx,0);
  closeModal('mPaySalary'); renderPayroll();
  alert('✅ Salary of ৳'+pf(net)+' paid to '+emp.name);
}


