// FEATURE 29: Stock Alerts
// ══════════════════════════════════════════════════════════════
function renderStockAlerts(){
  const products = DB.products||[];

  // Calculate stock from transactions
  const stockMap = {};
  products.forEach(p=>{ stockMap[p.name]={...p, computed:p.qty||0}; });

  (DB.tx||[]).forEach(t=>{
    const prod = t.prod;
    if(!prod) return;
    if(!stockMap[prod]) stockMap[prod]={name:prod,computed:0,minStock:50,unit:'KG'};
    const qty = parseFloat(t.qty)||0;
    if(isCogsTx(t)) stockMap[prod].computed+=qty;
    if(['Sale','Sales Return'].includes(t.type)) stockMap[prod].computed-=qty;
    if(t.type==='Purchase Return') stockMap[prod].computed-=qty;
  });

  const allProds = Object.values(stockMap);
  const outOfStock = allProds.filter(p=>p.computed<=0);
  const lowStock = allProds.filter(p=>p.computed>0&&p.computed<=(p.minStock||50));
  const healthy = allProds.filter(p=>p.computed>(p.minStock||50));

  // KPIs
  const kpiEl = document.getElementById('sa-kpis');
  if(kpiEl){
    kpiEl.innerHTML = [
      {label:'Total Products',val:allProds.length,icon:'📦',color:'#2563eb'},
      {label:'Out of Stock',val:outOfStock.length,icon:'🚨',color:'#dc2626'},
      {label:'Low Stock',val:lowStock.length,icon:'⚠️',color:'#d97706'},
      {label:'Healthy Stock',val:healthy.length,icon:'✅',color:'#16a34a'}
    ].map(k=>`<div style="background:linear-gradient(135deg,${k.color},${k.color}cc);color:#fff;border-radius:10px;padding:14px;display:flex;align-items:center;gap:12px;">
      <div style="font-size:26px;">${k.icon}</div>
      <div>
        <div style="font-size:22px;font-weight:900;">${k.val}</div>
        <div style="font-size:10px;opacity:.8;">${escHTML(k.label)}</div>
      </div>
    </div>`).join('');
  }

  function renderAlertList(elId, list, emptyMsg, color){
  const el=document.getElementById(elId);
  if(!el)return;
  if(!list||!list.length){
    el.innerHTML=`<div style="text-align:center;padding:16px;color:#9ca3af;font-size:12px;">${emptyMsg||'No items.'}</div>`;
    return;
  }
  el.innerHTML=list.map((item,i)=>`
    <div style="display:flex;align-items:flex-start;gap:10px;padding:10px 14px;background:${color||'#fef9c3'}22;border-left:4px solid ${color||'#d97706'};border-radius:0 8px 8px 0;margin-bottom:8px;">
      <span style="font-size:14px;">⚠️</span>
      <div style="flex:1;">
        <div style="font-size:12px;color:#374151;font-weight:600;">${typeof item==='string'?item:(item.msg||item.message||item.text||JSON.stringify(item))}</div>
        ${item.ts||item.time?`<div style="font-size:10px;color:#9ca3af;margin-top:2px;">${item.ts||item.time}</div>`:''}
      </div>
      <button data-x-click="dismissAlert(${i})" style="background:none;border:none;cursor:pointer;color:#9ca3af;font-size:14px;padding:0;">✕</button>
    </div>`).join('');
}

  renderAlertList('sa-outofstock', outOfStock, '✅ No out-of-stock products!', '#dc2626');
  renderAlertList('sa-lowstock', lowStock, '✅ No low-stock products!', '#d97706');

  // All products table
  const allEl = document.getElementById('sa-all');
  if(!allEl) return;
  if(!allProds.length){ allEl.innerHTML='<div style="text-align:center;padding:30px;color:#9ca3af;">No products found. Add products in the Inventory section.</div>'; return; }

  allEl.innerHTML=`<table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:#f9fafb;border-bottom:2px solid #e5e7eb;">
      <th style="padding:9px 12px;text-align:left;">Product</th>
      <th style="padding:9px 12px;text-align:right;">Current Stock</th>
      <th style="padding:9px 12px;text-align:right;">Min Stock</th>
      <th style="padding:9px 12px;text-align:left;">Unit</th>
      <th style="padding:9px 12px;text-align:center;">Status</th>
      <th style="padding:9px 12px;text-align:left;">Stock Bar</th>
    </tr></thead>
    <tbody>${allProds.map((p,i)=>{
      let status='Healthy',scolor='#16a34a';
      if(p.computed<=0){status='Out of Stock';scolor='#dc2626';}
      else if(p.computed<=(p.minStock||50)){status='Low Stock';scolor='#d97706';}
      const minS = p.minStock||50;
      const barPct = minS>0?Math.min((p.computed/minS)*100,100).toFixed(0):0;
      return `<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
        <td style="padding:8px 12px;font-weight:700;">${escHTML(p.name)}</td>
        <td style="padding:8px 12px;text-align:right;font-weight:800;color:${scolor};">${pf(p.computed)}</td>
        <td style="padding:8px 12px;text-align:right;color:#6b7280;">${pf(minS)}</td>
        <td style="padding:8px 12px;color:#6b7280;">${p.unit||'KG'}</td>
        <td style="padding:8px 12px;text-align:center;"><span style="background:${scolor}22;color:${scolor};padding:2px 8px;border-radius:8px;font-size:10px;font-weight:700;">${status}</span></td>
        <td style="padding:8px 12px;">
          <div style="background:#f3f4f6;border-radius:4px;height:8px;overflow:hidden;">
            <div style="background:${scolor};height:100%;width:${barPct}%;border-radius:4px;"></div>
          </div>
        </td>
      </tr>`;
    }).join('')}</tbody>
  </table>`;
}


