let _obTab = 'customers';

function setObTab(tab){
  _obTab = tab;
  ['customers','banks','partners','assets','suppliers'].forEach(t=>{
    const btn = document.getElementById('obtab-'+t);
    if(btn){
      btn.style.background = t===tab?'linear-gradient(135deg,#16a34a,#15803d)':'#f9fafb';
      btn.style.color = t===tab?'#fff':'#374151';
    }
  });
  renderObTabContent();
}

function renderOpeningBal(){
  renderOpenBal();
