function saveOpeningBalances(){
  if(!DB.openingBal) DB.openingBal={customers:{},banks:{},partners:{},assets:{},suppliers:{}};
  document.querySelectorAll('.ob-input').forEach(inp=>{
    const key = inp.dataset.key;
    const section = inp.dataset.section;
    if(!DB.openingBal[section]) DB.openingBal[section]={};
    if(!DB.openingBal[section][key]) DB.openingBal[section][key]={};
    DB.openingBal[section][key].balance = parseFloat(inp.value)||0;
  });
  document.querySelectorAll('.ob-notes').forEach(inp=>{
    const key = inp.dataset.key;
    const section = inp.dataset.section;
    if(!DB.openingBal[section]) DB.openingBal[section]={};
    if(!DB.openingBal[section][key]) DB.openingBal[section][key]={};
    DB.openingBal[section][key].notes = inp.value;
  });
  logAudit('UPDATE','Opening Balance','Saved opening balances for '+_obTab);
  saveDB();
  alert('✅ Opening balances saved successfully!');
}


// FEATURE 31: VAT Management
function renderVAT(){
  const today = new Date().toISOString().split('T')[0];
  const fromEl = document.getElementById('vat-from');
  const toEl = document.getElementById('vat-to');
  if(!fromEl.value) fromEl.value = today.slice(0,7)+'-01';
  if(!toEl.value) toEl.value = today;
  const from = fromEl.value, to = toEl.value;
  const vatRate = parseFloat(document.getElementById('vat-rate')?.value)||15;
  const rate = vatRate/100;

  /* FIX J: substring matching (k.split(' ')[0]) meant 'Sale' matched 'Sales
     Return', 'Sales Advance' and 'Sales Receipt' too — overstating VAT
     collected. This is a second, separate VAT module from FIX G (a merge
     duplicate); both now use the same canonical isRevenueTx/isCogsTx so they
     agree with each other and with the Ledger. */
  const txns = (DB.tx||[]).filter(t=>_dk(t.date)>=_dk(from) && _dk(t.date)<=_dk(to));
  const sales = txns.filter(t=>window.isRevenueTx(t));
  const purchases = txns.filter(t=>window.isCogsTx(t));

  const salesAmt = sales.reduce((s,t)=>s+txAmt(t),0);
  const purchAmt = purchases.reduce((s,t)=>s+txAmt(t),0);
  const vatCollected = salesAmt * rate;
  const vatPaid = purchAmt * rate;
  const netVAT = vatCollected - vatPaid;

  const sumEl = document.getElementById('vat-summary');
  if(sumEl){
    sumEl.innerHTML = [
      {label:'VAT Collected (Sales)',val:vatCollected,icon:'📥',color:'#16a34a'},
      {label:'VAT Paid (Purchases)',val:vatPaid,icon:'📤',color:'#dc2626'},
      {label:'Net VAT Payable',val:netVAT,icon:'🏛️',color:netVAT>=0?'#2563eb':'#7c3aed'},
      {label:'VAT Rate Applied',val:vatRate,icon:'%',color:'#f59e0b',isPercent:true}
    ].map(s=>`<div style="background:#fff;border:2px solid ${s.color}22;border-radius:10px;padding:16px;text-align:center;">
      <div style="font-size:22px;">${s.icon}</div>
      <div style="font-size:18px;font-weight:900;color:${s.color};">${s.isPercent?s.val+'%':'৳'+pf(Math.abs(s.val))}</div>
      <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(s.label)}</div>
    </div>`).join('');
  }

  const body = document.getElementById('vat-body');
  if(!body) return;
  const rows = [...sales.map(t=>({...t,vatType:'Output',vatAmt:txAmt(t)*rate})),
                ...purchases.map(t=>({...t,vatType:'Input',vatAmt:txAmt(t)*rate}))];
  rows.sort((a,b)=>a.date>b.date?1:-1);

  if(!rows.length){
    body.innerHTML='<div style="text-align:center;padding:30px;color:#9ca3af;">No transactions in selected period.</div>';
    return;
  }
  body.innerHTML=`<table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
      <th style="padding:9px 12px;text-align:left;">Date</th>
      <th style="padding:9px 12px;text-align:left;">Type</th>
      <th style="padding:9px 12px;text-align:left;">Party</th>
      <th style="padding:9px 12px;text-align:right;">Amount (৳)</th>
      <th style="padding:9px 12px;text-align:right;">VAT (৳)</th>
      <th style="padding:9px 12px;text-align:center;">VAT Type</th>
    </tr></thead>
    <tbody>${rows.map((t,i)=>`<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
      <td style="padding:8px 12px;color:#6b7280;">${t.date||'—'}</td>
      <td style="padding:8px 12px;font-weight:600;">${t.type||'—'}</td>
      <td style="padding:8px 12px;">${escHTML(t.party||'—')}</td>
      <td style="padding:8px 12px;text-align:right;font-weight:700;">৳${pf(t.amount||0)}</td>
      <td style="padding:8px 12px;text-align:right;color:${t.vatType==='Output'?'#16a34a':'#dc2626'};font-weight:700;">৳${pf(t.vatAmt)}</td>
      <td style="padding:8px 12px;text-align:center;"><span style="background:${t.vatType==='Output'?'#dcfce7':'#fee2e2'};color:${t.vatType==='Output'?'#16a34a':'#dc2626'};padding:2px 8px;border-radius:10px;font-size:11px;font-weight:700;">${t.vatType}</span></td>
    </tr>`).join('')}</tbody>
  </table>`;
}
function printVAT(){ printPageViaLetterhead('pg-vatmanagement','VAT Report'); logAudit('PRINT','VAT Management','Printed VAT report'); }


// FEATURE 32: Delivery Challan

function newChallan(){
  const fa = document.getElementById('challan-form-area');
  if(fa) fa.style.display='block';
  const today = new Date().toISOString().split('T')[0];
  // FIX 2 (security/refactor audit): this form's fields now have unique
  // chfa-* ids (previously ch-*, duplicated with the #challan-modal popup's
  // fields), so plain getElementById is safe here again.
  const g = id => document.getElementById(id);
  const dEl=g('chfa-date'); if(dEl) dEl.value=today;
  const nEl=g('chfa-no');   if(nEl) nEl.value='CH-'+Date.now().toString().slice(-6);

  const partySel=g('chfa-party');
  if(partySel && partySel.options && partySel.options.length<=1){
    (DB.masterData?.parties||MASTER.parties||[]).forEach(p=>{const o=document.createElement('option');o.value=p;o.textContent=p;partySel.appendChild(o);});
  }
  const prodSel=g('chfa-product');
  if(prodSel && prodSel.options && prodSel.options.length<=1){
    (DB.masterData?.products||MASTER.products||[]).forEach(p=>{const o=document.createElement('option');o.value=p;o.textContent=p;prodSel.appendChild(o);});
  }
  const destSel=g('ch-dest');
  if(destSel && destSel.options && destSel.options.length<=1){
    (DB.masterData?.locations||MASTER.locations||[]).forEach(l=>{const o=document.createElement('option');o.value=l;o.textContent=l;destSel.appendChild(o);});
  }
  populatePartyBankPicker('chfa-party','chfa-bankaccount','chfa-bankaccount-custom');
}

/* ADDED (2026-08-27, workflow audit): Orders and Delivery Challan were two
   entirely separate modules — creating a challan for an order meant
   retyping the customer, product, quantity, truck and bank account by
   hand. This opens the same live "+ New Challan" form (newChallan(), see
   above) and pre-fills it from the order; the user still reviews and
   clicks Save themselves, same as any other new challan. */
function createChallanFromOrder(orderId){
  const o=(DB.orders||[]).find(x=>String(x.id)===String(orderId));
  if(!o){ if(typeof toast==='function') toast('Order not found.','e'); return; }
  nav('deliverychallan');
  newChallan();
  const g=id=>document.getElementById(id);

  const partySel=g('chfa-party');
  if(partySel && o.customerName){
    const hasOption=Array.from(partySel.options).some(opt=>opt.value===o.customerName);
    if(!hasOption){ const opt=document.createElement('option'); opt.value=o.customerName; opt.textContent=o.customerName; partySel.appendChild(opt); }
    partySel.value=o.customerName;
  }
  const prodSel=g('chfa-product');
  if(prodSel && o.productName){
    const hasOption=Array.from(prodSel.options).some(opt=>opt.value===o.productName);
    if(!hasOption){ const opt=document.createElement('option'); opt.value=o.productName; opt.textContent=o.productName; prodSel.appendChild(opt); }
    prodSel.value=o.productName;
  }
  const qtyEl=g('chfa-qty'); if(qtyEl && o.qty) qtyEl.value=o.qty;
  const truckEl=g('chfa-truck'); if(truckEl && o.truckId) truckEl.value=o.truckId;
  const destSel=g('ch-dest');
  if(destSel && o.companyLocation){
    const hasOption=Array.from(destSel.options).some(opt=>opt.value===o.companyLocation);
    if(!hasOption){ const opt=document.createElement('option'); opt.value=o.companyLocation; opt.textContent=o.companyLocation; destSel.appendChild(opt); }
    destSel.value=o.companyLocation;
  }
  const remarksEl=g('ch-remarks'); if(remarksEl) remarksEl.value='From Order '+o.id;

  // Re-populate the bank picker now that the party is set, preselecting
  // the same bank account the order used (if any).
  populatePartyBankPicker('chfa-party','chfa-bankaccount','chfa-bankaccount-custom', o.bankAccount||'');

  if(typeof toast==='function') toast('Challan pre-filled from the order — review and save.','s');
  const formArea=g('challan-form-area');
  if(formArea) formArea.scrollIntoView({behavior:'smooth',block:'start'});
}







/* REMOVED (2026-08-27, workflow audit): renderChallan() populated
   #challan-list, but was only ever wired to nav('challan') — a page
   ('challan'/#pg-challan) with no sidebar item, button, or link anywhere,
   so it never ran. The Delivery Challan page you actually use is
   nav('deliverychallan') -> renderDeliveryChallan() -> #dc-body, which is
   untouched by this removal. The permanently-empty #challan-list box that
   sat on the live page (since nothing else populated it) has also been
   removed — see the "Challan List" card near #challan-form-area. */


// FEATURE 33: Invoice Generator

function newInvoice(){
  const fa=document.getElementById('inv-form-area');
  fa.style.display='block';
  const today=new Date().toISOString().split('T')[0];
  document.getElementById('inv-date').value=today;
  const due=new Date(); due.setDate(due.getDate()+30);
  document.getElementById('inv-due').value=due.toISOString().split('T')[0];
  document.getElementById('inv-no').value='INV-'+Date.now().toString().slice(-6);
  document.getElementById('inv-total').value='৳0.00';

  // Section 4: reset deductions to defaults for a fresh invoice
  const bagRateEl=document.getElementById('inv-bag-deduct-rate'); if(bagRateEl) bagRateEl.value='0';
  const unrealizedEl=document.getElementById('inv-unrealized'); if(unrealizedEl) unrealizedEl.value='0';
  const customNameEl=document.getElementById('inv-custom-deduct-name'); if(customNameEl) customNameEl.value='Other Deduction';
  const customValEl=document.getElementById('inv-custom-deduct-val'); if(customValEl) customValEl.value='0';
  calcInvTotal();

  const ps=document.getElementById('inv-party');
  if(ps && ps.options.length<=1){
    (DB.masterData?.parties||MASTER.parties||[]).forEach(p=>{const o=document.createElement('option');o.value=p;o.textContent=p;ps.appendChild(o);});
  }
  const prs=document.getElementById('inv-product');
  if(prs && prs.options.length<=1){
    (DB.masterData?.products||MASTER.products||[]).forEach(p=>{const o=document.createElement('option');o.value=p;o.textContent=p;prs.appendChild(o);});
  }
}

function fillInvRate(){
  const prod=document.getElementById('inv-product')?.value||'';
  const txns=(DB.tx||[]).filter(t=>t.product===prod && t.rate);
  if(txns.length){
    const lastRate=parseFloat(txns[txns.length-1].rate)||0;
    if(lastRate) document.getElementById('inv-rate').value=lastRate;
  }
  calcInvTotal();
}

function fillInvParty(){
  const party=document.getElementById('inv-party')?.value||'';
  if(!party) return;
  const txns=(DB.tx||[]).filter(t=>t.party===party && t.product);
  if(txns.length){
    const last=txns[txns.length-1];
    const prs=document.getElementById('inv-product');
    if(prs && last.product && [...prs.options].some(o=>o.value===last.product)){
      prs.value=last.product;
      fillInvRate();
    }
  }
}

// Section 4: Financial Sales Deductions & Adjustments — reads the
// bag-deduction / unrealized / custom-deduction inputs and writes the
// readonly amount fields + total. Shared by calcInvTotal() and saveInvoice()
// so the on-screen numbers and the saved invoice always agree.
function calcInvDeductions(qty){
  const bagRate=parseFloat(document.getElementById('inv-bag-deduct-rate')?.value)||0;
  const unrealized=parseFloat(document.getElementById('inv-unrealized')?.value)||0;
  const customName=(document.getElementById('inv-custom-deduct-name')?.value||'Other Deduction').trim()||'Other Deduction';
  const customVal=parseFloat(document.getElementById('inv-custom-deduct-val')?.value)||0;

  const bagAmt=bagRate*qty;
  const totalDeduct=bagAmt+unrealized+customVal;

  const bagEl=document.getElementById('inv-bag-deduct-amt');
  const unrealizedEl=document.getElementById('inv-unrealized-amt');
  const customLabelEl=document.getElementById('inv-custom-deduct-label');
  const customAmtEl=document.getElementById('inv-custom-deduct-amt');
  const totalDeductEl=document.getElementById('inv-total-deduct');
  if(bagEl) bagEl.textContent='৳'+pf(bagAmt);
  if(unrealizedEl) unrealizedEl.textContent='৳'+pf(unrealized);
  if(customLabelEl) customLabelEl.textContent=customName;
  if(customAmtEl) customAmtEl.textContent='৳'+pf(customVal);
  if(totalDeductEl) totalDeductEl.textContent='৳'+pf(totalDeduct);

  return {bagAmt,unrealized,customName,customVal,totalDeduct};
}

function calcInvTotal(){
  const qty=parseFloat(document.getElementById('inv-qty')?.value)||0;
  const rate=parseFloat(document.getElementById('inv-rate')?.value)||0;
  const disc=parseFloat(document.getElementById('inv-disc')?.value)||0;
  const vatPct=parseFloat(document.getElementById('inv-vat')?.value)||0;
  const sub=qty*rate;
  const afterDisc=sub-disc;
  const vatAmt=afterDisc*(vatPct/100);
  const total=afterDisc+vatAmt;
  const el=document.getElementById('inv-total');
  if(el) el.value='৳'+pf(total);

  const {totalDeduct}=calcInvDeductions(qty);
  const netAmt=total-totalDeduct;
  const netEl=document.getElementById('inv-net-amt');
  if(netEl) netEl.textContent='৳'+pf(netAmt);
}

function saveInvoice(){
  const qty=parseFloat(document.getElementById('inv-qty')?.value)||0;
  const rate=parseFloat(document.getElementById('inv-rate')?.value)||0;
  const disc=parseFloat(document.getElementById('inv-disc')?.value)||0;
  const vatPct=parseFloat(document.getElementById('inv-vat')?.value)||0;
  const sub=qty*rate; const afterDisc=sub-disc;
  const vatAmt=afterDisc*(vatPct/100); const total=afterDisc+vatAmt;
  // Section 4: Financial Sales Deductions & Adjustments
  const {bagAmt,unrealized,customName,customVal,totalDeduct}=calcInvDeductions(qty);
  const netAmt=parseFloat((total-totalDeduct).toFixed(2));
  const inv={
    id:newId(),
    no:document.getElementById('inv-no')?.value||'',
    date:document.getElementById('inv-date')?.value||'',
    due:document.getElementById('inv-due')?.value||'',
    party:document.getElementById('inv-party')?.value||'',
    product:document.getElementById('inv-product')?.value||'',
    qty,unit:document.getElementById('inv-unit')?.value||'KG',
    rate,disc,vatPct,vatAmt,total,
    bagDeductRate:parseFloat(document.getElementById('inv-bag-deduct-rate')?.value)||0,
    bagDeductAmt:bagAmt,
    unrealized,
    customDeductName:customName,
    customDeductVal:customVal,
    totalDeduct,
    netAmt,
    mode:document.getElementById('inv-mode')?.value||'Cash',
    notes:document.getElementById('inv-notes')?.value||'',
    status:'Unpaid'
  };
  if(!inv.party||!inv.product||!inv.qty){alert('⚠️ Fill Party, Product and Quantity');return;}
  DB.invoices.unshift(inv);
  saveDB();
  document.getElementById('inv-form-area').style.display='none';
  renderInvoiceGen();
  logAudit('CREATE','Invoice','Created invoice '+inv.no+' for '+inv.party);
}

