    <div style="background:#f9fafb;border:1px solid #e5e7eb;border-radius:8px;padding:12px 14px;min-width:180px;">
      <div style="font-size:10px;font-weight:700;color:#6b7280;text-transform:uppercase;">Invoice</div>
      <div style="font-size:14px;font-weight:700;margin-top:4px;">${inv.no}</div>
      <div style="font-size:11px;color:#6b7280;margin-top:2px;">Date: ${inv.date} &nbsp;|&nbsp; Due: ${inv.due||'—'}</div></div>
    <div style="background:#f9fafb;border:1px solid #e5e7eb;border-radius:8px;padding:12px 14px;min-width:140px;">
      <div style="font-size:10px;font-weight:700;color:#6b7280;text-transform:uppercase;">Status / Mode</div>
      <div style="font-size:14px;font-weight:800;margin-top:4px;color:${inv.status==='Paid'?'#16a34a':'#dc2626'};">${inv.status}</div>
      <div style="font-size:11px;color:#6b7280;margin-top:2px;">${inv.mode||'—'}</div></div>
  </div>
  <table style="width:100%;border-collapse:collapse;margin:12px 0;">
    <thead><tr>
      <th style="background:#0f3d26;color:#fff;padding:9px 12px;text-align:left;font-size:12px;">#</th>
      <th style="background:#0f3d26;color:#fff;padding:9px 12px;text-align:left;font-size:12px;">Product / Description</th>
      <th style="background:#0f3d26;color:#fff;padding:9px 12px;text-align:right;font-size:12px;">Qty</th>
      <th style="background:#0f3d26;color:#fff;padding:9px 12px;text-align:left;font-size:12px;">Unit</th>
      <th style="background:#0f3d26;color:#fff;padding:9px 12px;text-align:right;font-size:12px;">Rate (৳)</th>
      <th style="background:#0f3d26;color:#fff;padding:9px 12px;text-align:right;font-size:12px;">Amount (৳)</th></tr></thead>
    <tbody><tr>
      <td style="padding:9px 12px;border-bottom:1px solid #e5e7eb;">1</td>
      <td style="padding:9px 12px;border-bottom:1px solid #e5e7eb;">${escHTML(inv.product)}</td>
      <td style="padding:9px 12px;border-bottom:1px solid #e5e7eb;text-align:right;">${inv.qty}</td>
      <td style="padding:9px 12px;border-bottom:1px solid #e5e7eb;">${escHTML(inv.unit)}</td>
      <td style="padding:9px 12px;border-bottom:1px solid #e5e7eb;text-align:right;">${pf(inv.rate)}</td>
      <td style="padding:9px 12px;border-bottom:1px solid #e5e7eb;text-align:right;font-weight:700;">${pf(inv.qty*inv.rate)}</td></tr></tbody>
  </table>
  <div style="background:#f0fdf4;border:2px solid #16a34a;border-radius:8px;padding:14px 16px;text-align:right;margin-top:10px;">
    <div style="font-size:13px;color:#374151;">Subtotal: ${pf(inv.qty*inv.rate)}</div>
    ${inv.disc?'<div style="font-size:13px;color:#dc2626;">Discount: -'+pf(inv.disc)+'</div>':''}
    ${inv.vatPct?'<div style="font-size:13px;color:#374151;">VAT ('+inv.vatPct+'%): '+pf(inv.vatAmt)+'</div>':''}
    <div style="font-size:14px;font-weight:700;color:#374151;margin-top:4px;">Total: ${pf(inv.total)}</div>
    ${inv.bagDeductAmt?'<div style="font-size:13px;color:#dc2626;">Bag Deduction: -'+pf(inv.bagDeductAmt)+'</div>':''}
    ${inv.unrealized?'<div style="font-size:13px;color:#dc2626;">Unrealized Adjustment: -'+pf(inv.unrealized)+'</div>':''}
    ${inv.customDeductVal?'<div style="font-size:13px;color:#dc2626;">'+escHTML(inv.customDeductName||'Other Deduction')+': -'+pf(inv.customDeductVal)+'</div>':''}
    <div style="font-size:20px;font-weight:900;color:#0f3d26;margin-top:4px;">Net Sales Value: ${pf(inv.netAmt!==undefined?inv.netAmt:inv.total)}</div>
