      <div style="background:#fff;border:1px solid #e5e7eb;border-radius:8px;padding:12px 20px;text-align:center;">
        <div style="font-size:16px;font-weight:800;color:#16a34a;">৳${pf(totalPaid)}</div>
        <div style="font-size:11px;color:#6b7280;">Paid</div>
      </div>
      <div style="background:#fff;border:1px solid #e5e7eb;border-radius:8px;padding:12px 20px;text-align:center;">
        <div style="font-size:16px;font-weight:800;color:#2563eb;">${invs.length}</div>
        <div style="font-size:11px;color:#6b7280;">Total Invoices</div>
      </div>
    </div>
    <table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
