// FEATURE 34: Supplier Aging Report
function renderSupAge(){
  const today=new Date().toISOString().split('T')[0];
  const dateEl=document.getElementById('supage-date');
  if(!dateEl.value) dateEl.value=today;
  const asOf=new Date(dateEl.value);

  // Gather supplier payables from Purchase transactions minus Purchase Payments
  const txns=DB.tx||[];
  const supplierMap={};

  txns.forEach(t=>{
    const type=(t.type||'').toLowerCase();
    const party=t.party||'';
    const amt=txAmt(t);
    const txDate=new Date(t.date||today);
    if(txDate>asOf) return;

    if(!supplierMap[party]) supplierMap[party]={party,purchases:[],payments:0};

    if(type.includes('purchase') && !type.includes('payment') && !type.includes('advance') && !type.includes('return')){
      supplierMap[party].purchases.push({date:t.date,amt,daysOld:Math.floor((asOf-txDate)/(1000*60*60*24))});
    } else if(type.includes('purchase payment')||type.includes('purchase advance')){
      supplierMap[party].payments+=amt;
    }
  });

  // Calculate outstanding per supplier
  const rows=[];
  Object.values(supplierMap).forEach(s=>{
    let remaining=s.payments;
    const outstanding=[];
    // Apply payments to oldest first
    const sorted=[...s.purchases].sort((a,b)=>a.date>b.date?1:-1);
    sorted.forEach(p=>{
      if(remaining>=p.amt){ remaining-=p.amt; }
      else { outstanding.push({...p,amt:p.amt-remaining}); remaining=0; }
    });
    if(outstanding.length){
      const b0_30=outstanding.filter(o=>o.daysOld<=30).reduce((s,o)=>s+o.amt,0);
      const b31_60=outstanding.filter(o=>o.daysOld>30&&o.daysOld<=60).reduce((s,o)=>s+o.amt,0);
      const b61_90=outstanding.filter(o=>o.daysOld>60&&o.daysOld<=90).reduce((s,o)=>s+o.amt,0);
      const b91_180=outstanding.filter(o=>o.daysOld>90&&o.daysOld<=180).reduce((s,o)=>s+o.amt,0);
      const b180p=outstanding.filter(o=>o.daysOld>180).reduce((s,o)=>s+o.amt,0);
      const total=b0_30+b31_60+b61_90+b91_180+b180p;
      if(total>0) rows.push({party:s.party,b0_30,b31_60,b61_90,b91_180,b180p,total});
    }
  });

  const totals={b0_30:0,b31_60:0,b61_90:0,b91_180:0,b180p:0,total:0};
  rows.forEach(r=>{totals.b0_30+=r.b0_30;totals.b31_60+=r.b31_60;totals.b61_90+=r.b61_90;totals.b91_180+=r.b91_180;totals.b180p+=r.b180p;totals.total+=r.total;});

  const buckEl=document.getElementById('supage-buckets');
  if(buckEl){
    buckEl.innerHTML=[
      {label:'0-30 Days',val:totals.b0_30,color:'#16a34a'},
      {label:'31-60 Days',val:totals.b31_60,color:'#f59e0b'},
      {label:'61-90 Days',val:totals.b61_90,color:'#f97316'},
      {label:'91-180 Days',val:totals.b91_180,color:'#dc2626'},
      {label:'180+ Days',val:totals.b180p,color:'#7c3aed'}
    ].map(b=>`<div style="background:#fff;border:2px solid ${b.color}33;border-radius:10px;padding:14px;text-align:center;">
      <div style="font-size:16px;font-weight:900;color:${b.color};">৳${pf(b.val)}</div>
      <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(b.label)}</div>
    </div>`).join('');
  }

  const body=document.getElementById('supage-body');
  if(!body) return;
  if(!rows.length){
    body.innerHTML='<div style="text-align:center;padding:30px;color:#9ca3af;">No outstanding payables found.</div>';
    return;
  }
  rows.sort((a,b)=>b.total-a.total);
  body.innerHTML=`<table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
      <th style="padding:9px 12px;text-align:left;">Supplier</th>
      <th style="padding:9px 12px;text-align:right;">0-30 Days</th>
      <th style="padding:9px 12px;text-align:right;">31-60 Days</th>
      <th style="padding:9px 12px;text-align:right;">61-90 Days</th>
      <th style="padding:9px 12px;text-align:right;">91-180 Days</th>
      <th style="padding:9px 12px;text-align:right;">180+ Days</th>
      <th style="padding:9px 12px;text-align:right;">Total (৳)</th>
    </tr></thead>
    <tbody>
    ${rows.map((r,i)=>`<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
