      <th style="padding:9px 12px;text-align:left;">Mode</th>
    </tr></thead>
    <tbody>${txns.map((t,i)=>`<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
      <td style="padding:8px 12px;font-weight:600;">${t.type||'—'}</td>
      <td style="padding:8px 12px;">${escHTML(t.party||'—')}</td>
