// FEATURE 37: Expense Analysis
function renderExpAnalysis(){
  const today=new Date().toISOString().split('T')[0];
  const fromEl=document.getElementById('ea-from');
  const toEl=document.getElementById('ea-to');
  if(!fromEl.value) fromEl.value=today.slice(0,7)+'-01';
  if(!toEl.value) toEl.value=today;
  const from=fromEl.value, to=toEl.value;

  const EXP_TYPES=['Salary Payment','Employee Advance','Employee Loan','Office Rent','Electricity Bill',
    'Internet Bill','Telephone Bill','Fuel Expense','Transport Cost','Loading Charge','Unloading Charge',
    'Commission Payment','Brokerage Fee','Legal Fee','Audit Fee','Insurance Premium','Tax Payment',
    'Government Fee','License Fee','Maintenance Cost','Repair Expense','Stationery Purchase',
    'Other Expense','Interest Expense','Bank Charge'];

  const txns=(DB.tx||[]).filter(t=>_dk(t.date)>=_dk(from) && _dk(t.date)<=_dk(to) && EXP_TYPES.some(et=>(t.type||'').includes(et.split(' ')[0])));

  const CAT_MAP={
    'Payroll':['Salary Payment','Employee Advance','Employee Loan'],
    'Overhead':['Office Rent','Electricity Bill','Internet Bill','Telephone Bill','Stationery Purchase'],
    'Transport':['Fuel Expense','Transport Cost','Loading Charge','Unloading Charge'],
    'Finance':['Bank Charge','Interest Expense','Commission Payment','Brokerage Fee'],
    'Compliance':['Legal Fee','Audit Fee','Insurance Premium','Tax Payment','Government Fee','License Fee'],
    'Maintenance':['Maintenance Cost','Repair Expense'],
    'Other':['Other Expense']
  };

  const catTotals={};
  Object.keys(CAT_MAP).forEach(cat=>catTotals[cat]=0);
  const typeTotals={};

  txns.forEach(t=>{
    const amt=parseFloat(txAmt(t));
    const type=t.type||'';
    typeTotals[type]=(typeTotals[type]||0)+amt;
    for(const [cat,types] of Object.entries(CAT_MAP)){
      if(types.some(et=>type.includes(et.split(' ')[0]))){catTotals[cat]+=amt;break;}
    }
  });

  const totalExp=Object.values(catTotals).reduce((s,v)=>s+v,0);
  const topCat=Object.entries(catTotals).sort((a,b)=>b[1]-a[1])[0]||['—',0];

  const cards=document.getElementById('ea-cards');
  if(cards){
    if(cards) cards.innerHTML=[
      {label:'Total Expenses',val:'৳'+pf(totalExp),icon:'💸',color:'#dc2626'},
      {label:'Transactions',val:txns.length,icon:'📋',color:'#2563eb'},
      {label:'Top Category',val:topCat[0],icon:'🏆',color:'#f59e0b'},
      {label:'Avg per Day',val:'৳'+pf(totalExp/Math.max(1,Math.ceil((new Date(to)-new Date(from))/(1000*60*60*24)))),icon:'📅',color:'#7c3aed'}
    ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
      <div style="font-size:22px;">${c.icon}</div>
      <div style="font-size:15px;font-weight:900;color:${c.color};">${c.val}</div>
      <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)}</div>
    </div>`).join('');
  }

  const CAT_COLORS_EA={'Payroll':'#2563eb','Overhead':'#f59e0b','Transport':'#16a34a','Finance':'#7c3aed','Compliance':'#dc2626','Maintenance':'#f97316','Other':'#6b7280'};

  const catBody=document.getElementById('ea-cat-body');
  if(catBody){
    const catRows=Object.entries(catTotals).filter(([,v])=>v>0).sort((a,b)=>b[1]-a[1]);
    catBody.innerHTML=`<div style="padding:12px 14px;background:#f9fafb;border-bottom:1px solid #e5e7eb;font-size:12px;font-weight:700;color:#374151;">By Category</div>
    <table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
      <th style="padding:8px 12px;text-align:left;">Category</th>
      <th style="padding:8px 12px;text-align:right;">Amount (৳)</th>
      <th style="padding:8px 12px;text-align:right;">%</th>
    </tr></thead>
    <tbody>${catRows.map(([cat,amt],i)=>`<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
      <td style="padding:8px 12px;"><span style="display:inline-block;width:10px;height:10px;border-radius:50%;background:${CAT_COLORS_EA[cat]||'#6b7280'};margin-right:6px;"></span>${cat}</td>
      <td style="padding:8px 12px;text-align:right;font-weight:700;color:${CAT_COLORS_EA[cat]||'#374151'};">৳${pf(amt)}</td>
      <td style="padding:8px 12px;text-align:right;color:#6b7280;">${totalExp?((amt/totalExp)*100).toFixed(1)+'%':'0%'}</td>
    </tr>`).join('')}
    <tr style="background:#fef2f2;font-weight:800;border-top:2px solid #dc2626;">
      <td style="padding:9px 12px;color:#dc2626;">TOTAL</td>
      <td style="padding:9px 12px;text-align:right;color:#dc2626;">৳${pf(totalExp)}</td>
      <td style="padding:9px 12px;text-align:right;color:#dc2626;">100%</td>
    </tr></tbody></table>`;
  }

  const detBody=document.getElementById('ea-detail-body');
  if(detBody){
    const typeRows=Object.entries(typeTotals).sort((a,b)=>b[1]-a[1]);
    detBody.innerHTML=`<div style="padding:12px 14px;background:#f9fafb;border-bottom:1px solid #e5e7eb;font-size:12px;font-weight:700;color:#374151;">By Type</div>
    <table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
      <th style="padding:8px 12px;text-align:left;">Expense Type</th>
      <th style="padding:8px 12px;text-align:right;">Amount (৳)</th>
    </tr></thead>
    <tbody>${typeRows.map(([type,amt],i)=>`<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
      <td style="padding:8px 12px;">${type}</td>
      <td style="padding:8px 12px;text-align:right;font-weight:700;color:#dc2626;">৳${pf(amt)}</td>
    </tr>`).join('')}</tbody></table>`;
  }
}
