// FEATURE 39: Stock Movement Report
function renderStockMove(){
  const today=new Date().toISOString().split('T')[0];
  const fromEl=document.getElementById('sm-from');
  const toEl=document.getElementById('sm-to');
  if(!fromEl.value) fromEl.value=today.slice(0,7)+'-01';
  if(!toEl.value) toEl.value=today;
  const from=fromEl.value, to=toEl.value;

  const prodSel=document.getElementById('sm-product');
  if(prodSel && prodSel.options.length<=1){
    (DB.masterData?.products||MASTER.products||[]).forEach(p=>{const o=document.createElement('option');o.value=p;o.textContent=p;prodSel.appendChild(o);});
  }
  const filterProd=prodSel?.value||'';

  // FIX F: 'Customer Sale' never left stock, and 'Sales Return' was counted as
  // stock OUT even though returned goods come back IN.
  const IN_TYPES=Array.from(window.INV_IN_TYPES);
  const OUT_TYPES=Array.from(window.INV_OUT_TYPES);

  const txns=(DB.tx||[]).filter(t=>_dk(t.date)>=_dk(from) && _dk(t.date)<=_dk(to) && t.prod && (!filterProd||t.prod===filterProd));

  // Group by product
  const prodMap={};
  txns.forEach(t=>{
    const prod=t.prod;
    if(!prodMap[prod]) prodMap[prod]={product:prod,inQty:0,inAmt:0,outQty:0,outAmt:0,txns:[]};
    const qty=parseFloat(t.qty||0);
    const amt=parseFloat(txAmt(t));
    const type=t.type||'';
    if(IN_TYPES.some(it=>type.includes(it.split(' ')[0]))){
      prodMap[prod].inQty+=qty; prodMap[prod].inAmt+=amt;
    } else if(OUT_TYPES.some(ot=>type.includes(ot.split(' ')[0]))){
      prodMap[prod].outQty+=qty; prodMap[prod].outAmt+=amt;
    }
    prodMap[prod].txns.push(t);
  });

  const rows=Object.values(prodMap).map(p=>({...p,netQty:p.inQty-p.outQty,netAmt:p.inAmt-p.outAmt})).sort((a,b)=>b.inAmt-a.inAmt);

  const totalIn=rows.reduce((s,r)=>s+r.inAmt,0);
  const totalOut=rows.reduce((s,r)=>s+r.outAmt,0);
  const totalInQty=rows.reduce((s,r)=>s+r.inQty,0);
  const totalOutQty=rows.reduce((s,r)=>s+r.outQty,0);

  const cards=document.getElementById('sm-cards');
  if(cards){
    if(cards) cards.innerHTML=[
      {label:'Total In (৳)',val:'৳'+pf(totalIn),icon:'📥',color:'#16a34a'},
      {label:'Total Out (৳)',val:'৳'+pf(totalOut),icon:'📤',color:'#dc2626'},
      {label:'In Qty',val:pf(totalInQty),icon:'⬆️',color:'#2563eb'},
      {label:'Out Qty',val:pf(totalOutQty),icon:'⬇️',color:'#f59e0b'}
    ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
      <div style="font-size:22px;">${c.icon}</div>
      <div style="font-size:16px;font-weight:900;color:${c.color};">${c.val}</div>
      <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)}</div>
    </div>`).join('');
  }

  const body=document.getElementById('sm-body');
  if(!body) return;
  if(!rows.length){
    body.innerHTML='<div style="text-align:center;padding:30px;color:#9ca3af;">No stock movements in selected period.</div>';
    return;
  }
  body.innerHTML=`<table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
      <th style="padding:9px 12px;text-align:left;">Product</th>
      <th style="padding:9px 12px;text-align:right;">In Qty</th>
