// FEATURE 40: Payment Schedule

function newPaySchedule(){
  const f=document.getElementById('paysch-form');
  f.style.display='block';
  const today=new Date().toISOString().split('T')[0];
  document.getElementById('ps-due').value=today;
  const ps=document.getElementById('ps-party');
  if(ps && ps.options.length<=1){
    (DB.masterData?.parties||MASTER.parties||[]).forEach(p=>{const o=document.createElement('option');o.value=p;o.textContent=p;ps.appendChild(o);});
  }
}

function savePaySchedule(){
  const sch={
    id:newId(),
    party:document.getElementById('ps-party')?.value||'',
    type:document.getElementById('ps-type')?.value||'Payable',
    amount:parseFloat(document.getElementById('ps-amount')?.value)||0,
    due:document.getElementById('ps-due')?.value||'',
    priority:document.getElementById('ps-priority')?.value||'Medium',
    desc:document.getElementById('ps-desc')?.value||'',
    status:'Pending',
    createdAt:new Date().toISOString().split('T')[0]
  };
  if(!sch.party||!sch.amount||!sch.due){alert('⚠️ Fill Party, Amount and Due Date');return;}
  DB.paySchedules.unshift(sch);
  saveDB();
  document.getElementById('paysch-form').style.display='none';
  renderPaySch();
  logAudit('CREATE','Payment Schedule','Added schedule for '+sch.party+' ৳'+pf(sch.amount));
}

function markPaySchDone(id){
  const s=(DB.paySchedules||[]).find(s=>s.id===id);
  if(s){s.status='Completed';saveDB();renderPaySch();}
}

async function deletePaySch(id){
  if(!await __confirm('Delete this schedule?')) return;
  DB.paySchedules=(DB.paySchedules||[]).filter(s=>s.id!==id);
  saveDB();renderPaySch();
}

function renderPaySch(){
  const today=new Date().toISOString().split('T')[0];
  const schedules=DB.paySchedules||[];

  const overdue=schedules.filter(s=>s.status==='Pending'&&s.due<today);
  const upcoming=schedules.filter(s=>s.status==='Pending'&&s.due>=today);
  const completed=schedules.filter(s=>s.status==='Completed');
  const totalPayable=schedules.filter(s=>s.type==='Payable'&&s.status==='Pending').reduce((s,r)=>s+r.amount,0);
  const totalReceivable=schedules.filter(s=>s.type==='Receivable'&&s.status==='Pending').reduce((s,r)=>s+r.amount,0);

  const cards=document.getElementById('ps-cards');
  if(cards){
    if(cards) cards.innerHTML=[
      {label:'Overdue',val:overdue.length+' items',icon:'🚨',color:'#dc2626'},
      {label:'Upcoming',val:upcoming.length+' items',icon:'⏰',color:'#f59e0b'},
      {label:'Total Payable',val:'৳'+pf(totalPayable),icon:'📤',color:'#7c3aed'},
      {label:'Total Receivable',val:'৳'+pf(totalReceivable),icon:'📥',color:'#16a34a'}
    ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
      <div style="font-size:22px;">${c.icon}</div>
      <div style="font-size:16px;font-weight:900;color:${c.color};">${c.val}</div>
      <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)}</div>
    </div>`).join('');
  }

  const body=document.getElementById('ps-body');
  if(!body) return;
  if(!schedules.length){
    body.innerHTML='<div style="text-align:center;padding:30px;color:#9ca3af;">No payment schedules yet. Click "+ Add Schedule" to create one.</div>';
    return;
  }

  const PRIORITY_COLOR={High:'#dc2626',Medium:'#f59e0b',Low:'#16a34a'};
  const sorted=[...schedules].sort((a,b)=>{
    if(a.status!==b.status) return a.status==='Pending'?-1:1;
    return a.due>b.due?1:-1;
  });

  body.innerHTML=`<table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
      <th style="padding:9px 12px;text-align:left;">Party</th>
      <th style="padding:9px 12px;text-align:left;">Type</th>
      <th style="padding:9px 12px;text-align:right;">Amount (৳)</th>
      <th style="padding:9px 12px;text-align:left;">Due Date</th>
      <th style="padding:9px 12px;text-align:center;">Priority</th>
      <th style="padding:9px 12px;text-align:left;">Description</th>
      <th style="padding:9px 12px;text-align:center;">Status</th>
      <th style="padding:9px 12px;text-align:center;">Actions</th>
    </tr></thead>
    <tbody>${sorted.map((s,i)=>{
      const isOverdue=s.status==='Pending'&&s.due<today;
      const daysLeft=Math.ceil((new Date(s.due)-new Date(today))/(1000*60*60*24));
      return `<tr style="border-bottom:1px solid #f3f4f6;background:${isOverdue?'#fff5f5':i%2?'#f9fafb':'#fff'};">
        <td style="padding:8px 12px;font-weight:700;">${escHTML(s.party)}</td>
        <td style="padding:8px 12px;"><span style="background:${s.type==='Payable'?'#fee2e2':'#dcfce7'};color:${s.type==='Payable'?'#dc2626':'#16a34a'};padding:2px 8px;border-radius:10px;font-size:11px;font-weight:700;">${s.type}</span></td>
        <td style="padding:8px 12px;text-align:right;font-weight:800;color:#0f3d26;">৳${pf(s.amount)}</td>
        <td style="padding:8px 12px;color:${isOverdue?'#dc2626':'#374151'};font-weight:${isOverdue?'700':'400'};">
          ${s.due}${s.status==='Pending'?'<br><span style="font-size:10px;color:'+( isOverdue?'#dc2626':'#6b7280')+';">'+(isOverdue?'⚠️ '+Math.abs(daysLeft)+' days overdue':'⏰ '+daysLeft+' days left')+'</span>':''}
        </td>
        <td style="padding:8px 12px;text-align:center;"><span style="background:${PRIORITY_COLOR[s.priority]||'#6b7280'}22;color:${PRIORITY_COLOR[s.priority]||'#6b7280'};padding:2px 8px;border-radius:10px;font-size:11px;font-weight:700;">${s.priority}</span></td>
        <td style="padding:8px 12px;color:#6b7280;">${escHTML(s.desc||'—')}</td>
        <td style="padding:8px 12px;text-align:center;"><span style="background:${s.status==='Completed'?'#dcfce7':'#fef3c7'};color:${s.status==='Completed'?'#16a34a':'#92400e'};padding:2px 8px;border-radius:10px;font-size:11px;font-weight:700;">${s.status}</span></td>
        <td style="padding:8px 12px;text-align:center;display:flex;gap:4px;justify-content:center;">
          ${s.status!=='Completed'?'<button data-x-click="markPaySchDone('+s.id+')" style="padding:4px 8px;background:#16a34a;color:#fff;border:none;border-radius:5px;font-size:11px;cursor:pointer;">✅</button>':''}
          <button data-x-click="deletePaySch('+s.id+')" style="padding:4px 8px;background:#dc2626;color:#fff;border:none;border-radius:5px;font-size:11px;cursor:pointer;">🗑️</button>
        </td>
      </tr>`;
    }).join('')}</tbody>
  </table>`;
}
function printPaySch(){ printPageViaLetterhead('pg-paymentschedule','Payment Schedule'); logAudit('PRINT','Payment Schedule','Printed payment schedule'); }


