// BATCH A: LEDGERS
// ══════════════════════════════════════════════════════════════

// ── Shared ledger helpers ──────────────────────────────────────
function buildLedgerTable(txns, debitTypes, creditTypes, openingBal){
  let running = openingBal || 0;
  let totalDr = 0, totalCr = 0;
  const rows = txns.map((t,i) => {
    const amt = txAmt(t);
    const type = (t.type||'').toLowerCase().trim();
    let dr=0, cr=0;
    /* FIX (supplier ledger): this used to test `type.includes(k)`, so a
       'Purchase Payment' matched the debit keyword 'purchase' and every
       payment you ever made to a supplier was added to the amount owed
       instead of taken off it — ৳10 purchased + ৳250 paid closed at ৳260
       payable rather than ৳240 in advance. Matching is now exact, and the
       credit list is tested first so a longer name can never be swallowed
       by a shorter one. */
    const norm = k=>String(k||'').toLowerCase().trim();
    const isCr = creditTypes.some(k=>norm(k)===type);
    const isDr = !isCr && debitTypes.some(k=>norm(k)===type);
    if(isDr) { dr=amt; running+=amt; totalDr+=amt; }
    else if(isCr) { cr=amt; running-=amt; totalCr+=amt; }
    else { dr=amt; running+=amt; totalDr+=amt; }
    return `<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
      <td style="padding:8px 12px;color:#6b7280;">${t.date||'—'}</td>
      <td style="padding:8px 12px;font-weight:600;">${t.type||'—'}</td>
      <td style="padding:8px 12px;">${escHTML(t.party||t.account||'—')}</td>
      <td style="padding:8px 12px;">${escHTML(t.product||t.desc||t.description||'—')}</td>
      <td style="padding:8px 12px;text-align:right;color:#dc2626;">${dr?'৳'+pf(dr):''}</td>
      <td style="padding:8px 12px;text-align:right;color:#16a34a;">${cr?'৳'+pf(cr):''}</td>
      <td style="padding:8px 12px;text-align:right;font-weight:700;color:${running>=0?'#0f3d26':'#dc2626'};">৳${pf(Math.abs(running))}${running<0?' (Cr)':''}</td>
      <td style="padding:8px 12px;color:#6b7280;">${t.mode||'—'}</td>
    </tr>`;
  });
  return {rows, totalDr, totalCr, closing: running};
}

function ledgerTableHeader(){
  return `<table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
      <th style="padding:9px 12px;text-align:left;">Date</th>
      <th style="padding:9px 12px;text-align:left;">Type</th>
      <th style="padding:9px 12px;text-align:left;">Party/Account</th>
      <th style="padding:9px 12px;text-align:left;">Product/Desc</th>
      <th style="padding:9px 12px;text-align:right;">Debit (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Credit (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Balance (৳)</th>
      <th style="padding:9px 12px;text-align:left;">Mode</th>
    </tr></thead><tbody>`;
}

function ledgerSummaryCards(totalDr, totalCr, closing, label){
  /* FIX: "Total Debit / Total Credit" told a supplier statement's reader
     nothing. The columns are named for what they actually are, and the
     closing figure says whether it is payable or paid in advance. */
  const isSup = String(label||'').toLowerCase()==='supplier';
  const drLbl = isSup ? 'Total Paid to Him' : 'Total Debit';
  const crLbl = isSup ? 'Goods Received'    : 'Total Credit';
  const clLbl = isSup ? (closing>=0?'Money Still With Him':'You Owe Him') : 'Closing Balance';
  return [
    {label:drLbl,val:'৳'+pf(totalDr),icon:'📤',color:'#dc2626'},
    {label:crLbl,val:'৳'+pf(totalCr),icon:'📥',color:'#16a34a'},
    {label:clLbl,val:'৳'+pf(Math.abs(closing)),icon:'💰',color:closing>=0?'#2563eb':'#16a34a'}
  ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
    <div style="font-size:22px;">${c.icon}</div>
    <div style="font-size:17px;font-weight:900;color:${c.color};">${c.val}</div>
    <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)}</div>
  </div>`).join('');
}

function populateLedgerDropdown(selId, types){
  const sel=document.getElementById(selId);
  if(!sel||sel.options.length>1) return;
  const parties=(DB.masterData?.parties||MASTER.parties||[]);
  parties.forEach(p=>{const o=document.createElement('option');o.value=p;o.textContent=p;sel.appendChild(o);});
}

function printLedger(page){ window.print(); logAudit('PRINT','Ledger','Printed '+page); }

// ── All Ledgers Hub ────────────────────────────────────────────


// ── Customer Ledger ────────────────────────────────────────────


// ── Supplier Ledger ────────────────────────────────────────────
function renderSupLedger(){
  const today=new Date().toISOString().split('T')[0];
  populateLedgerDropdown('sl-party');
  const fromEl=document.getElementById('sl-from');
  const toEl=document.getElementById('sl-to');
  if(!fromEl.value) fromEl.value='2020-01-01';
  if(!toEl.value) toEl.value=today;
  const party=document.getElementById('sl-party')?.value||'';
  const from=fromEl.value, to=toEl.value;

  /* FIX: 'Supplier Payment', 'Advance to Supplier' and the other names the
     New Transaction dropdown offers for the same acts were missing from
     these lists, so they fell through to the "unknown = debit" default and
     added to the amount owed. */
  /* Money you pay him adds to the balance; goods he delivers use it up —
     the same direction as the figure on the Parties and Dashboard screens. */
  const PURCH_DR=['purchase payment','supplier payment','purchase advance','advance to supplier',
                  'supplier advance','payment refund'];
  const PURCH_CR=['purchase','warehouse purchase','supplier purchase','supplier due',
                  'purchase return','supplier refund'];

  const txns=(DB.tx||[]).filter(t=>t.party===party && _dk(t.date)>=_dk(from) && _dk(t.date)<=_dk(to))
    .sort((a,b)=>a.date>b.date?1:-1);

  const cards=document.getElementById('sl-cards');
  const body=document.getElementById('sl-body');
  if(!party){
    if(cards) cards.innerHTML='';
    if(body) body.innerHTML='<div style="text-align:center;padding:30px;color:#9ca3af;">Select a supplier to view ledger.</div>';
    return;
  }
  const supOpen=ayanPartyOpening(party,from,'supplier');
  /* A supplier can hold a large balance with no movement in the period —
     six of them here carry advances brought forward and nothing else. The
     statement used to say "No transactions found" and show nothing at all,
     hiding ৳19,00,000 in one case. An opening balance is now reported even
     when nothing moved. */
  if(!txns.length && Math.abs(supOpen)<0.01){
    if(cards) cards.innerHTML='';
    if(body) body.innerHTML='<div style="text-align:center;padding:30px;color:#9ca3af;">No transactions found for '+party+'.</div>';
    return;
  }
  const {rows,totalDr,totalCr,closing}=buildLedgerTable(txns,PURCH_DR,PURCH_CR,supOpen);
  if(cards) cards.innerHTML=ledgerSummaryCards(totalDr,totalCr,closing,'Supplier');
  if(body) body.innerHTML=ledgerTableHeader()+
    '<tr style="background:#f9fafb;border-bottom:1px solid #e5e7eb;"><td colspan="6" style="padding:8px 12px;font-weight:700;color:#6b7280;">Opening Balance</td>'+
    '<td style="padding:8px 12px;text-align:right;font-weight:700;">৳'+pf(supOpen)+'</td><td></td></tr>'+
    rows.join('')+
    `<tr style="background:#f0fdf4;font-weight:800;border-top:2px solid #16a34a;">
      <td colspan="4" style="padding:9px 12px;color:#0f3d26;">CLOSING BALANCE</td>
      <td style="padding:9px 12px;text-align:right;color:#dc2626;">৳${pf(totalDr)}</td>
      <td style="padding:9px 12px;text-align:right;color:#16a34a;">৳${pf(totalCr)}</td>
      <td style="padding:9px 12px;text-align:right;color:#0f3d26;">৳${pf(Math.abs(closing))}</td>
      <td></td>
    </tr></tbody></table>`;
}

// ── Partner Ledger ─────────────────────────────────────────────


// ── Expense Ledger ─────────────────────────────────────────────


// ── Fixed Assets Ledger ────────────────────────────────────────
function renderFALedger(){
  const txns=(DB.tx||[]).filter(t=>{
    const type=(t.type||'').toLowerCase();
    return type.includes('opening fixed asset')||type.includes('fixed asset');
  });

  // Also use DB.assets if available
  const assets=DB.assets||[];
  const DEPR_RATES={'Car':15,'Motorcycle':15,'Vehicle':15,'Building':5,'Warehouse':5,'Machinery':10,'Equipment':20,'Furniture':20,'Other':10};

  const currentYear=new Date().getFullYear();

  const cards=document.getElementById('fa-cards');
  const body=document.getElementById('fa-body');

  // Combine from transactions + DB.assets
  const allAssets=[];
  txns.forEach(t=>{
    allAssets.push({name:t.prod||t.desc||'Asset',cost:parseFloat(txAmt(t)),date:t.date,source:'txn'});
  });
  assets.forEach(a=>{
    allAssets.push({name:a.name||'Asset',cost:parseFloat(a.val||a.cost||0),date:a.date||'2020-01-01',source:'db'});
  });

  const totalCost=allAssets.reduce((s,a)=>s+a.cost,0);
  const totalDepr=allAssets.reduce((s,a)=>{
    const cat=Object.keys(DEPR_RATES).find(k=>a.name.toLowerCase().includes(k.toLowerCase()))||'Other';
    const rate=DEPR_RATES[cat]/100;
    const years=Math.max(0,currentYear-new Date(a.date||'2020-01-01').getFullYear());
    return s+(a.cost*rate*years);
  },0);
  const netValue=Math.max(0,totalCost-totalDepr);

  if(cards) cards.innerHTML=[
    {label:'Total Cost',val:'৳'+pf(totalCost),icon:'🏗️',color:'#2563eb'},
    {label:'Total Depreciation',val:'৳'+pf(totalDepr),icon:'📉',color:'#dc2626'},
    {label:'Net Book Value',val:'৳'+pf(netValue),icon:'💰',color:'#16a34a'},
    {label:'Total Assets',val:allAssets.length,icon:'📦',color:'#f59e0b'}
  ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
    <div style="font-size:22px;">${c.icon}</div>
    <div style="font-size:17px;font-weight:900;color:${c.color};">${c.val}</div>
    <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)}</div>
  </div>`).join('');

  if(!body) return;
  if(!allAssets.length){
    body.innerHTML='<div style="text-align:center;padding:30px;color:#9ca3af;">No fixed assets recorded. Add via Opening Balance or transactions.</div>';
    return;
  }
  body.innerHTML=`<table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
      <th style="padding:9px 12px;text-align:left;">Asset Name</th>
      <th style="padding:9px 12px;text-align:left;">Purchase Date</th>
      <th style="padding:9px 12px;text-align:right;">Cost (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Depr Rate</th>
      <th style="padding:9px 12px;text-align:right;">Years</th>
      <th style="padding:9px 12px;text-align:right;">Accum. Depr (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Net Value (৳)</th>
    </tr></thead>
    <tbody>${allAssets.map((a,i)=>{
      const cat=Object.keys(DEPR_RATES).find(k=>a.name.toLowerCase().includes(k.toLowerCase()))||'Other';
      const rate=DEPR_RATES[cat]/100;
      const years=Math.max(0,currentYear-new Date(a.date||'2020-01-01').getFullYear());
      const depr=a.cost*rate*years;
      const net=Math.max(0,a.cost-depr);
      return `<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
        <td style="padding:8px 12px;font-weight:700;">${escHTML(a.name)}</td>
        <td style="padding:8px 12px;color:#6b7280;">${a.date||'—'}</td>
        <td style="padding:8px 12px;text-align:right;">৳${pf(a.cost)}</td>
        <td style="padding:8px 12px;text-align:right;color:#f59e0b;">${(rate*100).toFixed(0)}%</td>
        <td style="padding:8px 12px;text-align:right;">${years}</td>
        <td style="padding:8px 12px;text-align:right;color:#dc2626;">৳${pf(depr)}</td>
        <td style="padding:8px 12px;text-align:right;font-weight:700;color:#16a34a;">৳${pf(net)}</td>
      </tr>`;
    }).join('')}
    <tr style="background:#f0fdf4;font-weight:800;border-top:2px solid #16a34a;">
      <td colspan="2" style="padding:9px 12px;color:#0f3d26;">TOTAL</td>
      <td style="padding:9px 12px;text-align:right;">৳${pf(totalCost)}</td>
      <td colspan="2"></td>
      <td style="padding:9px 12px;text-align:right;color:#dc2626;">৳${pf(totalDepr)}</td>
      <td style="padding:9px 12px;text-align:right;color:#16a34a;">৳${pf(netValue)}</td>
    </tr></tbody></table>`;
}

// ── Chart of Accounts ──────────────────────────────────────────
function renderChartAccts(){
  const txns=DB.tx||[];
  const today=new Date().toISOString().split('T')[0];

  function sumType(keywords){
    return txns.reduce((s,t)=>{
      const type=(t.type||'').toLowerCase();
      return keywords.some(k=>type.includes(k))?s+parseFloat(txAmt(t)):s;
    },0);
  }

  const accounts=[
    {group:'ASSETS',color:'#2563eb',items:[
      {code:'1001',name:'Cash Account',bal:sumType(['cash received','cash payment']>0?sumType(['cash received']):0)},
      {code:'1002',name:'Bank Accounts',bal:sumType(['bank deposit','bank withdrawal','bank transfer'])},
      {code:'1003',name:'Bkash Account',bal:sumType(['bkash deposit','bkash withdrawal','bkash'])},
      {code:'1100',name:'Accounts Receivable',bal:sumType(['sale','sales receipt','sales advance'])},
      {code:'1200',name:'Inventory / Stock',bal:sumType(['purchase','warehouse purchase'])},
      {code:'1300',name:'Supplier Advances',bal:sumType(['purchase advance'])},
      {code:'1500',name:'Fixed Assets',bal:sumType(['opening fixed asset','fixed asset'])},
    ]},
    {group:'LIABILITIES',color:'#dc2626',items:[
      {code:'2001',name:'Accounts Payable',bal:sumType(['purchase'])},
      {code:'2100',name:'Sales Advances Received',bal:sumType(['sales advance'])},
    ]},
    {group:'EQUITY',color:'#7c3aed',items:[
      {code:'3001',name:'Partner Capital',bal:sumType(['partner capital','opening partner fund'])},
      {code:'3100',name:'Partner Withdrawals',bal:sumType(['partner withdrawal'])},
      {code:'3200',name:'Retained Earnings',bal:sumType(['sale'])-sumType(['purchase','salary','expense','rent','electricity','transport','fuel','maintenance','repair','commission','legal','audit','insurance','tax','government','license','stationery','other expense','interest expense','bank charge'])},
    ]},
    {group:'INCOME',color:'#16a34a',items:[
      {code:'4001',name:'Sales Revenue',bal:sumType(['sale'])},
      {code:'4100',name:'Other Income',bal:sumType(['other income','interest income'])},
    ]},
    {group:'EXPENSES',color:'#f59e0b',items:[
      {code:'5001',name:'Cost of Goods Sold',bal:sumType(['purchase'])},
      {code:'5100',name:'Salary & Payroll',bal:sumType(['salary','employee'])},
      {code:'5200',name:'Overhead Expenses',bal:sumType(['office rent','electricity','internet','telephone','stationery'])},
      {code:'5300',name:'Transport & Logistics',bal:sumType(['transport','fuel','loading','unloading'])},
      {code:'5400',name:'Finance Charges',bal:sumType(['bank charge','interest expense','commission','brokerage'])},
      {code:'5500',name:'Compliance & Legal',bal:sumType(['legal','audit','insurance','tax','government','license'])},
      {code:'5600',name:'Maintenance & Repair',bal:sumType(['maintenance','repair'])},
      {code:'5900',name:'Other Expenses',bal:sumType(['other expense'])},
    ]},
  ];

  const body=document.getElementById('coa-body');
  if(!body) return;
  body.innerHTML=accounts.map(grp=>`
    <div style="background:${grp.color}11;border-left:4px solid ${grp.color};padding:10px 16px;font-size:12px;font-weight:800;color:${grp.color};letter-spacing:.5px;">${grp.group}</div>
    <table style="width:100%;border-collapse:collapse;font-size:12px;margin-bottom:0;">
    <tbody>${grp.items.map((item,i)=>`<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
      <td style="padding:8px 16px;color:#6b7280;width:80px;">${item.code}</td>
      <td style="padding:8px 12px;font-weight:600;">${escHTML(item.name)}</td>
      <td style="padding:8px 16px;text-align:right;font-weight:700;color:${grp.color};">৳${pf(item.bal)}</td>
    </tr>`).join('')}</tbody></table>
  `).join('');
}


