function openTenderModal(id){
  const m=document.getElementById('tender-modal');
  if(!m) return;
  if(id){
    const t=(DB.tenders||[]).find(x=>x.id===id);
    if(t){
      document.getElementById('td-title').value=t.title||'';
      document.getElementById('td-no').value=t.no||'';
      document.getElementById('td-org').value=t.org||'';
      document.getElementById('td-value').value=t.value||'';
      document.getElementById('td-security').value=t.security||'';
      document.getElementById('td-submit').value=t.submitDate||'';
      document.getElementById('td-open').value=t.openDate||'';
      document.getElementById('td-status').value=t.status||'Preparing';
      document.getElementById('td-product').value=t.product||'';
      document.getElementById('td-notes').value=t.notes||'';
      m._editId=id;
    }
  } else {
    ['td-title','td-no','td-org','td-value','td-security','td-submit','td-open','td-product','td-notes'].forEach(id=>{ const el=document.getElementById(id); if(el) el.value=''; });
    document.getElementById('td-status').value='Preparing';
    m._editId=null;
  }
  m.style.display='flex';
}

function closeTenderModal(){
  const m=document.getElementById('tender-modal');
  if(m) m.style.display='none';
}





function renderTenderMgmt(){
  const tenders=DB.tenders||[];
  const STATUS_COLOR={Draft:'#6b7280',Submitted:'#2563eb','Under Review':'#f59e0b',Won:'#16a34a',Lost:'#dc2626',Cancelled:'#9ca3af'};

  const cards=document.getElementById('tender-cards');
  if(cards){
    const total=tenders.length;
    const won=tenders.filter(t=>t.status==='Won').length;
    const active=tenders.filter(t=>['Submitted','Under Review'].includes(t.status)).length;
    const totalVal=tenders.reduce((s,t)=>s+t.value,0);
    if(cards) cards.innerHTML=[
      {label:'Total Tenders',val:total,icon:'📋',color:'#2563eb'},
      {label:'Won',val:won,icon:'🏆',color:'#16a34a'},
      {label:'Active',val:active,icon:'⏳',color:'#f59e0b'},
      {label:'Total Value',val:'৳'+pf(totalVal),icon:'💰',color:'#7c3aed'}
    ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
      <div style="font-size:22px;">${c.icon}</div>
      <div style="font-size:17px;font-weight:900;color:${c.color};">${c.val}</div>
      <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)}</div>
    </div>`).join('');
  }

  const wrap=document.getElementById('tender-table-wrap');
  if(!wrap) return;
  if(!tenders.length){
    wrap.innerHTML='<div style="text-align:center;padding:40px;color:#9ca3af;">No tenders yet. Click "+ New Tender" to add one.</div>';
    return;
  }
  wrap.innerHTML=`<table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
      <th style="padding:9px 12px;text-align:left;">Tender No</th>
      <th style="padding:9px 12px;text-align:left;">Title</th>
      <th style="padding:9px 12px;text-align:left;">Party</th>
      <th style="padding:9px 12px;text-align:right;">Value (৳)</th>
      <th style="padding:9px 12px;text-align:left;">Sub. Date</th>
      <th style="padding:9px 12px;text-align:left;">Status</th>
      <th style="padding:9px 12px;text-align:center;">Actions</th>
    </tr></thead>
    <tbody>${tenders.map((t,i)=>`<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
      <td style="padding:8px 12px;color:#6b7280;">${t.no||'—'}</td>
      <td style="padding:8px 12px;font-weight:700;">${t.title}</td>
      <td style="padding:8px 12px;">${escHTML(t.party)}</td>
      <td style="padding:8px 12px;text-align:right;font-weight:700;">৳${pf(t.value)}</td>
      <td style="padding:8px 12px;color:#6b7280;">${t.subdate||'—'}</td>
      <td style="padding:8px 12px;"><span style="background:${STATUS_COLOR[t.status]||'#6b7280'}22;color:${STATUS_COLOR[t.status]||'#6b7280'};padding:3px 10px;border-radius:20px;font-size:11px;font-weight:700;">${t.status}</span></td>
      <td style="padding:8px 12px;text-align:center;">
        <button data-x-click="openTenderModal(${t.id})" style="background:#f0fdf4;border:1px solid #16a34a;color:#16a34a;padding:4px 10px;border-radius:5px;font-size:11px;cursor:pointer;margin-right:4px;">✏️</button>
        <button data-x-click="deleteTender(${t.id})" style="background:#fef2f2;border:1px solid #dc2626;color:#dc2626;padding:4px 10px;border-radius:5px;font-size:11px;cursor:pointer;">🗑️</button>
      </td>
    </tr>`).join('')}</tbody></table>`;
}

function renderTenderTrack(){
  const tenders=DB.tenders||[];
  const STATUS_COLOR={Draft:'#6b7280',Submitted:'#2563eb','Under Review':'#f59e0b',Won:'#16a34a',Lost:'#dc2626',Cancelled:'#9ca3af'};
  const STATUS_STEPS=['Draft','Submitted','Under Review','Won'];
  const grid=document.getElementById('tender-track-grid');
  if(!grid) return;
  if(!tenders.length){
    grid.innerHTML='<div style="grid-column:1/-1;text-align:center;padding:40px;color:#9ca3af;">No tenders to track. Add tenders in Tender Management.</div>';
    return;
  }
  grid.innerHTML=tenders.map(t=>{
    const stepIdx=STATUS_STEPS.indexOf(t.status);
    const today=new Date().toISOString().split('T')[0];
    const daysLeft=t.subdate?Math.ceil((new Date(t.subdate)-new Date())/(1000*60*60*24)):null;
    return `<div style="background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:18px;">
      <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:12px;">
        <div>
          <div style="font-size:13px;font-weight:800;color:#0f3d26;">${escHTML(t.title)}</div>
          <div style="font-size:11px;color:#6b7280;margin-top:2px;">${escHTML(t.party)} • ${t.no||'No Ref'}</div>
        </div>
        <span style="background:${STATUS_COLOR[t.status]||'#6b7280'}22;color:${STATUS_COLOR[t.status]||'#6b7280'};padding:3px 10px;border-radius:20px;font-size:11px;font-weight:700;">${t.status}</span>
      </div>
      <div style="display:flex;gap:4px;margin-bottom:12px;">
        ${STATUS_STEPS.map((s,i)=>`<div style="flex:1;height:4px;border-radius:2px;background:${i<=stepIdx?STATUS_COLOR[t.status]||'#16a34a':'#e5e7eb'};"></div>`).join('')}
      </div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;font-size:11px;">
        <div><span style="color:#6b7280;">Value:</span> <strong>৳${pf(t.value)}</strong></div>
        <div><span style="color:#6b7280;">Advance:</span> <strong>৳${pf(t.advance||0)}</strong></div>
        <div><span style="color:#6b7280;">Sub. Date:</span> <strong>${t.subdate||'—'}</strong></div>
        <div><span style="color:#6b7280;">Days Left:</span> <strong style="color:${daysLeft!==null&&daysLeft<3?'#dc2626':'#16a34a'}">${daysLeft!==null?daysLeft+' days':'—'}</strong></div>
      </div>
      ${t.notes?`<div style="margin-top:10px;font-size:11px;color:#6b7280;background:#f9fafb;padding:8px;border-radius:6px;">${escHTML(t.notes)}</div>`:''}
    </div>`;
  }).join('');
}


