function openSmsModal(to, template, amount){
  const m=document.getElementById('sms-modal');
  if(!m) return;
  if(to) document.getElementById('sms-to').value=to;
  if(template){
    document.getElementById('sms-template').value=template;
    let msg=SMS_TEMPLATES[template]||'';
    if(to) msg=msg.replace('{party}',to);
    if(amount) msg=msg.replace('{amount}','৳'+pf(amount));
    document.getElementById('sms-msg').value=msg;
  }
  m.style.display='flex';
}

function openEmailModal(to, template, amount){
  const m=document.getElementById('email-modal');
  if(!m) return;
  if(to) document.getElementById('email-to').value=to;
  if(template){
    document.getElementById('email-template').value=template;
    applyEmailTemplate(to, amount);
  }
  m.style.display='flex';
}

function applySmsTemplate(){
  const tpl=document.getElementById('sms-template')?.value;
  const to=document.getElementById('sms-to')?.value||'{party}';
  let msg=SMS_TEMPLATES[tpl]||'';
  msg=msg.replace('{party}',to).replace('{amount}','[Amount]');
  document.getElementById('sms-msg').value=msg;
  updateSmsCount();
}

function applyEmailTemplate(to, amount){
  const tpl=document.getElementById('email-template')?.value;
  const toVal=to||document.getElementById('email-to')?.value||'{party}';
  let body=EMAIL_TEMPLATES[tpl]||'';
  body=body.replace(/{party}/g,toVal).replace(/{amount}/g,amount?'৳'+pf(amount):'[Amount]');
  document.getElementById('email-body').value=body;
  const subjects={invoice:'Invoice from Ayan Agro International Limited',statement:'Account Statement',reminder:'Payment Reminder - Action Required',order:'Order Confirmation',custom:''};
  if(subjects[tpl]) document.getElementById('email-subject').value=subjects[tpl];
}

function updateSmsCount(){
  const msg=document.getElementById('sms-msg')?.value||'';
  const el=document.getElementById('sms-char-count');
  if(el) el.textContent=msg.length+' / 160 characters';
}

function sendSms(){
  const to=document.getElementById('sms-to')?.value?.trim();
  const msg=document.getElementById('sms-msg')?.value?.trim();
  if(!to||!msg){ alert('⚠️ Recipient and message are required.'); return; }
  if(!DB.smsLog) DB.smsLog=[];
  DB.smsLog.unshift({id:newId(),to,msg,date:new Date().toISOString().split('T')[0],time:new Date().toLocaleTimeString(),status:'Sent'});
  saveDB();
  document.getElementById('sms-modal').style.display='none';
  logAudit('SMS','Communication','SMS sent to '+to);
  alert('✅ SMS logged successfully!\n\nNote: Connect an SMS gateway (e.g. SSL Wireless, Twilio) to send real SMS.');
  renderSmsInt();
}

function sendEmail(){
  const to=document.getElementById('email-to')?.value?.trim();
  const subject=document.getElementById('email-subject')?.value?.trim();
  const body=document.getElementById('email-body')?.value?.trim();
  if(!to||!subject){ alert('⚠️ Recipient and subject are required.'); return; }
  if(!DB.emailLog) DB.emailLog=[];
  DB.emailLog.unshift({id:newId(),to,subject,body,date:new Date().toISOString().split('T')[0],time:new Date().toLocaleTimeString(),status:'Sent'});
  saveDB();
  document.getElementById('email-modal').style.display='none';
  logAudit('EMAIL','Communication','Email sent to '+to);
  // Open mailto as fallback
  const mailto='mailto:'+encodeURIComponent(to)+'?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body);
  window.open(mailto,'_blank');
  renderEmailNotif();
}

