// ── Payment Reminders ──────────────────────────────────────────
function renderPayRemind(){
  const txns=DB.tx||[];
  const today=new Date().toISOString().split('T')[0];

  // Find overdue sales (unpaid)
  const salesByParty={};
  txns.forEach(t=>{
    const type=(t.type||'').toLowerCase();
    if(type==='sale'||type==='sales advance'){
      if(!salesByParty[t.party]) salesByParty[t.party]={due:0,lastDate:t.date};
      salesByParty[t.party].due+=txAmt(t);
      if(t.date>salesByParty[t.party].lastDate) salesByParty[t.party].lastDate=t.date;
    }
    if(type==='sales receipt'||type==='cash received'||type==='cheque received'){
      if(!salesByParty[t.party]) salesByParty[t.party]={due:0,lastDate:t.date};
      salesByParty[t.party].due-=txAmt(t);
    }
  });

  const reminders=Object.entries(salesByParty)
    .filter(([,v])=>v.due>0)
    .map(([party,v])=>{
      const daysSince=Math.ceil((new Date(today)-new Date(v.lastDate))/(1000*60*60*24));
      return {party,due:v.due,lastDate:v.lastDate,daysSince,
        priority:daysSince>60?'Critical':daysSince>30?'High':daysSince>15?'Medium':'Low'};
    })
    .sort((a,b)=>b.due-a.due);

  const PCOLOR={Critical:'#dc2626',High:'#f59e0b',Medium:'#2563eb',Low:'#16a34a'};
  const totalDue=reminders.reduce((s,r)=>s+r.due,0);

  const cards=document.getElementById('remind-cards');
