// ── Alerts ─────────────────────────────────────────────────────
function generateAlerts(){
  const alerts=[];
  const txns=DB.tx||[];
  const today=new Date().toISOString().split('T')[0];

  // Overdue payments
  const salesByParty={};
  txns.forEach(t=>{
    const type=(t.type||'').toLowerCase();
    if(type==='sale'){
      if(!salesByParty[t.party]) salesByParty[t.party]=0;
      salesByParty[t.party]+=txAmt(t);
    }
    if(type==='sales receipt'||type==='cash received'){
      if(!salesByParty[t.party]) salesByParty[t.party]=0;
      salesByParty[t.party]-=txAmt(t);
    }
  });
  Object.entries(salesByParty).forEach(([party,due])=>{
    if(due>500000) alerts.push({type:'danger',icon:'🚨',title:'High Outstanding Due',msg:party+' owes ৳'+pf(due)+'. Immediate follow-up required.',time:'Now'});
    else if(due>100000) alerts.push({type:'warning',icon:'⚠️',title:'Payment Due',msg:party+' has outstanding balance of ৳'+pf(due),time:'Now'});
  });

  // Low stock alerts
  (DB.products||[]).forEach(p=>{
    if(parseFloat(p.stockQty||0)<10) alerts.push({type:'warning',icon:'📦',title:'Low Stock Alert',msg:(p.name||'Product')+' stock is critically low: '+p.stockQty+' units remaining.',time:'Now'});
  });

  // Tender deadlines
  (DB.tenders||[]).forEach(t=>{
    if(t.subdate){
      const days=Math.ceil((new Date(t.subdate)-new Date())/(1000*60*60*24));
      if(days>=0&&days<=3) alerts.push({type:'danger',icon:'📋',title:'Tender Deadline',msg:'Tender "'+t.title+'" submission deadline in '+days+' day(s)!',time:t.subdate});
    }
  });

  // Cheque alerts
  (DB.cheques||[]).filter(c=>c.status==='Pending').forEach(c=>{
    if(c.dueDate){
      const days=Math.ceil((new Date(c.dueDate)-new Date())/(1000*60*60*24));
      if(days<=3) alerts.push({type:'warning',icon:'🏦',title:'Cheque Due',msg:'Cheque #'+c.chequeNo+' for ৳'+pf(c.amount)+' due in '+days+' day(s).',time:c.dueDate});
    }
  });

  if(!alerts.length) alerts.push({type:'success',icon:'✅',title:'All Clear',msg:'No critical alerts at this time. Business is running smoothly!',time:'Now'});
  return alerts;
}






