/* FIX (2026-08-27): approveTx() (below, the Transactions page's own Approve
   button) was the only one of three transaction-approval entry points that
   did the job completely — it flips t.approvalStatus AND actually posts the
   money via applyTxBalance()/applyTxStock()/applyAssetRegister(). The other
   two (approveAll() just below, and approveTransaction() on the Pending
   Approvals page) each grew their own partial copy: one only ever touched
   t.status, the other set approval fields but never called applyTxBalance()
   at all — so clicking either "approved" a transaction cosmetically (an
   approvalLog/audit entry, a success toast) while it stayed invisibly stuck
   as Pending everywhere that actually reads t.approvalStatus — the Pending
   badge, the KPI counts, and posted() in the balance engine, which is what
   actually decides whether a transaction's money counts toward any
   customer/bank/trial-balance total. That's exactly why a Customer
   Collection could be "approved" by an Admin and still show Pending to the
   person who entered it, with the customer's dues and the bank balance both
   left untouched. All three entry points now share this one function, so
   the fields that get flipped and the balance/stock/asset posting that
   actually happens can never drift apart again. */
function _applyTxApprovalCore(tx, ov){
  if(!tx || tx.approvalStatus==='Approved') return false;
  tx.approved=true;
  tx.status='Approved';
  tx.approvalStatus='Approved';
  tx.needsApproval=false;
  /* FIX (2026-08-29): both fields used `||`, so a record that had been
     rejected and re-approved, or that carried leftover approval fields from
     an earlier build, kept the OLD approver name and timestamp — the audit
     trail credited the wrong person. The approver is whoever is approving
     right now, always. */
  tx.approvedAt=new Date().toISOString();
  tx.approvedBy=(currentUser?.name||'Admin');
  if(ov && ov.override && typeof window.MakerChecker!=='undefined'){
    window.MakerChecker.recordOverride(tx,'Transaction',ov.reason);
  }
  applyTxBalance(tx,1);
  try{ applyTxStock(tx,1); }catch(e){ console.warn('stock sync on approve', e); }
  try{ applyAssetRegister(tx,1); }catch(e){ console.warn('asset register sync on approve', e); }
  try{ syncWeightLossExpense(tx); }catch(e){ console.warn('weight-loss expense sync on approve', e); }
  return true;
}

async function approveAll(){
  // FIX (approval gating): this bulk-approve button had no permission check
  // at all — any logged-in role could mass-approve every pending
  // transaction. Restricted to Admin, same rule as approveTx()/approveOrder().
  if(typeof isTopApprover!=='function'||!isTopApprover()){toast('Only Admin can approve transactions','e');return;}
  /* MAKER-CHECKER: bulk approve deliberately has NO override path. An
     override needs a reason written per record, and a single click that
     quietly self-approves an entire batch is precisely what separation of
     duties is meant to stop. Own entries are skipped and reported; they can
     still be approved one at a time, with a reason. */
  let _skipped=0, _done=0;
  (DB.tx||[]).forEach(t=>{
    if(t.status==='Pending'||t.needsApproval||t.approvalStatus==='Pending'){
      if(window.MakerChecker.isSelf(t)){ _skipped++; return; }
      if(_applyTxApprovalCore(t)) _done++;
    }
  });
  renderPendApprove();
  if(_skipped){
    toast(_done+' approved. '+_skipped+' entered by you were skipped \u2014 approve those individually to record a reason.','i');
  }
  /* FIX (2026-08-28, "approval resets back to Pending after refresh"): see
     _forceSaveAndConfirm() — approving a whole batch never changes how
     many transactions exist, so this was exactly the coalesced/debounced
     saveDB() case a fast refresh could beat to the server. */
  let saved = true;
  if(typeof _forceSaveAndConfirm === 'function'){
    try {
      saved = await _forceSaveAndConfirm();
    } catch(e) {
      console.warn('[approveAll] Save confirmation error:', e);
      saved = false;
    }
  } else {
    saveDB();
    saved = true;
  }
  if(saved === false){ toast('Approved on screen, but the server save failed — refreshing right now would lose this. Check your connection and try again.','e'); return; }
  logAudit('APPROVE_ALL','Transaction',_done+' pending transaction(s) approved'+(_skipped?', '+_skipped+' self-entered skipped':''));
}

