  DB.tx=(DB.tx||[]).filter(t=>{ if(seen.has(t.id)) return false; seen.add(t.id); return true; });
  saveDB();
  alert('✅ Duplicate records removed.');
  logAudit('CLEAN','System','Duplicates removed');
  runHealthCheck();
}

function clearOldAuditLog(){
  const cutoff=new Date(); cutoff.setDate(cutoff.getDate()-90);
  const cutoffStr=cutoff.toISOString().split('T')[0];
  const before=(DB.auditLog||[]).length;
  DB.auditLog=(DB.auditLog||[]).filter(a=>_dk(a.date)>=_dk(cutoffStr));
  saveDB();
  alert('✅ Removed '+(before-(DB.auditLog||[]).length)+' old audit entries.');
  logAudit('CLEAN','System','Old audit logs cleared');
  runHealthCheck();
}

async function exportFullBackup(){
  // See collectBackupExtras() (Backup & Restore section) for why Ledger and
  // Quotations — neither of which lives in DB — need fetching separately.
  const extras = (typeof collectBackupExtras==='function') ? await collectBackupExtras() : { ledgerEntries:null, quotationsData:null, warnings:[] };
  DB.lastBackup=new Date().toISOString().split('T')[0];
  saveDB();
  const exportObj=Object.assign({}, DB, { ledgerEntries: extras.ledgerEntries, quotationsData: extras.quotationsData });
  const blob=new Blob([JSON.stringify(exportObj,null,2)],{type:'application/json'});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');
  a.href=url; a.download='AyanAgro_FullBackup_'+new Date().toISOString().split('T')[0]+'.json';
  a.click(); URL.revokeObjectURL(url);
  logAudit('BACKUP','System','Full backup exported');
  if(typeof warnIfBackupIncomplete==='function') warnIfBackupIncomplete(extras);
}




