// ── Product P&L ────────────────────────────────────────────────
function renderProdPL(){
  const today=new Date().toISOString().split('T')[0];
  const fromEl=document.getElementById('ppl-from');
  const toEl=document.getElementById('ppl-to');
  if(!fromEl.value) fromEl.value=today.slice(0,7)+'-01';
  if(!toEl.value) toEl.value=today;
  const from=fromEl.value, to=toEl.value;
  const txns=(DB.tx||[]).filter(t=>_dk(t.date)>=_dk(from)&&_dk(t.date)<=_dk(to));

  // Group sales by product
  const prodMap={};
  txns.forEach(t=>{
    const type=(t.type||'').toLowerCase();
    const prod=t.prod||t.desc||'Unknown';
    if(!prodMap[prod]) prodMap[prod]={product:prod,salesQty:0,salesAmt:0,purchaseAmt:0,costAmt:0};
    if(type==='sale'||type==='sales advance'){
      prodMap[prod].salesQty+=parseFloat(t.qty||t.quantity||0);
      prodMap[prod].salesAmt+=parseFloat(txAmt(t));
    }
    if(type==='purchase'||type==='warehouse purchase'){
      prodMap[prod].purchaseAmt+=parseFloat(txAmt(t));
    }
    if(['salary','transport','loading','unloading','commission','fuel'].some(k=>type.includes(k))){
      // Distribute costs proportionally (simplified)
      const prods=Object.keys(prodMap);
      if(prods.length>0) prodMap[prod].costAmt+=parseFloat(txAmt(t))/prods.length;
    }
  });

  const _cogsMap=window.cogsByProduct(txns);
  const rows=Object.values(prodMap).map(p=>{
    const _c=_cogsMap[p.product]||_cogsMap[String(p.product).trim()];
    p.cogs=_c?_c.cogs:0;
    p.grossProfit=p.salesAmt-p.cogs;
    p.netProfit=p.grossProfit-p.costAmt;
    p.margin=p.salesAmt>0?((p.netProfit/p.salesAmt)*100).toFixed(1):0;
    return p;
  }).sort((a,b)=>b.netProfit-a.netProfit);

  const totalSales=rows.reduce((s,r)=>s+r.salesAmt,0);
  const totalProfit=rows.reduce((s,r)=>s+r.netProfit,0);
  const totalGross=rows.reduce((s,r)=>s+r.grossProfit,0);

  const cards=document.getElementById('ppl-cards');
  if(cards) cards.innerHTML=[
    {label:'Total Sales',val:'৳'+pf(totalSales),icon:'💰',color:'#16a34a'},
    {label:'Gross Profit',val:'৳'+pf(totalGross),icon:'📈',color:'#2563eb'},
    {label:'Net Profit',val:'৳'+pf(totalProfit),icon:'🏆',color:totalProfit>=0?'#16a34a':'#dc2626'},
    {label:'Products',val:rows.length,icon:'📦',color:'#7c3aed'}
  ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
    <div style="font-size:22px;">${c.icon}</div>
    <div style="font-size:17px;font-weight:900;color:${c.color};">${c.val}</div>
    <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)}</div>
  </div>`).join('');

  const body=document.getElementById('ppl-body');
  if(!body) return;
  if(!rows.length){
    body.innerHTML='<div style="text-align:center;padding:40px;color:#9ca3af;">No product transactions in selected period.</div>';
    return;
  }
  body.innerHTML=`<table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
      <th style="padding:9px 12px;text-align:left;">Product</th>
      <th style="padding:9px 12px;text-align:right;">Sales Qty</th>
      <th style="padding:9px 12px;text-align:right;">Sales (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Purchase (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Gross Profit (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Net Profit (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Margin %</th>
    </tr></thead>
    <tbody>${rows.map((r,i)=>`<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
      <td style="padding:8px 12px;font-weight:700;">${r.product}</td>
      <td style="padding:8px 12px;text-align:right;">${pf(r.salesQty)}</td>
      <td style="padding:8px 12px;text-align:right;">৳${pf(r.salesAmt)}</td>
      <td style="padding:8px 12px;text-align:right;color:#dc2626;">৳${pf(r.purchaseAmt)}</td>
      <td style="padding:8px 12px;text-align:right;color:${r.grossProfit>=0?'#16a34a':'#dc2626'};font-weight:700;">৳${pf(r.grossProfit)}</td>
      <td style="padding:8px 12px;text-align:right;color:${r.netProfit>=0?'#16a34a':'#dc2626'};font-weight:700;">৳${pf(r.netProfit)}</td>
      <td style="padding:8px 12px;text-align:right;font-weight:700;color:${r.margin>=15?'#16a34a':r.margin>=5?'#f59e0b':'#dc2626'};">${r.margin}%</td>
    </tr>`).join('')}
    <tr style="background:#f0fdf4;font-weight:800;border-top:2px solid #16a34a;">
      <td colspan="2" style="padding:9px 12px;color:#0f3d26;">TOTAL</td>
      <td style="padding:9px 12px;text-align:right;">৳${pf(totalSales)}</td>
      <td style="padding:9px 12px;text-align:right;color:#dc2626;">৳${pf(rows.reduce((s,r)=>s+r.purchaseAmt,0))}</td>
      <td style="padding:9px 12px;text-align:right;color:#16a34a;">৳${pf(totalGross)}</td>
      <td style="padding:9px 12px;text-align:right;color:#16a34a;">৳${pf(totalProfit)}</td>
      <td style="padding:9px 12px;text-align:right;">${totalSales>0?((totalProfit/totalSales)*100).toFixed(1):0}%</td>
    </tr></tbody></table>`;
}

// ── Sales by Product ───────────────────────────────────────────
function renderSalesByProd(){
  const today=new Date().toISOString().split('T')[0];
  const fromEl=document.getElementById('sbp-from');
  const toEl=document.getElementById('sbp-to');
  if(!fromEl.value) fromEl.value=today.slice(0,7)+'-01';
  if(!toEl.value) toEl.value=today;
  const from=fromEl.value, to=toEl.value;

  const sales=(DB.tx||[]).filter(t=>{
    const type=(t.type||'').toLowerCase();
    return (type==='sale'||type==='sales advance')&&_dk(t.date)>=_dk(from)&&_dk(t.date)<=_dk(to);
  });

  const prodMap={};
  sales.forEach(t=>{
    const prod=t.prod||t.desc||'Unknown';
    if(!prodMap[prod]) prodMap[prod]={product:prod,qty:0,amount:0,txns:0,customers:new Set()};
    prodMap[prod].qty+=parseFloat(t.qty||t.quantity||0);
    prodMap[prod].amount+=parseFloat(txAmt(t));
    prodMap[prod].txns++;
    if(t.party) prodMap[prod].customers.add(t.party);
  });

  const rows=Object.values(prodMap).map(p=>({...p,customers:p.customers.size}))
    .sort((a,b)=>b.amount-a.amount);
  const totalAmt=rows.reduce((s,r)=>s+r.amount,0);
  const totalQty=rows.reduce((s,r)=>s+r.qty,0);

  const cards=document.getElementById('sbp-cards');
  if(cards) cards.innerHTML=[
    {label:'Total Revenue',val:'৳'+pf(totalAmt),icon:'💰',color:'#16a34a'},
    {label:'Total Qty Sold',val:pf(totalQty),icon:'📦',color:'#2563eb'},
    {label:'Products Sold',val:rows.length,icon:'🏷️',color:'#7c3aed'},
    {label:'Transactions',val:sales.length,icon:'📋',color:'#f59e0b'}
  ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
    <div style="font-size:22px;">${c.icon}</div>
    <div style="font-size:17px;font-weight:900;color:${c.color};">${c.val}</div>
    <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)}</div>
  </div>`).join('');

  const body=document.getElementById('sbp-body');
  if(!body) return;
  if(!rows.length){
    body.innerHTML='<div style="text-align:center;padding:40px;color:#9ca3af;">No sales in selected period.</div>';
    return;
  }
  body.innerHTML=`<table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
      <th style="padding:9px 12px;text-align:left;">Product</th>
      <th style="padding:9px 12px;text-align:right;">Qty Sold</th>
      <th style="padding:9px 12px;text-align:right;">Revenue (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Avg Rate (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Transactions</th>
      <th style="padding:9px 12px;text-align:right;">Customers</th>
      <th style="padding:9px 12px;text-align:right;">Share %</th>
    </tr></thead>
    <tbody>${rows.map((r,i)=>`<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
      <td style="padding:8px 12px;font-weight:700;">${r.product}</td>
      <td style="padding:8px 12px;text-align:right;">${pf(r.qty)}</td>
      <td style="padding:8px 12px;text-align:right;font-weight:700;color:#16a34a;">৳${pf(r.amount)}</td>
      <td style="padding:8px 12px;text-align:right;">৳${pf(r.qty>0?r.amount/r.qty:0)}</td>
      <td style="padding:8px 12px;text-align:right;">${r.txns}</td>
      <td style="padding:8px 12px;text-align:right;">${r.customers}</td>
      <td style="padding:8px 12px;text-align:right;">
        <div style="display:flex;align-items:center;gap:6px;justify-content:flex-end;">
          <div style="width:50px;height:6px;background:#e5e7eb;border-radius:3px;overflow:hidden;">
            <div style="width:${totalAmt>0?(r.amount/totalAmt*100).toFixed(0):0}%;height:100%;background:#16a34a;border-radius:3px;"></div>
          </div>
          ${totalAmt>0?(r.amount/totalAmt*100).toFixed(1):0}%
        </div>
      </td>
    </tr>`).join('')}</tbody></table>`;
}

