// ── Google Drive Backup ────────────────────────────────────────
function connectGDrive(){
  const clientId=document.getElementById('gdrive-client')?.value?.trim();
  if(!clientId){alert('⚠️ Please enter your Google Client ID first.\n\nGet it from: console.cloud.google.com → APIs & Services → Credentials');return;}
  alert('🔗 Google Drive Connection\n\nTo complete setup:\n1. Go to console.cloud.google.com\n2. Create a project & enable Drive API\n3. Create OAuth 2.0 credentials\n4. Add your domain to authorized origins\n\nOnce configured, this button will open Google OAuth login.');
  logAudit('GDRIVE','Backup','Google Drive connection attempted');
}



function renderGDrive(){
  renderBackupRestore();
}


