// ── VAT Management ────────────────────────────────────────────
function renderVatMgmt(){
  const today=new Date().toISOString().split('T')[0];
  const fromEl=document.getElementById('vat-from');
  const toEl=document.getElementById('vat-to');
  if(!fromEl.value) fromEl.value=today.slice(0,7)+'-01';
  if(!toEl.value) toEl.value=today;
  const from=fromEl.value, to=toEl.value;
  const txns=(DB.tx||[]).filter(t=>_dk(t.date)>=_dk(from)&&_dk(t.date)<=_dk(to));

  const VAT_RATE=0.15; // 15% VAT
  let vatCollected=0, vatPaid=0;
  const salesRows=[], purchaseRows=[];

  txns.forEach(t=>{
    const type=(t.type||'').toLowerCase();
    const amt=txAmt(t);
    if(type==='sale'||type==='sales advance'){
      const vat=amt*VAT_RATE/(1+VAT_RATE);
      vatCollected+=vat;
      salesRows.push({...t,vat});
    }
    if(type==='purchase'||type==='warehouse purchase'){
      const vat=amt*VAT_RATE/(1+VAT_RATE);
      vatPaid+=vat;
      purchaseRows.push({...t,vat});
    }
  });

  const netVat=vatCollected-vatPaid;
  const cards=document.getElementById('vat-cards');
  if(cards) cards.innerHTML=[
    {label:'VAT Collected (Output)',val:'৳'+pf(vatCollected),icon:'📤',color:'#16a34a'},
    {label:'VAT Paid (Input)',val:'৳'+pf(vatPaid),icon:'📥',color:'#dc2626'},
    {label:'Net VAT Liability',val:'৳'+pf(netVat),icon:'🧾',color:netVat>=0?'#f59e0b':'#16a34a'},
    {label:'VAT Rate',val:'15%',icon:'%',color:'#2563eb'}
  ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
    <div style="font-size:22px;">${c.icon}</div>
    <div style="font-size:17px;font-weight:900;color:${c.color};">${c.val}</div>
    <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)}</div>
  </div>`).join('');

  const body=document.getElementById('vat-body');
  if(!body) return;
  body.innerHTML=`
  <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
    <div style="padding:12px 16px;background:#f0fdf4;border-bottom:1px solid #e5e7eb;font-weight:800;color:#0f3d26;font-size:13px;">📤 Output VAT (Sales)</div>
    <table style="width:100%;border-collapse:collapse;font-size:12px;">
      <thead><tr style="background:#f9fafb;border-bottom:1px solid #e5e7eb;">
        <th style="padding:8px 12px;text-align:left;">Date</th><th style="padding:8px 12px;text-align:left;">Party</th>
        <th style="padding:8px 12px;text-align:right;">Amount (৳)</th><th style="padding:8px 12px;text-align:right;">VAT (৳)</th>
      </tr></thead>
      <tbody>${salesRows.length?salesRows.map((r,i)=>`<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
        <td style="padding:7px 12px;color:#6b7280;">${r.date}</td>
        <td style="padding:7px 12px;">${escHTML(r.party||'—')}</td>
        <td style="padding:7px 12px;text-align:right;">৳${pf(r.amount)}</td>
        <td style="padding:7px 12px;text-align:right;color:#16a34a;font-weight:700;">৳${pf(r.vat)}</td>
      </tr>`).join(''):'<tr><td colspan="4" style="padding:20px;text-align:center;color:#9ca3af;">No sales in period</td></tr>'}
      <tr style="background:#f0fdf4;font-weight:800;border-top:2px solid #16a34a;">
        <td colspan="3" style="padding:8px 12px;color:#0f3d26;">Total Output VAT</td>
        <td style="padding:8px 12px;text-align:right;color:#16a34a;">৳${pf(vatCollected)}</td>
      </tr></tbody>
    </table>
  </div>
  <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
    <div style="padding:12px 16px;background:#fef2f2;border-bottom:1px solid #e5e7eb;font-weight:800;color:#991b1b;font-size:13px;">📥 Input VAT (Purchases)</div>
    <table style="width:100%;border-collapse:collapse;font-size:12px;">
      <thead><tr style="background:#f9fafb;border-bottom:1px solid #e5e7eb;">
        <th style="padding:8px 12px;text-align:left;">Date</th><th style="padding:8px 12px;text-align:left;">Party</th>
        <th style="padding:8px 12px;text-align:right;">Amount (৳)</th><th style="padding:8px 12px;text-align:right;">VAT (৳)</th>
      </tr></thead>
      <tbody>${purchaseRows.length?purchaseRows.map((r,i)=>`<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
        <td style="padding:7px 12px;color:#6b7280;">${r.date}</td>
        <td style="padding:7px 12px;">${escHTML(r.party||'—')}</td>
        <td style="padding:7px 12px;text-align:right;">৳${pf(r.amount)}</td>
        <td style="padding:7px 12px;text-align:right;color:#dc2626;font-weight:700;">৳${pf(r.vat)}</td>
      </tr>`).join(''):'<tr><td colspan="4" style="padding:20px;text-align:center;color:#9ca3af;">No purchases in period</td></tr>'}
      <tr style="background:#fef2f2;font-weight:800;border-top:2px solid #dc2626;">
        <td colspan="3" style="padding:8px 12px;color:#991b1b;">Total Input VAT</td>
        <td style="padding:8px 12px;text-align:right;color:#dc2626;">৳${pf(vatPaid)}</td>
      </tr></tbody>
    </table>
  </div>`;
}

// ── Payroll ────────────────────────────────────────────────────
function openPayrollModal(){
  document.getElementById('payroll-modal').style.display='flex';
  document.getElementById('pr-month').value=new Date().toISOString().slice(0,7);
  ['pr-name','pr-basic','pr-allow','pr-bonus','pr-deduct','pr-net','pr-notes'].forEach(id=>{
    const el=document.getElementById(id); if(el) el.value='';
  });
}

function calcPayroll(){
  const basic=parseFloat(document.getElementById('pr-basic')?.value||0);
  const allow=parseFloat(document.getElementById('pr-allow')?.value||0);
  const bonus=parseFloat(document.getElementById('pr-bonus')?.value||0);
  const deduct=parseFloat(document.getElementById('pr-deduct')?.value||0);
  const net=basic+allow+bonus-deduct;
  const netEl=document.getElementById('pr-net');
  if(netEl) netEl.value=net.toFixed(2);
}

function savePayroll(){
  const name=document.getElementById('pr-name')?.value?.trim();
  const month=document.getElementById('pr-month')?.value;
  if(!name||!month){alert('⚠️ Employee name and month are required.');return;}
  if(!DB.payroll) DB.payroll=[];
  const record={
    id:newId(),name,month,
    basic:parseFloat(document.getElementById('pr-basic')?.value||0),
    allowance:parseFloat(document.getElementById('pr-allow')?.value||0),
    bonus:parseFloat(document.getElementById('pr-bonus')?.value||0),
    deduction:parseFloat(document.getElementById('pr-deduct')?.value||0),
    net:parseFloat(document.getElementById('pr-net')?.value||0),
    mode:document.getElementById('pr-mode')?.value||'Cash',
    notes:document.getElementById('pr-notes')?.value||'',
    paidAt:new Date().toISOString()
  };
  DB.payroll.push(record);
  saveDB();
  document.getElementById('payroll-modal').style.display='none';
  logAudit('PAYROLL','Salary','Salary processed for '+name);
  renderPayroll();
}



async function deletePayroll(id){
  if(!await __confirm('Delete this payroll record?'))return;
  DB.payroll=(DB.payroll||[]).filter(p=>p.id!==id);
  saveDB(); renderPayroll();
}

// ── Profit Distribution ────────────────────────────────────────
function openProfitDistModal(){
  document.getElementById('pdist-modal').style.display='flex';
  document.getElementById('pd-period').value=new Date().toISOString().slice(0,7);
  document.getElementById('pd-total').value='';
  document.getElementById('pd-notes').value='';
  calcProfitDist();
}

function calcProfitDist(){
  const total=parseFloat(document.getElementById('pd-total')?.value||0);
  const partners=DB.partners||[];
  const el=document.getElementById('pd-breakdown');
  if(!el) return;
  if(!partners.length){
    el.innerHTML='<div style="color:#9ca3af;text-align:center;">No partners configured. Add partners first.</div>';
    return;
  }
  const totalShare=partners.reduce((s,p)=>s+(p.share||0),0)||100;
  el.innerHTML=`<div style="font-weight:700;color:#0f3d26;margin-bottom:10px;">Distribution Breakdown:</div>`+
    partners.map(p=>{
      const share=(p.share||0)/totalShare;
      const amount=total*share;
      return `<div style="display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid #e5e7eb;">
        <span style="font-weight:600;">${escHTML(p.name)}</span>
        <span style="color:#6b7280;">${(p.share||0).toFixed(1)}%</span>
        <span style="font-weight:800;color:#16a34a;">৳${pf(amount)}</span>
      </div>`;
    }).join('')+
    `<div style="display:flex;justify-content:space-between;padding:8px 0;font-weight:800;color:#0f3d26;border-top:2px solid #16a34a;margin-top:4px;">
      <span>Total</span><span></span><span style="color:#16a34a;">৳${pf(total)}</span>
    </div>`;
}





async function deleteProfitDist(id){
  if(!await __confirm('Delete this distribution record?'))return;
  DB.profitDist=(DB.profitDist||[]).filter(d=>d.id!==id);
  saveDB(); renderProfitDist();
}

// ── Payment Schedule ───────────────────────────────────────────
function openPaySchdModal(){
  document.getElementById('payschd-modal').style.display='flex';
  ['ps-desc','ps-party','ps-amount'].forEach(id=>{const el=document.getElementById(id);if(el)el.value='';});
  document.getElementById('ps-due').value=new Date().toISOString().split('T')[0];
}

function savePaySchd(){
  const desc=document.getElementById('ps-desc')?.value?.trim();
  const due=document.getElementById('ps-due')?.value;
  const amount=parseFloat(document.getElementById('ps-amount')?.value||0);
  if(!desc||!due||!amount){alert('⚠️ Description, due date and amount are required.');return;}
  if(!DB.paySchedule) DB.paySchedule=[];
  DB.paySchedule.push({
    id:newId(),desc,due,amount,
    party:document.getElementById('ps-party')?.value||'',
    type:document.getElementById('ps-type')?.value||'Payable',
    status:'Pending',
    createdAt:new Date().toISOString()
  });
  saveDB();
  document.getElementById('payschd-modal').style.display='none';
  logAudit('SCHEDULE','Payment','Schedule added: '+desc);
  renderPaySchd();
}

function markSchdPaid(id){
  const s=(DB.paySchedule||[]).find(x=>x.id===id);
  if(s){s.status='Paid';s.paidAt=new Date().toISOString();}
  saveDB(); renderPaySchd();
}

async function deletePaySchd(id){
  if(!await __confirm('Delete this schedule?'))return;
  DB.paySchedule=(DB.paySchedule||[]).filter(x=>x.id!==id);
  saveDB(); renderPaySchd();
}

function renderPaySchd(){
  const schd=DB.paySchedule||[];
  const today=new Date().toISOString().split('T')[0];
  const pending=schd.filter(s=>s.status==='Pending');
  const overdue=pending.filter(s=>s.due<today);
  const upcoming=pending.filter(s=>s.due>=today);
  const totalPending=pending.reduce((s,x)=>s+x.amount,0);

  const cards=document.getElementById('payschd-cards');
  if(cards) cards.innerHTML=[
    {label:'Total Pending',val:'৳'+pf(totalPending),icon:'⏳',color:'#f59e0b'},
    {label:'Overdue',val:overdue.length,icon:'🚨',color:'#dc2626'},
    {label:'Upcoming',val:upcoming.length,icon:'📅',color:'#2563eb'},
    {label:'Total Schedules',val:schd.length,icon:'📋',color:'#16a34a'}
  ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
    <div style="font-size:22px;">${c.icon}</div>
    <div style="font-size:17px;font-weight:900;color:${c.color};">${c.val}</div>
    <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)}</div>
  </div>`).join('');

  const body=document.getElementById('payschd-body');
  if(!body) return;
  if(!schd.length){
    body.innerHTML='<div style="text-align:center;padding:40px;color:#9ca3af;">No payment schedules yet.</div>';
    return;
  }
  const sorted=[...schd].sort((a,b)=>a.due.localeCompare(b.due));
  body.innerHTML=`<table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
      <th style="padding:9px 12px;text-align:left;">Description</th>
      <th style="padding:9px 12px;text-align:left;">Party</th>
      <th style="padding:9px 12px;text-align:left;">Due Date</th>
      <th style="padding:9px 12px;text-align:right;">Amount (৳)</th>
      <th style="padding:9px 12px;text-align:left;">Type</th>
      <th style="padding:9px 12px;text-align:left;">Status</th>
      <th style="padding:9px 12px;text-align:center;">Actions</th>
    </tr></thead>
    <tbody>${sorted.map((s,i)=>{
      const isOverdue=s.status==='Pending'&&s.due<today;
      return `<tr style="border-bottom:1px solid #f3f4f6;background:${isOverdue?'#fef2f2':i%2?'#f9fafb':'#fff'};">
        <td style="padding:8px 12px;font-weight:700;">${escHTML(s.desc)}</td>
        <td style="padding:8px 12px;color:#6b7280;">${escHTML(s.party||'—')}</td>
        <td style="padding:8px 12px;color:${isOverdue?'#dc2626':'#374151'};font-weight:${isOverdue?'700':'400'};">${s.due}${isOverdue?' ⚠️':''}</td>
        <td style="padding:8px 12px;text-align:right;font-weight:700;">৳${pf(s.amount)}</td>
        <td style="padding:8px 12px;"><span style="background:${s.type==='Payable'?'#fef2f2':'#f0fdf4'};color:${s.type==='Payable'?'#dc2626':'#16a34a'};padding:3px 8px;border-radius:20px;font-size:11px;font-weight:700;">${s.type}</span></td>
        <td style="padding:8px 12px;"><span style="background:${s.status==='Paid'?'#f0fdf4':'#fef9c3'};color:${s.status==='Paid'?'#16a34a':'#854d0e'};padding:3px 8px;border-radius:20px;font-size:11px;font-weight:700;">${s.status}</span></td>
        <td style="padding:8px 12px;text-align:center;display:flex;gap:4px;justify-content:center;">
          ${s.status==='Pending'?`<button data-x-click="markSchdPaid(${s.id})" style="background:#f0fdf4;border:1px solid #16a34a;color:#16a34a;padding:3px 8px;border-radius:5px;font-size:11px;cursor:pointer;">✅</button>`:''}
          <button data-x-click="deletePaySchd(${s.id})" style="background:#fef2f2;border:1px solid #dc2626;color:#dc2626;padding:3px 8px;border-radius:5px;font-size:11px;cursor:pointer;">🗑️</button>
        </td>
      </tr>`;
    }).join('')}</tbody></table>`;
}


// ══════════════════════════════════════════════════════════════
// BATCH G: EXPENSE CATEGORIES, OPENING BALANCE, BANK RECON, CHEQUES
// ══════════════════════════════════════════════════════════════

// ── Expense Categories ─────────────────────────────────────────
const EXPENSE_CATEGORY_MAP = {
  'salary payment':'Payroll','employee advance':'Payroll','employee loan':'Payroll',
  'office rent':'Overhead','electricity bill':'Overhead','internet bill':'Overhead',
  'telephone bill':'Overhead','stationery purchase':'Overhead',
  'fuel expense':'Transport','transport cost':'Transport','loading charge':'Transport',
  'unloading charge':'Transport',
  'commission payment':'Sales Cost','brokerage fee':'Sales Cost',
  'legal fee':'Professional','audit fee':'Professional','insurance premium':'Professional',
  'tax payment':'Government','government fee':'Government','license fee':'Government',
  'maintenance cost':'Maintenance','repair expense':'Maintenance',
  'other expense':'Other','interest expense':'Finance','bank charge':'Finance'
};

function getExpenseCategory(type){
  const t=(type||'').toLowerCase();
  for(const [key,cat] of Object.entries(EXPENSE_CATEGORY_MAP)){
    if(t.includes(key)) return cat;
  }
  return 'Other';
}

function renderExpCatsPage(expenses){
  // Render into the actual Expense Categories page (expcat-*)
  const kpiEl=document.getElementById('expcat-kpis');
  const listEl=document.getElementById('expcat-list');
  const txnEl=document.getElementById('expcat-txns');
  if(kpiEl||listEl||txnEl){
    const catTotals={};
    expenses.forEach(t=>{
      const c=t.cat||t.category||t.type||'Other';
      catTotals[c]=(catTotals[c]||0)+txAmt(t);
    });
    const cats=Object.entries(catTotals).sort((a,b)=>b[1]-a[1]);
    const totalX=cats.reduce((s2,c)=>s2+c[1],0);
    const avgX=expenses.length?totalX/expenses.length:0;
    const topX=cats[0]||['-',0];
    if(kpiEl) kpiEl.innerHTML=[
      {l:'Total Expenses',v:f(totalX),c:'#dc2626',i:'\uD83D\uDCB8'},
      {l:'Transactions',v:expenses.length,c:'#2563eb',i:'\uD83E\uDDFE'},
      {l:'Average / Txn',v:f(avgX),c:'#d97706',i:'\uD83D\uDCD0'},
      {l:'Top Category',v:topX[0],c:'#7c3aed',i:'\uD83C\uDFF7\uFE0F'}
    ].map(kk=>`<div style="background:#fff;border:1px solid #e5e7eb;border-left:4px solid ${kk.c};border-radius:10px;padding:14px;">
      <div style="font-size:11px;color:#6b7280;font-weight:700;">${kk.i} ${kk.l}</div>
      <div style="font-size:17px;font-weight:900;color:${kk.c};margin-top:4px;">${kk.v}</div></div>`).join('');
    if(listEl) listEl.innerHTML=cats.length?cats.map(([c,amt])=>{
      const pct=totalX?Math.round(amt/totalX*100):0;
      return `<div style="margin-bottom:10px;">
        <div style="display:flex;justify-content:space-between;font-size:12px;font-weight:600;margin-bottom:3px;">
          <span>${c}</span><span style="color:#dc2626;">${f(amt)} <span style="color:#9ca3af;font-weight:400;">(${pct}%)</span></span></div>
        <div style="height:8px;background:#f1f5f9;border-radius:6px;overflow:hidden;">
          <div style="height:100%;width:${pct}%;background:linear-gradient(90deg,#16a34a,#4ade80);"></div></div></div>`;
    }).join(''):'<div style="text-align:center;padding:30px;color:#9ca3af;">No expenses in this period</div>';
    if(txnEl) txnEl.innerHTML=expenses.length?`<table style="width:100%;border-collapse:collapse;font-size:11.5px;">
      <thead><tr style="background:#f8fafc;"><th style="padding:7px 10px;text-align:left;">Date</th><th style="padding:7px 10px;text-align:left;">Type</th><th style="padding:7px 10px;text-align:left;">Party</th><th style="padding:7px 10px;text-align:right;">Amount</th></tr></thead>
      <tbody>${[...expenses].reverse().map(t=>`<tr style="border-bottom:1px solid #f1f5f9;">
        <td style="padding:6px 10px;">${t.date||'-'}</td><td style="padding:6px 10px;">${t.type||'-'}</td>
        <td style="padding:6px 10px;">${escHTML(t.party||'-')}</td>
        <td style="padding:6px 10px;text-align:right;color:#dc2626;font-weight:700;">${f(txAmt(t))}</td></tr>`).join('')}</tbody></table>`
      :'<div style="text-align:center;padding:30px;color:#9ca3af;">No expense transactions</div>';
  }
}

function renderExpCats(){
  const today=new Date().toISOString().split('T')[0];
  const fromEl=document.getElementById('ec-from');
  const toEl=document.getElementById('ec-to');
  let from, to;
  if(fromEl && toEl){
    if(!fromEl.value) fromEl.value=today.slice(0,7)+'-01';
    if(!toEl.value) toEl.value=today;
    from=fromEl.value; to=toEl.value;
  } else {
    // The Expense Categories page uses a period dropdown (expcat-period), not date inputs
    const period=(document.getElementById('expcat-period')||{}).value||'all';
    const d=new Date();
    to=today; from='1970-01-01';
    if(period==='month'){ from=today.slice(0,7)+'-01'; }
    else if(period==='lastmonth'){
      const lm=new Date(d.getFullYear(),d.getMonth()-1,1);
      from=lm.toISOString().split('T')[0];
      to=new Date(d.getFullYear(),d.getMonth(),0).toISOString().split('T')[0];
    }
    else if(period==='year'){ from=d.getFullYear()+'-01-01'; }
  }

  const expenses=(DB.tx||[]).filter(t=>{
    const type=(t.type||'').toLowerCase();
    return _dk(t.date)>=_dk(from)&&_dk(t.date)<=_dk(to)&&(
      type.includes('expense')||type.includes('salary')||type.includes('rent')||
      type.includes('bill')||type.includes('fee')||type.includes('charge')||
      type.includes('payment')&&!type.includes('purchase')&&!type.includes('sales')
    );
  });
  renderExpCatsPage(expenses); // fill the Expense Categories page (expcat-*) before any legacy early-return

  const catMap={};
  expenses.forEach(t=>{
    const cat=getExpenseCategory(t.type);
    if(!catMap[cat]) catMap[cat]={category:cat,total:0,count:0,items:[]};
    catMap[cat].total+=txAmt(t);
    catMap[cat].count++;
    catMap[cat].items.push(t);
  });

  const rows=Object.values(catMap).sort((a,b)=>b.total-a.total);
  const grandTotal=rows.reduce((s,r)=>s+r.total,0);

  const cards=document.getElementById('ec-cards');
  if(cards) cards.innerHTML=[
    {label:'Total Expenses',val:'৳'+pf(grandTotal),icon:'💸',color:'#dc2626'},
    {label:'Categories',val:rows.length,icon:'🗂️',color:'#7c3aed'},
    {label:'Transactions',val:expenses.length,icon:'📋',color:'#2563eb'},
    {label:'Avg per Txn',val:'৳'+pf(expenses.length?grandTotal/expenses.length:0),icon:'📊',color:'#f59e0b'}
  ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
    <div style="font-size:22px;">${c.icon}</div>
    <div style="font-size:17px;font-weight:900;color:${c.color};">${c.val}</div>
    <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)}</div>
  </div>`).join('');

  const body=document.getElementById('ec-body');
  if(!body) return;
  if(!rows.length){
    body.innerHTML='<div style="text-align:center;padding:40px;color:#9ca3af;">No expense transactions in selected period.</div>';
    return;
  }
  body.innerHTML=`<table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
      <th style="padding:9px 12px;text-align:left;">Category</th>
      <th style="padding:9px 12px;text-align:right;">Total (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Transactions</th>
      <th style="padding:9px 12px;text-align:right;">Avg (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Share %</th>
    </tr></thead>
    <tbody>${rows.map((r,i)=>`<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
      <td style="padding:8px 12px;font-weight:700;">${r.category}</td>
      <td style="padding:8px 12px;text-align:right;font-weight:700;color:#dc2626;">৳${pf(r.total)}</td>
      <td style="padding:8px 12px;text-align:right;">${r.count}</td>
      <td style="padding:8px 12px;text-align:right;">৳${pf(r.total/r.count)}</td>
      <td style="padding:8px 12px;text-align:right;">
        <div style="display:flex;align-items:center;gap:6px;justify-content:flex-end;">
          <div style="width:60px;height:6px;background:#e5e7eb;border-radius:3px;overflow:hidden;">
            <div style="width:${grandTotal>0?(r.total/grandTotal*100).toFixed(0):0}%;height:100%;background:#dc2626;border-radius:3px;"></div>
          </div>
          ${grandTotal>0?(r.total/grandTotal*100).toFixed(1):0}%
        </div>
      </td>
    </tr>`).join('')}
    <tr style="background:#fef2f2;font-weight:800;border-top:2px solid #dc2626;">
      <td style="padding:9px 12px;color:#991b1b;">TOTAL</td>
      <td style="padding:9px 12px;text-align:right;color:#dc2626;">৳${pf(grandTotal)}</td>
      <td style="padding:9px 12px;text-align:right;">${expenses.length}</td>
      <td colspan="2"></td>
    </tr></tbody></table>`;

}

