    <!-- Partners -->
    <div style="background:${cardBg};border:1px solid ${border};border-radius:12px;padding:18px;">
      <div style="font-size:14px;font-weight:800;color:#7c3aed;margin-bottom:14px;">🤝 Partner Capital Opening Balances</div>
      ${partners.length?partners.map(p=>`
        <div style="display:flex;align-items:center;gap:10px;margin-bottom:10px;">
          <label style="flex:1;font-size:13px;font-weight:600;color:${textColor};">🤝 ${escHTML(p.name)}</label>
          <div style="text-align:right;">
            <div style="font-size:10px;color:${text2};margin-bottom:2px;">Current: ৳${(p.cap||0).toLocaleString('en-IN',{minimumFractionDigits:2})}</div>
            <input type="number" id="ob-part-${escHTML(p.id||p.name.replace(/\s/g,'_'))}"
              value="${ob['part_'+(p.id||p.name)]||p.cap||0}" placeholder="0.00"
              data-x-change="applyOpeningBal('partner','${p.name}',this.value)"
              style="width:160px;padding:7px 10px;border:1.5px solid ${border};border-radius:8px;font-size:13px;text-align:right;background:${cardBg};color:${textColor};">
          </div>
        </div>`).join('')
      :'<div style="color:#9ca3af;font-size:12px;">No partners found. Add partners first.</div>'}
    </div>

    <!-- Customers -->
    <div style="background:${cardBg};border:1px solid ${border};border-radius:12px;padding:18px;">
      <div style="font-size:14px;font-weight:800;color:#16a34a;margin-bottom:14px;">👥 Customer Opening Balances (Receivable)</div>
      ${customers.length?customers.map(c=>`
