// ── Cheque Management ──────────────────────────────────────────
function openChequeModal(){
  const m=document.getElementById('cheque-modal');
  if(!m) return;
  ['chq-no','chq-party','chq-bank'].forEach(id=>{const el=document.getElementById(id);if(el)el.value='';});
  document.getElementById('chq-amount').value='';
  document.getElementById('chq-date').value=new Date().toISOString().split('T')[0];
  document.getElementById('chq-due').value='';
  document.getElementById('chq-type').value='Received';
  document.getElementById('chq-status').value='Pending';
  m.style.display='flex';
}







function renderChequeMgmt(){
  const cheques=DB.cheques||[];
  const today=new Date().toISOString().split('T')[0];
  const pending=cheques.filter(c=>c.status==='Pending');
  const overdue=pending.filter(c=>c.dueDate&&c.dueDate<today);
  const STATUS_COLOR={Pending:'#f59e0b',Cleared:'#16a34a',Bounced:'#dc2626',Cancelled:'#9ca3af'};

  const cards=document.getElementById('cheque-cards');
  if(cards) cards.innerHTML=[
    {label:'Total Cheques',val:cheques.length,icon:'🏦',color:'#2563eb'},
    {label:'Pending',val:pending.length,icon:'⏳',color:'#f59e0b'},
    {label:'Overdue',val:overdue.length,icon:'🚨',color:'#dc2626'},
    {label:'Total Value',val:'৳'+pf(pending.reduce((s,c)=>s+c.amount,0)),icon:'💰',color:'#16a34a'}
  ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
    <div style="font-size:22px;">${c.icon}</div>
    <div style="font-size:17px;font-weight:900;color:${c.color};">${c.val}</div>
    <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)}</div>
  </div>`).join('');

  const body=document.getElementById('cheque-body');
  if(!body) return;
  if(!cheques.length){
    body.innerHTML='<div style="text-align:center;padding:40px;color:#9ca3af;">No cheques recorded yet.</div>';
    return;
  }
  body.innerHTML=`<table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
      <th style="padding:9px 12px;text-align:left;">Cheque No</th>
      <th style="padding:9px 12px;text-align:left;">Type</th>
      <th style="padding:9px 12px;text-align:left;">Party</th>
      <th style="padding:9px 12px;text-align:right;">Amount (৳)</th>
      <th style="padding:9px 12px;text-align:left;">Issue Date</th>
      <th style="padding:9px 12px;text-align:left;">Due Date</th>
      <th style="padding:9px 12px;text-align:left;">Status</th>
      <th style="padding:9px 12px;text-align:center;">Actions</th>
    </tr></thead>
    <tbody>${cheques.map((c,i)=>{
      const isOverdue=c.status==='Pending'&&c.dueDate&&c.dueDate<today;
      return `<tr style="border-bottom:1px solid #f3f4f6;background:${isOverdue?'#fef2f2':i%2?'#f9fafb':'#fff'};">
        <td style="padding:8px 12px;font-weight:700;">${c.no}</td>
        <td style="padding:8px 12px;"><span style="background:${c.type==='Issued'?'#fef2f2':'#f0fdf4'};color:${c.type==='Issued'?'#dc2626':'#16a34a'};padding:3px 8px;border-radius:20px;font-size:11px;font-weight:700;">${c.type}</span></td>
        <td style="padding:8px 12px;">${escHTML(c.party)}</td>
        <td style="padding:8px 12px;text-align:right;font-weight:700;">৳${pf(c.amount)}</td>
        <td style="padding:8px 12px;color:#6b7280;">${c.issueDate||'—'}</td>
        <td style="padding:8px 12px;color:${isOverdue?'#dc2626':'#6b7280'};font-weight:${isOverdue?'700':'400'};">${c.dueDate||'—'}${isOverdue?' ⚠️':''}</td>
        <td style="padding:8px 12px;"><span style="background:${STATUS_COLOR[c.status]||'#6b7280'}22;color:${STATUS_COLOR[c.status]||'#6b7280'};padding:3px 10px;border-radius:20px;font-size:11px;font-weight:700;">${c.status}</span></td>
        <td style="padding:8px 12px;text-align:center;display:flex;gap:3px;justify-content:center;">
          ${c.status==='Pending'?`<button data-x-click="updateChequeStatus(${c.id},'Cleared')" style="background:#f0fdf4;border:1px solid #16a34a;color:#16a34a;padding:3px 7px;border-radius:5px;font-size:10px;cursor:pointer;">✅</button>
          <button data-x-click="updateChequeStatus(${c.id},'Bounced')" style="background:#fef2f2;border:1px solid #dc2626;color:#dc2626;padding:3px 7px;border-radius:5px;font-size:10px;cursor:pointer;">↩️</button>`:''}
          <button data-x-click="deleteCheque(${c.id})" style="background:#f3f4f6;border:1px solid #d1d5db;color:#6b7280;padding:3px 7px;border-radius:5px;font-size:10px;cursor:pointer;">🗑️</button>
        </td>
      </tr>`;
    }).join('')}</tbody></table>`;
}


// ══════════════════════════════════════════════════════════════
// BATCH H: INVENTORY MOVEMENT, STOCK ADJUSTMENT, LOCATIONS, BANK STATEMENT
// ══════════════════════════════════════════════════════════════

// ── Inventory Movement ─────────────────────────────────────────
function initInvMovementDropdown(){
  const sel=document.getElementById('im-product');
  if(!sel||sel.options.length>1) return;
  (MASTER.products||[]).forEach(p=>{const o=document.createElement('option');o.value=p;o.textContent=p;sel.appendChild(o);});
}

function renderInvMovement(){
  initInvMovementDropdown();
  const today=new Date().toISOString().split('T')[0];
  const fromEl=document.getElementById('im-from');
  const toEl=document.getElementById('im-to');
  if(!fromEl.value) fromEl.value=today.slice(0,7)+'-01';
  if(!toEl.value) toEl.value=today;
  const from=fromEl.value, to=toEl.value;
  const filterProd=document.getElementById('im-product')?.value||'';

  const txns=(DB.tx||[]).filter(t=>{
    const type=(t.type||'').toLowerCase();
    const hasProd=!filterProd||(t.prod||'')===filterProd;
    return _dk(t.date)>=_dk(from)&&_dk(t.date)<=_dk(to)&&hasProd&&(
      type.includes('purchase')||type.includes('sale')||type.includes('warehouse')||type.includes('stock')
    );
  });

  let totalIn=0,totalOut=0;
  const rows=txns.map(t=>{
    const type=(t.type||'').toLowerCase();
    const qty=parseFloat(t.qty||t.quantity||0);
    const isIn=type.includes('purchase')||type.includes('warehouse purchase');
    if(isIn) totalIn+=qty; else totalOut+=qty;
    return {...t,qty,direction:isIn?'IN':'OUT'};
  });

  const cards=document.getElementById('im-cards');
  if(cards) cards.innerHTML=[
    {label:'Stock In',val:pf(totalIn)+' units',icon:'📥',color:'#16a34a'},
    {label:'Stock Out',val:pf(totalOut)+' units',icon:'📤',color:'#dc2626'},
    {label:'Net Movement',val:pf(totalIn-totalOut)+' units',icon:'📊',color:totalIn>=totalOut?'#16a34a':'#dc2626'},
    {label:'Transactions',val:rows.length,icon:'📋',color:'#2563eb'}
  ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
    <div style="font-size:22px;">${c.icon}</div>
    <div style="font-size:17px;font-weight:900;color:${c.color};">${c.val}</div>
    <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)}</div>
  </div>`).join('');

  const body=document.getElementById('im-body');
  if(!body) return;
  if(!rows.length){
    body.innerHTML='<div style="text-align:center;padding:40px;color:#9ca3af;">No inventory movements in selected period.</div>';
    return;
  }
  body.innerHTML=`<table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
      <th style="padding:9px 12px;text-align:left;">Date</th>
      <th style="padding:9px 12px;text-align:left;">Type</th>
      <th style="padding:9px 12px;text-align:left;">Product</th>
      <th style="padding:9px 12px;text-align:left;">Party</th>
      <th style="padding:9px 12px;text-align:right;">Qty</th>
      <th style="padding:9px 12px;text-align:right;">Amount (৳)</th>
      <th style="padding:9px 12px;text-align:center;">Direction</th>
    </tr></thead>
    <tbody>${rows.map((r,i)=>`<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
      <td style="padding:8px 12px;color:#6b7280;">${r.date}</td>
      <td style="padding:8px 12px;">${r.type}</td>
      <td style="padding:8px 12px;font-weight:700;">${escHTML(r.product||r.desc||'—')}</td>
      <td style="padding:8px 12px;">${escHTML(r.party||'—')}</td>
      <td style="padding:8px 12px;text-align:right;font-weight:700;">${pf(r.qty)}</td>
      <td style="padding:8px 12px;text-align:right;">৳${pf(r.amount||0)}</td>
      <td style="padding:8px 12px;text-align:center;">
        <span style="background:${r.direction==='IN'?'#f0fdf4':'#fef2f2'};color:${r.direction==='IN'?'#16a34a':'#dc2626'};padding:3px 10px;border-radius:20px;font-size:11px;font-weight:700;">${r.direction==='IN'?'📥 IN':'📤 OUT'}</span>
      </td>
    </tr>`).join('')}</tbody></table>`;
}

// ── Stock Adjustment ───────────────────────────────────────────
function openStockAdjModal(){
  const m=document.getElementById('stockadj-modal');
  if(!m) return;
  document.getElementById('sa-date').value=new Date().toISOString().split('T')[0];
  ['sa-qty','sa-notes'].forEach(id=>{const el=document.getElementById(id);if(el)el.value='';});
  const sel=document.getElementById('sa-product');
  if(sel&&sel.options.length<=1){
    (MASTER.products||[]).forEach(p=>{const o=document.createElement('option');o.value=p;o.textContent=p;sel.appendChild(o);});
  }
  m.style.display='flex';
}

function saveStockAdj(){
  const product=document.getElementById('sa-product')?.value;
  const qty=parseFloat(document.getElementById('sa-qty')?.value||0);
  const date=document.getElementById('sa-date')?.value;
  if(!product||!qty||!date){alert('⚠️ Date, product and quantity are required.');return;}
  if(!DB.stockAdjustments) DB.stockAdjustments=[];
  const adjType=document.getElementById('sa-adjtype')?.value||'add';
  DB.stockAdjustments.unshift({
    id:newId(),date,product,qty,adjType,
    reason:document.getElementById('sa-reason')?.value||'Other',
    notes:document.getElementById('sa-notes')?.value||'',
    createdAt:new Date().toISOString()
  });
  // Update inventory (array-safe: DB.inventory is the shared products array)
  let item = typeof invFind==='function' ? invFind(product) : null;
  if(!item && typeof invItems==='function'){
    item={id:newId(),name:product,category:'General',cat:'General',unit:'KG',rate:0,cost:0,stock:0,qty:0,stockQty:0,minStock:0,openingStock:0};
    invItems().push(item);
  }
  if(item){
    const cur=parseFloat(item.stock)||0;
    const next = adjType==='add' ? cur+qty : adjType==='remove' ? Math.max(0,cur-qty) : qty;
    invSetQty(item, next);
  }
  saveDB();
  document.getElementById('stockadj-modal').style.display='none';
  logAudit('STOCK','Adjustment','Stock adjusted for '+product);
  renderStockAdj();
}

function renderStockAdj(){
  const adjs=DB.stockAdjustments||[];
  const totalAdded=adjs.filter(a=>a.adjType==='add').reduce((s,a)=>s+a.qty,0);
  const totalRemoved=adjs.filter(a=>a.adjType==='remove').reduce((s,a)=>s+a.qty,0);

  /* FIX (duplicate element ids): 'sa-cards' / 'sa-body' were used by BOTH
     this page and Supplier Aging. That page builds its copies page-scoped
     with ensureDivIn(), but this renderer uses a plain getElementById, so
     the two only stayed apart thanks to the global duplicate-id resolver.
     Renamed to stkadj-* so they are unique on their own. */
  const cards=document.getElementById('stkadj-cards');
  if(cards) cards.innerHTML=[
    {label:'Total Adjustments',val:adjs.length,icon:'⚖️',color:'#2563eb'},
    {label:'Added',val:pf(totalAdded),icon:'➕',color:'#16a34a'},
    {label:'Removed',val:pf(totalRemoved),icon:'➖',color:'#dc2626'},
    {label:'Products Adjusted',val:new Set(adjs.map(a=>a.product)).size,icon:'📦',color:'#7c3aed'}
  ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
    <div style="font-size:22px;">${c.icon}</div>
    <div style="font-size:17px;font-weight:900;color:${c.color};">${c.val}</div>
    <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)}</div>
  </div>`).join('');

  const body=document.getElementById('stkadj-body');
  if(!body) return;
  if(!adjs.length){
    body.innerHTML='<div style="text-align:center;padding:40px;color:#9ca3af;">No stock adjustments yet.</div>';
    return;
  }
  body.innerHTML=`<table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
      <th style="padding:9px 12px;text-align:left;">Date</th>
      <th style="padding:9px 12px;text-align:left;">Product</th>
      <th style="padding:9px 12px;text-align:center;">Type</th>
      <th style="padding:9px 12px;text-align:right;">Qty</th>
      <th style="padding:9px 12px;text-align:left;">Reason</th>
      <th style="padding:9px 12px;text-align:left;">Notes</th>
      <th style="padding:9px 12px;text-align:center;">Action</th>
    </tr></thead>
    <tbody>${adjs.map((a,i)=>`<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
      <td style="padding:8px 12px;color:#6b7280;">${a.date}</td>
      <td style="padding:8px 12px;font-weight:700;">${a.product}</td>
      <td style="padding:8px 12px;text-align:center;">
        <span style="background:${a.adjType==='add'?'#f0fdf4':a.adjType==='remove'?'#fef2f2':'#eff6ff'};color:${a.adjType==='add'?'#16a34a':a.adjType==='remove'?'#dc2626':'#2563eb'};padding:3px 10px;border-radius:20px;font-size:11px;font-weight:700;">${a.adjType==='add'?'➕ Add':a.adjType==='remove'?'➖ Remove':'🎯 Set'}</span>
      </td>
      <td style="padding:8px 12px;text-align:right;font-weight:700;">${pf(a.qty)}</td>
      <td style="padding:8px 12px;color:#6b7280;">${escHTML(a.reason)}</td>
      <td style="padding:8px 12px;color:#6b7280;">${escHTML(a.notes||'—')}</td>
      <td style="padding:8px 12px;text-align:center;">
        <button data-x-click="deleteStockAdj(${a.id})" style="background:#fef2f2;border:1px solid #dc2626;color:#dc2626;padding:3px 8px;border-radius:5px;font-size:11px;cursor:pointer;">🗑️</button>
      </td>
    </tr>`).join('')}</tbody></table>`;
}

async function deleteStockAdj(id){
  if(!await __confirm('Delete this adjustment?'))return;
  DB.stockAdjustments=(DB.stockAdjustments||[]).filter(a=>a.id!==id);
  saveDB(); renderStockAdj();
}

// ── Locations ──────────────────────────────────────────────────
function openLocationModal(){
  const m=document.getElementById('location-modal');
  if(!m) return;
  ['loc-name','loc-addr','loc-contact'].forEach(id=>{const el=document.getElementById(id);if(el)el.value='';});
  m.style.display='flex';
}

function saveLocation(){
  const name=document.getElementById('loc-name')?.value?.trim();
  if(!name){alert('⚠️ Location name is required.');return;}
  if(!DB.locations) DB.locations=[];
  DB.locations.push({
    id:newId(),name,
    type:document.getElementById('loc-type')?.value||'Warehouse',
    address:document.getElementById('loc-addr')?.value||'',
    contact:document.getElementById('loc-contact')?.value||'',
    createdAt:new Date().toISOString()
  });
  saveDB();
  document.getElementById('location-modal').style.display='none';
  logAudit('LOCATION','Add','Location added: '+name);
  renderLocations();
}

async function deleteLocation(id){
  if(!await __confirm('Delete this location?'))return;
  DB.locations=(DB.locations||[]).filter(l=>l.id!==id);
  saveDB(); renderLocations();
}

function renderLocations(){
  const locs=DB.locations||[];
  // Merge with MASTER locations
  const masterLocs=(MASTER.locations||[]).map(l=>({id:'m_'+l,name:l,type:'City',address:'',contact:'',isMaster:true}));
  const allLocs=[...masterLocs,...locs];
  const TYPE_ICON={Warehouse:'🏭',Office:'🏢','Delivery Point':'🚚',Factory:'⚙️',City:'🏙️',Other:'📍'};
  const grid=document.getElementById('locations-grid');
  if(!grid) return;
  if(!allLocs.length){
    grid.innerHTML='<div style="grid-column:1/-1;text-align:center;padding:40px;color:#9ca3af;">No locations yet.</div>';
    return;
  }
  grid.innerHTML=allLocs.map(l=>`<div style="background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:18px;">
    <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:10px;">
      <div style="display:flex;align-items:center;gap:10px;">
        <div style="font-size:28px;">${TYPE_ICON[l.type]||'📍'}</div>
        <div>
          <div style="font-size:13px;font-weight:800;color:#0f3d26;">${escHTML(l.name)}</div>
          <div style="font-size:11px;color:#6b7280;margin-top:2px;">${l.type}</div>
        </div>
      </div>
      ${!l.isMaster?`<button data-x-click="deleteLocation(${l.id})" style="background:#fef2f2;border:1px solid #dc2626;color:#dc2626;padding:3px 8px;border-radius:5px;font-size:11px;cursor:pointer;">🗑️</button>`:''}
    </div>
    ${l.address?`<div style="font-size:11px;color:#6b7280;margin-bottom:4px;">📍 ${escHTML(l.address)}</div>`:''}
    ${l.contact?`<div style="font-size:11px;color:#6b7280;">📞 ${escHTML(l.contact)}</div>`:''}
    ${l.isMaster?`<div style="margin-top:8px;"><span style="background:#f0fdf4;color:#16a34a;padding:2px 8px;border-radius:20px;font-size:10px;font-weight:700;">Master Data</span></div>`:''}
  </div>`).join('');
}

// ── Bank Statement ─────────────────────────────────────────────
function initBankStmtDropdown(){
  const sel=document.getElementById('bs-account');
  if(!sel) return;
  // Always rebuild to reflect current DB.banks
  sel.innerHTML='<option value="">-- Select Account --</option>';
  (DB.banks||[]).forEach(b=>{
    const o=document.createElement('option');
    o.value=b.name; o.textContent=b.name+' (৳'+pf(b.bal||0)+')';
    sel.appendChild(o);
  });
}

function renderBankStmt(){
  initBankStmtDropdown();
  const account=document.getElementById('bs-account')?.value;
  const today=new Date().toISOString().split('T')[0];
  const fromEl=document.getElementById('bs-from');
  const toEl=document.getElementById('bs-to');
  if(fromEl&&!fromEl.value) fromEl.value=today.slice(0,7)+'-01';
  if(toEl&&!toEl.value) toEl.value=today;
  const from=(fromEl?.value)||today.slice(0,7)+'-01';
  const to=(toEl?.value)||today;
  if(!account) return;

  // Use DB.tx (correct field), match on t.bank or t.bank2
  const txns=(DB.tx||[]).filter(t=>
    (t.date||'')>=from&&(t.date||'')<=to&&
    ((t.bank||'').toLowerCase()===account.toLowerCase()||(t.bank2||'').toLowerCase()===account.toLowerCase())
  ).sort((a,b)=>(a.date||'').localeCompare(b.date||''));

  const bankObj=(DB.banks||[]).find(b=>b.name===account)||{};
  let runningBal=parseFloat(bankObj.bal||0);
  const bankInTypes=['bank deposit','sales receipt','cash received','cheque received','interest income','opening balance','partner capital','sales advance'];
  const rows=txns.map(t=>{
    const type=(t.type||'').toLowerCase();
    const amt=parseFloat(txAmt(t));
    let debit=0,credit=0;
    if(bankInTypes.some(k=>type.includes(k))){credit=amt;}
    else{debit=amt;}
    runningBal=runningBal+credit-debit;
    return {...t,debit,credit,balance:runningBal};
  });

  const totalCredit=rows.reduce((s,r)=>s+r.credit,0);
  const totalDebit=rows.reduce((s,r)=>s+r.debit,0);
  const openBal=parseFloat((DB.openingBalance||{})['bank_'+account]||0);

  const cards=document.getElementById('bs-cards');
  if(cards) cards.innerHTML=[
    {label:'Opening Balance',val:'৳'+pf(openBal),icon:'🏁',color:'#6b7280'},
    {label:'Total Credits',val:'৳'+pf(totalCredit),icon:'📥',color:'#16a34a'},
    {label:'Total Debits',val:'৳'+pf(totalDebit),icon:'📤',color:'#dc2626'},
    {label:'Closing Balance',val:'৳'+pf(runningBal),icon:'🏦',color:'#2563eb'}
  ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
    <div style="font-size:22px;">${c.icon}</div>
    <div style="font-size:17px;font-weight:900;color:${c.color};">${c.val}</div>
    <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)}</div>
  </div>`).join('');

  const body=document.getElementById('bs-body');
  if(!body) return;
  if(!rows.length){
    body.innerHTML='<div style="text-align:center;padding:40px;color:#9ca3af;">No transactions for this account in selected period.</div>';
    return;
  }
  body.innerHTML=`<table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
      <th style="padding:9px 12px;text-align:left;">Date</th>
      <th style="padding:9px 12px;text-align:left;">Description</th>
      <th style="padding:9px 12px;text-align:left;">Party</th>
      <th style="padding:9px 12px;text-align:right;">Debit (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Credit (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Balance (৳)</th>
    </tr></thead>
    <tbody>
    <tr style="background:#f9fafb;border-bottom:1px solid #e5e7eb;">
      <td colspan="5" style="padding:8px 12px;font-weight:700;color:#6b7280;">Opening Balance</td>
      <td style="padding:8px 12px;text-align:right;font-weight:700;">৳${pf(openBal)}</td>
    </tr>
    ${rows.map((r,i)=>`<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
      <td style="padding:8px 12px;color:#6b7280;">${r.date}</td>
      <td style="padding:8px 12px;">${r.type}</td>
      <td style="padding:8px 12px;">${escHTML(r.party||'—')}</td>
      <td style="padding:8px 12px;text-align:right;color:${r.debit>0?'#dc2626':'#9ca3af'};">${r.debit>0?'৳'+pf(r.debit):'—'}</td>
      <td style="padding:8px 12px;text-align:right;color:${r.credit>0?'#16a34a':'#9ca3af'};">${r.credit>0?'৳'+pf(r.credit):'—'}</td>
      <td style="padding:8px 12px;text-align:right;font-weight:700;color:${r.balance>=0?'#0f3d26':'#dc2626'};">৳${pf(r.balance)}</td>
    </tr>`).join('')}
    <tr style="background:#f0fdf4;font-weight:800;border-top:2px solid #16a34a;">
      <td colspan="3" style="padding:9px 12px;color:#0f3d26;">CLOSING BALANCE</td>
      <td style="padding:9px 12px;text-align:right;color:#dc2626;">৳${pf(totalDebit)}</td>
      <td style="padding:9px 12px;text-align:right;color:#16a34a;">৳${pf(totalCredit)}</td>
      <td style="padding:9px 12px;text-align:right;color:#0f3d26;">৳${pf(runningBal)}</td>
    </tr></tbody></table>`;
}


// ══════════════════════════════════════════════════════════════
// BATCH I: ALL LEDGERS, CUSTOMER, SUPPLIER, PARTNER, EXPENSE LEDGER
// ══════════════════════════════════════════════════════════════

// ── Shared ledger helper ───────────────────────────────────────
function buildPartyLedger(partyName, from, to, openBal, nature){
  const txns=(DB.tx||[]).filter(t=>
    t.party===partyName && _dk(t.date)>=_dk(from) && _dk(t.date)<=_dk(to)
  ).sort((a,b)=>a.date.localeCompare(b.date));

  /* FIX: the running balance started at zero, throwing away the opening
     balance the statement itself printed at the top. It also matched
     transaction types with `includes`, so 'Purchase Payment' was caught by
     the keyword 'purchase' and booked on the wrong side, and money the
     customer actually paid on a sale (tx.recv) was never credited — a
     fully paid invoice still showed as due. */
  let balance = parseFloat(openBal)||0;
  const isPartner = nature==='partner';
  return txns.map(t=>{
    const type=(t.type||'').toLowerCase().trim();
    const amt=txAmt(t);
    const recv=parseFloat(t.recv)||0, paid=parseFloat(t.paid)||0;
    const has=(...list)=>list.indexOf(type)>=0;
    let debit=0,credit=0;
    // Debit = they owe us more · Credit = they paid, or we owe them more
    /* The 0.5% withheld at source is credited alongside the cash, so a sale
       the customer has settled in full closes the row at zero. */
    if(has('sale','customer sale','warehouse sale')){ debit=amt; credit=recv+(parseFloat(t.salesTaxAmt)||0); }
    else if(has('sales receipt','customer collection','customer payment received',
                'cash received','cheque received','sales advance','advance from customer',
                'sales return')){ credit=amt; }
    else if(has('purchase','supplier purchase','warehouse purchase','werhouse purchase')){ credit=amt; debit=paid; }
    else if(has('purchase payment','supplier payment','purchase advance','advance to supplier',
                'supplier advance','cash payment','purchase return','supplier refund',
                'payment refund')){ debit=amt; }
    else if(has('supplier due')){ credit=amt; }
    else if(has('customer due')){ debit=amt; }
    else if(has('partner capital','partner fund','opening partner fund','partner profit share')){ credit=amt; }
    else if(has('partner withdrawal')){ debit=amt; }
    else{ debit=amt; }
    /* A partner's capital account grows on the credit side; a customer's
       or supplier's balance grows on the debit side. */
    balance = balance + (isPartner ? (credit-debit) : (debit-credit));
    return {...t,debit,credit,balance};
  });
}

function renderLedgerTable(rows, openBal, containerId){
  const body=document.getElementById(containerId);
  if(!body) return;
  /* Same as the supplier statement: a party with a balance brought forward
     and no movement in the period still has a balance worth showing. */
  if(!rows.length && Math.abs(parseFloat(openBal)||0)<0.01){
    body.innerHTML='<div style="text-align:center;padding:40px;color:#9ca3af;">No transactions found for selected period.</div>';
    return;
  }
  const totalDebit=rows.reduce((s,r)=>s+r.debit,0);
  const totalCredit=rows.reduce((s,r)=>s+r.credit,0);
  /* FIX (2026-08-28): a party with an opening balance but ZERO transactions
     inside the selected date range fell through "rows[rows.length-1]" to
     undefined, and "?.balance||0" turned that into a flat ৳0.00 — so the
     printed Closing Balance row said ৳0.00 even while the summary card
     above it (computed separately in renderCustLedger/renderSuppLedger/
     renderPartnerLedger, which already did this correctly) showed the real
     outstanding balance right next to it. Found via a live customer ledger
     print showing "Outstanding Due ৳5,89,663.20" in the summary card and
     "CLOSING BALANCE ৳0.00" in the same table. Carrying the opening balance
     forward when there are no rows makes this match the summary card and
     match every other closing-balance calculation in the app, none of
     which had this bug. */
  const closing=rows.length?rows[rows.length-1].balance:(parseFloat(openBal)||0);
  /* FIX (2026-08-28, "add Transport Type / Truck-Van ID to ledger"):
     Sale/Purchase transactions carry transport info as tx.transportType
     (Truck/Van/Covered Van/...) and tx.truck (the registration/ID) — see
     the "Transport, Costs & Agents" section of the transaction form. Rows
     built by buildPartyLedger() are spread from the original transaction
     ({...t,...}), so r.transportType / r.truck are already available here;
     they just weren't shown. Added as its own column so a customer's/
     supplier's ledger also shows which vehicle moved each delivery. */
  const transportCell=r=>{
    const type=(r.transportType||'').trim();
    const id=(r.truck||'').trim();
    if(!type && !id) return '<span style="color:#9ca3af;">—</span>';
    return escHTML([type,id].filter(Boolean).join(' • '));
  };
  /* FIX (2026-08-28, "also add Location"): each transaction already carries
     its warehouse/loading Location on t.loc (the same field used in the
     CSV/print exports elsewhere in the app) — surfaced here too so the
     ledger shows where each sale/purchase was handled from. */
  const locationCell=r=>{
    const loc=(r.loc||'').trim();
    return loc?escHTML(loc):'<span style="color:#9ca3af;">—</span>';
  };
  body.innerHTML=`<table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
      <th style="padding:9px 12px;text-align:left;">Date</th>
      <th style="padding:9px 12px;text-align:left;">Transaction Type</th>
      <th style="padding:9px 12px;text-align:left;">Description</th>
      <th style="padding:9px 12px;text-align:left;">Mode</th>
      <th style="padding:9px 12px;text-align:left;">Transport (Truck/Van ID)</th>
      <th style="padding:9px 12px;text-align:left;">Location</th>
      <th style="padding:9px 12px;text-align:right;">Debit (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Credit (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Balance (৳)</th>
    </tr></thead>
    <tbody>
    <tr style="background:#f9fafb;border-bottom:1px solid #e5e7eb;">
      <td colspan="8" style="padding:8px 12px;font-weight:700;color:#6b7280;">Opening Balance</td>
      <td style="padding:8px 12px;text-align:right;font-weight:700;">৳${pf(openBal)}</td>
    </tr>
    ${rows.map((r,i)=>`<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
      <td style="padding:8px 12px;color:#6b7280;">${r.date}</td>
      <td style="padding:8px 12px;">${r.type}</td>
      <td style="padding:8px 12px;color:#6b7280;">${escHTML(r.desc||r.product||'—')}</td>
      <td style="padding:8px 12px;"><span style="background:#f3f4f6;padding:2px 7px;border-radius:10px;font-size:10px;">${r.mode||'—'}</span></td>
      <td style="padding:8px 12px;color:#6b7280;">${transportCell(r)}</td>
      <td style="padding:8px 12px;color:#6b7280;">${locationCell(r)}</td>
      <td style="padding:8px 12px;text-align:right;color:${r.debit>0?'#dc2626':'#9ca3af'};">${r.debit>0?'৳'+pf(r.debit):'—'}</td>
      <td style="padding:8px 12px;text-align:right;color:${r.credit>0?'#16a34a':'#9ca3af'};">${r.credit>0?'৳'+pf(r.credit):'—'}</td>
      <td style="padding:8px 12px;text-align:right;font-weight:700;color:${r.balance>=0?'#0f3d26':'#dc2626'};">৳${pf(r.balance)}</td>
    </tr>`).join('')}
    <tr style="background:#f0fdf4;font-weight:800;border-top:2px solid #16a34a;">
      <td colspan="6" style="padding:9px 12px;color:#0f3d26;">CLOSING BALANCE</td>
      <td style="padding:9px 12px;text-align:right;color:#dc2626;">৳${pf(totalDebit)}</td>
      <td style="padding:9px 12px;text-align:right;color:#16a34a;">৳${pf(totalCredit)}</td>
      <td style="padding:9px 12px;text-align:right;color:#0f3d26;">৳${pf(closing)}</td>
    </tr></tbody></table>`;
}

// ── All Ledgers ────────────────────────────────────────────────
function renderAllLedgers(){
  const search=(document.getElementById('al-search')?.value||'').toLowerCase();
  const typeFilter=document.getElementById('al-type')?.value||'';
  const txns=DB.tx||[];

  // Build party summary
  const partyMap={};
  txns.forEach(t=>{
    const p=t.party||'Unknown';
    const pt=t.partyType||'Other';
    if(!partyMap[p]) partyMap[p]={name:p,type:pt,debit:0,credit:0,txnCount:0};
    const type=(t.type||'').toLowerCase();
    const amt=txAmt(t);
    if(['sale','sales advance'].some(k=>type.includes(k))){partyMap[p].debit+=amt;}
    else if(['sales receipt','purchase payment'].some(k=>type.includes(k))){partyMap[p].credit+=amt;}
    else if(['purchase','purchase advance'].some(k=>type.includes(k))){partyMap[p].credit+=amt;}
    else{partyMap[p].debit+=amt;}
    partyMap[p].txnCount++;
  });

  // Also add parties from DB.parties
  (DB.parties||[]).forEach(p=>{
    if(!partyMap[p.name]) partyMap[p.name]={name:p.name,type:p.type||'Other',debit:0,credit:0,txnCount:0};
    else partyMap[p.name].type=p.type||partyMap[p.name].type;
  });

  let parties=Object.values(partyMap);
  if(search) parties=parties.filter(p=>p.name.toLowerCase().includes(search));
  if(typeFilter) parties=parties.filter(p=>p.type===typeFilter);
  parties.sort((a,b)=>a.name.localeCompare(b.name));

  const totalDebit=parties.reduce((s,p)=>s+p.debit,0);
  const totalCredit=parties.reduce((s,p)=>s+p.credit,0);
  const cards=document.getElementById('al-cards');
  if(cards) cards.innerHTML=[
    {label:'Total Parties',val:parties.length,icon:'📚',color:'#2563eb'},
    {label:'Total Debit',val:'৳'+pf(totalDebit),icon:'📤',color:'#dc2626'},
    {label:'Total Credit',val:'৳'+pf(totalCredit),icon:'📥',color:'#16a34a'},
    {label:'Net Balance',val:'৳'+pf(totalDebit-totalCredit),icon:'⚖️',color:'#f59e0b'}
  ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
    <div style="font-size:22px;">${c.icon}</div>
    <div style="font-size:17px;font-weight:900;color:${c.color};">${c.val}</div>
    <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)}</div>
  </div>`).join('');

  const body=document.getElementById('al-body');
  if(!body) return;
  if(!parties.length){
    body.innerHTML='<div style="text-align:center;padding:40px;color:#9ca3af;">No parties found.</div>';
    return;
  }
  const TYPE_COLOR={Customer:'#2563eb',Supplier:'#f59e0b',Partner:'#7c3aed',Employee:'#16a34a',Other:'#6b7280'};
  body.innerHTML=`<table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
      <th style="padding:9px 12px;text-align:left;">Party Name</th>
      <th style="padding:9px 12px;text-align:left;">Type</th>
      <th style="padding:9px 12px;text-align:right;">Transactions</th>
      <th style="padding:9px 12px;text-align:right;">Total Debit (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Total Credit (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Net Balance (৳)</th>
      <th style="padding:9px 12px;text-align:center;">Action</th>
    </tr></thead>
    <tbody>${parties.map((p,i)=>{
      const net=p.debit-p.credit;
      return `<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
        <td style="padding:8px 12px;font-weight:700;">${escHTML(p.name)}</td>
        <td style="padding:8px 12px;"><span style="background:${TYPE_COLOR[p.type]||'#6b7280'}22;color:${TYPE_COLOR[p.type]||'#6b7280'};padding:3px 8px;border-radius:20px;font-size:11px;font-weight:700;">${p.type}</span></td>
        <td style="padding:8px 12px;text-align:right;">${p.txnCount}</td>
        <td style="padding:8px 12px;text-align:right;color:#dc2626;">৳${pf(p.debit)}</td>
        <td style="padding:8px 12px;text-align:right;color:#16a34a;">৳${pf(p.credit)}</td>
        <td style="padding:8px 12px;text-align:right;font-weight:800;color:${net>=0?'#dc2626':'#16a34a'};">৳${pf(Math.abs(net))} ${net>=0?'Dr':'Cr'}</td>
        <td style="padding:8px 12px;text-align:center;">
          <button data-x-click="viewPartyLedger('${escJSAttr(p.name)}','${p.type}')" style="background:#f0fdf4;border:1px solid #16a34a;color:#16a34a;padding:3px 10px;border-radius:5px;font-size:11px;cursor:pointer;">📋 View</button>
        </td>
      </tr>`;
    }).join('')}</tbody></table>`;
}



