function initCustLedgerDropdown(){
  const sel=document.getElementById('cl-party');
  if(!sel||sel.options.length>1) return;
  const customers=[...new Set([
    ...(MASTER.parties||[]),
    ...(DB.parties||[]).filter(p=>isCustomerParty(p)).map(p=>p.name),
    ...(DB.tx||[]).filter(t=>t.partyType==='Customer').map(t=>t.party)
  ])].filter(Boolean).sort();
  customers.forEach(c=>{const o=document.createElement('option');o.value=c;o.textContent=c;sel.appendChild(o);});
}

function renderCustLedger(){
  initCustLedgerDropdown();
  const party=document.getElementById('cl-party')?.value;
  const today=new Date().toISOString().split('T')[0];
  const fromEl=document.getElementById('cl-from');
  const toEl=document.getElementById('cl-to');
  if(!fromEl.value) fromEl.value=today.slice(0,7)+'-01';
  if(!toEl.value) toEl.value=today;
  if(!party) return;
  const from=fromEl.value, to=toEl.value;
  /* FIX: fall back to the derived opening balance when no opening figure
     has been configured, instead of silently opening at ৳0.00. */
  const _cfgOpen=parseFloat((DB.openingBalance||{})['cust_'+party]);
  const openBal=isFinite(_cfgOpen)&&_cfgOpen!==0?_cfgOpen:ayanPartyOpening(party,from,'customer');
  const rows=buildPartyLedger(party,from,to,openBal,'customer');
  const totalDebit=rows.reduce((s,r)=>s+r.debit,0);
  const totalCredit=rows.reduce((s,r)=>s+r.credit,0);
  const closing=rows.length?rows[rows.length-1].balance:openBal;

  const cards=document.getElementById('cl-cards');
  if(cards) cards.innerHTML=[
    {label:'Opening Balance',val:'৳'+pf(openBal),icon:'🏁',color:'#6b7280'},
    {label:'Total Sales',val:'৳'+pf(totalDebit),icon:'📤',color:'#dc2626'},
    {label:'Total Receipts',val:'৳'+pf(totalCredit),icon:'📥',color:'#16a34a'},
    {label:'Outstanding Due',val:'৳'+pf(closing),icon:'⏳',color:closing>0?'#f59e0b':'#16a34a'}
  ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
    <div style="font-size:22px;">${c.icon}</div>
    <div style="font-size:17px;font-weight:900;color:${c.color};">${c.val}</div>
    <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)}</div>
  </div>`).join('');
  renderLedgerTable(rows, openBal, 'cl-body');
}

