// ── Expense Ledger ─────────────────────────────────────────────


function initExpLedgerCats(){
  const sel=document.getElementById('el-cat');
  if(!sel||sel.options.length>1) return;
  EXPENSE_TYPES.forEach(t=>{const o=document.createElement('option');o.value=t;o.textContent=t;sel.appendChild(o);});
  ['Transport Cost','Agent A','Agent B','QC','Unload','Other Cost'].forEach(t=>{
    if(t==='Transport Cost') return; // already in EXPENSE_TYPES
    const o=document.createElement('option');o.value=t;o.textContent=t;sel.appendChild(o);
  });
}

function renderExpLedger(){
  initExpLedgerCats();
  const today=new Date().toISOString().split('T')[0];
  const fromEl=document.getElementById('el-from');
  const toEl=document.getElementById('el-to');
  if(!fromEl.value) fromEl.value=today.slice(0,7)+'-01';
  if(!toEl.value) toEl.value=today;
  const from=fromEl.value, to=toEl.value;
  const catFilter=document.getElementById('el-cat')?.value||'';

  const txns=(DB.tx||[]).filter(t=>{
    const type=t.type||'';
    const isExp=EXPENSE_TYPES.some(et=>type===et);
    const inRange=_dk(t.date)>=_dk(from)&&_dk(t.date)<=_dk(to);
    const matchCat=!catFilter||type===catFilter;
    return isExp&&inRange&&matchCat;
  });
  /* FIX (Transport, Costs & Agents never showed up as expenses): truck rent
     and the per-sale agent/QC/unload/other costs were only ever fields on a
     Sale/Purchase row — they silently reduced Net Profit but never appeared
     as a line item anywhere an owner would actually look for "expenses".
     They're pulled in here from the same ledgers the Cost Dues screens use,
     so what you see here always matches what those ledgers show. */
  const costLineCatLabel={agentA:'Agent A',agentB:'Agent B',qc:'QC',unload:'Unload',other:'Other Cost'};
  const extraRows=[];
  if(!catFilter||catFilter==='Transport Cost'){
    (DB.transportDues||[]).forEach(d=>{
      if(!(_dk(d.date)>=_dk(from)&&_dk(d.date)<=_dk(to))) return;
      extraRows.push({date:d.date,type:'Transport Cost',party:d.party||d.vehicle||'—',mode:d.status||'',desc:(d.transportType||'Freight')+(d.inv?' • '+d.inv:''),amount:(parseFloat(d.rent)||0)});
    });
  }
  (DB.costLines||[]).forEach(r=>{
    const label=costLineCatLabel[r.cat]||r.cat;
    if(catFilter&&catFilter!==label) return;
    if(!(_dk(r.date)>=_dk(from)&&_dk(r.date)<=_dk(to))) return;
    extraRows.push({date:r.date,type:label,party:r.party||'—',mode:r.status||'',desc:(r.loc?'Loc: '+r.loc+' • ':'')+(r.person?r.person+' • ':'')+(r.inv||''),amount:(parseFloat(r.amount)||0)});
  });
  /* FIX (City Bank fee + interest never showed up as expenses): the upfront
     fee and the days-outstanding interest on a Factory Finance drawdown were
     only ever netted straight out of the amount credited to the bank at
     settlement — real money, but with no visible expense record anywhere.
     They're shown here as their own line items (Finance Fee / Finance
     Interest), dated to when the charge was actually incurred, without
     posting anything extra to the bank — that side is already handled by
     the City Finance settlement itself. */
  if(!catFilter||catFilter==='Finance Fee'||catFilter==='Finance Interest'){
    (DB.cityFinance||[]).forEach(r=>{
      const chargeDate = r.buyerPaidDate || r.advDate || r.date || '';
      if(!(_dk(chargeDate)>=_dk(from)&&_dk(chargeDate)<=_dk(to))) return;
      const fee=parseFloat(r.fee)||0, interest=parseFloat(r.interest)||0;
      if(fee>0 && (!catFilter||catFilter==='Finance Fee'))
        extraRows.push({date:r.advDate||chargeDate,type:'Finance Fee',party:r.party||'—',mode:r.bank||'',desc:'City Bank upfront fee'+(r.inv?' • '+r.inv:''),amount:fee});
      if(interest>0 && (!catFilter||catFilter==='Finance Interest'))
        extraRows.push({date:chargeDate,type:'Finance Interest',party:r.party||'—',mode:r.bank||'',desc:'City Bank interest — '+(r.days||0)+' day'+(r.days===1?'':'s')+' @ '+(r.ratePct||0)+'% p.a.'+(r.inv?' • '+r.inv:''),amount:interest});
    });
  }
  txns.push(...extraRows);
  txns.sort((a,b)=>a.date.localeCompare(b.date));

  const totalExp=txns.reduce((s,t)=>s+txAmt(t),0);
  const cats=new Set(txns.map(t=>t.type));
  const avgExp=txns.length?totalExp/txns.length:0;

  const cards=document.getElementById('el-cards');
  if(cards) cards.innerHTML=[
    {label:'Total Expenses',val:'৳'+pf(totalExp),icon:'💸',color:'#dc2626'},
    {label:'Transactions',val:txns.length,icon:'📋',color:'#2563eb'},
    {label:'Categories',val:cats.size,icon:'🏷️',color:'#7c3aed'},
    {label:'Avg per Transaction',val:'৳'+pf(avgExp),icon:'📊',color:'#f59e0b'}
  ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
    <div style="font-size:22px;">${c.icon}</div>
    <div style="font-size:17px;font-weight:900;color:${c.color};">${c.val}</div>
    <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)}</div>
  </div>`).join('');

  const body=document.getElementById('el-body');
  if(!body) return;
  if(!txns.length){
    body.innerHTML='<div style="text-align:center;padding:40px;color:#9ca3af;">No expense transactions in selected period.</div>';
    return;
  }
  let running=0;
  const rows=txns.map(t=>{running+=txAmt(t);return {...t,running};});
  body.innerHTML=`<table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
      <th style="padding:9px 12px;text-align:left;">Date</th>
      <th style="padding:9px 12px;text-align:left;">Category</th>
      <th style="padding:9px 12px;text-align:left;">Party / Payee</th>
      <th style="padding:9px 12px;text-align:left;">Mode</th>
      <th style="padding:9px 12px;text-align:left;">Description</th>
      <th style="padding:9px 12px;text-align:right;">Amount (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Running Total (৳)</th>
    </tr></thead>
    <tbody>${rows.map((r,i)=>`<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
      <td style="padding:8px 12px;color:#6b7280;">${r.date}</td>
      <td style="padding:8px 12px;font-weight:700;">${r.type}</td>
      <td style="padding:8px 12px;">${escHTML(r.party||'—')}</td>
      <td style="padding:8px 12px;"><span style="background:#f3f4f6;padding:2px 7px;border-radius:10px;font-size:10px;">${r.mode||'—'}</span></td>
      <td style="padding:8px 12px;color:#6b7280;">${escHTML(r.desc||'—')}</td>
      <td style="padding:8px 12px;text-align:right;font-weight:700;color:#dc2626;">৳${pf(r.amount||0)}</td>
      <td style="padding:8px 12px;text-align:right;color:#6b7280;">৳${pf(r.running)}</td>
    </tr>`).join('')}
    <tr style="background:#fef2f2;font-weight:800;border-top:2px solid #dc2626;">
      <td colspan="5" style="padding:9px 12px;color:#991b1b;">TOTAL EXPENSES</td>
      <td style="padding:9px 12px;text-align:right;color:#dc2626;">৳${pf(totalExp)}</td>
      <td style="padding:9px 12px;text-align:right;color:#6b7280;"></td>
    </tr></tbody></table>`;
}


