// ── Fixed Assets Ledger ────────────────────────────────────────
function renderFixedAssetLedger(){
  const assets=DB.assets||[];
  // Also pull from transactions
  const assetTxns=(DB.tx||[]).filter(t=>{
    const type=(t.type||'').toLowerCase();
    return type.includes('fixed asset')||type.includes('opening fixed asset');
  });

  const DEPR_RATE={Car:0.15,Motorcycle:0.20,Machinery:0.10,Building:0.05,Equipment:0.20,Furniture:0.10,Vehicle:0.15,Other:0.10};
  const currentYear=new Date().getFullYear();

  // Merge DB assets + transaction-based assets
  const allAssets=[...assets];
  assetTxns.forEach(t=>{
    if(!allAssets.find(a=>a.name===t.desc||a.name===t.prod)){
      allAssets.push({id:t.id,name:t.desc||t.prod||'Asset',category:'Other',cost:txAmt(t),purchaseDate:t.date,depRate:10});
    }
  });

  const totalCost=allAssets.reduce((s,a)=>s+parseFloat(a.cost||0),0);
  const totalDepr=allAssets.reduce((s,a)=>{
    const years=a.purchaseDate?Math.max(0,(currentYear-parseInt(a.purchaseDate.slice(0,4)))):0;
    const rate=(a.depRate||10)/100;
    return s+Math.min(parseFloat(a.cost||0),parseFloat(a.cost||0)*rate*years);
  },0);
  const netBookValue=totalCost-totalDepr;

  const cards=document.getElementById('fal-cards');
  if(cards) cards.innerHTML=[
    {label:'Total Assets',val:allAssets.length,icon:'🏗️',color:'#2563eb'},
    {label:'Total Cost',val:'৳'+pf(totalCost),icon:'💰',color:'#0f3d26'},
    {label:'Total Depreciation',val:'৳'+pf(totalDepr),icon:'📉',color:'#dc2626'},
    {label:'Net Book Value',val:'৳'+pf(netBookValue),icon:'📊',color:'#16a34a'}
  ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
    <div style="font-size:22px;">${c.icon}</div>
    <div style="font-size:17px;font-weight:900;color:${c.color};">${c.val}</div>
    <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)}</div>
  </div>`).join('');

  const body=document.getElementById('fal-body');
  if(!body) return;
  if(!allAssets.length){
    body.innerHTML='<div style="text-align:center;padding:40px;color:#9ca3af;">No fixed assets recorded yet.</div>';
    return;
  }
  body.innerHTML=`<table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
      <th style="padding:9px 12px;text-align:left;">Asset Name</th>
      <th style="padding:9px 12px;text-align:left;">Category</th>
      <th style="padding:9px 12px;text-align:left;">Purchase Date</th>
      <th style="padding:9px 12px;text-align:right;">Cost (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Dep. Rate</th>
      <th style="padding:9px 12px;text-align:right;">Accum. Depr. (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Net Book Value (৳)</th>
    </tr></thead>
    <tbody>${allAssets.map((a,i)=>{
      const years=a.purchaseDate?Math.max(0,(currentYear-parseInt(a.purchaseDate.slice(0,4)))):0;
      const rate=(a.depRate||10)/100;
      const cost=parseFloat(a.cost||0);
      const depr=Math.min(cost,cost*rate*years);
      const nbv=cost-depr;
      return `<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
        <td style="padding:8px 12px;font-weight:700;">${escHTML(a.name)}</td>
        <td style="padding:8px 12px;color:#6b7280;">${a.category||'Other'}</td>
        <td style="padding:8px 12px;color:#6b7280;">${a.purchaseDate||'—'}</td>
        <td style="padding:8px 12px;text-align:right;">৳${pf(cost)}</td>
        <td style="padding:8px 12px;text-align:right;">${a.depRate||10}%</td>
        <td style="padding:8px 12px;text-align:right;color:#dc2626;">৳${pf(depr)}</td>
        <td style="padding:8px 12px;text-align:right;font-weight:800;color:${nbv>0?'#16a34a':'#dc2626'};">৳${pf(nbv)}</td>
      </tr>`;
    }).join('')}
    <tr style="background:#f0fdf4;font-weight:800;border-top:2px solid #16a34a;">
      <td colspan="3" style="padding:9px 12px;color:#0f3d26;">TOTAL</td>
      <td style="padding:9px 12px;text-align:right;">৳${pf(totalCost)}</td>
      <td></td>
      <td style="padding:9px 12px;text-align:right;color:#dc2626;">৳${pf(totalDepr)}</td>
      <td style="padding:9px 12px;text-align:right;color:#16a34a;">৳${pf(netBookValue)}</td>
    </tr></tbody></table>`;
}

