// ── Aging Report Helper ────────────────────────────────────────
function buildAgingReport(partyType, asOf){
  const txns=DB.tx||[];
  const partyMap={};

  txns.forEach(t=>{
    const pt=t.partyType||'';
    if(pt!==partyType) return;
    const p=t.party||'Unknown';
    if(!partyMap[p]) partyMap[p]={name:p,current:0,d30:0,d60:0,d90:0,d90plus:0,total:0};
    const type=(t.type||'').toLowerCase();
    const amt=txAmt(t);
    const daysDiff=Math.floor((new Date(asOf)-new Date(t.date))/(1000*60*60*24));
    let outstanding=0;
    if(partyType==='Customer'){
      if(['sale','sales advance'].some(k=>type.includes(k))) outstanding=amt;
      else if(['sales receipt'].some(k=>type.includes(k))) outstanding=-amt;
    } else {
      if(['purchase','purchase advance'].some(k=>type.includes(k))) outstanding=amt;
      else if(['purchase payment'].some(k=>type.includes(k))) outstanding=-amt;
    }
    if(outstanding<=0) return;
    if(daysDiff<=30) partyMap[p].current+=outstanding;
    else if(daysDiff<=60) partyMap[p].d30+=outstanding;
    else if(daysDiff<=90) partyMap[p].d60+=outstanding;
    else if(daysDiff<=120) partyMap[p].d90+=outstanding;
    else partyMap[p].d90plus+=outstanding;
    partyMap[p].total+=outstanding;
  });

  return Object.values(partyMap).filter(p=>p.total>0).sort((a,b)=>b.total-a.total);
}

