      <th style="padding:9px 12px;text-align:right;">91-120d (৳)</th>
      <th style="padding:9px 12px;text-align:right;">>120d (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Total (৳)</th>
    </tr></thead>
    <tbody>${rows.map((r,i)=>`<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
      <td style="padding:8px 12px;font-weight:700;">${escHTML(r.name)}</td>
      <td style="padding:8px 12px;text-align:right;color:#16a34a;">${r.current>0?'৳'+pf(r.current):'—'}</td>
      <td style="padding:8px 12px;text-align:right;color:#f59e0b;">${r.d30>0?'৳'+pf(r.d30):'—'}</td>
      <td style="padding:8px 12px;text-align:right;color:#ea580c;">${r.d60>0?'৳'+pf(r.d60):'—'}</td>
      <td style="padding:8px 12px;text-align:right;color:#dc2626;">${r.d90>0?'৳'+pf(r.d90):'—'}</td>
      <td style="padding:8px 12px;text-align:right;color:#7f1d1d;font-weight:700;">${r.d90plus>0?'৳'+pf(r.d90plus):'—'}</td>
      <td style="padding:8px 12px;text-align:right;font-weight:800;">৳${pf(r.total)}</td>
    </tr>`).join('')}
    <tr style="background:#f0fdf4;font-weight:800;border-top:2px solid #16a34a;">
      <td style="padding:9px 12px;color:#0f3d26;">TOTAL</td>
      <td style="padding:9px 12px;text-align:right;color:#16a34a;">৳${pf(totals.current)}</td>
      <td style="padding:9px 12px;text-align:right;color:#f59e0b;">৳${pf(totals.d30)}</td>
      <td style="padding:9px 12px;text-align:right;color:#ea580c;">৳${pf(totals.d60)}</td>
