      <td style="padding:9px 12px;text-align:right;color:#7f1d1d;">৳${pf(totals.d90plus)}</td>
      <td style="padding:9px 12px;text-align:right;">৳${pf(totals.total)}</td>
    </tr></tbody></table>`;
}

function renderCustAging(){
  const asOfEl=document.getElementById('ca-asof');
  if(!asOfEl) return;
  if(!asOfEl.value) asOfEl.value=new Date().toISOString().split('T')[0];
  const asOf=new Date(asOfEl.value);
  const customers=DB.customers||[];
  const txs=DB.tx||[];
  const aged=customers.filter(c=>(c.bal||0)>0).map(c=>{
    const lastTx=txs.filter(t=>t.party===c.name).sort((a,b)=>b.date.localeCompare(a.date))[0];
    const lastDate=lastTx?new Date(lastTx.date):new Date(asOf);
    const days=Math.floor((asOf-lastDate)/(1000*60*60*24));
    return {...c,days,lastDate:lastTx?.date||'—'};
  }).sort((a,b)=>b.days-a.days);
  const b0_30=aged.filter(c=>c.days<=30).reduce((s,c)=>s+(c.bal||0),0);
  const b31_60=aged.filter(c=>c.days>30&&c.days<=60).reduce((s,c)=>s+(c.bal||0),0);
  const b61_90=aged.filter(c=>c.days>60&&c.days<=90).reduce((s,c)=>s+(c.bal||0),0);
  const b90p=aged.filter(c=>c.days>90).reduce((s,c)=>s+(c.bal||0),0);
  const wrap=document.getElementById('ca-wrap');
  if(!wrap)return;
  wrap.innerHTML=`<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:16px;">
    <div class="kpi-card" style="border-left:4px solid #16a34a;"><div class="kpi-label">0-30 Days</div><div class="kpi-val" style="color:#16a34a;">${f(b0_30)}</div></div>
    <div class="kpi-card" style="border-left:4px solid #d97706;"><div class="kpi-label">31-60 Days</div><div class="kpi-val" style="color:#d97706;">${f(b31_60)}</div></div>
    <div class="kpi-card" style="border-left:4px solid #ea580c;"><div class="kpi-label">61-90 Days</div><div class="kpi-val" style="color:#ea580c;">${f(b61_90)}</div></div>
    <div class="kpi-card" style="border-left:4px solid #dc2626;"><div class="kpi-label">90+ Days</div><div class="kpi-val" style="color:#dc2626;">${f(b90p)}</div></div>
  </div>
  ${aged.length?`<table class="tbl"><thead><tr><th>Customer</th><th>Phone</th><th>Last Transaction</th><th>Days Outstanding</th><th>Balance (৳)</th><th>Status</th></tr></thead>
  <tbody>${aged.map(c=>{
    const color=c.days<=30?'#16a34a':c.days<=60?'#d97706':c.days<=90?'#ea580c':'#dc2626';
    const label=c.days<=30?'Current':c.days<=60?'30-60 Days':c.days<=90?'60-90 Days':'90+ Days (Critical)';
    return `<tr>
      <td><strong>${escHTML(c.name)}</strong></td>
      <td>${escHTML(c.phone ||'—')}</td>
      <td>${c.lastDate}</td>
      <td style="font-weight:700;color:${color};">${c.days} days</td>
      <td><strong style="color:#dc2626;">${f(c.bal||0)}</strong></td>
      <td><span style="padding:2px 8px;border-radius:8px;font-size:10px;font-weight:700;background:${color}22;color:${color};">${label}</span></td>
    </tr>`;
  }).join('')}</tbody>
  <tfoot><tr><td colspan="4" style="text-align:right;font-weight:800;padding:10px 12px;">Total Outstanding:</td>
    <td colspan="2" style="font-weight:900;color:#dc2626;padding:10px 12px;">${f(aged.reduce((s,c)=>s+(c.bal||0),0))}</td></tr></tfoot>
  </table>`:'<div style="text-align:center;padding:30px;color:#9ca3af;">No customers with outstanding balances.</div>'}`;
}

