// ── Daily Summary ──────────────────────────────────────────────
function renderDailySummary(){
  const dateEl=document.getElementById('daily-date');
  if(!dateEl) return;
  if(!dateEl.value) dateEl.value=new Date().toISOString().split('T')[0];
  const day=dateEl.value;
  const txns=(DB.tx||[]).filter(t=>t.date===day);
  const SALE_T=new Set(['Sale','Sales','Sales Invoice','Customer Sale','Warehouse Sale','Other Income','Interest Income']); // canonical: money receipts/advances are NOT revenue or cost
  const PURCH_T=new Set(['Purchase','Warehouse Purchase','Supplier Purchase']); // canonical: money receipts/advances are NOT revenue or cost
  const EXP_T=new Set(['Salary Payment','Office Rent','Electricity Bill','Internet Bill','Fuel Expense','Transport Cost','Loading Charge','Unloading Charge','Commission Payment','Other Expense','Interest Expense','Bank Charge']);
  const sales=txns.filter(t=>SALE_T.has(t.type));
  const purchases=txns.filter(t=>PURCH_T.has(t.type));
  const expenses=txns.filter(t=>EXP_T.has(t.type));
  const receipts=txns.filter(t=>t.type==='Sales Receipt'||t.type==='Cash Received'||t.type==='Cheque Received');
  const payments=txns.filter(t=>t.type==='Purchase Payment'||t.type==='Cash Paid'||t.type==='Cheque Issued');
  const salesTotal=sales.reduce((s,t)=>s+txAmt(t),0);
  const purchTotal=purchases.reduce((s,t)=>s+txAmt(t),0);
  const expTotal=expenses.reduce((s,t)=>s+txAmt(t),0);
  const recvTotal=receipts.reduce((s,t)=>s+txAmt(t),0);
  const payTotal=payments.reduce((s,t)=>s+txAmt(t),0);
  // For daily summary: COGS is computed against the day's transactions only.
  // If qty fields are missing on daily txns it falls back to same-day purchTotal.
  const cogsTotal=window.computeCOGS(txns);
  const grossProfit=salesTotal-cogsTotal;
  const netProfit=grossProfit-expTotal;
  const kpisEl=document.getElementById('daily-kpis');
  if(kpisEl) kpisEl.innerHTML=[
    {label:'Sales',val:salesTotal,color:'#16a34a',icon:'💰'},
    {label:'Purchases',val:purchTotal,color:'#2563eb',icon:'📦'},
    {label:'Expenses',val:expTotal,color:'#dc2626',icon:'💸'},
    {label:'Gross Profit',val:grossProfit,color:grossProfit>=0?'#059669':'#dc2626',icon:'📈'},
    {label:'Net Profit',val:netProfit,color:netProfit>=0?'#7c3aed':'#dc2626',icon:'🏆'},
    {label:'Transactions',val:txns.length,color:'#0891b2',icon:'📋'}
  ].map(k=>`<div data-x-click="openPLDrill('${day}','${day}')" style="cursor:pointer;background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:14px;text-align:center;" title="Click to see today's transactions">
    <div style="font-size:20px;">${k.icon}</div>
    <div style="font-size:10px;color:#6b7280;font-weight:700;margin-top:4px;">${escHTML(k.label)} →</div>
    <div style="font-size:18px;font-weight:800;color:${k.color};margin-top:2px;">${f(k.val)}</div>
  </div>`).join('');
  const rowsHtml=(list,emptyMsg)=>list.length?list.map(t=>`
    <div data-x-click="editTx(${t.id})" style="cursor:pointer;padding:8px 14px;border-bottom:1px solid #f3f4f6;display:flex;justify-content:space-between;font-size:12px;" title="Click to edit this transaction">
      <span>${escHTML(t.party||t.desc||'—')} →</span><span style="font-weight:700;">${f(txAmt(t))}</span>
    </div>`).join(''):`<div style="padding:20px;text-align:center;color:#9ca3af;font-size:12px;">${emptyMsg}</div>`;
  const set=(id,html)=>{const el=document.getElementById(id);if(el)el.innerHTML=html;};
  set('daily-sales',rowsHtml(sales,'No sales today.'));
  set('daily-purchases',rowsHtml(purchases,'No purchases today.'));
  set('daily-payments',rowsHtml([...receipts,...payments],'No payments/receipts today.'));
  set('daily-expenses',rowsHtml(expenses,'No expenses today.'));
}



