// ── Daily Sales Report ─────────────────────────────────────────
function initDsrDropdown(){
  const sel=document.getElementById('dsr-party');
  if(!sel||sel.options.length>1) return;
  /* FIX I: dropdown was missing 'Customer Sale', silently hiding customers
     whose only transactions used that type. */
  const customers=[...new Set((DB.tx||[]).filter(t=>window.isRevenueTx(t)||t.type==='Sales Advance').map(t=>t.party))].filter(Boolean).sort();
  customers.forEach(c=>{const o=document.createElement('option');o.value=c;o.textContent=c;sel.appendChild(o);});
}

function renderDailySales(){
  const dateEl=document.getElementById('ds-date');
  if(!dateEl) return;
  if(!dateEl.value) dateEl.value=new Date().toISOString().split('T')[0];
  const date=dateEl.value;
  const SALE_TYPES=['Sale','Sales Receipt','Sales Advance','Warehouse Sale','Other Income','Interest Income'];
  const txns=(DB.tx||[]).filter(t=>t.date===date&&SALE_TYPES.includes(t.type));
  const totalSales=txns.filter(isRevenueTx).reduce((s,t)=>s+txAmt(t),0);
  const totalReceipts=txns.filter(t=>t.type==='Sales Receipt').reduce((s,t)=>s+txAmt(t),0);
  const totalAdvances=txns.filter(t=>t.type==='Sales Advance').reduce((s,t)=>s+txAmt(t),0);
  const totalQty=txns.reduce((s,t)=>s+parseFloat(t.qty||0),0);
  const cardsEl=document.getElementById('ds-cards');
  if(cardsEl) cardsEl.innerHTML=[
    {label:'Total Sales',val:f(totalSales),color:'#16a34a',icon:'💰'},
    {label:'Receipts',val:f(totalReceipts),color:'#2563eb',icon:'🧾'},
    {label:'Advances',val:f(totalAdvances),color:'#7c3aed',icon:'⏩'},
    {label:'Total Qty',val:totalQty.toLocaleString('en-IN'),color:'#059669',icon:'📦'},
    {label:'Transactions',val:txns.length,color:'#0891b2',icon:'📋'}
  ].map(c=>`<div data-x-click="openPLDrill('${date}','${date}')" style="cursor:pointer;background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:14px;text-align:center;" title="Click to see this date's transactions">
    <div style="font-size:20px;">${c.icon}</div>
    <div style="font-size:10px;color:#6b7280;font-weight:700;margin-top:4px;">${escHTML(c.label)} →</div>
    <div style="font-size:18px;font-weight:800;color:${c.color};margin-top:2px;">${c.val}</div>
  </div>`).join('');
  const tableEl=document.getElementById('ds-table');
  if(tableEl){
    if(!txns.length){
      tableEl.innerHTML='<div style="text-align:center;padding:30px;color:#9ca3af;">No sales transactions for this date.</div>';
    } else {
      const total=txns.reduce((s,t)=>s+txAmt(t),0);
      tableEl.innerHTML=`<table class="tbl"><thead><tr>
        <th>#</th><th>Type</th><th>Party</th><th>Product</th><th>Qty</th><th>Rate</th><th>Amount</th><th>Mode</th>
      </tr></thead><tbody>${txns.map((t,i)=>`<tr data-x-click="editTx(${t.id})" style="cursor:pointer;" title="Click to edit">
        <td>${i+1}</td>
        <td><span style="padding:2px 8px;border-radius:8px;font-size:10px;font-weight:700;background:#dcfce7;color:#16a34a;">${t.type}</span></td>
        <td><strong>${escHTML(t.party||'—')} →</strong></td>
        <td>${t.product||t.item||'—'}</td>
        <td>${t.qty||'—'}</td>
        <td>${t.rate?f(t.rate):'—'}</td>
        <td><strong style="color:#16a34a;">${f(txAmt(t))}</strong></td>
        <td>${escHTML(t.mode||t.bank||'Cash')}</td>
      </tr>`).join('')}</tbody>
      <tfoot><tr><td colspan="6" style="text-align:right;font-weight:800;padding:10px 12px;">Total:</td>
        <td colspan="2" style="font-weight:900;color:#16a34a;padding:10px 12px;">${f(total)}</td></tr></tfoot>
      </table>`;
    }
  }
}

