// ── Monthly Report ─────────────────────────────────────────────
function initMrYears(){
  const sel=document.getElementById('mr-year');
  if(!sel||sel.options.length>0) return;
  const years=[...new Set((DB.tx||[]).map(t=>t.date?.slice(0,4)))].filter(Boolean).sort().reverse();
  const curYear=new Date().getFullYear().toString();
  if(!years.includes(curYear)) years.unshift(curYear);
  years.forEach(y=>{const o=document.createElement('option');o.value=y;o.textContent=y;if(y===curYear)o.selected=true;sel.appendChild(o);});
}

function renderMonthlyReport(){
  initMrYears();
  const year=document.getElementById('mr-year')?.value||new Date().getFullYear().toString();
  const MONTHS=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const txns=(DB.tx||[]).filter(t=>t.date?.startsWith(year));

  const monthData=MONTHS.map((m,idx)=>{
    const mm=String(idx+1).padStart(2,'0');
    const mTxns=txns.filter(t=>t.date?.slice(5,7)===mm);
    const sales=mTxns.filter(t=>isRevenueTx(t)).reduce((s,t)=>s+parseFloat(txAmt(t)),0);
    const purchases=mTxns.filter(t=>isCogsTx(t)).reduce((s,t)=>s+parseFloat(txAmt(t)),0);
    const receipts=mTxns.filter(t=>t.type==='Sales Receipt').reduce((s,t)=>s+parseFloat(txAmt(t)),0);
    const payments=mTxns.filter(t=>t.type==='Purchase Payment').reduce((s,t)=>s+parseFloat(txAmt(t)),0);
    const expenses=mTxns.filter(t=>isExpenseType(t.type)).reduce((s,t)=>s+parseFloat(txAmt(t)),0);
    // COGS for this month's transactions only
    const cogs=window.computeCOGS(mTxns);
    const profit=sales-cogs-expenses;
    return {month:m,sales,purchases,cogs,receipts,payments,expenses,profit,count:mTxns.length};
  });

  const totSales=monthData.reduce((s,m)=>s+m.sales,0);
  const totPurch=monthData.reduce((s,m)=>s+m.purchases,0);
  const totExp=monthData.reduce((s,m)=>s+m.expenses,0);
  const totProfit=monthData.reduce((s,m)=>s+m.profit,0);

  const cards=document.getElementById('mr-cards');
  if(cards) cards.innerHTML=[
    {label:'Annual Sales',val:'৳'+pf(totSales),icon:'📈',color:'#16a34a'},
    {label:'Annual Purchases',val:'৳'+pf(totPurch),icon:'📦',color:'#dc2626'},
    {label:'Annual Expenses',val:'৳'+pf(totExp),icon:'💸',color:'#f59e0b'},
    {label:'Annual Profit',val:'৳'+pf(totProfit),icon:'💰',color:totProfit>=0?'#0f3d26':'#dc2626'}
  ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
    <div style="font-size:22px;">${c.icon}</div>
    <div style="font-size:17px;font-weight:900;color:${c.color};">${c.val}</div>
    <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)}</div>
  </div>`).join('');

  const body=document.getElementById('mr-body');
  if(!body) return;
  body.innerHTML=`<table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
      <th style="padding:9px 12px;text-align:left;">Month</th>
      <th style="padding:9px 12px;text-align:right;">Sales (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Purchases (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Receipts (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Payments (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Expenses (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Profit (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Txns</th>
    </tr></thead>
    <tbody>${monthData.map((m,i)=>`<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
      <td style="padding:8px 12px;font-weight:700;color:#0f3d26;">${m.month} ${year}</td>
      <td style="padding:8px 12px;text-align:right;color:#16a34a;">${m.sales>0?'৳'+pf(m.sales):'—'}</td>
      <td style="padding:8px 12px;text-align:right;color:#dc2626;">${m.purchases>0?'৳'+pf(m.purchases):'—'}</td>
      <td style="padding:8px 12px;text-align:right;color:#2563eb;">${m.receipts>0?'৳'+pf(m.receipts):'—'}</td>
      <td style="padding:8px 12px;text-align:right;color:#7c3aed;">${m.payments>0?'৳'+pf(m.payments):'—'}</td>
      <td style="padding:8px 12px;text-align:right;color:#f59e0b;">${m.expenses>0?'৳'+pf(m.expenses):'—'}</td>
      <td style="padding:8px 12px;text-align:right;font-weight:800;color:${m.profit>=0?'#16a34a':'#dc2626'};">৳${pf(m.profit)}</td>
      <td style="padding:8px 12px;text-align:right;color:#6b7280;">${m.count}</td>
    </tr>`).join('')}
    <tr style="background:#f0fdf4;font-weight:800;border-top:2px solid #16a34a;">
      <td style="padding:9px 12px;color:#0f3d26;">ANNUAL TOTAL</td>
      <td style="padding:9px 12px;text-align:right;color:#16a34a;">৳${pf(totSales)}</td>
      <td style="padding:9px 12px;text-align:right;color:#dc2626;">৳${pf(totPurch)}</td>
      <td style="padding:9px 12px;text-align:right;color:#2563eb;">৳${pf(monthData.reduce((s,m)=>s+m.receipts,0))}</td>
      <td style="padding:9px 12px;text-align:right;color:#7c3aed;">৳${pf(monthData.reduce((s,m)=>s+m.payments,0))}</td>
      <td style="padding:9px 12px;text-align:right;color:#f59e0b;">৳${pf(totExp)}</td>
      <td style="padding:9px 12px;text-align:right;color:${totProfit>=0?'#16a34a':'#dc2626'};">৳${pf(totProfit)}</td>
      <td style="padding:9px 12px;text-align:right;">${txns.length}</td>
    </tr></tbody></table>`;
}

// ── Monthly Comparison ─────────────────────────────────────────
function getMonthStats(ym){
  const txns=(DB.tx||[]).filter(t=>t.date?.startsWith(ym));
  const sales=txns.filter(t=>isRevenueTx(t)).reduce((s,t)=>s+txAmt(t),0);
  const purchases=txns.filter(t=>isCogsTx(t)).reduce((s,t)=>s+txAmt(t),0);
  const expenses=txns.filter(t=>isExpenseType(t.type)).reduce((s,t)=>s+txAmt(t),0);
  const receipts=txns.filter(t=>t.type==='Sales Receipt').reduce((s,t)=>s+txAmt(t),0);
  const cogs=window.computeCOGS(txns);
  const profit=sales-cogs-expenses;
  return {sales,purchases,cogs,expenses,receipts,profit,count:txns.length};
}

function renderMonthlyComp(){
  const today=new Date().toISOString().slice(0,7);
  const m1El=document.getElementById('mc-m1');
  const m2El=document.getElementById('mc-m2');
  if(!m1El.value){const d=new Date();d.setMonth(d.getMonth()-1);m1El.value=d.toISOString().slice(0,7);}
  if(!m2El.value) m2El.value=today;
  const m1=m1El.value, m2=m2El.value;
  const s1=getMonthStats(m1), s2=getMonthStats(m2);

  const rows=[
    {label:'Total Sales',k:'sales',icon:'📈',color:'#16a34a'},
    {label:'Total Purchases',k:'purchases',icon:'📦',color:'#dc2626'},
    {label:'Total Expenses',k:'expenses',icon:'💸',color:'#f59e0b'},
    {label:'Total Receipts',k:'receipts',icon:'💵',color:'#2563eb'},
    {label:'Net Profit',k:'profit',icon:'💰',color:'#7c3aed'},
    {label:'Transactions',k:'count',icon:'📋',color:'#6b7280'},
  ];

  const body=document.getElementById('mc-body');
  if(!body) return;
  body.innerHTML=`<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
    <table style="width:100%;border-collapse:collapse;font-size:12px;">
      <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
        <th style="padding:10px 16px;text-align:left;">Metric</th>
        <th style="padding:10px 16px;text-align:right;">${m1}</th>
        <th style="padding:10px 16px;text-align:right;">${m2}</th>
        <th style="padding:10px 16px;text-align:right;">Change</th>
        <th style="padding:10px 16px;text-align:right;">% Change</th>
      </tr></thead>
      <tbody>${rows.map((r,i)=>{
        const v1=s1[r.k]||0, v2=s2[r.k]||0;
        const diff=v2-v1;
        const pct=v1?((diff/v1)*100):0;
        const isNum=r.k!=='count';
        return `<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
          <td style="padding:10px 16px;font-weight:700;color:${r.color};">${r.icon} ${r.label}</td>
          <td style="padding:10px 16px;text-align:right;">${isNum?'৳'+pf(v1):v1}</td>
          <td style="padding:10px 16px;text-align:right;font-weight:700;">${isNum?'৳'+pf(v2):v2}</td>
          <td style="padding:10px 16px;text-align:right;color:${diff>=0?'#16a34a':'#dc2626'};">${diff>=0?'+':''}${isNum?'৳'+pf(diff):diff}</td>
          <td style="padding:10px 16px;text-align:right;">
            <span style="background:${pct>=0?'#dcfce7':'#fee2e2'};color:${pct>=0?'#16a34a':'#dc2626'};padding:3px 8px;border-radius:20px;font-size:11px;font-weight:700;">
              ${pct>=0?'▲':'▼'} ${Math.abs(pct).toFixed(1)}%
            </span>
          </td>
        </tr>`;
      }).join('')}</tbody>
    </table>
  </div>`;
}

// ── Expense Analysis ───────────────────────────────────────────
const EXPENSE_GROUPS={
  'Staff Costs':['Salary Payment','Employee Advance','Employee Loan'],
  'Office & Utilities':['Office Rent','Electricity Bill','Internet Bill','Telephone Bill'],
  'Transport & Logistics':['Fuel Expense','Transport Cost','Loading Charge','Unloading Charge'],
  'Professional Fees':['Commission Payment','Brokerage Fee','Legal Fee','Audit Fee'],
  'Government & Compliance':['Insurance Premium','Tax Payment','Government Fee','License Fee'],
  'Maintenance':['Maintenance Cost','Repair Expense','Stationery Purchase'],
  'Finance Costs':['Interest Expense','Bank Charge'],
  'Other':['Other Expense']
};

function renderExpenseAnalysis(){
  // Auto-inject page structure if needed
  (function(){
    const _pg=document.getElementById('pg-expenseanalysis');
    if(_pg&&!_pg.querySelector('[id]')){
      _pg.innerHTML=`<div style="padding:20px;"><h2 style="font-size:18px;font-weight:800;color:#0f3d26;margin:0 0 16px;">💸 Expense Analysis</h2><div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:16px;"><input type=\"date\" id=\"ea-from\" data-x-change=\"renderExpenseAnalysis()\" style=\"padding:8px 12px;border:1.5px solid #d1d5db;border-radius:8px;font-size:13px;\"><input type=\"date\" id=\"ea-to\" data-x-change=\"renderExpenseAnalysis()\" style=\"padding:8px 12px;border:1.5px solid #d1d5db;border-radius:8px;font-size:13px;\"><button data-x-click=\"renderExpenseAnalysis()\" style=\"padding:8px 16px;background:#16a34a;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:12px;\">🔄 Refresh</button></div><div id=\"ea-cards\" style=\"display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:12px;margin-bottom:16px;\"></div><div id=\"ea-body\" style=\"background:#fff;border-radius:12px;padding:16px;border:1px solid #e5e7eb;\"></div></div>`;
    }
  })();
  const today=new Date().toISOString().split('T')[0];
  const fromEl=document.getElementById('ea-from');
  const toEl=document.getElementById('ea-to');
  if(!fromEl.value){const d=new Date();d.setDate(1);fromEl.value=d.toISOString().split('T')[0];}
  if(!toEl.value) toEl.value=today;
  const from=fromEl.value, to=toEl.value;

  const allExpTypes=Object.values(EXPENSE_GROUPS).flat();
  const txns=(DB.tx||[]).filter(t=>allExpTypes.includes(t.type)&&_dk(t.date)>=_dk(from)&&_dk(t.date)<=_dk(to));
  const totalExp=txns.reduce((s,t)=>s+txAmt(t),0);
  const cats=Object.keys(EXPENSE_GROUPS).filter(g=>EXPENSE_GROUPS[g].some(et=>txns.find(t=>t.type===et))).length;

  const cards=document.getElementById('ea-cards');
  if(cards) cards.innerHTML=[
    {label:'Total Expenses',val:'৳'+pf(totalExp),icon:'💸',color:'#dc2626'},
    {label:'Transactions',val:txns.length,icon:'📋',color:'#2563eb'},
    {label:'Categories',val:cats,icon:'🏷️',color:'#7c3aed'},
    {label:'Avg per Day',val:'৳'+pf(totalExp/Math.max(1,Math.ceil((new Date(to)-new Date(from))/(1000*60*60*24)))),icon:'📅',color:'#f59e0b'}
  ].map(c=>`<div data-x-click="openPLDrill('${from}','${to}')" style="cursor:pointer;background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;" title="Click to see these transactions">
    <div style="font-size:22px;">${c.icon}</div>
    <div style="font-size:17px;font-weight:900;color:${c.color};">${c.val}</div>
    <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)} →</div>
  </div>`).join('');

  const body=document.getElementById('ea-body');
  if(!body) return;
  if(!txns.length){body.innerHTML='<div style="text-align:center;padding:40px;color:#9ca3af;">No expenses in selected period.</div>';return;}

  const GRP_COLORS=['#dc2626','#f59e0b','#2563eb','#7c3aed','#16a34a','#ea580c','#0891b2','#6b7280'];
  let html='';
  Object.entries(EXPENSE_GROUPS).forEach(([grp,types],gi)=>{
    const grpTxns=txns.filter(t=>types.includes(t.type));
    if(!grpTxns.length) return;
    const grpTotal=grpTxns.reduce((s,t)=>s+txAmt(t),0);
    const pct=totalExp?((grpTotal/totalExp)*100).toFixed(1):0;
    const color=GRP_COLORS[gi%GRP_COLORS.length];
    html+=`<div style="margin-bottom:2px;">
      <div style="background:${color}11;border-left:4px solid ${color};padding:10px 16px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;" data-x-collapse-next="1">
        <span style="font-weight:700;color:${color};font-size:13px;">📂 ${grp}</span>
        <span style="font-weight:800;color:${color};">৳${pf(grpTotal)} <span style="font-size:10px;background:${color}22;padding:2px 7px;border-radius:10px;">${pct}%</span></span>
      </div>
      <div style="display:none;">
        <table style="width:100%;border-collapse:collapse;font-size:11px;">
          ${grpTxns.map((t,i)=>`<tr data-x-click="editTx(${t.id})" style="cursor:pointer;border-bottom:1px solid #f9fafb;background:${i%2?'#fafafa':'#fff'};" title="Click to edit this transaction">
            <td style="padding:7px 16px 7px 28px;color:#6b7280;">${t.date}</td>
            <td style="padding:7px 12px;font-weight:600;">${t.type}</td>
            <td style="padding:7px 12px;color:#6b7280;">${escHTML(t.party||'—')} →</td>
            <td style="padding:7px 12px;color:#6b7280;">${escHTML(t.desc||'—')}</td>
            <td style="padding:7px 12px;text-align:right;font-weight:700;color:${color};">৳${pf(txAmt(t))}</td>
          </tr>`).join('')}
          <tr style="background:${color}11;font-weight:800;">
            <td colspan="4" style="padding:7px 16px 7px 28px;color:${color};">Subtotal</td>
            <td style="padding:7px 12px;text-align:right;color:${color};">৳${pf(grpTotal)}</td>
          </tr>
        </table>
      </div>
    </div>`;
  });
  html+=`<div style="background:#f0fdf4;padding:12px 16px;display:flex;justify-content:space-between;font-weight:800;font-size:13px;border-top:2px solid #16a34a;">
    <span style="color:#0f3d26;">GRAND TOTAL EXPENSES</span>
    <span style="color:#dc2626;">৳${pf(totalExp)}</span>
  </div>`;
  body.innerHTML=html;
}


// ══════════════════════════════════════════════════════════════
// BATCH L: PRODUCT P&L, SALES BY PRODUCT, CUSTOMER PROFIT, STOCK MOVEMENT, PROFIT DIST
// ══════════════════════════════════════════════════════════════

// ── Product P&L ────────────────────────────────────────────────
function renderProductPL(){
  const today=new Date().toISOString().split('T')[0];
  const fromEl=document.getElementById('ppl-from');
  const toEl=document.getElementById('ppl-to');
  if(!fromEl.value){const d=new Date();d.setDate(1);fromEl.value=d.toISOString().split('T')[0];}
  if(!toEl.value) toEl.value=today;
  const from=fromEl.value, to=toEl.value;

  const txns=(DB.tx||[]).filter(t=>_dk(t.date)>=_dk(from)&&_dk(t.date)<=_dk(to));
  const prodMap={};

  /* FIX (Multiple Products lines invisible here): see txLines()/cogsByProduct()
     — a multi-product transaction's real lines live in t.items[], not the
     top-level product/qty/amount fields. Each line is now its own entry
     under its own real product name; ordinary single-product transactions
     (no items[]) are read exactly as before via txLines()'s fallback. */
  txns.forEach(t=>{
    const lines=window.txLines?window.txLines(t):[{product:t.product||t.desc||'Unknown',qty:parseFloat(t.qty||0),amt:txAmt(t)}];
    lines.forEach(ln=>{
      const prod=ln.product||'Unknown';
      if(!prodMap[prod]) prodMap[prod]={name:prod,salesAmt:0,salesQty:0,purchaseAmt:0,purchaseQty:0,costAmt:0};
      if(isRevenueTx(t)){prodMap[prod].salesAmt+=ln.amt;prodMap[prod].salesQty+=ln.qty;}
      else if(isCogsTx(t)){prodMap[prod].purchaseAmt+=ln.amt;prodMap[prod].purchaseQty+=ln.qty;}
      else if(['Transport Cost','Loading Charge','Unloading Charge'].includes(t.type)&&t.product){prodMap[prod].costAmt+=ln.amt;}
    });
  });

  const products=Object.values(prodMap).filter(p=>p.salesAmt>0||p.purchaseAmt>0);
  const _cogsMap2=window.cogsByProduct(txns);
  products.forEach(p=>{p.cogs=(_cogsMap2[p.name]||{}).cogs||0;p.grossProfit=p.salesAmt-p.cogs;p.netProfit=p.grossProfit-p.costAmt;p.margin=p.salesAmt?((p.netProfit/p.salesAmt)*100):0;});
  products.sort((a,b)=>b.netProfit-a.netProfit);

  const totSales=products.reduce((s,p)=>s+p.salesAmt,0);
  const totPurch=products.reduce((s,p)=>s+p.purchaseAmt,0);
  const totProfit=products.reduce((s,p)=>s+p.netProfit,0);
  const avgMargin=products.length?products.reduce((s,p)=>s+p.margin,0)/products.length:0;

  const cards=document.getElementById('ppl-cards');
  if(cards) cards.innerHTML=[
    {label:'Total Sales',val:'৳'+pf(totSales),icon:'📈',color:'#16a34a'},
    {label:'Total Purchases',val:'৳'+pf(totPurch),icon:'📦',color:'#dc2626'},
    {label:'Net Profit',val:'৳'+pf(totProfit),icon:'💰',color:totProfit>=0?'#0f3d26':'#dc2626'},
    {label:'Avg Margin',val:avgMargin.toFixed(1)+'%',icon:'📊',color:'#7c3aed'}
  ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
    <div style="font-size:22px;">${c.icon}</div>
    <div style="font-size:17px;font-weight:900;color:${c.color};">${c.val}</div>
    <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)}</div>
  </div>`).join('');

  const body=document.getElementById('ppl-body');
  if(!body) return;
  if(!products.length){body.innerHTML='<div style="text-align:center;padding:40px;color:#9ca3af;">No product data in selected period.</div>';return;}
  body.innerHTML=`<table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
      <th style="padding:9px 12px;text-align:left;">Product</th>
      <th style="padding:9px 12px;text-align:right;">Sales Qty</th>
      <th style="padding:9px 12px;text-align:right;">Sales (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Purchase (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Other Costs (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Gross Profit (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Net Profit (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Margin %</th>
    </tr></thead>
    <tbody>${products.map((p,i)=>`<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
      <td style="padding:8px 12px;font-weight:700;">${escHTML(p.name)}</td>
      <td style="padding:8px 12px;text-align:right;color:#6b7280;">${p.salesQty>0?pf(p.salesQty):'—'}</td>
      <td style="padding:8px 12px;text-align:right;color:#16a34a;">৳${pf(p.salesAmt)}</td>
      <td style="padding:8px 12px;text-align:right;color:#dc2626;">৳${pf(p.purchaseAmt)}</td>
      <td style="padding:8px 12px;text-align:right;color:#f59e0b;">${p.costAmt>0?'৳'+pf(p.costAmt):'—'}</td>
      <td style="padding:8px 12px;text-align:right;color:${p.grossProfit>=0?'#2563eb':'#dc2626'};">৳${pf(p.grossProfit)}</td>
      <td style="padding:8px 12px;text-align:right;font-weight:800;color:${p.netProfit>=0?'#16a34a':'#dc2626'};">৳${pf(p.netProfit)}</td>
      <td style="padding:8px 12px;text-align:right;">
        <span style="background:${p.margin>=0?'#dcfce7':'#fee2e2'};color:${p.margin>=0?'#16a34a':'#dc2626'};padding:3px 8px;border-radius:20px;font-size:11px;font-weight:700;">${p.margin.toFixed(1)}%</span>
      </td>
    </tr>`).join('')}
    <tr style="background:#f0fdf4;font-weight:800;border-top:2px solid #16a34a;">
      <td style="padding:9px 12px;color:#0f3d26;">TOTAL</td>
      <td></td>
      <td style="padding:9px 12px;text-align:right;color:#16a34a;">৳${pf(totSales)}</td>
      <td style="padding:9px 12px;text-align:right;color:#dc2626;">৳${pf(totPurch)}</td>
      <td></td>
      <td style="padding:9px 12px;text-align:right;color:#2563eb;">৳${pf(totSales-totPurch)}</td>
      <td style="padding:9px 12px;text-align:right;color:${totProfit>=0?'#16a34a':'#dc2626'};">৳${pf(totProfit)}</td>
      <td style="padding:9px 12px;text-align:right;">${avgMargin.toFixed(1)}%</td>
    </tr></tbody></table>`;
}

// ── Sales by Product ───────────────────────────────────────────
function renderSalesByProduct(){
  const today=new Date().toISOString().split('T')[0];
  const fromEl=document.getElementById('sbp-from');
  const toEl=document.getElementById('sbp-to');
  if(!fromEl.value){const d=new Date();d.setDate(1);fromEl.value=d.toISOString().split('T')[0];}
  if(!toEl.value) toEl.value=today;
  const from=fromEl.value, to=toEl.value;

  const txns=(DB.tx||[]).filter(t=>isRevenueTx(t)&&_dk(t.date)>=_dk(from)&&_dk(t.date)<=_dk(to));
  const prodMap={};
  /* FIX (Multiple Products lines invisible here): same issue as Product P&L
     — see txLines(). Each real line in a multi-product sale now counts
     under its own product name instead of one fake combined name carrying
     the whole sale's qty/amount. */
  txns.forEach(t=>{
    const lines=window.txLines?window.txLines(t):[{product:t.prod||t.desc||'Unknown',qty:parseFloat(t.qty||0),amt:txAmt(t)}];
    lines.forEach(ln=>{
      const prod=ln.product||'Unknown';
      if(!prodMap[prod]) prodMap[prod]={name:prod,qty:0,amount:0,txns:0,customers:new Set()};
      prodMap[prod].qty+=ln.qty;
      prodMap[prod].amount+=ln.amt;
      prodMap[prod].txns++;
      if(t.party) prodMap[prod].customers.add(t.party);
    });
  });

  const products=Object.values(prodMap).map(p=>({...p,customers:p.customers.size,avgRate:p.qty?p.amount/p.qty:0})).sort((a,b)=>b.amount-a.amount);
  const totAmt=products.reduce((s,p)=>s+p.amount,0);
  const totQty=products.reduce((s,p)=>s+p.qty,0);

  const cards=document.getElementById('sbp-cards');
  if(cards) cards.innerHTML=[
    {label:'Total Revenue',val:'৳'+pf(totAmt),icon:'💰',color:'#16a34a'},
    {label:'Total Qty Sold',val:pf(totQty),icon:'📦',color:'#2563eb'},
    {label:'Products Sold',val:products.length,icon:'🏷️',color:'#7c3aed'},
    {label:'Transactions',val:txns.length,icon:'📋',color:'#f59e0b'}
  ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
    <div style="font-size:22px;">${c.icon}</div>
    <div style="font-size:17px;font-weight:900;color:${c.color};">${c.val}</div>
    <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)}</div>
  </div>`).join('');

  const body=document.getElementById('sbp-body');
  if(!body) return;
  if(!products.length){body.innerHTML='<div style="text-align:center;padding:40px;color:#9ca3af;">No sales data in selected period.</div>';return;}
  body.innerHTML=`<table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
      <th style="padding:9px 12px;text-align:left;">Product</th>
      <th style="padding:9px 12px;text-align:right;">Qty Sold</th>
      <th style="padding:9px 12px;text-align:right;">Avg Rate (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Revenue (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Share %</th>
      <th style="padding:9px 12px;text-align:right;">Customers</th>
      <th style="padding:9px 12px;text-align:right;">Transactions</th>
    </tr></thead>
    <tbody>${products.map((p,i)=>{
      const share=totAmt?((p.amount/totAmt)*100):0;
      return `<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
        <td style="padding:8px 12px;font-weight:700;">${escHTML(p.name)}</td>
        <td style="padding:8px 12px;text-align:right;">${p.qty>0?pf(p.qty):'—'}</td>
        <td style="padding:8px 12px;text-align:right;color:#6b7280;">${p.avgRate>0?'৳'+pf(p.avgRate):'—'}</td>
        <td style="padding:8px 12px;text-align:right;font-weight:700;color:#16a34a;">৳${pf(p.amount)}</td>
        <td style="padding:8px 12px;text-align:right;">
          <div style="display:flex;align-items:center;gap:6px;justify-content:flex-end;">
            <div style="width:60px;height:6px;background:#e5e7eb;border-radius:3px;overflow:hidden;">
              <div style="width:${share}%;height:100%;background:#16a34a;border-radius:3px;"></div>
            </div>
            <span style="font-size:11px;color:#6b7280;">${share.toFixed(1)}%</span>
          </div>
        </td>
        <td style="padding:8px 12px;text-align:right;color:#6b7280;">${p.customers}</td>
        <td style="padding:8px 12px;text-align:right;color:#6b7280;">${p.txns}</td>
      </tr>`;
    }).join('')}
    <tr style="background:#f0fdf4;font-weight:800;border-top:2px solid #16a34a;">
      <td style="padding:9px 12px;color:#0f3d26;">TOTAL</td>
      <td style="padding:9px 12px;text-align:right;">৳${pf(totQty)}</td>
      <td></td>
      <td style="padding:9px 12px;text-align:right;color:#16a34a;">৳${pf(totAmt)}</td>
      <td style="padding:9px 12px;text-align:right;">100%</td>
      <td></td>
      <td style="padding:9px 12px;text-align:right;">${txns.length}</td>
    </tr></tbody></table>`;
}

// ── Customer Profit Report ─────────────────────────────────────
function renderCustProfit(){
  const today=new Date().toISOString().split('T')[0];
  const fromEl=document.getElementById('cp-from');
  const toEl=document.getElementById('cp-to');
  if(!fromEl.value){const d=new Date();d.setDate(1);fromEl.value=d.toISOString().split('T')[0];}
  if(!toEl.value) toEl.value=today;
  const from=fromEl.value, to=toEl.value;

  const txns=(DB.tx||[]).filter(t=>_dk(t.date)>=_dk(from)&&_dk(t.date)<=_dk(to));
  const custMap={};
  txns.forEach(t=>{
    if(!t.party) return;
    const pt=(t.partyType||'').toLowerCase();
    if(pt!=='customer'&&!['Sale','Sales Advance','Sales Receipt','Warehouse Sale'].includes(t.type)) return;
    const p=t.party;
    if(!custMap[p]) custMap[p]={name:p,sales:0,receipts:0,costs:0,txns:0};
    const amt=txAmt(t);
    if(isRevenueTx(t)){custMap[p].sales+=amt;custMap[p].txns++;}
    else if(t.type==='Sales Receipt') custMap[p].receipts+=amt;
    else if(['Transport Cost','Loading Charge','Commission Payment'].includes(t.type)&&t.party===p) custMap[p].costs+=amt;
  });

  const customers=Object.values(custMap).filter(c=>c.sales>0).map(c=>({...c,outstanding:c.sales-c.receipts,grossProfit:c.sales-c.costs,margin:c.sales?((c.sales-c.costs)/c.sales*100):0})).sort((a,b)=>b.sales-a.sales);
  const totSales=customers.reduce((s,c)=>s+c.sales,0);
  const totReceipts=customers.reduce((s,c)=>s+c.receipts,0);
  const totOutstanding=customers.reduce((s,c)=>s+c.outstanding,0);
  const totProfit=customers.reduce((s,c)=>s+c.grossProfit,0);

  const cards=document.getElementById('cp-cards');
  if(cards) cards.innerHTML=[
    {label:'Total Sales',val:'৳'+pf(totSales),icon:'📈',color:'#16a34a'},
    {label:'Total Receipts',val:'৳'+pf(totReceipts),icon:'💵',color:'#2563eb'},
    {label:'Outstanding',val:'৳'+pf(totOutstanding),icon:'⏳',color:'#f59e0b'},
    {label:'Gross Profit',val:'৳'+pf(totProfit),icon:'💰',color:'#7c3aed'}
  ].map(c=>`<div data-x-click="nav('customers')" style="cursor:pointer;background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;" title="Click to open Customers">
    <div style="font-size:22px;">${c.icon}</div>
    <div style="font-size:17px;font-weight:900;color:${c.color};">${c.val}</div>
    <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)} →</div>
  </div>`).join('');

  const body=document.getElementById('cp-body');
  if(!body) return;
  if(!customers.length){body.innerHTML='<div style="text-align:center;padding:40px;color:#9ca3af;">No customer sales data in selected period.</div>';return;}
  body.innerHTML=`<table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
      <th style="padding:9px 12px;text-align:left;">Customer</th>
      <th style="padding:9px 12px;text-align:right;">Sales (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Receipts (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Outstanding (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Gross Profit (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Margin %</th>
      <th style="padding:9px 12px;text-align:right;">Transactions</th>
    </tr></thead>
    <tbody>${customers.map((c,i)=>`<tr data-x-click="viewPartyLedger('${escHTML(c.name).replace(/'/g,"\\'")}')" style="cursor:pointer;border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};" title="Click to open ${escHTML(c.name)}'s ledger">
      <td style="padding:8px 12px;font-weight:700;">${escHTML(c.name)} →</td>
      <td style="padding:8px 12px;text-align:right;color:#16a34a;">৳${pf(c.sales)}</td>
      <td style="padding:8px 12px;text-align:right;color:#2563eb;">৳${pf(c.receipts)}</td>
      <td style="padding:8px 12px;text-align:right;color:${c.outstanding>0?'#f59e0b':'#16a34a'};font-weight:700;">৳${pf(c.outstanding)}</td>
      <td style="padding:8px 12px;text-align:right;color:${c.grossProfit>=0?'#7c3aed':'#dc2626'};font-weight:700;">৳${pf(c.grossProfit)}</td>
      <td style="padding:8px 12px;text-align:right;">
        <span style="background:${c.margin>=0?'#f3e8ff':'#fee2e2'};color:${c.margin>=0?'#7c3aed':'#dc2626'};padding:3px 8px;border-radius:20px;font-size:11px;font-weight:700;">${c.margin.toFixed(1)}%</span>
      </td>
      <td style="padding:8px 12px;text-align:right;color:#6b7280;">${c.txns}</td>
    </tr>`).join('')}
    <tr style="background:#f0fdf4;font-weight:800;border-top:2px solid #16a34a;">
      <td style="padding:9px 12px;color:#0f3d26;">TOTAL</td>
      <td style="padding:9px 12px;text-align:right;color:#16a34a;">৳${pf(totSales)}</td>
      <td style="padding:9px 12px;text-align:right;color:#2563eb;">৳${pf(totReceipts)}</td>
      <td style="padding:9px 12px;text-align:right;color:#f59e0b;">৳${pf(totOutstanding)}</td>
      <td style="padding:9px 12px;text-align:right;color:#7c3aed;">৳${pf(totProfit)}</td>
      <td></td>
      <td style="padding:9px 12px;text-align:right;">${customers.reduce((s,c)=>s+c.txns,0)}</td>
    </tr></tbody></table>`;
}

// ── Stock Movement Report ──────────────────────────────────────
function renderStockMovement(){
  // Auto-inject page structure if needed
  (function(){
    const _pg=document.getElementById('pg-stockmovement');
    if(_pg&&!_pg.querySelector('[id]')){
      _pg.innerHTML=`<div style="padding:20px;"><h2 style="font-size:18px;font-weight:800;color:#0f3d26;margin:0 0 16px;">📦 Stock Movement</h2><div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:16px;"><input type=\"date\" id=\"smr-from\" data-x-change=\"renderStockMovement()\" style=\"padding:8px 12px;border:1.5px solid #d1d5db;border-radius:8px;font-size:13px;\"><input type=\"date\" id=\"smr-to\" data-x-change=\"renderStockMovement()\" style=\"padding:8px 12px;border:1.5px solid #d1d5db;border-radius:8px;font-size:13px;\"><button data-x-click=\"renderStockMovement()\" style=\"padding:8px 16px;background:#16a34a;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:12px;\">🔄 Refresh</button></div><div id=\"smr-cards\" style=\"display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:12px;margin-bottom:16px;\"></div><div id=\"smr-body\" style=\"background:#fff;border-radius:12px;padding:16px;border:1px solid #e5e7eb;\"></div></div>`;
    }
  })();
  const today=new Date().toISOString().split('T')[0];
  const fromEl=document.getElementById('smr-from')||document.getElementById('stk-from');
  const toEl=document.getElementById('smr-to')||document.getElementById('stk-to');
  if(fromEl && !fromEl.value){const d=new Date();d.setDate(1);fromEl.value=d.toISOString().split('T')[0];}
  if(toEl && !toEl.value) toEl.value=today;
  const from=fromEl?fromEl.value:'1970-01-01', to=toEl?toEl.value:today;

  // populate product filter dropdown once (stockmovement page)
  const pFilt=document.getElementById('stk-product-filter');
  if(pFilt && pFilt.options.length<=1){
    (DB.products||[]).forEach(p=>{const o=document.createElement('option');o.value=p.name;o.textContent=p.name;pFilt.appendChild(o);});
  }
  const filtProd=pFilt?pFilt.value:'';
  const filtType=(document.getElementById('stk-move-type')||{}).value||'';

  let txns=(DB.tx||[]).filter(t=>_dk(t.date)>=_dk(from)&&_dk(t.date)<=_dk(to));
  if(filtProd) txns=txns.filter(t=>(t.product||t.prod||t.desc)===filtProd);
  if(filtType==='IN')  txns=txns.filter(t=>isCogsTx(t));
  if(filtType==='OUT') txns=txns.filter(t=>isRevenueTx(t));
  const prodMap={};
  /* FIX (Multiple Products lines vanished into one fake combined-name row):
     a "Multiple Products" transaction stores its real lines in t.items[]
     and only keeps a human-readable "Product A + Product B" string in the
     top-level t.product field, for display. This loop used to read only
     that combined field and the transaction's total qty/amount, so a
     multi-product purchase/sale showed up here as one movement of a
     product that isn't in the product master at all — with the FULL
     combined quantity and value — while the real products involved never
     got credited with their share. Each line in items[] is now counted
     under its own real product name; a transaction with no items[] (the
     normal single-product case) is unaffected. */
  txns.forEach(t=>{
    const lines=(Array.isArray(t.items)&&t.items.length)
      ? t.items.map(it=>({prod:it.prod, qty:parseFloat(it.qty||it.wt||it.grosswt||0), amt:parseFloat(it.amount||it.amt||0)}))
      : [{prod:t.product||t.desc, qty:parseFloat(t.qty||0), amt:txAmt(t)}];
    lines.forEach(ln=>{
      const prod=ln.prod;
      if(!prod) return;
      if(!prodMap[prod]) prodMap[prod]={name:prod,inQty:0,inAmt:0,outQty:0,outAmt:0};
      if(isCogsTx(t)){prodMap[prod].inQty+=ln.qty;prodMap[prod].inAmt+=ln.amt;}
      else if(isRevenueTx(t)){prodMap[prod].outQty+=ln.qty;prodMap[prod].outAmt+=ln.amt;}
    });
  });

  // Merge with DB products for opening stock
  (DB.products||[]).forEach(p=>{
    if(!prodMap[p.name]) prodMap[p.name]={name:p.name,inQty:0,inAmt:0,outQty:0,outAmt:0};
    prodMap[p.name].openingQty=parseFloat(p.stockQty||0);
    prodMap[p.name].openingAmt=parseFloat(p.stockQty||0)*parseFloat(p.rate||0);
  });

  const products=Object.values(prodMap).filter(p=>p.inQty>0||p.outQty>0||(p.openingQty||0)>0);
  products.forEach(p=>{
    p.openingQty=p.openingQty||0;
    p.closingQty=p.openingQty+p.inQty-p.outQty;
    p.avgCost=p.inQty?p.inAmt/p.inQty:0;
    p.closingAmt=p.closingQty*p.avgCost;
  });
  products.sort((a,b)=>b.inAmt-a.inAmt);

  const totIn=products.reduce((s,p)=>s+p.inAmt,0);
  const totOut=products.reduce((s,p)=>s+p.outAmt,0);
  const totClosing=products.reduce((s,p)=>s+p.closingAmt,0);

  const cards=document.getElementById('smr-cards');
  if(cards) cards.innerHTML=[
    {label:'Total Inflow',val:'৳'+pf(totIn),icon:'📥',color:'#16a34a'},
    {label:'Total Outflow',val:'৳'+pf(totOut),icon:'📤',color:'#dc2626'},
    {label:'Closing Stock Value',val:'৳'+pf(totClosing),icon:'📦',color:'#2563eb'},
    {label:'Products Tracked',val:products.length,icon:'🏷️',color:'#f59e0b'}
  ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
    <div style="font-size:22px;">${c.icon}</div>
    <div style="font-size:17px;font-weight:900;color:${c.color};">${c.val}</div>
    <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)}</div>
  </div>`).join('');

  const body=document.getElementById('smr-body')||document.getElementById('stk-movement-table');
  if(!body) return;
  if(!products.length){body.innerHTML='<div style="text-align:center;padding:40px;color:#9ca3af;">No stock movement data in selected period.</div>';return;}
  body.innerHTML=`<table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
      <th style="padding:9px 12px;text-align:left;">Product</th>
      <th style="padding:9px 12px;text-align:right;">Opening Qty</th>
      <th style="padding:9px 12px;text-align:right;">In Qty</th>
      <th style="padding:9px 12px;text-align:right;">In Value (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Out Qty</th>
      <th style="padding:9px 12px;text-align:right;">Out Value (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Closing Qty</th>
      <th style="padding:9px 12px;text-align:right;">Closing Value (৳)</th>
    </tr></thead>
    <tbody>${products.map((p,i)=>`<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
      <td style="padding:8px 12px;font-weight:700;">${escHTML(p.name)}</td>
      <td style="padding:8px 12px;text-align:right;color:#6b7280;">${pf(p.openingQty)}</td>
      <td style="padding:8px 12px;text-align:right;color:#16a34a;">${p.inQty>0?pf(p.inQty):'—'}</td>
      <td style="padding:8px 12px;text-align:right;color:#16a34a;">${p.inAmt>0?'৳'+pf(p.inAmt):'—'}</td>
      <td style="padding:8px 12px;text-align:right;color:#dc2626;">${p.outQty>0?pf(p.outQty):'—'}</td>
      <td style="padding:8px 12px;text-align:right;color:#dc2626;">${p.outAmt>0?'৳'+pf(p.outAmt):'—'}</td>
      <td style="padding:8px 12px;text-align:right;font-weight:700;color:${p.closingQty>=0?'#0f3d26':'#dc2626'};">${pf(p.closingQty)}</td>
      <td style="padding:8px 12px;text-align:right;font-weight:700;color:#2563eb;">৳${pf(p.closingAmt)}</td>
    </tr>`).join('')}
    <tr style="background:#f0fdf4;font-weight:800;border-top:2px solid #16a34a;">
      <td style="padding:9px 12px;color:#0f3d26;">TOTAL</td>
      <td></td>
      <td></td>
      <td style="padding:9px 12px;text-align:right;color:#16a34a;">৳${pf(totIn)}</td>
      <td></td>
      <td style="padding:9px 12px;text-align:right;color:#dc2626;">৳${pf(totOut)}</td>
      <td></td>
      <td style="padding:9px 12px;text-align:right;color:#2563eb;">৳${pf(totClosing)}</td>
    </tr></tbody></table>`;
}

// ── Profit Distribution ────────────────────────────────────────
function renderProfitDist(){
  // Auto-inject page structure if needed
  (function(){
    const _pg=document.getElementById('pg-profitdist');
    if(_pg&&!_pg.querySelector('[id]')){
      _pg.innerHTML=`<div style="padding:20px;"><h2 style="font-size:18px;font-weight:800;color:#0f3d26;margin:0 0 16px;">💼 Profit Distribution</h2><div id=\"pd-cards\" style=\"display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:12px;margin-bottom:16px;\"></div><div id=\"pd-body\" style=\"background:#fff;border-radius:12px;padding:16px;border:1px solid #e5e7eb;\"></div></div>`;
    }
  })();
  const today=new Date().toISOString().split('T')[0];
  const fromEl=document.getElementById('pd-from');
  const toEl=document.getElementById('pd-to');
  if(!fromEl.value){const d=new Date();d.setDate(1);fromEl.value=d.toISOString().split('T')[0];}
  if(!toEl.value) toEl.value=today;
  const from=fromEl.value, to=toEl.value;

  const txns=(DB.tx||[]).filter(t=>_dk(t.date)>=_dk(from)&&_dk(t.date)<=_dk(to));
  const sales=txns.filter(t=>isRevenueTx(t)).reduce((s,t)=>s+txAmt(t),0);
  const purchases=txns.filter(t=>isCogsTx(t)).reduce((s,t)=>s+txAmt(t),0);
  const expenses=txns.filter(t=>isExpenseType(t.type)).reduce((s,t)=>s+txAmt(t),0);
  // COGS = cost of goods actually sold (not all purchases — unsold stock is an asset)
  const cogs=window.computeCOGS(txns);
  const grossProfit=sales-cogs;
  const netProfit=grossProfit-expenses;

  const partners=DB.partners||[];
  const totalShares=partners.reduce((s,p)=>s+parseFloat(p.share||p.sharePercentage||0),0)||100;

  const cards=document.getElementById('pd-cards');
  if(cards) cards.innerHTML=[
    {label:'Total Sales',val:'৳'+pf(sales),icon:'📈',color:'#16a34a'},
    {label:'COGS + Expenses',val:'৳'+pf(cogs+expenses),icon:'💸',color:'#dc2626'},
    {label:'Net Profit',val:'৳'+pf(netProfit),icon:'💰',color:netProfit>=0?'#0f3d26':'#dc2626'},
    {label:'Partners',val:partners.length,icon:'🤝',color:'#7c3aed'}
  ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
    <div style="font-size:22px;">${c.icon}</div>
    <div style="font-size:17px;font-weight:900;color:${c.color};">${c.val}</div>
    <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)}</div>
  </div>`).join('');

  const body=document.getElementById('pd-body');
  if(!body) return;

  if(!partners.length){
    body.innerHTML=`<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:40px;text-align:center;color:#9ca3af;">
      No partners configured. Add partners in the Partners section first.
    </div>`;
    return;
  }

  const distRows=partners.map(p=>{
    const share=parseFloat(p.share||p.sharePercentage||0);
    const pct=totalShares?share/totalShares:0;
    const amount=netProfit*pct;
    return {...p,share,pct:pct*100,amount};
  });

  body.innerHTML=`<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;margin-bottom:16px;">
    <div style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;padding:12px 16px;font-weight:700;font-size:13px;">
      📊 Profit & Loss Summary (${from} to ${to})
    </div>
    <div style="padding:16px;display:grid;grid-template-columns:1fr 1fr;gap:12px;">
      <div>
        <div style="font-size:12px;color:#6b7280;margin-bottom:8px;">INCOME</div>
        <div style="display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid #f3f4f6;"><span>Sales Revenue</span><span style="color:#16a34a;font-weight:700;">৳${pf(sales)}</span></div>
      </div>
      <div>
        <div style="font-size:12px;color:#6b7280;margin-bottom:8px;">DEDUCTIONS</div>
        <div style="display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid #f3f4f6;"><span>Purchases</span><span style="color:#dc2626;">৳${pf(purchases)}</span></div>
        <div style="display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid #f3f4f6;"><span>Operating Expenses</span><span style="color:#dc2626;">৳${pf(expenses)}</span></div>
      </div>
    </div>
    <div style="background:#f0fdf4;padding:12px 16px;display:flex;justify-content:space-between;font-weight:800;font-size:14px;border-top:2px solid #16a34a;">
      <span style="color:#0f3d26;">NET PROFIT FOR DISTRIBUTION</span>
      <span style="color:${netProfit>=0?'#16a34a':'#dc2626'};">৳${pf(netProfit)}</span>
    </div>
  </div>
  <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
    <div style="background:linear-gradient(90deg,#7c3aed,#6d28d9);color:#fff;padding:12px 16px;font-weight:700;font-size:13px;">
      🤝 Partner Distribution
    </div>
    <table style="width:100%;border-collapse:collapse;font-size:12px;">
      <thead><tr style="background:#f5f3ff;">
        <th style="padding:9px 12px;text-align:left;color:#7c3aed;">Partner Name</th>
        <th style="padding:9px 12px;text-align:right;color:#7c3aed;">Share %</th>
        <th style="padding:9px 12px;text-align:right;color:#7c3aed;">Capital (৳)</th>
        <th style="padding:9px 12px;text-align:right;color:#7c3aed;">Profit Share (৳)</th>
      </tr></thead>
      <tbody>${distRows.map((p,i)=>`<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#faf5ff':'#fff'};">
        <td style="padding:8px 12px;font-weight:700;">${escHTML(p.name)}</td>
        <td style="padding:8px 12px;text-align:right;">${p.pct.toFixed(1)}%</td>
        <td style="padding:8px 12px;text-align:right;color:#6b7280;">৳${pf(p.cap||0)}</td>
        <td style="padding:8px 12px;text-align:right;font-weight:800;color:${p.amount>=0?'#7c3aed':'#dc2626'};">৳${pf(p.amount)}</td>
      </tr>`).join('')}
      <tr style="background:#f5f3ff;font-weight:800;border-top:2px solid #7c3aed;">
        <td style="padding:9px 12px;color:#7c3aed;">TOTAL</td>
        <td style="padding:9px 12px;text-align:right;">100%</td>
        <td></td>
        <td style="padding:9px 12px;text-align:right;color:${netProfit>=0?'#7c3aed':'#dc2626'};">৳${pf(netProfit)}</td>
      </tr></tbody>
    </table>
  </div>`;
}

function saveProfitDist(){
  const fromEl=document.getElementById('pd-from');
  const toEl=document.getElementById('pd-to');
  if(!fromEl?.value||!toEl?.value){alert('Please calculate distribution first.');return;}
  const txns=(DB.tx||[]).filter(t=>_dk(t.date)>=_dk(fromEl.value)&&_dk(t.date)<=_dk(toEl.value));
  const sales=txns.filter(t=>isRevenueTx(t)).reduce((s,t)=>s+txAmt(t),0);
  const expenses=txns.filter(t=>['Salary Payment','Office Rent','Electricity Bill','Transport Cost','Other Expense'].includes(t.type)).reduce((s,t)=>s+txAmt(t),0);
  // COGS = cost of goods actually sold; unsold stock remains an asset
  const cogs=window.computeCOGS(txns);
  const netProfit=sales-cogs-expenses;
  const partners=DB.partners||[];
  const totalShares=partners.reduce((s,p)=>s+parseFloat(p.share||p.sharePercentage||0),0)||100;
  const dist={id:newId(),from:fromEl.value,to:toEl.value,total:netProfit,partners:partners.map(p=>{const share=parseFloat(p.share||p.sharePercentage||0);return{name:p.name,share,amount:netProfit*(share/totalShares)};})};
  if(!DB.profitDist) DB.profitDist=[];
  DB.profitDist.push(dist);
  saveDB();
  alert('✅ Profit distribution saved successfully!');
}


// ══════════════════════════════════════════════════════════════
// BATCH M: PAYMENT SCHEDULE, AGING REPORT, CUSTOMER/SUPPLIER AGING, DAILY PRICE
// ══════════════════════════════════════════════════════════════

// ── Shared aging helper ────────────────────────────────────────
function getAgingBucket(dateStr){
  const today=new Date();
  const txDate=new Date(dateStr);
  const days=Math.floor((today-txDate)/(1000*60*60*24));
  if(days<=30) return '0-30';
  if(days<=60) return '31-60';
  if(days<=90) return '61-90';
  if(days<=180) return '91-180';
  return '180+';
}
const AGING_BUCKETS=['0-30','31-60','61-90','91-180','180+'];
const AGING_COLORS={'0-30':'#16a34a','31-60':'#f59e0b','61-90':'#ea580c','91-180':'#dc2626','180+':'#7f1d1d'};

// ── Payment Schedule ───────────────────────────────────────────
function renderPaymentSchedule(){
  const typeFilter=document.getElementById('ps-type')?.value||'';
  const today=new Date().toISOString().split('T')[0];

  // Build outstanding balances from transactions
  const partyMap={};
  (DB.tx||[]).forEach(t=>{
    if(!t.party) return;
    const amt=txAmt(t);
    if(!partyMap[t.party]) partyMap[t.party]={name:t.party,type:'',sales:0,purchases:0,receipts:0,payments:0,lastDate:t.date};
    if(t.date>partyMap[t.party].lastDate) partyMap[t.party].lastDate=t.date;
    if(isRevenueTx(t)){partyMap[t.party].sales+=amt;partyMap[t.party].type='receivable';}
    else if(isCogsTx(t)){partyMap[t.party].purchases+=amt;partyMap[t.party].type='payable';}
    else if(t.type==='Sales Receipt') partyMap[t.party].receipts+=amt;
    else if(t.type==='Purchase Payment') partyMap[t.party].payments+=amt;
  });

  let items=Object.values(partyMap).map(p=>({
    ...p,
    outstanding:p.type==='receivable'?(p.sales-p.receipts):(p.purchases-p.payments),
    bucket:getAgingBucket(p.lastDate)
  })).filter(p=>p.outstanding>0.01);

  if(typeFilter) items=items.filter(p=>p.type===typeFilter);
  items.sort((a,b)=>b.outstanding-a.outstanding);

  const totReceivable=items.filter(p=>p.type==='receivable').reduce((s,p)=>s+p.outstanding,0);
  const totPayable=items.filter(p=>p.type==='payable').reduce((s,p)=>s+p.outstanding,0);
  const overdue=items.filter(p=>['61-90','91-180','180+'].includes(p.bucket)).reduce((s,p)=>s+p.outstanding,0);

  const cards=document.getElementById('ps-cards');
  if(cards) cards.innerHTML=[
    {label:'Total Receivable',val:'৳'+pf(totReceivable),icon:'💵',color:'#16a34a'},
    {label:'Total Payable',val:'৳'+pf(totPayable),icon:'💸',color:'#dc2626'},
    {label:'Overdue (>60 days)',val:'৳'+pf(overdue),icon:'⚠️',color:'#ea580c'},
    {label:'Parties',val:items.length,icon:'👥',color:'#7c3aed'}
  ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
    <div style="font-size:22px;">${c.icon}</div>
    <div style="font-size:17px;font-weight:900;color:${c.color};">${c.val}</div>
    <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)}</div>
  </div>`).join('');

  const body=document.getElementById('ps-body');
  if(!body) return;
  if(!items.length){body.innerHTML='<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:40px;text-align:center;color:#9ca3af;">No outstanding payments found.</div>';return;}

  body.innerHTML=`<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
    <table style="width:100%;border-collapse:collapse;font-size:12px;">
      <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
        <th style="padding:9px 12px;text-align:left;">Party Name</th>
        <th style="padding:9px 12px;text-align:left;">Type</th>
        <th style="padding:9px 12px;text-align:right;">Total (৳)</th>
        <th style="padding:9px 12px;text-align:right;">Paid/Received (৳)</th>
        <th style="padding:9px 12px;text-align:right;">Outstanding (৳)</th>
        <th style="padding:9px 12px;text-align:left;">Last Activity</th>
        <th style="padding:9px 12px;text-align:left;">Age</th>
        <th style="padding:9px 12px;text-align:left;">Status</th>
      </tr></thead>
      <tbody>${items.map((p,i)=>{
        const color=AGING_COLORS[p.bucket]||'#6b7280';
        const isRec=p.type==='receivable';
        return `<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
          <td style="padding:8px 12px;font-weight:700;">${escHTML(p.name)}</td>
          <td style="padding:8px 12px;">
            <span style="background:${isRec?'#dcfce7':'#fee2e2'};color:${isRec?'#16a34a':'#dc2626'};padding:2px 8px;border-radius:10px;font-size:10px;font-weight:700;">${isRec?'RECEIVABLE':'PAYABLE'}</span>
          </td>
          <td style="padding:8px 12px;text-align:right;">৳${pf(isRec?p.sales:p.purchases)}</td>
          <td style="padding:8px 12px;text-align:right;color:#6b7280;">৳${pf(isRec?p.receipts:p.payments)}</td>
          <td style="padding:8px 12px;text-align:right;font-weight:800;color:${color};">৳${pf(p.outstanding)}</td>
          <td style="padding:8px 12px;color:#6b7280;">${p.lastDate}</td>
          <td style="padding:8px 12px;"><span style="background:${color}22;color:${color};padding:2px 8px;border-radius:10px;font-size:10px;font-weight:700;">${p.bucket} days</span></td>
          <td style="padding:8px 12px;">
            <span style="background:${['0-30'].includes(p.bucket)?'#dcfce7':['31-60'].includes(p.bucket)?'#fef3c7':'#fee2e2'};color:${['0-30'].includes(p.bucket)?'#16a34a':['31-60'].includes(p.bucket)?'#d97706':'#dc2626'};padding:2px 8px;border-radius:10px;font-size:10px;font-weight:700;">
              ${['0-30'].includes(p.bucket)?'Current':['31-60'].includes(p.bucket)?'Due Soon':'Overdue'}
            </span>
          </td>
        </tr>`;
      }).join('')}
      <tr style="background:#f0fdf4;font-weight:800;border-top:2px solid #16a34a;">
        <td colspan="4" style="padding:9px 12px;color:#0f3d26;">TOTAL OUTSTANDING</td>
        <td style="padding:9px 12px;text-align:right;color:#0f3d26;">৳${pf(items.reduce((s,p)=>s+p.outstanding,0))}</td>
        <td colspan="3"></td>
      </tr></tbody>
    </table>
  </div>`;
}

// ── Aging Report ───────────────────────────────────────────────
function renderAgingReport(){
  const type=document.getElementById('ar-type')?.value||'customer';
  const isCustomer=type==='customer';

  const partyMap={};
  (DB.tx||[]).forEach(t=>{
    if(!t.party) return;
    const amt=txAmt(t);
    if(isCustomer){
      if(isRevenueTx(t)){
        if(!partyMap[t.party]) partyMap[t.party]={name:t.party,txns:[]};
        partyMap[t.party].txns.push({date:t.date,amount:amt,type:'sale'});
      } else if(t.type==='Sales Receipt'){
        if(!partyMap[t.party]) partyMap[t.party]={name:t.party,txns:[]};
        partyMap[t.party].txns.push({date:t.date,amount:-amt,type:'receipt'});
      }
    } else {
      if(isCogsTx(t)){
        if(!partyMap[t.party]) partyMap[t.party]={name:t.party,txns:[]};
        partyMap[t.party].txns.push({date:t.date,amount:amt,type:'purchase'});
      } else if(t.type==='Purchase Payment'){
        if(!partyMap[t.party]) partyMap[t.party]={name:t.party,txns:[]};
        partyMap[t.party].txns.push({date:t.date,amount:-amt,type:'payment'});
      }
    }
  });

  const rows=Object.values(partyMap).map(p=>{
    const buckets={'0-30':0,'31-60':0,'61-90':0,'91-180':0,'180+':0};
    let balance=0;
    p.txns.sort((a,b)=>a.date.localeCompare(b.date)).forEach(t=>{
      balance+=t.amount;
    });
    // Assign outstanding to oldest bucket based on last transaction date
    const lastTxn=p.txns[p.txns.length-1];
    if(lastTxn&&balance>0) buckets[getAgingBucket(lastTxn.date)]=balance;
    return {name:p.name,balance,...buckets,total:balance};
  }).filter(r=>r.total>0.01);
  rows.sort((a,b)=>b.total-a.total);

  const totals={'0-30':0,'31-60':0,'61-90':0,'91-180':0,'180+':0,total:0};
  rows.forEach(r=>{AGING_BUCKETS.forEach(b=>{totals[b]+=r[b]||0;});totals.total+=r.total;});

  const cards=document.getElementById('ar-cards');
  if(cards) cards.innerHTML=AGING_BUCKETS.map(b=>{
    const color=AGING_COLORS[b];
    return `<div style="background:#fff;border:2px solid ${color}22;border-radius:10px;padding:14px;text-align:center;">
      <div style="font-size:11px;font-weight:700;color:${color};margin-bottom:4px;">${b} DAYS</div>
      <div style="font-size:16px;font-weight:900;color:${color};">৳${pf(totals[b])}</div>
      <div style="font-size:10px;color:#6b7280;margin-top:2px;">${totals.total?((totals[b]/totals.total)*100).toFixed(1)+'%':'0%'}</div>
    </div>`;
  }).join('');

  const body=document.getElementById('ar-body');
  if(!body) return;
  if(!rows.length){body.innerHTML='<div style="padding:40px;text-align:center;color:#9ca3af;">No outstanding balances found.</div>';return;}
  body.innerHTML=`<table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
      <th style="padding:9px 12px;text-align:left;">${isCustomer?'Customer':'Supplier'}</th>
      ${AGING_BUCKETS.map(b=>`<th style="padding:9px 12px;text-align:right;">${b} Days</th>`).join('')}
      <th style="padding:9px 12px;text-align:right;">Total (৳)</th>
    </tr></thead>
    <tbody>${rows.map((r,i)=>`<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
      <td style="padding:8px 12px;font-weight:700;">${escHTML(r.name)}</td>
      ${AGING_BUCKETS.map(b=>`<td style="padding:8px 12px;text-align:right;color:${AGING_COLORS[b]};">${r[b]>0?'৳'+pf(r[b]):'—'}</td>`).join('')}
      <td style="padding:8px 12px;text-align:right;font-weight:800;color:#0f3d26;">৳${pf(r.total)}</td>
    </tr>`).join('')}
    <tr style="background:#f0fdf4;font-weight:800;border-top:2px solid #16a34a;">
      <td style="padding:9px 12px;color:#0f3d26;">TOTAL</td>
      ${AGING_BUCKETS.map(b=>`<td style="padding:9px 12px;text-align:right;color:${AGING_COLORS[b]};">৳${pf(totals[b])}</td>`).join('')}
      <td style="padding:9px 12px;text-align:right;color:#0f3d26;">৳${pf(totals.total)}</td>
    </tr></tbody></table>`;
}

// ── Customer Aging ─────────────────────────────────────────────
function renderCustomerAging(){
  const partyMap={};
  (DB.tx||[]).forEach(t=>{
    if(!t.party) return;
    const amt=txAmt(t);
    if(isRevenueTx(t)){
      if(!partyMap[t.party]) partyMap[t.party]={name:t.party,sales:0,receipts:0,lastSale:t.date};
      partyMap[t.party].sales+=amt;
      if(t.date>partyMap[t.party].lastSale) partyMap[t.party].lastSale=t.date;
    } else if(t.type==='Sales Receipt'){
      if(!partyMap[t.party]) partyMap[t.party]={name:t.party,sales:0,receipts:0,lastSale:t.date};
      partyMap[t.party].receipts+=amt;
    }
  });

  /* FIX (didn't match the Balance Sheet): this used to size "outstanding"
     purely off Sale/Receipt transactions — sales minus receipts. Two ways
     that silently diverges from the party's real, current balance (the same
     .bal the Balance Sheet reads via partyBuckets()):
       1) A customer whose due comes from an opening balance typed into their
          party record — the normal way to bring an existing business's
          books into the app — has no matching Sale transaction at all, so
          they never appeared here even though the Balance Sheet counted
          them in Customer Due.
       2) A sale paid off some other way than a separate "Sales Receipt" row
          (e.g. money received against it on the sale transaction itself)
          left "receipts" understated, showing a customer as owing more than
          their actual ledger balance.
     Every actual customer's outstanding figure now comes straight from their
     ledger .bal, so this can never disagree with the Balance Sheet. The
     Sales/Received columns still come from transaction history, for
     context only; a party with no matching transactions (opening-balance-
     only) shows those as ৳0 and ages into the oldest bucket, since its true
     age is unknown. */
  (DB.customers||[]).forEach(p=>{
    if(window.isSupplierParty && window.isSupplierParty(p)) return;
    const bal=parseFloat(p&&p.bal)||0;
    const name=p.name;
    if(!partyMap[name]) partyMap[name]={name,sales:0,receipts:0,lastSale:null};
    partyMap[name].bal=bal;
  });

  const rows=Object.values(partyMap).map(p=>({...p,outstanding:(p.bal!=null?p.bal:(p.sales-p.receipts)),bucket:getAgingBucket(p.lastSale)})).filter(r=>r.outstanding>0.01).sort((a,b)=>b.outstanding-a.outstanding);
  const tot=rows.reduce((s,r)=>s+r.outstanding,0);
  const overdue=rows.filter(r=>['61-90','91-180','180+'].includes(r.bucket)).reduce((s,r)=>s+r.outstanding,0);

  const cards=document.getElementById('ca-cards');
  if(cards) cards.innerHTML=[
    {label:'Total Receivable',val:'৳'+pf(tot),icon:'💵',color:'#16a34a'},
    {label:'Customers',val:rows.length,icon:'👥',color:'#2563eb'},
    {label:'Overdue',val:'৳'+pf(overdue),icon:'⚠️',color:'#dc2626'},
    {label:'Avg Outstanding',val:'৳'+pf(rows.length?tot/rows.length:0),icon:'📊',color:'#7c3aed'}
  ].map(c=>`<div data-x-click="nav('customers')" style="cursor:pointer;background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;" title="Click to view customers">
    <div style="font-size:22px;">${c.icon}</div>
    <div style="font-size:17px;font-weight:900;color:${c.color};">${c.val}</div>
    <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)} →</div>
  </div>`).join('');

  const body=document.getElementById('ca-body');
  if(!body) return;
  if(!rows.length){body.innerHTML='<div style="padding:40px;text-align:center;color:#9ca3af;">No customer receivables found.</div>';return;}
  body.innerHTML=`<table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
      <th style="padding:9px 12px;text-align:left;">Customer</th>
      <th style="padding:9px 12px;text-align:right;">Total Sales (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Received (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Outstanding (৳)</th>
      <th style="padding:9px 12px;text-align:left;">Last Sale</th>
      <th style="padding:9px 12px;text-align:left;">Age</th>
      <th style="padding:9px 12px;text-align:left;">Risk</th>
    </tr></thead>
    <tbody>${rows.map((r,i)=>{
      const color=AGING_COLORS[r.bucket]||'#6b7280';
      const risk=r.bucket==='0-30'?'Low':r.bucket==='31-60'?'Medium':r.bucket==='61-90'?'High':'Critical';
      const riskColor=r.bucket==='0-30'?'#16a34a':r.bucket==='31-60'?'#f59e0b':r.bucket==='61-90'?'#ea580c':'#dc2626';
      return `<tr data-x-click="viewPartyLedger('${escHTML(r.name).replace(/'/g,"\\'")}')" style="cursor:pointer;border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};" title="Click to open ${escHTML(r.name)}'s ledger">
        <td style="padding:8px 12px;font-weight:700;">${escHTML(r.name)} →</td>
        <td style="padding:8px 12px;text-align:right;">৳${pf(r.sales)}</td>
        <td style="padding:8px 12px;text-align:right;color:#2563eb;">৳${pf(r.receipts)}</td>
        <td style="padding:8px 12px;text-align:right;font-weight:800;color:${color};">৳${pf(r.outstanding)}</td>
        <td style="padding:8px 12px;color:#6b7280;">${r.lastSale}</td>
        <td style="padding:8px 12px;"><span style="background:${color}22;color:${color};padding:2px 8px;border-radius:10px;font-size:10px;font-weight:700;">${r.bucket} days</span></td>
        <td style="padding:8px 12px;"><span style="background:${riskColor}22;color:${riskColor};padding:2px 8px;border-radius:10px;font-size:10px;font-weight:700;">${risk}</span></td>
      </tr>`;
    }).join('')}
    <tr style="background:#f0fdf4;font-weight:800;border-top:2px solid #16a34a;">
      <td style="padding:9px 12px;color:#0f3d26;">TOTAL</td>
      <td style="padding:9px 12px;text-align:right;">৳${pf(rows.reduce((s,r)=>s+r.sales,0))}</td>
      <td style="padding:9px 12px;text-align:right;color:#2563eb;">৳${pf(rows.reduce((s,r)=>s+r.receipts,0))}</td>
      <td style="padding:9px 12px;text-align:right;color:#0f3d26;">৳${pf(tot)}</td>
      <td colspan="3"></td>
    </tr></tbody></table>`;
}

// ── Supplier Aging ─────────────────────────────────────────────
// Ensure a page has the container an old render function expects (creates it if the
// static markup shipped without it — root cause of several "header-only" pages)
function ensureDivIn(pageId, id){
  const pg=document.getElementById(pageId);
  if(!pg) return null;
  // Scope to THIS page: several container ids exist on more than one page,
  // and document.getElementById would return the other page's copy.
  let el=pg.querySelector('#'+id);
  if(!el){
    el=document.createElement('div'); el.id=id;
    pg.appendChild(el);
  }
  return el;
}

function renderSupplierAging(){
  const partyMap={};
  (DB.tx||[]).forEach(t=>{
    if(!t.party) return;
    const amt=txAmt(t);
    if(isCogsTx(t)){
      if(!partyMap[t.party]) partyMap[t.party]={name:t.party,purchases:0,payments:0,lastPurch:t.date};
      partyMap[t.party].purchases+=amt;
      if(t.date>partyMap[t.party].lastPurch) partyMap[t.party].lastPurch=t.date;
    } else if(t.type==='Purchase Payment'){
      if(!partyMap[t.party]) partyMap[t.party]={name:t.party,purchases:0,payments:0,lastPurch:t.date};
      partyMap[t.party].payments+=amt;
    }
  });

  /* FIX (didn't match the Balance Sheet) — same issue as Customer Aging
     above, mirrored for suppliers: this used to size "outstanding" purely
     off Purchase/Purchase-Payment transactions, so (1) a supplier owed
     money purely via an opening balance (no Purchase transaction on file
     yet) never appeared here even though the Balance Sheet's Supply Due
     correctly counted them, and (2) a purchase paid off directly on the
     purchase transaction itself (mode: Cash, its own `paid` field) rather
     than via a separate "Purchase Payment" row was invisible to the
     payments sum, so a supplier already paid in full still showed as owed
     the entire purchase amount. Every supplier's outstanding figure now
     comes straight from their ledger .bal — the same number the Balance
     Sheet shows — so the two screens can never disagree. */
  (DB.customers||[]).forEach(p=>{
    if(!(window.isSupplierParty && window.isSupplierParty(p))) return;
    const bal=parseFloat(p&&p.bal)||0;
    const name=p.name;
    if(!partyMap[name]) partyMap[name]={name,purchases:0,payments:0,lastPurch:null};
    partyMap[name].bal=Math.max(0,-bal); // due to a supplier is a negative bal
  });

  const rows=Object.values(partyMap).map(p=>({...p,outstanding:(p.bal!=null?p.bal:(p.purchases-p.payments)),bucket:getAgingBucket(p.lastPurch)})).filter(r=>r.outstanding>0.01).sort((a,b)=>b.outstanding-a.outstanding);
  const tot=rows.reduce((s,r)=>s+r.outstanding,0);
  const overdue=rows.filter(r=>['61-90','91-180','180+'].includes(r.bucket)).reduce((s,r)=>s+r.outstanding,0);

  const cards=ensureDivIn('pg-supplieraging','sa-cards');
  if(cards) cards.innerHTML=[
    {label:'Total Payable',val:'৳'+pf(tot),icon:'💸',color:'#dc2626'},
    {label:'Suppliers',val:rows.length,icon:'🏭',color:'#2563eb'},
    {label:'Overdue',val:'৳'+pf(overdue),icon:'⚠️',color:'#ea580c'},
    {label:'Avg Payable',val:'৳'+pf(rows.length?tot/rows.length:0),icon:'📊',color:'#7c3aed'}
  ].map(c=>`<div data-x-click="nav('suppliers')" style="cursor:pointer;background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;" title="Click to view suppliers">
    <div style="font-size:22px;">${c.icon}</div>
    <div style="font-size:17px;font-weight:900;color:${c.color};">${c.val}</div>
    <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)} →</div>
  </div>`).join('');

  const body=ensureDivIn('pg-supplieraging','sa-body');
  if(!body) return;
  if(!rows.length){body.innerHTML='<div style="padding:40px;text-align:center;color:#9ca3af;">No supplier payables found.</div>';return;}
  body.innerHTML=`<table style="width:100%;border-collapse:collapse;font-size:12px;">
    <thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
      <th style="padding:9px 12px;text-align:left;">Supplier</th>
      <th style="padding:9px 12px;text-align:right;">Total Purchases (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Paid (৳)</th>
      <th style="padding:9px 12px;text-align:right;">Outstanding (৳)</th>
      <th style="padding:9px 12px;text-align:left;">Last Purchase</th>
      <th style="padding:9px 12px;text-align:left;">Age</th>
      <th style="padding:9px 12px;text-align:left;">Priority</th>
    </tr></thead>
    <tbody>${rows.map((r,i)=>{
      const color=AGING_COLORS[r.bucket]||'#6b7280';
      const priority=r.bucket==='0-30'?'Normal':r.bucket==='31-60'?'Due Soon':r.bucket==='61-90'?'Urgent':'Critical';
      return `<tr data-x-click="viewPartyLedger('${escHTML(r.name).replace(/'/g,"\\'")}')" style="cursor:pointer;border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};" title="Click to open ${escHTML(r.name)}'s ledger">
        <td style="padding:8px 12px;font-weight:700;">${escHTML(r.name)} →</td>
        <td style="padding:8px 12px;text-align:right;">৳${pf(r.purchases)}</td>
        <td style="padding:8px 12px;text-align:right;color:#2563eb;">৳${pf(r.payments)}</td>
        <td style="padding:8px 12px;text-align:right;font-weight:800;color:${color};">৳${pf(r.outstanding)}</td>
        <td style="padding:8px 12px;color:#6b7280;">${r.lastPurch}</td>
        <td style="padding:8px 12px;"><span style="background:${color}22;color:${color};padding:2px 8px;border-radius:10px;font-size:10px;font-weight:700;">${r.bucket} days</span></td>
        <td style="padding:8px 12px;"><span style="background:${color}22;color:${color};padding:2px 8px;border-radius:10px;font-size:10px;font-weight:700;">${priority}</span></td>
      </tr>`;
    }).join('')}
    <tr style="background:#fef2f2;font-weight:800;border-top:2px solid #dc2626;">
      <td style="padding:9px 12px;color:#991b1b;">TOTAL</td>
      <td style="padding:9px 12px;text-align:right;">৳${pf(rows.reduce((s,r)=>s+r.purchases,0))}</td>
      <td style="padding:9px 12px;text-align:right;color:#2563eb;">৳${pf(rows.reduce((s,r)=>s+r.payments,0))}</td>
      <td style="padding:9px 12px;text-align:right;color:#dc2626;">৳${pf(tot)}</td>
      <td colspan="3"></td>
    </tr></tbody></table>`;
}

// ── Daily Price Collection (multi-supplier comparison workflow) ────────
window.DPC_STATE = window.DPC_STATE || { tab: 'dashboard' };

function DPCProductList(){
  return (DB.masterData?.products || MASTER.products || (DB.products||[]).map(p=>p.name||p) || []);
}

function DPCStaffName(){
  return (window.currentUser && currentUser.name) || 'Current Staff';
}

/* Entry point — called by nav('dailyprice') and by the PB universal layer.
   Populates the dropdowns/filters then renders whichever tab is active. */
function renderDailyPrice(){
  if(!DB.dailyPrices) DB.dailyPrices=[];

  // Supplier dropdown — pulled from the real party/customer master so a
  // rate entry here links back to the same vendor used everywhere else.
  const supSel=document.getElementById('dpc-supplier');
  if(supSel){
    const cur=supSel.value;
    const sups=(typeof supplierList==='function') ? supplierList() : [];
    supSel.innerHTML='<option value="">Select Supplier</option>'+
      sups.map(n=>`<option value="${escHTML(n)}">${escHTML(n)}</option>`).join('');
    if(sups.includes(cur)) supSel.value=cur;
  }

  // Product dropdown — reuses the shared product master.
  const prodSel=document.getElementById('dpc-product');
  if(prodSel){
    const cur=prodSel.value;
    const prods=DPCProductList();
    prodSel.innerHTML='<option value="">Select Product</option>'+
      prods.map(p=>`<option value="${escHTML(p)}">${escHTML(p)}</option>`).join('');
    if(prods.includes(cur)) prodSel.value=cur;
  }

  // Product filter (comparative matrix)
  const prodFilter=document.getElementById('dpc-filter-product');
  if(prodFilter){
    const cur=prodFilter.value||'All';
    const prods=[...new Set(DB.dailyPrices.map(e=>e.product).filter(Boolean))];
    prodFilter.innerHTML='<option value="All">All Products</option>'+
      prods.map(p=>`<option value="${escHTML(p)}">${escHTML(p)}</option>`).join('');
    prodFilter.value=prods.includes(cur)?cur:'All';
  }

  // Date filter (comparative matrix)
  const dateFilter=document.getElementById('dpc-filter-date');
  if(dateFilter){
    const cur=dateFilter.value||'All';
    const dates=[...new Set(DB.dailyPrices.map(e=>e.date).filter(Boolean))].sort().reverse();
    dateFilter.innerHTML='<option value="All">All Dates</option>'+
      dates.map(d=>`<option value="${escHTML(d)}">${escHTML(d)}</option>`).join('');
    dateFilter.value=dates.includes(cur)?cur:'All';
  }

  DPCSetTab(window.DPC_STATE.tab||'dashboard');
}

/* Lowest quoted price per product across every recorded entry. */
function DPCLowestPrices(){
  const lowest={};
  (DB.dailyPrices||[]).forEach(e=>{
    if(!e.product) return;
    const price=parseFloat(e.price)||0;
    if(lowest[e.product]===undefined || price<lowest[e.product]) lowest[e.product]=price;
  });
  return lowest;
}

window.DPCSetTab = function(tab){
  window.DPC_STATE.tab=tab;
  const dashView=document.getElementById('dpc-dashboard-view');
  const anaView=document.getElementById('dpc-analytics-view');
  const dashBtn=document.getElementById('dpc-tab-dashboard');
  const anaBtn=document.getElementById('dpc-tab-analytics');
  if(dashView) dashView.style.display=(tab==='dashboard')?'block':'none';
  if(anaView) anaView.style.display=(tab==='analytics')?'block':'none';
  if(dashBtn){ dashBtn.style.background=(tab==='dashboard')?'#16a34a':'#f3f4f6'; dashBtn.style.color=(tab==='dashboard')?'#fff':'#374151'; }
  if(anaBtn){ anaBtn.style.background=(tab==='analytics')?'#16a34a':'#f3f4f6'; anaBtn.style.color=(tab==='analytics')?'#fff':'#374151'; }
  if(tab==='dashboard'){ DPCRenderCards(); DPCRenderTable(); }
  else { DPCRenderAnalytics(); }
};

/* "Best Rate Highlight" KPI cards — lowest quoted price for the products
   that actually have entries so far (capped so the row never gets absurd). */
function DPCRenderCards(){
  const cards=document.getElementById('dpc-cards');
  if(!cards) return;
  const lowest=DPCLowestPrices();
  const prods=Object.keys(lowest).slice(0,4);
  if(!prods.length){
    cards.innerHTML='<div style="grid-column:1/-1;background:#fff;border:1px dashed #d1d5db;border-radius:10px;padding:18px;text-align:center;color:#9ca3af;font-size:12px;">No rates recorded yet — add one on the left to see the best-rate highlights here.</div>';
    return;
  }
  const gradients=['#1d4ed8,#4338ca','#059669,#0f766e','#b45309,#d97706','#7c3aed,#8b5cf6'];
  cards.innerHTML=prods.map((p,i)=>`<div style="background:linear-gradient(135deg,${gradients[i%gradients.length]});color:#fff;padding:16px;border-radius:14px;position:relative;overflow:hidden;">
    <span style="font-size:10px;text-transform:uppercase;letter-spacing:.5px;background:rgba(255,255,255,.2);padding:3px 9px;border-radius:8px;font-weight:700;">Best Rate</span>
    <div style="font-size:13px;font-weight:700;margin-top:8px;">${escHTML(p)}</div>
    <div style="font-size:24px;font-weight:900;margin-top:2px;">৳${pf(lowest[p])} <span style="font-size:11px;font-weight:400;opacity:.8;">/kg</span></div>
  </div>`).join('');
}

/* Comparative Market Matrix — filterable/searchable table of every rate
   entry, with the cheapest quote per product flagged "Best Rate". */
window.DPCRenderTable = function(){
  const rows=document.getElementById('dpc-rows');
  if(!rows) return;
  const search=(document.getElementById('dpc-search')?.value||'').toLowerCase();
  const prodFilter=document.getElementById('dpc-filter-product')?.value||'All';
  const dateFilter=document.getElementById('dpc-filter-date')?.value||'All';
  const lowest=DPCLowestPrices();

  const list=(DB.dailyPrices||[]).filter(e=>{
    const matchesSearch=!search||[e.supplier,e.product,e.staff,e.bagType].some(v=>String(v||'').toLowerCase().includes(search));
    const matchesProduct=prodFilter==='All'||e.product===prodFilter;
    const matchesDate=dateFilter==='All'||e.date===dateFilter;
    return matchesSearch&&matchesProduct&&matchesDate;
  }).slice().sort((a,b)=>(b.date||'').localeCompare(a.date||''));

  if(!list.length){
    rows.innerHTML='<tr><td colspan="8" style="text-align:center;padding:36px;color:#9ca3af;">No price collection records found matching your filter criteria.</td></tr>';
    return;
  }

  const bagLabel={Plastic:'Plastic Bag',Jute:'Jute Bag',Bulk:'Bulk / Loose'};
  rows.innerHTML=list.map((e,i)=>{
    const isLowest=parseFloat(e.price)===lowest[e.product];
    const statusColor=e.status==='Approved'?'#16a34a':e.status==='Converted_to_PO'?'#7c3aed':'#f59e0b';
    const statusBg=e.status==='Approved'?'#dcfce7':e.status==='Converted_to_PO'?'#ede9fe':'#fef9c3';
    const statusLabel=e.status==='Converted_to_PO'?'PO Converted':(e.status||'Pending');
    return `<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
      <td style="padding:8px 12px;"><div style="font-weight:700;font-size:11px;">${escHTML(e.date||'')}</div><div style="font-size:10px;color:#9ca3af;">${escHTML(e.staff||'')}</div></td>
      <td style="padding:8px 12px;font-weight:700;">${escHTML(e.supplier||'')}</td>
      <td style="padding:8px 12px;">${escHTML(e.product||'')}</td>
      <td style="padding:8px 12px;text-align:right;">
        <span style="font-weight:800;color:#1d4ed8;">৳${pf(e.price)}</span>
        ${isLowest?'<span style="background:#dcfce7;color:#166534;font-size:9px;font-weight:800;padding:2px 6px;border-radius:8px;margin-left:6px;">✓ Best</span>':''}
      </td>
      <td style="padding:8px 12px;font-size:11px;">
        <span style="background:#f3f4f6;color:#374151;font-weight:700;padding:2px 8px;border-radius:6px;display:inline-block;margin-bottom:2px;">${escHTML(bagLabel[e.bagType]||e.bagType||'—')}</span>
        <div style="color:#9ca3af;">Min: ${escHTML(e.minQty||'—')}</div>
      </td>
      <td style="padding:8px 12px;font-size:11px;font-weight:600;">${escHTML(e.terms||'')}</td>
      <td style="padding:8px 12px;"><span style="background:${statusBg};color:${statusColor};font-size:10px;font-weight:800;padding:3px 9px;border-radius:10px;">${escHTML(statusLabel)}</span></td>
      <td style="padding:8px 12px;text-align:center;white-space:nowrap;">
        ${e.status!=='Converted_to_PO'?`<button data-x-click="DPCStatusChange('${e.id}','Converted_to_PO')" title="Convert to Purchase Order" style="background:#ede9fe;color:#6d28d9;border:none;padding:5px 8px;border-radius:6px;font-size:10px;font-weight:800;cursor:pointer;">PO</button>`:''}
        ${e.status==='Pending'?`<button data-x-click="DPCStatusChange('${e.id}','Approved')" title="Approve" style="background:#dcfce7;color:#166534;border:none;padding:5px 8px;border-radius:6px;font-size:10px;font-weight:800;cursor:pointer;margin-left:4px;">✓</button>`:''}
        <button data-x-click="DPCDelete('${e.id}')" title="Delete" style="background:#fef2f2;color:#b91c1c;border:none;padding:5px 8px;border-radius:6px;cursor:pointer;margin-left:4px;">🗑</button>
      </td>
    </tr>`;
  }).join('');
};

/* Trend Analytics tab — average/lowest/highest quoted rate per product. */
function DPCRenderAnalytics(){
  const el=document.getElementById('dpc-analytics-cards');
  if(!el) return;
  const prods=[...new Set((DB.dailyPrices||[]).map(e=>e.product).filter(Boolean))];
  if(!prods.length){
    el.innerHTML='<div style="grid-column:1/-1;text-align:center;color:#9ca3af;padding:30px;">No price entries recorded yet.</div>';
    return;
  }
  el.innerHTML=prods.map(prod=>{
    const entries=(DB.dailyPrices||[]).filter(e=>e.product===prod);
    const prices=entries.map(e=>parseFloat(e.price)||0);
    const avg=prices.reduce((s,v)=>s+v,0)/prices.length;
    const min=Math.min(...prices), max=Math.max(...prices);
    return `<div style="background:#f9fafb;border:1px solid #e5e7eb;border-radius:12px;padding:16px;">
      <div style="font-weight:800;color:#0f3d26;margin-bottom:2px;">${escHTML(prod)}</div>
      <div style="font-size:11px;color:#9ca3af;margin-bottom:10px;">Total Quotes Recorded: ${entries.length}</div>
      <div style="display:flex;justify-content:space-between;padding:5px 0;border-bottom:1px solid #e5e7eb;font-size:12px;"><span style="color:#6b7280;">Average Rate</span><span style="font-weight:700;">৳${pf(avg)} /kg</span></div>
      <div style="display:flex;justify-content:space-between;padding:5px 0;border-bottom:1px solid #e5e7eb;font-size:12px;"><span style="color:#16a34a;">Lowest Quoted</span><span style="font-weight:700;color:#16a34a;">৳${pf(min)} /kg</span></div>
      <div style="display:flex;justify-content:space-between;padding:5px 0;font-size:12px;"><span style="color:#dc2626;">Highest Quoted</span><span style="font-weight:700;color:#dc2626;">৳${pf(max)} /kg</span></div>
    </div>`;
  }).join('');
}

window.DPCAddEntry = function(){
  const supplier=document.getElementById('dpc-supplier')?.value||'';
  const product=document.getElementById('dpc-product')?.value||'';
  const price=parseFloat(document.getElementById('dpc-price')?.value||0);
  if(!supplier||!product||!(price>0)){
    toast('⚠️ Supplier, Product and a Price greater than 0 are required.','e');
    return;
  }
  if(!DB.dailyPrices) DB.dailyPrices=[];
  DB.dailyPrices.unshift({
    id:newId(),
    date:new Date().toISOString().split('T')[0],
    staff:DPCStaffName(),
    supplier, product, price,
    bagType:document.getElementById('dpc-bagtype')?.value||'Plastic',
    minQty:document.getElementById('dpc-minqty')?.value||'',
    terms:document.getElementById('dpc-terms')?.value||'Cash',
    status:'Pending'
  });
  saveDB();
  logAudit('PRICE','DailyPrice','Rate recorded: '+product+' from '+supplier+' @ ৳'+price);
  ['dpc-price','dpc-minqty'].forEach(id=>{ const el=document.getElementById(id); if(el) el.value=''; });
  toast('New rate entry recorded.','s');
  renderDailyPrice();
};

window.DPCStatusChange = function(id, status){
  const e=(DB.dailyPrices||[]).find(x=>String(x.id)===String(id));
  if(!e) return;
  e.status=status;
  saveDB();
  logAudit('PRICE','DailyPrice','Status updated to '+status.replace(/_/g,' ')+' for '+e.product+' ('+e.supplier+')');
  toast('Status updated to '+status.replace(/_/g,' ')+'.','s');
  DPCRenderTable();
};

window.DPCDelete = async function(id){
  if(!await __confirm('Delete this price entry?')) return;
  DB.dailyPrices=(DB.dailyPrices||[]).filter(x=>String(x.id)!==String(id));
  saveDB();
  logAudit('PRICE','DailyPrice','Deleted a price entry');
  toast('Entry removed.','s');
  renderDailyPrice();
};


