// ── Bank Reconciliation ────────────────────────────────────────
function initBrAccounts(){
  const sel=document.getElementById('br-account');
  if(!sel) return;
  const banks=DB.banks||[];
  sel.innerHTML='<option value="">-- Select Account --</option>'+
    banks.map(b=>`<option value="${escHTML(b.name)}">${escHTML(b.name)} — ৳${(b.bal||0).toLocaleString('en-IN',{minimumFractionDigits:2})}</option>`).join('');
}

function renderBankRecon(){
  // Populate bank dropdown
  const _brSel=document.getElementById('br-account');
  if(_brSel&&_brSel.options.length<=1){
    (DB.banks||[]).forEach(b=>{
      const opt=document.createElement('option');
      opt.value=b.name;
      opt.textContent=b.name+' — ৳'+(b.bal||0).toLocaleString('en-IN',{minimumFractionDigits:2});
      _brSel.appendChild(opt);
    });
  }
  // Set default month
  const _brMonth=document.getElementById('br-month');
  if(_brMonth&&!_brMonth.value) _brMonth.value=new Date().toISOString().substring(0,7);
  // Auto-inject page structure if needed
  (function(){
    const _pg=document.getElementById('pg-bankrecon');
    if(_pg&&!_pg.querySelector('[id]')){
      _pg.innerHTML=`<div style="padding:20px;"><h2 style="font-size:18px;font-weight:800;color:#0f3d26;margin:0 0 16px;">🔄 Bank Reconciliation</h2><div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:16px;"><select id=\"br-account\" data-x-change=\"renderBankRecon()\" style=\"padding:8px 12px;border:1.5px solid #d1d5db;border-radius:8px;font-size:13px;\"><option value=\"\">-- Select Account --</option></select><input type=\"month\" id=\"br-month\" data-x-change=\"renderBankRecon()\" style=\"padding:8px 12px;border:1.5px solid #d1d5db;border-radius:8px;font-size:13px;\"><button data-x-click=\"renderBankRecon()\" style=\"padding:8px 16px;background:#16a34a;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:12px;\">🔄 Reconcile</button></div><div id=\"br-cards\" style=\"display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:12px;margin-bottom:16px;\"></div><div id=\"br-body\" style=\"background:#fff;border-radius:12px;padding:16px;border:1px solid #e5e7eb;\"></div></div>`;
    }
  })();
  initBrAccounts();
  const account=document.getElementById('br-account')?.value||'';
  const monthEl=document.getElementById('br-month');
  if(!monthEl.value) monthEl.value=new Date().toISOString().slice(0,7);
  const month=monthEl.value;
  const from=month+'-01';
  const lastDay=new Date(parseInt(month.slice(0,4)),parseInt(month.slice(5,7)),0).getDate();
  const to=month+'-'+String(lastDay).padStart(2,'0');

  if(!account){
    const cardsEmpty=document.getElementById('br-cards');
    if(cardsEmpty) cardsEmpty.innerHTML='';
    const bodyEmpty=document.getElementById('br-body');
    if(bodyEmpty) bodyEmpty.innerHTML='<div style="padding:30px;text-align:center;color:#9ca3af;">Select a bank account to reconcile.</div>';
    window._brBookBalance=0;
    return;
  }

  const openingBal = ayanBankOpening(account, from);

  /* FIX (2026-09-03): this used to only recognise 6 hardcoded transaction
     types as "bank transactions" — Bank Deposit, Bank Withdrawal, Bank
     Transfer, Bank Charge, Purchase Payment, Sales Receipt. Every Salary
     Payment, Staff Salary, Expense, Supplier Payment, Bkash movement,
     split multi-bank payment and Journal Entry against this account was
     silently left out of the book balance, so reconciliation was wrong
     for any account with ordinary day-to-day activity. It now reuses the
     same ayanBankMove() engine the Bank Ledger relies on, so the two
     screens always agree on what counts as money in/out of an account. */
  const moves=(DB.tx||[]).filter(t=>{
    const inRange=_dk(t.date)>=_dk(from)&&_dk(t.date)<=_dk(to);
    return inRange;
  }).map(t=>({t,m:ayanBankMove(t,account)}))
    .filter(r=>r.m.in>0||r.m.out>0)
    .sort((a,b)=>(a.t.date||'')<(b.t.date||'')?-1:1);

  const txns=moves.map(r=>r.t);
  const deposits=moves.reduce((s,r)=>s+r.m.in,0);
  const withdrawals=moves.reduce((s,r)=>s+r.m.out,0);
  const bookBalance=deposits-withdrawals;

  const cards=document.getElementById('br-cards');
  if(cards) cards.innerHTML=[
    {label:'Total Deposits',val:'৳'+pf(deposits),icon:'📥',color:'#16a34a'},
    {label:'Total Withdrawals',val:'৳'+pf(withdrawals),icon:'📤',color:'#dc2626'},
    {label:'Book Balance',val:'৳'+pf(bookBalance),icon:'📒',color:'#2563eb'},
    {label:'Transactions',val:txns.length,icon:'📋',color:'#f59e0b'}
  ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
    <div style="font-size:22px;">${c.icon}</div>
    <div style="font-size:17px;font-weight:900;color:${c.color};">${c.val}</div>
    <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)}</div>
  </div>`).join('');

  const body=document.getElementById('br-body');
  if(!body) return;
  body.innerHTML=`<div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:16px;">
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
      <div style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;padding:12px 16px;font-weight:700;font-size:13px;">📒 Book Balance Statement</div>
      <table style="width:100%;border-collapse:collapse;font-size:12px;">
        <tbody>
          <tr style="border-bottom:1px solid #f3f4f6;"><td style="padding:10px 16px;color:#6b7280;">Opening Balance</td><td style="padding:10px 16px;text-align:right;font-weight:700;">৳${pf(openingBal)}</td></tr>
          <tr style="border-bottom:1px solid #f3f4f6;background:#f9fafb;"><td style="padding:10px 16px;color:#16a34a;">Add: Deposits</td><td style="padding:10px 16px;text-align:right;font-weight:700;color:#16a34a;">৳${pf(deposits)}</td></tr>
          <tr style="border-bottom:1px solid #f3f4f6;"><td style="padding:10px 16px;color:#dc2626;">Less: Withdrawals</td><td style="padding:10px 16px;text-align:right;font-weight:700;color:#dc2626;">(৳${pf(withdrawals)})</td></tr>
          <tr style="background:#f0fdf4;border-top:2px solid #16a34a;"><td style="padding:12px 16px;font-weight:800;color:#0f3d26;">CLOSING BOOK BALANCE</td><td style="padding:12px 16px;text-align:right;font-weight:900;font-size:15px;color:#16a34a;">৳${pf(openingBal+bookBalance)}</td></tr>
        </tbody>
      </table>
    </div>
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:16px;">
      <div style="font-weight:700;font-size:13px;color:#0f3d26;margin-bottom:12px;">🏦 Bank Statement Balance Entry</div>
      <div style="margin-bottom:12px;">
        <label style="font-size:11px;font-weight:600;color:#374151;display:block;margin-bottom:4px;">Bank Statement Closing Balance (৳)</label>
        <input id="br-stmt-bal" type="number" step="0.01" placeholder="Enter bank statement balance" style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:13px;box-sizing:border-box;" data-x-input="calcReconDiff()"/>
      </div>
      <div id="br-diff-box" style="background:#f9fafb;border:1px solid #e5e7eb;border-radius:8px;padding:12px;font-size:12px;">
        <div style="color:#6b7280;margin-bottom:4px;">Enter bank statement balance above to see difference</div>
      </div>
    </div>
  </div>
  <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
    <div style="background:#f3f4f6;padding:10px 16px;font-weight:700;font-size:12px;color:#374151;">📋 Transaction Details (${month}${account?' — '+account:''})</div>
    ${txns.length?`<table style="width:100%;border-collapse:collapse;font-size:12px;">
      <thead><tr style="background:#f9fafb;">
        <th style="padding:8px 12px;text-align:left;color:#6b7280;">Date</th>
        <th style="padding:8px 12px;text-align:left;color:#6b7280;">Type</th>
        <th style="padding:8px 12px;text-align:left;color:#6b7280;">Party</th>
        <th style="padding:8px 12px;text-align:right;color:#16a34a;">Deposit (৳)</th>
        <th style="padding:8px 12px;text-align:right;color:#dc2626;">Withdrawal (৳)</th>
      </tr></thead>
      <tbody>${moves.map((r,i)=>{
        const t=r.t, isDeposit=r.m.in>0, amt=isDeposit?r.m.in:r.m.out;
        return `<tr style="border-bottom:1px solid #f9fafb;background:${i%2?'#fafafa':'#fff'};">
          <td style="padding:7px 12px;color:#6b7280;">${t.date}</td>
          <td style="padding:7px 12px;">${t.type}</td>
          <td style="padding:7px 12px;font-weight:600;">${escHTML(t.party ||'—')}</td>
          <td style="padding:7px 12px;text-align:right;color:#16a34a;">${isDeposit?'৳'+pf(amt):'—'}</td>
          <td style="padding:7px 12px;text-align:right;color:#dc2626;">${!isDeposit?'৳'+pf(amt):'—'}</td>
        </tr>`;
      }).join('')}</tbody>
    </table>`:'<div style="padding:30px;text-align:center;color:#9ca3af;">No bank transactions found for this period.</div>'}
  </div>`;

  // Store book balance for diff calc
  window._brBookBalance=openingBal+bookBalance;
}

function calcReconDiff(){
  const stmtBal=parseFloat(document.getElementById('br-stmt-bal')?.value||0);
  const bookBal=window._brBookBalance||0;
  const diff=stmtBal-bookBal;
  const box=document.getElementById('br-diff-box');
  if(!box) return;
  box.innerHTML=`<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;">
    <div><div style="font-size:10px;color:#6b7280;">Book Balance</div><div style="font-weight:800;color:#2563eb;">৳${pf(bookBal)}</div></div>
    <div><div style="font-size:10px;color:#6b7280;">Bank Statement</div><div style="font-weight:800;color:#0f3d26;">৳${pf(stmtBal)}</div></div>
    <div style="grid-column:1/-1;border-top:1px solid #e5e7eb;padding-top:8px;">
      <div style="font-size:10px;color:#6b7280;">Difference</div>
      <div style="font-weight:900;font-size:16px;color:${Math.abs(diff)<0.01?'#16a34a':'#dc2626'};">
        ${Math.abs(diff)<0.01?'✅ RECONCILED':'⚠️ ৳'+pf(Math.abs(diff))+' '+( diff>0?'(Bank Higher)':'(Book Higher)')}
      </div>
    </div>
  </div>`;
}

// ── Cheque Management ──────────────────────────────────────────










// ── Opening Balance ────────────────────────────────────────────
function renderOpeningBalance(){
  // Auto-inject page structure if needed
  (function(){
    const _pg=document.getElementById('pg-openingbalance');
    if(_pg&&!_pg.querySelector('[id]')){
      _pg.innerHTML=`<div style="padding:20px;"><h2 style="font-size:18px;font-weight:800;color:#0f3d26;margin:0 0 16px;">🏦 Opening Balances</h2><div id=\"ob-body\" style=\"background:#fff;border-radius:12px;padding:16px;border:1px solid #e5e7eb;\"></div></div>`;
    }
  })();
  const body=document.getElementById('ob-body');
  if(!body) return;
  const ob=DB.openingBalance||{};

  const sections=[
    {title:'💵 Cash & Mobile Banking',color:'#16a34a',fields:[
      {key:'cash',label:'Hand Cash'},
      {key:'bkash',label:'bKash Account'},
      {key:'nagad',label:'Nagad Account'},
      {key:'another',label:'Another Account'}
    ]},
    {title:'🏦 Bank Accounts',color:'#2563eb',fields:(DB.bankAccounts||DB.master?.banks||MASTER.banks||[]).map(a=>{const name=typeof a==='string'?a:a.name;return{key:'bank_'+name.replace(/[^a-z0-9]/gi,'_'),label:name};})},
    {title:'👥 Customer Receivables',color:'#7c3aed',fields:(DB.parties||[]).filter(p=>isCustomerParty(p)||p.partyType==='Customer').map(p=>({key:'cust_'+p.name.replace(/[^a-z0-9]/gi,'_'),label:p.name+' (Receivable)'}))},
    {title:'🏭 Supplier Payables',color:'#dc2626',fields:(DB.parties||[]).filter(p=>isSupplierParty(p)||p.partyType==='Supplier').map(p=>({key:'supp_'+p.name.replace(/[^a-z0-9]/gi,'_'),label:p.name+' (Payable)'}))},
    {title:'🤝 Partner Capital',color:'#f59e0b',fields:(DB.partners||[]).map(p=>({key:'partner_'+p.name.replace(/[^a-z0-9]/gi,'_'),label:p.name+' (Capital)'}))},
    {title:'🏗️ Fixed Assets',color:'#ea580c',fields:[
      {key:'fa_car',label:'Car / Vehicle'},
      {key:'fa_motorcycle',label:'Motorcycle'},
      {key:'fa_warehouse',label:'Warehouse Security'},
      {key:'fa_equipment',label:'Equipment & Machinery'},
      {key:'fa_other',label:'Other Fixed Assets'}
    ]},
    {title:'📦 Inventory',color:'#0891b2',fields:[
      {key:'inv_stock',label:'Opening Stock Value'}
    ]}
  ];

  body.innerHTML=`<div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;">
    ${sections.map(sec=>`<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
      <div style="background:${sec.color}11;border-left:4px solid ${sec.color};padding:10px 16px;font-weight:700;font-size:13px;color:${sec.color};">${sec.title}</div>
      <div style="padding:12px 16px;">
        ${sec.fields.length?sec.fields.map(f=>`<div style="display:flex;align-items:center;gap:10px;margin-bottom:8px;">
          <label style="font-size:11px;color:#374151;flex:1;min-width:0;">${escHTML(f.label)}</label>
          <input type="number" step="0.01" min="0" id="ob-${f.key}" value="${ob[f.key]||''}" placeholder="0.00"
            style="width:130px;padding:6px 8px;border:1px solid #d1d5db;border-radius:5px;font-size:12px;text-align:right;"/>
        </div>`).join(''):'<div style="color:#9ca3af;font-size:12px;padding:8px 0;">No items configured yet.</div>'}
      </div>
    </div>`).join('')}
  </div>
  <div style="margin-top:16px;background:#f0fdf4;border:1px solid #16a34a;border-radius:10px;padding:14px 16px;font-size:12px;color:#0f3d26;">
    <strong>ℹ️ Note:</strong> Opening balances are used as starting values for all reports and ledgers. Enter the balances as of your business start date or the date you begin using this system.
  </div>`;
}

function saveOpeningBalance(){
  const ob={};
  document.querySelectorAll('[id^="ob-"]').forEach(el=>{
    const key=el.id.replace('ob-','');
    const val=parseFloat(el.value||0);
    if(val) ob[key]=val;
  });
  DB.openingBalance=ob;
  saveDB();
  alert('✅ Opening balance saved successfully!');
}


