// ── Audit Log Helper ───────────────────────────────────────────
function addAuditEntry(action, module, detail){
    DB.auditLog.unshift({
    id:newId(),
    ts:new Date().toISOString(),
    action,module,detail
  });
  if((DB.auditLog||[]).length>500) DB.auditLog=(DB.auditLog||[]).slice(0,500);
}

// ── Expense Categories ─────────────────────────────────────────
const EXPENSE_TYPES = [
  'Salary Payment','Staff Salary','Expense','Employee Advance','Employee Loan',
  'Office Rent','Electricity Bill','Internet Bill','Telephone Bill',
  'Fuel Expense','Transport Cost','Loading Charge','Unloading Charge',
  'Commission Payment','Brokerage Fee','Legal Fee','Audit Fee',
  'Insurance Premium','Tax Payment','Government Fee','License Fee',
  'Maintenance Cost','Repair Expense','Stationery Purchase',
  'Bank Charge','Other Expense','Interest Expense'
];

function renderExpenseCategories(){
  // Auto-inject page structure if needed
  (function(){
    const _pg=document.getElementById('pg-expensecategories');
    if(_pg&&!_pg.querySelector('[id]')){
      _pg.innerHTML=`<div style="padding:20px;"><h2 style="font-size:18px;font-weight:800;color:#0f3d26;margin:0 0 16px;">💸 Expense Categories</h2><div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:16px;"><input type=\"date\" id=\"ec-from\" data-x-change=\"renderExpenseCategories()\" style=\"padding:8px 12px;border:1.5px solid #d1d5db;border-radius:8px;font-size:13px;\"><input type=\"date\" id=\"ec-to\" data-x-change=\"renderExpenseCategories()\" style=\"padding:8px 12px;border:1.5px solid #d1d5db;border-radius:8px;font-size:13px;\"><button data-x-click=\"renderExpenseCategories()\" style=\"padding:8px 16px;background:#16a34a;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:12px;\">🔄 Refresh</button></div><div id=\"ec-cards\" style=\"display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:12px;margin-bottom:16px;\"></div><div id=\"ec-body\" style=\"background:#fff;border-radius:12px;padding:16px;border:1px solid #e5e7eb;\"></div></div>`;
    }
  })();
  const today=new Date().toISOString().split('T')[0];
  const fromEl=document.getElementById('ec-from');
  const toEl=document.getElementById('ec-to');
  if(!fromEl||!toEl){ if(typeof renderExpCats==='function') renderExpCats(); return; }
  if(!fromEl.value){const d=new Date();d.setDate(1);fromEl.value=d.toISOString().split('T')[0];}
  if(!toEl.value) toEl.value=today;
  const from=fromEl.value, to=toEl.value;

  const expTxns=(DB.tx||[]).filter(t=>{
    const isExp=Object.keys(EXPENSE_TYPES).includes(t.type)||t.type?.toLowerCase().includes('expense')||t.type?.toLowerCase().includes('payment')||t.type?.toLowerCase().includes('bill')||t.type?.toLowerCase().includes('charge')||t.type?.toLowerCase().includes('fee');
    return isExp&&_dk(t.date)>=_dk(from)&&_dk(t.date)<=_dk(to);
  });

  const catMap={};
  expTxns.forEach(t=>{
    const cat=EXPENSE_TYPES[t.type]||'Other';
    if(!catMap[cat]) catMap[cat]={total:0,count:0,items:[]};
    const amt=txAmt(t);
    catMap[cat].total+=amt;
    catMap[cat].count++;
    catMap[cat].items.push(t);
  });

  const totalExp=Object.values(catMap).reduce((s,c)=>s+c.total,0);
  const topCat=Object.entries(catMap).sort((a,b)=>b[1].total-a[1].total)[0];

  const cards=document.getElementById('ec-cards');
  if(cards) cards.innerHTML=[
    {label:'Total Expenses',val:'৳'+pf(totalExp),icon:'💸',color:'#dc2626'},
    {label:'Categories',val:Object.keys(catMap).length,icon:'📂',color:'#7c3aed'},
    {label:'Transactions',val:expTxns.length,icon:'📋',color:'#2563eb'},
    {label:'Top Category',val:topCat?topCat[0]:'—',icon:'🏆',color:'#f59e0b'}
  ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
    <div style="font-size:22px;">${c.icon}</div>
    <div style="font-size:${typeof c.val==='string'&&c.val.length>10?'13':'17'}px;font-weight:900;color:${c.color};">${c.val}</div>
    <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)}</div>
  </div>`).join('');

  const body=document.getElementById('ec-body');
  if(!body) return;
  if(!Object.keys(catMap).length){body.innerHTML='<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:40px;text-align:center;color:#9ca3af;">No expense transactions found for this period.</div>';return;}

  const catColors={'Payroll':'#7c3aed','Overhead':'#2563eb','Operations':'#f59e0b','Sales':'#16a34a','Admin':'#6b7280','Finance':'#dc2626','Maintenance':'#ea580c','Other':'#9ca3af'};
  const sorted=Object.entries(catMap).sort((a,b)=>b[1].total-a[1].total);

  body.innerHTML=`<div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:16px;">
    ${sorted.map(([cat,data])=>{
      const color=catColors[cat]||'#6b7280';
      const pct=totalExp?((data.total/totalExp)*100).toFixed(1):0;
      return `<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
        <div style="background:${color}11;border-left:4px solid ${color};padding:10px 16px;display:flex;justify-content:space-between;align-items:center;">
          <span style="font-weight:700;font-size:13px;color:${color};">${cat}</span>
          <span style="font-size:11px;background:${color}22;color:${color};padding:2px 8px;border-radius:10px;font-weight:700;">${pct}%</span>
        </div>
        <div style="padding:10px 16px;">
          <div style="display:flex;justify-content:space-between;margin-bottom:6px;">
            <span style="font-size:11px;color:#6b7280;">${data.count} transactions</span>
            <span style="font-size:15px;font-weight:900;color:${color};">৳${pf(data.total)}</span>
          </div>
          <div style="background:#f3f4f6;border-radius:4px;height:6px;overflow:hidden;">
            <div style="background:${color};height:100%;width:${pct}%;border-radius:4px;"></div>
          </div>
          <div style="margin-top:8px;max-height:80px;overflow-y:auto;">
            ${data.items.slice(0,5).map(t=>`<div style="display:flex;justify-content:space-between;font-size:10px;color:#6b7280;padding:2px 0;border-bottom:1px solid #f9fafb;">
              <span>${t.date} — ${t.type}</span><span>৳${pf(txAmt(t))}</span>
            </div>`).join('')}
            ${data.items.length>5?`<div style="font-size:10px;color:#9ca3af;text-align:center;padding-top:4px;">+${data.items.length-5} more</div>`:''}
          </div>
        </div>
      </div>`;
    }).join('')}
  </div>
  <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
    <div style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;padding:12px 16px;font-weight:700;font-size:13px;">📊 Category Summary</div>
    <table style="width:100%;border-collapse:collapse;font-size:12px;">
      <thead><tr style="background:#f0fdf4;">
        <th style="padding:8px 12px;text-align:left;color:#0f3d26;">Category</th>
        <th style="padding:8px 12px;text-align:right;color:#0f3d26;">Amount (৳)</th>
        <th style="padding:8px 12px;text-align:right;color:#0f3d26;">Count</th>
        <th style="padding:8px 12px;text-align:right;color:#0f3d26;">% of Total</th>
        <th style="padding:8px 12px;text-align:right;color:#0f3d26;">Avg per Txn</th>
      </tr></thead>
      <tbody>${sorted.map(([cat,data],i)=>{
        const color=catColors[cat]||'#6b7280';
        const pct=totalExp?((data.total/totalExp)*100).toFixed(1):0;
        return `<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
          <td style="padding:8px 12px;"><span style="display:inline-block;width:10px;height:10px;background:${color};border-radius:50%;margin-right:6px;"></span><strong>${cat}</strong></td>
          <td style="padding:8px 12px;text-align:right;font-weight:700;color:${color};">৳${pf(data.total)}</td>
          <td style="padding:8px 12px;text-align:right;">${data.count}</td>
          <td style="padding:8px 12px;text-align:right;">${pct}%</td>
          <td style="padding:8px 12px;text-align:right;color:#6b7280;">৳${pf(data.count?data.total/data.count:0)}</td>
        </tr>`;
      }).join('')}
      <tr style="background:#fef2f2;font-weight:800;border-top:2px solid #dc2626;">
        <td style="padding:9px 12px;color:#991b1b;">TOTAL</td>
        <td style="padding:9px 12px;text-align:right;color:#dc2626;">৳${pf(totalExp)}</td>
        <td style="padding:9px 12px;text-align:right;">${expTxns.length}</td>
        <td style="padding:9px 12px;text-align:right;">100%</td>
        <td style="padding:9px 12px;text-align:right;color:#6b7280;">৳${pf(expTxns.length?totalExp/expTxns.length:0)}</td>
      </tr></tbody>
    </table>
  </div>`;
}

// ── Payroll ────────────────────────────────────────────────────
function openAddEmployeeModal(){
  // FIX (Payroll/HR audit): this only ever set the join-date field and
  // opened the modal — every other field (name, designation, salary,
  // phone, NID) kept whatever was left over from the last time the modal
  // was used, including a half-finished Edit. Now resets every field and
  // clears the edit-id so Add always starts from a clean form.
  ['emp-name','emp-role','emp-salary','emp-phone','emp-nid'].forEach(id=>{
    const el=document.getElementById(id); if(el) el.value='';
  });
  const deptEl=document.getElementById('emp-dept'); if(deptEl) deptEl.selectedIndex=0;
  document.getElementById('emp-edit-id').value='';
  const t=document.getElementById('employee-modal-title'); if(t) t.textContent='👤 Add Employee';
  document.getElementById('emp-join').value=new Date().toISOString().split('T')[0];
  document.getElementById('employee-modal').style.display='flex';
}

/* FIX (Payroll/HR audit): there was no way to fix a typo in an employee's
   name/salary/phone/etc. short of deleting them (losing their history)
   and re-adding — the add-employee modal and saveEmployee() only ever
   supported creating a new record. This reuses the same modal/fields in
   an "edit" mode (tracked via the emp-edit-id hidden field) instead of
   building a second modal. */
function openEditEmployeeModal(id){
  const emp=(DB.employees||[]).find(e=>e.id===id);
  if(!emp){ toast('Employee not found','e'); return; }
  document.getElementById('emp-edit-id').value=emp.id;
  document.getElementById('emp-name').value=emp.name||'';
  document.getElementById('emp-role').value=emp.role||emp.designation||'';
  document.getElementById('emp-dept').value=emp.dept||'Operations';
  document.getElementById('emp-salary').value=emp.salary||'';
  document.getElementById('emp-join').value=emp.join||'';
  document.getElementById('emp-phone').value=emp.phone||'';
  document.getElementById('emp-nid').value=emp.nid||'';
  const t=document.getElementById('employee-modal-title'); if(t) t.textContent='✏️ Edit Employee';
  document.getElementById('employee-modal').style.display='flex';
}
window.openEditEmployeeModal=openEditEmployeeModal;

function saveEmployee(){
  // FIX (Payroll/HR audit): the Add Employee modal's "Job title" field only
  // ever got saved as emp.role — but at least 5 other places (the Payroll
  // page's own employee table, the employee profile card, global search
  // results, and more) all read emp.designation for the exact same value,
  // which was never set. Every employee's designation therefore showed as
  // "—" everywhere except the two spots that happened to read emp.role.
  // Saving both under the one value fixes every reader without touching
  // the handful of places already correctly using emp.role.
  const jobTitle=document.getElementById('emp-role')?.value||'';
  const name=document.getElementById('emp-name')?.value||'';
  const salary=parseFloat(document.getElementById('emp-salary')?.value||0);
  if(!name||!salary){alert('Name and salary are required.');return;}

  const editId=document.getElementById('emp-edit-id')?.value||'';
  const editing=editId&&(DB.employees||[]).find(e=>String(e.id)===String(editId));
  const emp=editing||{ id:newId(), status:'Active' };
  emp.name=name;
  emp.role=jobTitle;
  emp.designation=jobTitle;
  emp.dept=document.getElementById('emp-dept')?.value||'Operations';
  emp.salary=salary;
  emp.join=document.getElementById('emp-join')?.value||'';
  emp.phone=document.getElementById('emp-phone')?.value||'';
  emp.nid=document.getElementById('emp-nid')?.value||'';

  if(!editing){ (DB.employees=DB.employees||[]).push(emp); }
  saveDB();
  addAuditEntry(editing?'UPDATE':'CREATE','Payroll',(editing?'Updated':'Added')+' employee: '+emp.name);
  document.getElementById('employee-modal').style.display='none';
  renderPayroll();
  alert(editing?'✅ Employee updated!':'✅ Employee added!');
}

async function deleteEmployee(id){
  if(!await __confirm('Remove this employee?')) return;
  const emp=(DB.employees||[]).find(e=>e.id===id);
  DB.employees=(DB.employees||[]).filter(e=>e.id!==id);
  saveDB();
  addAuditEntry('DELETE','Payroll','Removed employee: '+(emp?.name||id));
  renderPayroll();
}

async function processPayroll(){
  const monthEl=document.getElementById('pr-month');
  if(!monthEl?.value){alert('Please select a month.');return;}
  const month=monthEl.value;
  const employees=(DB.employees||[]).filter(e=>e.status==='Active');
  if(!employees.length){alert('No active employees found.');return;}
  if(!await __confirm('Process payroll for '+month+'? This will create salary payment transactions.')) return;

  employees.forEach(emp=>{
    const txn={
      id:newId(),
      date:month+'-01',
      type:'Salary Payment',
      party:emp.name,
      partyType:'Employee',
      amount:emp.salary,
      mode:'Bank',
      desc:'Salary for '+month,
      account:'Cash Account'
    };
    if(!DB.transactions) DB.transactions=[];
    (DB.tx=DB.tx||[]).push(txn);
  });
  saveDB();
  addAuditEntry('CREATE','Payroll','Processed payroll for '+month+' — '+employees.length+' employees');
  alert('✅ Payroll processed for '+employees.length+' employees!');
  renderPayroll();
}


/* BUGFIX: this was a third, completely separate salary-payment path (the
   Payroll page's own employee list, distinct from the Payroll-tab "Salary"
   form and from the #mPaySalary modal opened via the Employees tab's own
   "💰 Pay" button) — a single __confirm() popup that pushed straight to
   DB.tx with mode hardcoded to 'Cash' and no account field at all, so it
   never called applyTxBalance() and never moved any bank balance. Rather
   than add a FOURTH bespoke account-picker, this now opens the same
   #mPaySalary modal (with the real account/split widget) pre-filled for
   this employee, so every "Pay Salary" entry point in the app funnels
   through the one real, working implementation. */
function paySalaryQuick(empName, salary, month){
  const emp=(DB.employees||[]).find(e=>e.name===empName);
  if(!emp){ toast('Employee not found','e'); return; }
  openPaySalaryFor(emp.id);
  setTimeout(function(){
    var monthEl=document.getElementById('pay-month');
    if(monthEl && month) monthEl.value=month;
  },150);
}
function renderPayroll(){
  const monthEl=document.getElementById('pr-month');
  if(monthEl && !monthEl.value) monthEl.value=new Date().toISOString().slice(0,7);
  const month=monthEl?monthEl.value:new Date().toISOString().slice(0,7);
  const employees=DB.employees||[];
  const salaryTxns=(DB.tx||[]).filter(t=>t.type==='Salary Payment'&&t.date&&t.date.startsWith(month));
  const advanceTxns=(DB.tx||[]).filter(t=>t.type==='Employee Advance'&&t.date&&t.date.startsWith(month));

  const totalSalary=employees.filter(e=>e.status==='Active').reduce((s,e)=>s+(e.salary||0),0);
  const paidSalary=salaryTxns.reduce((s,t)=>s+parseFloat(t.amount||t.amt||0),0);
  const totalAdvances=advanceTxns.reduce((s,t)=>s+parseFloat(t.amount||t.amt||0),0);
  const pending=Math.max(0,totalSalary-paidSalary);

  const cards=document.getElementById('pr-cards');
  if(cards) cards.innerHTML=[
    {label:'Total Payroll',val:'৳'+pf(totalSalary),icon:'💼',color:'#7c3aed'},
    {label:'Paid This Month',val:'৳'+pf(paidSalary),icon:'✅',color:'#16a34a'},
    {label:'Pending',val:'৳'+pf(pending),icon:'⏳',color:'#f59e0b'},
    {label:'Active Employees',val:employees.filter(e=>e.status==='Active').length,icon:'👥',color:'#2563eb'},
    {label:'Advances',val:'৳'+pf(totalAdvances),icon:'🏦',color:'#dc2626'},
    {label:'Total Staff',val:employees.length,icon:'👤',color:'#059669'}
  ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
    <div style="font-size:22px;">${c.icon}</div>
    <div style="font-size:11px;color:#6b7280;font-weight:700;margin-top:6px;">${escHTML(c.label)}</div>
    <div style="font-size:18px;font-weight:900;color:${c.color};margin-top:4px;">${c.val}</div>
  </div>`).join('');

  const empList=document.getElementById('pr-emp-list');
  if(empList){
    if(!employees.length){
      empList.innerHTML='<div style="text-align:center;padding:30px;color:#9ca3af;">No employees added yet.</div>';
    } else {
      empList.innerHTML=`<table class="tbl"><thead><tr>
        <th>#</th><th>Name</th><th>Designation</th><th>Salary (৳)</th><th>Status</th><th>Paid This Month</th><th>Actions</th>
      </tr></thead><tbody>${employees.map((e,i)=>{
        const empPaid=salaryTxns.filter(t=>t.party===e.name).reduce((s,t)=>s+parseFloat(t.amount||t.amt||0),0);
        const isPaid=empPaid>=(e.salary||0);
        return `<tr>
          <td>${i+1}</td>
          <td><strong>${escHTML(e.name)}</strong><br><span style="font-size:10px;color:#6b7280;">${escHTML(e.phone||'')}</span></td>
          <td>${escHTML(e.designation||'—')}</td>
          <td><strong>৳${pf(e.salary||0)}</strong></td>
          <td><span style="padding:2px 8px;border-radius:8px;font-size:10px;font-weight:700;background:${e.status==='Active'?'#dcfce7':'#fee2e2'};color:${e.status==='Active'?'#16a34a':'#dc2626'};">${e.status||'Active'}</span></td>
          <td><span style="padding:2px 8px;border-radius:8px;font-size:10px;font-weight:700;background:${isPaid?'#dcfce7':'#fef9c3'};color:${isPaid?'#16a34a':'#b45309'};">${isPaid?'✅ Paid':'⏳ Pending'}</span></td>
          <td>
            <button class="btn" style="padding:4px 10px;font-size:11px;background:#7c3aed;color:#fff;" data-x-click="paySalaryQuick('${escJSAttr(e.name)}',${e.salary||0},'${month}')">💰 Pay</button>
            <button class="btn" style="padding:4px 10px;font-size:11px;background:#f0fdf4;border:1px solid #bbf7d0;color:#16a34a;" data-x-click="openEditEmployeeModal('${e.id}')">✏️ Edit</button>
          </td>
        </tr>`;
      }).join('')}</tbody></table>`;
    }
  }

  const hist=document.getElementById('pr-salary-hist');
  if(hist){
    const allSalaryTx=(DB.tx||[]).filter(t=>t.type==='Salary Payment').sort((a,b)=>b.date.localeCompare(a.date)).slice(0,50);
    if(!allSalaryTx.length){
      hist.innerHTML='<div style="text-align:center;padding:30px;color:#9ca3af;">No salary payments recorded yet.</div>';
    } else {
      hist.innerHTML=`<table class="tbl"><thead><tr><th>Date</th><th>Employee</th><th>Amount</th><th>Month</th><th>Mode</th><th>Notes</th></tr></thead>
      <tbody>${allSalaryTx.map(t=>`<tr>
        <td>${t.date}</td>
        <td><strong>${escHTML(t.party||'—')}</strong></td>
        <td><strong style="color:#16a34a;">৳${pf(t.amount||t.amt||0)}</strong></td>
        <td>${t.salaryMonth||t.date?.substring(0,7)||'—'}</td>
        <td>${escHTML(t.mode||t.bank||'Cash')}</td>
        <td style="font-size:11px;color:#6b7280;">${escHTML(t.note||t.desc||'—')}</td>
      </tr>`).join('')}</tbody></table>`;
    }
  }

  renderPayrollAdvancesWrap();
}

/* FIX (Advances tab not refreshing): pulled out of renderPayroll() so the
   "🏦 Advances" tab click handler (renderPayrollTabContent -> was calling
   the stale renderAdvances(), which targets a #pr-adv-tbody that no longer
   exists) can call the same, correct rendering logic renderPayroll() already
   uses for #pr-advances-wrap. Previously, adding/deleting an advance and
   switching back to this tab wouldn't show the update until the whole
   Payroll page was reloaded. */
function renderPayrollAdvancesWrap(){
  const advWrap=document.getElementById('pr-advances-wrap');
  if(advWrap){
    const allAdv=(DB.tx||[]).filter(t=>t.type==='Employee Advance').sort((a,b)=>b.date.localeCompare(a.date));
    if(!allAdv.length){
      advWrap.innerHTML='<div style="text-align:center;padding:30px;color:#9ca3af;">No advances recorded.</div>';
    } else {
      advWrap.innerHTML=`<table class="tbl"><thead><tr><th>Date</th><th>Employee</th><th>Amount</th><th>Reason</th></tr></thead>
      <tbody>${allAdv.map(t=>`<tr>
        <td>${t.date}</td>
        <td><strong>${escHTML(t.party||'—')}</strong></td>
        <td><strong style="color:#dc2626;">৳${pf(t.amount||t.amt||0)}</strong></td>
        <td style="font-size:11px;color:#6b7280;">${escHTML(t.note||t.desc||'—')}</td>
      </tr>`).join('')}</tbody></table>`;
    }
  }
}

// ── Chart of Accounts ──────────────────────────────────────────
function renderChartOfAccounts(){
  const body=document.getElementById('coa-body');
  if(!body) return;

  /* FIX (Chart of Accounts disagreed with every other report in the app):
     this page computed every single balance itself, from scratch, using
     its own private (and in several cases simply wrong) rules — instead of
     the canonical computePosition()/isRevenueTx()/isCogsTx() engine every
     other screen in the app was already fixed to use today. Concretely,
     before this fix: "Bank Accounts" read DB.bankAccounts, a property that
     doesn't exist anywhere in this app (the real array is DB.banks) — so it
     always showed ৳0.00. "Fixed Assets" only counted transactions literally
     typed "Opening Fixed Asset" — it never saw a single Fixed Asset
     Purchase or Asset Sale, so it too stayed frozen at ৳0.00 forever, the
     exact same class of bug just fixed on the Balance Sheet. "Accounts
     Receivable" only subtracted the 'Sales Receipt' type, missing every
     other way a customer actually pays (cash at the point of sale, bKash,
     collections) — nowhere close to the real figure. "Salary Payable" only
     recognised payments literally typed 'Salary Payment', but the real
     Payroll module posts 'Staff Salary' — so a fully-paid payroll still
     showed as 100% outstanding here. On the books used for testing today,
     this page was showing Fixed Assets ৳0.00 and Cash Account ৳0.00 while
     the Balance Sheet correctly showed ৳27,12,936.00 and real bank
     balances — two "official" reports of the same company disagreeing with
     each other is exactly the kind of thing that gets a real business
     audited. Every figure below now traces back to the same single source
     of truth as the Balance Sheet and Trial Balance. */
  const txns=DB.tx||[];
  const P = computePosition();
  const cashBank = (DB.banks||[]).find(b=>(b.name||'').toLowerCase().includes('cash'));
  const cashBal = cashBank ? (parseFloat(cashBank.bal||cashBank.balance)||0) : 0;
  const otherBankBal = P.bankBalance - cashBal;
  const salesTxs = txns.filter(t=>window.isRevenueTx ? window.isRevenueTx(t) : false);
  const purchTxs = txns.filter(t=>window.isCogsTx ? window.isCogsTx(t) : false);
  const totalSales = salesTxs.reduce((s,t)=>s+txAmt(t),0);
  const totalPurch = purchTxs.reduce((s,t)=>s+txAmt(t),0);
  const vatRate = 0.15; // matches the VAT Management page's own default rate
  const outputVAT = totalSales*vatRate, inputVAT = totalPurch*vatRate;
  const totalExpenses = txns.filter(t=>window.EXPENSE_TX_TYPES && window.EXPENSE_TX_TYPES.has(t.type)).reduce((s,t)=>s+txAmt(t),0);
  const salaryExpense = txns.filter(t=>t.type==='Salary Payment'||t.type==='Staff Salary').reduce((s,t)=>s+txAmt(t),0);
  const salaryOwed = (DB.employees||[]).filter(e=>e.status==='Active').reduce((s,e)=>s+(parseFloat(e.salary)||0),0);

  const accounts=[
    {group:'ASSETS',color:'#2563eb',items:[
      {name:'Cash Account',code:'1001',balance:cashBal,page:'banks'},
      {name:'Bank Accounts',code:'1002',balance:otherBankBal,page:'banks'},
      {name:'Cash in Hand',code:'1050',balance:P.cashInHand,page:'banks'},
      {name:'Accounts Receivable',code:'1100',balance:P.customerDue,page:'customers'},
      {name:'Inventory / Stock',code:'1200',balance:P.stockVal,page:'inventory'},
      {name:'Fixed Assets',code:'1300',balance:P.fixedAsset,page:'assets'},
      {name:'Supplier Advances',code:'1400',balance:P.supplyAdv,page:'suppliers'}
    ]},
    {group:'LIABILITIES',color:'#dc2626',items:[
      {name:'Accounts Payable',code:'2001',balance:P.supplyDue,page:'suppliers'},
      {name:'VAT Payable',code:'2100',balance:outputVAT-inputVAT,page:'vat'},
      {name:'Salary Payable',code:'2200',balance:Math.max(0,salaryOwed-salaryExpense),page:'payroll'},
      {name:'Fixed Asset Payable',code:'2300',balance:P.leftItems.find(i=>i.label.indexOf('Fixed Asset Payable')===0)?.val||0,page:'assets'}
    ]},
    {group:'EQUITY',color:'#7c3aed',items:[
      {name:'Partner Capital',code:'3001',balance:P.partnerFund,page:'partners'},
      {name:'Retained Earnings',code:'3100',balance:P.netProfit,page:'profitloss'}
    ]},
    {group:'INCOME',color:'#16a34a',items:[
      {name:'Sales Revenue',code:'4001',balance:totalSales,types:[]},
      {name:'Other Income',code:'4100',balance:txns.filter(t=>t.type==='Other Income').reduce((s,t)=>s+txAmt(t),0),types:['Other Income']},
      {name:'Interest Income',code:'4200',balance:txns.filter(t=>t.type==='Interest Income').reduce((s,t)=>s+txAmt(t),0),types:['Interest Income']}
    ]},
    {group:'EXPENSES',color:'#f59e0b',items:[
      {name:'Cost of Goods Sold',code:'5001',balance:window.computeCOGS ? window.computeCOGS(txns) : totalPurch,types:[]},
      {name:'Salary Expense',code:'5100',balance:salaryExpense,page:'payroll'},
      {name:'Transport & Logistics',code:'5200',balance:txns.filter(t=>['Transport Cost','Loading Charge','Unloading Charge','Fuel Expense'].includes(t.type)).reduce((s,t)=>s+txAmt(t),0),types:['Transport Cost','Loading Charge','Unloading Charge','Fuel Expense']},
      {name:'Office & Admin',code:'5300',balance:txns.filter(t=>['Office Rent','Electricity Bill','Internet Bill','Telephone Bill','Stationery Purchase'].includes(t.type)).reduce((s,t)=>s+txAmt(t),0),types:['Office Rent','Electricity Bill','Internet Bill','Telephone Bill','Stationery Purchase']},
      {name:'Finance Charges',code:'5400',balance:txns.filter(t=>['Bank Charge','Interest Expense','Insurance Premium'].includes(t.type)).reduce((s,t)=>s+txAmt(t),0),types:['Bank Charge','Interest Expense','Insurance Premium']},
      {name:'Other Expenses',code:'5900',balance:txns.filter(t=>t.type==='Other Expense').reduce((s,t)=>s+txAmt(t),0),types:['Other Expense']}
    ]}
  ];

  body.innerHTML=accounts.map(grp=>{
    const grpTotal=grp.items.reduce((s,a)=>s+a.balance,0);
    return `<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;margin-bottom:16px;">
      <div style="background:${grp.color}11;border-left:4px solid ${grp.color};padding:10px 16px;display:flex;justify-content:space-between;align-items:center;">
        <span style="font-weight:800;font-size:14px;color:${grp.color};">${grp.group}</span>
        <span style="font-weight:900;font-size:15px;color:${grp.color};">৳${pf(grpTotal)}</span>
      </div>
      <table style="width:100%;border-collapse:collapse;font-size:12px;">
        <thead><tr style="background:#f9fafb;">
          <th style="padding:7px 16px;text-align:left;color:#6b7280;font-weight:600;">Code</th>
          <th style="padding:7px 16px;text-align:left;color:#6b7280;font-weight:600;">Account Name</th>
          <th style="padding:7px 16px;text-align:right;color:#6b7280;font-weight:600;">Balance (৳)</th>
        </tr></thead>
        <tbody>${grp.items.map((acc,i)=>{
          const click=acc.page?`nav('${acc.page}')`:(acc.types!==undefined?`openCOALine(${JSON.stringify(acc.types)})`:'');
          return `<tr${click?` data-x-click="${click}" style="cursor:pointer;"`:''} title="${click?'Click to open':''}" style="border-bottom:1px solid #f3f4f6;background:${i%2?'#fafafa':'#fff'};${click?'cursor:pointer;':''}">
          <td style="padding:7px 16px;font-family:monospace;color:#6b7280;">${acc.code}</td>
          <td style="padding:7px 16px;">${escHTML(acc.name)}${click?' →':''}</td>
          <td style="padding:7px 16px;text-align:right;font-weight:700;color:${acc.balance>=0?grp.color:'#dc2626'};">৳${pf(Math.abs(acc.balance))}${acc.balance<0?' (Cr)':''}</td>
        </tr>`;}).join('')}</tbody>
      </table>
    </div>`;
  }).join('');
}

// Chart of Accounts income/expense lines drill into the Transaction Sheet.
// A single-type line (e.g. "Other Income") also filters by that exact type;
// a multi-type or aggregate line (e.g. "Cost of Goods Sold") opens the full
// unfiltered sheet since the type box can only hold one value at a time.
function openCOALine(types){
  nav('txsheet');
  setTimeout(function(){
    var tyEl=document.getElementById('tsheet-type');
    if(tyEl) tyEl.value=(types&&types.length===1)?types[0]:'';
    if(typeof filterTxSheet==='function') filterTxSheet();
  },80);
}

