function saveCompanySettings(){
  if(!DB.settings) DB.settings={};
  ['companyName','companyAddress','companyPhone','companyEmail','companyTIN','companyVAT'].forEach(k=>{
    const el=document.getElementById('cfg-'+k);
    if(el) DB.settings[k]=el.value;
  });
  saveDB();
  addAuditEntry('UPDATE','Settings','Company settings updated');
  alert('✅ Settings saved!');
}

function optimizeDB(){
  // Remove duplicate transactions by ID (keep the most recent copy of each id)
  const byId=new Map();
  (DB.tx||[]).forEach(t=>byId.set(t.id,t));
  DB.tx=[...byId.values()];
  DB.transactions=DB.tx;
  // Trim audit log to 200
  if((DB.auditLog||[]).length>200) DB.auditLog=(DB.auditLog||[]).slice(0,200);
  saveDB();
  addAuditEntry('UPDATE','System','Database optimized');
  alert('✅ Database optimized!');
  renderAdminPanel();
}

function exportToCSV(){
  const txns=DB.tx||[];
  if(!txns.length){alert('No transactions to export.');return;}
  const headers=['Date','Type','Party','Party Type','Amount','Mode','Account','Product','Qty','Description'];
  const rows=txns.map(t=>[t.date,t.type,t.party,t.partyType,t.amount,t.mode,t.account,t.product,t.qty,t.desc||''].map(v=>__csvCell(v||'')).join(','));
  const csv=[headers.join(','),...rows].join('\n');
  const blob=new Blob([csv],{type:'text/csv'});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');
  a.href=url;a.download='transactions_'+new Date().toISOString().split('T')[0]+'.csv';a.click();
  addAuditEntry('EXPORT','Transactions','Exported '+txns.length+' transactions to CSV');
}

