// ── Notifications & Alerts ─────────────────────────────────────
function generateNotifications(){
  const alerts=[];
  const today=new Date();

  // Overdue payments
  const partyDues={};
  (DB.tx||[]).forEach(t=>{
    if(!t.party) return;
    const amt=txAmt(t);
    if(isRevenueTx(t)){
      if(!partyDues[t.party]) partyDues[t.party]={due:0,lastDate:t.date};
      partyDues[t.party].due+=amt;
      if(t.date>partyDues[t.party].lastDate) partyDues[t.party].lastDate=t.date;
    } else if(t.type==='Sales Receipt'){
      if(!partyDues[t.party]) partyDues[t.party]={due:0,lastDate:t.date};
      partyDues[t.party].due-=amt;
    }
  });
  Object.entries(partyDues).forEach(([name,data])=>{
    if(data.due>0){
      const days=Math.floor((today-new Date(data.lastDate))/(1000*60*60*24));
      const severity=days>90?'critical':days>60?'high':days>30?'medium':'low';
      if(days>7) alerts.push({type:'overdue',severity,title:'Overdue Payment: '+name,desc:'৳'+pf(data.due)+' outstanding for '+days+' days',icon:'💰',ts:Date.now()});
    }
  });

  // Low stock alerts
  (DB.products||[]).forEach(p=>{
    if(p.stock!==undefined&&p.minStock!==undefined&&parseFloat(p.stock||0)<parseFloat(p.minStock||0)){
      alerts.push({type:'stock',severity:'high',title:'Low Stock: '+p.name,desc:'Current: '+p.stock+' '+p.unit+' | Min: '+p.minStock+' '+p.unit,icon:'📦',ts:Date.now()});
    }
  });

  // Bounced cheques
  (DB.cheques||[]).filter(c=>c.status==='bounced').forEach(c=>{
    alerts.push({type:'cheque',severity:'critical',title:'Bounced Cheque: '+c.no,desc:'Party: '+c.party+' | Amount: ৳'+pf(c.amount),icon:'📝',ts:Date.now()});
  });

  // Pending cheques due soon
  (DB.cheques||[]).filter(c=>c.status==='pending'&&c.due).forEach(c=>{
    const daysLeft=Math.floor((new Date(c.due)-today)/(1000*60*60*24));
    if(daysLeft<=7&&daysLeft>=0) alerts.push({type:'cheque',severity:'medium',title:'Cheque Due Soon: '+c.no,desc:'Due in '+daysLeft+' days | ৳'+pf(c.amount)+' | '+c.party,icon:'⏰',ts:Date.now()});
  });

  // QC department talk reminder for active vehicles
  (DB.orders||[]).filter(o=>!o.qcTalked && o.truckId && ['Pending','Processing','On Route'].includes(o.deliveryStatus)).forEach(o=>{
    const hours=Math.floor((today-new Date(o.orderDate||o.submittedAt||today))/(1000*60*60));
    const severity=hours>48?'high':hours>12?'medium':'low';
    alerts.push({type:'qc',severity,title:'QC Talk Pending: '+o.truckId,desc:(o.customerName||'Order')+' — not yet talked with QC department',icon:'📞',ts:Date.now(),orderId:o.id});
  });

  return alerts.sort((a,b)=>{
    const order={critical:0,high:1,medium:2,low:3};
    return (order[a.severity]||3)-(order[b.severity]||3);
  });
}

function renderNotifications(){
  const alerts=generateNotifications();
  const critical=alerts.filter(a=>a.severity==='critical').length;
  const high=alerts.filter(a=>a.severity==='high').length;
  const medium=alerts.filter(a=>a.severity==='medium').length;

  const cards=document.getElementById('notif-cards');
  if(cards) cards.innerHTML=[
    {label:'Total Alerts',val:alerts.length,icon:'🔔',color:'#2563eb'},
    {label:'Critical',val:critical,icon:'🚨',color:'#dc2626'},
    {label:'High Priority',val:high,icon:'⚠️',color:'#ea580c'},
    {label:'Medium',val:medium,icon:'ℹ️',color:'#f59e0b'}
  ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
    <div style="font-size:22px;">${c.icon}</div>
    <div style="font-size:17px;font-weight:900;color:${c.color};">${c.val}</div>
    <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)}</div>
  </div>`).join('');

  const body=document.getElementById('notif-body');
  if(!body) return;
  if(!alerts.length){body.innerHTML='<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:40px;text-align:center;"><div style="font-size:40px;margin-bottom:8px;">✅</div><div style="font-size:16px;font-weight:700;color:#16a34a;">All Clear!</div><div style="font-size:12px;color:#9ca3af;margin-top:4px;">No alerts or notifications at this time.</div></div>';return;}

  const severityColors={critical:'#dc2626',high:'#ea580c',medium:'#f59e0b',low:'#6b7280'};
  const severityBg={critical:'#fef2f2',high:'#fff7ed',medium:'#fefce8',low:'#f9fafb'};
  body.innerHTML=`<div style="display:flex;flex-direction:column;gap:8px;">
    ${alerts.map(a=>{
      const color=severityColors[a.severity]||'#6b7280';
      const bg=severityBg[a.severity]||'#f9fafb';
      return `<div style="background:${bg};border:1px solid ${color}33;border-left:4px solid ${color};border-radius:8px;padding:12px 16px;display:flex;align-items:center;gap:12px;">
        <div style="font-size:24px;">${a.icon}</div>
        <div style="flex:1;">
          <div style="font-weight:700;font-size:13px;color:#0f3d26;">${a.title}</div>
          <div style="font-size:11px;color:#6b7280;margin-top:2px;">${escHTML(a.desc)}</div>
        </div>
        <span style="background:${color}22;color:${color};padding:3px 10px;border-radius:10px;font-size:10px;font-weight:700;text-transform:uppercase;">${a.severity}</span>
      </div>`;
    }).join('')}
  </div>`;
}

