  alert('✅ All notifications marked as read.');
}

// ── Health Check ───────────────────────────────────────────────
function renderHealthCheck(){
  const body=ensureDivIn('pg-healthcheck','hc-body');
  if(!body) return;
  const t0=(window.performance&&performance.now)?performance.now():Date.now();

  // ── shared helpers (single source of truth for field aliases) ──────────
  const esc=s=>String(s==null?'':s).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const n=v=>{const x=parseFloat(v);return isFinite(x)?x:0;};
  const money=v=>'৳'+Math.round(n(v)).toLocaleString('en-IN');
  const pstock=p=>(typeof window.stockQtyOf==='function')?n(window.stockQtyOf(p)):n(p.computed!=null?p.computed:(p.stockQty!=null?p.stockQty:(p.stock!=null?p.stock:p.qty)));
  const pcost=p=>(typeof window.unitCost==='function'&&n(window.unitCost(p)))||n(p.cost||p.buy||p.buyRate||p.costPrice||p.purchaseRate);
  const pmin=p=>n(p.minStock||p.reorder||p.reorderLevel);
  const DBx=(window.DB||{});
  const txns=DBx.tx||[], customers=DBx.customers||[], products=DBx.products||[],
        banks=DBx.banks||[], partners=DBx.partners||[], employees=DBx.employees||[],
        orders=DBx.orders||[], users=DBx.users||[], settings=DBx.settings||{};
  const cust=customers.filter(c=>isCustomerParty(c)), supp=customers.filter(c=>isSupplierParty(c));
  const sum=(arr,f)=>arr.reduce((s,x)=>s+n(f(x)),0);
  const thisMonth=new Date().toISOString().substring(0,7);
  const daysAgo=d=>new Date(Date.now()-d*86400000).toISOString().split('T')[0];
  const hasTx=txns.length>0;

  const salesAll=sum(txns.filter(t=>window.isRevenueTx(t)),txAmt);
  const cogsAll=n(window.computeCOGS(txns));
  const expAll=sum(txns.filter(t=>window.EXPENSE_TX_TYPES.has(t.type)),txAmt);
  const mTxs=txns.filter(t=>t.date&&t.date.startsWith(thisMonth));
  const mSales=sum(mTxs.filter(t=>window.isRevenueTx(t)),txAmt);
  const mCogs=n(window.computeCOGS(mTxs));
  const mExp=sum(mTxs.filter(t=>window.EXPENSE_TX_TYPES.has(t.type)),txAmt);
  const bankTotal=sum(banks,b=>b.bal);
  const recvTotal=sum(cust.filter(c=>n(c.bal)>0),c=>c.bal);
  const payTotal=sum(supp.filter(s=>n(s.bal)>0),s=>s.bal);
  const dbBytes=(()=>{try{return JSON.stringify(DBx).length;}catch(e){return 0;}})();

  // each check: {cat,name,status,detail,fix?:{label,action}}
  const C=[];
  const add=(cat,name,status,detail,fix)=>C.push({cat,name,status,detail,fix});

  // ── Data ──────────────────────────────────────────────────────────────
  add('Data','Database Connectivity','pass','Server dataset loaded (MySQL via api.php) — '+dbBytes.toLocaleString('en-IN')+' bytes in memory');
  add('Data','Transaction Records',hasTx?'pass':'warn',
      hasTx?txns.length.toLocaleString('en-IN')+' transactions loaded':'No transactions yet — add your first transaction',
      hasTx?null:{label:'Add transaction',action:"nav('transactions')"});
  (()=>{const ids=txns.map(t=>t.id),d=ids.length-new Set(ids).size;
    add('Data','Duplicate Transactions',d===0?'pass':'fail',d===0?'No duplicates found':d+' duplicate IDs detected — run Remove Duplicate Records',
        d===0?null:{label:'Remove duplicates',action:'clearDuplicates()'});})();
  (()=>{const neg=banks.filter(b=>n(b.bal)<0);
    add('Data','Negative Bank Balances',neg.length?'warn':'pass',
        neg.length?neg.map(b=>b.name+': '+money(b.bal)).join(', '):'All bank balances are positive',
        neg.length?{label:'Open banks',action:"nav('banks')"}:null);})();

  // ── Config ────────────────────────────────────────────────────────────
  add('Config','Company Settings',settings.companyName?'pass':'warn',
      settings.companyName?'Company: '+settings.companyName:'Company name not set — go to Settings',
      settings.companyName?null:{label:'Open settings',action:"nav('settings')"});
  add('Config','Bank Accounts',banks.length?'pass':'warn',
      banks.length?banks.length+' account(s) — Total: '+money(bankTotal):'No bank accounts configured',
      banks.length?null:{label:'Add bank',action:"nav('banks')"});
  add('Config','Customer Records',cust.length?'pass':'warn',cust.length+' customers, '+supp.length+' suppliers configured',
      cust.length?null:{label:'Add customer',action:"nav('customers')"});
  add('Config','Product Catalog',products.length?'pass':'warn',
      products.length?products.length+' products configured':'No products configured',
      products.length?null:{label:'Add product',action:"nav('products')"});
  (()=>{
    /* FIX: this counted DB.openingBalance, an object nothing ever writes to,
       and so reported "not configured" however many opening balances were
       actually entered. The real stores are DB.openingBalances (parties) and
       each bank's own openingBal. The action also pointed at a screen name
       that does not exist ('openbal'), so the button went nowhere. */
    const parties=(DBx.openingBalances||[]).filter(o=>o&&o.party&&n(o.amount!=null?o.amount:o.amt)).length;
    const banksOB=((DBx.banks)||[]).filter(b=>n(b.openingBal)).length;
    const partsOB=((DBx.partners)||[]).filter(p=>n(p.cap!=null?p.cap:p.capital)).length;
    const legacy=Object.keys(DBx.openingBalance||{}).length;
    const k=parties+banksOB+partsOB+legacy;
    add('Config','Opening Balances',k?'pass':'warn',
        k?(k+' opening balances set — '+parties+' parties, '+banksOB+' bank accounts, '+partsOB+' partners'):'Opening balances not configured',
        k?null:{label:'Set opening balances',action:"nav('openingbalance')"});})();
  add('Config','Sales Tax Settings',settings.salesTaxRate?'pass':'warn',
      settings.salesTaxRate?'Tax rate: '+settings.salesTaxRate+'% ('+(settings.salesTaxEnabled!==false?'Enabled':'Disabled')+')':'Sales tax not configured — go to Settings',
      settings.salesTaxRate?null:{label:'Open settings',action:"nav('settings')"});

  // ── Finance ───────────────────────────────────────────────────────────
  add('Finance','Receivables vs Bank',(bankTotal>0&&recvTotal>bankTotal*3)?'warn':'pass',
      'Receivables: '+money(recvTotal)+' | Bank: '+money(bankTotal));
  add('Finance','Partner Capital',partners.length?'pass':'warn',
      partners.length?partners.length+' partners — Capital: '+money(sum(partners,p=>p.cap)):'No partners configured',
      partners.length?null:{label:'Add partner',action:"nav('partners')"});
  add('Finance','Monthly Profit Check',!mTxs.length?'warn':(mSales-mCogs-mExp>=0?'pass':'warn'),
      !mTxs.length?'No transactions recorded this month yet':
      'This month — Sales: '+money(mSales)+' | COGS: '+money(mCogs)+' | Expenses: '+money(mExp)+' | Net Profit: '+money(mSales-mCogs-mExp));
  (()=>{
    /* FIX (2026-08-25): despite this comment already claiming "canonical
       type sets, not a hard-coded list", the six types below WERE a
       hard-coded list — missing Customer Collection, Bkash Receive,
       Sales Advance, Advance from Customer, Cheque Received, refunds,
       Other Income, Loan Received and every Opening Balance type. Any of
       those landing this month understated Inflow and could tip a
       genuinely healthy cash position into a false "Cash Flow" fail/warn.
       window.AYAN_MONEY_IN (see the shared money-direction block near the
       top of this file) is the actual canonical set — already used by the
       insufficient-balance guard and the bank ledger — so using it here
       too means this can't drift out of sync with those again. */
    const inflow=sum(mTxs.filter(t=>window.AYAN_MONEY_IN&&window.AYAN_MONEY_IN.has(String(t.type||'').toLowerCase())),txAmt);
    const outflow=sum(mTxs.filter(t=>window.isCogsTx(t)||window.EXPENSE_TX_TYPES.has(t.type)),txAmt);
    add('Finance','Cash Flow Status',!mTxs.length?'warn':(inflow>=outflow?'pass':(inflow>outflow*0.7?'warn':'fail')),
        !mTxs.length?'No cash movement recorded this month yet':
        'This month — Inflow: '+money(inflow)+' | Outflow: '+money(outflow)+' | Net: '+money(inflow-outflow));})();
  (()=>{const gm=salesAll>0?(salesAll-cogsAll)/salesAll*100:null;
    add('Finance','Gross Margin Check',gm===null?'warn':(gm>20?'pass':gm>5?'warn':'fail'),
        gm===null?'No sales recorded yet — margin cannot be calculated':
        'Gross Margin: '+gm.toFixed(1)+'% (Sales: '+money(salesAll)+' | COGS: '+money(cogsAll)+')');})();
  (()=>{const pend=(DBx.cheques||[]).filter(c=>c.status==='Pending'||c.status==='Issued');
    add('Finance','Cheque Clearance Status',pend.length===0?'pass':pend.length<5?'warn':'fail',
        pend.length===0?'No pending cheques':pend.length+' cheques pending clearance — total '+money(sum(pend,c=>c.amount||c.amt)),
        /* FIX (2026-08-28, "That section isn't available yet" on click):
           nav('cheques') pointed at a page id that doesn't exist — the real
           page is 'chequemanagement' (see PAGE_ALIASES: cheque ->
           chequemanagement). Same class of bug as the Reports quick-link
           grid fixed earlier via PAGE_ALIASES; this one's a literal string
           here rather than routed through nav(), so it's fixed directly. */
        pend.length?{label:'Open cheques',action:"nav('chequemanagement')"}:null);})();
  add('Finance','VAT Filing Status',settings.vatEnabled?'warn':'pass',
      settings.vatEnabled?'VAT is enabled — ensure the monthly VAT return is filed. Rate: '+(settings.vatRate||15)+'%':'VAT not enabled — enable in Settings if applicable');

  // ── Trial Balance ─────────────────────────────────────────────────────
  (()=>{
    /* FIX (2026-08-25): this used to reimplement the Left/Right math from
       scratch, so it could — and did — quote a different figure from the
       Balance Sheet's Trial Balance whenever that page's own formula was
       fixed (most recently the "Unlinked Bank Opening Balance" fix). Two
       independent copies of the same calculation drifting apart is exactly
       the bug pattern behind most of this app's earlier balance mismatches.
       Calling computePosition() directly — the same function renderBS()
       itself uses — makes this permanently impossible to go out of sync
       with the Balance Sheet again, instead of just "in sync as of today". */
    let P=null;
    try{ P=(typeof window.computePosition==='function')?window.computePosition():null; }catch(e){}
    const left=P?P.totalLeft:0, right=P?P.totalRight:0;
    const diff=left-right, ad=Math.abs(diff);
    // No transactions yet = opening data is simply not reconciled; that is a
    // setup warning, not a system failure.
    const status=!P?'warn':(ad<1?'pass':(!hasTx?'warn':(ad<50000?'warn':'fail')));
    const detail=!P
      ? 'Could not load computePosition() — open Balance Sheet to check manually'
      : ad<1
      ? '✅ Perfectly balanced — Liabilities + Equity '+money(left)+' = Assets '+money(right)
      : (!hasTx?'Opening data not reconciled yet — ':'')+'Difference '+money(ad)+
        ' · Liabilities + Equity: '+money(left)+' | Assets: '+money(right)+
        ' — see Balance Sheet for the full line-by-line breakdown';
    add('Trial Balance','Trial Balance Match',status,detail,(!P||ad>=1)?{label:'Open Balance Sheet',action:"nav('balancesheet')"}:null);
  })();
  (()=>{const cutoff=daysAgo(30);
    const od=txns.filter(t=>window.isRevenueTx(t)&&t.date&&t.date<cutoff&&t.paid!==true&&n(t.due||t.dueAmt)>0);
    add('Trial Balance','Overdue Customer Payments (>30d)',od.length===0?'pass':od.length<5?'warn':'fail',
        od.length===0?'No overdue customer payments':od.length+' sales older than 30 days still unpaid — total '+money(sum(od,t=>t.due||t.dueAmt)),
        od.length?{label:'Customer aging',action:"nav('customeraging')"}:null);})();
  (()=>{const cutoff=daysAgo(60);
    /* FIX: a supplier balance ABOVE zero is money of yours he is still
       holding — an advance, and an asset. This reported those six accounts
       as "payables" and warned about ৳21,57,909 you do not owe anybody,
       while what you actually owe was not mentioned. Both are reported now,
       each under its own name. */
    const advances=supp.filter(s=>n(s.bal)>0);
    const owing=supp.filter(s=>n(s.bal)<0);
    const advTotal=sum(advances,s=>s.bal);
    const oweTotal=Math.abs(sum(owing,s=>s.bal));
    const aged=txns.filter(t=>window.isCogsTx(t)&&t.date&&t.date<cutoff&&t.paid!==true&&n(t.due||t.dueAmt)>0);
    const status=!owing.length?'pass':(aged.length?'fail':'warn');
    add('Trial Balance','Supplier Payables',status,
        !owing.length?('Nothing owed to suppliers'+(advances.length?' · '+advances.length+' holding '+money(advTotal)+' of your money in advance':''))
          :owing.length+' supplier(s) owed '+money(oweTotal)+(advances.length?' · '+advances.length+' holding '+money(advTotal)+' in advance':'')+(aged.length?' · '+aged.length+' purchase(s) unpaid over 60 days':''),
        (owing.length||advances.length)?{label:'Supplier aging',action:"nav('supplieraging')"}:null);})();

  // ── Stock ─────────────────────────────────────────────────────────────
  (()=>{const neg=products.filter(p=>pstock(p)<0);
    add('Stock','Negative Stock Items',neg.length===0?'pass':neg.length<3?'warn':'fail',
        neg.length===0?'No negative stock':neg.length+' products have negative stock: '+neg.slice(0,8).map(p=>p.name).join(', '),
        neg.length?{label:'Open stock',action:"nav('stockmovement')"}:null);})();
  (()=>{ // only stock actually on hand can mis-value the balance sheet
    const held=products.filter(p=>pstock(p)>0);
    const z=held.filter(p=>!pcost(p));
    const noCostAtAll=products.filter(p=>!pcost(p)).length;
    const status=z.length===0?'pass':(z.length<5?'warn':'fail');
    add('Stock','Product Cost Price',status,
        z.length===0
          ? (noCostAtAll?'All stocked products have a cost price ('+noCostAtAll+' zero-stock products still need one)':'All products have cost price set')
          : z.length+' products hold stock without a cost price — stock valuation will be wrong',
        (z.length||noCostAtAll)?{label:'Open products',action:"nav('products')"}:null);})();
  (()=>{ // a reorder level of 0 is "not configured", not a breach
    const tracked=products.filter(p=>pmin(p)>0);
    const low=tracked.filter(p=>pstock(p)<=pmin(p));
    const status=!tracked.length?'warn':(low.length===0?'pass':low.length<3?'warn':'fail');
    add('Stock','Reorder Level / Low Stock',status,
        !tracked.length?'No minimum stock levels configured — low-stock alerts are inactive'
          :low.length===0?'All '+tracked.length+' tracked products are above their reorder level'
          :low.length+' of '+tracked.length+' tracked products at or below reorder level: '+low.slice(0,8).map(p=>p.name).join(', '),
        (!tracked.length||low.length)?{label:'Open inventory',action:"nav('inventory')"}:null);})();

  // ── Data Quality ──────────────────────────────────────────────────────
  (()=>{const bad=txns.filter(t=>!t.party&&!t.customer&&(window.isRevenueTx(t)||window.isCogsTx(t)));
    add('Data Quality','Transactions without Party',bad.length===0?'pass':bad.length<5?'warn':'fail',
        bad.length===0?'All sale/purchase transactions have party names':bad.length+' transactions missing party name',
        bad.length?{label:'Open transactions',action:"nav('transactions')"}:null);})();
  (()=>{const bad=txns.filter(t=>!txAmt(t));
    add('Data Quality','Transactions without Amount',bad.length===0?'pass':bad.length<3?'warn':'fail',
        bad.length===0?'All transactions have amounts':bad.length+' transactions have zero or missing amount',
        bad.length?{label:'Open transactions',action:"nav('transactions')"}:null);})();
  (()=>{const due=(DBx.agentLedger||[]).filter(a=>n(a.bal)>0);
    add('Data Quality','Agent Commission Uncleared',due.length===0?'pass':due.length<3?'warn':'fail',
        due.length===0?'No pending agent commissions':money(sum(due,a=>a.bal))+' commission pending for '+due.length+' agent(s)');})();

  // ── Operations ────────────────────────────────────────────────────────
  (()=>{/* FIX (2026-08-25): was hardcoded to type==='Salary Payment' only, so payroll
       paid via the real Payroll module's 'Staff Salary' type (see the already-fixed
       salaryExpense calc a few hundred lines up, ~line 12135) never counted here —
       a fully-paid payroll could still show as "0 of N employees paid" / fail. */
    const paid=txns.filter(t=>(t.type==='Salary Payment'||t.type==='Staff Salary')&&t.date&&t.date.startsWith(thisMonth));
    const act=employees.filter(e=>(e.status||'Active')==='Active').length;
    add('Operations','Payroll Status (This Month)',act===0?'pass':paid.length>=act?'pass':paid.length>0?'warn':'fail',
        act===0?'No active employees configured':paid.length+' of '+act+' employees paid this month',
        (act&&paid.length<act)?{label:'Open payroll',action:"nav('payroll')"}:null);})();
  (()=>{const today=new Date().toISOString().split('T')[0],soon=new Date(Date.now()+7*86400000).toISOString().split('T')[0];
    const u=(DBx.tenders||[]).filter(t=>t.deadline&&t.deadline>=today&&t.deadline<=soon&&t.status!=='Closed');
    add('Operations','Tender Deadlines Approaching',u.length===0?'pass':u.length<3?'warn':'fail',
        u.length===0?'No tenders due in next 7 days':u.length+' tender(s) due within 7 days: '+u.map(t=>t.name||t.title||'Tender').join(', '),
        u.length?{label:'Open tenders',action:"nav('tenders')"}:null);})();
  (()=>{
    if(!orders.length){ add('Operations','Orders','pass','No orders recorded'); return; }
    const ful=orders.filter(o=>o.deliveryStatus==='Delivered'||o.status==='Completed').length;
    const pend=orders.filter(o=>o.deliveryStatus==='Pending').length;
    const rate=ful/orders.length*100;
    add('Operations','Orders',rate>=80?'pass':rate>=50?'warn':'fail',
        orders.length+' orders — '+ful+' fulfilled ('+Math.round(rate)+'%), '+pend+' pending',
        pend?{label:'Open orders',action:"nav('orders')"}:null);})();
  (()=>{const p=(DBx.pendingApprovals||[]).length;
    add('Operations','Pending Approvals',p===0?'pass':p<5?'warn':'fail',
        p===0?'No pending approvals':p+' items awaiting approval',
        /* FIX (2026-08-28, "That section isn't available yet" on click):
           nav('approvals') pointed at a page id that doesn't exist —
           the actual page is 'pendingapprovals' (see the ✅ Pending
           Approvals nav item / PAGE_ALIASES: pendapprove ->
           pendingapprovals). */
        p?{label:'Review approvals',action:"nav('pendingapprovals')"}:null);})();
  add('Operations','Employee Records',employees.length?'pass':'warn',
      employees.length?employees.length+' employees — '+employees.filter(e=>(e.status||'Active')==='Active').length+' active':'No employees configured',
      /* FIX (2026-08-28, "That section isn't available yet" on click):
         there is no page id 'employees' — Employees is a TAB inside the
         Payroll page (see setPayrollTab()/pr-panel-employees), so this
         has to both open Payroll and switch to that tab, not just nav(). */
      employees.length?null:{label:'Add employee',action:"nav('payroll');setTimeout(function(){if(typeof setPayrollTab==='function')setPayrollTab('employees');if(typeof openAddEmployeeModal==='function')openAddEmployeeModal();},80);"});
  add('Operations','Auto-Save System','pass','Auto-save active — saves every 30 seconds and on every change');

  // ── Security ──────────────────────────────────────────────────────────
  add('Security','Two-Factor Authentication',settings.twoFactorEnabled?'pass':'warn',
      settings.twoFactorEnabled?'2FA is enabled — good security practice':'2FA not enabled — consider enabling in Settings',
      settings.twoFactorEnabled?null:{label:'Open settings',action:"nav('settings')"});
  (()=>{const len=u=>(u.pwLen!=null?u.pwLen:(u.password||'').length);
    const weak=users.filter(u=>len(u)>0&&len(u)<6);
    add('Security','User Password Strength',users.length?(weak.length===0?'pass':'warn'):'pass',
        !users.length?'No user accounts to check':weak.length===0?'All user passwords meet minimum length':weak.length+' user(s) have short passwords',
        weak.length?{label:'User management',action:"nav('users')"}:null);})();
  (()=>{ // role/status casing varies across seeds; no users at all = default login, a warning
    const admins=users.filter(u=>/admin/i.test(u.role||'')&&/^(active|1|true)?$/i.test(String(u.status==null?'active':u.status)));
    const status=!users.length?'warn':(admins.length?'pass':'fail');
    add('Security','Admin Account Status',status,
        !users.length?'No user accounts configured — the built-in default admin login is in use'
          :admins.length?admins.length+' active admin account(s) configured'
          :'No active admin account — system may become inaccessible',
        users.length&&!admins.length?{label:'User management',action:"nav('users')"}:(!users.length?{label:'Create admin user',action:"nav('users')"}:null));})();

  // ── Performance ───────────────────────────────────────────────────────
  add('Performance','Database Size',dbBytes<2000000?'pass':dbBytes<4000000?'warn':'fail',
      'Database size: '+(dbBytes/1024).toFixed(1)+' KB'+(dbBytes>2000000?' — consider archiving old transactions':''),
      dbBytes>2000000?{label:'Optimize database',action:'optimizeDB()'}:null);
  add('Performance','Transaction Volume',txns.length<5000?'pass':txns.length<15000?'warn':'fail',
      txns.length.toLocaleString('en-IN')+' transactions'+(txns.length>10000?' — large dataset, archive old records for better speed':''));
  add('Performance','IndexedDB / Offline Storage',('indexedDB' in window)?'pass':'warn',
      ('indexedDB' in window)?'IndexedDB available — large data can be stored offline':'IndexedDB not available in this browser');
  add('Performance','Mobile Responsive UI','pass','Responsive layouts, touch-friendly controls and scrollable tables are active on all pages');

  // ── Technology ────────────────────────────────────────────────────────
  add('Technology','PWA Install Ready',('serviceWorker' in navigator)?'pass':'warn',
      ('serviceWorker' in navigator)?'PWA ready — app can be installed on mobile/desktop':'Service Worker not supported in this browser');
  add('Technology','Offline Mode Support','pass','All data is stored locally — the system works fully offline');
  add('Technology','Dark Mode Support','pass','Dark mode toggle available with system-preference detection');
  add('Technology','Print & PDF Export','pass','Print-ready layouts for invoices, challans, receipts, vouchers, balance sheet and VAT reports');
  (()=>{ // one backup check instead of two contradicting ones
    const ls=localStorage.getItem('ayan_last_backup');
    const when=ls?new Date(parseInt(ls,10)):(DBx.lastBackup?new Date(DBx.lastBackup):null);
    const ok=when&&!isNaN(when)&&(Date.now()-when.getTime())<7*86400000;
    add('Technology','Data Backup',when&&!isNaN(when)?(ok?'pass':'warn'):'warn',
        when&&!isNaN(when)?'Last backup: '+when.toLocaleString('en-GB')+(ok?'':' — older than 7 days, take a fresh backup'):'No backup recorded — export a full backup now',
        ok?null:{label:'Backup now',action:'exportFullBackup()'});})();

  // ── Scoring: warnings count half, not zero ────────────────────────────
  const passed=C.filter(c=>c.status==='pass').length;
  const warned=C.filter(c=>c.status==='warn').length;
  const failed=C.filter(c=>c.status==='fail').length;
  const score=Math.round((passed+warned*0.5)/C.length*100);
  const scoreLabel=score>=90?'Excellent 🌟':score>=75?'Good 👍':score>=50?'Fair ⚠️':'Needs Attention 🚨';
  const took=Math.max(1,Math.round(((window.performance&&performance.now)?performance.now():Date.now())-t0));

  const isDark=document.documentElement.getAttribute('data-theme')==='dark';
  const bg=isDark?'#1e293b':'#fff', border=isDark?'#334155':'#e5e7eb',
        textColor=isDark?'#f1f5f9':'#1a202c', text2=isDark?'#94a3b8':'#6b7280';
  const CAT={'Data':['🗄️','#1d4ed8'],'Config':['⚙️','#7c3aed'],'Finance':['💰','#16a34a'],
             'Trial Balance':['⚖️','#0f766e'],'Stock':['📦','#b45309'],'Data Quality':['🔍','#be185d'],
             'Operations':['🏭','#d97706'],'Security':['🔐','#b91c1c'],'Performance':['⚡','#4338ca'],
             'Technology':['🚀','#0284c7']};
  const cats=[...new Set(C.map(c=>c.cat))];
  const attention=C.filter(c=>c.status!=='pass');
  const row=c=>{
    const icon=c.status==='pass'?'✅':c.status==='warn'?'⚠️':'❌';
    const color=c.status==='pass'?'#16a34a':c.status==='warn'?'#d97706':'#dc2626';
    const cbg=c.status==='pass'?(isDark?'#0f2a1a':'#f0fdf4'):c.status==='warn'?(isDark?'#2b2410':'#fffbeb'):(isDark?'#2c1414':'#fef2f2');
    return `<div style="display:flex;align-items:flex-start;gap:10px;padding:10px 12px;border-radius:8px;margin-bottom:4px;background:${cbg};">
      <span style="font-size:16px;flex-shrink:0;margin-top:1px;">${icon}</span>
      <div style="flex:1;min-width:0;">
        <div style="font-size:12px;font-weight:700;color:${textColor};">${esc(c.name)}</div>
        <div style="font-size:11px;color:${text2};margin-top:2px;word-break:break-word;">${esc(c.detail)}</div>
      </div>
      ${c.fix?`<button data-x-click="${esc(c.fix.action)}" style="flex-shrink:0;font-size:10px;font-weight:800;padding:4px 10px;border-radius:6px;border:1px solid ${color};background:transparent;color:${color};cursor:pointer;">${esc(c.fix.label)}</button>`:''}
      <span style="font-size:10px;font-weight:800;color:${color};text-transform:uppercase;flex-shrink:0;padding:2px 8px;border-radius:6px;background:${color}22;">${c.status}</span>
    </div>`;
  };

  body.innerHTML=`
    <div style="background:linear-gradient(135deg,#0f3d26,#16a34a);color:#fff;border-radius:14px;padding:24px;margin-bottom:20px;display:flex;align-items:center;gap:24px;flex-wrap:wrap;">
      <div style="text-align:center;min-width:140px;">
        <div style="font-size:56px;font-weight:900;line-height:1;">${score}</div>
        <div style="font-size:14px;opacity:.8;margin-top:2px;">/ 100</div>
        <div style="font-size:13px;font-weight:700;margin-top:6px;">${scoreLabel}</div>
        <div style="background:rgba(255,255,255,.2);border-radius:8px;height:8px;margin-top:10px;overflow:hidden;">
          <div style="width:${score}%;height:100%;background:#4ade80;border-radius:8px;transition:width .8s ease;"></div>
        </div>
      </div>
      <div style="flex:1;min-width:200px;">
        <div style="font-size:18px;font-weight:800;margin-bottom:8px;">System Health Report</div>
        <div style="font-size:12px;opacity:.8;margin-bottom:14px;">Generated: ${new Date().toLocaleString('en-GB')} · ${took} ms</div>
        <div style="display:flex;gap:12px;flex-wrap:wrap;">
          <div style="background:rgba(255,255,255,.15);border-radius:10px;padding:10px 16px;text-align:center;">
            <div style="font-size:22px;font-weight:900;color:#4ade80;">${passed}</div><div style="font-size:10px;opacity:.8;">PASSED</div></div>
          <div style="background:rgba(255,255,255,.15);border-radius:10px;padding:10px 16px;text-align:center;">
            <div style="font-size:22px;font-weight:900;color:#fbbf24;">${warned}</div><div style="font-size:10px;opacity:.8;">WARNINGS</div></div>
          <div style="background:rgba(255,255,255,.15);border-radius:10px;padding:10px 16px;text-align:center;">
            <div style="font-size:22px;font-weight:900;color:#f87171;">${failed}</div><div style="font-size:10px;opacity:.8;">FAILED</div></div>
          <div style="background:rgba(255,255,255,.15);border-radius:10px;padding:10px 16px;text-align:center;">
            <div style="font-size:22px;font-weight:900;">${C.length}</div><div style="font-size:10px;opacity:.8;">TOTAL CHECKS</div></div>
        </div>
      </div>
      <div style="display:flex;flex-direction:column;gap:8px;">
        <button data-x-click="renderHealthCheck()" style="padding:10px 18px;background:rgba(255,255,255,.2);color:#fff;border:1.5px solid rgba(255,255,255,.4);border-radius:8px;font-weight:700;cursor:pointer;font-size:13px;">🔄 Re-run</button>
        <button data-x-click="window.print()" style="padding:10px 18px;background:rgba(255,255,255,.2);color:#fff;border:1.5px solid rgba(255,255,255,.4);border-radius:8px;font-weight:700;cursor:pointer;font-size:13px;">🖨️ Print</button>
      </div>
    </div>

    ${attention.length?`<div style="background:${bg};border:1px solid ${border};border-radius:12px;overflow:hidden;margin-bottom:14px;">
      <div style="background:#b91c1c;color:#fff;padding:10px 16px;font-size:13px;font-weight:800;">🚨 Needs Attention (${attention.length})</div>
      <div style="padding:8px;">${attention.map(row).join('')}</div>
    </div>`:`<div style="background:#f0fdf4;border:1px solid #16a34a;color:#166534;border-radius:12px;padding:14px 16px;margin-bottom:14px;font-size:13px;font-weight:700;">✅ All ${C.length} checks passed — no action required.</div>`}

    ${cats.map(cat=>{
      const meta=CAT[cat]||['🏭','#d97706'];
      const items=C.filter(c=>c.cat===cat);
      const bad=items.filter(c=>c.status!=='pass').length;
      return `<div style="background:${bg};border:1px solid ${border};border-radius:12px;overflow:hidden;margin-bottom:14px;">
        <div style="background:${meta[1]};color:#fff;padding:10px 16px;font-size:13px;font-weight:800;display:flex;justify-content:space-between;">
          <span>${meta[0]} ${esc(cat)} Checks</span>
          <span style="opacity:.85;font-weight:700;">${items.length-bad}/${items.length} ok</span>
        </div>
        <div style="padding:8px;">${items.map(row).join('')}</div>
      </div>`;}).join('')}

    <div style="background:${bg};border:1px solid ${border};border-radius:12px;padding:18px;margin-bottom:14px;">
      <div style="font-size:14px;font-weight:800;color:#16a34a;margin-bottom:14px;">🔧 Optimization Tools</div>
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:10px;">
        <button data-x-click="optimizeDB()" style="padding:10px 16px;background:#f0fdf4;border:1px solid #16a34a;color:#16a34a;border-radius:7px;font-size:12px;font-weight:700;cursor:pointer;text-align:left;">🗜️ Compress &amp; Optimize Database</button>
        <button data-x-click="clearDuplicates()" style="padding:10px 16px;background:#fffbeb;border:1px solid #f59e0b;color:#b45309;border-radius:7px;font-size:12px;font-weight:700;cursor:pointer;text-align:left;">🧹 Remove Duplicate Records</button>
        <button data-x-click="clearOldAuditLog()" style="padding:10px 16px;background:#eff6ff;border:1px solid #2563eb;color:#2563eb;border-radius:7px;font-size:12px;font-weight:700;cursor:pointer;text-align:left;">📋 Clear Old Audit Logs (&gt;90 days)</button>
        <button data-x-click="exportFullBackup()" style="padding:10px 16px;background:#f5f3ff;border:1px solid #7c3aed;color:#7c3aed;border-radius:7px;font-size:12px;font-weight:700;cursor:pointer;text-align:left;">💾 Export Full System Backup</button>
      </div>
    </div>

    <div style="background:${bg};border:1px solid ${border};border-radius:12px;padding:18px;">
      <div style="font-size:14px;font-weight:800;color:#16a34a;margin-bottom:14px;">💡 Recommendations</div>
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:10px;">
        ${[
          {icon:'💾',text:'Backup your data regularly — use Backup & Restore',action:"nav('googledrivebackup')"},
          {icon:'🏦',text:'Set opening balances for accurate financial reports',action:"nav('openbal')"},
          {icon:'👥',text:'Keep customer and supplier records up to date',action:"nav('customers')"},
          {icon:'📦',text:'Set minimum stock levels for low stock alerts',action:"nav('inventory')"},
          {icon:'🏢',text:'Configure company settings for professional invoices',action:"nav('settings')"},
          {icon:'📅',text:'Review aging reports weekly to manage cash flow',action:"nav('customeraging')"},
        ].map(r=>`<div style="display:flex;gap:10px;align-items:flex-start;padding:10px 12px;background:#f0fdf4;border-radius:8px;cursor:pointer;" data-x-click="${r.action}" data-hover-bg="#dcfce7">
          <span style="font-size:18px;flex-shrink:0;">${r.icon}</span>
          <span style="font-size:11px;color:#374151;font-weight:600;">${r.text}</span>
          <span style="margin-left:auto;color:#16a34a;font-size:12px;">→</span>
        </div>`).join('')}
      </div>
    </div>

    <div id="hc-syserrors-wrap" style="background:${bg};border:1px solid ${border};border-radius:12px;overflow:hidden;margin-top:14px;">
      <div style="background:#1f2937;color:#fff;padding:10px 16px;font-size:13px;font-weight:800;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;">
        <span>🖥️ System Errors — live monitor (all users, all devices)</span>
        <span style="display:flex;gap:8px;">
          <button data-x-click="resolveAllSystemErrors()" style="font-size:10px;font-weight:800;padding:4px 10px;border-radius:6px;border:1px solid rgba(255,255,255,.5);background:transparent;color:#fff;cursor:pointer;">✔ Mark all resolved</button>
          <button data-x-click="loadSystemErrorPanel()" style="font-size:10px;font-weight:800;padding:4px 10px;border-radius:6px;border:1px solid rgba(255,255,255,.5);background:transparent;color:#fff;cursor:pointer;">🔄 Refresh</button>
        </span>
      </div>
      <div id="hc-syserrors" style="padding:12px;font-size:12px;color:${text2};">Checking for JavaScript errors reported by the app…</div>
    </div>`;
  window.__lastHealthCheck={score,passed,warned,failed,total:C.length,at:new Date().toISOString(),checks:C.map(c=>({cat:c.cat,name:c.name,status:c.status,detail:c.detail}))};
  if(typeof loadSystemErrorPanel==='function') loadSystemErrorPanel();
}

/* System Errors panel (2026-08-28, health monitor — localStorage removed 2026-09-05):
   Pulls from two sources:
     1. error_log.php (server-side, aggregates every user's browser — durable).
     2. window.__erpErrors in-memory ring buffer (this tab only, this session).
   localStorage is no longer used here: the shim made it volatile and it added
   no value over the ring buffer that already existed in memory. */
async function loadSystemErrorPanel(){
  const box=document.getElementById('hc-syserrors');
  if(!box) return;
  const esc=s=>String(s==null?'':s).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
  const isDark=document.documentElement.getAttribute('data-theme')==='dark';
  let serverRows=null, serverErr=null;
  try{
    const base=(window.ERP_CONFIG&&window.ERP_CONFIG.API_URL)?window.ERP_CONFIG.API_URL:'api.php';
    const url=String(base).replace(/api\.php.*$/i,'')+'error_log.php?action=list&unresolved=1&limit=50';
    const res=await fetch(url,{credentials:'include'});
    const out=await res.json();
    if(out&&out.success) serverRows=out.data||[];
    else serverErr=(out&&out.error)||'Server did not return a valid response.';
  }catch(e){ serverErr='error_log.php not reachable yet — upload it next to api.php on the server to enable cross-device monitoring.'; }

  /* PATCH 2026-09-05: read from window.__erpErrors ring buffer instead of localStorage */
  const localRows = Array.isArray(window.__erpErrors)
    ? window.__erpErrors.slice().reverse().slice(0, 20)
    : [];

  const rowHtml=(msg,src,who,when)=>`<div style="display:flex;gap:10px;align-items:flex-start;padding:8px 10px;border-radius:7px;margin-bottom:4px;background:${isDark?'#2c1414':'#fef2f2'};">
      <span style="font-size:14px;flex-shrink:0;">⚠️</span>
      <div style="flex:1;min-width:0;">
        <div style="font-size:11.5px;font-weight:700;color:${isDark?'#f1f5f9':'#1a202c'};word-break:break-word;">${esc(msg)}</div>
        <div style="font-size:10.5px;color:${isDark?'#94a3b8':'#6b7280'};margin-top:2px;">${esc(src||'')}${who?' · '+esc(who):''}${when?' · '+esc(when):''}</div>
      </div>
    </div>`;

  let html='';
  if(serverRows){
    html+=`<div style="font-size:11px;font-weight:800;color:${isDark?'#94a3b8':'#6b7280'};margin-bottom:6px;text-transform:uppercase;">Reported from the server (${serverRows.length} unresolved)</div>`;
    html+= serverRows.length
      ? serverRows.map(r=>rowHtml(r.message, r.source, r.userLabel, r.createdAt)).join('')
      : `<div style="padding:10px;color:#16a34a;font-weight:700;font-size:12px;">✅ No unresolved errors reported by any user or device.</div>`;
  } else {
    html+=`<div style="padding:10px 0;color:${isDark?'#94a3b8':'#6b7280'};font-size:11.5px;">${esc(serverErr||'')}</div>`;
  }
  if(localRows.length){
    html+=`<div style="font-size:11px;font-weight:800;color:${isDark?'#94a3b8':'#6b7280'};margin:10px 0 6px;text-transform:uppercase;">This session only (last ${localRows.length})</div>`;
    html+=localRows.map(r=>rowHtml(r.msg, r.src, '', r.t)).join('');
  }
  box.innerHTML=html || `<div style="padding:10px;color:#16a34a;font-weight:700;font-size:12px;">✅ No JavaScript errors recorded.</div>`;
}

async function resolveAllSystemErrors(){
  try{
    const base=(window.ERP_CONFIG&&window.ERP_CONFIG.API_URL)?window.ERP_CONFIG.API_URL:'api.php';
    const url=String(base).replace(/api\.php.*$/i,'')+'error_log.php?action=resolve';
    await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:'{}',credentials:'include'});
  }catch(e){}
  try{ localStorage.removeItem('ayan_error_log'); }catch(e){}
  if(typeof toast==='function') toast('System error log cleared.','s');
  loadSystemErrorPanel();
  if(typeof updateHealthCheckBadge==='function') updateHealthCheckBadge();
}

/* Sidebar badge: shows a red dot on the Health Check nav item whenever there
   are unresolved system errors, so a problem is visible without anyone
   having to open the page — checked once on load and then periodically. */
async function updateHealthCheckBadge(){
  try{
    const navItem=document.querySelector(".nav-item[onclick*=\"nav('healthcheck')\"]");
    if(!navItem) return;
    let count=0;
    try{
      const base=(window.ERP_CONFIG&&window.ERP_CONFIG.API_URL)?window.ERP_CONFIG.API_URL:'api.php';
      const url=String(base).replace(/api\.php.*$/i,'')+'error_log.php?action=list&unresolved=1&limit=1';
      const res=await fetch(url,{credentials:'include'});
      const out=await res.json();
      if(out&&out.success) count=out.unresolvedCount||0;
    }catch(e){
      try{ count=JSON.parse(localStorage.getItem('ayan_error_log')||'[]').length; }catch(e2){}
    }
    let dot=navItem.querySelector('.hc-err-badge');
    if(count>0){
      if(!dot){
        dot=document.createElement('span');
        dot.className='hc-err-badge';
        dot.style.cssText='position:absolute;top:6px;right:10px;background:#dc2626;color:#fff;border-radius:9px;min-width:16px;height:16px;font-size:9px;font-weight:800;display:flex;align-items:center;justify-content:center;padding:0 3px;';
        navItem.style.position='relative';
        navItem.appendChild(dot);
      }
      dot.textContent=count>99?'99+':String(count);
    } else if(dot){ dot.remove(); }
  }catch(e){}
}
(function(){
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',()=>setTimeout(updateHealthCheckBadge,3000));
  else setTimeout(updateHealthCheckBadge,3000);
  setInterval(updateHealthCheckBadge, 10*60*1000); // re-check every 10 minutes
})();


