// BATCH Q: TENDERS, IMPORT/EXPORT, BULK, TRASH BIN
// ══════════════════════════════════════════════════════════════

// ── Tenders ───────────────────────────────────────────────────
function openAddTenderModal(){
  document.getElementById('td-submit').value=new Date().toISOString().split('T')[0];
  document.getElementById('tender-modal').style.display='flex';
}

function saveTender(){
  const m=document.getElementById('tender-modal');
  const editId=m&&m._editId;
  const td={
    id:editId||Date.now(),
    title:document.getElementById('td-title')?.value||'',
    no:document.getElementById('td-no')?.value||'',
    org:document.getElementById('td-org')?.value||'',
    value:parseFloat(document.getElementById('td-value')?.value||0),
    security:parseFloat(document.getElementById('td-security')?.value||0),
    submitDate:document.getElementById('td-submit')?.value||'',
    openDate:document.getElementById('td-open')?.value||'',
    status:document.getElementById('td-status')?.value||'Preparing',
    product:document.getElementById('td-product')?.value||'',
    notes:document.getElementById('td-notes')?.value||'',
    createdAt:new Date().toISOString()
  };
  if(!td.title){alert('Tender title is required.');return;}
  if(!DB.tenders) DB.tenders=[];
  if(editId){
    const idx=DB.tenders.findIndex(t=>t.id===editId);
    if(idx>-1){ td.createdAt=DB.tenders[idx].createdAt||td.createdAt; DB.tenders[idx]=td; }
    else DB.tenders.unshift(td);
  } else {
    DB.tenders.unshift(td);
  }
  saveDB();
  if(typeof addAuditEntry==='function') addAuditEntry(editId?'UPDATE':'CREATE','Tenders',(editId?'Updated tender: ':'Added tender: ')+td.title);
  if(m) m._editId=null;
  document.getElementById('tender-modal').style.display='none';
  renderTenders();
  alert(editId?'✅ Tender updated!':'✅ Tender saved!');
}

async function deleteTender(id){
  if(!await __confirm('Delete this tender?')) return;
  const td=(DB.tenders||[]).find(t=>t.id===id);
  if(!DB.trash) DB.trash=[];
  if(td) DB.trash.unshift({...td,_deletedAt:new Date().toISOString(),_type:'tender'});
  DB.tenders=(DB.tenders||[]).filter(t=>t.id!==id);
  saveDB();
  renderTenders();
}

function updateTenderStatus(id,status){
  const td=(DB.tenders||[]).find(t=>t.id===id);
  if(td){td.status=status;saveDB();renderTenders();}
}

function renderTenders(){
  const tenders=DB.tenders||[];
  const won=tenders.filter(t=>t.status==='Won');
  const active=tenders.filter(t=>!['Won','Lost','Cancelled'].includes(t.status));
  const totalValue=tenders.reduce((s,t)=>s+t.value,0);
  const wonValue=won.reduce((s,t)=>s+t.value,0);

  const cards=document.getElementById('tender-cards');
  if(cards) cards.innerHTML=[
    {label:'Total Tenders',val:tenders.length,icon:'📋',color:'#2563eb'},
    {label:'Active',val:active.length,icon:'🔄',color:'#f59e0b'},
    {label:'Won',val:won.length,icon:'🏆',color:'#16a34a'},
    {label:'Won Value',val:'৳'+pf(wonValue),icon:'💰',color:'#7c3aed'}
  ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
    <div style="font-size:22px;">${c.icon}</div>
    <div style="font-size:${typeof c.val==='string'&&c.val.length>8?'13':'17'}px;font-weight:900;color:${c.color};">${c.val}</div>
    <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)}</div>
  </div>`).join('');

  const body=document.getElementById('tender-body');
  if(!body) return;
  if(!tenders.length){body.innerHTML='<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:40px;text-align:center;color:#9ca3af;">No tenders added yet. Click "New Tender" to get started.</div>';return;}

  const statusColors={Preparing:'#6b7280',Submitted:'#2563eb','Under Review':'#f59e0b',Won:'#16a34a',Lost:'#dc2626',Cancelled:'#9ca3af'};
  body.innerHTML=`<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
    <div style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;padding:12px 16px;font-weight:700;font-size:13px;">📋 All Tenders</div>
    <table style="width:100%;border-collapse:collapse;font-size:12px;">
      <thead><tr style="background:#f0fdf4;">
        <th style="padding:9px 12px;text-align:left;color:#0f3d26;">Tender No</th>
        <th style="padding:9px 12px;text-align:left;color:#0f3d26;">Title</th>
        <th style="padding:9px 12px;text-align:left;color:#0f3d26;">Organization</th>
        <th style="padding:9px 12px;text-align:right;color:#0f3d26;">Value (৳)</th>
        <th style="padding:9px 12px;text-align:right;color:#0f3d26;">Security (৳)</th>
        <th style="padding:9px 12px;text-align:left;color:#0f3d26;">Submit Date</th>
        <th style="padding:9px 12px;text-align:left;color:#0f3d26;">Status</th>
        <th style="padding:9px 12px;text-align:center;color:#0f3d26;">Action</th>
      </tr></thead>
      <tbody>${tenders.map((td,i)=>{
        const color=statusColors[td.status]||'#6b7280';
        return `<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
          <td style="padding:8px 12px;font-family:monospace;color:#6b7280;">${td.no||'—'}</td>
          <td style="padding:8px 12px;font-weight:700;">${td.title}</td>
          <td style="padding:8px 12px;color:#6b7280;">${td.org||'—'}</td>
          <td style="padding:8px 12px;text-align:right;font-weight:700;color:#0f3d26;">৳${pf(td.value)}</td>
          <td style="padding:8px 12px;text-align:right;color:#dc2626;">${td.security>0?'৳'+pf(td.security):'—'}</td>
          <td style="padding:8px 12px;color:#6b7280;">${td.submitDate||'—'}</td>
          <td style="padding:8px 12px;">
            <select data-x-change="updateTenderStatus(${td.id},this.value)" style="padding:3px 6px;border:1px solid ${color}44;border-radius:5px;font-size:10px;font-weight:700;color:${color};background:${color}11;">
              ${['Preparing','Submitted','Under Review','Won','Lost','Cancelled'].map(s=>`<option value="${s}" ${td.status===s?'selected':''}>${s}</option>`).join('')}
            </select>
          </td>
          <td style="padding:8px 12px;text-align:center;">
            <button data-x-click="deleteTender(${td.id})" style="background:#fee2e2;color:#dc2626;border:none;border-radius:5px;padding:3px 8px;font-size:10px;cursor:pointer;">🗑️</button>
          </td>
        </tr>`;
      }).join('')}</tbody>
    </table>
  </div>`;

  // Also keep the Tender Management page (pg-tendermanagement) in sync — it has its
  // own KPI cards (td-total-*) and table (tender-tbody) that nothing else fills.
  // Note: Advance/Cost/Refund/Net P&L aren't shown as figures because the Add Tender
  // form (saveTender()) doesn't currently capture that data — only Value/Security are saved.
  const tc=document.getElementById('td-total-count'); if(tc) tc.textContent=tenders.length;
  const tv=document.getElementById('td-total-value'); if(tv) tv.textContent='৳'+pf(totalValue);
  const ta=document.getElementById('td-total-advance'); if(ta) ta.textContent='—';
  const tCost=document.getElementById('td-total-cost'); if(tCost) tCost.textContent='—';
  const tNet=document.getElementById('td-net-profit'); if(tNet) tNet.textContent='—';

  const tbody=document.getElementById('tender-tbody');
  if(tbody){
    if(!tenders.length){
      tbody.innerHTML='<tr><td colspan="10" style="text-align:center;padding:30px;color:#9ca3af;">No tenders yet. Click ➕ New Tender to add one.</td></tr>';
    } else {
      tbody.innerHTML=tenders.map(td=>{
        const color=statusColors[td.status]||'#6b7280';
        return `<tr style="border-bottom:1px solid #f3f4f6;">
          <td style="padding:8px 12px;font-family:monospace;color:#6b7280;">${td.no||'—'}</td>
          <td style="padding:8px 12px;font-weight:700;">${escHTML(td.title)}${td.org?' <span style=\"color:#9ca3af;font-weight:400;\">— '+td.org+'</span>':''}</td>
          <td style="padding:8px 12px;color:#6b7280;">${escHTML(td.product ||'—')}</td>
          <td style="padding:8px 12px;text-align:right;font-weight:700;color:#0f3d26;">৳${pf(td.value)}</td>
          <td style="padding:8px 12px;text-align:right;color:#6b7280;">—</td>
          <td style="padding:8px 12px;text-align:right;color:#6b7280;">—</td>
          <td style="padding:8px 12px;text-align:right;color:#6b7280;">—</td>
          <td style="padding:8px 12px;text-align:right;color:#6b7280;">—</td>
          <td style="padding:8px 12px;text-align:center;"><span style="padding:3px 8px;border-radius:5px;font-size:10px;font-weight:700;color:${color};background:${color}11;">${td.status}</span></td>
          <td style="padding:8px 12px;text-align:center;">
            <button data-x-click="openTenderModal(${td.id})" style="background:#eff6ff;color:#2563eb;border:none;border-radius:5px;padding:3px 8px;font-size:10px;cursor:pointer;margin-right:4px;">✏️</button>
            <button data-x-click="deleteTender(${td.id})" style="background:#fee2e2;color:#dc2626;border:none;border-radius:5px;padding:3px 8px;font-size:10px;cursor:pointer;">🗑️</button>
          </td>
        </tr>`;
      }).join('');
    }
  }
}

// ── Tender Management ──────────────────────────────────────────
function renderTenderManagement(){
  // Auto-inject page structure if needed
  (function(){
    const _pg=document.getElementById('pg-tendermanagement');
    if(_pg&&!_pg.querySelector('[id]')){
      _pg.innerHTML=`<div style="padding:20px;"><h2 style="font-size:18px;font-weight:800;color:#0f3d26;margin:0 0 16px;">📋 Tender Management</h2><div id=\"tm-cards\" style=\"display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:12px;margin-bottom:16px;\"></div><div id=\"tm-body\" style=\"background:#fff;border-radius:12px;padding:16px;border:1px solid #e5e7eb;\"></div></div>`;
    }
  })();
  const body=document.getElementById('tm-body');
