  const tenders=DB.tenders||[];

  // Tender-related transactions
  const tenderTxns=(DB.tx||[]).filter(t=>['Tender Payment','Tender Advance','Tender Cost','Tender Refund'].includes(t.type));
  const totalPaid=tenderTxns.filter(t=>t.type==='Tender Payment').reduce((s,t)=>s+txAmt(t),0);
  const totalAdvance=tenderTxns.filter(t=>t.type==='Tender Advance').reduce((s,t)=>s+txAmt(t),0);
  const totalCost=tenderTxns.filter(t=>t.type==='Tender Cost').reduce((s,t)=>s+txAmt(t),0);
  const totalRefund=tenderTxns.filter(t=>t.type==='Tender Refund').reduce((s,t)=>s+txAmt(t),0);

  body.innerHTML=`<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:16px;">
    ${[
      {label:'Tender Payments',val:'৳'+pf(totalPaid),icon:'💸',color:'#dc2626'},
      {label:'Advances Paid',val:'৳'+pf(totalAdvance),icon:'⬆️',color:'#f59e0b'},
      {label:'Tender Costs',val:'৳'+pf(totalCost),icon:'📊',color:'#7c3aed'},
      {label:'Refunds Received',val:'৳'+pf(totalRefund),icon:'↩️',color:'#16a34a'}
    ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
      <div style="font-size:22px;">${c.icon}</div>
      <div style="font-size:14px;font-weight:900;color:${c.color};">${c.val}</div>
      <div style="font-size:11px;color:#6b7280;margin-top:4px;">${c.label}</div>
    </div>`).join('')}
  </div>
  <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;">
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
      <div style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;padding:12px 16px;font-weight:700;font-size:13px;">📋 Tender Pipeline</div>
      <div style="padding:12px;">
        ${['Preparing','Submitted','Under Review','Won','Lost'].map(status=>{
          const count=tenders.filter(t=>t.status===status).length;
          const val=tenders.filter(t=>t.status===status).reduce((s,t)=>s+t.value,0);
          const colors={Preparing:'#6b7280',Submitted:'#2563eb','Under Review':'#f59e0b',Won:'#16a34a',Lost:'#dc2626'};
          const color=colors[status]||'#6b7280';
          return `<div style="display:flex;justify-content:space-between;align-items:center;padding:8px 10px;border-radius:7px;margin-bottom:6px;background:${color}11;border:1px solid ${color}22;">
            <div style="font-weight:700;font-size:12px;color:${color};">${status}</div>
            <div style="text-align:right;">
              <div style="font-size:11px;font-weight:700;color:${color};">${count} tender${count!==1?'s':''}</div>
              <div style="font-size:10px;color:#6b7280;">৳${pf(val)}</div>
            </div>
          </div>`;
        }).join('')}
      </div>
    </div>
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
      <div style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;padding:12px 16px;font-weight:700;font-size:13px;">💰 Tender Transactions</div>
      ${tenderTxns.length?`<table style="width:100%;border-collapse:collapse;font-size:11px;">
        <thead><tr style="background:#f0fdf4;">
          <th style="padding:7px 10px;text-align:left;color:#0f3d26;">Date</th>
          <th style="padding:7px 10px;text-align:left;color:#0f3d26;">Type</th>
          <th style="padding:7px 10px;text-align:left;color:#0f3d26;">Party</th>
          <th style="padding:7px 10px;text-align:right;color:#0f3d26;">Amount (৳)</th>
        </tr></thead>
        <tbody>${tenderTxns.slice(0,15).map((t,i)=>`<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
          <td style="padding:6px 10px;color:#6b7280;">${t.date}</td>
          <td style="padding:6px 10px;font-weight:600;">${t.type}</td>
          <td style="padding:6px 10px;">${escHTML(t.party ||'—')}</td>
          <td style="padding:6px 10px;text-align:right;font-weight:700;color:#0f3d26;">৳${pf(txAmt(t))}</td>
        </tr>`).join('')}</tbody>
      </table>`:'<div style="padding:30px;text-align:center;color:#9ca3af;">No tender transactions yet.</div>'}
    </div>
  </div>`;
}

// ── Tender Tracking ────────────────────────────────────────────
function renderTenderTracking(){
  // Auto-inject page structure if needed
  (function(){
    const _pg=document.getElementById('pg-tendertracking');
    if(_pg&&!_pg.querySelector('[id]')){
      _pg.innerHTML=`<div style="padding:20px;"><h2 style="font-size:18px;font-weight:800;color:#0f3d26;margin:0 0 16px;">📊 Tender Tracking</h2><div id=\"tt-cards\" style=\"display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:12px;margin-bottom:16px;\"></div><div id=\"tt-body\" style=\"background:#fff;border-radius:12px;padding:16px;border:1px solid #e5e7eb;\"></div></div>`;
    }
  })();
  const body=document.getElementById('tt-body');
  if(!body) return;
  const tenders=DB.tenders||[];
  if(!tenders.length){body.innerHTML='<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:40px;text-align:center;color:#9ca3af;">No tenders to track. Add tenders from the Tenders page.</div>';return;}

  const stages=['Preparing','Submitted','Under Review','Won'];
  body.innerHTML=`<div style="display:flex;flex-direction:column;gap:12px;">
    ${tenders.map(td=>{
      const stageIdx=stages.indexOf(td.status);
      const isLost=['Lost','Cancelled'].includes(td.status);
      return `<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:16px;">
        <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:12px;">
          <div>
            <div style="font-weight:800;font-size:14px;color:#0f3d26;">${td.title}</div>
            <div style="font-size:11px;color:#6b7280;">${td.org||''} ${td.no?'| Ref: '+td.no:''}</div>
          </div>
          <div style="text-align:right;">
            <div style="font-size:16px;font-weight:900;color:#0f3d26;">৳${pf(td.value)}</div>
            <div style="font-size:10px;color:#6b7280;">Submit: ${td.submitDate||'—'}</div>
          </div>
        </div>
        ${isLost?`<div style="background:#fee2e2;border:1px solid #fca5a5;border-radius:6px;padding:8px 12px;font-size:12px;font-weight:700;color:#dc2626;text-align:center;">${td.status==='Lost'?'❌ Tender Lost':'🚫 Cancelled'}</div>`:`<div style="display:flex;gap:0;">
          ${stages.map((s,i)=>{
            const done=stageIdx>=i;
            const current=stageIdx===i;
            return `<div style="flex:1;text-align:center;position:relative;">
              <div style="width:28px;height:28px;border-radius:50%;background:${done?'#16a34a':'#e5e7eb'};color:${done?'#fff':'#9ca3af'};display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;margin:0 auto;border:2px solid ${current?'#0f3d26':done?'#16a34a':'#e5e7eb'};">${done?'✓':(i+1)}</div>
              <div style="font-size:9px;color:${done?'#16a34a':'#9ca3af'};margin-top:4px;font-weight:${current?'700':'400'};">${s}</div>
              ${i<stages.length-1?`<div style="position:absolute;top:14px;left:50%;width:100%;height:2px;background:${stageIdx>i?'#16a34a':'#e5e7eb'};z-index:0;"></div>`:''}
            </div>`;
          }).join('')}
        </div>`}
      </div>`;
    }).join('')}
  </div>`;
}

