let csvData=[];
function previewCSV(input){
  const file=input.files[0];
  if(!file) return;
  const reader=new FileReader();
  reader.onload=function(e){
    const lines=e.target.result.split('\n').filter(l=>l.trim());
    csvData=lines.slice(1).map(line=>{
      const cols=line.split(',').map(c=>c.trim().replace(/^"|"$/g,''));
      return {date:cols[0],type:cols[1],party:cols[2],partyType:cols[3],amount:parseFloat(cols[4]||0),mode:cols[5],account:cols[6],product:cols[7],qty:cols[8],desc:cols[9]};
    }).filter(r=>r.date&&r.type&&r.amount);

    const preview=document.getElementById('csv-preview');
    const table=document.getElementById('csv-preview-table');
    if(preview) preview.style.display='block';
    if(table) table.innerHTML=`<table style="width:100%;border-collapse:collapse;font-size:10px;">
      <thead><tr style="background:#f0fdf4;">${['Date','Type','Party','Amount','Mode'].map(h=>`<th style="padding:5px 8px;text-align:left;color:#0f3d26;">${h}</th>`).join('')}</tr></thead>
      <tbody>${csvData.slice(0,5).map((r,i)=>`<tr style="background:${i%2?'#f9fafb':'#fff'};">
        <td style="padding:4px 8px;">${escHTML(r.date)}</td><td style="padding:4px 8px;">${escHTML(r.type)}</td>
        <td style="padding:4px 8px;">${escHTML(r.party)}</td><td style="padding:4px 8px;font-weight:700;">৳${pf(r.amount)}</td>
        <td style="padding:4px 8px;">${escHTML(r.mode)}</td>
      </tr>`).join('')}</tbody>
    </table><div style="padding:6px 8px;font-size:10px;color:#6b7280;background:#f9fafb;">Total: ${csvData.length} rows to import</div>`;
  };
  reader.readAsText(file);
}

async function importCSV(){
  if(!csvData.length){alert('No data to import.');return;}
  if(!await __confirm('Import '+csvData.length+' transactions?')) return;
  if(!DB.transactions) DB.transactions=[];
  const imported=csvData.map(r=>({...r,id:newId()}));
  DB.transactions=[...imported,...DB.transactions];
  if(!DB.importLog) DB.importLog=[];
  DB.importLog.unshift({ts:Date.now(),type:'CSV Transactions',count:imported.length});
  saveDB();
  csvData=[];
  alert('✅ '+imported.length+' transactions imported!');
  renderImportExcel();
}

function previewJSONRestore(input){
  const file=input.files[0];
  if(!file) return;
  const reader=new FileReader();
  reader.onload=function(e){
    try{
      const data=__ayanSafeJSONParse(e.target.result);
      const preview=document.getElementById('json-restore-preview');
      if(preview){
        preview.style.display='block';
        preview.innerHTML=`<strong>Backup Contents:</strong><br/>
          Transactions: ${(data.transactions||[]).length}<br/>
          Parties: ${(data.parties||[]).length}<br/>
          Products: ${(data.products||[]).length}<br/>
          Employees: ${(data.employees||[]).length}<br/>
          <button data-x-click="restoreJSON()" style="margin-top:8px;padding:7px 14px;background:#16a34a;color:#fff;border:none;border-radius:6px;font-size:11px;font-weight:700;cursor:pointer;">✅ Restore This Backup</button>`;
        window._pendingRestore=data;
      }
    }catch(err){alert('Invalid JSON file.');}
  };
  reader.readAsText(file);
}

async function restoreJSON(){
  if(!window._pendingRestore){alert('No backup loaded.');return;}
  if(!await __confirm('This will REPLACE all current data. Are you sure?')) return;
  const _payload = window.__ayanScrubProto(window._pendingRestore);
  Object.assign(DB,_payload);
  try{ repairTxIds(); }catch(e){}
  /* Replay the two modules that do not live in DB — see restoreModuleExtras. */
  let _extras=null;
  try{ _extras = await restoreModuleExtras(_payload && _payload.DB ? _payload : _payload); }catch(e){}
  try{ tidyRestoredDB(); }catch(e){}
  saveDB();
  window._pendingRestore=null;
  try{ reportRestoredExtras(_extras); }catch(e){}
  alert('✅ Data restored successfully!');
  renderImportExcel();
}

