  const txnCount=(DB.tx||[]).length;
  const partyCount=(DB.parties||[]).length;
  const productCount=(DB.products||[]).length;

  body.innerHTML=`<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:16px;">
    ${[
      {title:'📊 Export Transactions',desc:'Export all '+txnCount+' transactions to CSV',color:'#16a34a',fn:'exportTransactionsCSV',icon:'📋'},
      {title:'👥 Export Parties',desc:'Export all '+partyCount+' parties/contacts to CSV',color:'#2563eb',fn:'exportPartiesCSV',icon:'👥'},
      {title:'📦 Export Products',desc:'Export all '+productCount+' products to CSV',color:'#7c3aed',fn:'exportProductsCSV',icon:'📦'},
      {title:'💰 Export Ledger',desc:'Export party-wise ledger summary to CSV',color:'#f59e0b',fn:'exportLedgerCSV',icon:'📒'},
      {title:'🏦 Export Bank Data',desc:'Export bank account transactions to CSV',color:'#0891b2',fn:'exportBankCSV',icon:'🏦'},
      {title:'💾 Full JSON Backup',desc:'Export complete database as JSON backup',color:'#dc2626',fn:'backupData',icon:'🗄️'}
    ].map(e=>`<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
      <div style="background:${e.color}11;border-left:4px solid ${e.color};padding:12px 16px;">
        <div style="font-size:20px;margin-bottom:4px;">${e.icon}</div>
        <div style="font-weight:700;font-size:13px;color:${e.color};">${e.title}</div>
        <div style="font-size:11px;color:#6b7280;margin-top:2px;">${escHTML(e.desc)}</div>
      </div>
      <div style="padding:12px;">
        <button data-x-click="${e.fn}()" style="width:100%;padding:9px;background:${e.color};color:#fff;border:none;border-radius:7px;font-size:12px;font-weight:700;cursor:pointer;">⬇️ Export</button>
      </div>
    </div>`).join('')}
  </div>`;
}

function exportPartiesCSV(){
  const parties=DB.parties||[];
  if(!parties.length){alert('No parties to export.');return;}
  const headers=['Name','Type','Phone','Email','Address','Balance'];
  const rows=parties.map(p=>[p.name,p.type,p.phone||'',p.email||'',p.address||'',p.bal||p.cap||0].map(v=>__csvCell(v||'')).join(','));
  const csv=[headers.join(','),...rows].join('\n');
  const blob=new Blob([csv],{type:'text/csv'});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');
  a.href=url;a.download='parties_'+new Date().toISOString().split('T')[0]+'.csv';a.click();
}

function exportProductsCSV(){
  const products=DB.products||[];
  if(!products.length){alert('No products to export.');return;}
  const headers=['Name','Category','Unit','Rate','Stock','Min Stock'];
  const rows=products.map(p=>[p.name,p.category||'',p.unit||'',p.rate||0,p.stock||0,p.minStock||0].map(v=>__csvCell(v||'')).join(','));
  const csv=[headers.join(','),...rows].join(`
`);
  const blob=new Blob([csv],{type:'text/csv'});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');
  a.href=url;a.download='products_'+new Date().toISOString().split('T')[0]+'.csv';a.click();
}

function exportLedgerCSV(){
  const txns=DB.tx||[];
  const ledger={};
  txns.forEach(t=>{
    if(!t.party) return;
    if(!ledger[t.party]) ledger[t.party]={name:t.party,type:t.partyType||'',debit:0,credit:0};
    const amt=txAmt(t);
    if(['Sale','Purchase Payment','Salary Payment','Expense'].includes(t.type)) ledger[t.party].debit+=amt;
    else ledger[t.party].credit+=amt;
  });
  const headers=['Party Name','Type','Total Debit','Total Credit','Net Balance'];
  const rows=Object.values(ledger).map(l=>[l.name,l.type,l.debit,l.credit,l.debit-l.credit].map(v=>__csvCell(v||'')).join(','));
  const csv=[headers.join(','),...rows].join(`
`);
  const blob=new Blob([csv],{type:'text/csv'});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');
  a.href=url;a.download='ledger_'+new Date().toISOString().split('T')[0]+'.csv';a.click();
}

function exportBankCSV(){
  const txns=(DB.tx||[]).filter(t=>['Bank Deposit','Bank Withdrawal','Bank Transfer','Bank Charge'].includes(t.type));
  if(!txns.length){alert('No bank transactions to export.');return;}
  const headers=['Date','Type','Party','Amount','Account','Mode','Description'];
  const rows=txns.map(t=>[t.date,t.type,t.party||'',t.amount,t.account||'',t.mode||'',t.desc||''].map(v=>__csvCell(v||'')).join(','));
  const csv=[headers.join(','),...rows].join(`
`);
  const blob=new Blob([csv],{type:'text/csv'});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');
  a.href=url;a.download='bank_transactions_'+new Date().toISOString().split('T')[0]+'.csv';a.click();
}

// ── Bulk Import/Export ─────────────────────────────────────────
function renderBulkImportExport(){
  const body=document.getElementById('bulk-body');
  if(!body) return;
  const dbSize=JSON.stringify(DB).length;
  body.innerHTML=`<div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;">
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
      <div style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;padding:12px 16px;font-weight:700;font-size:13px;">📤 Bulk Export</div>
      <div style="padding:16px;">
        <div style="background:#f0fdf4;border:1px solid #bbf7d0;border-radius:8px;padding:12px;margin-bottom:12px;font-size:11px;color:#166534;">
          Export all data in one click. Use for backup or migration.
        </div>
        ${[
          {label:'Export All as JSON',desc:'Complete database backup',fn:'backupData',color:'#16a34a'},
          {label:'Export Transactions CSV',desc:(DB.tx||[]).length+' transactions',fn:'exportTransactionsCSV',color:'#2563eb'},
          {label:'Export Parties CSV',desc:(DB.parties||[]).length+' parties',fn:'exportPartiesCSV',color:'#7c3aed'},
          {label:'Export Products CSV',desc:(DB.products||[]).length+' products',fn:'exportProductsCSV',color:'#f59e0b'}
        ].map(e=>`<div style="display:flex;justify-content:space-between;align-items:center;padding:8px 0;border-bottom:1px solid #f3f4f6;">
          <div>
            <div style="font-size:12px;font-weight:600;">${e.label}</div>
            <div style="font-size:10px;color:#9ca3af;">${escHTML(e.desc)}</div>
          </div>
          <button data-x-click="${e.fn}()" style="padding:5px 12px;background:${e.color};color:#fff;border:none;border-radius:5px;font-size:10px;font-weight:700;cursor:pointer;">⬇️</button>
        </div>`).join('')}
        <div style="margin-top:12px;padding:10px;background:#f9fafb;border-radius:6px;font-size:11px;color:#6b7280;text-align:center;">
          Database size: <strong>${Math.round(dbSize/1024)} KB</strong>
        </div>
      </div>
    </div>
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
      <div style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;padding:12px 16px;font-weight:700;font-size:13px;">📥 Bulk Import</div>
      <div style="padding:16px;">
        <div style="background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px;padding:12px;margin-bottom:12px;font-size:11px;color:#1e40af;">
          Import data from CSV or JSON files. Existing data will be preserved.
        </div>
        <div style="border:2px dashed #d1d5db;border-radius:8px;padding:20px;text-align:center;margin-bottom:12px;">
          <div style="font-size:28px;margin-bottom:6px;">📂</div>
          <div style="font-size:12px;font-weight:600;color:#374151;">Drop files here or click to browse</div>
          <div style="font-size:10px;color:#9ca3af;margin-top:2px;">Supports .csv and .json files</div>
          <!-- FIX (2026-09-12): these buttons used to try document.getElementById(
               'csv-file'/'json-restore-file').click() — but those file inputs only
               exist once the separate "Import Excel" page (renderImportExcel(),
               #import-body) has actually been rendered into the DOM. Landing on
               Bulk Import/Export first meant the elements didn't exist yet, so the
               click() call silently did nothing. Route to the page that owns the
               real upload widgets instead of reaching for elements that may not
               be there. -->
          <div style="display:flex;gap:8px;justify-content:center;margin-top:10px;">
            <button data-x-click="nav('importexcel')" style="padding:7px 14px;background:#16a34a;color:#fff;border:none;border-radius:6px;font-size:11px;font-weight:700;cursor:pointer;">📄 CSV</button>
            <button data-x-click="nav('importexcel')" style="padding:7px 14px;background:#2563eb;color:#fff;border:none;border-radius:6px;font-size:11px;font-weight:700;cursor:pointer;">🗄️ JSON</button>
          </div>
          <div style="font-size:10px;color:#9ca3af;margin-top:8px;">Opens the Import Excel page, where CSV and JSON backup uploads are handled.</div>
        </div>
        <div style="background:#fef3c7;border:1px solid #fcd34d;border-radius:8px;padding:10px;font-size:11px;color:#92400e;">
