  </div>`;
}

// ── Trash Bin ──────────────────────────────────────────────────
var trashBulkSel = (typeof trashBulkSel !== 'undefined') ? trashBulkSel : new Set();

function toggleTrashSel(i, checked){
  if(checked) trashBulkSel.add(i); else trashBulkSel.delete(i);
  renderTrashBin();
}
function toggleTrashSelAll(checked){
  const trash=DB.trash||[];
  trashBulkSel = checked ? new Set(trash.map((_,i)=>i)) : new Set();
  renderTrashBin();
}
function clearTrashSel(){
  trashBulkSel = new Set();
  renderTrashBin();
}

async function bulkRestoreSelectedTrash(){
  if(!trashBulkSel.size) return;
  const n = trashBulkSel.size;
  if(!await __confirm('Restore ' + n + ' selected item(s)? Balances, stock and other reversal effects will be re-applied for each.')) return;
  // Process from the highest index down so removing an item never shifts
  // the position of another item still waiting to be processed.
  const idxs = Array.from(trashBulkSel).sort(function(a,b){ return b-a; });
  let restored = 0;
  idxs.forEach(function(idx){
    const trash = DB.trash || [];
    const item = trash[idx];
    if(!item) return;
    const type = item._type || 'transaction';
    delete item._type; delete item._deletedAt;
    if(type==='transaction'){
      if(!DB.transactions) DB.transactions=[];
      (DB.tx=DB.tx||[]).unshift(item);
      try{ if(typeof applyTxBalance==='function') applyTxBalance(item,1); }catch(e){}
      try{ if(typeof applyTxStock==='function') applyTxStock(item,1); }catch(e){}
    } else if(type==='party'){
      if(item.type==='Partner'){ (DB.partners=DB.partners||[]).unshift(item); }
      else { (DB.customers=DB.customers||[]).unshift(item); }
    } else if(type==='product'){ if(!DB.products) DB.products=[]; DB.products.unshift(item); }
    else if(type==='tender'){ if(!DB.tenders) DB.tenders=[]; DB.tenders.unshift(item); }
    DB.trash = trash.filter(function(_, i){ return i !== idx; });
    restored++;
  });
  try{ if(typeof syncStock==='function') syncStock(); }catch(e){}
  trashBulkSel = new Set();
  saveDB();
  renderTrashBin();
  if(typeof toast==='function') toast(restored + ' item(s) restored', 's');
  else alert('✅ ' + restored + ' item(s) restored!');
}

async function bulkPurgeSelectedTrash(){
  if(!trashBulkSel.size) return;
  const n = trashBulkSel.size;
  if(!await __confirm('Permanently delete ' + n + ' selected item(s)? This cannot be undone.')) return;
  const idxs = Array.from(trashBulkSel).sort(function(a,b){ return b-a; });
  let purged = 0;
  idxs.forEach(function(idx){
    const trash = DB.trash || [];
    if(idx < 0 || idx >= trash.length) return;
    DB.trash = trash.filter(function(_, i){ return i !== idx; });
    purged++;
  });
  trashBulkSel = new Set();
  saveDB();
  renderTrashBin();
  if(typeof toast==='function') toast(purged + ' item(s) permanently deleted', 's');
}

function renderTrashBin(){
  const body=document.getElementById('trash-body');
  if(!body) return;
  const trash=DB.trash||[];
  if(!trash.length){trashBulkSel=new Set();body.innerHTML='<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:40px;text-align:center;"><div style="font-size:40px;margin-bottom:8px;">🗑️</div><div style="font-size:16px;font-weight:700;color:#6b7280;">Trash is Empty</div><div style="font-size:12px;color:#9ca3af;margin-top:4px;">Deleted items will appear here.</div></div>';return;}

  // drop any stale selections left over from a previous, larger trash list
  trashBulkSel = new Set(Array.from(trashBulkSel).filter(function(i){ return i < trash.length; }));
  const selN = trashBulkSel.size;
  const allSelected = selN > 0 && selN === trash.length;

  body.innerHTML=`<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
    <div style="background:linear-gradient(90deg,#dc2626,#b91c1c);color:#fff;padding:12px 16px;font-weight:700;font-size:13px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px;">
      <span>🗑️ Deleted Items (${trash.length})</span>
      ${selN ? `<span style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;">
        <b style="background:rgba(255,255,255,.22);border-radius:20px;padding:2px 10px;font-size:11px;">${selN} selected</b>
        <button data-x-click="bulkRestoreSelectedTrash()" style="background:#16a34a;color:#fff;border:0;border-radius:7px;padding:6px 11px;font:700 11px inherit;cursor:pointer;">↩️ Restore Selected</button>
        <button data-x-click="bulkPurgeSelectedTrash()" style="background:#7f1d1d;color:#fff;border:0;border-radius:7px;padding:6px 11px;font:700 11px inherit;cursor:pointer;">🗑️ Delete Selected</button>
        <button data-x-click="clearTrashSel()" style="background:rgba(255,255,255,.18);color:#fff;border:0;border-radius:7px;padding:6px 11px;font:700 11px inherit;cursor:pointer;">✕ Clear</button>
      </span>` : ''}
    </div>
    <table style="width:100%;border-collapse:collapse;font-size:12px;">
      <thead><tr style="background:#fef2f2;">
        <th style="padding:9px 6px;text-align:center;width:30px;"><input type="checkbox" ${allSelected?'checked':''} data-x-click="toggleTrashSelAll(this.checked)" title="Select all"></th>
        <th style="padding:9px 12px;text-align:left;color:#991b1b;">Type</th>
        <th style="padding:9px 12px;text-align:left;color:#991b1b;">Name / Title</th>
        <th style="padding:9px 12px;text-align:left;color:#991b1b;">Details</th>
        <th style="padding:9px 12px;text-align:left;color:#991b1b;">Deleted At</th>
        <th style="padding:9px 12px;text-align:center;color:#991b1b;">Action</th>
      </tr></thead>
      <tbody>${trash.map((item,i)=>{
        const type=item._type||'transaction';
        const name=item.name||item.title||item.party||item.type||'Unknown';
        const detail=item.amount?'৳'+pf(parseFloat(item.amount||0)):item.value?'৳'+pf(item.value):'—';
        const deletedAt=item._deletedAt?new Date(item._deletedAt).toLocaleString('en-BD'):'—';
        return `<tr style="border-bottom:1px solid #f3f4f6;background:${trashBulkSel.has(i)?'#dbeafe':(i%2?'#fef9f9':'#fff')};">
          <td style="padding:8px 6px;text-align:center;"><input type="checkbox" ${trashBulkSel.has(i)?'checked':''} data-x-change="toggleTrashSel(${i},this.checked)"></td>
          <td style="padding:8px 12px;"><span style="background:#fee2e2;color:#dc2626;padding:2px 8px;border-radius:8px;font-size:10px;font-weight:700;text-transform:uppercase;">${type}</span></td>
          <td style="padding:8px 12px;font-weight:700;">${name}</td>
          <td style="padding:8px 12px;color:#6b7280;">${detail}</td>
          <td style="padding:8px 12px;color:#6b7280;font-size:11px;">${deletedAt}</td>
          <td style="padding:8px 12px;text-align:center;display:flex;gap:6px;justify-content:center;">
            <button data-x-click="restoreFromTrash(${i})" style="background:#dcfce7;color:#16a34a;border:none;border-radius:5px;padding:3px 8px;font-size:10px;cursor:pointer;font-weight:700;">↩️ Restore</button>
            <button data-x-click="permanentDelete(${i})" style="background:#fee2e2;color:#dc2626;border:none;border-radius:5px;padding:3px 8px;font-size:10px;cursor:pointer;">🗑️</button>
          </td>
        </tr>`;
      }).join('')}</tbody>
    </table>
  </div>`;
}

function restoreFromTrash(idx){
  const trash=DB.trash||[];
  const item=trash[idx];
  if(!item) return;
  const type=item._type||'transaction';
  delete item._type;delete item._deletedAt;
  /* FIX: restoring put the row back in the list but never put the money or
     the stock back with it, so a restored transaction showed in the ledger
     while the bank, the party and the stock still had it reversed — the
     books went out by its value. Its effects are re-applied here. */
  if(type==='transaction'){
    if(!DB.transactions) DB.transactions=[];
    (DB.tx=DB.tx||[]).unshift(item);
    try{ if(typeof applyTxBalance==='function') applyTxBalance(item,1); }catch(e){}
    try{ if(typeof applyTxStock==='function') applyTxStock(item,1); }catch(e){}
    try{ if(typeof syncStock==='function') syncStock(); }catch(e){}
  }
  else if(type==='party'){
    // DB.parties is a computed view — real storage is DB.customers / DB.partners
    if(item.type==='Partner'){ (DB.partners=DB.partners||[]).unshift(item); }
    else { (DB.customers=DB.customers||[]).unshift(item); }
  }
  else if(type==='product'){if(!DB.products) DB.products=[];DB.products.unshift(item);}
  else if(type==='tender'){if(!DB.tenders) DB.tenders=[];DB.tenders.unshift(item);}
  DB.trash=trash.filter((_,i)=>i!==idx);
  saveDB();
  renderTrashBin();
  alert('✅ Item restored!');
}

async function permanentDelete(idx){
  if(!await __confirm('Permanently delete this item? This cannot be undone.')) return;
  DB.trash=(DB.trash||[]).filter((_,i)=>i!==idx);
  saveDB();
  renderTrashBin();
}

async function emptyTrash(){
  if(!await __confirm('Permanently delete ALL items in trash? This cannot be undone.')) return;
  DB.trash=[];
  saveDB();
  renderTrashBin();
}


// ══════════════════════════════════════════════════════════════
// BATCH R: USER ROLES, APPROVALS, ACTIVITY LOG, LOGIN LOG, 2FA, SETTINGS, PROFILE
// ══════════════════════════════════════════════════════════════

// ── User Roles ─────────────────────────────────────────────────
function openAddUserModal(){
  document.getElementById('user-modal').style.display='flex';
}

function saveUser(){
  /* FIX: unguarded, this let any account create a brand-new user with any
     role — including Admin — a straight privilege-escalation path. */
  if(typeof isAdminOrOwner!=='function'||!isAdminOrOwner()){toast('Only Admin/Owner can create user accounts','e');return;}
  const perms=['dashboard','transactions','reports','parties','inventory','finance','payroll','admin','export'];
  const permissions={};
  perms.forEach(p=>{permissions[p]=document.getElementById('perm-'+p)?.checked||false;});
  const user={
    id:newId(),
    name:document.getElementById('usr-name')?.value||'',
    username:document.getElementById('usr-username')?.value||'',
    pin:document.getElementById('usr-pin')?.value||'',
    role:document.getElementById('usr-role')?.value||'Operator',
    dept:document.getElementById('usr-dept')?.value||'Operations',
    phone:document.getElementById('usr-phone')?.value||'',
    permissions,
    status:'Active',
    createdAt:new Date().toISOString(),
    lastLogin:null
  };
  if(!user.name||!user.username){alert('Name and username are required.');return;}
  if(!DB.users) DB.users=[];
  if(DB.users.some(u=>u.username===user.username)){alert('Username already exists.');return;}
  DB.users.push(user);
  saveDB();
  if(typeof addAuditEntry==='function') addAuditEntry('CREATE','Users','Added user: '+user.name+' ('+user.role+')');
  document.getElementById('user-modal').style.display='none';
  renderUserRoles();
  alert('✅ User added!');
}

async function deleteUser(id){
  /* FIX: unguarded, any logged-in account — Staff included — could delete
     any other account, up to and including the real Admin's. */
  if(typeof isAdminOrOwner!=='function'||!isAdminOrOwner()){toast('Only Admin/Owner can remove user accounts','e');return;}
  if(!await __confirm('Remove this user?')) return;
  const u=(DB.users||[]).find(u=>u.id===id);
  DB.users=(DB.users||[]).filter(u=>u.id!==id);
  saveDB();
  if(typeof addAuditEntry==='function') addAuditEntry('DELETE','Users','Removed user: '+(u?.name||id));
  renderUserRoles();
}

function toggleUserStatus(id){
  /* FIX: unguarded, any logged-in account could deactivate any other
     account (including the real Admin's), locking them out. */
  if(typeof isAdminOrOwner!=='function'||!isAdminOrOwner()){toast('Only Admin/Owner can change a user\'s active status','e');return;}
  const u=(DB.users||[]).find(u=>u.id===id);
  if(u){u.status=u.status==='Active'?'Inactive':'Active';saveDB();renderUserRoles();}
}

function renderUserRoles(){
  const body=document.getElementById('ur-body');
  if(!body) return;
  /* FIX (2026-08-25, serious access-control gap): this page — reachable
     from the sidebar as "🔑 User Roles" by ANY logged-in account — let
     any Staff/Operator/Viewer create a brand new user with the Admin role
     (saveUser(), no check at all), delete or deactivate any existing
     account including the real Admin's (deleteUser()/toggleUserStatus(),
     also unchecked), and change anyone's role. Order Management already
     had the same "delete with no role check" bug fixed earlier; this one
     is worse, since it reaches account access itself, not order records.
     Gated the whole page here (not just the buttons) so non-admins see a
     clear message instead of a working-looking screen whose actions
     silently fail — matches how saveUser()/deleteUser()/toggleUserStatus()
     are now separately guarded below, so this can't be bypassed by
     calling those functions directly either. */
  if(typeof isAdminOrOwner!=='function'||!isAdminOrOwner()){
    body.innerHTML='<div style="text-align:center;padding:50px 20px;color:#6b7280;"><div style="font-size:40px;margin-bottom:10px;">🔒</div><div style="font-size:15px;font-weight:800;color:#1a202c;margin-bottom:6px;">Admin/Owner Access Only</div><div style="font-size:12.5px;">User accounts and roles can only be managed by an Admin or Owner. Ask an admin if you need a change here.</div></div>';
    return;
  }
  const users=DB.users||[];

  const roleColors={Admin:'#dc2626',Manager:'#7c3aed',Operator:'#2563eb',Viewer:'#6b7280'};
  const rolePerms={
    Admin:'Full access to all modules',
    Manager:'Access to reports, transactions, parties',
    Operator:'Add/edit transactions and inventory',
    Viewer:'Read-only access to dashboard and reports'
  };

  body.innerHTML=`<div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:16px;">
    ${Object.entries(roleColors).map(([role,color])=>`<div style="background:#fff;border:1px solid ${color}22;border-left:4px solid ${color};border-radius:10px;padding:14px 16px;">
      <div style="font-weight:800;font-size:14px;color:${color};">${role}</div>
      <div style="font-size:11px;color:#6b7280;margin-top:3px;">${rolePerms[role]}</div>
      <div style="font-size:12px;font-weight:700;color:#374151;margin-top:6px;">${users.filter(u=>u.role===role).length} user(s)</div>
    </div>`).join('')}
  </div>
  <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
    <div style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;padding:12px 16px;font-weight:700;font-size:13px;">👥 User Accounts</div>
    ${users.length?`<table style="width:100%;border-collapse:collapse;font-size:12px;">
      <thead><tr style="background:#f0fdf4;">
        <th style="padding:9px 12px;text-align:left;color:#0f3d26;">Name</th>
        <th style="padding:9px 12px;text-align:left;color:#0f3d26;">Username</th>
        <th style="padding:9px 12px;text-align:left;color:#0f3d26;">Role</th>
        <th style="padding:9px 12px;text-align:left;color:#0f3d26;">Department</th>
        <th style="padding:9px 12px;text-align:left;color:#0f3d26;">Status</th>
        <th style="padding:9px 12px;text-align:left;color:#0f3d26;">Last Login</th>
        <th style="padding:9px 12px;text-align:center;color:#0f3d26;">Action</th>
      </tr></thead>
      <tbody>${users.map((u,i)=>{
        const color=roleColors[u.role]||'#6b7280';
        return `<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
          <td style="padding:8px 12px;font-weight:700;">${escHTML(u.name)}</td>
          <td style="padding:8px 12px;font-family:monospace;color:#6b7280;">@${u.username}</td>
          <td style="padding:8px 12px;"><span style="background:${color}22;color:${color};padding:2px 8px;border-radius:8px;font-size:10px;font-weight:700;">${escHTML(u.role)}</span></td>
          <td style="padding:8px 12px;color:#6b7280;">${escHTML(u.dept ||'—')}</td>
          <td style="padding:8px 12px;">
            <span style="background:${u.status==='Active'?'#dcfce7':'#fee2e2'};color:${u.status==='Active'?'#16a34a':'#dc2626'};padding:2px 8px;border-radius:10px;font-size:10px;font-weight:700;cursor:pointer;" data-x-click="toggleUserStatus(${u.id})">${u.status}</span>
          </td>
          <td style="padding:8px 12px;color:#6b7280;font-size:11px;">${u.lastLogin?new Date(u.lastLogin).toLocaleString('en-BD'):'Never'}</td>
          <td style="padding:8px 12px;text-align:center;">
            <button data-x-click="deleteUser(${u.id})" style="background:#fee2e2;color:#dc2626;border:none;border-radius:5px;padding:3px 8px;font-size:10px;cursor:pointer;">🗑️</button>
          </td>
        </tr>`;
      }).join('')}</tbody>
    </table>`:'<div style="padding:40px;text-align:center;color:#9ca3af;">No users added yet. Click "Add User" to create user accounts.</div>'}
  </div>`;
}

// ── Pending Approvals ──────────────────────────────────────────

/**
 * Update approval page permission visibility.
 * Hides "Approve All" button for non-admin users.
 * @private
 */
function _updateApprovalPermissions() {
  const allBtn = document.getElementById('approve-all-btn');
  if (allBtn) {
    allBtn.style.display = (typeof isTopApprover === 'function' && isTopApprover()) ? '' : 'none';
  }
}

/**
 * Get approval statistics for dashboard cards.
 * @private
 * @returns {Object} Object with pending, highValue, and approvedToday counts
 */
function _getPendingApprovalStats() {
  const allPending = typeof window.getPendingApprovalTx === 'function'
    ? window.getPendingApprovalTx()
    : [];
  const highValue = (DB.tx || []).filter(t =>
    txAmt(t) > window.CONFIG.APPROVAL_THRESHOLD && !t.approved
  );
  const approvedToday = (DB.approvalLog || []).filter(a =>
    a.date === new Date().toISOString().split('T')[0]
  );

  return {
    pending: allPending.length,
    highValue: highValue.length,
    approved: approvedToday.length
  };
}

/**
 * Render approval statistics cards.
 * @private
 */
function _renderApprovalCards(stats) {
  const cards = ensureDivIn('pg-pendingapprovals', 'pa-cards');
  if (!cards) return;

  const cardData = [
    { label: 'Pending', val: stats.pending, icon: '⏳', color: window.CONFIG.COLORS.pending },
    { label: 'High Value', val: stats.highValue, icon: '💰', color: window.CONFIG.COLORS.error },
    { label: 'Approved Today', val: stats.approved, icon: '✅', color: window.CONFIG.COLORS.success }
  ];

  cards.innerHTML = cardData.map(c =>
    `<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
      <div style="font-size:22px;">${c.icon}</div>
      <div style="font-size:17px;font-weight:900;color:${c.color};">${c.val}</div>
      <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)}</div>
    </div>`
  ).join('');
}

function renderPendingApprovals(){
  const body=ensureDivIn('pg-pendingapprovals','pa-body');
  if(!body) return;

  // Update permissions and render cards
  _updateApprovalPermissions();
  const stats = _getPendingApprovalStats();
  _renderApprovalCards(stats);

  // Get pending transactions
  const allPending=typeof window.getPendingApprovalTx==='function'?window.getPendingApprovalTx():[];

  if(!allPending.length){
    body.innerHTML='<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:40px;text-align:center;"><div style="font-size:40px;margin-bottom:8px;">✅</div><div style="font-size:16px;font-weight:700;color:'+window.CONFIG.COLORS.success+';">No Pending Approvals</div><div style="font-size:12px;color:#9ca3af;margin-top:4px;">All transactions are up to date.</div></div>';
    return;
  }

  const isAdmin = typeof isTopApprover==='function'&&isTopApprover();
  body.innerHTML=`<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
    <div style="background:linear-gradient(90deg,${window.CONFIG.COLORS.pending},#d97706);color:#fff;padding:12px 16px;font-weight:700;font-size:13px;">⏳ Transactions Awaiting Approval</div>
    <table style="width:100%;border-collapse:collapse;font-size:12px;">
      <thead><tr style="background:#fefce8;">
        <th style="padding:9px 12px;text-align:left;color:#92400e;">Date</th>
        <th style="padding:9px 12px;text-align:left;color:#92400e;">Type</th>
        <th style="padding:9px 12px;text-align:left;color:#92400e;">Party</th>
        <th style="padding:9px 12px;text-align:right;color:#92400e;">Amount (৳)</th>
        <th style="padding:9px 12px;text-align:left;color:#92400e;">Mode</th>
        <th style="padding:9px 12px;text-align:left;color:#92400e;">Entered By</th>
        <th style="padding:9px 12px;text-align:center;color:#92400e;">Action</th>
      </tr></thead>
      <tbody>${allPending.map((t,i)=>`<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#fefce8':'#fff'};">
        <td style="padding:8px 12px;color:#6b7280;">${t.date}</td>
        <td style="padding:8px 12px;font-weight:700;">${t.type}</td>
        <td style="padding:8px 12px;">${escHTML(t.party||'—')}</td>
        <td style="padding:8px 12px;text-align:right;font-weight:800;color:${txAmt(t)>window.CONFIG.APPROVAL_THRESHOLD?window.CONFIG.COLORS.error:'#0f3d26'};">৳${pf(txAmt(t))}</td>
        <td style="padding:8px 12px;color:#6b7280;">${t.mode||'—'}</td>
        <td style="padding:8px 12px;">${window.MakerChecker.makerBadge(t)}</td>
        <td style="padding:8px 12px;text-align:center;display:flex;gap:6px;justify-content:center;">
          ${isAdmin?`<button data-x-click="approveTransaction(${t.id})" style="background:#dcfce7;color:${window.CONFIG.COLORS.success};border:none;border-radius:5px;padding:4px 10px;font-size:10px;cursor:pointer;font-weight:700;">✅ Approve</button>
          <button data-x-click="rejectTransaction(${t.id})" style="background:#fee2e2;color:${window.CONFIG.COLORS.error};border:none;border-radius:5px;padding:4px 10px;font-size:10px;cursor:pointer;font-weight:700;">❌ Reject</button>`:`<span style="color:#9ca3af;font-size:10px;">Admin only</span>`}
        </td>
      </tr>`).join('')}</tbody>
    </table>
  </div>`;
}

/* FIX (2026-08-28, "Approve shows the success message but the row is
   still there"): two problems compounded.
   1) `(DB.tx||[]).find(t=>String(t.id)===String(id))` grabs the FIRST
      transaction with a matching id. If two records ever end up sharing
      an id (e.g. a record that got re-saved instead of updated in place
      — exactly what happened when RCPT-0002 was re-pointed from Suborna
      to Sorna), find() can land on an already-approved sibling instead of
      the actual pending one, silently no-op, and leave the real pending
      row untouched.
   2) Even when that happened, `alert('✅ Transaction approved!')` fired
      unconditionally — outside the `if(t)` guard — so the user was told
      it worked no matter what, with no way to tell the click had failed.
   Fixed by (a) preferring a candidate that actually matches the pending
   rule (same rule as getPendingApprovalTx) when more than one record
   shares an id, and (b) only showing success once something was actually
   approved/rejected — otherwise a clear error, not a false "done". */
function _findPendingTxCandidate(id){
  const candidates=(DB.tx||[]).filter(t=>String(t.id)===String(id));
  if(candidates.length<=1) return candidates[0];
  return candidates.find(t=>t.status==='Pending'||t.needsApproval||(txAmt(t)>500000&&!t.approved)) || candidates[0];
}

/* FIX (2026-08-28, "approval resets back to Pending after refreshing the
   browser"): saveDB() is debounced/coalesced (see erp-durable-save-v4) —
   a mutation that doesn't add or remove a transaction (exactly what
   approving/rejecting is: the record count never changes) can sit unsaved
   in the browser for up to 400ms before the actual POST to api.php is even
   sent. A refresh inside that window reloads the last copy that made it to
   the erp_state row in the database — still Pending — and the approval
   silently disappears, even though the UI had already shown "✅ Approved".
   The database side (db.php: erp_save_state()) already does exactly what
   it should — decode, replace, UPDATE erp_state inside a transaction, and
   only report success once that UPDATE has actually committed — so the
   fix belongs on the client: force an immediate, AWAITED save
   (saveDBNow(), not the debounced saveDB()) and only tell the user it
   worked once that save is confirmed by the server, not the instant the
   in-memory object was mutated. */
async function _forceSaveAndConfirm(){
  if(typeof saveDBNow==='function'){
    /* FIX (2026-08-28, follow-up: "still resets after refresh"): awaiting
       saveDBNow() stops the app from CLAIMING success early, but it can't
       stop a person from refreshing the tab WHILE that request is still on
       the wire — a normal (non-keepalive) fetch is simply killed by
       navigation, and the approval is lost exactly as before, just in a
       narrower window. The only way to actually prevent that is to make a
       refresh during an in-flight approval save impossible to do by
       accident: block the Approve/Reject buttons and warn on
       beforeunload/pagehide for as long as this save is outstanding, the
       same way an unsaved-form warning works. */
    window.__erpApprovalSaveInFlight = (window.__erpApprovalSaveInFlight||0) + 1;
    _toggleApprovalButtonsBusy(true);
    try{
      const ok=await saveDBNow();
      return ok!==false;            // false = server explicitly rejected/failed; null/true = fine
    } finally {
      window.__erpApprovalSaveInFlight = Math.max(0,(window.__erpApprovalSaveInFlight||1)-1);
      if(!window.__erpApprovalSaveInFlight) _toggleApprovalButtonsBusy(false);
    }
  }
  if(typeof saveDB==='function') saveDB();
  return true;                      // no saveDBNow available — nothing more to await
}
function _toggleApprovalButtonsBusy(busy){
  try{
    document.querySelectorAll('#pg-pendingapprovals button').forEach(function(b){
      b.disabled = !!busy;
      if(busy) b.style.opacity='0.5';
      else b.style.opacity='';
    });
  }catch(e){}
}
if(!window.__erpApprovalUnloadGuardInstalled){
  window.__erpApprovalUnloadGuardInstalled = true;
  window.addEventListener('beforeunload', function(e){
    if(window.__erpApprovalSaveInFlight){
      // Standard browser-native "leave site?" confirmation — this is the
      // only mechanism that actually pauses navigation long enough for an
      // in-flight save to land, instead of letting it be silently killed.
      e.preventDefault();
      e.returnValue = 'A change is still being saved. Leaving now could lose it.';
      return e.returnValue;
    }
  });
}

/**
 * Approve a pending transaction.
 * Requires Admin permission. Updates approval status and saves immediately.
 * @param {number|string} id - Transaction ID to approve
 */
async function approveTransaction(id){
  // Permission check
  if(typeof isTopApprover!=='function'||!isTopApprover()){
    window.ErrorHandler.handle(
      { code: 'PERMISSION_DENIED' },
      'approveTransaction'
    );
    return;
  }

  // Find the transaction
  const t=_findPendingTxCandidate(id);
  if(!t){
    window.ErrorHandler.handle(
      { code: 'NOT_FOUND' },
      'approveTransaction'
    );
    return;
  }

  // MAKER-CHECKER: refuse a silent self-approval.
  const _mc=await window.MakerChecker.gate(t,'transaction');
  if(!_mc.ok){ toast('Approval cancelled \u2014 nothing was posted','i'); return; }

  // Check if already approved
  const applied=_applyTxApprovalCore(t,_mc);
  if(!applied && t.approvalStatus==='Approved'){
    toast('Already approved.','i');
    renderPendingApprovals();
    return;
  }

  // Log the approval
  if(!DB.approvalLog) DB.approvalLog=[];
  DB.approvalLog.unshift({
    id,
    action:_mc.override?'Approved (self, override)':'Approved',
    maker:window.MakerChecker.makerLabel(t),
    approver:currentUser?.name||'',
    reason:_mc.reason||'',
    date:new Date().toISOString().split('T')[0],
    ts:Date.now()
  });

  // Re-render and save
  renderPendingApprovals();
  let saved = true;
  try {
    saved = await _forceSaveAndConfirm();
  } catch(e) {
    console.warn('[approveTransaction] Save confirmation error:', e);
    saved = false;
  }
  if(saved === false){
    toast('Approved on screen, but the server save failed — refreshing right now would lose this. Check your connection and try again.','e');
    return;
  }
  alert('✅ Transaction approved!');
}

/**
 * Reject a pending transaction.
 * Requires Admin permission. Updates status and saves immediately.
 * @param {number|string} id - Transaction ID to reject
 */
async function rejectTransaction(id){
  // Permission check
  if(typeof isTopApprover!=='function'||!isTopApprover()){
    window.ErrorHandler.handle(
      { code: 'PERMISSION_DENIED' },
      'rejectTransaction'
    );
    return;
  }

  // Find the transaction
  const t=_findPendingTxCandidate(id);
  if(!t){
    window.ErrorHandler.handle(
      { code: 'NOT_FOUND' },
      'rejectTransaction'
    );
    return;
  }

  // Get rejection reason from user
  const reason=prompt('Reason for rejection (optional):');
  if(reason === null) return; // User cancelled

  // Update transaction status
  t.approved=false;
  t.status='Rejected';
  t.approvalStatus='Rejected';
  t.rejectedAt=new Date().toISOString();
  t.rejectReason=reason||'';

  // Log the rejection
  if(!DB.approvalLog) DB.approvalLog=[];
  DB.approvalLog.unshift({
    id,
    action:'Rejected',
    reason:reason||'',
    date:new Date().toISOString().split('T')[0],
    ts:Date.now()
  });

  // Re-render and save
  renderPendingApprovals();
  let saved = true;
  try {
    saved = await _forceSaveAndConfirm();
  } catch(e) {
    console.warn('[rejectTransaction] Save confirmation error:', e);
    saved = false;
  }
  if(saved === false) {
    toast('Rejected on screen, but the server save failed — refreshing right now would lose this. Check your connection and try again.','e');
  } else {
    toast('✅ Transaction rejected', 'i');
  }
}

/* REMOVED (2026-08-27, final audit): renderActivityLog() and its page
   (#pg-activitylog) were a second, unreachable copy of the Audit Log —
   no menu item, button, or link anywhere ever called nav('activitylog'),
   so this never showed up for any user. The Audit Log (nav('auditlog'),
   #pg-auditlog, restricted to the Admin role) is the one real, menu-linked
   activity log and is unaffected by this removal. */

// ── Login Time Log ─────────────────────────────────────────────
function renderLoginTimeLog(){
  const body=document.getElementById('ltl-body');
  if(!body) return;
  const loginLog=DB.loginLog||[];

  // Auto-record current session if not already
  const today=new Date().toISOString().split('T')[0];
  const todayLogins=loginLog.filter(l=>l.date===today);

  body.innerHTML=`<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:16px;">
    ${[
      {label:'Total Sessions',val:loginLog.length,icon:'🔑',color:'#2563eb'},
      {label:'Today',val:todayLogins.length,icon:'📅',color:'#16a34a'},
      {label:'This Month',val:loginLog.filter(l=>l.date?.startsWith(new Date().toISOString().slice(0,7))).length,icon:'📆',color:'#7c3aed'}
    ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
      <div style="font-size:22px;">${c.icon}</div>
      <div style="font-size:17px;font-weight:900;color:${c.color};">${c.val}</div>
      <div style="font-size:11px;color:#6b7280;margin-top:4px;">${c.label}</div>
    </div>`).join('')}
  </div>
  <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
    <div style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;padding:12px 16px;font-weight:700;font-size:13px;">🕐 Login Sessions</div>
    ${loginLog.length?`<table style="width:100%;border-collapse:collapse;font-size:12px;">
      <thead><tr style="background:#f0fdf4;">
        <th style="padding:9px 12px;text-align:left;color:#0f3d26;">Date</th>
        <th style="padding:9px 12px;text-align:left;color:#0f3d26;">Login Time</th>
        <th style="padding:9px 12px;text-align:left;color:#0f3d26;">User</th>
        <th style="padding:9px 12px;text-align:left;color:#0f3d26;">Device</th>
        <th style="padding:9px 12px;text-align:left;color:#0f3d26;">Duration</th>
      </tr></thead>
      <tbody>${loginLog.slice(0,50).map((l,i)=>`<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
        <td style="padding:8px 12px;color:#6b7280;">${l.date||'—'}</td>
        <td style="padding:8px 12px;font-weight:600;">${l.time||'—'}</td>
        <td style="padding:8px 12px;">${l.user||'Admin'}</td>
        <td style="padding:8px 12px;color:#6b7280;font-size:11px;">${l.device||'Browser'}</td>
        <td style="padding:8px 12px;color:#6b7280;">${l.duration||'Active'}</td>
      </tr>`).join('')}</tbody>
    </table>`:'<div style="padding:40px;text-align:center;color:#9ca3af;">No login sessions recorded. Sessions are logged when users log in.</div>'}
  </div>
  <div style="margin-top:12px;text-align:right;">
    <button data-x-click="logCurrentSession()" style="padding:8px 16px;background:#16a34a;color:#fff;border:none;border-radius:7px;font-size:12px;font-weight:700;cursor:pointer;">📝 Log Current Session</button>
  </div>`;
}

function logCurrentSession(){
  if(!DB.loginLog) DB.loginLog=[];
  const now=new Date();
  DB.loginLog.unshift({
    date:now.toISOString().split('T')[0],
    time:now.toLocaleTimeString('en-BD'),
    user:'Admin',
    device:navigator.userAgent.includes('Mobile')?'Mobile':'Desktop Browser',
    duration:'Active',
    ts:Date.now()
  });
  if((DB.loginLog||[]).length>200) DB.loginLog=(DB.loginLog||[]).slice(0,200);
  saveDB();
  renderLoginTimeLog();
}

// ── Two Factor Auth ────────────────────────────────────────────
function renderTwoFactorAuth(){
  // Auto-inject page structure if needed
  (function(){
    const _pg=document.getElementById('pg-twofactorauth');
    if(_pg&&!_pg.querySelector('[id]')){
      _pg.innerHTML=`<div style="padding:20px;"><div id=\"tfa-body\"></div></div>`;
    }
  })();
  const body=document.getElementById('tfa-body');
  if(!body) return;
  const tfaEnabled=DB.settings?.tfaEnabled||false;
  const pinSet=!!(DB.settings?.appPinHash||DB.settings?.appPin);

  body.innerHTML=`<div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;">
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
      <div style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;padding:12px 16px;font-weight:700;font-size:13px;">🔐 App PIN Lock</div>
      <div style="padding:16px;">
        <div style="background:${tfaEnabled?'#f0fdf4':'#fef3c7'};border:1px solid ${tfaEnabled?'#bbf7d0':'#fcd34d'};border-radius:8px;padding:12px;margin-bottom:14px;text-align:center;">
          <div style="font-size:28px;margin-bottom:4px;">${tfaEnabled?'🔒':'🔓'}</div>
          <div style="font-weight:700;font-size:14px;color:${tfaEnabled?'#16a34a':'#92400e'};">PIN Lock is ${tfaEnabled?'ENABLED':'DISABLED'}</div>
          <div style="font-size:11px;color:#6b7280;margin-top:3px;">${tfaEnabled?'App requires PIN to access':'Enable PIN for extra security'}</div>
        </div>
        <div style="margin-bottom:12px;">
          <label style="font-size:11px;font-weight:600;color:#374151;display:block;margin-bottom:4px;">Set App PIN (4-6 digits)</label>
          <input id="tfa-pin" type="password" maxlength="6" placeholder="${pinSet?'PIN is set — enter a new one to change':'Enter PIN'}" style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:14px;text-align:center;letter-spacing:8px;box-sizing:border-box;"/>
        </div>
        <div style="margin-bottom:12px;">
          <label style="font-size:11px;font-weight:600;color:#374151;display:block;margin-bottom:4px;">Confirm PIN</label>
          <input id="tfa-pin2" type="password" maxlength="6" placeholder="Confirm PIN" style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:14px;text-align:center;letter-spacing:8px;box-sizing:border-box;"/>
        </div>
        <div style="display:flex;gap:8px;">
          <button data-x-click="savePIN()" style="flex:1;padding:9px;background:#16a34a;color:#fff;border:none;border-radius:7px;font-size:12px;font-weight:700;cursor:pointer;">💾 Save PIN</button>
          <button data-x-click="toggleTFA()" style="flex:1;padding:9px;background:${tfaEnabled?'#fee2e2':'#dcfce7'};color:${tfaEnabled?'#dc2626':'#16a34a'};border:1px solid ${tfaEnabled?'#fca5a5':'#bbf7d0'};border-radius:7px;font-size:12px;font-weight:700;cursor:pointer;">${tfaEnabled?'🔓 Disable':'🔒 Enable'} PIN</button>
        </div>
      </div>
    </div>
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
      <div style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;padding:12px 16px;font-weight:700;font-size:13px;">🛡️ Security Settings</div>
      <div style="padding:16px;">
        ${[
          {key:'autoLock',label:'Auto-Lock After Inactivity',desc:'Lock app after 15 minutes of inactivity'},
          {key:'loginAlert',label:'Login Alerts',desc:'Show alert on each new login session'},
          {key:'exportPin',label:'Require PIN for Export',desc:'Ask for PIN before exporting data'},
          {key:'deleteConfirm',label:'Confirm Before Delete',desc:'Always ask confirmation before deleting'},
          {key:'sessionLog',label:'Log All Sessions',desc:'Record every login session automatically'}
        ].map(s=>`<div style="display:flex;justify-content:space-between;align-items:center;padding:10px 0;border-bottom:1px solid #f3f4f6;">
          <div>
            <div style="font-size:12px;font-weight:600;">${s.label}</div>
            <div style="font-size:10px;color:#9ca3af;">${escHTML(s.desc)}</div>
          </div>
          <label style="position:relative;display:inline-block;width:40px;height:22px;cursor:pointer;">
            <input type="checkbox" ${DB.settings?.[s.key]?'checked':''} data-x-change="saveSecuritySetting('${s.key}',this.checked)" style="opacity:0;width:0;height:0;">
            <span style="position:absolute;inset:0;background:${DB.settings?.[s.key]?'#16a34a':'#d1d5db'};border-radius:22px;transition:.3s;" id="sec-${s.key}"></span>
          </label>
        </div>`).join('')}
      </div>
    </div>
  </div>`;
}

function savePIN(){
  const pin=document.getElementById('tfa-pin')?.value;
  const pin2=document.getElementById('tfa-pin2')?.value;
  if(!pin||pin.length<4){alert('PIN must be at least 4 digits.');return;}
  if(pin!==pin2){alert('PINs do not match.');return;}
  if(!DB.settings) DB.settings={};
  /* SECURITY (2026-09-02): the PIN used to be written to storage in clear
     text, so it was readable in one DevTools line and rode along in every
     exported backup. It is stored hashed now (same hasher as passwords).
     Note this remains a convenience screen lock, not an auth boundary. */
  if(typeof window._erpHashPw==='function'){
    DB.settings.appPinHash=window._erpHashPw('pin:'+pin);
  }else{
    alert('Security module not ready — please reload and try again.');
    return;
  }
  delete DB.settings.appPin;
  saveDB();
  alert('✅ PIN saved successfully!');
}

function toggleTFA(){
  if(!DB.settings) DB.settings={};
  DB.settings.tfaEnabled=!DB.settings.tfaEnabled;
  saveDB();
  renderTwoFactorAuth();
}

function saveSecuritySetting(key,val){
  if(!DB.settings) DB.settings={};
  DB.settings[key]=val;
  const span=document.getElementById('sec-'+key);
  if(span) span.style.background=val?'#16a34a':'#d1d5db';
  saveDB();
}

