// ── Sales Tax Settings ──
function renderSalesTaxSettings(){
  const el=document.getElementById('sales-tax-settings-wrap');
  if(!el) return;
  const rate=isFinite(parseFloat(DB.settings?.salesTaxRate))?parseFloat(DB.settings.salesTaxRate):0.05;
  const enabled=DB.settings?.salesTaxEnabled!==false;
  const isDark=document.documentElement.getAttribute('data-theme')==='dark';
  const bg=isDark?'#1e293b':'#fff';
  const border=isDark?'#334155':'#e5e7eb';
  const textColor=isDark?'#f1f5f9':'#1a202c';
  const text2=isDark?'#94a3b8':'#6b7280';

  el.innerHTML=`
    <div style="background:${bg};border:1.5px solid ${border};border-radius:12px;padding:20px;margin-bottom:16px;">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;flex-wrap:wrap;gap:10px;">
        <div>
          <div style="font-size:15px;font-weight:800;color:#0f3d26;">🏛️ Sales Tax / Withholding Tax</div>
          <div style="font-size:12px;color:${text2};margin-top:2px;">Automatically deducted from sale amount at time of transaction</div>
        </div>
        <label style="display:flex;align-items:center;gap:8px;cursor:pointer;">
          <input type="checkbox" id="tax-enabled" ${enabled?'checked':''} data-x-change="saveSalesTaxSettings()"
            style="width:18px;height:18px;cursor:pointer;">
          <span style="font-size:13px;font-weight:700;color:${enabled?'#16a34a':'#dc2626'};">${enabled?'✅ Enabled':'❌ Disabled'}</span>
        </label>
      </div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;">
        <div>
          <label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:6px;">Tax Rate (%)</label>
          <div style="display:flex;align-items:center;gap:8px;">
            <input type="number" id="tax-rate-input" value="${rate}" min="0" max="100" step="0.01"
              data-x-change="saveSalesTaxSettings()"
              style="flex:1;padding:10px 12px;border:1.5px solid ${border};border-radius:8px;font-size:16px;font-weight:800;background:${bg};color:${textColor};">
            <span style="font-size:18px;font-weight:800;color:#374151;">%</span>
          </div>
          <div style="font-size:11px;color:${text2};margin-top:4px;">Current: <strong>${rate}%</strong> on gross sale amount</div>
        </div>
        <div>
          <label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:6px;">Tax Label</label>
          <input type="text" id="tax-label-input" value="${DB.settings?.salesTaxLabel||'Sales Tax'}"
            data-x-change="saveSalesTaxSettings()"
            style="width:100%;padding:10px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};">
          <div style="font-size:11px;color:${text2};margin-top:4px;">e.g. "Sales Tax", "VAT", "Withholding Tax"</div>
        </div>
      </div>
      <div style="margin-top:14px;padding:12px;background:${isDark?'#0f172a':'#f0fdf4'};border-radius:8px;border:1px solid ${isDark?'#16a34a33':'#bbf7d0'};">
        <div style="font-size:12px;font-weight:700;color:#16a34a;margin-bottom:6px;">📊 Example Calculation</div>
        <div style="font-size:12px;color:${textColor};">
          Sale Amount: <strong>৳10,000</strong><br>
          Tax (${rate}%): <strong style="color:#dc2626;">- ৳${(10000*rate/100).toFixed(2)}</strong><br>
          Net Payable: <strong style="color:#16a34a;">৳${(10000-10000*rate/100).toFixed(2)}</strong>
        </div>
      </div>
      <div style="margin-top:12px;display:flex;gap:10px;">
        <button data-x-click="saveSalesTaxSettings()" style="padding:10px 20px;background:#16a34a;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:13px;">
          💾 Save Tax Settings
        </button>
        <button data-x-click="previewTaxCalc()" style="padding:10px 20px;background:#2563eb;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:13px;">
          🧮 Test Calculator
        </button>
      </div>
    </div>

    <!-- Tax History Summary -->
    <div style="background:${bg};border:1.5px solid ${border};border-radius:12px;padding:18px;">
      <div style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:12px;">📋 Tax Collected Summary</div>
      ${(()=>{
        const taxTxs=(DB.tx||[]).filter(t=>t.salesTaxAmt>0);
        const totalTax=taxTxs.reduce((s,t)=>s+(t.salesTaxAmt||0),0);
        const thisMonth=new Date().toISOString().substring(0,7);
        const monthTax=taxTxs.filter(t=>(t.date||'').startsWith(thisMonth)).reduce((s,t)=>s+(t.salesTaxAmt||0),0);
        return taxTxs.length?`
          <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px;margin-bottom:14px;">
            <div class="kpi-card" style="border-left:4px solid #dc2626;">
              <div style="font-size:18px;">🏛️</div>
              <div style="font-size:20px;font-weight:900;color:#dc2626;">৳${totalTax.toLocaleString('en-IN',{minimumFractionDigits:2})}</div>
              <div style="font-size:10px;color:#6b7280;font-weight:700;">Total Tax Collected</div>
            </div>
            <div class="kpi-card" style="border-left:4px solid #d97706;">
              <div style="font-size:18px;">📅</div>
              <div style="font-size:20px;font-weight:900;color:#d97706;">৳${monthTax.toLocaleString('en-IN',{minimumFractionDigits:2})}</div>
              <div style="font-size:10px;color:#6b7280;font-weight:700;">This Month</div>
            </div>
            <div class="kpi-card" style="border-left:4px solid #7c3aed;">
              <div style="font-size:18px;">📊</div>
              <div style="font-size:20px;font-weight:900;color:#7c3aed;">${taxTxs.length}</div>
              <div style="font-size:10px;color:#6b7280;font-weight:700;">Taxed Transactions</div>
            </div>
          </div>
          <table class="tbl"><thead><tr><th>Date</th><th>Party</th><th>Sale Amount</th><th>Tax (${rate}%)</th><th>Net Paid</th></tr></thead>
          <tbody>${taxTxs.slice(0,10).map(t=>`<tr>
            <td>${t.date}</td>
            <td>${escHTML(t.party ||'—')}</td>
            <td>৳${txAmt(t).toLocaleString('en-IN',{minimumFractionDigits:2})}</td>
            <td style="color:#dc2626;font-weight:700;">- ৳${(t.salesTaxAmt||0).toLocaleString('en-IN',{minimumFractionDigits:2})}</td>
            <td style="color:#16a34a;font-weight:700;">৳${(t.netAmt!=null?t.netAmt:txAmt(t)).toLocaleString('en-IN',{minimumFractionDigits:2})}</td>
          </tr>`).join('')}</tbody></table>`
        :'<div style="text-align:center;padding:20px;color:#9ca3af;font-size:12px;">No taxed transactions yet. Enable tax and make a sale to see records here.</div>';
      })()}
    </div>`;
}

function saveSalesTaxSettings(){
  if(!DB.settings) DB.settings={};
  const _ri=parseFloat(document.getElementById('tax-rate-input')?.value);
  const rate=isFinite(_ri)?_ri:0.05;
  const enabled=document.getElementById('tax-enabled')?.checked!==false;
  const label=document.getElementById('tax-label-input')?.value||'Sales Tax';
  DB.settings.salesTaxRate=rate;
  DB.settings.salesTaxEnabled=enabled;
  DB.settings.salesTaxLabel=label;
  DB.taxRateUserSet=true;   // your choice stands; the 0.05% correction never overrides it
  try{ DB.rules=DB.rules||{}; DB.rules.salesTaxPct=rate; }catch(e){}
  saveDB();
  toast('✅ Tax settings saved! Rate: '+rate+'%','s');
  renderSalesTaxSettings();
  logAudit('SETTINGS','Tax','Sales tax rate set to '+rate+'%');
}

function previewTaxCalc(){
  const _ri=parseFloat(document.getElementById('tax-rate-input')?.value);
  const rate=isFinite(_ri)?_ri:0.05;
  const amt=parseFloat(prompt('Enter sale amount to test (৳):')||'0');
  if(!amt) return;
  const tax=amt*rate/100;
  const net=amt-tax;
  alert(`Tax Calculation Preview:\n\nSale Amount: ৳${amt.toLocaleString('en-IN',{minimumFractionDigits:2})}\nTax (${rate}%): - ৳${tax.toFixed(2)}\nNet Payable: ৳${net.toFixed(2)}\n\nThe customer pays ৳${net.toFixed(2)} after ${rate}% tax deduction.`);
}

