// ── Transaction Reset options ──
async function resetTxForm(){
  if(!await __confirm('Clear the whole form and start a fresh transaction?')) return;
  openModal('mTx'); // the fresh-open path clears every field and restores defaults
  const inv=document.getElementById('tx-inv'); if(inv){ inv.value=''; delete inv.dataset.autoGen; }
  txSectionsForType('');
  toast('Form reset — ready for a new transaction','s');
}
function resetAuditLog(action,detail,extra){
  try{
    if(!DB.auditLog) DB.auditLog=[];
    const session=JSON.parse(sessionStorage.getItem('ayan_session')||'{}');
    DB.auditLog.unshift({
      id:newId(),
      ts:new Date().toISOString(),
      action:action, module:'Reset Payments', detail:detail,
      user:session.username||(window.currentUser&&currentUser.name)||'admin',
      extra:extra||null
    });
    if(DB.auditLog.length>500) DB.auditLog=DB.auditLog.slice(0,500);
  }catch(e){}
}
function resetSnapshot(){
  const tx=(DB.tx||[]).length;
  /* FIX: the Opening Balances page's real store is DB.openingBalances (the
     array), not DB.openingBalance (singular) — counting only the singular
     object under-reported how much was actually about to be wiped. */
  const opening=(DB.openingBalance?Object.keys(DB.openingBalance).length:0)+(DB.openingBalances?DB.openingBalances.length:0);
  const cust=(DB.customers||[]).filter(c=>Number(c.bal||c.balance||0)!==0).length;
  const part=(DB.partners||[]).filter(p=>Number(p.cap||p.capital||0)!==0).length;
  const bank=(DB.banks||[]).length;
  const chq=(DB.cheques||[]).length;
  const inv=(DB.invoices||[]).length;
  const costDue=(DB.costLines||[]).filter(r=>Number(r.outstanding||0)>0).length;
  const transDue=(DB.transportDues||[]).filter(r=>Number(r.outstanding||0)>0).length;
  return {tx,opening,cust,part,bank,chq,inv,costDue,transDue};
}
function resetAllTransactions(){
  const s=resetSnapshot();
  if(!s.tx && !s.opening){ toast('There are no transactions to reset','e'); resetAuditLog('VIEW','Reset Payments opened — nothing to reset (0 transactions)'); return; }
  resetAuditLog('VIEW','Reset Payments confirmation opened — '+s.tx+' transactions, '+s.opening+' opening balances at risk');
  const ov=document.createElement('div');
  ov.id='resetConfirmOverlay';
  ov.style.cssText='position:fixed;inset:0;background:rgba(15,23,42,.62);z-index:99999;display:flex;align-items:center;justify-content:center;padding:16px;';
  ov.innerHTML=`<div style="background:#fff;border-radius:14px;max-width:520px;width:100%;max-height:92vh;overflow:auto;box-shadow:0 24px 60px rgba(0,0,0,.35);">
    <div style="background:linear-gradient(90deg,#991b1b,#dc2626);color:#fff;padding:14px 18px;font-weight:800;font-size:14px;">⚠️ Confirm Reset Payments</div>
    <div style="padding:18px;">
      <div style="font-size:12px;color:#374151;line-height:1.6;margin-bottom:12px;">
        This permanently deletes all transactions and zeros every balance.
        <b>Names of customers, suppliers, partners, products and banks are kept.</b>
        A backup file downloads first and a copy is stored in the Trash Bin.
      </div>
      <div style="border:1px solid #fecaca;background:#fef2f2;border-radius:10px;padding:12px;margin-bottom:14px;">
        <div style="font-size:11px;font-weight:800;color:#991b1b;margin-bottom:8px;">WILL BE DELETED</div>
        ${[['Transactions',s.tx],['Opening balances',s.opening],['Customer/supplier balances',s.cust],['Partner capital records',s.part],['Bank balances',s.bank],['Cheques',s.chq],['Invoices',s.inv],['Cost-line dues (Agent A/B, QC, Unload, Other)',s.costDue],['Transport/freight dues',s.transDue]].map(r=>`<div style="display:flex;justify-content:space-between;font-size:11.5px;padding:3px 0;color:#374151;"><span>${r[0]}</span><b>${r[1]}</b></div>`).join('')}
      </div>
      <label style="font-size:11.5px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Reason for this reset (recorded in Audit Log)</label>
      <input id="resetReason" placeholder="e.g. Starting new financial year" style="width:100%;padding:9px;border:1px solid #d1d5db;border-radius:8px;font-size:12px;margin-bottom:12px;">
      <label style="display:flex;gap:8px;align-items:flex-start;font-size:11.5px;color:#374151;margin-bottom:12px;cursor:pointer;">
        <input type="checkbox" id="resetBackupAck" style="margin-top:2px;"><span>I understand this cannot be undone and I have a backup.</span>
      </label>
      <label style="font-size:11.5px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Type <span style="color:#dc2626;font-weight:900;">RESET</span> to enable the button</label>
      <input id="resetConfirmWord" autocomplete="off" placeholder="RESET" style="width:100%;padding:9px;border:1.5px solid #d1d5db;border-radius:8px;font-size:13px;font-weight:800;letter-spacing:2px;text-transform:uppercase;margin-bottom:16px;">
      <div style="display:flex;gap:8px;">
        <button id="resetCancelBtn" style="flex:1;padding:10px;background:#f3f4f6;border:1px solid #d1d5db;border-radius:8px;font-size:12px;font-weight:700;cursor:pointer;">Cancel</button>
        <button id="resetGoBtn" disabled style="flex:1;padding:10px;background:#fca5a5;color:#fff;border:none;border-radius:8px;font-size:12px;font-weight:800;cursor:not-allowed;">↺ Reset Payments</button>
      </div>
    </div>
  </div>`;
  document.body.appendChild(ov);
  const word=ov.querySelector('#resetConfirmWord'), ack=ov.querySelector('#resetBackupAck'), go=ov.querySelector('#resetGoBtn');
  const sync=()=>{
    const ok = word.value.trim().toUpperCase()==='RESET' && ack.checked;
    go.disabled=!ok;
    go.style.background=ok?'#dc2626':'#fca5a5';
    go.style.cursor=ok?'pointer':'not-allowed';
  };
  word.addEventListener('input',sync); ack.addEventListener('change',sync);
  const close=(cancelled)=>{
    if(cancelled) resetAuditLog('VIEW','Reset Payments cancelled by user — no data changed');
    ov.remove();
  };
  ov.querySelector('#resetCancelBtn').onclick=()=>close(true);
  ov.addEventListener('mousedown',e=>{ if(e.target===ov) close(true); });
  go.onclick=()=>{
    if(go.disabled) return;
    const reason=(ov.querySelector('#resetReason').value||'').trim()||'No reason given';
    ov.remove();
    performResetAllTransactions(reason,s);
  };
  setTimeout(()=>word.focus(),50);
}
function performResetAllTransactions(reason,s){
  const n=(DB.tx||[]).length;
  try{ if(typeof backupData==='function') backupData(); }catch(e){}
  if(!DB.trash) DB.trash=[];
  DB.trash.unshift({
    _type:'txBulkReset',_deletedAt:new Date().toISOString(),count:n,_reason:reason,
    data:DB.tx, openingBalance:DB.openingBalance,
    /* FIX: DB.openingBalances (the array the rebuilt Opening Balances page
       actually reads for customers/suppliers) was never backed up here, so
       clearing it below would have lost that data with no way back. */
    openingBalances:JSON.parse(JSON.stringify(DB.openingBalances||[])),
    customers:JSON.parse(JSON.stringify(DB.customers||[])),
    partners:JSON.parse(JSON.stringify(DB.partners||[])),
    banks:JSON.parse(JSON.stringify(DB.banks||[])),
    products:JSON.parse(JSON.stringify(DB.products||[]))
  });
  DB.tx=[]; DB.transactions=[];
  DB.openingBalance={};
  DB.openingBalances=[];
  (DB.customers||[]).forEach(c=>{ c.bal=0; c.balance=0; c.openingBal=0; });
  (DB.partners||[]).forEach(p=>{ p.cap=0; p.capital=0; });
  /* FIX: the Opening Balances page reads bank.openingBal (falling back to
     bank.bal only when openingBal is unset) and product.openingStock /
     product.rate — zeroing only bank.bal and product.qty/stock (the old,
     no-longer-read fields) left every bank and every product's opening
     figures exactly as they were, so this "reset" would not actually have
     produced the blank Opening Balances page it promises. */
  (DB.banks||[]).forEach(b=>{ b.bal=0; if(b.balance!==undefined) b.balance=0; if(b.openingBal!==undefined) b.openingBal=0; });
  (DB.products||[]).forEach(p=>{ p.qty=0; if(p.stock!==undefined) p.stock=0; if(p.openingStock!==undefined) p.openingStock=0; if(p.rate!==undefined) p.rate=0; });
  DB.cheques=[]; DB.cityFinance=[]; DB.stockAdjustments=[];
  DB.invoices=[]; DB.challans=[]; DB.paySchedules=[]; DB.dailyPrices=[];
  /* FIX: Agent A/B, QC, Unload & Other cost-line dues and freight/transport
     dues are recorded in their own arrays (DB.costLines, DB.transportDues),
     populated when the now-deleted transactions were saved. Reset Payments
     forgot these two, so the dashboard's Cost Dues KPI kept showing money
     owed against transactions that no longer existed. Back them up into the
     same trash snapshot as everything else, then clear them. */
  DB.trash[0].costLines = JSON.parse(JSON.stringify(DB.costLines||[]));
  DB.trash[0].transportDues = JSON.parse(JSON.stringify(DB.transportDues||[]));
  DB.costLines=[]; DB.transportDues=[];
  try{ if(typeof W.refreshCostLineBadge==='function') W.refreshCostLineBadge(); }catch(e){}
  resetAuditLog('DELETE','Reset Payments executed — reason: '+reason+' | deleted '+s.tx+' transactions, '+s.opening+' opening balances, '+s.chq+' cheques, '+s.inv+' invoices; zeroed '+s.cust+' party balances, '+s.part+' partner capitals, '+s.bank+' bank balances; cleared outstanding cost-line and transport dues. Names kept. Backup downloaded + copy in Trash Bin.',{reason:reason,snapshot:s});
  saveDB();
  nav('auditlog');
  toast(n+' transactions and all balances cleared — logged in the Audit Log, copy kept in Trash Bin','s');
}
async function settingsFactoryReset(){
  if(!await __confirm('⚠️ This will ERASE ALL DATA in this browser.\n\nHave you downloaded a backup?')) return;
  if(!await __confirm('FINAL CONFIRMATION:\nDelete everything and start fresh?')) return;
  try{ if(typeof backupData==='function') backupData(); }catch(e){}
  /* This app is server-only storage (see the guard at the top of this file):
     the real database lives in MySQL behind api.php, not in the browser.
     Clearing localStorage alone leaves the server copy untouched, so the
     very next api.php?action=load on reload silently brings all the old
     data straight back — that is why Factory Reset looked like it "did
     nothing". Erase the in-memory DB and push that empty state to the
     server first, THEN clear local storage and reload. */
  W.DB = {};
  try{
    if(typeof W.saveDBNow==='function') await W.saveDBNow();
    else if(typeof W.saveDB==='function') W.saveDB();
  }catch(e){}
  try{ localStorage.clear(); }catch(e){}
  location.reload();
}
function saveAllSettings(){
  if(!DB.settings) DB.settings={};
  document.querySelectorAll('[id^="cfg2-"]').forEach(el=>{
    const key=el.id.replace('cfg2-','');
    DB.settings[key]=el.value;
  });
  saveDB();
  if(typeof addAuditEntry==='function') addAuditEntry('UPDATE','Settings','System settings updated');
  alert('✅ Settings saved!');
}

