async function compactDatabase(){
  if(!await __confirm('Compact database? This removes empty fields to save space.')) return;
  const compact=(obj)=>{
    if(Array.isArray(obj)) return obj.map(compact);
    if(obj&&typeof obj==='object'){
      const out={};
      Object.entries(obj).forEach(([k,v])=>{
        if(v!==null&&v!==undefined&&v!=='') out[k]=compact(v);
      });
      return out;
    }
    return obj;
  };
  const before=JSON.stringify(DB).length;
  const compacted=compact(DB);
  Object.assign(DB,compacted);
  saveDB();
  const after=JSON.stringify(DB).length;
  renderOptimizeDatabase();
  alert('✅ Database compacted! Saved '+(before-after)+' bytes.');
}

async function resetDatabase(){
  if(!await __confirm('⚠️ WARNING: This will DELETE ALL DATA permanently. Are you absolutely sure?')) return;
  if(!await __confirm('⚠️ FINAL WARNING: All transactions, parties, products, and settings will be lost. Type OK to confirm.')) return;
  /* FIX: this used to remove 'ayanAgroDB' from localStorage and reload —
     wrong key (loadDB() persists under 'rbo_v4'), and the wrong layer
     anyway: saveDB() syncs to the cloud, which is authoritative, so a
     reload just pulls the untouched server copy straight back down.
     No localStorage needed here at all: assign the INIT snapshot onto
     the live DB (same pattern restoreData() uses) — party/bank/partner/
     product NAMES are kept, every balance/capital/value on them is zero,
     and DB.transactions/DB.agents/DB.agentLedger go through empty, which
     also clears the real DB.tx store via the transactions accessor. */
  Object.assign(DB, JSON.parse(JSON.stringify(INIT)));
  DB.tx = [];
  DB.openingBal = {customers:{},banks:{},partners:{},assets:{},suppliers:{}};
  try{ tidyRestoredDB(); }catch(e){ if(window.reportSilentError) reportSilentError('reset', e.message, 'tidyRestoredDB'); }
  try{ applyPartyMaster(); }catch(e){ if(window.reportSilentError) reportSilentError('reset', e.message, 'applyPartyMaster'); }
  saveDB();
  render();
  toast('✅ Database reset: names kept, all amounts zeroed, transactions cleared.', 's');
}

