// ── WhatsApp ───────────────────────────────────────────────────
function renderWhatsApp(){
  /* FIX: the WhatsApp page rendered blank because renderWhatsAppHub() always
     targeted #pg-whatsapphub (the other page) when both pages exist.
     Pass the page we are actually on. */
  renderWhatsAppHub('pg-whatsapp');
}

function loadWAParty(phone){
  const el=document.getElementById('wa-phone');
  if(el) el.value=phone;
}

function loadWATemplate(type){
  const templates={
    greeting:'আস-সালামু আলাইকুম! Ayan Agro ERP International Limited থেকে শুভেচ্ছা। আপনার সাথে ব্যবসা করতে পেরে আমরা আনন্দিত।',
    payment_due:'আস-সালামু আলাইকুম! আপনার পেমেন্ট বাকি আছে। অনুগ্রহ করে যোগাযোগ করুন। - Ayan Agro ERP',
    invoice:'আস-সালামু আলাইকুম! আপনার ইনভয়েস তৈরি হয়েছে। বিস্তারিত জানতে যোগাযোগ করুন। - Ayan Agro ERP',
    statement:'আস-সালামু আলাইকুম! আপনার অ্যাকাউন্ট স্টেটমেন্ট পাঠানো হলো। - Ayan Agro ERP'
  };
  const el=document.getElementById('wa-message');
  if(el&&templates[type]) el.value=templates[type];
}

function openWhatsApp(){
  const phone=document.getElementById('wa-phone')?.value?.replace(/[^0-9+]/g,'');
  const msg=document.getElementById('wa-message')?.value;
  if(!phone){alert('Please enter a phone number.');return;}
  const url='https://wa.me/'+phone.replace('+','')+'?text='+encodeURIComponent(msg||'');
  window.open(url,'_blank');
}

function quickWA(phone,name){
  const msg='আস-সালামু আলাইকুম '+name+'! Ayan Agro ERP থেকে যোগাযোগ করা হচ্ছে।';
  const url='https://wa.me/'+phone.replace(/[^0-9]/g,'')+'?text='+encodeURIComponent(msg);
  window.open(url,'_blank');
}

// ── Email Notifications ────────────────────────────────────────
function renderEmailNotifications(){
  const body=ensureDivIn('pg-emailnotifications','email-body');
  if(!body) return;
  const s=DB.settings||{};

  body.innerHTML=`<div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;">
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
      <div style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;padding:12px 16px;font-weight:700;font-size:13px;">📧 Email Settings</div>
      <div style="padding:16px;">
        <div style="background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px;padding:10px;margin-bottom:12px;font-size:11px;color:#1e40af;">
          Configure SMTP settings to send emails directly from the system.
        </div>
        ${[
          {key:'emailFrom',label:'From Email',type:'email',placeholder:'noreply@ayanagro.com'},
          {key:'emailFromName',label:'From Name',type:'text',placeholder:'Ayan Agro ERP'},
          {key:'smtpHost',label:'SMTP Host',type:'text',placeholder:'smtp.gmail.com'},
          {key:'smtpPort',label:'SMTP Port',type:'number',placeholder:'587'},
          {key:'smtpUser',label:'SMTP Username',type:'email',placeholder:'your@gmail.com'},
          {key:'smtpPass',label:'SMTP Password',type:'password',placeholder:'App password'}
        ].map(f=>`<div style="margin-bottom:8px;">
          <label style="font-size:11px;font-weight:600;color:#374151;display:block;margin-bottom:3px;">${f.label}</label>
          <input type="${f.type}" id="em-${f.key}" value="${s[f.key]||''}" placeholder="${f.placeholder}"
            style="width:100%;padding:7px 10px;border:1px solid #d1d5db;border-radius:5px;font-size:12px;box-sizing:border-box;"/>
        </div>`).join('')}
        <div style="display:flex;gap:8px;margin-top:10px;">
          <button data-x-click="saveEmailSettings()" style="flex:1;padding:8px;background:#16a34a;color:#fff;border:none;border-radius:7px;font-size:12px;font-weight:700;cursor:pointer;">💾 Save</button>
          <button data-x-click="testEmail()" style="flex:1;padding:8px;background:#2563eb;color:#fff;border:none;border-radius:7px;font-size:12px;font-weight:700;cursor:pointer;">📤 Test</button>
        </div>
      </div>
    </div>
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
      <div style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;padding:12px 16px;font-weight:700;font-size:13px;">🔔 Email Notification Triggers</div>
      <div style="padding:16px;">
        ${[
          {key:'emailOnSale',label:'New Sale Notification',desc:'Email when a sale is recorded'},
          {key:'emailOnPayment',label:'Payment Received',desc:'Email when payment is received'},
          {key:'emailOnDue',label:'Payment Due Reminder',desc:'Email 3 days before due date'},
          {key:'emailOnOverdue',label:'Overdue Alert',desc:'Email for overdue payments'},
          {key:'emailDailySummary',label:'Daily Summary',desc:'Daily business summary email'},
          {key:'emailWeeklyReport',label:'Weekly Report',desc:'Weekly performance report'},
          {key:'emailMonthlyReport',label:'Monthly Report',desc:'Monthly financial report'},
          {key:'emailLowStock',label:'Low Stock Alert',desc:'Email when stock is low'}
        ].map(t=>`<div style="display:flex;justify-content:space-between;align-items:center;padding:8px 0;border-bottom:1px solid #f3f4f6;">
          <div>
            <div style="font-size:12px;font-weight:600;">${t.label}</div>
            <div style="font-size:10px;color:#9ca3af;">${escHTML(t.desc)}</div>
          </div>
          <label style="position:relative;display:inline-block;width:40px;height:22px;cursor:pointer;">
            <input type="checkbox" ${s[t.key]?'checked':''} data-x-change="saveEmailTrigger('${t.key}',this.checked)" style="opacity:0;width:0;height:0;">
            <span style="position:absolute;inset:0;background:${s[t.key]?'#16a34a':'#d1d5db'};border-radius:22px;transition:.3s;"></span>
          </label>
        </div>`).join('')}
      </div>
    </div>
  </div>`;
}

function saveEmailSettings(){
  if(!DB.settings) DB.settings={};
  ['emailFrom','emailFromName','smtpHost','smtpPort','smtpUser','smtpPass'].forEach(k=>{
    const el=document.getElementById('em-'+k);
    if(el) DB.settings[k]=el.value;
  });
  saveDB();
  alert('✅ Email settings saved!');
}

function saveEmailTrigger(key,val){
  if(!DB.settings) DB.settings={};
  DB.settings[key]=val;
  saveDB();
}

function testEmail(){
  alert(`📧 Email test requires live SMTP configuration.

For Gmail: Enable 2FA and create an App Password.
For other providers: Use their SMTP credentials.`);
}

