// ── Payment Reminders ──────────────────────────────────────────
function renderPaymentReminders(){
  const body=ensureDivIn('pg-paymentreminders','pr-body');
  if(!body) return;
  const parties=DB.parties||[];
  const txns=DB.tx||[];

  // Calculate outstanding balances
  const outstanding=parties.filter(p=>isCustomerParty(p)).map(p=>{
    const sales=txns.filter(t=>t.party===p.name&&isRevenueTx(t)).reduce((s,t)=>s+txAmt(t),0);
    const receipts=txns.filter(t=>t.party===p.name&&t.type==='Sales Receipt').reduce((s,t)=>s+txAmt(t),0);
    const balance=sales-receipts+(p.bal||0);
    return {...p,outstanding:balance};
  }).filter(p=>p.outstanding>0).sort((a,b)=>b.outstanding-a.outstanding);

  body.innerHTML=`<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:16px;">
    ${[
      {label:'Customers with Due',val:outstanding.length,icon:'👥',color:'#f59e0b'},
      {label:'Total Outstanding',val:'৳'+pf(outstanding.reduce((s,p)=>s+p.outstanding,0)),icon:'💰',color:'#dc2626'},
      {label:'Reminders Sent',val:(DB.reminderLog||[]).length,icon:'📱',color:'#16a34a'}
    ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
      <div style="font-size:22px;">${c.icon}</div>
      <div style="font-size:${typeof c.val==='string'&&c.val.length>8?'13':'17'}px;font-weight:900;color:${c.color};">${c.val}</div>
      <div style="font-size:11px;color:#6b7280;margin-top:4px;">${c.label}</div>
    </div>`).join('')}
  </div>
  <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
    <div style="background:linear-gradient(90deg,#f59e0b,#d97706);color:#fff;padding:12px 16px;font-weight:700;font-size:13px;">⏰ Outstanding Payments — Send Reminders</div>
    ${outstanding.length?`<table style="width:100%;border-collapse:collapse;font-size:12px;">
      <thead><tr style="background:#fefce8;">
        <th style="padding:9px 12px;text-align:left;color:#92400e;">Customer</th>
        <th style="padding:9px 12px;text-align:left;color:#92400e;">Phone</th>
        <th style="padding:9px 12px;text-align:right;color:#92400e;">Outstanding (৳)</th>
        <th style="padding:9px 12px;text-align:center;color:#92400e;">Send Reminder</th>
      </tr></thead>
      <tbody>${outstanding.map((p,i)=>`<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#fefce8':'#fff'};">
        <td style="padding:8px 12px;font-weight:700;">${escHTML(p.name)}</td>
        <td style="padding:8px 12px;color:#6b7280;">${escHTML(p.phone ||'—')}</td>
        <td style="padding:8px 12px;text-align:right;font-weight:800;color:#dc2626;">৳${pf(p.outstanding)}</td>
        <td style="padding:8px 12px;text-align:center;display:flex;gap:6px;justify-content:center;">
          ${p.phone?`<button data-x-click="sendWAReminder('${escJSAttr(p.phone)}','${escJSAttr(p.name)}',${p.outstanding})" style="background:#dcfce7;color:#16a34a;border:none;border-radius:5px;padding:4px 8px;font-size:10px;cursor:pointer;font-weight:700;">💬 WA</button>`:''}
          <button data-x-click="sendSMSReminder('${escHTML(p.name)}',${p.outstanding})" style="background:#eff6ff;color:#2563eb;border:none;border-radius:5px;padding:4px 8px;font-size:10px;cursor:pointer;font-weight:700;">📱 SMS</button>
        </td>
      </tr>`).join('')}</tbody>
    </table>`:'<div style="padding:40px;text-align:center;color:#9ca3af;">No outstanding payments. All customers are up to date! ✅</div>'}
  </div>`;
}

function sendWAReminder(phone,name,amount){
  const msg=`আস-সালামু আলাইকুম ${name}! আপনার বকেয়া পেমেন্ট ৳${pf(amount)} পরিশোধ করার জন্য অনুরোধ করা হচ্ছে। - Ayan Agro ERP International Limited`;
  const url='https://wa.me/'+phone.replace(/[^0-9]/g,'')+'?text='+encodeURIComponent(msg);
  window.open(url,'_blank');
  if(!DB.reminderLog) DB.reminderLog=[];
  DB.reminderLog.unshift({ts:Date.now(),party:name,method:'WhatsApp',amount});
  saveDB();
}

function sendSMSReminder(name,amount){
  if(!DB.reminderLog) DB.reminderLog=[];
  DB.reminderLog.unshift({ts:Date.now(),party:name,method:'SMS',amount});
  saveDB();
  alert('📱 SMS reminder queued for '+name+' (৳'+pf(amount)+').\n\nRequires SMS gateway configuration.');
}

// ── Alerts ─────────────────────────────────────────────────────
function renderAlerts(){
  const body=document.getElementById('alerts-body');
  if(!body) return;

  // Generate alerts from data
  const alerts=[];
  const today=new Date().toISOString().split('T')[0];

  // Low stock alerts
  (DB.products||[]).forEach(p=>{
    if((p.stock||0)<=(p.minStock||10)&&p.name){
      alerts.push({type:'warning',icon:'📦',title:'Low Stock: '+p.name,detail:'Current stock: '+(p.stock||0)+' '+( p.unit||'units')+' (Min: '+(p.minStock||10)+')',ts:Date.now(),category:'Inventory'});
    }
  });

  // High outstanding alerts
  (DB.parties||[]).filter(p=>(p.type==='Customer'||p.type==='Both')&&(p.bal||0)>500000).forEach(p=>{
    alerts.push({type:'danger',icon:'💰',title:'High Outstanding: '+p.name,detail:'Balance: ৳'+pf(p.bal||0),ts:Date.now(),category:'Finance'});
  });

  // Tender deadline alerts
  (DB.tenders||[]).filter(t=>t.submitDate&&t.submitDate>=today&&t.status==='Preparing').forEach(t=>{
    const days=Math.ceil((new Date(t.submitDate)-new Date())/86400000);
    if(days<=7) alerts.push({type:'warning',icon:'📋',title:'Tender Deadline: '+t.title,detail:'Submit by: '+t.submitDate+' ('+days+' days left)',ts:Date.now(),category:'Tenders'});
  });

  // Pending approvals
  const pendingCount=(DB.tx||[]).filter(t=>t.status==='Pending').length;
  if(pendingCount>0) alerts.push({type:'info',icon:'⏳',title:pendingCount+' Pending Approvals',detail:'Transactions awaiting approval',ts:Date.now(),category:'Admin'});

  // Merge with stored alerts
  const storedAlerts=DB.alerts||[];
  const allAlerts=[...alerts,...storedAlerts].slice(0,50);

  const typeColors={warning:'#f59e0b',danger:'#dc2626',info:'#2563eb',success:'#16a34a'};

  body.innerHTML=`<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:16px;">
    ${['warning','danger','info','success'].map(t=>{
      const count=allAlerts.filter(a=>a.type===t).length;
      const labels={warning:'Warnings',danger:'Critical',info:'Info',success:'Success'};
      const icons={warning:'⚠️',danger:'🚨',info:'ℹ️',success:'✅'};
      return `<div style="background:#fff;border:2px solid ${typeColors[t]}22;border-radius:10px;padding:14px;text-align:center;">
        <div style="font-size:22px;">${icons[t]}</div>
        <div style="font-size:17px;font-weight:900;color:${typeColors[t]};">${count}</div>
        <div style="font-size:11px;color:#6b7280;margin-top:4px;">${labels[t]}</div>
      </div>`;
    }).join('')}
  </div>
  <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
    <div style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;padding:12px 16px;font-weight:700;font-size:13px;">🔔 Active Alerts (${allAlerts.length})</div>
    ${allAlerts.length?`<div style="padding:12px;display:flex;flex-direction:column;gap:8px;">
      ${allAlerts.map((a,i)=>{
        const color=typeColors[a.type]||'#6b7280';
        return `<div style="display:flex;align-items:flex-start;gap:12px;padding:10px 12px;border:1px solid ${color}22;border-left:4px solid ${color};border-radius:8px;background:${color}08;">
          <span style="font-size:20px;">${a.icon}</span>
          <div style="flex:1;">
            <div style="font-weight:700;font-size:12px;color:${color};">${escHTML(a.title)}</div>
            <div style="font-size:11px;color:#6b7280;margin-top:2px;">${a.detail}</div>
            <div style="font-size:10px;color:#9ca3af;margin-top:2px;">${escHTML(a.category)} • ${new Date(a.ts).toLocaleString('en-BD')}</div>
          </div>
          <button data-x-click="dismissAlert(${i})" style="background:none;border:none;color:#9ca3af;cursor:pointer;font-size:14px;">✕</button>
        </div>`;
      }).join('')}
    </div>`:'<div style="padding:40px;text-align:center;"><div style="font-size:40px;margin-bottom:8px;">✅</div><div style="font-size:16px;font-weight:700;color:#16a34a;">No Active Alerts</div><div style="font-size:12px;color:#9ca3af;margin-top:4px;">All systems are running normally.</div></div>'}
  </div>`;
}

function dismissAlert(idx){
  if(!DB.alerts) DB.alerts=[];
  if(!DB.orders) DB.orders=[];
  if(!DB.reminders) DB.reminders=[];
  if(!DB.rawMaterials) DB.rawMaterials=[];
  if(!DB.qcRecords) DB.qcRecords=[];
  if(!DB.maintenance) DB.maintenance=[];
  if(!DB.syncLog) DB.syncLog=[];
  if(!DB.goals) DB.goals={};
  if(!DB.goalHistory) DB.goalHistory=[];
  DB.alerts=(DB.alerts||[]).filter((_,i)=>i!==idx);
  saveDB();
  renderAlerts();
}

async function clearAllAlerts(){
  if(!await __confirm('Clear all stored alerts?')) return;
  DB.alerts=[];
  saveDB();
  renderAlerts();
}

// ── Google Drive Backup ────────────────────────────────────────
function renderGoogleDriveBackup(){
  // Auto-inject page structure if needed
  (function(){
    const _pg=document.getElementById('pg-googledrivebackup');
    if(_pg&&!_pg.querySelector('[id]')){
      _pg.innerHTML=`<div style="padding:20px;"><div id=\"gdb-body\"></div></div>`;
    }
  })();
  const body=document.getElementById('gdb-body');
  if(!body) return;
  const lastBackup=DB.settings?.lastGDriveBackup;

  body.innerHTML=`<div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;">
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
      <div style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;padding:12px 16px;font-weight:700;font-size:13px;">☁️ Google Drive Integration</div>
      <div style="padding:16px;">
        <div style="text-align:center;padding:20px 0;">
          <div style="font-size:48px;margin-bottom:12px;">☁️</div>
          <div style="font-weight:700;font-size:16px;color:#0f3d26;margin-bottom:6px;">Google Drive Backup</div>
          <div style="font-size:12px;color:#6b7280;margin-bottom:16px;">Automatically backup your data to Google Drive for safe cloud storage.</div>
          <div style="background:#fef3c7;border:1px solid #fcd34d;border-radius:8px;padding:12px;font-size:11px;color:#92400e;text-align:left;margin-bottom:16px;">
            ⚠️ Google Drive integration requires OAuth 2.0 setup. This is a browser-based app — use the manual backup option below for reliable cloud storage.
          </div>
          <button data-x-click="manualGDriveBackup()" style="width:100%;padding:10px;background:#4285F4;color:#fff;border:none;border-radius:8px;font-size:13px;font-weight:700;cursor:pointer;margin-bottom:8px;">📤 Download Backup File</button>
          <div style="font-size:11px;color:#9ca3af;">Then manually upload to Google Drive</div>
          ${lastBackup?`<div style="margin-top:12px;font-size:11px;color:#16a34a;">Last backup: ${new Date(lastBackup).toLocaleString('en-BD')}</div>`:''}
        </div>
      </div>
    </div>
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
