          ${['All Transactions','Parties & Contacts','Products & Inventory','Bank Accounts','Tenders','Settings & Config','Audit Log'].map(i=>`<div style="font-size:11px;color:#374151;padding:2px 0;">✅ ${i}</div>`).join('')}
        </div>
        <button data-x-click="manualGDriveBackup()" style="width:100%;padding:9px;background:#16a34a;color:#fff;border:none;border-radius:7px;font-size:12px;font-weight:700;cursor:pointer;">💾 Backup Now</button>
      </div>
    </div>
  </div>`;
}

function manualGDriveBackup(){
  if(typeof backupData==='function'){
    backupData();
    if(!DB.settings) DB.settings={};
    DB.settings.lastGDriveBackup=Date.now();
    saveDB();
    alert('✅ Backup file downloaded! Upload it to Google Drive for cloud storage.');
  } else {
    const data=JSON.stringify(DB,null,2);
    const blob=new Blob([data],{type:'application/json'});
    const url=URL.createObjectURL(blob);
    const a=document.createElement('a');
    a.href=url;
    a.download='AyanAgro_GDrive_Backup_'+new Date().toISOString().split('T')[0]+'.json';
    a.click();
  }
}


