async function recalculateBalances(){
  if(!await __confirm('Recalculate all party balances from transaction history?')) return;
  const parties=DB.parties||[];
  const txns=DB.tx||[];
  let updated=0;
  parties.forEach(p=>{
    /* FIX M: two bugs in this balance recalculation:
       1) 'Sales Advance'/'Purchase Advance' were counted as new debit (owed),
          but an advance is money already received/paid — it should reduce
          the balance, same side as a receipt/payment.
       2) supplier balance was purchases-payments, the OPPOSITE sign from the
          convention documented in ayan-db-bridge ("supplier bal<0 => we owe
          the supplier") and from the sign partyBuckets()/'Both' already used
          below — flipped to payments-purchases so all three agree. */
    const sales=txns.filter(t=>t.party===p.name&&window.isRevenueTx(t)).reduce((s,t)=>s+txAmt(t),0);
    const receipts=txns.filter(t=>t.party===p.name&&['Sales Receipt','Sales Advance','Cash Received'].includes(t.type)).reduce((s,t)=>s+txAmt(t),0);
    const purchases=txns.filter(t=>t.party===p.name&&window.isCogsTx(t)).reduce((s,t)=>s+txAmt(t),0);
    const payments=txns.filter(t=>t.party===p.name&&['Purchase Payment','Purchase Advance'].includes(t.type)).reduce((s,t)=>s+txAmt(t),0);
    if(p.type==='Customer') p.bal=sales-receipts;
    else if(p.type==='Supplier') p.bal=payments-purchases;
    else if(p.type==='Both') p.bal=(sales-receipts)+(payments-purchases);
    updated++;
  });
  saveDB();
  alert('✅ Recalculated balances for '+updated+' parties!');
}

function fixDuplicateIDs(){
  const txns=DB.tx||[];
  const seen=new Set();
  let fixed=0;
  txns.forEach(t=>{
    if(seen.has(t.id)){t.id=Date.now()+Math.random();fixed++;}
    else seen.add(t.id);
  });
  if(fixed>0){saveDB();alert('✅ Fixed '+fixed+' duplicate IDs!');}
  else alert('✅ No duplicate IDs found. Data is clean!');
}

function validateDataIntegrity(){
  const issues=[];
  (DB.tx||[]).forEach((t,i)=>{
    if(!t.id) issues.push('Transaction #'+i+': Missing ID');
    if(!t.date) issues.push('Transaction #'+i+': Missing date');
    if(!t.type) issues.push('Transaction #'+i+': Missing type');
    if(isNaN(txAmt(t))) issues.push('Transaction #'+i+': Invalid amount');
  });
  (DB.parties||[]).forEach((p,i)=>{
    if(!p.name) issues.push('Party #'+i+': Missing name');
  });
  if(issues.length===0) alert('✅ Data integrity check passed! No issues found.');
  else alert('⚠️ Found '+issues.length+' issues:\n\n'+issues.slice(0,10).join('\n')+(issues.length>10?'\n...and '+(issues.length-10)+' more':''));
}

function rebuildSearchIndex(){
  // Rebuild in-memory search cache
  window._searchCache={
    transactions:(DB.tx||[]).map(t=>({id:t.id,text:(t.party+' '+t.type+' '+t.product+' '+t.amount).toLowerCase()})),
    parties:(DB.parties||[]).map(p=>({id:p.id,text:(p.name+' '+p.type+' '+p.phone).toLowerCase()}))
  };
  alert('✅ Search index rebuilt! '+((DB.tx||[]).length)+' transactions indexed.');
}

function runDiagnostics(){
  const out=document.getElementById('diagnostics-output');
  if(!out) return;
  const dbSize=JSON.stringify(DB).length;
  const txns=DB.tx||[];
  const parties=DB.parties||[];
  const checks=[
    {label:'Database accessible',pass:true},
    {label:'Browser storage disabled (server-only mode)',pass:!!(window.ERP_SERVER_MODE)},
    {label:'Transactions array valid',pass:Array.isArray(txns)},
    {label:'Parties array valid',pass:Array.isArray(parties)},
    {label:'DB size within limits',pass:dbSize<50*1024*1024},
    {label:'No null transactions',pass:txns.every(t=>t!==null)},
    {label:'All transactions have IDs',pass:txns.every(t=>t.id)},
    {label:'All parties have names',pass:parties.every(p=>p.name)},
    {label:'Settings object exists',pass:!!DB.settings},
    {label:'saveDB function available',pass:typeof saveDB==='function'}
  ];
  out.innerHTML=`<div style="font-size:12px;font-weight:700;color:#374151;margin-bottom:10px;">Diagnostics Results:</div>
    ${checks.map(c=>`<div style="display:flex;justify-content:space-between;padding:5px 0;border-bottom:1px solid #f3f4f6;font-size:11px;">
      <span>${c.label}</span>
      <span style="font-weight:700;color:${c.pass?'#16a34a':'#dc2626'};">${c.pass?'✅ PASS':'❌ FAIL'}</span>
    </div>`).join('')}
    <div style="margin-top:10px;padding:8px;background:#f0fdf4;border-radius:6px;font-size:11px;color:#166534;">
      ${checks.filter(c=>c.pass).length}/${checks.length} checks passed
    </div>`;
}

