    <div style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;padding:12px 16px;font-weight:700;font-size:13px;">📋 Audit Trail (${log.length} events)</div>
    ${log.length?`<table style="width:100%;border-collapse:collapse;font-size:12px;">
      <thead><tr style="background:#f0fdf4;">
        <th style="padding:9px 12px;text-align:left;color:#0f3d26;">Timestamp</th>
        <th style="padding:9px 12px;text-align:left;color:#0f3d26;">Action</th>
        <th style="padding:9px 12px;text-align:left;color:#0f3d26;">Module</th>
        <th style="padding:9px 12px;text-align:left;color:#0f3d26;">Detail</th>
      </tr></thead>
      <tbody>${log.slice(0,100).map((l,i)=>{
        const actionColor=l.action==='CREATE'?'#16a34a':l.action==='DELETE'?'#dc2626':l.action==='UPDATE'?'#f59e0b':'#6b7280';
        return `<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
          <td style="padding:7px 12px;color:#6b7280;font-size:11px;">${new Date(l.ts).toLocaleString('en-BD')}</td>
          <td style="padding:7px 12px;"><span style="background:${actionColor}22;color:${actionColor};padding:2px 8px;border-radius:8px;font-size:10px;font-weight:700;">${l.action}</span></td>
          <td style="padding:7px 12px;font-weight:600;">${l.module||'—'}</td>
          <td style="padding:7px 12px;color:#374151;">${l.detail||'—'}</td>
        </tr>`;
      }).join('')}</tbody>
    </table>`:'<div style="padding:40px;text-align:center;color:#9ca3af;">No audit events recorded yet.</div>'}
  </div>`;
}

function exportAuditLog(){
  const log=DB.auditLog||[];
  if(!log.length){alert('No audit log to export.');return;}
  const headers=['Timestamp','Action','Module','Detail'];
  const rows=log.map(l=>[new Date(l.ts).toLocaleString('en-BD'),l.action,l.module||'',l.detail||''].map(v=>__csvCell(v)).join(','));
  const csv=[headers.join(','),...rows].join('\n');
  const blob=new Blob([csv],{type:'text/csv'});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');
  a.href=url;a.download='audit_log_'+new Date().toISOString().split('T')[0]+'.csv';a.click();
}

