    <div style="font-weight:700;font-size:13px;color:#0f3d26;margin-bottom:10px;">🏦 Bank Accounts Master List</div>
    <div style="display:flex;flex-wrap:wrap;gap:6px;">
      ${(DB.masterData?.banks||['IBBL MESARS KARIMA ENTERPRISE','CITY MESARS KARIMA ENTERPRISE','CITY NOOR MOHAMMAD RAMIM','IFIC RASHID OIL MILLS','IFIC SUBORNA AUTO RICE MILL','IFIC MD FARKAIUL HAMID','PBBL M S KARIMA ENTERPRISE','PBBL M S SATHI TRADERS','PBBL PARVATI AGRO','PBBL SUDHA AGRO','PBBL KARMA AGRO TRADING CORPORATION','PBBL SEVEN STAR OIL MILLS','PBBL M3 FARKAIUL HAMID','PBBL MST SATHI KHATUN','PBBL NOOR MOHAMMAD RAMIM','Cash Account','Bkash Account','Nagad Account','Another Account']).map(b=>`<span style="background:#f0fdf4;border:1px solid #bbf7d0;color:#166534;padding:3px 10px;border-radius:12px;font-size:11px;">${b}</span>`).join('')}
    </div>
  </div>`;
}

function addMasterItem(listName){
  const item=prompt('Add new item to '+listName+':');
  if(!item||!item.trim()) return;
  if(!DB.masterData) DB.masterData={};
  const keyMap={'Transaction Types':'txnTypes','Payment Modes':'modes','Locations':'locations','Units':'units'};
  const key=keyMap[listName];
  if(!key) return;
  if(!DB.masterData[key]) DB.masterData[key]=[];
  if(!DB.masterData[key].includes(item.trim())){
    DB.masterData[key].push(item.trim());
    saveDB();
    renderMasterData();
  } else alert('Item already exists!');
}

async function removeMasterItem(listName,item){
  if(!await __confirm('Remove "'+item+'" from '+listName+'?')) return;
  if(!DB.masterData) return;
  const keyMap={'Transaction Types':'txnTypes','Payment Modes':'modes','Locations':'locations','Units':'units'};
  const key=keyMap[listName];
  if(!key||!DB.masterData[key]) return;
  DB.masterData[key]=DB.masterData[key].filter(i=>i!==item);
  saveDB();
  renderMasterData();
}

// ── VAT Management ─────────────────────────────────────────────
function renderVATManagement(){
  // Auto-inject page structure if needed
  (function(){
    const _pg=document.getElementById('pg-vatmanagement');
    if(_pg&&!_pg.querySelector('[id]')){
      _pg.innerHTML=`<div style="padding:20px;"><h2 style="font-size:18px;font-weight:800;color:#0f3d26;margin:0 0 16px;">🏛️ VAT Management</h2><div id=\"vat-body\" style=\"background:#fff;border-radius:12px;padding:16px;border:1px solid #e5e7eb;\"></div></div>`;
    }
  })();
  // Scope the lookup to this page: another page also declares #vat-body, and a
  // global getElementById would fill that hidden page instead of this one.
  const _vpg=document.getElementById('pg-vatmanagement');
  const body=_vpg?_vpg.querySelector('#vat-body'):null;
  if(!body){
    // The VAT Management page is built around #vat-table-wrap / #vat-summary-cards,
    // which renderVATReport() fills — without this the page opened empty until
    // the user pressed "Refresh".
    if(typeof renderVATReport==='function') renderVATReport();
    return;
  }
  const txns=DB.tx||[];
  const vatRate=(DB.settings?.vatRate||15)/100;
  const vatableSales=txns.filter(t=>isRevenueTx(t)&&t.vatApplied);
  const totalVatable=vatableSales.reduce((s,t)=>s+txAmt(t),0);
  const totalVAT=totalVatable*vatRate;
  const vatPaid=txns.filter(t=>t.type==='Tax Payment').reduce((s,t)=>s+txAmt(t),0);

  body.innerHTML=`<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:16px;">
    ${[
      {label:'VAT Rate',val:(DB.settings?.vatRate||15)+'%',icon:'📊',color:'#2563eb'},
      {label:'Vatable Sales',val:'৳'+pf(totalVatable),icon:'💰',color:'#16a34a'},
      {label:'VAT Collected',val:'৳'+pf(totalVAT),icon:'🧾',color:'#f59e0b'},
      {label:'VAT Paid',val:'৳'+pf(vatPaid),icon:'✅',color:'#7c3aed'}
    ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
      <div style="font-size:22px;">${c.icon}</div>
      <div style="font-size:${c.val.length>8?'13':'17'}px;font-weight:900;color:${c.color};">${c.val}</div>
      <div style="font-size:11px;color:#6b7280;margin-top:4px;">${c.label}</div>
    </div>`).join('')}
  </div>
  <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;">
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
      <div style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;padding:12px 16px;font-weight:700;font-size:13px;">⚙️ VAT Settings</div>
      <div style="padding:16px;">
        <div style="margin-bottom:10px;">
          <label style="font-size:11px;font-weight:600;color:#374151;display:block;margin-bottom:3px;">Standard VAT Rate (%)</label>
          <input type="number" id="vat-rate" value="${DB.settings?.vatRate||15}" min="0" max="100" step="0.5"
            style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:14px;font-weight:700;text-align:center;box-sizing:border-box;"/>
        </div>
        <div style="margin-bottom:10px;">
          <label style="font-size:11px;font-weight:600;color:#374151;display:block;margin-bottom:3px;">VAT Registration No (BIN)</label>
          <input type="text" id="vat-bin" value="${DB.settings?.companyBIN||''}" placeholder="Business Identification Number"
            style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;box-sizing:border-box;"/>
        </div>
        <div style="margin-bottom:10px;">
          <label style="font-size:11px;font-weight:600;color:#374151;display:block;margin-bottom:3px;">VAT Period</label>
          <select id="vat-period" style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;">
            <option value="monthly">Monthly</option>
            <option value="quarterly">Quarterly</option>
            <option value="yearly">Yearly</option>
          </select>
        </div>
        <button data-x-click="saveVATSettings()" style="width:100%;padding:9px;background:#16a34a;color:#fff;border:none;border-radius:7px;font-size:12px;font-weight:700;cursor:pointer;">💾 Save VAT Settings</button>
      </div>
    </div>
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
      <div style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;padding:12px 16px;font-weight:700;font-size:13px;">🧾 VAT Summary</div>
      <div style="padding:16px;">
        <div style="background:#f0fdf4;border:1px solid #bbf7d0;border-radius:8px;padding:12px;margin-bottom:12px;">
          <div style="font-size:11px;color:#6b7280;margin-bottom:6px;">Current Period VAT Position</div>
          <div style="display:flex;justify-content:space-between;margin-bottom:4px;">
            <span style="font-size:12px;">Output VAT (Collected)</span>
            <span style="font-weight:700;color:#16a34a;">৳${pf(totalVAT)}</span>
          </div>
          <div style="display:flex;justify-content:space-between;margin-bottom:4px;">
            <span style="font-size:12px;">Input VAT (Paid)</span>
            <span style="font-weight:700;color:#dc2626;">৳${pf(vatPaid)}</span>
          </div>
          <div style="border-top:1px solid #bbf7d0;margin-top:8px;padding-top:8px;display:flex;justify-content:space-between;">
            <span style="font-size:12px;font-weight:700;">Net VAT Payable</span>
            <span style="font-size:14px;font-weight:900;color:${totalVAT-vatPaid>0?'#dc2626':'#16a34a'};">৳${pf(Math.abs(totalVAT-vatPaid))}</span>
          </div>
        </div>
        <button data-x-click="printVAT()" style="width:100%;padding:9px;background:#2563eb;color:#fff;border:none;border-radius:7px;font-size:12px;font-weight:700;cursor:pointer;">🖨️ Print VAT Report</button>
      </div>
    </div>
  </div>`;
}

function saveVATSettings(){
  if(!DB.settings) DB.settings={};
  const rateEl=document.getElementById('vat-rate');
  const binEl=document.getElementById('vat-bin');
  if(rateEl) DB.settings.vatRate=parseFloat(rateEl.value)||15;
  if(binEl) DB.settings.companyBIN=binEl.value;
  saveDB();
  alert('✅ VAT settings saved!');
}

// ── Cheque Management ──────────────────────────────────────────
function openAddChequeModal(){
  document.getElementById('chq-date').value=new Date().toISOString().split('T')[0];
  document.getElementById('cheque-modal').style.display='flex';
}

function saveCheque(){
  const chq={
    id:newId(),
    no:document.getElementById('chq-no')?.value||'',
    type:document.getElementById('chq-type')?.value||'Received',
    party:document.getElementById('chq-party')?.value||'',
    bank:document.getElementById('chq-bank')?.value||'',
    amount:parseFloat(document.getElementById('chq-amount')?.value||0),
    date:document.getElementById('chq-date')?.value||'',
    dueDate:document.getElementById('chq-due')?.value||'',
    status:document.getElementById('chq-status')?.value||'Pending',
    createdAt:new Date().toISOString()
  };
  if(!chq.no||!chq.party){alert('Cheque number and party are required.');return;}
  if(!(chq.amount>0)){alert('⚠️ Cheque amount is required.');return;}
    DB.cheques.unshift(chq);
  saveDB();
  if(typeof addAuditEntry==='function') addAuditEntry('CREATE','Cheques','Added cheque: '+chq.no+' from '+chq.party);
  document.getElementById('cheque-modal').style.display='none';
  /* FIX (2026-08-24): this used to call renderChequeManagement(), which
     writes into #cheque-cards/#cheque-body — containers that only exist
     because a separate self-heal patch appends them at the bottom of the
     page as a fallback. The actual visible Cheque Management page (KPIs +
     table you see on screen) is #cheque-kpis/#cheque-table-body, which is
     what renderCheques() — the same function nav() and the page's own
     filter/refresh controls already use — updates. Calling the wrong one
     meant a saved cheque never appeared until you left the page and came
     back. */
  renderCheques();
  alert('✅ Cheque saved!');
}

function updateChequeStatus(id,status){
  const chq=(DB.cheques||[]).find(c=>c.id===id);
  if(chq){chq.status=status;saveDB();renderCheques();}
}

async function deleteCheque(id){
  if(!await __confirm('Delete this cheque record?')) return;
  DB.cheques=(DB.cheques||[]).filter(c=>c.id!==id);
  saveDB();
  renderCheques();
}

function renderChequeManagement(){
  // Auto-inject page structure if needed
  (function(){
    const _pg=document.getElementById('pg-chequemanagement');
    if(_pg&&!_pg.querySelector('[id]')){
      _pg.innerHTML=`<div style="padding:20px;"><h2 style="font-size:18px;font-weight:800;color:#0f3d26;margin:0 0 16px;">🧾 Cheque Management</h2><div id=\"cheque-cards\" style=\"display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:12px;margin-bottom:16px;\"></div><div id=\"cheque-body\" style=\"background:#fff;border-radius:12px;padding:16px;border:1px solid #e5e7eb;\"></div></div>`;
    }
  })();
  const cheques=DB.cheques||[];
  const cards=document.getElementById('cheque-cards');
  const body=document.getElementById('cheque-body');

  const received=cheques.filter(c=>c.type==='Received');
  const issued=cheques.filter(c=>c.type==='Issued');
  const pending=cheques.filter(c=>c.status==='Pending');
  const bounced=cheques.filter(c=>c.status==='Bounced');

  if(cards) cards.innerHTML=[
    {label:'Received',val:received.length,icon:'📥',color:'#16a34a'},
    {label:'Issued',val:issued.length,icon:'📤',color:'#2563eb'},
    {label:'Pending',val:pending.length,icon:'⏳',color:'#f59e0b'},
    {label:'Bounced',val:bounced.length,icon:'⚠️',color:'#dc2626'}
  ].map(c=>`<div style="background:#fff;border:2px solid ${c.color}22;border-radius:10px;padding:16px;text-align:center;">
    <div style="font-size:22px;">${c.icon}</div>
    <div style="font-size:17px;font-weight:900;color:${c.color};">${c.val}</div>
    <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(c.label)}</div>
  </div>`).join('');

  if(!body) return;
  if(!cheques.length){body.innerHTML='<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:40px;text-align:center;color:#9ca3af;">No cheques recorded. Click "Add Cheque" to start tracking.</div>';return;}

  const statusColors={Pending:'#f59e0b',Cleared:'#16a34a',Bounced:'#dc2626',Cancelled:'#9ca3af'};
  body.innerHTML=`<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
    <div style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;padding:12px 16px;font-weight:700;font-size:13px;">🏦 All Cheques</div>
    <table style="width:100%;border-collapse:collapse;font-size:12px;">
      <thead><tr style="background:#f0fdf4;">
        <th style="padding:9px 12px;text-align:left;color:#0f3d26;">Cheque No</th>
        <th style="padding:9px 12px;text-align:left;color:#0f3d26;">Type</th>
        <th style="padding:9px 12px;text-align:left;color:#0f3d26;">Party</th>
        <th style="padding:9px 12px;text-align:left;color:#0f3d26;">Bank</th>
        <th style="padding:9px 12px;text-align:right;color:#0f3d26;">Amount (৳)</th>
        <th style="padding:9px 12px;text-align:left;color:#0f3d26;">Due Date</th>
        <th style="padding:9px 12px;text-align:left;color:#0f3d26;">Status</th>
        <th style="padding:9px 12px;text-align:center;color:#0f3d26;">Action</th>
      </tr></thead>
      <tbody>${cheques.map((c,i)=>{
        const color=statusColors[c.status]||'#6b7280';
        return `<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
          <td style="padding:8px 12px;font-family:monospace;font-weight:700;">${c.no}</td>
          <td style="padding:8px 12px;"><span style="background:${c.type==='Received'?'#dcfce7':'#eff6ff'};color:${c.type==='Received'?'#16a34a':'#2563eb'};padding:2px 8px;border-radius:8px;font-size:10px;font-weight:700;">${c.type}</span></td>
          <td style="padding:8px 12px;font-weight:600;">${escHTML(c.party)}</td>
          <td style="padding:8px 12px;color:#6b7280;font-size:11px;">${escHTML(c.bank||'—')}</td>
          <td style="padding:8px 12px;text-align:right;font-weight:700;color:#0f3d26;">৳${pf(c.amount)}</td>
          <td style="padding:8px 12px;color:#6b7280;">${c.dueDate||'—'}</td>
          <td style="padding:8px 12px;">
            <select data-x-change="updateChequeStatus(${c.id},this.value)" style="padding:3px 6px;border:1px solid ${color}44;border-radius:5px;font-size:10px;font-weight:700;color:${color};background:${color}11;">
              ${['Pending','Cleared','Bounced','Cancelled'].map(s=>`<option value="${s}" ${c.status===s?'selected':''}>${s}</option>`).join('')}
            </select>
          </td>
          <td style="padding:8px 12px;text-align:center;">
            <button data-x-click="deleteCheque(${c.id})" style="background:#fee2e2;color:#dc2626;border:none;border-radius:5px;padding:3px 8px;font-size:10px;cursor:pointer;">🗑️</button>
          </td>
        </tr>`;
      }).join('')}</tbody>
    </table>
  </div>`;
}

// ── Delivery Challan ───────────────────────────────────────────
/* REMOVED (2026-08-27, workflow audit): openAddChallanModal(), saveChallan(),
   and the #challan-modal popup they drove. An earlier "FIX 2" pass (see the
   comment further down) had already removed one byte-for-byte duplicate
   copy of this modal as dead code, but the trigger it described for the
   surviving copy no longer exists anywhere in the page — nothing calls
   openAddChallanModal() any more, so the modal itself was unreachable too.
   The Delivery Challan page's real, working "+ New Challan" flow is
   newChallan() -> #challan-form-area -> saveChallanFromArea(), which is
   untouched by this removal. printChallan() and deleteChallan() are shared
   with the live table and are also untouched. */

/* FIX 2 (security/refactor audit): dedicated save handler for the inline
   "New Delivery Challan" panel (#challan-form-area), which used to share
   saveChallan() above via duplicate ch-* ids and the getElementById
   dedup patch. That worked only by luck (whichever copy was "visible" at
   save time) and silently dropped this form's Destination/Remarks fields,
   since saveChallan() never reads them. This reads the form's own unique
   chfa-* ids plus its unique ch-dest/ch-remarks fields, and writes to the
   same DB.challans array so reporting/printing behave identically either
   way. */
function saveChallanFromArea(){
  const ch={
    id:newId(),
    no:document.getElementById('chfa-no')?.value||'',
    date:document.getElementById('chfa-date')?.value||'',
    party:document.getElementById('chfa-party')?.value||'',
    address:'',
    product:document.getElementById('chfa-product')?.value||'',
    qty:parseFloat(document.getElementById('chfa-qty')?.value||0),
    unit:document.getElementById('chfa-unit')?.value||'KG',
    truck:document.getElementById('chfa-truck')?.value||'',
    bankAccount:getPartyBankPickerValue('chfa-bankaccount','chfa-bankaccount-custom'),
    driver:document.getElementById('chfa-driver')?.value||'',
    dest:document.getElementById('ch-dest')?.value||'',
    status:'Pending',
    notes:document.getElementById('ch-remarks')?.value||'',
    createdAt:new Date().toISOString()
  };
  if(!ch.party||!ch.product){alert('Party and product are required.');return;}
  if(!(ch.qty>0)){alert('⚠️ Quantity is required.');return;}
    DB.challans.unshift(ch);
  saveDB();
  if(typeof addAuditEntry==='function') addAuditEntry('CREATE','Challans','Created challan: '+ch.no+' for '+ch.party);
  document.getElementById('challan-form-area').style.display='none';
  renderDeliveryChallan();
  alert('✅ Challan saved!');
}

function updateChallanStatus(id,status){
  const ch=(DB.challans||[]).find(c=>c.id===id);
  if(ch){ch.status=status;saveDB();renderDeliveryChallan();}
}

async function deleteChallan(id){
  if(!await __confirm('Delete this challan?')) return;
  DB.challans=(DB.challans||[]).filter(c=>c.id!==id);
  saveDB();
  renderDeliveryChallan();
}

function printChallan(id){
  const ch=(DB.challans||[]).find(c=>c.id===id);
  if(!ch) return;
  // Print on official company letterhead
  const cell = (h,v)=>`<th style="border:1px solid #d1d5db;padding:8px 10px;text-align:left;background:#f0fdf4;color:#0f3d26;width:18%;">${h}</th><td style="border:1px solid #d1d5db;padding:8px 10px;">${escHTML(v)}</td>`;
  const html = `
  <div style="text-align:center;margin-bottom:12px;">
    <span style="font-size:15px;font-weight:800;color:#16a34a;">DELIVERY CHALLAN — ${ch.no}</span>
  </div>
  <table style="width:100%;border-collapse:collapse;">
    <tr>${cell('Date',ch.date)}${cell('Challan No',ch.no)}</tr>
    <tr>${cell('Customer',ch.party)}${cell('Delivery Address',ch.address||'—')}</tr>
    <tr>${cell('Product',ch.product)}${cell('Quantity',(ch.qty||'')+' '+(ch.unit||''))}</tr>
    <tr>${cell('Truck / Vehicle',ch.truck||'—')}${cell('Driver',ch.driver||'—')}</tr>
    <tr>${cell('Bank Account (Payment)',ch.bankAccount||'—')}${cell('Status',ch.status||'—')}</tr>
    <tr>${cell('Notes',ch.notes||'—')}</tr>
  </table>`;
  openPrintModal('Delivery Challan', ch.no, html, ch.party||'');
  const sel=document.getElementById('print-invoice-type'); if(sel) sel.value='challan';
}

function renderDeliveryChallan(){
  // Auto-inject page structure if needed
  (function(){
    const _pg=document.getElementById('pg-deliverychallan');
    if(_pg&&!_pg.querySelector('[id]')){
      _pg.innerHTML=`<div style="padding:20px;"><h2 style="font-size:18px;font-weight:800;color:#0f3d26;margin:0 0 16px;">📋 Delivery Challan</h2><div id=\"dc-cards\" style=\"display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:12px;margin-bottom:16px;\"></div><div id=\"dc-body\" style=\"background:#fff;border-radius:12px;padding:16px;border:1px solid #e5e7eb;\"></div></div>`;
    }
  })();
  const body=document.getElementById('dc-body');
  if(!body) return;
  const challans=DB.challans||[];
  if(!challans.length){body.innerHTML='<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:40px;text-align:center;color:#9ca3af;">No challans created. Click "New Challan" to create one.</div>';return;}

  const statusColors={Pending:'#f59e0b','In Transit':'#2563eb',Delivered:'#16a34a',Returned:'#dc2626'};
  body.innerHTML=`<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
    <div style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;padding:12px 16px;font-weight:700;font-size:13px;">🚚 All Delivery Challans</div>
    <table style="width:100%;border-collapse:collapse;font-size:12px;">
      <thead><tr style="background:#f0fdf4;">
        <th style="padding:9px 12px;text-align:left;color:#0f3d26;">Challan No</th>
        <th style="padding:9px 12px;text-align:left;color:#0f3d26;">Date</th>
        <th style="padding:9px 12px;text-align:left;color:#0f3d26;">Customer</th>
        <th style="padding:9px 12px;text-align:left;color:#0f3d26;">Product</th>
        <th style="padding:9px 12px;text-align:right;color:#0f3d26;">Qty</th>
        <th style="padding:9px 12px;text-align:left;color:#0f3d26;">Truck</th>
        <th style="padding:9px 12px;text-align:left;color:#0f3d26;">Status</th>
        <th style="padding:9px 12px;text-align:center;color:#0f3d26;">Action</th>
      </tr></thead>
      <tbody>${challans.map((c,i)=>{
        const color=statusColors[c.status]||'#6b7280';
        return `<tr style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};">
          <td style="padding:8px 12px;font-family:monospace;font-weight:700;color:#2563eb;">${c.no}</td>
          <td style="padding:8px 12px;color:#6b7280;">${c.date}</td>
          <td style="padding:8px 12px;font-weight:700;">${escHTML(c.party)}</td>
          <td style="padding:8px 12px;">${c.product}</td>
          <td style="padding:8px 12px;text-align:right;font-weight:700;">${c.qty} ${c.unit}</td>
          <td style="padding:8px 12px;color:#6b7280;">${c.truck||'—'}</td>
          <td style="padding:8px 12px;">
            <select data-x-change="updateChallanStatus(${c.id},this.value)" style="padding:3px 6px;border:1px solid ${color}44;border-radius:5px;font-size:10px;font-weight:700;color:${color};background:${color}11;">
              ${['Pending','In Transit','Delivered','Returned'].map(s=>`<option value="${s}" ${c.status===s?'selected':''}>${s}</option>`).join('')}
            </select>
          </td>
          <td style="padding:8px 12px;text-align:center;display:flex;gap:4px;justify-content:center;">
            <button data-x-click="printChallan(${c.id})" style="background:#eff6ff;color:#2563eb;border:none;border-radius:5px;padding:3px 8px;font-size:10px;cursor:pointer;">🖨️</button>
            <button data-x-click="deleteChallan(${c.id})" style="background:#fee2e2;color:#dc2626;border:none;border-radius:5px;padding:3px 8px;font-size:10px;cursor:pointer;">🗑️</button>
          </td>
        </tr>`;
      }).join('')}</tbody>
    </table>
  </div>`;
}

</script>
<style>
*{margin:0;padding:0;box-sizing:border-box;}
:root{
  --primary:#1a365d;--primary-light:#2b6cb0;--accent:#3182ce;
  --success:#38a169;--warning:#d69e2e;--danger:#e53e3e;--purple:#805ad5;
  --orange:#dd6b20;--teal:#319795;--bg:#f0f4f8;--white:#fff;
  --gray-50:#f7fafc;--gray-100:#edf2f7;--gray-200:#e2e8f0;
  --gray-400:#a0aec0;--gray-600:#718096;--gray-700:#4a5568;--gray-800:#2d3748;--gray-900:#1a202c;
  --shadow:0 1px 3px rgba(0,0,0,.1);--shadow-md:0 4px 12px rgba(0,0,0,.12);
  --radius:10px;--radius-lg:14px;
}
body{font-family:'Segoe UI',system-ui,sans-serif;background:var(--bg);color:var(--gray-900);font-size:14px;}

/* ── SIDEBAR ── */
.sidebar{position:fixed;left:0;top:0;width:240px;height:var(--app-vh,100vh);
  background:linear-gradient(180deg,#0d3320 0%,#0f3d26 40%,#0a2d1c 100%);
  color:#fff;z-index:200;transition:width .2s;
  display:flex;flex-direction:column;overflow:hidden;}
.logo{padding:16px 14px;border-bottom:1px solid rgba(255,255,255,.08);display:flex;align-items:center;gap:10px;background:rgba(0,0,0,.15);flex-shrink:0;}
.logo-icon{font-size:30px;flex-shrink:0;}
.logo-text .t1{font-size:12px;font-weight:800;letter-spacing:.3px;color:#fff;white-space:nowrap;}
.logo-text .t2{font-size:9px;color:#4ade80;margin-top:2px;font-weight:500;white-space:nowrap;}

/* ── Smart search filter ── */
.nav-search-wrap{padding:10px 12px 6px;flex-shrink:0;}
.nav-search-box{position:relative;display:flex;align-items:center;}
.nav-search-icon{position:absolute;left:9px;font-size:11.5px;opacity:.55;pointer-events:none;}
.nav-search-input{width:100%;padding:7px 26px 7px 28px;border-radius:8px;
  background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.12);
  color:#fff;font-size:12px;transition:all .18s;}
.nav-search-input::placeholder{color:rgba(255,255,255,.4);}
.nav-search-input:focus{outline:none;border-color:#4ade80;background:rgba(255,255,255,.13);}
.nav-search-clear{position:absolute;right:6px;background:none;border:none;color:rgba(255,255,255,.5);
  font-size:12px;cursor:pointer;padding:3px 5px;line-height:1;border-radius:4px;}
.nav-search-clear:hover{color:#fff;background:rgba(255,255,255,.12);}
.nav-no-results{display:none;padding:14px 6px 4px;font-size:11.5px;color:rgba(255,255,255,.5);text-align:center;}

/* ── Collapse-to-icons toggle ── */
.sidebar-collapse-btn{flex-shrink:0;margin:2px 12px 6px;align-self:flex-end;
  background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.1);color:rgba(255,255,255,.6);
  width:24px;height:24px;border-radius:6px;cursor:pointer;font-size:12px;
  display:flex;align-items:center;justify-content:center;transition:all .18s;}
.sidebar-collapse-btn:hover{background:rgba(74,222,128,.15);color:#4ade80;}
.sidebar-collapse-icon{transition:transform .2s;display:inline-block;}

/* ── Scrollable nav area (header/search stay fixed) ── */
.nav-scroll{flex:1;overflow-y:auto;overflow-x:hidden;
  scrollbar-width:thin;scrollbar-color:rgba(255,255,255,.15) transparent;}
.nav-scroll::-webkit-scrollbar{width:4px;}
.nav-scroll::-webkit-scrollbar-thumb{background:rgba(255,255,255,.2);border-radius:2px;}

/* ── Collapsible sections ── */
.nav-section{padding:2px 0;}
.nav-section-header{display:flex;align-items:center;justify-content:space-between;
  cursor:pointer;padding:9px 14px 4px;user-select:none;border-radius:6px;}
.nav-section-header:hover .nav-label{color:#6ee7a8;}
.nav-section-header .nav-label{padding:0;}
.nav-section-chevron{font-size:8px;color:rgba(255,255,255,.35);transition:transform .2s;margin-right:2px;}
.nav-section.collapsed .nav-section-chevron{transform:rotate(-90deg);}
.nav-section.collapsed .nav-section-body{display:none;}
.nav-label{font-size:9.5px;font-weight:700;letter-spacing:1.2px;color:#4ade80;padding:10px 14px 4px;text-transform:uppercase;opacity:.8;}
.nav-subgroup{padding:2px 0 2px 6px;}
.nav-sublabel{font-size:8.5px;font-weight:700;letter-spacing:1px;color:rgba(255,255,255,.35);
  padding:6px 14px 2px;text-transform:uppercase;}
.nav-item{display:flex;align-items:center;gap:9px;padding:8px 14px;
  cursor:pointer;border-radius:6px;margin:1px 8px;font-size:12.5px;
  color:rgba(255,255,255,.78);transition:all .18s;position:relative;}
.nav-item:hover{background:rgba(74,222,128,.15);color:#4ade80;}
.nav-item.active{background:linear-gradient(90deg,#16a34a,#15803d);color:#fff;font-weight:600;box-shadow:0 2px 8px rgba(22,163,74,.35);}
.nav-item.search-hidden{display:none !important;}
.nav-icon{font-size:15px;width:20px;text-align:center;flex-shrink:0;}
.nav-badge{margin-left:auto;background:rgba(255,255,255,.15);border-radius:10px;
  padding:1px 7px;font-size:10px;font-weight:700;}

/* ── Sidebar collapsed to icon rail (user-toggled, desktop) ── */
.sidebar.icon-collapsed{width:64px;}
.sidebar.icon-collapsed .logo-text,
.sidebar.icon-collapsed .nav-search-wrap,
.sidebar.icon-collapsed .nav-label,
.sidebar.icon-collapsed .nav-sublabel,
.sidebar.icon-collapsed .nav-item span:not(.nav-icon),
.sidebar.icon-collapsed .nav-badge,
.sidebar.icon-collapsed .nav-section-chevron{display:none;}
.sidebar.icon-collapsed .nav-section-header{justify-content:center;padding:6px 0;}
.sidebar.icon-collapsed .nav-item{justify-content:center;margin:1px 6px;padding:9px;}
.sidebar.icon-collapsed .sidebar-collapse-btn{align-self:center;margin:2px 0 6px;}
.sidebar.icon-collapsed .sidebar-collapse-icon{transform:rotate(180deg);}
.sidebar.icon-collapsed .nav-item:hover .nav-tooltip{display:block !important;}
.sidebar.icon-collapsed ~ .main,
.sidebar.icon-collapsed + .main{margin-left:64px;}
.sidebar.icon-collapsed ~ .topbar,
.sidebar.icon-collapsed + .topbar{left:64px;}

/* ── MAIN ── */
.main{margin-left:240px;min-height:var(--app-vh,100vh);display:flex;flex-direction:column;flex:1;width:auto;min-width:0;padding-top:var(--topbar-h,56px);}
.content{min-width:0;max-width:100%;}
html,body{max-width:100%;overflow-x:hidden;}
.card,.chart-card,.kpi-card{min-width:0;}
.tbl,table{max-width:100%;}
.topbar{position:fixed;top:0;left:240px;right:0;min-height:56px;height:auto;
  background:#fff;border-bottom:2px solid #16a34a;
  display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;row-gap:8px;
  padding:8px 20px;z-index:100;box-shadow:0 2px 8px rgba(15,61,38,.08);}
.topbar-left{display:flex;align-items:center;gap:12px;}
.page-title{font-size:16px;font-weight:700;color:#0f3d26;margin-left:10px;}
.topbar-right{display:flex;align-items:center;gap:10px;}
.date-chip{background:var(--gray-100);border-radius:20px;padding:5px 12px;
  font-size:11px;color:var(--gray-600);font-weight:600;}

/* ── BUTTONS ── */
.btn{padding:8px 16px;border-radius:8px;border:none;cursor:pointer;font-size:12.5px;
  font-weight:700;transition:all .2s;display:inline-flex;align-items:center;gap:6px;white-space:nowrap;}
.btn:active{transform:scale(.97);}
.btn-primary{background:var(--accent);color:#fff;}
.btn-primary:hover{background:var(--primary-light);}
.btn-success{background:var(--success);color:#fff;}
.btn-success:hover{background:#2f855a;}
.btn-danger{background:var(--danger);color:#fff;}
.btn-danger:hover{background:#c53030;}
.btn-warning{background:var(--warning);color:#fff;}
.btn-warning:hover{background:#b7791f;}
.btn-outline{background:var(--white);color:var(--accent);border:1.5px solid var(--accent);}
.btn-outline:hover{background:#ebf8ff;}
.btn-ghost{background:transparent;color:var(--gray-600);border:1.5px solid var(--gray-200);}
.btn-ghost:hover{background:var(--gray-100);}
.btn-sm{padding:5px 10px;font-size:11.5px;}
.btn-xs{padding:3px 8px;font-size:11px;}
.btn-icon{padding:6px;border-radius:6px;}

/* ── CONTENT ── */
.content{padding:20px 24px;flex:1;}
/* BUGFIX (2026-08-24): even shrunk to small 44px icon circles (see the
   #v2-launcher / #ayanPayBtn fixes above), the floating action-button
   column at right:16-18px still clips the last digit or two of whatever
   number happens to sit flush against the right edge at that same
   height — confirmed on the Balance Sheet's own TOTAL LIABILITIES + EQUITY
   and NET WORTH figures on an ordinary desktop window. Reserving a clear
   vertical channel down the right edge, wide enough for that icon column,
   keeps real numbers from ever running under it — narrow/phone screens
   are untouched since their own fixes already reposition these buttons. */
@media (min-width:769px){ .content{padding-right:76px;} }
.page{display:none;animation:fadeIn .3s ease;}
.page.active{display:block;}
@keyframes fadeIn{from{opacity:0;transform:translateY(6px);}to{opacity:1;transform:translateY(0);}}

/* ── KPI GRID ── */
.kpi-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:20px;}
.kpi-grid-3{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-bottom:20px;}
.kpi-grid-2{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;margin-bottom:20px;}
.kpi-card{background:var(--white);border-radius:var(--radius-lg);padding:18px 20px;
  box-shadow:var(--shadow);border-left:4px solid;transition:transform .2s,box-shadow .2s,border-color .2s;position:relative;overflow:hidden;cursor:pointer;}
.kpi-card:active{transform:translateY(0) scale(0.98);}
.kpi-card:hover{transform:translateY(-2px);box-shadow:var(--shadow-md);}
.kpi-card[onclick]:hover .kpi-label::after{content:' →';opacity:.5;font-size:11px;}
.kpi-card::after{content:attr(data-icon);position:absolute;right:14px;top:14px;
  font-size:32px;opacity:.08;pointer-events:none;}
.kpi-card.c-blue{border-color:var(--accent);}
.kpi-card.c-green{border-color:var(--success);}
.kpi-card.c-purple{border-color:var(--purple);}
.kpi-card.c-orange{border-color:var(--orange);}
.kpi-card.c-red{border-color:var(--danger);}
.kpi-card.c-teal{border-color:var(--teal);}
.kpi-card.c-yellow{border-color:var(--warning);}
.kpi-label{font-size:10.5px;text-transform:uppercase;letter-spacing:.6px;color:var(--gray-600);font-weight:700;margin-bottom:6px;}
.kpi-value{font-size:21px;font-weight:900;color:var(--gray-900);margin-bottom:3px;line-height:1.1;}
.kpi-sub{font-size:10.5px;color:var(--gray-400);}
.health-bar{height:6px;background:var(--gray-200);border-radius:3px;overflow:hidden;margin:6px 0 3px;}
.health-fill{height:100%;border-radius:3px;transition:width 1.2s ease;}

/* ── CHART GRID ── */
.chart-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:20px;}
.chart-grid-3{display:grid;grid-template-columns:1fr 1fr 1fr;gap:16px;margin-bottom:20px;}
.chart-card{background:var(--white);border-radius:var(--radius-lg);padding:18px 20px;box-shadow:var(--shadow);}
.chart-card.span2{grid-column:1/-1;}
.chart-title{font-size:13px;font-weight:800;color:var(--gray-800);margin-bottom:14px;
  display:flex;justify-content:space-between;align-items:center;}
.chart-title .sub{font-size:10.5px;color:var(--gray-400);font-weight:500;}
.chart-wrap{position:relative;}

/* ── TABLE CARD ── */
.table-card{background:var(--white);border-radius:var(--radius-lg);padding:18px 20px;
  box-shadow:var(--shadow);margin-bottom:18px;}
.table-header{display:flex;justify-content:space-between;align-items:center;
  margin-bottom:14px;flex-wrap:wrap;gap:10px;}
.table-title{font-size:14px;font-weight:800;color:var(--gray-800);}
.table-actions{display:flex;gap:8px;flex-wrap:wrap;align-items:center;}
.search-box{padding:7px 12px;border:1.5px solid var(--gray-200);border-radius:8px;
  font-size:12.5px;width:200px;outline:none;transition:border-color .2s;}
.search-box:focus{border-color:var(--accent);box-shadow:0 0 0 3px rgba(49,130,206,.1);}

/* ── SCROLLABLE TABLE WRAPPER ── */
.tbl-scroll{overflow-x:auto;-webkit-overflow-scrolling:touch;}
.tbl-scroll table{min-width:2200px;}

table{width:100%;border-collapse:collapse;font-size:12px;}
th{background:#1a365d;color:#fff;padding:8px 10px;text-align:left;font-size:10px;
  text-transform:uppercase;letter-spacing:.5px;font-weight:700;
  border-bottom:2px solid #2b6cb0;white-space:nowrap;position:sticky;top:0;z-index:2;}
td{padding:7px 10px;border-bottom:1px solid var(--gray-100);color:var(--gray-800);vertical-align:middle;white-space:nowrap;}
tr:hover td{background:#ebf8ff;}
tr:last-child td{border-bottom:none;}
.td-num{text-align:right;font-weight:700;font-variant-numeric:tabular-nums;}

/* ── BADGES ── */
.badge{display:inline-block;padding:2px 8px;border-radius:20px;font-size:10.5px;font-weight:700;white-space:nowrap;}
.b-green{background:#c6f6d5;color:#276749;}
.b-blue{background:#bee3f8;color:#2b6cb0;}
.b-red{background:#fed7d7;color:#c53030;}
.b-orange{background:#feebc8;color:#c05621;}
.b-purple{background:#e9d8fd;color:#6b46c1;}
.b-gray{background:#e2e8f0;color:#4a5568;}
.b-teal{background:#b2f5ea;color:#234e52;}
.b-yellow{background:#fefcbf;color:#744210;}

/* ── SUMMARY CARD ── */
.sum-card{background:var(--white);border-radius:var(--radius-lg);padding:16px 18px;box-shadow:var(--shadow);}
.sum-title{font-size:11px;font-weight:800;color:var(--gray-600);text-transform:uppercase;
  letter-spacing:.6px;margin-bottom:10px;padding-bottom:8px;border-bottom:2px solid var(--gray-100);}
.sum-row{display:flex;justify-content:space-between;align-items:center;
  padding:6px 0;border-bottom:1px solid var(--gray-100);font-size:12.5px;}
.sum-row:last-child{border-bottom:none;}
.sum-name{color:var(--gray-700);font-weight:500;}
.sum-val{font-weight:800;}
.sum-val.pos{color:var(--success);}
.sum-val.neg{color:var(--danger);}
.sum-val.neu{color:var(--accent);}
.sum-total{display:flex;justify-content:space-between;align-items:center;
  padding:8px 0 0;margin-top:6px;border-top:2px solid var(--gray-200);font-size:13px;font-weight:800;}

/* ── MODAL ── */
.overlay{display:none;position:fixed;inset:0;background:rgba(0,0,0,.55);
  z-index:500;align-items:center;justify-content:center;padding:16px;}
.overlay.open{display:flex;}
/* mCardCrud can have another modal (Add Customer/Bank/etc.) opened on top of it;
   keep it one layer behind so the nested modal is always clickable. */
#mCardCrud{z-index:499;}
.modal{background:var(--white);border-radius:var(--radius-lg);padding:26px;
  width:100%;max-width:900px;max-height:94vh;overflow-y:auto;
  box-shadow:0 20px 60px rgba(0,0,0,.3);animation:modalIn .25s ease;}
.modal.modal-lg{max-width:1180px;}
/* REVERTED (2026-08-25, user request): the full-height right-side slide-over
   panel below was tried for the New Transaction form but the user preferred
   the original centered popup look, so #mTx is back to the default .modal
   behavior (centered, rounded corners, max-width 900px). Kept here,
   commented out, in case a wide-form treatment is wanted again later.
@media (min-width:769px){
  #mTx.overlay{align-items:stretch !important;justify-content:flex-end !important;padding:0 !important;height:var(--app-vh,100vh) !important;}
  #mTx .modal{
    width:min(980px,96vw) !important;max-width:min(980px,96vw) !important;
    height:var(--app-vh,100vh) !important;max-height:var(--app-vh,100vh) !important;
    border-radius:0 !important;margin:0 !important;
    animation:erpSlideIn .28s cubic-bezier(.22,1,.36,1) both !important;
  }
  @keyframes erpSlideIn{from{transform:translateX(48px);opacity:.3;}to{transform:translateX(0);opacity:1;}}
}
*/
@keyframes modalIn{from{opacity:0;transform:scale(.94);}to{opacity:1;transform:scale(1);}}
.modal-title{font-size:17px;font-weight:800;color:var(--primary);
  margin-bottom:18px;padding-bottom:12px;border-bottom:2px solid var(--gray-100);
  display:flex;justify-content:space-between;align-items:center;}
.modal-close{cursor:pointer;font-size:18px;color:var(--gray-400);
  width:28px;height:28px;display:flex;align-items:center;justify-content:center;
  border-radius:6px;transition:all .2s;}
.modal-close:hover{background:var(--gray-100);color:var(--danger);}

/* ── FORM SECTIONS ── */
.form-section{background:var(--gray-50);border-radius:10px;padding:14px 16px;margin-bottom:14px;border:1px solid var(--gray-200);}
.form-section-title{font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:.8px;
  color:var(--primary);margin-bottom:12px;display:flex;align-items:center;gap:6px;}
.form-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;}
.form-grid-3{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;}
.form-grid-2{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;}
.fg{display:flex;flex-direction:column;gap:3px;}
.fg.full{grid-column:1/-1;}
.fg.span2{grid-column:span 2;}
label.lbl{font-size:9.5px;font-weight:700;color:var(--gray-600);text-transform:uppercase;letter-spacing:.3px;}
.fc{padding:7px 10px;border:1.5px solid var(--gray-200);border-radius:7px;
  font-size:12px;outline:none;transition:border-color .2s;background:var(--white);width:100%;}
.fc:focus{border-color:var(--accent);box-shadow:0 0 0 3px rgba(49,130,206,.1);}
.fc-highlight{border-color:var(--accent);background:#ebf8ff;font-weight:700;color:var(--accent);}
.fc-calc{border-color:var(--success);background:#f0fff4;font-weight:700;color:var(--success);}
.form-actions{display:flex;gap:10px;justify-content:flex-end;
  margin-top:18px;padding-top:14px;border-top:1px solid var(--gray-100);}

/* ── FILTER BAR ── */
.filter-bar{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px;}
.fsel{padding:6px 10px;border:1.5px solid var(--gray-200);border-radius:8px;
  font-size:12px;outline:none;background:var(--white);cursor:pointer;}
.fsel:focus{border-color:var(--accent);}

/* ── EMPTY STATE ── */
.empty{text-align:center;padding:40px 20px;color:var(--gray-400);}
.empty .ei{font-size:44px;margin-bottom:10px;}
.empty p{font-size:13px;}

/* ── TOAST ── */
.toast{position:fixed;bottom:22px;right:22px;padding:11px 18px;border-radius:10px;
  font-size:12.5px;font-weight:700;z-index:9999;transform:translateY(80px);opacity:0;
  transition:all .3s;box-shadow:0 4px 20px rgba(0,0,0,.25);max-width:320px;}
.toast.show{transform:translateY(0);opacity:1;}
.toast.s{background:#276749;color:#fff;}
.toast.e{background:#c53030;color:#fff;}
.toast.w{background:#b7791f;color:#fff;}

/* ── MISC ── */
.divider{height:1px;background:var(--gray-100);margin:14px 0;}
.text-pos{color:var(--success);font-weight:700;}
.text-neg{color:var(--danger);font-weight:700;}
.text-neu{color:var(--accent);font-weight:700;}
.text-muted{color:var(--gray-400);}
.fw7{font-weight:700;}
.fw8{font-weight:800;}
.fs11{font-size:11px;}
.fs12{font-size:12px;}
.section-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;}
.section-title{font-size:15px;font-weight:800;color:var(--gray-800);}
.info-row{display:flex;gap:16px;flex-wrap:wrap;margin-bottom:16px;}
.info-pill{background:var(--white);border-radius:20px;padding:6px 14px;font-size:11.5px;
  font-weight:700;box-shadow:var(--shadow);display:flex;align-items:center;gap:6px;}
.dot{width:8px;height:8px;border-radius:50%;display:inline-block;}

/* ── RESPONSIVE ── */
@media(max-width:1200px){.kpi-grid{grid-template-columns:repeat(2,1fr);}}
/* ── Sidebar overlay (mobile drawer backdrop) ── */
.sidebar-overlay{display:none;position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:199;backdrop-filter:blur(2px);}
.sidebar-overlay.active{display:block;}

/* ── Hamburger button ── */
.hamburger{display:none;flex-direction:column;justify-content:center;align-items:center;
  width:38px;height:38px;cursor:pointer;border-radius:8px;border:none;
  background:rgba(255,255,255,.08);gap:5px;flex-shrink:0;}
.hamburger span{display:block;width:20px;height:2px;background:#fff;border-radius:2px;
  transition:all .25s;}
.hamburger.open span:nth-child(1){transform:translateY(7px) rotate(45deg);}
.hamburger.open span:nth-child(2){opacity:0;transform:scaleX(0);}
.hamburger.open span:nth-child(3){transform:translateY(-7px) rotate(-45deg);}

/* ── Collapsed sidebar tooltip ── */
.nav-item{position:relative;}
.nav-item .nav-tooltip{display:none !important;position:absolute;left:60px;top:50%;transform:translateY(-50%);
  background:#1a365d;color:#fff;font-size:11px;padding:4px 10px;border-radius:6px;
  white-space:nowrap;z-index:300;pointer-events:none;box-shadow:0 2px 8px rgba(0,0,0,.3);}
.nav-item .nav-tooltip::before{content:'';position:absolute;right:100%;top:50%;
  transform:translateY(-50%);border:5px solid transparent;border-right-color:#1a365d;}

@media(max-width:900px){
  .sidebar{width:56px;}
  .logo-text,.nav-item span:not(.nav-icon),.nav-badge{display:none;}
  .main{margin-left:56px;}
  .chart-grid,.chart-grid-3{grid-template-columns:1fr;}
  .kpi-grid,.kpi-grid-3{grid-template-columns:1fr 1fr;}
  .form-grid{grid-template-columns:repeat(2,1fr);}
  /* Show tooltip on hover when collapsed */
  .nav-item:hover .nav-tooltip{display:block;}
}
@media(max-width:600px){
  .kpi-grid,.kpi-grid-3,.kpi-grid-2{grid-template-columns:1fr;}
  .form-grid,.form-grid-3,.form-grid-2{grid-template-columns:1fr;}
  .content{padding:14px;}
  .topbar{padding:10px 14px;}
  /* Mobile: sidebar is a full drawer, hidden off-screen by default */
  .sidebar{width:230px;left:-230px;transition:left .3s,width .3s;}
  .sidebar.mobile-open{left:0;}
  .main{margin-left:0;}
  .hamburger{display:flex;}
  /* Show all text in mobile drawer */
  .logo-text,.nav-item span:not(.nav-icon),.nav-badge{display:initial;}
  .nav-item .nav-tooltip{display:none !important;}
}

/* ═══════════════════════════════════════════════════════
   PRINT STYLES — AYAN AGRO INTERNATIONAL LIMITED
   ═══════════════════════════════════════════════════════ */
@media print {
  body * { visibility: hidden !important; }
  #print-area, #print-area * { visibility: visible !important; }
  #print-area { position: absolute !important; top: 0 !important; left: 0 !important; width: 100% !important; }
  @page { margin: 10mm 12mm; size: A4; }
}
.print-letterhead {
  font-family: Arial, sans-serif;
  width: 100%;
  border-collapse: collapse;
  margin-bottom: 0;
}
/* Top blue banner */
.lh-top {
  background: #1a3a6b;
  color: #fff;
  text-align: center;
  padding: 10px 16px 6px;
}
.lh-company {
  font-size: 22px;
  font-weight: 900;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  line-height: 1.2;
}
/* Gold tagline bar */
.lh-tagline {
  background: #f5a623;
  color: #1a3a6b;
  text-align: center;
  font-size: 11px;
  font-weight: 700;
  padding: 4px 12px;
  letter-spacing: .5px;
}
/* Contact info row */
.lh-contact {
  background: #e8f0fb;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 6px 16px;
  font-size: 11px;
  color: #1a3a6b;
  border-bottom: 2px solid #1a3a6b;
  flex-wrap: wrap;
  gap: 4px;
}
.lh-contact span { display: flex; align-items: center; gap: 4px; }
/* Dark blue activity bar */
.lh-activity {
  background: #0d2447;
  color: #f5a623;
  text-align: center;
  font-size: 10px;
  font-weight: 700;
  padding: 3px 12px;
  letter-spacing: .8px;
  text-transform: uppercase;
}
/* Document meta row */
.lh-docmeta {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 16px;
  background: #fff;
  border-bottom: 1px solid #ddd;
  font-size: 12px;
}
.lh-docmeta .doc-title {
  font-size: 15px;
  font-weight: 800;
  color: #1a3a6b;
  text-transform: uppercase;
  letter-spacing: .5px;
}
.lh-docmeta .doc-meta {
  display: flex;
  gap: 20px;
  font-size: 11px;
  color: #555;
}
/* Print body */
.print-body {
  padding: 10px 16px;
  font-size: 12px;
  font-family: Arial, sans-serif;
}
/* Print table */
.print-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 11px;
  margin-top: 8px;
}
.print-table th {
  background: #1a3a6b;
  color: #fff;
  padding: 6px 8px;
  text-align: left;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
}
.print-table td {
  padding: 5px 8px;
  border-bottom: 1px solid #e5e7eb;
  vertical-align: top;
}
.print-table tr:nth-child(even) td { background: #f8faff; }
.print-table .td-num { text-align: right; }
.print-table tfoot td {
  background: #1a3a6b;
  color: #fff;
  font-weight: 700;
  padding: 6px 8px;
}
/* Summary boxes */
.print-summary {
  display: flex;
  gap: 12px;
  margin: 10px 0;
  flex-wrap: wrap;
}
.print-sum-box {
  flex: 1;
  min-width: 120px;
  border: 1.5px solid #1a3a6b;
  border-radius: 6px;
  padding: 8px 12px;
  text-align: center;
}
.print-sum-box .psb-label { font-size: 10px; color: #666; font-weight: 600; text-transform: uppercase; }
.print-sum-box .psb-value { font-size: 15px; font-weight: 800; color: #1a3a6b; margin-top: 2px; }
/* Signature footer */
.print-sigfooter {
  margin-top: 20px;
  border-top: 1px solid #ddd;
  padding-top: 8px;
}
.print-sig-row {
  display: flex;
  gap: 0;
}
.print-sig-col {
  flex: 1;
  border: 1px solid #1a3a6b;
  padding: 8px 12px;
  min-height: 70px;
}
.print-sig-col .sig-header {
  background: #0f3d26;
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  text-align: center;
  padding: 3px;
  margin: -8px -12px 8px;
  text-transform: uppercase;
}
.print-sig-col .sig-line {
  font-size: 10px;
  color: #555;
  margin-top: 4px;
  border-bottom: 1px dotted #aaa;
  padding-bottom: 2px;
}
/* Gold footer strip */
.lh-footer {
  background: #f5a623;
  color: #1a3a6b;
  text-align: center;
  font-size: 10px;
  font-weight: 700;
  padding: 4px 12px;
  margin-top: 8px;
}
/* Print modal */
#print-modal {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,.6);
  z-index: 9999;
  overflow-y: auto;
  padding: 20px;
}
#print-modal.open { display: flex; align-items: flex-start; justify-content: center; }
#print-area {
  background: #fff;
  width: 210mm;
  min-height: 297mm;
  box-shadow: 0 4px 32px rgba(0,0,0,.3);
  position: relative;
}
.print-toolbar {
  position: sticky;
  top: 0;
  background: #1a3a6b;
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  z-index: 10;
  gap: 8px;
}
.print-toolbar button {
  padding: 6px 16px;
  border-radius: 6px;
  border: none;
  cursor: pointer;
  font-weight: 700;
  font-size: 13px;
}
.btn-print-go { background: #f5a623; color: #1a3a6b; }
.btn-print-close { background: rgba(255,255,255,.2); color: #fff; }

#sidebarOverlay{display:none;}
#sidebarOverlay.active{display:block;}

/* ── PRINT TOOLBAR & AREA ── */
.print-toolbar{display:flex;justify-content:space-between;align-items:center;
  padding:10px 16px;background:#f0fdf4;border-bottom:2px solid #16a34a;color:#0f3d26;
  position:sticky;top:0;z-index:10;}
.btn-print-go{background:linear-gradient(90deg,#16a34a,#15803d);color:#fff;
  border:none;padding:7px 16px;border-radius:6px;cursor:pointer;font-weight:600;font-size:12px;}
.btn-print-close{background:#ef4444;color:#fff;border:none;padding:7px 14px;
  border-radius:6px;cursor:pointer;font-weight:600;font-size:12px;}
#print-modal{display:none;position:fixed;inset:0;background:rgba(0,0,0,.6);
  z-index:9999;overflow-y:auto;padding:20px;}
#print-modal.open{display:flex;justify-content:center;align-items:flex-start;}
#print-area{background:#fff;padding:16px 20px;min-height:297mm;}
.lh-docmeta{display:flex;justify-content:space-between;align-items:center;
  padding:8px 0;border-bottom:2px solid #16a34a;margin-bottom:10px;}
.doc-title{font-size:16px;font-weight:800;color:#0f3d26;text-transform:uppercase;letter-spacing:.5px;}
.doc-meta{display:flex;gap:16px;font-size:11px;color:#374151;}
.print-body{padding:4px 0;}
.print-sigfooter{margin-top:24px;padding-top:12px;border-top:2px solid #16a34a;}
.print-sig-row{display:flex;gap:16px;justify-content:space-between;}
.print-sig-col{flex:1;background:#f9fafb;border:1px solid #e5e7eb;border-radius:6px;padding:10px 12px;}
.sig-header{font-weight:700;color:#0f3d26;font-size:11px;margin-bottom:8px;
  border-bottom:1px solid #bbf7d0;padding-bottom:4px;}
.sig-line{font-size:10px;color:#374151;margin-top:4px;}
.print-table{width:100%;border-collapse:collapse;font-size:11px;margin-top:8px;}
.print-table th{background:#0f3d26;color:#fff;padding:7px 10px;text-align:left;font-size:11px;}
.print-table td{padding:6px 10px;border-bottom:1px solid #e5e7eb;}
.print-table tr:nth-child(even) td{background:#f0fdf4;}
.sum-boxes{display:flex;gap:10px;margin-bottom:12px;flex-wrap:wrap;}
.sum-box{flex:1;min-width:100px;background:linear-gradient(135deg,#f0fdf4,#dcfce7);
  border:1px solid #16a34a;border-radius:8px;padding:8px 12px;text-align:center;}
.sum-box .sb-label{font-size:9px;color:#15803d;font-weight:600;text-transform:uppercase;}
.sum-box .sb-val{font-size:14px;font-weight:800;color:#0f3d26;margin-top:2px;}
/* Invoice-specific styles */
.inv-party-box{background:#f0fdf4;border:1px solid #bbf7d0;border-radius:8px;
  padding:10px 14px;margin-bottom:12px;display:flex;justify-content:space-between;}
.inv-party-label{font-size:9px;color:#15803d;font-weight:700;text-transform:uppercase;margin-bottom:4px;}
.inv-party-name{font-size:13px;font-weight:800;color:#0f3d26;}
.inv-items-table{width:100%;border-collapse:collapse;font-size:11px;}
.inv-items-table th{background:#0f3d26;color:#fff;padding:7px 10px;text-align:left;letter-spacing:.3px;}
.inv-items-table th:nth-child(n+3){text-align:right;}
.inv-items-table td{padding:6px 10px;border-bottom:1px solid #e5e7eb;}
.inv-items-table td:nth-child(n+3){text-align:right;}
.inv-items-table tr:nth-child(even) td{background:#f9fafb;}
.inv-items-table tbody tr:hover td{background:#f0fdf4;}
.inv-total-row td{font-weight:700;background:#f0fdf4!important;color:#0f3d26;border-top:2px solid #0f3d26;}
@media print{
  .print-toolbar{display:none!important;}
  body{overflow:visible!important;}
  /* Never display:none an ancestor of the print area — visibility handles hiding.
     (The old rule body>*:not(#print-modal){display:none} blanked all printing
     because #print-modal sits inside .main, not directly under body.) */
  #print-modal{display:block!important;position:static!important;background:none!important;padding:0!important;overflow:visible!important;}
  #print-area{padding:8mm 10mm!important;box-shadow:none!important;}
  .sidebar,.topbar,.sidebar-overlay{display:none!important;}
}

/* ── SMART FORM HINTS ── */
.smart-hint{font-size:10px;color:#15803d;background:#f0fdf4;border:1px solid #bbf7d0;
  border-radius:4px;padding:2px 8px;margin-top:3px;transition:opacity .5s;
  display:block;font-weight:500;}
.form-section{background:#fff;border:1px solid #e5e7eb;border-radius:8px;
  padding:12px 14px;margin-bottom:10px;}
.form-section-title{font-size:12px;font-weight:700;color:#0f3d26;margin-bottom:8px;
  padding-bottom:6px;border-bottom:2px solid #bbf7d0;}
.form-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;}
.fg{display:flex;flex-direction:column;}
.fg.span2{grid-column:span 2;}
.fg.span3{grid-column:span 3;}
.fg.span4{grid-column:span 4;}
.lbl{font-size:11px;font-weight:600;color:#374151;margin-bottom:3px;}
.fc{padding:7px 10px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;
  transition:border-color .2s;background:#fff;}
.fc:focus{outline:none;border-color:#16a34a;box-shadow:0 0 0 2px rgba(22,163,74,.15);}

/* ── ADVANCED DASHBOARD ── */
.adv-kpi-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:18px;}
.adv-kpi{border-radius:12px;padding:16px 18px;cursor:pointer;transition:transform .15s,box-shadow .15s;position:relative;overflow:hidden;}
.adv-kpi:hover{transform:translateY(-3px);box-shadow:0 8px 24px rgba(0,0,0,.15);}
.adv-kpi .kpi-icon{font-size:28px;margin-bottom:6px;}
.adv-kpi .kpi-label{font-size:11px;opacity:.85;font-weight:600;letter-spacing:.3px;}
.adv-kpi .kpi-value{font-size:20px;font-weight:800;margin:4px 0 2px;}
.adv-kpi .kpi-sub{font-size:10px;opacity:.75;}
.adv-kpi .kpi-arrow{position:absolute;right:14px;top:50%;transform:translateY(-50%);font-size:20px;opacity:.3;}
.chart-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:18px;}
.chart-card{background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:16px;}
.chart-card h4{font-size:13px;font-weight:700;color:#0f3d26;margin:0 0 12px;}
.chart-card canvas{max-height:220px;}
.health-bar-wrap{background:#f3f4f6;border-radius:8px;height:10px;overflow:hidden;margin:6px 0;}
.health-bar{height:100%;border-radius:8px;transition:width .6s;}
.top-table{width:100%;border-collapse:collapse;font-size:12px;}
.top-table th{padding:8px 10px;text-align:left;background:#f9fafb;color:#374151;font-weight:700;border-bottom:2px solid #e5e7eb;}
.top-table td{padding:8px 10px;border-bottom:1px solid #f3f4f6;}
.top-table tr:hover td{background:#f9fafb;}

/* ── LETTERHEAD STYLES (green theme, used by .lh-wrap party/statement printouts) ── */
.lh-wrap{border:2px solid #16a34a;border-radius:4px;overflow:hidden;margin-bottom:10px;}
.lh-greenbar{background:linear-gradient(135deg,#0f3d26 0%,#16a34a 100%);color:#fff;
  padding:12px 16px;display:flex;justify-content:space-between;align-items:center;}
.lh-leaf{font-size:32px;margin-right:10px;}
.lh-logo-area{display:flex;align-items:center;}
.lh-company{font-size:17px;font-weight:900;letter-spacing:.5px;color:#fff;}
.lh-concern{font-size:11px;color:#bbf7d0;margin-top:2px;font-weight:600;}
.lh-contact-right{text-align:right;font-size:10.5px;color:#d1fae5;line-height:1.7;}
.lh-accent-line{height:4px;background:linear-gradient(90deg,#f59e0b,#16a34a,#0f3d26);}
.lh-tagline-bar{background:#f0fdf4;padding:5px 16px;font-size:10.5px;color:#15803d;
  font-weight:600;display:flex;gap:10px;align-items:center;border-bottom:1px solid #bbf7d0;}
.lh-dot{color:#16a34a;font-size:8px;}
.lh-address-bar{background:#fff;padding:4px 16px;font-size:9.5px;color:#6b7280;
  display:flex;gap:10px;align-items:center;flex-wrap:wrap;}
.lh-footer-note{text-align:center;font-size:9px;color:#9ca3af;margin-top:12px;
  padding-top:8px;border-top:1px dashed #d1d5db;}


/* ═══ v17 MOBILE RESPONSIVE IMPROVEMENTS ═══ */
@media (max-width: 768px) {
  .sidebar { width: 0 !important; overflow: hidden; transition: width .3s; }
  .sidebar.mobile-open { width: 240px !important; z-index: 999; }
  .main { margin-left: 0 !important; }
  .topbar { left: 0 !important; }
  .mobile-menu-btn { display: flex !important; }
  .adv-kpi-grid { grid-template-columns: 1fr 1fr !important; }
  .page { padding: 12px !important; }
  table { font-size: 11px; }
  th, td { padding: 6px 8px !important; }
}
@media (max-width: 480px) {
  .adv-kpi-grid { grid-template-columns: 1fr !important; }
  .topbar { padding: 0 10px !important; }
  .page-title { font-size: 13px !important; }
}
.mobile-menu-btn { display: none; background: none; border: none; cursor: pointer; font-size: 22px; color: #0f3d26; padding: 4px; }
.mobile-overlay { display: none; position: fixed; inset: 0; background: rgba(0,0,0,.5); z-index: 998; }
.mobile-overlay.active { display: block; }
.kpi-card { background: #fff; border: 1px solid #e5e7eb; border-radius: 12px; padding: 16px; transition: transform .2s, box-shadow .2s; }
.kpi-card:hover { transform: translateY(-2px); box-shadow: 0 4px 12px rgba(0,0,0,.1); }
@media print {
  .sidebar, .topbar, .btn, .nav-item, .mobile-menu-btn { display: none !important; }
  .main { margin-left: 0 !important; }
  body { background: #fff !important; }
}

/* ═══════════════════════════════════════════════════════════
   v18 DARK MODE & THEME SYSTEM
═══════════════════════════════════════════════════════════ */
:root {
  --dm-bg: #f0f4f8;
  --dm-card: #ffffff;
  --dm-text: #1a202c;
  --dm-text2: #6b7280;
  --dm-border: #e5e7eb;
  --dm-input: #ffffff;
  --dm-sidebar: linear-gradient(180deg,#0d3320 0%,#0f3d26 40%,#0a2d1c 100%);
  --dm-topbar: #ffffff;
  --dm-topbar-border: #16a34a;
  --dm-table-head: #065f46;
  --dm-table-row: #ffffff;
  --dm-table-alt: #f9fafb;
  --dm-shadow: 0 1px 4px rgba(0,0,0,.08);
  --dm-kpi-bg: #ffffff;
  --transition: all .25s ease;
}
[data-theme="dark"] {
  --dm-bg: #0f172a;
  --dm-card: #1e293b;
  --dm-text: #f1f5f9;
  --dm-text2: #94a3b8;
  --dm-border: #334155;
  --dm-input: #1e293b;
  --dm-sidebar: linear-gradient(180deg,#020617 0%,#0f172a 40%,#020617 100%);
  --dm-topbar: #1e293b;
  --dm-topbar-border: #16a34a;
  --dm-table-head: #0f3d26;
  --dm-table-row: #1e293b;
  --dm-table-alt: #162032;
  --dm-shadow: 0 1px 4px rgba(0,0,0,.4);
  --dm-kpi-bg: #1e293b;
}
[data-theme="dark"] body { background: var(--dm-bg); color: var(--dm-text); }
[data-theme="dark"] .main { background: var(--dm-bg); }
[data-theme="dark"] .card, [data-theme="dark"] .kpi-card { background: var(--dm-card); border-color: var(--dm-border); color: var(--dm-text); }
[data-theme="dark"] .topbar { background: var(--dm-topbar); border-color: var(--dm-topbar-border); }
[data-theme="dark"] .page-title { color: #4ade80; }
[data-theme="dark"] input, [data-theme="dark"] select, [data-theme="dark"] textarea { background: var(--dm-input); color: var(--dm-text); border-color: var(--dm-border); }
[data-theme="dark"] table th { background: var(--dm-table-head); }
[data-theme="dark"] table td { border-color: var(--dm-border); color: var(--dm-text); }
[data-theme="dark"] table tr:hover td { background: #162032; }
[data-theme="dark"] .tbl tbody tr:nth-child(even) td { background: var(--dm-table-alt); }
[data-theme="dark"] .date-chip { background: #1e293b; color: #94a3b8; }
[data-theme="dark"] h2, [data-theme="dark"] h3, [data-theme="dark"] h4 { color: var(--dm-text); }
[data-theme="dark"] .page-header { background: linear-gradient(135deg,#052e16,#14532d); }
[data-theme="dark"] .adv-kpi { opacity: .95; }
[data-theme="dark"] label { color: #94a3b8; }
[data-theme="dark"] .nav-item { color: rgba(255,255,255,.8); }
[data-theme="dark"] .sidebar { background: var(--dm-sidebar); }

/* ═══ THEME COLORS ═══ */
[data-color="blue"] { --primary-accent: #2563eb; --primary-light: #dbeafe; }
[data-color="purple"] { --primary-accent: #7c3aed; --primary-light: #ede9fe; }
[data-color="orange"] { --primary-accent: #ea580c; --primary-light: #fff7ed; }
[data-color="teal"] { --primary-accent: #0891b2; --primary-light: #e0f2fe; }

/* ═══ PAGE TRANSITIONS ═══ */
.page { animation: fadeIn .2s ease; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: translateY(0); } }

/* ═══ ENHANCED TOPBAR ═══ */
.theme-toggle-btn {
  width: 36px; height: 36px; border-radius: 50%; border: 1.5px solid var(--dm-border);
  background: var(--dm-card); cursor: pointer; font-size: 16px;
  display: flex; align-items: center; justify-content: center; transition: var(--transition);
}
.theme-toggle-btn:hover { transform: rotate(20deg); }

/* ═══ ENHANCED CARDS ═══ */
.card { background: var(--dm-card); border: 1px solid var(--dm-border); border-radius: 14px; padding: 20px; box-shadow: var(--dm-shadow); margin-bottom: 20px; transition: var(--transition); }
.card:hover { box-shadow: 0 4px 16px rgba(0,0,0,.12); }

/* ═══ NOTIFICATION DOT ═══ */
.notif-dot { width: 8px; height: 8px; background: #dc2626; border-radius: 50%; position: absolute; top: 2px; right: 2px; animation: pulse 2s infinite; }
@keyframes pulse { 0%,100%{opacity:1;transform:scale(1)} 50%{opacity:.6;transform:scale(1.3)} }

/* ═══ PRINT TEMPLATES ═══ */
.print-template { display: none; }
@media print {
  body > *:not(#print-area) { display: none !important; }
  #print-area { display: block !important; }
  .print-template { display: block; }
}
/* FIX (2026-08-25): this unconditional, non-@media rule permanently hid
   #print-area even while its parent #print-modal was open on-screen — the
   Print Preview modal would show its toolbar (a separate element) but the
   actual voucher/invoice/report content underneath stayed invisible,
   letting whatever page was open behind it show through instead. #print-area
   exists in exactly one place in this document (inside #print-modal), and
   #print-modal is already display:none by default, so this rule was never
   needed to hide it while closed — it only ever hid it while open, which is
   the one time it must be visible. Removed. */

/* v19 AUTO-SAVE & SYNC */
#save-indicator{display:flex;align-items:center;gap:6px;padding:4px 12px;border-radius:20px;font-size:11px;font-weight:700;transition:all .3s;cursor:pointer;user-select:none;}
#save-indicator.saved{background:#dcfce7;color:#16a34a;border:1px solid #bbf7d0;}
#save-indicator.saving{background:#fef9c3;color:#b45309;border:1px solid #fde68a;animation:savePulse 1s infinite;}
#save-indicator.unsaved{background:#fee2e2;color:#dc2626;border:1px solid #fecaca;}
#save-indicator.synced{background:#dbeafe;color:#1d4ed8;border:1px solid #bfdbfe;}
@keyframes savePulse{0%,100%{opacity:1}50%{opacity:.6}}
#autosave-progress{position:fixed;top:0;left:0;height:3px;background:linear-gradient(90deg,#16a34a,#4ade80);width:0%;transition:width .4s ease;z-index:9999;border-radius:0 2px 2px 0;}
.sync-toast{position:fixed;bottom:80px;right:20px;background:#1d4ed8;color:#fff;padding:10px 16px;border-radius:10px;font-size:12px;font-weight:700;box-shadow:0 4px 12px rgba(0,0,0,.2);z-index:9998;animation:slideInRight .3s ease;display:flex;align-items:center;gap:8px;}
@keyframes slideInRight{from{transform:translateX(100px);opacity:0}to{transform:translateX(0);opacity:1}}
#last-saved-time{font-size:10px;color:var(--dm-text2,#6b7280);margin-left:2px;}

/* ═══════════════════════════════════════════════════════════
   v30 MOBILE APP EXPERIENCE
═══════════════════════════════════════════════════════════ */

/* Bottom Navigation Bar */
#bottom-nav {
  display: none;
  position: fixed;
  bottom: 0; left: 0; right: 0;
  height: 60px;
  background: var(--dm-card, #fff);
  border-top: 1px solid var(--dm-border, #e5e7eb);
  z-index: 500;
  box-shadow: 0 -2px 12px rgba(0,0,0,.08);
}
.bn-item {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  cursor: pointer;
  padding: 6px 4px;
  transition: all .2s;
  border: none;
  background: none;
  font-family: inherit;
}
.bn-item.active { color: #16a34a; }
.bn-item:not(.active) { color: #9ca3af; }
.bn-icon { font-size: 20px; line-height: 1; }
.bn-label { font-size: 9px; font-weight: 700; text-transform: uppercase; letter-spacing: .3px; }
.bn-badge {
  position: absolute;
  top: 4px;
  right: calc(50% - 18px);
  background: #dc2626;
  color: #fff;
  border-radius: 50%;
  width: 14px;
  height: 14px;
  font-size: 8px;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* Mobile adjustments */
@media (max-width: 768px) {
  #bottom-nav { display: flex; }
  .main { padding-bottom: 70px !important; }
  .topbar { height: 52px; }
  .page { padding: 12px !important; }
  .sidebar { display: none !important; }
  .main { margin-left: 0 !important; }

  /* Touch-friendly buttons */
  .btn { min-height: 40px; }
  input, select, textarea { font-size: 16px !important; } /* Prevents iOS zoom */

  /* Mobile KPI grid */
  .kpi-card { padding: 12px !important; }
  .adv-kpi-grid { grid-template-columns: 1fr 1fr !important; }

  /* Mobile table scroll */
  .card { overflow-x: auto; }
  table { min-width: 500px; }

  /* Mobile modal */
  .m-box { width: 100% !important; max-width: 100% !important; border-radius: 16px 16px 0 0 !important; position: fixed !important; bottom: 0 !important; margin: 0 !important; }

  /* Swipe hint */
  .swipe-hint { display: block !important; }
}

@media (min-width: 769px) {
  #bottom-nav { display: none !important; }
}

/* Swipe gesture overlay */
.swipe-hint {
  display: none;
  text-align: center;
  font-size: 11px;
  color: #9ca3af;
  padding: 8px;
  animation: fadeIn .3s ease;
}

/* Pull-to-refresh indicator */
#ptr-indicator {
  position: fixed;
  top: 52px;
  left: 50%;
  transform: translateX(-50%);
  background: #16a34a;
  color: #fff;
  padding: 6px 16px;
  border-radius: 0 0 12px 12px;
  font-size: 12px;
  font-weight: 700;
  z-index: 600;
  display: none;
  animation: slideDown .3s ease;
}
@keyframes slideDown { from{transform:translateX(-50%) translateY(-100%)} to{transform:translateX(-50%) translateY(0)} }

/* Touch ripple effect */
.touch-ripple {
  position: relative;
  overflow: hidden;
}
.touch-ripple::after {
  content: '';
  position: absolute;
  border-radius: 50%;
  background: rgba(255,255,255,.3);
  transform: scale(0);
  animation: ripple .4s linear;
  pointer-events: none;
}
@keyframes ripple { to { transform: scale(4); opacity: 0; } }

/* Mobile-optimized forms */
.mobile-form-group {
  margin-bottom: 16px;
}
.mobile-form-group label {
  font-size: 12px;
  font-weight: 700;
  color: #6b7280;
  display: block;
  margin-bottom: 6px;
  text-transform: uppercase;
  letter-spacing: .5px;
}
.mobile-form-group input,
.mobile-form-group select,
.mobile-form-group textarea {
  width: 100%;
  padding: 12px 14px;
  border: 1.5px solid #e5e7eb;
  border-radius: 10px;
  font-size: 15px;
  transition: border .2s;
}
.mobile-form-group input:focus,
.mobile-form-group select:focus {
  border-color: #16a34a;
  outline: none;
}

/* Floating Action Button */
#fab {
  position: fixed;
  bottom: 76px;
  right: 16px;
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: linear-gradient(135deg, #16a34a, #15803d);
  color: #fff;
  border: none;
  cursor: pointer;
  font-size: 22px;
  box-shadow: 0 4px 16px rgba(22,163,74,.4);
  z-index: 490;
  display: none;
  align-items: center;
  justify-content: center;
  transition: all .2s;
}
#fab:hover { transform: scale(1.1); }
#fab-menu {
  position: fixed;
  bottom: 136px;
  right: 16px;
  z-index: 489;
  display: none;
  flex-direction: column;
  gap: 8px;
  align-items: flex-end;
}
.fab-item {
  display: flex;
  align-items: center;
  gap: 8px;
  animation: fabIn .2s ease;
}
/* FIX (floating quick-action buttons burying real content — ALL screen
   sizes, not just mobile): #v2-launcher (bottom-right, position:fixed)
   started as one "Freight Due" button and grew a "Sync", "Cost Dues",
   "Cost Ledgers" and "Factory Finance" button over time — each added
   independently, by a different patch, each just appending itself to the
   same fixed-position stack with no awareness of how many were already
   there. This was first fixed for phone screens only, on the assumption
   that "a full-height desktop window" had room to spare — but a 1440px
   desktop sweep of the Balance Sheet and Dashboard pages proved that
   wrong: the opaque pill stack sits directly over the TOTAL LIABILITIES +
   EQUITY figure and the Business Health panel on an ordinary laptop
   screen too, not just on a phone. None of these five actions is used
   often enough to justify permanently occupying screen space on ANY
   device, so the stack is now collapsed behind a single toggle everywhere
   — capped height, scrollable, every button reachable with one click —
   instead of only below the old 480px breakpoint. */
#v2-launcher:not(.v2-open) > button{ display:none !important; }
#v2-launcher.v2-open{
  max-height:44vh !important;
  overflow-y:auto !important;
  -webkit-overflow-scrolling:touch;
  gap:6px !important;
  right:8px !important;
  bottom:calc(80px + var(--erp-reminder-h,0px)) !important;
  background:rgba(255,255,255,.0);
  padding-bottom:4px;
}
#v2-launcher.v2-open > button{
  padding:6px 10px !important;
  font-size:10.5px !important;
  border-radius:16px !important;
  box-shadow:0 3px 10px rgba(0,0,0,.22) !important;
}
#v2-launcher-toggle{
  position:fixed !important;right:14px !important;bottom:calc(80px + var(--erp-reminder-h,0px)) !important;z-index:9001 !important;
  width:44px;height:44px;border-radius:50%;border:0;
  background:#0f3d26;color:#fff;font-size:19px;line-height:1;
  display:flex;align-items:center;justify-content:center;cursor:pointer;
  box-shadow:0 6px 18px rgba(0,0,0,.3);
}
@keyframes fabIn { from{opacity:0;transform:translateY(10px)} to{opacity:1;transform:translateY(0)} }
.fab-label {
  background: rgba(0,0,0,.75);
  color: #fff;
  padding: 4px 10px;
  border-radius: 6px;
  font-size: 11px;
  font-weight: 700;
  white-space: nowrap;
}
.fab-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: none;
  cursor: pointer;
  font-size: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 2px 8px rgba(0,0,0,.2);
}

@media (max-width: 768px) {
  #fab { display: flex; }
}
</style>
<style id="mobile-optimize">
/* MOBILE OPTIMIZATION (unified override layer, must stay last in head) */
@media (max-width: 768px){
  .sidebar{
    display:block !important;
    position:fixed !important; top:0; bottom:0; left:0 !important;
    width:280px !important; max-width:85vw;
    transform:translateX(-105%); transition:transform .28s ease;
    z-index:1000 !important; overflow-y:auto; -webkit-overflow-scrolling:touch;
    padding-bottom:90px; box-shadow:4px 0 24px rgba(0,0,0,.25);
  }
  .sidebar.mobile-open{ transform:translateX(0); width:280px !important; }
  .sidebar .logo-text, .sidebar .nav-item span:not(.nav-icon), .sidebar .nav-badge{ display:initial !important; }
  .sidebar .nav-item .nav-tooltip{ display:none !important; }
  .sidebar .nav-item{ min-height:44px; align-items:center; font-size:13.5px; }

  #sidebarOverlay.active, #mobile-overlay.active, .sidebar-overlay.active{
    display:block !important; z-index:999 !important;
  }

  .mobile-menu-btn, #mobile-menu-btn{ display:none !important; }
  .hamburger{ display:flex !important; background:#f0fdf4; border:1px solid #d1fae5; }
  .hamburger span{ background:#0f3d26; }
  .topbar{ position:sticky; top:0; z-index:600; padding-top:calc(8px + env(safe-area-inset-top)) !important; }
  .sidebar{ padding-top:env(safe-area-inset-top); }

  .main{ margin-left:0 !important; padding-top:0 !important; padding-bottom:calc(76px + env(safe-area-inset-bottom)) !important; }
  .content, .page{ padding:12px !important; }
  #bottom-nav{ height:calc(60px + env(safe-area-inset-bottom)); padding-bottom:env(safe-area-inset-bottom); }

  .card, .table-wrap, .chart-card{ overflow-x:auto; -webkit-overflow-scrolling:touch; }
  .card table, .table-wrap table{ min-width:560px; }

  .chart-card canvas{ max-height:240px !important; }

  .adv-kpi-grid{ grid-template-columns:1fr 1fr !important; gap:10px !important; }
  .adv-kpi{ padding:12px !important; }
  .adv-kpi .kpi-value{ font-size:17px !important; }
  .adv-kpi .kpi-icon{ font-size:18px !important; }

  .m-box{
    width:100% !important; max-width:100% !important; margin:0 !important;
    position:fixed !important; bottom:0 !important; left:0 !important; right:0 !important;
    border-radius:16px 16px 0 0 !important;
    max-height:92dvh; overflow-y:auto; -webkit-overflow-scrolling:touch;
    padding-bottom:calc(16px + env(safe-area-inset-bottom)) !important;
  }

  .btn{ min-height:42px; }
  input, select, textarea{ font-size:16px !important; min-height:40px; }
  .page-header, .topbar-right{ flex-wrap:wrap; gap:8px; }
}
@media (max-width: 400px){
  .adv-kpi-grid{ grid-template-columns:1fr !important; }
  .sidebar{ width:88vw !important; max-width:88vw; }
}
@media (min-width: 769px){
  .hamburger{ display:none !important; }
  .mobile-menu-btn, #mobile-menu-btn{ display:none !important; }
}

/* ═══ PAGE PRINT MODE ═══
   The legacy print CSS shows ONLY #print-area (letterhead documents), which makes
   direct printing of the dashboard / reports blank. When no letterhead document is
   active, JS adds body.print-page-mode and these rules print the current page
   cleanly — app chrome (header, sidebar, panels, buttons) hidden. */
@media print{
  body.print-page-mode *{ visibility: visible !important; }
  body.print-page-mode > *{ display: revert !important; }
  body.print-page-mode .main{ display: block !important; margin: 0 !important; padding: 0 !important; }
  /* Hide app chrome in the printout */
  body.print-page-mode .topbar,
  body.print-page-mode .sidebar,
  body.print-page-mode .sidebar-overlay,
  body.print-page-mode #sidebarOverlay,
  body.print-page-mode #mobile-overlay,
  body.print-page-mode #bottom-nav,
  body.print-page-mode #fab,
  body.print-page-mode .hamburger,
  body.print-page-mode .mobile-menu-btn,
  body.print-page-mode .pb-bar,
  body.print-page-mode .pbm-overlay,
  body.print-page-mode #print-modal,
  body.print-page-mode #print-area,
  body.print-page-mode .print-template,
  body.print-page-mode #save-indicator,
  body.print-page-mode #autosave-progress,
  body.print-page-mode .btn,
  body.print-page-mode button{ display: none !important; visibility: hidden !important; }
  body.print-page-mode .content, body.print-page-mode .page{ padding: 0 !important; }
  body.print-page-mode .card, body.print-page-mode .chart-card{ box-shadow: none !important; overflow: visible !important; break-inside: avoid; }
  body.print-page-mode table{ min-width: 0 !important; font-size: 11px; }
  body.print-page-mode a{ text-decoration: none; color: inherit; }
}
</style>
<style id="ui-polish-2026">
/* ═══════════════════════════════════════════════════════════════════
   UI POLISH LAYER v2 — Ayan Agro reference look
   Light sidebar · blue primary · vibrant gradient KPI tiles
   Visual-only. No markup/JS/id/class changes.
   ═══════════════════════════════════════════════════════════════════ */

/* Web fonts are loaded via a non-blocking <link> in <head>; offline the
   local 'Segoe UI'/system-ui fallbacks in each font stack take over instantly. */

:root{
  --primary:#2563eb; --primary-light:#3b82f6; --primary-dark:#1d4ed8;
  --accent:#6366f1;
  --success:#10b981; --warning:#f59e0b; --danger:#ef4444;
  --purple:#8b5cf6; --orange:#f97316; --teal:#14b8a6; --pink:#ec4899;

  --bg:#f6f8fc; --white:#ffffff;
  --gray-50:#f8fafc; --gray-100:#f1f5f9; --gray-200:#e5e9f0;
  --gray-300:#d5dbe5; --gray-400:#94a3b8; --gray-500:#64748b;
  --gray-600:#475569; --gray-700:#334155; --gray-800:#1e293b; --gray-900:#0b1220;

  --shadow-xs:0 1px 2px rgba(15,23,42,.05);
  --shadow:0 1px 3px rgba(15,23,42,.06),0 1px 2px rgba(15,23,42,.04);
  --shadow-md:0 10px 25px -10px rgba(30,41,59,.15),0 4px 10px -6px rgba(30,41,59,.08);
  --shadow-lg:0 25px 50px -12px rgba(30,41,59,.25);

  --radius:14px; --radius-lg:20px;

  --grad-blue:linear-gradient(135deg,#3b82f6 0%,#2563eb 60%,#1e40af 100%);
  --grad-sky:linear-gradient(135deg,#38bdf8 0%,#0ea5e9 100%);
  --grad-emerald:linear-gradient(135deg,#34d399 0%,#059669 100%);
  --grad-teal:linear-gradient(135deg,#22d3ee 0%,#0891b2 100%);
  --grad-orange:linear-gradient(135deg,#fbbf24 0%,#f97316 100%);
  --grad-violet:linear-gradient(135deg,#a78bfa 0%,#8b5cf6 60%,#ec4899 100%);
  --grad-red:linear-gradient(135deg,#fb7185 0%,#ef4444 100%);
  --grad-page:linear-gradient(180deg,#f6f8fc 0%,#eef2f8 100%);
}

/* Base */
html,body{font-family:'Inter','Segoe UI',system-ui,-apple-system,sans-serif;
  -webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility;
  color:var(--gray-900);letter-spacing:-.005em;}
body{background:var(--grad-page) fixed !important;}
h1,h2,h3,h4,.page-title,.card-title{font-family:'Plus Jakarta Sans','Inter',sans-serif;letter-spacing:-.02em;font-weight:800;}

/* Scrollbar */
*::-webkit-scrollbar{width:10px;height:10px;}
*::-webkit-scrollbar-track{background:transparent;}
*::-webkit-scrollbar-thumb{background:#cbd5e1;border-radius:10px;border:2px solid transparent;background-clip:padding-box;}
*::-webkit-scrollbar-thumb:hover{background:#94a3b8;background-clip:padding-box;border:2px solid transparent;}

/* ═══════════ SIDEBAR — LIGHT with blue accents ═══════════ */
.sidebar{
  background:#ffffff !important;
  color:var(--gray-800) !important;
  border-right:1px solid var(--gray-200) !important;
  box-shadow:1px 0 0 rgba(15,23,42,.02), 4px 0 24px -12px rgba(15,23,42,.08) !important;
}
.sidebar::before{content:none !important;}

.logo{
  background:#fff !important;
  border-bottom:1px solid var(--gray-100) !important;
  padding:18px 16px !important;
}
.logo-icon{
  background:linear-gradient(135deg,#dbeafe,#c7d2fe);
  color:var(--primary) !important;
  width:44px;height:44px;border-radius:12px;
  display:flex;align-items:center;justify-content:center;
  font-size:22px !important;
  box-shadow:0 4px 14px -4px rgba(37,99,235,.4);
  flex-shrink:0;
}
.logo-text .t1{color:var(--gray-900) !important;font-family:'Plus Jakarta Sans',sans-serif;font-size:14px !important;font-weight:800;letter-spacing:.2px;}
.logo-text .t2{color:var(--gray-500) !important;font-size:10px !important;font-weight:600;letter-spacing:.8px;text-transform:uppercase;}

/* Search */
.nav-search-wrap{padding:12px 14px 8px;}
.nav-search-input{
  background:var(--gray-50) !important;
  border:1px solid var(--gray-200) !important;
  color:var(--gray-800) !important;
  border-radius:10px !important;padding:9px 28px 9px 30px !important;
  transition:all .18s;
}
.nav-search-input::placeholder{color:var(--gray-400) !important;}
.nav-search-input:focus{
  outline:none !important;background:#fff !important;
  border-color:var(--primary-light) !important;
  box-shadow:0 0 0 3px rgba(59,130,246,.15) !important;
}
.nav-search-icon{color:var(--gray-400) !important;opacity:1 !important;}
.nav-search-clear{color:var(--gray-400) !important;}
.nav-search-clear:hover{color:var(--gray-700) !important;background:var(--gray-100) !important;}

/* Section labels */
.nav-label{
  color:var(--gray-400) !important;font-size:10.5px !important;
  font-weight:700 !important;letter-spacing:1.4px !important;
  padding:14px 18px 6px !important;text-transform:uppercase;opacity:1 !important;
}
.nav-sublabel{color:var(--gray-400) !important;}
.nav-section-chevron{color:var(--gray-400) !important;}

/* Nav items */
.nav-item{
  color:var(--gray-700) !important;
  font-size:13px !important;font-weight:500 !important;
  padding:10px 14px !important;margin:2px 10px !important;
  border-radius:10px !important;
  transition:all .18s cubic-bezier(.4,0,.2,1) !important;
}
.nav-item:hover{
  background:var(--gray-100) !important;
  color:var(--gray-900) !important;
}
.nav-item.active{
  background:#eff6ff !important;
  color:var(--primary-dark) !important;
  font-weight:700 !important;
  box-shadow:inset 0 0 0 1px rgba(37,99,235,.18), 0 2px 8px -4px rgba(37,99,235,.25) !important;
}
.nav-item.active .nav-icon{color:var(--primary) !important;}
.nav-icon{color:var(--gray-500);font-size:15px !important;}
.nav-item:hover .nav-icon{color:var(--gray-800);}
.nav-badge{
  background:var(--gray-100) !important;color:var(--gray-700) !important;
  border-radius:999px !important;padding:2px 8px !important;
  font-size:10px !important;font-weight:700 !important;
}
.nav-item.active .nav-badge{background:var(--primary) !important;color:#fff !important;}

.sidebar-collapse-btn{
  background:var(--gray-100) !important;border:1px solid var(--gray-200) !important;
  color:var(--gray-500) !important;
}
.sidebar-collapse-btn:hover{background:#dbeafe !important;color:var(--primary) !important;}

/* ═══════════ TOPBAR ═══════════ */
.topbar{
  background:rgba(255,255,255,.92) !important;
  backdrop-filter:saturate(160%) blur(12px);
  -webkit-backdrop-filter:saturate(160%) blur(12px);
  border-bottom:1px solid var(--gray-200) !important;
  box-shadow:0 1px 0 rgba(15,23,42,.02) !important;
}

/* ═══════════ MAIN / PAGES ═══════════ */
.main{background:transparent !important;}
.content, .page{animation:pageFade .35s ease-out;}
@keyframes pageFade{from{opacity:0;transform:translateY(6px);}to{opacity:1;transform:none;}}

/* ═══════════ CARDS ═══════════ */
.card, .chart-card, .kpi-card, .stat-card, .form-card, .panel{
  background:#fff !important;
  border:1px solid var(--gray-200) !important;
  border-radius:var(--radius-lg) !important;
  box-shadow:var(--shadow) !important;
  transition:transform .25s cubic-bezier(.4,0,.2,1), box-shadow .25s, border-color .25s !important;
}
.card:hover, .chart-card:hover, .kpi-card:hover, .stat-card:hover{
  box-shadow:var(--shadow-md) !important;
  border-color:#c7d2fe !important;
  transform:translateY(-2px);
}

/* ═══════════ VIBRANT GRADIENT KPI TILES ═══════════ */
.adv-kpi{
  position:relative;overflow:hidden;
  border:none !important;color:#fff !important;
  border-radius:var(--radius-lg) !important;
  padding:20px !important;min-height:120px;
  
  box-shadow:0 12px 30px -12px rgba(37,99,235,.5), inset 0 1px 0 rgba(255,255,255,.15) !important;
  transition:transform .25s cubic-bezier(.4,0,.2,1), box-shadow .25s !important;
}
.adv-kpi:hover{transform:translateY(-3px);box-shadow:0 18px 40px -12px rgba(37,99,235,.6), inset 0 1px 0 rgba(255,255,255,.2) !important;}
.adv-kpi::after{
  content:"";position:absolute;right:-30px;bottom:-30px;
  width:140px;height:140px;border-radius:50%;
  background:radial-gradient(circle,rgba(255,255,255,.18) 0%,rgba(255,255,255,0) 70%);
  pointer-events:none;
}
.adv-kpi:nth-of-type(6n+1){box-shadow:0 12px 30px -12px rgba(37,99,235,.5), inset 0 1px 0 rgba(255,255,255,.15) !important;}
.adv-kpi:nth-of-type(6n+2){box-shadow:0 12px 30px -12px rgba(16,185,129,.5), inset 0 1px 0 rgba(255,255,255,.15) !important;}
.adv-kpi:nth-of-type(6n+3){box-shadow:0 12px 30px -12px rgba(8,145,178,.5), inset 0 1px 0 rgba(255,255,255,.15) !important;}
.adv-kpi:nth-of-type(6n+4){box-shadow:0 12px 30px -12px rgba(249,115,22,.5), inset 0 1px 0 rgba(255,255,255,.15) !important;}
.adv-kpi:nth-of-type(6n+5){box-shadow:0 12px 30px -12px rgba(139,92,246,.5), inset 0 1px 0 rgba(255,255,255,.15) !important;}
.adv-kpi:nth-of-type(6n+6){box-shadow:0 12px 30px -12px rgba(239,68,68,.5), inset 0 1px 0 rgba(255,255,255,.15) !important;}


.adv-kpi .kpi-label, .adv-kpi small, .adv-kpi .kpi-sub, .adv-kpi .kpi-caption{
  color:rgba(255,255,255,.85) !important;
  font-size:11px !important;font-weight:700 !important;
  letter-spacing:1.2px;text-transform:uppercase;
}
.adv-kpi .kpi-value{
  font-family:'Plus Jakarta Sans',sans-serif !important;
  font-size:30px !important;font-weight:800 !important;
  letter-spacing:-.02em;line-height:1.1;margin:6px 0 4px;
}
.adv-kpi .kpi-icon{
  background:rgba(255,255,255,.2) !important;
  backdrop-filter:blur(6px);
  border-radius:12px;padding:8px;
  font-size:22px !important;
  box-shadow:inset 0 0 0 1px rgba(255,255,255,.25);
  position:relative;z-index:1;
}

/* ═══════════ BUTTONS ═══════════ */
.btn, button.btn, .btn-primary, .btn-success, .btn-danger, .btn-warning, .btn-info, .btn-secondary{
  border-radius:10px !important;
  font-weight:600 !important;letter-spacing:.01em;
  transition:transform .12s ease, box-shadow .2s, filter .2s !important;
  box-shadow:var(--shadow-xs);
}
.btn:hover, button.btn:hover{transform:translateY(-1px);filter:brightness(1.05);box-shadow:var(--shadow-md);}
.btn:active, button.btn:active{transform:translateY(0);filter:brightness(.97);}
.btn-primary{color:#fff !important;border:none !important;box-shadow:0 6px 16px -6px rgba(37,99,235,.5) !important;}
.btn-success{color:#fff !important;border:none !important;}
.btn-danger{color:#fff !important;border:none !important;}
.btn-warning{color:#fff !important;border:none !important;}
.btn-info{background:var(--grad-sky) !important;color:#fff !important;border:none !important;}
.btn-secondary{background:#fff !important;color:var(--gray-800) !important;border:1px solid var(--gray-200) !important;}
.btn-secondary:hover{background:var(--gray-50) !important;border-color:var(--gray-400) !important;}

/* ═══════════ FORMS ═══════════ */
input, select, textarea{
  border-radius:10px !important;
  border:1px solid var(--gray-200) !important;
  background:#fff !important;
  transition:border-color .18s, box-shadow .18s, background .18s !important;
}
input:focus, select:focus, textarea:focus{
  outline:none !important;
  border-color:var(--primary-light) !important;
  box-shadow:0 0 0 4px rgba(59,130,246,.15) !important;
}
label{font-weight:600;color:var(--gray-700);}

/* ═══════════ TABLES ═══════════ */
table{border-collapse:separate !important;border-spacing:0;}
table thead th, .table thead th{
  background:linear-gradient(180deg,#f8fafc,#eef2f8) !important;
  color:var(--gray-600) !important;
  font-weight:700 !important;letter-spacing:.05em;
  text-transform:uppercase;font-size:11px !important;
  border-bottom:1px solid var(--gray-200) !important;
  position:sticky;top:0;z-index:1;
}
table tbody tr{transition:background .15s;}
table tbody tr:hover{background:#eff6ff !important;}
table tbody td{border-bottom:1px solid #f1f5f9 !important;}

/* ═══════════ BADGES ═══════════ */
.badge, .status, .tag, .chip{
  border-radius:999px !important;font-weight:600 !important;
  padding:3px 10px !important;letter-spacing:.02em;
  box-shadow:inset 0 0 0 1px rgba(15,23,42,.04);
}

/* ═══════════ MODALS ═══════════ */
.m-box, .modal, .modal-content, .dialog{
  border-radius:20px !important;
  border:1px solid var(--gray-200) !important;
  box-shadow:0 30px 60px -20px rgba(2,6,23,.35), 0 12px 24px -12px rgba(2,6,23,.2) !important;
  animation:modalIn .28s cubic-bezier(.16,1,.3,1);
}
@keyframes modalIn{from{opacity:0;transform:translateY(12px) scale(.98);}to{opacity:1;transform:none;}}
.modal-overlay, .m-overlay, .overlay{
  background:rgba(15,23,42,.5) !important;
  backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);
}

/* ═══════════ FAB ═══════════ */
#fab, .fab{
  
  box-shadow:0 12px 30px -8px rgba(37,99,235,.5), 0 4px 12px rgba(37,99,235,.35) !important;
  transition:transform .2s, box-shadow .2s !important;
}
#fab:hover, .fab:hover{transform:translateY(-2px) scale(1.05);}

/* ═══════════ BOTTOM NAV (mobile) ═══════════ */
#bottom-nav{
  background:rgba(255,255,255,.95) !important;
  backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);
  border-top:1px solid var(--gray-200) !important;
  box-shadow:0 -8px 30px -12px rgba(15,23,42,.15) !important;
}

/* ═══════════ TOASTS ═══════════ */
.toast, .notification, #save-indicator{
  border-radius:12px !important;box-shadow:var(--shadow-lg) !important;
  backdrop-filter:blur(10px);
}

/* Charts */
.chart-card{padding:20px;}
.chart-card canvas{border-radius:10px;}

/* Focus ring */
:focus-visible{outline:2px solid var(--primary-light);outline-offset:2px;border-radius:8px;}

/* Section titles */
.page-header, .page-title, h1.page, h2.page{
  font-family:'Plus Jakarta Sans',sans-serif;letter-spacing:-.02em;font-weight:800;
}

/* Tablet */
@media (min-width:769px) and (max-width:1180px){
  .adv-kpi-grid{grid-template-columns:repeat(2,1fr) !important;gap:14px !important;}
  .content, .page{padding:16px !important;}
}

/* Mobile sidebar keeps light theme */
@media (max-width:768px){
  .sidebar{box-shadow:4px 0 24px rgba(15,23,42,.15) !important;}
  .hamburger{background:#eff6ff !important;border:1px solid #dbeafe !important;}
  .hamburger span{background:var(--primary) !important;}
}

/* Reduced motion */
@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{animation-duration:.001ms !important;transition-duration:.001ms !important;}
}

/* ── Clean Page Headers ── */
.page > div:first-child{
  padding-top:22px !important;
  padding-bottom:16px !important;
  margin-bottom:22px !important;
  border-bottom:2px solid #16a34a !important;
}
.page > div:first-child h2{
  font-size:24px !important;
  line-height:1.35 !important;
  margin:0 0 6px 0 !important;
  color:#0f3d26 !important;
}
.page > div:first-child p{
  font-size:13px !important;
  color:#6b7280 !important;
  margin:0 !important;
}
[data-theme="dark"] .page > div:first-child h2{color:#4ade80 !important;}
[data-theme="dark"] .page > div:first-child p{color:#94a3b8 !important;}
[data-theme="dark"] .page > div:first-child{border-color:#22c55e !important;}
@media (max-width:768px){
  .page > div:first-child{padding-top:16px !important;padding-bottom:12px !important;margin-bottom:16px !important;}
  .page > div:first-child h2{font-size:20px !important;}
}
</style>

</head>
