<script nonce="<?php echo $cspNonceAttr; ?>">
function dashQuickTx(type){
  openModal('mTx');
  var sel=document.getElementById('tx-type');
  if(sel){
    sel.value=type;
    try{ smartTypeToPartyType(); }catch(e){}
    try{ calcSalesTax(); }catch(e){}
    try{ txSectionsForType(type); }catch(e){}
  }
}
</script>

