<script nonce="<?php echo $cspNonceAttr; ?>">
(function(){
  var root=document.getElementById('hero-carousel');
  var slides=root.querySelectorAll('.hero-slide');
  var dotsWrap=document.getElementById('hero-dots');
  var idx=0, timer=null, DUR=6000;
  slides.forEach(function(_,i){
    var b=document.createElement('button');
    b.className='hero-dot'+(i===0?' active':'');
    b.setAttribute('aria-label','Slide '+(i+1));
    b.onclick=function(){heroSet(i);restart();};
    dotsWrap.appendChild(b);
  });
  window.heroSet=function(n){
    slides[idx].classList.remove('active');
    dotsWrap.children[idx].classList.remove('active');
    idx=(n+slides.length)%slides.length;
    slides[idx].classList.add('active');
    var d=dotsWrap.children[idx];
    d.classList.remove('active');void d.offsetWidth;d.classList.add('active');
  };
  window.heroGo=function(d){heroSet(idx+d);restart();};
  function restart(){if(timer)clearInterval(timer);timer=setInterval(function(){heroSet(idx+1);},DUR);}
  root.addEventListener('mouseenter',function(){if(timer){clearInterval(timer);timer=null;}});
  root.addEventListener('mouseleave',restart);
  root.addEventListener('keydown',function(e){if(e.key==='ArrowLeft')heroGo(-1);else if(e.key==='ArrowRight')heroGo(1);});
  var sx=null;
  root.addEventListener('touchstart',function(e){sx=e.touches[0].clientX;},{passive:true});
  root.addEventListener('touchend',function(e){if(sx==null)return;var dx=e.changedTouches[0].clientX-sx;if(Math.abs(dx)>40)heroGo(dx<0?1:-1);sx=null;},{passive:true});
  restart();
})();
</script>
<!-- END HERO CAROUSEL -->
