<!-- ALL OPTIONS — CLICKABLE CARD HUB                          -->
<!-- ═══════════════════════════════════════════════════════ -->
<div class="page" id="pg-menuhub">
<style>
/* ═══ WIRED CONTROL PANEL — desktop monitor + cabled module cards ═══ */
#pg-menuhub{--wire:#16a34a;--wire-glow:rgba(22,163,74,.45);}
.hubx-wrap{max-width:1500px;margin:0 auto;}
/* Desktop monitor */
.hubx-monitor{width:min(560px,92%);margin:0 auto;position:relative;z-index:2;}
.hubx-screen{background:linear-gradient(160deg,#0a1f14,#0f3d26 55%,#14532d);border:6px solid #1f2937;border-radius:14px;box-shadow:0 18px 45px rgba(0,0,0,.35), inset 0 0 40px rgba(74,222,128,.12);padding:22px 26px;text-align:center;position:relative;overflow:hidden;}
.hubx-screen::after{content:'';position:absolute;inset:0;background:linear-gradient(115deg,transparent 40%,rgba(255,255,255,.07) 48%,transparent 56%);pointer-events:none;}
.hubx-cam{width:7px;height:7px;border-radius:50%;background:#374151;position:absolute;top:8px;left:50%;transform:translateX(-50%);box-shadow:inset 0 0 3px #000;}
.hubx-screen h2{color:#fff;font-size:19px;font-weight:900;margin:4px 0 2px;letter-spacing:.5px;}
.hubx-screen .sub{color:#86efac;font-size:11px;font-weight:700;letter-spacing:2px;text-transform:uppercase;}
.hubx-stats{display:flex;justify-content:center;gap:18px;margin-top:12px;flex-wrap:wrap;}
.hubx-stat{color:#d1fae5;font-size:11px;font-weight:600;background:rgba(255,255,255,.08);border:1px solid rgba(134,239,172,.35);border-radius:20px;padding:4px 14px;}
.hubx-stat b{color:#4ade80;font-family:monospace;font-size:13px;}
.hubx-neck{width:70px;height:26px;background:linear-gradient(#374151,#1f2937);margin:0 auto;border-radius:0 0 6px 6px;}
.hubx-base{width:190px;height:12px;background:linear-gradient(#4b5563,#1f2937);margin:0 auto;border-radius:10px;box-shadow:0 6px 14px rgba(0,0,0,.3);}
/* Main cable trunk from monitor to the bus */
.hubx-trunk{width:6px;height:42px;margin:0 auto;background:repeating-linear-gradient(180deg,var(--wire) 0 8px,#15803d 8px 12px);border-radius:4px;box-shadow:0 0 10px var(--wire-glow);position:relative;}
.hubx-trunk::after{content:'';position:absolute;bottom:-7px;left:50%;transform:translateX(-50%);width:16px;height:16px;border-radius:50%;background:radial-gradient(circle,#4ade80 30%,var(--wire) 70%);box-shadow:0 0 14px var(--wire-glow);animation:hubxPulse 2s infinite;}
@keyframes hubxPulse{0%,100%{box-shadow:0 0 8px var(--wire-glow);}50%{box-shadow:0 0 20px var(--wire-glow);}}
/* Horizontal cable bus */
.hubx-bus{height:6px;margin:14px 2% 0;background:repeating-linear-gradient(90deg,var(--wire) 0 14px,#15803d 14px 20px);border-radius:4px;box-shadow:0 0 10px var(--wire-glow);}
/* Search sits on the bus like a control */
.hubx-searchrow{display:flex;justify-content:center;margin:18px 0 8px;}
.hubx-search{width:min(460px,92%);padding:11px 18px;border:2px solid #bbf7d0;border-radius:24px;font-size:14px;outline:none;box-shadow:0 4px 14px rgba(22,163,74,.12);transition:all .2s;}
.hubx-search:focus{border-color:var(--wire);box-shadow:0 0 0 4px rgba(22,163,74,.15);}
/* Card grid */
.hubx-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:34px 22px;padding:34px 8px 10px;}
/* Each module card, wired to the bus with its own cable + plug */
.hubx-card{background:#fff;border:1.5px solid #e5e7eb;border-radius:14px;box-shadow:0 4px 16px rgba(0,0,0,.07);position:relative;transition:all .2s ease;display:flex;flex-direction:column;overflow:visible;}
.hubx-card::before{content:'';position:absolute;top:-34px;left:50%;transform:translateX(-50%);width:5px;height:34px;background:repeating-linear-gradient(180deg,var(--ac,#16a34a) 0 7px,rgba(0,0,0,.18) 7px 10px);border-radius:3px;}
.hubx-card::after{content:'';position:absolute;top:-8px;left:50%;transform:translateX(-50%);width:14px;height:14px;border-radius:4px;background:var(--ac,#16a34a);border:3px solid #fff;box-shadow:0 0 0 2px var(--ac,#16a34a),0 0 12px var(--wire-glow);}
.hubx-card:hover{transform:translateY(-4px);box-shadow:0 14px 32px rgba(0,0,0,.14);border-color:var(--ac,#16a34a);}
.hubx-card-head{display:flex;align-items:center;gap:11px;padding:15px 16px 12px;border-bottom:2px solid #f1f5f9;background:linear-gradient(180deg,color-mix(in srgb,var(--ac,#16a34a) 8%,#fff),#fff);border-radius:14px 14px 0 0;}
.hubx-card-ic{width:42px;height:42px;border-radius:11px;display:flex;align-items:center;justify-content:center;font-size:21px;background:color-mix(in srgb,var(--ac,#16a34a) 14%,#fff);border:1.5px solid color-mix(in srgb,var(--ac,#16a34a) 35%,#fff);}
.hubx-card-title{font-size:14px;font-weight:800;color:#111827;}
.hubx-card-count{margin-left:auto;font-size:10px;font-weight:800;color:#fff;background:var(--ac,#16a34a);border-radius:12px;padding:3px 10px;}
/* The card's OWN MENU */
.hubx-menu{list-style:none;margin:0;padding:6px 0;flex:1;}
.hubx-menu li{display:flex;align-items:center;gap:10px;padding:8px 16px;font-size:12.5px;font-weight:600;color:#374151;cursor:pointer;border-left:3px solid transparent;transition:all .13s;}
.hubx-menu li:hover{background:color-mix(in srgb,var(--ac,#16a34a) 9%,#fff);border-left-color:var(--ac,#16a34a);color:#0f3d26;padding-left:20px;}
.hubx-menu li .mi{font-size:15px;width:20px;text-align:center;}
.hubx-menu li .go{margin-left:auto;font-size:11px;font-weight:800;color:var(--ac,#16a34a);opacity:0;transition:opacity .13s;}
.hubx-menu li:hover .go{opacity:1;}
.hubx-led{width:7px;height:7px;border-radius:50%;background:var(--ac,#16a34a);box-shadow:0 0 6px var(--ac,#16a34a);animation:hubxPulse 2.4s infinite;}
@media(max-width:640px){.hubx-grid{grid-template-columns:1fr;gap:30px 0;}.hubx-screen h2{font-size:15px;}}
</style>
<div class="hubx-wrap">
  <div class="hubx-monitor">
    <div class="hubx-screen">
      <div class="hubx-cam"></div>
      <h2>🌿 AYAN AGRO ERP — CONTROL PANEL</h2>
      <div class="sub">All Modules · Wired &amp; Live</div>
      <div class="hubx-stats" id="hubx-stats"></div>
    </div>
    <div class="hubx-neck"></div>
    <div class="hubx-base"></div>
  </div>
  <div class="hubx-trunk"></div>
  <div class="hubx-bus"></div>
