<!-- TENDER MODAL -->
<div id="tender-modal" style="display:none;position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:1000;align-items:center;justify-content:center;">
  <div style="background:#fff;border-radius:12px;padding:24px;width:560px;max-width:95vw;max-height:90vh;overflow-y:auto;box-shadow:0 20px 60px rgba(0,0,0,.3);">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;">
      <h3 style="font-size:16px;font-weight:800;color:#0f3d26;margin:0;">📋 Add New Tender</h3>
      <button data-x-click="closeModalById('tender-modal')" style="background:none;border:none;font-size:20px;cursor:pointer;color:#6b7280;">✕</button>
    </div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;">
      <div style="grid-column:1/-1;"><label style="font-size:11px;font-weight:600;color:#374151;">Tender Title</label>
        <input id="td-title" type="text" placeholder="Tender title / description" style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;margin-top:4px;box-sizing:border-box;"/></div>
      <div><label style="font-size:11px;font-weight:600;color:#374151;">Tender No</label>
        <input id="td-no" type="text" placeholder="Tender reference number" style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;margin-top:4px;box-sizing:border-box;"/></div>
      <div><label style="font-size:11px;font-weight:600;color:#374151;">Organization</label>
        <input id="td-org" type="text" placeholder="Issuing organization" style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;margin-top:4px;box-sizing:border-box;"/></div>
      <div><label style="font-size:11px;font-weight:600;color:#374151;">Tender Value (৳)</label>
        <input id="td-value" type="number" step="1000" min="0" placeholder="0" style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;margin-top:4px;box-sizing:border-box;"/></div>
      <div><label style="font-size:11px;font-weight:600;color:#374151;">Security Deposit (৳)</label>
        <input id="td-security" type="number" step="100" min="0" placeholder="0" style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;margin-top:4px;box-sizing:border-box;"/></div>
      <div><label style="font-size:11px;font-weight:600;color:#374151;">Submission Date</label>
        <input id="td-submit" type="date" style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;margin-top:4px;box-sizing:border-box;"/></div>
      <div><label style="font-size:11px;font-weight:600;color:#374151;">Opening Date</label>
        <input id="td-open" type="date" style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;margin-top:4px;box-sizing:border-box;"/></div>
      <div><label style="font-size:11px;font-weight:600;color:#374151;">Status</label>
        <select id="td-status" style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;margin-top:4px;">
          <option value="Preparing">Preparing</option>
          <option value="Submitted">Submitted</option>
          <option value="Under Review">Under Review</option>
          <option value="Won">Won</option>
          <option value="Lost">Lost</option>
          <option value="Cancelled">Cancelled</option>
        </select></div>
      <div><label style="font-size:11px;font-weight:600;color:#374151;">Product / Category</label>
        <input id="td-product" type="text" placeholder="Rice Bran Oil, etc." style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;margin-top:4px;box-sizing:border-box;"/></div>
      <div style="grid-column:1/-1;"><label style="font-size:11px;font-weight:600;color:#374151;">Notes</label>
        <textarea id="td-notes" rows="2" placeholder="Additional notes..." style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;margin-top:4px;box-sizing:border-box;resize:vertical;"></textarea></div>
    </div>
    <div style="display:flex;gap:8px;margin-top:16px;justify-content:flex-end;">
      <button data-x-click="closeModalById('tender-modal')" style="padding:8px 16px;background:#f3f4f6;border:1px solid #d1d5db;border-radius:7px;font-size:12px;cursor:pointer;">Cancel</button>
      <button data-x-click="saveTender()" style="padding:8px 20px;background:#16a34a;color:#fff;border:none;border-radius:7px;font-size:12px;font-weight:700;cursor:pointer;">💾 Save Tender</button>
    </div>
  </div>
</div>


