<!-- USER MODAL -->
<div id="user-modal" style="display:none;position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:1000;align-items:center;justify-content:center;">
  <div style="background:#fff;border-radius:12px;padding:24px;width:460px;max-width:95vw;box-shadow:0 20px 60px rgba(0,0,0,.3);">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;">
      <h3 style="font-size:16px;font-weight:800;color:#0f3d26;margin:0;">👤 Add User</h3>
      <button data-x-click="closeModalById('user-modal')" style="background:none;border:none;font-size:20px;cursor:pointer;color:#6b7280;">✕</button>
    </div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;">
      <div style="grid-column:1/-1;"><label style="font-size:11px;font-weight:600;color:#374151;">Full Name</label>
        <input id="usr-name" type="text" placeholder="Full name" style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;margin-top:4px;box-sizing:border-box;"/></div>
      <div><label style="font-size:11px;font-weight:600;color:#374151;">Username</label>
        <input id="usr-username" type="text" placeholder="Login username" style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;margin-top:4px;box-sizing:border-box;"/></div>
      <div><label style="font-size:11px;font-weight:600;color:#374151;">PIN / Password</label>
        <input id="usr-pin" type="password" placeholder="4-6 digit PIN" style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;margin-top:4px;box-sizing:border-box;"/></div>
      <div><label style="font-size:11px;font-weight:600;color:#374151;">Role</label>
        <select id="usr-role" style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;margin-top:4px;">
          <option value="Admin">Admin</option>
          <option value="Manager">Manager</option>
          <option value="Operator" selected>Operator</option>
          <option value="Viewer">Viewer</option>
        </select></div>
      <div><label style="font-size:11px;font-weight:600;color:#374151;">Department</label>
        <select id="usr-dept" style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;margin-top:4px;">
          <option>Operations</option><option>Finance</option><option>Sales</option><option>Admin</option><option>Warehouse</option>
        </select></div>
      <div><label style="font-size:11px;font-weight:600;color:#374151;">Phone</label>
        <input id="usr-phone" type="text" placeholder="Phone number" style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;margin-top:4px;box-sizing:border-box;"/></div>
    </div>
    <div style="margin-top:12px;">
      <label style="font-size:11px;font-weight:600;color:#374151;display:block;margin-bottom:6px;">Permissions</label>
      <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px;">
        <label style="display:flex;align-items:center;gap:5px;font-size:11px;cursor:pointer;">
          <input type="checkbox" id="perm-dashboard" checked style="accent-color:#16a34a;"/> Dashboard
        </label>
        <label style="display:flex;align-items:center;gap:5px;font-size:11px;cursor:pointer;">
          <input type="checkbox" id="perm-transactions" checked style="accent-color:#16a34a;"/> Transactions
        </label>
        <label style="display:flex;align-items:center;gap:5px;font-size:11px;cursor:pointer;">
          <input type="checkbox" id="perm-reports" checked style="accent-color:#16a34a;"/> Reports
        </label>
        <label style="display:flex;align-items:center;gap:5px;font-size:11px;cursor:pointer;">
          <input type="checkbox" id="perm-parties" checked style="accent-color:#16a34a;"/> Parties
        </label>
        <label style="display:flex;align-items:center;gap:5px;font-size:11px;cursor:pointer;">
          <input type="checkbox" id="perm-inventory" checked style="accent-color:#16a34a;"/> Inventory
        </label>
        <label style="display:flex;align-items:center;gap:5px;font-size:11px;cursor:pointer;">
          <input type="checkbox" id="perm-finance" checked style="accent-color:#16a34a;"/> Finance
        </label>
        <label style="display:flex;align-items:center;gap:5px;font-size:11px;cursor:pointer;">
          <input type="checkbox" id="perm-payroll" checked style="accent-color:#16a34a;"/> Payroll
        </label>
        <label style="display:flex;align-items:center;gap:5px;font-size:11px;cursor:pointer;">
          <input type="checkbox" id="perm-admin" checked style="accent-color:#16a34a;"/> Admin
        </label>
        <label style="display:flex;align-items:center;gap:5px;font-size:11px;cursor:pointer;">
          <input type="checkbox" id="perm-export" checked style="accent-color:#16a34a;"/> Export
        </label>
      </div>
    </div>
    <div style="display:flex;gap:8px;margin-top:16px;justify-content:flex-end;">
      <button data-x-click="closeModalById('user-modal')" style="padding:8px 16px;background:#f3f4f6;border:1px solid #d1d5db;border-radius:7px;font-size:12px;cursor:pointer;">Cancel</button>
      <button data-x-click="saveUser()" style="padding:8px 20px;background:#16a34a;color:#fff;border:none;border-radius:7px;font-size:12px;font-weight:700;cursor:pointer;">💾 Save User</button>
    </div>
  </div>
</div>


