      <div><label style="font-size:11px;font-weight:600;color:#374151;">Due Date</label>
        <input id="chq-due" type="date" style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;margin-top:4px;box-sizing:border-box;"/></div>
      <div><label style="font-size:11px;font-weight:600;color:#374151;">Status</label>
        <select id="chq-status" style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;margin-top:4px;">
          <option value="Pending">Pending</option>
          <option value="Cleared">Cleared</option>
          <option value="Bounced">Bounced</option>
          <option value="Cancelled">Cancelled</option>
