<!-- STOCK ADJUSTMENT MODAL -->
<div id="stockadj-modal" style="display:none;position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:1000;align-items:center;justify-content:center;">
  <div style="background:#fff;border-radius:14px;padding:24px;width:440px;max-width:95vw;box-shadow:0 20px 60px rgba(0,0,0,.3);">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:18px;">
      <h3 style="font-size:16px;font-weight:800;color:#0f3d26;margin:0;">⚖️ Stock Adjustment</h3>
      <button data-x-click="closeModalById('stockadj-modal')" style="background:#f3f4f6;border:none;width:30px;height:30px;border-radius:50%;cursor:pointer;font-size:16px;">✕</button>
    </div>
    <div style="display:flex;flex-direction:column;gap:12px;">
      <div><label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Date *</label>
        <input id="sa-date" type="date" style="width:100%;padding:8px 12px;border:1px solid #d1d5db;border-radius:7px;font-size:12px;box-sizing:border-box;"/></div>
      <div><label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Product *</label>
        <select id="sa-product" style="width:100%;padding:8px 12px;border:1px solid #d1d5db;border-radius:7px;font-size:12px;box-sizing:border-box;">
          <option value="">-- Select Product --</option>
        </select></div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">
        <div><label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Adjustment Type</label>
          <select id="sa-adjtype" style="width:100%;padding:8px 12px;border:1px solid #d1d5db;border-radius:7px;font-size:12px;box-sizing:border-box;">
            <option value="add">Add Stock (+)</option><option value="remove">Remove Stock (-)</option><option value="set">Set Exact Qty</option>
          </select></div>
        <div><label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Quantity *</label>
          <input id="sa-qty" type="number" placeholder="0" style="width:100%;padding:8px 12px;border:1px solid #d1d5db;border-radius:7px;font-size:12px;box-sizing:border-box;"/></div>
      </div>
      <div><label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Reason</label>
        <select id="sa-reason" style="width:100%;padding:8px 12px;border:1px solid #d1d5db;border-radius:7px;font-size:12px;box-sizing:border-box;">
          <option>Physical Count</option><option>Damage/Loss</option><option>Theft</option><option>Expiry</option><option>Transfer</option><option>Other</option>
        </select></div>
      <div><label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Notes</label>
        <input id="sa-notes" placeholder="Optional notes" style="width:100%;padding:8px 12px;border:1px solid #d1d5db;border-radius:7px;font-size:12px;box-sizing:border-box;"/></div>
    </div>
    <div style="display:flex;gap:10px;margin-top:18px;justify-content:flex-end;">
      <button data-x-click="closeModalById('stockadj-modal')" style="padding:9px 20px;background:#f3f4f6;border:1px solid #d1d5db;border-radius:7px;font-size:12px;cursor:pointer;">Cancel</button>
      <button data-x-click="saveStockAdj()" style="padding:9px 20px;background:linear-gradient(90deg,#16a34a,#15803d);color:#fff;border:none;border-radius:7px;font-size:12px;font-weight:700;cursor:pointer;">💾 Save Adjustment</button>
    </div>
  </div>
</div>

