<div id="employee-modal" style="display:none;position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:1000;align-items:center;justify-content:center;">
  <div style="background:#fff;border-radius:12px;padding:24px;width:480px;max-width:95vw;box-shadow:0 20px 60px rgba(0,0,0,.3);">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;">
      <h3 id="employee-modal-title" style="font-size:16px;font-weight:800;color:#0f3d26;margin:0;">👤 Add Employee</h3>
      <button data-x-click="closeModalById('employee-modal')" style="background:none;border:none;font-size:20px;cursor:pointer;color:#6b7280;">✕</button>
    </div>
    <input type="hidden" id="emp-edit-id" value="">
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;">
      <div style="grid-column:1/-1;"><label style="font-size:11px;font-weight:600;color:#374151;">Full Name</label>
        <input id="emp-name" type="text" placeholder="Employee name" style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;margin-top:4px;box-sizing:border-box;"/></div>
      <div><label style="font-size:11px;font-weight:600;color:#374151;">Designation</label>
        <input id="emp-role" type="text" placeholder="Job title" style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;margin-top:4px;box-sizing:border-box;"/></div>
      <div><label style="font-size:11px;font-weight:600;color:#374151;">Department</label>
        <select id="emp-dept" style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;margin-top:4px;">
          <option>Operations</option><option>Sales</option><option>Finance</option><option>Admin</option><option>Warehouse</option>
        </select></div>
      <div><label style="font-size:11px;font-weight:600;color:#374151;">Basic Salary (৳)</label>
        <input id="emp-salary" type="number" step="100" min="0" placeholder="0" style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;margin-top:4px;box-sizing:border-box;"/></div>
      <div><label style="font-size:11px;font-weight:600;color:#374151;">Join Date</label>
        <input id="emp-join" type="date" style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;margin-top:4px;box-sizing:border-box;"/></div>
      <div><label style="font-size:11px;font-weight:600;color:#374151;">Phone</label>
        <input id="emp-phone" type="text" placeholder="Phone number" style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;margin-top:4px;box-sizing:border-box;"/></div>
      <div><label style="font-size:11px;font-weight:600;color:#374151;">NID / ID No</label>
        <input id="emp-nid" type="text" placeholder="National ID" style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;margin-top:4px;box-sizing:border-box;"/></div>
    </div>
    <div style="display:flex;gap:8px;margin-top:16px;justify-content:flex-end;">
      <button data-x-click="closeModalById('employee-modal')" style="padding:8px 16px;background:#f3f4f6;border:1px solid #d1d5db;border-radius:7px;font-size:12px;cursor:pointer;">Cancel</button>
      <button data-x-click="saveEmployee()" style="padding:8px 20px;background:#16a34a;color:#fff;border:none;border-radius:7px;font-size:12px;font-weight:700;cursor:pointer;">💾 Save Employee</button>
    </div>
  </div>
</div>


