    <div style="display:flex;gap:8px;">
      <button data-x-click="renderMasterData()" style="padding:8px 16px;background:#16a34a;color:#fff;border:none;border-radius:7px;font-size:12px;font-weight:700;cursor:pointer;">🔄 Refresh</button>
    </div>
  </div>
  <div id="md-body"></div>
</div>

