<div class="overlay" id="mTx">
<div class="modal" style="max-width:980px;padding:0;overflow:hidden;">
<div class="modal-title" style="border-radius:0;margin:0;">
  <span id="mTx-title">💰 New Transaction — Unified Sales Entry</span>
  <span class="modal-close" data-x-click="closeModal('mTx')">&#x2715;</span>
</div>
<input type="hidden" id="tx-edit-id" value="">

<!-- Unified Sales Form Styles (scoped inside modal) -->
<style>
.ust-cell-input {
  width:100%;padding:.375rem .5rem;border:1px solid #cbd5e1;border-radius:.375rem;
  font-size:.8rem;transition:all .15s ease-in-out;background:#fff;
}
.ust-cell-input:focus{outline:none;border-color:#1b4385;box-shadow:0 0 0 2px rgba(27,67,133,.2);}
.ust-readonly{background:#f8fafc;font-weight:600;cursor:not-allowed;}
.ust-green{background:#d1e7dd!important;color:#0f5132!important;font-weight:700;}
.ust-orange{background:#ffe69c!important;color:#664d03!important;font-weight:700;}
.ust-sec-hd{background:#1b4385;color:#fff;padding:.5rem 1rem;font-weight:600;font-size:.8rem;display:flex;align-items:center;gap:.5rem;}
.ust-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem;padding:1rem;background:rgba(248,250,252,.5);}
.ust-grid-2{display:grid;grid-template-columns:repeat(2,1fr);gap:1rem;padding:1rem;background:rgba(248,250,252,.5);}
.ust-label{display:block;font-size:.7rem;font-weight:600;color:#374151;margin-bottom:.25rem;}
.ust-pen-blue{background:#eff6ff;padding:.6rem;border-radius:.5rem;border:1px solid #bfdbfe;}
.ust-pen-amber{background:#fffbeb;padding:.6rem;border-radius:.5rem;border:1px solid #fde68a;}
.ust-pen-red{background:#fff1f2;padding:.6rem;border-radius:.5rem;border:1px solid #fecdd3;}
.ust-pen-green{background:#ecfdf5;padding:.6rem;border-radius:.5rem;border:1px solid #a7f3d0;}
.ust-nutrition-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:.75rem;padding:1rem;background:linear-gradient(135deg,rgba(239,246,255,.96),rgba(248,250,252,.92));}
.ust-nutrition-field{position:relative;padding:.65rem;background:rgba(255,255,255,.82);border:1px solid #bfdbfe;border-radius:.5rem;box-shadow:0 4px 14px rgba(30,64,175,.06);}
.ust-nutrition-field .ust-label{color:#1e3a8a;}
.ust-nutrition-result{background:linear-gradient(135deg,#ecfdf5,#eff6ff);border-color:#86efac;}
.ust-unit{position:absolute;right:1rem;bottom:1.03rem;color:#64748b;font-size:.68rem;font-weight:700;pointer-events:none;}
.ust-has-unit{padding-right:2.3rem;}
@media(max-width:900px){.ust-nutrition-grid{grid-template-columns:repeat(2,minmax(0,1fr));}}
@media(max-width:680px){.ust-grid,.ust-grid-2,.ust-nutrition-grid{grid-template-columns:1fr;}}

/* ── NTX spreadsheet-style paired label/value rows (Sections 1,2,3,6,7,8) ── */
.ntx-block{border:1px solid #94a3b8;border-radius:.5rem;overflow:hidden;margin-bottom:.75rem;background:#fff;}
.ntx-hd{background:#122a52;color:#fff;font-weight:700;font-size:.78rem;padding:.5rem .85rem;display:flex;align-items:center;gap:.5rem;letter-spacing:.01em;}
.ntx-hd .ntx-hint{margin-left:auto;font-weight:400;font-size:.68rem;color:#bcd0f7;}
.ntx-rows{display:grid;grid-template-columns:1fr 1.5fr 1fr 1.5fr;}
@media(max-width:760px){.ntx-rows{grid-template-columns:1fr 1.5fr;}}
.ntx-lbl{background:#eef2f8;font-weight:700;font-size:.68rem;color:#1e293b;display:flex;align-items:center;padding:.4rem .6rem;border-top:1px solid #dbe3ee;border-left:1px solid #dbe3ee;}
.ntx-val{background:#fffdf2;display:flex;align-items:center;padding:.25rem .4rem;border-top:1px solid #dbe3ee;border-left:1px solid #dbe3ee;border-right:1px solid #dbe3ee;}
.ntx-val.ro{background:#eef2f7;}
.ntx-val.blank{background:#fafafa;}
.ntx-val input,.ntx-val select{width:100%;border:none;background:transparent;padding:.3rem .15rem;font-size:.76rem;outline:none;color:#1e293b;}
.ntx-val select{cursor:pointer;}
.ntx-val input:focus,.ntx-val select:focus{background:#fff;box-shadow:inset 0 0 0 2px #1b4385;border-radius:.25rem;}
.ntx-val input[readonly]{cursor:not-allowed;font-weight:700;color:#0f5132;}
.ntx-pen-blue{background:#eaf2ff;}
.ntx-pen-amber{background:#fff8e6;}
.ntx-pen-red{background:#fff0f1;}
.ntx-pen-green{background:#e9fbf3;}
.ntx-total-row{display:grid;grid-template-columns:1fr 1.5fr;border-top:2px solid #94a3b8;}
.ntx-total-row .ntx-lbl{background:#122a52;color:#fff;font-size:.75rem;}
.ntx-total-row .ntx-val{background:#eef7ee;font-weight:800;font-size:.85rem;color:#0f5132;justify-content:flex-end;text-align:right;}
.ntx-note{grid-column:1/-1;padding:.4rem .7rem;font-size:.68rem;color:#64748b;font-style:italic;background:#fafafa;border-top:1px solid #dbe3ee;}
</style>

<div style="max-height:80vh;overflow-y:auto;padding:.5rem;">

<!-- SECTION 1: GENERAL INFORMATION & MULTI-POOL ROUTING -->
<div class="ntx-block">
<div class="ntx-hd"><i class="fa-regular fa-file-lines"></i> 1. GENERAL INFORMATION &amp; MULTI-POOL ROUTING</div>
<div class="ntx-rows">
  <div class="ntx-lbl">Date *</div>
  <div class="ntx-val"><input type="date" id="tx-date" class="fc" required/></div>
  <div class="ntx-lbl">Invoice No</div>
  <div class="ntx-val"><input type="text" id="tx-inv" placeholder="INV-2026-001" class="fc"/></div>

  <div class="ntx-lbl">PO Number</div>
  <div class="ntx-val"><input type="text" id="tx-po" placeholder="PO-88291" class="fc"/></div>
  <div class="ntx-lbl">GRN No.</div>
  <div class="ntx-val"><input type="text" id="tx-grn" placeholder="GRN-5502" class="fc"/></div>

  <div class="ntx-lbl">Challan No.</div>
  <div class="ntx-val"><input type="text" id="tx-challan" placeholder="CH-9921" class="fc"/></div>
  <div class="ntx-lbl">Transaction Type *</div>
  <div class="ntx-val">
    <select id="tx-type" class="fc" data-x-change="smartTypeToPartyType();calcSalesTax();calcWeightLoss();autoFillSaleCosts();autoFillPurchaseCosts();autoFillWarehousePurchaseProduct()">
      <option value="">-- Select Type --</option>
      <option value="Purchase">🛒 Purchase</option>
      <option value="Sale">💰 Sales</option>
      <option value="Warehouse Purchase">🏪 Warehouse Purchase</option>
      <option value="Supplier Payment">🏦 Supplier Payment</option>
      <option value="Customer Collection">👥 Customer Collection</option>
      <option value="Bkash Receive">📱 Bkash Receive</option>
      <option value="Expense">💸 Expense</option>
      <optgroup label="── Purchase ──">
        <option>Purchase</option><option>Purchase Return</option><option>Supplier Purchase</option>
        <option>Supplier Payment</option><option>Supplier Refund</option><option>Advance to Supplier</option>
        <option>Supplier Due</option><option>Supplier Advance</option>
      </optgroup>
      <optgroup label="── Sales ──">
        <option>Sale</option><option>Sales Return</option><option>Customer Sale</option>
        <option>Customer Collection</option><option>Customer Payment Received</option>
        <option>Advance from Customer</option><option>Customer Due</option>
      </optgroup>
      <optgroup label="── Warehouse ──">
        <option>Warehouse Purchase</option><option>Warehouse Sale</option><option>Warehouse Transfer</option>
      </optgroup>
      <optgroup label="── Expenses ──">
        <option>Expense</option><option>Staff Salary</option><option>Utility Bill</option><option>Office Expense</option>
        <option>Transport Cost</option><option>Unload Cost</option><option>Extra Cost</option>
        <option>Expense Payment</option>
      </optgroup>
      <optgroup label="── Banking ──">
        <option>Bank Deposit</option><option>Bank Withdrawal</option>
        <option>Inter Bank Transfer</option><option>Inter-Account Transfer</option>
        <option>Bkash Payment Paid</option><option>Bkash Receive</option><option>Bkash Receive from Agent</option>
      </optgroup>
      <optgroup label="── Partners ──">
        <option>Partner Fund</option><option>Partner Withdrawal</option>
      </optgroup>
      <optgroup label="── Production ──">
        <option>Raw Material Issue</option><option>Finished Goods Entry</option><option>Production Cost</option>
        <option>Manufacturing Consumption</option><option>Manufacturing Output</option>
      </optgroup>
      <optgroup label="── Opening Balances ──">
        <option>Opening Balance</option><option>Opening Cash Balance</option><option>Opening Bank Balance</option>
        <option>Opening Customer Due</option><option>Opening Supplier Due</option>
        <option>Opening Stock</option><option>Opening Warehouse Purchase</option>
      </optgroup>
      <optgroup label="── Other ──">
        <option>Transfer (Internal)</option><option>Journal</option>
      </optgroup>
    </select>
  </div>

  <!-- Hidden from New Transaction form per Ayan's request (2026-09-13): not
       needed on entry. Kept in the DOM (display:none) so any code that reads
       tx-sourcepool / tx-destpool / tx-supervisor keeps working. -->
  <div class="ntx-lbl" style="display:none;">Source Pool (Dispatch Godown)</div>
  <div class="ntx-val ntx-pen-blue" style="display:none;"><select id="tx-sourcepool" class="fc" style="font-weight:600;color:#1e40af;">
      <option value="Main Godown (Kushtia)">Main Godown (Kushtia)</option>
      <option value="Factory Yard Pool">Factory Yard Pool</option>
      <option value="Mojumpur Depot">Mojumpur Depot</option>
      <option value="Central Warehouse">Central Warehouse</option>
      <option value="Processing Facility">External Processing Facility</option>
    </select></div>
  <div class="ntx-lbl" style="display:none;">Destination Pool (Receiving)</div>
  <div class="ntx-val" style="display:none;"><select id="tx-destpool" class="fc">
      <option value="Customer Site">Customer Site / External Delivery</option>
      <option value="Main Godown (Kushtia)">Main Godown (Kushtia)</option>
      <option value="Factory Yard Pool">Factory Yard Pool</option>
      <option value="Mojumpur Depot">Mojumpur Depot</option>
      <option value="Central Warehouse">Central Warehouse</option>
      <option value="Transit Pool">Transit / In-Transit Pool</option>
    </select></div>

  <div class="ntx-lbl" style="display:none;">Dispatch Supervisor</div>
  <div class="ntx-val" style="display:none;"><input type="text" id="tx-supervisor" placeholder="Supervisor Name" class="fc"/></div>
  <div class="ntx-lbl blank-lbl" style="background:#fafafa;"></div>
  <div class="ntx-val blank"></div>
</div>
</div>

<!-- SECTION 2: PARTY INFORMATION -->
<div class="ntx-block">
<div class="ntx-hd"><i class="fa-solid fa-users"></i> 2. PARTY INFORMATION</div>
<div class="ntx-rows">
  <div class="ntx-lbl">Party Name</div>
  <div class="ntx-val"><input type="text" id="tx-party" list="dl-party" placeholder="Type or select party..." class="fc" data-x-input="smartPartyAutoFill()" data-x-change="smartPartyAutoFill()"/><datalist id="dl-party"></datalist></div>
  <div class="ntx-lbl">Party Type</div>
  <div class="ntx-val"><select id="tx-ptype" class="fc">
      <option>Customer</option><option>Supplier</option><option>Both</option>
      <option>Partner</option><option>Employee</option><option>Other</option>
    </select></div>

  <div class="ntx-lbl">Location Zone</div>
  <div class="ntx-val"><select id="tx-loc" class="fc" data-x-change="autoFillSaleCosts()">
      <option>Dhaka</option><option>Chittagong</option><option>Narsingdi</option>
      <option>Bogura</option><option>Sirajganj</option><option>Chuadanga</option>
      <option>Jashore</option><option>Valuka</option><option>Birganj</option>
      <option>Kushtia</option><option>Mojumpur</option>
    </select></div>
  <div class="ntx-lbl blank-lbl" style="background:#fafafa;"></div>
  <div class="ntx-val blank"></div>
</div>
</div>

<!-- SECTION 3: PRODUCT & 3-PEN WEIGHBRIDGE -->
<div class="ntx-block" id="txsec-product">
<div class="ntx-hd"><i class="fa-solid fa-weight-scale"></i> 3. PRODUCT &amp; WEIGHBRIDGE SCALE DETAILS (3 WEIGHT PENS)
  <span class="ntx-hint"><i class="fa-solid fa-circle-info"></i> Dispatch vs. Buyer Scale Discrepancy Tracking</span>
</div>
<div class="ntx-rows">
  <div class="ntx-lbl">Product / Purpose</div>
  <div class="ntx-val"><input type="text" id="tx-prod" list="dl-prod" placeholder="Select product..." class="fc" data-x-input-set-dataset="autoFilled" data-x-input-set-val="false"/><datalist id="dl-prod"></datalist></div>
  <div class="ntx-lbl">Bag Type</div>
  <div class="ntx-val"><select id="tx-bagtype" class="fc">
      <option value="Plastic">Plastic Bag (150g Tare)</option>
      <option value="Jute">Jute Bag (700g Tare)</option>
      <option value="Bulk">Bulk / Loose (0g Tare)</option>
    </select></div>

  <!-- Hidden from New Transaction form per Ayan's request (2026-09-13): not
       needed on entry. Kept in the DOM (display:none) so smartCalcAmount()/
       calcDue()/etc. that read these IDs (as optional overrides/fallbacks)
       keep working. -->
  <div class="ntx-lbl" style="display:none;">Batch / Serial No</div>
  <div class="ntx-val" style="display:none;"><input type="text" id="tx-batchno" placeholder="BATCH-2026-X" class="fc"/></div>
  <div class="ntx-lbl">Bag Qty</div>
  <div class="ntx-val"><input type="number" id="tx-bagqty" min="0" step="any" placeholder="0" class="fc" style="font-weight:600;" data-x-input="smartCalcAmount();calcTx();autoFillSaleCosts();autoFillPurchaseCosts();calcWeightLoss()"/></div>

  <div class="ntx-lbl" style="display:none;">Return Bag Qty</div>
  <div class="ntx-val" style="display:none;"><input type="number" id="tx-bagret" min="0" step="any" placeholder="0" class="fc"/></div>
  <div class="ntx-lbl" style="display:none;">Bag Tare Weight (g/bag)</div>
  <div class="ntx-val" style="display:none;"><input type="number" id="tx-tare-grams" min="0" step="1" placeholder="150" class="fc" data-x-input="smartCalcAmount();calcDue()"/></div>

  <div class="ntx-lbl" style="display:none;">QTY (KG / Ltr / Pcs) *</div>
  <div class="ntx-val" style="display:none;"><input type="number" id="tx-qty" min="0" placeholder="0" class="fc" data-x-input="smartCalcAmount();calcDue();calcTotalCost();autoFillSaleCosts();autoFillPurchaseCosts()"/></div>
  <div class="ntx-lbl">Pen 1: Dispatch Weighbridge Weight (KG)</div>
  <div class="ntx-val ntx-pen-blue"><input type="number" id="tx-grosswt" min="0" step="any" placeholder="0.00" style="font-weight:700;color:#1e40af;" data-x-input="smartCalcAmount();calcTotalOil();calcDue();autoFillSaleCosts();autoFillPurchaseCosts();calcWeightLoss()"/></div>

  <div class="ntx-lbl">Pen 2: Buyer / Company Received Weight (KG)</div>
  <div class="ntx-val ntx-pen-amber"><input type="number" id="tx-wt" min="0" step="any" placeholder="0.00" style="font-weight:700;color:#92400e;" data-x-input="smartCalcAmount();calcTotalOil();calcDue();autoFillSaleCosts();autoFillPurchaseCosts();calcWeightLoss()"/></div>
  <!-- Hidden from New Transaction form per Ayan's request (2026-09-13): kept
       in the DOM (display:none) so calcWeightLoss() keeps working. -->
  <div class="ntx-lbl" style="display:none;">Weight Shortage / Discrepancy (KG)</div>
  <div class="ntx-val ro ntx-pen-red" style="display:none;"><input type="text" id="tx-wdiscrepancy" readonly style="color:#9f1239;font-weight:700;text-align:right;"/></div>

  <div class="ntx-lbl">Pen 3: Final Billable Net Weight (KG) — Auto</div>
  <div class="ntx-val ro ntx-pen-green"><input type="text" id="tx-netweight" readonly style="text-align:right;font-weight:700;color:#065f46;"/></div>
  <div class="ntx-lbl">Rate (&#x9F3;/KG)</div>
  <div class="ntx-val"><input type="number" id="tx-rate" min="0" step="any" placeholder="0.00" style="font-weight:600;" data-x-input="smartCalcAmount();txProfitHint();calcDue();calcWeightLoss()"/></div>

  <div class="ntx-lbl">Amount (&#x9F3;) *</div>
  <div class="ntx-val"><input type="number" id="tx-amt" min="0" placeholder="0.00" style="font-weight:700;" data-x-input="calcSalesTax();calcDue();calcAdvanceControl()"/></div>
  <div class="ntx-lbl blank-lbl" style="background:#fafafa;"></div>
  <div class="ntx-val blank"></div>
</div>
</div>

<!-- PRODUCT NUTRITION & QUALITY SPECIFICATION (optional lab/QC values) -->
<!-- 2026-09-13: converted from "hidden per Ayan's request" to a collapsible
     toggle — closed by default, opened on demand via the header click.
     No longer tied to transaction type (see txSectionsForType()). -->
<div style="border:1px solid #bfdbfe;border-radius:.5rem;overflow:hidden;margin-bottom:.75rem;" id="txsec-nutrition" data-section="nutrition-quality">
<div class="ust-sec-hd" style="justify-content:space-between;cursor:pointer;" data-x-click="toggleNutritionSection()">
  <div style="display:flex;align-items:center;gap:.5rem;"><i class="fa-solid fa-flask"></i> PRODUCT NUTRITION &amp; QUALITY SPECIFICATION</div>
  <span style="font-size:.7rem;color:#fde68a;display:flex;align-items:center;gap:.5rem;">
    <i class="fa-solid fa-circle-info"></i> Batch lab / QC certificate values
    <i class="fa-solid fa-chevron-down" id="tx-nutrition-chevron" style="transition:transform .15s ease;font-size:.75rem;"></i>
  </span>
</div>
<div class="ust-nutrition-grid" id="tx-nutrition-body" style="display:none;">
  <div class="ust-nutrition-field">
    <label class="ust-label" for="tx-oilpct">Oil / Fat Content</label>
    <input type="number" id="tx-oilpct" name="oilPct" min="0" max="100" step="0.01" inputmode="decimal" placeholder="0.00" class="ust-cell-input ust-has-unit fc" data-x-input="calcTotalOil()"/>
    <span class="ust-unit">%</span>
  </div>
  <div class="ust-nutrition-field ust-nutrition-result">
    <label class="ust-label" for="tx-totaloil" style="color:#065f46;font-weight:700;">Total Oil — Auto</label>
    <input type="text" id="tx-totaloil" name="totalOil" readonly aria-readonly="true" class="ust-cell-input ust-readonly ust-green ust-has-unit" style="text-align:right;font-weight:700;"/>
    <span class="ust-unit">KG</span>
    <div id="tx-totaloil-hint" aria-live="polite" style="font-size:.65rem;color:#6b7280;margin-top:.2rem;min-height:.85rem;"></div>
  </div>
  <div class="ust-nutrition-field">
    <label class="ust-label" for="tx-moisture">Moisture</label>
    <input type="number" id="tx-moisture" name="moisturePct" min="0" max="100" step="0.01" inputmode="decimal" placeholder="0.00" class="ust-cell-input ust-has-unit fc"/><span class="ust-unit">%</span>
  </div>
  <div class="ust-nutrition-field">
    <label class="ust-label" for="tx-protein">Protein</label>
    <input type="number" id="tx-protein" name="proteinPct" min="0" max="100" step="0.01" inputmode="decimal" placeholder="0.00" class="ust-cell-input ust-has-unit fc"/><span class="ust-unit">%</span>
  </div>
  <div class="ust-nutrition-field">
    <label class="ust-label" for="tx-fiber">Fiber</label>
    <input type="number" id="tx-fiber" name="fiberPct" min="0" max="100" step="0.01" inputmode="decimal" placeholder="0.00" class="ust-cell-input ust-has-unit fc"/><span class="ust-unit">%</span>
  </div>
  <div class="ust-nutrition-field">
    <label class="ust-label" for="tx-ash">Ash</label>
    <input type="number" id="tx-ash" name="ashPct" min="0" max="100" step="0.01" inputmode="decimal" placeholder="0.00" class="ust-cell-input ust-has-unit fc"/><span class="ust-unit">%</span>
  </div>
  <div class="ust-nutrition-field">
    <label class="ust-label" for="tx-ffa">FFA — Free Fatty Acid</label>
    <input type="number" id="tx-ffa" name="ffaPct" min="0" max="100" step="0.01" inputmode="decimal" placeholder="0.00" class="ust-cell-input ust-has-unit fc"/><span class="ust-unit">%</span>
  </div>
</div>
</div>

<!-- SECTION 4: FINANCIAL SALES DEDUCTIONS & ADJUSTMENTS -->
<div style="border:1px solid #e2e8f0;border-radius:.5rem;overflow:hidden;margin-bottom:.75rem;">
<div class="ust-sec-hd"><i class="fa-solid fa-calculator"></i> 4. FINANCIAL SALES DEDUCTIONS &amp; ADJUSTMENTS</div>
<div class="ust-grid-2">
  <div style="display:flex;flex-direction:column;gap:.6rem;">
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:.5rem;align-items:center;">
      <label class="ust-label" style="margin:0;">Bag Deduction Rate (&#x9F3;/KG)</label>
      <input type="number" id="tx-bag-deduct-rate" step="any" min="0" value="150.00" class="ust-cell-input" data-x-input="safeCalcDue()"/>
    </div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:.5rem;align-items:center;">
      <label class="ust-label" style="margin:0;">Sales Tax Rate (%)</label>
      <input type="number" id="tx-tax-rate" step="any" min="0" value="0.05" class="ust-cell-input" data-x-input="calcSalesTax()"/>
    </div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:.5rem;align-items:center;">
      <label class="ust-label" style="margin:0;">Unrealized / Non-Realization Adjustment (&#x9F3;)</label>
      <input type="number" id="tx-unrealized" step="any" min="0" value="0.00" placeholder="Waiver / Loss" class="ust-cell-input" data-x-input="safeCalcDue()"/>
    </div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:.5rem;align-items:center;">
      <input type="text" id="tx-custom-deduct-name" value="Other Deduction" class="ust-cell-input" style="font-size:.7rem;border-style:dashed;"/>
      <input type="number" id="tx-custom-deduct-val" step="any" min="0" value="0.00" placeholder="Amount" class="ust-cell-input" data-x-input="safeCalcDue()"/>
    </div>
  </div>
  <div style="background:#fff;padding:.75rem;border-radius:.375rem;border:1px solid #e2e8f0;display:flex;flex-direction:column;gap:.6rem;">
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:.5rem;align-items:center;">
      <span class="ust-label" style="margin:0;">Bag Deduction Amount (&#x9F3;)</span>
      <input type="text" id="tx-bag-deduct-amt" readonly class="ust-cell-input ust-readonly ust-green" style="text-align:right;"/>
    </div>
    <div id="tx-tax-section" style="display:grid;grid-template-columns:1fr 1fr;gap:.5rem;align-items:center;">
      <span class="ust-label" style="margin:0;">Sales Tax Deduction (&#x9F3;) <span id="tx-tax-pct-display" style="font-weight:400;color:#94a3b8;"></span></span>
      <input type="text" id="tx-tax-amt" readonly class="ust-cell-input ust-readonly ust-green" style="text-align:right;"/>
    </div>
    <div id="tx-wloss-section" style="display:none;grid-template-columns:1fr 1fr;gap:.5rem;align-items:center;">
      <span class="ust-label" style="margin:0;">Weight Loss (KG) <span id="tx-wloss-pct-display" style="font-weight:400;color:#94a3b8;"></span></span>
      <input type="text" id="tx-wloss-kg" readonly class="ust-cell-input ust-readonly ust-green" style="text-align:right;"/>
    </div>
    <div id="tx-wlossamt-section" style="display:none;grid-template-columns:1fr 1fr;gap:.5rem;align-items:center;">
      <span class="ust-label" style="margin:0;">Weight Loss Deduction (&#x9F3;)</span>
      <input type="text" id="tx-wloss-amt" readonly class="ust-cell-input ust-readonly ust-green" style="text-align:right;"/>
    </div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:.5rem;align-items:center;">
      <span class="ust-label" style="margin:0;">Unrealized Adjustment (&#x9F3;)</span>
      <input type="text" id="tx-unrealized-amt" readonly class="ust-cell-input ust-readonly ust-green" style="text-align:right;"/>
    </div>
    <div id="tx-net-section" style="display:grid;grid-template-columns:1fr 1fr;gap:.5rem;align-items:center;padding-top:.4rem;border-top:1px solid #e2e8f0;">
      <span class="ust-label" style="margin:0;font-weight:800;color:#1e293b;">Total — Net Sales Value (&#x9F3;)</span>
      <input type="text" id="tx-net-amt" readonly class="ust-cell-input ust-readonly ust-orange" style="text-align:right;font-size:.9rem;"/>
    </div>
  </div>
</div>
</div>

<!-- SECTION 5: PAYMENT SETTLEMENT & SCHEDULE ENGINE -->
<div class="ntx-block">
<div class="ntx-hd"><i class="fa-solid fa-file-invoice-dollar"></i> 5. PAYMENT SETTLEMENT &amp; SCHEDULE ENGINE
  <span class="ntx-hint"><i class="fa-solid fa-calendar-check"></i> Mon/Wed Dues ➔ Tue/Thu Bank Deposits</span>
</div>
<div class="ntx-rows">
  <div class="ntx-lbl">Payment Terms</div>
  <div class="ntx-val"><select id="tx-payterms" class="fc" style="font-weight:600;">
      <option value="Net 7">Net 7 Days (Mon/Wed Target)</option>
      <option value="Net 15">Net 15 Days (Mon/Wed Target)</option>
      <option value="COD">Immediate / COD</option>
      <option value="Advance">Advance Payment</option>
    </select></div>
  <div class="ntx-lbl">Delivery Date</div>
  <div class="ntx-val"><input type="date" id="tx-deliverydate" class="fc"/></div>

  <div class="ntx-lbl">Payment Due Date (Mon/Wed) — Auto</div>
  <div class="ntx-val ro"><input type="text" id="tx-paydue-text" readonly style="font-weight:700;color:#0f5132;"/></div>
  <div class="ntx-lbl">Paid (&#x9F3;)</div>
  <div class="ntx-val"><input type="number" id="tx-paid" min="0" placeholder="0.00" class="fc" data-x-input="smartCalcDue()"/></div>

  <div class="ntx-lbl">Received (&#x9F3;)</div>
  <div class="ntx-val"><input type="number" id="tx-recv" min="0" placeholder="0.00" class="fc" data-x-input="smartCalcDue();"/></div>
  <div class="ntx-lbl">Outstanding Due (&#x9F3;) — Auto</div>
  <div class="ntx-val ro"><input type="text" id="tx-due" readonly style="text-align:right;font-weight:700;color:#0f5132;"/></div>

  <div class="ntx-lbl">Payment Mode</div>
  <div class="ntx-val"><select id="tx-mode" class="fc">
      <option>Cash</option><option>Bank</option><option>Bkash</option>
      <option>Nagad</option><option>Rocket</option><option>Mobile Banking</option>
      <option>Cheque</option><option>Online Transfer</option><option>Partial</option>
    </select></div>
  <div class="ntx-lbl">Receiving Bank / Cash Account</div>
  <div class="ntx-val"><select id="tx-acc" class="fc"><option value="">-- Select Account --</option></select></div>

  <div class="ntx-lbl">Note / Remarks</div>
  <div class="ntx-val" style="grid-column:span 3;"><input type="text" id="tx-rem" placeholder="Any additional notes..." class="fc"/></div>

  <div class="ntx-lbl">Supplier Bank / Account Reference</div>
  <div class="ntx-val" style="grid-column:span 3;display:flex;gap:.4rem;">
    <select id="tx-supplierbank" class="fc" style="flex:1;" data-x-change="onSupplierBankSelect()"><option value="">-- Select Bank Account --</option></select>
    <input type="text" id="tx-supplierbank-custom" placeholder="Type bank / account manually" class="fc" style="flex:1;display:none;" data-x-input="syncSupplierBankCustom()"/>
  </div>
</div>
</div>

<!-- SECTION 6: TRANSPORTATION & FREIGHT MANAGEMENT -->
<div class="ntx-block" id="txsec-transport">
<div class="ntx-hd"><i class="fa-solid fa-truck-front"></i> 6. TRANSPORTATION &amp; FREIGHT MANAGEMENT</div>
<div class="ntx-rows">
  <div class="ntx-lbl">Transport Type</div>
  <div class="ntx-val"><select id="tx-transporttype" class="fc">
      <option value="">-- No Transport --</option>
      <option value="Truck">Truck</option><option value="Van">Van</option>
      <option value="Covered Van">Covered Van</option><option value="Pickup">Pickup</option>
      <option value="Trailer">Trailer</option><option value="Lorry">Lorry</option>
      <option value="Tractor">Tractor</option><option value="CNG / Auto">CNG / Auto</option>
      <option value="Boat / Trawler">Boat / Trawler</option><option value="Rail">Rail</option>
      <option value="Courier">Courier</option><option value="Own Vehicle">Own Vehicle</option>
      <option value="Other">Other</option>
    </select></div>
  <div class="ntx-lbl" id="tx-vehicle-lbl">Vehicle / Truck ID</div>
  <div class="ntx-val"><input type="text" id="tx-truck" placeholder="Vehicle registration / ID" class="fc"/></div>

  <div class="ntx-lbl">Transport Rent (&#x9F3;)</div>
  <div class="ntx-val"><input type="number" id="tx-truckrent" min="0" step="any" placeholder="0.00" class="fc" data-x-input="calcTotalCost()"/></div>
  <div class="ntx-lbl">Paid Transport Rent (&#x9F3;)</div>
  <div class="ntx-val"><input type="number" id="tx-paid2" min="0" placeholder="0.00" class="fc"/></div>

  <div class="ntx-lbl">Due Transport Rent (&#x9F3;) — Auto</div>
  <div class="ntx-val ro"><input type="number" id="tx-due2" min="0" placeholder="0.00" readonly/></div>
  <div class="ntx-lbl">Transport / Cartage Paid From</div>
  <div class="ntx-val"><select id="tx-acc2" class="fc"><option value="">-- Select Account --</option></select></div>
</div>
</div>

<!-- SECTION 7: AGENT / QC / UNLOAD & OTHER COSTS -->
<!-- Hidden from New Transaction form per Ayan's request (2026-09-12): not needed on
     entry. Fields kept in the DOM (display:none) so existing calc functions
     (calcTotalCost, cost-line ledger, dashboard KPIs, CSV exports) that read
     these element IDs keep working for historical transactions. -->
<div class="ntx-block" id="txsec-costs" style="display:none;">
<div class="ntx-hd"><i class="fa-solid fa-user-tie"></i> 7. AGENT / QC / UNLOAD &amp; OTHER COSTS</div>
<div class="ntx-rows">
  <div class="ntx-lbl">Agent A <span id="tag-agentA" style="font-weight:400;color:#94a3b8;"></span></div>
  <div class="ntx-val"><select id="tx-agentA" class="fc"><option value="">-- Select Agent --</option></select></div>
  <div class="ntx-lbl">Agent A Cost (&#x9F3;)</div>
  <div class="ntx-val"><input type="number" id="tx-agentAcost" min="0" step="any" placeholder="0.00" class="fc" data-x-input="calcTotalCost()"/></div>

  <div class="ntx-lbl">Agent B <span id="tag-agentB" style="font-weight:400;color:#94a3b8;"></span></div>
  <div class="ntx-val"><select id="tx-agentB" class="fc"><option value="">-- Select Agent --</option></select></div>
  <div class="ntx-lbl">Agent B Cost (&#x9F3;)</div>
  <div class="ntx-val"><input type="number" id="tx-agentBcost" min="0" step="any" placeholder="0.00" class="fc" data-x-input="calcTotalCost()"/></div>

  <div class="ntx-lbl">QC Person</div>
  <div class="ntx-val"><input type="text" id="tx-qcperson" list="dl-agents" placeholder="Type or select..." class="fc"/></div>
  <div class="ntx-lbl">QC Cost (&#x9F3;) <span id="tag-qc" style="font-weight:400;color:#94a3b8;"></span></div>
  <div class="ntx-val"><input type="number" id="tx-qc" min="0" step="any" placeholder="0.00" class="fc" data-x-input="calcTotalCost()"/></div>

  <div class="ntx-lbl">Unload Person</div>
  <div class="ntx-val"><input type="text" id="tx-unloadperson" list="dl-agents" placeholder="Type or select..." class="fc"/></div>
  <div class="ntx-lbl">Unload Cost (&#x9F3;) <span id="tag-unload" style="font-weight:400;color:#94a3b8;"></span></div>
  <div class="ntx-val"><input type="number" id="tx-unload" min="0" step="any" placeholder="0.00" class="fc" data-x-input="calcTotalCost()"/></div>

  <div class="ntx-lbl">Other Cost Person</div>
  <div class="ntx-val"><input type="text" id="tx-otherperson" list="dl-agents" placeholder="Type or select..." class="fc"/></div>
  <div class="ntx-lbl">Other Cost (&#x9F3;) <span id="tag-other" style="font-weight:400;color:#94a3b8;"></span></div>
  <div class="ntx-val"><input type="number" id="tx-othercost" min="0" step="any" placeholder="0.00" class="fc" data-x-input="calcTotalCost()"/></div>

  <div class="ntx-lbl">Another 2 Person</div>
  <div class="ntx-val"><input type="text" id="tx-otherperson2" list="dl-agents" placeholder="Type or select..." class="fc"/></div>
  <div class="ntx-lbl">Another 2 Cost (&#x9F3;) <span id="tag-other2" style="font-weight:400;color:#94a3b8;"></span></div>
  <div class="ntx-val"><input type="number" id="tx-othercost2" min="0" step="any" placeholder="0.00" class="fc" data-x-input="calcTotalCost()"/></div>
</div>
<div class="ntx-total-row">
  <div class="ntx-lbl">Total Extra Cost (&#x9F3;) — Auto</div>
  <div class="ntx-val"><input type="text" id="tx-totalcost" readonly style="width:100%;border:none;background:transparent;text-align:right;font-weight:800;"/></div>
</div>
</div>

<!-- SECTION 8: PURCHASE PAYMENT & ADVANCE CONTROL -->
<!-- Hidden from New Transaction form per Ayan's request (2026-09-12): not needed
     on entry. Fields kept in the DOM (display:none) so onPurchasePayTypeChange()/
     calcAdvanceControl() and any code reading these IDs don't break. -->
<div class="ntx-block" id="txsec-purchpay" style="display:none;">
<div class="ntx-hd"><i class="fa-solid fa-hand-holding-dollar"></i> 8. PURCHASE PAYMENT &amp; ADVANCE CONTROL</div>
<div class="ntx-rows">
  <div class="ntx-lbl">Purchase Payment Type</div>
  <div class="ntx-val"><select id="tx-purchpaytype" class="fc" data-x-change="onPurchasePayTypeChange()">
      <option value="Not Applicable">Not Applicable (Sales)</option>
      <option value="Full Advance">Full Advance</option>
      <option value="Partial Advance">Partial Advance</option>
      <option value="Credit Purchase">Credit Purchase (No Advance)</option>
      <option value="Cash on Delivery">Cash on Delivery</option>
    </select></div>
  <div class="ntx-lbl">Agreed Supplier Due Date</div>
  <div class="ntx-val"><input type="date" id="tx-supplierduedate" class="fc"/></div>

  <div class="ntx-lbl">Advance Amount (&#x9F3;)</div>
  <div class="ntx-val"><input type="number" id="tx-advance-amt" min="0" step="any" placeholder="0.00" class="fc" data-x-input="calcAdvanceControl()"/></div>
  <div class="ntx-lbl">Advance Rate (%)</div>
  <div class="ntx-val"><input type="number" id="tx-advance-rate" min="0" max="100" step="any" placeholder="0.00" class="fc" data-x-input-set-dataset="userEdited" data-x-input-set-val="1" data-x-input="calcAdvanceControl()"/></div>

  <div class="ntx-lbl">Calculated Advance (&#x9F3;) — Auto</div>
  <div class="ntx-val ro"><input type="text" id="tx-advance-calc" readonly style="text-align:right;font-weight:700;color:#0f5132;"/></div>
  <div class="ntx-lbl">Remaining Supplier Balance (&#x9F3;) — Auto</div>
  <div class="ntx-val ro"><input type="text" id="tx-supplier-balance" readonly style="text-align:right;font-weight:700;color:#0f5132;"/></div>

  <div class="ntx-note">For Advance, enter either a fixed Advance Amount or an Advance Rate (%); a fixed amount always takes priority over the rate.</div>
</div>
</div>

<!-- Hidden legacy fields for backward compatibility -->
<input type="hidden" id="tx-bagdeduct-kg" value="0"/>
<input type="hidden" id="tx-bagdeduct-amt" value="0"/>
<input type="hidden" id="tx-purchdeduct-kg" value="0"/>
<input type="hidden" id="tx-purchdeduct-amt" value="0"/>
<input type="hidden" id="tx-profit" value="0"/>
<input type="hidden" id="tx-paydate" value=""/>
<input type="hidden" id="tx-paymentduedate" value=""/>
<input type="hidden" id="tx-serialno" value=""/>

</div><!-- end scrollable -->

<div class="form-actions" style="padding:.75rem 1rem;border-top:1px solid #e2e8f0;background:#f8fafc;display:flex;gap:.5rem;justify-content:flex-end;flex-wrap:wrap;">
  <button class="btn btn-ghost" data-x-click="closeModal('mTx')">Cancel</button>
  <button class="btn btn-sm" style="background:#64748b;color:#fff;" data-x-click="resetTxForm()" title="Clear every field and start fresh">↺ Reset Form</button>
  <button class="btn btn-sm" style="background:#2563eb;color:#fff;" data-x-click="getFinanceFromModal()" title="Send this transaction to Factory Finance (City Bank)">🏦 Get Finance</button>
  <button class="btn btn-success" data-x-click="saveTx()">💾 Save Transaction</button>
</div>
</div>
</div>
<!-- CUSTOMER MODAL -->
<div class="overlay" id="mCust"><input type="hidden" id="c-edit-id" value="0">
<div class="modal">
<div class="modal-title">👥 Add Party <span class="modal-close" data-x-click="closeModal('mCust')">✕</span></div>
<div class="form-grid-2">
<div class="fg"><label class="lbl">ID</label><input class="fc" id="c-code" readonly style="background:#f9fafb;font-weight:700;color:#2563eb;"/></div>
<div class="fg full"><label class="lbl">Party Name *</label><input class="fc" id="c-name" placeholder="Full name" type="text"/></div>
<div class="fg"><label class="lbl">Type *</label>
<select class="fc" id="c-type" data-x-change="updateEntityIdPreview('mCust')"><option>Customer</option><option>Supplier</option><option>Both</option><option>Other</option></select>
</div>
<div class="fg"><label class="lbl">Phone</label><input class="fc" id="c-phone" placeholder="+880-..." type="text"/></div>
<div class="fg"><label class="lbl">Current Balance (৳)</label><input class="fc" id="c-bal" placeholder="0" type="number"/></div>
<div class="fg"><label class="lbl">Credit Limit (৳)</label><input class="fc" id="c-lim" placeholder="0" type="number"/></div>
<div class="fg full"><label class="lbl">Address</label><input class="fc" id="c-addr" placeholder="City, District" type="text"/></div>
<div class="fg full"><label class="lbl">Email</label><input class="fc" id="c-email" placeholder="email@example.com" type="email"/></div>
<div class="fg full" id="c-bank-section" style="border-top:1px solid #e5e7eb;padding-top:12px;margin-top:4px;">
  <label class="lbl" style="font-weight:800;color:#2563eb;">🏦 Bank Account Details (for Suppliers)</label>
</div>
<div class="fg"><label class="lbl">Bank Name</label><input class="fc" id="c-bank-name" placeholder="e.g. Dutch Bangla Bank" type="text"/></div>
<div class="fg"><label class="lbl">Account Number</label><input class="fc" id="c-bank-acc" placeholder="Account number" type="text"/></div>
<div class="fg"><label class="lbl">Branch</label><input class="fc" id="c-bank-branch" placeholder="Branch name" type="text"/></div>
<div class="fg"><label class="lbl">Routing Number</label><input class="fc" id="c-bank-routing" placeholder="Routing number" type="text"/></div>
<div class="fg"><label class="lbl">Account Holder</label><input class="fc" id="c-bank-holder" placeholder="Account holder name" type="text"/></div>
<div class="fg span4"><label class="lbl">Additional Bank Accounts</label>
  <div id="c-extra-banks"></div>
  <button type="button" class="btn btn-xs" style="background:#f0fdf4;border:1px solid #16a34a;color:#16a34a;margin-top:6px;padding:6px 12px;font-weight:700;cursor:pointer;border-radius:6px;" data-x-click="addPartyBankRow()">➕ Add Another Bank Account</button>
</div>
<div class="fg"><label class="lbl">Notes</label><input class="fc" id="c-notes" placeholder="Additional notes" type="text"/></div>
</div>
<div class="form-actions">
<button class="btn btn-ghost" data-x-click="closeModal('mCust')">Cancel</button>
<button class="btn btn-success" data-x-click="saveCust()">💾 Save Party</button>
</div>
</div>
</div>
