// ─────────────────────────────────────────────────────────
// STATE
// ─────────────────────────────────────────────────────────
var DB = {
  users: [], tx: [], customers: [], partners: [], banks: [], assets: [],
  inventory: [], tenders: [], payroll: [], salaryHistory: [], empAdvances: [],
  customTemplates: [], auditLog: [], employees: [], agents: [], agentLedger: [],
  orders: [], expenses: [], products: [], leaves: [], attendance: [],
  recurring: [], notifications: [], settings: {}, nid: {}
};

// ── PARTY MASTER LIST (derived from the owner's official INIT data) ─────────
const PARTY_MASTER = {
  get customers(){ return (INIT.customers||[]).filter(c=>c.type==='Customer').map(c=>c.name); },
  get suppliers(){ return (INIT.customers||[]).filter(c=>c.type==='Supplier').map(c=>c.name); },
  get partners(){ return (INIT.partners||[]).map(p=>p.name); }
};
function normName(n){ return String(n||'').toLowerCase().replace(/[^a-z0-9]/g,''); }
/* Loose key: also ignores the "M S / M/S / MS / Mesars" business prefix so
   "M S Simra Traders" and "M/S SIMRA TRADERS" are recognised as ONE party. */
function normKey(n){
  let s = String(n||'').toLowerCase().replace(/[^a-z0-9 ]/g,' ');
  s = s.replace(/^\s*(m\s*s|ms|mesars?)\s+/,'');
  return s.replace(/\s+/g,'');
}
/* One-time master-data refresh (v3): every official name lands in the right
   panel, missing names are added, opening balances are filled in when the
   record still has none, and duplicates of the same real-world name are
   merged instead of piling up. */
function applyPartyMaster(){
  if(DB.partyMasterV==='v3') return;
  DB.customers=DB.customers||[]; DB.partners=DB.partners||[];
  DB.banks=DB.banks||[]; DB.products=DB.products||[]; DB.assets=DB.assets||[];
  DB.nid=DB.nid||{};

  // 1) collapse existing duplicates (keep the one carrying a balance/most data)
  const dedupe=(arr,valOf)=>{
    const keep={}, out=[];
    arr.forEach(r=>{
      const k=normKey(r&&r.name);
      if(!k) { out.push(r); return; }
      if(keep[k]===undefined){ keep[k]=out.length; out.push(r); return; }
      const cur=out[keep[k]];
      if(Math.abs(valOf(r)||0) > Math.abs(valOf(cur)||0)) out[keep[k]]=r;
    });
    return out;
  };
  DB.customers=dedupe(DB.customers,c=>c.bal||c.balance);
  DB.partners =dedupe(DB.partners, p=>p.cap||p.capital);
  DB.banks    =dedupe(DB.banks,    b=>b.bal||b.balance);
  DB.products =dedupe(DB.products, p=>p.stockQty);
  DB.assets   =dedupe(DB.assets,   a=>a.val||a.value);

  // 2) merge the official list in (match on the loose key — never duplicate)
  const merge=(list,seed,mk)=>{
    const idx={}; list.forEach((r,i)=>{ idx[normKey(r.name)]=i; });
    seed.forEach(s=>{
      const k=normKey(s.name), at=idx[k];
      if(at===undefined){ idx[k]=list.length; list.push(mk(s)); }
      else { const r=list[at]; Object.keys(s).forEach(f=>{
        if(f==='id'||f==='name') return;
        const sv=s[f];
        if(typeof sv==='number'){ if(!r[f]) r[f]=sv; }
        else if(sv!=='' && sv!=null && (r[f]===''||r[f]==null)) r[f]=sv;
      }); }
    });
    return list;
  };
  const nextId=(arr)=>arr.reduce((m,r)=>Math.max(m,+r.id||0),0)+1;
  DB.customers=merge(DB.customers,(INIT.customers||[]),s=>({...s,id:nextId(DB.customers)}));
  DB.partners =merge(DB.partners, (INIT.partners ||[]),s=>({...s,id:nextId(DB.partners)}));
  DB.banks    =merge(DB.banks,    (INIT.banks    ||[]),s=>({...s,id:nextId(DB.banks)}));
  DB.products =merge(DB.products, (INIT.products ||[]),s=>({...s,id:nextId(DB.products)}));
  DB.assets   =merge(DB.assets,   (INIT.assets   ||[]),s=>({...s,id:nextId(DB.assets)}));

  // 3) official types win, and partners live only in their own panel
  const seedType={}; (INIT.customers||[]).forEach(c=>{ seedType[normKey(c.name)]=c.type; });
  DB.customers.forEach(c=>{ const t=seedType[normKey(c.name)]; if(t) c.type=t; });
  const pNorm=(INIT.partners||[]).map(p=>normKey(p.name));
  DB.customers=DB.customers.filter(c=>pNorm.indexOf(normKey(c.name))===-1);

  // 4) locations
  DB.locations=DB.locations||[];
  const locNames=DB.locations.map(l=>normKey(l&&l.name?l.name:l));
  DEFAULT_LOCATIONS.forEach(n=>{ if(locNames.indexOf(normKey(n))===-1){ locNames.push(normKey(n)); DB.locations.push({id:newId(),name:n}); } });

  /* 5) opening balances — recorded as real opening entries so the balance
     reconciler keeps them instead of zeroing the party/bank out. */
  DB.openingBalances=DB.openingBalances||[];
  const obSeen={}; DB.openingBalances.forEach(o=>{ if(o&&o.party) obSeen[normKey(o.party)]=o; });
  (INIT.customers||[]).forEach(s=>{
    const amt=+(s.balance||s.bal||0); if(!amt) return;
    const rec=DB.customers.find(c=>normKey(c.name)===normKey(s.name)); if(!rec) return;
    const ex=obSeen[normKey(rec.name)];
    if(ex){ if(!+(ex.amount||ex.amt||0)) ex.amount=amt; }
    else { const o={party:rec.name,amount:amt,date:'2026-01-08',note:'Opening balance'}; DB.openingBalances.push(o); obSeen[normKey(rec.name)]=o; }
    if(!rec.bal) rec.bal=amt;
    if(!rec.openingBal) rec.openingBal=amt;
  });
  (INIT.banks||[]).forEach(s=>{
    const amt=+(s.balance||s.bal||0); if(!amt) return;
    const rec=DB.banks.find(b=>normKey(b.name)===normKey(s.name)); if(!rec) return;
    if(!rec.openingBal) rec.openingBal=amt;
    if(!rec.bal) rec.bal=amt;
  });
  (INIT.partners||[]).forEach(s=>{
    const amt=+(s.capital||s.cap||0); if(!amt) return;
    const rec=DB.partners.find(p=>normKey(p.name)===normKey(s.name)); if(!rec) return;
    if(!rec.cap) rec.cap=amt; if(!rec.capital) rec.capital=amt;
  });
  (INIT.assets||[]).forEach(s=>{
    const amt=+(s.value||s.val||0); if(!amt) return;
    const rec=DB.assets.find(a=>normKey(a.name)===normKey(s.name)); if(!rec) return;
    if(!rec.val) rec.val=amt; if(!rec.value) rec.value=amt; if(!rec.cost) rec.cost=amt;
  });


  DB.nid.c=nextId(DB.customers); DB.nid.p=nextId(DB.partners);
  DB.nid.b=nextId(DB.banks); DB.nid.pr=nextId(DB.products); DB.nid.a=nextId(DB.assets);
  DB.partyMasterV='v3';
  try{ saveDB(); }catch(e){}
}



// Opens a blank window for print/export output. Returns null (and shows a
// toast) instead of throwing when a popup blocker prevents window.open()
// from returning a usable window — previously every print/export call site
// did `window.open('','_blank')` and immediately called `.document.write()`
// on the result, which throws "Cannot read properties of null" whenever the
// popup was blocked.
function openPrintWindow(){
  const w = window.open('', '_blank');
  if(!w){
    if(typeof toast === 'function') toast('Popup blocked — please allow popups for this site to print.', 'e');
    else alert('Popup blocked — please allow popups for this site to print.');
    return null;
  }
  return w;
}

// MASTER: derived name-lists used as fallbacks when DB.masterData (a manually
// curated override list) hasn't been set up. This was previously referenced in
// ~16 places but never defined anywhere, which threw "MASTER is not defined"
// and broke party/product/location/bank dropdowns wherever it was hit.
const DEFAULT_LOCATIONS = ['Chittagong','Dhaka','Narsingdi','Bogura','Sirajganj','Chuadanga','Jessore','Valuka','Birganj','Kushtia','Moijampur'];
const MASTER = {
  get banks(){ return (DB.banks||[]).map(b=>b.name); },
  get parties(){ return [...(DB.customers||[]).map(c=>c.name), ...(DB.partners||[]).map(p=>p.name)]; },
  get products(){ return (DB.products||[]).map(p=>p.name); },
  /* Fall back to the standard city list so location dropdowns are never empty
     before any custom location has been added. */
  get locations(){
    const saved=(DB.locations||[]).map(l=>(l && l.name) ? l.name : l).filter(Boolean);
    return saved.length ? saved : DEFAULT_LOCATIONS.slice();
  }
};
let charts = {};
let txF = {search:'',type:'',mode:'',partyType:'',dateFrom:'',dateTo:''};


/* FIX 4: `DB.transactions` was a second, always-empty transaction list while the
   real data lives in `DB.tx`. It is now an alias of DB.tx. */
window._erpTxAlias=function(){
  try{
    var d=window.DB; if(!d||typeof d!=='object') return;
    var own=Object.getOwnPropertyDescriptor(d,'transactions');
    if(own&&own.get) return;
    if(own&&Array.isArray(d.transactions)&&d.transactions.length&&!(d.tx||[]).length) d.tx=d.transactions;
    delete d.transactions;
    Object.defineProperty(d,'transactions',{
      configurable:true,enumerable:false,
      get:function(){ if(!Array.isArray(d.tx)) d.tx=[]; return d.tx; },
      set:function(v){ if(Array.isArray(v)) d.tx=v; }
    });
  }catch(e){}
};

function loadDB(){
  /* SERVER-ONLY (2026-09-02): boot from the built-in defaults, never from a
     browser copy. loadDataFromServer() (api.php?action=load) fills DB in
     straight after login, so a stale local snapshot can no longer overwrite
     what is in MySQL. */
  try{
    DB = JSON.parse(JSON.stringify(INIT));
  }catch(e){ DB = JSON.parse(JSON.stringify(INIT)); }
  // One-time migration: correct the historical "Werhouse" typo in saved records
  try{
    let migrated=0;
    (DB.tx||[]).forEach(t=>{
      if(t.type==='Werhouse Purchase'){ t.type='Warehouse Purchase'; migrated++; }
      else if(t.type==='Opening Werhouse Purchase'){ t.type='Opening Warehouse Purchase'; migrated++; }
    });
    if(migrated>0){
      console.info('Migration: corrected "Werhouse" spelling on '+migrated+' transaction(s).');
      /* SERVER-ONLY: the corrected records are pushed to MySQL by the next
         saveDB() / autosave — never written to browser storage. */
    }
  }catch(e){}
  // Ensure all arrays exist with defaults
  if(!DB.banks) DB.banks = JSON.parse(JSON.stringify(INIT.banks||[]));
  if(!DB.partners) DB.partners = JSON.parse(JSON.stringify(INIT.partners||[]));
  if(!DB.products) DB.products = JSON.parse(JSON.stringify(INIT.products||[]));
  if(!DB.assets) DB.assets = JSON.parse(JSON.stringify(INIT.assets||[]));
  if(!DB.inventory) DB.inventory = JSON.parse(JSON.stringify(INIT.inventory||[]));
  if(!DB.customers) DB.customers = JSON.parse(JSON.stringify(INIT.customers||[]));
  try{ applyPartyMaster(); }catch(e){ console.error('party master', e); if(window.reportSilentError) reportSilentError('load', e.message, 'applyPartyMaster'); }
  // Normalise inventory on load: keeps DB.inventory an Array, merges it with
  // DB.products and repairs stock/qty/stockQty aliases from older saves.
  try{ if(typeof invItems==='function') invItems(); }catch(e){ console.warn('inventory normalise', e); }
  // Every collection the reports rely on must stay an Array.
  ['tx','customers','banks','partners','products','inventory','assets','tenders','employees','users'].forEach(function(k){
    if(DB[k] && !Array.isArray(DB[k])) DB[k] = Object.values(DB[k]);
    if(!DB[k]) DB[k] = [];
  });
  // One-time cleanup: remove the seeded dummy "Warehouse Stock" 802400 KG row
  if(DB.dummyStockCleaned!=='v1'){
    DB.inventory = (DB.inventory||[]).filter(i=>String(i.product||'').toLowerCase()!=='warehouse stock');
    DB.products  = (DB.products||[]).filter(p=>String(p.name||'').toLowerCase()!=='warehouse stock');
    DB.dummyStockCleaned='v1';
    try{ saveDB(); }catch(e){}
  }
  try{ window._erpTxAlias(); }catch(e){}  // FIX 4: transactions === tx
  try{ repairTxIds(); }catch(e){ console.warn('repairTxIds', e); }
  if(!DB.agents) DB.agents = [];
  if(!DB.agentLedger) DB.agentLedger = [];
  if(!DB.tenders) DB.tenders = [];
  if(!DB.employees) DB.employees = [];
  if(!DB.salaryHistory) DB.salaryHistory = [];
  if(!DB.empAdvances) DB.empAdvances = [];
  if(!DB.cheques) DB.cheques = [];
  if(!DB.customTemplates) DB.customTemplates = [];
  if(!DB.auditLog) DB.auditLog = [];
  if(!DB.challans) DB.challans = [];
  if(!DB.invoices) DB.invoices = [];
  if(!DB.paySchedules) DB.paySchedules = [];
  if(!DB.wastage) DB.wastage = [];
  if(!DB.loans) DB.loans = [];
  // Parboiled Costing / DORB module — previously these values lived only in
  // page-local variables/DOM inputs with no persistence, so they reset on
  // every refresh. They now live in DB and save via the normal saveDB() path.
  if(!DB.costSettings) DB.costSettings = {cost:{}, prod:{}};
  if(!DB.costSettings.cost) DB.costSettings.cost = {};
  if(!DB.costSettings.prod) DB.costSettings.prod = {};
  if(!DB.pbBatchRows) DB.pbBatchRows = [];
  if(!DB.dorbRows) DB.dorbRows = [];
  if(!DB.locationRates || !DB.locationRates.length){
    const _dorbRentMap = {'Valuka FM':1.5,'Narsingdi FM':1.0,'Dhaka FM':1.0,'Chittagong FM':2.0,'Birganj FM':1.0};
    const _dorbLocNames = ['Chuadanga FM','Jessore FM','Bogura FM','Valuka FM','Narsingdi FM','Dhaka FM','Chittagong FM','Birganj FM'];
    DB.locationRates = _dorbLocNames.map(name=>({name, rent: _dorbRentMap[name]!==undefined?_dorbRentMap[name]:0.7}));
  }
  // bankAccounts alias
  DB.bankAccounts = DB.banks;
  // Compatibility alias: DB.transactions mirrors DB.tx
  Object.defineProperty(DB, 'transactions', {
    get(){ return DB.tx||[]; },
    set(v){ DB.tx=v; },
    configurable:true
  });
  // Compatibility alias: DB.parties is a unified live view of customers
  // (type 'Customer'/'Supplier') plus partners (tagged type:'Partner').
  // Many report/reminder/dashboard functions were written against this
  // unified shape; DB.customers/DB.partners remain the real storage.
  Object.defineProperty(DB, 'parties', {
    get(){
      return [
        ...(DB.customers||[]),
        ...(DB.partners||[]).map(p=>({...p, type:'Partner'}))
      ];
    },
    configurable:true
  });
}

function saveObField(section, key, val){
  if(!DB.openingBal) DB.openingBal={customers:{},banks:{},partners:{},assets:{},suppliers:{}};
  if(!DB.openingBal[section]) DB.openingBal[section]={};
  const num=parseFloat(val)||0;
  DB.openingBal[section][key]=num;
  // Also update the actual record
  if(section==='banks'){
    const b=(DB.banks||[]).find(b=>b.name===key);
    if(b) b.bal=num;
  } else if(section==='partners'){
    const p=(DB.partners||[]).find(p=>p.name===key);
    if(p) p.cap=num;
  } else if(section==='customers'){
    const c=(DB.customers||[]).find(c=>c.name===key);
    if(c) c.bal=num;
  }
  _scheduleAutoSave();
}

// ═══════════════════════════════════════════════════════════
// PARBOILED COSTING & DORB
// Ported from the "Advanced Suite" build. That version kept costs in bare
// DOM inputs with no persistence — a refresh silently wiped everything
// entered. Here all of it lives in DB (DB.costSettings, DB.pbBatchRows,
// DB.dorbRows, DB.locationRates) and saves via the normal saveDB() path,
// same as every other module. Deliberately NOT wired into DB.inventory —
// this is production costing/DORB tracking only, not stock.
// ═══════════════════════════════════════════════════════════
const COST_ITEMS_DEF = [
  {label:'Labour', key:'labour'},
  {label:'Reaches Rent', key:'reachesRent'},
  {label:'Inter Rent', key:'interRent'},
  {label:'A Profit', key:'aProfit'},
  {label:'B Profit', key:'bProfit'},
  {label:'Bag Loss', key:'bagLoss'},
  {label:'Unload Cost', key:'unloadCost'},
  {label:'If Unseating Bran', key:'unseatingBran'},
  {label:'New Bag', key:'newBag'}
];
const PROD_ITEMS_DEF = [
  {label:'A', key:'a'},
  {label:'B', key:'b'},
  {label:'Unload', key:'unload'},
  {label:'Commission', key:'commission'},
  {label:'Loading', key:'loading'},
  {label:'Shrinkage', key:'shrinkage'},
  {label:'Other', key:'other'},
  {label:'My Profit', key:'myProfit'}
];
const DORB_LOCATION_NAMES = ['Chuadanga FM','Jessore FM','Bogura FM','Valuka FM','Narsingdi FM','Dhaka FM','Chittagong FM','Birganj FM'];

function ensureProdCostingDefaults(){
  if(!DB.costSettings) DB.costSettings = {cost:{}, prod:{}};
  if(!DB.costSettings.cost) DB.costSettings.cost = {};
  if(!DB.costSettings.prod) DB.costSettings.prod = {};
  if(!DB.pbBatchRows) DB.pbBatchRows = [];
  if(!DB.dorbRows) DB.dorbRows = [];
  if(!DB.locationRates || !DB.locationRates.length){
    const rentMap = {'Valuka FM':1.5,'Narsingdi FM':1.0,'Dhaka FM':1.0,'Chittagong FM':2.0,'Birganj FM':1.0};
    DB.locationRates = DORB_LOCATION_NAMES.map(name=>({name, rent: rentMap[name]!==undefined?rentMap[name]:0.7}));
  }
}
function pcNum(v){ return parseFloat(v)||0; }

function renderProdCosting(){
  ensureProdCostingDefaults();
  const el = document.getElementById('pg-prodcosting');
  if(!el) return;
  el.innerHTML = `
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;flex-wrap:wrap;gap:8px;">
      <div style="font-size:15px;font-weight:800;color:#0f3d26;">🧮 Parboiled Cost Sheet &amp; DORB Locations</div>
      <button class="btn btn-xs" data-x-click="nav('dashboard')">← Dashboard</button>
    </div>

    <div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:14px;">
      <div class="chart-card">
        <div class="chart-title">Cost Items (per KG)</div>
        <table class="table" style="width:100%;font-size:12px;">
          <thead><tr><th>Item</th><th style="width:100px;">Value</th></tr></thead>
          <tbody id="pc-cost-body"></tbody>
        </table>
      </div>
      <div class="chart-card">
        <div class="chart-title">Production Items (per KG)</div>
        <table class="table" style="width:100%;font-size:12px;">
          <thead><tr><th>Item</th><th style="width:100px;">Value</th></tr></thead>
          <tbody id="pc-prod-body"></tbody>
        </table>
      </div>
    </div>

    <div class="chart-card" style="margin-bottom:14px;">
      <div class="chart-title" style="display:flex;justify-content:space-between;align-items:center;">
        <span>Parboiled Batches</span>
        <button class="btn btn-xs" data-x-click="addPbBatchRow()">+ Add Batch</button>
      </div>
      <table class="table" style="width:100%;font-size:12px;">
        <thead><tr><th>Bags</th><th>Rate/KG</th><th>Oil %</th><th>Weight (KG)</th><th>Cost</th><th>Oil (KG)</th><th></th></tr></thead>
        <tbody id="pc-batch-body"></tbody>
      </table>
      <div style="display:flex;gap:18px;font-size:12px;font-weight:700;margin-top:10px;flex-wrap:wrap;">
        <div>Total Weight: <span id="pc-sum-weight">0</span> KG</div>
        <div>Avg Rate: <span id="pc-sum-rate">0</span></div>
        <div>Total Cost: <span id="pc-sum-cost">0</span></div>
        <div>Avg Oil%: <span id="pc-sum-oilpct">0%</span></div>
        <div>Base Rate (all-in): <span id="pc-base-rate" style="color:#16a34a;">0</span></div>
      </div>
    </div>

    <div class="chart-card" style="margin-bottom:14px;">
      <div class="chart-title" style="display:flex;justify-content:space-between;align-items:center;">
        <span>DORB (De-Oiled Rice Bran) Entries</span>
        <button class="btn btn-xs" data-x-click="addDorbRow()">+ Add Entry</button>
      </div>
      <table class="table" style="width:100%;font-size:12px;">
        <thead><tr><th>Date</th><th>Location</th><th>Spot</th><th>Rent</th><th>A</th><th>B</th><th>Unload</th><th>Other</th><th></th></tr></thead>
        <tbody id="pc-dorb-body"></tbody>
      </table>
    </div>

    <div class="chart-card">
      <div class="chart-title">Delivered Rate by Location</div>
      <table class="table" style="width:100%;font-size:12px;">
        <thead><tr><th>Location</th><th>Rent</th><th>QC Rate (৳/KG)</th><th>Base Rate</th><th>Delivered Rate</th></tr></thead>
        <tbody id="pc-location-body"></tbody>
      </table>
      <div style="font-size:11px;color:#6b7280;margin-top:6px;">QC Rate sets the per-KG quality-control cost used on Sale transactions from that location (leave blank to use the company default, ৳<span id="pc-default-qc">0.10</span>/KG — set on the Cost Rates panel).</div>
    </div>
  `;
  renderCostPanels();
  renderPbBatchRows();
  renderDorbRows();
  recalcProdCosting();
}

function renderCostPanels(){
  const costBody = document.getElementById('pc-cost-body');
  const prodBody = document.getElementById('pc-prod-body');
  if(costBody) costBody.innerHTML = COST_ITEMS_DEF.map(ci=>`
    <tr><td>${escHTML(ci.label)}</td><td><input type="number" step="0.01" value="${DB.costSettings.cost[ci.key]||0}"
      data-x-input="updateCostItem('${ci.key}', this.value)" style="width:90px;"></td></tr>
  `).join('');
  if(prodBody) prodBody.innerHTML = PROD_ITEMS_DEF.map(pi=>`
    <tr><td>${escHTML(pi.label)}</td><td><input type="number" step="0.01" value="${DB.costSettings.prod[pi.key]||0}"
      data-x-input="updateProdItem('${pi.key}', this.value)" style="width:90px;"></td></tr>
  `).join('');
}
function updateCostItem(key,val){
  ensureProdCostingDefaults();
  DB.costSettings.cost[key] = pcNum(val);
  saveDB(); recalcProdCosting();
}
function updateProdItem(key,val){
  ensureProdCostingDefaults();
  DB.costSettings.prod[key] = pcNum(val);
  saveDB(); recalcProdCosting();
}

function addPbBatchRow(){
  ensureProdCostingDefaults();
  DB.pbBatchRows.push({bags:0, rate:0, oilPct:0});
  saveDB(); renderPbBatchRows(); recalcProdCosting();
}
function removePbBatchRow(i){
  DB.pbBatchRows.splice(i,1);
  saveDB(); renderPbBatchRows(); recalcProdCosting();
}
function updatePbBatchRow(i,field,val){
  if(!DB.pbBatchRows[i]) return;
  DB.pbBatchRows[i][field] = pcNum(val);
  saveDB(); recalcProdCosting();
}
function renderPbBatchRows(){
  const body = document.getElementById('pc-batch-body');
  if(!body) return;
  if(!DB.pbBatchRows.length){
    body.innerHTML = '<tr><td colspan="7" style="text-align:center;color:#9ca3af;padding:14px;">No batches yet — click "Add Batch"</td></tr>';
    return;
  }
  body.innerHTML = DB.pbBatchRows.map((r,i)=>{
    const w=(r.bags||0)*50, c=w*(r.rate||0), ok=(r.oilPct||0)/100*w;
    return `<tr>
      <td><input type="number" value="${r.bags||0}" style="width:60px;" data-x-input="updatePbBatchRow(${i},'bags',this.value)"></td>
      <td><input type="number" step="0.01" value="${r.rate||0}" style="width:70px;" data-x-input="updatePbBatchRow(${i},'rate',this.value)"></td>
      <td><input type="number" step="0.01" value="${r.oilPct||0}" style="width:60px;" data-x-input="updatePbBatchRow(${i},'oilPct',this.value)"></td>
      <td>${w.toFixed(2)}</td><td>${c.toFixed(2)}</td><td>${ok.toFixed(2)}</td>
      <td><button class="btn-del" data-x-click="removePbBatchRow(${i})">✕</button></td>
    </tr>`;
  }).join('');
}

function addDorbRow(){
  ensureProdCostingDefaults();
  DB.dorbRows.push({date:new Date().toISOString().slice(0,10), loc:DORB_LOCATION_NAMES[0], spot:0, rent:0, a:0, b:0, unload:0, other:0});
  saveDB(); renderDorbRows();
}
function removeDorbRow(i){
  DB.dorbRows.splice(i,1);
  saveDB(); renderDorbRows();
}
function updateDorbRow(i,field,val){
  if(!DB.dorbRows[i]) return;
  DB.dorbRows[i][field] = (field==='date'||field==='loc') ? val : pcNum(val);
  saveDB();
}
function renderDorbRows(){
  const body = document.getElementById('pc-dorb-body');
  if(!body) return;
  if(!DB.dorbRows.length){
    body.innerHTML = '<tr><td colspan="9" style="text-align:center;color:#9ca3af;padding:14px;">No DORB entries yet</td></tr>';
    return;
  }
  body.innerHTML = DB.dorbRows.map((r,i)=>{
    const locOpts = DORB_LOCATION_NAMES.map(n=>`<option value="${n}"${n===r.loc?' selected':''}>${n}</option>`).join('');
    return `<tr>
      <td><input type="date" value="${r.date}" style="width:120px;" data-x-input="updateDorbRow(${i},'date',this.value)"></td>
      <td><select data-x-change="updateDorbRow(${i},'loc',this.value)">${locOpts}</select></td>
      <td><input type="number" step="0.01" value="${r.spot||0}" style="width:60px;" data-x-input="updateDorbRow(${i},'spot',this.value)"></td>
      <td><input type="number" step="0.01" value="${r.rent||0}" style="width:60px;" data-x-input="updateDorbRow(${i},'rent',this.value)"></td>
      <td><input type="number" step="0.01" value="${r.a||0}" style="width:50px;" data-x-input="updateDorbRow(${i},'a',this.value)"></td>
      <td><input type="number" step="0.01" value="${r.b||0}" style="width:50px;" data-x-input="updateDorbRow(${i},'b',this.value)"></td>
      <td><input type="number" step="0.01" value="${r.unload||0}" style="width:50px;" data-x-input="updateDorbRow(${i},'unload',this.value)"></td>
      <td><input type="number" step="0.01" value="${r.other||0}" style="width:50px;" data-x-input="updateDorbRow(${i},'other',this.value)"></td>
      <td><button class="btn-del" data-x-click="removeDorbRow(${i})">✕</button></td>
    </tr>`;
  }).join('');
}

function recalcProdCosting(){
  ensureProdCostingDefaults();
  let sumW=0,sumC=0,sumOK=0;
  DB.pbBatchRows.forEach(r=>{
    const w=(r.bags||0)*50, c=w*(r.rate||0), ok=(r.oilPct||0)/100*w;
    sumW+=w; sumC+=c; sumOK+=ok;
  });
  const avgR = sumW>0 ? sumC/sumW : 0;
  const avgOP = sumW>0 ? (sumOK/sumW)*100 : 0;
  set('pc-sum-weight', sumW.toFixed(2));
  set('pc-sum-rate', avgR.toFixed(2));
  set('pc-sum-cost', sumC.toFixed(2));
  set('pc-sum-oilpct', avgOP.toFixed(2)+'%');

  const costTotal = COST_ITEMS_DEF.reduce((s,ci)=>s+(DB.costSettings.cost[ci.key]||0),0);
  const prodTotal = PROD_ITEMS_DEF.reduce((s,pi)=>s+(DB.costSettings.prod[pi.key]||0),0);
  const baseRate = avgR + costTotal + prodTotal;
  set('pc-base-rate', baseRate.toFixed(8));

  const locBody = document.getElementById('pc-location-body');
  if(locBody){
    locBody.innerHTML = (DB.locationRates||[]).map((loc,i)=>{
      const delivered = baseRate + (loc.rent||0);
      return `<tr>
        <td>${escHTML(loc.name)}</td>
        <td><input type="number" step="0.01" value="${loc.rent||0}" style="width:70px;" data-x-input="updateLocationRent(${i},this.value)"></td>
        <td><input type="number" step="0.01" value="${loc.qcRate!=null?loc.qcRate:''}" placeholder="${(parseFloat(DB.costRates?.qc)||0.10).toFixed(2)}" style="width:70px;" data-x-input="updateLocationQcRate(${i},this.value)"></td>
        <td>${baseRate.toFixed(8)}</td>
        <td style="font-weight:700;color:#16a34a;">${delivered.toFixed(8)}</td>
      </tr>`;
    }).join('');
  }
  const defQcEl=document.getElementById('pc-default-qc');
  if(defQcEl) defQcEl.textContent=(parseFloat(DB.costRates?.qc)||0.10).toFixed(2);
}
function updateLocationRent(i,val){
  if(!DB.locationRates[i]) return;
  DB.locationRates[i].rent = pcNum(val);
  saveDB(); recalcProdCosting();
}
/* Per-location QC rate — used by autoFillSaleCosts()/qcRateForLocation() on
   Sale transactions so QC cost can differ by location, instead of one flat
   company-wide rate. Blank = fall back to DB.costRates.qc. */
function updateLocationQcRate(i,val){
  if(!DB.locationRates[i]) return;
  DB.locationRates[i].qcRate = (val===''||val==null) ? null : pcNum(val);
  saveDB(); recalcProdCosting();
}


// ═══════════════════════════════════════════════════════════
// COST CALCULATION PAGE  (Parboiled Cost Sheet — from erp_fixed_4)
// ═══════════════════════════════════════════════════════════

/* ── CSS injected once for cost-calc page ── */
(function(){
  if(document.getElementById('_costcalc-style')) return;
  const s = document.createElement('style');
  s.id = '_costcalc-style';
  s.textContent = `
    :root {
      --cc-g1:#064e20; --cc-g2:#0a6b2c; --cc-brand:#00c853;
      --cc-brand-d:#00a846; --cc-brand-l:#b9f6ca; --cc-brand-xl:#e8fff0;
      --cc-border:#b2dfdb; --cc-txt3:#52af72; --cc-surface:#edfff4;
      --cc-radius:10px;
    }
    .cc-erp-table { border-collapse:collapse; width:100%; font-size:12px; }
    .cc-erp-table th { background:var(--cc-brand-xl); color:var(--cc-g1); font-weight:700; font-size:10.5px; text-transform:uppercase; letter-spacing:.3px; border-bottom:2px solid var(--cc-brand-l); padding:7px 8px; white-space:nowrap; text-align:right; }
    .cc-erp-table th:first-child, .cc-erp-table th.cc-left { text-align:left; }
    .cc-erp-table td { border-bottom:1px solid #f1f5f9; padding:6px 8px; text-align:right; background:white; vertical-align:middle; }
    .cc-erp-table td:first-child { text-align:center; }
    .cc-erp-table td.cc-left-td { text-align:left; }
    .cc-erp-table tbody tr:hover td { background:#fafbfc; }
    .cc-erp-table .cc-subtotal-row td { background:#ecfdf5; font-weight:700; color:var(--cc-g2); border-bottom:1px solid var(--cc-brand-l); }
    .cc-erp-table .cc-grand-row td { background:var(--cc-brand-l); font-weight:800; color:var(--cc-g1); border-bottom:2px solid var(--cc-brand); }
    .cc-readonly-cell { background:#f0fdf4 !important; color:#166534; font-weight:600; }
    .cc-erp-table input[type="number"], .cc-erp-table input[type="text"],
    .cc-cost-table input[type="number"] {
      width:100%; background:transparent; border:none; border-bottom:1px solid transparent;
      border-radius:0; padding:2px 4px; font-size:12px; font-family:inherit;
      color:inherit; outline:none; text-align:right;
    }
    .cc-erp-table input[type="text"] { text-align:left; }
    .cc-erp-table input:focus, .cc-cost-table input:focus { background:#fffde7; border-bottom:2px solid var(--cc-brand); }
    .cc-cost-table { border-collapse:collapse; font-size:12px; width:100%; }
    .cc-cost-table td { border:1px solid var(--cc-border); padding:5px 10px; background:white; vertical-align:middle; }
    .cc-cost-table td:last-child { text-align:right; min-width:100px; }
    .cc-cost-table th { background:var(--cc-g2); color:white; font-weight:700; font-size:11px; padding:7px 10px; border:1px solid var(--cc-g1); text-align:left; }
    .cc-cost-table th:last-child { text-align:right; }
    .cc-cost-table .cc-total-row td { background:var(--cc-brand-xl); font-weight:700; color:var(--cc-g1); border-color:var(--cc-brand-l); }
    .cc-cost-spacer { width:24px; border:none !important; background:var(--cc-surface) !important; }
    .cc-e11-live { background:var(--cc-g2) !important; color:white !important; font-size:11px; font-weight:700; }
    .cc-loc-hdr { background:var(--cc-g2); color:white; font-weight:700; padding:8px 14px; font-size:12px; display:flex; align-items:center; gap:8px; border-radius:var(--cc-radius) var(--cc-radius) 0 0; justify-content:space-between; }
    .cc-bulk-bar { display:flex; align-items:center; gap:8px; background:#f0fdf4; border:1px solid var(--cc-brand-l); border-radius:8px; padding:6px 12px; margin-bottom:10px; flex-wrap:wrap; }
    .cc-bulk-info { font-size:11px; color:var(--cc-g2); font-weight:600; flex:1; }
    .cc-bulk-btn { border:none; border-radius:6px; padding:4px 12px; font-size:11px; font-weight:600; cursor:pointer; font-family:inherit; }
    .cc-bulk-btn.cc-bulk-select-all { background:#e0f2fe; color:#0369a1; }
    .cc-bulk-btn.cc-bulk-delete { background:#fee2e2; color:#dc2626; }
    .cc-btn-add { background:linear-gradient(135deg,var(--cc-g2),var(--cc-brand-d)); color:#fff; border:none; border-radius:8px; padding:7px 16px; font-size:12px; font-weight:600; cursor:pointer; display:inline-flex; align-items:center; gap:5px; font-family:inherit; transition:all .2s; }
    .cc-btn-add:hover { background:linear-gradient(135deg,var(--cc-g1),var(--cc-g2)); transform:translateY(-1px); }
    .cc-btn-sm { padding:4px 12px; font-size:11px; }
    .cc-btn-del { background:none; border:none; color:#ef4444; cursor:pointer; padding:3px 7px; border-radius:6px; font-size:13px; }
    .cc-btn-del:hover { background:#fef2f2; }
    .cc-btn-edit { background:none; border:none; color:#2563eb; cursor:pointer; padding:3px 7px; border-radius:6px; font-size:13px; }
    .cc-btn-edit:hover { background:#dbeafe; }
    .cc-btn-view { background:none; border:none; color:#7c3aed; cursor:pointer; padding:3px 7px; border-radius:6px; font-size:13px; }
    .cc-btn-view:hover { background:#ede9fe; }
    .cc-loc-select { width:100%; padding:2px 6px; font-size:11px; border:1px solid var(--cc-border); border-radius:6px; background:#fafafa; cursor:pointer; }
    input[type="number"]::-webkit-inner-spin-button, input[type="number"]::-webkit-outer-spin-button { -webkit-appearance:none; margin:0; }
  `;
  document.head.appendChild(s);
})();

/* FIX (UI/UX redesign blueprint item #2 — Form Input Density Defect):
   number-spinner removal was only ever wired for Chrome/Safari/Edge
   (-webkit-appearance:none above); Firefox users (confirmed live via a
   screenshot — Firefox's own "Profiles" menu is visible in the browser
   chrome) still saw the native up/down stepper arrows cluttering every
   qty/rate/amount cell across the whole app, including the Multiple
   Products grid. Added the missing Firefox rule, app-wide, plus a shared
   .erp-grid-input class that gives dense table cells (like the Multiple
   Products rows) the same clear padding/border/focus-glow treatment the
   blueprint calls for, instead of the cramped 4px-padding inline style
   they had before. */
(function(){
  var s=document.createElement('style');
  s.textContent=`
    input[type="number"] { -moz-appearance: textfield; }
    input[type="number"]::-webkit-inner-spin-button,
    input[type="number"]::-webkit-outer-spin-button { -webkit-appearance:none; margin:0; }
    .erp-grid-input{
      width:100%; padding:6px 8px; border:1px solid #cbd5e1; border-radius:5px;
      font-size:12px; background:#fff; transition:border-color .15s ease,box-shadow .15s ease;
      font-family:inherit;
    }
    .erp-grid-input:focus{
      outline:none; border-color:#16a34a; box-shadow:0 0 0 2px rgba(22,163,74,.18);
    }
  `;
  document.head.appendChild(s);
})();

/* ── Data definitions ── */
const CC_COST_ITEMS = [
  { label:'Labour',            cbId:'cc_cb_Labour',          val:0 },
  { label:'Reaches Rent',      cbId:'cc_cb_ReachesRent',     val:0 },
  { label:'Inter Rent',        cbId:'cc_cb_InterRent',       val:0 },
  { label:'A Profit',          cbId:'cc_cb_Aprofit',         val:0 },
  { label:'B Profit',          cbId:'cc_cb_BProfit',         val:0 },
  { label:'Bag Loss',          cbId:'cc_cb_BagLoss',         val:0 },
  { label:'Unload Cost',       cbId:'cc_cb_UnloadCost',      val:0 },
  { label:'If Unseating Bran', cbId:'cc_cb_IfUnseatingBran', val:0 },
  { label:'New Bag',           cbId:'cc_cb_NewBag',          val:0 },
];
const CC_PROD_ITEMS = [
  { label:'A',          pcId:'cc_pc_A',        val:0 },
  { label:'B',          pcId:'cc_pc_B',        val:0 },
  { label:'Unload',     pcId:'cc_pc_Unload',   val:0 },
  { label:'Commission', pcId:'cc_pc_A2',       val:0 },
  { label:'Loading',    pcId:'cc_pc_A3',       val:0 },
  { label:'Shrinkage',  pcId:'cc_pc_A4',       val:0 },
  { label:'Other',      pcId:'cc_pc_A5',       val:0 },
  { label:'My Profit',  pcId:'cc_pc_MyProfit', val:0 },
];
const CC_LOCATION_NAMES = ['Chuadanga FM','Jessore FM','Bogura FM','Valuka FM','Narsingdi FM','Dhaka FM','Chittagong FM','Birganj FM'];
let _ccLocationRows = [];
let _ccPbRowCount = 0;

function _ccToNum(v){ return parseFloat(String(v).replace(/,/g,''))||0; }
function _ccSet(id,v){ const e=document.getElementById(id); if(e) e.textContent=v; }

function _ccRenderLocationTable(){
  const tbody = document.getElementById('cc-locationBody');
  if(!tbody) return;
  tbody.innerHTML = '';
  if(!_ccLocationRows.length){
    _ccLocationRows = CC_LOCATION_NAMES.map(name=>({name, rent:0.7}));
    const rentMap={'Valuka FM':1.5,'Narsingdi FM':1.0,'Dhaka FM':1.0,'Chittagong FM':2.0,'Birganj FM':1.0};
    _ccLocationRows.forEach(loc=>{ if(rentMap[loc.name]!==undefined) loc.rent=rentMap[loc.name]; });
  }
  const baseRate = _ccToNum(document.getElementById('cc-g24cell')?.textContent) || 0;
  const avgOil   = parseFloat((document.getElementById('cc-gt_oilpct')?.textContent||'0%').replace('%',''))||0;
  const opts = CC_LOCATION_NAMES.map(n=>`<option value="${n}">${n}</option>`).join('');
  _ccLocationRows.forEach((loc,idx)=>{
    const tr = document.createElement('tr');
    const finalRate = baseRate + _ccToNum(loc.rent);
    tr.innerHTML = `
      <td class="cc-left-td"><select class="cc-loc-select" data-x-change="window._ccLocUpdateName(${idx},this.value)">${opts}</select></td>
      <td><input type="number" value="${loc.rent}" step="0.01" data-x-input="window._ccLocUpdateRent(${idx},this.value)" style="width:60px;text-align:right;border:1px solid #b2dfdb;border-radius:4px;padding:2px 4px;font-size:11px;"></td>
      <td style="font-weight:600;color:#0a6b2c;font-size:12px;">${baseRate.toFixed(8)}</td>
      <td>${avgOil.toFixed(2)}%</td>
      <td style="font-weight:700;color:#00a846;font-size:13px;">${finalRate.toFixed(8)}</td>
      <td><button class="cc-btn-del" data-x-click="window._ccLocDelete(${idx})">🗑</button></td>`;
    // set selected option
    tr.querySelector('select').value = loc.name;
    tbody.appendChild(tr);
  });
}

window._ccLocUpdateName = function(i,v){ _ccLocationRows[i].name=v; };
window._ccLocUpdateRent = function(i,v){ _ccLocationRows[i].rent=_ccToNum(v); _ccRenderLocationTable(); };
window._ccLocDelete      = function(i){ _ccLocationRows.splice(i,1); _ccRenderLocationTable(); };
window.ccAddLocationRow  = function(){ _ccLocationRows.push({name:CC_LOCATION_NAMES[0],rent:0}); _ccRenderLocationTable(); toast('Location added','s'); };
window.ccExportPbCSV     = function(){
  const rows = document.querySelectorAll('#cc-parboiledBody tr:not(#cc-pbEmptyState)');
  if(!rows.length){ toast('No rows to export','w'); return; }
  const headers = ['SL','Product','Bags','Weight KG','Rate','Total Cost','Oil %','Oil KG'];
  const lines = [headers.join(',')];
  rows.forEach((row,i)=>{
    lines.push([i+1,
      row.querySelector('.cc-name-input')?.value||'',
      row.querySelector('.cc-bag-input')?.value||0,
      row.querySelector('.cc-weight-col')?.textContent.trim()||0,
      row.querySelector('.cc-rate-input')?.value||0,
      row.querySelector('.cc-cost-col')?.textContent.trim()||0,
      row.querySelector('.cc-oil-input')?.value||0,
      row.querySelector('.cc-oilkg-col')?.textContent.trim()||0
    ].map(v=>__csvCell(v)).join(','));
  });
  const a=document.createElement('a');
  a.href='data:text/csv;charset=utf-8,'+encodeURIComponent(lines.join('\n'));
  a.download='parboiled_'+new Date().toISOString().slice(0,10)+'.csv';
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  toast('CSV exported','s');
};

function _ccRecalcParboiled(){
  let sumW=0, sumC=0, sumOK=0;
  document.querySelectorAll('#cc-parboiledBody tr').forEach(row=>{
    const bags=_ccToNum(row.querySelector('.cc-bag-input')?.value);
    const rate=_ccToNum(row.querySelector('.cc-rate-input')?.value);
    const oilP=_ccToNum(row.querySelector('.cc-oil-input')?.value);
    const w=bags*50, c=w*rate, ok=(oilP/100)*w;
    const wc=row.querySelector('.cc-weight-col'), cc=row.querySelector('.cc-cost-col'), okc=row.querySelector('.cc-oilkg-col');
    if(wc) wc.textContent=w.toFixed(2);
    if(cc) cc.textContent=c.toFixed(2);
    if(okc) okc.textContent=ok.toFixed(2);
    sumW+=w; sumC+=c; sumOK+=ok;
  });
  const avgR=sumW>0?sumC/sumW:0, avgOP=sumW>0?(sumOK/sumW)*100:0;
  _ccSet('cc-st_weight', sumW.toFixed(2));
  _ccSet('cc-st_rate',   avgR.toFixed(2));
  _ccSet('cc-st_cost',   sumC.toFixed(2));
  _ccSet('cc-st_oilpct', avgOP.toFixed(2)+'%');
  _ccSet('cc-st_oilkg',  sumOK.toFixed(2));

  const r12Bags  = _ccToNum(document.getElementById('cc-r12_bags')?.value)||0;
  const r12KG    = _ccToNum(document.getElementById('cc-r12_kgperbag')?.value)||0;
  const r12Rate  = _ccToNum(document.getElementById('cc-r12_rate')?.value)||0;
  const r12OilP  = _ccToNum(document.getElementById('cc-r12_oilpct')?.value)||0;
  const r12W=r12Bags*r12KG, r12C=r12W*r12Rate, r12OK=(r12OilP/100)*r12W;
  _ccSet('cc-r12_weight', r12W.toFixed(2));
  _ccSet('cc-r12_cost',   r12C.toFixed(2));
  _ccSet('cc-r12_oilkg',  r12OK.toFixed(2));

  const gtW=sumW+r12W, gtC=sumC+r12C, gtOK=sumOK+r12OK;
  const gtR=gtW>0?gtC/gtW:0, gtOP=gtW>0?(gtOK/gtW)*100:0;
  _ccSet('cc-gt_weight', gtW.toFixed(2));
  _ccSet('cc-gt_rate',   gtR.toFixed(8));
  _ccSet('cc-gt_cost',   gtC.toFixed(2));
  _ccSet('cc-gt_oilpct', gtOP.toFixed(2)+'%');
  _ccSet('cc-gt_oilkg',  gtOK.toFixed(2));

  let B24=0;
  CC_COST_ITEMS.forEach(ci=>{ B24+=_ccToNum(document.getElementById(ci.cbId)?.value); });
  _ccSet('cc-b24cell', B24.toFixed(2));
  let pcSum=0;
  CC_PROD_ITEMS.forEach(pi=>{ pcSum+=_ccToNum(document.getElementById(pi.pcId)?.value); });
  _ccSet('cc-pcTotalCell', pcSum.toFixed(2));

  const baseRate=gtR+B24+pcSum;
  _ccSet('cc-e11cell', gtR.toFixed(8));
  _ccSet('cc-g24cell', baseRate.toFixed(8));

  _ccSet('cc-pbsc_weight', Math.round(sumW)+' KG');
  _ccSet('cc-pbsc_cost',   '৳'+Math.round(sumC).toLocaleString('en-IN'));
  _ccSet('cc-pbsc_oil',    avgOP.toFixed(2)+'%');
  _ccSet('cc-pbsc_gt',     Math.round(gtW)+' KG');
  _ccSet('cc-pbsc_rate',   gtR.toFixed(2));

  _ccRenderLocationTable();
}

function _ccMakePbRow(rowNum, p={}){
  const w=_ccToNum(p.bags)*50, c=w*_ccToNum(p.rate), ok=(_ccToNum(p.oilPct)/100)*w;
  const tr=document.createElement('tr');
  tr.id=`cc-prow_${rowNum}`;
  tr.innerHTML=`
    <td><input type="checkbox" class="cc-pb-check" data-id="${rowNum}" data-x-change="_ccUpdateBulkInfo()"></td>
    <td style="color:#52af72;font-size:11px;">${rowNum}</td>
    <td class="cc-left-td"><input type="text" class="cc-name-input" value="${escHTML(p.name||'New Product')}" style="width:100%;text-align:left;border:none;border-bottom:1px solid #b2dfdb;background:transparent;font-size:12px;outline:none;"></td>
    <td><input type="number" class="cc-bag-input" value="${p.bags||0}" min="0" step="1" style="width:50px;"></td>
    <td class="cc-readonly-cell cc-weight-col">${w.toFixed(2)}</td>
    <td><input type="number" class="cc-rate-input" value="${p.rate||0}" step="0.1" style="width:55px;"></td>
    <td class="cc-readonly-cell cc-cost-col">${c.toFixed(2)}</td>
    <td><input type="number" class="cc-oil-input" value="${p.oilPct||0}" step="0.1" min="0" max="100" style="width:50px;"></td>
    <td class="cc-readonly-cell cc-oilkg-col">${ok.toFixed(2)}</td>
    <td>
      <button class="cc-btn-del" data-x-click="_ccRemovePbRow(this)" title="Delete">🗑</button>
    </td>`;
  tr.querySelectorAll('input').forEach(i=>i.addEventListener('input',_ccRecalcParboiled));
  return tr;
}

function _ccUpdateBulkInfo(){
  const checks=document.querySelectorAll('.cc-pb-check:checked');
  const infoEl=document.getElementById('cc-pbBulkInfo');
  if(infoEl) infoEl.textContent=checks.length+' selected';
  const all=document.getElementById('cc-pbSelectAll');
  const total=document.querySelectorAll('.cc-pb-check').length;
  if(all) all.checked=total>0&&checks.length===total;
}

window.ccToggleAllPbChecks = function(){
  const all=document.getElementById('cc-pbSelectAll');
  document.querySelectorAll('.cc-pb-check').forEach(c=>c.checked=all.checked);
  _ccUpdateBulkInfo();
};
window.ccBulkDeletePb = async function(){
  const checks=document.querySelectorAll('.cc-pb-check:checked');
  if(!checks.length){ toast('No rows selected','w'); return; }
  if(!await __confirm(`Delete ${checks.length} product(s)?`)) return;
  checks.forEach(c=>{ const row=c.closest('tr'); if(row) row.remove(); });
  _ccUpdateBulkSlNumbers(); _ccUpdateBulkInfo(); _ccRecalcParboiled();
  _ccShowEmptyIfNeeded();
  toast(`${checks.length} product(s) deleted`,'s');
};
window.ccAddPbRow = function(){
  const emptyState=document.getElementById('cc-pbEmptyState');
  if(emptyState) emptyState.remove();
  const tb=document.getElementById('cc-parboiledBody');
  if(!tb) return;
  _ccPbRowCount++;
  tb.appendChild(_ccMakePbRow(_ccPbRowCount));
  _ccUpdateBulkInfo(); _ccRecalcParboiled();
  toast('Product added','s');
};
async function _ccRemovePbRow(btn){
  if(!await __confirm('Delete this product row?')) return;
  const row=btn.closest('tr');
  if(row) row.remove();
  _ccUpdateBulkSlNumbers(); _ccUpdateBulkInfo(); _ccRecalcParboiled();
  _ccShowEmptyIfNeeded();
  toast('Product deleted','s');
}
function _ccUpdateBulkSlNumbers(){
  const rows=document.querySelectorAll('#cc-parboiledBody tr');
  rows.forEach((row,i)=>{
    const slCell=row.querySelector('td:nth-child(2)');
    if(slCell) slCell.textContent=i+1;
    const check=row.querySelector('.cc-pb-check');
    if(check) check.dataset.id=i+1;
  });
}
function _ccShowEmptyIfNeeded(){
  const tb=document.getElementById('cc-parboiledBody');
  if(tb&&!tb.children.length){
    const tr=document.createElement('tr');
    tr.id='cc-pbEmptyState';
    tr.innerHTML='<td colspan="10" style="text-align:center;color:#9ca3af;padding:16px;">No products yet — click <strong>Add</strong>.</td>';
    tb.appendChild(tr);
  }
}

function renderCostCalc(){
  const el = document.getElementById('pg-costcalc');
  if(!el) return;
  _ccPbRowCount = 0;

  el.innerHTML = `
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;flex-wrap:wrap;gap:8px;">
      <div style="font-size:15px;font-weight:800;color:#0f3d26;">💼 Cost Calculation — Parboiled Rice Bran</div>
      <button class="btn btn-xs" data-x-click="nav('dashboard')">← Dashboard</button>
    </div>

    <!-- KPI row -->
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:8px;margin-bottom:12px;">
      <div style="background:#f0fdf4;border:1px solid #86efac;border-radius:10px;padding:10px 12px;">
        <div style="font-size:9px;color:#0a6b2c;font-weight:700;text-transform:uppercase;">Total Weight</div>
        <div id="cc-pbsc_weight" style="font-size:18px;font-weight:800;color:#064e20;">0 KG</div>
      </div>
      <div style="background:#eff6ff;border:1px solid #93c5fd;border-radius:10px;padding:10px 12px;">
