}

// ═══════════════════════════════════════════════════════════
// v19 AUTO-SAVE & CROSS-TAB SYNC SYSTEM
// ═══════════════════════════════════════════════════════════
window._tabId='tab_'+Date.now()+'_'+Math.random().toString(36).slice(2,6);
window._isDirty=false;
window._lastSavedTs=null;
window._autoSaveTimer=null;
window._syncChannel=null;

function _markSaved(){
  window._isDirty=false;
  window._lastSavedTs=new Date();
  const el=document.getElementById('save-indicator');
  const icon=document.getElementById('save-icon');
  const text=document.getElementById('save-text');
  const time=document.getElementById('last-saved-time');
  if(el) el.className='saved';
  if(icon) icon.textContent='✅';
  if(text) text.textContent='Saved';
  if(time) time.textContent='· '+window._lastSavedTs.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',second:'2-digit'});
  const bar=document.getElementById('autosave-progress');
  if(bar){bar.style.width='100%';bar.style.background='linear-gradient(90deg,#16a34a,#4ade80)';setTimeout(()=>{bar.style.width='0%';},700);}
}

function _markSaving(){
  const el=document.getElementById('save-indicator');
  const icon=document.getElementById('save-icon');
  const text=document.getElementById('save-text');
  if(el) el.className='saving';
  if(icon) icon.textContent='💾';
  if(text) text.textContent='Saving...';
  const bar=document.getElementById('autosave-progress');
  if(bar){bar.style.width='60%';bar.style.background='linear-gradient(90deg,#d97706,#fbbf24)';}
}

function _markUnsaved(){
  window._isDirty=true;
  const el=document.getElementById('save-indicator');
  const icon=document.getElementById('save-icon');
  const text=document.getElementById('save-text');
  if(el) el.className='unsaved';
  if(icon) icon.textContent='⚠️';
  if(text) text.textContent='Unsaved';
}

function _markSynced(){
  const el=document.getElementById('save-indicator');
  const icon=document.getElementById('save-icon');
  const text=document.getElementById('save-text');
  if(el) el.className='synced';
  if(icon) icon.textContent='🔄';
  if(text) text.textContent='Synced';
  setTimeout(()=>_markSaved(),2500);
}

/* SERVER-ONLY AUTOSAVE: pushes straight to MySQL through api.php
   (window.saveDBNow, owned by ayan-final-save-authority near </body>).
   Nothing is written to localStorage / IndexedDB. */
function _serverSaveNow(){
  try{
    var p = (typeof window.saveDBNow==='function') ? window.saveDBNow() : window.saveDB();
    return Promise.resolve(p).then(function(ok){
      if(ok!==false){ window._isDirty=false; window._lastSavedTs=new Date(); }
      return ok;
    }).catch(function(){ try{ _markUnsaved(); }catch(e){} return false; });
  }catch(e){ try{ _markUnsaved(); }catch(_){} return Promise.resolve(false); }
}
window._serverSaveNow=_serverSaveNow;

function _scheduleAutoSave(){
  window._isDirty=true;
  _markUnsaved();
  clearTimeout(window._autoSaveTimer);
  window._autoSaveTimer=setTimeout(function(){
    _markSaving();
    _serverSaveNow();
  },1200);
}

function _startPeriodicAutoSave(){
  setInterval(()=>{
    if(window._isDirty){
      _markSaving();
      _serverSaveNow();
    } else {
      const time=document.getElementById('last-saved-time');
      if(time&&window._lastSavedTs){
        const secs=Math.floor((new Date()-window._lastSavedTs)/1000);
        if(secs<60) time.textContent='· just now';
        else if(secs<3600) time.textContent='· '+Math.floor(secs/60)+'m ago';
        else time.textContent='· '+window._lastSavedTs.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});
      }
    }
  },30000);
}

function _initTabSync(){
  try{
    if(!window.BroadcastChannel){console.info('BroadcastChannel not supported');return;}
    window._syncChannel=new BroadcastChannel('rbo_sync_v4');
    window._syncChannel.onmessage=(event)=>{
      const msg=event.data;
      if(!msg||msg.tabId===window._tabId) return;
      if(msg.type==='db_updated'){
        /* SERVER-ONLY: another tab saved to MySQL — re-read from api.php
           instead of from a browser copy (there is none). */
        try{
          if(typeof window.loadDataFromServer==='function'){
            Promise.resolve(window.loadDataFromServer()).then(function(){
              _markSynced();
              _showSyncToast('🔄 Data reloaded from server');
              const activePage=document.querySelector('.page.active');
              if(activePage){
                const pageId=activePage.id?.replace('pg-','');
                if(pageId){try{render(pageId);}catch(e){}}
              }
            });
          }
        }catch(e){console.warn('Tab sync reload failed:',e);}
      } else if(msg.type==='tab_opened'){
        window._syncChannel.postMessage({type:'tab_hello',tabId:window._tabId,ts:Date.now()});
      } else if(msg.type==='tab_hello'){
        _showSyncToast('👋 Another tab is open — changes will sync automatically');
      }
    };
    window._syncChannel.postMessage({type:'tab_opened',tabId:window._tabId,ts:Date.now()});
    console.info('Tab sync ready — tabId:',window._tabId);
  }catch(e){console.warn('Tab sync init failed:',e);}
}

function _showSyncToast(msg){
  const existing=document.getElementById('sync-toast');
  if(existing) existing.remove();
  const el=document.createElement('div');
  el.id='sync-toast';
  el.className='sync-toast';
  el.innerHTML=msg;
  document.body.appendChild(el);
  setTimeout(()=>{el.style.opacity='0';el.style.transition='opacity .3s';setTimeout(()=>el.remove(),300);},3500);
}

function _initUnloadWarning(){
  window.addEventListener('beforeunload',(e)=>{
    if(window._isDirty){
      e.preventDefault();
      e.returnValue='You have unsaved changes. Are you sure you want to leave?';
      return e.returnValue;
    }
  });
}

function manualSave(){
  _markSaving();
  _serverSaveNow().then(function(ok){
    _showSyncToast(ok===false ? '⚠️ Save failed — check your connection' : '✅ Saved to server');
  });
}

function showAutoSaveStatus(){
  const isDark=document.documentElement.getAttribute('data-theme')==='dark';
  const bg=isDark?'#1e293b':'#fff';
  const border=isDark?'#334155':'#e5e7eb';
  const textColor=isDark?'#f1f5f9':'#1a202c';
  const existing=document.getElementById('autosave-status-panel');
  if(existing){existing.remove();return;}
  const panel=document.createElement('div');
  panel.id='autosave-status-panel';
  /* FIX (2026-08-25): same bug as the Smart Notification toast — a
     hardcoded top:64px assumed a short topbar and didn't account for the
     app's 80% desktop zoom (CSS `top` gets zoomed again after
     getBoundingClientRect() already returns on-screen/zoomed pixels), so
     this panel opened partly hidden behind the real topbar buttons. */
  const _tb2=document.querySelector('.topbar');
  const _zoom2=parseFloat(getComputedStyle(document.documentElement).zoom)||1;
  const _topOffset2=_tb2?Math.ceil((_tb2.getBoundingClientRect().bottom+10)/_zoom2):64;
  panel.style.cssText=`position:fixed;top:${_topOffset2}px;right:16px;background:${bg};border:1.5px solid ${border};border-radius:12px;padding:16px;z-index:600;box-shadow:0 4px 20px rgba(0,0,0,.2);min-width:270px;color:${textColor};font-family:'Segoe UI',sans-serif;`;
  const secs=window._lastSavedTs?Math.floor((new Date()-window._lastSavedTs)/1000):null;
  const lastSavedStr=window._lastSavedTs?(secs<60?'just now':window._lastSavedTs.toLocaleTimeString('en-GB')):'Never';
  panel.innerHTML=`
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;">
      <div style="font-size:13px;font-weight:800;">💾 Auto-Save Status</div>
      <button data-x-click="document.getElementById('autosave-status-panel').remove()" style="background:none;border:none;cursor:pointer;font-size:18px;color:#9ca3af;line-height:1;">✕</button>
    </div>
    <div style="display:flex;flex-direction:column;gap:8px;font-size:12px;margin-bottom:14px;">
      <div style="display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid ${border};">
        <span style="color:#6b7280;">Status</span>
        <span style="font-weight:700;color:${window._isDirty?'#dc2626':'#16a34a'};">${window._isDirty?'⚠️ Unsaved changes':'✅ All saved'}</span>
      </div>
      <div style="display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid ${border};">
        <span style="color:#6b7280;">Last saved</span>
        <span style="font-weight:700;">${lastSavedStr}</span>
      </div>
      <div style="display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid ${border};">
        <span style="color:#6b7280;">Auto-save interval</span>
        <span style="font-weight:700;">30 seconds</span>
      </div>
      <div style="display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid ${border};">
        <span style="color:#6b7280;">Tab sync</span>
        <span style="font-weight:700;color:${window._syncChannel?'#16a34a':'#9ca3af'};">${window._syncChannel?'✅ Active':'❌ Not supported'}</span>
      </div>
      <div style="display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid ${border};">
        <span style="color:#6b7280;">DB size</span>
        <span style="font-weight:700;">${(JSON.stringify(DB).length/1024).toFixed(1)} KB</span>
      </div>
      <div style="display:flex;justify-content:space-between;padding:6px 0;">
        <span style="color:#6b7280;">Tab ID</span>
        <span style="font-weight:700;font-size:10px;font-family:monospace;">${window._tabId}</span>
      </div>
    </div>
    <div style="display:flex;gap:8px;">
      <button data-x-click="manualSave();document.getElementById('autosave-status-panel').remove()" style="flex:1;padding:9px;background:#16a34a;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:12px;">💾 Save Now</button>
      <button data-x-click="exportFullBackupJSON();document.getElementById('autosave-status-panel').remove()" style="flex:1;padding:9px;background:#2563eb;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:12px;">📥 Backup</button>
    </div>`;
  document.body.appendChild(panel);
  setTimeout(()=>{if(panel.parentNode)panel.remove();},10000);
}

function initAutoSave(){
  _initTabSync();
  _startPeriodicAutoSave();
  _initUnloadWarning();
  setTimeout(()=>{window._lastSavedTs=new Date();_markSaved();},800);
  console.info('✅ Auto-save initialized (30s + tab sync)');
}


// ═══════════════════════════════════════════════════════════════
// PWA — Progressive Web App System
// ═══════════════════════════════════════════════════════════════
function initPWA(){
  // Generate and inject manifest dynamically
  const co=DB.settings||{};
  const appName=co.companyName||'Rice Bran Oil ERP';
  const manifest={
    name:appName,
    short_name:co.shortName||'RBO ERP',
    description:'Rice Bran Oil Management System — Complete ERP',
    start_url:window.location.href.split('?')[0],
    display:'standalone',
    background_color:'#0f3d26',
    theme_color:'#16a34a',
    orientation:'portrait-primary',
    icons:[
      {src:"data:image/png;base64,",sizes:'192x192',type:'image/png'},
      {src:"data:image/png;base64,",sizes:'512x512',type:'image/png'},
    ],
    shortcuts:[
      {name:'Dashboard',url:window.location.href.split('?')[0]+'#dashboard',description:'Open Dashboard'},
      {name:'New Order',url:window.location.href.split('?')[0]+'#orders',description:'Create New Order'},
      {name:'Transactions',url:window.location.href.split('?')[0]+'#transactions',description:'View Transactions'},
    ]
  };
  const blob=new Blob([JSON.stringify(manifest)],{type:'application/json'});
  const url=URL.createObjectURL(blob);
  const link=document.getElementById('pwa-manifest-link');
  if(link) link.href=url;

  // Register service worker for offline support
  /* FIX 7 (superseded): the old probe was hardcoded to Promise.resolve({ok:false}),
     so it ALWAYS skipped registration even when sw.js was deployed right next to
     this file. It now actually checks for the file before registering. */
  if('serviceWorker' in navigator && (location.protocol==='https:'||location.protocol==='http:')){
    fetch('sw.js', {method:'HEAD', cache:'no-store'}).then(function(r){
      // Many servers rewrite unknown paths to index.php, so a 200 is not enough:
      // the response must really be JavaScript, otherwise registration throws
      // "The script has an unsupported MIME type ('text/html')".
      var ct = (r.headers.get('content-type')||'').toLowerCase();
      if(!r.ok || !(ct.indexOf('javascript')>=0 || ct.indexOf('ecmascript')>=0)) throw new Error('sw.js not deployed');
      return navigator.serviceWorker.register('sw.js');
    }).then(function(){ console.info('\u2705 Service Worker registered \u2014 offline support active'); })
      .catch(function(){ console.info('Service Worker skipped \u2014 sw.js not deployed (app still works online)'); });
  }


  // Install prompt
  window._pwaInstallPrompt=null;
  window.addEventListener('beforeinstallprompt',e=>{
    e.preventDefault();
    window._pwaInstallPrompt=e;
    showPWAInstallBanner();
  });

  window.addEventListener('appinstalled',()=>{
    hidePWAInstallBanner();
    toast('App installed! You can now open it from your home screen.', 's');
    logAudit('PWA','Install','App installed to home screen');
  });
}

function showPWAInstallBanner(){
  if(document.getElementById('pwa-install-banner')) return;
  const isDark=document.documentElement.getAttribute('data-theme')==='dark';
  const banner=document.createElement('div');
  banner.id='pwa-install-banner';
  banner.style.cssText=`position:fixed;bottom:20px;left:50%;transform:translateX(-50%);
    background:${isDark?'#1e293b':'#fff'};border:1.5px solid #16a34a;border-radius:14px;
    padding:14px 20px;box-shadow:0 8px 24px rgba(0,0,0,.2);z-index:9990;
    display:flex;align-items:center;gap:14px;max-width:380px;width:90%;
    animation:slideInUp .3s ease;`;
  banner.innerHTML=`
    <span style="font-size:32px;">🌾</span>
    <div style="flex:1;">
      <div style="font-size:13px;font-weight:800;color:${isDark?'#f1f5f9':'#0f3d26'};">Install RBO ERP App</div>
      <div style="font-size:11px;color:${isDark?'#94a3b8':'#6b7280'};margin-top:2px;">Add to home screen for quick access</div>
    </div>
    <button data-x-click="installPWA()" style="padding:8px 16px;background:#16a34a;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:12px;white-space:nowrap;">Install</button>
    <button data-x-click="hidePWAInstallBanner()" style="background:none;border:none;cursor:pointer;font-size:18px;color:#9ca3af;padding:0;">✕</button>`;
  document.body.appendChild(banner);
}

function hidePWAInstallBanner(){
  const b=document.getElementById('pwa-install-banner');
  if(b) b.remove();
}

function installPWA(){
  if(window._pwaInstallPrompt){
    window._pwaInstallPrompt.prompt();
    window._pwaInstallPrompt.userChoice.then(r=>{
      if(r.outcome==='accepted') toast('Installing app...', 's');
      window._pwaInstallPrompt=null;
      hidePWAInstallBanner();
    });
  } else {
    // Manual instructions
    const ua=navigator.userAgent;
    let msg='To install:\n\n';
    if(/iPhone|iPad/.test(ua)) msg+='1. Tap the Share button (□↑)\n2. Tap "Add to Home Screen"\n3. Tap "Add"';
    else if(/Android/.test(ua)) msg+='1. Tap the menu (⋮)\n2. Tap "Add to Home Screen"\n3. Tap "Add"';
    else msg+='1. Click the install icon (⊕) in your browser address bar\n2. Click "Install"';
    alert(msg);
  }
}

function renderPWASettings(){
  const el=document.getElementById('pwa-settings-wrap');
  if(!el) return;
  const isDark=document.documentElement.getAttribute('data-theme')==='dark';
  const bg=isDark?'#1e293b':'#fff';
  const border=isDark?'#334155':'#e5e7eb';
  const textColor=isDark?'#f1f5f9':'#1a202c';
  const text2=isDark?'#94a3b8':'#6b7280';
  const isInstalled=window.matchMedia('(display-mode: standalone)').matches;
  el.innerHTML=`
    <div style="background:${bg};border:1.5px solid ${border};border-radius:12px;padding:18px;margin-bottom:16px;">
      <div style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:12px;">📱 Install as App (PWA)</div>
      <div style="display:flex;align-items:center;gap:14px;flex-wrap:wrap;">
        <div style="font-size:48px;">🌾</div>
        <div style="flex:1;">
          <div style="font-size:13px;font-weight:700;color:${textColor};">Rice Bran Oil ERP</div>
          <div style="font-size:11px;color:${text2};margin-top:4px;">Install this app on your device for offline access and a native app experience</div>
          <div style="margin-top:10px;display:flex;gap:8px;flex-wrap:wrap;">
            ${isInstalled
              ?'<span style="padding:6px 14px;background:#dcfce7;color:#16a34a;border-radius:8px;font-size:12px;font-weight:700;">✅ Already Installed</span>'
              :`<button data-x-click="installPWA()" style="padding:8px 18px;background:#16a34a;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:13px;">📱 Install App</button>`}
            <button data-x-click="showPWAInstallBanner()" style="padding:8px 14px;background:#f3f4f6;color:#374151;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:12px;">Show Banner</button>
          </div>
        </div>
      </div>
      <div style="margin-top:14px;padding:12px;background:#f0fdf4;border-radius:8px;font-size:11px;color:#374151;">
        <strong>Benefits:</strong> Works offline • Faster loading • Home screen icon • No browser UI • Push notifications ready
      </div>
    </div>`;
}


// ═══════════════════════════════════════════════════════════════
// SMART NOTIFICATIONS SYSTEM
// Auto-detects: overdue payments, low stock, low bank, late orders
// ═══════════════════════════════════════════════════════════════
let _notifCheckInterval = null;

function initSmartNotifications(){
  // Check every 5 minutes
  _notifCheckInterval = setInterval(checkSmartNotifications, 5 * 60 * 1000);
  // Also check on startup after 3 seconds
  setTimeout(checkSmartNotifications, 3000);
  console.info('✅ Smart Notifications initialized');
}

function checkSmartNotifications(){
  if(!DB) return;
  const notifs=[];
  const today=new Date().toISOString().split('T')[0];
  const now=new Date();

  // ── 1. Overdue Customer Payments ──
  const overdueCustomers=(DB.customers||[]).filter(c=>{
    const isCustomer=isCustomerParty(c);
    return isCustomer&&(c.bal||0)>100000; // over 1 lakh
  });
  if(overdueCustomers.length>0){
    notifs.push({
      id:'overdue-customers',
      type:'warning',
      icon:'💰',
      title:'Overdue Payments',
      msg:overdueCustomers.length+' customer(s) have dues over ৳1 lakh',
      detail:overdueCustomers.slice(0,3).map(c=>c.name+': ৳'+(c.bal||0).toLocaleString('en-IN')).join(', '),
      action:"nav('customers')",
      actionLabel:'View Customers',
      priority:'high'
    });
  }

  // ── 2. Low Stock Alert ──
  const lowStock=(DB.products||[]).filter(p=>(p.qty||0)<=(p.minStock||p.minQty||10)&&(p.qty||0)>=0);
  const outOfStock=(DB.products||[]).filter(p=>(p.qty||0)<=0);
  if(outOfStock.length>0){
    notifs.push({
      id:'out-of-stock',
      type:'critical',
      icon:'📦',
      title:'Out of Stock!',
      msg:outOfStock.length+' product(s) are OUT OF STOCK',
      detail:outOfStock.slice(0,3).map(p=>p.name).join(', '),
      action:"nav('inventory')",
      actionLabel:'View Inventory',
      priority:'critical'
    });
  } else if(lowStock.length>0){
    notifs.push({
      id:'low-stock',
      type:'warning',
      icon:'⚠️',
      title:'Low Stock Warning',
      msg:lowStock.length+' product(s) below minimum stock level',
      detail:lowStock.slice(0,3).map(p=>p.name+': '+p.qty+' left').join(', '),
      action:"nav('stockalerts')",
      actionLabel:'View Stock',
      priority:'medium'
    });
  }

  // ── 3. Low Bank Balance ──
  const lowBanks=(DB.banks||[]).filter(b=>(b.bal||0)<50000);
  const negativeBanks=(DB.banks||[]).filter(b=>(b.bal||0)<0);
  if(negativeBanks.length>0){
    notifs.push({
      id:'negative-bank',
      type:'critical',
      icon:'🏦',
      title:'Negative Bank Balance!',
      msg:negativeBanks.length+' account(s) have negative balance',
      detail:negativeBanks.map(b=>b.name+': ৳'+b.bal.toLocaleString('en-IN')).join(', '),
      action:"nav('banks')",
      actionLabel:'View Banks',
      priority:'critical'
    });
  } else if(lowBanks.length>0){
    notifs.push({
      id:'low-bank',
      type:'warning',
      icon:'🏦',
      title:'Low Bank Balance',
      msg:lowBanks.length+' account(s) below ৳50,000',
      detail:lowBanks.map(b=>b.name+': ৳'+(b.bal||0).toLocaleString('en-IN')).join(', '),
      action:"nav('banks')",
      actionLabel:'View Banks',
      priority:'medium'
    });
  }

  // ── 4. Late Orders ──
  const lateOrders=(DB.orders||[]).filter(o=>{
    if(!o.deliveryDate||o.deliveryStatus==='Delivered'||o.deliveryStatus==='Cancelled') return false;
    return o.deliveryDate<today;
  });
  if(lateOrders.length>0){
    notifs.push({
      id:'late-orders',
      type:'warning',
      icon:'🚛',
      title:'Late Deliveries',
      msg:lateOrders.length+' order(s) past delivery date',
      detail:lateOrders.slice(0,3).map(o=>o.customerName+' (due: '+o.deliveryDate+')').join(', '),
      action:"nav('orders')",
      actionLabel:'View Orders',
      priority:'high'
    });
  }

  // ── 5. Pending Orders (too many) ──
  const pendingOrders=(DB.orders||[]).filter(o=>o.deliveryStatus==='Pending');
  if(pendingOrders.length>15){
    notifs.push({
      id:'many-pending',
      type:'info',
      icon:'📋',
      title:'Many Pending Orders',
      msg:pendingOrders.length+' orders are still pending',
      detail:'Consider processing or updating order statuses',
      action:"nav('orders')",
      actionLabel:'View Orders',
      priority:'low'
    });
  }

  // ── 6. No Backup Warning ──
  if(!DB.lastBackup){
    notifs.push({
      id:'no-backup',
      type:'info',
      icon:'💾',
      title:'No Backup Found',
      msg:'Your data has never been backed up',
      detail:'Create a backup to protect your business data',
      action:"nav('googledrivebackup')",
      actionLabel:'Backup Now',
      priority:'medium'
    });
  }

  // ── 7. Unpaid Employees This Month ──
  const thisMonth=now.toISOString().substring(0,7);
  const activeEmps=(DB.employees||[]).filter(e=>e.status==='Active');
  const paidThisMonth=new Set((DB.tx||[]).filter(t=>t.type==='Salary Payment'&&(t.date||'').startsWith(thisMonth)).map(t=>t.party));
  const unpaidEmps=activeEmps.filter(e=>!paidThisMonth.has(e.name));
  if(unpaidEmps.length>0&&now.getDate()>20){
    notifs.push({
      id:'unpaid-salary',
      type:'warning',
      icon:'💼',
      title:'Salary Not Paid',
      msg:unpaidEmps.length+' employee(s) not paid for '+thisMonth,
      detail:unpaidEmps.slice(0,3).map(e=>e.name).join(', '),
      action:"nav('payroll')",
      actionLabel:'Pay Salary',
      priority:'high'
    });
  }

  // Store and display
  if(!DB.smartNotifications) DB.smartNotifications={};
  DB.smartNotifications.lastCheck=new Date().toISOString();
  DB.smartNotifications.items=notifs;

  // Update notification badge
  updateNotifBadge(notifs);

  // Show toast for critical items (only once per session)
  if(!window._notifShown) {
    window._notifShown=new Set();
  }
  notifs.filter(n=>n.priority==='critical').forEach(n=>{
    if(!window._notifShown.has(n.id)){
      window._notifShown.add(n.id);
      showSmartNotifToast(n);
    }
  });

  return notifs;
}

function updateNotifBadge(notifs){
  const count=notifs.filter(n=>n.priority==='critical'||n.priority==='high').length;
  // Update topbar notification indicator
  let badge=document.getElementById('smart-notif-badge');
  if(!badge){
    const topbarRight=document.querySelector('.topbar-right');
    if(topbarRight){
      const wrap=document.createElement('div');
      wrap.style.cssText='position:relative;cursor:pointer;';
      wrap.onclick=()=>nav('realtimealerts');
      wrap.title='Smart Notifications';
      wrap.innerHTML=`<span style="font-size:20px;">🔔</span><span id="smart-notif-badge" style="position:absolute;top:-4px;right:-4px;background:#dc2626;color:#fff;border-radius:50%;width:16px;height:16px;font-size:9px;font-weight:800;display:flex;align-items:center;justify-content:center;"></span>`;
      topbarRight.insertBefore(wrap, topbarRight.firstChild);
      badge=document.getElementById('smart-notif-badge');
    }
  }
  if(badge){
    badge.textContent=count>0?count:'';
    badge.style.display=count>0?'flex':'none';
    badge.style.animation=count>0?'pulse 2s infinite':'none';
  }
}

function showSmartNotifToast(n){
  const colors={critical:'#dc2626',warning:'#d97706',info:'#2563eb'};
  const color=colors[n.type]||'#6b7280';
  const toast=document.createElement('div');
  /* FIX (2026-08-25): the hardcoded top:70px assumed a short single-row
     topbar. The topbar is height:auto and can run taller (more buttons,
     narrower windows), so this toast — including the New Transaction
     button — regularly sat on top of the real topbar controls instead of
     below them. Measuring the topbar's actual bottom edge keeps this toast
     clear of it at any width or button count.
     getBoundingClientRect() returns already-zoomed (on-screen) pixels, but
     the CSS `top` property is a pre-zoom length that the browser zooms
     AGAIN when applying it — this app defaults to 80% zoom on desktop (see
     --app-vh), so a raw rect value assigned straight to `top` renders at
     only 80% of the intended offset. Dividing by the current zoom factor
     converts the on-screen gap back into the pre-zoom length `top` expects. */
  const _tb=document.querySelector('.topbar');
  const _zoom=parseFloat(getComputedStyle(document.documentElement).zoom)||1;
  const _topOffset=_tb?Math.ceil((_tb.getBoundingClientRect().bottom+10)/_zoom):70;
  toast.style.cssText=`position:fixed;top:${_topOffset}px;right:16px;background:#fff;border:2px solid ${color};border-radius:12px;padding:14px 16px;z-index:9990;box-shadow:0 4px 20px rgba(0,0,0,.15);max-width:320px;animation:slideInRight .3s ease;`;
  toast.innerHTML=`
    <div style="display:flex;align-items:flex-start;gap:10px;">
      <span style="font-size:22px;">${n.icon}</span>
      <div style="flex:1;">
        <div style="font-size:13px;font-weight:800;color:#1a202c;">${escHTML(n.title)}</div>
        <div style="font-size:11px;color:#6b7280;margin-top:2px;">${n.msg}</div>
        <div style="display:flex;gap:8px;margin-top:8px;">
          <button data-x-click="xNotifAction(this,'${escJSAttr(n.action)}')" style="padding:5px 12px;background:${color};color:#fff;border:none;border-radius:6px;font-size:11px;font-weight:700;cursor:pointer;">${n.actionLabel}</button>
          <button data-x-click="this.closest('div[style]').remove()" style="padding:5px 10px;background:#f3f4f6;color:#374151;border:none;border-radius:6px;font-size:11px;cursor:pointer;">Dismiss</button>
        </div>
      </div>
    </div>`;
  document.body.appendChild(toast);
  setTimeout(()=>{toast.style.opacity='0';toast.style.transition='opacity .3s';setTimeout(()=>toast.remove(),300);},8000);
}

function renderSmartNotifications(){
  // Enhanced renderRealtimeAlerts with smart notifications
  const el=document.getElementById('pg-realtimealerts');
  if(!el) return;
  const notifs=checkSmartNotifications();
  const isDark=document.documentElement.getAttribute('data-theme')==='dark';
  const bg=isDark?'#1e293b':'#fff';
  const border=isDark?'#334155':'#e5e7eb';
  const textColor=isDark?'#f1f5f9':'#1a202c';
  const text2=isDark?'#94a3b8':'#6b7280';

  const critical=notifs.filter(n=>n.priority==='critical').length;
  const high=notifs.filter(n=>n.priority==='high').length;
  const medium=notifs.filter(n=>n.priority==='medium').length;
  const low=notifs.filter(n=>n.priority==='low').length;

  const priorityColors={critical:'#dc2626',high:'#ea580c',medium:'#d97706',low:'#2563eb',info:'#2563eb'};
  const typeColors={critical:'#dc2626',warning:'#d97706',info:'#2563eb'};

  el.innerHTML=`<div style="padding:20px;">
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:20px;flex-wrap:wrap;gap:10px;">
      <div>
        <h2 style="font-size:20px;font-weight:800;color:#0f3d26;margin:0;">🔔 Smart Notifications</h2>
        <p style="font-size:12px;color:${text2};margin:4px 0 0;">Auto-detected alerts — Last checked: ${DB.smartNotifications?.lastCheck?new Date(DB.smartNotifications.lastCheck).toLocaleTimeString('en-GB'):'Never'}</p>
      </div>
      <button data-x-click="renderSmartNotifications()" style="padding:9px 18px;background:#16a34a;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:13px;">🔄 Refresh</button>
    </div>

    <!-- Summary KPIs -->
    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:12px;margin-bottom:20px;">
      ${[
        {label:'Critical',val:critical,color:'#dc2626',icon:'🚨'},
        {label:'High Priority',val:high,color:'#ea580c',icon:'🔴'},
        {label:'Medium',val:medium,color:'#d97706',icon:'⚠️'},
        {label:'Low / Info',val:low,color:'#2563eb',icon:'ℹ️'},
        {label:'Total Alerts',val:notifs.length,color:'#7c3aed',icon:'🔔'},
      ].map(k=>`<div class="kpi-card" style="border-left:4px solid ${k.color};">
        <div style="font-size:18px;">${k.icon}</div>
        <div style="font-size:22px;font-weight:900;color:${k.color};margin-top:4px;">${k.val}</div>
        <div style="font-size:10px;color:${text2};font-weight:700;">${k.label}</div>
      </div>`).join('')}
    </div>

    <!-- Notification List -->
    <div style="background:${bg};border:1px solid ${border};border-radius:12px;overflow:hidden;">
      ${notifs.length?notifs.sort((a,b)=>{
        const order={critical:0,high:1,medium:2,low:3,info:4};
        return (order[a.priority]||4)-(order[b.priority]||4);
      }).map(n=>`
        <div style="display:flex;align-items:flex-start;gap:14px;padding:16px 18px;border-bottom:1px solid ${border};background:${n.priority==='critical'?'#fef2f2':n.priority==='high'?'#fff7ed':bg};">
          <span style="font-size:24px;flex-shrink:0;">${n.icon}</span>
          <div style="flex:1;">
            <div style="display:flex;align-items:center;gap:8px;margin-bottom:4px;flex-wrap:wrap;">
              <span style="font-size:13px;font-weight:800;color:${textColor};">${n.title}</span>
              <span style="padding:2px 8px;border-radius:6px;font-size:9px;font-weight:800;background:${priorityColors[n.priority]||'#6b7280'};color:#fff;text-transform:uppercase;">${n.priority}</span>
            </div>
            <div style="font-size:12px;color:${textColor};font-weight:600;">${n.msg}</div>
            <div style="font-size:11px;color:${text2};margin-top:3px;">${n.detail}</div>
          </div>
          <button data-x-click="${n.action}" style="padding:7px 14px;background:${typeColors[n.type]||'#6b7280'};color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:12px;flex-shrink:0;white-space:nowrap;">${n.actionLabel} →</button>
        </div>`).join('')
      :`<div style="text-align:center;padding:40px;color:${text2};">
        <div style="font-size:48px;margin-bottom:12px;">✅</div>
        <div style="font-size:16px;font-weight:800;color:#16a34a;">All Clear!</div>
        <div style="font-size:12px;margin-top:6px;">No alerts detected. Your system is healthy.</div>
      </div>`}
    </div>

    <!-- Notification Settings -->
    <div style="background:${bg};border:1px solid ${border};border-radius:12px;padding:18px;margin-top:16px;">
      <div style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:12px;">⚙️ Notification Settings</div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">
        ${[
          ['Overdue Payments (>৳1L)','notif-overdue',true],
          ['Low Stock Alerts','notif-lowstock',true],
          ['Low Bank Balance (<৳50K)','notif-lowbank',true],
          ['Late Deliveries','notif-lateorders',true],
          ['Unpaid Salary (after 20th)','notif-salary',true],
          ['No Backup Warning','notif-backup',true],
        ].map(([label,key,def])=>`
          <label style="display:flex;align-items:center;gap:8px;cursor:pointer;padding:8px;background:#f9fafb;border-radius:8px;">
            <input type="checkbox" id="${key}" ${(DB.settings?.[key]!==false)?'checked':''} data-x-change="saveNotifSetting('${key}',this.checked)" style="width:16px;height:16px;cursor:pointer;">
            <span style="font-size:12px;font-weight:600;color:${textColor};">${label}</span>
          </label>`).join('')}
      </div>
    </div>
  </div>`;
}

function saveNotifSetting(key, val){
  if(!DB.settings) DB.settings={};
  DB.settings[key]=val;
  saveDB();
  toast('Notification setting saved','s');
}


// ═══════════════════════════════════════════════════════════════
// ADVANCED ORDER REPORTS
// ═══════════════════════════════════════════════════════════════
function renderOrderReports(){
  const el=document.getElementById('pg-orderreports');
  if(!el) return;
  const isDark=document.documentElement.getAttribute('data-theme')==='dark';
  const bg=isDark?'#1e293b':'#fff';
  const border=isDark?'#334155':'#e5e7eb';
  const textColor=isDark?'#f1f5f9':'#1a202c';
  const text2=isDark?'#94a3b8':'#6b7280';
  const orders=DB.orders||[];
  const today=new Date().toISOString().split('T')[0];

  // ── Delivery Performance ──
  const delivered=orders.filter(o=>o.deliveryStatus==='Delivered');
  const onTime=delivered.filter(o=>!o.deliveryDate||o.deliveryDate>=o.orderDate);
  const late=orders.filter(o=>o.deliveryDate&&o.deliveryDate<today&&o.deliveryStatus!=='Delivered'&&o.deliveryStatus!=='Cancelled');
  const cancelled=orders.filter(o=>o.deliveryStatus==='Cancelled');
  const deliveryRate=orders.length>0?Math.round(delivered.length/orders.length*100):0;

  // ── Customer Order Summary ──
  const custMap={};
  orders.forEach(o=>{
    if(!custMap[o.customerName]) custMap[o.customerName]={name:o.customerName,orders:0,qty:0,value:0,delivered:0};
    custMap[o.customerName].orders++;
    custMap[o.customerName].qty+=parseFloat(o.qty)||0;
    custMap[o.customerName].value+=(parseFloat(o.qty)||0)*(parseFloat(o.rate)||0);
    if(o.deliveryStatus==='Delivered') custMap[o.customerName].delivered++;
  });
  const topCustomers=Object.values(custMap).sort((a,b)=>b.value-a.value).slice(0,10);

  // ── Product Summary ──
  const prodMap={};
  orders.forEach(o=>{
    if(!prodMap[o.productName]) prodMap[o.productName]={name:o.productName,orders:0,qty:0,value:0};
    prodMap[o.productName].orders++;
    prodMap[o.productName].qty+=parseFloat(o.qty)||0;
    prodMap[o.productName].value+=(parseFloat(o.qty)||0)*(parseFloat(o.rate)||0);
  });
  const topProducts=Object.values(prodMap).sort((a,b)=>b.qty-a.qty).slice(0,10);

  // ── Driver/Truck Performance ──
  const truckMap={};
  orders.filter(o=>o.truckId).forEach(o=>{
    const key=o.truckId;
    if(!truckMap[key]) truckMap[key]={truck:key,driver:o.driverMobile||'—',trips:0,qty:0,delivered:0,late:0};
    truckMap[key].trips++;
    truckMap[key].qty+=parseFloat(o.sendingQty||o.qty)||0;
    if(o.deliveryStatus==='Delivered') truckMap[key].delivered++;
    if(o.deliveryDate&&o.deliveryDate<today&&o.deliveryStatus!=='Delivered') truckMap[key].late++;
  });
  const trucks=Object.values(truckMap).sort((a,b)=>b.trips-a.trips);

  // ── Monthly Order Trend ──
  const monthMap={};
  orders.forEach(o=>{
    const m=(o.orderDate||'').substring(0,7);
    if(!m) return;
    if(!monthMap[m]) monthMap[m]={month:m,orders:0,qty:0,value:0,delivered:0};
    monthMap[m].orders++;
    monthMap[m].qty+=parseFloat(o.qty)||0;
    monthMap[m].value+=(parseFloat(o.qty)||0)*(parseFloat(o.rate)||0);
    if(o.deliveryStatus==='Delivered') monthMap[m].delivered++;
  });
  const months=Object.values(monthMap).sort((a,b)=>a.month.localeCompare(b.month)).slice(-12);

  // ── Dispatch / Sales Register ──
  // Date, Invoice No, Product, Truck ID, Bag Qty, Return Bag Qty, Weight,
  // Location, Amount — one row per sale transaction. Location is read from
  // tx.loc, so it matches whatever the invoice was actually recorded against
  // (Chuadanga / Bogura / Dhaka / Birganj / Valuka / Chittagong / etc.).
  const dispatchLocFilter=document.getElementById('dr-loc-filter')?.value||'';
  const dispatchTxs=(DB.tx||[])
    .filter(t=>isSaleType(t.type))
    .filter(t=>!dispatchLocFilter||t.loc===dispatchLocFilter)
    .sort((a,b)=>(b.date||'').localeCompare(a.date||'')||(b.id||0)-(a.id||0));
  const dispatchLocations=(DB.tx||[]).filter(t=>isSaleType(t.type)).map(t=>t.loc).filter(Boolean)
    .filter((v,i,arr)=>arr.indexOf(v)===i);
  const dispatchTotals=dispatchTxs.reduce((s,t)=>{
    s.bag+=parseFloat(t.bagqty)||0; s.ret+=parseFloat(t.bagret)||0;
    s.wt+=parseFloat(t.wt||t.grosswt||t.qty)||0; s.amt+=parseFloat(t.amount)||0;
    return s;
  },{bag:0,ret:0,wt:0,amt:0});

  el.innerHTML=`<div style="padding:20px;">
