      </div>
      <div style="display:flex;gap:8px;">
        <button data-x-click="exportOrderReportsCSV()" style="padding:9px 16px;background:#2563eb;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:12px;">📥 Export</button>
        <button data-x-click="printPageViaLetterhead('pg-orderreports','Order Reports & Analytics')" style="padding:9px 16px;background:#7c3aed;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:12px;">🖨️ Print</button>
      </div>
    </div>

    <!-- Delivery Performance KPIs -->
    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:12px;margin-bottom:20px;">
      ${[
        {icon:'📋',label:'Total Orders',val:orders.length,color:'#2563eb'},
        {icon:'✅',label:'Delivered',val:delivered.length,color:'#16a34a'},
        {icon:'🚛',label:'In Progress',val:orders.filter(o=>o.deliveryStatus==='On Route'||o.deliveryStatus==='Processing').length,color:'#7c3aed'},
        {icon:'⏳',label:'Pending',val:orders.filter(o=>o.deliveryStatus==='Pending').length,color:'#d97706'},
        {icon:'🔴',label:'Late/Overdue',val:late.length,color:'#dc2626'},
        {icon:'❌',label:'Cancelled',val:cancelled.length,color:'#6b7280'},
        {icon:'📈',label:'Delivery Rate',val:deliveryRate+'%',color:deliveryRate>=80?'#16a34a':deliveryRate>=60?'#d97706':'#dc2626'},
        {icon:'⚖️',label:'Total Qty (KG)',val:orders.reduce((s,o)=>s+(parseFloat(o.qty)||0),0).toLocaleString('en-IN'),color:'#059669'},
      ].map(k=>`<div class="kpi-card" style="border-left:4px solid ${k.color};">
        <div style="font-size:18px;">${k.icon}</div>
        <div style="font-size:18px;font-weight:900;color:${k.color};margin-top:4px;">${k.val}</div>
        <div style="font-size:10px;color:${text2};font-weight:700;">${k.label}</div>
      </div>`).join('')}
    </div>

    <!-- Monthly Trend -->
    ${months.length?`<div style="background:${bg};border:1px solid ${border};border-radius:12px;padding:18px;margin-bottom:16px;">
      <div style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:14px;">📅 Monthly Order Trend</div>
      <div style="overflow-x:auto;">
        <table style="width:100%;border-collapse:collapse;font-size:12px;min-width:600px;">
          <thead><tr style="background:#0f3d26;color:#fff;">
            <th style="padding:8px 12px;text-align:left;">Month</th>
            <th style="padding:8px 12px;text-align:right;">Orders</th>
            <th style="padding:8px 12px;text-align:right;">Total Qty (KG)</th>
            <th style="padding:8px 12px;text-align:right;">Order Value (৳)</th>
            <th style="padding:8px 12px;text-align:right;">Delivered</th>
            <th style="padding:8px 12px;text-align:right;">Delivery Rate</th>
          </tr></thead>
          <tbody>${months.map((m,i)=>`<tr style="background:${i%2===0?'transparent':(isDark?'#162032':'#f9fafb')};border-bottom:1px solid ${border};">
            <td style="padding:8px 12px;font-weight:700;color:${textColor};">${m.month}</td>
            <td style="padding:8px 12px;text-align:right;color:${textColor};">${m.orders}</td>
            <td style="padding:8px 12px;text-align:right;color:#16a34a;font-weight:700;">${m.qty.toLocaleString('en-IN')}</td>
            <td style="padding:8px 12px;text-align:right;color:#2563eb;font-weight:700;">৳${m.value.toLocaleString('en-IN',{minimumFractionDigits:0})}</td>
            <td style="padding:8px 12px;text-align:right;color:#16a34a;">${m.delivered}</td>
            <td style="padding:8px 12px;text-align:right;">
              <span style="padding:2px 8px;border-radius:6px;font-size:10px;font-weight:700;background:${m.orders>0&&m.delivered/m.orders>=.8?'#dcfce7':'#fef9c3'};color:${m.orders>0&&m.delivered/m.orders>=.8?'#16a34a':'#b45309'};">
                ${m.orders>0?Math.round(m.delivered/m.orders*100):0}%
