function renderProductionMgmt(){
  const el=document.getElementById('pg-production');
  if(!el) return;
  const isDark=document.documentElement.getAttribute('data-theme')==='dark';
  const bg=isDark?'#1e293b':'#fff';
  const border=isDark?'#334155':'#e5e7eb';
  const textColor=isDark?'#f1f5f9':'#1a202c';
  const text2=isDark?'#94a3b8':'#6b7280';

  // Data
  const batches=DB.batches||[];
  const prodLog=DB.productionLog||[];
  const rawMaterials=DB.rawMaterials||[];
  const maintenance=DB.maintenance||[];
  const qcRecords=DB.qcRecords||[];

  // KPIs
  const totalBranProcessed=prodLog.reduce((s,l)=>s+(l.bran||0),0);
  const totalOilProduced=prodLog.reduce((s,l)=>s+(l.oil||0),0);
  const avgYield=totalBranProcessed>0?(totalOilProduced/totalBranProcessed*100).toFixed(2):0;
  const totalBatches=batches.length;
  const gradeA=batches.filter(b=>b.grade==='Grade A').length;

  el.innerHTML=`<div style="padding:20px;">
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:20px;flex-wrap:wrap;gap:10px;">
      <div>
        <h2 style="font-size:20px;font-weight:800;color:#0f3d26;margin:0;">🏭 Production Management</h2>
        <p style="font-size:12px;color:${text2};margin:4px 0 0;">Raw materials, batches, quality control & machine maintenance</p>
      </div>
    </div>

    <!-- Production KPIs -->
    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:12px;margin-bottom:20px;">
      ${[
        {icon:'🌾',label:'Bran Processed',val:totalBranProcessed.toLocaleString('en-IN')+' KG',color:'#d97706'},
        {icon:'🛢️',label:'Oil Produced',val:totalOilProduced.toLocaleString('en-IN')+' KG',color:'#16a34a'},
        {icon:'📊',label:'Avg Yield',val:avgYield+'%',color:'#2563eb'},
        {icon:'📦',label:'Total Batches',val:totalBatches,color:'#7c3aed'},
        {icon:'⭐',label:'Grade A Batches',val:gradeA,color:'#059669'},
        {icon:'🔧',label:'Maintenance Records',val:maintenance.length,color:'#dc2626'},
      ].map(k=>`<div class="kpi-card" style="border-left:4px solid ${k.color};">
        <div style="font-size:20px;">${k.icon}</div>
        <div style="font-size:18px;font-weight:900;color:${k.color};margin-top:4px;">${k.val}</div>
        <div style="font-size:10px;color:${text2};font-weight:700;">${k.label}</div>
      </div>`).join('')}
    </div>

    <!-- Tabs -->
    <div style="display:flex;gap:4px;background:${bg};border-radius:12px;padding:6px;border:1px solid ${border};margin-bottom:16px;flex-wrap:wrap;">
      ${['rawmat','batches','qc','maintenance','log'].map((t,i)=>`
        <button data-x-click="prodTab('${t}')" id="prod-tab-${t}"
          style="padding:8px 14px;border-radius:8px;border:none;cursor:pointer;font-size:12px;font-weight:700;transition:all .2s;background:${i===0?'#16a34a':'transparent'};color:${i===0?'#fff':'#6b7280'};">
          ${['🌾 Raw Materials','📦 Batches','✅ Quality Control','🔧 Maintenance','📋 Production Log'][i]}
        </button>`).join('')}
    </div>

    <!-- RAW MATERIALS -->
    <div id="prod-panel-rawmat">
      <div style="background:${bg};border:1px solid ${border};border-radius:12px;overflow:hidden;">
        <div style="padding:14px 18px;border-bottom:1px solid ${border};display:flex;justify-content:space-between;align-items:center;">
          <div style="font-size:14px;font-weight:800;color:#0f3d26;">🌾 Raw Material Inventory</div>
          <button data-x-click="openRawMatModal()" style="padding:7px 14px;background:#16a34a;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:12px;">➕ Add Material</button>
        </div>
        ${rawMaterials.length?`<div style="overflow-x:auto;"><table style="width:100%;border-collapse:collapse;font-size:12px;">
          <thead><tr style="background:#f9fafb;">
            <th style="padding:8px 12px;text-align:left;font-size:10px;font-weight:700;color:${text2};">MATERIAL</th>
            <th style="padding:8px 12px;text-align:right;font-size:10px;font-weight:700;color:${text2};">STOCK (KG)</th>
            <th style="padding:8px 12px;text-align:right;font-size:10px;font-weight:700;color:${text2};">MIN STOCK</th>
            <th style="padding:8px 12px;text-align:right;font-size:10px;font-weight:700;color:${text2};">RATE (৳/KG)</th>
            <th style="padding:8px 12px;text-align:right;font-size:10px;font-weight:700;color:${text2};">VALUE (৳)</th>
            <th style="padding:8px 12px;text-align:center;font-size:10px;font-weight:700;color:${text2};">STATUS</th>
            <th style="padding:8px 12px;text-align:center;font-size:10px;font-weight:700;color:${text2};">ACTIONS</th>
          </tr></thead>
          <tbody>${rawMaterials.map(m=>{
            const isLow=(m.stock||0)<=(m.minStock||100);
            const val=(m.stock||0)*(m.rate||0);
            return `<tr style="border-bottom:1px solid ${border};">
              <td style="padding:8px 12px;font-weight:700;color:${textColor};">${escHTML(m.name)}</td>
              <td style="padding:8px 12px;text-align:right;font-weight:700;color:${isLow?'#dc2626':'#16a34a'};">${(m.stock||0).toLocaleString('en-IN')}</td>
              <td style="padding:8px 12px;text-align:right;color:${text2};">${(m.minStock||0).toLocaleString('en-IN')}</td>
              <td style="padding:8px 12px;text-align:right;color:${textColor};">৳${(m.rate||0).toLocaleString('en-IN',{minimumFractionDigits:2})}</td>
              <td style="padding:8px 12px;text-align:right;color:#2563eb;font-weight:700;">৳${val.toLocaleString('en-IN',{minimumFractionDigits:0})}</td>
              <td style="padding:8px 12px;text-align:center;"><span style="padding:2px 8px;border-radius:6px;font-size:10px;font-weight:700;background:${isLow?'#fee2e2':'#dcfce7'};color:${isLow?'#dc2626':'#16a34a'};">${isLow?'⚠️ Low':'✅ OK'}</span></td>
              <td style="padding:8px 12px;text-align:center;">
                <button data-x-click="addRawMatStock('${m.id}')" style="padding:3px 8px;background:#dcfce7;color:#16a34a;border:none;border-radius:5px;cursor:pointer;font-size:10px;font-weight:700;margin-right:3px;">+Stock</button>
                <button data-x-click="deleteRawMat('${m.id}')" style="padding:3px 8px;background:#fee2e2;color:#dc2626;border:none;border-radius:5px;cursor:pointer;font-size:10px;font-weight:700;">🗑️</button>
              </td>
            </tr>`;
          }).join('')}</tbody>
        </table></div>`
        :`<div style="text-align:center;padding:30px;color:${text2};">No raw materials added yet. Click "Add Material" to start.</div>`}
      </div>
    </div>

    <!-- BATCHES -->
    <div id="prod-panel-batches" style="display:none;">
      <div style="background:${bg};border:1px solid ${border};border-radius:12px;overflow:hidden;">
        <div style="padding:14px 18px;border-bottom:1px solid ${border};display:flex;justify-content:space-between;align-items:center;">
          <div style="font-size:14px;font-weight:800;color:#0f3d26;">📦 Production Batches</div>
          <button data-x-click="openBatchModal()" style="padding:7px 14px;background:#16a34a;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:12px;">➕ New Batch</button>
        </div>
        ${batches.length?`<div style="overflow-x:auto;"><table style="width:100%;border-collapse:collapse;font-size:12px;">
          <thead><tr style="background:#0f3d26;color:#fff;">
            <th style="padding:8px 12px;text-align:left;">Batch #</th>
            <th style="padding:8px 12px;text-align:left;">Date</th>
            <th style="padding:8px 12px;text-align:right;">Bran (KG)</th>
            <th style="padding:8px 12px;text-align:right;">Oil (KG)</th>
            <th style="padding:8px 12px;text-align:right;">Cake (KG)</th>
            <th style="padding:8px 12px;text-align:right;">Yield %</th>
            <th style="padding:8px 12px;text-align:center;">Grade</th>
            <th style="padding:8px 12px;text-align:left;">Notes</th>
            <th style="padding:8px 12px;text-align:center;">Del</th>
          </tr></thead>
          <tbody>${batches.sort((a,b)=>b.date.localeCompare(a.date)).map(b=>{
            const yld=b.bran>0?((b.oil/b.bran)*100).toFixed(1):0;
            const gc={'Grade A':'#dcfce7;color:#16a34a','Grade B':'#fef9c3;color:#b45309','Grade C':'#fee2e2;color:#dc2626','Rejected':'#f3f4f6;color:#6b7280'}[b.grade]||'#f3f4f6;color:#6b7280';
            return `<tr style="border-bottom:1px solid ${border};">
              <td style="padding:8px 12px;font-weight:700;color:${textColor};">${b.no}</td>
              <td style="padding:8px 12px;color:${text2};">${b.date}</td>
              <td style="padding:8px 12px;text-align:right;color:#d97706;font-weight:700;">${(b.bran||0).toLocaleString('en-IN')}</td>
              <td style="padding:8px 12px;text-align:right;color:#16a34a;font-weight:700;">${(b.oil||0).toLocaleString('en-IN')}</td>
              <td style="padding:8px 12px;text-align:right;color:${text2};">${(b.cake||0).toLocaleString('en-IN')}</td>
              <td style="padding:8px 12px;text-align:right;font-weight:700;color:#2563eb;">${yld}%</td>
              <td style="padding:8px 12px;text-align:center;"><span style="padding:2px 8px;border-radius:6px;font-size:10px;font-weight:700;background:${gc.split(';')[0]};${gc.split(';')[1]||''}">${b.grade}</span></td>
              <td style="padding:8px 12px;font-size:11px;color:${text2};">${escHTML(b.notes ||'—')}</td>
              <td style="padding:8px 12px;text-align:center;"><button data-x-click="deleteBatch(${b.id})" style="padding:3px 8px;background:#fee2e2;color:#dc2626;border:none;border-radius:5px;cursor:pointer;font-size:10px;">🗑️</button></td>
