      <div class="row"><span style="color:#6b7280;">Payment Type:</span><span style="font-weight:700;">${tx.type}</span></div>
      <div class="row"><span style="color:#6b7280;">Payment Mode:</span><span style="font-weight:700;">${escHTML(tx.mode||tx.bank||'Cash')}</span></div>
      <div class="row"><span style="color:#6b7280;">Bank Account:</span><span style="font-weight:700;">${tx.acc?bankNameToDisplay(tx.acc):'—'}</span></div>
      ${tx.rem||tx.note?`<div class="row"><span style="color:#6b7280;">Narration:</span><span>${escHTML(tx.rem||tx.note)}</span></div>`:''}
      <div class="amount-box">
        <div style="font-size:11px;color:#6b7280;font-weight:700;text-transform:uppercase;margin-bottom:6px;">Amount Paid</div>
        <div style="font-size:28px;font-weight:900;color:#2563eb;">৳${txAmt(tx).toLocaleString('en-IN',{minimumFractionDigits:2})}</div>
      </div>
      <div class="sig-section">
