}

function printStockReport(){
  const co=DB.settings||{};
  const products=DB.products||[];
  const rawMats=DB.rawMaterials||[];
  const totalProdVal=products.reduce((s,p)=>s+(p.qty||0)*(p.rate||0),0);
  const totalRawVal=rawMats.reduce((s,m)=>s+(m.stock||0)*(m.rate||0),0);
  const html=`<!DOCTYPE html><html><head><title>Stock Report</title>
  <style>
    *{margin:0;padding:0;box-sizing:border-box;}
    body{font-family:'Segoe UI',sans-serif;padding:30px;color:#1a202c;font-size:12px;}
    .header{display:flex;justify-content:space-between;margin-bottom:20px;padding-bottom:12px;border-bottom:3px solid #0f3d26;}
    table{width:100%;border-collapse:collapse;margin-bottom:20px;}
    th{background:#0f3d26;color:#fff;padding:8px 10px;text-align:left;font-size:10px;}
    td{padding:7px 10px;border-bottom:1px solid #e5e7eb;}
    tfoot td{background:#f0fdf4;font-weight:800;}
    .section-title{font-size:14px;font-weight:800;color:#0f3d26;margin:16px 0 8px;}
    @page{size:A4;margin:10mm 12mm;}@media print{html,body{max-width:100%!important;}*{overflow:visible!important;max-height:none!important;}img,svg,canvas{max-width:100%!important;height:auto!important;}table{width:100%!important;table-layout:auto!important;word-break:break-word;overflow-wrap:anywhere;}th,td{white-space:normal!important;overflow-wrap:anywhere;}.container,.voucher,.receipt,.doc,.page{max-width:100%!important;width:auto!important;}}table{page-break-inside:auto;}tr{page-break-inside:avoid;}thead{display:table-header-group;}@media print{body{padding:15px;}}
  <\/style></head><body>
  <div class="header">
    <div>
      <div style="font-size:18px;font-weight:900;color:#0f3d26;">${prtCo().logo} ${escHTML(prtCo().name)}</div>
      <div style="font-size:11px;color:#6b7280;">${escHTML(prtCo().address)}</div>
    </div>
    <div style="text-align:right;">
      <div style="font-size:18px;font-weight:900;color:#0f3d26;">STOCK REPORT</div>
      <div style="font-size:11px;color:#6b7280;">As of: ${new Date().toLocaleDateString('en-GB')}</div>
    </div>
  </div>
  <div class="section-title">📦 Finished Products</div>
  <table><thead><tr><th>#</th><th>Product</th><th>Category</th><th>Unit</th><th style="text-align:right;">Stock</th><th style="text-align:right;">Rate (৳)</th><th style="text-align:right;">Value (৳)</th><th>Status</th></tr></thead>
  <tbody>${products.map((p,i)=>{
    const val=(p.qty||0)*(p.rate||0);
    const isLow=(p.qty||0)<=(p.minStock||10);
    return `<tr><td>${i+1}</td><td><strong>${escHTML(p.name)}</strong></td><td>${p.cat||'—'}</td><td>${p.unit||'KG'}</td>
      <td style="text-align:right;font-weight:700;color:${isLow?'#dc2626':'#16a34a'};">${(p.qty||0).toLocaleString('en-IN')}</td>
      <td style="text-align:right;">৳${(p.rate||0).toLocaleString('en-IN',{minimumFractionDigits:2})}</td>
      <td style="text-align:right;font-weight:700;">৳${val.toLocaleString('en-IN',{minimumFractionDigits:0})}</td>
      <td><span style="padding:2px 6px;border-radius:4px;font-size:9px;font-weight:700;background:${isLow?'#fee2e2':'#dcfce7'};color:${isLow?'#dc2626':'#16a34a'};">${isLow?'Low':'OK'}</span></td>
    </tr>`;
  }).join('')}</tbody>
  <tfoot><tr><td colspan="6" style="text-align:right;padding:8px 10px;">Total Inventory Value:</td><td style="text-align:right;padding:8px 10px;">৳${totalProdVal.toLocaleString('en-IN',{minimumFractionDigits:0})}</td><td></td></tr></tfoot></table>
  ${rawMats.length?`<div class="section-title">🌾 Raw Materials</div>
  <table><thead><tr><th>#</th><th>Material</th><th style="text-align:right;">Stock (KG)</th><th style="text-align:right;">Rate (৳)</th><th style="text-align:right;">Value (৳)</th><th>Status</th></tr></thead>
  <tbody>${rawMats.map((m,i)=>{
    const val=(m.stock||0)*(m.rate||0);
    const isLow=(m.stock||0)<=(m.minStock||100);
    return `<tr><td>${i+1}</td><td><strong>${escHTML(m.name)}</strong></td>
      <td style="text-align:right;font-weight:700;color:${isLow?'#dc2626':'#16a34a'};">${(m.stock||0).toLocaleString('en-IN')}</td>
      <td style="text-align:right;">৳${(m.rate||0).toLocaleString('en-IN',{minimumFractionDigits:2})}</td>
      <td style="text-align:right;font-weight:700;">৳${val.toLocaleString('en-IN',{minimumFractionDigits:0})}</td>
      <td><span style="padding:2px 6px;border-radius:4px;font-size:9px;font-weight:700;background:${isLow?'#fee2e2':'#dcfce7'};color:${isLow?'#dc2626':'#16a34a'};">${isLow?'Low':'OK'}</span></td>
    </tr>`;
  }).join('')}</tbody>
  <tfoot><tr><td colspan="4" style="text-align:right;padding:8px 10px;">Total Raw Material Value:</td><td style="text-align:right;padding:8px 10px;">৳${totalRawVal.toLocaleString('en-IN',{minimumFractionDigits:0})}</td><td></td></tr></tfoot></table>`:''}
  <div style="background:#f0fdf4;border-radius:8px;padding:12px 16px;display:flex;justify-content:space-between;font-size:14px;font-weight:900;color:#0f3d26;">
    <span>Total Stock Value:</span>
    <span>৳${(totalProdVal+totalRawVal).toLocaleString('en-IN',{minimumFractionDigits:0})}</span>
  </div>
  </body></html>`;
  const w=openPrintWindow(); if(!w) return;
  w.document.write(html);
  w.document.close();
  setTimeout(()=>w.print(),500);
  logAudit('PRINT','Stock Report','Printed stock report');
}

function printProfitLossStatement(fromDate, toDate){
  const from=fromDate||new Date(new Date().getFullYear(),0,1).toISOString().split('T')[0];
  const to=toDate||new Date().toISOString().split('T')[0];
  const co=DB.settings||{};
  const txs=(DB.tx||[]).filter(t=>t.date&&_dk(t.date)>=_dk(from)&&_dk(t.date)<=_dk(to));
  /* FIX (the printed P&L did not match the P&L on screen): expenses used to
     be classified with a hardcoded list of 18 category names, 17 of which
     are not transaction types in this app ('Office Rent', 'Salary Payment',
     'Electricity Bill' …). Only 'Transport Cost' ever matched, so printed
     expenses came out near zero and printed profit was overstated by almost
     every taka of cost recorded — reproduced: ৳58,000 of expenses printed
     as ৳5,000, and profit as ৳2,31,000 instead of ৳1,78,000.
     It now uses ayanPL(), the same engine the P&L screen uses, which also
     brings in tax deducted at source, transport/handling side costs and
     finance charges — all of which this document simply never counted. */
  let sales, cogs, grossProfit, totalExp, netProfit;
  const expBycat={};
  if(typeof window.ayanPL==='function'){
    const _pl=window.ayanPL(from,to);
    sales=_pl.netSales; cogs=_pl.cogs; grossProfit=_pl.grossProfit;
    totalExp=_pl.totalExp; netProfit=_pl.netProfit;
    Object.keys(_pl.expenses||{}).forEach(k=>{ if(_pl.expenses[k]>0) expBycat[k]=_pl.expenses[k]; });
  }else{
    sales=txs.filter(t=>window.isRevenueTx(t)).reduce((s,t)=>s+txAmt(t),0);
    cogs=window.computeCOGS(txs);
    grossProfit=sales-cogs;
    totalExp=0;
    txs.filter(prtIsExpense).forEach(t=>{
      const k=t.type||'Other Expenses';
      const a=txAmt(t); expBycat[k]=(expBycat[k]||0)+a; totalExp+=a;
    });
    netProfit=grossProfit-totalExp;
  }
  const html=`<!DOCTYPE html><html><head><title>Profit & Loss Statement</title>
  <style>
    *{margin:0;padding:0;box-sizing:border-box;}
    body{font-family:'Segoe UI',sans-serif;padding:30px;color:#1a202c;font-size:13px;}
    .header{display:flex;justify-content:space-between;margin-bottom:24px;padding-bottom:16px;border-bottom:3px solid #0f3d26;}
    .section{margin-bottom:16px;}
    .section-title{font-size:13px;font-weight:800;color:#0f3d26;padding:8px 12px;background:#f0fdf4;border-radius:6px;margin-bottom:8px;}
    .row{display:flex;justify-content:space-between;padding:6px 12px;font-size:13px;}
    .row.sub{padding-left:24px;color:#6b7280;}
    .row.total{font-weight:800;border-top:1px solid #e5e7eb;padding-top:8px;margin-top:4px;}
    .row.grand{font-size:16px;font-weight:900;background:${netProfit>=0?'#f0fdf4':'#fef2f2'};border-radius:8px;padding:12px;color:${netProfit>=0?'#16a34a':'#dc2626'};}
    @page{size:A4;margin:10mm 12mm;}@media print{html,body{max-width:100%!important;}*{overflow:visible!important;max-height:none!important;}img,svg,canvas{max-width:100%!important;height:auto!important;}table{width:100%!important;table-layout:auto!important;word-break:break-word;overflow-wrap:anywhere;}th,td{white-space:normal!important;overflow-wrap:anywhere;}.container,.voucher,.receipt,.doc,.page{max-width:100%!important;width:auto!important;}}table{page-break-inside:auto;}tr{page-break-inside:avoid;}thead{display:table-header-group;}@media print{body{padding:15px;}}
  <\/style></head><body>
  <div class="header">
    <div>
      <div style="font-size:20px;font-weight:900;color:#0f3d26;">${prtCo().logo} ${escHTML(prtCo().name)}</div>
      <div style="font-size:11px;color:#6b7280;">${prtContact()}</div>
    </div>
    <div style="text-align:right;">
      <div style="font-size:20px;font-weight:900;color:#0f3d26;">PROFIT & LOSS STATEMENT</div>
      <div style="font-size:12px;color:#6b7280;">Period: ${from} to ${to}</div>
    </div>
  </div>
  <div class="section">
    <div class="section-title">💰 Revenue</div>
    <div class="row"><span>Sales Revenue</span><span style="color:#16a34a;font-weight:700;">৳${sales.toLocaleString('en-IN',{minimumFractionDigits:2})}</span></div>
    <div class="row total"><span>Total Revenue</span><span style="color:#16a34a;">৳${sales.toLocaleString('en-IN',{minimumFractionDigits:2})}</span></div>
  </div>
  <div class="section">
    <div class="section-title">📦 Cost of Goods Sold</div>
    <div class="row"><span>COGS (qty sold × avg purchase cost)</span><span style="color:#dc2626;">৳${cogs.toLocaleString('en-IN',{minimumFractionDigits:2})}</span></div>
    <div class="row total"><span>Total COGS</span><span style="color:#dc2626;">৳${cogs.toLocaleString('en-IN',{minimumFractionDigits:2})}</span></div>
  </div>
  <div class="row" style="font-size:15px;font-weight:800;padding:10px 12px;background:#f9fafb;border-radius:6px;margin-bottom:16px;">
    <span>Gross Profit</span>
    <span style="color:${grossProfit>=0?'#16a34a':'#dc2626'};">৳${grossProfit.toLocaleString('en-IN',{minimumFractionDigits:2})}</span>
  </div>
  <div class="section">
    <div class="section-title">💸 Operating Expenses</div>
    ${Object.entries(expBycat).map(([cat,amt])=>`<div class="row sub"><span>${cat}</span><span>৳${amt.toLocaleString('en-IN',{minimumFractionDigits:2})}</span></div>`).join('')}
    <div class="row total"><span>Total Expenses</span><span style="color:#dc2626;">৳${totalExp.toLocaleString('en-IN',{minimumFractionDigits:2})}</span></div>
  </div>
  <div class="row grand">
    <span>NET PROFIT / (LOSS)</span>
    <span>৳${netProfit.toLocaleString('en-IN',{minimumFractionDigits:2})}</span>
  </div>
  <div style="margin-top:20px;font-size:11px;color:#9ca3af;text-align:center;">
    ${escHTML(prtCo().name)} • Printed: ${new Date().toLocaleString('en-GB')}
  </div>
  </body></html>`;
  const w=openPrintWindow(); if(!w) return;
  w.document.write(html);
  w.document.close();
  setTimeout(()=>w.print(),500);
  logAudit('PRINT','P&L Statement','Printed P&L for '+from+' to '+to);
}

function renderPrintTemplates(){
  const el=document.getElementById('pg-printtemplates');
  if(!el) return;
  const isDark=document.documentElement.getAttribute('data-theme')==='dark';
  const bg=isDark?'#1e293b':'#fff';
  const border=isDark?'#334155':'#e5e7eb';
  const textColor=isDark?'#f1f5f9':'#1a202c';
  const text2=isDark?'#94a3b8':'#6b7280';
  const thisMonth=new Date().toISOString().substring(0,7);
  const thisYear=new Date().getFullYear();

  el.innerHTML=`<div style="padding:20px;">
    <div style="margin-bottom:20px;">
      <h2 style="font-size:20px;font-weight:800;color:#0f3d26;margin:0;">🖨️ Print Templates</h2>
      <p style="font-size:12px;color:${text2};margin:4px 0 0;">Professional print layouts for all business documents</p>
    </div>
    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:16px;">
      ${[
        {icon:'🧾',title:'Sales Invoice',desc:'Professional invoice with company branding, line items, totals',color:'#16a34a',action:`quickPrintLastInvoice()`},
        {icon:'📦',title:'Purchase Order',desc:'PO with supplier info, items, signature lines',color:'#2563eb',action:`printPurchaseOrder()`},
        {icon:'📋',title:'Delivery Challan',desc:'Challan with delivery details, items, 3 signature boxes',color:'#059669',action:`printDeliveryChallan()`},
        {icon:'🧾',title:'Payment Receipt',desc:'Styled receipt with amount box, company footer',color:'#7c3aed',action:`quickPrintLastReceipt()`},
        {icon:'💼',title:'Salary Slip',desc:'Salary slip with earnings/deductions, net pay, signatures',color:'#d97706',action:`quickPrintSalarySlip()`},
        {icon:'📄',title:'Supplier Payment Voucher',desc:'Payment voucher for supplier payments with authorization',color:'#dc2626',action:`printSupplierPaymentVoucher()`},
        {icon:'📅',title:'Monthly Statement',desc:'Full month P&L with all transactions and summary',color:'#0891b2',action:`printMonthlyStatement('${thisMonth}')`},
        {icon:'📦',title:'Stock Report',desc:'Complete inventory with values, low stock alerts',color:'#d97706',action:`printStockReport()`},
        {icon:'📈',title:'P&L Statement',desc:'Profit & Loss with revenue, COGS, expenses breakdown',color:'#059669',action:`printProfitLossStatement('${thisYear}-01-01','${new Date().toISOString().split('T')[0]}')`},
        {icon:'💰',title:'Daily Sales Report',desc:'All sales transactions for today',color:'#16a34a',action:`printDailySales()`},
        {icon:'📦',title:'Daily Purchase Report',desc:'All purchases for today',color:'#2563eb',action:`printDailyPurch()`},
        {icon:'🏦',title:'Bank Statement',desc:'Bank account transaction history with running balance',color:'#7c3aed',action:`printBankStatement()`},
      ].map(t=>`
        <div style="background:${bg};border:1.5px solid ${border};border-radius:12px;padding:18px;transition:all .2s;"
          data-hover-style-bordercolor="${t.color}" data-hover-transform="translateY(-2px)">
          <div style="font-size:32px;margin-bottom:10px;">${t.icon}</div>
          <div style="font-size:14px;font-weight:800;color:${textColor};margin-bottom:6px;">${t.title}</div>
          <div style="font-size:11px;color:${text2};margin-bottom:14px;line-height:1.5;">${escHTML(t.desc)}</div>
          <button data-x-click="${t.action}" style="width:100%;padding:9px;background:${t.color};color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:12px;">
            🖨️ Print ${t.title}
          </button>
        </div>`).join('')}
    </div>

    <!-- Custom P&L Date Range -->
    <div style="background:${bg};border:1px solid ${border};border-radius:12px;padding:18px;margin-top:16px;">
      <div style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:14px;">📈 Custom P&L Statement</div>
      <div style="display:flex;gap:12px;align-items:flex-end;flex-wrap:wrap;">
        <div><label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">From Date</label>
          <!-- FIX (2026-08-28, structural audit): was id="pl-from", which
               collided with the always-present Partner Ledger page's own
               date field of the same id — getElementById would silently
               grab Partner Ledger's value here instead of this page's own,
               since that page's (hidden but present) copy comes first in
               the DOM. Renamed to plt-from/plt-to, unique to this page. -->
          <input type="date" id="plt-from" value="${thisYear}-01-01" style="padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};"></div>
        <div><label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">To Date</label>
          <input type="date" id="plt-to" value="${new Date().toISOString().split('T')[0]}" style="padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};"></div>
        <button data-x-click="printPLReportBtn()"
          style="padding:9px 20px;background:#059669;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:13px;">🖨️ Print P&L</button>
      </div>
    </div>

    <!-- Custom Monthly Statement -->
    <div style="background:${bg};border:1px solid ${border};border-radius:12px;padding:18px;margin-top:14px;">
      <div style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:14px;">📅 Monthly Statement</div>
      <div style="display:flex;gap:12px;align-items:flex-end;flex-wrap:wrap;">
        <div><label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">Select Month</label>
          <input type="month" id="stmt-month" value="${thisMonth}" style="padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};"></div>
        <button data-x-click="printMonthlyStatementBtn()"
          style="padding:9px 20px;background:#0891b2;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:13px;">🖨️ Print Statement</button>
      </div>
    </div>
  </div>`;
}


