function renderDataSync(){
  const el=document.getElementById('pg-datasync');
  if(!el) return;
  const isDark=document.documentElement.getAttribute('data-theme')==='dark';
  const bg=isDark?'#1e293b':'#fff';
  const border=isDark?'#334155':'#e5e7eb';
  const textColor=isDark?'#f1f5f9':'#1a202c';
  const text2=isDark?'#94a3b8':'#6b7280';
  const dbSize=(JSON.stringify(DB).length/1024).toFixed(1);
  const txCount=(DB.tx||[]).length;
  const custCount=(DB.customers||[]).length;

  el.innerHTML=`<div style="padding:20px;">
    <div style="margin-bottom:20px;">
      <h2 style="font-size:20px;font-weight:800;color:#0f3d26;margin:0;">🔄 Data Sync & Transfer</h2>
      <p style="font-size:12px;color:${text2};margin:4px 0 0;">Transfer data between devices, merge files, QR code sync</p>
    </div>

    <!-- Stats -->
    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:12px;margin-bottom:20px;">
      ${[
        {icon:'💾',label:'Database Size',val:dbSize+' KB',color:'#16a34a'},
        {icon:'📋',label:'Transactions',val:txCount,color:'#2563eb'},
        {icon:'👥',label:'Customers',val:custCount,color:'#7c3aed'},
        {icon:'🕐',label:'Last Backup',val:DB.lastBackup||'Never',color:'#d97706'},
      ].map(k=>`<div class="kpi-card" style="border-left:4px solid ${k.color};">
        <div style="font-size:20px;">${k.icon}</div>
        <div style="font-size:16px;font-weight:900;color:${k.color};margin-top:4px;">${k.val}</div>
        <div style="font-size:10px;color:${text2};font-weight:700;">${k.label}</div>
      </div>`).join('')}
    </div>

    <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;">

      <!-- Export -->
      <div style="background:${bg};border:1px solid ${border};border-radius:12px;padding:18px;">
        <div style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:14px;">📤 Export Data</div>
        <div style="display:flex;flex-direction:column;gap:10px;">
          <button data-x-click="exportFullBackupJSON()" style="width:100%;padding:11px;background:linear-gradient(135deg,#16a34a,#15803d);color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:13px;display:flex;align-items:center;justify-content:center;gap:8px;">
            📥 Full Backup (JSON) — All Data
          </button>
          <button data-x-click="exportTransactionsCSV()" style="width:100%;padding:11px;background:linear-gradient(135deg,#2563eb,#1d4ed8);color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:13px;display:flex;align-items:center;justify-content:center;gap:8px;">
            📊 Transactions Only (CSV)
          </button>
          <button data-x-click="exportAllCSV()" style="width:100%;padding:11px;background:linear-gradient(135deg,#7c3aed,#6d28d9);color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:13px;display:flex;align-items:center;justify-content:center;gap:8px;">
            📦 All Data (CSV Bundle)
          </button>
          <button data-x-click="exportPartialData()" style="width:100%;padding:11px;background:linear-gradient(135deg,#d97706,#b45309);color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:13px;display:flex;align-items:center;justify-content:center;gap:8px;">
            ✂️ Export Selected Data
          </button>
        </div>
      </div>

      <!-- Import -->
      <div style="background:${bg};border:1px solid ${border};border-radius:12px;padding:18px;">
        <div style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:14px;">📥 Import & Merge Data</div>
        <div style="border:2px dashed ${border};border-radius:10px;padding:20px;text-align:center;cursor:pointer;margin-bottom:12px;"
          data-x-click="document.getElementById('sync-file-input').click()"
