    <!-- QR Code Sync -->
    <div style="background:${bg};border:1px solid ${border};border-radius:12px;padding:18px;margin-top:16px;">
      <div style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:14px;">📱 QR Code Quick Transfer</div>
