        </div>
        <div>
          <div style="font-size:12px;color:${text2};margin-bottom:12px;">Transfer instructions:</div>
          <ol style="font-size:12px;color:${textColor};padding-left:16px;line-height:2;">
            <li>Click "Full Backup" on Device A</li>
            <li>Transfer the .json file to Device B</li>
            <li>On Device B, click "Restore from Backup"</li>
            <li>Or use "Merge" to combine data from both devices</li>
          </ol>
          <div style="margin-top:12px;padding:10px;background:#f0fdf4;border-radius:8px;font-size:11px;color:#16a34a;">
            <strong>💡 Tip:</strong> Use Google Drive to sync between devices automatically. Save backup to Drive, then restore on other device.
          </div>
        </div>
      </div>
    </div>

    <!-- Merge History -->
    <div style="background:${bg};border:1px solid ${border};border-radius:12px;padding:18px;margin-top:14px;">
      <div style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:12px;">📋 Sync History</div>
      ${(DB.syncLog||[]).length?`<table style="width:100%;border-collapse:collapse;font-size:12px;">
        <thead><tr style="background:#f9fafb;">
          <th style="padding:8px 12px;text-align:left;font-size:10px;font-weight:700;color:${text2};">DATE/TIME</th>
          <th style="padding:8px 12px;text-align:left;font-size:10px;font-weight:700;color:${text2};">ACTION</th>
          <th style="padding:8px 12px;text-align:right;font-size:10px;font-weight:700;color:${text2};">RECORDS</th>
        </tr></thead>
        <tbody>${(DB.syncLog||[]).slice(0,10).map(s=>`<tr style="border-bottom:1px solid ${border};">
          <td style="padding:8px 12px;color:${text2};">${s.ts}</td>
          <td style="padding:8px 12px;color:${textColor};">${s.action}</td>
          <td style="padding:8px 12px;text-align:right;color:#16a34a;font-weight:700;">${s.records}</td>
        </tr>`).join('')}</tbody>
      </table>`
      :`<div style="text-align:center;padding:20px;color:${text2};font-size:12px;">No sync history yet.</div>`}
    </div>
  </div>`;
}

function syncHandleDrop(e){
  const file=e.dataTransfer.files[0];
  if(file) syncProcessFile(file,'restore');
}

function syncHandleFile(inp){
  const file=inp.files[0];
  if(file) syncProcessFile(file,'restore');
}

function syncProcessFile(file, mode){
  const status=document.getElementById('sync-status');
  if(status) status.textContent='Reading file...';
  const reader=new FileReader();
  reader.onload=async e=>{
    try{
      const data=__ayanSafeJSONParse(e.target.result);
      if(!data.tx&&!data.customers&&!data.banks){
        if(status) status.textContent='❌ Invalid backup file';
        return;
      }
      if(mode==='restore'){
        if(!await __confirm('⚠️ This will REPLACE all current data. Are you sure?')) return;
        // Must write through the real save path (server), not the old dead
        // localStorage key — the app reloads its data from the server, so a
        // localStorage-only write here was silently discarded on reload,
        // making "restore" appear to succeed while doing nothing.
        window.DB = window.__ayanScrubProto(data);
        if(status) status.textContent='Saving restored data...';
        (typeof saveDBNow==='function' ? saveDBNow() : Promise.resolve()).then(()=>{
          if(status) status.textContent='✅ Data restored! Reloading...';
          setTimeout(()=>location.reload(),1000);
        });
      }
    }catch(err){
      if(status) status.textContent='❌ Error: '+err.message;
    }
  };
  reader.readAsText(file);
}

function mergeData(inp){
  const file=inp.files[0];
  if(!file) return;
  const status=document.getElementById('sync-status');
  if(status) status.textContent='Merging data...';
  const reader=new FileReader();
  reader.onload=e=>{
    try{
      const other=window.__ayanScrubProto(__ayanSafeJSONParse(e.target.result));
      if(!other.tx&&!other.customers){
        if(status) status.textContent='❌ Invalid backup file';
        return;
      }
      let merged=0;
      // Merge transactions (avoid duplicates by ID)
      const existingIds=new Set((DB.tx||[]).map(t=>t.id));
      (other.tx||[]).forEach(t=>{
        if(!existingIds.has(t.id)){
          (DB.tx=DB.tx||[]).push(t);
          merged++;
        }
      });
      // Merge customers (avoid duplicates by name)
      const existingCusts=new Set((DB.customers||[]).map(c=>c.name));
      (other.customers||[]).forEach(c=>{
        if(!existingCusts.has(c.name)){
          (DB.customers=DB.customers||[]).push(c);
          merged++;
        }
      });
      // Merge orders
      const existingOrders=new Set((DB.orders||[]).map(o=>o.id));
      (other.orders||[]).forEach(o=>{
        if(!existingOrders.has(o.id)){
          (DB.orders=DB.orders||[]).push(o);
          merged++;
        }
      });
      if(!DB.syncLog) DB.syncLog=[];
      DB.syncLog.unshift({ts:new Date().toLocaleString('en-GB'),action:'Merge from backup',records:merged+' new records'});
      saveDB();
      if(status) status.textContent='✅ Merged '+merged+' new records successfully!';
      toast('✅ Merged '+merged+' records from backup!','s');
      logAudit('SYNC','Data Sync','Merged '+merged+' records from backup file');
      setTimeout(()=>renderDataSync(),1000);
    }catch(err){
      if(status) status.textContent='❌ Merge error: '+err.message;
    }
  };
  reader.readAsText(file);
}

function exportPartialData(){
  const isDark=document.documentElement.getAttribute('data-theme')==='dark';
  const bg=isDark?'#1e293b':'#fff';
  const border=isDark?'#334155':'#e5e7eb';
  const textColor=isDark?'#f1f5f9':'#1a202c';
  const modal=document.createElement('div');
  modal.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:2000;display:flex;align-items:center;justify-content:center;';
  modal.innerHTML=`<div style="background:${bg};border-radius:14px;padding:24px;width:90%;max-width:400px;color:${textColor};">
    <div style="font-size:15px;font-weight:800;color:#0f3d26;margin-bottom:16px;">✂️ Export Selected Data</div>
    <div style="display:grid;gap:8px;margin-bottom:16px;">
      ${[['tx','Transactions'],['customers','Customers & Suppliers'],['partners','Partners'],['banks','Bank Accounts'],['products','Products'],['orders','Orders'],['employees','Employees'],['batches','Production Batches']].map(([key,label])=>`
        <label style="display:flex;align-items:center;gap:8px;cursor:pointer;padding:8px;background:#f9fafb;border-radius:6px;">
          <input type="checkbox" id="exp-${key}" checked style="width:16px;height:16px;">
          <span style="font-size:13px;font-weight:600;">${label} (${(DB[key]||[]).length})</span>
        </label>`).join('')}
    </div>
    <div style="display:flex;gap:10px;justify-content:flex-end;">
      <button data-x-click="this.closest('div[style]').remove()" style="padding:9px 18px;background:#f3f4f6;color:#374151;border:none;border-radius:8px;font-weight:700;cursor:pointer;">Cancel</button>
      <button data-x-click="doPartialExport(this)" style="padding:9px 18px;background:#16a34a;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;">📥 Export</button>
    </div>
  </div>`;
  document.body.appendChild(modal);
}

function doPartialExport(btn){
  const keys=['tx','customers','partners','banks','products','orders','employees','batches'];
  const partial={settings:DB.settings,nid:DB.nid};
  keys.forEach(k=>{
    const cb=document.getElementById('exp-'+k);
    if(cb?.checked) partial[k]=DB[k]||[];
  });
  partial.exportedAt=new Date().toISOString();
  partial.exportedBy=currentUser?.name||'User';
  const blob=new Blob([JSON.stringify(partial,null,2)],{type:'application/json'});
  const a=document.createElement('a');
  a.href=URL.createObjectURL(blob);
  a.download='RBO_Partial_'+new Date().toISOString().split('T')[0]+'.json';
  a.click();
  btn.closest('div[style]').remove();
  toast('Partial export downloaded!', 's');
  logAudit('EXPORT','Data Sync','Partial data export');
}

function generateSyncQR(){
  const disp=document.getElementById('qr-display');
  if(!disp) return;
  const co=DB.settings||{};
  const txCount=(DB.tx||[]).length;
  const custCount=(DB.customers||[]).length;
  const bankBal=(DB.banks||[]).reduce((s,b)=>s+(b.bal||0),0);
  const summary={
    company:co.companyName||'RBO ERP',
    transactions:txCount,
    customers:custCount,
    bankBalance:bankBal,
    exportedAt:new Date().toISOString(),
    version:'v29'
  };
  const data=JSON.stringify(summary);
  // Use QR code API
  const qrUrl='https://api.qrserver.com/v1/create-qr-code/?size=200x200&data='+encodeURIComponent(data);
  disp.innerHTML=`
    <img src="${qrUrl}" alt="QR Code" style="border-radius:8px;border:2px solid #0f3d26;" onerror="this.parentNode.innerHTML='<div style=\\'padding:20px;color:#9ca3af;font-size:12px;\\'>QR generation requires internet connection</div>'">
    <div style="font-size:10px;color:#6b7280;margin-top:6px;">Scan to view data summary</div>`;
}


// ═══════════════════════════════════════════════════════════════
// MOBILE APP EXPERIENCE
// Bottom nav, swipe gestures, touch optimization, FAB
// ═══════════════════════════════════════════════════════════════

function initMobileExperience(){
  if(window.innerWidth>768) return; // Desktop only needs minimal setup

  // Update bottom nav badge
  updateBottomNavBadges();

  // Pull-to-refresh
  initPullToRefresh();

  // Swipe navigation
  initSwipeNavigation();

  // Touch ripple on buttons
  initTouchRipple();

  // Prevent double-tap zoom on buttons
  document.querySelectorAll('button,.btn').forEach(btn=>{
    btn.addEventListener('touchend',e=>e.preventDefault());
  });

  console.info('✅ Mobile experience initialized');
}

function bnNav(page){
  // Update active state
  document.querySelectorAll('.bn-item').forEach(b=>b.classList.remove('active'));
  const btn=document.getElementById('bn-'+page);
  if(btn) btn.classList.add('active');
  nav(page);
  // Close FAB if open
  closeFAB();
}

function updateBottomNavBadges(){
  // Orders badge
  const pendingOrders=(DB.orders||[]).filter(o=>o.deliveryStatus==='Pending').length;
  const badge=document.getElementById('bn-orders-badge');
  if(badge){
    badge.textContent=pendingOrders>0?pendingOrders:'';
    badge.style.display=pendingOrders>0?'flex':'none';
  }
}

let _fabOpen=false;
function toggleFAB(){
  _fabOpen=!_fabOpen;
  const fab=document.getElementById('fab');
  const menu=document.getElementById('fab-menu');
  if(fab) fab.textContent=_fabOpen?'✕':'➕';
  if(menu) menu.style.display=_fabOpen?'flex':'none';
}
function closeFAB(){
  _fabOpen=false;
  const fab=document.getElementById('fab');
  const menu=document.getElementById('fab-menu');
  if(fab) fab.textContent='➕';
  if(menu) menu.style.display='none';
}

// Close FAB when clicking outside
document.addEventListener('click',e=>{
  if(_fabOpen&&!e.target.closest('#fab')&&!e.target.closest('#fab-menu')){
    closeFAB();
  }
});

function initPullToRefresh(){
  let startY=0;
  let pulling=false;
  const indicator=document.getElementById('ptr-indicator');

  document.addEventListener('touchstart',e=>{
    if(window.scrollY===0) startY=e.touches[0].clientY;
  },{passive:true});

  document.addEventListener('touchmove',e=>{
    if(!startY) return;
    const dy=e.touches[0].clientY-startY;
    if(dy>60&&window.scrollY===0){
      pulling=true;
      if(indicator) indicator.style.display='block';
    }
  },{passive:true});

  document.addEventListener('touchend',()=>{
    if(pulling){
      pulling=false;
      startY=0;
      // Refresh current page
      const activePage=document.querySelector('.page.active');
      if(activePage){
        const pageId=activePage.id?.replace('pg-','');
        if(pageId){
          try{render(pageId);}catch(e){}
        }
      }
      setTimeout(()=>{if(indicator) indicator.style.display='none';},1000);
    }
    startY=0;
  });
}

function initSwipeNavigation(){
  const pages=['dashboard','transactions','orders','calendar','menuhub'];
  let touchStartX=0;
  let touchStartY=0;

  document.addEventListener('touchstart',e=>{
    touchStartX=e.touches[0].clientX;
    touchStartY=e.touches[0].clientY;
  },{passive:true});

  document.addEventListener('touchend',e=>{
    const dx=e.changedTouches[0].clientX-touchStartX;
    const dy=e.changedTouches[0].clientY-touchStartY;
    // Only horizontal swipes (dx > 80, dy < 50)
    if(Math.abs(dx)>80&&Math.abs(dy)<50){
      const activePage=document.querySelector('.page.active');
      const pageId=activePage?.id?.replace('pg-','');
      const idx=pages.indexOf(pageId);
      if(dx<0&&idx<pages.length-1){
        // Swipe left → next page
        bnNav(pages[idx+1]);
      } else if(dx>0&&idx>0){
        // Swipe right → previous page
        bnNav(pages[idx-1]);
      }
    }
  });
}

function initTouchRipple(){
  document.querySelectorAll('.btn,.kpi-card,.nav-item').forEach(el=>{
    el.classList.add('touch-ripple');
    el.addEventListener('touchstart',e=>{
      const rect=el.getBoundingClientRect();
      const x=e.touches[0].clientX-rect.left;
      const y=e.touches[0].clientY-rect.top;
      el.style.setProperty('--ripple-x',x+'px');
      el.style.setProperty('--ripple-y',y+'px');
    },{passive:true});
  });
}

function renderMobileDashboard(){
  // Enhanced mobile dashboard with large touch targets
  const el=document.getElementById('pg-mobiledash');
  if(!el) return;
  const isDark=document.documentElement.getAttribute('data-theme')==='dark';
  const bg=isDark?'#1e293b':'#fff';
  const border=isDark?'#334155':'#e5e7eb';
  const textColor=isDark?'#f1f5f9':'#1a202c';
  const text2=isDark?'#94a3b8':'#6b7280';
  const user=currentUser||{name:'User',role:'Staff'};
  const banks=DB.banks||[];
  const totalBankBal=banks.reduce((s,b)=>s+(b.bal||0),0);
  const today=new Date().toISOString().split('T')[0];
  const txs=DB.tx||[];
  const todaySales=txs.filter(t=>t.date===today&&isRevenueTx(t)).reduce((s,t)=>s+txAmt(t),0);
  const pendingOrders=(DB.orders||[]).filter(o=>o.deliveryStatus==='Pending').length;
  const goals=DB.goals||{};
  const thisMonth=new Date().toISOString().substring(0,7);
  const monthSales=txs.filter(t=>t.date&&t.date.startsWith(thisMonth)&&isRevenueTx(t)).reduce((s,t)=>s+txAmt(t),0);
  const salesTarget=goals.monthlySalesTarget||0;
  const salesPct=salesTarget>0?Math.min(100,Math.round(monthSales/salesTarget*100)):0;

  el.innerHTML=`<div style="padding:12px;padding-bottom:80px;">
    <!-- Welcome -->
    <div style="background:linear-gradient(135deg,#0f3d26,#16a34a);color:#fff;border-radius:14px;padding:16px;margin-bottom:14px;">
      <div style="font-size:12px;opacity:.7;">Welcome back</div>
      <div style="font-size:20px;font-weight:900;">${escHTML(user.name)}</div>
      <div style="font-size:24px;font-weight:900;margin-top:8px;">৳${totalBankBal.toLocaleString('en-IN',{minimumFractionDigits:0})}</div>
      <div style="font-size:11px;opacity:.7;">Total Bank Balance</div>
    </div>

    <!-- Today's Quick Stats -->
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:14px;">
      ${[
        {icon:'💰',label:"Today's Sales",val:'৳'+todaySales.toLocaleString('en-IN',{minimumFractionDigits:0}),color:'#16a34a'},
        {icon:'⏳',label:'Pending Orders',val:pendingOrders,color:'#d97706'},
      ].map(k=>`<div style="background:${bg};border:1px solid ${border};border-radius:12px;padding:14px;">
        <div style="font-size:22px;">${k.icon}</div>
        <div style="font-size:20px;font-weight:900;color:${k.color};margin-top:4px;">${k.val}</div>
        <div style="font-size:10px;color:${text2};font-weight:700;">${k.label}</div>
      </div>`).join('')}
    </div>

    <!-- Monthly Goal Progress -->
    ${salesTarget>0?`<div style="background:${bg};border:1px solid ${border};border-radius:12px;padding:14px;margin-bottom:14px;">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">
        <div style="font-size:13px;font-weight:800;color:${textColor};">🎯 Monthly Sales Goal</div>
        <div style="font-size:12px;font-weight:700;color:${salesPct>=100?'#16a34a':'#d97706'};">${salesPct}%</div>
      </div>
      <div style="background:#e5e7eb;border-radius:6px;height:10px;overflow:hidden;margin-bottom:6px;">
        <div style="width:${salesPct}%;height:100%;background:${salesPct>=100?'#16a34a':salesPct>=70?'#d97706':'#2563eb'};border-radius:6px;transition:width .5s ease;"></div>
      </div>
      <div style="display:flex;justify-content:space-between;font-size:11px;color:${text2};">
        <span>৳${monthSales.toLocaleString('en-IN',{minimumFractionDigits:0})} achieved</span>
        <span>Target: ৳${salesTarget.toLocaleString('en-IN',{minimumFractionDigits:0})}</span>
      </div>
    </div>`:''}

    <!-- Quick Actions (Large Touch Targets) -->
    <div style="font-size:13px;font-weight:800;color:${textColor};margin-bottom:10px;">⚡ Quick Actions</div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:14px;">
      ${[
        {icon:'📋',label:'New Order',color:'#16a34a',action:"openOrderModal()"},
        {icon:'📱',label:'bKash Receive',color:'#be185d',action:"openStaffBkash()"},
        {icon:'💸',label:'Log Expense',color:'#dc2626',action:"openStaffExpense()"},
        {icon:'📊',label:'Today Report',color:'#2563eb',action:"nav('dailysummary')"},
        {icon:'💰',label:'New Transaction',color:'#7c3aed',action:"openModal('mTx')"},
        {icon:'🗓️',label:'Calendar',color:'#0891b2',action:"nav('calendar')"},
      ].map(a=>`<button data-x-click="${a.action}" style="padding:16px 12px;background:${a.color}11;border:1.5px solid ${a.color}33;border-radius:12px;cursor:pointer;text-align:center;font-family:inherit;transition:all .2s;" data-hover-bg="${a.color}22">
        <div style="font-size:28px;margin-bottom:6px;">${a.icon}</div>
        <div style="font-size:12px;font-weight:700;color:${textColor};">${a.label}</div>
      </button>`).join('')}
    </div>

    <!-- Recent Transactions -->
    <div style="font-size:13px;font-weight:800;color:${textColor};margin-bottom:10px;">📊 Recent Transactions</div>
    <div style="background:${bg};border:1px solid ${border};border-radius:12px;overflow:hidden;">
      ${txs.slice(-5).reverse().map(t=>{
        const isIn=['Sale','Warehouse Sale','Sales Receipt','Cash Received'].includes(t.type);
        return `<div style="display:flex;align-items:center;gap:12px;padding:12px 14px;border-bottom:1px solid ${border};">
          <div style="width:36px;height:36px;border-radius:50%;background:${isIn?'#dcfce7':'#fee2e2'};display:flex;align-items:center;justify-content:center;font-size:16px;flex-shrink:0;">${isIn?'📥':'📤'}</div>
          <div style="flex:1;min-width:0;">
            <div style="font-size:13px;font-weight:700;color:${textColor};white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${escHTML(t.party||t.type)}</div>
            <div style="font-size:10px;color:${text2};">${t.type} • ${t.date}</div>
          </div>
          <div style="font-size:14px;font-weight:900;color:${isIn?'#16a34a':'#dc2626'};flex-shrink:0;">${isIn?'+':'-'}৳${txAmt(t).toLocaleString('en-IN',{minimumFractionDigits:0})}</div>
        </div>`;
      }).join('')||`<div style="text-align:center;padding:20px;color:${text2};font-size:12px;">No transactions yet.</div>`}
    </div>
  </div>`;
}


// ═══════════════════════════════════════════════════════════════
// BUSINESS GOALS & KPIs
// Monthly targets, profit goals, collection targets, progress
// ═══════════════════════════════════════════════════════════════

function renderGoals(){
  const el=document.getElementById('pg-goals');
  if(!el) return;
  const isDark=document.documentElement.getAttribute('data-theme')==='dark';
  const bg=isDark?'#1e293b':'#fff';
  const border=isDark?'#334155':'#e5e7eb';
  const textColor=isDark?'#f1f5f9':'#1a202c';
  const text2=isDark?'#94a3b8':'#6b7280';
  const goals=DB.goals||{};
  const txs=DB.tx||[];
  const now=new Date();
  const thisMonth=now.toISOString().substring(0,7);
  const today=now.toISOString().split('T')[0];
  const daysInMonth=new Date(now.getFullYear(),now.getMonth()+1,0).getDate();
  const dayOfMonth=now.getDate();
  const monthProgress=Math.round(dayOfMonth/daysInMonth*100);

  // ── Calculate actuals ──
  const SALE_T=['Sale','Sales','Sales Invoice','Customer Sale','Warehouse Sale','Other Income','Interest Income']; // canonical: money receipts/advances are NOT revenue or cost
  const PURCH_T=['Purchase','Warehouse Purchase','Supplier Purchase']; // canonical: money receipts/advances are NOT revenue or cost
  const EXP_T=['Salary Payment','Office Rent','Electricity Bill','Internet Bill','Fuel Expense','Transport Cost','Other Expense'];

  const monthSales=txs.filter(t=>t.date&&t.date.startsWith(thisMonth)&&SALE_T.includes(t.type)).reduce((s,t)=>s+txAmt(t),0);
  const monthPurch=txs.filter(t=>t.date&&t.date.startsWith(thisMonth)&&PURCH_T.includes(t.type)).reduce((s,t)=>s+txAmt(t),0);
  const monthExp=txs.filter(t=>t.date&&t.date.startsWith(thisMonth)&&EXP_T.includes(t.type)).reduce((s,t)=>s+txAmt(t),0);
  const monthCOGS=window.computeCOGS(txs.filter(t=>t.date&&t.date.startsWith(thisMonth)));
  const monthProfit=monthSales-monthCOGS-monthExp;
  const customers=(DB.customers||[]).filter(c=>isCustomerParty(c));
  const totalRecv=customers.reduce((s,c)=>s+(c.bal||0),0);
  const collectedThisMonth=txs.filter(t=>t.date&&t.date.startsWith(thisMonth)&&['Sales Receipt','Cash Received'].includes(t.type)).reduce((s,t)=>s+txAmt(t),0);
  const ordersDelivered=(DB.orders||[]).filter(o=>o.deliveryDate&&o.deliveryDate.startsWith(thisMonth)&&o.deliveryStatus==='Delivered').length;
  const totalOrders=(DB.orders||[]).filter(o=>o.orderDate&&o.orderDate.startsWith(thisMonth)).length;

  // ── Goal progress helper ──
  function goalCard(icon, title, actual, target, unit, color, desc, extraInfo){
    const pct=target>0?Math.min(100,Math.round(actual/target*100)):0;
    const remaining=Math.max(0,target-actual);
    const onTrack=target>0&&(actual/target)>=(monthProgress/100*0.9);
    const statusColor=pct>=100?'#16a34a':onTrack?'#2563eb':'#dc2626';
    const statusLabel=pct>=100?'🎉 Achieved!':onTrack?'✅ On Track':'⚠️ Behind';
    return `<div style="background:${bg};border:1.5px solid ${pct>=100?'#16a34a':border};border-radius:14px;padding:18px;position:relative;overflow:hidden;">
      ${pct>=100?`<div style="position:absolute;top:0;right:0;background:#16a34a;color:#fff;padding:4px 12px;border-radius:0 14px 0 10px;font-size:10px;font-weight:800;">ACHIEVED ✓</div>`:''}
      <div style="display:flex;align-items:flex-start;gap:12px;margin-bottom:14px;">
        <div style="font-size:28px;">${icon}</div>
        <div style="flex:1;">
          <div style="font-size:14px;font-weight:800;color:${textColor};">${title}</div>
          <div style="font-size:11px;color:${text2};margin-top:2px;">${desc}</div>
        </div>
        <div style="text-align:right;">
          <div style="font-size:11px;font-weight:700;color:${statusColor};">${statusLabel}</div>
          <div style="font-size:10px;color:${text2};">${monthProgress}% of month done</div>
        </div>
      </div>
      <div style="margin-bottom:10px;">
        <div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:6px;">
          <span style="font-weight:700;color:${textColor};">${unit}${actual.toLocaleString('en-IN',{minimumFractionDigits:0})} achieved</span>
          <span style="color:${text2};">Target: ${unit}${target.toLocaleString('en-IN',{minimumFractionDigits:0})}</span>
        </div>
        <div style="background:#e5e7eb;border-radius:8px;height:12px;overflow:hidden;">
          <div style="width:${pct}%;height:100%;background:${pct>=100?'#16a34a':pct>=70?color:'#dc2626'};border-radius:8px;transition:width .8s ease;position:relative;">
            ${pct>15?`<span style="position:absolute;right:6px;top:50%;transform:translateY(-50%);font-size:8px;font-weight:800;color:#fff;">${pct}%</span>`:''}
          </div>
        </div>
        <div style="display:flex;justify-content:space-between;font-size:10px;color:${text2};margin-top:4px;">
          <span>${pct}% complete</span>
          <span>${remaining>0?unit+remaining.toLocaleString('en-IN',{minimumFractionDigits:0})+' remaining':'✅ Goal met!'}</span>
        </div>
      </div>
      ${extraInfo?`<div style="background:${color}11;border-radius:8px;padding:8px 12px;font-size:11px;color:${textColor};">${extraInfo}</div>`:''}
    </div>`;
  }

  el.innerHTML=`<div style="padding:20px;">
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:20px;flex-wrap:wrap;gap:10px;">
      <div>
        <h2 style="font-size:20px;font-weight:800;color:#0f3d26;margin:0;">🎯 Business Goals & KPIs</h2>
        <p style="font-size:12px;color:${text2};margin:4px 0 0;">${thisMonth} — Day ${dayOfMonth} of ${daysInMonth} (${monthProgress}% of month)</p>
      </div>
      <button data-x-click="openGoalsSettings()" style="padding:9px 18px;background:#16a34a;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:13px;">⚙️ Set Targets</button>
    </div>

    <!-- Month Progress Bar -->
    <div style="background:${bg};border:1px solid ${border};border-radius:12px;padding:14px;margin-bottom:20px;">
      <div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:6px;">
        <span style="font-weight:700;color:${textColor};">📅 Month Progress</span>
        <span style="color:${text2};">${dayOfMonth} / ${daysInMonth} days</span>
      </div>
      <div style="background:#e5e7eb;border-radius:6px;height:8px;overflow:hidden;">
        <div style="width:${monthProgress}%;height:100%;background:linear-gradient(90deg,#16a34a,#4ade80);border-radius:6px;"></div>
      </div>
    </div>

    <!-- Goals Grid -->
    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:16px;margin-bottom:20px;">
      ${goalCard('💰','Monthly Sales Target',monthSales,goals.monthlySalesTarget||0,'৳','#16a34a',
        'Total sales revenue for '+thisMonth,
        goals.monthlySalesTarget>0?`Daily target: ৳${Math.round(goals.monthlySalesTarget/daysInMonth).toLocaleString('en-IN')} | Today's sales: ৳${txs.filter(t=>t.date===today&&SALE_T.includes(t.type)).reduce((s,t)=>s+txAmt(t),0).toLocaleString('en-IN')}`:'Set a target to track progress')}

      ${goalCard('📈','Monthly Profit Goal',monthProfit,goals.monthlyProfitTarget||0,'৳','#059669',
        'Net profit after purchases and expenses',
        goals.monthlyProfitTarget>0?`Gross profit: ৳${(monthSales-monthCOGS).toLocaleString('en-IN')} | Expenses: ৳${monthExp.toLocaleString('en-IN')}`:'Set a profit target to track')}

      ${goalCard('💳','Collection Target',collectedThisMonth,goals.collectionTarget||0,'৳','#2563eb',
        'Cash collected from customers this month',
        `Outstanding receivables: ৳${totalRecv.toLocaleString('en-IN')} | ${customers.filter(c=>c.bal>0).length} customers with dues`)}

      ${goalCard('📦','Purchase Budget',monthPurch,goals.purchaseBudget||0,'৳','#d97706',
        'Keep purchases within budget',
        goals.purchaseBudget>0?`${monthPurch>goals.purchaseBudget?'⚠️ Over budget by ৳'+(monthPurch-goals.purchaseBudget).toLocaleString('en-IN'):'✅ Within budget'}`:'')}

      ${goalCard('🚛','Order Delivery Target',ordersDelivered,goals.deliveryTarget||0,'','#7c3aed',
        'Orders delivered this month',
        `Total orders this month: ${totalOrders} | Delivery rate: ${totalOrders>0?Math.round(ordersDelivered/totalOrders*100):0}%`)}

      ${goalCard('👥','New Customers',customers.filter(c=>c.createdAt&&c.createdAt.startsWith(thisMonth)).length,goals.newCustomerTarget||0,'','#0891b2',
        'New customers acquired this month',
        `Total customers: ${customers.length}`)}
    </div>

    <!-- Performance Summary -->
    <div style="background:${bg};border:1px solid ${border};border-radius:14px;padding:18px;margin-bottom:16px;">
      <div style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:14px;">📊 This Month's Performance Summary</div>
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:12px;">
        ${[
          {label:'Sales Revenue',val:'৳'+monthSales.toLocaleString('en-IN',{minimumFractionDigits:0}),icon:'💰',color:'#16a34a'},
          {label:'Total Purchases',val:'৳'+monthPurch.toLocaleString('en-IN',{minimumFractionDigits:0}),icon:'📦',color:'#2563eb'},
          {label:'Total Expenses',val:'৳'+monthExp.toLocaleString('en-IN',{minimumFractionDigits:0}),icon:'💸',color:'#dc2626'},
          {label:'Net Profit',val:'৳'+monthProfit.toLocaleString('en-IN',{minimumFractionDigits:0}),icon:'📈',color:monthProfit>=0?'#059669':'#dc2626'},
          {label:'Cash Collected',val:'৳'+collectedThisMonth.toLocaleString('en-IN',{minimumFractionDigits:0}),icon:'💳',color:'#7c3aed'},
          {label:'Orders Delivered',val:ordersDelivered+' / '+totalOrders,icon:'🚛',color:'#d97706'},
        ].map(k=>`<div style="padding:12px;background:${k.color}11;border-radius:10px;border:1px solid ${k.color}33;">
          <div style="font-size:18px;">${k.icon}</div>
          <div style="font-size:16px;font-weight:900;color:${k.color};margin-top:4px;">${k.val}</div>
          <div style="font-size:10px;color:${text2};font-weight:700;">${k.label}</div>
        </div>`).join('')}
      </div>
    </div>

    <!-- Historical Goals -->
    <div style="background:${bg};border:1px solid ${border};border-radius:14px;padding:18px;">
      <div style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:14px;">📅 Goal History</div>
      ${(DB.goalHistory||[]).length?`<table style="width:100%;border-collapse:collapse;font-size:12px;">
        <thead><tr style="background:#0f3d26;color:#fff;">
          <th style="padding:8px 12px;text-align:left;">Month</th>
          <th style="padding:8px 12px;text-align:right;">Sales Target</th>
          <th style="padding:8px 12px;text-align:right;">Actual Sales</th>
          <th style="padding:8px 12px;text-align:right;">Achievement</th>
        </tr></thead>
        <tbody>${(DB.goalHistory||[]).slice(0,6).map((h,i)=>`<tr style="border-bottom:1px solid ${border};background:${i%2===0?'transparent':(isDark?'#162032':'#f9fafb')};">
          <td style="padding:8px 12px;font-weight:700;color:${textColor};">${h.month}</td>
          <td style="padding:8px 12px;text-align:right;color:${text2};">৳${(h.salesTarget||0).toLocaleString('en-IN',{minimumFractionDigits:0})}</td>
          <td style="padding:8px 12px;text-align:right;color:#16a34a;font-weight:700;">৳${(h.actualSales||0).toLocaleString('en-IN',{minimumFractionDigits:0})}</td>
          <td style="padding:8px 12px;text-align:right;">
            <span style="padding:2px 8px;border-radius:6px;font-size:10px;font-weight:700;background:${h.salesTarget>0&&h.actualSales>=h.salesTarget?'#dcfce7':'#fee2e2'};color:${h.salesTarget>0&&h.actualSales>=h.salesTarget?'#16a34a':'#dc2626'};">
              ${h.salesTarget>0?Math.round(h.actualSales/h.salesTarget*100)+'%':'—'}
            </span>
          </td>
        </tr>`).join('')}</tbody>
      </table>`
      :`<div style="text-align:center;padding:20px;color:${text2};font-size:12px;">No goal history yet. Goals are saved at month end.</div>`}
    </div>
  </div>

  <!-- Goals Settings Modal -->
  <div id="goals-modal" style="display:none;position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:2000;align-items:center;justify-content:center;overflow-y:auto;">
    <div style="background:${bg};border-radius:16px;padding:0;width:95%;max-width:560px;margin:20px auto;color:${textColor};box-shadow:0 8px 40px rgba(0,0,0,.3);">
      <div style="background:linear-gradient(135deg,#0f3d26,#16a34a);color:#fff;padding:16px 20px;border-radius:16px 16px 0 0;display:flex;justify-content:space-between;align-items:center;">
        <div style="font-size:15px;font-weight:800;">⚙️ Set Monthly Targets</div>
        <button data-x-click="closeModalById('goals-modal')" style="background:none;border:none;color:#fff;font-size:20px;cursor:pointer;">✕</button>
      </div>
      <div style="padding:20px;display:grid;gap:14px;">
        <div style="background:#f0fdf4;border-radius:8px;padding:10px 14px;font-size:12px;color:#16a34a;font-weight:700;">
          📅 Setting targets for: ${thisMonth}
        </div>
        ${[
          ['monthlySalesTarget','💰 Monthly Sales Target (৳)','e.g. 1000000','Target total sales revenue for the month'],
          ['monthlyProfitTarget','📈 Monthly Profit Goal (৳)','e.g. 200000','Target net profit after all costs'],
          ['collectionTarget','💳 Collection Target (৳)','e.g. 500000','Target cash to collect from customers'],
          ['purchaseBudget','📦 Purchase Budget (৳)','e.g. 600000','Maximum budget for purchases'],
          ['deliveryTarget','🚛 Delivery Target (orders)','e.g. 50','Number of orders to deliver'],
          ['newCustomerTarget','👥 New Customer Target','e.g. 5','Number of new customers to acquire'],
        ].map(([key,label,placeholder,desc])=>`
          <div>
            <label style="font-size:12px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">${label}</label>
            <input type="number" id="goal-${key}" value="${goals[key]||''}" placeholder="${placeholder}"
              style="width:100%;padding:10px 12px;border:1.5px solid ${border};border-radius:8px;font-size:14px;background:${bg};color:${textColor};">
            <div style="font-size:10px;color:${text2};margin-top:3px;">${desc}</div>
          </div>`).join('')}
      </div>
      <div style="padding:14px 20px;border-top:1px solid ${border};display:flex;gap:10px;justify-content:flex-end;">
        <button data-x-click="closeModalById('goals-modal')" style="padding:10px 18px;background:#f3f4f6;color:#374151;border:none;border-radius:8px;font-weight:700;cursor:pointer;">Cancel</button>
        <button data-x-click="saveGoals()" style="padding:10px 24px;background:#16a34a;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:14px;">💾 Save Targets</button>
      </div>
    </div>
  </div>`;
}

function openGoalsSettings(){
  const goals=DB.goals||{};
  ['monthlySalesTarget','monthlyProfitTarget','collectionTarget','purchaseBudget','deliveryTarget','newCustomerTarget'].forEach(key=>{
    const el=document.getElementById('goal-'+key);
    if(el) el.value=goals[key]||'';
  });
  document.getElementById('goals-modal').style.display='flex';
}

function saveGoals(){
  if(!DB.goals) DB.goals={};
  const keys=['monthlySalesTarget','monthlyProfitTarget','collectionTarget','purchaseBudget','deliveryTarget','newCustomerTarget'];
  keys.forEach(key=>{
    const val=parseFloat(document.getElementById('goal-'+key)?.value)||0;
    DB.goals[key]=val;
  });
  DB.goals.setMonth=new Date().toISOString().substring(0,7);
  DB.goals.setAt=new Date().toISOString();
  saveDB();
  document.getElementById('goals-modal').style.display='none';
  toast('✅ Goals saved for '+DB.goals.setMonth,'s');
  logAudit('GOALS','Business Goals','Monthly targets updated');
  renderGoals();
  _scheduleAutoSave();
}

function saveMonthEndGoals(){
  // Called at month end to save history
  const thisMonth=new Date().toISOString().substring(0,7);
  const txs=DB.tx||[];
  const SALE_T=['Sale','Sales','Sales Invoice','Customer Sale','Warehouse Sale','Other Income','Interest Income']; // canonical: money receipts/advances are NOT revenue or cost
  const actualSales=txs.filter(t=>t.date&&t.date.startsWith(thisMonth)&&SALE_T.includes(t.type)).reduce((s,t)=>s+txAmt(t),0);
  if(!DB.goalHistory) DB.goalHistory=[];
  // Remove existing entry for this month
  DB.goalHistory=(DB.goalHistory||[]).filter(h=>h.month!==thisMonth);
  DB.goalHistory.unshift({
    month:thisMonth,
    salesTarget:DB.goals?.monthlySalesTarget||0,
    actualSales,
    savedAt:new Date().toISOString()
  });
  if(DB.goalHistory.length>24) DB.goalHistory.pop();
  saveDB();
}


// ═══════════════════════════════════════════════════════════════
// 🔍 COMPLETE BUSINESS AUDITOR
// A to Z business health check with guidelines & action items
// Covers: Finance, Operations, Inventory, HR, Compliance, Growth
// ═══════════════════════════════════════════════════════════════

function renderBusinessAuditor(){
  const el=document.getElementById('pg-auditor');
  if(!el) return;
  const isDark=document.documentElement.getAttribute('data-theme')==='dark';
  const bg=isDark?'#1e293b':'#fff';
  const border=isDark?'#334155':'#e5e7eb';
  const textColor=isDark?'#f1f5f9':'#1a202c';
  const text2=isDark?'#94a3b8':'#6b7280';
  const now=new Date();
  const today=now.toISOString().split('T')[0];
  const thisMonth=now.toISOString().substring(0,7);
  const co=DB.settings||{};

  // ── Run complete audit ──
  const audit=runCompleteAudit();
  const score=audit.score;
  const scoreColor=score>=80?'#16a34a':score>=60?'#d97706':score>=40?'#ea580c':'#dc2626';
  const scoreLabel=score>=80?'Excellent 🌟':score>=60?'Good 👍':score>=40?'Fair ⚠️':'Needs Attention 🚨';

  el.innerHTML=`<div style="padding:20px;">

    <!-- Header -->
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:20px;flex-wrap:wrap;gap:12px;">
      <div>
        <h2 style="font-size:22px;font-weight:900;color:#0f3d26;margin:0;">🔍 Complete Business Auditor</h2>
        <p style="font-size:12px;color:${text2};margin:4px 0 0;">A to Z business health check — ${now.toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</p>
      </div>
      <div style="display:flex;gap:8px;">
        <button data-x-click="renderBusinessAuditor()" style="padding:9px 18px;background:#16a34a;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:13px;">🔄 Re-Audit</button>
        <button data-x-click="printAuditReport()" style="padding:9px 16px;background:#7c3aed;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:12px;">🖨️ Print Report</button>
      </div>
    </div>

    <!-- Overall Score -->
    <div style="background:linear-gradient(135deg,#0f3d26,#16a34a);color:#fff;border-radius:16px;padding:24px;margin-bottom:20px;display:flex;align-items:center;gap:24px;flex-wrap:wrap;">
      <div style="text-align:center;min-width:140px;">
        <div style="font-size:64px;font-weight:900;line-height:1;">${score}</div>
        <div style="font-size:14px;opacity:.8;">/100</div>
        <div style="font-size:14px;font-weight:700;margin-top:6px;">${scoreLabel}</div>
        <div style="background:rgba(255,255,255,.2);border-radius:8px;height:8px;margin-top:10px;overflow:hidden;">
          <div style="width:${score}%;height:100%;background:#4ade80;border-radius:8px;"></div>
        </div>
      </div>
      <div style="flex:1;min-width:200px;">
        <div style="font-size:18px;font-weight:800;margin-bottom:8px;">Business Audit Report</div>
        <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:12px;">
          ${[
            {label:'✅ Passed',val:audit.passed,color:'#4ade80'},
            {label:'⚠️ Warnings',val:audit.warnings,color:'#fbbf24'},
            {label:'❌ Critical',val:audit.critical,color:'#f87171'},
          ].map(k=>`<div style="background:rgba(255,255,255,.15);border-radius:8px;padding:10px;text-align:center;">
            <div style="font-size:20px;font-weight:900;color:${k.color};">${k.val}</div>
            <div style="font-size:10px;opacity:.8;">${k.label}</div>
          </div>`).join('')}
        </div>
        <div style="font-size:12px;opacity:.75;">
          ${audit.topIssue?'🚨 Top Issue: '+audit.topIssue:'✅ No critical issues found!'}
        </div>
      </div>
      <div style="display:flex;flex-direction:column;gap:8px;">
        <div style="font-size:11px;opacity:.7;text-align:center;">Category Scores</div>
        ${audit.categories.map(c=>`
          <div style="display:flex;align-items:center;gap:8px;min-width:180px;">
            <span style="font-size:12px;opacity:.8;width:80px;">${escHTML(c.name)}</span>
            <div style="flex:1;background:rgba(255,255,255,.2);border-radius:4px;height:6px;overflow:hidden;">
              <div style="width:${c.score}%;height:100%;background:${c.score>=80?'#4ade80':c.score>=60?'#fbbf24':'#f87171'};border-radius:4px;"></div>
            </div>
            <span style="font-size:11px;font-weight:700;color:${c.score>=80?'#4ade80':c.score>=60?'#fbbf24':'#f87171'};">${c.score}%</span>
          </div>`).join('')}
      </div>
    </div>

    <!-- Action Items (Priority) -->
    ${audit.actionItems.length?`<div style="background:${bg};border:1px solid ${border};border-radius:14px;padding:18px;margin-bottom:16px;">
      <div style="font-size:15px;font-weight:800;color:#0f3d26;margin-bottom:14px;">⚡ Priority Action Items</div>
      <div style="display:grid;gap:10px;">
        ${audit.actionItems.slice(0,8).map((item,i)=>`
          <div style="display:flex;align-items:flex-start;gap:12px;padding:12px 14px;background:${item.priority==='critical'?'#fef2f2':item.priority==='high'?'#fff7ed':'#fffbeb'};border-left:4px solid ${item.priority==='critical'?'#dc2626':item.priority==='high'?'#ea580c':'#d97706'};border-radius:0 10px 10px 0;">
            <div style="width:28px;height:28px;border-radius:50%;background:${item.priority==='critical'?'#dc2626':item.priority==='high'?'#ea580c':'#d97706'};color:#fff;display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:800;flex-shrink:0;">${i+1}</div>
            <div style="flex:1;">
              <div style="font-size:13px;font-weight:800;color:${textColor};">${escHTML(item.title)}</div>
              <div style="font-size:11px;color:${text2};margin-top:3px;">${escHTML(item.description)}</div>
              ${item.action?`<div style="margin-top:6px;"><button data-x-click="${item.action}" style="padding:4px 12px;background:${item.priority==='critical'?'#dc2626':item.priority==='high'?'#ea580c':'#d97706'};color:#fff;border:none;border-radius:6px;font-size:11px;font-weight:700;cursor:pointer;">${item.actionLabel||'Fix Now →'}</button></div>`:''}
            </div>
            <span style="padding:2px 8px;border-radius:6px;font-size:9px;font-weight:800;background:${item.priority==='critical'?'#dc2626':item.priority==='high'?'#ea580c':'#d97706'};color:#fff;text-transform:uppercase;flex-shrink:0;">${item.priority}</span>
          </div>`).join('')}
      </div>
    </div>`:''}

    <!-- Detailed Audit by Category -->
    ${audit.categories.map(cat=>`
      <div style="background:${bg};border:1px solid ${border};border-radius:14px;overflow:hidden;margin-bottom:14px;">
        <div style="background:${cat.score>=80?'linear-gradient(135deg,#065f46,#16a34a)':cat.score>=60?'linear-gradient(135deg,#92400e,#d97706)':'linear-gradient(135deg,#7f1d1d,#dc2626)'};color:#fff;padding:14px 18px;display:flex;align-items:center;justify-content:space-between;">
          <div style="font-size:14px;font-weight:800;">${cat.icon} ${escHTML(cat.name)}</div>
          <div style="display:flex;align-items:center;gap:10px;">
            <div style="background:rgba(255,255,255,.2);border-radius:6px;height:6px;width:80px;overflow:hidden;">
              <div style="width:${cat.score}%;height:100%;background:#fff;border-radius:6px;"></div>
            </div>
            <span style="font-size:14px;font-weight:900;">${cat.score}%</span>
          </div>
        </div>
        <div style="padding:14px;">
          <div style="display:grid;gap:8px;">
            ${cat.checks.map(check=>`
              <div style="display:flex;align-items:flex-start;gap:10px;padding:10px 12px;background:${check.status==='pass'?'#f0fdf4':check.status==='warn'?'#fffbeb':'#fef2f2'};border-radius:8px;">
                <span style="font-size:18px;flex-shrink:0;">${check.status==='pass'?'✅':check.status==='warn'?'⚠️':'❌'}</span>
                <div style="flex:1;">
                  <div style="font-size:12px;font-weight:700;color:${textColor};">${escHTML(check.name)}</div>
                  <div style="font-size:11px;color:${text2};margin-top:2px;">${check.detail}</div>
                  ${check.guideline?`<div style="font-size:10px;color:#2563eb;margin-top:4px;font-style:italic;">💡 Guideline: ${check.guideline}</div>`:''}
                </div>
                <span style="font-size:9px;font-weight:800;padding:2px 6px;border-radius:4px;background:${check.status==='pass'?'#16a34a':check.status==='warn'?'#d97706':'#dc2626'};color:#fff;text-transform:uppercase;flex-shrink:0;">${check.status}</span>
              </div>`).join('')}
          </div>
        </div>
      </div>`).join('')}

    <!-- Business Guidelines -->
    <div style="background:${bg};border:1px solid ${border};border-radius:14px;padding:18px;margin-bottom:16px;">
      <div style="font-size:15px;font-weight:800;color:#0f3d26;margin-bottom:14px;">📚 Business Guidelines & Best Practices</div>
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:12px;">
        ${[
          {icon:'💰',title:'Daily Cash Flow',guide:'Check bank balance every morning. Ensure daily sales cover daily expenses. Keep minimum ৳50,000 in bank at all times.',color:'#16a34a'},
          {icon:'📦',title:'Inventory Management',guide:'Check stock levels daily. Reorder when stock falls below minimum. Never let raw materials run out — it stops production.',color:'#2563eb'},
          {icon:'👥',title:'Customer Collections',guide:'Follow up on dues every week. No customer should have dues older than 60 days. Send WhatsApp reminders for dues over ৳1 lakh.',color:'#7c3aed'},
          {icon:'🏭',title:'Production Efficiency',guide:'Target 20%+ oil yield from rice bran. Log production daily. Any yield below 18% needs immediate investigation.',color:'#d97706'},
          {icon:'🔧',title:'Machine Maintenance',guide:'Preventive maintenance every 30 days. Log all repairs with cost. A broken machine costs more than maintenance.',color:'#dc2626'},
          {icon:'📊',title:'Monthly Review',guide:'Review P&L on 1st of every month. Compare with previous month. If profit drops >20%, investigate immediately.',color:'#059669'},
          {icon:'💾',title:'Data Backup',guide:'Backup data every Friday. Store in Google Drive. Test restore quarterly. Lost data = lost business history.',color:'#0891b2'},
          {icon:'🎯',title:'Goal Setting',guide:'Set monthly sales target at start of month. Review progress weekly. Adjust strategy if behind by more than 30%.',color:'#be185d'},
          {icon:'🚛',title:'Order Management',guide:'Confirm all orders in writing. Update delivery status daily. Follow up on overdue deliveries within 24 hours.',color:'#ea580c'},
          {icon:'💼',title:'Payroll',guide:'Pay salaries by 25th of every month. Keep salary records. Late salary = unhappy workers = poor productivity.',color:'#6b7280'},
          {icon:'🏛️',title:'Tax Compliance',guide:'Deduct 0.5% sales tax on every sale. Keep records for 5 years. File returns on time to avoid penalties.',color:'#374151'},
          {icon:'📱',title:'Communication',guide:'Send order confirmations via WhatsApp. Payment reminders on 1st and 15th. Delivery updates when truck departs.',color:'#25d366'},
        ].map(g=>`
          <div style="padding:14px;background:${g.color}08;border:1px solid ${g.color}22;border-radius:10px;">
            <div style="font-size:20px;margin-bottom:6px;">${g.icon}</div>
            <div style="font-size:13px;font-weight:800;color:${textColor};margin-bottom:6px;">${g.title}</div>
            <div style="font-size:11px;color:${text2};line-height:1.6;">${g.guide}</div>
          </div>`).join('')}
      </div>
    </div>

    <!-- Daily Checklist -->
    <div style="background:${bg};border:1px solid ${border};border-radius:14px;padding:18px;">
      <div style="font-size:15px;font-weight:800;color:#0f3d26;margin-bottom:14px;">✅ Daily Business Checklist</div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;">
        <div>
          <div style="font-size:12px;font-weight:800;color:#16a34a;margin-bottom:10px;">🌅 Morning (Start of Day)</div>
          ${['Check bank balance','Review pending orders','Check low stock alerts','Review overdue payments','Check machine status','Plan production for the day','Review yesterday\'s transactions'].map((item,i)=>`
            <label style="display:flex;align-items:center;gap:8px;padding:7px 0;border-bottom:1px solid ${border};cursor:pointer;">
              <input type="checkbox" id="chk-morning-${i}" style="width:16px;height:16px;cursor:pointer;" data-x-change="saveChecklist('morning-${i}',this.checked)">
              <span style="font-size:12px;color:${textColor};">${item}</span>
            </label>`).join('')}
        </div>
        <div>
          <div style="font-size:12px;font-weight:800;color:#7c3aed;margin-bottom:10px;">🌆 Evening (End of Day)</div>
          ${['Record all transactions','Update order statuses','Check cash in hand','Send payment reminders','Log production output','Backup data','Plan tomorrow\'s deliveries'].map((item,i)=>`
            <label style="display:flex;align-items:center;gap:8px;padding:7px 0;border-bottom:1px solid ${border};cursor:pointer;">
              <input type="checkbox" id="chk-evening-${i}" style="width:16px;height:16px;cursor:pointer;" data-x-change="saveChecklist('evening-${i}',this.checked)">
              <span style="font-size:12px;color:${textColor};">${item}</span>
            </label>`).join('')}
        </div>
      </div>
      <div style="margin-top:14px;padding:12px;background:#f0fdf4;border-radius:8px;font-size:12px;color:#16a34a;font-weight:700;text-align:center;">
        💡 Complete this checklist every day to keep your business running smoothly
      </div>
    </div>
  </div>`;

  // Load saved checklist state
  loadChecklistState();
}

function runCompleteAudit(){
  const now=new Date();
  const today=now.toISOString().split('T')[0];
  const thisMonth=now.toISOString().substring(0,7);
  const txs=DB.tx||[];
  const customers=(DB.customers||[]).filter(c=>isCustomerParty(c));
  const suppliers=(DB.customers||[]).filter(c=>c.type==='Supplier');
  const banks=DB.banks||[];
  const products=DB.products||[];
  const employees=DB.employees||[];
  const orders=DB.orders||[];
  const batches=DB.batches||[];
  const maintenance=DB.maintenance||[];
  const co=DB.settings||{};

  const SALE_T=['Sale','Sales','Sales Invoice','Customer Sale','Warehouse Sale','Other Income','Interest Income']; // canonical: money receipts/advances are NOT revenue or cost
  const PURCH_T=['Purchase','Warehouse Purchase','Supplier Purchase']; // canonical: money receipts/advances are NOT revenue or cost
  const EXP_T=['Salary Payment','Office Rent','Electricity Bill','Other Expense'];

  const monthSales=txs.filter(t=>t.date&&t.date.startsWith(thisMonth)&&SALE_T.includes(t.type)).reduce((s,t)=>s+txAmt(t),0);
  const monthPurch=txs.filter(t=>t.date&&t.date.startsWith(thisMonth)&&PURCH_T.includes(t.type)).reduce((s,t)=>s+txAmt(t),0);
  const monthExp=txs.filter(t=>t.date&&t.date.startsWith(thisMonth)&&EXP_T.includes(t.type)).reduce((s,t)=>s+txAmt(t),0);
  const monthCOGS=window.computeCOGS(txs.filter(t=>t.date&&t.date.startsWith(thisMonth)));
  const monthProfit=monthSales-monthCOGS-monthExp;
  const totalBankBal=banks.reduce((s,b)=>s+(b.bal||0),0);
  const totalRecv=customers.reduce((s,c)=>s+(c.bal||0),0);
  const overdueCustomers=customers.filter(c=>(c.bal||0)>500000);
  const lowStockProducts=products.filter(p=>(p.qty||0)<=(p.minStock||10));
  const outOfStock=products.filter(p=>(p.qty||0)<=0);
  const pendingOrders=orders.filter(o=>o.deliveryStatus==='Pending');
  const lateOrders=orders.filter(o=>o.deliveryDate&&o.deliveryDate<today&&o.deliveryStatus!=='Delivered'&&o.deliveryStatus!=='Cancelled');
  const avgYield=batches.length>0?(batches.reduce((s,b)=>s+(b.bran>0?b.oil/b.bran*100:0),0)/batches.length):0;
  const lastMaint=maintenance.sort((a,b)=>b.date.localeCompare(a.date))[0];
  const daysSinceMaint=lastMaint?Math.floor((new Date(today)-new Date(lastMaint.date))/(1000*60*60*24)):999;
  const activeEmps=employees.filter(e=>e.status==='Active');
  const paidThisMonth=new Set(txs.filter(t=>t.type==='Salary Payment'&&(t.date||'').startsWith(thisMonth)).map(t=>t.party));
  const unpaidEmps=activeEmps.filter(e=>!paidThisMonth.has(e.name));
  const negativeBanks=banks.filter(b=>(b.bal||0)<0);
  const profitMargin=monthSales>0?(monthProfit/monthSales*100):0;
  const goals=DB.goals||{};
  const salesTarget=goals.monthlySalesTarget||0;
  const salesPct=salesTarget>0?monthSales/salesTarget*100:100;

  // ── CATEGORY 1: Financial Health ──
  const finChecks=[
    {name:'Bank Balance',status:totalBankBal>100000?'pass':totalBankBal>50000?'warn':'fail',detail:totalBankBal>100000?'৳'+totalBankBal.toLocaleString('en-IN')+' — Healthy balance':'৳'+totalBankBal.toLocaleString('en-IN')+' — Low! Keep minimum ৳1 lakh',guideline:'Maintain minimum ৳1 lakh in bank for operational safety'},
    {name:'Negative Bank Accounts',status:negativeBanks.length===0?'pass':'fail',detail:negativeBanks.length===0?'No negative balances':negativeBanks.map(b=>b.name+': ৳'+b.bal).join(', '),guideline:'Never let any bank account go negative — arrange transfer immediately'},
    {name:'Monthly Profit',status:monthProfit>0?'pass':monthProfit>-50000?'warn':'fail',detail:'৳'+monthProfit.toLocaleString('en-IN')+' | Margin: '+profitMargin.toFixed(1)+'%',guideline:'Target minimum 15% profit margin. Below 10% needs immediate review'},
    {name:'Customer Receivables',status:totalRecv<monthSales*2?'pass':totalRecv<monthSales*3?'warn':'fail',detail:'৳'+totalRecv.toLocaleString('en-IN')+' outstanding from '+customers.filter(c=>c.bal>0).length+' customers',guideline:'Receivables should not exceed 2x monthly sales. Follow up weekly'},
    {name:'Overdue Payments (>৳5L)',status:overdueCustomers.length===0?'pass':overdueCustomers.length<=2?'warn':'fail',detail:overdueCustomers.length===0?'No large overdue amounts':overdueCustomers.length+' customers with dues over ৳5 lakh',guideline:'Any customer with >৳5 lakh due needs immediate follow-up call'},
    {name:'Sales Tax Compliance',status:co.salesTaxEnabled!==false?'pass':'warn',detail:co.salesTaxEnabled!==false?'Sales tax ('+(isFinite(parseFloat(co.salesTaxRate))?parseFloat(co.salesTaxRate):0.05)+'%) is active':'Sales tax is disabled — ensure compliance',guideline:'Deduct '+(isFinite(parseFloat(co.salesTaxRate))?parseFloat(co.salesTaxRate):0.05)+'% tax on every sale. Keep records for 5 years'},
    {name:'Monthly Sales Target',status:salesTarget===0?'warn':salesPct>=80?'pass':salesPct>=60?'warn':'fail',detail:salesTarget===0?'No target set':'৳'+monthSales.toLocaleString('en-IN')+' of ৳'+salesTarget.toLocaleString('en-IN')+' target ('+Math.round(salesPct)+'%)',guideline:'Set monthly targets and review weekly. Adjust strategy if behind by 30%'},
  ];

  // ── CATEGORY 2: Inventory & Stock ──
  const invChecks=[
    {name:'Out of Stock Products',status:outOfStock.length===0?'pass':'fail',detail:outOfStock.length===0?'All products have stock':outOfStock.map(p=>p.name).join(', ')+' — OUT OF STOCK',guideline:'Out of stock = lost sales. Reorder immediately when stock hits minimum'},
    {name:'Low Stock Warning',status:lowStockProducts.length===0?'pass':lowStockProducts.length<=2?'warn':'fail',detail:lowStockProducts.length===0?'All products above minimum':lowStockProducts.length+' products below minimum: '+lowStockProducts.slice(0,3).map(p=>p.name).join(', '),guideline:'Set minimum stock levels for all products. Reorder when reached'},
    {name:'Product Catalog',status:products.length>0?'pass':'warn',detail:products.length+' products configured',guideline:'Keep product catalog updated with current rates and stock levels'},
    {name:'Raw Materials',status:(DB.rawMaterials||[]).length>0?'pass':'warn',detail:(DB.rawMaterials||[]).length+' raw materials tracked',guideline:'Track all raw materials. Rice bran shortage stops production'},
    {name:'Inventory Value',status:'pass',detail:'Total inventory value: ৳'+products.reduce((s,p)=>s+(p.qty||0)*(p.rate||0),0).toLocaleString('en-IN'),guideline:'Review inventory value monthly. High value = capital locked in stock'},
  ];

  // ── CATEGORY 3: Operations & Orders ──
  const opsChecks=[
    {name:'Pending Orders',status:pendingOrders.length<=10?'pass':pendingOrders.length<=20?'warn':'fail',detail:pendingOrders.length+' orders pending',guideline:'Process orders within 24 hours. More than 20 pending = bottleneck'},
    {name:'Late Deliveries',status:lateOrders.length===0?'pass':lateOrders.length<=3?'warn':'fail',detail:lateOrders.length===0?'All deliveries on time':lateOrders.length+' orders past delivery date',guideline:'Contact customer immediately for late deliveries. Update status daily'},
    {name:'Order Tracking',status:orders.length>0?'pass':'warn',detail:orders.length+' total orders | '+orders.filter(o=>o.deliveryStatus==='Delivered').length+' delivered',guideline:'Update order status every day. Customers need to know delivery status'},
    {name:'Production Batches',status:batches.length>0?'pass':'warn',detail:batches.length+' batches recorded | Avg yield: '+avgYield.toFixed(1)+'%',guideline:'Log every production batch. Target 20%+ oil yield from rice bran'},
    {name:'Oil Yield Performance',status:avgYield>=20?'pass':avgYield>=18?'warn':avgYield>0?'fail':'warn',detail:avgYield>0?'Average yield: '+avgYield.toFixed(2)+'%':'No production batches recorded yet',guideline:'Below 18% yield = machine problem or poor quality bran. Investigate immediately'},
  ];

  // ── CATEGORY 4: Machine & Maintenance ──
  const maintChecks=[
    {name:'Maintenance Records',status:maintenance.length>0?'pass':'warn',detail:maintenance.length+' maintenance records logged',guideline:'Log every repair and maintenance. Helps predict future breakdowns'},
    {name:'Last Maintenance',status:daysSinceMaint<=30?'pass':daysSinceMaint<=60?'warn':'fail',detail:lastMaint?'Last maintenance: '+lastMaint.date+' ('+daysSinceMaint+' days ago)':'No maintenance records found',guideline:'Preventive maintenance every 30 days. Prevents costly breakdowns'},
    {name:'Overdue Maintenance',status:(()=>{const overdue=maintenance.filter(m=>m.nextDue&&m.nextDue<today);return overdue.length===0?'pass':'fail';})(),detail:(()=>{const overdue=maintenance.filter(m=>m.nextDue&&m.nextDue<today);return overdue.length===0?'No overdue maintenance':overdue.length+' machines overdue for maintenance';})(),guideline:'Never skip scheduled maintenance. A broken machine costs 10x more than maintenance'},
    {name:'Maintenance Cost Tracking',status:maintenance.filter(m=>m.cost>0).length>0?'pass':'warn',detail:'৳'+maintenance.reduce((s,m)=>s+(m.cost||0),0).toLocaleString('en-IN')+' total maintenance cost recorded',guideline:'Track all maintenance costs. High costs = machine needs replacement'},
  ];

  // ── CATEGORY 5: HR & Payroll ──
  const hrChecks=[
    {name:'Employee Records',status:employees.length>0?'pass':'warn',detail:employees.length+' employees | '+activeEmps.length+' active',guideline:'Keep all employee records updated. Required for payroll and compliance'},
    {name:'Salary Payments',status:activeEmps.length===0?'pass':unpaidEmps.length===0?'pass':unpaidEmps.length<=2?'warn':'fail',detail:activeEmps.length===0?'No active employees':unpaidEmps.length===0?'All employees paid for '+thisMonth:unpaidEmps.length+' employees not yet paid for '+thisMonth,guideline:'Pay salaries by 25th of every month. Late payment = unhappy workers'},
    {name:'Payroll Budget',status:'pass',detail:'Monthly payroll: ৳'+activeEmps.reduce((s,e)=>s+(e.salary||0),0).toLocaleString('en-IN'),guideline:'Payroll should not exceed 30% of monthly revenue'},
  ];

  // ── CATEGORY 6: Data & Compliance ──
  const dataChecks=[
    {name:'Company Settings',status:co.companyName?'pass':'warn',detail:co.companyName?'Company: '+co.companyName:'Company name not configured',guideline:'Complete company settings for professional invoices and reports'},
    {name:'Data Backup',status:DB.lastBackup?'pass':'warn',detail:DB.lastBackup?'Last backup: '+DB.lastBackup:'No backup recorded — data at risk!',guideline:'Backup every Friday. Store in Google Drive. Lost data = lost business'},
    {name:'Transaction Records',status:txs.length>0?'pass':'warn',detail:txs.length+' transactions recorded',guideline:'Record every transaction same day. Delayed recording = errors'},
    {name:'Audit Trail',status:(DB.auditLog||[]).length>0?'pass':'warn',detail:(DB.auditLog||[]).length+' audit log entries',guideline:'All changes are logged automatically. Review monthly for unauthorized changes'},
    {name:'User Management',status:(DB.users||[]).length>1?'pass':'warn',detail:(DB.users||[]).length+' users configured',guideline:'Each person should have their own login. Never share passwords'},
  ];

  // ── Calculate scores ──
  function calcScore(checks){
    const pass=checks.filter(c=>c.status==='pass').length;
    return Math.round(pass/checks.length*100);
  }

  const categories=[
    {name:'Finance',icon:'💰',score:calcScore(finChecks),checks:finChecks},
    {name:'Inventory',icon:'📦',score:calcScore(invChecks),checks:invChecks},
    {name:'Operations',icon:'🏭',score:calcScore(opsChecks),checks:opsChecks},
    {name:'Maintenance',icon:'🔧',score:calcScore(maintChecks),checks:maintChecks},
    {name:'HR & Payroll',icon:'👥',score:calcScore(hrChecks),checks:hrChecks},
    {name:'Data & Compliance',icon:'📋',score:calcScore(dataChecks),checks:dataChecks},
  ];

  const allChecks=[...finChecks,...invChecks,...opsChecks,...maintChecks,...hrChecks,...dataChecks];
  const passed=allChecks.filter(c=>c.status==='pass').length;
  const warnings=allChecks.filter(c=>c.status==='warn').length;
  const critical=allChecks.filter(c=>c.status==='fail').length;
  const score=Math.round(passed/allChecks.length*100);

  // ── Build action items ──
  const actionItems=[];
  if(negativeBanks.length>0) actionItems.push({priority:'critical',title:'Fix Negative Bank Balance',description:negativeBanks.map(b=>b.name+': ৳'+b.bal).join(', '),action:"nav('banks')",actionLabel:'View Banks'});
  if(outOfStock.length>0) actionItems.push({priority:'critical',title:'Restock Out-of-Stock Products',description:outOfStock.map(p=>p.name).join(', ')+' — production may stop',action:"nav('inventory')",actionLabel:'View Inventory'});
  if(lateOrders.length>0) actionItems.push({priority:'critical',title:'Follow Up on Late Deliveries',description:lateOrders.length+' orders past delivery date — contact customers now',action:"nav('orders')",actionLabel:'View Orders'});
  if(overdueCustomers.length>0) actionItems.push({priority:'high',title:'Collect Overdue Payments',description:overdueCustomers.length+' customers with dues over ৳5 lakh',action:"nav('apar')",actionLabel:'View AP/AR'});
  if(unpaidEmps.length>0&&now.getDate()>20) actionItems.push({priority:'high',title:'Pay Employee Salaries',description:unpaidEmps.length+' employees not paid for '+thisMonth,action:"nav('payroll')",actionLabel:'Pay Salary'});
  if(daysSinceMaint>60) actionItems.push({priority:'high',title:'Schedule Machine Maintenance',description:'No maintenance in '+daysSinceMaint+' days — risk of breakdown',action:"nav('production')",actionLabel:'Log Maintenance'});
  if(lowStockProducts.length>0) actionItems.push({priority:'medium',title:'Reorder Low Stock Products',description:lowStockProducts.length+' products below minimum stock level',action:"nav('inventory')",actionLabel:'View Stock'});
  if(!DB.lastBackup) actionItems.push({priority:'medium',title:'Backup Your Data',description:'No backup found — your data is at risk',action:"nav('googledrivebackup')",actionLabel:'Backup Now'});
  if(!co.companyName) actionItems.push({priority:'medium',title:'Complete Company Settings',description:'Company name and details not configured',action:"nav('settings')",actionLabel:'Go to Settings'});
  if(salesTarget===0) actionItems.push({priority:'low',title:'Set Monthly Sales Target',description:'No target set for '+thisMonth+' — track your progress',action:"nav('goals')",actionLabel:'Set Goals'});

  const topIssue=actionItems.find(a=>a.priority==='critical')?.title||actionItems.find(a=>a.priority==='high')?.title||'';

  return {score,passed,warnings,critical,categories,actionItems,topIssue};
}

function saveChecklist(key, val){
  if(!DB.checklists) DB.checklists={};
  const today=new Date().toISOString().split('T')[0];
  if(!DB.checklists[today]) DB.checklists[today]={};
  DB.checklists[today][key]=val;
  saveDB();
}

function loadChecklistState(){
  const today=new Date().toISOString().split('T')[0];
  const saved=(DB.checklists||{})[today]||{};
  Object.entries(saved).forEach(([key,val])=>{
    const el=document.getElementById('chk-'+key);
    if(el) el.checked=val;
  });
}

function printAuditReport(){
  const co=DB.settings||{};
  const audit=runCompleteAudit();
  const html=`<!DOCTYPE html><html><head><title>Business Audit Report</title>
  <style>body{font-family:'Segoe UI',sans-serif;padding:20px;font-size:12px;color:#1a202c;}
  h1{color:#0f3d26;font-size:20px;}h2{color:#0f3d26;font-size:14px;margin-top:16px;}
  .score{font-size:48px;font-weight:900;color:${audit.score>=80?'#16a34a':audit.score>=60?'#d97706':'#dc2626'};}
  .check{padding:6px 10px;border-radius:6px;margin-bottom:4px;display:flex;gap:8px;}
  .pass{background:#f0fdf4;}.warn{background:#fffbeb;}.fail{background:#fef2f2;}
  .action{padding:8px 12px;border-left:4px solid #dc2626;margin-bottom:6px;background:#fef2f2;}
  @page{size:A4;margin:10mm 12mm;}@media print{html,body{max-width:100%!important;}*{overflow:visible!important;max-height:none!important;}img,svg,canvas{max-width:100%!important;height:auto!important;}table{width:100%!important;table-layout:auto!important;word-break:break-word;overflow-wrap:anywhere;}th,td{white-space:normal!important;overflow-wrap:anywhere;}.container,.voucher,.receipt,.doc,.page{max-width:100%!important;width:auto!important;}}table{page-break-inside:auto;}tr{page-break-inside:avoid;}thead{display:table-header-group;}@media print{body{padding:10px;}}</style></head><body>
  <div style="display:flex;justify-content:space-between;margin-bottom:16px;padding-bottom:12px;border-bottom:2px solid #0f3d26;">
    <div><h1>${prtCo().logo} ${escHTML(prtCo().name)}</h1><div style="font-size:11px;color:#6b7280;">${escHTML(prtCo().address)}</div></div>
    <div style="text-align:right;"><div style="font-size:16px;font-weight:800;color:#0f3d26;">BUSINESS AUDIT REPORT</div><div style="font-size:11px;color:#6b7280;">Generated: ${new Date().toLocaleString('en-GB')}</div></div>
  </div>
  <div style="text-align:center;margin:16px 0;"><div class="score">${audit.score}/100</div><div style="font-size:14px;font-weight:700;">${audit.score>=80?'Excellent 🌟':audit.score>=60?'Good 👍':audit.score>=40?'Fair ⚠️':'Needs Attention 🚨'}</div></div>
  <h2>Priority Action Items</h2>
  ${audit.actionItems.map(a=>`<div class="action"><strong>${a.title}</strong><br>${escHTML(a.description)}</div>`).join('')}
  ${audit.categories.map(cat=>`<h2>${cat.icon} ${escHTML(cat.name)} — ${cat.score}%</h2>${cat.checks.map(c=>`<div class="check ${c.status}"><span>${c.status==='pass'?'✅':c.status==='warn'?'⚠️':'❌'}</span><div><strong>${escHTML(c.name)}</strong><br>${c.detail}</div></div>`).join('')}`).join('')}
  <div style="margin-top:20px;font-size:10px;color:#9ca3af;text-align:center;">${escHTML(prtCo().name)} • Business Audit Report • ${new Date().toLocaleDateString('en-GB')}</div>
  </body></html>`;
  const w=openPrintWindow(); if(!w) return;
  w.document.write(html);
