// ═══════════════════════════════════════════════════════════════
// PUSH NOTIFICATIONS SYSTEM
// Browser notifications for overdue payments, low stock, orders
// ═══════════════════════════════════════════════════════════════

let _pushPermission = 'default';
let _pushCheckInterval = null;
let _sentNotifications = new Set(); // Track sent notifications to avoid duplicates

async function initPushNotifications(){
  // Check if browser supports notifications
  if(!('Notification' in window)){
    console.info('Push notifications not supported in this browser');
    return;
  }

  _pushPermission = Notification.permission;

  // If already granted, start checking
  if(_pushPermission === 'granted'){
    startPushNotificationChecks();
    console.info('✅ Push notifications active');
  }

  // Load sent notifications from session
  try{
    const saved = sessionStorage.getItem('rbo_sent_notifs');
    if(saved) _sentNotifications = new Set(JSON.parse(saved));
  }catch(e){}
}

async function requestPushPermission(){
  if(!('Notification' in window)){
    toast('Push notifications not supported in this browser','e');
    return false;
  }

  if(Notification.permission === 'granted'){
    toast('Push notifications already enabled!', 's');
    startPushNotificationChecks();
    return true;
  }

  if(Notification.permission === 'denied'){
    toast('Notifications blocked. Please enable in browser settings.', 'e');
    return false;
  }

  const permission = await Notification.requestPermission();
  _pushPermission = permission;

  if(permission === 'granted'){
    toast('Push notifications enabled!', 's');
    startPushNotificationChecks();
    // Send welcome notification
    sendPushNotification('🌾 RBO ERP Notifications Active',
      'You will now receive alerts for overdue payments, low stock and delivery reminders.',
      {icon:'🌾',tag:'welcome'});
    logAudit('NOTIFICATIONS','Push','Push notifications enabled');
    return true;
  } else {
    toast('Notification permission denied','e');
    return false;
  }
}

function startPushNotificationChecks(){
  // Clear existing interval
  if(_pushCheckInterval) clearInterval(_pushCheckInterval);

  // Check immediately
  runPushNotificationChecks();

  // Then check every 15 minutes
  _pushCheckInterval = setInterval(runPushNotificationChecks, 15 * 60 * 1000);

  // Also schedule daily summary at 6 PM
  scheduleDailySummaryNotification();
}

function runPushNotificationChecks(){
  if(Notification.permission !== 'granted') return;
  const settings=DB.settings||{};
  const today=new Date().toISOString().split('T')[0];
  const now=new Date();

  // ── 1. Overdue Payment Alerts ──
  if(settings['push-overdue'] !== false){
    const overdueCustomers=(DB.customers||[]).filter(c=>{
      const isCustomer=isCustomerParty(c);
      return isCustomer&&(c.bal||0)>500000; // Over 5 lakh
    });
    overdueCustomers.forEach(c=>{
      const notifId='overdue-'+c.id+'-'+today;
      if(!_sentNotifications.has(notifId)){
        _sentNotifications.add(notifId);
        sendPushNotification(
          '💰 Overdue Payment Alert',
          `${c.name} has outstanding balance of ৳${(c.bal||0).toLocaleString('en-IN',{minimumFractionDigits:0})}`,
          {icon:'💰',tag:notifId,requireInteraction:true,
           actions:[{action:'view',title:'View Customer'}]}
        );
      }
    });
  }

  // ── 2. Low Stock Warnings ──
  if(settings['push-lowstock'] !== false){
    const outOfStock=(DB.products||[]).filter(p=>(p.qty||0)<=0);
    const lowStock=(DB.products||[]).filter(p=>(p.qty||0)>0&&(p.qty||0)<=(p.minStock||10));

    outOfStock.forEach(p=>{
      const notifId='outofstock-'+p.id+'-'+today;
      if(!_sentNotifications.has(notifId)){
        _sentNotifications.add(notifId);
        sendPushNotification(
          '📦 OUT OF STOCK!',
          `${p.name} is completely out of stock. Reorder immediately!`,
          {icon:'📦',tag:notifId,requireInteraction:true,urgent:true}
        );
      }
    });

    if(lowStock.length>0){
      const notifId='lowstock-'+today+'-'+lowStock.length;
      if(!_sentNotifications.has(notifId)){
        _sentNotifications.add(notifId);
        sendPushNotification(
          '⚠️ Low Stock Warning',
          `${lowStock.length} product(s) below minimum: ${lowStock.slice(0,2).map(p=>p.name).join(', ')}${lowStock.length>2?'...':''}`,
          {icon:'⚠️',tag:notifId}
        );
      }
    }
  }

  // ── 3. Order Delivery Reminders ──
  if(settings['push-delivery'] !== false){
    const tomorrow=new Date(now);
    tomorrow.setDate(tomorrow.getDate()+1);
    const tomorrowStr=tomorrow.toISOString().split('T')[0];

    // Orders due today
    const dueToday=(DB.orders||[]).filter(o=>
      o.deliveryDate===today&&
      o.deliveryStatus!=='Delivered'&&
      o.deliveryStatus!=='Cancelled'
    );
    if(dueToday.length>0){
      const notifId='delivery-today-'+today;
      if(!_sentNotifications.has(notifId)){
        _sentNotifications.add(notifId);
        sendPushNotification(
          '🚛 Deliveries Due TODAY',
          `${dueToday.length} order(s) scheduled for delivery today: ${dueToday.slice(0,2).map(o=>o.customerName).join(', ')}`,
          {icon:'🚛',tag:notifId,requireInteraction:true}
        );
      }
    }

    // Orders due tomorrow
    const dueTomorrow=(DB.orders||[]).filter(o=>
      o.deliveryDate===tomorrowStr&&
      o.deliveryStatus!=='Delivered'&&
      o.deliveryStatus!=='Cancelled'
    );
    if(dueTomorrow.length>0){
      const notifId='delivery-tomorrow-'+tomorrowStr;
      if(!_sentNotifications.has(notifId)){
        _sentNotifications.add(notifId);
        sendPushNotification(
          '📋 Deliveries Due Tomorrow',
          `${dueTomorrow.length} order(s) due tomorrow: ${dueTomorrow.slice(0,2).map(o=>o.customerName).join(', ')}`,
          {icon:'📋',tag:notifId}
        );
      }
    }

    // Overdue orders (past delivery date, not delivered)
    const overdueOrders=(DB.orders||[]).filter(o=>
      o.deliveryDate&&o.deliveryDate<today&&
      o.deliveryStatus!=='Delivered'&&
      o.deliveryStatus!=='Cancelled'
    );
    if(overdueOrders.length>0){
      const notifId='overdue-orders-'+today;
      if(!_sentNotifications.has(notifId)){
        _sentNotifications.add(notifId);
        sendPushNotification(
          '🔴 Overdue Deliveries!',
          `${overdueOrders.length} order(s) past delivery date. Immediate action required!`,
          {icon:'🔴',tag:notifId,requireInteraction:true,urgent:true}
        );
      }
    }
  }

  // ── 4. Cheque Due Reminders ──
  if(settings['push-cheques'] !== false){
    const tomorrow=new Date(now);
    tomorrow.setDate(tomorrow.getDate()+1);
    const tomorrowStr=tomorrow.toISOString().split('T')[0];

    const chequesTomorrow=(DB.cheques||[]).filter(c=>
      c.dueDate===tomorrowStr&&c.status==='Pending'
    );
    if(chequesTomorrow.length>0){
      const notifId='cheque-due-'+tomorrowStr;
      if(!_sentNotifications.has(notifId)){
        _sentNotifications.add(notifId);
        sendPushNotification(
          '🧾 Cheque Due Tomorrow',
          `${chequesTomorrow.length} cheque(s) due tomorrow: ৳${chequesTomorrow.reduce((s,c)=>s+(c.amount||0),0).toLocaleString('en-IN',{minimumFractionDigits:0})}`,
          {icon:'🧾',tag:notifId}
        );
      }
    }
  }

  // ── 5. Salary Reminder (on 20th of month) ──
  if(settings['push-salary'] !== false && now.getDate()===20){
    const thisMonth=now.toISOString().substring(0,7);
    const activeEmps=(DB.employees||[]).filter(e=>e.status==='Active');
    const paidThisMonth=new Set((DB.tx||[]).filter(t=>t.type==='Salary Payment'&&(t.date||'').startsWith(thisMonth)).map(t=>t.party));
    const unpaidEmps=activeEmps.filter(e=>!paidThisMonth.has(e.name));
    if(unpaidEmps.length>0){
      const notifId='salary-reminder-'+thisMonth;
      if(!_sentNotifications.has(notifId)){
        _sentNotifications.add(notifId);
        sendPushNotification(
          '💼 Salary Payment Reminder',
          `${unpaidEmps.length} employee(s) not yet paid for ${thisMonth}. Salary day is approaching!`,
          {icon:'💼',tag:notifId}
        );
      }
    }
  }

  // Save sent notifications to session
  try{
    sessionStorage.setItem('rbo_sent_notifs', JSON.stringify([..._sentNotifications]));
  }catch(e){}
}

function _sendPushNotificationCore(title, body, options={}){
  try{
    const co=DB.settings||{};
    const notif=new Notification(title,{
      body,
      icon:options.icon||'🌾',
      badge:'🌾',
      tag:options.tag||'rbo-'+Date.now(),
      requireInteraction:options.requireInteraction||false,
      silent:false,
      data:{url:window.location.href,...(options.data||{})}
    });

    // Auto-close after 8 seconds (unless requireInteraction)
    if(!options.requireInteraction){
      setTimeout(()=>notif.close(),8000);
    }

    // Handle click
    notif.onclick=function(e){
      e.preventDefault();
      window.focus();
      notif.close();
      // Navigate based on notification type
      const tag=options.tag||'';
      if(tag.includes('overdue')&&!tag.includes('order')) nav('customers');
      else if(tag.includes('stock')) nav('inventory');
      else if(tag.includes('delivery')||tag.includes('order')) nav('orders');
      else if(tag.includes('cheque')) nav('cheque');
      else if(tag.includes('salary')) nav('payroll');
    };

    return notif;
  }catch(e){
    console.warn('Push notification failed:', e);
  }
}

function scheduleDailySummaryNotification(){
  if(Notification.permission !== 'granted') return;
  const settings=DB.settings||{};
  if(settings['push-daily-summary'] === false) return;

  const now=new Date();
  const target=new Date(now);
  target.setHours(18,0,0,0); // 6 PM

  if(now>target) target.setDate(target.getDate()+1); // Tomorrow 6 PM

  const delay=target-now;
  setTimeout(()=>{
    sendDailySummaryNotification();
    // Reschedule for next day
    setInterval(sendDailySummaryNotification, 24*60*60*1000);
  }, delay);
}

function sendDailySummaryNotification(){
  if(Notification.permission !== 'granted') return;
  const today=new Date().toISOString().split('T')[0];
  const txs=DB.tx||[];
  const SALE_T=['Sale','Sales','Sales Invoice','Customer Sale','Warehouse Sale','Other Income','Interest Income']; // canonical: money receipts/advances are NOT revenue or cost
  const todaySales=txs.filter(t=>t.date===today&&SALE_T.includes(t.type)).reduce((s,t)=>s+txAmt(t),0);
  const todayTxCount=txs.filter(t=>t.date===today).length;
  const pendingOrders=(DB.orders||[]).filter(o=>o.deliveryStatus==='Pending').length;

  sendPushNotification(
    '📊 Daily Summary — '+today,
    `Sales: ৳${todaySales.toLocaleString('en-IN',{minimumFractionDigits:0})} | Transactions: ${todayTxCount} | Pending Orders: ${pendingOrders}`,
    {icon:'📊',tag:'daily-summary-'+today}
  );
}

function renderPushNotificationSettings(){
  const el=document.getElementById('pg-pushnotifications');
  if(!el) return;
  const isDark=document.documentElement.getAttribute('data-theme')==='dark';
  const bg=isDark?'#1e293b':'#fff';
  const border=isDark?'#334155':'#e5e7eb';
  const textColor=isDark?'#f1f5f9':'#1a202c';
  const text2=isDark?'#94a3b8':'#6b7280';
  const settings=DB.settings||{};
  const isGranted=Notification.permission==='granted';
  const isSupported='Notification' in window;

  el.innerHTML=`<div style="padding:20px;">
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:20px;flex-wrap:wrap;gap:10px;">
      <div>
        <h2 style="font-size:20px;font-weight:800;color:#0f3d26;margin:0;">🔔 Push Notifications</h2>
        <p style="font-size:12px;color:${text2};margin:4px 0 0;">Browser alerts for overdue payments, low stock & delivery reminders</p>
      </div>
    </div>

    <!-- Permission Status -->
    <div style="background:${isGranted?'#f0fdf4':'#fef9c3'};border:1.5px solid ${isGranted?'#bbf7d0':'#fde68a'};border-radius:12px;padding:18px;margin-bottom:20px;">
      <div style="display:flex;align-items:center;gap:14px;flex-wrap:wrap;">
        <div style="font-size:40px;">${isGranted?'✅':isSupported?'🔔':'❌'}</div>
        <div style="flex:1;">
          <div style="font-size:15px;font-weight:800;color:${isGranted?'#16a34a':'#b45309'};">
            ${isGranted?'Push Notifications Active':isSupported?'Notifications Not Enabled':'Not Supported'}
          </div>
          <div style="font-size:12px;color:${text2};margin-top:4px;">
            ${isGranted?'You will receive browser alerts for important events.':
              isSupported?'Click the button below to enable browser notifications.':
              'Your browser does not support push notifications.'}
          </div>
        </div>
        ${isSupported&&!isGranted?`<button data-x-click="requestPushPermissionBtn()"
          style="padding:10px 20px;background:#16a34a;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:13px;white-space:nowrap;">
          🔔 Enable Notifications
        </button>`:''}
        ${isGranted?`<button data-x-click="sendTestNotification()"
          style="padding:10px 16px;background:#2563eb;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:12px;white-space:nowrap;">
          🧪 Test
        </button>`:''}
      </div>
    </div>

    <!-- Notification Types -->
    <div style="background:${bg};border:1px solid ${border};border-radius:12px;padding:18px;margin-bottom:16px;">
      <div style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:14px;">⚙️ Notification Settings</div>
      <div style="display:grid;gap:12px;">
        ${[
          {key:'push-overdue',icon:'💰',title:'Overdue Payment Alerts',desc:'Alert when customer balance exceeds ৳5 lakh',default:true},
          {key:'push-lowstock',icon:'📦',title:'Low Stock Warnings',desc:'Alert when products fall below minimum stock level',default:true},
          {key:'push-delivery',icon:'🚛',title:'Delivery Reminders',desc:'Alert for orders due today, tomorrow and overdue deliveries',default:true},
          {key:'push-cheques',icon:'🧾',title:'Cheque Due Reminders',desc:'Alert when cheques are due tomorrow',default:true},
          {key:'push-salary',icon:'💼',title:'Salary Payment Reminder',desc:'Alert on 20th of month if employees not yet paid',default:true},
          {key:'push-daily-summary',icon:'📊',title:'Daily Summary (6 PM)',desc:'Daily business summary notification at 6 PM',default:true},
        ].map(n=>`
          <div style="display:flex;align-items:center;gap:12px;padding:12px;background:#f9fafb;border-radius:10px;border:1px solid ${border};">
            <span style="font-size:22px;">${n.icon}</span>
            <div style="flex:1;">
              <div style="font-size:13px;font-weight:700;color:${textColor};">${n.title}</div>
              <div style="font-size:11px;color:${text2};margin-top:2px;">${escHTML(n.desc)}</div>
            </div>
            <label style="position:relative;display:inline-block;width:44px;height:24px;flex-shrink:0;">
              <input type="checkbox" id="${n.key}" ${settings[n.key]!==false?'checked':''} data-x-change="savePushSetting('${n.key}',this.checked)"
                style="opacity:0;width:0;height:0;">
              <span data-x-click="document.getElementById('${n.key}').click()" style="position:absolute;cursor:pointer;inset:0;background:${settings[n.key]!==false?'#16a34a':'#d1d5db'};border-radius:24px;transition:.3s;">
                <span style="position:absolute;content:'';height:18px;width:18px;left:${settings[n.key]!==false?'23px':'3px'};bottom:3px;background:#fff;border-radius:50%;transition:.3s;display:block;"></span>
              </span>
            </label>
          </div>`).join('')}
      </div>
    </div>

    <!-- Manual Trigger -->
    <div style="background:${bg};border:1px solid ${border};border-radius:12px;padding:18px;margin-bottom:16px;">
      <div style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:14px;">🔄 Manual Checks</div>
      <div style="display:flex;gap:10px;flex-wrap:wrap;">
        <button data-x-click="runPushNotificationChecks();toast('Notification check complete', 's')"
          style="padding:10px 18px;background:#16a34a;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:13px;">
