          📊 Send Daily Summary
        </button>
        <button data-x-click="clearSentNotifications()"
          style="padding:10px 18px;background:#f3f4f6;color:#374151;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:13px;">
          🗑️ Clear Sent History
        </button>
      </div>
    </div>

    <!-- Recent Notifications Log -->
    <div style="background:${bg};border:1px solid ${border};border-radius:12px;padding:18px;">
      <div style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:12px;">📋 Notification Log</div>
      ${(DB.notificationLog||[]).length?`<table style="width:100%;border-collapse:collapse;font-size:12px;">
        <thead><tr style="background:#f9fafb;">
          <th style="padding:8px 12px;text-align:left;font-size:10px;font-weight:700;color:${text2};">TIME</th>
          <th style="padding:8px 12px;text-align:left;font-size:10px;font-weight:700;color:${text2};">TITLE</th>
          <th style="padding:8px 12px;text-align:left;font-size:10px;font-weight:700;color:${text2};">MESSAGE</th>
        </tr></thead>
        <tbody>${(DB.notificationLog||[]).slice(0,10).map(n=>`<tr style="border-bottom:1px solid ${border};">
          <td style="padding:8px 12px;color:${text2};white-space:nowrap;">${n.ts}</td>
          <td style="padding:8px 12px;font-weight:700;color:${textColor};">${escHTML(n.title)}</td>
          <td style="padding:8px 12px;color:${text2};">${n.body}</td>
        </tr>`).join('')}</tbody>
      </table>`
      :`<div style="text-align:center;padding:20px;color:${text2};font-size:12px;">No notifications sent yet.</div>`}
    </div>
  </div>`;
}

function savePushSetting(key, val){
  if(!DB.settings) DB.settings={};
  DB.settings[key]=val;
  saveDB();
  toast((val?'✅ Enabled':'❌ Disabled')+' '+key.replace('push-','').replace(/-/g,' '),'s');
}

function sendTestNotification(){
  sendPushNotification(
    '🧪 Test Notification',
    'Push notifications are working correctly! You will receive alerts for important business events.',
    {icon:'🧪',tag:'test-'+Date.now()}
  );
  toast('Test notification sent!', 's');
}

function clearSentNotifications(){
  _sentNotifications.clear();
  sessionStorage.removeItem('rbo_sent_notifs');
  toast('Notification history cleared', 's');
}

// Enhanced sendPushNotification with logging
function sendPushNotification(title, body, options={}){
  // Log the notification
  if(!DB.notificationLog) DB.notificationLog=[];
  DB.notificationLog.unshift({
    ts:new Date().toLocaleString('en-GB'),
    title, body,
    tag:options.tag||''
  });
  if(DB.notificationLog.length>50) DB.notificationLog.pop();
  // Don't save to DB every time (too frequent) - just keep in memory
  return _sendPushNotificationCore(title, body, options);
}

// ── Goals Widget for Dashboard ──
function renderGoalsWidget(){
  const el=document.getElementById('goals-widget');
  if(!el) return;
  const goals=DB.goals||{};
  const txs=DB.tx||[];
  const thisMonth=new Date().toISOString().substring(0,7);
  const SALE_T=['Sale','Sales','Sales Invoice','Customer Sale','Warehouse Sale','Other Income','Interest Income']; // canonical: money receipts/advances are NOT revenue or cost
  const monthSales=txs.filter(t=>t.date&&t.date.startsWith(thisMonth)&&SALE_T.includes(t.type)).reduce((s,t)=>s+txAmt(t),0);
  const isDark=document.documentElement.getAttribute('data-theme')==='dark';
  const bg=isDark?'#1e293b':'#fff';
  const border=isDark?'#334155':'#e5e7eb';
  const textColor=isDark?'#f1f5f9':'#1a202c';
  const text2=isDark?'#94a3b8':'#6b7280';

  if(!goals.monthlySalesTarget){
    el.innerHTML=`<div style="text-align:center;padding:16px;color:${text2};font-size:12px;">
      <div style="font-size:24px;margin-bottom:6px;">🎯</div>
      No goals set yet.
      <button data-x-click="nav('goals')" style="display:block;margin:8px auto 0;padding:6px 14px;background:#16a34a;color:#fff;border:none;border-radius:6px;font-size:11px;font-weight:700;cursor:pointer;">Set Goals</button>
    </div>`;
    return;
  }

  const targets=[
    {label:'Sales',actual:monthSales,target:goals.monthlySalesTarget,color:'#16a34a'},
  ];
  if(goals.monthlyProfitTarget){
    const PURCH_T=['Purchase','Warehouse Purchase','Supplier Purchase']; // canonical: money receipts/advances are NOT revenue or cost
    const EXP_T=['Salary Payment','Office Rent','Other Expense'];
    const purch=txs.filter(t=>t.date&&t.date.startsWith(thisMonth)&&PURCH_T.includes(t.type)).reduce((s,t)=>s+txAmt(t),0);
    const exp=txs.filter(t=>t.date&&t.date.startsWith(thisMonth)&&EXP_T.includes(t.type)).reduce((s,t)=>s+txAmt(t),0);
    targets.push({label:'Profit',actual:monthSales-purch-exp,target:goals.monthlyProfitTarget,color:'#059669'});
  }

  el.innerHTML=`<div style="padding:4px 0;">
    ${targets.map(t=>{
      const pct=t.target>0?Math.min(100,Math.round(t.actual/t.target*100)):0;
      return `<div style="margin-bottom:10px;">
        <div style="display:flex;justify-content:space-between;font-size:11px;margin-bottom:4px;">
          <span style="font-weight:700;color:${textColor};">🎯 ${t.label} Goal</span>
          <span style="font-weight:700;color:${pct>=100?'#16a34a':pct>=70?'#d97706':'#dc2626'};">${pct}%</span>
        </div>
        <div style="background:#e5e7eb;border-radius:4px;height:8px;overflow:hidden;">
          <div style="width:${pct}%;height:100%;background:${pct>=100?'#16a34a':pct>=70?t.color:'#dc2626'};border-radius:4px;transition:width .5s;"></div>
        </div>
        <div style="display:flex;justify-content:space-between;font-size:10px;color:${text2};margin-top:2px;">
          <span>৳${t.actual.toLocaleString('en-IN',{minimumFractionDigits:0})}</span>
          <span>৳${t.target.toLocaleString('en-IN',{minimumFractionDigits:0})}</span>
        </div>
      </div>`;
    }).join('')}
    <button data-x-click="nav('goals')" style="width:100%;padding:7px;background:#f0fdf4;border:1px solid #bbf7d0;border-radius:8px;color:#16a34a;font-weight:700;cursor:pointer;font-size:11px;margin-top:4px;">View All Goals →</button>
  </div>`;
}

// Ctrl+S / Cmd+S keyboard shortcut for manual save
document.addEventListener('keydown', function(e) {
  if ((e.ctrlKey || e.metaKey) && e.key === 's') {
    e.preventDefault();
    manualSave();
  }
});


// ─────────────────────────────────────────────────────────
// FORMATTING
// ─────────────────────────────────────────────────────────
function f(n){ return '৳'+(parseFloat(n)||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2}); }

// Global pf() — number formatter used throughout (Bengali Taka format)
function pf(v){ return (parseFloat(v)||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2}); }
// Global pf2() alias
function pf2(v){ return (parseFloat(v)||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2}); }
function pfCompact(n){
  n=parseFloat(n)||0;
  if(n>=10000000) return (n/10000000).toFixed(2)+'Cr';
  if(n>=100000)   return (n/100000).toFixed(2)+'L';
  if(n>=1000)     return (n/1000).toFixed(1)+'K';
  return n.toLocaleString('en-IN');
}
function fn(n){ return (n||0).toLocaleString('en-IN'); }
function fd(n){ return n ? parseFloat(n).toLocaleString('en-IN',{minimumFractionDigits:0,maximumFractionDigits:2}) : '-'; }

