// ── Global back-button history stack ──
// Every navigation goes through nav(), so tracking history here (once)
// gives every page a working Back button with no per-page wiring needed.
window.__navHistory = window.__navHistory || [];
window.__navCurrent = window.__navCurrent || null;
function navBack(){
  if(window.__navHistory.length===0){ nav('dashboard'); return; }
  const prev = window.__navHistory.pop();
  window.__navSkipPush = true; // don't re-push the page we're going back to
  nav(prev);
}
function updateGlobalBackBtn(page){
  const btn = document.getElementById('globalBackBtn');
  if(!btn) return;
  btn.style.display = (page==='dashboard') ? 'none' : '';
}
function nav(page){
  const navKey = page;
  if(PAGE_ALIASES[page]) page = PAGE_ALIASES[page];
  if(window.__navSkipPush){
    window.__navSkipPush = false;
  } else if(window.__navCurrent && window.__navCurrent!==page){
    window.__navHistory.push(window.__navCurrent);
  }
  window.__navCurrent = page;
  updateGlobalBackBtn(page);
  let target = document.getElementById('pg-'+page);
  if(!target){
    console.warn('nav(): no page found for "'+page+'"');
    toast('That section isn\'t available yet.','e');
    return;
  }
  document.querySelectorAll('.page').forEach(p=>{
    p.classList.remove('active');
    // Some pages carry an inline style="display:none" which otherwise permanently
    // overrides the .page.active{display:block} CSS rule regardless of class state.
    if(p.style.display) p.style.display='none';
  });
  document.querySelectorAll('.nav-item').forEach(n=>n.classList.remove('active'));
  target.classList.add('active');
  target.style.display='block';
  document.querySelectorAll('.nav-item').forEach(n=>{
    const oc = n.getAttribute('onclick')||'';
    if(oc.includes("'"+navKey+"'") || oc.includes("'"+page+"'")) n.classList.add('active');
  });
  const pageTitle = page==='staffdash' ? `👥 ${(currentUser?.name||'Staff')}'s Dashboard` : (TITLES[navKey] || TITLES[page] || readableTitle(page));
  document.getElementById('pageTitle').textContent = pageTitle;
  render(page);
  // Close mobile nav after navigation
  closeMobileNav();
}

// ── D6: Mobile Nav Functions ──
function toggleMobileNav(){
  const sidebar = document.getElementById('sidebar');
  const overlay = document.getElementById('sidebarOverlay');
  const btn = document.getElementById('hamburgerBtn');
  const isOpen = sidebar.classList.contains('mobile-open');
  if(isOpen){
    sidebar.classList.remove('mobile-open');
    overlay.classList.remove('active');
    btn.classList.remove('open');
  } else {
    sidebar.classList.add('mobile-open');
    overlay.classList.add('active');
    btn.classList.add('open');
  }
}
function closeMobileNav(){
  const sidebar = document.getElementById('sidebar');
  const overlay = document.getElementById('sidebarOverlay');
  const btn = document.getElementById('hamburgerBtn');
  sidebar.classList.remove('mobile-open');
  overlay.classList.remove('active');
  if(btn) btn.classList.remove('open');
}
// Close mobile nav on Escape key
document.addEventListener('keydown', function(e){
  if(e.key === 'Escape') closeMobileNav();
});

function render(page){
  try{
    // Ensure page container exists
    let el=document.getElementById('pg-'+page);
    if(!el){
      // Create missing page container on the fly
      el=document.createElement('div');
      el.id='pg-'+page;
      el.className='page';
      el.style.display='none';
      const main=document.querySelector('.main')||document.body;
      main.appendChild(el);
    }
    _renderSwitch(page);
  }
  catch(err){
    console.error('render('+page+') failed:', err);
    const el=document.getElementById('pg-'+page);
    if(el){
      const isDark=document.documentElement.getAttribute('data-theme')==='dark';
      const bg=isDark?'#1e293b':'#fff';
      const border=isDark?'#7f1d1d':'#fecaca';
      const textColor=isDark?'#f1f5f9':'#1a202c';
      el.innerHTML=`<div style="max-width:640px;margin:40px auto;background:${bg};border:1.5px solid ${border};border-radius:14px;padding:28px;text-align:center;color:${textColor};">
        <div style="font-size:48px;margin-bottom:12px;">⚠️</div>
        <div style="font-size:18px;font-weight:800;color:#dc2626;margin-bottom:8px;">Page Error</div>
        <div style="font-size:13px;color:#6b7280;margin-bottom:12px;">The <strong>${page}</strong> page encountered an error loading your data.</div>
        <div style="font-size:11px;font-family:monospace;background:#fef2f2;color:#991b1b;border-radius:8px;padding:10px 14px;word-break:break-all;text-align:left;margin-bottom:16px;">${String(err&&err.message||err).replace(/</g,'&lt;')}</div>
        <div style="display:flex;gap:10px;justify-content:center;flex-wrap:wrap;">
          <button data-x-click="nav('${page}')" style="padding:9px 20px;background:#16a34a;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:13px;">🔄 Try Again</button>
          <button data-x-click="nav('dashboard')" style="padding:9px 20px;background:#2563eb;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:13px;">🏠 Dashboard</button>
          <button data-x-click="manualSave()" style="padding:9px 20px;background:#d97706;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:13px;">💾 Save Data</button>
        </div>
        <div style="font-size:11px;color:#9ca3af;margin-top:14px;">Your data is safe. This is a display error only.</div>
      </div>`;
    }
  }
}
function _renderSwitch(page){
  switch(page){
    case 'dashboard': renderDash(); renderAdvancedDashboard(); break;
