// ─────────────────────────────────────────────────────────
// COLORS
// ─────────────────────────────────────────────────────────
const COLORS = ['#3182ce','#38a169','#805ad5','#dd6b20','#e53e3e','#319795','#d69e2e','#667eea','#f6ad55','#68d391','#fc8181','#b794f4'];

function mkChart(id, type, labels, datasets, opts={}){
  const ctx = document.getElementById(id);
  if(!ctx) return;
  if(typeof Chart === 'undefined'){
    // Chart.js failed to load (offline, ad-blocker, CDN issue). Fail quietly so
    // the rest of the calling function (e.g. renderDash) still completes.
    if(ctx.tagName==='CANVAS' && ctx.parentElement){
      ctx.parentElement.innerHTML = '<div style="padding:20px;text-align:center;color:#9ca3af;font-size:12px;">Chart library unavailable (offline?)</div>';
    }
    return;
  }
  if(charts[id]){ try{ charts[id].destroy(); }catch(e){} delete charts[id]; }
  charts[id] = new Chart(ctx, {
    type, data:{labels, datasets},
    options:{
      responsive:true, maintainAspectRatio:false,
      plugins:{
        legend:{position:'bottom',labels:{font:{size:11},padding:10,usePointStyle:true}},
        tooltip:{callbacks:{label:ctx2=>{
          const v = ctx2.raw||0;
          return ` ${ctx2.label||ctx2.dataset.label}: ৳${v.toLocaleString('en-IN')}`;
        }}}
      },
      ...opts


    }
  });
}

// ─────────────────────────────────────────────────────────
// DASHBOARD
// ─────────────────────────────────────────────────────────
function renderDash(){
  const today = new Date().toISOString().split('T')[0];
  const txs = DB.tx||[];

  // ── KPI calculations ──────────────────────────────────
  const _pb       = partyBuckets(DB.customers||[]);
  const customers = _pb.custDueList;
  const partners  = DB.partners||[];
  const recv      = _pb.custDue;
  const partTotal = partners.reduce((s,p)=>s+(p.cap||0),0);
  const bankTotal = (DB.banks||[]).reduce((s,b)=>s+(b.bal||0),0);
  const assetTotal= (DB.assets||[]).reduce((s,a)=>s+(a.val||0),0);
  const adv       = _pb.suppAdv;
  const stock     = stockValue(DB.products);
  const net       = recv+partTotal+bankTotal+assetTotal+stock-adv;
  const health    = Math.min(100,Math.round((net/(net+adv+1))*100));

  set('k-recv', f(recv));
  set('k-recv-count', customers.length + ' customers with dues');
  set('k-part', f(partTotal));
  set('k-bank', f(bankTotal));
  set('k-bank-count', (DB.banks||[]).filter(b=>(b.bal||0)>0).length + ' active accounts');
  set('k-asset', f(assetTotal));
  set('k-adv', f(adv));
  // FIX 1/4: Update Warehouse Stock (k-stock) with live inventory value
  // stockValue() uses stockQtyOf(p)*unitCost(p) so out-of-stock items = ৳0
  const liveStockVal = (typeof stockValue === 'function') ? stockValue(DB.products||[]) : 0;
  set('k-stock', f(liveStockVal));
  set('k-net', f(net));
  set('k-health', health+'%');
  const hfill = document.getElementById('hfill');
  if(hfill){ hfill.style.width=health+'%'; hfill.style.background=health>70?'#38a169':health>40?'#d69e2e':'#e53e3e'; }

  // ── Parboiled Costing / DORB KPI (links to its own page; does not touch Inventory) ──
  if(typeof ensureProdCostingDefaults==='function'){
    ensureProdCostingDefaults();
    let _pbW=0,_pbC=0;
    (DB.pbBatchRows||[]).forEach(r=>{ const w=(r.bags||0)*50; _pbW+=w; _pbC+=w*(r.rate||0); });
    const _pbAvgR = _pbW>0 ? _pbC/_pbW : 0;
    const _costTotal = COST_ITEMS_DEF.reduce((s,ci)=>s+(DB.costSettings.cost[ci.key]||0),0);
    const _prodTotal = PROD_ITEMS_DEF.reduce((s,pi)=>s+(DB.costSettings.prod[pi.key]||0),0);
    set('k-pbrate', f(_pbAvgR+_costTotal+_prodTotal));
    set('k-dorb-count', (DB.dorbRows||[]).length+' DORB entries · '+(DB.locationRates||[]).length+' locations');
  }

  // ── Today strip ───────────────────────────────────────
  const todayTxs  = txs.filter(t=>t.date===today);
  const saleTypes = window.REVENUE_TX_TYPES;
  const purchTypes= window.COGS_TX_TYPES;
  const recvTypes = new Set(['Sales Receipt','Customer Collection','Customer Payment Received','Cash Received']);
  const todaySales= sumRevenue(todayTxs);
  const todayPurch= sumCogs(todayTxs);
  const todayRecv = todayTxs.filter(t=>recvTypes.has(String(t.type||'').trim())).reduce((s,t)=>s+(t.recv!=null?parseFloat(t.recv)||0:txAmt(t)),0);
  const overduePar= customers.filter(c=>(c.bal||0)>0).length;
  set('k-today-sales', f(todaySales));
  set('k-today-purch', f(todayPurch));
  set('k-today-recv',  f(todayRecv));
  set('k-overdue',     overduePar);

  // ── Top customers bar ─────────────────────────────────
  const topCust = [...customers].filter(c=>(c.bal||0)>0).sort((a,b)=>(b.bal||0)-(a.bal||0)).slice(0,6);
  const maxBal  = topCust[0]?.bal||1;
  const tcEl    = document.getElementById('dash-top-cust');
  if(tcEl) tcEl.innerHTML = topCust.length===0
    ? '<div style="text-align:center;color:#9ca3af;padding:20px;font-size:12px;">No customer dues</div>'
    : topCust.map((c,i)=>{
        const pct = Math.round(((c.bal||0)/maxBal)*100);
        const colors=['#16a34a','#2563eb','#7c3aed','#dc2626','#d97706','#0891b2'];
        return `<div style="margin-bottom:10px;">
          <div style="display:flex;justify-content:space-between;font-size:11px;margin-bottom:3px;">
            <span style="font-weight:600;color:#374151;">${i+1}. ${escHTML(c.name)}</span>
            <span style="font-weight:700;color:${colors[i%6]};">৳${pf(c.bal||0)}</span>
          </div>
          <div style="background:#f3f4f6;border-radius:4px;height:7px;">
            <div style="background:${colors[i%6]};width:${pct}%;height:7px;border-radius:4px;transition:width .5s;"></div>
          </div>
        </div>`;
      }).join('');

  // ── Overdue alerts ────────────────────────────────────
  const alertsBox  = document.getElementById('dash-alerts-box');
  const alertsList = document.getElementById('dash-alerts-list');
  const overdueList= customers.filter(c=>(c.bal||0)>0).sort((a,b)=>(b.bal||0)-(a.bal||0));
  if(alertsBox && alertsList){
    if(overdueList.length>0){
      alertsBox.style.display='block';
      alertsList.innerHTML = overdueList.slice(0,5).map(c=>`
        <div style="display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #fee2e2;">
          <div style="display:flex;align-items:center;gap:8px;">
            <span style="background:#dc2626;color:#fff;border-radius:50%;width:22px;height:22px;display:inline-flex;align-items:center;justify-content:center;font-size:10px;font-weight:800;">!</span>
            <span style="font-weight:600;font-size:12px;">${escHTML(c.name)}</span>
          </div>
          <div style="display:flex;align-items:center;gap:8px;">
            <span style="font-weight:700;color:#dc2626;font-size:13px;">৳${pf(c.bal||0)}</span>
            <button class="btn btn-xs" style="background:#dc2626;color:#fff;font-size:10px;" data-x-click="nav('customers')">View</button>
          </div>
        </div>`).join('');
      if(overdueList.length>5) alertsList.innerHTML += `<div style="text-align:center;padding:6px;font-size:11px;color:#6b7280;">+${overdueList.length-5} more overdue parties</div>`;
    } else {
      alertsBox.style.display='none';
    }
  }

  // ── Summary lists ─────────────────────────────────────
  set('s-cust', customers.filter(c=>(c.bal||0)>0).map(c=>
    `<div class="sum-row" data-x-click="viewPartyLedger('${escHTML(c.name).replace(/'/g,"\\'")}')" style="cursor:pointer;" title="Click to open ledger"><span class="sum-name">${escHTML(c.name)} →</span><span class="sum-val pos">${f(c.bal||0)}</span></div>`
  ).join('')+`<div class="sum-total"><span>Total</span><span class="text-pos">${f(recv)}</span></div>`);

  set('s-part', partners.map(p=>
    `<div class="sum-row" data-x-click="nav('partners')" style="cursor:pointer;" title="Click to open Partners"><span class="sum-name">${escHTML(p.name)} <span class="badge b-blue">${p.share||0}%</span> →</span><span class="sum-val pos">${f(p.cap||0)}</span></div>`
  ).join('')+`<div class="sum-total"><span>Total</span><span class="text-pos">${f(partTotal)}</span></div>`);

  set('s-bank', (DB.banks||[]).filter(b=>(b.bal||0)>0).map(b=>
    `<div class="sum-row" data-x-click="nav('banks')" style="cursor:pointer;" title="Click to open Bank Accounts"><span class="sum-name fs11">${escHTML(b.name)} →</span><span class="sum-val pos">${f(b.bal||0)}</span></div>`
  ).join('')+`<div class="sum-total"><span>Total</span><span class="text-pos">${f(bankTotal)}</span></div>`);

  // ── Recent transactions ───────────────────────────────
  const recent = [...txs].reverse().slice(0,10);
  set('t-recent', recent.length===0
    ? `<tr><td colspan="14" style="text-align:center;color:var(--gray-400);padding:24px;">No transactions yet. Click ➕ New Transaction to start!</td></tr>`
    : recent.map(t=>`<tr>
        <td>${t.date}</td>
        <td class="fs11">${t.inv||'-'}</td>
        <td><span class="badge ${txBadge(t.type)}">${t.type}</span></td>
        <td><strong>${escHTML(t.party ||'-')}</strong></td>
        <td class="fs11">${escHTML(t.prod ||'-')}</td>
        <td class="td-num">${t.qty?fn(t.qty):'-'}</td>
        <td class="td-num">${t.rate?f(t.rate):'-'}</td>
        <td class="td-num ${txAmt(t)>=0?'text-pos':'text-neg'}">${f(txAmt(t))}</td>
        <td class="td-num">${t.paid?f(t.paid):'-'}</td>
        <td class="td-num">${t.recv?f(t.recv):'-'}</td>
        <td class="td-num ${t.due>0?'text-neg':''}">${t.due?f(t.due):'-'}</td>
        <td><span class="badge b-gray">${t.mode||'-'}</span></td>
        <td class="fs11">${t.acc?bankNameToDisplay(t.acc):'-'}</td>
        <td class="fs11">${escHTML(t.rem ||'-')}</td>
      </tr>`).join('')
  );

  // ── Charts ────────────────────────────────────────────
  const custData = customers.filter(c=>(c.bal||0)>0);
  mkChart('cCust','doughnut',custData.map(c=>c.name),[{data:custData.map(c=>c.bal||0),backgroundColor:COLORS,borderWidth:2,borderColor:'#fff'}]);
  mkChart('cPart','pie',partners.map(p=>p.name),[{data:partners.map(p=>p.cap||0),backgroundColor:COLORS,borderWidth:2,borderColor:'#fff'}]);

  const bankPos = (DB.banks||[]).filter(b=>(b.bal||0)>0);
  mkChart('cBank','bar',bankPos.map(b=>b.name.length>18?b.name.slice(0,18)+'…':b.name),[{
    label:'Balance',data:bankPos.map(b=>b.bal||0),
    backgroundColor:COLORS,borderRadius:6
  }],{plugins:{legend:{display:false}},scales:{y:{ticks:{callback:v=>'৳'+(v/1000).toFixed(0)+'K'}},x:{ticks:{font:{size:10}}}}});

  mkChart('cAsset','doughnut',
    ['Receivables','Partner Funds','Bank Balance','Fixed Assets','Stock'],
    [{data:[recv,partTotal,bankTotal,assetTotal,stock],backgroundColor:COLORS,borderWidth:2,borderColor:'#fff'}]);

  // ── Monthly trend chart (last 6 months) ───────────────
  const now = new Date();
  const months = [];
  const salesByMonth = [];
  const purchByMonth = [];
  for(let i=5;i>=0;i--){
    const d = new Date(now.getFullYear(), now.getMonth()-i, 1);
    const ym = d.toISOString().slice(0,7); // YYYY-MM
    const lbl = d.toLocaleString('default',{month:'short',year:'2-digit'});
    months.push(lbl);
    const mTxs = txs.filter(t=>(t.date||'').startsWith(ym));
    salesByMonth.push(mTxs.filter(t=>saleTypes.has(t.type)).reduce((s,t)=>s+txAmt(t),0));
    purchByMonth.push(mTxs.filter(t=>purchTypes.has(t.type)).reduce((s,t)=>s+txAmt(t),0));
  }
  mkChart('cMonthly','bar',months,[
    {label:'Sales',data:salesByMonth,backgroundColor:'rgba(22,163,74,0.8)',borderRadius:5,borderSkipped:false},
    {label:'Purchase',data:purchByMonth,backgroundColor:'rgba(37,99,235,0.7)',borderRadius:5,borderSkipped:false}
  ],{
    plugins:{legend:{position:'top',labels:{usePointStyle:true,padding:12,font:{size:11}}}},
    scales:{
      y:{ticks:{callback:v=>'৳'+(v>=1000?(v/1000).toFixed(0)+'K':v)},grid:{color:'rgba(0,0,0,.05)'}},
      x:{grid:{display:false}}
    }
  });

  try{ if(typeof ayanShowDupBanner==='function') ayanShowDupBanner(); }catch(e){}
}


function txAccCell(t){
  const acc = t.acc ? bankNameToDisplay(t.acc) : '-';
  if(!Array.isArray(t.payAccounts) || !t.payAccounts.length) return acc;
  const detail = t.payAccounts.map(p=>`${bankNameToDisplay(p.acc)}: ৳${pf(p.amt)}`).join(', ').replace(/"/g,'&quot;');
  return `${acc} <span style="font-size:9px;color:#7c3aed;font-weight:700;" title="${detail}">(split × ${t.payAccounts.length})</span>`;
}

function txBadge(t){
  if(['Sale','Sales Receipt','Other Income','Cash Received','Interest Income'].includes(t)) return 'b-green';
  if(['Purchase','Purchase Payment','Salary Payment','Other Expense','Cash Payment'].includes(t)) return 'b-red';
  if(['Bank Deposit','Bank Transfer','Bank Withdrawal'].includes(t)) return 'b-blue';
  if(['Partner Capital','Partner Withdrawal'].includes(t)) return 'b-purple';
  if(['Sales Advance','Purchase Advance'].includes(t)) return 'b-orange';
  return 'b-gray';
}

function renderTx(data){
  let txs = data || DB.tx||[];
  if(txF.search) txs=txs.filter(t=>(t.party||'').toLowerCase().includes(txF.search)||(t.type||'').toLowerCase().includes(txF.search)||(t.prod||'').toLowerCase().includes(txF.search)||(t.inv||'').toLowerCase().includes(txF.search));
  if(txF.type) txs=txs.filter(t=>t.type===txF.type);
  if(txF.mode) txs=txs.filter(t=>t.mode===txF.mode);
  if(txF.partyType) txs=txs.filter(t=>t.ptype===txF.partyType);
  if(txF.dateFrom) txs=txs.filter(t=>_dk(t.date)>=_dk(txF.dateFrom));
  if(txF.dateTo)   txs=txs.filter(t=>_dk(t.date)<=_dk(txF.dateTo));

  const tbody = document.getElementById('t-tx');
  const empty = document.getElementById('tx-empty');
  const footer = document.getElementById('tx-footer');

  if(txs.length===0){tbody.innerHTML='';empty.style.display='block';footer.textContent='';return;}
  empty.style.display='none';

  const totalAmt = txs.reduce((s,t)=>s+txAmt(t),0);
  const _shownCount = Math.min(_txShown, txs.length);
  footer.innerHTML = `Showing <strong>${_shownCount===txs.length?txs.length:_shownCount+' of '+txs.length}</strong> transactions | Total Amount: <strong class="${totalAmt>=0?'text-pos':'text-neg'}">${f(totalAmt)}</strong>`;

  const sales = txs.filter(isRevenueTx).reduce((s,t)=>s+txAmt(t),0);
  const purchases = txs.filter(isCogsTx).reduce((s,t)=>s+txAmt(t),0);
  const pendingApprovalCount = txs.filter(t=>t.approvalStatus==='Pending').length;
  set('tx-stats',`
    <div class="info-pill"><span class="dot" style="background:var(--success)"></span>Sales: <strong>${f(sales)}</strong></div>
    <div class="info-pill"><span class="dot" style="background:var(--danger)"></span>Purchases: <strong>${f(purchases)}</strong></div>
    <div class="info-pill"><span class="dot" style="background:var(--accent)"></span>Total Entries: <strong>${txs.length}</strong></div>
    ${pendingApprovalCount>0?`<div class="info-pill"><span class="dot" style="background:#b45309"></span>⏳ Pending Approval: <strong>${pendingApprovalCount}</strong></div>`:''}
  `);

  /* FIX (Transactions page took 24s to open with 10,000 rows): this drew
     EVERY matching row - 37 columns and 5 buttons each, ~47 DOM elements per
     transaction - in one blocking string build. It now draws the newest
     TX_PAGE_SIZE rows and offers "Show more". Every total above is still
     computed over the COMPLETE filtered set, so no figure on screen changes. */
  const _ordered = [...txs].reverse();
  const _limit   = Math.min(_txShown, _ordered.length);
  if(tbody) tbody.innerHTML = _ordered.slice(0,_limit).map((t,i)=>`<tr>
    <td class="text-muted fs11">${txs.length-i}</td>
    <td class="fs11">${t.po||'-'}</td>
    <td class="fs11">${t.inv||'-'}</td>
    <td class="fs11">${escHTML(t.grn||'-')}</td>
    <td class="fs11">${escHTML(t.challan||'-')}</td>
    <td>${t.date||'-'}</td>
    <td>${t.deliverydate||'-'}</td>
    <td>${t.paydate||'-'}</td>
    <td><span class="badge ${txBadge(t.type)}">${t.type}</span>${t.approvalStatus==='Pending'?' <span title="Awaiting Admin/Owner approval — not yet posted to any balance" style="background:#fef3c7;color:#b45309;border-radius:6px;padding:1px 6px;font-size:9px;font-weight:800;">⏳ PENDING</span>':''}</td>
    <td><strong>${escHTML(t.party ||'-')}</strong></td>
    <td><span class="badge b-gray fs11">${t.ptype||'-'}</span></td>
    <td class="fs11">${[t.prod,t.loc].filter(Boolean).join(' / ')||'-'}</td>
    <td class="fs11">${escHTML(t.truck ||'-')}</td>
    <td class="fs11">${t.bagtype||'-'}</td>
    <td class="td-num">${t.oilPct?fd(t.oilPct):'-'}</td>
    <td class="td-num">${t.bagqty?fn(t.bagqty):'-'}</td>
    <td class="td-num">${t.grosswt?fn(t.grosswt):'-'}</td>
    <td class="td-num">${t.wt?fn(t.wt):'-'}</td>
    <td class="td-num">${t.rate?fd(t.rate):'-'}</td>
    <td class="td-num ${txAmt(t)>=0?'text-pos':'text-neg'}">${f(txAmt(t))}</td>
    <td class="td-num">${t.totalOil?fn(t.totalOil):'-'}</td>
    <td class="fs11">${t.supplierBankInfo||'-'}</td>
    <td><span class="badge b-gray">${t.mode||'-'}</span></td>
    <td class="fs11">${txAccCell(t)}</td>
    <td class="td-num">${t.paid?f(t.paid):'-'}</td>
    <td class="td-num">${t.recv?f(t.recv):'-'}</td>
    <td class="td-num ${t.due>0?'text-neg':''}">${t.due?f(t.due):'-'}</td>
    <td class="td-num">${t.paid2?f(t.paid2):'-'}</td>
    <td class="td-num">${t.due2?f(t.due2):'-'}</td>
    <td class="td-num">${t.agentAcost?f(t.agentAcost):'-'}</td>
    <td class="td-num">${t.agentBcost?f(t.agentBcost):'-'}</td>
    <td class="td-num">${t.qc?f(t.qc):'-'}</td>
    <td class="td-num">${t.unload?f(t.unload):'-'}</td>
    <td class="td-num">${(t.othercost||t.othercost2)?f((t.othercost||0)+(t.othercost2||0)):'-'}</td>
    <td class="td-num text-neg">${t.totalcost?f(t.totalcost):'-'}</td>
    <td class="fs11">${escHTML(t.rem ||'-')}</td>
    <td style="white-space:nowrap;">${(t.approvalStatus==='Pending'&&typeof isTopApprover==='function'&&isTopApprover())?`<button class="btn btn-xs btn-icon" style="background:#16a34a;color:#fff;margin-right:2px;" data-x-click="approveTx(${t.id})" title="Approve — posts this to the balance">✅</button>`:''}<button class="btn btn-xs btn-icon" style="background:#2563eb;color:#fff;margin-right:2px;" data-x-click="getFinanceFromTx(${t.id})" title="Get Finance (City Bank)">🏦</button><button class="btn btn-xs btn-icon" style="background:#1a3a6b;color:#fff;margin-right:2px;" data-x-click="openModal(${t.id})" title="Edit">✏️</button><button class="btn btn-xs btn-icon" style="background:#f5a623;color:#000;margin-right:2px;" data-x-click="printTransaction(${t.id})" title="Print Voucher">🖨️</button><button class="btn btn-danger btn-xs btn-icon" data-x-click="delTx(${t.id})" title="Delete">🗑</button></td>
  </tr>`).join('')
    + (_ordered.length>_limit
        ? `<tr><td colspan="37" style="padding:14px;text-align:center;background:#f9fafb;">`
          + `<button class="btn btn-xs" style="background:#16a34a;color:#fff;padding:7px 20px;font-weight:700;cursor:pointer;" data-x-click="txShowMore()">Show ${Math.min(TX_PAGE_SIZE,_ordered.length-_limit)} more</button>`
          + `<span style="font-size:11px;color:#6b7280;margin-left:10px;">${_ordered.length-_limit} older not shown</span>`
          + `</td></tr>`
        : '');
}

/* Paging state for the Transactions table. TX_PAGE_SIZE rows are drawn at a
   time, newest first; any change of filter starts again from the newest page.
   Raise TX_PAGE_SIZE if you would rather see more per click. */
var TX_PAGE_SIZE = 200;
var _txShown = TX_PAGE_SIZE;
function txShowMore(){ _txShown += TX_PAGE_SIZE; renderTx(); }
function txResetPaging(){ _txShown = TX_PAGE_SIZE; }

/* FIX (typing in the Transactions search froze the page): this ran a FULL
   table rebuild on every keystroke, so a six-letter name meant six complete
   re-renders - measured at 3.9s of blocked main thread with 10,000 rows.
   The filter value is stored immediately (nothing is ever lost) and the
   redraw is coalesced onto the last keystroke. txSearchNow() redraws
   synchronously if anything ever needs that. */
var _txSearchTimer=null;
function txSearchNow(v){ if(v!=null) txF.search=String(v).toLowerCase(); txResetPaging(); renderTx(); }
function txSearch(v){
  txF.search=String(v==null?'':v).toLowerCase();
  txResetPaging();
  clearTimeout(_txSearchTimer);
  _txSearchTimer=setTimeout(function(){ try{ renderTx(); }catch(e){ console.error('[txSearch]',e); } },250);
}
function clearTxDates(){
  txF.dateFrom=''; txF.dateTo=''; txResetPaging();
  const df=document.getElementById('txDateFrom');
  const dt=document.getElementById('txDateTo');
  if(df) df.value='';
  if(dt) dt.value='';
  renderTx();
}
function txFilt(k,v){txF[k]=v;txResetPaging();renderTx();}

// Auto-calculations
function calcTx(){
  const q=parseFloat(document.getElementById('tx-qty').value)||0;
  const r=parseFloat(document.getElementById('tx-rate').value)||0;
  if(q&&r){
    document.getElementById('tx-amt').value=(q*r).toFixed(2);
    calcDue();
    calcTotalCost();
  }
}

function calcTotalOil(){
  // FIX OIL: Total Oil = NET WEIGHT (tx-wt) × Oil% / 100
  // Net Weight is the correct base — not Gross Weight
  const netWt = parseFloat(document.getElementById('tx-wt')?.value) || 0;
  const grossWt = parseFloat(document.getElementById('tx-grosswt')?.value) || 0;
  // Use Net Weight if available, else fall back to Gross Weight
  const wt = netWt > 0 ? netWt : grossWt;
  const pct = parseFloat(document.getElementById('tx-oilpct')?.value) || 0;
  const oilEl = document.getElementById('tx-totaloil');
  if(wt && pct && oilEl){
    const totalOil = (wt * pct / 100);
    oilEl.value = totalOil.toFixed(3);
    // Show hint: NET WEIGHT × Oil%
    const hint = document.getElementById('tx-totaloil-hint');
    if(hint) hint.textContent = (netWt>0?'Net':'Gross')+' Wt '+wt.toFixed(2)+' × '+pct+'% = '+totalOil.toFixed(3);
  } else if(oilEl && !pct){
    oilEl.value = '';
  }
}

// VAT / sales tax applies to sale-side transactions ONLY.
const SALE_TAX_TYPES=['sale','customer sale','warehouse sale'];
function isSaleType(t){ return SALE_TAX_TYPES.includes(String(t||'').trim().toLowerCase()); }
window.isSaleType=isSaleType;
function calcSalesTax(){
  const typeEl=document.getElementById('tx-type');
  const type=(typeEl?.value||'').toLowerCase();
  const taxEnabled=DB.settings?.salesTaxEnabled!==false;
  const isSale=taxEnabled&&isSaleType(type);

  const taxSection=document.getElementById('tx-tax-section');
  const netSection=document.getElementById('tx-net-section');
  const taxDisplay=document.getElementById('tx-tax-pct-display');
  const taxAmtEl=document.getElementById('tx-tax-amt');
  const netAmtEl=document.getElementById('tx-net-amt');

  if(!isSale){
    if(taxSection) taxSection.style.display='none';
    if(netSection) netSection.style.display='none';
    if(taxAmtEl) taxAmtEl.value='';
    if(netAmtEl) netAmtEl.value='';
    return;
  }

  const _tr=parseFloat(DB.settings?.salesTaxRate);
  const taxRate=isFinite(_tr)?_tr:0.05;
  if(taxDisplay) taxDisplay.textContent=taxRate;

  const amt=parseFloat(document.getElementById('tx-amt')?.value)||0;
  if(amt<=0){
    if(taxSection) taxSection.style.display='none';
    if(netSection) netSection.style.display='none';
    return;
  }

  var taxAmt=parseFloat((amt*taxRate/100).toFixed(2));
  /* Keep whatever was typed by hand on this entry. */
  if(taxAmtEl && taxAmtEl.dataset.userEdited==='1' && String(taxAmtEl.value||'').trim()!==''){
    taxAmt=parseFloat(taxAmtEl.value)||0;
  }
  const netAmt=parseFloat((amt-taxAmt).toFixed(2));

  if(taxAmtEl && taxAmtEl.dataset.userEdited!=='1') taxAmtEl.value=taxAmt.toFixed(2);
  if(netAmtEl) netAmtEl.value=netAmt.toFixed(2);
  if(taxSection) taxSection.style.display='grid';
  if(netSection) netSection.style.display='grid';
}

/* A tax figure typed by hand is kept — calcSalesTax() must not overwrite it,
   and the net payable and the due have to follow what was actually typed. */
function ayanTaxEdited(){
  var el=document.getElementById('tx-tax-amt');
  if(el) el.dataset.userEdited='1';
  try{
    var amt=parseFloat(document.getElementById('tx-amt')?.value)||0;
    var tax=parseFloat(el&&el.value)||0;
    var net=document.getElementById('tx-net-amt');
    if(net) net.value=(amt-tax).toFixed(2);
  }catch(e){}
  try{ calcDue(); }catch(e){}
}

function calcDue(){
  const amt=parseFloat(document.getElementById('tx-amt')?.value)||0;
  const paid=parseFloat(document.getElementById('tx-paid')?.value)||0;
  const recv=parseFloat(document.getElementById('tx-recv')?.value)||0;
  // Use net amount (after tax) for due calculation if tax applies
  const netAmtRaw=document.getElementById('tx-net-amt')?.value;
  const netAmt=(netAmtRaw!==undefined&&netAmtRaw!=='')?parseFloat(netAmtRaw)||0:0;
  const effectiveAmt=netAmt>0?netAmt:amt;
  /* FIX: rounding the tax and the net amount separately left a fraction of
     a taka behind, so an invoice the customer had paid in full still
     reported a due of −৳0.10. Anything under half a taka is treated as
     settled. */
  let due=effectiveAmt-paid-recv;
  if(Math.abs(due)<0.5) due=0;
  due=parseFloat(due.toFixed(2));
  const dueEl=document.getElementById('tx-due');
  if(dueEl) dueEl.value=due.toFixed(2);
  try{ calcAdvanceControl(); }catch(e){}
  return due;
}





// ─────────────────────────────────────────────────────────────────────────────
// D2: AUTO-BALANCE ENGINE
// Updates customer/bank/partner balances automatically when a transaction is
// saved or deleted.  dir = +1 (apply) or -1 (reverse).
// ─────────────────────────────────────────────────────────────────────────────
// ── AUTO CATEGORY ─────────────────────────────────────────
function autoCategory(type){
  const t=(type||'').toLowerCase();
  if(['sale','sales return','sales receipt','sales advance','other income','interest income','tender refund','warehouse sale'].includes(t)) return 'Income';
  if(['purchase','purchase return','purchase payment','purchase advance','warehouse purchase'].includes(t)) return 'Purchase';
  if(['salary payment','employee advance','employee loan','office rent','electricity bill','internet bill','telephone bill','fuel expense','transport cost','loading charge','unloading charge','commission payment','brokerage fee','legal fee','audit fee','insurance premium','tax payment','government fee','license fee','maintenance cost','repair expense','stationery purchase','other expense','interest expense','tender payment','tender advance','tender cost','bank charge'].includes(t)) return 'Expense';
  if(['bank deposit','bank withdrawal','bank transfer','bkash deposit','bkash withdrawal','bkash cash out','bkash transfer'].includes(t)) return 'Transfer';
  if(['partner capital','partner withdrawal','partner profit share'].includes(t)) return 'Partner';
  if(['opening balance','opening partner fund','opening fixed asset'].includes(t)) return 'Opening';
  if(['tender payment','tender advance','tender cost','tender refund'].includes(t)) return 'Tender';
  return 'Other';
}

// ── CALC TX COST (for Sales transactions) ─────────────────
function calcTxCost(){
  const qty   = parseFloat(document.getElementById('tx-qty')?.value)||0;
  const agAc  = parseFloat(document.getElementById('tx-agentAcost')?.value)||0;
  const agBc  = parseFloat(document.getElementById('tx-agentBcost')?.value)||0;
  const qc    = parseFloat(document.getElementById('tx-qc')?.value)||0;
  const unl   = parseFloat(document.getElementById('tx-unload')?.value)||0;
  const oth   = parseFloat(document.getElementById('tx-othercost')?.value)||0;
  const oth2  = parseFloat(document.getElementById('tx-othercost2')?.value)||0;
  const total = agAc + agBc + qc + unl + oth + oth2;
  const el = document.getElementById('tx-totalcost');
  if(el) el.value = total.toFixed(2);
  // Also auto-calc agent costs from rates if qty given
  const rA = DB.costRates?.agentA||0;
  const rB = DB.costRates?.agentB||0;
  const rQ = DB.costRates?.qc||0;
  const rU = DB.costRates?.unload||0;
  if(qty>0){
    const elA = document.getElementById('tx-agentAcost');
    const elB = document.getElementById('tx-agentBcost');
    const elQ = document.getElementById('tx-qc');
    const elU = document.getElementById('tx-unload');
    let _filled=false;
    if(elA && !elA.value){ elA.value = (qty*rA).toFixed(2); _filled=true; }
    if(elB && !elB.value){ elB.value = (qty*rB).toFixed(2); _filled=true; }
    if(elQ && !elQ.value){ elQ.value = (qty*rQ).toFixed(2); _filled=true; }
    if(elU && !elU.value){
      const _bt=document.getElementById('tx-bagtype')?.value||'';
      const _bags=parseFloat(document.getElementById('tx-bagqty')?.value)||0;
      elU.value = ayanUnloadCost(_bt,_bags,qty).toFixed(2); _filled=true;
    }
    void rU;
    /* FIX: this recursed unconditionally; it now only recalculates when a
       field was actually filled in, so the totals settle in one pass. */
    if(_filled) calcTxCost(); // recalc after filling
  }
}

// ── AUTO-FILL AGENT COSTS ON QTY CHANGE ───────────────────
function onTxQtyChange(){
  const qty = parseFloat(document.getElementById('tx-qty')?.value)||0;
  if(qty<=0) return;
  const rA = DB.costRates?.agentA||0.25;
  const rB = DB.costRates?.agentB||0.30;
  const rQ = DB.costRates?.qc||0.10;
  const rU = DB.costRates?.unload||3.00;
  const elA = document.getElementById('tx-agentAcost');
  const elB = document.getElementById('tx-agentBcost');
  const elQ = document.getElementById('tx-qc');
  const elU = document.getElementById('tx-unload');
  if(elA) elA.value = (qty*rA).toFixed(2);
  if(elB) elB.value = (qty*rB).toFixed(2);
  if(elQ) elQ.value = (qty*rQ).toFixed(2);
  if(elU){
    const bt=document.getElementById('tx-bagtype')?.value||'';
    const bags=parseFloat(document.getElementById('tx-bagqty')?.value)||0;
    elU.value = ayanUnloadCost(bt, bags, qty).toFixed(2);
  }
  void rU;
  calcTxCost();
}

function applyTxBalance(tx, dir){
  /* FIX (same defect, existing records): rows already saved with amount = 0
     and the figure only in `recv` must still post, or reloading the file
     would leave the money missing for ever. For money-in types the received
     figure stands in for a blank amount. */
  var _rawAmt = parseFloat(tx.amount)||0;
  try{
    if(!_rawAmt && window.AYAN_MONEY_IN_AMT && window.AYAN_MONEY_IN_AMT.has(String(tx.type||'').toLowerCase()))
      _rawAmt = parseFloat(tx.recv)||0;
  }catch(e){}
  const amt  = _rawAmt * dir;
  const paid = (parseFloat(tx.paid)||0)   * dir;
  const recv = (parseFloat(tx.recv)||0)   * dir;
  const type = (tx.type||'').toLowerCase();
  const acc  = (tx.acc||'').trim();
  const acc2 = (tx.acc2||'').trim();
  const party= (tx.party||'').trim();
  const ptype= (tx.ptype||'').toLowerCase();

  function adjBank(name, delta){
    if(!name) return;
    /* FIX (duplicate fields): banks, parties and partners each store the
       same figure under two names (bal/balance, cap/capital). Only one was
       updated, so screens reading the other name — Balance Check, for one —
       kept reporting the figure from before the entry. Both are written. */
    const b=(DB.banks||[]).find(b=>b.name===name);
    /* FIX (2026-08-29): the mirror was only updated `if(...!==undefined)`.
       On a record where the mirror was missing it was therefore never
       created — and once some later screen created it at 0, it began
       accumulating deltas from 0 while the real field carried the true
       figure. The two could then never converge. The mirror is now always
       written, and is kept equal to the primary rather than accumulated
       separately, so a missing or stale mirror self-heals on the next
       posting instead of drifting further. */
    if(b){ b.bal=(b.bal||0)+delta; b.balance=b.bal; }
  }
  function adjParty(name, delta){
    if(!name) return;
    const c=(DB.customers||[]).find(c=>c.name===name);
    if(c){ c.bal=(c.bal||0)+delta; c.balance=c.bal; }
  }
  function adjPartner(name, delta){
    if(!name) return;
    const p=(DB.partners||[]).find(p=>p.name===name);
    if(p){ p.cap=(p.cap||0)+delta; p.capital=p.cap; }
  }

  /* FIX (2026-08-20): this switch only ever matched the literal type string
     'sale' — every other name for the exact same transaction that the New
     Transaction dropdown itself offers ('Customer Sale', 'Warehouse Sale',
     which are literally in window.REVENUE_TX_TYPES and treated as revenue
     everywhere else in the app) fell through to nothing at all: no change
     to the customer's balance, and — the concrete complaint this was found
     from — money received (tx.recv) never got deposited into the bank,
     silently. Same story on the receiving/collecting side: 'Customer
     Collection', 'Customer Payment Received' and 'Advance from Customer'
     are all real, prominent options in the same dropdown for the single
     most common act in this business — collecting a payment from a
     customer — and none of them were wired to touch the bank either. The
     mirrored purchase-side names ('Advance to Supplier', 'Supplier
     Advance', 'Supplier Refund') had the identical gap. Every one of these
     is now mapped to the same math as its already-working sibling. */
  // ── SALE ──
  if(type==='sale'||type==='customer sale'||type==='warehouse sale'){
    adjParty(party, amt);
    if(recv) adjParty(party, -recv);
    /* FIX (withholding tax): the 0.5% sales tax is deducted at source — the
       buyer keeps it back and pays the invoice less the tax, then deposits
       it against our TIN. It is not money the customer still owes us, but
       the receivable was raised on the full invoice and only the cash
       received was taken off, so 0.5% of every sale stayed behind as a
       permanent fake due. The invoice would read "fully settled" while the
       customer's ledger showed a balance. The withheld amount is now
       cleared from the receivable, exactly as the cash is. */
    var saleTax = (parseFloat(tx.salesTaxAmt)||0) * dir;
    if(saleTax) adjParty(party, -saleTax);
    if(recv && acc) adjBank(acc, recv);
    // FIX paid2/acc2: second payment (e.g. truck rent) via second bank account
    const paid2_s = (parseFloat(tx.paid2)||0) * dir;
    if(paid2_s && acc2) adjBank(acc2, -paid2_s);
  }
  // ── SALES RECEIPT / CUSTOMER COLLECTION ──
  else if(type==='sales receipt'||type==='customer collection'||type==='customer payment received'){
    adjParty(party, -amt);
    if(acc) adjBank(acc, amt);
  }
  // ── SALES ADVANCE ──
  else if(type==='sales advance'||type==='advance from customer'){
    adjParty(party, -amt);
    if(acc) adjBank(acc, amt);
  }
  // ── SALES RETURN ──
  else if(type==='sales return'){
    adjParty(party, -amt);
    if(acc) adjBank(acc, -amt);
  }
  // ── CUSTOMER DUE (records a receivable with no money changing hands) ──
  else if(type==='customer due'){
    adjParty(party, amt);
  }
  // ── PURCHASE ──
  else if(type==='purchase'||type==='warehouse purchase'||type==='supplier purchase'){
    adjParty(party, -amt);
    if(paid) adjParty(party, paid);
    if(paid && acc) adjBank(acc, -paid);
    // FIX paid2/acc2: second payment (e.g. truck rent) via second bank account
    const paid2_p = (parseFloat(tx.paid2)||0) * dir;
    if(paid2_p && acc2) adjBank(acc2, -paid2_p);
  }
  // ── PURCHASE PAYMENT ──
  else if(type==='purchase payment'||type==='supplier payment'){
    adjParty(party, amt);
    if(acc) adjBank(acc, -amt);
  }
  // ── PURCHASE ADVANCE ──
  else if(type==='purchase advance'||type==='advance to supplier'||type==='supplier advance'){
    adjParty(party, amt);
    if(acc) adjBank(acc, -amt);
  }
  // ── PURCHASE RETURN / SUPPLIER REFUND ──
  else if(type==='purchase return'||type==='supplier refund'){
    adjParty(party, amt);
    if(acc) adjBank(acc, amt);
  }
  // ── SUPPLIER DUE (records a payable with no money changing hands) ──
  else if(type==='supplier due'){
    adjParty(party, -amt);
  }
  // ── BANK DEPOSIT ──
  else if(type==='bank deposit'){
    if(acc) adjBank(acc, amt);
  }
  // ── BANK WITHDRAWAL ──
  else if(type==='bank withdrawal'){
    if(acc) adjBank(acc, -amt);
  }
  // ── BANK TRANSFER / INTER TRANSFER ──
  /* FIX: the New Transaction dropdown offers 'Inter Bank Transfer',
     'Inter-Account Transfer' and 'Transfer (Internal)' as well, and none of
     them were listed here — so moving money between your own accounts did
     nothing at all when saved. It only appeared after the next page load,
     when the rebuild (which does know those names) put it right. Between
     saving and reloading, both accounts showed the wrong balance. */
  else if(type==='bank transfer'||type==='inter transfer'||type==='inter bank transfer'
       || type==='inter-account transfer'||type==='transfer (internal)'||type==='transfer'){
    if(acc)  adjBank(acc,  -amt);
    if(acc2) adjBank(acc2,  amt);
  }
  // ── BANK CHARGE ──
  else if(type==='bank charge'){
    if(acc) adjBank(acc, -amt);
  }
  // ── BKASH ──
  else if(type==='bkash deposit'||type==='bkash receive'||type==='bkash receive from agent'){
    if(acc) adjBank(acc, amt);
    // FIX 3: If party is specified (supplier/customer paying via bKash),
    // update their balance: receiving money from them reduces their due
    if(party){
      // Supplier paying us via bKash → supplier due decreases (bal goes toward 0)
      // Customer paying us via bKash → customer due decreases
      adjParty(party, -amt);
    }
  }
  else if(type==='bkash withdrawal'||type==='bkash cash out'||type==='bkash payment paid'){
    if(acc) adjBank(acc, -amt);
  }
  else if(type==='bkash transfer'){
    if(acc)  adjBank(acc,  -amt);
    if(acc2) adjBank(acc2,  amt);
  }
  // ── PARTNER CAPITAL / FUND ──
  else if(type==='partner capital'||type==='partner fund'||type==='opening partner fund'){
    adjPartner(party, amt);
    if(acc) adjBank(acc, amt);
  }
  // ── PARTNER WITHDRAWAL ──
  else if(type==='partner withdrawal'){
    adjPartner(party, -amt);
    if(acc) adjBank(acc, -amt);
  }
  // ── PARTNER PROFIT SHARE ──
  else if(type==='partner profit share'){
    adjPartner(party, amt);
  }
  // ── CASH RECEIVED ──
  else if(type==='cash received'){
    adjParty(party, -amt);
    if(acc) adjBank(acc, amt);
  }
  // ── CASH PAYMENT ──
  else if(type==='cash payment'){
    adjParty(party, amt);
    if(acc) adjBank(acc, -amt);
  }
  // ── SALARY PAYMENT ──
  else if(type==='salary payment'){
    if(acc) adjBank(acc, -amt);
  }
  // ── EMPLOYEE ADVANCE / LOAN ──
  else if(type==='employee advance'||type==='employee loan'){
    adjParty(party, amt);
    if(acc) adjBank(acc, -amt);
  }
  // ── OPENING BALANCE ──
  else if(type==='opening balance'){
    if(ptype==='customer') adjParty(party, amt);
    else if(ptype==='supplier') adjParty(party, -amt);
    else if(ptype==='partner') adjPartner(party, amt);
    else if(acc) adjBank(acc, amt);
  }
  // ── OPENING BANK BALANCE ──
  else if(type==='opening bank balance'){
    if(acc) adjBank(acc, amt);
  }
  // ── FIXED ASSETS ──
  /* FIX (over-debited by the unpaid portion): these two used the full
     invoice amount, not what was actually paid/received — a ৳500,000 Fixed
     Asset Purchase with only ৳200,000 paid still pulled all ৳500,000 out of
     the bank, and the unrecorded ৳300,000 "due" (see the Fixed Asset
     Payable/Receivable lines added to computePosition) had nothing on the
     other side of the sheet to match it against. Purchase/Sale already get
     this right (adjBank uses `paid`/`recv`, never the invoice total); Fixed
     Asset Purchase/Sale now follow the same rule. */
  else if(type==='fixed asset purchase'){
    if(acc) adjBank(acc, -paid);
  }
  else if(type==='asset sale'){
    if(acc) adjBank(acc, recv);
  }
  // ── GENERIC EXPENSES (reduce bank) ──
  // FIX (2026-09-12): 'production cost' is a real dropdown option (Production
  // group) but was in none of the branches above, so a paid Production Cost
  // transaction touched no balance at all — the money simply vanished from
  // the books instead of leaving the bank. Added alongside its siblings.
  else if(['office rent','electricity bill','internet bill','telephone bill',
           'fuel expense','transport cost','loading charge','unloading charge',
           'commission payment','brokerage fee','legal fee','audit fee',
           'insurance premium','tax payment','government fee','license fee',
           'maintenance cost','repair expense','stationery purchase',
           'other expense','interest expense','tender payment','tender advance',
           'tender cost','staff salary','utility bill','office expense',
           'extra cost','unload cost','expense','expense payment',
           'production cost'].includes(type)){
    if(acc) adjBank(acc, -amt);
  }
  // ── GENERIC INCOME (increase bank) ──
  else if(['other income','interest income','tender refund'].includes(type)){
    if(acc) adjBank(acc, amt);
  }
  /* ── JOURNAL ENTRY ──
     FIX (bank stays "unlinked" after Post Opening Entry): standard
     double-entry. Debit side (acc) increases the account; credit side
     (acc2) decreases it. Applied against whichever ledger the name
     belongs to — bank, customer, or partner — so a Dr <bank> / Cr
     <Partner Capital> opening posting actually moves both figures and
     the unlinked flag clears permanently on the next rebuild. */
  else if(type==='journal entry'){
    function _adjAny(name, delta){
      if(!name) return;
      if((DB.banks||[]).some(b=>b.name===name)) return adjBank(name, delta);
      if((DB.customers||[]).some(c=>c.name===name)) return adjParty(name, delta);
      if((DB.partners||[]).some(p=>p.name===name)) return adjPartner(name, delta);
    }
    if(acc)  _adjAny(acc,  amt);   // debit  → +
    if(acc2) _adjAny(acc2, -amt);  // credit → −
  }
}

/* FIX (Fixed Assets frozen — Trial Balance mismatch): 'Fixed Asset Purchase'
   and 'Asset Sale' only ever moved cash (via applyTxBalance above) — neither
   type touched DB.assets, the array the Balance Sheet's "Fixed Assets" line
   actually reads (see computePosition). A ৳500,000 Fixed Asset Purchase
   moved ৳200,000 out of the bank but never added a ৳500,000 asset to the
   register; a ৳15,000 Asset Sale brought cash in but never wrote the asset
   off. Left and Right silently drifted apart by the untouched side every
   time either type was used. Each save now mirrors the transaction into the
   register: a Purchase adds a register line at full invoice value (matching
   accrual accounting — the asset is worth its full price the moment it's
   bought, whether or not it's fully paid for yet); a Sale writes off exactly
   the invoice amount as a synthetic negative line, so the register's change
   is the exact mirror of whatever the sale added to cash/receivables,
   regardless of whether any specific named asset in the register actually
   corresponds to what was sold. Both are tagged with srcTxId so an edit or
   delete can find and reverse exactly the line this transaction created,
   the same way applyTxBalance/applyTxStock are reversed with dir=-1. */
function applyAssetRegister(tx, dir){
  try{
    if(!tx) return;
    var type = String(tx.type||'').trim();
    if(type!=='Fixed Asset Purchase' && type!=='Asset Sale') return;
    DB.assets = DB.assets||[];
    DB.nid = DB.nid||{};
    var amt = (typeof window.txAmt==='function') ? window.txAmt(tx) : (parseFloat(tx.amt!=null?tx.amt:tx.amount)||0);
    var name = tx.prod || tx.product || tx.item || tx.rem || tx.remarks || ('Asset (TXN #'+(tx.code||tx.id||'')+')');
    var nextAssetId = function(){
      if(DB.nid.a) return DB.nid.a++;
      var mx=0; DB.assets.forEach(function(a){ if((a.id||0)>mx) mx=a.id||0; });
      return mx+1;
    };
    if(dir>0){
      var line = {
        id: nextAssetId(),
        name: type==='Asset Sale' ? (name+' (sold)') : name,
        cat: 'Fixed Asset (from Transaction)',
        val: type==='Asset Sale' ? -amt : amt,
        dep: 0,
        date: tx.date||'',
        location: '',
        srcTxId: tx.id
      };
      DB.assets.push(line);
    } else {
      // Reversal (edit / delete): remove exactly the line this tx created.
      DB.assets = DB.assets.filter(function(a){ return a.srcTxId!==tx.id; });
    }
  }catch(e){ console.error('[asset register sync]', e); }
}
window.applyAssetRegister = applyAssetRegister;

// ── Bank Balance Checker ──
function checkBankBalance(accName, requiredAmt){
  if(!accName) return {ok:true, bal:0};
  const b=(DB.banks||[]).find(b=>b.name===accName);
  const bal=b?(b.bal||0):0;
  return {ok: bal>=requiredAmt, bal, required:requiredAmt, shortfall:requiredAmt-bal};
}

// ── Show insufficient balance warning with multi-bank option ──
