  const modal=document.createElement('div');
  modal.id='balance-warning-modal';
  modal.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:2000;display:flex;align-items:center;justify-content:center;';
  modal.innerHTML=`
    <div style="background:${bg};border-radius:16px;padding:28px;width:90%;max-width:480px;color:${textColor};box-shadow:0 8px 32px rgba(0,0,0,.3);">
      <div style="text-align:center;margin-bottom:20px;">
        <div style="font-size:48px;margin-bottom:8px;">⚠️</div>
        <div style="font-size:18px;font-weight:800;color:#dc2626;">Insufficient Balance</div>
        <div style="font-size:13px;color:#6b7280;margin-top:6px;">Account: <strong>${accName}</strong></div>
      </div>
      <div style="background:#fef2f2;border:1.5px solid #fecaca;border-radius:10px;padding:14px;margin-bottom:16px;">
        <div style="display:flex;justify-content:space-between;font-size:13px;margin-bottom:6px;">
          <span style="color:#6b7280;">Required:</span>
          <span style="font-weight:800;color:#dc2626;">৳${required.toLocaleString('en-IN',{minimumFractionDigits:2})}</span>
        </div>
        <div style="display:flex;justify-content:space-between;font-size:13px;margin-bottom:6px;">
          <span style="color:#6b7280;">Available:</span>
          <span style="font-weight:800;color:#16a34a;">৳${available.toLocaleString('en-IN',{minimumFractionDigits:2})}</span>
        </div>
        <div style="display:flex;justify-content:space-between;font-size:13px;border-top:1px solid #fecaca;padding-top:6px;margin-top:6px;">
          <span style="color:#6b7280;">Shortfall:</span>
          <span style="font-weight:800;color:#dc2626;">৳${shortfall.toLocaleString('en-IN',{minimumFractionDigits:2})}</span>
        </div>
      </div>
      ${otherBanks.length>0?`
      <div style="margin-bottom:16px;">
        <div style="font-size:12px;font-weight:700;color:#374151;margin-bottom:8px;">💡 Pay from another account instead:</div>
        ${otherBanks.map(b=>`
          <button data-x-click="switchPaymentAccount('${escHTML(b.name)}');document.getElementById('balance-warning-modal').remove()"
            style="width:100%;padding:10px 14px;background:#f0fdf4;border:1.5px solid #bbf7d0;border-radius:8px;margin-bottom:6px;cursor:pointer;display:flex;justify-content:space-between;align-items:center;font-family:inherit;">
            <span style="font-weight:700;font-size:13px;">🏦 ${escHTML(b.name)}</span>
            <span style="color:#16a34a;font-weight:800;font-size:13px;">৳${(b.bal||0).toLocaleString('en-IN',{minimumFractionDigits:2})}</span>
          </button>`).join('')}
      </div>`:'<div style="font-size:12px;color:#9ca3af;text-align:center;margin-bottom:16px;">No other accounts with sufficient balance.</div>'}
      <div style="display:flex;gap:10px;">
        <button data-x-click="document.getElementById('balance-warning-modal').remove()"
          style="flex:1;padding:10px;background:#f3f4f6;color:#374151;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:13px;">
