  const existing=document.getElementById('expense-post-confirm-modal');
  if(existing) existing.remove();

  const modal=document.createElement('div');
  modal.id='expense-post-confirm-modal';
  modal.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:2000;display:flex;align-items:center;justify-content:center;';
  modal.innerHTML=`
    <div style="background:${bg};border-radius:16px;padding:28px;width:90%;max-width:440px;color:${textColor};box-shadow:0 8px 32px rgba(0,0,0,.3);">
      <div style="text-align:center;margin-bottom:20px;">
        <div style="font-size:48px;margin-bottom:8px;">🧾</div>
