// ── Core data-sanity validation (2026-09-02, error-proofing pass) ──
// Catches unambiguous data-entry corruption before it ever reaches the
// party balance / bank balance / P&L math — none of those recalculation
// paths check for NaN, Infinity, or a negative amount, so a bad value
// here would otherwise silently poison every report downstream. This is
// intentionally narrow: it never blocks on a MISSING optional field
// (party, product, etc. are legitimately blank on some entry types, e.g.
// QC-only or unload-only cost rows), only on a value that is clearly
// wrong for a field that WAS filled in.
function validateTxCore(tx){
  const numericFields=['amount','qty','rate','wt','grosswt','paid','recv','due','paid2','due2',
    'qc','unload','othercost','othercost2','agentAcost','agentBcost','truckrent','totalcost','bagqty'];
  for(const k of numericFields){
    const val=tx[k];
    if(val==null) continue; // legitimately blank — not this function's concern
    if(!isFinite(val)) return {valid:false, msg:'“'+k+'” is not a valid number.'};
  }
  if(tx.amount<0){
    return {valid:false, msg:'Amount cannot be negative — use the matching Refund/Return type instead of a minus sign.'};
  }
  if(Math.abs(tx.amount)>=1e12){
    // Almost certainly an extra typed digit, not a real transaction — this
    // business's largest recorded figures run in the low crores (10^7),
    // several orders of magnitude below this.
    return {valid:false, msg:'That amount looks like a typo (an extra digit?) — please recheck it.'};
  }
  return {valid:true};
}

// ── Validate bank balance before saving transaction ──
function validateBankBalance(tx){
  const type=(tx.type||'').toLowerCase();
  const acc=(tx.acc||'').trim();
  const amt=parseFloat(tx.amount)||0;
  const paid=parseFloat(tx.paid)||0;

  /* FIX (2026-09-03): this used to only deduct/check for types on a
     hand-maintained allow-list. 'Expense' and 'Staff Salary' — both real,
     selectable transaction types that clearly pay money out of a bank
     account — were never on that list, so validateBankBalance() computed
     deductAmt=0 for them and the whole balance check was silently skipped.
     A Staff Salary or Expense payment could therefore drive an account
     negative with no warning, even though the sibling guard on the quick
     Payment form (singleAccValidate) already blocks exactly this. Deny by
     default now, mirroring that safer logic: anything that isn't a known
     money-IN type (or a refund) is treated as money OUT and checked. */
  let deductAmt=0;
  if(type==='purchase'||type==='warehouse purchase'||type==='supplier purchase'||type==='werhouse purchase'){
    deductAmt=paid;                                   // purchases settle through tx.paid, not tx.amount
  } else if(window.AYAN_MONEY_IN && window.AYAN_MONEY_IN.has(type)){
    deductAmt=0;                                       // known money coming IN — never blocked
  } else if(type==='payment refund'){
    deductAmt=0;                                        // a refund adds money in
  } else {
    deductAmt=amt;                                       // deny-by-default: treat as money OUT
  }

  if(deductAmt>0 && acc){
    const check=checkBankBalance(acc, deductAmt);
    if(!check.ok) return {valid:false, acc, required:deductAmt, available:check.bal};
  }
  return {valid:true};
}

function editTx(id){
  const tx=(DB.tx||[]).find(t=>t.id===id);
  if(!tx){toast('Transaction not found','e');return;}
  // Set edit ID
  const eid=document.getElementById('tx-edit-id');
  if(eid) eid.value=id;
  // Fill form fields
  const fields={
    'tx-date':tx.date,'tx-type':tx.type,'tx-party':tx.party,'tx-amt':tx.amt||tx.amount,
    'tx-mode':tx.mode,'tx-acc':tx.acc,'tx-acc2':tx.acc2,'tx-prod':tx.prod,
    'tx-qty':tx.qty,'tx-rate':tx.rate,'tx-rem':tx.rem,'tx-inv':tx.inv,
    'tx-paid':tx.paid,'tx-recv':tx.recv,'tx-due':tx.due,
    'tx-truck':tx.truck,'tx-truckrent':tx.truckrent,
    'tx-agentA':tx.agentA,'tx-agentAcost':tx.agentAcost,
    'tx-agentB':tx.agentB,'tx-agentBcost':tx.agentBcost,
    /* FIX (2026-09-06): QC/Unload/Other cost fields were saved on the
       transaction but never read back in when re-opening it for editing —
       only Agent A/B made the round trip. */
    'tx-qcperson':tx.qcperson,'tx-qc':tx.qc,
    'tx-oilpct':tx.oilPct,'tx-totaloil':tx.totalOil,
    'tx-moisture':tx.moisturePct,'tx-protein':tx.proteinPct,
    'tx-fiber':tx.fiberPct,'tx-ash':tx.ashPct,'tx-ffa':tx.ffaPct,
    'tx-unloadperson':tx.unloadperson,'tx-unload':tx.unload,
    'tx-otherperson':tx.otherperson,'tx-othercost':tx.othercost,
    'tx-otherperson2':tx.otherperson2,'tx-othercost2':tx.othercost2,
    'tx-totalcost':tx.totalcost,
    'tx-purchpaytype':tx.purchPayType,'tx-supplierduedate':tx.supplierDueDate,
    'tx-advance-amt':tx.advanceAmt,'tx-advance-rate':tx.advanceRate,
    'tx-advance-calc':tx.advanceCalc,'tx-supplier-balance':tx.supplierBalance
  };
  Object.entries(fields).forEach(([fid,val])=>{
    const el=document.getElementById(fid);
    if(el&&val!==null&&val!==undefined) el.value=val;
  });
  populateSupplierBankDropdown(tx.supplierBankInfo);
  openModal('mTx');
  // Trigger type change to show correct sections
  try{txSectionsForType(tx.type);}catch(e){}
  try{calcAdvanceControl();}catch(e){}
  toast('Editing transaction — make changes and save','s');
}

// ── Open the single canonical transaction modal, pre-set to a given type ──
// Used by the Sales/Purchase/Warehouse/Expense quick-access pages so they
// launch the exact same multi-product form instead of keeping their own
// separate stripped-down copies.
function openTxModalAs(type){
  openModal('mTx');
  const typeEl = document.getElementById('tx-type');
  if(typeEl){
    typeEl.value = type;
    smartTypeToPartyType();
    // Trigger form re-render for the selected type to show all relevant fields
    setTimeout(() => {
      try {
        if(typeof renderTxSections === 'function') renderTxSections();
        if(typeof showExpenseFields === 'function' && type.toLowerCase() === 'expense') showExpenseFields();
      } catch(e) { console.warn('Error rendering sections:', e); }
    }, 50);
  }
}


// ── Shared profit vocabulary ──────────────────────────────────────────
// One list of sale / purchase / expense transaction types so every module
// computes profit the same way: Sales − Purchase − Expense.
/* FIX G: this line used to redefine the canonical revenue set to ALSO include
   'Sales Receipt' and 'Sales Advance'. A sale and the cash received against
   that same sale were then both counted as revenue, so every profit figure
   computed here was overstated. Money movements are settlement, not income. */
/* FIX N: this used to assign straight to window.SALE_TX_TYPES, clobbering the
   canonical revenue-only alias set up near the top of the file (window.SALE_TX_TYPES
   = window.REVENUE_TX_TYPES). Because inline scripts run in document order, every
   screen loaded after this one — including the KPI block that reads
   window.SALE_TX_TYPES directly — silently started counting 'Other Income' and
   'Interest Income' as sales. calcNetProfit() below needs sales+other-income as
   one bucket, but that is a local concept for net-profit math, not the site-wide
   definition of "sales" — so it now lives in its own name instead of overwriting
   the shared global. */
const NET_PROFIT_REVENUE_TYPES = new Set(['Sale','Customer Sale','Warehouse Sale','Other Income','Interest Income']);
/* FIX H: 'Purchase Advance' is a payment, not a cost, and the misspelled
   legacy type 'Werhouse Purchase' was missing entirely. */
window.PURCHASE_TX_TYPES = new Set(['Purchase','Supplier Purchase','Warehouse Purchase','Werhouse Purchase']);
/* FIX (2026-09-12): kept in sync with the canonical definition near the top
   of the file — Utility Bill/Office Expense/Unload Cost/Extra Cost/Expense
   Payment/Production Cost added there; mirrored here so this later
   assignment (same document-order clobbering this file already documents
   above for SALE_TX_TYPES) can't reintroduce the gap. */
window.EXPENSE_TX_TYPES = new Set(['Salary Payment','Staff Salary','Expense','Office Rent','Electricity Bill','Internet Bill','Telephone Bill','Fuel Expense','Transport Cost','Loading Charge','Unloading Charge','Commission Payment','Brokerage Fee','Legal Fee','Audit Fee','Insurance Premium','Tax Payment','Government Fee','License Fee','Maintenance Cost','Repair Expense','Stationery Purchase','Other Expense','Interest Expense','Bank Charge','Utility Bill','Office Expense','Unload Cost','Extra Cost','Expense Payment','Production Cost']);
function isSaleTxType(t){ return NET_PROFIT_REVENUE_TYPES.has(window.normTxType(t)); }
function isPurchaseTxType(t){ return window.PURCHASE_TX_TYPES.has(window.normTxType(t)); }
function isExpenseType(t){ return window.EXPENSE_TX_TYPES.has(String(t||'').trim()); }
function sumTx(list, pred){ return (list||[]).filter(t=>pred(t.type)).reduce((s,t)=>s+(parseFloat(t.amt||t.amount)||0),0); }
// Canonical profit: Sales − Purchase − Expense
function calcNetProfit(list){
  const tx = Array.isArray(list) ? list : (Array.isArray(window.DB&&DB.tx)?DB.tx:[]);
  // Receipts / advances are collections against an invoice, not new income, and
  // purchase advances are not a new cost — counting them here double-booked profit.
  const MOVE = new Set(['Sales Receipt','Sales Advance','Purchase Advance','Purchase Payment']);
  const rev = (t)=>isSaleTxType(t) && !MOVE.has(String(t||'').trim());
  const cost = (t)=>isPurchaseTxType(t) && !MOVE.has(String(t||'').trim());
  const ret = (t)=>['Sales Return','Sale Return'].includes(String(t||'').trim());
  const pret = (t)=>['Purchase Return','Supplier Refund'].includes(String(t||'').trim());
  return (sumTx(tx,rev)-sumTx(tx,ret)) - (sumTx(tx,cost)-sumTx(tx,pret)) - sumTx(tx,isExpenseType);
}

// ══════════════════════════════════════════════════════════════
// INVENTORY SYNC LAYER
// DB.products and DB.inventory are kept as ONE shared array so every module
// (dashboard valuation, stock movement, product P&L) reads the same numbers.
// Each item carries the aliases stock / qty / stockQty and rate / cost, because
// different modules were written against different field names.
// ══════════════════════════════════════════════════════════════
function invItems(){
  if(!Array.isArray(DB.products)){
    DB.products = Array.isArray(DB.inventory) ? DB.inventory
                : (DB.products && typeof DB.products==='object' ? Object.values(DB.products) : []);
  }
  DB.inventory = DB.products;               // same reference, never a plain object
  DB.products.forEach(function(p){
    var q = p.stock!=null ? p.stock : (p.qty!=null ? p.qty : (p.stockQty||0));
    p.stock = p.qty = p.stockQty = parseFloat(q)||0;
    p.rate = parseFloat(p.rate)||0;
    p.cost = parseFloat(p.cost)||0;
  });
  return DB.products;
}
function invFind(name){
  if(!name) return null;
  var n = String(name).trim().toLowerCase();
  return invItems().find(function(p){ return String(p.name||'').trim().toLowerCase()===n; }) || null;
}
function invSetQty(item, qty){
  var q = Math.round(((parseFloat(qty)||0) + Number.EPSILON)*1000)/1000;
  item.stock = item.qty = item.stockQty = q;
}
function invTxQty(tx){
  // Sales Deduction / Weight Loss requirement: for Sale / Warehouse Sale
  // (and their aliases in isSaleType), Stock Out Quantity = GROSS WEIGHT
  // always — never Net Weight or Qty — so a 150g/bag (or any) weight-loss
  // deduction never leaves leftover "phantom" stock behind. The lost/
  // deducted portion is billed via the Weight Loss/Deduction ledger entry
  // instead (see calcWeightLoss/syncWeightLossExpense), not via stock.
  if(typeof isSaleType==='function' && isSaleType(tx && tx.type)){
    return parseFloat(tx.grosswt) || parseFloat(tx.qty) || parseFloat(tx.wt) || parseFloat(tx.bagqty) || 0;
  }
  return parseFloat(tx.qty) || parseFloat(tx.wt) || parseFloat(tx.grosswt) || parseFloat(tx.bagqty) || 0;
}
var INV_IN_TYPES  = ['purchase','warehouse purchase','supplier purchase','opening stock','stock in','production output','sales return'];
var INV_OUT_TYPES = ['sale','customer sale','warehouse sale','stock out','wastage','purchase return'];

// Stock In / Stock Out. dir = +1 when a transaction is applied, -1 when it is
// reversed (edit or delete), so stock never drifts.
function applyTxStock(tx, dir){
  if(!tx) return;
  var type = String(tx.type||'').toLowerCase();
  var isIn = INV_IN_TYPES.indexOf(type)>=0, isOut = INV_OUT_TYPES.indexOf(type)>=0;
  // Warehouse Transfer moves stock between pools without changing the
  // company-wide total, so it's neither an IN nor an OUT type below — but it
  // still needs to run applyTxPoolStock (handled specially there), so this
  // branches off BEFORE the "not a stock type at all" early return.
  if(type==='warehouse transfer'){
    try{ applyTxPoolStock(tx, dir); }catch(e){ console.warn('pool stock sync', e); }
    return;
  }
  if(!isIn && !isOut) return;
  var name = tx.prod || tx.product;
  if(!name) return;
  var item = invFind(name);
  if(!item){                                   // auto-create so stock is never lost
    item = {id:(DB.nid&&DB.nid.pr?DB.nid.pr++:Date.now()), name:String(name),
            category:'General', cat:'General', unit:'KG', rate:0, cost:0,
            stock:0, qty:0, stockQty:0, minStock:0, openingStock:0};
    // openingStock is explicitly 0 (not left undefined) so the later
    // "ayan-stock-sync" recompute never mistakes this transaction's own
    // just-applied quantity for pre-existing opening stock and doubles it
    // — see claude-fix-newproduct-stock-double below for the full story.
    invItems().push(item);
  }
  var qty = invTxQty(tx);
  if(!qty) return;
  var delta = (isIn ? qty : -qty) * dir;
  var before = parseFloat(item.stock)||0;
  // weighted-average cost on stock-in so inventory valuation follows purchases
  var rate = parseFloat(tx.rate) || (qty ? (parseFloat(tx.amt||tx.amount)||0)/qty : 0);
  if(isIn && dir>0 && rate>0){
    var newQty = before + qty;
    if(newQty>0) item.cost = ((before*(parseFloat(item.cost)||0)) + (qty*rate)) / newQty;
    if(!item.rate) item.rate = rate;
  }
  invSetQty(item, before + delta);
  try{ applyTxPoolStock(tx, dir); }catch(e){ console.warn('pool stock sync', e); }
}

// ══════════════════════════════════════════════════════════════
// PER-POOL STOCK TRACKING (2026-09-12)
// The "Source Pool" / "Destination Pool" dropdowns on the transaction form
// (Main Godown, Factory Yard Pool, Mojumpur Depot, Central Warehouse,
// External Processing Facility, Transit Pool, Customer Site) used to be
// decorative — nothing read them, saveTx() never stored them, and there was
// no data structure anywhere tracking stock per physical location. A
// "Warehouse Transfer" had zero effect on any number in the system.
//
// This is now real: DB.poolStock[productName][poolName] = qty, kept in sync
// automatically because applyTxStock() (the single source of truth for a
// product's TOTAL stock) calls applyTxPoolStock() with the exact same
// tx/dir on every apply and every reversal (create, edit, delete, approve).
// The sum of a product's pools always equals its flat p.stock — that
// invariant is what every existing report (P&L, Balance Sheet, dashboard
// valuation) keeps reading unchanged; this only adds a breakdown underneath.
//
// Historical transactions never had a pool, so on first use — and defensively
// on every stock-summary render — reconcilePoolStock() true's up any gap
// between a product's flat stock and its pool total by parking the
// difference in DEFAULT_POOL, so nothing appears to have vanished.
var AYAN_DEFAULT_POOL = 'Main Godown (Kushtia)';
// "Customer Site / External Delivery" and "External Processing Facility" are
// exit points, not storage pools — goods sent there have left the business's
// own stock, so a transfer INTO either one is not tracked as pool inventory
// (it's already handled as an ordinary stock-OUT by the ordinary Sale/Send
// types; Warehouse Transfer to either is treated as ordinary internal-pool
// stock leaving with nowhere internal left to land, i.e. dropped, same as
// this file's other stock-out movements).
var AYAN_EXTERNAL_POOLS = ['Customer Site','Customer Site / External Delivery','Processing Facility','External Processing Facility'];
function applyTxPoolStock(tx, dir){
  if(!tx) return;
  var type = String(tx.type||'').toLowerCase();
  var name = tx.prod || tx.product;
  if(!name) return;
  var qty = invTxQty(tx);
  if(!qty) return;
  DB.poolStock = DB.poolStock || {};
  var bucket = DB.poolStock[name] || (DB.poolStock[name] = {});
  function adj(pool, delta){
    if(!pool) pool = AYAN_DEFAULT_POOL;
    bucket[pool] = (parseFloat(bucket[pool])||0) + delta;
  }
  if(type==='warehouse transfer'){
    var src = tx.sourcepool, dst = tx.destpool;
    if(!src || !dst || src===dst) return;   // nothing well-defined to move
    adj(src, -qty*dir);
    if(AYAN_EXTERNAL_POOLS.indexOf(dst)<0) adj(dst, qty*dir);
    return;
  }
  var isIn = INV_IN_TYPES.indexOf(type)>=0, isOut = INV_OUT_TYPES.indexOf(type)>=0;
  if(isIn) adj(tx.destpool, qty*dir);
  else if(isOut) adj(tx.sourcepool, -qty*dir);
}
window.applyTxPoolStock = applyTxPoolStock;

// Trues up DB.poolStock so every product's pool total matches its flat
// p.stock, parking any gap (all pre-existing history, plus anything that
// slipped through before this layer existed) in the default pool.
function reconcilePoolStock(){
  DB.poolStock = DB.poolStock || {};
  (invItems()||[]).forEach(function(p){
    if(!p.name) return;
    var bucket = DB.poolStock[p.name] || (DB.poolStock[p.name] = {});
    var have = 0;
    Object.keys(bucket).forEach(function(k){ have += parseFloat(bucket[k])||0; });
    var total = parseFloat(p.stock)||0;
    var diff = Math.round((total-have)*1000)/1000;
    if(Math.abs(diff)>0.001){
      bucket[AYAN_DEFAULT_POOL] = (parseFloat(bucket[AYAN_DEFAULT_POOL])||0) + diff;
    }
  });
}
window.reconcilePoolStock = reconcilePoolStock;
function productPoolBreakdown(name){
  reconcilePoolStock();
  var bucket = (DB.poolStock||{})[name] || {};
  var out = {};
  Object.keys(bucket).forEach(function(k){ var q=parseFloat(bucket[k])||0; if(Math.abs(q)>0.001) out[k]=q; });
  return out;
}
window.productPoolBreakdown = productPoolBreakdown;

/* FIX (2026-09-12 - "new transaction replaced an old one"): the id counter
   DB.nid.tx is never rebuilt from the actual transactions - not on load, not
   after a backup/JSON restore - so once it falls behind (restoring an older
   backup, importing data, or a partial save), saveTx() hands out an id that
   an existing transaction already owns. Every later find-by-id step (edit,
   delete, approve, the batch/serial post-save writer) then lands on the OLD
   record, and the new entry appears to overwrite it. nextTxId() clamps the
   counter above the real maximum before issuing an id; repairTxIds() runs at
   load and after every restore and gives any already-duplicated or invalid
   row a fresh unique id. */
function nextTxId(){
  DB.nid=DB.nid||{};
  var mx=0; (DB.tx||[]).forEach(function(t){ var n=+((t&&t.id)); if(isFinite(n)&&n>mx) mx=n; });
  var c=+DB.nid.tx; if(!isFinite(c)||c<mx+1) c=mx+1;
  DB.nid.tx=c+1; return c;
}
function repairTxIds(){
  DB.nid=DB.nid||{};
  var mx=0; (DB.tx||[]).forEach(function(t){ var n=+((t&&t.id)); if(isFinite(n)&&n>mx) mx=n; });
  var used={}, fixed=0;
  (DB.tx||[]).forEach(function(t){
    if(!t) return;
    var n=+t.id;
    if(isFinite(n)&&n>0&&!used[n]){ used[n]=1; return; }
    t.id=++mx; used[t.id]=1; fixed++;
  });
  var c=+DB.nid.tx; if(!isFinite(c)||c<mx+1) DB.nid.tx=mx+1;
  if(fixed) console.warn('repairTxIds: reassigned fresh ids to '+fixed+' duplicated/invalid transaction(s).');
  return fixed;
}

function saveTx(){
  const date=v('tx-date'), type=v('tx-type');
  /* FIX (money received was saved as zero): for every money-coming-in type —
     Bkash Receive, Bank Deposit, Customer Collection, Partner Fund, Asset
     Sale, all the Opening Balance rows and the rest — this form HIDES the
     Amount box and shows a "Received" box instead, so the figure the user
     types is the only one they can type. The record was still built from the
     hidden Amount box, which is necessarily empty, so the transaction saved
     with amount = 0: the bank never went up, the party balance never moved,
     and the money simply was not in the books anywhere. (A ৳5,000 bKash
     receipt in the 22-Aug data is exactly this.) When the type is one of
     those, the received figure is the amount. */
  let amt=parseFloat(v('tx-amt'))||0;
  try{
    if(!amt && window.AYAN_MONEY_IN_AMT && window.AYAN_MONEY_IN_AMT.has(String(type||'').toLowerCase()))
      amt = parseFloat(v('tx-recv'))||0;
  }catch(e){}
  // Only Date + Type are mandatory in general — Amount may be blank/0 so that
  // entries like "Baksh received", QC-only or unload-only cost records can be
  // saved. But for actual goods movement (Sale/Purchase types), Quantity and
  // Amount ARE required: a sale/purchase row with no qty or no amount is an
  // incomplete/broken record, not a legitimate use case.
  if(!date||!type){toast('Fill Date and Type!','e');return;}
  const _isGoodsTx = isSaleType(type) || (typeof ayanIsPurchaseType==='function' && ayanIsPurchaseType(type));
  if(_isGoodsTx){
    const _qtyVal = parseFloat(v('tx-qty'))||0;
    if(!(_qtyVal>0)){toast('⚠️ Quantity is required for this transaction type.','e');return;}
    if(!(amt>0)){toast('⚠️ Amount is required for this transaction type.','e');return;}
  }
  // Warehouse Transfer moves real stock between physical pools (see
  // applyTxPoolStock) — it needs a product, a quantity, and two DIFFERENT
  // pools, or the "transfer" either does nothing or isn't a transfer at all.
  if(String(type).toLowerCase()==='warehouse transfer'){
    const _tqty = parseFloat(v('tx-qty'))||0;
    const _src = v('tx-sourcepool'), _dst = v('tx-destpool');
    if(!v('tx-prod')){toast('⚠️ Select a product to transfer.','e');return;}
    if(!(_tqty>0)){toast('⚠️ Quantity is required for a Warehouse Transfer.','e');return;}
    if(!_src||!_dst){toast('⚠️ Select both a Source Pool and a Destination Pool.','e');return;}
    if(_src===_dst){toast('⚠️ Source Pool and Destination Pool must be different.','e');return;}
  }
  const tx={
    id:nextTxId(), date, type,
    inv:v('tx-inv')||nextInvNo(v('tx-type')),
    po:v('tx-po'), grn:v('tx-grn'), challan:v('tx-challan'),
    deliverydate:v('tx-deliverydate'), paydate:v('tx-paydate'),
    party:v('tx-party'), ptype:v('tx-ptype'),
    prod:v('tx-prod'), loc:v('tx-loc'),
    // Physical warehouse/godown pool (distinct from the "Location Zone" district
    // above, which only drives per-district sale-cost lookups). Feeds
    // applyTxPoolStock() so stock is tracked per physical pool, not just as one
    // company-wide number.
    sourcepool:v('tx-sourcepool'), destpool:v('tx-destpool'),
    // Aliases: several report/card modules read `product` / `account` instead of
    // `prod` / `acc`. Storing both keeps every dashboard card in sync.
    product:v('tx-prod'), account:v('tx-acc'),
    bagtype:v('tx-bagtype'),
    bagqty:parseFloat(v('tx-bagqty'))||null,
    // Return Bag Qty — bags sent back by the buyer (e.g. empty jute/plastic
    // bags returned on delivery). Separate from bagqty (bags sent out).
    bagret:parseFloat(v('tx-bagret'))||null,
    qty:parseFloat(v('tx-qty'))||null,
    grosswt:parseFloat(v('tx-grosswt'))||null,
    wt:parseFloat(v('tx-wt'))||null,
    rate:parseFloat(v('tx-rate'))||null,
    amount:amt, amt:amt,
    /* FIX (the rate on the record did not match the tax on it): this always
       wrote whatever the Settings rate happened to be, even when the tax box
       had been typed over by hand — so an invoice could read "0.5%" beside a
       figure that was nothing of the sort, and no report could reconcile the
       two. The rate stored is now the rate the tax actually represents. */
    salesTaxRate:(function(){
      if(!isSaleType(type)) return 0;
      var _t=parseFloat(document.getElementById('tx-tax-amt')?.value)||0;
      if(!(_t>0)) return 0;
      if(amt>0) return parseFloat((_t/amt*100).toFixed(4));
      var _s=parseFloat(DB.settings&&DB.settings.salesTaxRate);
      return isFinite(_s)?_s:0.05;
    })(),
    salesTaxAmt:isSaleType(type)?(parseFloat(document.getElementById('tx-tax-amt')?.value)||0):0,
    netAmt:isSaleType(type)?(parseFloat(document.getElementById('tx-net-amt')?.value)||amt):amt,
    oilPct:parseFloat(v('tx-oilpct'))||null,
    totalOil:parseFloat(v('tx-totaloil'))||null,
    // Product Nutrition / Quality Specification (Section 4) — lab/QC values
    // captured per batch alongside Oil %. Pure data-capture fields; they do
    // not feed any existing cost/tax/weight calculation.
    moisturePct:parseFloat(v('tx-moisture'))||null,
    proteinPct:parseFloat(v('tx-protein'))||null,
    fiberPct:parseFloat(v('tx-fiber'))||null,
    ashPct:parseFloat(v('tx-ash'))||null,
    ffaPct:parseFloat(v('tx-ffa'))||null,
    // Sales Deduction / Weight Loss (Tax-formula style) — additive fields,
    // only meaningful for Sale/Warehouse Sale rows where Gross > Net.
    weightLossKg:isSaleType(type)?(parseFloat(v('tx-wloss-kg'))||0):0,
    weightLossAmt:isSaleType(type)?(parseFloat(v('tx-wloss-amt'))||0):0,
    // FIX 3: Bag tare weight deduction (150g × bagqty) — stored for audit/invoice
    bagDeductKg:isSaleType(type)?(parseFloat(document.getElementById('tx-bagdeduct-kg')?.value)||0):0,
    bagDeductAmt:isSaleType(type)?(parseFloat(document.getElementById('tx-bagdeduct-amt')?.value)||0):0,
    /* Purchase-side deductions and the weighbridge shortage, kept on the
       transaction so they can be reported per supplier later. */
    purchDeductKg:(typeof ayanIsPurchaseType==='function'&&ayanIsPurchaseType(type))?(parseFloat(document.getElementById('tx-purchdeduct-kg')?.value)||0):0,
    purchDeductAmt:(typeof ayanIsPurchaseType==='function'&&ayanIsPurchaseType(type))?(parseFloat(document.getElementById('tx-purchdeduct-amt')?.value)||0):0,
    shortageKg:(typeof ayanIsPurchaseType==='function'&&ayanIsPurchaseType(type))
      ?Math.max(0,(parseFloat(v('tx-grosswt'))||0)-(parseFloat(v('tx-wt'))||0)):0,
    supplierBankInfo:getSupplierBankValue(),
    // Section 8 — Purchase Payment & Advance Control
    purchPayType:v('tx-purchpaytype'),
    supplierDueDate:v('tx-supplierduedate'),
    advanceAmt:parseFloat(v('tx-advance-amt'))||null,
    advanceRate:parseFloat(v('tx-advance-rate'))||null,
    advanceCalc:parseFloat(document.getElementById('tx-advance-calc')?.value)||null,
    supplierBalance:parseFloat(document.getElementById('tx-supplier-balance')?.value)||null,
    paid:parseFloat(v('tx-paid'))||null,
    recv:parseFloat(v('tx-recv'))||null,
    due:parseFloat(v('tx-due'))||null,
    mode:v('tx-mode'), acc:v('tx-acc'),
    /* FIX (the vehicle type was asked for and then discarded): the form has
       a Transport Type dropdown — Truck, Van, Pickup, Covered Van and the
       rest — which decides whether the vehicle fields appear and relabels
       them ("Truck ID", "Van ID"). The chosen value was never written onto
       the transaction, so after saving there was no way to tell a truck
       load from a van load; only the registration number survived. */
    transporttype:v('tx-transporttype'),
    truck:v('tx-truck'),
    truckrent:parseFloat(v('tx-truckrent'))||null,
    paid2:parseFloat(v('tx-paid2'))||null,
    due2:parseFloat(v('tx-due2'))||null,
    acc2:v('tx-acc2'),
    agentA:v('tx-agentA'), agentAcost:parseFloat(v('tx-agentAcost'))||null,
    agentB:v('tx-agentB'), agentBcost:parseFloat(v('tx-agentBcost'))||null,
    qcperson:v('tx-qcperson'),
    qc:parseFloat(v('tx-qc'))||null,
    unloadperson:v('tx-unloadperson'),
    unload:parseFloat(v('tx-unload'))||null,
    otherperson:v('tx-otherperson'),
    othercost:parseFloat(v('tx-othercost'))||null,
    otherperson2:v('tx-otherperson2'),
    othercost2:parseFloat(v('tx-othercost2'))||null,
    totalcost:parseFloat(v('tx-totalcost'))||null,
    rem:v('tx-rem'),
    cat:autoCategory(type),
    /* FIX (unapproved entries silently moved the bank balance): a Manager's
       ৳5,000 expense used to hit the bank balance the instant it was saved —
       before anyone had reviewed it — so the owner would see money already
       gone for something nobody had signed off on. Only Admin/Owner entries
       post immediately now; everyone else's entry is held Pending until
       approveTx() explicitly posts it (see _executeSaveTx below). The entry
       itself is still saved and visible right away — only its effect on the
       real balance waits. */
    /* MAKER-CHECKER (2026-08-29): this used to auto-approve the entry when an
       Admin was the one saving it, which posted the money instantly and put
       the Admin's own name in approvedBy without anyone reviewing anything —
       a self-authorization with no record that it had happened. Every entry
       now starts Pending no matter who saves it. An Admin approving their own
       entry is still possible (single-Admin deployment) but must go through
       the logged override in approveTx(). */
    approvalStatus:'Pending',
    approvedBy:'',
    approvedAt:'',
    enteredBy:currentUser?.name||'',
    enteredRole:currentUser?.role||'',
    makerUserId:(currentUser?.id!=null?String(currentUser.id):''),
    makerUsername:currentUser?.username||'',
    makerAt:new Date().toISOString()
  };

  // ── BANK BALANCE VALIDATION ──
  const editId=parseInt(document.getElementById('tx-edit-id')?.value)||0;
  const balCheck=validateBankBalance(tx);
  if(!balCheck.valid){
    // HARD BLOCK: no override path. The modal only offers Close or
    // switching to another account that actually has the funds.
    showInsufficientBalanceWarning(balCheck.acc, balCheck.required, balCheck.available);
    return;
  }

  /* FIX (Expense Post Confirmation, was missing entirely): an Expense/
     Salary/Bill-type entry is real money going out and easy to fat-finger
     — give the user one explicit look at amount/account/party before it's
     written, via showExpensePostConfirmation() above. Runs after the hard
     balance block, never replaces it; _executeSaveTx only fires once the
     user actually confirms. */
  if(typeof isExpenseType==='function' && isExpenseType(type) && typeof showExpensePostConfirmation==='function'){
    showExpensePostConfirmation(tx, function(){ _executeSaveTx(tx, editId); });
    return;
  }

  _executeSaveTx(tx, editId);
}

// ── Sales Deduction / Weight Loss → ledger hit ─────────────
// Posts (or updates/removes) a companion 'Other Expense' transaction equal
// to the Sale/Warehouse Sale row's weightLossAmt, linked back via
// linkedSaleTxId so it can be kept in sync on edit and cleaned up on
// delete. 'Other Expense' is already a first-class member of
// window.EXPENSE_TX_TYPES, so this flows through every existing expense/P&L
// report with zero changes to any report code.
function syncWeightLossExpense(saleTx){
  const lossAmt = parseFloat(saleTx && saleTx.weightLossAmt) || 0;
  const existing = (DB.tx||[]).find(t=>t.linkedSaleTxId===saleTx.id && t.autoGenerated==='weightLoss');

  if(lossAmt<=0){
    if(existing){
      try{applyTxBalance(existing,-1);}catch(e){}
      try{applyTxStock(existing,-1);}catch(e){}
      DB.tx=(DB.tx||[]).filter(t=>t.id!==existing.id);
      DB.transactions=DB.tx;
    }
    return;
  }

  const remark='Weight Loss / Sales Deduction — auto from '+(saleTx.inv||('TXN #'+saleTx.id));
  if(existing){
    try{applyTxBalance(existing,-1);}catch(e){}
    existing.date=saleTx.date;
    existing.amount=existing.amt=lossAmt;
    existing.rem=remark;
    existing.party=saleTx.party||existing.party;
    existing.prod=existing.product=saleTx.prod||existing.prod;
    try{applyTxBalance(existing,1);}catch(e){}
  } else {
    const exp={
      id:nextTxId(), code:genCode('TXN'), date:saleTx.date, type:'Other Expense',
      inv:'', po:'', grn:'', challan:'', deliverydate:'', paydate:'',
      party:saleTx.party||'', ptype:'',
      prod:saleTx.prod||'', product:saleTx.prod||'', loc:saleTx.loc||'',
      amount:lossAmt, amt:lossAmt,
      rem:remark, cat:'Expense',
      linkedSaleTxId:saleTx.id, autoGenerated:'weightLoss'
    };
    (DB.tx=DB.tx||[]).push(exp);
    DB.transactions=DB.tx;
    try{applyTxBalance(exp,1);}catch(e){}
  }
}

async function _executeSaveTx(tx, editId){
  const oldTx=editId?(DB.tx||[]).find(t=>t.id===editId):null;
  tx.code = tx.code || (oldTx&&oldTx.code) || genCode('TXN');
  const isUpdate = !!editId;
  if(editId){
    tx.id=editId;
    const idx=(DB.tx||[]).findIndex(t=>t.id===editId);
    if(idx>=0) DB.tx[idx]=tx;
    else (DB.tx=DB.tx||[]).push(tx);
    DB.transactions=DB.tx;
  } else {
    (DB.tx=DB.tx||[]).push(tx);
    DB.transactions=DB.tx;
  }
  // FIX (approval gating): a Pending transaction was never posted to any
  // balance in the first place, so reversing it here would wrongly credit
  // money that was never actually deducted. Only reverse what was truly
  // applied, and only apply the new entry now if it's Approved.
  if(oldTx && oldTx.approvalStatus!=='Pending'){ applyTxBalance(oldTx,-1); try{applyTxStock(oldTx,-1);}catch(e){console.warn('stock reverse',e);} try{applyAssetRegister(oldTx,-1);}catch(e){console.warn('asset register reverse',e);} }
  if(tx.approvalStatus!=='Pending'){
    applyTxBalance(tx,1);
    try{ applyTxStock(tx,1); }catch(e){ console.warn('stock sync', e); }
    try{ applyAssetRegister(tx,1); }catch(e){ console.warn('asset register sync', e); }
    try{ syncWeightLossExpense(tx); }catch(e){ console.warn('weight-loss expense sync', e); }
  }
  closeModal('mTx');
  try{set('nb-tx',(DB.tx||[]).length);}catch(e){}
  try{renderTx();}catch(e){}
  try{renderDash();}catch(e){}
  try{ if(typeof renderProd==='function') renderProd(); }catch(e){}
  /* FIX (save-reliability parity with approveTx()/_forceSaveAndConfirm(),
     see the 2026-08-28 fix above): this used to fire the debounced
     saveDB() and claim success immediately — the identical "a refresh
     inside the coalescing window loses the change" bug already found and
     fixed for approvals, just left unfixed on the far more common
     Save/Edit Transaction path. Await the same immediate, confirmed save
     (with the same beforeunload guard) and only report success once the
     server has actually confirmed it. */
  let saved = true;
  if(typeof _forceSaveAndConfirm === 'function'){
    try{ saved = await _forceSaveAndConfirm(); }
    catch(e){ console.warn('[_executeSaveTx] Save confirmation error:', e); saved = false; }
  } else {
    saveDB();
  }
  if(saved === false){
    toast('Shown on screen, but the server save failed \u2014 refreshing right now would lose this. Check your connection and try again.','e');
    _scheduleAutoSave();
    return;
  }
  toast(isUpdate ? 'Transaction updated!' : 'Transaction saved!','s');
  _scheduleAutoSave();
}

function _forceSaveTx(tx, editId){
  // No caller reaches this anymore (the "Proceed Anyway" override that used
  // to call it has been removed), but this stays defensive: re-run the same
  // balance check _executeSaveTx would rely on, and refuse if it still
  // fails, so nothing can be wired up later to bypass the block.
  const balCheck=(typeof validateBankBalance==='function')?validateBankBalance(tx):{valid:true};
  if(!balCheck.valid){
    if(typeof toast==='function') toast('Blocked: insufficient balance in '+(balCheck.acc||'the selected account'),'e');
    return;
  }
  _executeSaveTx(tx, editId);
}

/* Approve a Manager/Staff-entered transaction: only Admin/Owner may call
   this. Nothing about the entry changes — it was already fully visible —
   only now does it actually post to the bank account, party balance, and
   stock, exactly as if it had been entered by an Admin in the first place. */
async function approveTx(id){
  if(typeof isTopApprover!=='function'||!isTopApprover()){toast('Only Admin/Owner can approve transactions','e');return;}
  /* FIX (2026-08-28): prefer the candidate that's actually still pending
     when more than one transaction shares an id — see
     _findPendingTxCandidate() for why that can happen. */
  const tx=(typeof _findPendingTxCandidate==='function')?_findPendingTxCandidate(id):(DB.tx||[]).find(t=>String(t.id)===String(id));
  if(!tx){toast('Transaction not found','e');return;}
  if(tx.approvalStatus!=='Pending'){toast('Already approved','i');return;}
  /* MAKER-CHECKER: refuse a silent self-approval. */
  const _mc=await window.MakerChecker.gate(tx,'transaction');
  if(!_mc.ok){ toast('Approval cancelled \u2014 nothing was posted','i'); return; }
  _applyTxApprovalCore(tx,_mc);
  try{renderTx();}catch(e){}
  try{renderDash();}catch(e){}
  /* FIX (2026-08-28, "approval resets back to Pending after refresh"): see
     _forceSaveAndConfirm() — an awaited, immediate save instead of the
     debounced saveDB(), so a fast refresh can't beat this to the server
     and reload the still-Pending copy. */
  let saved = true;
  if(typeof _forceSaveAndConfirm === 'function'){
    try {
      saved = await _forceSaveAndConfirm();
    } catch(e) {
      console.warn('[approveTx] Save confirmation error:', e);
      saved = false;
    }
  } else {
    saveDB();
    saved = true;
  }
  if(saved === false){
    toast('Approved on screen, but the server save failed — refreshing right now would lose this. Check your connection and try again.','e');
    return;
  }
  logAudit('APPROVE','Transaction','Approved '+(tx.type||'')+' of '+(tx.amount||tx.amt||0)+' for '+(tx.party||'')+' entered by '+(tx.enteredBy||''));
  toast('Transaction approved — now posted to the balance','s');
  _scheduleAutoSave();
}
window.approveTx = approveTx;

async function delTx(id){
  if(!await __confirm('Delete this transaction? This will reverse its balance effects.')) return;
  const tx = (DB.tx||[]).find(t=>t.id===id);
  if(tx && tx.approvalStatus!=='Pending'){ applyTxBalance(tx, -1); try{applyTxStock(tx,-1);}catch(e){} try{applyAssetRegister(tx,-1);}catch(e){} }  // reverse balance + stock + asset register (only if it was ever posted)
  const linkedWLoss = (DB.tx||[]).find(t=>t.linkedSaleTxId===id && t.autoGenerated==='weightLoss');
  if(linkedWLoss && linkedWLoss.approvalStatus!=='Pending'){ try{applyTxBalance(linkedWLoss,-1);}catch(e){} }      // clean up its ledger deduction too
  /* FIX: the Trash Bin screen invites you to restore deleted items, but
     transactions never reached it — a mis-click destroyed the entry for
     good. Deleted transactions are kept there now. */
  if(tx){
    if(!DB.trash) DB.trash=[];
    DB.trash.unshift(Object.assign({},tx,{_type:'transaction',_deletedAt:new Date().toISOString()}));
    if(linkedWLoss) DB.trash.unshift(Object.assign({},linkedWLoss,{_type:'transaction',_deletedAt:new Date().toISOString()}));
  }
  DB.tx=(DB.tx||[]).filter(t=>t.id!==id && t!==linkedWLoss);
  DB.transactions=DB.tx;
  try{renderTx();}catch(e){}
  try{renderDash();}catch(e){}
  /* FIX (save-reliability parity with approveTx()/_executeSaveTx(), see
     the 2026-08-28 fix and _forceSaveAndConfirm() above): deletion used to
     fire the debounced saveDB() and immediately toast "Transaction
     deleted" — the same refresh-loses-it race already fixed for
     approvals. A delete that silently un-deletes itself on refresh is
     worse than most saves here, because the reversed balance/stock/asset
     effects above have already been shown to the user as done. */
  let saved = true;
  if(typeof _forceSaveAndConfirm === 'function'){
    try{ saved = await _forceSaveAndConfirm(); }
    catch(e){ console.warn('[delTx] Save confirmation error:', e); saved = false; }
  } else {
    saveDB();
  }
  if(saved === false){
    toast('Deleted on screen, but the server save failed \u2014 refreshing right now would restore it. Check your connection and try again.','e');
    _scheduleAutoSave();
    return;
  }
  logAudit('DELETE','Transaction','Deleted transaction ID '+id);
  toast('Transaction deleted','s');
  _scheduleAutoSave();
}

