function renderCust(data){
  const custs = data||(DB.customers||[]);
  const custCount = custs.filter(c=>isCustomerParty(c)).length;
  const suppCount = custs.filter(c=>isSupplierParty(c)).length;
  const netRecv = custs.reduce((s,c)=>s+(c.bal||0),0);
  set('k-cust-count',custCount);
  set('k-supp-count',suppCount);
  set('k-net-recv',f(netRecv));
  set('t-cust', custs.map((c,i)=>`<tr>
    <td class="text-muted fs11">${i+1}</td>
    <td><strong>${escHTML(c.name)}</strong>${entityCodeBadge(c.code)}${c.bankName?`<br><span style="font-size:10px;color:#2563eb;">🏦 ${escHTML(c.bankName)}${c.bankAcc?' | '+escHTML(c.bankAcc):''}</span>`:''}${(c.bankAccounts&&c.bankAccounts.length)?`<br><span style="font-size:10px;color:#2563eb;">🏦 +${c.bankAccounts.length} more account${c.bankAccounts.length>1?'s':''}</span>`:''}</td>
    <td><span class="badge ${c.type==='Customer'?'b-blue':c.type==='Supplier'?'b-orange':c.type==='Both'?'b-teal':c.type==='Partner'?'b-purple':'b-gray'}">${c.type}</span></td>
    <td>${escHTML(c.phone ||'-')}</td>
    <td class="td-num ${(c.bal||0)>0?'text-pos':(c.bal||0)<0?'text-neg':''}">${f(c.bal||0)}</td>
    <td class="td-num">${f(c.creditLimit)}</td>
    <td class="fs11">${escHTML(c.address ||'-')}</td>
    <td><span class="badge b-green">Active</span></td>
    <td style="white-space:nowrap;"><button class="btn btn-xs btn-icon" style="background:#3182ce;color:#fff;margin-right:2px;" data-x-click="viewPartyLedger('${escJSAttr(c.name)}')" title="View Ledger">👁</button><button class="btn btn-xs btn-icon" style="background:#f5a623;color:#000;margin-right:2px;" data-x-click="printPartyLedger('${escJSAttr(c.name)}')" title="Print">🖨️</button><button class="btn btn-xs btn-icon" style="background:#f5a623;color:#000;margin-right:2px;" data-x-click="editCust(${c.id})" title="Edit">✏️</button><button class="btn btn-danger btn-xs btn-icon" data-x-click="delCust(${c.id})" title="Delete">🗑</button></td>
  </tr>`).join(''));
  // Update footer totals
  const totalBal = custs.reduce((s,c)=>s+(c.bal||0),0);
  const tfoot=document.getElementById('t-cust-foot');
  if(tfoot) tfoot.innerHTML=`<tr style="background:#f0fdf4;font-weight:800;border-top:2px solid #16a34a;"><td colspan="4" style="text-align:right;padding:10px 12px;">Totals (${custs.length} parties):</td><td class="td-num" style="padding:10px 12px;color:${totalBal>=0?'#16a34a':'#dc2626'};font-size:13px;">${f(totalBal)}</td><td colspan="4"></td></tr>`;
  // Summary
  const sumEl=document.getElementById('cust-filter-summary');
  if(sumEl) sumEl.innerHTML=`Showing <strong>${custs.length}</strong> parties | Customers: <strong>${custCount}</strong> | Suppliers: <strong>${suppCount}</strong> | Net Balance: <strong style="color:${totalBal>=0?'#16a34a':'#dc2626'}">${f(totalBal)}</strong>`;
}

function custSearch(v){
  if(document.getElementById('cust-search-box')) document.getElementById('cust-search-box').value=v;
  custAdvSearch();
}


let _partyTab='Customer';
function setPartyTab(t){
  _partyTab=t;
  const sel=document.getElementById('cust-type-filter'); if(sel) sel.value=t;
  const title=document.getElementById('party-panel-title');
  if(title) title.innerHTML = t==='Customer'?'🧑‍💼 Customers':t==='Supplier'?'🏭 Suppliers':t==='Partner'?'🤝 Partners':'📋 All Parties';
  document.querySelectorAll('#party-tabs .party-tab').forEach(b=>{
    const on=(b.getAttribute('data-tab')||'')===t;
    b.style.background=on?'#1a3a6b':'#eef2f7';
    b.style.color=on?'#fff':'#334155';
    b.style.fontWeight=on?'800':'600';
  });
  custAdvSearch();
}
function openPartyPanel(t){ nav('customers'); setTimeout(()=>setPartyTab(t),50); }

function custAdvSearch(){
  const q=(document.getElementById('cust-search-box')?.value||'').toLowerCase();
  const type=document.getElementById('cust-type-filter')?.value||'';
  const balF=document.getElementById('cust-bal-filter')?.value||'';
  let custs=DB.customers||[];
  if(type==='Partner'||_partyTab==='Partner'){
    custs=(DB.partners||[]).map(p=>({id:p.id,name:p.name,type:'Partner',bal:p.cap||0,phone:p.phone||'',address:p.role||'',creditLimit:0,code:p.code}));
  }
  if(q) custs=custs.filter(c=>(c.name||'').toLowerCase().includes(q)||(c.phone||'').toLowerCase().includes(q)||(c.address||'').toLowerCase().includes(q)||(c.type||'').toLowerCase().includes(q));
  if(type&&type!=='Partner') custs=custs.filter(c=>c.type===type);
  if(balF==='due') custs=custs.filter(c=>(c.bal||0)>0);
  else if(balF==='advance') custs=custs.filter(c=>(c.bal||0)<0);
  else if(balF==='zero') custs=custs.filter(c=>(c.bal||0)===0);
  renderCust(custs);
}

function importCustomersCSV(){
  const inp=document.createElement('input');inp.type='file';inp.accept='.csv';
  inp.onchange=e=>{
    const file=e.target.files[0]; if(!file) return;
    const reader=new FileReader();
    reader.onload=ev=>{
      const lines=ev.target.result.split('\n').filter(Boolean);
      const headers=lines[0].split(',').map(h=>h.trim().toLowerCase().replace(/"/g,''));
      let added=0;
      for(let i=1;i<lines.length;i++){
        const cols=lines[i].match(/(".*?"|[^,]+)(?=,|$)/g)||[];
        const row={};
        headers.forEach((h,j)=>{ row[h]=(cols[j]||'').replace(/^"|"$/g,'').trim(); });
        if(!row.name) continue;
        const exists=(DB.customers||[]).find(c=>c.name.toLowerCase()===row.name.toLowerCase());
        if(!exists){
          const c={id:DB.nid.c++,name:row.name,type:row.type||'Customer',phone:row.phone||'',bal:parseFloat(row.balance||row.bal||0)||0,creditLimit:parseFloat(row.creditlimit||row['credit limit']||0)||0,address:row.address||'',email:row.email||'',notes:row.notes||''};
          c.code=genCode(partyPrefix(c.type));
          (DB.customers=DB.customers||[]).push(c);
          added++;
        }
      }
      saveDB(); renderCust(DB.customers); toast(`Imported ${added} new parties`,'s');
    };
    reader.readAsText(file);
  };
  inp.click();
}

// ── Unique entity codes (CUS/SUP/PTR/BNK/PRD/TXN) ──
function genCode(prefix){
  DB.seq=DB.seq||{};
  DB.seq[prefix]=(DB.seq[prefix]||0)+1;
  return prefix+'-'+String(DB.seq[prefix]).padStart(prefix==='TXN'?6:4,'0');
}
function partyPrefix(type){ return type==='Supplier'?'SUP':type==='Partner'?'PTR':'CUS'; }
// Preview the code genCode(prefix) will hand out NEXT, without consuming it
// (genCode() itself increments DB.seq, so calling it just to display a
// preview would burn a real code and cause a gap the next time someone
// actually saves).
function peekNextCode(prefix){
  DB.seq=DB.seq||{};
  const n=(DB.seq[prefix]||0)+1;
  return prefix+'-'+String(n).padStart(prefix==='TXN'?6:4,'0');
}
// Show the auto-generated ID in the Add/Edit modals for Party, Partner,
// Bank Account and Product: the existing code when editing, or a live
// preview of the next one to be issued when adding new.
function updateEntityIdPreview(modalId){
  const cfg={
    mCust:{codeField:'c-code', editField:'c-edit-id', list:()=>DB.customers, prefix:()=>partyPrefix(v('c-type')||'Customer')},
    mPart:{codeField:'p-code', editField:'p-edit-id', list:()=>DB.partners, prefix:()=>'PTR'},
    mBank:{codeField:'b-code', editField:'b-edit-id', list:()=>DB.banks, prefix:()=>'BNK'},
    mProd:{codeField:'pr-code', editField:'pr-edit-id', list:()=>DB.products, prefix:()=>'PRD'}
  }[modalId];
  if(!cfg) return;
  const codeEl=document.getElementById(cfg.codeField);
  if(!codeEl) return;
  const editId=parseInt(document.getElementById(cfg.editField)?.value)||0;
  if(editId){
    const rec=(cfg.list()||[]).find(r=>r.id===editId);
    codeEl.value=(rec&&rec.code)||'(existing — unassigned)';
  } else {
    codeEl.value=peekNextCode(cfg.prefix());
  }
}
function migrateEntityCodes(){
  let changed=false;
  (DB.customers||[]).forEach(c=>{ if(!c.code){ c.code=genCode(partyPrefix(c.type)); changed=true; } });
  (DB.partners||[]).forEach(p=>{ if(!p.code){ p.code=genCode('PTR'); changed=true; } });
  (DB.banks||[]).forEach(b=>{ if(!b.code){ b.code=genCode('BNK'); changed=true; } });
  (DB.products||[]).forEach(p=>{ if(!p.code){ p.code=genCode('PRD'); changed=true; } });
  (DB.tx||[]).forEach(t=>{ if(!t.code){ t.code=genCode('TXN'); changed=true; } });
  if(changed) saveDB();
}
function entityCodeBadge(code){
  return code?`<span style="font-size:9.5px;color:#6b7280;background:#f3f4f6;border:1px solid #e5e7eb;border-radius:4px;padding:0 4px;margin-left:5px;vertical-align:middle;">${code}</span>`:'';
}

// ── Additional bank accounts on a party (supplier panel) ──
function addPartyBankRow(d){
  const box=document.getElementById('c-extra-banks'); if(!box) return;
  const esc=s=>String(s||'').replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;');
  const row=document.createElement('div');
  row.className='cpb-row';
  row.style.cssText='display:grid;grid-template-columns:1.2fr 1.2fr 1fr 1fr auto;gap:6px;margin-top:6px;';
  row.innerHTML=`<input class="fc cpb-bank" placeholder="Bank name" value="${esc(d&&d.bank)}">
    <input class="fc cpb-acc" placeholder="Account number" value="${esc(d&&d.acc)}">
    <input class="fc cpb-branch" placeholder="Branch" value="${esc(d&&d.branch)}">
    <input class="fc cpb-routing" placeholder="Routing" value="${esc(d&&d.routing)}">
    <button type="button" class="btn btn-danger btn-xs" style="align-self:center;" data-x-click="this.parentElement.remove()">✕</button>`;
  box.appendChild(row);
}
function clearPartyBankRows(){ const box=document.getElementById('c-extra-banks'); if(box) box.innerHTML=''; }
function collectPartyBankRows(){
  return Array.from(document.querySelectorAll('#c-extra-banks .cpb-row')).map(r=>({
    bank:r.querySelector('.cpb-bank').value.trim(),
    acc:r.querySelector('.cpb-acc').value.trim(),
    branch:r.querySelector('.cpb-branch').value.trim(),
    routing:r.querySelector('.cpb-routing').value.trim()
  })).filter(b=>b.bank||b.acc);
}

function saveCust(){
  const name=v('c-name').trim();
  if(!name){toast('Name required!','e');return;}
  const editId=parseInt(document.getElementById('c-edit-id')?.value)||0;
  const custData={
    name, type:v('c-type'), phone:v('c-phone'),
    bal:parseFloat(v('c-bal'))||0,
    creditLimit:parseFloat(v('c-lim'))||0,
    address:v('c-addr'),
    email:v('c-email')||'',
    notes:v('c-notes')||'',
    bankName:v('c-bank-name')||'',
    bankAcc:v('c-bank-acc')||'',
    bankBranch:v('c-bank-branch')||'',
    bankRouting:v('c-bank-routing')||'',
    bankHolder:v('c-bank-holder')||'',
  };
  custData.bankAccounts=collectPartyBankRows();
  if(editId){
    const idx=(DB.customers||[]).findIndex(c=>c.id===editId);
    if(idx>=0){
      custData.id=editId;
      custData.code=DB.customers[idx].code||genCode(partyPrefix(custData.type));
      DB.customers[idx]=custData;
      toast('Party updated!','s');
    }
  } else {
    custData.id=DB.nid.c++;
    custData.code=genCode(partyPrefix(custData.type));
    (DB.customers=DB.customers||[]).push(custData);
    toast('Party added! ID: '+custData.code,'s');
  }
  clearPartyBankRows();
  saveDB();
  closeModal('mCust');
  renderCust(DB.customers);
  syncPartyDropdowns();
  renderDash();
  // FIX (2026-09-12): a party saved from here (including "+ Add Supplier",
  // which just opens this same mCust modal pre-set to type Supplier) never
  // refreshed the standalone Suppliers page (#pg-suppliers / renderSuppliers()).
  // If that page happened to be the one open, the new/edited party was saved
  // correctly but stayed invisible in its table until the user navigated
  // away and back, which re-ran renderSuppliers() from scratch.
  try{ if(typeof renderSuppliers==='function') renderSuppliers(); }catch(e){}
  try{refreshCardCrudIfOpen();}catch(e){}
  _scheduleAutoSave();
}

function editCust(id){
  const c=(DB.customers||[]).find(c=>c.id===id);
  if(!c) return;
  document.getElementById('c-edit-id') && (document.getElementById('c-edit-id').value=id);
  ['c-name','c-type','c-phone','c-bal','c-lim','c-addr','c-email','c-notes',
   'c-bank-name','c-bank-acc','c-bank-branch','c-bank-routing','c-bank-holder'].forEach(fid=>{
    const el=document.getElementById(fid);
    if(!el) return;
    const key=fid.replace('c-','').replace(/-([a-z])/g,(_,l)=>l.toUpperCase());
    const keyMap={'name':'name','type':'type','phone':'phone','bal':'bal','lim':'creditLimit',
      'addr':'address','email':'email','notes':'notes','bankName':'bankName','bankAcc':'bankAcc',
      'bankBranch':'bankBranch','bankRouting':'bankRouting','bankHolder':'bankHolder'};
    const dataKey=keyMap[fid.replace('c-','')]||fid.replace('c-','');
    el.value=c[dataKey]||'';
  });
  clearPartyBankRows();
  (c.bankAccounts||[]).forEach(b=>addPartyBankRow(b));
  const title=document.querySelector('#mCust .modal-title');
  if(title) title.innerHTML='✏️ Edit Party <span class="modal-close" data-x-click="closeModal(\'mCust\')">✕</span>';
  openModal('mCust');
}

async function delCust(id){
