function renderBank(){
  const total=(DB.banks||[]).reduce((s,b)=>s+(b.bal||b.balance||0),0);
  const bals=(DB.banks||[]).map(b=>b.bal||b.balance||0);
  const high=bals.length?Math.max(...bals):0;
  set('k-btotal',f(total));
  set('k-bcount',(DB.banks||[]).length);
  set('k-bhigh',f(high));

  const bankPos=(DB.banks||[]).filter(b=>(b.bal||b.balance||0)>0);
  mkChart('cBankDetail','bar',bankPos.map(b=>b.name.length>22?b.name.slice(0,22)+'…':b.name),[{
    label:'Balance (৳)',data:bankPos.map(b=>b.bal||b.balance||0),
    backgroundColor:COLORS,borderRadius:8
  }],{plugins:{legend:{display:false}},scales:{y:{ticks:{callback:v=>'৳'+(v/1000).toFixed(0)+'K'}},x:{ticks:{font:{size:10}}}}});

  set('t-bank', (DB.banks||[]).map((b,i)=>{
    const bal=b.bal||b.balance||0;
    return `<tr>
    <td class="text-muted fs11">${i+1}</td>
    <td><strong>${escHTML(b.name)}</strong>${entityCodeBadge(b.code)}</td>
    <td>${escHTML(b.bank||b.bankName||'')}</td>
    <td><span class="badge b-gray">${b.type||'Current'}</span></td>
    <td class="td-num ${bal>0?'text-pos':bal<0?'text-neg':''}">${f(bal)}</td>
    <td class="fs11" style="font-size:10px;color:#6b7280;">${b.accno||b.accountNo||b.no||'-'}</td>
    <td style="white-space:nowrap;"><button class="btn btn-xs btn-icon" style="background:#f5a623;color:#000;margin-right:2px;" data-x-click="printBankStatementByName('${escJSAttr(b.name)}')" title="Print">🖨️</button><button class=\"btn btn-xs btn-icon\" style=\"background:#f5a623;color:#000;margin-right:2px;\" data-x-click=\"editBank(${b.id})\" title=\"Edit\">✏️</button><button class="btn btn-danger btn-xs btn-icon" data-x-click="delBank(${b.id})" title="Delete">🗑</button></td>
  </tr>`;
  }).join(''));
}

/* Net effect of every transaction posted against a named account, using the
   exact same per-type math as applyTxBalance() (without mutating anything).
   Shared by previewBankBal() (Opening Balance -> Current Balance) and
   editBank()'s fallback guess (Current Balance -> Opening Balance) below. */
function bankTxNetEffect(name){
  let net=0;
  if(name && typeof applyTxBalance==='function'){
    (DB.tx||[]).forEach(t=>{
      if((t.acc||'').trim()!==name && (t.acc2||'').trim()!==name) return;
      const fakeBanks=[{name,bal:0}];
      const origBanks=DB.banks;
      DB.banks=fakeBanks;
      try{ applyTxBalance(t,1); }catch(e){}
      DB.banks=origBanks;
      net+=fakeBanks[0].bal;
    });
  }
  return net;
}

/* Live preview of "Current Balance" = Opening Balance + everything posted
   against this account since (same math recomputeBalances() uses at boot),
   so the read-only field always shows what will actually be saved instead
   of a number that just gets silently reset on next reload. */
function previewBankBal(){
  const ob=parseFloat(document.getElementById('b-openbal')?.value)||0;
  const name=(document.getElementById('b-name')?.value||'').trim();
  const el=document.getElementById('b-bal');
  if(el) el.value=(ob+bankTxNetEffect(name)).toFixed(2);
}
window.previewBankBal=previewBankBal;

function editBank(id){
  const b=(DB.banks||[]).find(b=>b.id===id);
  if(!b) return;
  const eid=document.getElementById('b-edit-id');
  if(eid) eid.value=id;
  const bankGet={
    'b-name':()=>b.name||'',
    'b-bank':()=>b.bank||b.bankName||'',
    'b-type':()=>b.type||'Current',
    'b-accno':()=>b.accno||b.accountNo||b.no||'',
    'b-branch':()=>b.branch||'',
    /* No openingBal recorded yet (legacy account) → back-solve it from what
       we do know: currentBal = openingBal + netTransactionEffect, so
       openingBal = currentBal - netTransactionEffect. This is the only
       fallback that doesn't change what's displayed the moment you open
       Edit (current bal minus its own transaction history, then added back
       by previewBankBal(), returns exactly to today's stored balance) —
       guessing openingBal = currentBal instead would double count every
       transaction in the preview and show a wildly wrong number on open. */
    'b-openbal':()=>(b.openingBal!=null?b.openingBal:+(((b.bal!=null?b.bal:(b.balance||0))-bankTxNetEffect(b.name))).toFixed(2))
  };
  Object.keys(bankGet).forEach(fid=>{
    const el=document.getElementById(fid);
    if(el) el.value=bankGet[fid]();
  });
  const title=document.querySelector('#mBank .modal-title');
  if(title) title.innerHTML='✏️ Edit Bank Account <span class="modal-close" data-x-click="closeModal(\'mBank\')">✕</span>';
  openModal('mBank');
  previewBankBal();
}

function openBankModal(){
  const eid=document.getElementById('b-edit-id');
  if(eid) eid.value=0;
  ['b-name','b-bank','b-accno','b-branch','b-openbal','b-bal'].forEach(fid=>{
    const el=document.getElementById(fid); if(el) el.value='';
  });
  const t=document.getElementById('b-type'); if(t) t.value='Current';
  const title=document.querySelector('#mBank .modal-title');
  if(title) title.innerHTML='🏦 Add Bank Account <span class="modal-close" data-x-click="closeModal(\'mBank\')">✕</span>';
  openModal('mBank');
}
window.openBankModal=openBankModal;

function saveBank(){
  const name=v('b-name').trim();
  if(!name){toast('Name required!','e');return;}
  const editId=parseInt(document.getElementById('b-edit-id')?.value)||0;
  const accNo=(v('b-accno')||v('b-acc')||'').trim();
  const bankNm=(v('b-bank')||'').trim();
  const openBal=parseFloat(v('b-openbal'))||0;
  const bankData={
    name, bank:bankNm, bankName:bankNm, type:v('b-type')||'Current',
    accno:accNo, accountNo:accNo, branch:v('b-branch')||'',
    /* FIX (2026-08-20): this modal used to save straight into `bal`, but the
       boot-time drift repair (recomputeBalances(), see ayan-v2-enhancements)
       only ever trusts `openingBal` as the starting point and silently
       resets `bal` from openingBal + transaction history on every reload —
       so a manual balance fix typed here would vanish the next time the app
       loaded. Saving openingBal instead makes the fix actually stick. */
    openingBal:openBal,
    bal:openBal // reconciled against real transaction history immediately below
  };
  if(editId){
    const idx=(DB.banks||[]).findIndex(b=>b.id===editId);
    if(idx>=0){ bankData.id=editId; bankData.code=DB.banks[idx].code||genCode('BNK'); DB.banks[idx]=bankData; toast('Bank updated!','s'); }
  } else {
    bankData.id=DB.nid.b++;
    bankData.code=genCode('BNK');
    (DB.banks=DB.banks||[]).push(bankData);
    toast('Bank account added!','s');
  }
  try{ if(typeof recomputeBalances==='function') recomputeBalances({apply:true}); }catch(e){}
  saveDB(); closeModal('mBank'); renderBank(); renderDash(); syncPartyDropdowns();
  try{refreshCardCrudIfOpen();}catch(e){}
  _scheduleAutoSave();
}

async function delBank(id){
  if(!await __confirm('Delete?')) return;
  DB.banks=(DB.banks||[]).filter(b=>b.id!==id);
  saveDB();renderBank();renderDash();refreshCardCrudIfOpen();toast('Deleted','s');
}

function updateBankSel(){
  const opts='<option value="">-- Select Account --</option>'+
    (DB.banks||[]).map(b=>`<option value="${escHTML(b.name)}">${escHTML(bankDisplayId(b))} (${f(b.bal||0)})</option>`).join('');
  document.getElementById('tx-acc').innerHTML=opts;
  document.getElementById('tx-acc2').innerHTML=opts;
}

function syncPartyDropdowns(){
  // Customers + Suppliers + Partners → party datalist (tx-party)
  const dl = document.getElementById('dl-party');
  if(dl){
    const names = [
      ...(DB.customers||[]).map(c=>c.name),
      ...(DB.partners||[]).map(p=>p.name)
    ].filter(Boolean);
    dl.innerHTML = [...new Set(names)].map(n=>`<option value="${n}">`).join('');
  }
  // Products datalist
  const dlp = document.getElementById('dl-prod');
  if(dlp) dlp.innerHTML=(DB.products||[]).map(p=>`<option value="${escHTML(p.name)}">`).join('');

  // Bank accounts → tx-acc / tx-acc2 / tx-refund-acc, preserving current selection
  const bankOpts = '<option value="">-- Select Account --</option>' +
    (DB.banks||[]).map(b=>`<option value="${escHTML(b.name)}">${escHTML(bankDisplayId(b))} (${f(b.bal!=null?b.bal:(b.balance||0))})</option>`).join('');
  ['tx-acc','tx-acc2','tx-refund-acc'].forEach(id=>{
    const el=document.getElementById(id);
    if(el){ const cur=el.value; el.innerHTML=bankOpts; if(cur) el.value=cur; }
  });
  // Split-payment bank rows (if the split-payment feature is active)
  try{ if(typeof refreshSplitBankDropdowns==='function') refreshSplitBankDropdowns(); }catch(e){}
}

