function renderProd(data){
  const prods=data||DB.products||[];
  const _stk=p=>(p.stock!=null?p.stock:(p.qty||0))||0;
  const totalVal=prods.reduce((s,p)=>s+(p.rate||0)*_stk(p),0);
  const totalCost=stockValue(prods); // cost, falling back to rate when no cost is recorded
  set('k-prtotal',prods.length);
  set('k-prval',f(totalVal));
  set('k-prcost',f(totalCost));
  set('t-prod', prods.map((p,i)=>{
    const margin=(p.cost||0)>0?(((p.rate||0)-(p.cost||0))/p.cost*100).toFixed(1):'0.0';
    return `<tr>
      <td class="text-muted fs11">${i+1}</td>
      <td><strong>${escHTML(p.name)}</strong>${entityCodeBadge(p.code)}</td>
      <td><span class="badge b-gray">${p.category||p.cat||'—'}</span></td>
      <td>${escHTML(p.unit ||'KG')}</td>
      <td class="td-num text-neu">${f(p.rate||0)}</td>
      <td class="td-num">${f(p.cost||0)}</td>
      <td class="td-num">${fn(_stk(p))}</td>
      <td class="td-num text-pos">${f((p.rate||0)*_stk(p))}</td>
      <td class="td-num"><span class="badge ${margin>20?'b-green':margin>10?'b-yellow':'b-red'}">${margin}%</span></td>
      <td style="white-space:nowrap;"><button class="btn btn-xs btn-icon" style="background:#f5a623;color:#000;margin-right:2px;" data-x-click="printAllTransactions((DB.tx||[]).filter(t=>t.prod==='${escJSAttr(p.name)}'))" title="Print">🖨️</button><button class=\"btn btn-xs btn-icon\" style=\"background:#f5a623;color:#000;margin-right:2px;\" data-x-click=\"editProd(${p.id})\" title=\"Edit\">✏️</button><button class="btn btn-danger btn-xs btn-icon" data-x-click="delProd(${p.id})" title="Delete">🗑</button></td>
    </tr>`;
  }).join(''));
}

function prSearch(v){
  const q=(v||'').toLowerCase();
  renderProd((DB.products||[]).filter(p=>
    ((p.name||'').toLowerCase().includes(q)) ||
    ((p.category||p.cat||'').toLowerCase().includes(q))
  ));
