    'pr-cat':p.category||p.cat||'',
    'pr-unit':p.unit||'KG',
    'pr-rate':p.rate||0,
    'pr-cost':p.cost||0,
    'pr-stock':(p.stock!=null?p.stock:(p.qty||0)),
    'pr-min':p.minStock||10
  };
  Object.keys(vals).forEach(fid=>{
