function saveProd(){
  const name=v('pr-name').trim();
  if(!name){toast('Name required!','e');return;}
  const editId=parseInt(document.getElementById('pr-edit-id')?.value)||0;
  // Field names must match what renderProd()/renderProducts() read:
  // category, stock, cost. (The modal only has pr-cat/pr-cost/pr-stock.)
  const stock=parseFloat(v('pr-stock'))||0;
  const prodData={
    name,
    category:v('pr-cat')||'General',
    cat:v('pr-cat')||'General',
    unit:v('pr-unit')||'KG',
    rate:parseFloat(v('pr-rate'))||0,
    cost:parseFloat(v('pr-cost'))||0,
    stock, qty:stock,
    minStock:parseFloat(v('pr-min'))||10
  };
  if(editId){
    const idx=(DB.products||[]).findIndex(p=>p.id===editId);
    if(idx>=0){ prodData.id=editId; prodData.code=DB.products[idx].code||genCode('PRD'); DB.products[idx]=prodData; toast('Product updated!','s'); }
  } else {
    prodData.id=DB.nid.pr++;
    prodData.code=genCode('PRD');
    (DB.products=DB.products||[]).push(prodData);
    toast('Product added!','s');
  }
  saveDB(); closeModal('mProd'); renderProd(DB.products); renderDash();
  // FIX (2026-09-12): same stale-page bug as saveCust()/delCust() above —
  // the standalone Products card page (#pg-products / renderProducts(), a
  // different view from the inventory table renderProd() updates) was never
  // told to refresh, so a product added or edited while that page was open
  // stayed invisible there until you navigated away and back.
  try{ refreshProductsPage(); }catch(e){}
  try{refreshCardCrudIfOpen();}catch(e){}
  _scheduleAutoSave();
}
// Products page (card view) helpers — were referenced by renderProducts() but never defined
function refreshProductsPage(){
  const el=document.getElementById('pg-products');
  if(el && el.classList.contains('active')){ el.innerHTML=''; if(typeof renderProducts==='function') renderProducts(); }
}
function openAddProduct(){
  window._prodEditIdx=null;
  const eid=document.getElementById('pr-edit-id'); if(eid) eid.value=0;
  const t=document.querySelector('#mProd .modal-title');
  if(t) t.innerHTML='📦 Add Product <span class="modal-close" data-x-click="closeModal(\'mProd\')">✕</span>';
  ['pr-name','pr-cat','pr-rate','pr-cost','pr-stock'].forEach(id=>{const e=document.getElementById(id);if(e)e.value='';});
  const u=document.getElementById('pr-unit'); if(u)u.value='KG';
  openModal('mProd');
}
function editProduct(i){
  const prod=(DB.products||[])[i];
  if(!prod){toast('Product not found','e');return;}
  window._prodEditIdx=i;
  const setP=(id,val)=>{const e=document.getElementById(id);if(e)e.value=(val===undefined||val===null)?'':val;};
  setP('pr-name',prod.name);setP('pr-cat',prod.category);setP('pr-unit',prod.unit||'KG');
  setP('pr-rate',prod.rate);setP('pr-cost',prod.cost);setP('pr-stock',prod.stock);
  openModal('mProd');
}

async function delProd(id){
  if(!await __confirm('Delete?')) return;
  DB.products=(DB.products||[]).filter(p=>p.id!==id);
  saveDB();renderProd();renderDash();
  try{ refreshProductsPage(); }catch(e){}
