// ─────────────────────────────────────────────────────────
function assetVal(a){ return parseFloat(a.val!=null?a.val:(a.cost!=null?a.cost:(a.value!=null?a.value:a.purchaseValue)))||0; }
function assetDep(a){ return parseFloat(a.dep!=null?a.dep:a.depreciation)||0; }
function renderAsset(data){
  const list=(data||(DB.assets||[])).map(a=>({...a, val:assetVal(a), dep:assetDep(a)}));
  const total=list.reduce((s,a)=>s+a.val,0);
  const dep=list.reduce((s,a)=>s+a.val*a.dep/100,0);
  set('k-atotal',f(total));
  set('k-adep',f(dep));
  set('k-anet',f(total-dep));
  set('t-asset', list.map((a,i)=>{
    const d=(a.val||0)*(a.dep||0)/100;
    return `<tr>
      <td class="text-muted fs11">${i+1}</td>
      <td><strong>${escHTML(a.name)}</strong></td>
      <td><span class="badge b-orange">${escHTML(a.category)}</span></td>
      <td class="td-num text-neu">${f(a.val||0)}</td>
      <td>${a.dep}%</td>
      <td class="td-num text-neg">${f(d)}</td>
      <td class="td-num text-pos">${f((a.val||0)-d)}</td>
      <td style="white-space:nowrap;"><button class="btn btn-xs btn-icon" style="background:#f5a623;color:#000;margin-right:2px;" data-x-click="printBalanceSheet()" title="Print">🖨️</button><button class=\"btn btn-xs btn-icon\" style=\"background:#f5a623;color:#000;margin-right:2px;\" data-x-click=\"editAsset(${a.id})\" title=\"Edit\">✏️</button><button class="btn btn-danger btn-xs btn-icon" data-x-click="delAsset(${a.id})" title="Delete">🗑</button></td>
    </tr>`;
  }).join(''));
}

