  try{refreshCardCrudIfOpen();}catch(e){}
  _scheduleAutoSave();
}

async function delAsset(id){
  if(!await __confirm('Delete?')) return;
  DB.assets=(DB.assets||[]).filter(a=>a.id!==id);
  saveDB();renderAsset();renderDash();refreshCardCrudIfOpen();toast('Deleted','s');
}

