// ─────────────────────────────────────────────────────────
// BALANCE SHEET
// ─────────────────────────────────────────────────────────
// ══════════════════════════════════════════════════════════════
// CANONICAL FINANCIAL POSITION
// The Balance Sheet and the Trial Balance used to compute their own numbers
// with different rules (supplier advances were a liability in one and an asset
// in the other, supplier dues were counted twice on the left, stock was valued
// off a field that is often empty). Both screens now read this ONE function,
// so they can never disagree.
// ══════════════════════════════════════════════════════════════
function computePosition(){
  const txs      = DB.tx||[];
  const partners = DB.partners||[];
  const B        = partyBuckets(DB.customers||[]);
  const ty       = t => String((t&&t.type)||'').trim();

  // ── Profit (canonical tx-type sets; receipts are cash moves, not revenue) ──
  // Uses COGS (cost of goods actually sold) so unsold stock stays as an asset,
  // not deducted from profit.  Purchases that are still in inventory appear on
  // the right side of the balance sheet as "Warehouse Stock Value".
  const otherInc  = window.OTHER_INCOME_TX_TYPES;
  const expT      = window.EXPENSE_TX_TYPES;
  const sales     = sumRevenue(txs) + txs.filter(t=>otherInc.has(ty(t))).reduce((a,t)=>a+txAmt(t),0);
  const cogs      = window.computeCOGS(txs);   // cost of goods SOLD only
  /* FIX (Transport, Costs & Agents were never expensed here): truck rent
     (tx.truckrent) and the per-bag sale costs (agentAcost/agentBcost/qc/
     unload/othercost) are real costs of doing business, but they live as
     FIELDS on Sale/Purchase rows, not as their own "Expense"-typed
     transactions — so this expenses total, filtered only by type, never
     saw them. They now count here exactly as the P&L report already
     counts them. */
  const transportAgentCosts = txs.reduce((s,t)=>s+(parseFloat(t.truckrent)||0),0)
    + ((typeof window.sumSaleSubCosts==='function') ? window.sumSaleSubCosts(txs) : 0);
  const expenses  = txs.filter(t=>expT.has(ty(t))).reduce((a,t)=>a+txAmt(t),0) + transportAgentCosts;
  let netProfit = sales - cogs - expenses;
  /* FIX (Trial Balance Left vs Right mismatch): the COGS above still matches
     purchases to sales BY PRODUCT NAME, so a Warehouse Purchase ("Atop Bran")
     never matches the Warehouse Sale it's actually sold as ("Parboiled Rice
     Bran High Fat") — COGS silently comes out as ৳0 here, inflating Net
     Profit and throwing Left out of balance with Right by the same amount
     (see the Dashboard Net Profit fix for the identical bug). ayanPL() pools
     warehouse purchases into the brand before matching and uses real
     weighted-average costing off the stock ledger — and it already includes
     the transport/agent costs above — so it is used here whenever available,
     with the calculation above kept only as a fallback. */
  try{
    if(typeof window.ayanPL==='function'){
      const _p = window.ayanPL(null,null);
      if(_p && isFinite(_p.netProfit)) netProfit = _p.netProfit;
    }
  }catch(e){}

  // ── SOURCES OF FUNDS (liabilities + equity) ──
  const partnerFund  = partners.reduce((a,p)=>a+(p.cap||0),0);
  const supplyDue    = B.suppDue;                       // what we owe suppliers
  const customerAdv  = B.custAdv;                       // money received in advance
  const bkashDue     = txs.filter(t=>t.bank&&String(t.bank).toLowerCase().includes('bkash')&&(ty(t)==='Purchase'||ty(t)==='Warehouse Purchase')).reduce((a,t)=>a+txAmt(t),0);
  const agentDue     = (DB.agentLedger||[]).filter(a=>(a.bal||0)>0).reduce((a,l)=>a+(l.bal||0),0);
  /* FIX (would now be counted twice): unpaid commissions are expenses like
     any other and are carried by the Unpaid Expenses line below. Only rows
     with neither a paid nor a due figure — genuinely ambiguous ones — are
     left here, so nothing is counted on both lines. */
  const commDue      = txs.filter(t=>ty(t)==='Commission Payment'&&!t.paid&&!((parseFloat(t.due)||0)>0)).reduce((a,t)=>a+txAmt(t),0);
  const otherPayable = txs.filter(t=>ty(t)==='Journal Entry'&&txAmt(t)<0).reduce((a,t)=>a+Math.abs(txAmt(t)),0);
  /* FIX (Fixed Assets Trial Balance mismatch, part 2): applyAssetRegister now
     books a Fixed Asset Purchase into DB.assets at its FULL invoice value the
     moment it's saved (correct accrual accounting — see applyAssetRegister),
     even though only the `paid` portion has actually left the bank so far.
     Left the unpaid portion untracked and Right would outweigh Left by
     exactly that due amount on every partly-paid asset purchase. This payable
     — and its receivable mirror for a partly-collected Asset Sale — close
     that gap the same way Supply Due / Customer Due already do for ordinary
     purchases and sales. */
  const fixedAssetDue = txs.filter(t=>ty(t)==='Fixed Asset Purchase').reduce((a,t)=>a+Math.max(0,txAmt(t)-(parseFloat(t.paid)||0)),0);
  const assetSaleDue  = txs.filter(t=>ty(t)==='Asset Sale').reduce((a,t)=>a+Math.max(0,txAmt(t)-(parseFloat(t.recv)||0)),0);
  /* FIX (Trial Balance Left vs Right mismatch — unlinked bank opening
     balances): a bank account's Opening Balance is a field typed directly
     onto the account (see the "b-openbal" note: "what this account
     actually held before you started entering transactions here"), not a
     transaction. Bank Balance on the right already includes it in full,
     but unless someone also records where that money came from (a
     Partner Fund / Loan / Supplier opening entry on the left), nothing on
     the left ever grows to match it — Right silently outweighs Left by
     exactly that amount. diagnoseImbalance() already detects and lists
     these accounts by name; this mirrors that same detection so the two
     sides actually foot instead of just being flagged after the fact. */
  const txBankNames = new Set();
  txs.forEach(t=>{ const b=t.bank||t.acc; if(b) txBankNames.add(String(b).trim().toLowerCase()); });
  const unlinkedBankOpening = (DB.banks||[]).reduce((a,b)=>{
    const has = txBankNames.has(String(b.name||'').trim().toLowerCase());
    return a + (((b.bal||0)!==0 && !has) ? (b.bal||0) : 0);
  },0);
  /* FIX (Post Opening Entry / Post All Opening Entries left the books
     unbalanced): once a bank account is "linked" by a Dr <bank> / Cr
     <equity account> Journal Entry, Unlinked Bank Opening Balance above
     correctly drops to ৳0 for it — but nothing on the Left ever picked up
     the credit side of that entry, so Left fell exactly as far as it used
     to be artificially propped up by the unlinked-balance line. A Journal
     Entry's credit side (acc2) is genuine Sources of Funds whenever it is
     NOT itself a bank account — crediting a bank means money is simply
     moving between two of this app's own accounts (a transfer, or the
     debit side of some other bank's entry) and is already fully carried
     by Bank Balance on the Right, so it is excluded here to avoid double-
     counting. This mirrors ayanBankMove()'s Dr=in/Cr=out convention: the
     debit increases a real bank asset (Right), the credit increases a
     real Source of Funds (Left, here) whenever it lands on a non-bank
     account name such as "Opening Balance Equity" or "Partner Capital". */
  const journalEquityCredits = txs.filter(t=>ty(t)==='Journal Entry').reduce((a,t)=>{
    const acc2 = String(t.acc2||'').trim();
    if(!acc2) return a;
    const isBank = (DB.banks||[]).some(bk=>bk.name===acc2);
    return isBank ? a : a + txAmt(t);
  },0);

  // ── USES OF FUNDS (assets) ──
  const customerDue = B.custDue;
  const bankBalance = (DB.banks||[]).reduce((a,b)=>a+(b.bal||0),0);
  const fixedAsset  = (DB.assets||[]).reduce((a,x)=>a+(x.val||0),0);
  const supplyAdv   = B.suppAdv;                        // prepaid to suppliers = asset
  /* FIX (Trial Balance broken by out-of-order entry): this used to read
     stockValue(DB.products) — a SEPARATE running balance that
     applyTxStock() updates strictly in the order transactions are SAVED,
     not the order their dates fall in. Net Profit just above, however,
     comes from ayanPL()/stockPosition(), which walks the exact same
     purchases and sales sorted by DATE. The two engines only ever agreed
     by coincidence: enter a Sale before the Purchase that supplies it
     (dated a day earlier, or simply typed in first — the two most normal
     ways real bookkeeping happens) and applyTxStock() credits that
     Purchase's full cost to DB.products, while stockPosition() correctly
     recognises ৳0 cost basis for the units sold ahead of it — so Net
     Profit comes out overstated by exactly the uncosted COGS while
     Warehouse Stock Value does not shrink to match, and Left stops
     equalling Right by that exact amount (reproduced: ৳1,28,000 off from
     one Sale dated one day before its Purchase). Sourcing Warehouse Stock
     Value from the SAME stockPosition() run used for Net Profit makes the
     two figures two sides of the same coin — whatever COGS that engine
     recognises is exactly what leaves inventory — so Left and Right can
     never drift apart on this account again, regardless of entry or date
     order. Falls back to the old field-based value only if that engine
     isn't loaded at all. */
  const stockVal    = (function(){
    try{
      if(typeof window.stockPosition==='function'){
        const items = window.stockPosition().items||[];
        return items.reduce((s,p)=>s+(parseFloat(p.value)||0),0);
      }
    }catch(e){}
    return stockValue(DB.products);
  })();
  const cashInHand  = txs.filter(t=>ty(t)==='Cash Received').reduce((a,t)=>a+txAmt(t),0)
                    - txs.filter(t=>ty(t)==='Cash Payment').reduce((a,t)=>a+txAmt(t),0);

  const nameList = list => list.map(x=>`${escHTML(x.name)}: ৳${Math.abs(x.bal||0).toLocaleString('en-IN')}`).join(', ');

  const leftItems = [
    {label:'Partner Fund',                val:partnerFund,  icon:'🤝', page:'partners'},
    {label:'Net Profit',                  val:netProfit,    icon:'📈', signed:true, page:'profitloss'},
    {label:'Supply Due (Creditors)',      val:supplyDue,    icon:'🏭', detail:nameList(B.suppDueList), page:'suppliers'},
    {label:'Customer Advance (Received)', val:customerAdv,  icon:'🧾', detail:nameList(B.custAdvList), page:'customers'},
    {label:'Bkash Due',                   val:bkashDue,     icon:'📱', page:'bkashledger'},
    {label:'Agent Due',                   val:agentDue,     icon:'👤', page:'agents'},
    {label:'Commission Due',              val:commDue,      icon:'💼', page:'agents'},
    {label:'Other Payables',              val:otherPayable, icon:'📋', page:'allledgers'},
    {label:'Bank Loans / LC',             val:(typeof window.ayanLoansOutstanding==='function'?window.ayanLoansOutstanding():0), icon:'🏦', page:'loans'},
    {label:'Factory Finance (advance + charges)', val:(typeof window.ayanFinanceOutstanding==='function'?window.ayanFinanceOutstanding():0), icon:'🏭', page:'cityfinance'},
    {label:'Transport / Freight Due',     val:(typeof window.ayanTransportDue==='function'?window.ayanTransportDue():0), icon:'🚛', fn:"if(typeof openTransportDueLedger==='function')openTransportDueLedger();"},
    {label:'Sale Handling Costs Due',     val:(typeof window.ayanSaleCostDue==='function'?window.ayanSaleCostDue():0), icon:'👷', fn:"if(typeof openCostLineLedger==='function')openCostLineLedger();"},
    {label:'Unpaid Expenses',             val:(typeof window.ayanExpensePayable==='function'?window.ayanExpensePayable():0), icon:'🧾', page:'expenseentry'},
    {label:'Fixed Asset Payable (Unpaid Asset Purchases)', val:fixedAssetDue, icon:'🏗️', page:'assets'},
    {label:'Unlinked Bank Opening Balance (source not recorded)', val:unlinkedBankOpening, icon:'🌱', page:'banks'},
    {label:'Opening Balance Equity / Journal Credits', val:journalEquityCredits, icon:'📒', page:'chartofaccounts'},
  ];
  const rightItems = [
    {label:'Customer Due',            val:customerDue, icon:'👥', detail:nameList(B.custDueList), page:'customers'},
    {label:'Bank Balance',            val:bankBalance, icon:'🏦', page:'banks'},
    {label:'Fixed Assets',            val:fixedAsset,  icon:'🏗️', page:'assets'},
    {label:'Supply Advance',          val:supplyAdv,   icon:'💰', detail:nameList(B.suppAdvList), page:'suppliers'},
    {label:'Warehouse Stock Value',   val:stockVal,    icon:'🏭', page:'inventory'},
    {label:'Cash in Hand',            val:cashInHand,  icon:'💵', signed:true, page:'banks'},
    {label:'Asset Sale Receivable',   val:assetSaleDue, icon:'🏗️', page:'assets'},
  ];
  const totalLeft   = leftItems.reduce((a,i)=>a+i.val,0);
  const totalRight  = rightItems.reduce((a,i)=>a+i.val,0);
  const liabilities = totalLeft - partnerFund - netProfit;   // outside obligations only

  return {leftItems,rightItems,totalLeft,totalRight,liabilities,
          partnerFund,netProfit,supplyDue,customerAdv,customerDue,bankBalance,
          fixedAsset,supplyAdv,stockVal,cashInHand,journalEquityCredits,
          totalAssets:totalRight, netWorth:totalRight-liabilities};
}

function renderBS(){
  const P = computePosition();
  window.__ayanLastBSPosition = P; // cache so the diagnostics wrapper below doesn't recompute it
  const partners = DB.partners||[];

  set('bs-assets', P.rightItems.map(i=>
    `<div class="sum-row"${i.page?` data-x-click="nav('${i.page}')" style="cursor:pointer;" title="Click to open"`:''}><span class="sum-name">${i.icon} ${escHTML(i.label)}${i.page?' →':''}</span><span class="sum-val ${i.val<0?'neg':'pos'}">${f(i.val)}</span></div>`
  ).join('') + `<div class="sum-total"><span>TOTAL ASSETS</span><span class="text-pos">${f(P.totalAssets)}</span></div>`);

  set('bs-liab', `
    ${partners.map(p=>`<div class="sum-row" data-x-click="nav('partners')" style="cursor:pointer;" title="Click to open"><span class="sum-name">🤝 Partner Capital (${escHTML(p.name)}) →</span><span class="sum-val pos">${f(p.cap||0)}</span></div>`).join('')}
    <div class="sum-row" data-x-click="nav('profitloss')" style="cursor:pointer;" title="Click to open"><span class="sum-name">📈 Retained Profit →</span><span class="sum-val ${P.netProfit<0?'neg':'pos'}">${f(P.netProfit)}</span></div>
    ${P.leftItems.slice(2).map(i=>
      `<div class="sum-row"${i.page?` data-x-click="nav('${i.page}')" style="cursor:pointer;" title="Click to open"`:(i.fn?` data-x-click="${i.fn}" style="cursor:pointer;" title="Click to open"`:'')}><span class="sum-name">${i.icon} ${i.label}${(i.page||i.fn)?' →':''}</span><span class="sum-val neg">${f(i.val)}</span></div>`).join('')}
    <div class="sum-total"><span>TOTAL LIABILITIES + EQUITY</span><span class="text-pos">${f(P.totalLeft)}</span></div>
    <div class="sum-row" style="margin-top:8px;"><span class="sum-name fw8">NET WORTH</span><span class="sum-val pos fw8">${f(P.netWorth)}</span></div>
  `);

  mkChart('cBS','bar',
    ['Receivables','Bank','Fixed Assets','Stock','Supply Advance','Cash','Partner Capital','Supply Due'],
    [{label:'Amount',data:[P.customerDue,P.bankBalance,P.fixedAsset,P.stockVal,P.supplyAdv,P.cashInHand,P.partnerFund,P.supplyDue],
      backgroundColor:['#3182ce','#805ad5','#dd6b20','#319795','#0ea5e9','#65a30d','#38a169','#e53e3e'],borderRadius:8}],
    {plugins:{legend:{display:false}},scales:{y:{ticks:{callback:v=>'৳'+(v/100000).toFixed(1)+'L'}}}}
  );

  // ══════════════════════════════════════════════════════════
  // TRIAL BALANCE — LEFT vs RIGHT (same numbers as above)
  // ══════════════════════════════════════════════════════════
  (function renderTrialBalance(){
    const fmt = v => '৳' + Math.abs(v).toLocaleString('en-IN');
    const setEl = (id,html) => { const el=document.getElementById(id); if(el) el.innerHTML=html; };
    const setTxt = (id,txt) => { const el=document.getElementById(id); if(el) el.textContent=txt; };

    const netProfit   = P.netProfit;
    const bankBalance = P.bankBalance;
    const customerDue = P.customerDue;
    const leftItems   = P.leftItems;
    const rightItems  = P.rightItems;
    const totalLeft   = P.totalLeft;
    const totalRight  = P.totalRight;

    // ── Render ROWS ──
    const rowHtml = (items) => items.map(item=>{
      const isNeg = item.signed && item.val < 0;
      const click = item.page ? `nav('${item.page}')` : (item.fn || '');
      return `<div class="qa-tb-row${isNeg?' neg':''}"${click?` data-x-click="${click}" style="cursor:pointer;"`:''} title="${click?'Click to open':''}">
        <div class="qa-tb-row-main">
          <span class="qa-tb-row-label">${item.icon} ${escHTML(item.label)}${click?' →':''}</span>
          <span class="qa-tb-row-val">${isNeg?'('+fmt(item.val)+')':fmt(item.val)}</span>
        </div>
        ${item.detail ? `<div class="qa-tb-row-detail">${item.detail}</div>` : ''}
      </div>`;
    }).join('');

    setEl('tb-left-rows',   rowHtml(leftItems));
    setEl('tb-right-rows', rowHtml(rightItems));
    setTxt('tb-left-total-val',   fmt(totalLeft));
    setTxt('tb-right-total-val', fmt(totalRight));

    // ── Mismatch Detection ──
    const diff = totalLeft - totalRight;
    const banner = document.getElementById('tb-mismatch-banner');
    const diffRow = document.getElementById('tb-diff-row');
    const diffDetail = document.getElementById('tb-diff-detail');
    const diffAction = document.getElementById('tb-diff-action');

    if(Math.abs(diff) < 1){
      // MATCHED ✅
      if(banner){ banner.style.display='block'; banner.className='qa-banner success';
        banner.innerHTML='✅ <strong>BALANCED!</strong> Left side ('+fmt(totalLeft)+') = Right side ('+fmt(totalRight)+'). Trial Balance is matched.'; }
      if(diffRow) diffRow.style.display='none';
    } else {
      // MISMATCH ❌
      if(banner){ banner.style.display='block'; banner.className='qa-banner error';
        banner.innerHTML='❌ <strong>MISMATCH!</strong> Difference of <strong>'+fmt(Math.abs(diff))+'</strong> detected. See details below.'; }
      if(diffRow) diffRow.style.display='block';
      if(diffDetail) diffDetail.innerHTML = `
        <div>Left Total &nbsp;: <strong>${fmt(totalLeft)}</strong></div>
        <div>Right Total: <strong>${fmt(totalRight)}</strong></div>
        <div>Difference : <strong style="color:#dc2626;">${fmt(Math.abs(diff))}</strong></div>
        <div style="margin-top:6px;">${diff>0
          ? '⬅️ Left side is <strong>MORE</strong> than Right side by '+fmt(diff)+'. Some assets may be unrecorded or liabilities are overstated.'
          : '➡️ Right side is <strong>MORE</strong> than Left side by '+fmt(Math.abs(diff))+'. Some liabilities may be unrecorded or assets are overstated.'
        }</div>`;
      if(diffAction) diffAction.innerHTML = diff>0
        ? '💡 <strong>Action:</strong> Check if all assets (bank accounts, receivables, stock) are fully recorded. Possible missing: cash in hand, advance payments, or unrecorded assets.'
        : '💡 <strong>Action:</strong> Check if all liabilities (supplier dues, partner capital, loans) are fully recorded. Possible missing: unpaid bills, partner contributions, or unrecorded payables.';
    }

    // ── All Reports Quick Links ──
    const reports = [
      {label:'📊 Balance Sheet',    nav:'balancesheet'},
      {label:'📈 Profit & Loss',    nav:'profitloss'},
      {label:'📋 Ledger',            nav:'ledger'},
      {label:'👥 Customer Aging',    nav:'customeraging'},
      {label:'🏭 Supplier Aging',    nav:'supplieraging'},
      {label:'💰 Bank Statement',    nav:'bankstatement'},
      {label:'📦 Stock Summary',     nav:'stocksummary'},
      {label:'💼 Expense Analysis', nav:'expenseanalysis'},
      {label:'📅 Daily Sales',       nav:'dailysales'},
      {label:'📅 Daily Purchase',    nav:'dailypurchase'},
      {label:'📊 Analytics',         nav:'analytics'},
      {label:'💚 Biz Health',        nav:'bizhealth'},
    ];
    const linksEl = document.getElementById('tb-report-links');
    if(linksEl) linksEl.innerHTML = reports.map(r=>
      `<button class="qa-report-link" data-x-click="nav('${r.nav}')">${escHTML(r.label)}</button>`
    ).join('');

    // ── Health Widget ──
    const healthCards = [
      {label:'Net Profit',    val:fmt(netProfit),    color: netProfit>=0?'#4ade80':'#f87171', icon:'📈'},
      {label:'Bank Balance',  val:fmt(bankBalance),  color: bankBalance>100000?'#4ade80':'#fbbf24', icon:'🏦'},
      {label:'Customer Due',  val:fmt(customerDue),  color:'#93c5fd', icon:'👥'},
      {label:'Trial Balance', val:Math.abs(diff)<1?'✅ Matched':'❌ '+fmt(Math.abs(diff))+' off', color:Math.abs(diff)<1?'#4ade80':'#f87171', icon:'⚖️'},
    ];
    const hwEl = document.getElementById('tb-health-cards');
    if(hwEl) hwEl.innerHTML = healthCards.map(c=>
      `<div class="qa-health-card">
        <div class="qa-health-icon">${c.icon}</div>
        <div class="qa-health-val" style="color:${c.color};">${c.val}</div>
        <div class="qa-health-label">${escHTML(c.label)}</div>
      </div>`
    ).join('');

  })(); // end renderTrialBalance
}

