function updateDL(){
  document.getElementById('dl-party').innerHTML=(DB.customers||[]).map(c=>`<option value="${escHTML(c.name)}">`).join('');

  document.getElementById('dl-prod').innerHTML=(DB.products||[]).map(p=>`<option value="${escHTML(p.name)}">`).join('');
