function resetAndOpenModal(modalId, title){
  // Reset hidden edit ID
  const eid=document.getElementById(modalId.replace('m','').toLowerCase()+'-edit-id')||
            document.getElementById(modalId.slice(1).toLowerCase()+'-edit-id');
  if(eid) eid.value=0;
  // Reset title
  const titleEl=document.querySelector('#'+modalId+' .modal-title');
  if(titleEl&&title) titleEl.innerHTML=title+' <span class="modal-close" data-x-click="closeModal(\''+modalId+'\')">✕</span>';
  // Clear all inputs in modal
  document.querySelectorAll('#'+modalId+' input:not([type=hidden]), #'+modalId+' select, #'+modalId+' textarea').forEach(el=>{
    if(el.tagName==='SELECT') el.selectedIndex=0;
    else el.value='';
  });
  openModal(modalId);
}
/* ── Expense Field Display Handler ──────────────────────────────────────
   When posting Expense from "New Transaction" modal, this ensures all
   expense-specific form fields are visible and properly labeled. */
function showExpenseFields(){
  const type = v('tx-type');
  if(!type || !type.toLowerCase().includes('expense')) return;
  
  // Show expense-specific fields
  const fields = [
    'tx-date',     // Date
    'tx-party',    // Payee name
    'tx-mode',     // Payment mode (Cash/Bank)
    'tx-acc',      // Account/Bank name
    'tx-amt',      // Amount
    'tx-inv',      // Invoice number
    'tx-rem'       // Notes/Remarks
  ];
  
  fields.forEach(f => {
    const el = document.getElementById(f);
    if(el && el.parentElement) {
      el.parentElement.style.display = 'block';
      el.style.display = 'block';
    }
  });
  
  // Update label for expense context
  const partyLabel = document.querySelector('label[for="tx-party"]');
  if(partyLabel) partyLabel.textContent = '💰 Payee/Vendor';
  
  const modeLabel = document.querySelector('label[for="tx-mode"]');
  if(modeLabel) modeLabel.textContent = '💳 Payment Mode';
}

function openModal(id){
  try{ if(id==='mTx') setTimeout(ayanFillRateInputs,60); }catch(e){}
  try{ if(id==='mTx'){ var _t=document.getElementById('tx-tax-amt'); if(_t) delete _t.dataset.userEdited; } }catch(e){}
  // Edit mode: numeric id = transaction id to edit
  if(typeof id === 'number'){
    const tx = (DB.tx||DB.tx||[]).find(t=>t.id===id);
    if(!tx){ toast('Transaction not found','e'); return; }
    // Open the mTx modal first (to create elements)
    openModal('mTx');
    // Populate all fields
    const setV = (fid, val) => { const el=document.getElementById(fid); if(el) el.value = val||''; };
    setV('tx-edit-id', tx.id);
    setV('tx-date', tx.date);
    const typeEl=document.getElementById('tx-type');
    if(typeEl){ typeEl.value=tx.type||''; }
    txSectionsForType(tx.type||'');
    setV('tx-inv', tx.inv);
    const invEl=document.getElementById('tx-inv');
    if(invEl) delete invEl.dataset.autoGen;
    setV('tx-po', tx.po);
    setV('tx-grn', tx.grn);
    setV('tx-challan', tx.challan);
    setV('tx-deliverydate', tx.deliverydate);
    setV('tx-paydate', tx.paydate);
    setV('tx-oilpct', tx.oilPct);
    setV('tx-totaloil', tx.totalOil);
    setV('tx-moisture', tx.moisturePct);
    setV('tx-protein', tx.proteinPct);
    setV('tx-fiber', tx.fiberPct);
    setV('tx-ash', tx.ashPct);
    setV('tx-ffa', tx.ffaPct);
    populateSupplierBankDropdown(tx.supplierBankInfo);
    setV('tx-party', tx.party);
    const ptypeEl=document.getElementById('tx-ptype');
    if(ptypeEl) ptypeEl.value=tx.ptype||'';
    setV('tx-prod', tx.prod);
    setV('tx-loc', tx.loc);
    setV('tx-sourcepool', tx.sourcepool);
    setV('tx-destpool', tx.destpool);
    setV('tx-bagtype', tx.bagtype);
    setV('tx-bagqty', tx.bagqty);
    setV('tx-bagret', tx.bagret);
    setV('tx-qty', tx.qty);
    setV('tx-grosswt', tx.grosswt);
    setV('tx-wt', tx.wt);
    setV('tx-rate', tx.rate);
    setV('tx-amt', tx.amount);
    setV('tx-paid', tx.paid);
    setV('tx-recv', tx.recv);
    setV('tx-due', tx.due);
    const modeEl=document.getElementById('tx-mode');
    if(modeEl) modeEl.value=tx.mode||'';
    setV('tx-acc', tx.acc);
    setV('tx-truck', tx.truck);
    setV('tx-truckrent', tx.truckrent);
    setV('tx-paid2', tx.paid2);
    setV('tx-due2', tx.due2);
    setV('tx-acc2', tx.acc2);
    setV('tx-agentA', tx.agentA);
    setV('tx-agentAcost', tx.agentAcost);
    setV('tx-agentB', tx.agentB);
    setV('tx-agentBcost', tx.agentBcost);
    setV('tx-qcperson', tx.qcperson);
    setV('tx-qc', tx.qc);
    setV('tx-unloadperson', tx.unloadperson);
    setV('tx-unload', tx.unload);
    setV('tx-otherperson', tx.otherperson);
    setV('tx-othercost', tx.othercost);
    setV('tx-otherperson2', tx.otherperson2);
    setV('tx-othercost2', tx.othercost2);
    setV('tx-totalcost', tx.totalcost);
    setV('tx-rem', tx.rem);
    /* FIX (2026-09-12): Sales Tax, Net Sales Value and Weight Loss were saved
       on the transaction but never read back when re-opening it for edit —
       the fields stayed blank until the user nudged Weight/Rate by hand. */
    setV('tx-tax-amt', tx.salesTaxAmt);
    setV('tx-net-amt', tx.netAmt);
    setV('tx-wloss-kg', tx.weightLossKg);
    setV('tx-wloss-amt', tx.weightLossAmt);
    const purchTypeEl=document.getElementById('tx-purchpaytype');
    if(purchTypeEl){ purchTypeEl.value=tx.purchPayType||''; if(tx.purchPayType) purchTypeEl.dataset.userEdited='1'; }
    setV('tx-supplierduedate', tx.supplierDueDate);
    setV('tx-advance-amt', tx.advanceAmt);
    setV('tx-advance-rate', tx.advanceRate);
    setV('tx-advance-calc', tx.advanceCalc);
    setV('tx-supplier-balance', tx.supplierBalance);
    try{ if(typeof calcSalesTax==='function') calcSalesTax(); }catch(_){}
    try{ if(typeof calcWeightLoss==='function') calcWeightLoss(); }catch(_){}
    try{ if(typeof calcAdvanceControl==='function') calcAdvanceControl(); }catch(_){}
    toggleSalesCost();
    // Update modal title
    const titleEl=document.getElementById('mTx-title');
    if(titleEl) titleEl.textContent='✏️ Edit Transaction — ' + (tx.inv||tx.id);
    return;
  }
  if(id==='mTx'){
    /* FIX (2026-09-06): this used to reset only a hand-picked list of field
       IDs, and that list quietly fell behind as the form grew — PO/GRN/
       Challan, Delivery/Pay dates, Gross Weight, Oil %/Total Oil, the
       bag-tare grams override, every deduction/adjustment/tax field, the
       commission & reimbursement rows, transport, and payment-settlement
       fields were never in it. Result: click "New Transaction" right after
       saving one, and all of that leftover data was still sitting in the
       form. Sweep every real input inside the modal instead, so nothing new
       that gets added to the form can be missed again. */
    const modalEl = document.getElementById('mTx');
    if(modalEl){
      modalEl.querySelectorAll('input, select, textarea').forEach(el=>{
        if(el.id==='tx-date') return; // set explicitly to today, below
        if(el.tagName==='SELECT') el.selectedIndex = 0;
        else if(el.type==='checkbox' || el.type==='radio') el.checked = false;
        else el.value = '';
        delete el.dataset.autoGen;
        delete el.dataset.userEdited;
      });
    }
    // Reset rate tags
    ['tag-agentA','tag-agentB','tag-qc','tag-unload','tag-other','tag-other2'].forEach(id=>{
      const el=document.getElementById(id); if(el) el.textContent='';
    });
    const typeEl=document.getElementById('tx-type');
    if(typeEl) typeEl.selectedIndex=0;
    const dateEl=document.getElementById('tx-date');
    if(dateEl) dateEl.value=new Date().toISOString().split('T')[0];
    toggleSalesCost();
    txSectionsForType('');
    const titleEl=document.getElementById('mTx-title');
    if(titleEl) titleEl.textContent='💰 New Transaction';
    document.getElementById('tx-edit-id') && (document.getElementById('tx-edit-id').value='');
  }
  // Populate bank account dropdowns from DB.banks (name + current balance)
  if(id==='mTx'){
    try{ if(typeof syncPartyDropdowns==='function') syncPartyDropdowns(); }catch(e){}
    try{ if(typeof refreshSplitBankDropdowns==='function') refreshSplitBankDropdowns(); }catch(e){}
  }
  if(!DB.banks) DB.banks=[];
  if(id==='mCust'||id==='mPart'||id==='mBank'||id==='mProd'){
    try{ updateEntityIdPreview(id); }catch(e){}
  }
  const mEl = document.getElementById(id);
  if(!mEl) return;
  // Stamp the moment this modal opened so the outside-click-to-close
  // handler below can tell a genuine later click on the backdrop apart
  // from the second click of the SAME double-click/hard-click that just
  // opened it (see that handler for the full story).
  mEl.dataset.openedAt = Date.now();
  // Support both overlay class system and inline display:none modals
  if(mEl.classList.contains('overlay') || mEl.style.display === '' || mEl.style.display === 'none'){
    if(mEl.classList.contains('overlay')){
      mEl.classList.add('open');
    } else {
      mEl.style.display = 'flex';
    }
  } else {
    mEl.classList.add('open');
  }
}

function closeModal(id){
  const mEl = document.getElementById(id);
  if(!mEl) return;
  if(mEl.classList.contains('overlay')){
    mEl.classList.remove('open');
  } else {
    mEl.style.display = 'none';
  }
}

// ─────────────────────────────────────────────────────────
// DASHBOARD CARD → CRUD MODAL
// ─────────────────────────────────────────────────────────
let _cardCrudType = null;

function openCardCrud(type){
  _cardCrudType = type;
  openModal('mCardCrud');
  renderCardCrud();
}

function refreshCardCrudIfOpen(){
  const mEl = document.getElementById('mCardCrud');
  if(mEl && mEl.classList.contains('open')) renderCardCrud();
}

function renderCardCrud(){
  const titleEl = document.getElementById('mcc-title');
  const bodyEl = document.getElementById('mcc-body');
  const actionsEl = document.getElementById('mcc-actions');
  if(!titleEl||!bodyEl||!actionsEl) return;
  const tbl = (headers, rows) => `<table class="tbl"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows}</tbody></table>`;
  const closeBtn = '<button class="btn btn-ghost" data-x-click="closeModal(\'mCardCrud\')">Close</button>';

  if(_cardCrudType==='receivables'){
    titleEl.textContent='👥 Customer Receivables';
    const custs=(DB.customers||[]).filter(c=>(c.type==='Customer'||c.type==='Both')&&(c.bal||0)>0).sort((a,b)=>(b.bal||0)-(a.bal||0));
    bodyEl.innerHTML = custs.length===0 ? '<div class="empty"><p>No customers currently owe a balance.</p></div>' :
      tbl(['Name','Phone','Due (৳)',''], custs.map(c=>`<tr>
        <td>${escHTML(c.name)}</td><td>${escHTML(c.phone ||'-')}</td>
        <td class="td-num text-pos">${f(c.bal||0)}</td>
        <td style="white-space:nowrap;"><button class="btn btn-xs btn-icon" style="background:#3182ce;color:#fff;" data-x-click="viewPartyLedger('${escJSAttr(c.name)}')" title="View Ledger">👁</button> <button class="btn btn-xs btn-icon" style="background:#f5a623;color:#000;margin-right:2px;" data-x-click="editCust(${c.id})" title="Edit">✏️</button><button class="btn btn-danger btn-xs btn-icon" data-x-click="delCust(${c.id})" title="Delete">🗑</button></td>
      </tr>`).join(''));
    actionsEl.innerHTML = closeBtn+'<button class="btn btn-success" data-x-click="openAddCustomerModalBtn()">➕ Add Customer</button>';
  } else if(_cardCrudType==='partners'){
    titleEl.textContent='🤝 Partner Capital';
    const parts=DB.partners||[];
    bodyEl.innerHTML = parts.length===0 ? '<div class="empty"><p>No partners added yet.</p></div>' :
      tbl(['Name','Capital (৳)','Share %','Role',''], parts.map(p=>`<tr>
        <td>${escHTML(p.name)}</td><td class="td-num text-pos">${f(p.cap||0)}</td>
        <td>${p.share||0}%</td><td>${escHTML(p.role ||'-')}</td>
        <td style="white-space:nowrap;"><button class="btn btn-danger btn-xs btn-icon" data-x-click="delPart(${p.id})" title="Delete">🗑</button></td>
      </tr>`).join(''));
    actionsEl.innerHTML = closeBtn+'<button class="btn btn-success" data-x-click="openAddPartnerModalBtn()">➕ Add Partner</button>';
  } else if(_cardCrudType==='banks'){
    titleEl.textContent='🏦 Bank Accounts';
    const banks=DB.banks||[];
    bodyEl.innerHTML = banks.length===0 ? '<div class="empty"><p>No bank accounts added yet.</p></div>' :
      tbl(['Name','Bank','Balance (৳)',''], banks.map(b=>`<tr>
        <td>${escHTML(b.name)}</td><td>${escHTML(b.bank ||'-')}</td>
        <td class="td-num ${(b.bal||0)>=0?'text-pos':'text-neg'}">${f(b.bal||0)}</td>
        <td style="white-space:nowrap;"><button class="btn btn-danger btn-xs btn-icon" data-x-click="delBank(${b.id})" title="Delete">🗑</button></td>
      </tr>`).join(''));
    actionsEl.innerHTML = closeBtn+'<button class="btn btn-success" data-x-click="openBankModal()">➕ Add Account</button>';
  } else if(_cardCrudType==='assets'){
    titleEl.textContent='🏭 Fixed Assets';
    const assets=DB.assets||[];
    bodyEl.innerHTML = assets.length===0 ? '<div class="empty"><p>No assets added yet.</p></div>' :
      tbl(['Name','Category','Value (৳)','Dep %',''], assets.map(a=>`<tr>
        <td>${escHTML(a.name)}</td><td>${escHTML(a.category ||'-')}</td>
        <td class="td-num text-neu">${f(a.val||0)}</td><td>${a.dep||0}%</td>
        <td style="white-space:nowrap;"><button class="btn btn-danger btn-xs btn-icon" data-x-click="delAsset(${a.id})" title="Delete">🗑</button></td>
      </tr>`).join(''));
    actionsEl.innerHTML = closeBtn+'<button class="btn btn-success" data-x-click="openModal(\'mAsset\')">➕ Add Asset</button>';
  } else if(_cardCrudType==='advances'){
    titleEl.textContent='📤 Supplier Advances';
    const supps=(DB.customers||[]).filter(c=>isSupplierParty(c)&&(c.bal||0)<0).sort((a,b)=>(a.bal||0)-(b.bal||0));
    bodyEl.innerHTML = supps.length===0 ? '<div class="empty"><p>No supplier advances recorded.</p></div>' :
      tbl(['Name','Phone','Advance (৳)',''], supps.map(c=>`<tr>
        <td>${escHTML(c.name)}</td><td>${escHTML(c.phone ||'-')}</td>
        <td class="td-num text-neg">${f(Math.abs(c.bal||0))}</td>
        <td style="white-space:nowrap;"><button class="btn btn-xs btn-icon" style="background:#3182ce;color:#fff;" data-x-click="viewPartyLedger('${escJSAttr(c.name)}')" title="View Ledger">👁</button> <button class="btn btn-xs btn-icon" style="background:#f5a623;color:#000;margin-right:2px;" data-x-click="editCust(${c.id})" title="Edit">✏️</button><button class="btn btn-danger btn-xs btn-icon" data-x-click="delCust(${c.id})" title="Delete">🗑</button></td>
      </tr>`).join(''));
    actionsEl.innerHTML = closeBtn+'<button class="btn btn-success" data-x-click="openModal(\'mCust\')">➕ Add Supplier</button>';
  } else if(_cardCrudType==='stock'){
    titleEl.textContent='📦 Warehouse Stock';
    const prods=DB.products||[];
    bodyEl.innerHTML = prods.length===0 ? '<div class="empty"><p>No products added yet.</p></div>' :
      tbl(['Product','Unit','Stock','Value (৳)',''], prods.map(p=>`<tr>
        <td>${escHTML(p.name)}</td><td>${escHTML(p.unit ||'-')}</td><td class="td-num">${fn(p.stock||0)}</td>
        <td class="td-num text-pos">${f((p.rate||0)*(p.stock||0))}</td>
        <td style="white-space:nowrap;"><button class="btn btn-danger btn-xs btn-icon" data-x-click="delProd(${p.id})" title="Delete">🗑</button></td>
      </tr>`).join(''));
    actionsEl.innerHTML = closeBtn+'<button class="btn btn-success" data-x-click="openAddProduct()">➕ Add Product</button>';
  } else if(_cardCrudType==='networth'){
    titleEl.textContent='💎 Net Worth Breakdown';
    const customers=(DB.customers||[]).filter(c=>isCustomerParty(c));
    const suppliers=(DB.customers||[]).filter(c=>isSupplierParty(c));
    const recv=customers.filter(c=>(c.bal||0)>0).reduce((s,c)=>s+(c.bal||0),0);
    const bankTotal=(DB.banks||[]).reduce((s,b)=>s+(b.bal||0),0);
    const assetTotal=(DB.assets||[]).reduce((s,a)=>s+(a.val||0),0);
    const stock=stockValue(DB.products);
    const adv=Math.abs(suppliers.filter(s=>(s.bal||0)<0).reduce((s,c)=>s+(c.bal||0),0));
    const totalAssets=recv+bankTotal+assetTotal+stock;
    const net=totalAssets-adv;
    bodyEl.innerHTML = `
      <div class="sum-row"><span class="sum-name">Customer Receivables</span><span class="sum-val pos">${f(recv)}</span></div>
      <div class="sum-row"><span class="sum-name">Bank Balance</span><span class="sum-val pos">${f(bankTotal)}</span></div>
      <div class="sum-row"><span class="sum-name">Fixed Assets</span><span class="sum-val pos">${f(assetTotal)}</span></div>
      <div class="sum-row"><span class="sum-name">Warehouse Stock</span><span class="sum-val pos">${f(stock)}</span></div>
      <div class="sum-row"><span class="sum-name">Supplier Advances (Payable)</span><span class="sum-val neg">-${f(adv)}</span></div>
      <div class="sum-total"><span>NET WORTH</span><span class="text-pos">${f(net)}</span></div>
    `;
    actionsEl.innerHTML = closeBtn+'<button class="btn btn-outline" data-x-click="closeModal(\'mCardCrud\');nav(\'reports\')">Full Balance Sheet →</button>';
  } else if(_cardCrudType==='health'){
    titleEl.textContent='❤️ Business Health Breakdown';
    const customers=(DB.customers||[]).filter(c=>isCustomerParty(c));
    const suppliers=(DB.customers||[]).filter(c=>isSupplierParty(c));
    const partners=DB.partners||[];
    const recv=customers.filter(c=>(c.bal||0)>0).reduce((s,c)=>s+(c.bal||0),0);
    const partTotal=partners.reduce((s,p)=>s+(p.cap||0),0);
    const bankTotal=(DB.banks||[]).reduce((s,b)=>s+(b.bal||0),0);
    const assetTotal=(DB.assets||[]).reduce((s,a)=>s+(a.val||0),0);
    const stock=stockValue(DB.products);
    const adv=Math.abs(suppliers.filter(s=>(s.bal||0)<0).reduce((s,c)=>s+(c.bal||0),0));
    const net=recv+partTotal+bankTotal+assetTotal+stock-adv;
    const health=Math.min(100,Math.round((net/(net+adv+1))*100));
    bodyEl.innerHTML = `
      <div class="sum-row"><span class="sum-name">Net Position</span><span class="sum-val pos">${f(net)}</span></div>
      <div class="sum-row"><span class="sum-name">Total Liabilities (Advances)</span><span class="sum-val neg">${f(adv)}</span></div>
      <div class="sum-total"><span>HEALTH SCORE</span><span class="text-pos">${health}%</span></div>
      <p style="font-size:12px;color:#6b7280;margin-top:10px;">Score = Net Position ÷ (Net Position + Liabilities), capped at 100%. Higher is healthier.</p>
    `;
    actionsEl.innerHTML = closeBtn;
  } else {
    titleEl.textContent='Details';
    bodyEl.innerHTML = '<div class="empty"><p>Nothing to show.</p></div>';
    actionsEl.innerHTML = closeBtn;
  }
}


function toggleSalesCost(){
  const type=(document.getElementById('tx-type')||{}).value||'';
  const isSale=['sale','sales return','sales receipt','sales advance'].includes(type.toLowerCase());
  const sec=document.getElementById('sec-salescost');
  if(sec){
    sec.style.display=isSale?'':'none';
    if(isSale) populateCostRates();
  }
}

function calcTxAmt(){
  const qty=parseFloat(document.getElementById('tx-qty')?.value||0);
  const rate=parseFloat(document.getElementById('tx-rate')?.value||0);
  const amtEl=document.getElementById('tx-amt');
  if(amtEl && qty>0 && rate>0){
    amtEl.value=(qty*rate).toFixed(2);
  }
  calcTxTotalCost();
}
function calcTxTotalCost(){
  const agentA=parseFloat(document.getElementById('tx-agentAcost')?.value||0);
  const agentB=parseFloat(document.getElementById('tx-agentBcost')?.value||0);
  const qc=parseFloat(document.getElementById('tx-qc')?.value||0);
  const unload=parseFloat(document.getElementById('tx-unload')?.value||0);
  const other=parseFloat(document.getElementById('tx-othercost')?.value||0);
  const other2=parseFloat(document.getElementById('tx-othercost2')?.value||0);
  const truckRent=parseFloat(document.getElementById('tx-truckrent')?.value||0);
  const total=agentA+agentB+qc+unload+other+other2+truckRent;
  const el=document.getElementById('tx-totalcost');
  if(el) el.value=total.toFixed(2);
}

function calcTotalCost(){
  const agentA=parseFloat((document.getElementById('tx-agentAcost')||{}).value)||0;
  const agentB=parseFloat((document.getElementById('tx-agentBcost')||{}).value)||0;
  const qc=parseFloat((document.getElementById('tx-qc')||{}).value)||0;
  const unload=parseFloat((document.getElementById('tx-unload')||{}).value)||0;
  const other=parseFloat((document.getElementById('tx-othercost')||{}).value)||0;
  const other2=parseFloat((document.getElementById('tx-othercost2')||{}).value)||0;
  const total=agentA+agentB+qc+unload+other+other2;
  const el=document.getElementById('tx-totalcost');
  if(el) el.value=total>0?total.toFixed(2):'';

  // Auto-calc profit
  const amt = parseFloat(document.getElementById('tx-amt')?.value||0);
  const profitEl = document.getElementById('tx-profit');
  if(profitEl){ const tc = parseFloat(document.getElementById('tx-totalcost')?.value||0); profitEl.value = (amt - tc).toFixed(2); }
  // Auto-category
  const catEl = document.getElementById('tx-cat');
  const txType = document.getElementById('tx-type')?.value||'';
  if(catEl){
    if(['Sale','Sales Return','Sales Receipt','Sales Advance'].includes(txType)) catEl.value='Income';
    else if(['Purchase','Purchase Return','Purchase Payment','Purchase Advance'].includes(txType)) catEl.value='Purchase';
    else if(['Salary Payment','Office Rent','Electricity Bill','Transport Cost','Fuel Expense'].includes(txType)) catEl.value='Expense';
    else if(['Bank Deposit','Bank Withdrawal','Bank Transfer','Bkash Deposit','Bkash Withdrawal'].includes(txType)) catEl.value='Transfer';
    else if(['Partner Capital','Partner Withdrawal','Partner Profit Share'].includes(txType)) catEl.value='Capital';
    else catEl.value='Other';
  }
}

/* Section 8 — Purchase Payment Type auto-defaults from Transaction Type.
   Only touches the field while the user hasn't picked one by hand
   (same "protection flag" pattern used elsewhere in this form — e.g.
   smartCalcAmount's bag/weight auto-fills). Manually choosing a value in
   the dropdown (onPurchasePayTypeChange) also applies a sensible default
   Advance Rate for that payment type, which the user can still overwrite. */
function autoSetPurchasePaymentType(type){
  const el = document.getElementById('tx-purchpaytype');
  if(!el || el.dataset.userEdited==='1') return;
  const isPurch = (typeof ayanIsPurchaseType==='function' && ayanIsPurchaseType(type))
    || ['Purchase','Purchase Return','Supplier Purchase','Warehouse Purchase'].includes(type);
  el.value = isPurch ? 'Partial Advance' : 'Not Applicable';
  try{ calcAdvanceControl(); }catch(e){}
}
window.autoSetPurchasePaymentType = autoSetPurchasePaymentType;

function onPurchasePayTypeChange(){
  const el = document.getElementById('tx-purchpaytype');
  if(!el) return;
  el.dataset.userEdited = '1'; // stop auto-defaulting once the user has chosen
  const rateEl = document.getElementById('tx-advance-rate');
  const defaults = {'Full Advance':100,'Partial Advance':50,'Credit Purchase':0,'Cash on Delivery':0,'Not Applicable':0};
  if(rateEl && Object.prototype.hasOwnProperty.call(defaults, el.value)){
    // Only overwrite the rate if it hasn't been hand-typed either.
    if(!rateEl.dataset.userEdited) rateEl.value = defaults[el.value];
  }
  calcAdvanceControl();
}
window.onPurchasePayTypeChange = onPurchasePayTypeChange;

/* Calculated Advance: a fixed Advance Amount always takes priority; otherwise
   it's the Advance Rate (%) applied to the transaction Amount.
   Remaining Supplier Balance: Amount minus whatever has already been paid
   (Paid box) minus the calculated advance, floored at 0. */
function calcAdvanceControl(){
  const amt = parseFloat(document.getElementById('tx-amt')?.value) || 0;
  const fixedAdv = parseFloat(document.getElementById('tx-advance-amt')?.value) || 0;
  const pct = parseFloat(document.getElementById('tx-advance-rate')?.value) || 0;
  const calcAdv = fixedAdv > 0 ? fixedAdv : (amt * pct / 100);
  const calcEl = document.getElementById('tx-advance-calc');
  if(calcEl) calcEl.value = calcAdv > 0 ? calcAdv.toFixed(4) : '0.0000';

  const paid = parseFloat(document.getElementById('tx-paid')?.value) || 0;
  const remaining = Math.max(0, amt - paid - calcAdv);
  const balEl = document.getElementById('tx-supplier-balance');
  if(balEl) balEl.value = remaining.toFixed(4);
}
window.calcAdvanceControl = calcAdvanceControl;

function applyRatesToCosts(){
  /* FIX (2026-08-20): fell back to tx-qty only, which is blank for every
     weight-based purchase/sale (they use Gross/Net Weight instead), so this
     silently computed everything as 0. Also priced Unload per KG like the
     rest — it's a per-BAG cost (৳3/bag), not per-KG. */
  const qty=parseFloat((document.getElementById('tx-wt')||{}).value)
         || parseFloat((document.getElementById('tx-grosswt')||{}).value)
         || parseFloat((document.getElementById('tx-qty')||{}).value)||0;
  const bags=parseFloat((document.getElementById('tx-bagqty')||{}).value)||0;
  const r={
    agentA:parseFloat((document.getElementById('rate-agentA')||{}).value)||0,
    agentB:parseFloat((document.getElementById('rate-agentB')||{}).value)||0,
    qc:    parseFloat((document.getElementById('rate-qc')||{}).value)||0,
    unload:parseFloat((document.getElementById('rate-unload')||{}).value)||0,
    other: parseFloat((document.getElementById('rate-other')||{}).value)||0
  };
  const map=[
    ['agentA','tx-agentAcost','tag-agentA',qty,'KG'],
    ['agentB','tx-agentBcost','tag-agentB',qty,'KG'],
    ['qc',   'tx-qc',        'tag-qc',     qty,'KG'],
    ['other', 'tx-othercost','tag-other',  qty,'KG']
  ];
  map.forEach(([key,costId,tagId,base,unit])=>{
    const cost=base*r[key];
    const el=document.getElementById(costId);
    const tag=document.getElementById(tagId);
    if(el) el.value=cost>0?cost.toFixed(2):'';
    if(tag) tag.textContent=r[key]>0?(unit+'×'+r[key]):'';
  });
  /* Unloading follows the bag type: per 1000 kg in bulk, per bag otherwise. */
  const bagtype=(document.getElementById('tx-bagtype')||{}).value||'';
  const unl=ayanIsBulk(bagtype) ? (qty/1000)*(parseFloat((document.getElementById('rate-unloadbulk')||{}).value)||ayanBagRules().unloadBulk||0)
                                : bags*r.unload;
  const elU2=document.getElementById('tx-unload'), tagU2=document.getElementById('tag-unload');
  if(elU2) elU2.value=unl>0?unl.toFixed(2):'';
  if(tagU2) tagU2.textContent=unl>0?ayanUnloadLabel(bagtype):'';
  calcTotalCost();
}

function saveCostRates(){
  ayanBagRules();
  ['agentA','agentB','qc','unload','other'].forEach(k=>{
    const el=document.getElementById('rate-'+k);
    if(el) DB.costRates[k]=parseFloat(el.value)||0;
  });
  /* Bulk unloading rate and the per-type bag tare. */
  const ub=document.getElementById('rate-unloadbulk');
  if(ub && ub.value!=='') DB.costRates.unloadBulk=parseFloat(ub.value)||0;
  const tp=document.getElementById('rate-tare-plastic');
  if(tp && tp.value!=='') DB.costRates.tare.Plastic=parseFloat(tp.value)||0;
  const tj=document.getElementById('rate-tare-jute');
  if(tj && tj.value!=='') DB.costRates.tare.Jute=parseFloat(tj.value)||0;
  saveDB();
  toast('Rates saved!','s');
}
/* Put the stored rates back into the boxes when the form opens. */
function ayanFillRateInputs(){
  try{
    var c=ayanBagRules();
    var set=function(id,v){ var el=document.getElementById(id); if(el&&!el.value) el.value=v; };
    set('rate-agentA',c.agentA); set('rate-agentB',c.agentB); set('rate-qc',c.qc);
    set('rate-unload',c.unload); set('rate-other',c.other);
    set('rate-unloadbulk',c.unloadBulk);
    set('rate-tare-plastic',c.tare.Plastic); set('rate-tare-jute',c.tare.Jute);
  }catch(e){}
}
/* Changing the bag type changes both the tare and the unloading basis, so
   the amount and the costs are recalculated the moment it is picked. */
document.addEventListener('change', function(e){
  if(!e.target || e.target.id!=='tx-bagtype') return;
  try{ if(typeof smartCalcAmount==='function') smartCalcAmount(); }catch(_){}
  try{ if(typeof autoFillSaleCosts==='function') autoFillSaleCosts(); }catch(_){}
  try{ if(typeof autoFillPurchaseCosts==='function') autoFillPurchaseCosts(); }catch(_){}
  try{ if(typeof calcTotalCost==='function') calcTotalCost(); }catch(_){}
  try{ if(typeof calcDue==='function') calcDue(); }catch(_){}
}, true);

function resetSaleCosts(){
  ['tx-agentAcost','tx-agentBcost','tx-qc','tx-unload','tx-othercost','tx-othercost2','tx-totalcost'].forEach(id=>{
    const el=document.getElementById(id); if(el) el.value='';
  });
  ['tag-agentA','tag-agentB','tag-qc','tag-unload','tag-other','tag-other2'].forEach(id=>{
    const el=document.getElementById(id); if(el) el.textContent='';
  });
}

function populateCostRates(){
  const r=DB.costRates||{agentA:0.25,agentB:0.30,qc:0.10,unload:3.00,other:0.50};
  ['agentA','agentB','qc','unload','other'].forEach(k=>{
    const el=document.getElementById('rate-'+k);
    if(el && !el.value) el.value=r[k]||0;
  });
  applyRatesToCosts();
}

