function exportData(){
  const data={
    exportDate:new Date().toISOString(),
    summary:{
      customers:(DB.customers||[]).length,
      partners:(DB.partners||[]).length,
      banks:(DB.banks||[]).length,
      products:(DB.products||[]).length,
      assets:(DB.assets||[]).length,
      transactions:(DB.tx||[]).length
    },
    ...DB
  };
  const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');
  a.href=url;
  a.download=`RiceBranOil_Export_${new Date().toISOString().split('T')[0]}.json`;
  a.click();
  URL.revokeObjectURL(url);
  toast('Data exported!','s');
}

// ─────────────────────────────────────────────────────────
// TOAST
// ─────────────────────────────────────────────────────────
function toast(msg,type='s'){
  const el=document.getElementById('toast');
  el.textContent=(type==='s'?'✅ ':type==='e'?'❌ ':'⚠️ ')+msg;
  el.className='toast '+type+' show';
  setTimeout(()=>el.classList.remove('show'),3000);
}

// ─────────────────────────────────────────────────────────
// HELPERS
// ─────────────────────────────────────────────────────────
function v(id){ return (document.getElementById(id)||{}).value||''; }
function set(id,html){
  const el=document.getElementById(id);
  if(el){ if(typeof html==='string'&&html.includes('<')) el.innerHTML=html; else el.textContent=html; }
}

// Safe innerHTML helper — prevents null reference crashes
function sHTML(id, html) {
  const el = document.getElementById(id);
  if (el !== null && el !== undefined) {
    if(el) el.innerHTML = html;
  }
}
// Safe textContent helper
function sTXT(id, txt) {
  const el = document.getElementById(id);
  if (el !== null && el !== undefined) {
    el.textContent = txt;
  }
}

// ─────────────────────────────────────────────────────────
// AGENTS
// ─────────────────────────────────────────────────────────
let currentAgentId = null;

function agentEarned(agId){
  const ag=(DB.agents||[]).find(a=>a.id===agId);
  if(!ag) return 0;
  // Calculate from transactions where this agent is involved
  const txs=(DB.tx||[]).filter(t=>t.agentA===ag.name||t.agentB===ag.name);
  let earned=0;
  txs.forEach(t=>{
    if(t.agentA===ag.name&&t.agentAcost) earned+=parseFloat(t.agentAcost)||0;
    if(t.agentB===ag.name&&t.agentBcost) earned+=parseFloat(t.agentBcost)||0;
  });
  // Also check agentLedger entries
  (DB.agentLedger||[]).filter(l=>l.agentId===agId&&l.type==='earning').forEach(l=>earned+=l.amount||0);
  return earned;
}

function agentPaid(agId){
  return (DB.agentLedger||[]).filter(l=>l.agentId===agId&&l.type==='payment').reduce((s,l)=>s+l.amount,0);
}

function agentBalance(agId){
  return agentEarned(agId) - agentPaid(agId);
}

// ═══════════════════════════════════════════════════════════════
// STOCK WASTAGE & DAMAGE LOG — feature 5
// Tracks natural weight loss / storage damage on raw materials and
// finished goods, and automatically adjusts DB.products stock on save.
// ═══════════════════════════════════════════════════════════════
function saveWastageEntry(){
  const date = v('wst-date'), product = v('wst-product'), qty = parseFloat(v('wst-qty'))||0;
  const reason = v('wst-reason'), loc = v('wst-loc'), note = v('wst-note');
  if(!date || !product || !qty){ toast('Fill Date, Product and Quantity!','e'); return; }
  DB.nid.wastage = (DB.nid.wastage||0)+1;
  /* FIX: this saved the name under `product` while the stock ledger and the
     inventory valuation both read `prod`, so a wastage entry was invisible to
     them — the loss never reached the stock value or the P&L. Both names are
     written now. The hand-adjustment of p.stock that used to sit here has
     gone: stock is derived from the movements (syncStock), which now counts
     wastage, so writing it by hand only got overwritten a moment later. */
  DB.wastage.push({id:DB.nid.wastage, date, prod:product, product, qty, reason, loc, note, createdAt:new Date().toISOString()});
  try{ if(typeof syncStock==='function') syncStock(); }catch(e){}
  saveDB();
  ['wst-qty','wst-note'].forEach(id=>{ const el=document.getElementById(id); if(el) el.value=''; });
  toast('Wastage/damage recorded and stock adjusted','s');
  renderWastage();
}
async function deleteWastageEntry(id){
  const w = (DB.wastage||[]).find(x=>x.id===id);
  if(!w) return;
  if(!await __confirm('Delete this entry? Stock will be restored by '+w.qty+' '+(w.product||''))) return;
  const p = (typeof invFind==='function') ? invFind(w.product) : (DB.products||[]).find(x=>x.name===w.product);
  if(p){ const cur=(typeof stockQtyOf==='function')?stockQtyOf(p):(p.stock||0);
         const nv=cur+(w.qty||0); // reverse the earlier deduction
         if(typeof invSetQty==='function') invSetQty(p,nv); else p.stock=p.qty=p.stockQty=nv; }
  DB.wastage = DB.wastage.filter(x=>x.id!==id);
  saveDB(); renderWastage();
}
function renderWastage(){
  const el = document.getElementById('pg-wastage');
  if(!el) return;
  const productOpts = (DB.products||[]).map(p=>`<option value="${escHTML(p.name)}">${escHTML(p.name)}</option>`).join('');
  const locOpts = MASTER.locations.map(l=>`<option value="${l}">${l}</option>`).join('');
  const rows = (DB.wastage||[]).slice().sort((a,b)=>(a.date<b.date?1:-1)).map(w=>`
    <tr style="border-bottom:1px solid #f3f4f6;">
      <td style="padding:9px 12px;">${w.date}</td>
      <td style="padding:9px 12px;">${escHTML(w.product)}</td>
      <td style="padding:9px 12px;text-align:right;">${pn(w.qty)}</td>
      <td style="padding:9px 12px;">${escHTML(w.reason||'—')}</td>
      <td style="padding:9px 12px;">${w.loc||'—'}</td>
      <td style="padding:9px 12px;font-size:11px;color:#6b7280;">${escHTML(w.note ||'')}</td>
      <td style="padding:9px 12px;text-align:center;"><button data-x-click="deleteWastageEntry(${w.id})" style="background:#fee2e2;color:#dc2626;border:none;padding:4px 10px;border-radius:6px;font-size:11px;cursor:pointer;">Delete</button></td>
    </tr>`).join('');
  const totalQty = (DB.wastage||[]).reduce((s,w)=>s+(w.qty||0),0);
  el.innerHTML = `
    <h2 style="font-size:20px;font-weight:800;color:#0f3d26;margin:0 0 4px;">♻️ Stock Wastage & Damage Log</h2>
    <p style="font-size:12px;color:#6b7280;margin:0 0 16px;">Natural weight loss and storage damage on raw materials / finished goods — auto-adjusts inventory on save.</p>
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:16px;margin-bottom:16px;display:flex;gap:12px;flex-wrap:wrap;align-items:end;">
      <div><label style="font-size:10px;font-weight:700;color:#374151;display:block;">DATE</label><input type="date" id="wst-date" style="padding:7px 10px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;"/></div>
      <div><label style="font-size:10px;font-weight:700;color:#374151;display:block;">PRODUCT</label><select id="wst-product" style="padding:7px 10px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;min-width:160px;"><option value="">-- Select --</option>${productOpts}</select></div>
      <div><label style="font-size:10px;font-weight:700;color:#374151;display:block;">QTY LOST/DAMAGED</label><input type="number" id="wst-qty" min="0" step="0.01" placeholder="0.00" style="padding:7px 10px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;width:110px;"/></div>
      <div><label style="font-size:10px;font-weight:700;color:#374151;display:block;">REASON</label>
        <select id="wst-reason" style="padding:7px 10px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;">
          <option>Natural Weight Loss</option><option>Storage Damage</option><option>Moisture Loss</option><option>Pest/Rodent Damage</option><option>Handling Loss</option><option>Other</option>
        </select>
      </div>
      <div><label style="font-size:10px;font-weight:700;color:#374151;display:block;">LOCATION</label><select id="wst-loc" style="padding:7px 10px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;"><option value="">-- Select --</option>${locOpts}</select></div>
      <div style="flex:1;min-width:160px;"><label style="font-size:10px;font-weight:700;color:#374151;display:block;">NOTE</label><input type="text" id="wst-note" placeholder="Optional note" style="padding:7px 10px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;width:100%;"/></div>
      <button data-x-click="saveWastageEntry()" style="padding:8px 18px;background:#16a34a;color:#fff;border:none;border-radius:6px;font-size:12px;font-weight:700;cursor:pointer;">+ Log Entry</button>
    </div>
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
      <table style="width:100%;border-collapse:collapse;font-size:12px;">
        <thead><tr style="background:#f9fafb;text-align:left;"><th style="padding:9px 12px;">Date</th><th style="padding:9px 12px;">Product</th><th style="padding:9px 12px;text-align:right;">Qty</th><th style="padding:9px 12px;">Reason</th><th style="padding:9px 12px;">Location</th><th style="padding:9px 12px;">Note</th><th style="padding:9px 12px;"></th></tr></thead>
        <tbody>${rows || '<tr><td colspan="7" style="padding:30px;text-align:center;color:#9ca3af;">No wastage/damage entries logged yet.</td></tr>'}</tbody>
      </table>
    </div>
    <div style="margin-top:10px;font-size:12px;color:#6b7280;">Total logged quantity: <strong>${pn(totalQty)}</strong></div>`;
}

// ═══════════════════════════════════════════════════════════════
// BANK LOAN & LC TRACKER — feature 6
// Tracks Letter of Credit margins, bank loan installments and charges.
// ═══════════════════════════════════════════════════════════════
function saveLoanEntry(){
  const type = v('loan-type'), bank = v('loan-bank'), refNo = v('loan-ref');
  const principal = parseFloat(v('loan-principal'))||0;
  const startDate = v('loan-startdate'), dueDate = v('loan-duedate');
  const note = v('loan-note');
  if(!type || !bank || !principal){ toast('Fill Type, Bank and Amount!','e'); return; }
  DB.nid.loans = (DB.nid.loans||0)+1;
  DB.loans.push({id:DB.nid.loans, type, bank, refNo, principal, paid:0, startDate, dueDate, note, status:'Open'});
  saveDB();
  ['loan-ref','loan-principal','loan-note'].forEach(id=>{ const el=document.getElementById(id); if(el) el.value=''; });
  toast('Loan / LC record added','s');
  renderLoans();
}
function addLoanPayment(id){
  const l = (DB.loans||[]).find(x=>x.id===id);
  if(!l) return;
  const amt = parseFloat(prompt('Installment / charge amount to record against '+l.bank+' ('+l.refNo+'):','')||0);
  if(!amt || amt<=0) return;
  l.paid = (l.paid||0) + amt;
  if(l.paid >= l.principal) l.status='Closed';
  saveDB(); renderLoans();
}
async function deleteLoanEntry(id){
  if(!await __confirm('Delete this loan/LC record?')) return;
  DB.loans = DB.loans.filter(x=>x.id!==id);
  saveDB(); renderLoans();
}
function renderLoans(){
  const el = document.getElementById('pg-loans');
  if(!el) return;
  const bankOpts = (DB.banks||[]).map(b=>`<option value="${escHTML(b.name)}">${escHTML(b.name)}</option>`).join('');
  const rows = (DB.loans||[]).slice().sort((a,b)=>(a.startDate<b.startDate?1:-1)).map(l=>{
    const outstanding = (l.principal||0) - (l.paid||0);
    return `<tr style="border-bottom:1px solid #f3f4f6;">
      <td style="padding:9px 12px;">${l.type}</td>
      <td style="padding:9px 12px;">${escHTML(l.bank)}</td>
      <td style="padding:9px 12px;font-size:11px;">${l.refNo||'—'}</td>
      <td style="padding:9px 12px;text-align:right;">৳${pf(l.principal)}</td>
      <td style="padding:9px 12px;text-align:right;color:#16a34a;">৳${pf(l.paid||0)}</td>
      <td style="padding:9px 12px;text-align:right;font-weight:700;color:${outstanding>0?'#dc2626':'#16a34a'};">৳${pf(outstanding)}</td>
      <td style="padding:9px 12px;">${l.dueDate||'—'}</td>
      <td style="padding:9px 12px;text-align:center;"><span style="padding:2px 8px;border-radius:10px;font-size:10px;font-weight:700;background:${l.status==='Closed'?'#dcfce7':'#fef3c7'};color:${l.status==='Closed'?'#16a34a':'#92400e'};">${l.status}</span></td>
      <td style="padding:9px 12px;text-align:center;white-space:nowrap;">
        <button data-x-click="addLoanPayment(${l.id})" style="background:#dbeafe;color:#1e40af;border:none;padding:4px 8px;border-radius:6px;font-size:11px;cursor:pointer;margin-right:4px;">+ Payment</button>
        <button data-x-click="deleteLoanEntry(${l.id})" style="background:#fee2e2;color:#dc2626;border:none;padding:4px 8px;border-radius:6px;font-size:11px;cursor:pointer;">Delete</button>
      </td>
    </tr>`;
  }).join('');
  const totalOutstanding = (DB.loans||[]).reduce((s,l)=>s+((l.principal||0)-(l.paid||0)),0);
  el.innerHTML = `
    <h2 style="font-size:20px;font-weight:800;color:#0f3d26;margin:0 0 4px;">🏦 Bank Loan & LC Tracker</h2>
    <p style="font-size:12px;color:#6b7280;margin:0 0 16px;">Letter of Credit margins, bank loan installments and associated charges.</p>
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:16px;margin-bottom:16px;display:flex;gap:12px;flex-wrap:wrap;align-items:end;">
      <div><label style="font-size:10px;font-weight:700;color:#374151;display:block;">TYPE</label>
        <select id="loan-type" style="padding:7px 10px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;">
          <option>Bank Loan</option><option>LC Margin</option><option>LC Charge</option><option>Overdraft</option>
        </select>
      </div>
      <div><label style="font-size:10px;font-weight:700;color:#374151;display:block;">BANK</label><select id="loan-bank" style="padding:7px 10px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;"><option value="">-- Select --</option>${bankOpts}</select></div>
      <div><label style="font-size:10px;font-weight:700;color:#374151;display:block;">REF / LC NO</label><input type="text" id="loan-ref" placeholder="e.g. LC-2026-001" style="padding:7px 10px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;"/></div>
      <div><label style="font-size:10px;font-weight:700;color:#374151;display:block;">AMOUNT (৳)</label><input type="number" id="loan-principal" min="0" step="0.01" placeholder="0.00" style="padding:7px 10px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;width:120px;"/></div>
      <div><label style="font-size:10px;font-weight:700;color:#374151;display:block;">START DATE</label><input type="date" id="loan-startdate" style="padding:7px 10px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;"/></div>
      <div><label style="font-size:10px;font-weight:700;color:#374151;display:block;">DUE DATE</label><input type="date" id="loan-duedate" style="padding:7px 10px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;"/></div>
      <div style="flex:1;min-width:160px;"><label style="font-size:10px;font-weight:700;color:#374151;display:block;">NOTE</label><input type="text" id="loan-note" placeholder="Optional note" style="padding:7px 10px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;width:100%;"/></div>
      <button data-x-click="saveLoanEntry()" style="padding:8px 18px;background:#16a34a;color:#fff;border:none;border-radius:6px;font-size:12px;font-weight:700;cursor:pointer;">+ Add Record</button>
    </div>
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
      <table style="width:100%;border-collapse:collapse;font-size:12px;">
        <thead><tr style="background:#f9fafb;text-align:left;"><th style="padding:9px 12px;">Type</th><th style="padding:9px 12px;">Bank</th><th style="padding:9px 12px;">Ref/LC No</th><th style="padding:9px 12px;text-align:right;">Principal</th><th style="padding:9px 12px;text-align:right;">Paid</th><th style="padding:9px 12px;text-align:right;">Outstanding</th><th style="padding:9px 12px;">Due Date</th><th style="padding:9px 12px;text-align:center;">Status</th><th style="padding:9px 12px;"></th></tr></thead>
        <tbody>${rows || '<tr><td colspan="9" style="padding:30px;text-align:center;color:#9ca3af;">No loan / LC records yet.</td></tr>'}</tbody>
      </table>
    </div>
    <div style="margin-top:10px;font-size:12px;color:#6b7280;">Total outstanding: <strong style="color:#dc2626;">৳${pf(totalOutstanding)}</strong></div>`;
}

function renderAgents(data){
  const agents = data||DB.agents;
  const totalMonthly = agents.reduce((s,a)=>s+a.monthly,0);
  const totalDue = agents.reduce((s,a)=>s+agentBalance(a.id),0);
  const totalPaid = agents.reduce((s,a)=>s+agentPaid(a.id),0);

  set('k-agtotal', agents.length);
  set('k-agmonthly', f(totalMonthly));
  set('k-agdue', f(totalDue));
  set('k-agpaid', f(totalPaid));
  set('nb-ag', agents.length);

  // Agent Cards
  const cards = document.getElementById('ag-cards');
  if(cards){
    if(cards) cards.innerHTML = agents.map(ag=>{
      const earned = agentEarned(ag.id);
      const paid = agentPaid(ag.id);
      const bal = earned - paid;
      const pct = earned>0 ? Math.min(100,Math.round(paid/earned*100)) : 0;
      return `<div style="background:var(--white);border-radius:var(--radius-lg);padding:18px;box-shadow:var(--shadow);border-top:4px solid var(--purple);">
        <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:10px;">
          <div>
            <div style="font-size:15px;font-weight:800;color:var(--gray-900);">${escHTML(ag.name)}</div>
            <div style="font-size:11px;color:var(--gray-400);">${escHTML(ag.role ||'Agent A')} ${ag.area?'· '+escHTML(ag.area):''} ${ag.phone?'· '+escHTML(ag.phone):''}</div>
          </div>
          <span class="badge ${bal>0?'b-red':'b-green'}">${bal>0?'Due':'Clear'}</span>
        </div>
        <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-bottom:10px;">
          <div style="text-align:center;background:var(--gray-50);border-radius:8px;padding:8px;">
            <div style="font-size:10px;color:var(--gray-400);font-weight:700;">EARNED</div>
            <div style="font-size:13px;font-weight:800;color:var(--accent);">${f(earned)}</div>
          </div>
          <div style="text-align:center;background:var(--gray-50);border-radius:8px;padding:8px;">
            <div style="font-size:10px;color:var(--gray-400);font-weight:700;">PAID</div>
            <div style="font-size:13px;font-weight:800;color:var(--success);">${f(paid)}</div>
          </div>
          <div style="text-align:center;background:${bal>0?'#fff5f5':'#f0fff4'};border-radius:8px;padding:8px;">
            <div style="font-size:10px;color:var(--gray-400);font-weight:700;">BALANCE</div>
            <div style="font-size:13px;font-weight:800;color:${bal>0?'var(--danger)':'var(--success)'};">${f(bal)}</div>
          </div>
        </div>
        <div style="margin-bottom:10px;">
          <div style="display:flex;justify-content:space-between;font-size:10px;color:var(--gray-400);margin-bottom:3px;">
            <span>Payment Progress</span><span>${pct}%</span>
          </div>
          <div style="height:6px;background:var(--gray-200);border-radius:3px;overflow:hidden;">
            <div style="height:100%;width:${pct}%;background:${pct>=100?'var(--success)':pct>=50?'var(--warning)':'var(--danger)'};border-radius:3px;transition:width 1s;"></div>
          </div>
        </div>
        ${ag.monthly>0?`<div style="font-size:11px;color:var(--gray-500);margin-bottom:8px;">Monthly Rate: <strong>${f(ag.monthly)}</strong></div>`:''}
        <div style="display:flex;gap:6px;">
          <button class="btn btn-outline btn-sm" style="flex:1;" data-x-click="openAgLedger(${ag.id})">📒 Ledger</button>
          <button class="btn btn-success btn-sm" style="flex:1;" data-x-click="openAgPayModalFor(${ag.id})">💳 Pay</button>
        </div>
      </div>`;
    }).join('');
  }

  // Table
  set('t-agent', agents.map((ag,i)=>{
    const earned = agentEarned(ag.id);
    const paid = agentPaid(ag.id);
    const bal = earned - paid;
    const lastPay = (DB.agentLedger||[]).filter(l=>l.agentId===ag.id&&l.type==='payment').sort((a,b)=>b.date.localeCompare(a.date))[0];
    return `<tr>
      <td class="text-muted fs11">${i+1}</td>
      <td><strong>${escHTML(ag.name)}</strong></td>
      <td><span class="badge b-purple">${escHTML(ag.role ||'Agent A')}</span></td>
      <td>${escHTML(ag.phone ||'-')}</td>
      <td class="fs11">${escHTML(ag.area||'-')}</td>
      <td class="td-num">${ag.monthly?f(ag.monthly):'-'}</td>
      <td class="td-num text-pos">${f(paid)}</td>
      <td class="td-num ${bal>0?'text-neg':'text-pos'}">${f(bal)}</td>
      <td class="fs11">${lastPay?lastPay.date:'-'}</td>
      <td><span class="badge ${bal>0?'b-red':'b-green'}">${bal>0?'Due':'Clear'}</span></td>
      <td><button class="btn btn-outline btn-xs" data-x-click="openAgLedger(${ag.id})">📒 View</button></td>
      <td><button class="btn btn-success btn-xs" data-x-click="openAgPayModalFor(${ag.id})">💳 Pay</button></td>
      <td style="white-space:nowrap;"><button class="btn btn-xs btn-icon" style="background:#f5a623;color:#000;margin-right:2px;" data-x-click="printAgentLedger(${ag.id})" title="Print">🖨️</button><button class="btn btn-danger btn-xs btn-icon" data-x-click="delAgent(${ag.id})" title="Delete">🗑</button></td>
    </tr>`;
  }).join(''));
}

function agSearch(v){
  renderAgents((DB.agents||[]).filter(a=>a.name.toLowerCase().includes(v.toLowerCase())||
    (a.area||'').toLowerCase().includes(v.toLowerCase())));
}

function editAgent(id){
  const a=(DB.agents||[]).find(a=>a.id===id);
  if(!a) return;
  const eid=document.getElementById('ag-edit-id');
  if(eid) eid.value=id;
  ['ag-name','ag-phone','ag-rate','ag-addr'].forEach(fid=>{
    const el=document.getElementById(fid);
    if(!el) return;
    const keyMap={'ag-name':'name','ag-phone':'phone','ag-rate':'rate','ag-addr':'address'};
    el.value=a[keyMap[fid]||fid.replace('ag-','')]||'';
  });
  const title=document.querySelector('#mAgent .modal-title');
  if(title) title.innerHTML='✏️ Edit Agent <span class="modal-close" data-x-click="closeModal(\'mAgent\')">✕</span>';
  openModal('mAgent');
}

function saveAgent(){
  const name = v('ag-name').trim();
  if(!name){toast('Agent name required!','e');return;}
  DB.agents.push({
    id:DB.nid.ag++, name,
    role:v('ag-role')||'Agent A',
    phone:v('ag-phone'), area:v('ag-area'),
    monthly:parseFloat(v('ag-monthly'))||0,
    pertrip:parseFloat(v('ag-pertrip'))||0,
    opening:parseFloat(v('ag-opening'))||0,
    totalPaid:0, notes:v('ag-notes')
  });
  saveDB();
  closeModal('mAgent');
  renderAgents();
  updateAgentDL();
  toast('Cost person added!','s');
}

async function delAgent(id){
  if(!await __confirm('Delete this agent and all their ledger entries?')) return;
  DB.agents = (DB.agents||[]).filter(a=>a.id!==id);
  DB.agentLedger = (DB.agentLedger||[]).filter(l=>l.agentId!==id);
  saveDB();
  renderAgents();
  toast('Agent deleted','s');
}

// ── LEDGER ──
function openAgLedger(agId){
  currentAgentId = agId;
  const ag = (DB.agents||[]).find(a=>a.id===agId);
  if(!ag) return;
  const earned = agentEarned(agId);
  const paid = agentPaid(agId);
  const bal = earned - paid;

  set('ag-ledger-title', `📒 Ledger — ${ag.name} (${ag.area||'All Routes'})`);

  set('ag-ledger-kpis',`
    <div class="kpi-card c-blue" data-icon="💰" style="margin:0;" data-x-click="nav('agents')" title="Click to view Agents">
      <div class="kpi-label">Total Earned</div>
      <div class="kpi-value">${f(earned)}</div>
      <div class="kpi-sub">From transactions + opening</div>
    </div>
    <div class="kpi-card c-green" data-icon="✅" style="margin:0;" data-x-click="nav('agents')" title="Click to view Agents">
      <div class="kpi-label">Total Paid</div>
      <div class="kpi-value">${f(paid)}</div>
      <div class="kpi-sub">All payments made</div>
    </div>
    <div class="kpi-card ${bal>0?'c-red':'c-green'}" data-icon="${bal>0?'⏳':'🎉'}" style="margin:0;" data-x-click="nav('agents')" title="Click to view Agents">
      <div class="kpi-label">Outstanding Balance</div>
      <div class="kpi-value">${f(bal)}</div>
      <div class="kpi-sub">${bal>0?'Still owed to agent':'Fully paid'}</div>
    </div>
  `);

  // Build ledger rows: transactions where this agent appears + payment entries
  let rows = [];
  let running = ag.opening||0;

  // Opening balance row
  if(ag.opening>0){
    rows.push({date:'Opening',desc:'Opening Balance',ref:'-',earned:ag.opening,paid:0,type:'opening'});
  }

  // Transaction rows
  const role = ag.role||'Agent A';
  const nm = ag.name.toLowerCase();
  (DB.tx||[]).forEach(t=>{
    let agEarned = 0;
    let desc = '';
    if(role==='Agent A'&&(t.agentA||'').toLowerCase()===nm&&t.agentAcost>0){
      agEarned=t.agentAcost; desc=`Agent A — ${t.type} | ${t.party||''}`;
    } else if(role==='Agent B'&&(t.agentB||'').toLowerCase()===nm&&t.agentBcost>0){
      agEarned=t.agentBcost; desc=`Agent B — ${t.type} | ${t.party||''}`;
    } else if(role==='QC Person'&&(t.qcperson||'').toLowerCase()===nm&&t.qc>0){
      agEarned=t.qc; desc=`QC — ${t.type} | ${t.party||''}`;
    } else if(role==='Unloader'&&(t.unloadperson||'').toLowerCase()===nm&&t.unload>0){
      agEarned=t.unload; desc=`Unload — ${t.type} | ${t.party||''}`;
    } else if(role==='Other Cost Person'&&(t.otherperson||'').toLowerCase()===nm&&t.othercost>0){
      agEarned=t.othercost; desc=`Other Cost — ${t.type} | ${t.party||''}`;
    } else if(role==='Another 2 Person'&&(t.otherperson2||'').toLowerCase()===nm&&t.othercost2>0){
      agEarned=t.othercost2; desc=`Another 2 Cost — ${t.type} | ${t.party||''}`;
    }
    if(agEarned>0){
      rows.push({date:t.date,desc,ref:t.inv||'TX-'+t.id,earned:agEarned,paid:0,type:'earned'});
    }
  });

  // Payment rows
  (DB.agentLedger||[]).filter(l=>l.agentId===agId&&l.type==='payment').forEach(l=>{
    rows.push({date:l.date,desc:l.desc||'Payment',ref:'PAY-'+l.id,earned:0,paid:l.amount,type:'payment',mode:l.mode,notes:l.notes});
  });

  // Sort by date
  rows.sort((a,b)=>a.date.localeCompare(b.date));

  // Render with running balance
  let runBal = 0;
  set('t-ag-ledger', rows.length===0
    ? `<tr><td colspan="9" style="text-align:center;color:var(--gray-400);padding:24px;">No ledger entries yet. Transactions with this agent will appear here automatically.</td></tr>`
    : rows.map((r,i)=>{
        runBal += r.earned - r.paid;
        return `<tr style="${r.type==='payment'?'background:#f0fff4;':''}">
          <td class="text-muted fs11">${i+1}</td>
          <td>${r.date}</td>
          <td class="fs11">${escHTML(r.desc)}</td>
          <td class="fs11">${escHTML(r.ref)}</td>
          <td class="td-num ${r.earned>0?'text-pos':''}">${r.earned>0?f(r.earned):'-'}</td>
          <td class="td-num ${r.paid>0?'text-neg':''}">${r.paid>0?f(r.paid):'-'}</td>
          <td class="td-num ${runBal>0?'text-neg':'text-pos'} fw8">${f(runBal)}</td>
          <td>${r.mode?`<span class="badge b-gray">${r.mode}</span>`:'-'}</td>
          <td class="fs11">${escHTML(r.notes ||'-')}</td>
        </tr>`;
      }).join('')
  );

  document.getElementById('ag-ledger-wrap').style.display='block';
  document.getElementById('ag-ledger-wrap').scrollIntoView({behavior:'smooth',block:'start'});
}

function closeAgLedger(){
  document.getElementById('ag-ledger-wrap').style.display='none';
  currentAgentId=null;
}

// ── PAYMENT ──
function openAgPayModal(){
  if(!currentAgentId) return;
  openAgPayModalFor(currentAgentId);
}

function openAgPayModalFor(agId){
  currentAgentId = agId;
  const ag = (DB.agents||[]).find(a=>a.id===agId);
  if(!ag) return;
  const bal = agentBalance(agId);
  set('ag-pay-info',`
    <div style="display:flex;justify-content:space-between;align-items:center;">
      <div><strong style="font-size:15px;">${escHTML(ag.name)}</strong><br>
      <span style="font-size:11px;color:var(--gray-400);">${escHTML(ag.area||'')}</span></div>
      <div style="text-align:right;">
        <div style="font-size:11px;color:var(--gray-400);">Outstanding Balance</div>
        <div style="font-size:20px;font-weight:900;color:${bal>0?'var(--danger)':'var(--success)'};">${f(bal)}</div>
      </div>
    </div>
  `);
  document.getElementById('agp-date').value = new Date().toISOString().split('T')[0];
  document.getElementById('agp-amount').value = bal>0?bal.toFixed(2):'';
  document.getElementById('agp-desc').value = `Payment to ${ag.name}`;
  openModal('mAgPay');
}

function saveAgPay(){
  const date = v('agp-date');
  const amount = parseFloat(v('agp-amount'));
  if(!date||!amount){toast('Date and amount required!','e');return;}
  if(!currentAgentId){toast('No agent selected!','e');return;}
  DB.agentLedger.push({
    id:DB.nid.agl++, agentId:currentAgentId, type:'payment',
    date, amount, mode:v('agp-mode'),
    desc:v('agp-desc'), notes:v('agp-notes')
  });
  saveDB();
  closeModal('mAgPay');
  toast('Payment recorded!','s');
  renderAgents();
  if(document.getElementById('ag-ledger-wrap').style.display!=='none'){
    openAgLedger(currentAgentId);
  }
}

function updateAgentDL(){
  const agents=DB.agents||[];
  const opts='<option value="">-- Select Agent --</option>'+
    agents.map(a=>`<option value="${escHTML(a.name)}">${escHTML(a.name)}</option>`).join('');
  const dlOpts=agents.map(a=>`<option value="${escHTML(a.name)}"></option>`).join('');
  ['tx-agentA','tx-agentB','dl-agents'].forEach(id=>{
    const el=document.getElementById(id);
    if(!el) return;
    if(el.tagName==='SELECT') el.innerHTML=opts;
    else if(el.tagName==='DATALIST') el.innerHTML=dlOpts;
  });
}

// ─────────────────────────────────────────────────────────
// KEYBOARD SHORTCUTS
// ─────────────────────────────────────────────────────────
document.addEventListener('keydown',e=>{
  if(e.key==='Escape') document.querySelectorAll('.overlay.open').forEach(o=>o.classList.remove('open'));
  if(e.ctrlKey&&e.key==='n'){e.preventDefault();openModal('mTx');}
});

// ─────────────────────────────────────────────────────────
// INIT
// ─────────────────────────────────────────────────────────
function init(){
  setTimeout(()=>initPushNotifications(),1000);
  setTimeout(()=>initMobileExperience(),400);
  // v27 new features
  setTimeout(()=>initPWA(),500);
  setTimeout(()=>initSmartNotifications(),2000);
  setTimeout(()=>initBranding(),300);
  setTimeout(()=>initGlobalSearch(),300);
  initAutoSave();
  initTheme();
  loadDB();
  try{migrateEntityCodes();}catch(e){}
  document.getElementById('dateChip').textContent=
    new Date().toLocaleDateString('en-IN',{weekday:'short',year:'numeric',month:'short',day:'numeric'});
  syncPartyDropdowns();
  updateAgentDL();
  // Close modals when clicking overlay background
  // BUGFIX (2026-08-24): "the page goes away if I double-click, or click a
  // little harder, right after opening New Transaction". Reproduced it:
  // a trigger button (e.g. "➕ New Transaction") sits at screen coordinates
  // that, the instant the modal opens, become covered by this same
  // full-screen overlay backdrop (the modal's own content box is centered
  // elsewhere, not over the button). So the SECOND click of a fast
  // double-click — or a firm click a mouse/trackpad reports as two clicks —
  // lands squarely on the overlay instead of the button, and this very
  // handler (e.target===overlay) closed the modal a fraction of a second
  // after it opened. Fix: ignore an outside-click that arrives within
  // 400ms of the modal being opened (openModal() stamps data-openedAt);
  // a deliberate "click outside to dismiss" always comes later than that,
  // so real close-by-clicking-outside still works exactly as before.
  document.querySelectorAll('.overlay').forEach(o=>{
    o.addEventListener('click',function(e){
      if(e.target!==this) return;
      var openedAt = +(this.dataset.openedAt||0);
      if(openedAt && (Date.now()-openedAt) < 400) return;
      closeModal(this.id);
    });
  });
}

// Defer startup until all script blocks are parsed — init() calls functions
// (initTheme, initPWA, initSmartNotifications, ...) defined in later \x3cscript\x3e blocks.
if(document.readyState==='loading'){
  document.addEventListener('DOMContentLoaded', init);
}else{
  init();
}
</script>

