<script nonce="<?php echo $cspNonceAttr; ?>">
// ═══════════════════════════════════════════════════════
// PRINT SYSTEM — AYAN AGRO INTERNATIONAL LIMITED
// ═══════════════════════════════════════════════════════

const TODAY = () => new Date().toLocaleDateString('en-GB');

/* ═══════════════════════════════════════════════════════════════════
   PRINT TEMPLATE HELPERS  (fix pack)

   Every printed document used to classify transactions with its own
   hardcoded list of type names. Those lists were written against names
   this app does not use — of the 18 expense categories in the printed
   P&L, 17 ("Office Rent", "Salary Payment", "Electricity Bill" …) are
   not transaction types here at all, so printed expenses came out at
   almost zero and printed profit was overstated by nearly every taka of
   cost recorded. The same lists made money COMING IN (Customer
   Collection, Bkash Receive, Partner Fund) print as an outflow.

   These helpers route every printed document through the same engines
   the screens already use — ayanPL(), isRevenueTx(), isCogsTx() and
   AYAN_MONEY_IN — so a printed statement can no longer disagree with
   the one on screen.
   ═══════════════════════════════════════════════════════════════════ */

/* Company details for a letterhead. Settings → Company Information saves
   companyPhone/companyEmail/companyAddress, while the Branding form saves
   plain phone/email/address; the print windows read whichever exists.
   (syncLetterheadFromSettings() already did this, but only for the
   in-page #print-area — never for these pop-up windows.) */
function prtCo(){
  const s=(window.DB&&DB.settings)||{};
  return {
    /* Defaults come from the company letterhead, so a printed document is
       correct even before Settings is filled in. Anything saved in
       Settings -> Company Information still wins over these.
       Email is deliberately left blank: the address on the letterhead
       supplied was a placeholder, so put the real one in Settings. */
    name    : s.companyName    || 'AYAN AGRO INTERNATIONAL LIMITED',
    tagline : s.companyTagline || s.tagline || 'Premium Rice Bran Oil Trading & Distribution',
    address : s.companyAddress || s.address || 'Mojumpur, Kushtia',
    region  : s.companyRegion  || s.region  || 'Dhaka, Bangladesh',
    phone   : s.companyPhone   || s.phone   || '01725219156',
    phone2  : s.companyPhone2  || s.phone2  || '01711404063',
    email   : s.companyEmail   || s.email   || '',
    website : s.companyWebsite || s.website || '',
    sister  : s.sisterConcern  || s.companySister || 'M S Karima Enterprise',
    tin     : s.companyTIN     || s.tin     || '',
    bin     : s.companyBIN     || '',
    vat     : s.companyVAT     || '',
    logo    : s.logoEmoji      || '🌾'
  };
}
/* The contact line every template prints under the company name. Only the
   parts that are actually filled in appear, so a half-filled Settings page
   never prints stray separators or an empty "📞". */
function prtContact(){
  const c=prtCo(), bits=[];
  /* The region is only appended when the address does not already say it,
     so a Settings address of "Dhaka, Bangladesh" cannot print as
     "Dhaka, Bangladesh, Dhaka, Bangladesh". */
  const _sameRegion = c.region && c.address &&
        c.address.toLowerCase().indexOf(c.region.toLowerCase()) >= 0;
  if(c.address) bits.push('📍 '+c.address+((c.region && !_sameRegion)?', '+c.region:''));
  if(c.phone)   bits.push('📞 '+c.phone+(c.phone2?', '+c.phone2:''));
  if(c.email)   bits.push('✉️ '+c.email);
  if(c.website) bits.push('🌐 '+c.website);
  return bits.join(' &nbsp;|&nbsp; ');
}
function prtFooter(){
  const c=prtCo(), bits=[c.name];
  if(c.sister) bits.push('Sister Concern: '+c.sister);
  if(c.bin)    bits.push('BIN: '+c.bin);
  if(c.tin)    bits.push('TIN: '+c.tin);
  return bits.join(' • ');
}

/* Does this transaction bring money IN? Uses the shared AYAN_MONEY_IN set
   that the bank ledger and the balance rebuild already use, so the sign on
   a printed row can never contradict the bank ledger. */
function prtIsMoneyIn(t){
  const ty=String((t&&t.type)||'').toLowerCase();
  try{
    if(window.AYAN_MONEY_IN && window.AYAN_MONEY_IN.has(ty)) return true;
    if(window.AYAN_SALE_TYPES_LC && window.AYAN_SALE_TYPES_LC.has(ty)) return true;
  }catch(e){}
  return false;
}

/* Every transaction type that is an operating expense — derived from the
   shared AYAN_NON_EXPENSE set rather than from a list of invented names,
   so a new expense type added to the form is counted automatically. */
function prtIsExpense(t){
  const ty=String((t&&t.type)||'').toLowerCase();
  if(!ty) return false;
  try{ if(window.AYAN_NON_EXPENSE && window.AYAN_NON_EXPENSE.has(ty)) return false; }catch(e){}
  try{ if(window.isRevenueTx && window.isRevenueTx(t)) return false; }catch(e){}
  try{ if(window.isCogsTx && window.isCogsTx(t)) return false; }catch(e){}
  return true;
}

/* Transaction types that are a customer receipt, for the Payment Receipt
   document. The old list ('Sales Receipt', 'Cash Received',
   'Payment Received') contained no name this app actually uses, so the
   receipt printer could never find anything to print. */
const PRT_RECEIPT_TYPES=['Customer Collection','Customer Payment Received',
  'Advance from Customer','Sales Receipt','Sales Advance','Bkash Receive',
  'Bkash Receive from Agent','Cash Received','Payment Received'];
function prtIsReceipt(t){ return PRT_RECEIPT_TYPES.indexOf(String((t&&t.type)||''))>=0; }

// ── Letterhead ⇄ Company Settings sync ────────────────────────────────
// Whatever is saved in Settings → Company Information automatically shows on
// every printed letterhead. Empty settings keep the built-in defaults, so the
// design is unchanged unless the user customises it.
function syncLetterheadFromSettings(){
  try{
    const s = (DB && DB.settings) || {};
    // NOTE: the live "Save Branding" form (saveBranding()) writes plain keys
    // (phone/email/website/address/tin) — accept both those and the older
    // company-prefixed keys so the letterhead reflects whatever was actually saved.
    const companyPhone   = s.companyPhone   || s.phone   || '';
    const companyEmail   = s.companyEmail   || s.email   || '';
    const companyWebsite = s.companyWebsite || s.website || '';
    const companyAddress = s.companyAddress || s.address || '';
    const companyTIN     = s.companyTIN     || s.tin     || '';
    const companyVAT     = s.companyVAT     || '';
    const companyBIN     = s.companyBIN     || '';
    const companyConcern = s.companyConcern || s.businessType || '';
    const footerText     = s.footerText     || s.invoiceFooter || '';

    const area = document.getElementById('print-area');
    if(!area) return;
    const setTxt = (sel, val) => { const el = area.querySelector(sel); if(el && val) el.textContent = val; };
    setTxt('.lh-company', s.companyName ? String(s.companyName).toUpperCase() : '');
    if(companyConcern) setTxt('.lh-concern', 'Concern: ' + companyConcern);
    const contact = area.querySelector('.lh-contact-right');
    if(contact){
      const divs = contact.querySelectorAll('div');
      if(divs[0] && companyPhone)   divs[0].textContent = '📞 ' + companyPhone;
      if(divs[1] && companyEmail)   divs[1].textContent = '✉️ ' + companyEmail;
      if(divs[2] && companyWebsite) divs[2].textContent = '🌐 ' + companyWebsite;
    }
    const addr = area.querySelector('.lh-address-bar');
    if(addr && (companyAddress || companyTIN || companyBIN || companyVAT)){
      const bits = [];
      bits.push('📍 ' + (companyAddress || 'Head Office: Dhaka, Bangladesh'));
      if(s.tradeLicense) bits.push('Trade License: ' + s.tradeLicense);
      if(companyTIN)   bits.push('TIN: ' + companyTIN);
      if(companyVAT)   bits.push('VAT Reg: ' + companyVAT);
      if(companyBIN)   bits.push('BIN: ' + companyBIN);
      addr.innerHTML = bits.map(b=>'<span></span>').join('<span class="lh-dot">|</span>');
      addr.querySelectorAll('span:not(.lh-dot)').forEach((sp,i)=>sp.textContent = bits[i]);
    }
    const foot = area.querySelector('.lh-footer-note');
    if(foot && (footerText || companyEmail || companyPhone)){
      foot.textContent = (footerText ? footerText + ' | ' : 'This is a computer-generated document. ')
        + 'For queries contact: ' + (companyEmail || 'admin@ayanagro.com')
        + (companyPhone ? ' | ' + companyPhone : '');
    }
  }catch(e){ /* letterhead sync is best-effort */ }
}

function openPrintModal(title, docNo, content, ref=''){
  syncLetterheadFromSettings();
  document.getElementById('print-modal-title').textContent = '🖨️ ' + title;
  document.getElementById('print-doc-title').textContent = title;
  document.getElementById('print-doc-date').textContent = TODAY();
  document.getElementById('print-doc-no').textContent = docNo || '—';
  document.getElementById('print-doc-ref').textContent = ref || '—';
  document.getElementById('print-content').innerHTML = content;
  document.getElementById('print-modal').classList.add('open');
  document.body.style.overflow = 'hidden';
}

// ── Print a whole report page on the company letterhead ──────────────────
// Many reports (VAT, aging, expense analysis, etc.) were printing via a bare
// window.print(), which skips the letterhead entirely. This clones the
// report's live page content, drops the interactive filter controls (turning
// each into plain text showing whatever was selected), and routes it through
// the same letterhead system as every other document.
function printPageViaLetterhead(pageId, title, ref){
  const src = document.getElementById(pageId);
  if(!src){ window.print(); return; }
  const clone = src.cloneNode(true);
  clone.querySelectorAll('input,select,textarea').forEach(function(el){
    const span = document.createElement('span');
    span.style.cssText = 'font-weight:700;padding:0 4px;';
    if(el.tagName==='SELECT' && el.selectedOptions && el.selectedOptions.length){
      span.textContent = [...el.selectedOptions].map(o=>o.textContent).join(', ');
    } else {
      span.textContent = el.value || '';
    }
    el.replaceWith(span);
  });
  clone.querySelectorAll('button,.btn,.no-print').forEach(function(el){ el.remove(); });
  const docNo = title.replace(/[^A-Za-z]/g,'').slice(0,4).toUpperCase() + '-' + Date.now().toString().slice(-6);
  openPrintModal(title, docNo, clone.innerHTML, ref || '');
}

// ── GENERAL PRINT: print whatever page is currently open, on letterhead ──
var _currentPrintPage = null;
function printCurrentPage(){
  const pg = _currentPrintPage || (document.querySelector('.page.active')||{}).id?.replace('pg-','');
  if(!pg){ if(typeof toast==='function') toast('Open a page first, then print.','e'); return; }
  const _pb = (typeof PB!=='undefined' && PB) || window.PB;
  if(_pb && _pb.printPage){ _pb.printPage(pg); }
  else window.print();
}

function closePrintModal(){
  document.getElementById('print-modal').classList.remove('open');
  document.body.style.overflow = '';
}

// ── PRINT ENGINE: render the letterhead document in its own window ──────
// Printing directly from this page fails when the app is embedded in a
// preview iframe (the parent page prints instead → blank sheet), so we
// always print an isolated document window.
function printDocument(){
  const area = document.getElementById('print-area');
  if(!area){ window.print(); return; }
  const title = (document.getElementById('print-doc-title')||{}).textContent || 'Report';
  const css = [...document.querySelectorAll('style')].map(s=>s.textContent).join('\n');
  let w = null;
  try{ w = window.open('', '_blank', 'width=1024,height=768'); }catch(e){ w = null; }
  if(!w){ window.print(); return; }
  w.document.open();
  w.document.write('<!doctype html><html><head><meta charset="utf-8"><title>'+title+'</title>'+
    '<style>'+css+'</style>'+
    '<style>html,body{background:#fff!important;margin:0;padding:10px;}'+
    '#print-modal,.print-modal{display:block!important;position:static!important;opacity:1!important;background:#fff!important;}'+
    '#print-area *{visibility:visible!important;}'+
    '#print-area{display:block!important;visibility:visible!important;position:static!important;box-shadow:none!important;margin:0 auto!important;max-width:190mm;}'+
    '@page{size:A4;margin:12mm}</style></head><body>'+area.outerHTML+'</body></html>');
  w.document.close();
  w.focus();
  setTimeout(function(){ try{ w.print(); }catch(e){} }, 700);
}
window.printDocument = printDocument;

// ── Format helpers ──────────────────────────────────────
const pfTk = v => '৳' + (parseFloat(v)||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
const pn = v => (parseFloat(v)||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});

// ── Summary boxes HTML ──────────────────────────────────
function sumBoxes(items){
  return '<div class="print-summary">' +
    items.map(i=>`<div class="print-sum-box"><div class="psb-label">${escHTML(i.label)}</div><div class="psb-value">${i.value}</div></div>`).join('') +
  '</div>';
}

// ══════════════════════════════════════════════════════
// 1. PRINT SINGLE TRANSACTION VOUCHER
// ══════════════════════════════════════════════════════
function printTransaction(txId){
  const tx = (DB.tx||[]).find(t=>t.id===txId);
  if(!tx){ toast('Transaction not found','e'); return; }
  _currentPrintTx = tx;
  document.getElementById('print-invoice-type').value = 'voucher';

  const rows = [
    ['Transaction Type', `<span style="background:#1a3a6b;color:#fff;padding:2px 8px;border-radius:4px;font-size:11px;">${tx.type}</span>`],
    ['Date', tx.date||'—'],
    ['Invoice No', tx.inv||'—'],
    ['Party Name', `<strong>${escHTML(tx.party ||'—')}</strong>`],
    ['Party Type', tx.ptype||'—'],
    ['Product / Purpose', tx.prod||'—'],
    ['Location', tx.loc||'—'],
    ['Bag Type / Qty', tx.bagtype ? `${tx.bagtype} × ${tx.bagqty||0}` : '—'],
    ['Quantity (KG/Ltr)', tx.qty ? pn(tx.qty) : '—'],
    ['Gross Weight (KG)', tx.grosswt ? pn(tx.grosswt) : '—'],
    ['Net Weight (KG)', tx.wt ? pn(tx.wt) : '—'],
    ['Rate (৳)', tx.rate ? pfTk(tx.rate) : '—'],
    ['Gross Amount (৳)', pfTk(tx.amount)],
    ['Paid (৳)', tx.paid ? pfTk(tx.paid) : '—'],
    ['Received (৳)', tx.recv ? pfTk(tx.recv) : '—'],
    ['Due (৳)', tx.due ? `<strong style="color:#c0392b;">${pfTk(tx.due)}</strong>` : '—'],
    ['Payment Mode', tx.mode||'—'],
    ['Bank Account', tx.acc ? bankNameToDisplay(tx.acc) : '—'],
    ['Truck ID', tx.truck||'—'],
    ['Truck Rent (৳)', tx.truckrent ? pfTk(tx.truckrent) : '—'],
    ['Paid Truck Rent (৳)', tx.truckpaid ? pfTk(tx.truckpaid) : '—'],
    ['Due Truck Rent (৳)', tx.truckdue ? pfTk(tx.truckdue) : '—'],
    ['Agent A', tx.agentA ? `${tx.agentA} — ${pfTk(tx.agentAcost)}` : '—'],
    ['Agent B', tx.agentB ? `${tx.agentB} — ${pfTk(tx.agentBcost)}` : '—'],
    ['QC Person', tx.qcperson ? `${tx.qcperson} — ${pfTk(tx.qc)}` : '—'],
    ['Unloader', tx.unloadperson ? `${tx.unloadperson} — ${pfTk(tx.unload)}` : '—'],
    ['Other Cost', tx.otherperson ? `${tx.otherperson} — ${pfTk(tx.othercost)}` : '—'],
    ['Another 2 Cost', tx.otherperson2 ? `${tx.otherperson2} — ${pfTk(tx.othercost2)}` : '—'],
    ['Total Cost (৳)', tx.totalcost ? `<strong>${pfTk(tx.totalcost)}</strong>` : '—'],
    ['Notes / Remarks', tx.rem||'—'],
  ].filter(r => r[1] !== '—');

  const html = buildVoucher(tx);
  openPrintModal('Transaction Voucher', tx.inv||tx.id, html, tx.party);
}

// ══════════════════════════════════════════════════════
// 2. PRINT PARTY / CUSTOMER LEDGER
// ══════════════════════════════════════════════════════
function viewPartyLedger(partyName){
  const txs = [...(DB.tx||[]).filter(t=>t.party===partyName)].sort((a,b)=>a.date.localeCompare(b.date));
  const party = (DB.customers||[]).find(c=>c.name===partyName);
  let runBal = 0;
  const DR_TYPES = ['Sale','Purchase Advance','Sales Advance','Employee Advance','Employee Loan'];
  const CR_TYPES = ['Sales Receipt','Purchase Payment','Purchase Return','Sales Return','Cash Received'];
  const rows = txs.map((t,i)=>{
    const dr = DR_TYPES.includes(t.type) ? (t.amount||0) : 0;
    const cr = CR_TYPES.includes(t.type) ? (t.amount||0) : 0;
    runBal += dr - cr;
    const bc = runBal>0?'#c0392b':runBal<0?'#27ae60':'#555';
    return `<tr style="border-bottom:1px solid #eee;">
      <td style="padding:6px 8px;font-size:11px;color:#888;">${i+1}</td>
      <td style="padding:6px 8px;">${t.date||'—'}</td>
      <td style="padding:6px 8px;font-size:11px;">${t.inv||'—'}</td>
      <td style="padding:6px 8px;"><span class="badge ${txBadge(t.type)}">${t.type}</span></td>
      <td style="padding:6px 8px;font-size:11px;">${escHTML(t.prod ||'—')}</td>
      <td style="padding:6px 8px;text-align:right;color:#c0392b;font-weight:600;">${dr>0?f(dr):'—'}</td>
      <td style="padding:6px 8px;text-align:right;color:#27ae60;font-weight:600;">${cr>0?f(cr):'—'}</td>
      <td style="padding:6px 8px;text-align:right;font-weight:700;color:${bc};">${f(runBal)}</td>
      <td style="padding:6px 8px;font-size:11px;">${escHTML(t.rem ||'—')}</td>
    </tr>`;
  });
  const totalDr = txs.reduce((s,t)=>s+(DR_TYPES.includes(t.type)?t.amount||0:0),0);
  const totalCr = txs.reduce((s,t)=>s+(CR_TYPES.includes(t.type)?t.amount||0:0),0);
  const finalBal = totalDr - totalCr;
  const bc2 = finalBal>0?'#c0392b':'#27ae60';

  const summaryHtml = `<div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:16px;">
    <div style="background:#ebf8ff;border:1px solid #bee3f8;border-radius:8px;padding:10px 16px;">
      <div style="font-size:11px;color:#4a5568;">Party</div>
      <div style="font-weight:700;font-size:14px;">${partyName}</div>
    </div>
    <div style="background:#ebf8ff;border:1px solid #bee3f8;border-radius:8px;padding:10px 16px;">
      <div style="font-size:11px;color:#4a5568;">Type</div>
      <div style="font-weight:700;">${party?party.type:'—'}</div>
    </div>
    <div style="background:#fff5f5;border:1px solid #fed7d7;border-radius:8px;padding:10px 16px;">
      <div style="font-size:11px;color:#4a5568;">Total Debit</div>
      <div style="font-weight:700;color:#c0392b;">${f(totalDr)}</div>
    </div>
    <div style="background:#f0fff4;border:1px solid #c6f6d5;border-radius:8px;padding:10px 16px;">
      <div style="font-size:11px;color:#4a5568;">Total Credit</div>
      <div style="font-weight:700;color:#27ae60;">${f(totalCr)}</div>
    </div>
    <div style="background:${finalBal>0?'#fff5f5':'#f0fff4'};border:1px solid ${finalBal>0?'#fed7d7':'#c6f6d5'};border-radius:8px;padding:10px 16px;">
      <div style="font-size:11px;color:#4a5568;">Balance</div>
      <div style="font-weight:700;color:${bc2};">${f(finalBal)}</div>
    </div>
    <div style="background:#faf5ff;border:1px solid #e9d8fd;border-radius:8px;padding:10px 16px;">
      <div style="font-size:11px;color:#4a5568;">Entries</div>
      <div style="font-weight:700;">${txs.length}</div>
    </div>
  </div>`;

  const tableHtml = `<div style="overflow-x:auto;">
    <table style="width:100%;border-collapse:collapse;font-size:13px;">
      <thead><tr style="background:#1a3a6b;color:#fff;">
        <th style="padding:8px;">#</th>
        <th style="padding:8px;">Date</th>
        <th style="padding:8px;">Invoice</th>
        <th style="padding:8px;">Type</th>
        <th style="padding:8px;">Product</th>
        <th style="padding:8px;text-align:right;">Debit (৳)</th>
        <th style="padding:8px;text-align:right;">Credit (৳)</th>
        <th style="padding:8px;text-align:right;">Running Balance (৳)</th>
        <th style="padding:8px;">Remarks</th>
      </tr></thead>
      <tbody>${rows.length?rows.join(''):'<tr><td colspan="9" style="text-align:center;padding:20px;color:#999;">No transactions found</td></tr>'}</tbody>
      <tfoot><tr style="background:#f7fafc;font-weight:700;border-top:2px solid #e2e8f0;">
        <td colspan="5" style="padding:8px;">TOTAL</td>
        <td style="padding:8px;text-align:right;color:#c0392b;">${f(totalDr)}</td>
        <td style="padding:8px;text-align:right;color:#27ae60;">${f(totalCr)}</td>
        <td style="padding:8px;text-align:right;color:${bc2};">${f(finalBal)}</td>
        <td></td>
      </tr></tfoot>
    </table>
  </div>
  <div style="margin-top:12px;text-align:right;">
    <button class="btn btn-sm" style="background:#f5a623;color:#000;" data-x-click="printPartyLedger('${partyName}')">🖨️ Print Ledger</button>
  </div>`;

  document.getElementById('mViewLedgerTitle').textContent = '📒 Party Ledger — ' + partyName;
  document.getElementById('mViewLedgerBody').innerHTML = summaryHtml + tableHtml;
  openModal('mViewLedger');
}

function printPartyLedger(partyName){
  const txs = (DB.tx||[]).filter(t=>t.party===partyName);
  const party = (DB.parties||[]).filter(p=>p.type==='Customer'||p.type==='Supplier'||p.type==='Both').find(c=>c.name===partyName);
  let runBal = 0;
  const rows = txs.map(t=>{
    const dr = ['Sale','Purchase Advance','Sales Advance'].includes(t.type) ? (t.amount||0) : 0;
    const cr = ['Sales Receipt','Purchase Payment','Purchase Return'].includes(t.type) ? (t.amount||0) : 0;
    runBal += dr - cr;
    return `<tr>
      <td>${t.date||'—'}</td>
      <td class="fs11">${t.inv||'—'}</td>
      <td><span style="background:#1a3a6b;color:#fff;padding:1px 6px;border-radius:3px;font-size:10px;">${t.type}</span></td>
      <td>${escHTML(t.prod ||'—')}</td>
      <td class="td-num">${dr>0?pfTk(dr):'—'}</td>
      <td class="td-num">${cr>0?pfTk(cr):'—'}</td>
      <td class="td-num" style="font-weight:700;color:${runBal>0?'#c0392b':'#27ae60'};">${pfTk(runBal)}</td>
      <td class="fs11">${escHTML(t.rem ||'—')}</td>
    </tr>`;
  });

  const totalDr = txs.reduce((s,t)=>s+(['Sale','Purchase Advance','Sales Advance'].includes(t.type)?t.amount||0:0),0);
  const totalCr = txs.reduce((s,t)=>s+(['Sales Receipt','Purchase Payment','Purchase Return'].includes(t.type)?t.amount||0:0),0);

  const html = `
    ${sumBoxes([
      {label:'Party',value:partyName},
      {label:'Type',value:party?.type||'—'},
      {label:'Total Debit',value:pfTk(totalDr)},
      {label:'Total Credit',value:pfTk(totalCr)},
      {label:'Balance',value:pfTk(totalDr-totalCr)},
      {label:'Transactions',value:txs.length},
    ])}
    <table class="print-table">
      <thead><tr>
        <th>Date</th><th>Invoice</th><th>Type</th><th>Product</th>
        <th class="td-num">Debit (৳)</th><th class="td-num">Credit (৳)</th>
        <th class="td-num">Balance (৳)</th><th>Remarks</th>
      </tr></thead>
      <tbody>${rows.length ? rows.join('') : '<tr><td colspan="8" style="text-align:center;padding:20px;color:#999;">No transactions found</td></tr>'}</tbody>
      <tfoot><tr>
        <td colspan="4"><strong>TOTAL</strong></td>
        <td class="td-num">${pfTk(totalDr)}</td>
        <td class="td-num">${pfTk(totalCr)}</td>
        <td class="td-num">${pfTk(totalDr-totalCr)}</td>
        <td></td>
      </tr></tfoot>
    </table>`;

  openPrintModal(`Party Ledger — ${partyName}`, 'LEDGER', html, partyName);
}

// ══════════════════════════════════════════════════════
// 3. PRINT AGENT / COST PERSON LEDGER
// ══════════════════════════════════════════════════════
function printAgentLedger(agentId){
  const ag = (DB.agents||[]).find(a=>a.id===agentId);
  if(!ag){ toast('Agent not found','e'); return; }
  const ledger = (DB.agentLedger||[]).filter(l=>l.agentId===agentId);
  let runBal = ag.openingBalance||0;

  const rows = ledger.map(l=>{
    if(l.type==='earned') runBal += l.amount||0;
    else runBal -= l.amount||0;
    return `<tr>
      <td>${l.date||'—'}</td>
      <td><span style="background:${l.type==='earned'?'#1a3a6b':'#27ae60'};color:#fff;padding:1px 6px;border-radius:3px;font-size:10px;">${l.type==='earned'?'Earned':'Paid'}</span></td>
      <td class="fs11">${l.txRef||'—'}</td>
      <td class="td-num">${l.type==='earned'?pfTk(l.amount):'—'}</td>
      <td class="td-num">${l.type==='paid'?pfTk(l.amount):'—'}</td>
      <td class="td-num" style="font-weight:700;color:${runBal>0?'#c0392b':'#27ae60'};">${pfTk(runBal)}</td>
      <td class="fs11">${escHTML(l.note ||'—')}</td>
    </tr>`;
  });

  const totalEarned = ledger.filter(l=>l.type==='earned').reduce((s,l)=>s+l.amount,0);
  const totalPaid = ledger.filter(l=>l.type==='paid').reduce((s,l)=>s+l.amount,0);

  const html = `
    ${sumBoxes([
      {label:'Person',value:ag.name},
      {label:'Role',value:ag.role||'—'},
      {label:'Area/Route',value:ag.area||'—'},
      {label:'Total Earned',value:pfTk(totalEarned)},
      {label:'Total Paid',value:pfTk(totalPaid)},
      {label:'Outstanding',value:pfTk(totalEarned-totalPaid)},
    ])}
    <table class="print-table">
      <thead><tr>
        <th>Date</th><th>Type</th><th>Ref</th>
        <th class="td-num">Earned (৳)</th><th class="td-num">Paid (৳)</th>
        <th class="td-num">Balance (৳)</th><th>Note</th>
      </tr></thead>
      <tbody>${rows.length ? rows.join('') : '<tr><td colspan="7" style="text-align:center;padding:20px;color:#999;">No ledger entries found</td></tr>'}</tbody>
      <tfoot><tr>
        <td colspan="3"><strong>TOTAL</strong></td>
        <td class="td-num">${pfTk(totalEarned)}</td>
        <td class="td-num">${pfTk(totalPaid)}</td>
        <td class="td-num">${pfTk(totalEarned-totalPaid)}</td>
        <td></td>
      </tr></tfoot>
    </table>`;

  openPrintModal(`Cost Person Ledger — ${ag.name}`, 'AGENT-LEDGER', html, ag.role);
}

