// ══════════════════════════════════════════════════════
// 5. PRINT BANK ACCOUNT STATEMENT
// ══════════════════════════════════════════════════════
function printBankStatementByName(bankName){
  const b = (DB.banks||[]).find(b=>b.name===bankName);
  if(!b){ toast('Bank not found','e'); return; }
  const txs = (DB.tx||[]).filter(t=>(t.bank||'').toLowerCase()===bankName.toLowerCase()||(t.bank2||'').toLowerCase()===bankName.toLowerCase());
  const bal = b.bal||b.balance||0;

  let running = bal, totalIn=0, totalOut=0;
  const bankInTypes=['bank deposit','sales receipt','cash received','cheque received','interest income','opening balance','partner capital','sales advance'];
  const rows = [...txs].sort((a,b)=>(a.date||'').localeCompare(b.date||'')).map(t=>{
    const type=(t.type||'').toLowerCase();
    const amt = txAmt(t);
    let debit=0,credit=0;
    if(bankInTypes.some(k=>type.includes(k))){credit=amt;totalIn+=amt;}
    else{debit=amt;totalOut+=amt;}
    running=running+credit-debit;
    const bc=running>=0?'#16a34a':'#dc2626';
    return `<tr>
    <td>${t.date||'—'}</td>
    <td class="fs11">${t.inv||'—'}</td>
    <td><span style="background:#0f3d26;color:#fff;padding:1px 6px;border-radius:3px;font-size:10px;">${t.type}</span></td>
    <td>${escHTML(t.party ||'—')}</td>
    <td class="td-num" style="color:#16a34a;">${credit>0?'৳'+pf(credit):'—'}</td>
    <td class="td-num" style="color:#dc2626;">${debit>0?'৳'+pf(debit):'—'}</td>
    <td class="td-num" style="font-weight:700;color:${bc};">৳${pf(running)}</td>
    <td>${t.mode||'—'}</td>
  </tr>`;
  });

  const html = `
    ${sumBoxes([
      {label:'Account',value:b.name},
      {label:'Bank',value:b.bank||'—'},
      {label:'Opening Balance',value:'৳'+pf(bal)},
      {label:'Total Credits',value:'৳'+pf(totalIn)},
      {label:'Total Debits',value:'৳'+pf(totalOut)},
      {label:'Closing Balance',value:'৳'+pf(running)},
    ])}
    <table class="print-table">
      <thead><tr>
        <th>Date</th><th>Invoice</th><th>Type</th><th>Party</th>
        <th class="td-num" style="color:#16a34a;">Credit (৳)</th>
        <th class="td-num" style="color:#dc2626;">Debit (৳)</th>
        <th class="td-num">Balance (৳)</th><th>Mode</th>
      </tr></thead>
      <tbody>${rows.length ? rows.join('') : '<tr><td colspan="8" style="text-align:center;padding:20px;color:#999;">No transactions found for this account</td></tr>'}</tbody>
    </table>`;

  openPrintModal('Bank Statement — '+b.name, 'BANK-STMT', html, b.bank||b.name);
}

