// 6. PRINT ALL TRANSACTIONS
// ══════════════════════════════════════════════════════
function printAllTransactions(filtered){
  const txs = filtered || DB.tx || [];
  const rows = [...txs].reverse().map(t=>`<tr>
    <td>${t.date||'—'}</td>
    <td class="fs11">${t.inv||'—'}</td>
    <td><span style="background:#1a3a6b;color:#fff;padding:1px 5px;border-radius:3px;font-size:9px;">${t.type}</span></td>
    <td><strong>${escHTML(t.party ||'—')}</strong></td>
    <td class="fs11">${escHTML(t.prod ||'—')}</td>
    <td class="td-num">${t.qty?pn(t.qty):'—'}</td>
    <td class="td-num">${t.rate?pfTk(t.rate):'—'}</td>
    <td class="td-num" style="font-weight:700;">${pfTk(txAmt(t))}</td>
    <td class="td-num">${t.paid?pfTk(t.paid):'—'}</td>
    <td class="td-num">${t.recv?pfTk(t.recv):'—'}</td>
    <td class="td-num" style="color:${t.due>0?'#c0392b':'inherit'};">${t.due?pfTk(t.due):'—'}</td>
    <td class="fs11">${t.mode||'—'}</td>
    <td class="fs11">${escHTML(t.rem ||'—')}</td>
  </tr>`);

  const totalAmt = txs.reduce((s,t)=>s+txAmt(t),0);
  const totalPaid = txs.reduce((s,t)=>s+(t.paid||0),0);
  const totalDue = txs.reduce((s,t)=>s+(t.due||0),0);

  const html = `
    ${sumBoxes([
      {label:'Total Transactions',value:txs.length},
      {label:'Total Amount',value:pfTk(totalAmt)},
      {label:'Total Paid',value:pfTk(totalPaid)},
      {label:'Total Due',value:pfTk(totalDue)},
    ])}
    <div style="overflow-x:auto;">
    <table class="print-table" style="font-size:10px;">
      <thead><tr>
        <th>Date</th><th>Invoice</th><th>Type</th><th>Party</th><th>Product</th>
        <th class="td-num">Qty</th><th class="td-num">Rate</th><th class="td-num">Amount</th>
        <th class="td-num">Paid</th><th class="td-num">Received</th><th class="td-num">Due</th>
        <th>Mode</th><th>Remarks</th>
      </tr></thead>
      <tbody>${rows.length ? rows.join('') : '<tr><td colspan="13" style="text-align:center;padding:20px;color:#999;">No transactions found</td></tr>'}</tbody>
      <tfoot><tr>
        <td colspan="7"><strong>TOTAL</strong></td>
        <td class="td-num">${pfTk(totalAmt)}</td>
        <td class="td-num">${pfTk(totalPaid)}</td>
        <td></td>
        <td class="td-num">${pfTk(totalDue)}</td>
        <td colspan="2"></td>
      </tr></tfoot>
    </table></div>`;

  openPrintModal('All Transactions', 'TX-LIST', html, `${txs.length} records`);
}

// ══════════════════════════════════════════════════════
// 7. PRINT BALANCE SHEET
// ══════════════════════════════════════════════════════
function printBalanceSheet(){
  /* FIX (printed Balance Sheet always showed ৳0.00): this read DB.parties —
     an array that doesn't exist in this app's data model (real customer,
     supplier and partner records live in DB.customers/DB.partners, exactly
     as computePosition() — the same engine the ON-SCREEN Balance Sheet and
     today's Trial Balance fix both use — already reads them). Every
     printed Balance Sheet therefore showed ৳0.00 Partner Capital, ৳0.00
     Liabilities and ৳0.00 next to every customer, no matter what the
     screen correctly showed a moment before. Printing now reads from the
     exact same computePosition() snapshot the screen renders, so the
     printed document can never disagree with what's on screen, and stays
     correct automatically as new asset/liability lines (like the Fixed
     Asset Payable line added today) are added to that engine. */
  const P = computePosition();
  const partners = DB.partners||[];
  const customersWithDue = (DB.customers||[]).filter(c=>(c.bal||c.balance||0)>0);
  const banksWithBal = (DB.banks||[]).filter(b=>(b.bal||b.balance||0)!==0);
  const assetsList = DB.assets||[];

  const html = `
    ${sumBoxes([
      {label:'Total Assets',value:'৳'+pf(P.totalAssets)},
      {label:'Partner Capital',value:'৳'+pf(P.partnerFund)},
      {label:'Total Liabilities',value:'৳'+pf(P.totalLeft-P.partnerFund-P.netProfit)},
      {label:'Net Worth',value:'৳'+pf(P.netWorth)},
    ])}
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:8px;">
      <div>
        <div style="background:#0f3d26;color:#fff;padding:6px 10px;font-weight:700;font-size:12px;border-radius:4px 4px 0 0;">ASSETS</div>
        <table class="print-table" style="margin-top:0;">
          <tbody>
            <tr><td>Customer Due (Receivables)</td><td class="td-num">৳${pf(P.customerDue)}</td></tr>
            ${customersWithDue.map(c=>`<tr><td style="padding-left:16px;color:#555;font-size:11px;">↳ ${escHTML(c.name)}</td><td class="td-num">৳${pf(c.bal||c.balance||0)}</td></tr>`).join('')}
            <tr><td>Bank & Cash Balance</td><td class="td-num">৳${pf(P.bankBalance)}</td></tr>
            ${banksWithBal.map(b=>`<tr><td style="padding-left:16px;color:#555;font-size:11px;">↳ ${escHTML(b.name)}</td><td class="td-num">৳${pf(b.bal||b.balance||0)}</td></tr>`).join('')}
            <tr><td>Fixed Assets</td><td class="td-num">৳${pf(P.fixedAsset)}</td></tr>
            ${assetsList.map(a=>`<tr><td style="padding-left:16px;color:#555;font-size:11px;">↳ ${escHTML(a.name)}</td><td class="td-num">৳${pf(a.val||a.value||0)}</td></tr>`).join('')}
            <tr><td>Supply Advance</td><td class="td-num">৳${pf(P.supplyAdv)}</td></tr>
            <tr><td>Warehouse Stock Value</td><td class="td-num">৳${pf(P.stockVal)}</td></tr>
            <tr><td>Cash in Hand</td><td class="td-num">৳${pf(P.cashInHand)}</td></tr>
          </tbody>
          <tfoot><tr style="background:#f0fdf4;"><td><strong>TOTAL ASSETS</strong></td><td class="td-num"><strong>৳${pf(P.totalAssets)}</strong></td></tr></tfoot>
        </table>
      </div>
      <div>
        <div style="background:#0f3d26;color:#fff;padding:6px 10px;font-weight:700;font-size:12px;border-radius:4px 4px 0 0;">EQUITY & LIABILITIES</div>
        <table class="print-table" style="margin-top:0;">
          <tbody>
            ${partners.map(p=>`<tr><td>Partner Capital — ${escHTML(p.name)} <span style="font-size:10px;color:#888;">(${p.share||p.pct||0}%)</span></td><td class="td-num">৳${pf(p.cap||0)}</td></tr>`).join('')}
            <tr><td>Retained Profit</td><td class="td-num">৳${pf(P.netProfit)}</td></tr>
            ${P.leftItems.slice(2).filter(i=>i.val).map(i=>`<tr><td style="color:#c0392b;">${escHTML(i.label)}</td><td class="td-num" style="color:#c0392b;">৳${pf(i.val)}</td></tr>`).join('')}
          </tbody>
          <tfoot>
            <tr><td><strong>TOTAL PARTNER CAPITAL</strong></td><td class="td-num"><strong>৳${pf(P.partnerFund)}</strong></td></tr>
            <tr><td><strong>TOTAL LIABILITIES + EQUITY</strong></td><td class="td-num"><strong>৳${pf(P.totalLeft)}</strong></td></tr>
            <tr style="background:#f5a623;"><td><strong>NET WORTH</strong></td><td class="td-num"><strong>৳${pf(P.netWorth)}</strong></td></tr>
          </tfoot>
        </table>
      </div>
    </div>`;

  openPrintModal('Balance Sheet', 'BAL-SHEET', html, TODAY());
}
