function printVoucher(txId){
  const t = (DB.tx||[]).find(x=>x.id===txId)||(DB.tx||[])[0];
  if(!t){ toast('Transaction not found','e'); return; }
  const amt = txAmt(t);
  const html = `
    ${sumBoxes([
      {label:'Voucher No',value:t.inv||'—'},
      {label:'Date',value:t.date||'—'},
      {label:'Type',value:t.type||'—'},
      {label:'Amount',value:'৳'+pf(amt)},
    ])}
    <table class="print-table">
      <tbody>
        <tr><td style="width:40%;font-weight:700;">Party</td><td>${escHTML(t.party ||'—')} <span style="font-size:10px;color:#888;">(${t.ptype||''})</span></td></tr>
        <tr><td style="font-weight:700;">Product/Purpose</td><td>${escHTML(t.prod||t.desc||'—')}</td></tr>
        <tr><td style="font-weight:700;">Quantity</td><td>${t.qty?pn(t.qty)+' '+(t.unit||''):'—'}</td></tr>
        <tr><td style="font-weight:700;">Rate</td><td>${t.rate?'৳'+pf(t.rate):'—'}</td></tr>
        <tr><td style="font-weight:700;">Amount</td><td style="font-weight:900;font-size:15px;color:#0f3d26;">৳${pf(amt)}</td></tr>
        <tr><td style="font-weight:700;">Payment Mode</td><td>${t.mode||'—'}</td></tr>
        <tr><td style="font-weight:700;">Bank Account</td><td>${escHTML(t.bank ||'—')}</td></tr>
        <tr><td style="font-weight:700;">Location</td><td>${t.loc||'—'}</td></tr>
        <tr><td style="font-weight:700;">Remarks</td><td>${escHTML(t.rem ||'—')}</td></tr>
      </tbody>
    </table>`;
  /* FIX (duplicate signature block): openPrintModal()'s shared template
     already appends a Prepared By / Checked By / Authorized Signatory
     footer to every printed document — this inline copy was printing a
     second, differently-styled signature row right above it, so every
     voucher printed with two sets of signature lines stacked back to
     back. Removed here; the shared footer already covers it. */
  openPrintModal('Payment Voucher', t.inv||'VCHR', html, t.party||'');
}

function printReceipt(txId){
  const t = (DB.tx||[]).find(x=>x.id===txId)||(DB.tx||[])[0];
  if(!t){ toast('Transaction not found','e'); return; }
  const amt = txAmt(t);
  const html = `
    ${sumBoxes([
      {label:'Receipt No',value:t.inv||'—'},
      {label:'Date',value:t.date||'—'},
      {label:'Received From',value:t.party||'—'},
      {label:'Amount',value:'৳'+pf(amt)},
    ])}
    <div style="background:#f0fdf4;border:2px solid #16a34a;border-radius:10px;padding:20px;margin:16px 0;text-align:center;">
      <div style="font-size:13px;color:#6b7280;margin-bottom:6px;">Received with thanks from</div>
      <div style="font-size:18px;font-weight:900;color:#0f3d26;">${escHTML(t.party ||'—')}</div>
      <div style="font-size:13px;color:#6b7280;margin:8px 0;">the sum of</div>
      <div style="font-size:28px;font-weight:900;color:#16a34a;">৳${pf(amt)}</div>
      <div style="font-size:12px;color:#6b7280;margin-top:6px;">via ${t.mode||'Cash'} | ${escHTML(t.bank ||'')}</div>
      <div style="font-size:12px;color:#6b7280;">For: ${escHTML(t.prod||t.desc||t.type||'—')}</div>
    </div>`;
  // FIX (duplicate signature block): see the identical fix in printVoucher()
  // just above — openPrintModal()'s shared footer already provides this.
  openPrintModal('Money Receipt', t.inv||'RCPT', html, t.party||'');
}

function printPartyList() {
  // Prints exactly the panel the user is looking at (Customers / Suppliers / Partners / All)
  const _tab = (typeof _partyTab!=='undefined') ? _partyTab : '';
  const _src = _tab==='Partner'
    ? (DB.partners||[]).map(p=>({name:p.name,type:'Partner',phone:p.phone||'',bal:p.cap||0}))
    : (DB.customers||[]).filter(c=>!_tab || c.type===_tab || c.type==='Both');
  const _label = _tab==='Customer'?'All Customers':_tab==='Supplier'?'All Suppliers':_tab==='Partner'?'All Partners':'All Parties';
  const rows = _src.map((c,i) => {
    const cls = (c.bal||0) > 0 ? 'pos' : (c.bal||0) < 0 ? 'neg' : '';
    return '<tr><td>'+(i+1)+'</td><td><strong>'+c.name+'</strong></td><td>'+(c.type||'Customer')+'</td><td>'+(c.phone||'-')+'</td><td class="td-num '+cls+'">'+f(Math.abs(c.bal||0))+'</td><td>'+((c.bal||0)>0?'Receivable':(c.bal||0)<0?'Payable':'Nil')+'</td></tr>';
  }).join('');
  const totalRecv = _src.filter(p=>(p.bal||0)>0).reduce((s,c)=>s+(c.bal||0),0);
  const totalPay  = Math.abs(_src.filter(p=>(p.bal||0)<0).reduce((s,c)=>s+(c.bal||0),0));
  const html = '<h2 style="text-align:center;margin:0 0 4px">Party Ledger Summary</h2>'
    +'<p style="text-align:center;color:#555;margin:0 0 16px">'+_label+'</p>'
    +'<table class="print-table"><thead><tr><th>#</th><th>Name</th><th>Type</th><th>Phone</th><th>Balance</th><th>Status</th></tr></thead><tbody>'+rows+'</tbody></table>'
    +'<div class="print-summary"><span>Total Receivable: <strong class="pos">'+f(totalRecv)+'</strong></span>'
    +'<span style="margin-left:32px">Total Payable: <strong class="neg">'+f(totalPay)+'</strong></span>'
    +'<span style="margin-left:32px">Net: <strong>'+f(totalRecv-totalPay)+'</strong></span></div>';
  openPrintModal(_label, 'PARTY-'+Date.now().toString().slice(-6), html, _src.length+' records');
}

