function printInventory() {
  const rows = (DB.products||[]).map((p,i) => {
    const stockVal = (p.stockQty||0)*(p.rate||0);
    return '<tr><td>'+(i+1)+'</td><td><strong>'+p.name+'</strong></td><td>'+(p.category||'-')+'</td><td>'+(p.unit||'KG')+'</td><td class="td-num">'+f(p.rate||0)+'</td><td class="td-num">'+f(p.costPrice||0)+'</td><td class="td-num">'+((p.stockQty||0).toLocaleString())+'</td><td class="td-num pos">'+f(stockVal)+'</td></tr>';
  }).join('');
  const totalVal  = (DB.products||[]).reduce((s,p)=>s+(p.stockQty||0)*(p.rate||0),0);
  const totalCost = (DB.products||[]).reduce((s,p)=>s+(p.stockQty||0)*(p.costPrice||0),0);
  const html = '<h2 style="text-align:center;margin:0 0 4px">Inventory Register</h2>'
    +'<p style="text-align:center;color:#555;margin:0 0 16px">Products &amp; Stock Status</p>'
    +'<table class="print-table"><thead><tr><th>#</th><th>Product</th><th>Category</th><th>Unit</th><th>Rate (&#2547;)</th><th>Cost (&#2547;)</th><th>Stock Qty</th><th>Stock Value (&#2547;)</th></tr></thead><tbody>'+rows+'</tbody></table>'
    +'<div class="print-summary"><span>Total Stock Value: <strong class="pos">'+f(totalVal)+'</strong></span>'
    +'<span style="margin-left:32px">Total Cost Value: <strong>'+f(totalCost)+'</strong></span>'
    +'<span style="margin-left:32px">Products: <strong>'+(DB.products||[]).length+'</strong></span></div>';
  openPrintModal('Inventory Register', 'STOCK-'+Date.now().toString().slice(-6), html, (DB.products||[]).length+' products');
}

