function printAssetRegister() {
  const rows = (DB.assets||[]).map((a,i) => {
    const dep = (a.value||0)*(a.depRate||0)/100;
    const net = (a.value||0) - dep;
    return '<tr><td>'+(i+1)+'</td><td><strong>'+a.name+'</strong></td><td>'+(a.category||'-')+'</td><td class="td-num">'+f(a.value||0)+'</td><td>'+(a.depRate||0)+'%</td><td class="td-num neg">'+f(dep)+'</td><td class="td-num pos">'+f(net)+'</td><td>'+(a.purchaseDate||'-')+'</td></tr>';
  }).join('');
  const totalVal = (DB.assets||[]).reduce((s,a)=>s+(a.value||0),0);
  const totalDep = (DB.assets||[]).reduce((s,a)=>s+(a.value||0)*(a.depRate||0)/100,0);
  const html = '<h2 style="text-align:center;margin:0 0 4px">Fixed Asset Register</h2>'
    +'<p style="text-align:center;color:#555;margin:0 0 16px">All Fixed Assets</p>'
    +'<table class="print-table"><thead><tr><th>#</th><th>Asset Name</th><th>Category</th><th>Purchase Value (&#2547;)</th><th>Dep %</th><th>Depreciation (&#2547;)</th><th>Net Book Value (&#2547;)</th><th>Purchase Date</th></tr></thead><tbody>'+rows+'</tbody></table>'
    +'<div class="print-summary"><span>Total Value: <strong>'+f(totalVal)+'</strong></span>'
    +'<span style="margin-left:32px">Total Depreciation: <strong class="neg">'+f(totalDep)+'</strong></span>'
    +'<span style="margin-left:32px">Net Book Value: <strong class="pos">'+f(totalVal-totalDep)+'</strong></span></div>';
  openPrintModal('Fixed Asset Register', 'ASSET-'+Date.now().toString().slice(-6), html, ((DB.assets||[]).length)+' assets');
}

// ─────────────────────────────────────────────────────────────────────────────
// PRINT: All Agent Ledgers (combined)
// ─────────────────────────────────────────────────────────────────────────────
function printAllAgentLedgers() {
  let html = '<h2 style="text-align:center;margin:0 0 16px">Cost Persons — All Ledgers</h2>';
  (DB.agents||[]).forEach(ag => {
    const payments = (DB.agentLedger||[]).filter(p=>p.agentId===ag.id&&p.type==='payment');
    const totalPaid = payments.reduce((s,p)=>s+(p.amount||0),0);
    const outstanding = (ag.totalDue||0) - totalPaid;
    const payRows = payments.map((p,i)=>
      '<tr><td>'+(i+1)+'</td><td>'+(p.date||'-')+'</td><td class="td-num pos">'+f(p.amount)+'</td><td>'+(p.mode||'-')+'</td><td>'+(p.note||'-')+'</td></tr>'
    ).join('');
    html += '<div style="margin-bottom:24px;page-break-inside:avoid;">'
      +'<h3 style="background:#1a3a6b;color:#fff;padding:6px 12px;margin:0 0 8px;border-radius:4px;">'+ag.name+' — '+(ag.role||'Cost Person')+'</h3>'
      +'<table class="print-table" style="margin-bottom:8px;"><tr>'
      +'<td><strong>Phone:</strong> '+(ag.phone||'-')+'</td>'
      +'<td><strong>Area:</strong> '+(ag.area||'-')+'</td>'
      +'<td><strong>Monthly Rate:</strong> '+f(ag.monthlyRate||0)+'</td>'
      +'<td><strong>Total Due:</strong> '+f(ag.totalDue||0)+'</td>'
      +'<td><strong>Total Paid:</strong> '+f(totalPaid)+'</td>'
      +'<td><strong>Outstanding:</strong> <span class="'+(outstanding>0?'neg':'pos')+'">'+f(outstanding)+'</span></td>'
      +'</tr></table>'
      +(payments.length>0
        ? '<table class="print-table"><thead><tr><th>#</th><th>Date</th><th>Amount (&#2547;)</th><th>Mode</th><th>Note</th></tr></thead><tbody>'+payRows+'</tbody></table>'
        : '<p style="color:#888;font-style:italic;">No payments recorded.</p>')
      +'</div>';
  });
  if((DB.agents||[]).length===0) html += '<p style="text-align:center;color:#888;">No cost persons found.</p>';
  openPrintModal('All Cost Person Ledgers', 'AGENT-'+Date.now().toString().slice(-6), html, (DB.agents||[]).length+' cost persons');
}


// ══════════════════════════════════════════════════════════════════════════
// STEP C — CSV / EXCEL EXPORT FUNCTIONS
// ══════════════════════════════════════════════════════════════════════════

function csvEsc(v){
  if(v===null||v===undefined) return '';
  const s=String(v);
  if(s.indexOf(',')>=0||s.indexOf('"')>=0||s.indexOf('\n')>=0) return '"'+s.replace(/"/g,'""')+'"';
  return s;
}
function csvRow(arr){ return arr.map(csvEsc).join(',')+'\r\n'; }
function dlCSV(filename,csvStr){
  const bom='\uFEFF';
  const blob=new Blob([bom+csvStr],{type:'text/csv;charset=utf-8;'});
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');
  a.href=url; a.download=filename; a.click();
  URL.revokeObjectURL(url);
}
function todayStr(){ return new Date().toISOString().split('T')[0]; }

function exportTransactionsCSV(){
  const txs=DB.tx||[];
  if(!txs||txs.length===0){toast('No transactions to export','e');return;}
  let csv='';
  csv+=csvRow(['#','Date','Invoice No','Type','Party','Party Type','Product','Truck ID','Location',
    'Bag Type','Bag Qty','Return Bag Qty','Qty','Gross Weight','Net Weight','Rate','Amount','Paid','Received','Due',
    'Mode','Account','Truck Rent','Truck Paid','Truck Due','Account 2',
    'Agent A','Agent A Cost','Agent B','Agent B Cost',
    'QC Person','QC Cost','Unload Person','Unload Cost','Other Person','Other Cost',
    'Another 2 Person','Another 2 Cost','Total Cost','Remark']);
  var rev=[...txs].reverse();
  rev.forEach(function(t,i){
    csv+=csvRow([
      txs.length-i, t.date||'', t.inv||'', t.type||'', t.party||'', t.ptype||'',
      t.prod||'', t.truck||'', t.loc||'', t.bagtype||'',
      t.bagqty!=null?t.bagqty:'', t.bagret!=null?t.bagret:'', t.qty!=null?t.qty:'', t.grosswt!=null?t.grosswt:'', t.wt!=null?t.wt:'', t.rate!=null?t.rate:'', t.amount||0,
      t.paid!=null?t.paid:'', t.recv!=null?t.recv:'', t.due!=null?t.due:'',
      t.mode||'', t.acc?bankNameToDisplay(t.acc):'',
      t.truckrent!=null?t.truckrent:'', t.paid2!=null?t.paid2:'', t.due2!=null?t.due2:'', t.acc2?bankNameToDisplay(t.acc2):'',
      t.agentA||'', t.agentAcost!=null?t.agentAcost:'',
      t.agentB||'', t.agentBcost!=null?t.agentBcost:'',
      t.qcperson||'', t.qc!=null?t.qc:'',
      t.unloadperson||'', t.unload!=null?t.unload:'',
      t.otherperson||'', t.othercost!=null?t.othercost:'',
      t.otherperson2||'', t.othercost2!=null?t.othercost2:'',
      t.totalcost!=null?t.totalcost:'', t.rem||''
    ]);
  });
  dlCSV('Transactions_'+todayStr()+'.csv',csv);
  toast('Transactions exported to CSV!','s');
}

function exportCustomersCSV(){
  var rows=DB.customers||[];
  if(rows.length===0){toast('No party data','e');return;}
  var csv=csvRow(['#','Name','Type','Phone','Balance','Credit Limit','Address']);
  rows.forEach(function(c,i){ csv+=csvRow([i+1,c.name,c.type,c.phone||'',c.bal||0,c.creditLimit||0,c.address||'']); });
  dlCSV('Parties_'+todayStr()+'.csv',csv);
  toast('Party list exported!','s');
}

function exportPartnersCSV(){
  var rows=DB.partners||[];
  if(rows.length===0){toast('No partner data','e');return;}
  var csv=csvRow(['#','Name','Capital','Share %','Role','Contact']);
  rows.forEach(function(p,i){ csv+=csvRow([i+1,p.name,p.cap||0,p.share||0,p.role||'',p.contact||'']); });
  dlCSV('Partners_'+todayStr()+'.csv',csv);
  toast('Partners exported!','s');
}

function exportBanksCSV(){
  var rows=DB.banks||[];
  if(rows.length===0){toast('No bank data','e');return;}
  var csv=csvRow(['#','Account Name','Bank','Type','Balance','Account No']);
  rows.forEach(function(b,i){ csv+=csvRow([i+1,b.name,b.bank||'',b.type||'',b.bal||0,b.accno||'']); });
  dlCSV('Banks_'+todayStr()+'.csv',csv);
  toast('Bank accounts exported!','s');
}

function exportInventoryCSV(){
  var rows=DB.products||[];
  if(rows.length===0){toast('No inventory data','e');return;}
  var csv=csvRow(['#','Product Name','Category','Unit','Sale Rate','Cost Rate','Stock Qty','Stock Value']);
  rows.forEach(function(p,i){ csv+=csvRow([i+1,p.name,p.category||'',p.unit||'',p.rate||0,p.cost||0,p.stock||0,stockQtyOf(p)*unitCost(p)]); });
  dlCSV('Inventory_'+todayStr()+'.csv',csv);
  toast('Inventory exported!','s');
}

function exportAssetsCSV(){
  var rows=DB.assets||[];
  if(rows.length===0){toast('No asset data','e');return;}
  var csv=csvRow(['#','Asset Name','Category','Original Value','Depreciation %','Annual Dep','Net Book Value']);
  rows.forEach(function(a,i){
    var annDep=(a.val||0)*(a.dep||0)/100;
    csv+=csvRow([i+1,a.name,a.category||'',a.val||0,a.dep||0,annDep,(a.val||0)-annDep]);
  });
  dlCSV('Assets_'+todayStr()+'.csv',csv);
  toast('Assets exported!','s');
}

function exportAgentsCSV(){
  var rows=DB.agents||[];
  if(rows.length===0){toast('No cost person data','e');return;}
  var csv=csvRow(['#','Name','Role','Rate/Unit','Contact']);
  rows.forEach(function(a,i){ csv+=csvRow([i+1,a.name,a.role||'',a.rate||0,a.contact||'']); });
  var ledger=DB.agentLedger||[];
  if(ledger.length>0){
    csv+=csvRow([]);
    csv+=csvRow(['--- PAYMENT LEDGER ---']);
    csv+=csvRow(['#','Date','Agent','Type','Amount','Note']);
    ledger.forEach(function(l,i){ csv+=csvRow([i+1,l.date||'',l.agent||'',l.type||'',l.amount||0,l.note||'']); });
  }
  dlCSV('CostPersons_'+todayStr()+'.csv',csv);
  toast('Cost persons exported!','s');
}

function exportBalanceSheetCSV(){
  var cust=DB.customers||[], part=DB.partners||[], banks=DB.banks||[], assets=DB.assets||[], prods=DB.products||[];
  var totalRecv=cust.filter(function(c){return c.type==='Customer'||(c.type==='Both'&&(c.bal||0)>=0);}).reduce(function(s,c){return s+(c.bal||0);},0);
  var totalPay=cust.filter(function(c){return c.type==='Supplier'||(c.type==='Both'&&(c.bal||0)<0);}).reduce(function(s,c){return s+Math.abs(c.bal||0);},0);
  var totalBank=banks.reduce(function(s,b){return s+(b.bal||0);},0);
  var totalAssets=assets.reduce(function(s,a){return s+(a.val||0);},0);
  var totalStock=stockValue(prods);
  var totalCapital=part.reduce(function(s,p){return s+(p.cap||0);},0);
  var totalA=totalRecv+totalBank+totalAssets+totalStock;
  var totalL=totalPay+totalCapital;
  var csv='';
  csv+=csvRow(['AYAN AGRO INTERNATIONAL LIMITED']);
  csv+=csvRow(['Balance Sheet as of '+todayStr()]);
  csv+=csvRow([]);
  csv+=csvRow(['ASSETS','Amount','LIABILITIES & EQUITY','Amount']);
  csv+=csvRow(['Customer Receivables',totalRecv,'Supplier Payables',totalPay]);
  csv+=csvRow(['Bank & Cash Balance',totalBank,'Partner Capital',totalCapital]);
  csv+=csvRow(['Fixed Assets',totalAssets,'','']);
  csv+=csvRow(['Warehouse Stock',totalStock,'','']);
  csv+=csvRow(['TOTAL ASSETS',totalA,'TOTAL LIABILITIES + EQUITY',totalL]);
  csv+=csvRow([]);
  csv+=csvRow(['--- CUSTOMER RECEIVABLES ---']);
  csv+=csvRow(['Name','Balance']);
  cust.filter(function(c){return c.type==='Customer'||(c.type==='Both'&&(c.bal||0)>=0);}).forEach(function(c){ csv+=csvRow([c.name,c.bal||0]); });
  csv+=csvRow([]);
  csv+=csvRow(['--- SUPPLIER PAYABLES ---']);
  csv+=csvRow(['Name','Balance']);
  cust.filter(function(c){return c.type==='Supplier'||(c.type==='Both'&&(c.bal||0)<0);}).forEach(function(c){ csv+=csvRow([c.name,Math.abs(c.bal||0)]); });
  csv+=csvRow([]);
  csv+=csvRow(['--- PARTNER CAPITAL ---']);
  csv+=csvRow(['Name','Capital','Share %']);
  part.forEach(function(p){ csv+=csvRow([p.name,p.cap||0,p.share||0]); });
  csv+=csvRow([]);
  csv+=csvRow(['--- BANK ACCOUNTS ---']);
  csv+=csvRow(['Account','Balance']);
  banks.forEach(function(b){ csv+=csvRow([b.name,b.bal||0]); });
  dlCSV('BalanceSheet_'+todayStr()+'.csv',csv);
  toast('Balance Sheet exported!','s');
}

function exportAllCSV(){
  var jobs=[exportTransactionsCSV,exportCustomersCSV,exportPartnersCSV,exportBanksCSV,exportInventoryCSV,exportAssetsCSV,exportBalanceSheetCSV];
  jobs.forEach(function(fn,i){ setTimeout(fn,i*500); });
  toast('Exporting 7 CSV files...','s');
}


