// ============================================================
// PROFIT & LOSS REPORT
// ============================================================
function renderPL(){
  const txs = DB.tx||[];
  // Income
  const sales       = txs.filter(isRevenueTx).reduce((s,t)=>s+txAmt(t),0);
  const salesRet    = txs.filter(t=>t.type==='Sales Return').reduce((s,t)=>s+txAmt(t),0);
  const otherInc    = txs.filter(t=>t.type==='Other Income'||t.type==='Interest Income').reduce((s,t)=>s+txAmt(t),0);
  const grossIncome = sales - salesRet + otherInc;

  // Cost of Goods Sold (COGS) — only the cost of items actually sold,
  // not all purchases.  Unsold stock stays as an inventory asset.
  const purchases   = txs.filter(t=>t.type==='Purchase').reduce((s,t)=>s+txAmt(t),0);
  const whPurchase  = txs.filter(t=>t.type==='Warehouse Purchase'||t.type==='Werhouse Purchase').reduce((s,t)=>s+txAmt(t),0);
  const purchRet    = txs.filter(t=>t.type==='Purchase Return').reduce((s,t)=>s+txAmt(t),0);
  const cogs        = window.computeCOGS(txs) - purchRet;  // COGS adjusted for returns
  const grossProfit = grossIncome - cogs;

  // Operating Expenses
  // FIX (2026-09-12): 'Production Cost' is a real dropdown type that was
  // missing here while its Expenses-group siblings were already present —
  // see the window.EXPENSE_TX_TYPES fix near the top of the file.
  const expTypes = ['Expense','Expense Payment','Staff Salary','Utility Bill','Office Expense',
    'Unload Cost','Extra Cost','QC Cost','Salary Payment','Office Rent','Electricity Bill','Internet Bill',
    'Telephone Bill','Fuel Expense','Transport Cost','Loading Charge','Unloading Charge',
    'Commission Payment','Brokerage Fee','Legal Fee','Audit Fee','Insurance Premium',
    'Tax Payment','Government Fee','License Fee','Maintenance Cost','Repair Expense',
    'Stationery Purchase','Other Expense','Interest Expense','Production Cost'];
  const expenses = txs.filter(t=>expTypes.includes(t.type)).reduce((s,t)=>s+txAmt(t),0);
  const agentCosts = txs.reduce((s,t)=>s+(t.agentAcost||0)+(t.agentBcost||0)+(t.qc||0)+(t.unload||0)+(t.othercost||0)+(t.othercost2||0),0);
  const totalExp = expenses + agentCosts;
  const netProfit = grossProfit - totalExp;

  const fmt = n => {
    const abs = Math.abs(n);
    const sign = n < 0 ? '-' : '';
    if(abs >= 10000000) return sign + (abs/10000000).toFixed(2) + ' Cr';
    if(abs >= 100000)   return sign + (abs/100000).toFixed(2) + ' L';
    if(abs >= 1000)     return sign + (abs/1000).toFixed(1) + 'K';
    return sign + abs.toFixed(0);
  };

  const rows = (items) => items.map(([label,val])=>`
    <tr>
      <td style="padding:6px 10px;">${label}</td>
      <td style="padding:6px 10px;text-align:right;font-weight:600;color:${val>=0?'#16a34a':'#dc2626'}">৳${fmt(val)}</td>
    </tr>`).join('');

  const html = `
  <div style="max-width:600px;margin:0 auto;">
    <h3 style="text-align:center;margin-bottom:16px;color:#1a3a6b;">📊 Profit & Loss Statement</h3>
    <table style="width:100%;border-collapse:collapse;font-size:14px;">
      <thead><tr style="background:#1a3a6b;color:#fff;">
        <th style="padding:8px 10px;text-align:left;">Description</th>
        <th style="padding:8px 10px;text-align:right;">Amount</th>
      </tr></thead>
      <tbody>
        <tr style="background:#f0fdf4;"><td colspan="2" style="padding:6px 10px;font-weight:700;color:#16a34a;">📈 INCOME</td></tr>
        ${rows([['Sales Revenue',sales],['Less: Sales Returns',-salesRet],['Other Income',otherInc]])}
        <tr style="background:#dcfce7;"><td style="padding:6px 10px;font-weight:700;">Gross Income</td><td style="padding:6px 10px;text-align:right;font-weight:700;color:#16a34a;">৳${fmt(grossIncome)}</td></tr>
        <tr style="background:#fef9c3;"><td colspan="2" style="padding:6px 10px;font-weight:700;color:#854d0e;">📦 COST OF GOODS</td></tr>
        ${rows([['Purchases',purchases],['Less: Purchase Returns',-purchRet],['Warehouse Purchases',whPurchase]])}
        <tr style="background:#fef08a;"><td style="padding:6px 10px;font-weight:700;">Cost of Goods Sold</td><td style="padding:6px 10px;text-align:right;font-weight:700;color:#854d0e;">৳${fmt(cogs)}</td></tr>
        <tr style="background:#dbeafe;"><td style="padding:6px 10px;font-weight:700;color:#1d4ed8;">💰 GROSS PROFIT</td><td style="padding:6px 10px;text-align:right;font-weight:700;color:${grossProfit>=0?'#16a34a':'#dc2626'};">৳${fmt(grossProfit)}</td></tr>
        <tr style="background:#fef2f2;"><td colspan="2" style="padding:6px 10px;font-weight:700;color:#dc2626;">💸 OPERATING EXPENSES</td></tr>
        ${rows([['Business Expenses',expenses],['Agent & Field Costs',agentCosts]])}
        <tr style="background:#fecaca;"><td style="padding:6px 10px;font-weight:700;">Total Expenses</td><td style="padding:6px 10px;text-align:right;font-weight:700;color:#dc2626;">৳${fmt(totalExp)}</td></tr>
        <tr style="background:${netProfit>=0?'#16a34a':'#dc2626'};color:#fff;">
          <td style="padding:10px;font-weight:800;font-size:16px;">🏆 NET PROFIT / LOSS</td>
          <td style="padding:10px;text-align:right;font-weight:800;font-size:16px;">৳${fmt(netProfit)}</td>
        </tr>
      </tbody>
    </table>
    <div style="margin-top:12px;display:flex;gap:8px;justify-content:flex-end;">
      <button class="btn btn-sm" style="background:#1a3a6b;color:#fff;" data-x-click="printPageViaLetterhead('pl-report-body-v2','Profit &amp; Loss Statement')">🖨️ Print P&L</button>
    </div>
  </div>`;

  const el = document.getElementById('pl-report-body-v2');
  if(el) el.innerHTML = html;
}

// ============================================================
// BACKUP & RESTORE
// ============================================================
/* FIX (2026-08-28, "backup not all data"): General Ledger entries and
   Quotations are NOT stored in window.DB at all — GLSaveEntry() and QTSave()
   write straight to ledger.php/quotations.php, each backed by its own MySQL
   table (erp_ledger / erp_quotations) that nothing ever mirrors into DB (see
   "var QT = { list: [] };  // module-local state only — never touches
   window.DB" in the quotations module, and the equivalent for Ledger). Every
   backup function below only ever dumped DB, so a full backup silently
   left out every ledger entry and every quotation ever saved — exactly the
   kind of gap that would only surface the day someone actually needed the
   backup. This fetches both fresh from the server and folds them into the
   exported file as extra top-level keys (ledgerEntries / quotationsData),
   without writing them into window.DB itself — DB stays exactly what the
   rest of the app already expects it to be, and this data is export-only.
   Fetch failures (offline, module not uploaded yet) degrade gracefully: the
   backup still completes with whatever DB has, and the user is told which
   part could not be included instead of the export silently going quiet
   about it. */
async function collectBackupExtras(){
  const extras = { ledgerEntries: null, quotationsData: null, warnings: [] };
  try{
    if(window.Ledger && typeof window.Ledger.list === 'function'){
      const out = await window.Ledger.list({ limit: 1000 });
      extras.ledgerEntries = (out && out.data) || [];
    }
  }catch(e){
    extras.warnings.push('General Ledger entries could not be included: ' + ((e && e.message) || e));
  }
  try{
    const base = (window.ERP_CONFIG && window.ERP_CONFIG.API_URL) ? window.ERP_CONFIG.API_URL : 'api.php';
    const url = String(base).replace(/api\.php.*$/i, '') + 'quotations.php?action=list&limit=1000';
    const res = await fetch(url, { credentials: 'include' });
    const out = await res.json();
    if(out && out.success) extras.quotationsData = out.data || [];
    else extras.warnings.push('Quotations could not be included: ' + ((out && out.error) || 'unknown error'));
  }catch(e){
    extras.warnings.push('Quotations could not be included: ' + ((e && e.message) || e));
  }
  return extras;
}
/* ═══════════════════════════════════════════════════════════════════
   RESTORING THE TWO MODULES THAT DO NOT LIVE IN DB

   collectBackupExtras() fetches General Ledger entries and Quotations at
   backup time, because neither is stored in window.DB — they live in the
   erp_ledger / erp_quotations tables behind ledger.php and
   quotations.php. That half was done. The other half never was: every
   restore path (restoreFromBackup, restoreData, restoreJSON) put the
   backup straight into DB, so ledgerEntries and quotationsData landed in
   DB as dead keys that nothing reads — and the real tables stayed empty.
   Ledger entries and quotations were therefore backed up and could never
   be restored, and the two stray keys were then written back into the
   server's state blob on every save, growing it for no reason.

   This replays them into their own tables. Both module endpoints upsert
   by id, so a row keeps its original id and replaying the same backup
   twice updates rather than duplicates.
   ═══════════════════════════════════════════════════════════════════ */
async function restoreModuleExtras(payload){
  const out = { ledger:{ok:0,fail:0}, quotations:{ok:0,fail:0}, notes:[] };
  if(!payload || typeof payload !== 'object') return out;
  const entries = Array.isArray(payload.ledgerEntries)   ? payload.ledgerEntries   : [];
  const quotes  = Array.isArray(payload.quotationsData)  ? payload.quotationsData  : [];
  if(!entries.length && !quotes.length) return out;

  const base = (window.ERP_CONFIG && window.ERP_CONFIG.API_URL) ? window.ERP_CONFIG.API_URL : 'api.php';
  const root = String(base).replace(/api\.php.*$/i, '');
  const post = async (url, body) => {
    const res = await fetch(url, { method:'POST', credentials:'include',
      headers:{ 'Content-Type':'application/json', 'Accept':'application/json' },
      body: JSON.stringify(body) });
    const j = await res.json().catch(function(){ return null; });
    if(!res.ok || !j || j.success === false) throw new Error((j && (j.message||j.error)) || ('HTTP '+res.status));
    return j;
  };

  for(const e of entries){
    try{ await post(root+'ledger.php?action=save', { entry: e }); out.ledger.ok++; }
    catch(err){ out.ledger.fail++; if(out.notes.length<3) out.notes.push('Ledger: '+err.message); }
  }
  for(const q of quotes){
    try{ await post(root+'quotations.php?action=save', { quotation: q }); out.quotations.ok++; }
    catch(err){ out.quotations.fail++; if(out.notes.length<3) out.notes.push('Quotations: '+err.message); }
  }
  return out;
}

/* The two extras keys must never be left sitting in DB: nothing reads them
   there, and they would be written into the server's state blob on the
   next save. Also re-establishes the products/inventory shared array,
   which JSON cannot preserve — a restored file always arrives with two
   separate copies. */
function tidyRestoredDB(){
  try{ delete window.DB.ledgerEntries; }catch(e){}
  try{ delete window.DB.quotationsData; }catch(e){}
  try{ if(typeof invItems==='function') invItems(); }catch(e){}
}

/* One line the user can actually read, after a restore. */
function reportRestoredExtras(r){
  if(!r) return;
  const bits=[];
  if(r.ledger.ok)      bits.push(r.ledger.ok+' ledger entries');
  if(r.quotations.ok)  bits.push(r.quotations.ok+' quotations');
  const failed=r.ledger.fail+r.quotations.fail;
  if(bits.length && typeof toast==='function') toast('Also restored '+bits.join(' and ')+'.', 's');
  if(failed && typeof toast==='function')
    toast(failed+' ledger/quotation row(s) could not be restored'+(r.notes.length?' — '+r.notes[0]:'')+'. Check the modules are installed.', 'e');
}

function warnIfBackupIncomplete(extras){
  if(extras && extras.warnings && extras.warnings.length && typeof toast === 'function'){
    toast('Backup saved, but: ' + extras.warnings.join(' · '), 'w');
  }
}
async function backupData(){
  const extras = await collectBackupExtras();
  const backup = {
    version: '1.0',
    date: new Date().toISOString(),
    DB: DB,
    ledgerEntries: extras.ledgerEntries,
    quotationsData: extras.quotationsData
  };
  const blob = new Blob([JSON.stringify(backup, null, 2)], {type:'application/json'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'RBO_Backup_' + new Date().toISOString().split('T')[0] + '.json';
  a.click();
  URL.revokeObjectURL(url);
  /* FIX: the file downloaded but nothing recorded that it had happened, so
     Health Check kept saying "No backup recorded — your data is at risk"
     however many backups were taken. */
  try{
    DB.lastBackup = new Date().toISOString().split('T')[0];
    localStorage.setItem('ayan_last_backup', String(Date.now()));
    if(typeof saveDB==='function') saveDB();
  }catch(e){}
  toast('Backup downloaded!', 's');
  warnIfBackupIncomplete(extras);
}

function restoreData(){
  const input = document.createElement('input');
  input.type = 'file';
  input.accept = '.json';
  input.onchange = e => {
    const file = e.target.files[0];
    if(!file) return;
    const reader = new FileReader();
    reader.onload = async ev => {
      try {
        const backup = __ayanSafeJSONParse(ev.target.result);
        if(!backup.DB) { toast('Invalid backup file!', 'e'); return; }
        if(!await __confirm('⚠️ This will REPLACE all current data with the backup. Continue?')) return;
        Object.assign(DB, backup.DB);
        try{ repairTxIds(); }catch(e){}
        /* Same gap as restoreFromBackup: backup.ledgerEntries and
           backup.quotationsData were read at backup time and then ignored
           here, so those two modules were never actually restored. */
        let extras=null;
        try{ extras = await restoreModuleExtras(backup); }catch(e){}
        try{ tidyRestoredDB(); }catch(e){}
        saveDB();
        render();
        toast('Data restored successfully!', 's');
        try{ reportRestoredExtras(extras); }catch(e){}
      } catch(err) {
        toast('Failed to read backup file!', 'e');
      }
    };
    reader.readAsText(file);
  };
  input.click();
}

// ============================================================
// OVERDUE TRACKING
// ============================================================
function getOverdueCustomers(){
  // Customers with positive balance (they owe us)
  return DB.customers
    .filter(c => (c.bal||0) > 0)
    .sort((a,b) => (b.bal||0) - (a.bal||0));
}

function renderOverdue(){
  const overdue = getOverdueCustomers();
  const total = overdue.reduce((s,c)=>s+(c.bal||0),0);
  const el = document.getElementById('overdue-body');
  if(!el) return;
  if(overdue.length === 0){
    if(el) el.innerHTML = '<tr><td colspan="4" style="text-align:center;padding:20px;color:#6b7280;">✅ No overdue amounts</td></tr>';
    return;
  }
  if(el) el.innerHTML = overdue.map((c,i) => `
    <tr style="background:${(c.bal||0)>500000?'#fef2f2':(c.bal||0)>100000?'#fef9c3':'#fff'}">
      <td style="padding:8px 10px;">${i+1}</td>
      <td style="padding:8px 10px;font-weight:600;">${escHTML(c.name)}</td>
      <td style="padding:8px 10px;"><span class="badge b-gray">${c.type||'-'}</span></td>
      <td style="padding:8px 10px;text-align:right;font-weight:700;color:#dc2626;">৳${(c.bal||0).toLocaleString('en-IN')}</td>
    </tr>`).join('');
  const footer = document.getElementById('overdue-footer');
  if(footer) footer.innerHTML = `Total Overdue: <strong style="color:#dc2626;">৳${total.toLocaleString('en-IN')}</strong> from <strong>${overdue.length}</strong> parties`;
}

