    <table style="width:100%;border-collapse:collapse;font-size:12px;">
      <thead>
        <tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
          <th style="padding:10px 12px;text-align:left;font-weight:700;">Tender No</th>
          <th style="padding:10px 12px;text-align:left;font-weight:700;">Title / Party</th>
