<!-- PAGE: LEDGERS -->
<!-- ══════════════════════════════════════════════════════════════ -->
<div id="pg-ledgers" class="page" style="display:none">
  <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:18px;">
    <div>
      <h2 style="font-size:20px;font-weight:800;color:#0f3d26;margin:0;">📒 Ledger Statements</h2>
      <p style="font-size:12px;color:#6b7280;margin:2px 0 0;">Customer · Supplier · Partner · Expense ledgers with full transaction history</p>
    </div>
    <button data-x-click="printLedger()" style="background:linear-gradient(135deg,#0f3d26,#16a34a);color:#fff;border:none;padding:9px 18px;border-radius:8px;font-size:13px;font-weight:700;cursor:pointer;">🖨️ Print Ledger</button>
  </div>

  <!-- Controls -->
  <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:14px 16px;margin-bottom:14px;display:flex;gap:12px;align-items:center;flex-wrap:wrap;">
    <div style="display:flex;flex-direction:column;gap:3px;">
      <label style="font-size:10px;font-weight:700;color:#374151;">LEDGER TYPE</label>
      <select id="ldg-type" data-x-change="loadLedgerParties()" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;min-width:140px;">
        <option value="Customer">Customer</option>
        <option value="Supplier">Supplier</option>
        <option value="Partner">Partner</option>
        <option value="Expense">Expense</option>
        <option value="Bank">Bank</option>
        <option value="Location">Location / Warehouse</option>
        <option value="Agent">Agent / Service Provider</option>
      </select>
    </div>
    <div style="display:flex;flex-direction:column;gap:3px;">
      <label style="font-size:10px;font-weight:700;color:#374151;">PARTY / ACCOUNT</label>
      <select id="ldg-party" data-x-change="renderLedger()" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;min-width:200px;">
        <option value="">-- Select --</option>
      </select>
    </div>
    <div style="display:flex;flex-direction:column;gap:3px;">
      <label style="font-size:10px;font-weight:700;color:#374151;">FROM DATE</label>
      <input id="ldg-from" type="date" data-x-change="renderLedger()" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;"/>
    </div>
    <div style="display:flex;flex-direction:column;gap:3px;">
      <label style="font-size:10px;font-weight:700;color:#374151;">TO DATE</label>
      <input id="ldg-to" type="date" data-x-change="renderLedger()" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;"/>
    </div>
    <div style="margin-top:16px;">
      <button data-x-click="renderLedger()" style="padding:7px 16px;background:#16a34a;color:#fff;border:none;border-radius:6px;font-size:12px;font-weight:700;cursor:pointer;">🔍 Show</button>
    </div>
  </div>

  <!-- Ledger Summary Bar -->
  <div id="ldg-summary" style="display:none;background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;border-radius:10px;padding:14px 20px;margin-bottom:14px;display:grid;grid-template-columns:repeat(4,1fr);gap:12px;">
    <div><div style="font-size:10px;opacity:.8;">Opening Balance</div><div style="font-size:16px;font-weight:800;" id="ldg-opening">৳0</div></div>
    <div><div style="font-size:10px;opacity:.8;">Total Debit</div><div style="font-size:16px;font-weight:800;" id="ldg-debit">৳0</div></div>
    <div><div style="font-size:10px;opacity:.8;">Total Credit</div><div style="font-size:16px;font-weight:800;" id="ldg-credit">৳0</div></div>
    <div><div style="font-size:10px;opacity:.8;">Closing Balance</div><div style="font-size:16px;font-weight:800;" id="ldg-closing">৳0</div></div>
  </div>

  <!-- Ledger Table -->
  <div id="ldg-table-wrap" style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
    <div style="text-align:center;padding:40px;color:#9ca3af;">Select a ledger type and party to view statement.</div>
  </div>
</div>


