<!-- PAGE: BANK RECONCILIATION -->
<!-- ══════════════════════════════════════════════════════════════ -->
<div id="pg-bankreconciliation" class="page" style="display:none">
  <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:18px;">
    <div>
      <h2 style="font-size:20px;font-weight:800;color:#0f3d26;margin:0;">🏦 Bank Reconciliation</h2>
      <p style="font-size:12px;color:#6b7280;margin:2px 0 0;">Bank ledger, cheque register and reconciliation statement</p>
    </div>
    <button data-x-click="openChequeModal()" style="background:linear-gradient(135deg,#16a34a,#15803d);color:#fff;border:none;padding:9px 18px;border-radius:8px;font-size:13px;font-weight:700;cursor:pointer;">➕ Add Cheque</button>
  </div>

  <!-- Tabs -->
  <div style="display:flex;gap:0;margin-bottom:0;border-bottom:2px solid #e5e7eb;">
    <button data-x-click="switchBankTab('ledger')" id="bk-tab-ledger"
      style="padding:9px 20px;border:none;background:none;font-size:13px;font-weight:700;color:#16a34a;border-bottom:3px solid #16a34a;cursor:pointer;">📋 Bank Ledger</button>
    <button data-x-click="switchBankTab('cheques')" id="bk-tab-cheques"
      style="padding:9px 20px;border:none;background:none;font-size:13px;font-weight:600;color:#6b7280;cursor:pointer;">🧾 Cheque Register</button>
    <button data-x-click="switchBankTab('recon')" id="bk-tab-recon"
      style="padding:9px 20px;border:none;background:none;font-size:13px;font-weight:600;color:#6b7280;cursor:pointer;">⚖️ Reconciliation</button>
  </div>

  <!-- Bank Ledger Panel -->
  <div id="bk-panel-ledger" style="background:#fff;border:1px solid #e5e7eb;border-top:none;border-radius:0 0 10px 10px;padding:14px;">
    <div style="display:flex;gap:10px;margin-bottom:12px;flex-wrap:wrap;">
      <select id="bk-account" data-x-change="renderBankLedger()" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;min-width:220px;">
        <option value="">-- Select Bank Account --</option>
      </select>
      <input id="bk-from" type="date" data-x-change="renderBankLedger()" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;"/>
      <input id="bk-to" type="date" data-x-change="renderBankLedger()" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;"/>
      <button data-x-click="renderBankLedger()" style="padding:7px 14px;background:#16a34a;color:#fff;border:none;border-radius:6px;font-size:12px;font-weight:700;cursor:pointer;">🔍 Show</button>
      <button data-x-click="renderAllBankAccountsSummary()" style="padding:7px 14px;background:#0f3d26;color:#fff;border:none;border-radius:6px;font-size:12px;font-weight:700;cursor:pointer;">📊 All Accounts Summary</button>
    </div>
    <!-- All-accounts summary (opening → in/out → closing, every account at once) -->
    <div id="bk-all-summary" style="display:none;"></div>
    <!-- Summary -->
    <div id="bk-ledger-summary" style="display:none;background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;border-radius:8px;padding:12px 16px;margin-bottom:12px;display:grid;grid-template-columns:repeat(4,1fr);gap:10px;">
      <div><div style="font-size:10px;opacity:.8;">Opening</div><div style="font-size:15px;font-weight:800;" id="bk-open">৳0</div></div>
      <div><div style="font-size:10px;opacity:.8;">Total In</div><div style="font-size:15px;font-weight:800;" id="bk-in">৳0</div></div>
      <div><div style="font-size:10px;opacity:.8;">Total Out</div><div style="font-size:15px;font-weight:800;" id="bk-out">৳0</div></div>
      <div><div style="font-size:10px;opacity:.8;">Closing</div><div style="font-size:15px;font-weight:800;" id="bk-close">৳0</div></div>
    </div>
    <div id="bk-ledger-table"><div style="text-align:center;padding:30px;color:#9ca3af;">Select a bank account to view ledger.</div></div>
  </div>

  <!-- Cheque Register Panel -->
  <div id="bk-panel-cheques" style="display:none;background:#fff;border:1px solid #e5e7eb;border-top:none;border-radius:0 0 10px 10px;overflow:hidden;">
    <table style="width:100%;border-collapse:collapse;font-size:12px;">
      <thead>
        <tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">
          <th style="padding:10px 12px;text-align:left;">Cheque No</th>
          <th style="padding:10px 12px;text-align:left;">Date</th>
          <th style="padding:10px 12px;text-align:left;">Party</th>
          <th style="padding:10px 12px;text-align:left;">Bank Account</th>
          <th style="padding:10px 12px;text-align:left;">Type</th>
          <th style="padding:10px 12px;text-align:right;">Amount (৳)</th>
          <th style="padding:10px 12px;text-align:center;">Status</th>
          <th style="padding:10px 12px;text-align:center;">Actions</th>
        </tr>
      </thead>
      <tbody id="cheque-tbody">
        <tr><td colspan="8" style="text-align:center;padding:30px;color:#9ca3af;">No cheques recorded. Click ➕ Add Cheque.</td></tr>
      </tbody>
    </table>
  </div>

  <!-- Reconciliation Panel -->
  <div id="bk-panel-recon" style="display:none;background:#fff;border:1px solid #e5e7eb;border-top:none;border-radius:0 0 10px 10px;padding:16px;">
    <div style="display:flex;gap:10px;margin-bottom:14px;">
      <select id="recon-account" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;min-width:220px;">
        <option value="">-- Select Bank Account --</option>
      </select>
      <input id="recon-statement-bal" type="number" placeholder="Bank Statement Balance (৳)" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;min-width:200px;"/>
      <button data-x-click="runReconciliation()" style="padding:7px 16px;background:#16a34a;color:#fff;border:none;border-radius:6px;font-size:12px;font-weight:700;cursor:pointer;">⚖️ Reconcile</button>
    </div>
    <div id="recon-result" style="display:none;">
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;">
        <div style="background:#f0fdf4;border:1px solid #bbf7d0;border-radius:10px;padding:16px;">
          <h4 style="color:#0f3d26;margin:0 0 12px;font-size:13px;">📒 Book Balance</h4>
          <div id="recon-book-detail"></div>
        </div>
        <div style="background:#eff6ff;border:1px solid #bfdbfe;border-radius:10px;padding:16px;">
          <h4 style="color:#1d4ed8;margin:0 0 12px;font-size:13px;">🏦 Bank Statement</h4>
          <div id="recon-bank-detail"></div>
        </div>
      </div>
      <div id="recon-status" style="margin-top:14px;padding:14px;border-radius:10px;text-align:center;font-size:15px;font-weight:800;"></div>
    </div>

    <!-- Auto-Match: Bank Statement vs System Transactions -->
    <div style="margin-top:22px;padding-top:18px;border-top:2px dashed #e5e7eb;">
      <h4 style="color:#0f3d26;margin:0 0 6px;font-size:14px;">🤖 Auto-Match Bank Statement</h4>
      <p style="font-size:11.5px;color:#6b7280;margin:0 0 12px;">Upload a bank statement CSV. Each line is matched against existing transactions by amount and date so you only import genuinely new entries — no duplicate bookings.</p>
      <div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-bottom:12px;">
        <input type="file" id="am-csv-file" accept=".csv" style="font-size:12px;"/>
        <input id="am-bank-name" type="text" placeholder="Bank / account name for these rows" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;min-width:220px;"/>
        <button data-x-click="autoMatchRunSuggestions()" style="padding:7px 16px;background:#2563eb;color:#fff;border:none;border-radius:6px;font-size:12px;font-weight:700;cursor:pointer;">🔎 Suggest Matches</button>
      </div>
      <div id="am-results"></div>
    </div>
  </div>
</div>

