    <button data-x-click="switchRptTab('product')" id="rpt-tab-product" style="padding:9px 18px;border:none;background:none;font-size:13px;font-weight:600;color:#6b7280;cursor:pointer;">📦 Product P&L</button>
    <button data-x-click="switchRptTab('aging')" id="rpt-tab-aging" style="padding:9px 18px;border:none;background:none;font-size:13px;font-weight:600;color:#6b7280;cursor:pointer;">⏰ Aging</button>
