      <button data-x-click="renderDailySalesReport()" style="padding:7px 14px;background:#16a34a;color:#fff;border:none;border-radius:6px;font-size:12px;font-weight:700;cursor:pointer;">📊 Show</button>
    </div>
    <div id="rpt-daily-body"></div>
  </div>

  <!-- Product P&L Panel -->
  <div id="rpt-panel-product" style="display:none;background:#fff;border:1px solid #e5e7eb;border-top:none;border-radius:0 0 10px 10px;padding:16px;">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;">
      <h3 style="font-size:14px;font-weight:800;color:#0f3d26;margin:0;">Product-wise Profit & Loss</h3>
      <button data-x-click="renderProductPL()" style="padding:6px 14px;background:#16a34a;color:#fff;border:none;border-radius:6px;font-size:12px;cursor:pointer;">🔄 Refresh</button>
    </div>
    <div id="rpt-product-body"></div>
  </div>

  <!-- Aging Panel -->
  <div id="rpt-panel-aging" style="display:none;background:#fff;border:1px solid #e5e7eb;border-top:none;border-radius:0 0 10px 10px;padding:16px;">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px;">
      <h3 style="font-size:14px;font-weight:800;color:#0f3d26;margin:0;">Customer Aging Report</h3>
      <button data-x-click="renderAgingReport()" style="padding:6px 14px;background:#16a34a;color:#fff;border:none;border-radius:6px;font-size:12px;cursor:pointer;">🔄 Refresh</button>
    </div>
    <div id="rpt-aging-body"></div>
  </div>
</div>


