<!-- PAGE: STOCK MOVEMENT & ALERTS -->
<!-- ══════════════════════════════════════════════════════════════ -->
<div id="pg-stockmovement" class="page" style="display:none">
  <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:18px;">
    <div>
      <h2 style="font-size:20px;font-weight:800;color:#0f3d26;margin:0;">📦 Stock Movement & Alerts</h2>
      <p style="font-size:12px;color:#6b7280;margin:2px 0 0;">Track inventory movements and low stock warnings</p>
    </div>
    <button data-x-click="renderStockMovement()" style="background:linear-gradient(135deg,#16a34a,#15803d);color:#fff;border:none;padding:9px 18px;border-radius:8px;font-size:13px;font-weight:700;cursor:pointer;">🔄 Refresh</button>
  </div>

  <!-- Tabs -->
  <div style="display:flex;gap:0;border-bottom:2px solid #e5e7eb;margin-bottom:0;">
    <button data-x-click="switchStockTab('movement')" id="stk-tab-movement" style="padding:9px 18px;border:none;background:none;font-size:13px;font-weight:700;color:#16a34a;border-bottom:3px solid #16a34a;cursor:pointer;">📋 Movement Log</button>
    <button data-x-click="switchStockTab('alerts')" id="stk-tab-alerts" style="padding:9px 18px;border:none;background:none;font-size:13px;font-weight:600;color:#6b7280;cursor:pointer;">🔔 Low Stock Alerts</button>
    <button data-x-click="switchStockTab('summary')" id="stk-tab-summary" style="padding:9px 18px;border:none;background:none;font-size:13px;font-weight:600;color:#6b7280;cursor:pointer;">📊 Stock Summary</button>
  </div>

  <!-- Movement Log Panel -->
  <div id="stk-panel-movement" style="background:#fff;border:1px solid #e5e7eb;border-top:none;border-radius:0 0 10px 10px;padding:14px;">
    <div style="display:flex;gap:10px;margin-bottom:12px;flex-wrap:wrap;">
      <select id="stk-product-filter" data-x-change="renderStockMovement()" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;min-width:180px;">
        <option value="">All Products</option>
      </select>
      <select id="stk-move-type" data-x-change="renderStockMovement()" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;">
        <option value="">All Types</option>
        <option value="IN">Stock In</option>
        <option value="OUT">Stock Out</option>
      </select>
      <input id="stk-from" type="date" data-x-change="renderStockMovement()" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;"/>
      <input id="stk-to" type="date" data-x-change="renderStockMovement()" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;"/>
    </div>
    <div id="stk-movement-table"></div>
  </div>

  <!-- Low Stock Alerts Panel -->
  <div id="stk-panel-alerts" style="display:none;background:#fff;border:1px solid #e5e7eb;border-top:none;border-radius:0 0 10px 10px;padding:14px;">
    <div style="display:flex;gap:10px;align-items:center;margin-bottom:12px;">
      <label style="font-size:12px;font-weight:600;color:#374151;">Alert Threshold:</label>
      <input id="stk-threshold" type="number" value="100" min="0" style="padding:6px 10px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;width:100px;"/>
      <button data-x-click="renderLowStockAlerts()" style="padding:7px 14px;background:#dc2626;color:#fff;border:none;border-radius:6px;font-size:12px;font-weight:700;cursor:pointer;">🔔 Check Alerts</button>
    </div>
    <div id="stk-alerts-body"></div>
  </div>

  <!-- Stock Summary Panel -->
  <div id="stk-panel-summary" style="display:none;background:#fff;border:1px solid #e5e7eb;border-top:none;border-radius:0 0 10px 10px;padding:14px;">
    <div id="stk-summary-body"></div>
  </div>
</div>


<!-- ══════════════════════════════════════════════════════════════ -->
<!-- LOGIN SCREEN -->
<!-- ══════════════════════════════════════════════════════════════ -->
<!-- ══════════════════════════════════════════════════════════════ -->
<!-- ENHANCED LOGIN SCREEN v14 -->
<!-- ══════════════════════════════════════════════════════════════ -->
<style>
#login-screen { font-family:'Segoe UI',Arial,sans-serif; }
#login-screen .ls-card { animation: lsFadeIn .4s ease; }
@keyframes lsFadeIn { from{opacity:0;transform:translateY(20px)} to{opacity:1;transform:translateY(0)} }
#login-screen .ls-input-wrap { position:relative; }
#login-screen .ls-input-wrap input { padding-right:42px!important; }
#login-screen .ls-eye { position:absolute;right:12px;top:50%;transform:translateY(-50%);cursor:pointer;font-size:16px;user-select:none;color:#9ca3af;transition:color .2s; }
#login-screen .ls-eye:hover { color:#16a34a; }
#login-screen .ls-field { width:100%;padding:11px 14px;border:2px solid #e5e7eb;border-radius:9px;font-size:13px;box-sizing:border-box;outline:none;transition:border .2s,box-shadow .2s; }
#login-screen .ls-field:focus { border-color:#16a34a;box-shadow:0 0 0 3px rgba(22,163,74,.12); }
#login-screen .ls-btn { width:100%;padding:13px;background:linear-gradient(135deg,#16a34a,#0f3d26);color:#fff;border:none;border-radius:9px;font-size:15px;font-weight:800;cursor:pointer;letter-spacing:.5px;transition:opacity .2s,transform .1s; }
#login-screen .ls-btn:hover { opacity:.92; }
#login-screen .ls-btn:active { transform:scale(.98); }
#login-screen .ls-btn:disabled { opacity:.55;cursor:not-allowed; }
#login-screen .ls-caps { display:none;background:#fff8e1;border:1px solid #f59e0b;color:#b45309;padding:5px 10px;border-radius:5px;font-size:11px;margin-bottom:8px;text-align:center; }
#login-screen .ls-hint { background:#f0fdf4;border:1px solid #bbf7d0;border-radius:7px;padding:8px 12px;font-size:11px;color:#15803d;margin-top:10px;text-align:center; }
.ls-spinner { display:inline-block;width:16px;height:16px;border:2px solid rgba(255,255,255,.4);border-top-color:#fff;border-radius:50%;animation:lsSpin .7s linear infinite;vertical-align:middle;margin-right:6px; }
@keyframes lsSpin { to{transform:rotate(360deg)} }
/* Floating shapes background */
#login-screen .ls-shape { position:absolute;border-radius:50%;background:rgba(255,255,255,.05);animation:lsFloat 6s ease-in-out infinite; }
@keyframes lsFloat { 0%,100%{transform:translateY(0)} 50%{transform:translateY(-20px)} }
</style>
<div id="login-screen" style="display:none;position:fixed;inset:0;z-index:9999;background:linear-gradient(135deg,#0a2d1c 0%,#0f3d26 55%,#16a34a 100%);align-items:center;justify-content:center;overflow-y:auto;-webkit-overflow-scrolling:touch;padding:16px 0;box-sizing:border-box;">
  <!-- Decorative floating circles -->
  <div class="ls-shape" style="width:180px;height:180px;top:-60px;left:-60px;animation-delay:0s;"></div>
  <div class="ls-shape" style="width:100px;height:100px;bottom:80px;right:60px;animation-delay:2s;"></div>
  <div class="ls-shape" style="width:60px;height:60px;top:40%;left:5%;animation-delay:4s;"></div>
  <div class="ls-shape" style="width:140px;height:140px;bottom:-40px;left:30%;animation-delay:1s;"></div>

  <div class="ls-card" style="background:#fff;border-radius:20px;padding:0;width:400px;max-width:96vw;box-shadow:0 32px 80px rgba(0,0,0,.5);overflow:hidden;position:relative;z-index:1;">
    <!-- Top banner -->
    <div style="background:linear-gradient(135deg,#0f3d26,#16a34a);padding:28px 32px 22px;text-align:center;">
      <div style="width:72px;height:72px;background:rgba(255,255,255,.15);border-radius:18px;display:flex;align-items:center;justify-content:center;font-size:36px;margin:0 auto 12px;border:2px solid rgba(255,255,255,.25);box-shadow:0 8px 24px rgba(0,0,0,.2);">🌿</div>
      <div style="font-size:19px;font-weight:900;color:#fff;letter-spacing:.5px;">AYAN AGRO ERP</div>
      <div style="font-size:10px;color:#bbf7d0;font-weight:600;letter-spacing:2px;margin-top:3px;">INTERNATIONAL LIMITED</div>
      <div style="font-size:10px;color:rgba(255,255,255,.55);margin-top:5px;">🌾 Rice Bran Oil Management System</div>
    </div>

    <!-- Form body -->
    <div style="padding:24px 28px 26px;">
      <div style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:18px;text-align:center;">🔐 Sign In to Your Account</div>

      <!-- Caps Lock warning -->
      <div class="ls-caps" id="ls-caps-warn">⚠️ Caps Lock is ON</div>
      <!-- Lockout warning -->
      <div id="ls-lockout-warn" style="display:none;background:#fef2f2;border:1px solid #fecaca;color:#dc2626;padding:8px 12px;border-radius:7px;font-size:11px;margin-bottom:12px;text-align:center;"></div>

      <!-- Username -->
      <div style="margin-bottom:14px;">
        <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:5px;text-transform:uppercase;letter-spacing:.5px;">📧 Email</label>
        <div class="ls-input-wrap">
          <input class="ls-field" id="login-user" type="email" placeholder="you@company.com" autocomplete="email"
            onkeydown="if(event.key==='Enter')document.getElementById('login-pass').focus()"/>
        </div>
      </div>

      <!-- Password -->
      <div style="margin-bottom:6px;">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:5px;">
          <label style="font-size:11px;font-weight:700;color:#374151;text-transform:uppercase;letter-spacing:.5px;">🔑 Password</label>
          <span style="font-size:10px;color:#16a34a;cursor:pointer;font-weight:600;" data-x-click="lsShowHint()">Forgot password?</span>
        </div>
        <div class="ls-input-wrap">
          <input class="ls-field" id="login-pass" type="password" placeholder="Enter your password" autocomplete="current-password"
            onkeydown="if(event.key==='Enter')doLogin();lsCheckCaps(event)"
            data-x-keyup-caps="1"/>
          <span class="ls-eye" id="ls-eye-btn" data-x-click="lsTogglePass()" title="Show/Hide password">👁</span>
        </div>
      </div>

      <!-- Remember me -->
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;margin-top:10px;">
        <label style="display:flex;align-items:center;gap:7px;cursor:pointer;font-size:12px;color:#374151;font-weight:600;">
          <input type="checkbox" id="ls-remember" style="accent-color:#16a34a;width:14px;height:14px;">
          Remember me (30 days)
        </label>
        <span id="ls-attempts-left" style="font-size:10px;color:#9ca3af;"></span>
      </div>

      <!-- Error -->
      <div id="login-error" style="display:none;background:#fef2f2;border:1px solid #fecaca;color:#dc2626;padding:9px 12px;border-radius:7px;font-size:12px;margin-bottom:14px;text-align:center;border-left:4px solid #dc2626;"></div>

      <!-- Login button -->
      <button class="ls-btn" id="ls-login-btn" data-x-click="doLogin()">🔐 Sign In</button>
      <div style="margin-top:10px;text-align:center;font-size:12px;color:#374151;">
        First time here?
        <span id="ls-signup-link" data-x-click="erpSignUp()" style="color:#16a34a;font-weight:700;cursor:pointer;text-decoration:underline;">Create an account</span>
      </div>
      <div id="ls-cloud-note" style="margin-top:10px;text-align:center;font-size:10px;color:#9ca3af;">Connecting to secure cloud…</div>
      <div style="margin-top:12px;text-align:center;">
        <button data-x-click="emergencyReset()" style="background:none;border:none;color:rgba(255,255,255,.6);font-size:11px;cursor:pointer;text-decoration:underline;">
          🔄 Reset & Clear Session (if login fails)
        </button>
      </div>

      <!-- Hint box -->
      <div class="ls-hint" id="ls-hint-box" style="display:none;">
        Enter your work email and we will send you a password reset link.
      </div>

      <!-- Footer -->
      <div style="text-align:center;margin-top:14px;padding-top:14px;border-top:1px solid #f3f4f6;">
        <div style="font-size:10px;color:#9ca3af;">🔒 Secure login &nbsp;|&nbsp; Session expires after inactivity</div>
        <div style="font-size:10px;color:#d1d5db;margin-top:3px;">v14 &nbsp;©&nbsp; Ayan Agro ERP International Ltd.</div>
      </div>
    </div>
  </div>
</div>

<!-- ══════════════════════════════════════════════════════════════ -->
<!-- PAGE: USER MANAGEMENT v14 — Full CRUD + Search + Filter + Print -->
<!-- ══════════════════════════════════════════════════════════════ -->
<style>
/* ── User Management Page Styles ── */
.um-stat-card{background:#fff;border-radius:12px;padding:16px 20px;border:1px solid #e5e7eb;cursor:pointer;transition:box-shadow .2s,transform .15s;}
.um-stat-card:hover{box-shadow:0 4px 20px rgba(0,0,0,.1);transform:translateY(-2px);}
.um-toolbar{display:flex;flex-wrap:wrap;gap:8px;align-items:center;background:#fff;padding:12px 14px;border-radius:10px;border:1px solid #e5e7eb;margin-bottom:12px;}
.um-search{flex:1;min-width:180px;padding:8px 12px 8px 34px;border:1.5px solid #e5e7eb;border-radius:8px;font-size:12px;outline:none;transition:border .2s;}
.um-search:focus{border-color:#16a34a;box-shadow:0 0 0 3px rgba(22,163,74,.1);}
.um-select{padding:8px 10px;border:1.5px solid #e5e7eb;border-radius:8px;font-size:12px;outline:none;background:#fff;cursor:pointer;color:#374151;}
.um-select:focus{border-color:#16a34a;}
.um-btn{padding:8px 14px;border:none;border-radius:8px;font-size:12px;font-weight:700;cursor:pointer;white-space:nowrap;transition:opacity .2s,transform .1s;}
.um-btn:active{transform:scale(.97);}
.um-btn-green{background:linear-gradient(135deg,#16a34a,#0f3d26);color:#fff;}
.um-btn-blue{background:linear-gradient(135deg,#2563eb,#1d4ed8);color:#fff;}
.um-btn-amber{background:linear-gradient(135deg,#d97706,#b45309);color:#fff;}
.um-btn-red{background:linear-gradient(135deg,#dc2626,#b91c1c);color:#fff;}
.um-btn-gray{background:#f3f4f6;border:1px solid #d1d5db;color:#374151;}
.um-btn-sm{padding:5px 10px;font-size:11px;}
.um-table{width:100%;border-collapse:collapse;font-size:12px;}
.um-table thead tr{background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;}
.um-table th{padding:11px 12px;text-align:left;font-weight:700;white-space:nowrap;}
.um-table td{padding:9px 12px;border-bottom:1px solid #f3f4f6;vertical-align:middle;}
.um-table tbody tr:hover{background:#f0fdf4;}
.um-table tbody tr:nth-child(even){background:#fafafa;}
.um-table tbody tr:nth-child(even):hover{background:#f0fdf4;}
.um-badge{display:inline-block;padding:3px 10px;border-radius:20px;font-size:10px;font-weight:800;letter-spacing:.3px;}
.um-status-active{background:#dcfce7;color:#16a34a;}
.um-status-inactive{background:#fee2e2;color:#dc2626;}
.um-status-suspended{background:#fef3c7;color:#d97706;}
.um-role-admin{background:#fee2e2;color:#dc2626;}
.um-role-manager{background:#ede9fe;color:#7c3aed;}
.um-role-operator{background:#dbeafe;color:#2563eb;}
.um-role-viewer{background:#f3f4f6;color:#6b7280;}
.um-modal-overlay{display:none;position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:8000;align-items:center;justify-content:center;backdrop-filter:blur(2px);}
.um-modal-overlay.open{display:flex;}
.um-modal-box{background:#fff;border-radius:16px;width:600px;max-width:96vw;max-height:92vh;overflow:hidden;display:flex;flex-direction:column;box-shadow:0 25px 80px rgba(0,0,0,.35);animation:umSlideIn .25s ease;}
@keyframes umSlideIn{from{opacity:0;transform:scale(.95) translateY(-10px)}to{opacity:1;transform:scale(1) translateY(0)}}
.um-modal-hdr{padding:16px 20px;display:flex;justify-content:space-between;align-items:center;flex-shrink:0;}
.um-modal-body{padding:20px;overflow-y:auto;flex:1;}
.um-modal-ftr{padding:14px 20px;border-top:1px solid #f3f4f6;display:flex;justify-content:flex-end;gap:10px;flex-shrink:0;background:#fafafa;}
.um-field-group{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:0;}
.um-field{display:flex;flex-direction:column;gap:4px;}
.um-field.span2{grid-column:span 2;}
.um-label{font-size:11px;font-weight:700;color:#374151;text-transform:uppercase;letter-spacing:.4px;}
.um-input{padding:9px 12px;border:1.5px solid #e5e7eb;border-radius:8px;font-size:13px;outline:none;transition:border .2s;width:100%;box-sizing:border-box;}
.um-input:focus{border-color:#16a34a;box-shadow:0 0 0 3px rgba(22,163,74,.1);}
.um-input-wrap{position:relative;}
.um-input-wrap .um-input{padding-right:40px;}
.um-eye-btn{position:absolute;right:10px;top:50%;transform:translateY(-50%);cursor:pointer;font-size:15px;color:#9ca3af;}
.um-perms-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:10px;}
.um-perm-item{display:flex;align-items:center;gap:7px;padding:7px 10px;background:#f9fafb;border:1px solid #e5e7eb;border-radius:7px;cursor:pointer;transition:background .15s;}
.um-perm-item:hover{background:#f0fdf4;border-color:#bbf7d0;}
.um-perm-item input{accent-color:#16a34a;}
.um-perm-label{font-size:11px;font-weight:600;color:#374151;}
.um-str-bar{height:4px;border-radius:4px;margin-top:6px;transition:width .3s,background .3s;}
.um-activity-dot{width:8px;height:8px;border-radius:50%;display:inline-block;margin-right:5px;}
.um-empty{text-align:center;padding:50px 20px;color:#9ca3af;}
.um-empty-icon{font-size:40px;margin-bottom:12px;}
.um-pagination{display:flex;align-items:center;gap:6px;flex-wrap:wrap;}
.um-page-btn{padding:5px 11px;border:1.5px solid #e5e7eb;border-radius:7px;font-size:11px;cursor:pointer;background:#fff;font-weight:600;transition:all .15s;}
.um-page-btn:hover{background:#f0fdf4;border-color:#16a34a;color:#16a34a;}
.um-page-btn.active{background:#16a34a;border-color:#16a34a;color:#fff;}
/* Print styles for user list */
@media print {
  .um-toolbar,.um-modal-overlay,.um-pagination,.um-no-print{display:none!important;}
}
</style>

<div id="pg-users" class="page" style="display:none">
<div style="padding:20px;">
  <!-- Page Header (FIX: this used to be duplicated by a second, smaller
       header below -- "👥 User Management" heading + a lone Add User
       button -- which rendered stacked above the stats/table on every
       page load. That compact header added nothing this one doesn't
       already have, so it was removed; this is now the only header,
       correctly positioned above the stats/table it introduces. -->
  <div style="display:flex;align-items:flex-start;justify-content:space-between;flex-wrap:wrap;gap:12px;margin-bottom:18px;">
    <div>
      <h2 style="font-size:22px;font-weight:900;color:#0f3d26;margin:0;display:flex;align-items:center;gap:8px;">
        👥 User Management
        <span id="um-user-count-badge" style="background:#dcfce7;color:#16a34a;font-size:12px;font-weight:800;padding:3px 10px;border-radius:20px;"></span>
      </h2>
      <p style="font-size:12px;color:#6b7280;margin:3px 0 0;">Full CRUD • Role-Based Access • Activity Tracking • Print on Letterhead</p>
    </div>
    <div style="display:flex;gap:8px;flex-wrap:wrap;">
      <button class="um-btn um-btn-blue" data-x-click="umImportCSV()">📥 Import CSV</button>
      <button class="um-btn um-btn-amber" data-x-click="umExportCSV()">📤 Export CSV</button>
      <button class="um-btn um-btn-gray" data-x-click="umPrintUserList()">🖨️ Print List</button>
      <button class="um-btn um-btn-green" data-x-click="umOpenModal()">➕ Add User</button>
    </div>
  </div>
  <div id="um-stats" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:12px;margin-bottom:14px;"></div>
  <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px;">
    <input type="text" id="um-search" placeholder="🔍 Search..." data-x-input="umRender()"
      style="flex:1;min-width:160px;padding:8px 12px;border:1.5px solid #d1d5db;border-radius:8px;font-size:12px;">
    <select id="um-role-filter" data-x-change="umRender()" style="padding:8px 12px;border:1.5px solid #d1d5db;border-radius:8px;font-size:12px;">
      <option value="">All Roles</option><option>Admin</option><option>Manager</option><option>Operator</option><option>Viewer</option>
    </select>
    <select id="um-status-filter" data-x-change="umRender()" style="padding:8px 12px;border:1.5px solid #d1d5db;border-radius:8px;font-size:12px;">
      <option value="">All Status</option><option>Active</option><option>Inactive</option>
    </select>
  </div>
  <div id="um-list-wrap"></div>
  <div id="um-pagination"></div>
</div>

<!-- Stats Cards, search/filter toolbar, and data table originally duplicated
     here were removed (FIX 2, security/refactor audit): #um-stats, #um-search,
     #um-pagination collided with the working versions above (#um-role-filter/
     #um-status-filter/#um-list-wrap feed the only render path, umRender()).
     This second table (#um-table/#um-tbody) was never populated by any
     function -- _umFiltered() is only called by umToggleAll(), and nothing
     ever writes rows into #um-tbody -- so it always showed "Loading users..."
     and its filters (#um-filter-role/status/dept, #um-sort), select-all
     checkbox, and bulk actions were inert. Removing it drops 7 duplicate ids
     (um-stats, um-search, um-pagination) plus dead, never-functional markup,
     with zero behavior change; the CSV import/export/print buttons and the
     Add/Edit/View user modals above and below this comment are unaffected
     and remain fully wired. -->

  <!-- Import hidden input -->
  <input type="file" id="um-import-input" accept=".csv" style="display:none;" data-x-change="umHandleImport(this)">
</div>


