<!-- MODAL: ADD / EDIT USER (v14) -->
<!-- ══════════════════════════════════════════════════════════════ -->
<div class="um-modal-overlay" id="um-modal"><input type="hidden" id="um-f-edit-id" value="0">
  <div class="um-modal-box">
    <!-- Header -->
    <div class="um-modal-hdr" style="background:linear-gradient(135deg,#0f3d26,#16a34a);color:#fff;">
      <div>
        <div style="font-size:17px;font-weight:900;" id="um-modal-title">➕ Add New User</div>
        <div style="font-size:11px;opacity:.8;margin-top:2px;">Fill all required fields *</div>
      </div>
      <button data-x-click="umCloseModal()" style="background:rgba(255,255,255,.2);border:none;color:#fff;width:30px;height:30px;border-radius:50%;cursor:pointer;font-size:18px;line-height:1;">✕</button>
    </div>

    <!-- Tabs -->
    <div style="display:flex;border-bottom:1px solid #e5e7eb;background:#f9fafb;flex-shrink:0;">
      <button class="um-tab-btn active" id="um-tab-info" data-x-click="umSwitchTab('info')"
        style="padding:10px 20px;font-size:12px;font-weight:700;border:none;background:none;cursor:pointer;border-bottom:2px solid #16a34a;color:#16a34a;">👤 Basic Info</button>
      <button class="um-tab-btn" id="um-tab-perms" data-x-click="umSwitchTab('perms')"
        style="padding:10px 20px;font-size:12px;font-weight:700;border:none;background:none;cursor:pointer;border-bottom:2px solid transparent;color:#9ca3af;">🔑 Permissions</button>
      <button class="um-tab-btn" id="um-tab-security" data-x-click="umSwitchTab('security')"
        style="padding:10px 20px;font-size:12px;font-weight:700;border:none;background:none;cursor:pointer;border-bottom:2px solid transparent;color:#9ca3af;">🛡 Security</button>
    </div>

    <div class="um-modal-body">
      <!-- Tab: Basic Info -->
      <div id="um-panel-info">
        <div class="um-field-group">
          <div class="um-field span2">
            <label class="um-label">Full Name *</label>
            <input class="um-input" id="um-f-name" type="text" placeholder="e.g. Mohammad Ayan Hossain"/>
          </div>
          <div class="um-field">
            <label class="um-label">Username *</label>
            <input class="um-input" id="um-f-username" type="text" placeholder="e.g. m.ayan" autocomplete="off"/>
            <span id="um-username-check" style="font-size:10px;margin-top:2px;"></span>
          </div>
          <div class="um-field">
            <label class="um-label">Employee ID</label>
            <input class="um-input" id="um-f-empid" type="text" placeholder="e.g. EMP-001"/>
          </div>
          <div class="um-field">
            <label class="um-label">Role *</label>
            <select class="um-input" id="um-f-role" data-x-change="umRoleAutofill()">
              <option value="">— Select Role —</option>
              <option>Owner</option><option>Admin</option><option>Manager</option><option>Staff</option><option>Operator</option><option>Viewer</option>
            </select>
          </div>
          <div class="um-field">
            <label class="um-label">Department</label>
            <select class="um-input" id="um-f-dept">
              <option value="">— Select —</option>
              <option>Administration</option><option>Finance</option><option>Operations</option>
              <option>Sales</option><option>HR</option><option>IT</option><option>Warehouse</option>
            </select>
          </div>
          <div class="um-field">
            <label class="um-label">Email</label>
            <input class="um-input" id="um-f-email" type="email" placeholder="user@ayanagro.com"/>
          </div>
          <div class="um-field">
            <label class="um-label">Phone</label>
            <input class="um-input" id="um-f-phone" type="tel" placeholder="01XXXXXXXXX"/>
          </div>
          <div class="um-field">
            <label class="um-label">Status</label>
            <select class="um-input" id="um-f-status">
              <option>Active</option><option>Inactive</option><option>Suspended</option>
            </select>
          </div>
          <div class="um-field span2">
            <label class="um-label">Notes / Remarks</label>
            <input class="um-input" id="um-f-notes" type="text" placeholder="Optional notes about this user"/>
          </div>
        </div>
      </div>

      <!-- Tab: Permissions -->
      <div id="um-panel-perms" style="display:none;">
        <div style="background:#f0fdf4;border:1px solid #bbf7d0;border-radius:8px;padding:10px 14px;margin-bottom:14px;font-size:12px;color:#15803d;">
          <strong>💡 Tip:</strong> Selecting a Role above auto-fills typical permissions. You can customise them here.
        </div>
        <div style="font-size:12px;font-weight:700;color:#374151;margin-bottom:8px;">Module Access</div>
        <div class="um-perms-grid" id="um-perms-grid">
          <!-- Filled by JS -->
        </div>
        <div style="font-size:12px;font-weight:700;color:#374151;margin:14px 0 8px;">Action Permissions</div>
        <div class="um-perms-grid" id="um-action-perms-grid">
          <!-- Filled by JS -->
        </div>
      </div>

      <!-- Tab: Security -->
      <div id="um-panel-security" style="display:none;">
        <div class="um-field-group">
          <div class="um-field">
            <label class="um-label">Password *</label>
            <div class="um-input-wrap">
              <input class="um-input" id="um-f-password" type="password" placeholder="Min 6 characters" data-x-input="umCheckStrength()"/>
              <span class="um-eye-btn" data-x-click="umTogglePwd('um-f-password',this)">👁</span>
            </div>
            <div id="um-pwd-strength-bar" class="um-str-bar" style="width:0%;background:#e5e7eb;"></div>
            <div id="um-pwd-strength-label" style="font-size:10px;color:#9ca3af;margin-top:2px;"></div>
          </div>
          <div class="um-field">
            <label class="um-label">Confirm Password *</label>
            <div class="um-input-wrap">
              <input class="um-input" id="um-f-confirm" type="password" placeholder="Re-enter password" data-x-input="umCheckMatch()"/>
              <span class="um-eye-btn" data-x-click="umTogglePwd('um-f-confirm',this)">👁</span>
            </div>
            <div id="um-pwd-match-label" style="font-size:10px;margin-top:2px;"></div>
          </div>
          <div class="um-field">
            <label class="um-label">PIN (4–6 digits, optional)</label>
            <input class="um-input" id="um-f-pin" type="password" maxlength="6" placeholder="Quick PIN for mobile"/>
          </div>
          <div class="um-field">
            <label class="um-label">Session Timeout</label>
            <select class="um-input" id="um-f-timeout">
              <option value="30">30 minutes</option>
              <option value="60">1 hour</option>
              <option value="120">2 hours</option>
              <option value="480">8 hours</option>
              <option value="0">No timeout</option>
            </select>
          </div>
          <div class="um-field span2">
            <label style="display:flex;align-items:center;gap:8px;cursor:pointer;">
              <input type="checkbox" id="um-f-force-pwd" style="accent-color:#16a34a;">
              <span class="um-label" style="text-transform:none;">Force password change on next login</span>
            </label>
          </div>
          <div class="um-field span2">
            <label style="display:flex;align-items:center;gap:8px;cursor:pointer;">
              <input type="checkbox" id="um-f-can-print" style="accent-color:#16a34a;" checked>
              <span class="um-label" style="text-transform:none;">Allow printing on company letterhead</span>
            </label>
          </div>
        </div>
      </div>
    </div>

    <!-- Footer -->
    <div class="um-modal-ftr">
      <button class="um-btn um-btn-gray" data-x-click="umCloseModal()">Cancel</button>
      <button class="um-btn um-btn-blue" data-x-click="umSaveAndPrint()">🖨️ Save &amp; Print Card</button>
      <button class="um-btn um-btn-green" data-x-click="umSaveUser()">💾 Save User</button>
    </div>
  </div>
</div>

