      <select id="audit-filter-action" data-x-change="renderAuditLog()" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;">
        <option value="">All Actions</option>
        <option value="CREATE">Create</option>
        <option value="UPDATE">Update</option>
