    <div>
      <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Date</label>
      <input id="audit-filter-date" type="date" data-x-change="renderAuditLog()" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;"/>
    </div>
    <div>
      <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Search</label>
      <input id="audit-filter-search" type="text" placeholder="Search logs..." data-x-input="renderAuditLog()" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;width:180px;"/>
    </div>
    <button data-x-click="renderAuditLog()" style="padding:8px 16px;background:#16a34a;color:#fff;border:none;border-radius:7px;font-size:12px;font-weight:700;cursor:pointer;">🔄 Refresh</button>
  </div>

  <!-- Stats Row -->
