  <!-- Row 2: Top Customers Bar + Product Sales -->
  <div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:14px;">
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:16px;">
      <div style="font-size:13px;font-weight:800;color:#0f3d26;margin-bottom:12px;">🏆 Top Customers by Sales</div>
      <canvas id="chart-topcust" height="200"></canvas>
