    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:16px;">
      <div style="font-size:13px;font-weight:800;color:#0f3d26;margin-bottom:12px;">📦 Product Sales Distribution</div>
      <canvas id="chart-products" height="200"></canvas>
    </div>
  </div>

  <!-- Row 3: Cash Flow Line -->
  <div style="background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:16px;margin-bottom:14px;">
    <div style="font-size:13px;font-weight:800;color:#0f3d26;margin-bottom:12px;">💵 Cumulative Cash Flow</div>
    <canvas id="chart-cashflow" height="120"></canvas>
  </div>

  <!-- Row 4: Bank Balance Doughnut + Expense Breakdown -->
