<!-- PAGE: VAT MANAGEMENT -->
<!-- ══════════════════════════════════════════════════════════════ -->
<div id="pg-vatmanagement" class="page" style="display:none">
  <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:18px;">
    <div>
      <h2 style="font-size:20px;font-weight:800;color:#0f3d26;margin:0;">🧾 VAT Management</h2>
      <p style="font-size:12px;color:#6b7280;margin:2px 0 0;">Track VAT on sales & purchases, compute payable/refundable</p>
    </div>
    <div style="display:flex;gap:8px;">
      <button data-x-click="renderVATReport()" style="padding:8px 16px;background:#16a34a;color:#fff;border:none;border-radius:7px;font-size:12px;font-weight:700;cursor:pointer;">🔄 Refresh</button>
      <button data-x-click="printVATReport()" style="padding:8px 16px;background:#f3f4f6;border:1px solid #d1d5db;border-radius:7px;font-size:12px;cursor:pointer;">🖨️ Print</button>
    </div>
  </div>

  <!-- VAT Rate Settings -->
  <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:14px;margin-bottom:14px;display:flex;gap:16px;align-items:flex-end;flex-wrap:wrap;">
    <div>
      <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">VAT Rate on Sales (%)</label>
      <input id="vat-rate-sales" type="number" value="15" min="0" max="100" step="0.5" data-x-change="renderVATReport()" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:13px;width:100px;font-weight:700;"/>
    </div>
    <div>
      <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">VAT Rate on Purchases (%)</label>
      <input id="vat-rate-purch" type="number" value="15" min="0" max="100" step="0.5" data-x-change="renderVATReport()" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:13px;width:100px;font-weight:700;"/>
    </div>
    <div>
      <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Period</label>
      <select id="vat-period-filter" data-x-change="renderVATReport()" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;">
        <option value="all">All Time</option>
        <option value="thismonth">This Month</option>
        <option value="lastmonth">Last Month</option>
        <option value="thisyear">This Year</option>
      </select>
    </div>
  </div>

  <!-- VAT Summary Cards -->
  <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:14px;" id="vat-summary-cards"></div>

  <!-- VAT Table -->
