<!-- PAGE: DATA MANAGEMENT (Import / Export) -->
<!-- ══════════════════════════════════════════════════════════════ -->
<div id="pg-datamgmt" class="page" style="display:none">
  <div style="margin-bottom:18px;">
    <h2 style="font-size:20px;font-weight:800;color:#0f3d26;margin:0;">📂 Data Management</h2>
    <p style="font-size:12px;color:#6b7280;margin:2px 0 0;">Import, export, backup and restore your business data</p>
  </div>

  <div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:14px;">

    <!-- Export Section -->
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:18px;">
      <div style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:14px;">📥 Export Data</div>
      <div style="display:flex;flex-direction:column;gap:10px;">
        <button data-x-click="exportCSV('transactions')" style="padding:11px 16px;background:linear-gradient(135deg,#16a34a,#15803d);color:#fff;border:none;border-radius:8px;font-size:13px;font-weight:700;cursor:pointer;text-align:left;">
          📊 Export Transactions (CSV)
        </button>
        <button data-x-click="exportCSV('customers')" style="padding:11px 16px;background:linear-gradient(135deg,#2563eb,#1d4ed8);color:#fff;border:none;border-radius:8px;font-size:13px;font-weight:700;cursor:pointer;text-align:left;">
          👥 Export Customers (CSV)
        </button>
        <button data-x-click="exportCSV('partners')" style="padding:11px 16px;background:linear-gradient(135deg,#7c3aed,#6d28d9);color:#fff;border:none;border-radius:8px;font-size:13px;font-weight:700;cursor:pointer;text-align:left;">
          🤝 Export Partners (CSV)
        </button>
        <button data-x-click="exportCSV('banks')" style="padding:11px 16px;background:linear-gradient(135deg,#0891b2,#0e7490);color:#fff;border:none;border-radius:8px;font-size:13px;font-weight:700;cursor:pointer;text-align:left;">
          🏦 Export Bank Accounts (CSV)
        </button>
        <button data-x-click="exportFullBackup()" style="padding:11px 16px;background:linear-gradient(135deg,#0f3d26,#16a34a);color:#fff;border:none;border-radius:8px;font-size:13px;font-weight:700;cursor:pointer;text-align:left;">
          💾 Full Backup (JSON)
        </button>
      </div>
    </div>

    <!-- Import Section -->
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:18px;">
      <div style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:14px;">📤 Import Data</div>
      <div style="background:#f9fafb;border:2px dashed #d1d5db;border-radius:10px;padding:20px;text-align:center;margin-bottom:12px;" id="import-drop-zone"
        ondragover="event.preventDefault();this.style.borderColor='#16a34a';"
        ondragleave="this.style.borderColor='#d1d5db';"
        ondrop="handleImportDrop(event)">
        <div style="font-size:32px;margin-bottom:8px;">📁</div>
        <div style="font-size:13px;font-weight:700;color:#374151;margin-bottom:4px;">Drop CSV or JSON file here</div>
        <div style="font-size:11px;color:#6b7280;margin-bottom:12px;">or click to browse</div>
        <input type="file" id="import-file-input" accept=".csv,.json" style="display:none;" data-x-change="xImportFileChange(this)"/>
        <button data-x-click="document.getElementById('import-file-input').click()" style="padding:8px 20px;background:#16a34a;color:#fff;border:none;border-radius:6px;font-size:12px;font-weight:700;cursor:pointer;">Browse File</button>
      </div>
      <div style="font-size:11px;color:#6b7280;margin-bottom:10px;">
        <strong>CSV Format:</strong> Date, Type, Party, Amount, Product, Mode, Account, Notes
      </div>
      <button data-x-click="downloadImportTemplate()" style="width:100%;padding:9px;background:#f3f4f6;border:1px solid #d1d5db;border-radius:7px;font-size:12px;cursor:pointer;font-weight:600;">
        📋 Download Import Template (CSV)
      </button>
    </div>
  </div>

  <!-- Import Preview -->
  <div id="import-preview-wrap" style="display:none;background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:16px;margin-bottom:14px;">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;">
      <div style="font-size:14px;font-weight:800;color:#0f3d26;">📋 Import Preview</div>
      <div style="display:flex;gap:8px;">
        <button data-x-click="confirmImport()" style="padding:8px 18px;background:#16a34a;color:#fff;border:none;border-radius:7px;font-size:12px;font-weight:700;cursor:pointer;">✅ Confirm Import</button>
        <button data-x-click="cancelImport()" style="padding:8px 14px;background:#fef2f2;border:1px solid #fecaca;color:#dc2626;border-radius:7px;font-size:12px;cursor:pointer;">✕ Cancel</button>
      </div>
    </div>
    <div id="import-preview-body" style="overflow-x:auto;max-height:300px;overflow-y:auto;"></div>
  </div>

  <!-- Database Stats -->
  <div style="background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:16px;">
    <div style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:12px;">📊 Database Statistics</div>
    <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:10px;" id="db-stats"></div>
    <div style="margin-top:14px;padding-top:14px;border-top:1px solid #e5e7eb;display:flex;gap:10px;">
      <button data-x-click="optimizeDB()" style="padding:8px 16px;background:#f3f4f6;border:1px solid #d1d5db;border-radius:7px;font-size:12px;cursor:pointer;">⚡ Optimize DB</button>
      <button data-x-click="clearAllData()" style="padding:8px 16px;background:#fef2f2;border:1px solid #fecaca;color:#dc2626;border-radius:7px;font-size:12px;cursor:pointer;">🗑️ Clear All Data</button>
    </div>
  </div>
</div>


