<!-- MODAL: Add Employee -- duplicate copy removed (FIX 2, security/refactor
     audit). #mAddEmployee had zero call sites anywhere in the file (nothing
     ever calls openModal('mAddEmployee')), unlike the neighboring #mPaySalary
     modal which is genuinely wired to a live "Pay" button. The live employee
     form remains #employee-modal (opened by openAddEmployeeModal()), which
     both this dead modal and the live one fed into the same saveEmployee().
     Removes 6 duplicate ids (emp-name, emp-role, emp-salary, emp-join,
     emp-phone; emp-status/emp-notes were unique to this dead copy and are
     simply gone) with zero behavior change. -->

<!-- MODAL: Pay Salary -->
<div id="mPaySalary" class="overlay">
  <div class="modal" style="max-width:480px;">
    <div class="modal-header" style="background:linear-gradient(135deg,#0f3d26,#16a34a);color:#fff;padding:14px 18px;border-radius:10px 10px 0 0;display:flex;justify-content:space-between;align-items:center;">
      <h3 style="margin:0;font-size:16px;font-weight:800;">💰 Pay Salary</h3>
      <button data-x-click="closeModal('mPaySalary')" style="background:rgba(255,255,255,.2);border:none;color:#fff;width:28px;height:28px;border-radius:50%;cursor:pointer;font-size:16px;">✕</button>
    </div>
    <div style="padding:16px 18px;">
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;">
        <div class="fg"><label class="lbl">Employee</label>
          <select class="fc" id="pay-emp" data-x-change="fillSalaryAmount()">
            <option value="">-- Select --</option>
          </select>
        </div>
        <div class="fg"><label class="lbl">Month</label><input class="fc" id="pay-month" type="month"/></div>
        <div class="fg"><label class="lbl">Basic Salary (৳)</label><input class="fc" id="pay-basic" type="number" placeholder="0"/></div>
        <div class="fg"><label class="lbl">Bonus (৳)</label><input class="fc" id="pay-bonus" type="number" placeholder="0" value="0"/></div>
        <div class="fg"><label class="lbl">Deduction (৳)</label><input class="fc" id="pay-deduct" type="number" placeholder="0" value="0"/></div>
        <div class="fg"><label class="lbl">Net Pay (৳)</label><input class="fc" id="pay-net" type="number" readonly style="background:#f9fafb;font-weight:800;color:#16a34a;"/></div>
      </div>
      <div id="pay-acc-widget-modal" style="grid-column:1/-1;margin-top:6px;border-top:2px dashed #16a34a;padding-top:10px;"></div>
      <div style="display:flex;gap:10px;justify-content:flex-end;margin-top:16px;">
        <button data-x-click="closeModal('mPaySalary')" style="padding:9px 20px;background:#f3f4f6;border:1px solid #d1d5db;border-radius:7px;font-size:13px;cursor:pointer;">Cancel</button>
        <button data-x-click="processSalaryPayment()" style="padding:9px 24px;background:linear-gradient(135deg,#16a34a,#15803d);color:#fff;border:none;border-radius:7px;font-size:13px;font-weight:700;cursor:pointer;">✅ Process Payment</button>
      </div>
    </div>
  </div>
</div>

<!-- Supplier quick-pay modal — same account(+split) widget as New Transaction
     and Salary Payment, saved through the same _executeSaveTx() pipeline so
     it actually moves a real bank balance (see _supQuickPay() bugfix note). -->
<div id="mSupQuickPay" class="overlay">
  <div class="modal" style="max-width:420px;">
    <div class="modal-header" style="background:linear-gradient(135deg,#4c1d95,#7c3aed);color:#fff;padding:14px 18px;border-radius:10px 10px 0 0;display:flex;justify-content:space-between;align-items:center;">
      <h3 style="margin:0;font-size:16px;font-weight:800;">💳 Pay Supplier</h3>
      <button data-x-click="closeModal('mSupQuickPay')" style="background:rgba(255,255,255,.2);border:none;color:#fff;width:28px;height:28px;border-radius:50%;cursor:pointer;font-size:16px;">✕</button>
    </div>
    <div style="padding:16px 18px;">
      <div id="sqp-supplier-info" style="margin-bottom:12px;font-size:13px;color:#374151;"></div>
      <div class="fg"><label class="lbl">Amount (৳)</label><input class="fc" id="sqp-amt" type="number" min="0" data-x-input="_sqpRecalc()"/></div>
      <div class="fg"><label class="lbl">Date</label><input class="fc" id="sqp-date" type="date"/></div>
      <div id="sqp-acc-widget" style="margin-top:8px;border-top:2px dashed #7c3aed;padding-top:10px;"></div>
      <div class="fg" style="margin-top:8px;"><label class="lbl">Note</label><input class="fc" id="sqp-note" type="text" placeholder="Optional"/></div>
      <div style="display:flex;gap:10px;justify-content:flex-end;margin-top:16px;">
        <button data-x-click="closeModal('mSupQuickPay')" style="padding:9px 20px;background:#f3f4f6;border:1px solid #d1d5db;border-radius:7px;font-size:13px;cursor:pointer;">Cancel</button>
        <button data-x-click="_supQuickPaySubmit()" style="padding:9px 24px;background:linear-gradient(135deg,#7c3aed,#4c1d95);color:#fff;border:none;border-radius:7px;font-size:13px;font-weight:700;cursor:pointer;">✅ Pay</button>
      </div>
    </div>
  </div>
</div>


