<div id="pg-profitdist" class="page" style="display:none">
  <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:18px;">
    <div>
      <h2 style="font-size:20px;font-weight:800;color:#0f3d26;margin:0;">🏆 Profit Distribution</h2>
      <p style="font-size:12px;color:#6b7280;margin:2px 0 0;">Distribute net profit among partners by share percentage</p>
    </div>
    <button data-x-click="printProfitDist()" style="background:#f3f4f6;border:1px solid #d1d5db;padding:8px 14px;border-radius:7px;font-size:12px;cursor:pointer;">🖨️ Print</button>
  </div>

  <!-- Period Filter -->
  <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:14px;margin-bottom:14px;display:flex;gap:12px;flex-wrap:wrap;align-items:flex-end;">
    <div>
      <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Period</label>
      <select id="pd-period" data-x-change="renderProfitDist()" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;">
        <option value="all">All Time</option>
        <option value="year">This Year</option>
        <option value="month">This Month</option>
        <option value="custom">Custom Range</option>
      </select>
    </div>
    <div id="pd-custom-range" style="display:none;gap:10px;display:flex;">
      <div>
        <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">From</label>
        <input id="pd-from" type="date" data-x-change="renderProfitDist()" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;"/>
      </div>
      <div>
        <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">To</label>
        <input id="pd-to" type="date" data-x-change="renderProfitDist()" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;"/>
      </div>
    </div>
    <button data-x-click="renderProfitDist()" style="padding:8px 16px;background:#16a34a;color:#fff;border:none;border-radius:7px;font-size:12px;font-weight:700;cursor:pointer;">🔄 Calculate</button>
  </div>

  <!-- Summary -->
  <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:14px;" id="pd-summary"></div>

  <!-- Partner Distribution Table -->
  <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
    <div id="pd-table"></div>
  </div>
</div>


