<!-- PAGE: STOCK ALERTS -->
<!-- ══════════════════════════════════════════════════════════════ -->
<div id="pg-stockalerts" class="page" style="display:none">
  <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:18px;">
    <div>
      <h2 style="font-size:20px;font-weight:800;color:#0f3d26;margin:0;">🔔 Stock Alerts</h2>
      <p style="font-size:12px;color:#6b7280;margin:2px 0 0;">Low stock, out-of-stock and overstock warnings</p>
    </div>
    <button data-x-click="renderStockAlerts()" style="background:#16a34a;color:#fff;border:none;padding:8px 16px;border-radius:7px;font-size:12px;font-weight:700;cursor:pointer;">🔄 Refresh</button>
  </div>

  <!-- Alert KPIs -->
  <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:14px;" id="sa-kpis"></div>

  <!-- Alert Lists -->
  <div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;">
    <div style="background:#fff;border:2px solid #fecaca;border-radius:10px;overflow:hidden;">
      <div style="padding:10px 14px;background:linear-gradient(90deg,#dc2626,#b91c1c);color:#fff;font-size:12px;font-weight:700;">🚨 Out of Stock</div>
      <div id="sa-outofstock" style="max-height:300px;overflow-y:auto;padding:10px;"></div>
    </div>
    <div style="background:#fff;border:2px solid #fde68a;border-radius:10px;overflow:hidden;">
      <div style="padding:10px 14px;background:linear-gradient(90deg,#d97706,#b45309);color:#fff;font-size:12px;font-weight:700;">⚠️ Low Stock</div>
      <div id="sa-lowstock" style="max-height:300px;overflow-y:auto;padding:10px;"></div>
    </div>
  </div>

  <!-- All Products Stock Status -->
  <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;margin-top:14px;">
    <div style="padding:10px 14px;background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;font-size:12px;font-weight:700;">📦 All Products Stock Status</div>
    <div id="sa-all" style="overflow-x:auto;"></div>
  </div>
</div>


