<!-- PAGE: OPENING BALANCE -->
<!-- ══════════════════════════════════════════════════════════════ -->
<div id="pg-openingbalance" class="page" style="display:none">
  <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:18px;">
    <div>
      <h2 style="font-size:20px;font-weight:800;color:#0f3d26;margin:0;">🏁 Opening Balance</h2>
      <p style="font-size:12px;color:#6b7280;margin:2px 0 0;">Set initial balances for customers, banks, partners and assets</p>
    </div>
    <button data-x-click="saveOpeningBalances()" style="background:linear-gradient(135deg,#16a34a,#15803d);color:#fff;border:none;padding:9px 18px;border-radius:8px;font-size:13px;font-weight:700;cursor:pointer;">💾 Save All</button>
  </div>

  <!-- Tabs -->
  <div style="display:flex;gap:0;margin-bottom:14px;background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
    <button data-x-click="setObTab('customers')" id="obtab-customers" style="flex:1;padding:10px;font-size:12px;font-weight:700;border:none;cursor:pointer;background:linear-gradient(135deg,#16a34a,#15803d);color:#fff;">👥 Customers</button>
    <button data-x-click="setObTab('banks')" id="obtab-banks" style="flex:1;padding:10px;font-size:12px;font-weight:700;border:none;cursor:pointer;background:#f9fafb;color:#374151;">🏦 Banks</button>
    <button data-x-click="setObTab('partners')" id="obtab-partners" style="flex:1;padding:10px;font-size:12px;font-weight:700;border:none;cursor:pointer;background:#f9fafb;color:#374151;">🤝 Partners</button>
    <button data-x-click="setObTab('assets')" id="obtab-assets" style="flex:1;padding:10px;font-size:12px;font-weight:700;border:none;cursor:pointer;background:#f9fafb;color:#374151;">🏗️ Fixed Assets</button>
    <button data-x-click="setObTab('suppliers')" id="obtab-suppliers" style="flex:1;padding:10px;font-size:12px;font-weight:700;border:none;cursor:pointer;background:#f9fafb;color:#374151;">🚚 Suppliers</button>
  </div>

  <div id="ob-tab-content"></div>
</div>


