<!-- PAGE: DELIVERY CHALLAN -->
<div id="pg-deliverychallan" class="page" style="display:none">
  <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:18px;">
    <div>
      <h2 style="font-size:20px;font-weight:800;color:#0f3d26;margin:0;">🚚 Delivery Challan</h2>
      <p style="font-size:12px;color:#6b7280;margin:2px 0 0;">Generate & print delivery challans for shipments</p>
    </div>
    <button data-x-click="newChallan()" style="background:#16a34a;color:#fff;border:none;padding:8px 16px;border-radius:7px;font-size:12px;font-weight:700;cursor:pointer;">+ New Challan</button>
  </div>

  <!-- Challan Form -->
  <div id="challan-form-area" style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:18px;margin-bottom:14px;display:none;">
    <h3 style="font-size:14px;font-weight:700;color:#0f3d26;margin:0 0 14px;">📋 New Delivery Challan</h3>
    <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:12px;">
      <div>
        <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Challan No</label>
        <input id="chfa-no" type="text" placeholder="Auto-generated" readonly style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;width:100%;background:#f9fafb;"/>
      </div>
      <div>
        <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Date</label>
        <input id="chfa-date" type="date" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;width:100%;"/>
      </div>
      <div>
        <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Party Name</label>
        <select id="chfa-party" data-x-change="onPartyNameFieldChanged('chfa-party','chfa-bankaccount','chfa-bankaccount-custom')" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;width:100%;"><option value="">-- Select Party --</option></select>
      </div>
      <div>
        <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Product</label>
        <select id="chfa-product" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;width:100%;"><option value="">-- Select Product --</option></select>
      </div>
      <div>
        <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Quantity</label>
        <input id="chfa-qty" type="number" placeholder="0" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;width:100%;"/>
      </div>
      <div>
        <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Unit</label>
        <select id="chfa-unit" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;width:100%;">
          <option>KG</option><option>Liter</option><option>Ton</option><option>Bag</option><option>Piece</option>
        </select>
      </div>
      <div>
        <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Truck/Vehicle No</label>
        <input id="chfa-truck" type="text" placeholder="e.g. DHA-1234" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;width:100%;"/>
      </div>
      <div>
        <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Bank Account (Payment)</label>
        <select id="chfa-bankaccount" data-x-change="onPartyBankPickerChange('chfa-bankaccount','chfa-bankaccount-custom')" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;width:100%;"><option value="">-- Select Bank Account --</option></select>
        <input id="chfa-bankaccount-custom" type="text" placeholder="Type bank name, account no., branch..." style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;width:100%;margin-top:6px;box-sizing:border-box;display:none;"/>
      </div>
      <div>
        <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Driver Name</label>
        <input id="chfa-driver" type="text" placeholder="Driver name" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;width:100%;"/>
      </div>
      <div>
        <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Destination</label>
        <select id="ch-dest" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;width:100%;"><option value="">-- Select --</option></select>
      </div>
    </div>
    <div style="margin-bottom:12px;">
      <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Remarks</label>
      <textarea id="ch-remarks" rows="2" placeholder="Additional notes..." style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;width:100%;resize:vertical;"></textarea>
    </div>
    <div style="display:flex;gap:10px;">
      <button data-x-click="saveChallanFromArea()" style="padding:8px 20px;background:#16a34a;color:#fff;border:none;border-radius:7px;font-size:12px;font-weight:700;cursor:pointer;">💾 Save Challan</button>
      <button data-x-click="closeModalById('challan-form-area')" style="padding:8px 16px;background:#f3f4f6;border:1px solid #d1d5db;border-radius:7px;font-size:12px;cursor:pointer;">Cancel</button>
    </div>
  </div>

  <!-- REMOVED (2026-08-27, workflow audit): the "Challan List" box that
       used to sit here was permanently empty — it was only ever populated
       by the now-removed renderChallan(), which nothing called. The real
       challan list is #dc-body, injected further down by the structure
       normalizer above and rendered by renderDeliveryChallan(). -->
</div>


<!-- PAGE: INVOICE GENERATOR -->
<div id="pg-invoicegen" class="page" style="display:none">
  <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:18px;">
    <div>
      <h2 style="font-size:20px;font-weight:800;color:#0f3d26;margin:0;">🧾 Invoice Generator</h2>
      <p style="font-size:12px;color:#6b7280;margin:2px 0 0;">Create & print professional invoices with letterhead</p>
    </div>
    <button data-x-click="newInvoice()" style="background:#16a34a;color:#fff;border:none;padding:8px 16px;border-radius:7px;font-size:12px;font-weight:700;cursor:pointer;">+ New Invoice</button>
  </div>

  <!-- Invoice Form -->
  <div id="inv-form-area" style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:18px;margin-bottom:14px;display:none;">
    <h3 style="font-size:14px;font-weight:700;color:#0f3d26;margin:0 0 14px;">📄 Create Invoice</h3>
    <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:12px;">
      <div>
        <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Invoice No</label>
        <input id="inv-no" type="text" readonly style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;width:100%;background:#f9fafb;"/>
      </div>
      <div>
        <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Date</label>
        <input id="inv-date" type="date" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;width:100%;"/>
      </div>
      <div>
        <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Due Date</label>
        <input id="inv-due" type="date" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;width:100%;"/>
      </div>
      <div>
        <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Bill To (Party)</label>
        <select id="inv-party" data-x-change="fillInvParty()" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;width:100%;"><option value="">-- Select Party --</option></select>
      </div>
      <div>
        <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Product</label>
        <select id="inv-product" data-x-change="fillInvRate()" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;width:100%;"><option value="">-- Select Product --</option></select>
      </div>
      <div>
        <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Quantity</label>
        <input id="inv-qty" type="number" placeholder="0" data-x-input="calcInvTotal()" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;width:100%;"/>
      </div>
      <div>
        <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Unit</label>
        <select id="inv-unit" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;width:100%;">
          <option>KG</option><option>Liter</option><option>Ton</option><option>Bag</option><option>Piece</option>
        </select>
      </div>
      <div>
        <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Rate (৳)</label>
        <input id="inv-rate" type="number" placeholder="0.00" data-x-input="calcInvTotal()" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;width:100%;"/>
      </div>
      <div>
        <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Discount (৳)</label>
        <input id="inv-disc" type="number" value="0" data-x-input="calcInvTotal()" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;width:100%;"/>
      </div>
      <div>
        <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">VAT % (optional)</label>
        <input id="inv-vat" type="number" value="0" data-x-input="calcInvTotal()" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;width:100%;"/>
      </div>
      <div>
        <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Total Amount (৳)</label>
        <input id="inv-total" type="text" readonly style="padding:7px 12px;border:1px solid #16a34a;border-radius:6px;font-size:13px;font-weight:800;color:#0f3d26;width:100%;background:#f0fdf4;"/>
      </div>
      <div>
        <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Payment Mode</label>
        <select id="inv-mode" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;width:100%;">
          <option>Cash</option><option>Bank</option><option>Bkash</option><option>Cheque</option><option>Credit</option>
        </select>
      </div>
    </div>
    <!-- SECTION 4: FINANCIAL SALES DEDUCTIONS & ADJUSTMENTS (2026-09-13: added
         to the Invoice Generator to match the New Transaction modal) -->
    <div style="border:1px solid #e2e8f0;border-radius:.5rem;overflow:hidden;margin-bottom:12px;">
      <div style="background:#f8fafc;padding:8px 12px;font-size:12px;font-weight:700;color:#374151;display:flex;align-items:center;gap:6px;border-bottom:1px solid #e2e8f0;"><i class="fa-solid fa-calculator"></i> 4. Financial Sales Deductions &amp; Adjustments</div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;padding:12px;">
        <div style="display:flex;flex-direction:column;gap:8px;">
          <div>
            <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Bag Deduction Rate (৳/KG)</label>
            <input id="inv-bag-deduct-rate" type="number" step="any" min="0" value="0" data-x-input="calcInvTotal()" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;width:100%;"/>
          </div>
          <div>
            <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Unrealized / Non-Realization Adjustment (৳)</label>
            <input id="inv-unrealized" type="number" step="any" min="0" value="0" data-x-input="calcInvTotal()" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;width:100%;"/>
          </div>
          <div>
            <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Other Deduction — Name</label>
            <input id="inv-custom-deduct-name" type="text" value="Other Deduction" data-x-input="calcInvTotal()" style="padding:7px 12px;border:1px dashed #d1d5db;border-radius:6px;font-size:12px;width:100%;"/>
          </div>
          <div>
            <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Other Deduction — Amount (৳)</label>
            <input id="inv-custom-deduct-val" type="number" step="any" min="0" value="0" data-x-input="calcInvTotal()" style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;width:100%;"/>
          </div>
        </div>
        <div style="background:#f9fafb;border:1px solid #e5e7eb;border-radius:6px;padding:10px 12px;display:flex;flex-direction:column;gap:8px;font-size:12px;">
          <div style="display:flex;justify-content:space-between;"><span>Bag Deduction Amount</span><span id="inv-bag-deduct-amt" style="font-weight:700;">৳0.00</span></div>
          <div style="display:flex;justify-content:space-between;"><span>Unrealized Adjustment</span><span id="inv-unrealized-amt" style="font-weight:700;">৳0.00</span></div>
          <div style="display:flex;justify-content:space-between;"><span id="inv-custom-deduct-label">Other Deduction</span><span id="inv-custom-deduct-amt" style="font-weight:700;">৳0.00</span></div>
          <div style="display:flex;justify-content:space-between;border-top:1px solid #e5e7eb;padding-top:6px;"><span style="font-weight:700;">Total Deductions</span><span id="inv-total-deduct" style="font-weight:800;color:#dc2626;">৳0.00</span></div>
          <div style="display:flex;justify-content:space-between;font-size:13px;"><span style="font-weight:800;">Net Sales Value (after deductions + VAT)</span><span id="inv-net-amt" style="font-weight:900;color:#0f3d26;">৳0.00</span></div>
        </div>
      </div>
    </div>

    <div style="margin-bottom:12px;">
      <label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Notes</label>
      <textarea id="inv-notes" rows="2" placeholder="Terms, conditions, or notes..." style="padding:7px 12px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;width:100%;resize:vertical;"></textarea>
    </div>
    <div style="display:flex;gap:10px;">
      <button data-x-click="saveInvoice()" style="padding:8px 20px;background:#16a34a;color:#fff;border:none;border-radius:7px;font-size:12px;font-weight:700;cursor:pointer;">💾 Save Invoice</button>
      <button data-x-click="closeModalById('inv-form-area')" style="padding:8px 16px;background:#f3f4f6;border:1px solid #d1d5db;border-radius:7px;font-size:12px;cursor:pointer;">Cancel</button>
    </div>
  </div>

  <!-- Invoice List -->
  <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
    <div id="inv-list"></div>
  </div>
</div>


