<script nonce="<?php echo $cspNonceAttr; ?>">

// ============================================================
// MISSING RENDER FUNCTIONS

function renderAnalytics(){
  const el=document.getElementById('pg-analytics');
  if(!el)return;
  const txs=DB.tx||[];
  const now=new Date();
  const thisYear=now.getFullYear();
  const lastYear=thisYear-1;

  // Monthly breakdown for current year
  const monthlyData={};
  for(let m=1;m<=12;m++){
    const key=`${thisYear}-${String(m).padStart(2,'0')}`;
    monthlyData[key]={sales:0,purch:0,exp:0,profit:0};
  }
  txs.forEach(t=>{
    const m=(t.date||'').substring(0,7);
    if(!monthlyData[m]) return;
    const amt=t.amt||t.amount||0;
    if(['Sale','Warehouse Sale','Other Income'].includes(t.type)) monthlyData[m].sales+=amt;
    else if(isCogsTx(t)) monthlyData[m].purch+=amt;
    else monthlyData[m].exp+=amt;
  });
  Object.entries(monthlyData).forEach(([mk,m])=>{
    const mTxs=(DB.tx||[]).filter(t=>t.date&&t.date.startsWith(mk));
    m.profit=m.sales-window.computeCOGS(mTxs)-m.exp;
  });

  const months=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const totalSales=Object.values(monthlyData).reduce((s,m)=>s+m.sales,0);
  const totalPurch=Object.values(monthlyData).reduce((s,m)=>s+m.purch,0);
  const totalExp=Object.values(monthlyData).reduce((s,m)=>s+m.exp,0);
  const totalProfit=Object.values(monthlyData).reduce((s,m)=>s+m.profit,0);
  const bestMonth=Object.entries(monthlyData).sort((a,b)=>b[1].profit-a[1].profit)[0];
  const maxSales=Math.max(...Object.values(monthlyData).map(m=>m.sales))||1;

  // Top products
  const prodMap={};
  txs.filter(t=>isRevenueTx(t)&&t.product).forEach(t=>{
    if(!prodMap[t.product]) prodMap[t.product]={qty:0,total:0,count:0};
    prodMap[t.product].qty+=parseFloat(t.qty||0);
    prodMap[t.product].total+=txAmt(t);
    prodMap[t.product].count++;
  });
  const topProds=Object.entries(prodMap).sort((a,b)=>b[1].total-a[1].total).slice(0,5);

  // Customer analysis
  const custMap={};
  txs.filter(t=>isRevenueTx(t)&&t.party).forEach(t=>{
    if(!custMap[t.party]) custMap[t.party]={total:0,count:0};
    custMap[t.party].total+=txAmt(t);
    custMap[t.party].count++;
  });
  const topCusts=Object.entries(custMap).sort((a,b)=>b[1].total-a[1].total).slice(0,5);

  el.innerHTML=`<div class="page-header"><h2>📈 Advanced Analytics</h2><p>${thisYear} business performance analysis</p></div>

  <!-- KPI Summary -->
  <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:14px;margin-bottom:20px;">
    <div class="kpi-card" data-x-click="nav('txsheet')" style="cursor:pointer;background:linear-gradient(135deg,#065f46,#059669);color:#fff;border:none;" title="Click to open Transaction Sheet">
      <div style="font-size:10px;opacity:.8;font-weight:700;text-transform:uppercase;">Total Revenue ${thisYear} →</div>
      <div style="font-size:24px;font-weight:900;margin-top:6px;">${f(totalSales)}</div>
    </div>
    <div class="kpi-card" data-x-click="nav('txsheet')" style="cursor:pointer;background:linear-gradient(135deg,#1d4ed8,#2563eb);color:#fff;border:none;" title="Click to open Transaction Sheet">
      <div style="font-size:10px;opacity:.8;font-weight:700;text-transform:uppercase;">Total Purchases →</div>
      <div style="font-size:24px;font-weight:900;margin-top:6px;">${f(totalPurch)}</div>
    </div>
    <div class="kpi-card" data-x-click="nav('txsheet')" style="cursor:pointer;background:linear-gradient(135deg,#dc2626,#ef4444);color:#fff;border:none;" title="Click to open Transaction Sheet">
      <div style="font-size:10px;opacity:.8;font-weight:700;text-transform:uppercase;">Total Expenses →</div>
      <div style="font-size:24px;font-weight:900;margin-top:6px;">${f(totalExp)}</div>
    </div>
    <div class="kpi-card" data-x-click="nav('profitloss')" style="cursor:pointer;background:linear-gradient(135deg,${totalProfit>=0?'#7c3aed,#8b5cf6':'#dc2626,#ef4444'});color:#fff;border:none;" title="Click to open Profit & Loss">
      <div style="font-size:10px;opacity:.8;font-weight:700;text-transform:uppercase;">Net Profit →</div>
      <div style="font-size:24px;font-weight:900;margin-top:6px;">${f(totalProfit)}</div>
    </div>
    <div class="kpi-card" data-x-click="${bestMonth?`openPLDrill('${bestMonth[0]}-01','${bestMonth[0]}-31')`:''}" style="cursor:${bestMonth?'pointer':'default'};background:linear-gradient(135deg,#b45309,#d97706);color:#fff;border:none;" title="${bestMonth?'Click to see this month\'s transactions':''}">
      <div style="font-size:10px;opacity:.8;font-weight:700;text-transform:uppercase;">Best Month${bestMonth?' →':''}</div>
      <div style="font-size:18px;font-weight:900;margin-top:6px;">${bestMonth?months[parseInt(bestMonth[0].split('-')[1])-1]+' '+bestMonth[0].split('-')[0]:'—'}</div>
      <div style="font-size:11px;opacity:.8;">${bestMonth?f(bestMonth[1].profit):''}</div>
    </div>
    <div class="kpi-card" data-x-click="nav('profitloss')" style="cursor:pointer;background:linear-gradient(135deg,#0891b2,#06b6d4);color:#fff;border:none;" title="Click to open Profit & Loss">
      <div style="font-size:10px;opacity:.8;font-weight:700;text-transform:uppercase;">Profit Margin →</div>
      <div style="font-size:24px;font-weight:900;margin-top:6px;">${totalSales>0?(totalProfit/totalSales*100).toFixed(1)+'%':'—'}</div>
    </div>
  </div>

  <!-- Monthly Bar Chart -->
  <div class="card" style="margin-bottom:16px;">
    <h3 style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:16px;">📊 Monthly Sales Trend — ${thisYear}</h3>
    <div style="display:flex;gap:6px;align-items:flex-end;height:140px;padding:0 4px;">
      ${Object.entries(monthlyData).map(([key,m],idx)=>{
        const h=Math.round(m.sales/maxSales*120)||2;
        const ph=Math.round(m.purch/maxSales*120)||2;
        const isProfit=m.profit>=0;
        return `<div style="flex:1;display:flex;flex-direction:column;align-items:center;gap:2px;">
          <div style="font-size:8px;color:#6b7280;white-space:nowrap;">${f(m.sales).replace('৳','')}</div>
          <div style="width:100%;display:flex;gap:1px;align-items:flex-end;height:120px;">
            <div style="flex:1;background:#16a34a;border-radius:3px 3px 0 0;height:${h}px;min-height:2px;" title="Sales: ${f(m.sales)}"></div>
            <div style="flex:1;background:#dc2626;border-radius:3px 3px 0 0;height:${ph}px;min-height:2px;" title="Purchases: ${f(m.purch)}"></div>
          </div>
          <div style="font-size:8px;color:#374151;font-weight:700;">${months[idx]}</div>
        </div>`;
      }).join('')}
    </div>
    <div style="display:flex;gap:16px;justify-content:center;margin-top:10px;">
      <span style="font-size:11px;color:#374151;display:flex;align-items:center;gap:4px;"><span style="width:12px;height:12px;background:#16a34a;border-radius:2px;display:inline-block;"></span>Sales</span>
      <span style="font-size:11px;color:#374151;display:flex;align-items:center;gap:4px;"><span style="width:12px;height:12px;background:#dc2626;border-radius:2px;display:inline-block;"></span>Purchases</span>
    </div>
  </div>

  <!-- Monthly P&L Table -->
  <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:16px;">
    <div class="card">
      <h3 style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:12px;">📅 Monthly P&L — ${thisYear}</h3>
      <table class="tbl"><thead><tr><th>Month</th><th>Sales</th><th>Cost</th><th>Profit</th></tr></thead>
      <tbody>${Object.entries(monthlyData).map(([key,m],idx)=>`<tr data-x-click="openPLDrill('${key}-01','${key}-31')" style="cursor:pointer;" title="Click to see this month's transactions">
        <td><strong>${months[idx]} →</strong></td>
        <td style="color:#16a34a;">${f(m.sales)}</td>
        <td style="color:#dc2626;">${f(m.purch+m.exp)}</td>
        <td style="font-weight:800;color:${m.profit>=0?'#059669':'#dc2626'};">${f(m.profit)}</td>
      </tr>`).join('')}</tbody>
      <tfoot><tr data-x-click="nav('profitloss')" style="cursor:pointer;" title="Click to open Profit & Loss">
        <td><strong>Total →</strong></td>
        <td style="color:#16a34a;font-weight:800;">${f(totalSales)}</td>
        <td style="color:#dc2626;font-weight:800;">${f(totalPurch+totalExp)}</td>
        <td style="font-weight:900;color:${totalProfit>=0?'#059669':'#dc2626'};">${f(totalProfit)}</td>
      </tr></tfoot></table>
    </div>
    <div class="card">
      <h3 style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:12px;">🏆 Top Products by Revenue</h3>
      ${topProds.length?`<table class="tbl"><thead><tr><th>Product</th><th>Qty</th><th>Revenue</th></tr></thead>
      <tbody>${topProds.map(([name,d],i)=>`<tr data-x-click="nav('inventory')" style="cursor:pointer;" title="Click to open Inventory">
        <td><span style="font-size:14px;">${['🥇','🥈','🥉','4️⃣','5️⃣'][i]}</span> <strong>${name} →</strong></td>
        <td>${d.qty.toLocaleString('en-IN')}</td>
        <td><strong style="color:#16a34a;">${f(d.total)}</strong></td>
      </tr>`).join('')}</tbody></table>`
      :'<div style="text-align:center;padding:20px;color:#9ca3af;">No product sales data yet.</div>'}
      <h3 style="font-size:14px;font-weight:800;color:#0f3d26;margin:16px 0 12px;">👥 Top Customers</h3>
      ${topCusts.length?`<table class="tbl"><thead><tr><th>Customer</th><th>Orders</th><th>Total</th></tr></thead>
      <tbody>${topCusts.map(([name,d],i)=>`<tr data-x-click="viewPartyLedger('${escHTML(name).replace(/'/g,"\\'")}')" style="cursor:pointer;" title="Click to open ${escHTML(name)}'s ledger">
        <td><span style="font-size:14px;">${['🥇','🥈','🥉','4️⃣','5️⃣'][i]}</span> <strong>${name} →</strong></td>
        <td>${d.count}</td>
        <td><strong style="color:#16a34a;">${f(d.total)}</strong></td>
      </tr>`).join('')}</tbody></table>`
      :'<div style="text-align:center;padding:20px;color:#9ca3af;">No customer data yet.</div>'}
    </div>
  </div>`;
}


