function renderRBOTools(){
  const el=document.getElementById('pg-rbotools')||document.getElementById('pg-analytics');
  if(!el) return;
  const isDark=document.documentElement.getAttribute('data-theme')==='dark';
  const bg=isDark?'#1e293b':'#fff';
  const border=isDark?'#334155':'#e5e7eb';
  const textColor=isDark?'#f1f5f9':'#1a202c';
  const text2=isDark?'#94a3b8':'#6b7280';

  el.innerHTML=`<div style="padding:20px;">
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:20px;flex-wrap:wrap;gap:10px;">
      <div>
        <h2 style="font-size:20px;font-weight:800;color:#0f3d26;margin:0;">🌾 Rice Bran Oil Business Tools</h2>
        <p style="font-size:12px;color:${text2};margin:4px 0 0;">Production, yield, batch tracking & vehicle management</p>
      </div>
    </div>

    <!-- Tool Tabs -->
    <div style="display:flex;gap:4px;background:${bg};border-radius:12px;padding:6px;border:1px solid ${border};margin-bottom:20px;flex-wrap:wrap;">
      ${['yield','batch','vehicle','production','pricing'].map((t,i)=>`
        <button data-x-click="rboTab('${t}')" id="rbo-tab-${t}"
          style="padding:8px 16px;border-radius:8px;border:none;cursor:pointer;font-size:12px;font-weight:700;transition:all .2s;
          background:${i===0?'#16a34a':'transparent'};color:${i===0?'#fff':'#6b7280'};"
          class="rbo-tab-btn">
          ${['🛢️ Yield Calc','📦 Batch Track','🚛 Vehicles','🏭 Production','⚖️ Pricing'][i]}
        </button>`).join('')}
    </div>

    <!-- YIELD CALCULATOR -->
    <div id="rbo-panel-yield">
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;">
        <div style="background:${bg};border:1px solid ${border};border-radius:14px;padding:20px;">
          <h3 style="font-size:15px;font-weight:800;color:#0f3d26;margin-bottom:16px;">🛢️ Oil Extraction Yield Calculator</h3>
          <div style="display:grid;gap:12px;">
            <div>
              <label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">Raw Rice Bran Input (KG)</label>
              <input type="number" id="yc-bran" placeholder="e.g. 1000" data-x-input="calcYield()"
                style="width:100%;padding:10px 12px;border:1.5px solid ${border};border-radius:8px;font-size:14px;background:${bg};color:${textColor};">
            </div>
            <div>
              <label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">Expected Oil % (typical: 18-22%)</label>
              <input type="number" id="yc-pct" value="20" min="1" max="50" data-x-input="calcYield()"
                style="width:100%;padding:10px 12px;border:1.5px solid ${border};border-radius:8px;font-size:14px;background:${bg};color:${textColor};">
            </div>
            <div>
              <label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">Bran Purchase Rate (৳/KG)</label>
              <input type="number" id="yc-bran-rate" placeholder="e.g. 45" data-x-input="calcYield()"
                style="width:100%;padding:10px 12px;border:1.5px solid ${border};border-radius:8px;font-size:14px;background:${bg};color:${textColor};">
            </div>
            <div>
              <label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">Processing Cost (৳/KG bran)</label>
              <input type="number" id="yc-proc-cost" placeholder="e.g. 8" data-x-input="calcYield()"
                style="width:100%;padding:10px 12px;border:1.5px solid ${border};border-radius:8px;font-size:14px;background:${bg};color:${textColor};">
            </div>
            <div>
              <label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">Oil Selling Price (৳/KG)</label>
              <input type="number" id="yc-oil-price" placeholder="e.g. 180" data-x-input="calcYield()"
                style="width:100%;padding:10px 12px;border:1.5px solid ${border};border-radius:8px;font-size:14px;background:${bg};color:${textColor};">
            </div>
          </div>
        </div>
        <div id="yc-results" style="background:linear-gradient(135deg,#0f3d26,#16a34a);border-radius:14px;padding:20px;color:#fff;">
          <h3 style="font-size:15px;font-weight:800;margin-bottom:16px;">📊 Yield Results</h3>
          <div style="text-align:center;padding:20px 0;color:rgba(255,255,255,.6);">Enter values to see results</div>
        </div>
      </div>
    </div>

    <!-- BATCH TRACKING -->
    <div id="rbo-panel-batch" style="display:none;">
      <div style="background:${bg};border:1px solid ${border};border-radius:14px;padding:20px;margin-bottom:16px;">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;">
          <h3 style="font-size:15px;font-weight:800;color:#0f3d26;margin:0;">📦 Batch / Lot Tracking</h3>
          <button data-x-click="openBatchModal()" style="padding:8px 16px;background:#16a34a;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:12px;">➕ New Batch</button>
        </div>
        <div id="batch-list"></div>
      </div>
    </div>

    <!-- VEHICLE MANAGEMENT -->
    <div id="rbo-panel-vehicle" style="display:none;">
      <div style="background:${bg};border:1px solid ${border};border-radius:14px;padding:20px;margin-bottom:16px;">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;">
          <h3 style="font-size:15px;font-weight:800;color:#0f3d26;margin:0;">🚛 Vehicle & Delivery Management</h3>
          <button data-x-click="openVehicleModal()" style="padding:8px 16px;background:#16a34a;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:12px;">➕ Add Vehicle</button>
        </div>
        <div id="vehicle-list"></div>
      </div>
    </div>

    <!-- PRODUCTION LOG -->
    <div id="rbo-panel-production" style="display:none;">
      <div style="background:${bg};border:1px solid ${border};border-radius:14px;padding:20px;margin-bottom:16px;">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;">
          <h3 style="font-size:15px;font-weight:800;color:#0f3d26;margin:0;">🏭 Daily Production Log</h3>
          <button data-x-click="openProductionModal()" style="padding:8px 16px;background:#16a34a;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:12px;">➕ Log Production</button>
        </div>
        <div id="production-list-2"></div>
      </div>
    </div>

    <!-- WEIGHT PRICING -->
    <div id="rbo-panel-pricing" style="display:none;">
      <div style="background:${bg};border:1px solid ${border};border-radius:14px;padding:20px;">
        <h3 style="font-size:15px;font-weight:800;color:#0f3d26;margin-bottom:16px;">⚖️ Weight-Based Pricing Calculator</h3>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;">
          <div style="display:grid;gap:12px;">
            <div>
              <label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">Product</label>
              <select id="wp-product" data-x-change="calcWeightPrice()"
                style="width:100%;padding:10px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};">
                <option value="">-- Select Product --</option>
                ${(DB.products||[]).map(p=>`<option value="${escHTML(p.name)}" data-rate="${p.rate||0}">${escHTML(p.name)} (৳${p.rate||0}/KG)</option>`).join('')}
              </select>
            </div>
            <div>
              <label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">Gross Weight (KG)</label>
              <input type="number" id="wp-gross" placeholder="e.g. 1050" data-x-input="calcWeightPrice()"
                style="width:100%;padding:10px 12px;border:1.5px solid ${border};border-radius:8px;font-size:14px;background:${bg};color:${textColor};">
            </div>
            <div>
              <label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">Tare Weight / Bag Weight (KG)</label>
              <input type="number" id="wp-tare" placeholder="e.g. 50" data-x-input="calcWeightPrice()"
                style="width:100%;padding:10px 12px;border:1.5px solid ${border};border-radius:8px;font-size:14px;background:${bg};color:${textColor};">
            </div>
            <div>
              <label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">Moisture Deduction %</label>
              <input type="number" id="wp-moisture" value="0" min="0" max="20" data-x-input="calcWeightPrice()"
                style="width:100%;padding:10px 12px;border:1.5px solid ${border};border-radius:8px;font-size:14px;background:${bg};color:${textColor};">
            </div>
            <div>
              <label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">Rate Override (৳/KG) — optional</label>
              <input type="number" id="wp-rate" placeholder="Leave blank to use product rate" data-x-input="calcWeightPrice()"
                style="width:100%;padding:10px 12px;border:1.5px solid ${border};border-radius:8px;font-size:14px;background:${bg};color:${textColor};">
            </div>
          </div>
          <div id="wp-results" style="background:linear-gradient(135deg,#1d4ed8,#2563eb);border-radius:12px;padding:20px;color:#fff;">
            <h4 style="font-size:14px;font-weight:800;margin-bottom:16px;">⚖️ Pricing Breakdown</h4>
            <div style="text-align:center;padding:20px 0;color:rgba(255,255,255,.6);">Enter values to calculate</div>
          </div>
        </div>
      </div>
    </div>
  </div>

  <!-- Batch Modal -->
  <div id="batch-modal" style="display:none;position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:1000;align-items:center;justify-content:center;">
    <div style="background:${bg};border-radius:16px;padding:24px;width:90%;max-width:500px;color:${textColor};">
      <div style="font-size:16px;font-weight:800;color:#0f3d26;margin-bottom:16px;">📦 New Batch / Lot</div>
      <div style="display:grid;gap:10px;">
        <div><label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">Batch Number *</label>
          <input id="bt-no" placeholder="e.g. BATCH-2024-001" style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};"></div>
        <div><label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">Date *</label>
          <input type="date" id="bt-date" style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};"></div>
        <div><label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">Raw Bran Input (KG)</label>
          <input type="number" id="bt-bran" placeholder="0" style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};"></div>
        <div><label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">Oil Output (KG)</label>
          <input type="number" id="bt-oil" placeholder="0" style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};"></div>
        <div><label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">De-oiled Cake (KG)</label>
          <input type="number" id="bt-cake" placeholder="0" style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};"></div>
        <div><label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">Quality Grade</label>
          <select id="bt-grade" style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};">
            <option>Grade A</option><option>Grade B</option><option>Grade C</option><option>Rejected</option>
          </select></div>
        <div><label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">Notes</label>
          <input id="bt-notes" placeholder="Optional notes" style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};"></div>
      </div>
      <div style="display:flex;gap:10px;justify-content:flex-end;margin-top:16px;">
        <button data-x-click="closeModalById('batch-modal')"
          style="padding:9px 18px;background:#f3f4f6;color:#374151;border:none;border-radius:8px;font-weight:700;cursor:pointer;">Cancel</button>
        <button data-x-click="saveBatch()"
          style="padding:9px 18px;background:#16a34a;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;">💾 Save Batch</button>
      </div>
    </div>
  </div>

  <!-- Vehicle Modal -->
  <div id="vehicle-modal" style="display:none;position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:1000;align-items:center;justify-content:center;">
    <div style="background:${bg};border-radius:16px;padding:24px;width:90%;max-width:500px;color:${textColor};">
      <div style="font-size:16px;font-weight:800;color:#0f3d26;margin-bottom:16px;">🚛 Add Vehicle</div>
      <div style="display:grid;gap:10px;">
        <div><label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">Vehicle Number *</label>
          <input id="vh-no" placeholder="e.g. DHAKA-TA-1234" style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};"></div>
        <div><label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">Vehicle Type</label>
          <select id="vh-type" style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};">
            <option>Truck</option><option>Pickup</option><option>Van</option><option>Tempo</option><option>Other</option>
          </select></div>
        <div><label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">Driver Name</label>
          <input id="vh-driver" placeholder="Driver name" style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};"></div>
        <div><label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">Driver Phone</label>
          <input id="vh-phone" placeholder="01XXXXXXXXX" style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};"></div>
        <div><label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">Capacity (KG)</label>
          <input type="number" id="vh-cap" placeholder="e.g. 5000" style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};"></div>
        <div><label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">Rate per Trip (৳)</label>
          <input type="number" id="vh-rate" placeholder="e.g. 5000" style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};"></div>
      </div>
      <div style="display:flex;gap:10px;justify-content:flex-end;margin-top:16px;">
        <button data-x-click="closeModalById('vehicle-modal')"
          style="padding:9px 18px;background:#f3f4f6;color:#374151;border:none;border-radius:8px;font-weight:700;cursor:pointer;">Cancel</button>
        <button data-x-click="saveVehicle()"
          style="padding:9px 18px;background:#16a34a;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;">💾 Save Vehicle</button>
      </div>
    </div>
  </div>

  <!-- Production Modal -->
  <div id="production-modal" style="display:none;position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:1000;align-items:center;justify-content:center;">
    <div style="background:${bg};border-radius:16px;padding:24px;width:90%;max-width:500px;color:${textColor};">
      <div style="font-size:16px;font-weight:800;color:#0f3d26;margin-bottom:16px;">🏭 Log Production</div>
      <div style="display:grid;gap:10px;">
        <div><label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">Date *</label>
          <input type="date" id="pr-log-date" style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};"></div>
        <div><label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">Shift</label>
          <select id="pr-log-shift" style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};">
            <option>Morning (6AM-2PM)</option><option>Afternoon (2PM-10PM)</option><option>Night (10PM-6AM)</option><option>Full Day</option>
          </select></div>
        <div><label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">Bran Processed (KG)</label>
          <input type="number" id="pr-log-bran" placeholder="0" data-x-input="calcProdYield()"
            style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};"></div>
        <div><label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">Oil Produced (KG)</label>
          <input type="number" id="pr-log-oil" placeholder="0" data-x-input="calcProdYield()"
            style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};"></div>
        <div id="pr-log-yield-display" style="background:#f0fdf4;border-radius:8px;padding:10px;font-size:13px;color:#16a34a;font-weight:700;display:none;"></div>
        <div><label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">Machine Hours</label>
          <input type="number" id="pr-log-hours" placeholder="e.g. 8" style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};"></div>
        <div><label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">Operator</label>
          <input id="pr-log-operator" placeholder="Operator name" style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};"></div>
        <div><label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">Issues / Notes</label>
          <input id="pr-log-notes" placeholder="Any issues or notes" style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};"></div>
      </div>
      <div style="display:flex;gap:10px;justify-content:flex-end;margin-top:16px;">
        <button data-x-click="closeModalById('production-modal')"
          style="padding:9px 18px;background:#f3f4f6;color:#374151;border:none;border-radius:8px;font-weight:700;cursor:pointer;">Cancel</button>
        <button data-x-click="saveProductionLog()"
          style="padding:9px 18px;background:#16a34a;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;">💾 Save Log</button>
      </div>
    </div>
  </div>`;

  // Initialize
  renderBatchList();
  renderVehicleList();
  renderProductionList();
}


// ═══════════════════════════════════════════════════════════════
// ORDER MANAGEMENT SYSTEM
// Columns: Order Date, Customer Name, Products Name, Load Location,
//          Qty, Rate, Loading Date, Delivery Date, Company Location,
//          Truck ID, Driver Mobile, Sending QTY, Received Qty,
//          Delivery Status, Remarks
// A-H = Admin/Owner editable | Staff = submit only
// NOT linked to main inventory
// ═══════════════════════════════════════════════════════════════

function renderOrderManagement(){
  const el=document.getElementById('pg-orders')||document.getElementById('pg-ordermanagement');
  if(!el) return;
  const isDark=document.documentElement.getAttribute('data-theme')==='dark';
  const bg=isDark?'#1e293b':'#fff';
  const border=isDark?'#334155':'#e5e7eb';
  const textColor=isDark?'#f1f5f9':'#1a202c';
  const text2=isDark?'#94a3b8':'#6b7280';
  const isAdmin=isAdminOrOwner();
  const orders=(DB.orders||[]).sort((a,b)=>b.orderDate.localeCompare(a.orderDate));

  // KPI summary
  const pending=orders.filter(o=>o.deliveryStatus==='Pending'||o.deliveryStatus==='Processing').length;
  const delivered=orders.filter(o=>o.deliveryStatus==='Delivered').length;
  const onRoute=orders.filter(o=>o.deliveryStatus==='On Route').length;
  const totalQty=orders.reduce((s,o)=>s+(parseFloat(o.qty)||0),0);
  const pendingApproval=orders.filter(o=>o.approvalStatus==='Pending').length;

  el.innerHTML=`<div style="padding:20px;">
    <!-- Header -->
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:20px;flex-wrap:wrap;gap:12px;">
      <div>
        <h2 style="font-size:20px;font-weight:800;color:#0f3d26;margin:0;">📋 Order Management</h2>
        <p style="font-size:12px;color:${text2};margin:4px 0 0;">Track orders from placement to delivery</p>
      </div>
      <div style="display:flex;gap:8px;flex-wrap:wrap;">
        <button data-x-click="openOrderModal()" style="padding:9px 18px;background:#16a34a;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:13px;display:flex;align-items:center;gap:6px;">
          ➕ New Order
        </button>
        <button data-x-click="exportOrdersCSV()" style="padding:9px 14px;background:#2563eb;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:12px;">
          📥 Export CSV
        </button>
        <button data-x-click="printOrdersReportBtn()" style="padding:9px 14px;background:#7c3aed;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:12px;">
          🖨️ Print
        </button>
      </div>
    </div>

    <!-- KPI Cards -->
    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:12px;margin-bottom:20px;">
      ${[
        {icon:'📋',label:'Total Orders',val:orders.length,color:'#2563eb'},
        {icon:'⏳',label:'Pending',val:pending,color:'#d97706'},
        {icon:'🚛',label:'On Route',val:onRoute,color:'#7c3aed'},
        {icon:'✅',label:'Delivered',val:delivered,color:'#16a34a'},
        {icon:'⚖️',label:'Total Qty',val:totalQty.toLocaleString('en-IN')+' KG',color:'#059669'},
        {icon:'🔏',label:'Pending Approval',val:pendingApproval,color:'#b45309'},
      ].map(k=>`<div class="kpi-card" style="border-left:4px solid ${k.color};">
        <div style="font-size:20px;">${k.icon}</div>
        <div style="font-size:20px;font-weight:900;color:${k.color};margin-top:4px;">${k.val}</div>
        <div style="font-size:10px;color:${text2};font-weight:700;">${k.label}</div>
      </div>`).join('')}
    </div>

    <!-- Filters -->
    <div style="background:${bg};border:1px solid ${border};border-radius:10px;padding:12px 16px;margin-bottom:16px;display:flex;gap:10px;flex-wrap:wrap;align-items:center;">
      <input type="text" id="order-search" placeholder="🔍 Search customer, product, truck..." data-x-input="filterOrders()"
        style="flex:1;min-width:200px;padding:8px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};">
      <select id="order-status-filter" data-x-change="filterOrders()"
        style="padding:8px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};">
        <option value="">All Status</option>
        <option>Pending</option><option>Processing</option><option>On Route</option>
        <option>Delivered</option><option>Cancelled</option>
      </select>
      <select id="order-approval-filter" data-x-change="filterOrders()"
        style="padding:8px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};">
        <option value="">All Approval</option>
        <option value="Pending">⏳ Pending Approval</option>
        <option value="Approved">✅ Approved</option>
      </select>
      <input type="date" id="order-date-from" data-x-change="filterOrders()"
        style="padding:8px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};">
      <input type="date" id="order-date-to" data-x-change="filterOrders()"
        style="padding:8px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};">
      <button data-x-click="filterOrders()" style="padding:8px 14px;background:#16a34a;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:12px;">🔄</button>
    </div>

    <!-- Orders Table -->
    <div style="background:${bg};border:1px solid ${border};border-radius:12px;overflow:hidden;">
      <div style="overflow-x:auto;">
        <table style="width:100%;border-collapse:collapse;font-size:12px;min-width:1500px;">
          <thead>
            <tr style="background:#0f3d26;color:#fff;">
              <th style="padding:10px 8px;text-align:left;white-space:nowrap;font-size:10px;font-weight:700;letter-spacing:.5px;">A. ORDER DATE</th>
              <th style="padding:10px 8px;text-align:left;white-space:nowrap;font-size:10px;font-weight:700;letter-spacing:.5px;">B. CUSTOMER NAME</th>
              <th style="padding:10px 8px;text-align:left;white-space:nowrap;font-size:10px;font-weight:700;letter-spacing:.5px;">C. PRODUCT NAME</th>
              <th style="padding:10px 8px;text-align:left;white-space:nowrap;font-size:10px;font-weight:700;letter-spacing:.5px;">D. LOAD LOCATION</th>
              <th style="padding:10px 8px;text-align:right;white-space:nowrap;font-size:10px;font-weight:700;letter-spacing:.5px;">E. QTY (KG)</th>
              <th style="padding:10px 8px;text-align:right;white-space:nowrap;font-size:10px;font-weight:700;letter-spacing:.5px;">F. RATE (৳)</th>
              <th style="padding:10px 8px;text-align:left;white-space:nowrap;font-size:10px;font-weight:700;letter-spacing:.5px;">G. LOADING DATE</th>
              <th style="padding:10px 8px;text-align:left;white-space:nowrap;font-size:10px;font-weight:700;letter-spacing:.5px;">H. DELIVERY DATE</th>
              <th style="padding:10px 8px;text-align:left;white-space:nowrap;font-size:10px;font-weight:700;letter-spacing:.5px;">COMPANY LOCATION</th>
              <th style="padding:10px 8px;text-align:left;white-space:nowrap;font-size:10px;font-weight:700;letter-spacing:.5px;">TRUCK ID</th>
              <th style="padding:10px 8px;text-align:left;white-space:nowrap;font-size:10px;font-weight:700;letter-spacing:.5px;">DRIVER MOBILE</th>
              <th style="padding:10px 8px;text-align:center;white-space:nowrap;font-size:10px;font-weight:700;letter-spacing:.5px;">QC DEPT</th>
              <th style="padding:10px 8px;text-align:right;white-space:nowrap;font-size:10px;font-weight:700;letter-spacing:.5px;">SENDING QTY</th>
              <th style="padding:10px 8px;text-align:right;white-space:nowrap;font-size:10px;font-weight:700;letter-spacing:.5px;">RECEIVED QTY</th>
              <th style="padding:10px 8px;text-align:center;white-space:nowrap;font-size:10px;font-weight:700;letter-spacing:.5px;">DELIVERY STATUS</th>
              <th style="padding:10px 8px;text-align:left;white-space:nowrap;font-size:10px;font-weight:700;letter-spacing:.5px;">REMARKS</th>
              <th style="padding:10px 8px;text-align:center;white-space:nowrap;font-size:10px;font-weight:700;letter-spacing:.5px;">ACTIONS</th>
            </tr>
          </thead>
          <tbody id="orders-tbody">
            ${renderOrderRows(orders)}
          </tbody>
          <tfoot>
            <tr style="background:#f0fdf4;font-weight:800;">
              <td colspan="4" style="padding:10px 8px;color:#0f3d26;font-size:12px;">TOTALS (${orders.length} orders)</td>
              <td style="padding:10px 8px;text-align:right;color:#16a34a;">${orders.reduce((s,o)=>s+(parseFloat(o.qty)||0),0).toLocaleString('en-IN')}</td>
              <td style="padding:10px 8px;"></td>
              <td colspan="6" style="padding:10px 8px;"></td>
              <td style="padding:10px 8px;text-align:right;color:#2563eb;">${orders.reduce((s,o)=>s+(parseFloat(o.sendingQty)||0),0).toLocaleString('en-IN')}</td>
              <td style="padding:10px 8px;text-align:right;color:#16a34a;">${orders.reduce((s,o)=>s+(parseFloat(o.receivedQty)||0),0).toLocaleString('en-IN')}</td>
              <td colspan="3" style="padding:10px 8px;"></td>
            </tr>
          </tfoot>
        </table>
      </div>
    </div>

    ${!orders.length?'<div style="text-align:center;padding:40px;color:'+text2+';">No orders yet. Click "➕ New Order" to add the first order.</div>':''}
  </div>

  <!-- Order Modal -->
  <div id="order-modal" style="display:none;position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:2000;align-items:center;justify-content:center;overflow-y:auto;">
    <div style="background:${bg};border-radius:16px;padding:0;width:95%;max-width:800px;margin:20px auto;color:${textColor};box-shadow:0 8px 40px rgba(0,0,0,.3);">
      <div style="background:linear-gradient(135deg,#0f3d26,#16a34a);color:#fff;padding:18px 24px;border-radius:16px 16px 0 0;display:flex;justify-content:space-between;align-items:center;">
        <div style="font-size:16px;font-weight:800;" id="order-modal-title">📋 New Order</div>
        <button data-x-click="closeOrderModal()" style="background:none;border:none;color:#fff;font-size:22px;cursor:pointer;line-height:1;">✕</button>
      </div>
      <div style="padding:24px;">
        <div style="background:#f0fdf4;border:1px solid #bbf7d0;border-radius:8px;padding:10px 14px;margin-bottom:16px;font-size:12px;color:#16a34a;font-weight:700;">
          📌 All fields are editable by any user. Orders created or edited by a Manager go to "Pending Approval" until an Admin/Owner approves them.
        </div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;">
          <!-- A: Order Date -->
          <div>
            <label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">A. ORDER DATE *</label>
            <input type="date" id="ord-date" style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};">
          </div>
          <!-- B: Customer Name -->
          <div>
            <label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">B. CUSTOMER NAME *</label>
            <input type="text" id="ord-customer" list="ord-customer-list" placeholder="Customer name" data-x-input="onPartyNameFieldChanged('ord-customer','ord-bankaccount','ord-bankaccount-custom')" data-x-change="onPartyNameFieldChanged('ord-customer','ord-bankaccount','ord-bankaccount-custom')" style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};">
            <datalist id="ord-customer-list">${(DB.customers||[]).filter(c=>isCustomerParty(c)).map(c=>`<option value="${escHTML(c.name)}">`).join('')}</datalist>
          </div>
          <!-- C: Product Name -->
          <div>
            <label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">C. PRODUCT NAME *</label>
            <input type="text" id="ord-product" list="ord-product-list" placeholder="Product name" style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};">
            <datalist id="ord-product-list">${(DB.products||[]).map(p=>`<option value="${escHTML(p.name)}">`).join('')}</datalist>
          </div>
          <!-- D: Load Location -->
          <div>
            <label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">D. LOAD LOCATION</label>
            <input type="text" id="ord-load-loc" placeholder="Loading point/warehouse" style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};">
          </div>
          <!-- E: Qty -->
          <div>
            <label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">E. QTY (KG) *</label>
            <input type="number" id="ord-qty" placeholder="0" data-x-input="calcOrderTotal()" style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};">
          </div>
          <!-- F: Rate -->
          <div>
            <label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">F. RATE (৳/KG)</label>
            <input type="number" id="ord-rate" placeholder="0.00" data-x-input="calcOrderTotal()" style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};">
          </div>
          <!-- G: Loading Date (Admin/Owner) -->
          <div>
            <label style="font-size:11px;font-weight:700;color:#16a34a;display:block;margin-bottom:4px;">G. LOADING DATE </label>
            <input type="date" id="ord-loading-date" style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};">
          </div>
          <!-- H: Delivery Date (Admin/Owner) -->
          <div>
            <label style="font-size:11px;font-weight:700;color:#16a34a;display:block;margin-bottom:4px;">H. DELIVERY DATE </label>
            <input type="date" id="ord-delivery-date" style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};">
          </div>
          <!-- Company Location (Admin/Owner) -->
          <div>
            <label style="font-size:11px;font-weight:700;color:#16a34a;display:block;margin-bottom:4px;">COMPANY LOCATION </label>
            <input type="text" id="ord-company-loc" placeholder="Delivery destination" style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};">
          </div>
          <!-- Truck ID (Admin/Owner) -->
          <div>
            <label style="font-size:11px;font-weight:700;color:#16a34a;display:block;margin-bottom:4px;">TRUCK ID </label>
            <input type="text" id="ord-truck-id" placeholder="e.g. DHAKA-TA-1234" style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};">
          </div>
          <!-- Bank Account for payment on this order — pulls the customer's
               saved bank account automatically (see populatePartyBankPicker),
               or lets one be typed for a one-off. -->
          <div>
            <label style="font-size:11px;font-weight:700;color:#16a34a;display:block;margin-bottom:4px;">BANK ACCOUNT (PAYMENT)</label>
            <select id="ord-bankaccount" data-x-change="onPartyBankPickerChange('ord-bankaccount','ord-bankaccount-custom')" style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};"><option value="">-- Select Bank Account --</option></select>
            <input type="text" id="ord-bankaccount-custom" placeholder="Type bank name, account no., branch..." style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};display:none;margin-top:6px;box-sizing:border-box;">
          </div>
          <!-- Driver Mobile (Admin/Owner) -->
          <div>
            <label style="font-size:11px;font-weight:700;color:#16a34a;display:block;margin-bottom:4px;">DRIVER MOBILE </label>
            <input type="text" id="ord-driver-mobile" placeholder="01XXXXXXXXX" style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};">
          </div>
          <!-- Sending QTY (Admin/Owner) -->
          <div>
            <label style="font-size:11px;font-weight:700;color:#16a34a;display:block;margin-bottom:4px;">SENDING QTY </label>
            <input type="number" id="ord-sending-qty" placeholder="0" style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};">
          </div>
          <!-- Received QTY (Admin/Owner) -->
          <div>
            <label style="font-size:11px;font-weight:700;color:#16a34a;display:block;margin-bottom:4px;">RECEIVED QTY </label>
            <input type="number" id="ord-received-qty" placeholder="0" style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};">
          </div>
          <!-- Delivery Status (Admin/Owner) -->
          <div>
            <label style="font-size:11px;font-weight:700;color:#16a34a;display:block;margin-bottom:4px;">DELIVERY STATUS </label>
            <select id="ord-status" style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};">
              <option value="Pending">⏳ Pending</option>
              <option value="Processing">⚙️ Processing</option>
              <option value="On Route">🚛 On Route</option>
              <option value="Delivered">✅ Delivered</option>
              <option value="Cancelled">❌ Cancelled</option>
            </select>
          </div>
          <!-- Remarks -->
          <div style="grid-column:1/-1;">
            <label style="font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;">REMARKS</label>
            <textarea id="ord-remarks" rows="2" placeholder="Additional notes..." style="width:100%;padding:9px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};resize:vertical;"></textarea>
          </div>
        </div>
        <!-- Total preview -->
        <div style="background:#f0fdf4;border:1.5px solid #bbf7d0;border-radius:8px;padding:12px 16px;margin-top:14px;display:flex;justify-content:space-between;align-items:center;">
          <span style="font-size:13px;font-weight:700;color:#0f3d26;">Order Total:</span>
          <span id="ord-total-display" style="font-size:18px;font-weight:900;color:#16a34a;">৳0.00</span>
        </div>
        <input type="hidden" id="ord-edit-id" value="">
      </div>
      <div style="padding:14px 24px;border-top:1px solid ${border};display:flex;gap:10px;justify-content:flex-end;">
        <button data-x-click="closeOrderModal()" style="padding:10px 20px;background:#f3f4f6;color:#374151;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:13px;">Cancel</button>
        <button data-x-click="saveOrder()" style="padding:10px 24px;background:#16a34a;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:14px;">💾 Save Order</button>
      </div>
    </div>
  </div>`;
}

function renderOrderRows(orders){
  const isDark=document.documentElement.getAttribute('data-theme')==='dark';
  const border=isDark?'#334155':'#f1f5f9';
  const textColor=isDark?'#f1f5f9':'#1a202c';
  const text2=isDark?'#94a3b8':'#6b7280';
  const isAdmin=isAdminOrOwner();

  if(!orders.length) return `<tr><td colspan="17" style="text-align:center;padding:30px;color:${text2};">No orders found.</td></tr>`;

  const statusColors={
    'Pending':'#fef9c3;color:#b45309',
    'Processing':'#dbeafe;color:#1d4ed8',
    'On Route':'#ede9fe;color:#7c3aed',
    'Delivered':'#dcfce7;color:#16a34a',
    'Cancelled':'#fee2e2;color:#dc2626',
  };

  return orders.map((o,i)=>{
    const sc=statusColors[o.deliveryStatus]||'#f3f4f6;color:#6b7280';
    const total=(parseFloat(o.qty)||0)*(parseFloat(o.rate)||0);
    return `<tr style="border-bottom:1px solid ${border};" data-hover-bg="${isDark?'#162032':'#f9fafb'}">
      <td style="padding:9px 8px;color:${textColor};white-space:nowrap;">${o.orderDate||'—'}</td>
      <td style="padding:9px 8px;font-weight:700;color:${textColor};">${escHTML(o.customerName||'—')}</td>
      <td style="padding:9px 8px;color:${textColor};">${escHTML(o.productName ||'—')}</td>
      <td style="padding:9px 8px;color:${text2};">${o.loadLocation||'—'}</td>
      <td style="padding:9px 8px;text-align:right;font-weight:700;color:#16a34a;">${(parseFloat(o.qty)||0).toLocaleString('en-IN')}</td>
      <td style="padding:9px 8px;text-align:right;color:${textColor};">${o.rate?'৳'+parseFloat(o.rate).toLocaleString('en-IN',{minimumFractionDigits:2}):'—'}</td>
      <td style="padding:9px 8px;color:${text2};white-space:nowrap;">${o.loadingDate||'—'}</td>
      <td style="padding:9px 8px;color:${text2};white-space:nowrap;">${o.deliveryDate||'—'}</td>
      <td style="padding:9px 8px;color:${text2};">${o.companyLocation||'—'}</td>
      <td style="padding:9px 8px;color:${textColor};font-weight:700;">${o.truckId||'—'}</td>
      <td style="padding:9px 8px;color:${text2};">${o.driverMobile||'—'}</td>
      <td style="padding:9px 8px;text-align:center;">
        ${o.qcTalked?`<span style="padding:3px 8px;border-radius:8px;font-size:10px;font-weight:700;background:#dcfce7;color:#16a34a;" title="${o.qcTalkedBy||'—'} at ${o.qcTalkedAt?new Date(o.qcTalkedAt).toLocaleString('en-GB'):'—'}">✅ TALKED</span>`:`<button data-x-click="toggleOrderQC('${o.id}')" style="padding:4px 10px;background:#fef3c7;color:#b45309;border:none;border-radius:6px;cursor:pointer;font-size:10px;font-weight:700;animation:pulse 2s infinite;">📞 Talk with QC</button>`}
      </td>
      <td style="padding:9px 8px;text-align:right;color:#2563eb;font-weight:700;">${o.sendingQty?parseFloat(o.sendingQty).toLocaleString('en-IN'):'—'}</td>
      <td style="padding:9px 8px;text-align:right;color:#16a34a;font-weight:700;">${o.receivedQty?parseFloat(o.receivedQty).toLocaleString('en-IN'):'—'}</td>
      <td style="padding:9px 8px;text-align:center;">
        <span style="padding:3px 10px;border-radius:8px;font-size:10px;font-weight:700;background:${sc.split(';')[0]};${sc.split(';')[1]||''}">${o.deliveryStatus||'Pending'}</span>
        <br><span style="padding:2px 8px;border-radius:8px;font-size:9px;font-weight:800;margin-top:3px;display:inline-block;background:${o.approvalStatus==='Pending'?'#fef3c7;color:#b45309':'#dcfce7;color:#16a34a'};" title="${o.approvalStatus==='Approved'?'Approved by '+(o.approvedBy||'—'):'Awaiting Admin/Owner approval'}">${o.approvalStatus==='Pending'?'⏳ PENDING APPROVAL':'✅ APPROVED'}</span>
      </td>
      <td style="padding:9px 8px;font-size:11px;color:${text2};max-width:120px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="${escHTML(o.remarks ||'')}">${escHTML(o.remarks ||'—')}</td>
      <td style="padding:9px 8px;text-align:center;white-space:nowrap;">
        <button data-x-click="editOrder('${o.id}')" style="padding:4px 10px;background:#dbeafe;color:#1d4ed8;border:none;border-radius:6px;cursor:pointer;font-size:11px;font-weight:700;margin-right:4px;">✏️</button>
        <!-- FIX (deletion was open to every logged-in user): isAdmin was
             computed above but never actually used to gate anything — Staff
             could permanently delete any order with no approval step, even
             though editing the same order correctly requires Admin/Owner
             review. Delete is now shown, and enforced in deleteOrder()
             itself, to Admin/Owner/Manager only — matching canEditOrder(). -->
        <button data-x-click="createChallanFromOrder('${o.id}')" title="Create a Delivery Challan pre-filled from this order" style="padding:4px 10px;background:#ede9fe;color:#7c3aed;border:none;border-radius:6px;cursor:pointer;font-size:11px;font-weight:700;margin-right:4px;">🚚 Challan</button>
        ${isAdmin?`<button data-x-click="deleteOrder('${o.id}')" style="padding:4px 10px;background:#fee2e2;color:#dc2626;border:none;border-radius:6px;cursor:pointer;font-size:11px;font-weight:700;margin-right:4px;">🗑️</button>`:''}
        ${(o.approvalStatus==='Pending'&&typeof isTopApprover==='function'&&isTopApprover())?`<button data-x-click="approveOrder('${o.id}')" style="padding:4px 10px;background:#dcfce7;color:#16a34a;border:none;border-radius:6px;cursor:pointer;font-size:11px;font-weight:700;">✅ Approve</button>`:''}
      </td>
    </tr>`;
  }).join('');
}


async function toggleOrderQC(id){
  const o=(DB.orders||[]).find(x=>String(x.id)===String(id));
  if(!o) return;
  if(o.qcTalked){
    if(!await __confirm('Reset QC talk status for this vehicle?')) return;
    delete o.qcTalked; delete o.qcTalkedBy; delete o.qcTalkedAt;
  } else {
    o.qcTalked=true;
    o.qcTalkedBy=currentUser?.name||'Staff';
    o.qcTalkedAt=new Date().toISOString();
    toast('QC department talk recorded', 's');
  }
  saveDB();
  renderOrderManagement();
  _scheduleAutoSave();
}

async function approveOrder(id){
  if(typeof isTopApprover!=='function'||!isTopApprover()){toast('Only Admin/Owner can approve orders','e');return;}
  const o=(DB.orders||[]).find(x=>String(x.id)===String(id));
  if(!o) return;
  if(o.approvalStatus==='Approved'){ toast('Already approved','i'); return; }
  /* MAKER-CHECKER: refuse a silent self-approval. */
  const _mc=await window.MakerChecker.gate(o,'order');
  if(!_mc.ok){ toast('Approval cancelled','i'); return; }
  o.approvalStatus='Approved';
  o.approvedBy=currentUser?.name||'Admin';
  o.approvedAt=new Date().toISOString();
  if(_mc.override) window.MakerChecker.recordOverride(o,'Order',_mc.reason);
  saveDB();
  logAudit('ORDER','Order Approved','Approved order for '+(o.customerName||'')+' by '+(currentUser?.name||'')+(_mc.override?' [SELF-APPROVED, override]':''));
  toast('Order approved','s');
  renderOrderManagement();
  _scheduleAutoSave();
}

function filterOrders(){
  const q=(document.getElementById('order-search')?.value||'').toLowerCase();
  const status=document.getElementById('order-status-filter')?.value||'';
  const approval=document.getElementById('order-approval-filter')?.value||'';
  const dateFrom=document.getElementById('order-date-from')?.value||'';
  const dateTo=document.getElementById('order-date-to')?.value||'';
  const orders=(DB.orders||[]).filter(o=>{
    const matchQ=!q||(o.customerName||'').toLowerCase().includes(q)||(o.productName||'').toLowerCase().includes(q)||(o.truckId||'').toLowerCase().includes(q)||(o.driverMobile||'').includes(q);
    const matchS=!status||o.deliveryStatus===status;
    const matchA=!approval||o.approvalStatus===approval;
    const matchD=(!dateFrom||o.orderDate>=dateFrom)&&(!dateTo||o.orderDate<=dateTo);
    return matchQ&&matchS&&matchA&&matchD;
  }).sort((a,b)=>b.orderDate.localeCompare(a.orderDate));
  const tbody=document.getElementById('orders-tbody');
  if(tbody) tbody.innerHTML=renderOrderRows(orders);
}

function openOrderModal(editId){
  const modal=document.getElementById('order-modal');
  if(!modal) return;
  const today=new Date().toISOString().split('T')[0];
  if(!editId){
    // New order
    document.getElementById('order-modal-title').textContent='📋 New Order';
    document.getElementById('ord-edit-id').value='';
    document.getElementById('ord-date').value=today;
    ['ord-customer','ord-product','ord-load-loc','ord-qty','ord-rate',
     'ord-loading-date','ord-delivery-date','ord-company-loc','ord-truck-id',
     'ord-driver-mobile','ord-sending-qty','ord-received-qty','ord-remarks',
     'ord-bankaccount-custom'].forEach(id=>{
      const el=document.getElementById(id);
      if(el) el.value='';
    });
    const statusEl=document.getElementById('ord-status');
    if(statusEl) statusEl.value='Pending';
    document.getElementById('ord-total-display').textContent='৳0.00';
    populatePartyBankPicker('ord-customer','ord-bankaccount','ord-bankaccount-custom');
  }
  modal.style.display='flex';
}

function editOrder(id){
  const o=(DB.orders||[]).find(o=>o.id===id);
  if(!o) return;
  document.getElementById('order-modal-title').textContent='✏️ Edit Order';
  document.getElementById('ord-edit-id').value=id;
  const fields={
    'ord-date':o.orderDate,'ord-customer':o.customerName,'ord-product':o.productName,
    'ord-load-loc':o.loadLocation,'ord-qty':o.qty,'ord-rate':o.rate,
    'ord-loading-date':o.loadingDate,'ord-delivery-date':o.deliveryDate,
    'ord-company-loc':o.companyLocation,'ord-truck-id':o.truckId,
    'ord-driver-mobile':o.driverMobile,'ord-sending-qty':o.sendingQty,
    'ord-received-qty':o.receivedQty,'ord-remarks':o.remarks
  };
  Object.entries(fields).forEach(([id,val])=>{
    const el=document.getElementById(id);
    if(el&&val!==undefined&&val!==null) el.value=val;
  });
  const statusEl=document.getElementById('ord-status');
  if(statusEl) statusEl.value=o.deliveryStatus||'Pending';
  populatePartyBankPicker('ord-customer','ord-bankaccount','ord-bankaccount-custom', o.bankAccount||'');
  calcOrderTotal();
  document.getElementById('order-modal').style.display='flex';
}

function closeOrderModal(){
  const modal=document.getElementById('order-modal');
  if(modal) modal.style.display='none';
}

function calcOrderTotal(){
  const qty=parseFloat(document.getElementById('ord-qty')?.value)||0;
  const rate=parseFloat(document.getElementById('ord-rate')?.value)||0;
  const total=qty*rate;
  const disp=document.getElementById('ord-total-display');
  if(disp) disp.textContent='৳'+total.toLocaleString('en-IN',{minimumFractionDigits:2});
}

function saveOrder(){
  const date=document.getElementById('ord-date')?.value;
  const customer=document.getElementById('ord-customer')?.value?.trim();
  const product=document.getElementById('ord-product')?.value?.trim();
  const qty=parseFloat(document.getElementById('ord-qty')?.value)||0;
  if(!date){toast('Please select order date','e');return;}
  if(!customer){toast('Customer name is required','e');return;}
  if(!product){toast('Product name is required','e');return;}
  if(!qty){toast('Quantity is required','e');return;}

  const editId=document.getElementById('ord-edit-id')?.value;
  /* FIX (order access & approval): every field used to be locked to
     Admin/Owner only, and Staff/Manager entries were never distinguished
     from an Admin's — there was no approval concept at all. Now every
     logged-in user can fill in every field, but anything created or
     edited by someone other than Admin/Owner (this is what actually
     covers a Manager's entries) is marked Pending Approval until an
     Admin or Owner reviews and approves it via approveOrder(). */
  const isTopApprover = (typeof window.isTopApprover==='function') ? window.isTopApprover() : isAdminOrOwner();
  const orderData={
    id:editId||'ORD-'+Date.now(),
    orderDate:date,
    customerName:customer,
    productName:product,
    loadLocation:document.getElementById('ord-load-loc')?.value||'',
    qty,
    rate:parseFloat(document.getElementById('ord-rate')?.value)||0,
    total:qty*(parseFloat(document.getElementById('ord-rate')?.value)||0),
    loadingDate:document.getElementById('ord-loading-date')?.value||'',
    deliveryDate:document.getElementById('ord-delivery-date')?.value||'',
    companyLocation:document.getElementById('ord-company-loc')?.value||'',
    truckId:document.getElementById('ord-truck-id')?.value||'',
    bankAccount:getPartyBankPickerValue('ord-bankaccount','ord-bankaccount-custom'),
    driverMobile:document.getElementById('ord-driver-mobile')?.value||'',
    sendingQty:parseFloat(document.getElementById('ord-sending-qty')?.value)||0,
    receivedQty:parseFloat(document.getElementById('ord-received-qty')?.value)||0,
    deliveryStatus:document.getElementById('ord-status')?.value||'Pending',
    remarks:document.getElementById('ord-remarks')?.value||'',
    qcTalked: editId?(DB.orders.find(x=>String(x.id)===String(editId))?.qcTalked||false):false,
    qcTalkedBy: editId?(DB.orders.find(x=>String(x.id)===String(editId))?.qcTalkedBy||''):'',
    qcTalkedAt: editId?(DB.orders.find(x=>String(x.id)===String(editId))?.qcTalkedAt||''):'',
    submittedBy:currentUser?.name||'Staff',
    submittedAt:new Date().toISOString(),
    role:currentUser?.role||'Staff',
    /* MAKER-CHECKER (2026-08-29): an Admin-submitted order used to approve
       itself on save. Every order now starts Pending; see approveOrder(). */
    approvalStatus: 'Pending',
    approvedBy: '',
    approvedAt: '',
    makerUserId: (currentUser?.id!=null?String(currentUser.id):''),
    makerUsername: currentUser?.username||'',
    enteredBy: currentUser?.name||'',
    enteredRole: currentUser?.role||'',
    makerAt: new Date().toISOString()
  };

  if(!DB.orders) DB.orders=[];
  if(editId){
    const idx=DB.orders.findIndex(o=>o.id===editId);
    if(idx>=0) DB.orders[idx]=orderData;
    else DB.orders.push(orderData);
    toast('Order updated!', 's');
  } else {
    DB.orders.push(orderData);
    toast('Order submitted!', 's');
  }
  saveDB();
  logAudit('ORDER','Order Submission (Pending Approval)','Order for '+customer+' — '+qty+' KG '+product);
  closeOrderModal();
  renderOrderManagement();
  _scheduleAutoSave();
}

async function deleteOrder(id){
  if(!currentUser){toast('Please sign in','e');return;}
  /* FIX (open to everyone): deleting an order had no role check at all —
     any logged-in Staff account could permanently remove any order,
     bypassing the whole Pending Approval workflow that edits go through.
     Enforced here (not just by hiding the button) so it can't be triggered
     by calling the function directly either. */
  if(typeof isAdminOrOwner!=='function'||!isAdminOrOwner()){toast('Only Admin/Owner/Manager can delete orders — ask an admin to remove this.','e');return;}
  if(!await __confirm('Delete this order?')) return;
  DB.orders=(DB.orders||[]).filter(o=>o.id!==id);
  saveDB();
  logAudit('ORDER','Order Deleted','Deleted order '+id+' by '+(currentUser?.name||'Staff'));
  toast('Order deleted','s');
  renderOrderManagement();
}

function exportOrdersCSV(){
  const orders=DB.orders||[];
  if(!orders.length){toast('No orders to export','e');return;}
  const headers=['Order Date','Customer Name','Product Name','Load Location','Qty','Rate','Total',
    'Loading Date','Delivery Date','Company Location','Truck ID','Driver Mobile','QC Talked',
    'Sending QTY','Received QTY','Delivery Status','Remarks','Submitted By'];
  let csv=headers.join(',')+'\r\n';
  orders.forEach(o=>{
    csv+=[o.orderDate,o.customerName,o.productName,o.loadLocation,o.qty,o.rate,o.total,
      o.loadingDate,o.deliveryDate,o.companyLocation,o.truckId,o.driverMobile,o.qcTalked?'Yes':'No',
      o.sendingQty,o.receivedQty,o.deliveryStatus,o.remarks,o.submittedBy
    ].map(v=>'"'+(v||'').toString().replace(/"/g,'""')+'"').join(',')+'\r\n';
  });
  const blob=new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'});
  const a=document.createElement('a');
  a.href=URL.createObjectURL(blob);
  a.download='Orders_'+new Date().toISOString().split('T')[0]+'.csv';
  a.click();
  logAudit('EXPORT','Orders','Exported '+orders.length+' orders to CSV');
}

function rboTab(tab){
  ['yield','batch','vehicle','production','pricing'].forEach(t=>{
    const panel=document.getElementById('rbo-panel-'+t);
    const btn=document.getElementById('rbo-tab-'+t);
    if(panel) panel.style.display=t===tab?'block':'none';
    if(btn){
      btn.style.background=t===tab?'#16a34a':'transparent';
      btn.style.color=t===tab?'#fff':'#6b7280';
    }
  });
}

function calcYield(){
  const bran=parseFloat(document.getElementById('yc-bran')?.value)||0;
  const pct=parseFloat(document.getElementById('yc-pct')?.value)||20;
  const branRate=parseFloat(document.getElementById('yc-bran-rate')?.value)||0;
  const procCost=parseFloat(document.getElementById('yc-proc-cost')?.value)||0;
  const oilPrice=parseFloat(document.getElementById('yc-oil-price')?.value)||0;
  const res=document.getElementById('yc-results');
  if(!res||!bran) return;

  const oilKg=bran*pct/100;
  const cakeKg=bran-oilKg;
  const totalCost=bran*(branRate+procCost);
  const revenue=oilKg*oilPrice;
  const profit=revenue-totalCost;
  const costPerKgOil=oilKg>0?totalCost/oilKg:0;
  const margin=revenue>0?profit/revenue*100:0;

  res.innerHTML=`
    <h3 style="font-size:15px;font-weight:800;margin-bottom:16px;">📊 Yield Results</h3>
    <div style="display:grid;gap:10px;">
      ${[
        ['🛢️ Oil Output',oilKg.toLocaleString('en-IN',{maximumFractionDigits:1})+' KG','rgba(255,255,255,.2)'],
        ['🌾 De-oiled Cake',cakeKg.toLocaleString('en-IN',{maximumFractionDigits:1})+' KG','rgba(255,255,255,.2)'],
        ['📊 Actual Yield %',pct.toFixed(1)+'%','rgba(255,255,255,.2)'],
        ['💰 Total Cost','৳'+totalCost.toLocaleString('en-IN',{minimumFractionDigits:2}),'rgba(255,255,255,.2)'],
        ['💵 Revenue','৳'+revenue.toLocaleString('en-IN',{minimumFractionDigits:2}),'rgba(255,255,255,.2)'],
        ['📈 Gross Profit','৳'+profit.toLocaleString('en-IN',{minimumFractionDigits:2}),profit>=0?'rgba(74,222,128,.3)':'rgba(248,113,113,.3)'],
        ['⚖️ Cost/KG Oil','৳'+costPerKgOil.toLocaleString('en-IN',{minimumFractionDigits:2}),'rgba(255,255,255,.2)'],
        ['📉 Profit Margin',margin.toFixed(1)+'%',margin>=0?'rgba(74,222,128,.3)':'rgba(248,113,113,.3)'],
      ].map(([label,val,bg])=>`
        <div style="display:flex;justify-content:space-between;align-items:center;background:${bg};border-radius:8px;padding:10px 12px;">
          <span style="font-size:12px;opacity:.85;">${label}</span>
          <span style="font-size:14px;font-weight:800;">${val}</span>
        </div>`).join('')}
    </div>`;
}

function calcWeightPrice(){
  const gross=parseFloat(document.getElementById('wp-gross')?.value)||0;
  const tare=parseFloat(document.getElementById('wp-tare')?.value)||0;
  const moisture=parseFloat(document.getElementById('wp-moisture')?.value)||0;
  const prodSel=document.getElementById('wp-product');
  const prodRate=parseFloat(prodSel?.options[prodSel?.selectedIndex]?.dataset?.rate)||0;
  const rateOverride=parseFloat(document.getElementById('wp-rate')?.value)||0;
  const rate=rateOverride||prodRate;
  const res=document.getElementById('wp-results');
  if(!res||!gross) return;

  const netWt=gross-tare;
  const moistureDeduct=netWt*moisture/100;
  const payableWt=netWt-moistureDeduct;
  const totalAmt=payableWt*rate;

  res.innerHTML=`
    <h4 style="font-size:14px;font-weight:800;margin-bottom:16px;">⚖️ Pricing Breakdown</h4>
    <div style="display:grid;gap:8px;">
      ${[
        ['Gross Weight',gross.toLocaleString('en-IN')+' KG'],
        ['Tare/Bag Weight','-'+tare.toLocaleString('en-IN')+' KG'],
        ['Net Weight',netWt.toLocaleString('en-IN')+' KG'],
        ['Moisture Deduction ('+moisture+'%)','-'+moistureDeduct.toFixed(2)+' KG'],
        ['Payable Weight',payableWt.toFixed(2)+' KG'],
        ['Rate',rate?'৳'+rate+'/KG':'Not set'],
        ['Total Amount','৳'+totalAmt.toLocaleString('en-IN',{minimumFractionDigits:2})],
      ].map(([label,val],i)=>`
        <div style="display:flex;justify-content:space-between;padding:8px 10px;background:${i===6?'rgba(255,255,255,.25)':'rgba(255,255,255,.1)'};border-radius:6px;${i===6?'font-size:16px;font-weight:900;':'font-size:12px;'}">
          <span style="opacity:.85;">${label}</span>
          <span style="font-weight:${i===6?'900':'700'};">${val}</span>
        </div>`).join('')}
    </div>`;
}

function calcProdYield(){
  const bran=parseFloat(document.getElementById('pr-log-bran')?.value)||0;
  const oil=parseFloat(document.getElementById('pr-log-oil')?.value)||0;
  const disp=document.getElementById('pr-log-yield-display');
  if(!disp) return;
  if(bran>0&&oil>0){
    const yld=(oil/bran*100).toFixed(2);
    disp.style.display='block';
    disp.textContent='✅ Yield: '+yld+'% ('+oil+' KG oil from '+bran+' KG bran)';
  } else {
    disp.style.display='none';
  }
}

function openBatchModal(){
  document.getElementById('bt-date').value=new Date().toISOString().split('T')[0];
  ['bt-no','bt-bran','bt-oil','bt-cake','bt-notes'].forEach(id=>{
    const el=document.getElementById(id);
    if(el) el.value='';
  });
