}

function saveBatch(){
  const no=document.getElementById('bt-no')?.value?.trim();
  const date=document.getElementById('bt-date')?.value;
  if(!no||!date){toast('Batch number and date required','e');return;}
  if(!DB.batches) DB.batches=[];
  DB.batches.push({
    id:newId(), no, date,
    bran:parseFloat(document.getElementById('bt-bran')?.value)||0,
    oil:parseFloat(document.getElementById('bt-oil')?.value)||0,
    cake:parseFloat(document.getElementById('bt-cake')?.value)||0,
    grade:document.getElementById('bt-grade')?.value||'Grade A',
    notes:document.getElementById('bt-notes')?.value||''
  });
  saveDB();
  document.getElementById('batch-modal').style.display='none';
  renderBatchList();
  toast('Batch saved!', 's');
}

function renderBatchList(){
  const el=document.getElementById('batch-list');
  if(!el) return;
  const batches=(DB.batches||[]).sort((a,b)=>b.date.localeCompare(a.date));
  if(!batches.length){
    el.innerHTML='<div style="text-align:center;padding:30px;color:#9ca3af;">No batches recorded yet. Click "New Batch" to start.</div>';
    return;
  }
  el.innerHTML=`<table class="tbl"><thead><tr><th>Batch #</th><th>Date</th><th>Bran (KG)</th><th>Oil (KG)</th><th>Cake (KG)</th><th>Yield %</th><th>Grade</th><th>Notes</th><th>Del</th></tr></thead>
  <tbody>${batches.map(b=>`<tr>
    <td><strong>${b.no}</strong></td>
    <td>${b.date}</td>
    <td>${(b.bran||0).toLocaleString('en-IN')}</td>
    <td style="color:#16a34a;font-weight:700;">${(b.oil||0).toLocaleString('en-IN')}</td>
    <td>${(b.cake||0).toLocaleString('en-IN')}</td>
    <td style="font-weight:700;color:#2563eb;">${b.bran>0?((b.oil/b.bran)*100).toFixed(1)+'%':'—'}</td>
    <td><span style="padding:2px 8px;border-radius:6px;font-size:10px;font-weight:700;background:${b.grade==='Grade A'?'#dcfce7':b.grade==='Grade B'?'#fef9c3':b.grade==='Rejected'?'#fee2e2':'#f3f4f6'};color:${b.grade==='Grade A'?'#16a34a':b.grade==='Grade B'?'#b45309':b.grade==='Rejected'?'#dc2626':'#6b7280'};">${b.grade}</span></td>
    <td style="font-size:11px;color:#6b7280;">${escHTML(b.notes||'—')}</td>
    <td><button data-x-click="deleteBatch(${b.id})" style="padding:4px 8px;background:#fee2e2;color:#dc2626;border:none;border-radius:6px;cursor:pointer;font-size:11px;">🗑️</button></td>
  </tr>`).join('')}</tbody></table>`;
}

async function deleteBatch(id){
  if(!await __confirm('Delete this batch?')) return;
  DB.batches=(DB.batches||[]).filter(b=>b.id!==id);
  saveDB(); renderBatchList(); toast('Batch deleted','s');
}

