function saveProductionLog(){
  const date=document.getElementById('pr-log-date')?.value;
  if(!date){toast('Date required','e');return;}
  if(!DB.productionLog) DB.productionLog=[];
  const bran=parseFloat(document.getElementById('pr-log-bran')?.value)||0;
  const oil=parseFloat(document.getElementById('pr-log-oil')?.value)||0;
  DB.productionLog.push({
    id:newId(), date,
    shift:document.getElementById('pr-log-shift')?.value||'Full Day',
    bran, oil,
    yield:bran>0?(oil/bran*100).toFixed(2):0,
    hours:parseFloat(document.getElementById('pr-log-hours')?.value)||0,
    operator:document.getElementById('pr-log-operator')?.value||'',
    notes:document.getElementById('pr-log-notes')?.value||''
  });
  saveDB();
  document.getElementById('production-modal').style.display='none';
  renderProductionList();
  toast('Production log saved!', 's');
}

function renderProductionList(){
  /* Two panel copies exist in the markup (main Factory tab + rbo panel group),
     so every element with either id gets the same content instead of only
     the first one document.getElementById would have matched. */
  const els=[document.getElementById('production-list'),document.getElementById('production-list-2')].filter(Boolean);
  if(!els.length) return;
  const logs=(DB.productionLog||[]).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,30);
  if(!logs.length){
    els.forEach(el=>{el.innerHTML='<div style="text-align:center;padding:30px;color:#9ca3af;">No production logs yet.</div>';});
    return;
  }
  const totalBran=logs.reduce((s,l)=>s+(l.bran||0),0);
  const totalOil=logs.reduce((s,l)=>s+(l.oil||0),0);
  const avgYield=totalBran>0?(totalOil/totalBran*100).toFixed(2):0;
  const html=`
    <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:16px;">
      <div class="kpi-card" style="border-left:4px solid #16a34a;"><div style="font-size:18px;">🌾</div><div style="font-size:20px;font-weight:900;color:#16a34a;">${totalBran.toLocaleString('en-IN')} KG</div><div style="font-size:10px;color:#6b7280;font-weight:700;">Total Bran Processed</div></div>
      <div class="kpi-card" style="border-left:4px solid #2563eb;"><div style="font-size:18px;">🛢️</div><div style="font-size:20px;font-weight:900;color:#2563eb;">${totalOil.toLocaleString('en-IN')} KG</div><div style="font-size:10px;color:#6b7280;font-weight:700;">Total Oil Produced</div></div>
      <div class="kpi-card" style="border-left:4px solid #7c3aed;"><div style="font-size:18px;">📊</div><div style="font-size:20px;font-weight:900;color:#7c3aed;">${avgYield}%</div><div style="font-size:10px;color:#6b7280;font-weight:700;">Average Yield</div></div>
    </div>
    <table class="tbl"><thead><tr><th>Date</th><th>Shift</th><th>Bran (KG)</th><th>Oil (KG)</th><th>Yield %</th><th>Hours</th><th>Operator</th><th>Notes</th><th>Del</th></tr></thead>
    <tbody>${logs.map(l=>`<tr>
      <td>${l.date}</td>
      <td>${l.shift}</td>
      <td>${(l.bran||0).toLocaleString('en-IN')}</td>
      <td style="color:#16a34a;font-weight:700;">${(l.oil||0).toLocaleString('en-IN')}</td>
      <td style="font-weight:700;color:#7c3aed;">${l.yield}%</td>
      <td>${l.hours||'—'}</td>
      <td>${l.operator||'—'}</td>
      <td style="font-size:11px;color:#6b7280;">${escHTML(l.notes||'—')}</td>
      <td><button data-x-click="deleteProductionLog(${l.id})" style="padding:4px 8px;background:#fee2e2;color:#dc2626;border:none;border-radius:6px;cursor:pointer;font-size:11px;">🗑️</button></td>
    </tr>`).join('')}</tbody></table>`;
  els.forEach(el=>{el.innerHTML=html;});
}

async function deleteProductionLog(id){
  if(!await __confirm('Delete this log?')) return;
  DB.productionLog=(DB.productionLog||[]).filter(l=>l.id!==id);
  saveDB(); renderProductionList(); toast('Log deleted','s');
}


// ═══════════════════════════════════════════════════════════════
// GLOBAL SEARCH SYSTEM
// ═══════════════════════════════════════════════════════════════
let _globalSearchTimeout = null;

function initGlobalSearch(){
  // Add search bar to topbar if not exists
  const topbarLeft = document.querySelector('.topbar-left');
  if(topbarLeft && !document.getElementById('global-search-input')){
    const searchWrap = document.createElement('div');
    searchWrap.style.cssText = 'position:relative;margin-left:10px;';
    searchWrap.innerHTML = `
      <input type="text" id="global-search-input" placeholder="🔍 Search everything..."
        data-x-input="globalSearch(this.value)"
        onkeydown="if(event.key==='Escape'){this.value='';closeGlobalSearch();}"
        style="padding:7px 14px 7px 36px;border:1.5px solid var(--dm-border,#e5e7eb);border-radius:20px;
        font-size:12px;width:220px;outline:none;background:var(--dm-card,#fff);color:var(--dm-text,#1a202c);
        transition:all .2s;"
        onfocus="this.style.width='300px';this.style.borderColor='#16a34a'"
        onblur="if(!this.value){this.style.width='220px';this.style.borderColor='var(--dm-border,#e5e7eb)'}">
      <span style="position:absolute;left:12px;top:50%;transform:translateY(-50%);font-size:14px;pointer-events:none;">🔍</span>
      <div id="global-search-results" style="display:none;position:absolute;top:calc(100% + 6px);left:0;width:420px;
        background:var(--dm-card,#fff);border:1.5px solid var(--dm-border,#e5e7eb);border-radius:12px;
        box-shadow:0 8px 24px rgba(0,0,0,.15);z-index:500;max-height:400px;overflow-y:auto;"></div>`;
    topbarLeft.appendChild(searchWrap);
  }
}

function globalSearch(q){
  clearTimeout(_globalSearchTimeout);
  const res = document.getElementById('global-search-results');
  if(!res) return;
  if(!q || q.length < 2){ res.style.display='none'; return; }
  _globalSearchTimeout = setTimeout(()=>{
    const query = q.toLowerCase();
    const results = [];
    const isDark = document.documentElement.getAttribute('data-theme')==='dark';
    const bg = isDark?'#1e293b':'#fff';
    const textColor = isDark?'#f1f5f9':'#1a202c';
    const text2 = isDark?'#94a3b8':'#6b7280';
    const hoverBg = isDark?'#0f3d26':'#f0fdf4';

    // Search transactions
    (DB.tx||[]).filter(t=>
      (t.party||'').toLowerCase().includes(query)||
      (t.type||'').toLowerCase().includes(query)||
      (t.prod||'').toLowerCase().includes(query)||
      (t.inv||'').toLowerCase().includes(query)||
      (t.rem||'').toLowerCase().includes(query)
    ).slice(0,5).forEach(t=>results.push({
      type:'Transaction', icon:'💰', title:t.type+' — '+(t.party||''),
      sub:'৳'+txAmt(t).toLocaleString('en-IN')+' | '+t.date,
      action:`nav('transactions')`, color:'#16a34a'
    }));

    // Search customers
    (DB.customers||[]).filter(c=>
      (c.name||'').toLowerCase().includes(query)||
      (c.phone||'').toLowerCase().includes(query)||
      (c.address||'').toLowerCase().includes(query)
    ).slice(0,4).forEach(c=>results.push({
      type:'Customer', icon:'👤', title:c.name,
      sub:(c.type||'Customer')+' | Balance: ৳'+(c.bal||0).toLocaleString('en-IN'),
      action:`nav('customers')`, color:'#2563eb'
    }));

    // Search products
    (DB.products||[]).filter(p=>
      (p.name||'').toLowerCase().includes(query)||
      (p.cat||'').toLowerCase().includes(query)
    ).slice(0,3).forEach(p=>results.push({
      type:'Product', icon:'📦', title:p.name,
      sub:(p.cat||'')+'| Stock: '+(p.qty||0)+' '+(p.unit||'KG')+' | Rate: ৳'+(p.rate||0),
      action:`nav('inventory')`, color:'#7c3aed'
    }));

    // Search banks
    (DB.banks||[]).filter(b=>
      (b.name||'').toLowerCase().includes(query)||
      (b.bankName||'').toLowerCase().includes(query)||
      (b.accountNo||'').toLowerCase().includes(query)
    ).slice(0,3).forEach(b=>results.push({
      type:'Bank', icon:'🏦', title:b.name,
      sub:(b.bankName||'')+' | Balance: ৳'+(b.bal||0).toLocaleString('en-IN'),
      action:`nav('banks')`, color:'#059669'
    }));

    // Search partners
    (DB.partners||[]).filter(p=>
      (p.name||'').toLowerCase().includes(query)||
      (p.phone||'').toLowerCase().includes(query)
    ).slice(0,3).forEach(p=>results.push({
      type:'Partner', icon:'🤝', title:p.name,
      sub:'Capital: ৳'+(p.cap||0).toLocaleString('en-IN')+' | Share: '+(p.share||0)+'%',
      action:`nav('partners')`, color:'#d97706'
    }));

    // Search employees
    (DB.employees||[]).filter(e=>
      (e.name||'').toLowerCase().includes(query)||
      (e.designation||'').toLowerCase().includes(query)
    ).slice(0,2).forEach(e=>results.push({
      type:'Employee', icon:'👷', title:e.name,
      sub:(e.designation||'')+'| Salary: ৳'+(e.salary||0).toLocaleString('en-IN'),
      action:`nav('payroll')`, color:'#dc2626'
    }));

    // Search batches
    (DB.batches||[]).filter(b=>
      (b.no||'').toLowerCase().includes(query)||
      (b.notes||'').toLowerCase().includes(query)
    ).slice(0,2).forEach(b=>results.push({
      type:'Batch', icon:'📦', title:'Batch: '+b.no,
      sub:b.date+' | Oil: '+(b.oil||0)+' KG | Yield: '+(b.bran>0?((b.oil/b.bran)*100).toFixed(1)+'%':'—'),
      action:`nav('analytics')`, color:'#0891b2'
    }));

    if(!results.length){
      res.innerHTML=`<div style="padding:20px;text-align:center;color:${text2};font-size:13px;">No results for "<strong>${q}</strong>"</div>`;
    } else {
      res.innerHTML=`
        <div style="padding:10px 14px;font-size:10px;font-weight:800;color:${text2};text-transform:uppercase;border-bottom:1px solid var(--dm-border,#e5e7eb);">
          ${results.length} result${results.length!==1?'s':''} for "${q}"
        </div>
        ${results.map(r=>`
          <div data-x-click="${r.action};closeGlobalSearch()"
            style="padding:10px 14px;cursor:pointer;border-bottom:1px solid var(--dm-border,#e5e7eb);transition:background .15s;"
            data-hover-bg="${hoverBg}">
            <div style="display:flex;align-items:center;gap:10px;">
              <span style="font-size:18px;">${r.icon}</span>
              <div style="flex:1;">
                <div style="font-size:13px;font-weight:700;color:${textColor};">${r.title}</div>
                <div style="font-size:11px;color:${text2};margin-top:1px;">${r.sub}</div>
              </div>
              <span style="padding:2px 8px;border-radius:6px;font-size:9px;font-weight:800;background:${r.color}22;color:${r.color};">${r.type}</span>
            </div>
          </div>`).join('')}
        <div style="padding:8px 14px;text-align:center;border-top:1px solid var(--dm-border,#e5e7eb);">
          <span style="font-size:11px;color:${text2};">Press Esc to close</span>
        </div>`;
    }
    res.style.display='block';
  }, 200);
}

function closeGlobalSearch(){
  const res=document.getElementById('global-search-results');
  const inp=document.getElementById('global-search-input');
  if(res) res.style.display='none';
  if(inp){ inp.value=''; inp.style.width='220px'; }
}


// ═══════════════════════════════════════════════════════════════
// ENHANCED DASHBOARD — Trend arrows, month comparison, KPI widgets
// ═══════════════════════════════════════════════════════════════
function renderEnhancedDashboard(){
  const el=document.getElementById('enhanced-dash-wrap');
  if(!el) return;

  const txs=DB.tx||[];
  const now=new Date();
  const thisMonth=now.toISOString().substring(0,7);
  const lastMonthDate=new Date(now.getFullYear(),now.getMonth()-1,1);
  const lastMonth=lastMonthDate.toISOString().substring(0,7);
  const today=now.toISOString().split('T')[0];

  const SALE_T=['Sale','Sales','Sales Invoice','Customer Sale','Warehouse Sale','Other Income','Interest Income']; // canonical: money receipts/advances are NOT revenue or cost
  const PURCH_T=['Purchase','Warehouse Purchase','Supplier Purchase']; // canonical: money receipts/advances are NOT revenue or cost
  const EXP_T=['Salary Payment','Office Rent','Electricity Bill','Internet Bill','Fuel Expense',
    'Transport Cost','Loading Charge','Unloading Charge','Commission Payment','Other Expense'];

  function monthSum(month, types){
    return txs.filter(t=>t.date&&t.date.startsWith(month)&&types.includes(t.type))
      .reduce((s,t)=>s+txAmt(t),0);
  }
  function todaySum(types){
    return txs.filter(t=>t.date===today&&types.includes(t.type))
      .reduce((s,t)=>s+txAmt(t),0);
  }

  const thisSales=monthSum(thisMonth,SALE_T);
  const lastSales=monthSum(lastMonth,SALE_T);
  const thisPurch=monthSum(thisMonth,PURCH_T);
  const lastPurch=monthSum(lastMonth,PURCH_T);
  const thisExp=monthSum(thisMonth,EXP_T);
  const lastExp=monthSum(lastMonth,EXP_T);
  const thisProfit=thisSales-thisPurch-thisExp;
  const lastProfit=lastSales-lastPurch-lastExp;
  const todaySales=todaySum(SALE_T);
  const todayPurch=todaySum(PURCH_T);

  const totalBankBal=(DB.banks||[]).reduce((s,b)=>s+(b.bal||0),0);
  const totalRecv=(DB.customers||[]).filter(c=>isCustomerParty(c)).reduce((s,c)=>s+(c.bal||0),0);
  const totalPartCap=(DB.partners||[]).reduce((s,p)=>s+(p.cap||0),0);
  const lowStock=(DB.products||[]).filter(p=>(p.qty||0)<=(p.minStock||10)).length;

  function trend(curr,prev){
    if(!prev) return {arrow:'→',color:'#6b7280',pct:'—'};
    const pct=((curr-prev)/Math.abs(prev)*100);
    if(pct>0) return {arrow:'↑',color:'#16a34a',pct:'+'+pct.toFixed(1)+'%'};
    if(pct<0) return {arrow:'↓',color:'#dc2626',pct:pct.toFixed(1)+'%'};
    return {arrow:'→',color:'#6b7280',pct:'0%'};
  }

  const salesTrend=trend(thisSales,lastSales);
  const profitTrend=trend(thisProfit,lastProfit);
  const expTrend=trend(thisExp,lastExp);

  const isDark=document.documentElement.getAttribute('data-theme')==='dark';
  const bg=isDark?'#1e293b':'#fff';
  const border=isDark?'#334155':'#e5e7eb';
  const textColor=isDark?'#f1f5f9':'#1a202c';
  const text2=isDark?'#94a3b8':'#6b7280';

  el.innerHTML=`
    <!-- Enhanced KPI Grid -->
    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:14px;margin-bottom:20px;">
      ${[
        {icon:'💰',label:'This Month Sales',val:f(thisSales),sub:salesTrend.arrow+' '+salesTrend.pct+' vs last month',subColor:salesTrend.color,grad:'linear-gradient(135deg,#065f46,#059669)'},
        {icon:'📈',label:'This Month Profit',val:f(thisProfit),sub:profitTrend.arrow+' '+profitTrend.pct+' vs last month',subColor:profitTrend.color,grad:'linear-gradient(135deg,'+( thisProfit>=0?'#7c3aed,#8b5cf6':'#dc2626,#ef4444')+')'},
        {icon:'🏦',label:'Total Bank Balance',val:f(totalBankBal),sub:(DB.banks||[]).length+' accounts',subColor:'rgba(255,255,255,.7)',grad:'linear-gradient(135deg,#1d4ed8,#2563eb)'},
        {icon:'📋',label:'Customer Receivables',val:f(totalRecv),sub:(DB.customers||[]).filter(c=>c.bal>0).length+' customers with dues',subColor:'rgba(255,255,255,.7)',grad:'linear-gradient(135deg,#b45309,#d97706)'},
        {icon:'💵',label:"Today's Sales",val:f(todaySales),sub:'Purchases: '+f(todayPurch),subColor:'rgba(255,255,255,.7)',grad:'linear-gradient(135deg,#0891b2,#06b6d4)'},
        {icon:'⚠️',label:'Low Stock Items',val:lowStock,sub:lowStock>0?'Needs restocking':'All stock OK',subColor:lowStock>0?'#fbbf24':'rgba(255,255,255,.7)',grad:lowStock>0?'linear-gradient(135deg,#dc2626,#ef4444)':'linear-gradient(135deg,#16a34a,#22c55e)'},
      ].map(k=>`
        <div style="background:${k.grad};border-radius:14px;padding:18px;color:#fff;position:relative;overflow:hidden;">
          <div style="font-size:28px;margin-bottom:8px;">${k.icon}</div>
          <div style="font-size:10px;font-weight:700;opacity:.8;text-transform:uppercase;letter-spacing:.5px;">${k.label}</div>
          <div style="font-size:22px;font-weight:900;margin-top:4px;">${k.val}</div>
          <div style="font-size:11px;margin-top:4px;color:${k.subColor};">${k.sub}</div>
        </div>`).join('')}
    </div>

    <!-- Month Comparison -->
    <div style="background:${bg};border:1px solid ${border};border-radius:14px;padding:18px;margin-bottom:16px;">
      <div style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:14px;">📊 Month-over-Month Comparison</div>
      <div style="overflow-x:auto;">
        <table style="width:100%;border-collapse:collapse;font-size:13px;">
          <thead><tr>
            <th style="padding:8px 12px;text-align:left;background:#0f3d26;color:#fff;border-radius:8px 0 0 0;">Metric</th>
            <th style="padding:8px 12px;text-align:right;background:#0f3d26;color:#fff;">${lastMonth}</th>
            <th style="padding:8px 12px;text-align:right;background:#0f3d26;color:#fff;">${thisMonth}</th>
            <th style="padding:8px 12px;text-align:right;background:#0f3d26;color:#fff;border-radius:0 8px 0 0;">Change</th>
          </tr></thead>
          <tbody>
            ${[
              ['💰 Sales',lastSales,thisSales,salesTrend],
              ['📦 Purchases',lastPurch,thisPurch,trend(thisPurch,lastPurch)],
              ['💸 Expenses',lastExp,thisExp,expTrend],
              ['📈 Gross Profit',lastProfit,thisProfit,profitTrend],
            ].map(([label,last,curr,tr],i)=>`
              <tr style="background:${i%2===0?'transparent':(isDark?'#162032':'#f9fafb')};">
                <td style="padding:10px 12px;font-weight:700;color:${textColor};">${label}</td>
                <td style="padding:10px 12px;text-align:right;color:${text2};">${f(last)}</td>
                <td style="padding:10px 12px;text-align:right;font-weight:800;color:${textColor};">${f(curr)}</td>
                <td style="padding:10px 12px;text-align:right;">
                  <span style="padding:3px 10px;border-radius:8px;font-size:11px;font-weight:800;
                    background:${tr.color}22;color:${tr.color};">
                    ${tr.arrow} ${tr.pct}
                  </span>
                </td>
              </tr>`).join('')}
          </tbody>
        </table>
      </div>
    </div>

    <!-- Recent Activity -->
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;">
      <div style="background:${bg};border:1px solid ${border};border-radius:14px;padding:18px;">
        <div style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:12px;">🕐 Recent Transactions</div>
        ${(DB.tx||[]).slice(-8).reverse().map(t=>`
          <div style="display:flex;justify-content:space-between;align-items:center;padding:8px 0;border-bottom:1px solid ${border};">
            <div>
              <div style="font-size:12px;font-weight:700;color:${textColor};">${escHTML(t.party||t.type)}</div>
              <div style="font-size:10px;color:${text2};">${t.type} • ${t.date}</div>
            </div>
            <div style="font-size:13px;font-weight:800;color:${['Sale','Warehouse Sale','Sales Receipt'].includes(t.type)?'#16a34a':'#dc2626'};">
              ${['Sale','Warehouse Sale','Sales Receipt'].includes(t.type)?'+':'-'}${f(txAmt(t))}
            </div>
          </div>`).join('')||'<div style="color:'+text2+';font-size:12px;text-align:center;padding:20px;">No transactions yet</div>'}
      </div>
      <div style="background:${bg};border:1px solid ${border};border-radius:14px;padding:18px;">
        <div style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:12px;">🏆 Top Customers This Month</div>
        ${Object.entries((DB.tx||[]).filter(t=>t.date&&t.date.startsWith(thisMonth)&&SALE_T.includes(t.type)&&t.party)
          .reduce((acc,t)=>{acc[t.party]=(acc[t.party]||0)+txAmt(t);return acc;},{})
        ).sort((a,b)=>b[1]-a[1]).slice(0,6).map(([name,amt],i)=>`
          <div style="display:flex;justify-content:space-between;align-items:center;padding:8px 0;border-bottom:1px solid ${border};">
            <div style="display:flex;align-items:center;gap:8px;">
              <span style="font-size:14px;">${['🥇','🥈','🥉','4️⃣','5️⃣','6️⃣'][i]}</span>
              <span style="font-size:12px;font-weight:700;color:${textColor};">${name}</span>
            </div>
            <span style="font-size:13px;font-weight:800;color:#16a34a;">${f(amt)}</span>
          </div>`).join('')||'<div style="color:'+text2+';font-size:12px;text-align:center;padding:20px;">No sales this month</div>'}
      </div>
    </div>`;
}

// Close search on click outside
document.addEventListener('click', function(e){
  if(!e.target.closest('#global-search-input') && !e.target.closest('#global-search-results')){
    closeGlobalSearch();
  }
});

// Ctrl+K shortcut to focus search
document.addEventListener('keydown', function(e){
  if((e.ctrlKey||e.metaKey) && e.key==='k'){
    e.preventDefault();
    const inp=document.getElementById('global-search-input');
    if(inp){ inp.focus(); inp.select(); }
  }
});

function renderRealtimeAlerts(){
  const el = document.getElementById('pg-realtimealerts');
  if(!el) return;
  const txs = DB.tx||[];
  const products = DB.products||[];
  const customers = DB.customers||[];
  const banks = DB.banks||[];
  const today = new Date().toISOString().split('T')[0];
  const thisMonth = new Date().toISOString().substring(0,7);
  const f = v => '৳'+Math.abs(v||0).toLocaleString('en-IN');

  // Build real-time alerts
  const alerts = [];

  // Low stock alerts
  products.filter(p=>(p.stock||0)<=(p.reorder||10)&&(p.reorder||10)>0).forEach(p=>{
    alerts.push({type:'stock',level:'critical',icon:'📦',title:'Low Stock: '+p.name,
      detail:'Current: '+(p.stock||0)+' '+( p.unit||'units')+' | Reorder at: '+(p.reorder||10),
      time:today, action:"nav('stockalerts')"});
  });

  // Overdue customers
  customers.filter(c=>(c.type==='Customer'||c.type==='Both')&&(c.bal||0)>50000).forEach(c=>{
    alerts.push({type:'finance',level:'warning',icon:'👥',title:'High Receivable: '+c.name,
      detail:'Outstanding: '+f(c.bal),time:today, action:"nav('customeraging')"});
  });

  // Negative bank balance
  banks.filter(b=>(b.bal||0)<0).forEach(b=>{
    alerts.push({type:'bank',level:'critical',icon:'🏦',title:'Negative Bank: '+b.name,
      detail:'Balance: '+f(b.bal)+' (overdrawn)',time:today, action:"nav('banks')"});
  });

  // Today's large transactions
  const largeTx = txs.filter(t=>t.date===today&&txAmt(t)>500000);
  largeTx.forEach(t=>{
    alerts.push({type:'tx',level:'info',icon:'💰',title:'Large Transaction Today',
      detail:t.type+' — '+f(t.amt)+(t.party?' with '+t.party:''),time:today, action:"nav('transactions')"});
  });

  // Negative stock
  products.filter(p=>(p.stock||0)<0).forEach(p=>{
    alerts.push({type:'stock',level:'critical',icon:'⚠️',title:'Negative Stock: '+p.name,
      detail:'Stock: '+p.stock+' (below zero — check transactions)',time:today, action:"nav('stockadj')"});
  });

  // Pending tenders
  const urgentTenders = (DB.tenders||[]).filter(t=>{
    if(!t.deadline||t.status==='Closed') return false;
    const days = Math.ceil((new Date(t.deadline)-new Date())/(86400000));
    return days>=0&&days<=7;
  });
  urgentTenders.forEach(t=>{
    const days = Math.ceil((new Date(t.deadline)-new Date())/(86400000));
    alerts.push({type:'tender',level:'warning',icon:'📋',title:'Tender Deadline: '+(t.name||t.title||'Tender'),
      detail:'Due in '+days+' day(s) — '+t.deadline,time:today, action:"nav('tenders')"});
  });

  // High supplier dues
  customers.filter(c=>isSupplierParty(c)&&(c.bal||0)>100000).forEach(c=>{
    alerts.push({type:'finance',level:'warning',icon:'🏭',title:'High Supplier Due: '+c.name,
      detail:'Payable: '+f(c.bal),time:today, action:"nav('supplieraging')"});
  });

  // Monthly sales check
  const monthTxsForLoss = txs.filter(t=>t.date&&t.date.startsWith(thisMonth));
  const monthSales = monthTxsForLoss.filter(t=>isRevenueTx(t)).reduce((s,t)=>s+txAmt(t),0);
  const monthCOGSForLoss = window.computeCOGS(monthTxsForLoss);
  const monthExpForLoss = monthTxsForLoss.filter(t=>window.EXPENSE_TX_TYPES.has(t.type)).reduce((s,t)=>s+txAmt(t),0);
  const monthNetForLoss = monthSales - monthCOGSForLoss - monthExpForLoss;
  if(monthNetForLoss < 0){
    alerts.push({type:'finance',level:'critical',icon:'📉',title:'Monthly Loss Alert',
      detail:'Net loss of '+f(Math.abs(monthNetForLoss))+' this month (Sales '+f(monthSales)+' − COGS '+f(monthCOGSForLoss)+' − Expenses '+f(monthExpForLoss)+')',time:today, action:"nav('profitloss')"});
  }

  const levelColors = {
    critical:{bg:'#fef2f2',border:'#fecaca',dot:'#dc2626',badge:'#dc2626',badgeTxt:'CRITICAL'},
    warning: {bg:'#fffbeb',border:'#fde68a',dot:'#d97706',badge:'#d97706',badgeTxt:'WARNING'},
    info:    {bg:'#eff6ff',border:'#bfdbfe',dot:'#3b82f6',badge:'#3b82f6',badgeTxt:'INFO'},
  };

  el.innerHTML = `
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:18px;">
      <div>
        <h2 style="font-size:20px;font-weight:900;color:#0f3d26;margin:0;">🔔 Real-Time Alerts</h2>
        <p style="font-size:12px;color:#6b7280;margin:2px 0 0;">Live system alerts — refreshed every time you visit this page</p>
      </div>
      <div style="display:flex;gap:8px;">
        <button data-x-click="renderRealtimeAlerts()" style="padding:8px 16px;background:#16a34a;color:#fff;border:none;border-radius:7px;font-size:12px;font-weight:700;cursor:pointer;">🔄 Refresh</button>
        <button data-x-click="nav('smartnotifications')" style="padding:8px 16px;background:#f3f4f6;border:1px solid #d1d5db;border-radius:7px;font-size:12px;cursor:pointer;">⚙️ Settings</button>
      </div>
    </div>

    <!-- Summary Cards -->
    <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:18px;">
      ${[
        {label:'Total Alerts',val:alerts.length,color:'#1e40af',bg:'#eff6ff',icon:'🔔'},
        {label:'Critical',val:alerts.filter(a=>a.level==='critical').length,color:'#dc2626',bg:'#fef2f2',icon:'🚨'},
        {label:'Warnings',val:alerts.filter(a=>a.level==='warning').length,color:'#d97706',bg:'#fffbeb',icon:'⚠️'},
      ].map(c=>`<div style="background:${c.bg};border-radius:10px;padding:14px;text-align:center;">
        <div style="font-size:24px;">${c.icon}</div>
        <div style="font-size:28px;font-weight:900;color:${c.color};">${c.val}</div>
        <div style="font-size:11px;color:#6b7280;">${c.label}</div>
      </div>`).join('')}
    </div>

    <!-- Alert List -->
    <div style="display:flex;flex-direction:column;gap:10px;">
      ${alerts.length===0
        ? '<div style="text-align:center;padding:40px;background:#f0fdf4;border-radius:12px;color:#16a34a;font-size:14px;font-weight:700;">✅ No alerts — system is healthy!</div>'
        : alerts.sort((a,b)=>a.level==='critical'?-1:b.level==='critical'?1:0).map(a=>{
            const lc = levelColors[a.level]||levelColors.info;
            return `<div style="background:${lc.bg};border:1px solid ${lc.border};border-radius:10px;padding:14px;display:flex;align-items:center;gap:14px;cursor:pointer;" data-x-click="${a.action}">
              <div style="font-size:28px;min-width:36px;text-align:center;">${a.icon}</div>
              <div style="flex:1;">
                <div style="display:flex;align-items:center;gap:8px;margin-bottom:4px;">
                  <span style="font-size:13px;font-weight:800;color:#1e293b;">${a.title}</span>
                  <span style="background:${lc.badge};color:#fff;font-size:9px;font-weight:800;padding:2px 6px;border-radius:4px;">${lc.badgeTxt}</span>
                </div>
                <div style="font-size:12px;color:#6b7280;">${a.detail}</div>
              </div>
              <div style="font-size:11px;color:#9ca3af;white-space:nowrap;">${a.time}</div>
              <div style="font-size:16px;color:#9ca3af;">›</div>
            </div>`;
          }).join('')
      }
    </div>

    <!-- Auto-refresh note -->
    <div style="margin-top:16px;text-align:center;font-size:11px;color:#9ca3af;">
      Last checked: ${new Date().toLocaleTimeString('en-IN')} — Click Refresh to update
    </div>
  `;
}

function renderProInvoice(){
  const el=document.getElementById('pg-profinvoice');
  if(!el)return;
  const company=DB.settings||{};
  const customers=(DB.customers||[]).filter(c=>isCustomerParty(c));
  const products=DB.products||[];
  const today=new Date().toISOString().split('T')[0];
  const invNo='INV-'+Date.now().toString().slice(-6);
  el.innerHTML=`<div class="page-header"><h2>🧾 Professional Invoice Generator</h2><p>Create and print professional invoices with company branding</p></div>
  <div style="display:grid;grid-template-columns:1fr 1fr;gap:20px;">
    <!-- Invoice Form -->
    <div class="card">
      <h3 style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:16px;">📝 Invoice Details</h3>
      <div style="display:grid;gap:10px;">
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">
          <div><label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Invoice #</label>
            <input id="pi-no" value="${invNo}" style="width:100%;padding:8px 10px;border:1.5px solid #d1d5db;border-radius:7px;font-size:12px;"></div>
          <div><label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Date</label>
            <input type="date" id="pi-date" value="${today}" style="width:100%;padding:8px 10px;border:1.5px solid #d1d5db;border-radius:7px;font-size:12px;"></div>
        </div>
        <div><label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Customer *</label>
          <select id="pi-cust" data-x-change="piUpdateCust()" style="width:100%;padding:8px 10px;border:1.5px solid #d1d5db;border-radius:7px;font-size:12px;">
            <option value="">-- Select Customer --</option>
            ${customers.map(c=>`<option value="${escHTML(c.name)}" data-phone="${escHTML(c.phone||'')}" data-addr="${escHTML(c.address||'')}">${escHTML(c.name)}</option>`).join('')}
          </select></div>
        <div id="pi-cust-info" style="background:#f9fafb;border-radius:7px;padding:8px;font-size:11px;color:#6b7280;display:none;"></div>
        <div><label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Due Date</label>
          <input type="date" id="pi-due" style="width:100%;padding:8px 10px;border:1.5px solid #d1d5db;border-radius:7px;font-size:12px;"></div>
        <div><label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Notes</label>
          <textarea id="pi-notes" rows="2" placeholder="Payment terms, delivery notes..." style="width:100%;padding:8px 10px;border:1.5px solid #d1d5db;border-radius:7px;font-size:12px;resize:vertical;"></textarea></div>
      </div>
      <h3 style="font-size:14px;font-weight:800;color:#0f3d26;margin:16px 0 12px;">📦 Line Items</h3>
      <div id="pi-items">
        <div class="pi-item" style="display:grid;grid-template-columns:2fr 1fr 1fr 1fr auto;gap:6px;margin-bottom:6px;align-items:center;">
          <select style="padding:7px 8px;border:1.5px solid #d1d5db;border-radius:6px;font-size:11px;" data-x-change="piCalcRow(this)">
            <option value="">-- Product --</option>
            ${products.map(p=>`<option value="${escHTML(p.name)}" data-rate="${p.rate||p.price||0}">${escHTML(p.name)}</option>`).join('')}
          </select>
          <input type="number" placeholder="Qty" value="1" style="padding:7px 8px;border:1.5px solid #d1d5db;border-radius:6px;font-size:11px;" data-x-input="piCalcRow(this)">
          <input type="number" placeholder="Rate" style="padding:7px 8px;border:1.5px solid #d1d5db;border-radius:6px;font-size:11px;" data-x-input="piCalcRow(this)">
          <input type="number" placeholder="Total" readonly style="padding:7px 8px;border:1.5px solid #bbf7d0;border-radius:6px;font-size:11px;background:#f0fdf4;font-weight:700;">
          <button data-x-click="this.closest('.pi-item').remove();piCalcTotal()" style="padding:5px 8px;background:#fee2e2;color:#dc2626;border:none;border-radius:6px;cursor:pointer;font-size:12px;">✕</button>
        </div>
      </div>
      <button data-x-click="piAddRow()" style="width:100%;padding:8px;background:#f0fdf4;border:1.5px dashed #16a34a;border-radius:7px;color:#16a34a;font-weight:700;cursor:pointer;font-size:12px;margin-top:6px;">+ Add Item</button>
      <div style="margin-top:12px;padding:12px;background:#f9fafb;border-radius:8px;">
        <div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:4px;"><span>Subtotal:</span><span id="pi-subtotal">৳0.00</span></div>
        <div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:4px;">
          <span>Discount: <input type="number" id="pi-disc" value="0" style="width:60px;padding:2px 6px;border:1px solid #d1d5db;border-radius:4px;font-size:11px;" data-x-input="piCalcTotal()">৳</span>
          <span id="pi-disc-val">-৳0.00</span>
        </div>
        <div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:4px;">
          <span>VAT: <input type="number" id="pi-vat" value="0" style="width:40px;padding:2px 6px;border:1px solid #d1d5db;border-radius:4px;font-size:11px;" data-x-input="piCalcTotal()">%</span>
          <span id="pi-vat-val">+৳0.00</span>
        </div>
        <div style="display:flex;justify-content:space-between;font-size:15px;font-weight:900;color:#0f3d26;border-top:2px solid #e5e7eb;padding-top:8px;margin-top:4px;"><span>TOTAL:</span><span id="pi-total">৳0.00</span></div>
      </div>
      <div style="display:flex;gap:8px;margin-top:14px;">
        <button data-x-click="piPrint()" style="flex:1;padding:10px;background:#16a34a;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:13px;">🖨️ Print Invoice</button>
        <button data-x-click="piSave()" style="flex:1;padding:10px;background:#2563eb;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:13px;">💾 Save Invoice</button>
      </div>
    </div>
    <!-- Invoice Preview -->
    <div>
      <div id="pi-preview" style="background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:28px;font-family:'Segoe UI',sans-serif;">
