          <div>
            <div style="font-size:22px;font-weight:900;color:#0f3d26;">🌾 ${company.companyName||'Rice Bran Oil Co.'}</div>
            <div style="font-size:11px;color:#6b7280;margin-top:4px;">${escHTML(company.address ||'Factory Address, Bangladesh')}</div>
            <div style="font-size:11px;color:#6b7280;">${escHTML(company.phone ||'')} ${company.email?'| '+escHTML(company.email):''}</div>
          </div>
          <div style="text-align:right;">
            <div style="font-size:24px;font-weight:900;color:#0f3d26;">INVOICE</div>
            <div style="font-size:13px;color:#6b7280;margin-top:4px;" id="prev-invno">#${invNo}</div>
            <div style="font-size:11px;color:#6b7280;" id="prev-date">Date: ${today}</div>
          </div>
        </div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-bottom:20px;">
          <div><div style="font-size:10px;font-weight:800;color:#6b7280;text-transform:uppercase;margin-bottom:4px;">Bill To:</div>
            <div id="prev-cust" style="font-size:13px;font-weight:700;color:#1a202c;">—</div></div>
          <div style="text-align:right;"><div style="font-size:10px;font-weight:800;color:#6b7280;text-transform:uppercase;margin-bottom:4px;">Due Date:</div>
            <div id="prev-due" style="font-size:13px;font-weight:700;color:#dc2626;">—</div></div>
        </div>
        <table style="width:100%;border-collapse:collapse;margin-bottom:16px;">
          <thead><tr style="background:#0f3d26;color:#fff;">
            <th style="padding:8px 10px;text-align:left;font-size:11px;">Item</th>
            <th style="padding:8px 10px;text-align:right;font-size:11px;">Qty</th>
            <th style="padding:8px 10px;text-align:right;font-size:11px;">Rate</th>
            <th style="padding:8px 10px;text-align:right;font-size:11px;">Amount</th>
          </tr></thead>
          <tbody id="prev-items"><tr><td colspan="4" style="padding:12px;text-align:center;color:#9ca3af;font-size:12px;">Add items to see preview</td></tr></tbody>
        </table>
        <div style="display:flex;justify-content:flex-end;">
          <div style="width:200px;">
            <div style="display:flex;justify-content:space-between;font-size:11px;padding:4px 0;"><span>Subtotal:</span><span id="prev-sub">৳0.00</span></div>
            <div style="display:flex;justify-content:space-between;font-size:11px;padding:4px 0;"><span>Discount:</span><span id="prev-disc">-৳0.00</span></div>
            <div style="display:flex;justify-content:space-between;font-size:11px;padding:4px 0;"><span>VAT:</span><span id="prev-vat">+৳0.00</span></div>
            <div style="display:flex;justify-content:space-between;font-size:14px;font-weight:900;padding:8px 0;border-top:2px solid #0f3d26;margin-top:4px;color:#0f3d26;"><span>TOTAL:</span><span id="prev-tot">৳0.00</span></div>
          </div>
        </div>
        <div style="margin-top:20px;padding-top:16px;border-top:1px solid #e5e7eb;">
          <div id="prev-notes" style="font-size:11px;color:#6b7280;"></div>
          <div style="margin-top:12px;font-size:10px;color:#9ca3af;text-align:center;">Thank you for your business! • ${company.companyName||'Rice Bran Oil Co.'}</div>
        </div>
      </div>
    </div>
  </div>`;
  piCalcTotal();
}

function piUpdateCust(){
  const sel=document.getElementById('pi-cust');
  const opt=sel.options[sel.selectedIndex];
  const info=document.getElementById('pi-cust-info');
  const prevCust=document.getElementById('prev-cust');
  if(sel.value){
    const phone=opt.dataset.phone;
    const addr=opt.dataset.addr;
    info.style.display='block';
    info.innerHTML=`<strong>${escHTML(sel.value)}</strong>${phone?' | 📞 '+escHTML(phone):''}${addr?'<br>'+escHTML(addr):''}`;
    if(prevCust) prevCust.innerHTML=`<strong>${escHTML(sel.value)}</strong>${phone?'<br><span style="font-size:11px;color:#6b7280;">'+escHTML(phone)+'</span>':''}`;
  } else {
    info.style.display='none';
    if(prevCust) prevCust.textContent='—';
  }
}

function piAddRow(){
  const products=DB.products||[];
  const container=document.getElementById('pi-items');
  const row=document.createElement('div');
  row.className='pi-item';
  row.style.cssText='display:grid;grid-template-columns:2fr 1fr 1fr 1fr auto;gap:6px;margin-bottom:6px;align-items:center;';
  row.innerHTML=`<select style="padding:7px 8px;border:1.5px solid #d1d5db;border-radius:6px;font-size:11px;" data-x-change="piCalcRow(this)">
    <option value="">-- Product --</option>
    ${products.map(p=>`<option value="${escHTML(p.name)}" data-rate="${p.rate||p.price||0}">${escHTML(p.name)}</option>`).join('')}
  </select>
  <input type="number" placeholder="Qty" value="1" style="padding:7px 8px;border:1.5px solid #d1d5db;border-radius:6px;font-size:11px;" data-x-input="piCalcRow(this)">
  <input type="number" placeholder="Rate" style="padding:7px 8px;border:1.5px solid #d1d5db;border-radius:6px;font-size:11px;" data-x-input="piCalcRow(this)">
  <input type="number" placeholder="Total" readonly style="padding:7px 8px;border:1.5px solid #bbf7d0;border-radius:6px;font-size:11px;background:#f0fdf4;font-weight:700;">
  <button data-x-click="this.closest('.pi-item').remove();piCalcTotal()" style="padding:5px 8px;background:#fee2e2;color:#dc2626;border:none;border-radius:6px;cursor:pointer;font-size:12px;">✕</button>`;
  container.appendChild(row);
}

function piCalcRow(el){
  const row=el.closest('.pi-item');
  const sel=row.querySelector('select');
  const opt=sel.options[sel.selectedIndex];
  const rateInput=row.querySelectorAll('input')[1];
  if(sel.value&&opt.dataset.rate&&!rateInput.value) rateInput.value=opt.dataset.rate;
  const qty=parseFloat(row.querySelectorAll('input')[0].value)||0;
  const rate=parseFloat(rateInput.value)||0;
  row.querySelectorAll('input')[2].value=(qty*rate).toFixed(2);
  piCalcTotal();
}

function piCalcTotal(){
  const pf2=v=>'৳'+(parseFloat(v)||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
  const rows=document.querySelectorAll('.pi-item');
  let sub=0;
  const previewRows=[];
  rows.forEach(row=>{
    const sel=row.querySelector('select');
    const inputs=row.querySelectorAll('input');
    const qty=parseFloat(inputs[0].value)||0;
    const rate=parseFloat(inputs[1].value)||0;
    const total=parseFloat(inputs[2].value)||0;
    sub+=total;
    if(sel.value) previewRows.push({name:sel.value,qty,rate,total});
  });
  const disc=parseFloat(document.getElementById('pi-disc')?.value)||0;
  const vatPct=parseFloat(document.getElementById('pi-vat')?.value)||0;
  const vatAmt=(sub-disc)*vatPct/100;
  const grand=sub-disc+vatAmt;
  const set=(id,v)=>{const e=document.getElementById(id);if(e)e.textContent=v;};
  set('pi-subtotal',pf2(sub)); set('pi-disc-val','-'+pf2(disc));
  set('pi-vat-val','+'+pf2(vatAmt)); set('pi-total',pf2(grand));
  set('prev-sub',pf2(sub)); set('prev-disc','-'+pf2(disc));
  set('prev-vat','+'+pf2(vatAmt)); set('prev-tot',pf2(grand));
  const tbody=document.getElementById('prev-items');
  if(tbody) tbody.innerHTML=previewRows.length?previewRows.map(r=>`<tr>
    <td style="padding:7px 10px;border-bottom:1px solid #f1f5f9;font-size:12px;">${escHTML(r.name)}</td>
    <td style="padding:7px 10px;border-bottom:1px solid #f1f5f9;font-size:12px;text-align:right;">${r.qty}</td>
    <td style="padding:7px 10px;border-bottom:1px solid #f1f5f9;font-size:12px;text-align:right;">${pf2(r.rate)}</td>
    <td style="padding:7px 10px;border-bottom:1px solid #f1f5f9;font-size:12px;text-align:right;font-weight:700;">${pf2(r.total)}</td>
  </tr>`).join(''):'<tr><td colspan="4" style="padding:12px;text-align:center;color:#9ca3af;font-size:12px;">No items added</td></tr>';
  const prevNotes=document.getElementById('prev-notes');
  const notes=document.getElementById('pi-notes')?.value;
  if(prevNotes&&notes) prevNotes.textContent=notes;
  const prevDue=document.getElementById('prev-due');
  const due=document.getElementById('pi-due')?.value;
  if(prevDue&&due) prevDue.textContent=due;
  const prevInvNo=document.getElementById('prev-invno');
  const invNo=document.getElementById('pi-no')?.value;
  if(prevInvNo&&invNo) prevInvNo.textContent='#'+invNo;
  const prevDate=document.getElementById('prev-date');
  const invDate=document.getElementById('pi-date')?.value;
  if(prevDate&&invDate) prevDate.textContent='Date: '+invDate;
}

function piPrint(){
  const preview=document.getElementById('pi-preview');
  if(!preview){alert('Invoice preview not found.');return;}
  const w=openPrintWindow(); if(!w) return;
  w.document.write(`<!DOCTYPE html><html><head><title>Invoice</title>
  <style>body{font-family:'Segoe UI',sans-serif;margin:20px;}table{width:100%;border-collapse:collapse;}
  th,td{padding:8px 10px;border:1px solid #e5e7eb;}th{background:#0f3d26;color:#fff;}
  @page{size:A4;margin:10mm 12mm;}@media print{html,body{max-width:100%!important;}*{overflow:visible!important;max-height:none!important;}img,svg,canvas{max-width:100%!important;height:auto!important;}table{width:100%!important;table-layout:auto!important;word-break:break-word;overflow-wrap:anywhere;}th,td{white-space:normal!important;overflow-wrap:anywhere;}.container,.voucher,.receipt,.doc,.page{max-width:100%!important;width:auto!important;}}table{page-break-inside:auto;}tr{page-break-inside:avoid;}thead{display:table-header-group;}@media print{body{margin:0;}}</style></head><body>${preview.innerHTML}</body></html>`);
  w.document.close();
  setTimeout(()=>w.print(),500);
  logAudit('PRINT','Invoice','Printed professional invoice');
}

function piSave(){
  const invNo=document.getElementById('pi-no')?.value;
  const cust=document.getElementById('pi-cust')?.value;
  const date=document.getElementById('pi-date')?.value;
  const total=parseFloat(document.getElementById('pi-total')?.textContent.replace(/[৳,]/g,''))||0;
  if(!cust){alert('Please select a customer.');return;}
  if(!total){alert('Please add items to the invoice.');return;}
  if(!DB.invoices) DB.invoices=[];
  DB.invoices.push({id:newId(),invNo,party:cust,date,total,status:'Unpaid',createdAt:new Date().toISOString()});
  saveDB();
  logAudit('CREATE','Invoice','Created invoice '+invNo+' for '+cust+' — ৳'+total);
  toast('✅ Invoice '+invNo+' saved!','s');
}

