        <input type="file" id="imp-file" accept=".csv,.txt" style="display:none;" data-x-change="impHandleFile(this)">
      </div>
      <button data-x-click="impDownloadTemplate()" style="width:100%;padding:9px;background:#f0fdf4;border:1.5px solid #16a34a;border-radius:8px;color:#16a34a;font-weight:700;cursor:pointer;font-size:12px;margin-bottom:8px;">
