    accent: '#64748b',
    bodyText: '#1e293b',
    borderLight: '#cbd5e1',
    bgLight: '#f1f5f9',
    headerBg: '#0f172a'
  },
  signatures: {
    prepared: 'Prepared By',
    checked: 'Checked By (Accounts)',
    supplier: 'Supplier Signature',
    authorized: 'Authorized Approval'
  }
};

window.AuditStamp = window.AuditStamp || {
  generate(range = '6 Months') {
    const now = new Date();
    let startDate = null;
    
    if (range === 'All-time') startDate = new Date('2000-01-01');
    else if (range === '6 Months') startDate = new Date(now.getTime() - 180*24*60*60*1000);
    else if (range === '1 Month') startDate = new Date(now.getTime() - 30*24*60*60*1000);
    else if (range === '7 Days') startDate = new Date(now.getTime() - 7*24*60*60*1000);
    
    const creatorName = (typeof window.MakerChecker !== 'undefined' && window.MakerChecker.actor) 
      ? (window.MakerChecker.actor()?.name || 'System')
      : 'System User';
    
    const dateRangeStr = startDate 
      ? `${startDate.toLocaleDateString('en-BD')} to ${now.toLocaleDateString('en-BD')}`
      : 'All-time';
    
    return {
      printedAt: now.toLocaleString('en-BD', { 
        year: 'numeric', month: 'short', day: 'numeric',
        hour: '2-digit', minute: '2-digit', second: '2-digit'
      }),
      dateRange: dateRangeStr,
      creator: creatorName
    };
  }
};

