    .items-section{padding:0 28px;margin:24px 0;}
    table{width:100%;border-collapse:collapse;}
    thead{background:${cfg.theme.primary};color:#fff;}
    th{padding:12px 14px;text-align:left;font-size:11px;font-weight:900;letter-spacing:0.3px;text-transform:uppercase;border:none;}
