    .total-row:last-child{border:none;}
    .total-label{color:${cfg.theme.accent};font-weight:600;}
    .total-amount{color:${cfg.theme.bodyText};font-weight:700;text-align:right;}
    .grand-total{display:flex;justify-content:space-between;padding:12px 0;font-size:16px;font-weight:900;color:${cfg.theme.primary};border-top:2px solid ${cfg.theme.primary};margin-top:8px;padding-top:12px;}
