          <div>Date: <strong>${tx.date||new Date().toISOString().split('T')[0]}</strong></div>
        </div>
      </div>
    </div>
    <div class="audit-stamp">
      <div class="audit-label">📋 Audit</div>
      <div><strong>${audit.dateRange}</strong></div>
      <div>Printed: ${audit.printedAt}</div>
      <div>By: ${audit.creator}</div>
    </div>
    <div class="bill-section">
      <div>
        <div class="bill-label">Bill To</div>
        <div class="bill-value">${escHTML(tx.party||'—')}</div>
        <div class="bill-detail">${escHTML((DB.customers||[]).find(c=>c.name===tx.party)?.phone||'')}</div>
      </div>
      <div style="text-align:right;">
        <div class="bill-label">Transaction Type</div>
        <div class="bill-value">${tx.type||'Sale'}</div>
        <div class="status-badge">✅ ${tx.status||'Completed'}</div>
      </div>
    </div>
    <div class="items-section">
      <table>
        <thead><tr><th>Description</th><th>Product</th><th style="text-align:right;">Qty</th><th style="text-align:right;">Rate (৳)</th><th style="text-align:right;">Amount (৳)</th></tr></thead>
        <tbody>
          <tr>
            <td>${tx.type||'Sale'}</td>
            <td>${tx.product||tx.item||'—'}</td>
            <td style="text-align:right;">${tx.qty||1} ${escHTML(tx.unit||'')}</td>
            <td style="text-align:right;">${(tx.rate||0).toLocaleString('en-IN',{minimumFractionDigits:2})}</td>
            <td style="text-align:right;"><strong>${txAmt(tx).toLocaleString('en-IN',{minimumFractionDigits:2})}</strong></td>
          </tr>
        </tbody>
