    <div class="totals-section">
      <div class="totals-box">
        <div class="total-row">
          <span class="total-label">Subtotal:</span>
          <span class="total-amount">৳${txAmt(tx).toLocaleString('en-IN',{minimumFractionDigits:2})}</span>
        </div>
        <div class="total-row">
          <span class="total-label">Discount:</span>
          <span class="total-amount">৳0.00</span>
        </div>
        <div class="total-row">
          <span class="total-label">Tax:</span>
          <span class="total-amount">৳0.00</span>
        </div>
        <div class="grand-total">
          <span>TOTAL:</span>
          <span>৳${txAmt(tx).toLocaleString('en-IN',{minimumFractionDigits:2})}</span>
        </div>
