        ${(ch.items||[{name:ch.product||'Product',qty:ch.qty||1,unit:ch.unit||'Piece'}]).map((item,i)=>`
        <tr>
          <td>${i+1}</td>
          <td>${escHTML(item.name||item.product||'—')}</td>
          <td style="text-align:right;"><strong>${item.qty||1}</strong></td>
