        <div class="company-contact">
          <div>📞 ${escHTML(prtCo().phone)}</div>
          <div>📧 ${escHTML(prtCo().email)}</div>
        </div>
      </div>
      <div style="text-align:right;">
        <div class="ledger-title">SUPPLIER LEDGER</div>
      </div>
    </div>
    <div class="audit-stamp">
      <div class="audit-label">📋 Audit</div>
      <div style="font-size:9px;margin:2px 0;">${audit.dateRange}</div>
      <div style="font-size:9px;">By: ${audit.creator}</div>
    </div>
    <div class="info-grid">
      <div class="info-card">
        <div class="info-title">Supplier Profile</div>
        <div class="info-item"><span class="info-label">Name:</span><span class="info-value">${escHTML(supplier.name)}</span></div>
        <div class="info-item"><span class="info-label">Contact:</span><span class="info-value">${escHTML(supplier.phone||'—')}</span></div>
        <div class="info-item"><span class="info-label">Address:</span><span class="info-value">${escHTML(supplier.address||'—')}</span></div>
        <div class="info-item"><span class="info-label">Opening Balance:</span><span class="info-value">৳${(supplier.bal||0).toLocaleString('en-IN',{minimumFractionDigits:2})}</span></div>
      </div>
      <div class="info-card">
        <div class="info-title">Bank Account</div>
        <div class="banking-section">
          <div class="banking-item"><span class="info-label">Bank Code:</span><span class="info-value">${(supplier.bankName||'').substring(0,3).toUpperCase()||'—'}</span></div>
          <div class="banking-item"><span class="info-label">Account #:</span><span class="info-value">${supplier.accountNumber||'—'}</span></div>
        </div>
      </div>
    </div>
    <div class="transactions-section">
      <table>
        <thead><tr><th>Date</th><th>Type</th><th>Description</th><th style="text-align:right;">Amount (৳)</th></tr></thead>
        <tbody>
          ${txs.length>0?txs.map(tx=>`<tr><td>${tx.date||'—'}</td><td>${tx.type||'—'}</td><td>${escHTML(tx.product||tx.item||'—')}</td><td class="amount">৳${txAmt(tx).toLocaleString('en-IN',{minimumFractionDigits:2})}</td></tr>`).join(''):`<tr><td colspan="4" style="text-align:center;padding:20px;">No transactions found</td></tr>`}
        </tbody>
      </table>
    </div>
    <div class="summary-section">
      <div class="summary-item">
        <div class="summary-label">Opening Balance</div>
        <div class="summary-value">৳${(supplier.bal||0).toLocaleString('en-IN',{minimumFractionDigits:2})}</div>
      </div>
      <div class="summary-item">
        <div class="summary-label">Total Transactions</div>
        <div class="summary-value">${txs.length}</div>
      </div>
      <div class="summary-item">
        <div class="summary-label">Closing Balance</div>
        <div class="summary-value">৳${(parseFloat(supplier.bal||0)+txs.reduce((s,t)=>s+txAmt(t),0)).toLocaleString('en-IN',{minimumFractionDigits:2})}</div>
      </div>
    </div>
  </div>
  </body></html>`;
  const w=openPrintWindow(); if(!w) return;
  w.document.write(html);
  w.document.close();
  setTimeout(()=>w.print(),600);
  logAudit('PRINT','Ledger','Printed supplier ledger for '+supplier.name);
}

function printPurchaseOrder(poId){
  /* FIX (Purchase Order never printed): this looked for t.type==='PO' or
     t.poNo. There is no 'PO' transaction type in this app, and `poNo`
     appeared nowhere else in the file — the PO Number input writes t.po.
     Both halves of the test were always false, so every attempt ended at
     the "Purchase Order not found." alert. Now: the requested PO if an id
     was passed, else the newest purchase that carries a PO number, else
     the newest purchase. */
  const _purch=(DB.tx||[]).filter(t=>{ try{ return window.isCogsTx(t); }catch(e){ return false; } });
  const po=(poId!=null&&(DB.tx||[]).find(t=>String(t.id)===String(poId)))
        || _purch.filter(t=>t.po).slice(-1)[0]
        || _purch.slice(-1)[0]
        || {};
  if(!po.party){alert('Purchase Order not found.');return;}
  const co=DB.settings||{};
  const cfg=window.ERPPrintConfig;
  const audit=window.AuditStamp.generate('1 Month');
  const html=`<!DOCTYPE html><html><head><meta charset="UTF-8"><title>PO</title><style>*{margin:0;padding:0;box-sizing:border-box;}html,body{font-family:'Inter','Segoe UI',system-ui,sans-serif;color:${cfg.theme.bodyText};background:#fff;}@page{size:A4;margin:10mm 12mm;}@media print{html,body{max-width:100%!important;}*{overflow:visible!important;max-height:none!important;}img,svg,canvas{max-width:100%!important;height:auto!important;}table{width:100%!important;table-layout:auto!important;word-break:break-word;overflow-wrap:anywhere;}th,td{white-space:normal!important;overflow-wrap:anywhere;}.container,.voucher,.receipt,.doc,.page{max-width:100%!important;width:auto!important;}}@media print{body{padding:15px;margin:0;}table{page-break-inside:avoid;}tr{page-break-inside:avoid;}}.container{max-width:900px;margin:auto;background:#fff;border-radius:12px;overflow:hidden;position:relative;}.header{display:grid;grid-template-columns:2fr 1fr;gap:24px;padding:28px;border-bottom:3px solid ${cfg.theme.secondary};background:linear-gradient(135deg,${cfg.theme.bgLight},#fff);}.company-legal{font-size:18px;font-weight:900;color:${cfg.theme.secondary};}.company-contact{font-size:11px;color:${cfg.theme.accent};margin-top:8px;}.po-title{font-size:32px;font-weight:900;color:${cfg.theme.secondary};text-align:right;}.audit-stamp{position:absolute;top:20px;right:20px;background:${cfg.theme.bgLight};border:2px solid ${cfg.theme.secondary};border-radius:8px;padding:10px 14px;font-size:9px;}.audit-label{font-weight:700;color:${cfg.theme.secondary};text-transform:uppercase;font-size:8px;}.info-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px;padding:24px 28px;background:#fff;border-bottom:1px solid ${cfg.theme.borderLight};}.info-block{display:flex;flex-direction:column;gap:4px;}.info-label{font-size:10px;font-weight:900;color:${cfg.theme.accent};text-transform:uppercase;}.info-value{font-size:14px;font-weight:700;color:${cfg.theme.bodyText};}.info-detail{font-size:11px;color:${cfg.theme.accent};margin-top:2px;}table{width:100%;border-collapse:collapse;margin:24px 28px;}thead{background:${cfg.theme.secondary};color:#fff;}th{padding:12px 14px;text-align:left;font-size:11px;font-weight:900;}tbody tr{border-bottom:1px solid ${cfg.theme.borderLight};}td{padding:10px 14px;font-size:12px;}.totals-section{display:flex;justify-content:flex-end;padding:24px 28px;background:${cfg.theme.bgLight};}.totals-box{width:280px;}.total-row{display:flex;justify-content:space-between;padding:8px 0;font-size:12px;border-bottom:1px solid ${cfg.theme.borderLight};}.grand-total{display:flex;justify-content:space-between;padding:12px 0;font-size:16px;font-weight:900;color:${cfg.theme.secondary};border-top:2px solid ${cfg.theme.secondary};}.auth-section{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;padding:32px 28px;}.sig-line{border-top:1.5px solid ${cfg.theme.bodyText};margin-top:50px;padding-top:8px;font-size:11px;font-weight:700;}.terms{padding:20px 28px;background:${cfg.theme.bgLight};font-size:10px;color:${cfg.theme.accent};}</style></head><body><div class="container"><div class="header"><div><div class="company-legal">${escHTML(prtCo().name)}</div><div class="company-contact">${prtContact()}</div></div><div><div class="po-title">PURCHASE ORDER</div><div style="font-size:12px;color:#6b7280;text-align:right;margin-top:4px;">${escHTML(po.po||po.inv||('#'+(po.id||'')))} &nbsp;·&nbsp; ${escHTML(po.date||'')}</div></div></div><div class="audit-stamp"><div class="audit-label">AUDIT</div><div style="font-size:9px;margin:2px 0;">${audit.dateRange}</div></div><div class="info-grid"><div class="info-block"><div class="info-label">Supplier</div><div class="info-value">${escHTML(po.party||'—')}</div><div class="info-detail">${escHTML(po.address||'')}</div></div></div><table><thead><tr><th>Description</th><th>Product</th><th style="text-align:right;">Qty</th><th style="text-align:right;">Rate (৳)</th><th style="text-align:right;">Amount (৳)</th></tr></thead><tbody><tr><td>${po.type||'—'}</td><td>${po.product||'—'}</td><td style="text-align:right;">${po.qty||1}</td><td style="text-align:right;">${(po.rate||0).toLocaleString('en-IN',{minimumFractionDigits:2})}</td><td style="text-align:right;"><strong>${txAmt(po).toLocaleString('en-IN',{minimumFractionDigits:2})}</strong></td></tr></tbody></table><div class="totals-section"><div class="totals-box"><div class="total-row"><span>Subtotal:</span><span>৳${txAmt(po).toLocaleString('en-IN',{minimumFractionDigits:2})}</span></div><div class="grand-total"><span>TOTAL:</span><span>৳${txAmt(po).toLocaleString('en-IN',{minimumFractionDigits:2})}</span></div></div></div><div class="auth-section"><div style="text-align:center;"><div style="height:45px;"></div><div class="sig-line">${cfg.signatures.prepared}</div></div><div style="text-align:center;"><div style="height:45px;"></div><div class="sig-line">Supplier Confirm</div></div><div style="text-align:center;"><div style="height:45px;"></div><div class="sig-line">${cfg.signatures.authorized}</div></div></div><div class="terms"><strong>Terms:</strong> Payment due within 30 days.</div></div></body></html>`;
  const w=openPrintWindow(); if(!w) return; w.document.write(html); w.document.close(); setTimeout(()=>w.print(),600); logAudit('PRINT','PO','Printed PO from '+po.party);
}

function printPaymentReceipt(txId){
  /* FIX (Payment Receipt never printed): the old list — 'Sales Receipt',
     'Cash Received', 'Payment Received' — contains no transaction type this
     app uses. Real customer receipts are Customer Collection, Customer
     Payment Received, Advance from Customer and the bKash receives. */
  const tx=(DB.tx||[]).find(t=>t.id===txId)||(DB.tx||[]).filter(prtIsReceipt).slice(-1)[0];
  if(!tx){alert('Receipt not found.');return;}
  const co=DB.settings||{};
  const receiptNo='RCP-'+String(tx.id||Date.now()).slice(-6);
  const html=`<!DOCTYPE html><html><head><title>Payment Receipt</title>
