    .amount-label{font-size:11px;color:#6b7280;font-weight:700;text-transform:uppercase;}
    .amount-value{font-size:28px;font-weight:900;color:#16a34a;margin-top:4px;}
    .receipt-footer{background:#f9fafb;padding:16px;text-align:center;font-size:11px;color:#6b7280;}
    .sig-line{border-top:1px solid #374151;margin-top:30px;padding-top:6px;font-size:11px;color:#6b7280;text-align:center;}
    @page{size:A4;margin:10mm 12mm;}@media print{html,body{max-width:100%!important;}*{overflow:visible!important;max-height:none!important;}img,svg,canvas{max-width:100%!important;height:auto!important;}table{width:100%!important;table-layout:auto!important;word-break:break-word;overflow-wrap:anywhere;}th,td{white-space:normal!important;overflow-wrap:anywhere;}.container,.voucher,.receipt,.doc,.page{max-width:100%!important;width:auto!important;}}table{page-break-inside:auto;}tr{page-break-inside:avoid;}thead{display:table-header-group;}@media print{body{padding:0;}.receipt{border:2px solid #0f3d26;}}
  </style></head><body>
  <div class="receipt">
    <div class="receipt-header">
      <div style="font-size:20px;font-weight:900;">🌾 ${escHTML(prtCo().name)}</div>
      <div style="font-size:12px;opacity:.8;margin-top:4px;">PAYMENT RECEIPT</div>
    </div>
    <div class="receipt-body">
      <div class="receipt-row"><span style="color:#6b7280;">Receipt No:</span><span style="font-weight:700;">${receiptNo}</span></div>
