      <div class="receipt-row"><span style="color:#6b7280;">Received From:</span><span style="font-weight:700;">${escHTML(tx.party ||'—')}</span></div>
      <div class="receipt-row"><span style="color:#6b7280;">Payment Type:</span><span style="font-weight:700;">${tx.type||'Receipt'}</span></div>
      <div class="receipt-row"><span style="color:#6b7280;">Payment Mode:</span><span style="font-weight:700;">${escHTML(tx.mode||tx.bank||'Cash')}</span></div>
      ${tx.note||tx.desc?`<div class="receipt-row"><span style="color:#6b7280;">Note:</span><span>${escHTML(tx.note||tx.desc)}</span></div>`:''}
      <div class="amount-box">
        <div class="amount-label">Amount Received</div>
        <div class="amount-value">৳${txAmt(tx).toLocaleString('en-IN',{minimumFractionDigits:2})}</div>
      </div>
      <div class="sig-line">Authorized Signature</div>
    </div>
    <div class="receipt-footer">
      Thank you! • ${escHTML(prtCo().name)} • ${escHTML(prtCo().phone)}
    </div>
  </div>
  </body></html>`;
  const cfg=window.ERPPrintConfig;
  const audit=window.AuditStamp.generate('1 Month');
  const newHtml=`<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Receipt</title><style>*{margin:0;padding:0;box-sizing:border-box;}html,body{font-family:'Inter','Segoe UI',system-ui,sans-serif;color:${cfg.theme.bodyText};background:#fff;}@page{size:A4;margin:10mm 12mm;}@media print{html,body{max-width:100%!important;}*{overflow:visible!important;max-height:none!important;}img,svg,canvas{max-width:100%!important;height:auto!important;}table{width:100%!important;table-layout:auto!important;word-break:break-word;overflow-wrap:anywhere;}th,td{white-space:normal!important;overflow-wrap:anywhere;}.container,.voucher,.receipt,.doc,.page{max-width:100%!important;width:auto!important;}}.container{max-width:600px;margin:auto;background:#fff;border-radius:12px;overflow:hidden;position:relative;}.header{padding:28px;border-bottom:3px solid #16a34a;background:linear-gradient(135deg,${cfg.theme.bgLight},#fff);text-align:center;}.company-legal{font-size:18px;font-weight:900;color:#16a34a;}.receipt-title{font-size:28px;font-weight:900;color:#16a34a;margin:12px 0;}.audit-stamp{position:absolute;top:20px;right:20px;background:${cfg.theme.bgLight};border:2px solid #16a34a;border-radius:8px;padding:10px 14px;font-size:9px;}.audit-label{font-weight:700;color:#16a34a;text-transform:uppercase;font-size:8px;}.receipt-body{padding:24px 28px;}.row{display:flex;justify-content:space-between;padding:8px 0;font-size:12px;border-bottom:1px solid ${cfg.theme.borderLight};}.row-label{color:${cfg.theme.accent};font-weight:600;}.row-value{color:${cfg.theme.bodyText};font-weight:700;}.amount-box{background:#16a34a15;border:1px solid #16a34a;border-radius:8px;padding:16px;text-align:center;margin:16px 0;}.amount-label{font-size:11px;font-weight:900;color:${cfg.theme.accent};text-transform:uppercase;}.amount-value{font-size:28px;font-weight:900;color:#16a34a;margin-top:6px;}.payment-method{background:${cfg.theme.bgLight};padding:12px;border-radius:6px;margin-top:12px;font-size:11px;}.footer{padding:16px 28px;background:${cfg.theme.bgLight};text-align:center;font-size:10px;color:${cfg.theme.accent};border-top:1px solid ${cfg.theme.borderLight};}.thank-you{font-size:14px;font-weight:900;color:#16a34a;margin:12px 0;}</style></head><body><div class="container"><div class="header"><div class="company-legal">${escHTML(prtCo().name)}</div><div class="receipt-title">💳 PAYMENT RECEIPT</div></div><div class="audit-stamp"><div class="audit-label">📋 Audit</div><div style="font-size:9px;margin:2px 0;">${audit.dateRange}</div></div><div class="receipt-body"><div style="font-size:11px;font-weight:900;color:#16a34a;text-transform:uppercase;margin-bottom:8px;">Transaction Details</div><div class="row"><span class="row-label">Receipt Date:</span><span class="row-value">${tx.date||new Date().toISOString().split('T')[0]}</span></div><div class="row"><span class="row-label">From:</span><span class="row-value">${escHTML(tx.party||'—')}</span></div><div class="row"><span class="row-label">Type:</span><span class="row-value">${tx.type||'Payment'}</span></div><div class="amount-box"><div class="amount-label">Amount Received</div><div class="amount-value">৳${txAmt(tx).toLocaleString('en-IN',{minimumFractionDigits:2})}</div></div><div style="font-size:11px;font-weight:900;color:#16a34a;text-transform:uppercase;margin:16px 0 8px 0;">Payment Info</div><div class="payment-method"><strong>Method:</strong> ${escHTML(tx.mode||tx.bank||'Cash')}<br/><strong>Status:</strong> ✅ ${tx.status||'Completed'}</div><div class="thank-you">✅ Payment Recorded</div></div><div class="footer"><div>Thank you for your payment</div><div>${escHTML(prtCo().name)}</div></div></div></body></html>`;
  const w=openPrintWindow(); if(!w) return;
  w.document.write(newHtml);
  w.document.close();
  setTimeout(()=>w.print(),600);
  logAudit('PRINT','Receipt','Printed payment receipt for '+tx.party);
}

function printSalarySlipFor(empName, month){
  const emp=(DB.employees||[]).find(e=>e.name===empName)||{name:empName};
  const co=DB.settings||{};
