  const html=`<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Salary Slip</title><style>*{margin:0;padding:0;box-sizing:border-box;}html,body{font-family:'Inter','Segoe UI',system-ui,sans-serif;color:${cfg.theme.bodyText};background:#fff;}@page{size:A4;margin:10mm 12mm;}@media print{html,body{max-width:100%!important;}*{overflow:visible!important;max-height:none!important;}img,svg,canvas{max-width:100%!important;height:auto!important;}table{width:100%!important;table-layout:auto!important;word-break:break-word;overflow-wrap:anywhere;}th,td{white-space:normal!important;overflow-wrap:anywhere;}.container,.voucher,.receipt,.doc,.page{max-width:100%!important;width:auto!important;}}.container{max-width:900px;margin:auto;background:#fff;border-radius:12px;overflow:hidden;position:relative;}.header{padding:28px;border-bottom:3px solid #7c3aed;background:linear-gradient(135deg,${cfg.theme.bgLight},#fff);display:grid;grid-template-columns:2fr 1fr;gap:24px;}.company-legal{font-size:18px;font-weight:900;color:#7c3aed;}.company-contact{font-size:11px;color:${cfg.theme.accent};margin-top:8px;}.slip-title{font-size:28px;font-weight:900;color:#7c3aed;text-align:right;}.slip-meta{font-size:12px;color:${cfg.theme.accent};text-align:right;margin-top:8px;}.audit-stamp{position:absolute;top:20px;right:20px;background:${cfg.theme.bgLight};border:2px solid #7c3aed;border-radius:8px;padding:10px 14px;font-size:9px;}.audit-label{font-weight:700;color:#7c3aed;text-transform:uppercase;font-size:8px;}.emp-info{display:grid;grid-template-columns:1fr 1fr;gap:24px;padding:24px 28px;background:#fff;border-bottom:1px solid ${cfg.theme.borderLight};}.info-block{display:flex;flex-direction:column;gap:8px;}.info-label{font-size:10px;font-weight:900;color:${cfg.theme.accent};text-transform:uppercase;}.info-value{font-size:14px;font-weight:700;color:${cfg.theme.bodyText};}.salary-section{padding:24px 28px;}table{width:100%;border-collapse:collapse;}thead{background:#7c3aed;color:#fff;}th{padding:12px 14px;text-align:left;font-size:11px;font-weight:900;}tbody tr{border-bottom:1px solid ${cfg.theme.borderLight};}td{padding:10px 14px;font-size:12px;}.label-cell{font-weight:600;color:${cfg.theme.accent};}.amount-cell{text-align:right;font-weight:700;color:${cfg.theme.bodyText};}.summary-row{display:grid;grid-template-columns:1fr 1fr;gap:20px;padding:20px 28px;background:${cfg.theme.bgLight};border-top:2px solid ${cfg.theme.borderLight};}.summary-box{display:flex;justify-content:space-between;padding:8px 0;font-size:12px;}.summary-label{color:${cfg.theme.accent};font-weight:600;}.summary-value{font-weight:900;color:#7c3aed;}.auth-section{display:grid;grid-template-columns:1fr 1fr;gap:20px;padding:32px 28px;background:#fff;border-top:2px solid ${cfg.theme.borderLight};}.auth-box{text-align:center;}.sig-line{border-top:1.5px solid ${cfg.theme.bodyText};margin-top:50px;padding-top:8px;font-size:11px;font-weight:700;color:${cfg.theme.bodyText};}</style></head><body><div class="container"><div class="header"><div><div class="company-legal">${escHTML(prtCo().name)}</div><div class="company-contact"><div>📞 ${escHTML(prtCo().phone)}</div><div>HR Department</div></div></div><div><div class="slip-title">SALARY SLIP</div><div class="slip-meta"><div>Month: <strong>${month||new Date().toLocaleString('default',{month:'long',year:'numeric'})}</strong></div></div></div></div><div class="audit-stamp"><div class="audit-label">📋 Audit</div><div style="font-size:9px;margin:2px 0;">${audit.dateRange}</div></div><div class="emp-info"><div class="info-block"><div class="info-label">Employee Name</div><div class="info-value">${escHTML(emp.name)}</div><div style="font-size:11px;color:${cfg.theme.accent};margin-top:4px;">ID: ${emp.empId||emp.id||'—'}</div></div><div class="info-block"><div class="info-label">Designation & Department</div><div class="info-value">${escHTML(emp.designation||'—')}</div><div style="font-size:11px;color:${cfg.theme.accent};margin-top:4px;">${emp.department||'—'}</div></div></div><div class="salary-section"><table><thead><tr><th>Earnings</th><th style="text-align:right;">Amount (৳)</th></tr></thead><tbody><tr><td class="label-cell">Basic Salary</td><td class="amount-cell">${basicSal.toLocaleString('en-IN',{minimumFractionDigits:2})}</td></tr><tr><td class="label-cell">House Allowance</td><td class="amount-cell">${(emp.houseAllow||0).toLocaleString('en-IN',{minimumFractionDigits:2})}</td></tr><tr><td class="label-cell">Other Allowances</td><td class="amount-cell">${(emp.otherAllow||0).toLocaleString('en-IN',{minimumFractionDigits:2})}</td></tr></tbody></table><table style="margin-top:20px;"><thead><tr><th>Deductions</th><th style="text-align:right;">Amount (৳)</th></tr></thead><tbody><tr><td class="label-cell">Tax</td><td class="amount-cell">${(emp.tax||0).toLocaleString('en-IN',{minimumFractionDigits:2})}</td></tr><tr><td class="label-cell">Provident Fund</td><td class="amount-cell">${(emp.pf||0).toLocaleString('en-IN',{minimumFractionDigits:2})}</td></tr><tr><td class="label-cell">Other Deductions</td><td class="amount-cell">${(emp.otherDed||0).toLocaleString('en-IN',{minimumFractionDigits:2})}</td></tr></tbody></table></div><div class="summary-row"><div><div class="summary-box"><span class="summary-label">Gross Salary:</span><span class="summary-value">৳${((emp.basicSalary||0)+(emp.houseAllow||0)+(emp.otherAllow||0)).toLocaleString('en-IN',{minimumFractionDigits:2})}</span></div></div><div><div class="summary-box"><span class="summary-label">Total Deductions:</span><span class="summary-value">৳${((emp.tax||0)+(emp.pf||0)+(emp.otherDed||0)).toLocaleString('en-IN',{minimumFractionDigits:2})}</span></div></div></div><div class="summary-row" style="background:#7c3aed15;border-top:2px solid #7c3aed;"><div style="grid-column:1/-1;display:flex;justify-content:space-between;padding:12px 0;font-size:14px;font-weight:900;color:#7c3aed;"><span>NET SALARY:</span><span>৳${(((emp.basicSalary||0)+(emp.houseAllow||0)+(emp.otherAllow||0))-((emp.tax||0)+(emp.pf||0)+(emp.otherDed||0))).toLocaleString('en-IN',{minimumFractionDigits:2})}</span></div></div><div class="auth-section"><div class="auth-box"><div style="height:45px;"></div><div class="sig-line">Employee Signature</div></div><div class="auth-box"><div style="height:45px;"></div><div class="sig-line">HR Manager</div></div></div></div></body></html>`;
  const w=openPrintWindow(); if(!w) return;
  w.document.write(html);
  w.document.close();
  setTimeout(()=>w.print(),600);
  logAudit('PRINT','Salary Slip','Printed salary slip for '+empName+' — '+month);
}

