function impHandleDrop(e){
  const file=e.dataTransfer.files[0];
  if(file) impProcessFile(file);
}

function impHandleFile(inp){
  const file=inp.files[0];
  if(file) impProcessFile(file);
}

function impProcessFile(file){
  const status=document.getElementById('imp-status');
  if(status) status.textContent='Reading file...';
  const reader=new FileReader();
  reader.onload=e=>{
    const text=e.target.result;
    const lines=text.trim().split('\n').filter(l=>l.trim());
    if(lines.length<2){if(status)status.textContent='❌ File must have at least a header row and one data row.';return;}
    const headers=lines[0].split(',').map(h=>h.trim().replace(/"/g,''));
    const rows=lines.slice(1).map(line=>{
      const vals=line.split(',').map(v=>v.trim().replace(/"/g,''));
      const obj={};
      headers.forEach((h,i)=>obj[h]=vals[i]||'');
      return obj;
    });
    window._impRows=rows;
    window._impHeaders=headers;
    const preview=document.getElementById('imp-preview');
    const wrap=document.getElementById('imp-preview-wrap');
    if(preview&&wrap){
      wrap.style.display='block';
      const previewRows=rows.slice(0,5);
      preview.innerHTML=`<div style="font-size:11px;color:#6b7280;margin-bottom:6px;">${rows.length} rows found (showing first 5)</div>
        <table style="width:100%;border-collapse:collapse;font-size:11px;">
          <thead><tr>${headers.map(h=>`<th style="padding:6px 8px;background:#0f3d26;color:#fff;text-align:left;">${h}</th>`).join('')}</tr></thead>
          <tbody>${previewRows.map(r=>`<tr>${headers.map(h=>`<td style="padding:5px 8px;border-bottom:1px solid #f1f5f9;">${r[h]||'—'}</td>`).join('')}</tr>`).join('')}</tbody>
        </table>`;
    }
    if(status) status.textContent=`✅ ${rows.length} rows ready to import`;
  };
  reader.readAsText(file);
}

function impConfirm(){
  const type=document.getElementById('imp-type')?.value||'transactions';
  const rows=window._impRows||[];
  if(!rows.length){alert('No data to import.');return;}
  let imported=0;
  if(type==='transactions'){
    if(!DB.tx) DB.tx=[];
    rows.forEach(r=>{
      if(!r.date||!r.type) return;
      DB.tx.push({id:newId(),date:r.date,type:r.type,party:r.party||'',product:r.product||'',qty:parseFloat(r.qty)||0,rate:parseFloat(r.rate)||0,amt:parseFloat(r.amount)||0,amount:parseFloat(r.amount)||0,mode:r.mode||'Cash',note:r.note||''});
      imported++;
    });
  } else if(type==='customers'){
    if(!DB.customers) DB.customers=[];
    rows.forEach(r=>{
      if(!r.name) return;
      if(!(DB.customers||[]).find(c=>c.name===r.name)){
        DB.customers.push({id:newId(),name:r.name,type:r.type||'Customer',phone:r.phone||'',address:r.address||'',bal:parseFloat(r.balance)||0});
        imported++;
      }
    });
  } else if(type==='products'){
    if(!DB.products) DB.products=[];
    rows.forEach(r=>{
      if(!r.name) return;
      if(!(DB.products||[]).find(p=>p.name===r.name)){
        DB.products.push({id:newId(),name:r.name,cat:r.category||'',qty:parseFloat(r.qty)||0,rate:parseFloat(r.rate)||0,unit:r.unit||'Piece',minStock:parseFloat(r.minStock)||10});
        imported++;
      }
    });
  } else if(type==='banks'){
    if(!DB.banks) DB.banks=[];
    rows.forEach(r=>{
      if(!r.name) return;
      if(!(DB.banks||[]).find(b=>b.name===r.name)){
        DB.banks.push({id:newId(),name:r.name,accountNo:r.accountNo||'',bal:parseFloat(r.balance)||0});
        imported++;
      }
    });
  }
  saveDB();
  logAudit('IMPORT','Data Import',`Imported ${imported} ${type} records from CSV`);
  toast(`✅ Successfully imported ${imported} ${type} records!`,'s');
  window._impRows=[];
  const wrap=document.getElementById('imp-preview-wrap');
  if(wrap) wrap.style.display='none';
  const status=document.getElementById('imp-status');
  if(status) status.textContent=`✅ ${imported} records imported successfully!`;
  renderCsvImport();
}

function impCancel(){
  window._impRows=[];
  const wrap=document.getElementById('imp-preview-wrap');
  if(wrap) wrap.style.display='none';
  const status=document.getElementById('imp-status');
  if(status) status.textContent='';
}

function impDownloadTemplate(){
  const type=document.getElementById('imp-type')?.value||'transactions';
  const templates={
    transactions:'date,type,party,product,qty,rate,amount,mode,note\r\n2024-01-15,Sale,Ahmed Store,Rice Bran Oil 15L,10,1200,12000,Cash,\r\n',
    customers:'name,type,phone,address,balance\r\nAhmed Store,Customer,01711000000,Dhaka,0\r\n',
    products:'name,category,qty,rate,unit,minStock\r\nRice Bran Oil 15L,Oil,100,1200,Piece,10\r\n',
    banks:'name,accountNo,balance\r\nMain Bank Account,1234567890,500000\r\n'
  };
  const csv=templates[type]||'';
  const blob=new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'});
  const a=document.createElement('a');
  a.href=URL.createObjectURL(blob);
  a.download=`template_${type}.csv`;
  a.click();
  logAudit('EXPORT','Template','Downloaded CSV template for '+type);
}
