/* Single source of truth for the Staff Quick Entry modals (bKash Receive + Log Expense).
   Used by renderStaffDash() (Staff Dashboard) and ensureStaffModals() (Mobile Dashboard,
   floating action bar), so the markup and the ids (sbk-..., sexp-..., staff-...-modal) only
   exist in one place instead of two, which is what was causing the duplicate-id situation. */
function staffQuickModalsHTML(bg, border, textColor, text2) {
  const inp = `width:100%;padding:10px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};`;
  const lab = `font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;`;
  return `
    <!-- Staff Quick Entry Modals -->
    <div id="staff-bkash-modal" style="display:none;position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:2000;align-items:center;justify-content:center;">
      <div style="background:${bg};border-radius:16px;width:90%;max-width:420px;color:${textColor};box-shadow:0 8px 40px rgba(0,0,0,.3);">
        <div style="background:linear-gradient(135deg,#be185d,#ec4899);color:#fff;padding:16px 20px;border-radius:16px 16px 0 0;display:flex;justify-content:space-between;align-items:center;">
          <div style="font-size:15px;font-weight:800;">📱 bKash Receive</div>
          <button data-x-click="closeModalById('staff-bkash-modal')" style="background:none;border:none;color:#fff;font-size:20px;cursor:pointer;">✕</button>
        </div>
        <div style="padding:20px;display:grid;gap:12px;">
          <div><label style="${lab}">Amount (৳) *</label><input type="number" id="sbk-amount" placeholder="0.00" style="${inp}"></div>
          <div><label style="${lab}">Product *</label><select id="sbk-product" style="${inp}"><option value="">Select product…</option></select></div>
          <div><label style="${lab}">Quantity</label><input type="number" id="sbk-qty" placeholder="0" style="${inp}"></div>
          <div><label style="${lab}">From (Party/Name)</label><input type="text" id="sbk-party" placeholder="Sender name" style="${inp}"></div>
          <div><label style="${lab}">bKash TxID</label><input type="text" id="sbk-txid" placeholder="Transaction ID" style="${inp}"></div>
          <div><label style="${lab}">Notes</label><input type="text" id="sbk-notes" placeholder="Optional" style="${inp}"></div>
        </div>
        <div style="padding:14px 20px;border-top:1px solid ${border};display:flex;gap:10px;justify-content:flex-end;">
          <button data-x-click="closeModalById('staff-bkash-modal')" style="padding:9px 18px;background:#f3f4f6;color:#374151;border:none;border-radius:8px;font-weight:700;cursor:pointer;">Cancel</button>
          <button data-x-click="saveStaffBkash()" style="padding:9px 20px;background:#be185d;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;">💾 Save</button>
        </div>
      </div>
    </div>
    <div id="staff-expense-modal" style="display:none;position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:2000;align-items:center;justify-content:center;">
      <div style="background:${bg};border-radius:16px;width:90%;max-width:420px;color:${textColor};box-shadow:0 8px 40px rgba(0,0,0,.3);">
        <div style="background:linear-gradient(135deg,#dc2626,#ef4444);color:#fff;padding:16px 20px;border-radius:16px 16px 0 0;display:flex;justify-content:space-between;align-items:center;">
          <div style="font-size:15px;font-weight:800;">💸 Log Expense</div>
          <button data-x-click="closeModalById('staff-expense-modal')" style="background:none;border:none;color:#fff;font-size:20px;cursor:pointer;">✕</button>
        </div>
        <div style="padding:20px;display:grid;gap:12px;">
          <div><label style="${lab}">Expense Type *</label>
            <select id="sexp-type" style="${inp}">
              <option>Office Rent</option><option>Electricity Bill</option><option>Internet Bill</option>
              <option>Fuel Expense</option><option>Transport Cost</option><option>Loading Charge</option>
              <option>Unloading Charge</option><option>Salary Payment</option><option>Other Expense</option>
            </select></div>
          <div><label style="${lab}">Amount (৳) *</label><input type="number" id="sexp-amount" placeholder="0.00" style="${inp}"></div>
          <div><label style="${lab}">Description</label><input type="text" id="sexp-desc" placeholder="What was this expense for?" style="${inp}"></div>
          <div><label style="${lab}">Payment Mode</label>
            <select id="sexp-mode" style="${inp}"><option>Cash</option><option>Bank Transfer</option><option>bKash</option></select></div>
        </div>
        <div style="padding:14px 20px;border-top:1px solid ${border};display:flex;gap:10px;justify-content:flex-end;">
          <button data-x-click="closeModalById('staff-expense-modal')" style="padding:9px 18px;background:#f3f4f6;color:#374151;border:none;border-radius:8px;font-weight:700;cursor:pointer;">Cancel</button>
          <button data-x-click="saveStaffExpense()" style="padding:9px 20px;background:#dc2626;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;">💾 Save</button>
        </div>
      </div>
    </div>`;
}

function renderStaffDash(){
  const el=document.getElementById('pg-staffdash');
  if(!el) return;
  const isDark=document.documentElement.getAttribute('data-theme')==='dark';
  const bg=isDark?'#1e293b':'#fff';
  const border=isDark?'#334155':'#e5e7eb';
  const textColor=isDark?'#f1f5f9':'#1a202c';
  const text2=isDark?'#94a3b8':'#6b7280';
  const user=currentUser||{name:'Staff',role:'Staff'};
  const isAdmin=isAdminOrOwner();

  // ── Data calculations ──
  const txs=DB.tx||[];
  const banks=DB.banks||[];
  const orders=DB.orders||[];
  const today=new Date().toISOString().split('T')[0];
  const thisMonth=new Date().toISOString().substring(0,7);

  const totalBankBal=banks.reduce((s,b)=>s+(b.bal||0),0);
  const todaySales=txs.filter(t=>t.date===today&&isRevenueTx(t)).reduce((s,t)=>s+txAmt(t),0);
  const todayPurch=txs.filter(t=>t.date===today&&isCogsTx(t)).reduce((s,t)=>s+txAmt(t),0);
  const todayExp=txs.filter(t=>t.date===today&&['Expense','Office Rent','Electricity Bill','Other Expense','Salary Payment'].includes(t.type)).reduce((s,t)=>s+txAmt(t),0);
  const bkashTxs=txs.filter(t=>t.date===today&&(t.mode==='bKash'||t.mode==='Bkash'||(t.type||'').toLowerCase().includes('bkash')));
  const bkashIn=bkashTxs.filter(t=>['Sale','Sales Receipt','Cash Received'].includes(t.type)).reduce((s,t)=>s+txAmt(t),0);
  const pendingOrders=orders.filter(o=>o.deliveryStatus==='Pending'||o.deliveryStatus==='Processing');
  const myOrders=orders.filter(o=>o.submittedBy===user.name);
  const recentTxs=txs.filter(t=>t.date===today).sort((a,b)=>(b.id||0)-(a.id||0)).slice(0,8);

  const roleColors={Admin:'#dc2626',Owner:'#7c3aed',Manager:'#2563eb',Operator:'#059669',Viewer:'#6b7280',Staff:'#d97706'};
  const roleColor=roleColors[user.role]||'#6b7280';

  el.innerHTML=`<div style="padding:20px;">

    <!-- Welcome Banner -->
    <div style="background:linear-gradient(135deg,#0f3d26,#16a34a);color:#fff;border-radius:14px;padding:20px 24px;margin-bottom:20px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:12px;">
      <div>
        <div style="font-size:11px;opacity:.7;text-transform:uppercase;letter-spacing:1px;margin-bottom:4px;">Welcome back</div>
        <div style="font-size:22px;font-weight:900;">${escHTML(user.name)}</div>
        <div style="display:flex;align-items:center;gap:8px;margin-top:6px;">
          <span style="background:${roleColor};padding:3px 12px;border-radius:20px;font-size:11px;font-weight:800;">${escHTML(user.role)}</span>
          <span style="font-size:12px;opacity:.75;">${new Date().toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</span>
        </div>
      </div>
      <div style="text-align:right;">
        <div style="font-size:11px;opacity:.7;text-transform:uppercase;letter-spacing:.5px;">Bank Balance</div>
        <div style="font-size:28px;font-weight:900;letter-spacing:-1px;">৳${totalBankBal.toLocaleString('en-IN',{minimumFractionDigits:2})}</div>
        <div style="font-size:11px;opacity:.7;margin-top:2px;">${banks.length} account${banks.length!==1?'s':''}</div>
      </div>
    </div>

    <!-- Quick Actions -->
    <div style="background:${bg};border:1px solid ${border};border-radius:14px;padding:18px;margin-bottom:20px;">
      <div style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:14px;">⚡ Quick Actions</div>
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(130px,1fr));gap:10px;">
        ${[
          {icon:'📋',label:'New Order',color:'#16a34a',action:"openOrderModal()"},
          {icon:'📱',label:'bKash Receive',color:'#be185d',action:"openStaffBkash()"},
          {icon:'💸',label:'Log Expense',color:'#dc2626',action:"openStaffExpense()"},
          ...(isAdmin?[
            {icon:'📦',label:'Purchase',color:'#2563eb',action:"openStaffPurchase()"},
            {icon:'💰',label:'Make Payment',color:'#7c3aed',action:"openStaffPayment()"},
          ]:[]),
          {icon:'📊',label:'My Orders',color:'#d97706',action:"nav('orders')"},
          {icon:'🏦',label:'Bank Balance',color:'#059669',action:"nav('banks')"},
          {icon:'📈',label:'Today Report',color:'#0891b2',action:"nav('dailysummary')"},
        ].map(a=>`
          <button data-x-click="${a.action}" style="padding:14px 8px;background:${a.color}11;border:1.5px solid ${a.color}33;border-radius:10px;cursor:pointer;text-align:center;transition:all .2s;font-family:inherit;"
            data-hover-bg="${a.color}22">
            <div style="font-size:24px;margin-bottom:6px;">${a.icon}</div>
            <div style="font-size:11px;font-weight:700;color:${textColor};">${a.label}</div>
          </button>`).join('')}
      </div>
    </div>

    <!-- Today's Summary -->
    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:12px;margin-bottom:20px;">
      ${[
        {icon:'💰',label:"Today's Sales",val:'৳'+todaySales.toLocaleString('en-IN',{minimumFractionDigits:2}),color:'#16a34a'},
        {icon:'📦',label:"Today's Purchases",val:'৳'+todayPurch.toLocaleString('en-IN',{minimumFractionDigits:2}),color:'#2563eb'},
        {icon:'💸',label:"Today's Expenses",val:'৳'+todayExp.toLocaleString('en-IN',{minimumFractionDigits:2}),color:'#dc2626'},
        {icon:'📱',label:'bKash Received',val:'৳'+bkashIn.toLocaleString('en-IN',{minimumFractionDigits:2}),color:'#be185d'},
        {icon:'⏳',label:'Pending Orders',val:pendingOrders.length,color:'#d97706'},
        {icon:'📋',label:'My Orders',val:myOrders.length,color:'#7c3aed'},
      ].map(k=>`<div class="kpi-card" style="border-left:4px solid ${k.color};">
        <div style="font-size:20px;">${k.icon}</div>
        <div style="font-size:18px;font-weight:900;color:${k.color};margin-top:4px;">${k.val}</div>
        <div style="font-size:10px;color:${text2};font-weight:700;">${k.label}</div>
      </div>`).join('')}
    </div>

    <!-- Two column: My Orders + Bank Accounts -->
    <div style="display:grid;grid-template-columns:1fr;gap:16px;margin-bottom:20px;">

      <!-- My Recent Orders -->
      <div style="background:${bg};border:1px solid ${border};border-radius:14px;overflow:hidden;">
        <div style="padding:14px 18px;border-bottom:1px solid ${border};display:flex;justify-content:space-between;align-items:center;">
          <div style="font-size:14px;font-weight:800;color:#0f3d26;">📋 My Recent Orders</div>
          <button data-x-click="nav('orders')" style="padding:5px 12px;background:#16a34a;color:#fff;border:none;border-radius:6px;font-size:11px;font-weight:700;cursor:pointer;">View All</button>
        </div>
        <div style="overflow-x:auto;">
          ${myOrders.length?`<table style="width:100%;border-collapse:collapse;font-size:12px;">
            <thead><tr style="background:#f9fafb;">
              <th style="padding:8px 12px;text-align:left;font-size:10px;font-weight:700;color:${text2};">DATE</th>
              <th style="padding:8px 12px;text-align:left;font-size:10px;font-weight:700;color:${text2};">CUSTOMER</th>
              <th style="padding:8px 12px;text-align:right;font-size:10px;font-weight:700;color:${text2};">QTY</th>
              <th style="padding:8px 12px;text-align:center;font-size:10px;font-weight:700;color:${text2};">STATUS</th>
            </tr></thead>
            <tbody>${myOrders.slice(0,6).map(o=>{
              const sc={'Pending':'#fef9c3;color:#b45309','Processing':'#dbeafe;color:#1d4ed8','On Route':'#ede9fe;color:#7c3aed','Delivered':'#dcfce7;color:#16a34a','Cancelled':'#fee2e2;color:#dc2626'}[o.deliveryStatus]||'#f3f4f6;color:#6b7280';
              return `<tr style="border-bottom:1px solid ${border};">
                <td style="padding:8px 12px;color:${text2};">${o.orderDate}</td>
                <td style="padding:8px 12px;font-weight:700;color:${textColor};">${escHTML(o.customerName)}</td>
                <td style="padding:8px 12px;text-align:right;color:#16a34a;font-weight:700;">${(o.qty||0).toLocaleString('en-IN')}</td>
                <td style="padding:8px 12px;text-align:center;"><span style="padding:2px 8px;border-radius:6px;font-size:10px;font-weight:700;background:${sc.split(';')[0]};${sc.split(';')[1]||''}">${o.deliveryStatus}</span></td>
              </tr>`;
            }).join('')}</tbody>
          </table>`
          :`<div style="text-align:center;padding:30px;color:${text2};font-size:12px;">No orders submitted yet.<br><button data-x-click="openOrderModal()" style="margin-top:10px;padding:7px 16px;background:#16a34a;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:12px;">➕ Submit First Order</button></div>`}
        </div>
      </div>

      <!-- Bank Accounts -->
      <div style="background:${bg};border:1px solid ${border};border-radius:14px;overflow:hidden;">
        <div style="padding:14px 18px;border-bottom:1px solid ${border};display:flex;justify-content:space-between;align-items:center;">
          <div style="font-size:14px;font-weight:800;color:#0f3d26;">🏦 Bank Accounts</div>
          <div style="font-size:13px;font-weight:900;color:#16a34a;">৳${totalBankBal.toLocaleString('en-IN',{minimumFractionDigits:2})}</div>
        </div>
        ${banks.length?`<div style="padding:12px 18px;">${banks.map(b=>`
          <div style="display:flex;justify-content:space-between;align-items:center;padding:10px 0;border-bottom:1px solid ${border};">
            <div>
              <div style="font-size:13px;font-weight:700;color:${textColor};">🏦 ${escHTML(b.name)}</div>
              <div style="font-size:10px;color:${text2};">${escHTML(b.bankName ||'')}</div>
            </div>
            <div style="font-size:15px;font-weight:900;color:${(b.bal||0)>=0?'#16a34a':'#dc2626'};">৳${(b.bal||0).toLocaleString('en-IN',{minimumFractionDigits:2})}</div>
          </div>`).join('')}</div>`
        :`<div style="text-align:center;padding:30px;color:${text2};font-size:12px;">No bank accounts added yet.</div>`}
      </div>
    </div>

    <!-- Today's Transactions -->
    <div style="background:${bg};border:1px solid ${border};border-radius:14px;overflow:hidden;margin-bottom:20px;">
      <div style="padding:14px 18px;border-bottom:1px solid ${border};display:flex;justify-content:space-between;align-items:center;">
        <div style="font-size:14px;font-weight:800;color:#0f3d26;">📊 Today's Transactions</div>
        <div style="font-size:12px;color:${text2};">${today}</div>
      </div>
      ${recentTxs.length?`<div style="overflow-x:auto;"><table style="width:100%;border-collapse:collapse;font-size:12px;">
        <thead><tr style="background:#f9fafb;">
          <th style="padding:8px 12px;text-align:left;font-size:10px;font-weight:700;color:${text2};">TYPE</th>
          <th style="padding:8px 12px;text-align:left;font-size:10px;font-weight:700;color:${text2};">PARTY</th>
          <th style="padding:8px 12px;text-align:right;font-size:10px;font-weight:700;color:${text2};">AMOUNT</th>
          <th style="padding:8px 12px;text-align:left;font-size:10px;font-weight:700;color:${text2};">MODE</th>
        </tr></thead>
        <tbody>${recentTxs.map(t=>{
          const isIn=['Sale','Warehouse Sale','Sales Receipt','Cash Received'].includes(t.type);
          return `<tr style="border-bottom:1px solid ${border};">
            <td style="padding:8px 12px;"><span style="padding:2px 8px;border-radius:6px;font-size:10px;font-weight:700;background:${isIn?'#dcfce7':'#fee2e2'};color:${isIn?'#16a34a':'#dc2626'};">${t.type}</span></td>
            <td style="padding:8px 12px;font-weight:600;color:${textColor};">${escHTML(t.party ||'—')}</td>
            <td style="padding:8px 12px;text-align:right;font-weight:800;color:${isIn?'#16a34a':'#dc2626'};">${isIn?'+':'-'}৳${txAmt(t).toLocaleString('en-IN',{minimumFractionDigits:2})}</td>
            <td style="padding:8px 12px;color:${text2};">${t.mode||'Cash'}</td>
          </tr>`;
        }).join('')}</tbody>
      </table></div>`
      :`<div style="text-align:center;padding:30px;color:${text2};font-size:12px;">No transactions today yet.</div>`}
    </div>

    ${staffQuickModalsHTML(bg,border,textColor,text2)}

  </div>`;
}

/* The staff quick-entry modals are part of the Staff Dashboard template, but the
   same buttons also exist on the Mobile Dashboard and the floating action bar.
   Build them on demand so those entry points work from any page. */
function ensureStaffModals(){
  if(document.getElementById('staff-bkash-modal') && document.getElementById('staff-expense-modal')) return;
  const isDark=document.documentElement.getAttribute('data-theme')==='dark';
  const bg=isDark?'#1e293b':'#fff';
  const border=isDark?'#334155':'#e5e7eb';
  const textColor=isDark?'#f1f5f9':'#1a202c';
  const text2=isDark?'#94a3b8':'#6b7280';
  const inp=`width:100%;padding:10px 12px;border:1.5px solid ${border};border-radius:8px;font-size:13px;background:${bg};color:${textColor};`;
  const lab=`font-size:11px;font-weight:700;color:${text2};display:block;margin-bottom:4px;`;
  const host=document.createElement('div');
  host.id='staff-quick-modals';
  host.innerHTML = staffQuickModalsHTML(bg,border,textColor,text2);
  document.body.appendChild(host);
}

function openStaffBkash(){
  ensureStaffModals();
  document.getElementById('staff-bkash-modal').style.display='flex';
  const set=(id,v)=>{const e=document.getElementById(id); if(e) e.value=v;};
  set('sbk-amount','');
  set('sbk-party','');
  set('sbk-txid','');
  set('sbk-notes','');
  set('sbk-qty','');
  const prodSel=document.getElementById('sbk-product');
  if(prodSel){
    const products=(DB.products||[]);
    prodSel.innerHTML='<option value="">Select product…</option>'+
      products.map(p=>`<option value="${escHTML(p.name)}">${escHTML(p.name)}</option>`).join('');
  }
}

function saveStaffBkash(){
  const amt=parseFloat(document.getElementById('sbk-amount')?.value)||0;
  if(!amt){toast('Please enter amount','e');return;}
  const product=document.getElementById('sbk-product')?.value||'';
  if(!product){toast('Please select a product','e');return;}
  const qty=parseFloat(document.getElementById('sbk-qty')?.value)||0;
  const party=document.getElementById('sbk-party')?.value||'bKash';
  const txid=document.getElementById('sbk-txid')?.value||'';
  const notes=document.getElementById('sbk-notes')?.value||'';
  if(!DB.tx) DB.tx=[];
  DB.tx.push({
    id:newId(),date:new Date().toISOString().split('T')[0],
    type:'Sales Receipt',party,amt,amount:amt,
    product,prod:product,qty,
    mode:'bKash',note:'bKash TxID: '+txid+(notes?' — '+notes:''),
    desc:'bKash received from '+party+' for '+product,
    submittedBy:currentUser?.name||'Staff'
  });
  saveDB();
  document.getElementById('staff-bkash-modal').style.display='none';
  toast('✅ bKash receipt of ৳'+amt.toLocaleString('en-IN')+' saved!','s');
  logAudit('BKASH','Staff Dashboard','bKash received ৳'+amt+' from '+party+' for '+product);
  renderStaffDash();
  _scheduleAutoSave();
}

