// Live party balance from transactions (positive = they owe / we owe depending on type)
function livePartyBalance(p){
  const name=p.name; let bal=parseFloat(p.bal||p.cap||0)||0;
  (DB.tx||[]).forEach(t=>{
    if(t.party!==name) return;
    const a=parseFloat(txAmt(t))||0;
    switch(t.type){
      case 'Sale': case 'Customer Sale': case 'Warehouse Sale': bal+=a; break;   // customer owes us
      case 'Sales Receipt': case 'Customer Collection': case 'Customer Payment Received': case 'Sales Return': bal-=a; break;
      case 'Purchase': case 'Supplier Purchase': case 'Warehouse Purchase': case 'Werhouse Purchase': bal-=a; break; // we owe supplier
      case 'Purchase Payment': case 'Supplier Payment': case 'Purchase Return': case 'Supplier Refund': bal+=a; break;
      case 'Payment Refund': bal-=a; break;   // refund received back -> supplier due restored
    }
  });
  return bal;
}
// ── One-time bulk recategorization ──────────────────────────────
// Source: A.xlsx (Sheet1) — three independent columns (Supplier,
// Customer, Partner), NOT paired rows. Names are kept exactly as
// given — no merging of similar-looking names, since the same
// party can legitimately appear worded differently in different
// places. Run once from the Parties Hub button; safe to re-run.
const PARTY_LIST_CUSTOMERS = ["Karima","Suborna","Sorna","Saven","Desh","Progati","Rashid Oil","Local"];
const PARTY_LIST_PARTNERS  = ["Md. Rafiqul Islam","Mr. Soleman","Mst. Sathi"];
const PARTY_LIST_SUPPLIERS = ["Afifa Auto Rice Mill","AM Bran Oil","Anika Agro","Another Badam Vusi","Asanur Rhamin","Bhai Bhai Rice Mill","Desh Agro Industries","Golden Auto Rice","Jafor Auto Rice","Jordar Auto Rice","Karima Agro","M S Jibon Enterprise","M S Mahamud Traders","M S RS Enterprise","M S Shamim Traders","M S Simra Traders","M S Sohan Traders","M S Tanha Traders","Maa Babar Dowa Enterprise","Majumder Agro Tech Bd Ltd","M/S DESH AGRO IND. LTD","M S NUR ENTERPRICE","M/S MULLA TRADERS","M/S SIMRA TRADERS","M/S AFIFA AUTO RICE MILL","MAA BABAR DOWA ENTREPRISE","SADDM VAI","M S MHAMUD TRADERS","M S GOLDEN AUTO RICE MILL","MOHABUL UNCAL BKASH","M S R S ENTERPRISE","M N Agro","PABNA SEVEN STAR RICE Bran OILL MILLS LTD"];
// "Party Name" (a placeholder row in the source sheet) was intentionally excluded.

async function applyPartyListMigration(){
  DB.customers = DB.customers||[];
  DB.partners  = DB.partners||[];

  const msg = `This will:\n`
    + `• Set ${PARTY_LIST_CUSTOMERS.length} parties as Customer\n`
    + `• Set ${PARTY_LIST_SUPPLIERS.length} parties as Supplier\n`
    + `• Ensure ${PARTY_LIST_PARTNERS.length} Partners exist: ${PARTY_LIST_PARTNERS.join(', ')}\n\n`
    + `This does not delete anyone or touch balances — only the Type field changes, and missing names are added fresh. Continue?`;
  if(!await __confirm(msg)) return;

  // 1) Named customers: match by name (case-insensitive) or create.
  PARTY_LIST_CUSTOMERS.forEach(name=>{
    let c = DB.customers.find(c=>(c.name||'').toLowerCase()===name.toLowerCase());
    if(c){ c.type='Customer'; c.updatedAt=Date.now(); }
    else {
      c = {id:DB.nid.c++, name, type:'Customer', bal:0, creditLimit:0, phone:'', address:'', createdAt:Date.now(), updatedAt:Date.now()};
      c.code=genCode('CUS');
      DB.customers.push(c);
    }
  });

  // 2) Named suppliers: match by name (case-insensitive) or create.
  //    Kept in DB.customers (same array as Customer, per app convention),
  //    just tagged type:'Supplier'.
  PARTY_LIST_SUPPLIERS.forEach(name=>{
    let c = DB.customers.find(c=>(c.name||'').toLowerCase()===name.toLowerCase());
    if(c){ c.type='Supplier'; c.updatedAt=Date.now(); }
    else {
      c = {id:DB.nid.c++, name, type:'Supplier', bal:0, creditLimit:0, phone:'', address:'', createdAt:Date.now(), updatedAt:Date.now()};
      c.code=genCode('SUP');
      DB.customers.push(c);
    }
  });

  // 3) Named partners: match by name in DB.partners or create.
  PARTY_LIST_PARTNERS.forEach(name=>{
    let p = DB.partners.find(p=>(p.name||'').toLowerCase()===name.toLowerCase());
    if(!p){
      p = {id:DB.nid.p++, name, cap:0, share:0, phone:'', address:'', createdAt:Date.now(), updatedAt:Date.now()};
      p.code=genCode('PTR');
      DB.partners.push(p);
    }
  });

  saveDB();
  try{ renderPartiesHub(); }catch(e){}
  try{ renderCust(); }catch(e){}
  try{ renderSuppliers(); }catch(e){}
  try{ renderPart(); }catch(e){}
  try{ renderDash(); }catch(e){}
  try{ logAudit('UPDATE','Parties','Bulk recategorized: '+PARTY_LIST_CUSTOMERS.length+' Customers, '+PARTY_LIST_SUPPLIERS.length+' Suppliers, '+PARTY_LIST_PARTNERS.length+' Partners'); }catch(e){}
  toast('Party list applied — Customers, Partners, and Suppliers updated','s');
}

let _partiesHubTab='all';
function setPartiesHubTab(t){ _partiesHubTab=t; renderPartiesHub(); }
function renderPartiesHub(){
  const el=document.getElementById('pg-partieshub');
  if(!el)return;
  const parties=DB.parties||[];
  const custs=parties.filter(p=>isCustomerParty(p));
  const sups=parties.filter(p=>isSupplierParty(p));
  const parts=parties.filter(p=>p.type==='Partner');

  // Which own-list is shown below the KPI row. 'all' = everyone;
  // the other tabs are each party type's own list, rendered right
  // here on the hub page (no navigation away needed).
  const tabs=[
    {key:'all',       label:'🏢 All Parties', list:parties},
    {key:'customers', label:'👥 Customers',    list:custs},
    {key:'suppliers', label:'🏭 Suppliers',    list:sups},
    {key:'partners',  label:'🤝 Partners',     list:parts},
  ];
  const active=tabs.find(t=>t.key===_partiesHubTab)||tabs[0];

  el.innerHTML=`<div class="page-header" style="display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:8px;">
    <div><h2>🏢 Parties Hub</h2><p>All business parties at a glance</p></div>
    <button class="btn btn-sm" style="background:#7c3aed;color:#fff;white-space:nowrap;" data-x-click="applyPartyListMigration()">🔧 Apply Customer/Supplier/Partner List</button>
  </div>
  <div class="kpi-grid">
    <div class="kpi-card" data-x-click="setPartiesHubTab('customers')" style="cursor:pointer"><div class="kpi-icon">👥</div><div class="kpi-val">${custs.length}</div><div class="kpi-label">Customers</div></div>
    <div class="kpi-card" data-x-click="setPartiesHubTab('suppliers')" style="cursor:pointer"><div class="kpi-icon">🏭</div><div class="kpi-val">${sups.length}</div><div class="kpi-label">Suppliers</div></div>
    <div class="kpi-card" data-x-click="setPartiesHubTab('partners')" style="cursor:pointer"><div class="kpi-icon">🤝</div><div class="kpi-val">${parts.length}</div><div class="kpi-label">Partners</div></div>
    <div class="kpi-card" data-x-click="setPartiesHubTab('all')" style="cursor:pointer"><div class="kpi-icon">📊</div><div class="kpi-val">${parties.length}</div><div class="kpi-label">Total Parties</div></div>
  </div>
  <div class="card">
    <div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center;justify-content:space-between;margin-bottom:10px;">
      <h3 style="margin:0;">${escHTML(active.label)} <span style="font-size:12px;font-weight:600;color:#9ca3af;">(${active.list.length})</span></h3>
      <div style="display:flex;gap:6px;flex-wrap:wrap;">
        ${tabs.map(t=>`<button class="btn btn-xs" data-x-click="setPartiesHubTab('${t.key}')" style="background:${t.key===active.key?'#0f3d26':'#e5e7eb'};color:${t.key===active.key?'#fff':'#111827'};border:none;border-radius:6px;padding:6px 12px;font-weight:700;cursor:pointer;">${t.label}</button>`).join('')}
      </div>
    </div>
    <table class="tbl"><thead><tr><th>Name</th><th>Type</th><th>Balance (৳)</th><th>Transactions</th></tr></thead>
    <tbody>${active.list.map(p=>{/* FIX (2026-08-20): livePartyBalance() started from p.bal (already the
      canonical, continuously-updated running balance) and then re-applied every
      matching transaction's delta ON TOP of it — double-counting. A supplier
      paid in full for a single ৳15,39,174 purchase showed as owing ৳30,78,348
      here while every other page (Suppliers, Customers, Dashboard) correctly
      showed ৳0, purely because this one page used a different, stale
      calculation. Use p.bal directly, same as everywhere else in the app. */
      const bal=parseFloat(p.bal||p.cap||0)||0;const txCount=(DB.tx||[]).filter(t=>t.party===p.name).length;const lbl=bal>0?'Receivable':(bal<0?'Payable':'Clear');return`<tr><td><b>${escHTML(p.name||'—')}</b></td><td><span class="badge badge-blue">${p.type||'—'}</span></td><td style="font-weight:700;color:${bal>0?'#166534':(bal<0?'#dc2626':'#6b7280')}">${f(Math.abs(bal))} <span style="font-size:10px;font-weight:600;color:#9ca3af;">${lbl}</span></td><td>${txCount}</td></tr>`;}).join('')||`<tr><td colspan="4" style="text-align:center;color:#888">No ${active.key==='all'?'parties':active.key} found</td></tr>`}</tbody>
    </table>
  </div>`;
}

/* ═══════════════════════════════════════════════════════════════
