  const sups=allParties.filter(p=>isSupplierParty(p));

  // KPI totals
  const totalPayable=Math.abs(sups.reduce((s,p)=>{const b=p.bal||0;return s+(b<0?b:0);},0));
  const totalAdv=sups.reduce((s,p)=>{const b=p.bal||0;return s+(b>0?b:0);},0);
  const totalBal=sups.reduce((s,p)=>s+(p.bal||0),0);
  const purchaseCount=(DB.tx||[]).filter(isCogsTx).length;
  const overdueCount=sups.filter(p=>(p.bal||0)<0).length;

  el.innerHTML=`
  <div class="page-header">
    <h2>🏭 Suppliers</h2>
    <p>Full supplier management — balances, ledger, and payables</p>
