      <div class="kpi-label">Advance Paid</div>
      <div class="kpi-sub">Pre-paid to suppliers</div>
    </div>
    <div class="kpi-card c-orange">
      <div class="kpi-icon">📦</div>
      <div class="kpi-val">${purchaseCount}</div>
      <div class="kpi-label">Purchase Transactions</div>
      <div class="kpi-sub">All time</div>
    </div>
  </div>

  <!-- Toolbar -->
  <div class="table-card">
    <div class="table-header" style="flex-wrap:wrap;gap:8px;align-items:flex-start;">
      <div class="table-title">🏭 Supplier Directory</div>
