/* Build table rows (shared by initial render + filter redraw) */
function _buildSupplierRows(sups){
  if(!sups.length) return '<tr><td colspan="9" style="text-align:center;color:#9ca3af;padding:32px;">No suppliers found. Click <strong>➕ Add Supplier</strong> to get started.</td></tr>';
  const allTx=DB.tx||[];
  return sups.map((p,i)=>{
    const bal=p.bal||0;
    const balColor=bal<0?'#dc2626':bal>0?'#16a34a':'#6b7280';
    const balLabel=bal<0?'Payable':bal>0?'Advance':'Clear';
    const balBg=bal<0?'#fef2f2':bal>0?'#f0fdf4':'#f9fafb';
    const ptx=allTx.filter(t=>t.party===p.name);
    const lastTx=ptx.sort((a,b)=>new Date(b.date)-new Date(a.date))[0];
    const purchCount=ptx.filter(isCogsTx).length;
    const safeName=escJSAttr(p.name||'');
    const badge=entityCodeBadge&&entityCodeBadge(p.code)||'';
    return `<tr data-id="${p.id}"
                data-name="${escHTML((p.name||'').toLowerCase())}"
                data-bal="${bal}"
                data-lasttx="${lastTx?lastTx.date:'0000-00-00'}"
                data-purchcount="${purchCount}"
                style="transition:background .15s;">
      <td class="text-muted fs11">${i+1}</td>
      <td>
        <strong>${escHTML(p.name ||'—')}</strong>${badge}
        ${p.email?`<br><span style="font-size:10px;color:#6b7280;">✉ ${escHTML(p.email)}</span>`:''}
        ${p.bankName?`<br><span style="font-size:10px;color:#2563eb;">🏦 ${p.bankName}${p.bankAcc?' · '+p.bankAcc:''}</span>`:''}
      </td>
      <td>${escHTML(p.phone ||'—')}</td>
      <td class="fs11" style="max-width:180px;white-space:normal;">${escHTML(p.address ||'—')}${p.notes?`<br><span style="color:#9ca3af;">${escHTML(p.notes)}</span>`:''}
      </td>
      <td class="td-num">
        <div style="background:${balBg};border-radius:6px;padding:4px 8px;display:inline-block;min-width:110px;text-align:right;">
          <span style="font-weight:700;color:${balColor};">${f(bal)}</span><br>
          <span style="font-size:10px;color:#9ca3af;">${balLabel}</span>
        </div>
      </td>
      <td class="td-num fs11">${p.creditLimit?f(p.creditLimit):'—'}</td>
      <td class="fs11">${lastTx?`<span title="${lastTx.type}">${lastTx.date}</span>`:'—'}</td>
      <td class="td-num fs11">${purchCount>0?`<span style="background:#dbeafe;color:#1d4ed8;border-radius:4px;padding:2px 6px;">${purchCount}</span>`:'0'}</td>
      <td style="white-space:nowrap;text-align:center;">
        <button class="btn btn-xs" style="background:#3b82f6;color:#fff;margin:1px;"
                data-x-click="_supToggleLedger('${safeName}')" title="View Ledger">📋</button>
        <button class="btn btn-xs" style="background:#f59e0b;color:#fff;margin:1px;"
                data-x-click="editCust(${p.id})" title="Edit Supplier">✏️</button>
        <button class="btn btn-xs" style="background:#8b5cf6;color:#fff;margin:1px;"
                data-x-click="_supQuickPay('${safeName}',${Math.abs(bal)})" title="Record Payment"
                ${bal>=0?'disabled style="opacity:.4;cursor:not-allowed;background:#8b5cf6;color:#fff;margin:1px;"':''}>💳</button>
        <button class="btn btn-xs btn-danger" style="margin:1px;"
                data-x-click="_supDelete(${p.id},'${safeName}')" title="Delete Supplier">🗑</button>
      </td>
    </tr>`;
  }).join('');
}

function _buildSupplierFoot(sups){
  const netBal=sups.reduce((s,p)=>s+(p.bal||0),0);
  const totalLim=sups.reduce((s,p)=>s+(p.creditLimit||0),0);
  return `<tr style="background:#fef3c7;font-weight:800;border-top:2px solid #d97706;">
    <td colspan="4" style="text-align:right;padding:10px 14px;font-size:12px;">
      Totals — <span style="color:#6b7280;">${sups.length} supplier${sups.length!==1?'s':''}</span>
    </td>
    <td class="td-num" style="padding:10px 12px;font-size:13px;color:${netBal<0?'#dc2626':netBal>0?'#16a34a':'#6b7280'};">
      ${f(netBal)}
    </td>
    <td class="td-num" style="padding:10px 12px;">${totalLim?f(totalLim):'—'}</td>
    <td colspan="3"></td>
  </tr>`;
}

/* ── Filter / sort (runs on every input change) ── */
function _filterSuppliers(){
  const q=(document.getElementById('sup-search')?.value||'').toLowerCase().trim();
  const balF=document.getElementById('sup-bal-filter')?.value||'';
  const sortK=document.getElementById('sup-sort')?.value||'name';

  // Get current supplier list
  const allParties=(DB.customers||DB.parties||[]);
  let sups=allParties.filter(p=>isSupplierParty(p));

  // Text filter (name, phone, address, email)
  if(q) sups=sups.filter(p=>{
    const hay=((p.name||'')+' '+(p.phone||'')+' '+(p.address||'')+' '+(p.email||'')).toLowerCase();
    return hay.includes(q);
  });

  // Balance filter
  if(balF==='payable') sups=sups.filter(p=>(p.bal||0)<0);
  else if(balF==='advance') sups=sups.filter(p=>(p.bal||0)>0);
  else if(balF==='clear') sups=sups.filter(p=>(p.bal||0)===0);

  // Sort
  const allTx=DB.tx||[];
  if(sortK==='name') sups.sort((a,b)=>(a.name||'').localeCompare(b.name||''));
  else if(sortK==='name-desc') sups.sort((a,b)=>(b.name||'').localeCompare(a.name||''));
  else if(sortK==='bal-asc') sups.sort((a,b)=>(a.bal||0)-(b.bal||0));
  else if(sortK==='bal-desc') sups.sort((a,b)=>(b.bal||0)-(a.bal||0));
  else if(sortK==='recent'){
    const lastDate=p=>{
      const tx=allTx.filter(t=>t.party===p.name).sort((a,b)=>b.date.localeCompare(a.date))[0];
      return tx?tx.date:'0000-00-00';
    };
    sups.sort((a,b)=>lastDate(b).localeCompare(lastDate(a)));
  }

  // Re-render body & foot
  const body=document.getElementById('sup-body');
  const foot=document.getElementById('sup-foot');
  if(body) body.innerHTML=_buildSupplierRows(sups);
  if(foot) foot.innerHTML=_buildSupplierFoot(sups);

  // Summary bar
  const netBal=sups.reduce((s,p)=>s+(p.bal||0),0);
  const payable=sups.filter(p=>(p.bal||0)<0).length;
  const sumEl=document.getElementById('sup-summary');
  if(sumEl) sumEl.innerHTML=
    `Showing <strong>${sups.length}</strong> supplier${sups.length!==1?'s':''} &nbsp;|&nbsp;
     Net balance: <strong style="color:${netBal<0?'#dc2626':netBal>0?'#16a34a':'#6b7280'}">${f(netBal)}</strong>
     &nbsp;|&nbsp; <span style="color:#dc2626;">${payable} with payable</span>`;
}

/* ── Add supplier (opens existing party modal pre-set to Supplier) ── */
function _addSupplierQuick(){
  const e=document.getElementById('c-edit-id');if(e) e.value=0;
  if(typeof clearPartyBankRows==='function') clearPartyBankRows();
  const typeEl=document.getElementById('c-type');if(typeEl) typeEl.value='Supplier';
  openModal('mCust');
}

/* ── Delete with confirmation ── */
async function _supDelete(id, name){
  const txCount=(DB.tx||[]).filter(t=>t.party===name).length;
  const warn=txCount?`\n⚠ This supplier has ${txCount} transaction(s). Deleting will remove the account only — transactions remain.`:'';
  if(!await __confirm(`Delete supplier "${name}"?${warn}`)) return;
  if(typeof delCust==='function') delCust(id);
  toast(`Supplier "${name}" deleted.`,'s');
  renderSuppliers();
}

/* ── Quick payment helper ── */
/* BUGFIX: this used to be a pair of prompt() popups (amount, then a free-text
   "mode" string) that pushed straight into DB.tx and manually bumped the
   supplier's own balance — it never had a real bank-account field, never
   called applyTxBalance(), and so never actually moved money out of any
   bank account (Cash/Bank/Cheque was just a label). It now opens a small
   modal with the same account(+split) widget New Transaction and Salary
   Payment use, and saves through the same _executeSaveTx() pipeline, so a
   supplier quick-payment now behaves exactly like every other payment in
   the app — the party balance AND the bank balance both update correctly
   via applyTxBalance()'s existing 'purchase payment' handling (manually
   adjusting supp.bal here as well would have double-counted it). */
var _sqpCtx=null, _sqpWidget=null;
function _supQuickPay(supplierName, outstanding){
  _sqpCtx={supplierName:supplierName, outstanding:outstanding};
  const info=document.getElementById('sqp-supplier-info');
  if(info) info.innerHTML='Paying <b>'+escHTML(supplierName)+'</b> — Outstanding: ৳'+pf(outstanding);
  const amtEl=document.getElementById('sqp-amt'); if(amtEl) amtEl.value=outstanding>0?outstanding:'';
  const dateEl=document.getElementById('sqp-date'); if(dateEl) dateEl.value=new Date().toISOString().split('T')[0];
  const noteEl=document.getElementById('sqp-note'); if(noteEl) noteEl.value='';
  _sqpWidget=createPayAccountWidget(document.getElementById('sqp-acc-widget'),function(){
    return parseFloat(document.getElementById('sqp-amt')?.value)||0;
  });
  const modal=document.getElementById('mSupQuickPay');
  if(modal) modal.style.display='flex';
}
function _sqpRecalc(){ if(_sqpWidget&&_sqpWidget.recalc) _sqpWidget.recalc(); }
function _supQuickPaySubmit(){
  if(!_sqpCtx){ toast('No supplier selected.','e'); return; }
  const amt=parseFloat(document.getElementById('sqp-amt')?.value)||0;
  if(!amt||amt<=0){ toast('Enter a valid amount.','w'); return; }
  const date=document.getElementById('sqp-date')?.value||new Date().toISOString().split('T')[0];
  const note=document.getElementById('sqp-note')?.value||'';
  if(!_sqpWidget){ toast('Payment account widget not ready.','e'); return; }
  const v=_sqpWidget.validate();
  if(!v.ok){ toast(v.msg,'e'); return; }
  const tx={
    id:newId(), date, type:'Purchase Payment',
    party:_sqpCtx.supplierName, amount:amt, amt,
    rem: note||'Quick payment via Suppliers page'
  };
  if(v.payAccounts){ tx.payAccounts=v.payAccounts; tx.acc=v.payAccounts[0].acc; tx.splitPayment=true; }
  else tx.acc=v.acc;
  _executeSaveTx(tx,0);
  if(typeof logAudit==='function') logAudit('PAYMENT','Suppliers',`Paid ৳${pf(amt)} to ${_sqpCtx.supplierName}`);
  toast(`✅ Payment of ৳${pf(amt)} recorded for ${_sqpCtx.supplierName}`,'s');
  closeModal('mSupQuickPay');
  renderSuppliers();
  _sqpCtx=null;
}

/* ── Inline ledger toggle ── */
function _supToggleLedger(partyName){
  const panel=document.getElementById('sup-ledger-panel');
  if(!panel) return;
  // If same supplier is already open, toggle close
  if(panel.dataset.open===partyName && panel.style.display!=='none'){
    panel.style.display='none';
    panel.dataset.open='';
    return;
  }
  panel.dataset.open=partyName;
  panel.style.display='block';
  panel.scrollIntoView({behavior:'smooth',block:'nearest'});

  // Build ledger inline
  const txs=[...(DB.tx||[]).filter(t=>t.party===partyName)].sort((a,b)=>a.date.localeCompare(b.date));
  const party=(DB.customers||[]).find(c=>c.name===partyName);
  const PURCHASE_TYPES=['Purchase','Warehouse Purchase','Purchase Advance'];
  const PAYMENT_TYPES=['Purchase Payment','Supplier Payment','Purchase Return','Supplier Refund'];
  const REFUND_TYPES=['Payment Refund'];

  let runBal=0;
  const rows=txs.map((t,i)=>{
    const isPurch=PURCHASE_TYPES.includes(t.type);
    const isPay=PAYMENT_TYPES.includes(t.type);
    const isRef=REFUND_TYPES.includes(t.type);
    const dr=isPurch?(t.amount||0):0;
    const cr=isPay?(t.amount||0):(isRef?-(t.amount||0):0);
    runBal+=dr-cr;
    const bc=runBal<0?'#16a34a':runBal>0?'#dc2626':'#6b7280';
    return `<tr style="border-bottom:1px solid #f3f4f6;">
      <td style="padding:5px 8px;font-size:11px;color:#9ca3af;">${i+1}</td>
      <td style="padding:5px 8px;font-size:12px;">${t.date||'—'}</td>
      <td style="padding:5px 8px;font-size:11px;color:#6b7280;">${t.inv||'—'}</td>
      <td style="padding:5px 8px;"><span style="font-size:11px;background:#e0e7ff;color:#3730a3;border-radius:4px;padding:1px 6px;">${t.type}</span></td>
      <td style="padding:5px 8px;font-size:11px;">${escHTML(t.prod ||'—')}</td>
      <td style="padding:5px 8px;text-align:right;color:#dc2626;font-weight:600;">${dr>0?f(dr):'—'}</td>
      <td style="padding:5px 8px;text-align:right;color:#16a34a;font-weight:600;">${cr>0?f(cr):'—'}</td>
      <td style="padding:5px 8px;text-align:right;font-weight:700;color:${bc};">${f(Math.abs(runBal))} <span style="font-size:10px;font-weight:400;">${runBal<0?'Adv':runBal>0?'Due':''}</span></td>
      <td style="padding:5px 8px;font-size:11px;color:#6b7280;">${escHTML(t.rem ||'—')}</td>
    </tr>`;
  }).join('');

  const totalPurch=txs.reduce((s,t)=>s+(PURCHASE_TYPES.includes(t.type)?t.amount||0:0),0);
  const totalPaid=txs.reduce((s,t)=>s+(PAYMENT_TYPES.includes(t.type)?t.amount||0:0)-(REFUND_TYPES.includes(t.type)?t.amount||0:0),0);
  const finalBal=totalPurch-totalPaid;

  panel.innerHTML=`
  <div style="background:#fff;border:2px solid #3b82f6;border-radius:12px;box-shadow:0 4px 20px rgba(59,130,246,.12);overflow:hidden;">
    <div style="background:#1e40af;color:#fff;padding:12px 16px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px;">
      <div>
        <strong style="font-size:15px;">📋 Ledger — ${escHTML(partyName)}</strong>
        ${party?`<span style="font-size:11px;opacity:.8;margin-left:8px;">${escHTML(party.type)} | ${escHTML(party.phone||'')}</span>`:''}
      </div>
      <div style="display:flex;gap:6px;align-items:center;">
        <button class="btn btn-sm" style="background:#fff;color:#1e40af;font-size:11px;"
                data-x-click="_printSupLedger('${escJSAttr(partyName)}')">🖨️ Print</button>
        <button class="btn btn-sm" style="background:rgba(255,255,255,.2);color:#fff;font-size:11px;"
                data-x-click="_supToggleLedger('${escJSAttr(partyName)}')">✕ Close</button>
      </div>
    </div>

    <!-- Mini KPI strip -->
    <div style="display:flex;gap:12px;flex-wrap:wrap;padding:12px 16px;background:#eff6ff;border-bottom:1px solid #bfdbfe;">
      <div style="text-align:center;">
        <div style="font-size:11px;color:#6b7280;">Transactions</div>
        <div style="font-weight:700;color:#1e40af;">${txs.length}</div>
      </div>
      <div style="text-align:center;">
        <div style="font-size:11px;color:#6b7280;">Total Purchases</div>
        <div style="font-weight:700;color:#dc2626;">${f(totalPurch)}</div>
      </div>
      <div style="text-align:center;">
        <div style="font-size:11px;color:#6b7280;">Total Paid</div>
        <div style="font-weight:700;color:#16a34a;">${f(totalPaid)}</div>
      </div>
      <div style="text-align:center;">
        <div style="font-size:11px;color:#6b7280;">Net Balance</div>
        <div style="font-weight:700;color:${finalBal>0?'#dc2626':finalBal<0?'#16a34a':'#6b7280'};">
          ${f(Math.abs(finalBal))} <span style="font-size:10px;">${finalBal>0?'(Due)':finalBal<0?'(Advance)':'(Clear)'}</span>
        </div>
      </div>
      ${party&&party.creditLimit?`<div style="text-align:center;">
        <div style="font-size:11px;color:#6b7280;">Credit Limit</div>
        <div style="font-weight:700;color:#7c3aed;">${f(party.creditLimit)}</div>
      </div>`:''}
    </div>

    <!-- Ledger table -->
    <div style="overflow-x:auto;max-height:380px;overflow-y:auto;">
      <table style="width:100%;border-collapse:collapse;font-size:12px;">
        <thead style="position:sticky;top:0;background:#f8fafc;z-index:1;">
          <tr style="border-bottom:2px solid #e2e8f0;">
            <th style="padding:7px 8px;text-align:left;font-size:11px;color:#6b7280;">#</th>
            <th style="padding:7px 8px;text-align:left;">Date</th>
            <th style="padding:7px 8px;text-align:left;">Invoice</th>
            <th style="padding:7px 8px;text-align:left;">Type</th>
            <th style="padding:7px 8px;text-align:left;">Item</th>
            <th style="padding:7px 8px;text-align:right;color:#dc2626;">Debit (৳)</th>
            <th style="padding:7px 8px;text-align:right;color:#16a34a;">Credit (৳)</th>
            <th style="padding:7px 8px;text-align:right;">Balance (৳)</th>
            <th style="padding:7px 8px;text-align:left;">Remarks</th>
          </tr>
        </thead>
        <tbody>
          ${rows||`<tr><td colspan="9" style="text-align:center;padding:24px;color:#9ca3af;">No transactions found for ${partyName}.</td></tr>`}
        </tbody>
        <tfoot>
          <tr style="background:#f0fdf4;font-weight:700;border-top:2px solid #16a34a;">
            <td colspan="5" style="padding:8px 12px;text-align:right;">Totals:</td>
            <td style="padding:8px 12px;text-align:right;color:#dc2626;">${f(totalPurch)}</td>
            <td style="padding:8px 12px;text-align:right;color:#16a34a;">${f(totalPaid)}</td>
            <td style="padding:8px 12px;text-align:right;color:${finalBal>0?'#dc2626':'#16a34a'};">${f(Math.abs(finalBal))}</td>
            <td></td>
          </tr>
        </tfoot>
      </table>
    </div>
  </div>`;
}

/* ── Print ledger for one supplier ── */
function _printSupLedger(partyName){
  const txs=[...(DB.tx||[]).filter(t=>t.party===partyName)].sort((a,b)=>a.date.localeCompare(b.date));
  const party=(DB.customers||[]).find(c=>c.name===partyName);
  const PURCHASE_TYPES=['Purchase','Warehouse Purchase','Purchase Advance'];
  const PAYMENT_TYPES=['Purchase Payment','Supplier Payment','Purchase Return','Supplier Refund'];
  const REFUND_TYPES=['Payment Refund'];
  let runBal=0;
  const rows=txs.map((t,i)=>{
    const dr=PURCHASE_TYPES.includes(t.type)?t.amount||0:0;
    const cr=PAYMENT_TYPES.includes(t.type)?t.amount||0:(REFUND_TYPES.includes(t.type)?-(t.amount||0):0);
    runBal+=dr-cr;
    return `<tr><td>${i+1}</td><td>${t.date}</td><td>${t.inv||'—'}</td><td>${t.type}</td>
      <td>${escHTML(t.prod ||'—')}</td>
      <td style="text-align:right;color:#dc2626;">${dr>0?f(dr):'—'}</td>
      <td style="text-align:right;color:#16a34a;">${cr>0?f(cr):'—'}</td>
      <td style="text-align:right;font-weight:700;">${f(runBal)}</td>
      <td>${escHTML(t.rem ||'—')}</td></tr>`;
  }).join('');
  const totalPurch=txs.reduce((s,t)=>s+(PURCHASE_TYPES.includes(t.type)?t.amount||0:0),0);
  const totalPaid=txs.reduce((s,t)=>s+(PAYMENT_TYPES.includes(t.type)?t.amount||0:0)-(REFUND_TYPES.includes(t.type)?t.amount||0:0),0);
  const html=`<p><strong>Supplier:</strong> ${partyName} &nbsp;|&nbsp;
    <strong>Type:</strong> ${party?party.type:'Supplier'} &nbsp;|&nbsp;
    <strong>Phone:</strong> ${party?escHTML(party.phone||'—'):'—'} &nbsp;|&nbsp;
    <strong>Address:</strong> ${party?escHTML(party.address||'—'):'—'}</p>
    <table border="1" cellpadding="5" cellspacing="0" style="width:100%;border-collapse:collapse;font-size:11px;">
      <thead style="background:#1a3a6b;color:#fff;">
        <tr><th>#</th><th>Date</th><th>Invoice</th><th>Type</th><th>Item</th>
            <th>Debit (৳)</th><th>Credit (৳)</th><th>Balance (৳)</th><th>Remarks</th></tr>
      </thead>
      <tbody>${rows}</tbody>
      <tfoot>
        <tr style="font-weight:700;background:#f0fdf4;">
          <td colspan="5" style="text-align:right;">Totals:</td>
          <td style="text-align:right;">${f(totalPurch)}</td>
          <td style="text-align:right;">${f(totalPaid)}</td>
          <td style="text-align:right;">${f(totalPurch-totalPaid)}</td>
          <td></td>
        </tr>
      </tfoot>
    </table>`;
  if(typeof openPrintModal==='function')
    openPrintModal(`Supplier Ledger — ${partyName}`, 'SUP-LDG', html, partyName);
}

/* ── Export visible/filtered suppliers to CSV ── */
function _exportSuppliersCSV(){
  const allParties=(DB.customers||DB.parties||[]);
  let sups=allParties.filter(p=>isSupplierParty(p));
  // Apply same filter as UI
  const q=(document.getElementById('sup-search')?.value||'').toLowerCase().trim();
  const balF=document.getElementById('sup-bal-filter')?.value||'';
  if(q) sups=sups.filter(p=>((p.name||'')+' '+(p.phone||'')+' '+(p.address||'')).toLowerCase().includes(q));
  if(balF==='payable') sups=sups.filter(p=>(p.bal||0)<0);
  else if(balF==='advance') sups=sups.filter(p=>(p.bal||0)>0);
  else if(balF==='clear') sups=sups.filter(p=>(p.bal||0)===0);

  const allTx=DB.tx||[];
  const headers=['Name','Type','Phone','Email','Address','Balance (৳)','Balance Status',
                 'Credit Limit','Bank Name','Bank Account','Purchase Count','Last Tx Date','Notes'];
  const csvRows=sups.map(p=>{
    const ptx=allTx.filter(t=>t.party===p.name);
    const lastTx=ptx.sort((a,b)=>b.date.localeCompare(a.date))[0];
    const pCount=ptx.filter(isCogsTx).length;
    const bal=p.bal||0;
    return [p.name,p.type,p.phone,p.email,p.address,bal,
            bal<0?'Payable':bal>0?'Advance':'Clear',
            p.creditLimit||0,p.bankName,p.bankAcc,pCount,
            lastTx?lastTx.date:'',p.notes]
      .map(v=>'"'+(v==null?'':String(v)).replace(/"/g,'""')+'"').join(',');
  });
  const csv=[headers.join(','),...csvRows].join('\n');
  const blob=new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8;'});
  const a=document.createElement('a');
  a.href=URL.createObjectURL(blob);
  a.download='suppliers_'+(new Date().toISOString().split('T')[0])+'.csv';
  a.click();
  toast(`✅ Exported ${sups.length} supplier${sups.length!==1?'s':''} to CSV`,'s');
  if(typeof logAudit==='function') logAudit('EXPORT','Suppliers',`Exported ${sups.length} suppliers`);
}

/* ── Print supplier list (filtered) ── */
function _printSuppliers(){
  const allParties=(DB.customers||DB.parties||[]);
  let sups=allParties.filter(p=>isSupplierParty(p));
  const q=(document.getElementById('sup-search')?.value||'').toLowerCase().trim();
  const balF=document.getElementById('sup-bal-filter')?.value||'';
  if(q) sups=sups.filter(p=>((p.name||'')+' '+(p.phone||'')+' '+(p.address||'')).toLowerCase().includes(q));
  if(balF==='payable') sups=sups.filter(p=>(p.bal||0)<0);
  else if(balF==='advance') sups=sups.filter(p=>(p.bal||0)>0);
  else if(balF==='clear') sups=sups.filter(p=>(p.bal||0)===0);

  const allTx=DB.tx||[];
  const netBal=sups.reduce((s,p)=>s+(p.bal||0),0);
  const rows=sups.map((p,i)=>{
    const bal=p.bal||0;
    const ptx=allTx.filter(t=>t.party===p.name);
    const lastTx=ptx.sort((a,b)=>b.date.localeCompare(a.date))[0];
    return `<tr>
      <td>${i+1}</td>
      <td><b>${escHTML(p.name)}</b>${p.phone?`<br><small>${escHTML(p.phone)}</small>`:''}
      <td>${escHTML(p.address ||'—')}</td>
      <td style="text-align:right;color:${bal<0?'#dc2626':bal>0?'#16a34a':'#555'};font-weight:700;">${f(bal)}</td>
      <td style="text-align:center;">${bal<0?'Payable':bal>0?'Advance':'Clear'}</td>
      <td>${lastTx?lastTx.date:'—'}</td>
    </tr>`;
  }).join('');
  const html=`
    <p style="margin:0 0 8px;font-size:12px;color:#555;">
      Generated: ${new Date().toLocaleDateString()} &nbsp;|&nbsp; ${sups.length} supplier${sups.length!==1?'s':''}
      ${balF?` &nbsp;|&nbsp; Filter: ${balF}`:''}${q?` &nbsp;|&nbsp; Search: "${q}"`:''}</p>
    <table border="1" cellpadding="6" cellspacing="0"
           style="width:100%;border-collapse:collapse;font-size:12px;">
      <thead style="background:#1a3a6b;color:#fff;">
        <tr><th>#</th><th>Supplier</th><th>Address</th>
            <th style="text-align:right;">Balance (৳)</th>
            <th>Status</th><th>Last Tx</th></tr>
      </thead>
      <tbody>${rows}</tbody>
      <tfoot>
        <tr style="background:#fef3c7;font-weight:700;">
          <td colspan="3" style="text-align:right;">Net Total:</td>
          <td style="text-align:right;color:${netBal<0?'#dc2626':'#16a34a'};">${f(netBal)}</td>
          <td colspan="2"></td>
        </tr>
      </tfoot>
    </table>`;
  if(typeof openPrintModal==='function')
    openPrintModal('Supplier List','SUP-LIST',html,`${sups.length} Suppliers`);
  if(typeof logAudit==='function') logAudit('PRINT','Suppliers',`Printed ${sups.length} suppliers`);
}

function renderPartyStatement(){
  const el=document.getElementById('pg-partystatement');
  if(!el)return;
  el.innerHTML=`<div class="page-header"><h2>📄 Party Statement</h2><p>Individual party account statement</p></div>
  <div class="card"><div style="display:flex;gap:12px;align-items:center;flex-wrap:wrap;">
    <!-- FIX (2026-08-28, structural audit): was id="ps-party", which
         collided with the live Payment Schedule feature's own "ps-party"
         field (newPaySchedule()/savePaySchedule()) — an unrelated feature
         that happens to use the same "ps" (Payment Schedule) prefix this
         page's own "ps" (Party Statement) prefix coincidentally matches.
         Both pages are reachable in normal use, so both selects could be
         live in the DOM together, and getElementById would always resolve
         to whichever renders first — silently reading/writing the wrong
         page's party selection. Renamed to pst-party (Party STatement),
         unique to this page. -->
    <select id="pst-party" style="padding:8px 12px;border:1px solid #ddd;border-radius:6px;font-size:13px;min-width:200px;" data-x-change="renderPartyStatementData()">
      <option value="">— Select Party —</option>
      ${(DB.parties||[]).map(p=>`<option value="${escHTML(p.name)}">${escHTML(p.name)} (${p.type})</option>`).join('')}
    </select>
    <input type="date" id="ps-from" style="padding:8px 12px;border:1px solid #ddd;border-radius:6px;font-size:13px;">
    <input type="date" id="ps-to" style="padding:8px 12px;border:1px solid #ddd;border-radius:6px;font-size:13px;">
    <button class="btn" data-x-click="renderPartyStatementData()">🔍 Show</button>
    <button class="btn btn-outline" data-x-click="printPartyStatement()">🖨️ Print</button>
  </div></div>
  <div id="ps-result" class="card"><p style="text-align:center;color:#888">Select a party to view statement</p></div>`;
}

function renderPartyStatementData(){
  const party=document.getElementById('pst-party')?.value;
  const from=document.getElementById('ps-from')?.value;
  const to=document.getElementById('ps-to')?.value;
  const el=document.getElementById('ps-result');
  if(!el||!party)return;
  let txs=(DB.tx||[]).filter(t=>t.party===party);
  if(from) txs=txs.filter(t=>_dk(t.date)>=_dk(from));
  if(to) txs=txs.filter(t=>_dk(t.date)<=_dk(to));
  txs.sort((a,b)=>new Date(a.date)-new Date(b.date));
  let bal=0;
  el.innerHTML=`<h3>📄 Statement: ${escHTML(party)}</h3>
  <table class="tbl"><thead><tr><th>Date</th><th>Invoice</th><th>Type</th><th>Debit (৳)</th><th>Credit (৳)</th><th>Balance (৳)</th></tr></thead>
  <tbody>${txs.map(t=>{const isDebit=['Sale','Sales Advance'].includes(t.type);const amt = txAmt(t);if(isDebit)bal+=amt;else bal-=amt;return`<tr><td>${t.date}</td><td>${t.inv||'—'}</td><td>${t.type}</td><td>${isDebit?f(amt):'—'}</td><td>${!isDebit?f(amt):'—'}</td><td style="font-weight:700;color:${bal>=0?'#166534':'#dc2626'}">${f(bal)}</td></tr>`;}).join('')||'<tr><td colspan="6" style="text-align:center;color:#888">No transactions found</td></tr>'}</tbody>
  </table><div style="text-align:right;margin-top:12px;font-size:15px;font-weight:700;">Closing Balance: <span style="color:${bal>=0?'#166534':'#dc2626'}">${f(bal)}</span></div>`;
}

function printPartyStatement(){
  const party=document.getElementById('pst-party')?.value;
  const resultEl=document.getElementById('ps-result');
  if(!party||!resultEl||resultEl.innerHTML.includes('Select a party')){
    alert('Please select a party and click Show first.');
    return;
  }
  // Print on official company letterhead
  const html = '<style>#print-content table{width:100%;border-collapse:collapse;margin-top:10px;}#print-content th,#print-content td{padding:7px 10px;border:1px solid #ddd;font-size:12px;text-align:left;}#print-content th{background:#0f3d26;color:#fff;}<\/style>'
    + '<h2 style="text-align:center;margin:0 0 10px;color:#0f3d26;">Party Statement — '+party+'</h2>'
    + resultEl.innerHTML;
  openPrintModal('Party Statement — '+party, 'PSTMT-'+Date.now().toString().slice(-6), html, party);
}

function renderPartyRankings(){
  const el=document.getElementById('pg-partyrankings');
  if(!el)return;
  const txs=DB.tx||[];
  const custMap={};
  const suppMap={};
  txs.forEach(t=>{
    if(isRevenueTx(t)&&t.party){
      if(!custMap[t.party]) custMap[t.party]={name:t.party,total:0,count:0};
      custMap[t.party].total+=txAmt(t);
      custMap[t.party].count++;
    }
    if(isCogsTx(t)&&t.party){
      if(!suppMap[t.party]) suppMap[t.party]={name:t.party,total:0,count:0};
      suppMap[t.party].total+=txAmt(t);
      suppMap[t.party].count++;
    }
  });
  const topCust=Object.values(custMap).sort((a,b)=>b.total-a.total).slice(0,10);
  const topSupp=Object.values(suppMap).sort((a,b)=>b.total-a.total).slice(0,10);
  el.innerHTML=`<div class="page-header"><h2>🏆 Party Rankings</h2><p>Top customers and suppliers by transaction volume</p></div>
  <div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;">
    <div class="card">
      <h3 style="font-size:14px;font-weight:800;color:#16a34a;margin-bottom:14px;">🥇 Top Customers by Sales</h3>
      ${topCust.length?`<table class="tbl"><thead><tr><th>Rank</th><th>Customer</th><th>Transactions</th><th>Total Sales</th></tr></thead>
      <tbody>${topCust.map((c,i)=>`<tr>
        <td><span style="font-size:16px;">${['🥇','🥈','🥉'][i]||'#'+(i+1)}</span></td>
        <td><strong>${escHTML(c.name)}</strong></td>
        <td>${c.count}</td>
        <td><strong style="color:#16a34a;">${f(c.total)}</strong></td>
      </tr>`).join('')}</tbody></table>`
      :'<div style="text-align:center;padding:20px;color:#9ca3af;">No sales data yet.</div>'}
    </div>
    <div class="card">
      <h3 style="font-size:14px;font-weight:800;color:#2563eb;margin-bottom:14px;">🥇 Top Suppliers by Purchases</h3>
      ${topSupp.length?`<table class="tbl"><thead><tr><th>Rank</th><th>Supplier</th><th>Transactions</th><th>Total Purchases</th></tr></thead>
      <tbody>${topSupp.map((s,i)=>`<tr>
        <td><span style="font-size:16px;">${['🥇','🥈','🥉'][i]||'#'+(i+1)}</span></td>
        <td><strong>${escHTML(s.name)}</strong></td>
        <td>${s.count}</td>
        <td><strong style="color:#2563eb;">${f(s.total)}</strong></td>
      </tr>`).join('')}</tbody></table>`
      :'<div style="text-align:center;padding:20px;color:#9ca3af;">No purchase data yet.</div>'}
    </div>
  </div>`;
}

function renderProducts(){
  const el=document.getElementById('pg-products');
  if(!el)return;
  const prods=DB.products||[];
  const txs=DB.tx||[];
  const _stk=p=>((p.stock!=null?p.stock:p.qty)||0);
  const totalVal=prods.reduce((s,p)=>s+_stk(p)*(p.rate||p.price||0),0);
  const lowStock=prods.filter(p=>_stk(p)<=(p.minStock||p.minQty||10));
  el.innerHTML=`<div class="page-header"><h2>📦 Products & Inventory</h2><p>Product catalog and stock levels</p></div>
  <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:12px;margin-bottom:20px;">
    <div class="kpi-card"><div class="kpi-icon">📦</div><div class="kpi-val">${prods.length}</div><div class="kpi-label">Total Products</div></div>
    <div class="kpi-card"><div class="kpi-icon">💰</div><div class="kpi-val">${f(totalVal)}</div><div class="kpi-label">Inventory Value</div></div>
    <div class="kpi-card" style="border-left:4px solid #dc2626;"><div class="kpi-icon">⚠️</div><div class="kpi-val" style="color:#dc2626;">${lowStock.length}</div><div class="kpi-label">Low Stock Items</div></div>
    <div class="kpi-card"><div class="kpi-icon">📊</div><div class="kpi-val">${prods.reduce((s,p)=>s+_stk(p),0).toLocaleString('en-IN')}</div><div class="kpi-label">Total Stock Units</div></div>
  </div>
  ${lowStock.length?`<div style="background:#fef2f2;border:1.5px solid #fecaca;border-radius:10px;padding:14px;margin-bottom:16px;">
    <div style="font-weight:800;color:#dc2626;margin-bottom:8px;">⚠️ Low Stock Alert (${lowStock.length} items)</div>
    ${lowStock.map(p=>`<span style="display:inline-block;padding:3px 10px;background:#fee2e2;color:#dc2626;border-radius:8px;font-size:11px;font-weight:700;margin:2px;">${escHTML(p.name)} (${_stk(p)} left)</span>`).join('')}
  </div>`:''}
  <div class="card">
    <h3 style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:14px;">📦 Product List</h3>
    ${prods.length?`<table class="tbl"><thead><tr><th>Product</th><th>Category</th><th>Stock</th><th>Rate (৳)</th><th>Value (৳)</th><th>Status</th></tr></thead>
    <tbody>${prods.map(p=>{
      const val=_stk(p)*(p.rate||p.price||0);
      const isLow=_stk(p)<=(p.minStock||p.minQty||10);
      return `<tr>
        <td><strong>${escHTML(p.name)}</strong><br><span style="font-size:10px;color:#6b7280;">${p.sku||p.code||''}</span></td>
        <td>${p.category||p.cat||'—'}</td>
        <td style="font-weight:700;color:${isLow?'#dc2626':'#16a34a'};">${_stk(p).toLocaleString('en-IN')} ${escHTML(p.unit ||'units')}</td>
        <td>${f(p.rate||p.price||0)}</td>
        <td><strong>${f(val)}</strong></td>
        <td><span style="padding:2px 8px;border-radius:8px;font-size:10px;font-weight:700;background:${isLow?'#fee2e2':'#dcfce7'};color:${isLow?'#dc2626':'#16a34a'};">${isLow?'Low Stock':'In Stock'}</span></td>
      </tr>`;
    }).join('')}</tbody></table>`
    :'<div style="text-align:center;padding:30px;color:#9ca3af;">No products found. Add products from the Inventory page.</div>'}
  </div>`;
}

function filterProducts(){
  const q=(document.getElementById('prod-search')?.value||'').toLowerCase();
  const filtered=q?(DB.products||[]).filter(p=>
    (p.name||'').toLowerCase().includes(q)||(p.cat||'').toLowerCase().includes(q)
  ):(DB.products||[]);
  renderProd(filtered);
}

