  <div class="card" style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;">
    <input type="text" id="tsheet-search" placeholder="🔍 Search party, type, product..." style="padding:8px 12px;border:1px solid #ddd;border-radius:6px;font-size:13px;flex:1;min-width:160px;" data-x-input="filterTxSheet()">
    <select id="tsheet-type" style="padding:8px 12px;border:1px solid #ddd;border-radius:6px;font-size:13px;" data-x-change="filterTxSheet()">
      <option value="">All Types</option>
      ${[...new Set((DB.tx||[]).map(t=>t.type).filter(Boolean))].sort().map(t=>`<option>${t}</option>`).join('')}
    </select>
    <input type="date" id="tsheet-from" style="padding:8px;border:1px solid #ddd;border-radius:6px;font-size:13px;" data-x-change="filterTxSheet()" title="From date">
    <input type="date" id="tsheet-to" style="padding:8px;border:1px solid #ddd;border-radius:6px;font-size:13px;" data-x-change="filterTxSheet()" title="To date">
    <button class="btn btn-outline" data-x-click="exportTxSheetCSV()" title="Export to CSV">📥 Export</button>
    <button class="btn btn-outline" data-x-click="printAllTransactions()">🖨️ Print</button>
    <button class="btn btn-outline" data-x-click="renderTxSheet()">🔄 Reset</button>
  </div>
  <div class="card" style="overflow-x:auto;">
    <div id="tsheet-summary" style="padding:8px 4px 10px;font-size:12.5px;color:#4a5568;display:flex;gap:18px;flex-wrap:wrap;"></div>
    <!-- Transport, Vehicle ID, Location and Supplier Bank are added AFTER
         Account on purpose: filterTxSheet() reads the amount from
         td:nth-child(9), so nothing may be inserted before it. -->
    <table class="tbl" id="tsheet-tbl"><thead><tr><th>#</th><th>Date</th><th>Invoice</th><th>Type</th><th>Party</th><th>Product</th><th style="text-align:right">Qty</th><th style="text-align:right">Rate</th><th style="text-align:right">Amount (৳)</th><th>Mode</th><th>Account</th><th>Transport</th><th>Vehicle ID</th><th>Location</th><th>Supplier Bank A/C</th><th>Actions</th></tr></thead>
    <tbody id="tsheet-tbody">${tx.map((t,i)=>`<tr data-idx="${i}" data-type="${(t.type||'').toLowerCase()}" data-text="${escHTML(((t.party||'')+(t.type||'')+(t.prod||'')+(t.inv||'')).toLowerCase())}" data-date="${t.date||''}">
      <td class="text-muted fs11">${i+1}</td>
      <td>${t.date||''}</td><td>${t.inv||'—'}</td>
      <td><span class="badge b-green" style="font-size:10px;">${t.type||''}</span></td>
      <td><strong>${escHTML(t.party||'')}</strong></td><td>${t.prod||'—'}</td>
      <td style="text-align:right">${t.qty||'—'}</td>
      <td style="text-align:right">${t.rate?f(t.rate):'—'}</td>
      <td style="text-align:right;font-weight:700;color:${txAmt(t)>=0?'#16a34a':'#dc2626'}">${f(txAmt(t))}</td>
      <td>${t.mode||''}</td>
      <!-- FIX (this column was always blank): it read t.bank, which saveTx
           never writes — the account is stored as t.acc (and mirrored to
           t.account). Every row showed an empty Account. -->
      <td class="fs11">${escHTML(bankNameToDisplay(t.acc||t.account||t.bank||'')||'—')}</td>
      <td>${t.transporttype?`<span class="badge b-gray fs11">${escHTML(t.transporttype)}</span>`:'—'}</td>
      <td class="fs11">${escHTML(t.truck||'—')}</td>
      <td>${t.loc?`<span class="badge b-green fs11" title="Warehouse / location">📍 ${escHTML(t.loc)}</span>`:'—'}</td>
      <td class="fs11">${escHTML(t.supplierBankInfo||'—')}</td>
      <td style="white-space:nowrap"><button class="btn btn-xs" style="background:#f5a623;color:#000;" data-x-click="editTx(${t.id})" title="Edit">✏️</button> <button class="btn btn-xs btn-danger" data-x-click="delTx(${t.id})" title="Delete">🗑</button></td>
    </tr>`).join('')||'<tr><td colspan="16" style="text-align:center;color:#888;padding:24px">No transactions found</td></tr>'}
    </tbody>
    <tfoot id="tsheet-tfoot"><tr style="background:#f0fdf4;font-weight:800;border-top:2px solid #16a34a;">
      <td colspan="8" style="text-align:right;padding:10px 12px;">Visible Total:</td>
      <td id="tsheet-total" style="text-align:right;padding:10px 12px;color:#16a34a;font-size:14px;">৳0.00</td>
      <td colspan="7"></td>
    </tr></tfoot>
    </table>
  </div>`;
  _updateTxSheetSummary(tx);
}

function filterTxSheet(){
  const q=(document.getElementById('tsheet-search')?.value||'').toLowerCase();
  const type=(document.getElementById('tsheet-type')?.value||'').toLowerCase();
  const from=document.getElementById('tsheet-from')?.value||'';
  const to=document.getElementById('tsheet-to')?.value||'';
  const rows=document.querySelectorAll('#tsheet-tbody tr[data-idx]');
  let visibleTotal=0; let visibleCount=0;
  rows.forEach(r=>{
    const txt=r.dataset.text||'';
    const rtype=r.dataset.type||'';
    const rdate=r.dataset.date||'';
    const show=(!q||txt.includes(q))&&(!type||rtype.includes(type))&&(!from||rdate>=from)&&(!to||rdate<=to);
    r.style.display=show?'':'none';
    if(show){
      const amtCell=r.querySelector('td:nth-child(9)');
      if(amtCell){ const v=parseFloat(amtCell.textContent.replace(/[^0-9.-]/g,'')||'0'); if(!isNaN(v)) visibleTotal+=v; }
      visibleCount++;
    }
  });
  const totalEl=document.getElementById('tsheet-total');
  if(totalEl) totalEl.textContent='৳'+visibleTotal.toLocaleString('en-IN',{minimumFractionDigits:2});
  const sumEl=document.getElementById('tsheet-summary');
  if(sumEl) sumEl.innerHTML=`<span>Showing <strong>${visibleCount}</strong> of <strong>${document.querySelectorAll('#tsheet-tbody tr[data-idx]').length}</strong> transactions</span> | <span>Filtered Total: <strong style="color:${visibleTotal>=0?'#16a34a':'#dc2626'}">৳${visibleTotal.toLocaleString('en-IN',{minimumFractionDigits:2})}</strong></span>`;
}

function _updateTxSheetSummary(tx){
  const sumEl=document.getElementById('tsheet-summary');
  if(!sumEl) return;
  const total=tx.reduce((s,t)=>s+txAmt(t),0);
  /* FIX L: was substring-matching 'sale'/'purchase', which also caught 'Sales
     Return', 'Sales Advance'/'Receipt' and 'Purchase Return'/'Advance'/
     'Payment' in this summary label — using canonical isRevenueTx/isCogsTx
     to match the rest of the app. */
  const sales=tx.filter(t=>window.isRevenueTx(t)).reduce((s,t)=>s+txAmt(t),0);
  const purch=tx.filter(t=>window.isCogsTx(t)).reduce((s,t)=>s+txAmt(t),0);
  sumEl.innerHTML=`<span>Total: <strong>${tx.length}</strong> transactions</span> | <span>Grand Total: <strong style="color:${total>=0?'#16a34a':'#dc2626'}">৳${total.toLocaleString('en-IN',{minimumFractionDigits:2})}</strong></span> | <span>Sales: <strong style="color:#16a34a">৳${sales.toLocaleString('en-IN',{minimumFractionDigits:2})}</strong></span> | <span>Purchases: <strong style="color:#dc2626">৳${purch.toLocaleString('en-IN',{minimumFractionDigits:2})}</strong></span>`;
  const totalEl=document.getElementById('tsheet-total');
  if(totalEl) totalEl.textContent='৳'+total.toLocaleString('en-IN',{minimumFractionDigits:2});
}

function exportTxSheetCSV(){
  const rows=document.querySelectorAll('#tsheet-tbody tr[data-idx]');
  const visible=[...rows].filter(r=>r.style.display!=='none');
  const headers=['#','Date','Invoice','Type','Party','Product','Qty','Rate','Amount','Mode','Account','Transport','Vehicle ID','Location','Supplier Bank A/C'];
  const lines=[headers.join(',')];
  visible.forEach((r,i)=>{
    const cells=[...r.querySelectorAll('td')].slice(0,15);   /* every column except Actions */
    const vals=cells.map((c,ci)=>{
      let v=c.textContent.trim();
      if(ci===3) v=c.querySelector('.badge')?.textContent||v; // type badge
      return '"'+v.replace(/"/g,'""')+'"';
    });
    vals[0]=i+1; // renumber
    lines.push(vals.join(','));
  });
  const blob=new Blob([lines.join('\n')],{type:'text/csv'});
  const a=document.createElement('a');
  a.href=URL.createObjectURL(blob);
  a.download='transactions_'+(new Date().toISOString().split('T')[0])+'.csv';
  a.click();
  toast('CSV exported!','s');
}

function renderTxEntry(){
  const el=document.getElementById('pg-txentry');
  if(!el)return;
  const today=new Date().toISOString().split('T')[0];
  const parties=(DB.parties||[]).map(p=>`<option value="${escHTML(p.name)}">`).join('');
  const products=(DB.products||[]).map(p=>`<option value="${escHTML(p.name)}">`).join('');
  const banks=(DB.banks||[]).map(b=>`<option value="${escHTML(b.name)}">${escHTML(b.name)}</option>`).join('');
  const locs=(DB.locations||[]).map(l=>`<option>${escHTML(l.name||l)}</option>`).join('') ||
    ['Dhaka','Chittagong','Narsingdi','Bogura','Chuadanga','Jashore','Kushtia'].map(l=>`<option>${l}</option>`).join('');
  const recentRows=(DB.tx||[]).slice(0,10).map(t=>`
    <tr style="border-bottom:1px solid #f3f4f6;">
      <td style="padding:7px 10px;font-size:12px;">${t.date||''}</td>
      <td style="padding:7px 10px;font-size:12px;color:#2563eb;">${t.inv||''}</td>
      <td style="padding:7px 10px;font-size:12px;">${t.type||''}</td>
      <td style="padding:7px 10px;font-size:12px;">${escHTML(t.party ||'')}</td>
      <td style="padding:7px 10px;font-size:12px;text-align:right;font-weight:700;color:#16a34a;">৳${pf(txAmt(t))}</td>
      <td style="padding:7px 10px;font-size:12px;">${t.mode||''}</td>
    </tr>`).join('');

  el.innerHTML=`
  <div class="page-header"><h2>📝 Transaction Entry</h2><p>Uses the standard, full multi-product transaction form — the same one used everywhere else in the app.</p></div>

  <div class="card" style="text-align:center;padding:32px;margin-bottom:16px;">
    <div style="font-size:38px;margin-bottom:10px;">💰</div>
    <p style="color:#6b7280;font-size:13px;margin-bottom:16px;">Click below to open the full transaction form (all fields, multi-product rows, PO/GRN/Challan, cost breakdown).</p>
    <button class="btn btn-primary" style="padding:14px 28px;font-size:15px;font-weight:700;background:linear-gradient(90deg,#16a34a,#15803d);border:none;" data-x-click="openModal('mTx')">➕ New Transaction</button>
  </div>


  <!-- RECENT TRANSACTIONS -->
