    ${recentRows ? `<div style="overflow-x:auto;"><table style="width:100%;border-collapse:collapse;">
      <thead><tr style="background:#f0fdf4;">
        <th style="padding:8px 10px;text-align:left;font-size:11px;color:#6b7280;font-weight:700;">DATE</th>
        <th style="padding:8px 10px;text-align:left;font-size:11px;color:#6b7280;font-weight:700;">INVOICE</th>
        <th style="padding:8px 10px;text-align:left;font-size:11px;color:#6b7280;font-weight:700;">TYPE</th>
        <th style="padding:8px 10px;text-align:left;font-size:11px;color:#6b7280;font-weight:700;">PARTY</th>
