function teClearForm(){
  const today=new Date().toISOString().split('T')[0];
  const ids=['tx-date','tx-inv','tx-po','tx-grn','tx-challan','tx-deliverydate','tx-paydate',
    'tx-party','tx-prod','tx-bagtype','tx-bagqty','tx-qty','tx-grosswt','tx-wt','tx-rate','tx-amt',
    'tx-oilpct','tx-totaloil','tx-moisture','tx-protein','tx-fiber','tx-ash','tx-ffa',
    'tx-supplierbank','tx-supplierbank-custom','tx-paid','tx-recv','tx-due',
    'tx-truck','tx-truckrent','tx-paid2','tx-due2',
    'tx-agentA','tx-agentAcost','tx-agentB','tx-agentBcost',
    'tx-qcperson','tx-qc','tx-unloadperson','tx-unload','tx-otherperson','tx-othercost',
    'tx-otherperson2','tx-othercost2','tx-totalcost',
    'tx-tax-amt','tx-net-amt','tx-wloss-kg','tx-wloss-amt',
    'tx-rem','tx-profit','tx-cat','tx-edit-id'];
  ids.forEach(id=>{
    const el=document.getElementById(id);
    if(!el)return;
    if(el.type==='date'&&id==='tx-date') el.value=today;
    else if(el.tagName==='SELECT') el.selectedIndex=0;
    else el.value='';
  });
  toast('Form cleared','s');
}

// ═══════════════════════════════════════════════════════════
// SHARED TRANSACTION-ENTRY INFRASTRUCTURE
// Used by Sales/Purchase/Payment/Expense/Journal entry below. Previously each
// module repeated its own `if(!DB.tx)DB.tx=[];DB.tx.unshift(tx);`, its own
// required-field check, and its own manual field-by-field form clear. Pulled
// out here so all five push/validate/reset the same way; each module keeps
// its own distinct business logic (auto-rate, splits, Dr/Cr) untouched.
// ═══════════════════════════════════════════════════════════
function pushTx(tx){
  if(!DB.tx) DB.tx=[];
  DB.tx.unshift(tx);
  return tx;
}
function requireFields(values, msg){
  for(const v of values){ if(v===undefined||v===null||v===''||(typeof v==='number'&&isNaN(v))){ alert(msg||'⚠️ Fill required fields'); return false; } }
  return true;
}
function clearFields(ids){
  ids.forEach(id=>{ const el=document.getElementById(id); if(el) el.value=''; });
}

