    <tbody>${txs.slice(0,25).map(t=>`<tr>
      <td>${t.date||'—'}</td>
      <td style="color:#2563eb;">${t.inv||'—'}</td>
      <td><strong>${escHTML(t.party ||'—')}</strong></td>
