function renderWarehousePurch(){
  const el=document.getElementById('pg-warehousepurch');
  if(!el)return;
  const txs=(DB.tx||[]).filter(t=>t.type==='Warehouse Purchase'||t.type==='Opening Warehouse Purchase').sort((a,b)=>(b.date||'').localeCompare(a.date||''));
  const total=txs.reduce((s,t)=>s+txAmt(t),0);
  const totalQty=txs.reduce((s,t)=>s+parseFloat(t.qty||0),0);

  // Weighted-average Oil % across all warehouse purchases:
  // (sum of every item's oil total) ÷ (grand total kg). Uses txItemRows()
  // so multi-product purchases (tx.items) are counted per-item, and
  // single-product/legacy transactions still fall back correctly.
  let grandTotalKg = 0, grandTotalOil = 0;
  txs.forEach(t=>{
    txItemRows(t).forEach(it=>{
      const kg = parseFloat(it.wt||it.qty||0) || 0;
      const oil = it.totalOil != null ? parseFloat(it.totalOil)||0 : kg*(parseFloat(it.oilPct)||0)/100;
      grandTotalKg += kg;
      grandTotalOil += oil;
    });
  });
  const avgOilPct = grandTotalKg > 0 ? (grandTotalOil / grandTotalKg) * 100 : 0;

  el.innerHTML=`<div class="page-header" style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px;"><div><h2>🏭 Warehouse Purchase Summary</h2><p>All warehouse purchase transactions</p></div><button class="btn btn-primary" style="padding:10px 20px;font-weight:700;background:linear-gradient(90deg,#16a34a,#15803d);border:none;" data-x-click="openTxModalAs('Warehouse Purchase')">➕ New Warehouse Purchase</button></div>
  <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:12px;margin-bottom:20px;">
    <div class="kpi-card"><div class="kpi-icon">🏭</div><div class="kpi-val">${txs.length}</div><div class="kpi-label">Transactions</div></div>
    <div class="kpi-card"><div class="kpi-icon">💰</div><div class="kpi-val">${f(total)}</div><div class="kpi-label">Total Value</div></div>
    <div class="kpi-card"><div class="kpi-icon">⚖️</div><div class="kpi-val">${totalQty.toLocaleString('en-IN')} kg</div><div class="kpi-label">Total Quantity</div></div>
    <div class="kpi-card"><div class="kpi-icon">📅</div><div class="kpi-val">${txs.length?txs[0].date:'—'}</div><div class="kpi-label">Last Purchase</div></div>
    <div class="kpi-card"><div class="kpi-icon">⚗️</div><div class="kpi-val">${avgOilPct.toFixed(2)}%</div><div class="kpi-label">Avg Oil % (weighted)</div></div>
    <div class="kpi-card"><div class="kpi-icon">🏦</div><div class="kpi-val">৳0.00</div><div class="kpi-label">Bank Account</div></div>
    <div class="kpi-card"><div class="kpi-icon">🏗️</div><div class="kpi-val">৳0.00</div><div class="kpi-label">Fixed Assets</div></div>
  </div>
  <div class="card">
    <h3 style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:14px;">🏭 Warehouse Purchase History</h3>
    ${txs.length?`<table class="tbl"><thead><tr><th>Date</th><th>Supplier</th><th>Product</th><th>Qty (kg)</th><th>Rate</th><th>Amount</th><th>Mode</th><th></th></tr></thead>
    <tbody>${txs.map(t=>`<tr>
      <td>${t.date||'—'}</td>
      <td><strong>${escHTML(t.party ||'—')}</strong></td>
      <td>${t.product||t.item||'—'}</td>
      <td>${parseFloat(t.qty||0).toLocaleString('en-IN')}</td>
      <td>${t.rate?f(t.rate):'—'}</td>
      <td><strong style="color:#2563eb;">${f(txAmt(t))}</strong></td>
      <td>${escHTML(t.mode||t.bank||'Cash')}</td>
      <td style="white-space:nowrap;"><button class="btn btn-xs btn-icon" style="background:#1a3a6b;color:#fff;margin-right:2px;" data-x-click="openModal(${t.id})" title="Edit">✏️</button><button class="btn btn-xs btn-icon" style="background:#f5a623;color:#000;margin-right:2px;" data-x-click="printTransaction(${t.id})" title="Print Voucher">🖨️</button><button class="btn btn-danger btn-xs btn-icon" data-x-click="delTx(${t.id})" title="Delete">🗑</button></td>
    </tr>`).join('')}</tbody>
    <tfoot><tr><td colspan="3" style="text-align:right;font-weight:800;padding:10px 12px;">Total:</td>
      <td style="font-weight:800;padding:10px 12px;">${totalQty.toLocaleString('en-IN')} kg</td>
      <td></td>
      <td style="font-weight:900;color:#2563eb;padding:10px 12px;">${f(total)}</td>
      <td></td><td></td></tr></tfoot>
    </table>`
    :'<div style="text-align:center;padding:30px;color:#9ca3af;">No warehouse purchases found.</div>'}
  </div>`;
}

