        <div><label style="font-size:12px;font-weight:600;">Payment Type</label><select id="pye-type" style="width:100%;padding:8px;border:1px solid #ddd;border-radius:6px;font-size:13px;"><option>Purchase Payment</option><option>Sales Receipt</option><option>Cash Payment</option><option>Cash Received</option></select></div>
