        <div><label style="font-size:12px;font-weight:600;">Total Amount (৳)</label><input type="number" id="pye-amt" placeholder="0.00" data-x-input="updateSplitSummary()" style="width:100%;padding:8px;border:1px solid #ddd;border-radius:6px;font-size:13px;"></div>
        <div><label style="font-size:12px;font-weight:600;">Mode</label><select id="pye-mode" style="width:100%;padding:8px;border:1px solid #ddd;border-radius:6px;font-size:13px;"><option>Bank</option><option>Cash</option><option>Bkash</option><option>Cheque</option></select></div>
      </div>
      <div><label style="font-size:12px;font-weight:600;">Pay From Account</label><select id="pye-bank" style="width:100%;padding:8px;border:1px solid #ddd;border-radius:6px;font-size:13px;">${(DB.banks||[]).map(b=>`<option value="${escHTML(b.name)}">${escHTML(bankDisplayId(b))} (Bal: ${f(b.bal||b.balance||0)})</option>`).join('')}</select></div>
      <div id="pye-splits"></div>
      <button type="button" style="background:#eff6ff;border:1px solid #2563eb;color:#2563eb;padding:8px 12px;border-radius:6px;font-size:12px;font-weight:700;cursor:pointer;text-align:left;" data-x-click="addPaymentSplit()">➕ Pay part from another account</button>
      <div id="pye-split-summary" style="font-size:12px;color:#374151;"></div>
      <div><label style="font-size:12px;font-weight:600;">Note</label><input type="text" id="pye-note" placeholder="Optional" style="width:100%;padding:8px;border:1px solid #ddd;border-radius:6px;font-size:13px;"></div>
      <button class="btn" style="width:100%;padding:12px;" data-x-click="savePaymentEntry()">💾 Save Payment</button>
