function showPartyBankHint(){
  const name=(document.getElementById('pye-party')?.value||'').trim().toLowerCase();
  const box=document.getElementById('pye-party-banks'); if(!box) return;
  const c=(DB.customers||[]).find(x=>x.name.toLowerCase()===name);
  if(!c){ box.innerHTML=''; return; }
  const accounts=[];
  if(c.bankName||c.bankAcc) accounts.push({bank:c.bankName,acc:c.bankAcc,branch:c.bankBranch});
  (c.bankAccounts||[]).forEach(b=>accounts.push(b));
  box.innerHTML = accounts.length
    ? '🏦 '+(c.code?c.code+' — ':'')+'Supplier accounts: '+accounts.map(a=>`${escHTML(a.bank||'')} ${a.acc||''}`.trim()).filter(Boolean).join(' • ')
    : (c.code?('ID: '+c.code):'');
}

function addPaymentSplit(){
  const box=document.getElementById('pye-splits'); if(!box) return;
  const opts=(DB.banks||[]).map(b=>`<option value="${escHTML(b.name)}">${escHTML(b.name)} (Bal: ${f(b.bal||b.balance||0)})</option>`).join('');
  const row=document.createElement('div');
  row.className='pye-split';
  row.style.cssText='display:grid;grid-template-columns:1.6fr 1fr auto;gap:8px;margin-bottom:6px;align-items:center;';
  row.innerHTML=`<select style="padding:8px;border:1px solid #ddd;border-radius:6px;font-size:13px;">${opts}</select>
    <input type="number" placeholder="Amount (৳)" data-x-input="updateSplitSummary()" style="padding:8px;border:1px solid #ddd;border-radius:6px;font-size:13px;">
    <button type="button" style="background:#fef2f2;border:1px solid #dc2626;color:#dc2626;border-radius:6px;padding:7px 10px;font-weight:700;cursor:pointer;" data-x-click="this.parentElement.remove();updateSplitSummary()">✕</button>`;
  box.appendChild(row);
  updateSplitSummary();
}

function getPaymentSplits(){
  return Array.from(document.querySelectorAll('#pye-splits .pye-split')).map(r=>({
    bank:r.querySelector('select').value,
    amt:parseFloat(r.querySelector('input').value)||0
  })).filter(s=>s.amt>0);
}

function updateSplitSummary(){
  const box=document.getElementById('pye-split-summary'); if(!box) return;
  const total=parseFloat(document.getElementById('pye-amt')?.value)||0;
  const splits=getPaymentSplits();
  if(!splits.length){ box.innerHTML=''; return; }
  const splitSum=splits.reduce((s,x)=>s+x.amt,0);
  const mainAmt=total-splitSum;
  const mainAcc=document.getElementById('pye-bank')?.value||'';
  if(total<=0){ box.innerHTML='<span style="color:#b45309;">Enter the total amount first.</span>'; return; }
  if(mainAmt<0){ box.innerHTML='<span style="color:#dc2626;">⚠️ Split amounts (${'+f(splitSum)+'}) exceed the total.</span>'.replace('${'+f(splitSum)+'}',f(splitSum)); return; }
  box.innerHTML=`<b>${mainAcc}</b> pays <b>${f(mainAmt)}</b>`+splits.map(s=>` • <b>${escHTML(s.bank)}</b> pays <b>${f(s.amt)}</b>`).join('')+` — total <b>${f(total)}</b>`;
}

async function savePaymentEntry(){
  const date=document.getElementById('pye-date')?.value;const type=document.getElementById('pye-type')?.value;
  const party=document.getElementById('pye-party')?.value;const amt=parseFloat(document.getElementById('pye-amt')?.value||0);
  const mode=document.getElementById('pye-mode')?.value;const bank=document.getElementById('pye-bank')?.value;
  const note=document.getElementById('pye-note')?.value;
  if(!requireFields([date,amt],'⚠️ Fill Date and Amount')) return;
  /* FIX: every entry made here is collected in _saved and its effect on the
     bank and the party is applied straight away. This used to end with a
     call to recalculateBalances(), which opens a confirmation dialog and
     rebuilds DB.parties — a list this app does not use — so nothing on
     screen moved after saving a payment until the page was reloaded, and
     the natural response was to enter the payment a second time. */
  const _saved=[];
  const splits=getPaymentSplits();
  if(!splits.length){
    _saved.push(pushTx({id:newId(),date,type,party,amt,amount:amt,mode,bank,acc:bank,note,inv:'PY-'+Date.now().toString().slice(-6),code:genCode('TXN')}));
  } else {
    const splitSum=splits.reduce((s,x)=>s+x.amt,0);
    if(splitSum>=amt){alert('⚠️ Split amounts must be less than the total. The main account pays the remainder.');return;}
    const parts=[{bank:bank,amt:amt-splitSum},...splits];
    if(parts.some(p=>!p.bank)){alert('⚠️ Select an account for every split row.');return;}
    // warn (not block) if any account lacks balance
    const short=parts.filter(p=>{const b=(DB.banks||[]).find(x=>x.name===p.bank);return b&&(b.bal||b.balance||0)<p.amt;});
    if(short.length && !await __confirm('⚠️ Insufficient balance in: '+short.map(p=>p.bank).join(', ')+'. Save anyway?')) return;
    const group='SPLIT-'+Date.now();
    const inv='PY-'+Date.now().toString().slice(-6);
    parts.forEach((p,i)=>{
      _saved.push(pushTx({id:newId(),date,type,party,amt:p.amt,amount:p.amt,mode,bank:p.bank,acc:p.bank,
        note:(note?note+' ':'')+`(Split ${i+1}/${parts.length})`,inv,splitGroup:group,code:genCode('TXN')}));
    });
    toast(`✅ Payment saved across ${parts.length} accounts!`,'s');
  }
  _saved.forEach(t=>{ try{ applyTxBalance(t,1); }catch(e){} });
  if(typeof saveDBNow==='function') saveDBNow(); else saveDB();
  ['renderBanks','renderCust','renderDash','renderTx','renderSupLedger'].forEach(fn=>{
    try{ if(typeof window[fn]==='function') window[fn](); }catch(e){}
  });
  if(!splits.length)toast('Payment saved!', 's');
  clearFields(['pye-amt','pye-party','pye-note']);
  const sb=document.getElementById('pye-splits'); if(sb) sb.innerHTML='';
  updateSplitSummary(); showPartyBankHint();
  try{renderPaymentEntry();}catch(e){}
}

function renderExpenseEntry(){
  const el=document.getElementById('pg-expenseentry');
  if(!el)return;
  const expTypes=['Expense','Staff Salary','Utility Bill','Office Expense','Transport Cost','Unload Cost','Extra Cost','Expense Payment'];
  const txs=(DB.tx||[]).filter(t=>expTypes.includes(t.type)).sort((a,b)=>(b.date||'').localeCompare(a.date||''));
  const total=txs.reduce((s,t)=>s+parseFloat(txAmt(t)),0);
  el.innerHTML=`<div class="page-header"><h2>💸 Expense Entry</h2><p>Uses the standard multi-product transaction form</p></div>
  <div class="card" style="text-align:center;padding:28px;margin-bottom:16px;">
    <div style="font-size:34px;margin-bottom:8px;">💸</div>
    <button class="btn btn-primary" style="padding:12px 26px;font-size:14px;font-weight:700;background:#dc2626;border:none;" data-x-click="openTxModalAs('Expense')">➕ New Expense</button>
  </div>
  <div class="card">
    <h3 style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:14px;">🕐 Recent Expenses (${txs.length}, total ${f(total)})</h3>
    ${txs.length?`<table class="tbl"><thead><tr><th>Date</th><th>Invoice</th><th>Type</th><th>Party/Payee</th><th>Amount</th><th>Mode</th><th></th></tr></thead>
    <tbody>${txs.slice(0,25).map(t=>`<tr>
      <td>${t.date||'—'}</td>
      <td style="color:#2563eb;">${t.inv||'—'}</td>
      <td>${t.type||'—'}</td>
      <td><strong>${escHTML(t.party ||'—')}</strong></td>
      <td><strong style="color:#dc2626;">${f(txAmt(t))}</strong></td>
      <td>${escHTML(t.mode||t.bank||'Cash')}</td>
      <td style="white-space:nowrap;"><button class="btn btn-xs btn-icon" style="background:#1a3a6b;color:#fff;margin-right:2px;" data-x-click="openModal(${t.id})" title="Edit">✏️</button><button class="btn btn-xs btn-icon" style="background:#f5a623;color:#000;margin-right:2px;" data-x-click="printTransaction(${t.id})" title="Print Voucher">🖨️</button><button class="btn btn-danger btn-xs btn-icon" data-x-click="delTx(${t.id})" title="Delete">🗑</button></td>
    </tr>`).join('')}</tbody></table>`
    :'<div style="text-align:center;padding:30px;color:#9ca3af;">No expenses recorded yet.</div>'}
  </div>`;
}

function renderJournalEntry(){
  const el=document.getElementById('pg-journalentry');
  if(!el)return;
  el.innerHTML=`<div class="page-header"><h2>📒 Journal Entry</h2><p>Double-entry bookkeeping journal</p></div>
  <div class="card" style="max-width:700px;margin:0 auto;">
    <h3>📒 New Journal Entry</h3>
    <div style="display:grid;gap:12px;">
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">
        <div><label style="font-size:12px;font-weight:600;">Date</label><input type="date" id="je-date" value="${new Date().toISOString().split('T')[0]}" style="width:100%;padding:8px;border:1px solid #ddd;border-radius:6px;font-size:13px;"></div>
        <div><label style="font-size:12px;font-weight:600;">Reference No</label><input type="text" id="je-ref" placeholder="JE-001" style="width:100%;padding:8px;border:1px solid #ddd;border-radius:6px;font-size:13px;"></div>
      </div>
      <div><label style="font-size:12px;font-weight:600;">Narration</label><textarea id="je-narr" rows="2" placeholder="Describe the journal entry..." style="width:100%;padding:8px;border:1px solid #ddd;border-radius:6px;font-size:13px;resize:vertical;"></textarea></div>
      <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;">
        <div><label style="font-size:12px;font-weight:600;">Debit Account</label><input type="text" id="je-dr-acc" placeholder="Account name" style="width:100%;padding:8px;border:1px solid #ddd;border-radius:6px;font-size:13px;"></div>
        <div><label style="font-size:12px;font-weight:600;">Credit Account</label><input type="text" id="je-cr-acc" placeholder="Account name" style="width:100%;padding:8px;border:1px solid #ddd;border-radius:6px;font-size:13px;"></div>
        <div><label style="font-size:12px;font-weight:600;">Amount (৳)</label><input type="number" id="je-amt" placeholder="0.00" style="width:100%;padding:8px;border:1px solid #ddd;border-radius:6px;font-size:13px;"></div>
      </div>
      <button class="btn" style="width:100%;padding:12px;" data-x-click="saveJournalEntry()">💾 Post Journal Entry</button>
    </div>
  </div>`;
}


/* ── FIX (opening balance typed straight into the bank, then ALSO posted as
   an opening Journal Entry — the same money counted twice) ───────────────
   How the problem arises: a bank account is created and its balance is
   typed directly into the account (bank.bal), with no transaction behind
   it. That is exactly what makes the row show "⚠ unlinked". Clicking
   "Post Opening Entry" then posts Dr <bank> / Cr <capital>, and
   applyTxBalance() ADDS that amount on top of the balance that was already
   sitting there — so the bank shows twice its real money right after
   posting, and the Balance Sheet / Trial Balance tilt by the same figure.
   (On the next boot recomputeBalances() rebuilds from openingBal + the
   journal, so the figure silently changes again — two different answers
   for the same account.)

   The rule this enforces: an opening balance is either a typed seed OR a
   posted journal entry — never both. When the opening entry is posted for
   a bank whose seed matches it, the seed is absorbed (cleared) so the
   journal supplies the figure exactly once, on screen and after reload. */
function ayanAbsorbDirectBankSeed(bankName, amount){
  const name = String(bankName||'').trim();
  const a    = parseFloat(amount)||0;
  if(!name || !a) return false;
  const bank = (DB.banks||[]).find(b=>b.name===name);
  if(!bank) return false;
  const typed = (bank.openingBal!=null && bank.openingBal!=='');
  let seed;
  try{ seed = typed ? (parseFloat(bank.openingBal)||0) : ayanBankOpening(name,''); }
  catch(e){ seed = typed ? (parseFloat(bank.openingBal)||0) : 0; }
  if(!seed) return false;                       // nothing pre-seeded: normal entry
  if(Math.abs(seed - a) > 0.01) return false;   // a different figure: never touch it
  bank.openingBal = 0;
  bank.opening    = 0;
  bank.bal        = (parseFloat(bank.bal)||0) - a;  // the journal puts it straight back
  try{ if(DB.openingBalance) delete DB.openingBalance['bank_'+name]; }catch(e){}
  return true;
}

/* Repair for accounts where this already happened before the fix above
   existed: a bank that still carries a typed seed AND has an opening
   Journal Entry for the same amount is holding the money twice. Clearing
   the seed leaves the journal as the single source. */
function ayanFindDoubleSeededBanks(){
  const jes = (DB.tx||[]).filter(t=>(t.type||'')==='Journal Entry');
  const out = [];
  (DB.banks||[]).forEach(b=>{
    const seed = parseFloat(b.openingBal)||0;
    if(!seed) return;
    const hit = jes.find(t=>String(t.acc||'').trim()===b.name &&
      Math.abs((parseFloat(t.amount!=null?t.amount:t.amt)||0) - seed) <= 0.01);
    if(hit) out.push({bank:b, tx:hit, amount:seed});
  });
  return out;
}

function ayanFixDoubleSeededBanks(){
  const hits = ayanFindDoubleSeededBanks();
  if(!hits.length){ if(typeof toast==='function') toast('No double-counted opening balances found.','i'); return; }
  const total = hits.reduce((s,h)=>s+h.amount,0);
  if(!confirm(hits.length+' account(s) carry an opening balance twice — once typed into the account and once as a Journal Entry (৳'
      +total.toLocaleString('en-IN',{minimumFractionDigits:2})+' in total).\n\nKeep the Journal Entry and clear the typed figure?')) return;
  hits.forEach(h=>{
    h.bank.openingBal = 0;
    h.bank.opening    = 0;
    try{ if(DB.openingBalance) delete DB.openingBalance['bank_'+h.bank.name]; }catch(e){}
  });
  saveDB();
  try{ if(typeof recomputeBalances==='function') recomputeBalances({apply:true}); }catch(e){}
  try{ renderDash(); }catch(e){}
  try{ if(document.getElementById('bk-all-summary')?.style.display==='block') renderAllBankAccountsSummary(); }catch(e){}
  try{ ayanShowDupBanner(); }catch(e){}
  if(typeof toast==='function') toast(hits.length+' opening balance(s) de-duplicated — balances rebuilt.','s');
}

/* Batch-posts an Opening Balance Journal Entry (Dr <bank account> / Cr the
   chosen equity account, e.g. "Opening Balance Equity") for every bank
   account currently flagged "⚠ unlinked" in the All Accounts Summary —
   i.e. every account that carries an opening balance with zero linked
   transactions. This is the one-click equivalent of clicking
   "📒 Post Opening Entry" on each unlinked row in turn and posting the
   Journal Entry form for it; it reuses the exact same detection logic
   (renderAllBankAccountsSummary) and the exact same posting logic
   (ayanAbsorbDirectBankSeed + pushTx as type:'Journal Entry') so results
   can never disagree with what the summary screen shows or what a manual
   post would have produced. Safe to re-run: once an account's seed has
   been absorbed by a posted entry it no longer reads as "unlinked", so a
   second run finds nothing left to post for it. */
async function postAllOpeningEntries(){
  const banks=(DB.banks||[]).slice();
  const rows=banks.map(b=>{
    const name=b.name;
    const opening=ayanBankOpening(name,'');
    let hasTx=false;
    (DB.tx||[]).forEach(t=>{
      const split=Array.isArray(t.payAccounts)?t.payAccounts.find(p=>p&&p.acc===name):null;
      const acctMatch=t.acc===name||t.acc2===name||!!split;
      if(!acctMatch) return;
      const m=ayanBankMove(t,name);
      if(m.in||m.out) hasTx=true;
    });
    return {name,opening,unlinked:!hasTx&&!!opening};
  }).filter(r=>r.unlinked);

  if(!rows.length){ if(typeof toast==='function') toast('No unlinked accounts — nothing to post.','i'); return; }

  const date=document.getElementById('ob-batch-date')?.value||new Date().toISOString().split('T')[0];
  const credit=(document.getElementById('ob-batch-credit')?.value||'Opening Balance Equity').trim()||'Opening Balance Equity';
  const total=rows.reduce((s,r)=>s+r.opening,0);
  const list=rows.map(r=>`• ${r.name} — ৳${pf(r.opening)}`).join('\n');
  if(!await __confirm(`Post ${rows.length} opening balance journal entr${rows.length===1?'y':'ies'} totalling ৳${pf(total)}?\n\n${list}\n\nEach posts as Dr <account> / Cr "${credit}", dated ${date}.`)) return;

  let posted=0;
  rows.forEach(r=>{
    const _seedAbsorbed=ayanAbsorbDirectBankSeed(r.name,r.opening);
    pushTx({id:newId(),date,type:'Journal Entry',party:r.name,acc:r.name,acc2:credit,
      note:`Dr: ${r.name} | Cr: ${credit} | Opening balance for ${r.name}`+(_seedAbsorbed?' (typed seed replaced, not stacked)':''),
      amt:r.opening,amount:r.opening,inv:'OB-'+newId(),mode:'Journal'});
    posted++;
  });
  saveDB();
  if(typeof toast==='function') toast(`✅ ${posted} opening balance entr${posted===1?'y':'ies'} posted (৳${pf(total)} total).`,'s');
  try{ renderAllBankAccountsSummary(); }catch(e){}
  try{ renderDash(); }catch(e){}
}

function saveJournalEntry(){
  const date=document.getElementById('je-date')?.value;const ref=document.getElementById('je-ref')?.value||'JE-'+Date.now().toString().slice(-6);
  const narr=document.getElementById('je-narr')?.value;const drAcc=document.getElementById('je-dr-acc')?.value;
  const crAcc=document.getElementById('je-cr-acc')?.value;const amt=parseFloat(document.getElementById('je-amt')?.value||0);
  if(!requireFields([date,amt],'⚠️ Fill Date and Amount')) return;
  if(!drAcc||!crAcc){ toast('⚠️ Enter both a Debit and a Credit account','e'); return; }
  if(drAcc.trim()===crAcc.trim()){ toast('⚠️ Debit and Credit account cannot be the same','e'); return; }
  /* FIX: the row was saved with `amt` only. applyTxBalance() reads
     parseFloat(tx.amount), so every journal entry posted a value of 0 and
     never moved a single balance — the real reason a bank kept its
     "⚠ unlinked" flag after Post Opening Entry. Both names are written. */
  /* An opening entry for a bank whose balance was typed in directly must
     replace that seed, not stack on top of it (see helper above). */
  const _seedAbsorbed = ayanAbsorbDirectBankSeed(drAcc, amt);
  pushTx({id:newId(),date,type:'Journal Entry',party:drAcc,acc:drAcc.trim(),acc2:crAcc.trim(),note:`Dr: ${drAcc} | Cr: ${crAcc} | ${narr}`,amt,amount:amt,inv:ref,mode:'Journal'});
  saveDB();toast(_seedAbsorbed?'Opening entry posted — the balance already typed into this account was replaced, not added again.':'Journal entry posted — balances updated.', 's');
  clearFields(['je-ref','je-narr','je-dr-acc','je-cr-acc','je-amt']);
  /* Refresh the Bank Reconciliation summary if it is what sent us here, so
     the "⚠ unlinked" flag visibly clears instead of needing a reload. */
  try{ if(document.getElementById('bk-all-summary')?.style.display==='block') renderAllBankAccountsSummary(); }catch(e){}
}

/* Jumps to Journal Entry and pre-fills a Dr <bank account> / Cr Partner
   Capital line for the given amount — the one-click fix for a bank account
   flagged "⚠ unlinked" on the Bank Reconciliation summary and the Trial
   Balance mismatch check. Credit account defaults to "Partner Capital" but
   stays editable, since the real source may be a loan or another account. */
function openJournalForUnlinkedBank(bankName, amount){
  nav('journalentry');
  /* FIX: nav() may re-render the page after this call returns, wiping any
     value written synchronously. The prefill is retried on the next frame
     (and once more shortly after) so it survives an async render. */
  const fill = () => {
    const dr   = document.getElementById('je-dr-acc');
    const cr   = document.getElementById('je-cr-acc');
    const amt  = document.getElementById('je-amt');
    const narr = document.getElementById('je-narr');
    if(!dr || !cr || !amt) return false;
    /* Credit an account that actually exists, otherwise the credit side is
       a dead string and only half the entry ever posts. Falls back to the
       first partner on record before the generic "Partner Capital" label. */
    const firstPartner = ((DB.partners||[])[0]||{}).name || '';
    dr.value   = bankName;
    cr.value   = firstPartner || 'Partner Capital';
    amt.value  = Number(amount||0).toFixed(2);
    if(narr) narr.value = `Opening balance source for ${bankName} (previously unlinked) — confirm the real source before posting.`;
    cr.focus(); cr.select && cr.select();
    return true;
  };
  if(!fill()){ requestAnimationFrame(()=>{ if(!fill()) setTimeout(fill,150); }); }
  else { requestAnimationFrame(fill); }
  if(typeof toast==='function') toast('Confirm the Credit account, then post the entry.', 'i');
}

/* ── Duplicate Opening-Entry Detector & Cleanup ──────────────────────────
   The recomputeBalances() bug that let a doubled Dr-Bank/Cr-Partner-Capital
   posting drain twice the correct amount is already fixed (see the
   Journal Entry branch in the balance-movement helper above) — the boot
   rebuild no longer double-counts these rows. This is just cleanup: if
   "Post Opening Entry" (or a manual equivalent) was posted more than once
   for the same bank/amount, the extra rows are still sitting in the
   ledger and worth removing so reports/exports don't show a doubled
   opening entry even though the balance itself is already correct. */
function ayanFindDuplicateOpenings(){
  const txs=(DB.tx||[]).filter(t=>(t.type||'')==='Journal Entry');
  const groups={};
  txs.forEach(t=>{
    const acc=(t.acc||'').trim();
    const acc2=(t.acc2||'').trim();
    const amt=parseFloat(t.amount!=null?t.amount:t.amt)||0;
    if(!acc||!acc2||!amt) return;
    // Only the specific "opening balance source" pattern created by
    // openJournalForUnlinkedBank() / a manual Dr-bank / Cr-Partner-Capital
    // opening posting — not every ordinary journal entry.
    const looksLikeOpening = /partner capital/i.test(acc2) || /opening balance source/i.test(t.note||t.rem||'');
    if(!looksLikeOpening) return;
    const key=acc+'|'+acc2+'|'+amt;
    (groups[key]=groups[key]||[]).push(t);
  });
  // stable date order so "kept" is always the earliest posting
  Object.values(groups).forEach(g=>g.sort((a,b)=>(a.date||'').localeCompare(b.date||'')||(a.id-b.id)));
  return Object.values(groups).filter(g=>g.length>1);
}

function ayanShowDupBanner(){
  const slot=document.getElementById('ayan-dup-banner');
  if(!slot) return;
  const dupGroups=ayanFindDuplicateOpenings();
  /* Banks holding their opening balance twice (typed seed + journal entry). */
  const seeded=(typeof ayanFindDoubleSeededBanks==='function')?ayanFindDoubleSeededBanks():[];
  const seedBanner = seeded.length ? `
    <div style="background:#fee2e2;border:1.5px solid #fca5a5;border-radius:10px;padding:14px 16px;margin-bottom:16px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;">
      <div>
        <div style="font-weight:800;color:#991b1b;font-size:13px;">⚠️ ${seeded.length} bank account(s) are counting their opening balance twice (৳${seeded.reduce((s2,h)=>s2+h.amount,0).toLocaleString('en-IN',{minimumFractionDigits:2})})</div>
        <div style="font-size:11px;color:#991b1b;margin-top:2px;">The balance was typed straight into the account and also posted as an opening Journal Entry: ${seeded.map(h=>escHTML(h.bank.name)).join(', ')}</div>
      </div>
      <button data-x-click="ayanFixDoubleSeededBanks()" style="padding:8px 16px;background:#991b1b;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:12px;white-space:nowrap;">Fix — keep the Journal Entry</button>
    </div>` : '';
  if(!dupGroups.length){ slot.innerHTML=seedBanner; return; }
  const extraCount=dupGroups.reduce((s,g)=>s+(g.length-1),0);
  const totalExtraAmt=dupGroups.reduce((s,g)=>s+(g.length-1)*(parseFloat(g[0].amount!=null?g[0].amount:g[0].amt)||0),0);
  slot.innerHTML=seedBanner+`
    <div style="background:#fef3c7;border:1.5px solid #fbbf24;border-radius:10px;padding:14px 16px;margin-bottom:16px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;">
      <div>
        <div style="font-weight:800;color:#92400e;font-size:13px;">⚠️ ${dupGroups.length} duplicate opening ${dupGroups.length===1?'entry':'entries'} found (${extraCount} extra row${extraCount===1?'':'s'}, ৳${totalExtraAmt.toLocaleString('en-IN',{minimumFractionDigits:2})} posted twice)</div>
        <div style="font-size:11px;color:#92400e;margin-top:2px;">Balances already rebuild correctly on load — this only cleans up the doubled ledger rows.</div>
      </div>
      <button data-x-click="ayanReviewDuplicateOpenings()" style="padding:8px 16px;background:#92400e;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:12px;white-space:nowrap;">Review &amp; Clean Up</button>
    </div>`;
}

function ayanReviewDuplicateOpenings(){
  const dupGroups=ayanFindDuplicateOpenings();
  const existing=document.getElementById('ayan-dup-review-modal');
  if(existing) existing.remove();
  if(!dupGroups.length){ if(typeof toast==='function') toast('No duplicate opening entries found.','i'); return; }
  const isDark=document.documentElement.getAttribute('data-theme')==='dark';
  const bg=isDark?'#1e293b':'#fff';
  const textColor=isDark?'#f1f5f9':'#1a202c';
  const modal=document.createElement('div');
  modal.id='ayan-dup-review-modal';
  modal.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.6);z-index:2000;display:flex;align-items:center;justify-content:center;padding:20px;';
  modal.innerHTML=`
    <div style="background:${bg};border-radius:16px;padding:24px;width:100%;max-width:640px;max-height:80vh;overflow-y:auto;color:${textColor};box-shadow:0 8px 32px rgba(0,0,0,.3);">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;">
        <div style="font-size:16px;font-weight:800;">🧹 Duplicate Opening Entries</div>
        <span style="cursor:pointer;font-size:18px;" data-x-click="document.getElementById('ayan-dup-review-modal').remove()">✕</span>
      </div>
      ${dupGroups.map(g=>{
        const acc=escHTML(g[0].acc||'');
        const acc2=escHTML(g[0].acc2||'');
        const amt=parseFloat(g[0].amount!=null?g[0].amount:g[0].amt)||0;
        return `<div style="border:1px solid #e5e7eb;border-radius:10px;padding:12px;margin-bottom:12px;">
          <div style="font-weight:700;font-size:13px;margin-bottom:8px;">Dr ${acc} / Cr ${acc2} — ৳${amt.toLocaleString('en-IN',{minimumFractionDigits:2})} × ${g.length}</div>
          ${g.map((t,i)=>`
            <div style="display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-top:1px dashed #e5e7eb;font-size:12px;gap:10px;">
              <span>${t.date||'—'} · ${escHTML(t.inv||'no ref')} ${i===0?'<span style="color:#16a34a;font-weight:700;">(kept)</span>':''}</span>
              ${i===0?'':`<button data-x-click="ayanDeleteDupOpening(${JSON.stringify(t.id)})" style="padding:4px 10px;background:#dc2626;color:#fff;border:none;border-radius:6px;font-size:11px;font-weight:700;cursor:pointer;white-space:nowrap;">Delete this one</button>`}
            </div>`).join('')}
        </div>`;
      }).join('')}
    </div>`;
  document.body.appendChild(modal);
}

function ayanDeleteDupOpening(txId){
  const idx=(DB.tx||[]).findIndex(t=>String(t.id)===String(txId));
  if(idx<0){ if(typeof toast==='function') toast('Entry not found (already removed?)','e'); return; }
  DB.tx.splice(idx,1);
  DB.transactions=DB.tx;
  saveDB();
  try{ if(typeof recomputeBalances==='function') recomputeBalances({apply:true}); }catch(e){}
  try{renderDash();}catch(e){}
  try{renderTx();}catch(e){}
  if(typeof toast==='function') toast('Duplicate entry removed — balances rebuilt.','s');
  // Refresh the review list in place instead of closing it, so the rest
  // of the duplicates (if any) can be worked through in one pass.
  ayanReviewDuplicateOpenings();
}


function renderInterTransfer(){
  const el=document.getElementById('pg-intertransfer');
  if(!el)return;
  const banks=DB.banks||[];
  const transfers=(DB.tx||[]).filter(t=>t.type==='Inter Transfer'||t.type==='Bank Transfer').sort((a,b)=>b.date.localeCompare(a.date));
  const totalTransferred=transfers.reduce((s,t)=>s+txAmt(t),0);

  el.innerHTML=`<div class="page-header"><h2>🔄 Inter-Account Transfer</h2><p>Transfer funds between bank accounts</p></div>
  <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:12px;margin-bottom:20px;">
    <div class="kpi-card"><div class="kpi-icon">🏦</div><div class="kpi-val">${banks.length}</div><div class="kpi-label">Bank Accounts</div></div>
    <div class="kpi-card"><div class="kpi-icon">🔄</div><div class="kpi-val">${transfers.length}</div><div class="kpi-label">Transfers Made</div></div>
    <div class="kpi-card"><div class="kpi-icon">💰</div><div class="kpi-val">${f(totalTransferred)}</div><div class="kpi-label">Total Transferred</div></div>
  </div>
  <div class="card" style="max-width:640px;margin:0 auto 20px;">
    <h3 style="font-size:15px;font-weight:800;color:#0f3d26;margin-bottom:16px;">🔄 New Transfer</h3>
    <div style="display:grid;gap:12px;">
      <div><label style="font-size:12px;font-weight:700;color:#374151;">Date</label>
        <input type="date" id="it-date" value="${new Date().toISOString().split('T')[0]}" style="width:100%;padding:9px 12px;border:1.5px solid #d1d5db;border-radius:8px;font-size:13px;margin-top:4px;"></div>
      <div><label style="font-size:12px;font-weight:700;color:#374151;">From Account</label>
        <select id="it-from" style="width:100%;padding:9px 12px;border:1.5px solid #d1d5db;border-radius:8px;font-size:13px;margin-top:4px;">
          ${banks.length?banks.map(b=>`<option value="${escHTML(b.name)}">${escHTML(bankDisplayId(b))} — ৳${pf(b.bal||0)}</option>`).join(''):'<option>No bank accounts found</option>'}
        </select></div>
      <div><label style="font-size:12px;font-weight:700;color:#374151;">To Account</label>
        <select id="it-to" style="width:100%;padding:9px 12px;border:1.5px solid #d1d5db;border-radius:8px;font-size:13px;margin-top:4px;">
          ${banks.length?banks.map(b=>`<option value="${escHTML(b.name)}">${escHTML(bankDisplayId(b))} — ৳${pf(b.bal||0)}</option>`).join(''):'<option>No bank accounts found</option>'}
        </select></div>
      <div><label style="font-size:12px;font-weight:700;color:#374151;">Amount (৳)</label>
        <input type="number" id="it-amt" placeholder="0.00" style="width:100%;padding:9px 12px;border:1.5px solid #d1d5db;border-radius:8px;font-size:13px;margin-top:4px;"></div>
      <div><label style="font-size:12px;font-weight:700;color:#374151;">Transfer Charge (৳)</label>
        <input type="number" id="it-charge" value="0" style="width:100%;padding:9px 12px;border:1.5px solid #d1d5db;border-radius:8px;font-size:13px;margin-top:4px;"></div>
      <div><label style="font-size:12px;font-weight:700;color:#374151;">Reference / Note</label>
        <input type="text" id="it-note" placeholder="Transfer reference or description..." style="width:100%;padding:9px 12px;border:1.5px solid #d1d5db;border-radius:8px;font-size:13px;margin-top:4px;"></div>
      <button class="btn" style="width:100%;padding:12px;background:#16a34a;color:#fff;font-size:14px;font-weight:700;border-radius:8px;" data-x-click="saveInterTransfer()">🔄 Execute Transfer</button>
    </div>
  </div>
  <div class="card">
    <h3 style="font-size:15px;font-weight:800;color:#0f3d26;margin-bottom:14px;">📋 Transfer History</h3>
    ${transfers.length?`<table class="tbl"><thead><tr><th>Date</th><th>From</th><th>To</th><th>Amount</th><th>Charge</th><th>Reference</th></tr></thead>
    <tbody>${transfers.map(t=>`<tr>
      <td>${t.date}</td>
      <td><strong>${escHTML(t.fromBank||t.party||'—')}</strong></td>
      <td><strong>${escHTML(t.toBank||t.bank||'—')}</strong></td>
      <td><strong style="color:#16a34a;">৳${pf(txAmt(t))}</strong></td>
      <td style="color:#d97706;">${t.charge?'৳'+pf(t.charge):'—'}</td>
      <td style="font-size:11px;color:#6b7280;">${escHTML(t.note||t.desc||'—')}</td>
    </tr>`).join('')}</tbody></table>`
    :'<div style="text-align:center;padding:30px;color:#9ca3af;">No transfers recorded yet.</div>'}
  </div>`;
}

function saveInterTransfer(){
  const date=document.getElementById('it-date')?.value;
  const fromAcc=document.getElementById('it-from')?.value;
  const toAcc=document.getElementById('it-to')?.value;
  const amt=parseFloat(document.getElementById('it-amt')?.value)||0;
  const charge=parseFloat(document.getElementById('it-charge')?.value)||0;
  const note=document.getElementById('it-note')?.value||'';

  if(!date){toast('Please select a date','e');return;}
  if(!fromAcc){toast('Please select source account','e');return;}
  if(!toAcc){toast('Please select destination account','e');return;}
  if(fromAcc===toAcc){toast('Source and destination cannot be the same','e');return;}
  if(!amt||amt<=0){toast('Please enter a valid amount','e');return;}

  // ── Bank balance check ──
  const check=checkBankBalance(fromAcc, amt+charge);
  if(!check.ok){
    showInsufficientBalanceWarning(fromAcc, amt+charge, check.bal, null);
    return;
  }

  // ── Save transfer as two transactions ──
  if(!DB.tx) DB.tx=[];
  const txId1=nextTxId();
  const txId2=nextTxId();

  DB.tx.push({id:txId1,date,type:'Bank Transfer',party:toAcc,acc:fromAcc,acc2:toAcc,
    amount:amt,amt:amt,note:'Transfer to '+toAcc+(note?' — '+note:''),mode:'Bank Transfer'});

  if(charge>0){
    DB.tx.push({id:txId2,date,type:'Bank Charge',acc:fromAcc,
      amount:charge,amt:charge,note:'Transfer charge for '+fromAcc+'→'+toAcc,mode:'Bank Charge'});
  }

  // ── Update balances ──
  const fromBank=(DB.banks||[]).find(b=>b.name===fromAcc);
  const toBank=(DB.banks||[]).find(b=>b.name===toAcc);
  if(fromBank) fromBank.bal=(fromBank.bal||0)-amt-charge;
  if(toBank) toBank.bal=(toBank.bal||0)+amt;

  saveDB();
  logAudit('TRANSFER','Bank','Transferred ৳'+amt+' from '+fromAcc+' to '+toAcc);
  toast('✅ Transfer of ৳'+amt.toLocaleString('en-IN')+' completed!','s');

  // Reset form
  if(document.getElementById('it-amt')) document.getElementById('it-amt').value='';
  if(document.getElementById('it-charge')) document.getElementById('it-charge').value=0;
  if(document.getElementById('it-note')) document.getElementById('it-note').value='';

  // Refresh page
  try{renderInterTransfer();}catch(e){}
  try{renderDash();}catch(e){}
}

function renderBkashLedger(){
  const el=document.getElementById('pg-bkashledger');
  if(!el)return;
  const bkashTx=(DB.tx||[]).filter(t=>
    t.mode==='Bkash'||t.mode==='bKash'||
    t.bank==='Bkash Account'||t.bank==='bKash'||
    (t.type||'').toLowerCase().includes('bkash')
  ).sort((a,b)=>b.date.localeCompare(a.date));

  const inTypes=new Set(['Bkash Deposit','Cash Received','Bkash Cash In','Sales Receipt']);
  const outTypes=new Set(['Bkash Withdrawal','Bkash Cash Out','Send Money','Bkash Payment']);
  const totalIn=bkashTx.filter(t=>inTypes.has(t.type)||(t.mode==='Bkash'&&['Sale','Sales Receipt','Cash Received'].includes(t.type))).reduce((s,t)=>s+txAmt(t),0);
  const totalOut=bkashTx.filter(t=>outTypes.has(t.type)||(t.mode==='Bkash'&&['Purchase','Expense','Payment'].includes(t.type))).reduce((s,t)=>s+txAmt(t),0);
  const charges=bkashTx.reduce((s,t)=>s+(t.charge||0),0);
  const balance=totalIn-totalOut-charges;

  let runBal=0;
  const rows=[...bkashTx].reverse().map(t=>{
    const isIn=inTypes.has(t.type)||(t.mode==='Bkash'&&['Sale','Sales Receipt','Cash Received'].includes(t.type));
    const amt=t.amt||t.amount||0;
    if(isIn) runBal+=amt; else runBal-=amt;
    return {t,isIn,amt,bal:runBal};
  }).reverse();

  el.innerHTML=`<div class="page-header"><h2>📱 bKash Ledger</h2><p>All bKash transactions and balance</p></div>
  <div style="background:linear-gradient(135deg,#be185d,#ec4899);color:#fff;border-radius:14px;padding:20px;margin-bottom:20px;">
    <div style="font-size:11px;opacity:.8;font-weight:700;text-transform:uppercase;">bKash Balance</div>
    <div style="font-size:36px;font-weight:900;margin-top:6px;">${f(balance)}</div>
    <div style="font-size:11px;opacity:.75;margin-top:4px;">${bkashTx.length} total transactions</div>
  </div>
  <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:12px;margin-bottom:20px;">
    <div class="kpi-card" style="border-left:4px solid #16a34a;"><div class="kpi-icon">📥</div><div class="kpi-val" style="color:#16a34a;">${f(totalIn)}</div><div class="kpi-label">Total In</div></div>
    <div class="kpi-card" style="border-left:4px solid #dc2626;"><div class="kpi-icon">📤</div><div class="kpi-val" style="color:#dc2626;">${f(totalOut)}</div><div class="kpi-label">Total Out</div></div>
    <div class="kpi-card" style="border-left:4px solid #d97706;"><div class="kpi-icon">💸</div><div class="kpi-val" style="color:#d97706;">${f(charges)}</div><div class="kpi-label">Charges Paid</div></div>
    <div class="kpi-card" style="border-left:4px solid #7c3aed;"><div class="kpi-icon">📊</div><div class="kpi-val" style="color:#7c3aed;">${bkashTx.length}</div><div class="kpi-label">Transactions</div></div>
    <div class="kpi-card" style="border-left:4px solid #be185d;"><div class="kpi-icon">📱</div><div class="kpi-val" style="color:#be185d;">${f(balance<0?Math.abs(balance):0)}</div><div class="kpi-label">bKash Due</div></div>
  </div>
  <div class="card">
    <h3 style="font-size:15px;font-weight:800;color:#be185d;margin-bottom:14px;">📱 bKash Transaction History</h3>
    ${rows.length?`<table class="tbl"><thead><tr>
      <th>Date</th><th>Type</th><th>Party</th><th>In (৳)</th><th>Out (৳)</th><th>Charge</th><th>Balance (৳)</th>
    </tr></thead>
    <tbody>${rows.map(({t,isIn,amt,bal})=>`<tr>
      <td>${t.date}</td>
      <td><span style="padding:2px 8px;border-radius:8px;font-size:10px;font-weight:700;background:${isIn?'#dcfce7':'#fee2e2'};color:${isIn?'#16a34a':'#dc2626'};">${t.type}</span></td>
      <td>${escHTML(t.party ||'—')}</td>
      <td style="color:#16a34a;font-weight:700;">${isIn?f(amt):'—'}</td>
      <td style="color:#dc2626;font-weight:700;">${!isIn?f(amt):'—'}</td>
      <td style="color:#d97706;">${t.charge?f(t.charge):'—'}</td>
      <td style="font-weight:800;color:${bal>=0?'#16a34a':'#dc2626'};">${f(bal)}</td>
    </tr>`).join('')}</tbody></table>`
    :'<div style="text-align:center;padding:30px;color:#9ca3af;">No bKash transactions found.<br><small>Transactions with mode "Bkash" or bKash-type entries will appear here.</small></div>'}
  </div>`;
}

function plSetPeriod(period){
  window._plPeriod=period;
  if(period!=='custom'){window._plFrom='';window._plTo='';}
  renderProfitLoss();
}
function plSetCustom(){
  window._plPeriod='custom';
  /* FIX (2026-08-28, structural audit): the Profit & Loss page's own
     date-range inputs shared the ids "pl-from"/"pl-to" with the always-
     present (just hidden) Partner Ledger page's date filter — the exact
     same ids, coexisting in the DOM. getElementById always returns the
     FIRST match in document order, and Partner Ledger comes first, so this
     used to silently read Partner Ledger's date fields instead of P&L's
     own — the P&L "Custom" range never actually used what was typed here.
     Renamed to pl2-from/pl2-to (see renderProfitLoss below) so each page
     has its own unique ids. */
  window._plFrom=(document.getElementById('pl2-from')||{}).value||'';
  window._plTo=(document.getElementById('pl2-to')||{}).value||'';
  renderProfitLoss();
}
function plRange(){
  const today=new Date().toISOString().split('T')[0];
  const d=new Date();
  switch(window._plPeriod||'all'){
    case 'month': return [today.slice(0,7)+'-01', today];
    case 'lastmonth':{
      const a=new Date(d.getFullYear(),d.getMonth()-1,1).toISOString().split('T')[0];
      const b=new Date(d.getFullYear(),d.getMonth(),0).toISOString().split('T')[0];
      return [a,b];
    }
    case 'year': return [d.getFullYear()+'-01-01', today];
    case 'custom': return [window._plFrom||'1970-01-01', window._plTo||today];
    default: return ['1970-01-01', today];
  }
}
function renderProfitLoss(){
  const el=document.getElementById('pg-profitloss');
  if(!el)return;
  const [plFrom,plTo]=plRange();
  const tx=(DB.tx||[]).filter(t=>(t.date||'')>=plFrom&&(t.date||'')<=plTo);
  const sales=tx.filter(isRevenueTx).reduce((s,t)=>s+txAmt(t),0);
  const salesRet=tx.filter(t=>t.type==='Sales Return').reduce((s,t)=>s+txAmt(t),0);
  const purchRet=tx.filter(t=>t.type==='Purchase Return').reduce((s,t)=>s+txAmt(t),0);
  /* FIX (2026-08-28, structural audit): the "Purchases" row further down
     this table referenced a variable "purch" that was never declared
     anywhere in this function — a ReferenceError on every single call,
     since the very first line of the table body. The whole function's own
     try/catch wrapper (added later, see the "ayan-pl-corrected" patch
     below) silently swallowed that error, so this entire P&L view —
     including the Custom Date Range picker above it — has never actually
     rendered; only the appended "Cost-of-Sales Corrected View" box below
     it ever showed. window.sumCogs() is the same canonical "total gross
     purchase-type transactions" helper already used elsewhere in the file
     (e.g. the Charts Dashboard). */
  const purch=window.sumCogs(tx);
  const expenses=['Salary Payment','Office Rent','Electricity Bill','Internet Bill','Telephone Bill','Fuel Expense','Transport Cost','Loading Charge','Unloading Charge','Commission Payment','Maintenance Cost','Repair Expense','Stationery Purchase','Other Expense'];
  const totalExp=tx.filter(t=>expenses.includes(t.type)).reduce((s,t)=>s+txAmt(t),0);
  const netSales=sales-salesRet;
  // COGS = cost of goods actually sold (not all purchases; unsold stock = inventory asset)
  const cogsAmt=window.computeCOGS(tx)-purchRet;
  const grossProfit=netSales-cogsAmt;
  const netProfit=grossProfit-totalExp;
  const pd=window._plPeriod||'all';
  const pbtn=(val,lbl)=>`<button data-x-click="plSetPeriod('${val}')" style="padding:7px 14px;border:1.5px solid ${pd===val?'#16a34a':'#d1d5db'};background:${pd===val?'#16a34a':'#fff'};color:${pd===val?'#fff':'#374151'};border-radius:20px;font-size:12px;font-weight:700;cursor:pointer;">${lbl}</button>`;
  el.innerHTML=`<div class="page-header"><h2>📊 Profit & Loss Statement</h2><p>Income and expense summary</p></div>
  <div style="max-width:700px;margin:0 auto 14px;display:flex;gap:8px;flex-wrap:wrap;align-items:center;justify-content:center;">
    ${pbtn('all','All Time')}${pbtn('month','This Month')}${pbtn('lastmonth','Last Month')}${pbtn('year','This Year')}
    <input id="pl2-from" type="date" value="${pd==='custom'?(window._plFrom||''):''}" data-x-change="plSetCustom()" style="padding:6px 10px;border:1.5px solid ${pd==='custom'?'#16a34a':'#d1d5db'};border-radius:8px;font-size:12px;"/>
    <span style="font-size:11px;color:#6b7280;">to</span>
    <input id="pl2-to" type="date" value="${pd==='custom'?(window._plTo||''):''}" data-x-change="plSetCustom()" style="padding:6px 10px;border:1.5px solid ${pd==='custom'?'#16a34a':'#d1d5db'};border-radius:8px;font-size:12px;"/>
  </div>
  <div class="card" style="max-width:700px;margin:0 auto;">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:20px;">
      <div><h3 style="margin:0;">📊 P&L Statement</h3>
      <div style="font-size:11px;color:#6b7280;margin-top:2px;">Period: ${pd==='all'?'All Time':plFrom+' → '+plTo} · ${tx.length} transactions</div></div>
      <button class="btn btn-outline" data-x-click="printProfitLoss()">🖨️ Print</button>
    </div>
    <table style="width:100%;border-collapse:collapse;">
      <tr style="background:#f0fdf4;"><td colspan="2" style="padding:10px 14px;font-weight:700;color:#166534;font-size:14px;">INCOME</td></tr>
      <tr data-x-click="openPLDrill('${plFrom}','${plTo}')" style="cursor:pointer;" title="Click to see these transactions"><td style="padding:8px 14px;border-bottom:1px solid #f0f0f0;">Sales Revenue →</td><td style="padding:8px 14px;text-align:right;font-weight:600;">${f(sales)}</td></tr>
      <tr data-x-click="openPLDrill('${plFrom}','${plTo}','Sales Return')" style="cursor:pointer;" title="Click to see these transactions"><td style="padding:8px 14px;border-bottom:1px solid #f0f0f0;color:#dc2626;">Less: Sales Returns →</td><td style="padding:8px 14px;text-align:right;color:#dc2626;">(${f(salesRet)})</td></tr>
      <tr style="background:#f9fafb;"><td style="padding:10px 14px;font-weight:700;">Net Sales</td><td style="padding:10px 14px;text-align:right;font-weight:700;">${f(netSales)}</td></tr>
      <tr style="background:#fef2f2;"><td colspan="2" style="padding:10px 14px;font-weight:700;color:#dc2626;font-size:14px;">COST OF GOODS</td></tr>
      <tr data-x-click="openPLDrill('${plFrom}','${plTo}')" style="cursor:pointer;" title="Click to see these transactions"><td style="padding:8px 14px;border-bottom:1px solid #f0f0f0;">Purchases →</td><td style="padding:8px 14px;text-align:right;">${f(purch)}</td></tr>
      <tr data-x-click="openPLDrill('${plFrom}','${plTo}','Purchase Return')" style="cursor:pointer;" title="Click to see these transactions"><td style="padding:8px 14px;border-bottom:1px solid #f0f0f0;color:#166534;">Less: Purchase Returns →</td><td style="padding:8px 14px;text-align:right;color:#166534;">(${f(purchRet)})</td></tr>
      <tr style="background:#f9fafb;"><td style="padding:10px 14px;font-weight:700;">Gross Profit</td><td style="padding:10px 14px;text-align:right;font-weight:700;color:${grossProfit>=0?'#166534':'#dc2626'}">${f(grossProfit)}</td></tr>
      <tr style="background:#fffbeb;"><td colspan="2" style="padding:10px 14px;font-weight:700;color:#92400e;font-size:14px;">OPERATING EXPENSES</td></tr>
      ${expenses.map(e=>{const amt=tx.filter(t=>t.type===e).reduce((s,t)=>s+txAmt(t),0);return amt>0?`<tr data-x-click="openPLDrill('${plFrom}','${plTo}','${e}')" style="cursor:pointer;" title="Click to see these transactions"><td style="padding:8px 14px;border-bottom:1px solid #f0f0f0;">${e} →</td><td style="padding:8px 14px;text-align:right;">${f(amt)}</td></tr>`:''}).join('')}
      <tr style="background:#f9fafb;"><td style="padding:10px 14px;font-weight:700;">Total Expenses</td><td style="padding:10px 14px;text-align:right;font-weight:700;color:#dc2626;">${f(totalExp)}</td></tr>
      <tr data-x-click="openPLDrill('${plFrom}','${plTo}')" style="cursor:pointer;background:${netProfit>=0?'#f0fdf4':'#fef2f2'};border-top:2px solid ${netProfit>=0?'#16a34a':'#dc2626'};" title="Click to see this period's transactions"><td style="padding:14px;font-weight:800;font-size:16px;color:${netProfit>=0?'#166534':'#dc2626'};">NET PROFIT / (LOSS) →</td><td style="padding:14px;text-align:right;font-weight:800;font-size:18px;color:${netProfit>=0?'#166534':'#dc2626'};">${f(netProfit)}</td></tr>
      <tr><td style="padding:8px 14px;color:#6b7280;font-size:12px;">Gross Margin</td><td style="padding:8px 14px;text-align:right;font-size:12px;font-weight:700;color:#374151;">${netSales?((grossProfit/netSales*100).toFixed(1)):'0.0'}%</td></tr>
      <tr><td style="padding:8px 14px;color:#6b7280;font-size:12px;">Net Margin</td><td style="padding:8px 14px;text-align:right;font-size:12px;font-weight:700;color:${netProfit>=0?'#16a34a':'#dc2626'};">${netSales?((netProfit/netSales*100).toFixed(1)):'0.0'}%</td></tr>
    </table>
  </div>`;
}

// Clicking any P&L line opens the Transaction Sheet filtered to this
// statement's date range (and, for lines that map to one exact
// transaction type, that type too) — real, editable/printable rows.
function openPLDrill(from,to,type){
  nav('txsheet');
  setTimeout(function(){
    var fEl=document.getElementById('tsheet-from'), tEl=document.getElementById('tsheet-to'), tyEl=document.getElementById('tsheet-type');
    if(fEl) fEl.value=from||'';
    if(tEl) tEl.value=to||'';
    if(tyEl) tyEl.value=type||'';
    if(typeof filterTxSheet==='function') filterTxSheet();
  },80);
}

