function renderChallanPrint(){
  const el=document.getElementById('pg-challanprint');
  if(!el)return;
  const challans=(DB.challans||[]).sort((a,b)=>(b.date||'').localeCompare(a.date||''));
  el.innerHTML=`<div class="page-header"><h2>📋 Delivery Challan Print</h2><p>View and print delivery challans</p></div>
  <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:12px;margin-bottom:20px;">
    <div class="kpi-card"><div class="kpi-icon">📋</div><div class="kpi-val">${challans.length}</div><div class="kpi-label">Total Challans</div></div>
    <div class="kpi-card"><div class="kpi-icon">✅</div><div class="kpi-val">${challans.filter(c=>c.status==='Delivered').length}</div><div class="kpi-label">Delivered</div></div>
    <div class="kpi-card"><div class="kpi-icon">⏳</div><div class="kpi-val">${challans.filter(c=>c.status!=='Delivered').length}</div><div class="kpi-label">Pending</div></div>
  </div>
  <div class="card">
    <h3 style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:14px;">📋 Challan List</h3>
    ${challans.length?`<table class="tbl"><thead><tr><th>Challan #</th><th>Date</th><th>Customer</th><th>Items</th><th>Status</th><th>Actions</th></tr></thead>
    <tbody>${challans.map(ch=>`<tr>
      <td><strong>${ch.challanNo||ch.id||'—'}</strong></td>
      <td>${ch.date||'—'}</td>
      <td>${escHTML(ch.party||ch.customer||'—')}</td>
      <td>${(ch.items||[]).length} item(s)</td>
      <td><span style="padding:2px 8px;border-radius:8px;font-size:10px;font-weight:700;background:${ch.status==='Delivered'?'#dcfce7':'#fef9c3'};color:${ch.status==='Delivered'?'#16a34a':'#b45309'};">${ch.status||'Pending'}</span></td>
      <td><button class="btn" style="padding:4px 10px;font-size:11px;background:#2563eb;color:#fff;" data-x-click="printChallan(${ch.id})">🖨️ Print</button></td>
    </tr>`).join('')}</tbody></table>`
    :'<div style="text-align:center;padding:30px;color:#9ca3af;">No challans found. Create challans from the Delivery Challan page.</div>'}
  </div>`;
}

function renderReceiptPrint(){
  const el=document.getElementById('pg-receiptprint');
  if(!el)return;
  const receipts=(DB.tx||[]).filter(t=>['Sales Receipt','Cash Received','Cheque Received','Payment Received'].includes(t.type)).sort((a,b)=>(b.date||'').localeCompare(a.date||'')).slice(0,100);
  el.innerHTML=`<div class="page-header"><h2>🧾 Receipt Print</h2><p>View and print payment receipts</p></div>
  <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:12px;margin-bottom:20px;">
    <div class="kpi-card"><div class="kpi-icon">🧾</div><div class="kpi-val">${receipts.length}</div><div class="kpi-label">Total Receipts</div></div>
    <div class="kpi-card"><div class="kpi-icon">💰</div><div class="kpi-val">${f(receipts.reduce((s,t)=>s+txAmt(t),0))}</div><div class="kpi-label">Total Received</div></div>
  </div>
  <div class="card">
    <h3 style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:14px;">🧾 Receipt List</h3>
    ${receipts.length?`<table class="tbl"><thead><tr><th>Date</th><th>Type</th><th>Party</th><th>Amount</th><th>Mode</th><th>Actions</th></tr></thead>
    <tbody>${receipts.map(t=>`<tr>
      <td>${t.date||'—'}</td>
      <td><span style="padding:2px 8px;border-radius:8px;font-size:10px;font-weight:700;background:#dcfce7;color:#16a34a;">${t.type}</span></td>
      <td><strong>${escHTML(t.party ||'—')}</strong></td>
      <td><strong style="color:#16a34a;">${f(txAmt(t))}</strong></td>
      <td>${escHTML(t.mode||t.bank||'Cash')}</td>
      <td><button class="btn" style="padding:4px 10px;font-size:11px;background:#2563eb;color:#fff;" data-x-click="printReceiptById(${t.id})">🖨️ Print</button></td>
    </tr>`).join('')}</tbody></table>`
    :'<div style="text-align:center;padding:30px;color:#9ca3af;">No receipts found.</div>'}
  </div>`;
}

