function renderPaymentVoucher(){
  const el=document.getElementById('pg-paymentvoucher');
  if(!el)return;
  el.innerHTML=`<div class="page-header"><h2>💳 Payment Voucher</h2><p>Create and print payment vouchers</p></div>
  <div class="card" style="max-width:600px;margin:0 auto;">
    <h3>💳 New Payment Voucher</h3>
    <div style="display:grid;gap:12px;">
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">
        <div><label style="font-size:12px;font-weight:600;">Date</label><input type="date" id="pv-date" value="${new Date().toISOString().split('T')[0]}" style="width:100%;padding:8px;border:1px solid #ddd;border-radius:6px;font-size:13px;"></div>
        <div><label style="font-size:12px;font-weight:600;">Voucher No</label><input type="text" id="pv-no" placeholder="PV-001" style="width:100%;padding:8px;border:1px solid #ddd;border-radius:6px;font-size:13px;"></div>
      </div>
      <div><label style="font-size:12px;font-weight:600;">Pay To</label><input list="pv-party-list" id="pv-party" placeholder="Payee name" style="width:100%;padding:8px;border:1px solid #ddd;border-radius:6px;font-size:13px;"><datalist id="pv-party-list">${(DB.parties||[]).map(p=>`<option value="${escHTML(p.name)}">`).join('')}</datalist></div>
      <div><label style="font-size:12px;font-weight:600;">Amount (৳)</label><input type="number" id="pv-amt" placeholder="0.00" style="width:100%;padding:8px;border:1px solid #ddd;border-radius:6px;font-size:13px;"></div>
      <div><label style="font-size:12px;font-weight:600;">Purpose</label><input type="text" id="pv-purpose" placeholder="Payment for..." style="width:100%;padding:8px;border:1px solid #ddd;border-radius:6px;font-size:13px;"></div>
      <div><label style="font-size:12px;font-weight:600;">Paid From</label><select id="pv-bank" style="width:100%;padding:8px;border:1px solid #ddd;border-radius:6px;font-size:13px;">${(DB.banks||[]).map(b=>`<option>${escHTML(b.name)}</option>`).join('')}</select></div>
      <div style="display:flex;gap:10px;">
        <button class="btn" style="flex:1;padding:12px;" data-x-click="saveAndPrintVoucher()">🖨️ Save & Print</button>
        <button class="btn btn-outline" style="flex:1;padding:12px;" data-x-click="savePaymentVoucherOnly()">💾 Save Only</button>
      </div>
    </div>
  </div>`;
}

function saveAndPrintVoucher(){
  const date=document.getElementById('pv-date')?.value;const no=document.getElementById('pv-no')?.value||'PV-'+Date.now().toString().slice(-6);
  const party=document.getElementById('pv-party')?.value;const amt=parseFloat(document.getElementById('pv-amt')?.value||0);
  const purpose=document.getElementById('pv-purpose')?.value;const bank=document.getElementById('pv-bank')?.value;
  if(!date||!amt){alert('⚠️ Fill Date and Amount');return;}
  const tx={id:newId(),date,type:'Cash Payment',party,amt,bank,note:purpose,inv:no};
  if(!DB.tx)DB.tx=[];DB.tx.unshift(tx);recalculateBalances();saveDB();
  printVoucherById(tx.id);
}

function savePaymentVoucherOnly(){
  const date=document.getElementById('pv-date')?.value;const no=document.getElementById('pv-no')?.value||'PV-'+Date.now().toString().slice(-6);
  const party=document.getElementById('pv-party')?.value;const amt=parseFloat(document.getElementById('pv-amt')?.value||0);
  const purpose=document.getElementById('pv-purpose')?.value;const bank=document.getElementById('pv-bank')?.value;
  if(!date||!amt){alert('⚠️ Fill Date and Amount');return;}
  const tx={id:newId(),date,type:'Cash Payment',party,amt,bank,note:purpose,inv:no};
  if(!DB.tx)DB.tx=[];DB.tx.unshift(tx);recalculateBalances();saveDB();toast('Voucher saved!', 's');
}

function renderPdfReports(){
  const el=document.getElementById('pg-pdfreports');
  if(!el)return;
  el.innerHTML=`<div class="page-header"><h2>📄 PDF Reports</h2><p>Generate and download PDF reports</p></div>
  <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:16px;padding:8px 0;">
    ${[
      {icon:'📊',title:'Balance Sheet',fn:'printBalanceSheet'},
      {icon:'💹',title:'Profit & Loss',fn:'printProfitLoss'},
      {icon:'📋',title:'All Transactions',fn:'printAllTransactions'},
      {icon:'🏦',title:'Bank Statement',fn:"nav('banks')"},
      {icon:'👥',title:'Customer Aging',fn:"nav('customeraging')"},
      {icon:'🏭',title:'Supplier Aging',fn:"nav('supplieraging')"},
      {icon:'📦',title:'Stock Report',fn:"nav('inventory')"},
      {icon:'💰',title:'Sales Report',fn:"nav('salesbyproduct')"},
    ].map(r=>`<div class="card" style="text-align:center;cursor:pointer;transition:all .2s;" data-x-click="${r.fn.endsWith(')')?r.fn:r.fn+'()'}" data-hover-transform="translateY(-3px)">
      <div style="font-size:36px;margin-bottom:10px;">${r.icon}</div>
      <div style="font-weight:700;font-size:14px;">${r.title}</div>
      <div style="color:#666;font-size:12px;margin-top:4px;">Click to generate</div>
    </div>`).join('')}
  </div>`;
}

// Helper: print by ID (delegates to the letterhead voucher printer)
function printInvoiceById(id){
  const t=(DB.tx||[]).find(tx=>tx.id===id);
  if(!t){alert('Transaction not found');return;}
  printTransaction(id);
  const sel=document.getElementById('print-invoice-type'); if(sel) sel.value='invoice';
  const ttl=document.getElementById('print-doc-title'); if(ttl) ttl.textContent='Sales Invoice';
}
function printReceiptById(id){
  const t=(DB.tx||[]).find(tx=>tx.id===id);
  if(!t){alert('Transaction not found');return;}
  printTransaction(id);
  const sel=document.getElementById('print-invoice-type'); if(sel) sel.value='receipt';
  const ttl=document.getElementById('print-doc-title'); if(ttl) ttl.textContent='Money Receipt';
}
function printVoucherById(id){
  const t=(DB.tx||[]).find(tx=>tx.id===id);
  if(!t){alert('Transaction not found');return;}
  printTransaction(id); // route through the letterhead voucher printer
}
function printProfitLoss(){
  nav('profitloss');
  setTimeout(()=>{
    const el=document.getElementById('pg-profitloss');
    if(!el)return;
    const tbl = el.querySelector('table');
    const html = '<h2 style="text-align:center;margin:0 0 12px;color:#0f3d26;">Profit &amp; Loss Statement</h2>'
      + (tbl ? tbl.outerHTML : '<p style="text-align:center;color:#888;">No data</p>');
    openPrintModal('Profit & Loss Statement', 'PL-'+Date.now().toString().slice(-6), html, TODAY());
  },500);
}

