<script nonce="<?php echo $cspNonceAttr; ?>">
// ═══════════════════════════════════════════════════════
// FACTORY FINANCE — CITY BANK INVOICE FINANCING MODULE
// Formula (City Bank): advance = invoice × 85%,
// upfront fee = invoice × 0.5%, holdback = invoice − advance,
// interest = holdback × rate(9% p.a.) × days ÷ 365,
// total charges = upfront fee + interest,
// net released = holdback − total charges.
// All rates editable; all auto fields overridable; defaults 0.
// ═══════════════════════════════════════════════════════
let finF = {search:'', status:'', dateFrom:'', dateTo:''};

function ensureFin(){
  if(!DB.cityFinance) DB.cityFinance = [];
  if(!DB.finSettings) DB.finSettings = {advPct:85, feePct:0.5, ratePct:9, alertDays:60};
  if(!DB.nid) DB.nid = {};
  if(!DB.nid.fin) DB.nid.fin = ((DB.cityFinance||[]).reduce((m,r)=>Math.max(m,r.id||0),0)+1);
}
function finV(id){ const e=document.getElementById(id); return e?e.value:''; }
function finN(id){ return parseFloat(finV(id))||0; }
function finSet(id,val){ const e=document.getElementById(id); if(e) e.value=(val===null||val===undefined)?'':val; }
function finAudit(action,desc){ try{ if(typeof logAudit==='function') logAudit(action,'Factory Finance',desc); }catch(e){} }
function finFmt(n){ return (typeof pf==='function')?pf(n):('৳'+(parseFloat(n)||0).toLocaleString('en-IN',{minimumFractionDigits:2})); }

// ── Overdue / status helpers ─────────────────────────────
function finIsOverdue(r){
  ensureFin();
  if(r.status!=='Funded') return false;
  const base=r.advDate||r.date; if(!base) return false;
  const days=Math.floor((new Date().setHours(0,0,0,0)-new Date(base).setHours(0,0,0,0))/86400000);
  return days > (DB.finSettings.alertDays||60);
}
function finDaysUsed(r){
  const base=r.advDate||r.date; if(!base) return 0;
  const endStr=r.buyerPaidDate||todayStr();
  return Math.max(0, Math.round((new Date(endStr)-new Date(base))/86400000));
}
function finBadge(r){
  if(r.status==='Settled')   return '<span class="badge b-green">🟢 Settled</span>';
  if(r.status==='Cancelled') return '<span class="badge b-gray">⚫ Cancelled</span>';
  if(finIsOverdue(r))        return '<span class="badge b-red" title="Funded longer than alert limit">🔴 Funded · Overdue</span>';
  return '<span class="badge b-blue">🔵 Funded</span>';
}

// ── RENDER ───────────────────────────────────────────────
function renderCityFinance(){
  ensureFin();
  let rows = [...DB.cityFinance];
  if(finF.search){
    const q=finF.search;
    rows=rows.filter(r=>['party','inv','prsGrn','status','notes','alertNote','bank'].some(k=>String(r[k]||'').toLowerCase().includes(q)));
  }
  if(finF.status==='Overdue') rows=rows.filter(r=>finIsOverdue(r));
  else if(finF.status) rows=rows.filter(r=>r.status===finF.status);
  if(finF.dateFrom) rows=rows.filter(r=>(r.date||'')>=finF.dateFrom);
  if(finF.dateTo)   rows=rows.filter(r=>(r.date||'')<=finF.dateTo);

  const all=(DB.cityFinance||[]).filter(r=>r.status!=='Cancelled');
  const funded=all.filter(r=>r.status==='Funded');
  const settled=all.filter(r=>r.status==='Settled');
  const overdue=(DB.cityFinance||[]).filter(r=>finIsOverdue(r));
  const sum=(arr,k)=>arr.reduce((s,r)=>s+(parseFloat(r[k])||0),0);
  set('fin-stats',`
    <div class="info-pill"><span class="dot" style="background:#2563eb"></span>Financed Invoices: <strong>${f(sum(all,'invoiceTotal'))}</strong> (${all.length})</div>
    <div class="info-pill"><span class="dot" style="background:#1e40af"></span>Advance Taken: <strong>${f(sum(all,'advPaid'))}</strong></div>
    <div class="info-pill"><span class="dot" style="background:#dc2626"></span>Holdback Outstanding: <strong>${f(sum(funded,'holdback'))}</strong> (${funded.length} funded)</div>
    <div class="info-pill"><span class="dot" style="background:#d97706"></span>Interest + Fees Paid: <strong>${f(sum(settled,'charges'))}</strong></div>
    <div class="info-pill"><span class="dot" style="background:#16a34a"></span>Net Released: <strong>${f(sum(settled,'net'))}</strong> (${settled.length} settled)</div>
    ${overdue.length?`<div class="info-pill" style="border-color:#fecaca;background:#fef2f2;"><span class="dot" style="background:#ef4444"></span>⚠️ Overdue Alerts: <strong>${overdue.length}</strong></div>`:''}
  `);
  const nb=document.getElementById('nb-fin'); if(nb) nb.textContent=funded.length;

  const tbody=document.getElementById('t-fin');
  const empty=document.getElementById('fin-empty');
  const footer=document.getElementById('fin-footer');
  if(!tbody) return;
  if(rows.length===0){ tbody.innerHTML=''; empty.style.display='block'; footer.textContent=''; return; }
  empty.style.display='none';
  footer.innerHTML=`Showing <strong>${rows.length}</strong> records | Invoice Total: <strong>${f(sum(rows,'invoiceTotal'))}</strong> | Advance: <strong>${f(sum(rows,'advPaid'))}</strong> | Charges: <strong>${f(sum(rows,'charges'))}</strong> | Net Released: <strong>${f(sum(rows,'net'))}</strong>`;

  if(tbody) tbody.innerHTML=[...rows].reverse().map((r,i)=>{
    const od=finIsOverdue(r);
    const bg=r.status==='Settled'?'background:#f0fdf4;':(od?'background:#fef2f2;':(r.status==='Cancelled'?'opacity:.55;':''));
    const days=r.status==='Settled'?(r.days||0):finDaysUsed(r);
    return `<tr style="${bg}">
      <td class="text-muted fs11">${rows.length-i}</td>
      <td>${r.date||'-'}</td>
      <td class="fs11">${r.inv||'-'}${r.txId?' <span class="badge b-gray fs11" title="Linked to transaction #'+r.txId+'">TX'+r.txId+'</span>':''}</td>
      <td class="fs11">${r.prsGrn||'-'}</td>
      <td class="fs11">${r.invoiceDate||'-'}</td>
      <td><strong>${escHTML(r.party ||'-')}</strong></td>
      <td class="td-num">${f(r.invoiceTotal||0)}</td>
      <td class="td-num">${(r.advPct||0)}%</td>
      <td class="td-num" style="color:#1e40af;font-weight:600;">${f(r.advPaid||0)}</td>
      <td class="td-num">${f(r.fee||0)}</td>
      <td class="td-num" style="color:#b91c1c;">${f(r.holdback||0)}</td>
      <td>${r.buyerPaidDate||'-'}</td>
      <td class="td-num">${days||'-'}${(r.status==='Funded'&&!r.buyerPaidDate&&days)?' <span title="running">⏳</span>':''}</td>
      <td class="td-num" style="color:#b45309;">${r.interest?f(r.interest):'-'}</td>
      <td class="td-num text-neg">${r.charges?f(r.charges):'-'}</td>
      <td class="td-num text-pos">${r.net?f(r.net):'-'}</td>
      <td>${finBadge(r)}</td>
      <td class="fs11">${od&&!r.alertNote?'<span style="color:#dc2626;">⚠ Follow up with buyer</span>':(r.alertNote||'-')}</td>
      <td style="white-space:nowrap;">
        <button class="btn btn-xs btn-icon" style="background:#1a3a6b;color:#fff;margin-right:2px;" data-x-click="openFinModal(${r.id})" title="Edit">✏️</button>
        ${r.status==='Funded'?`<button class="btn btn-xs btn-icon" style="background:#16a34a;color:#fff;margin-right:2px;" data-x-click="quickSettleFin(${r.id})" title="Settle (buyer paid)">🧮</button>`:''}
        <button class="btn btn-xs btn-icon" style="background:#f5a623;color:#000;margin-right:2px;" data-x-click="printFinVoucher(${r.id})" title="Print (letterhead)">🖨️</button>
        ${r.status==='Funded'?`<button class="btn btn-xs btn-icon" style="background:#64748b;color:#fff;margin-right:2px;" data-x-click="cancelFin(${r.id})" title="Cancel drawdown">⛔</button>`:''}
        <button class="btn btn-danger btn-xs btn-icon" data-x-click="delFin(${r.id})" title="Delete (goes to Trash Bin)">🗑</button>
      </td>
    </tr>`;
  }).join('');
}
function finSearch(v){ finF.search=(v||'').toLowerCase(); renderCityFinance(); }
function finFilt(k,v){ finF[k]=v; renderCityFinance(); }
function clearFinFilters(){
  finF={search:'',status:'',dateFrom:'',dateTo:''};
  ['finSearchBox','finDateFrom','finDateTo'].forEach(id=>{const e=document.getElementById(id);if(e)e.value='';});
  const s=document.getElementById('finStatusSel'); if(s)s.value='';
  renderCityFinance();
}

// ── MODAL (Add / Edit) ───────────────────────────────────
function finFillDatalists(){
  const pl=document.getElementById('fin-party-list');
  if(pl) pl.innerHTML=(DB.customers||[]).map(c=>`<option value="${escHTML(c.name||'')}">`).join('');
  /* FIX B: this was a free-text input backed by a <datalist>, so no list ever
     appeared until the user typed an exact prefix and no balance was shown.
     It is now a real <select> of DB.banks with the live balance beside it. */
  const bl=document.getElementById('fin-bank');
  if(bl){
    const keep=bl.value;
    const esc=v=>String(v==null?'':v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/"/g,'&quot;');
    bl.innerHTML='<option value="">— Select bank account —</option>'+
      finBankList().map(b=>`<option value="${esc(b.name)}">${esc(b.name)}${b.acno?' · A/C '+esc(b.acno):''} — ${f(b.bal||0)}</option>`).join('');
    if(keep) finSetBankValue(keep);
  }
  const ts=document.getElementById('fin-txsel');
  if(ts){
    const txs=[...(DB.tx||[])].reverse().slice(0,300);
    ts.innerHTML='<option value="">— Manual (no link) —</option>'+txs.map(t=>
      `<option value="${t.id}">#${t.id} · ${t.date||''} · ${t.type||''} · ${escHTML(t.party||'')} · ${f(txAmt(t))}</option>`).join('');
  }
}
/* Master bank list — DB.bankAccounts is only an alias of DB.banks, but older
   imports populated one and not the other, so read both. */
function finBankList(){
  /* FIX: DB.bankAccounts is a stale copy of DB.banks that nothing keeps up
     to date, and it was read FIRST — so this dropdown quoted balances from
     before the day's entries while every other screen showed the live
     figure. DB.banks is the live list; the old alias is only a fallback,
     and a balance is always looked up by name in DB.banks when it exists. */
  let raw = [];
  try {
    if (Array.isArray(DB.banks) && DB.banks.length > 0) raw = DB.banks;
    else if (Array.isArray(DB.bankAccounts) && DB.bankAccounts.length > 0) raw = DB.bankAccounts;
  } catch (e) {
    raw = [];
  }
  const live = name => {
    try{
      const b=(DB.banks||[]).find(x=>x&&x.name===name);
      if(b) return isFinite(parseFloat(b.bal)) ? parseFloat(b.bal)
           : (isFinite(parseFloat(b.balance)) ? parseFloat(b.balance) : 0);
    }catch(e){}
    return null;
  };
  return raw.map(b => {
    if (!b) return null;
    if (typeof b === 'string') {
      return { name: b, acno: '', bal: live(b) || 0 };
    }
    const name = b.name || 'Unnamed Bank';
    const own = isFinite(parseFloat(b.bal)) ? parseFloat(b.bal) : (isFinite(parseFloat(b.balance)) ? parseFloat(b.balance) : 0);
    const l = live(name);
    return { name: name, acno: b.acno || b.accountNo || '', bal: l==null ? own : l };
  }).filter(Boolean);
}
/* FIX C: saved bank strings arrive corrupted — leading tabs/NBSP, collapsed
   words, and an appended account code (" \tCity SND MESARS KARIMA
   ENTERPRISEBNK-0003"). Exact matching blanked the field or showed
   "not found", so normalise both sides before comparing. */
function finNormBank(s){
  return String(s==null?'':s)
    .replace(/\u00a0/g,' ')            // NBSP
    .replace(/[\t\r\n]+/g,' ')
    .replace(/\s*[·—–-]\s*A\/C.*$/i,'')// trailing " · A/C 123" decoration
    .replace(/\s*[·—]\s*৳[\d.,]+\s*$/,'')
    .replace(/\s+/g,' ')
    .trim()
    .toUpperCase();
}
/* Strips a trailing account-code suffix glued onto the name (…ENTERPRISEBNK-0003). */
function finStripCode(n){ return n.replace(/[A-Z]{2,4}-?\d{2,}\s*$/,'').trim(); }
function finMatchBank(raw){
  const list=finBankList(); if(!raw) return null;
  const n=finNormBank(raw), nStripped=finStripCode(n);
  let hit=list.find(b=>finNormBank(b.name)===n) || list.find(b=>finNormBank(b.name)===nStripped);
  if(hit) return hit;
  // account number embedded anywhere in the saved string
  hit=list.find(b=>b.acno && n.indexOf(finNormBank(b.acno))>=0);
  if(hit) return hit;
  // longest master name that the (possibly suffixed) string starts with / contains
  const cands=list.filter(b=>{const bn=finNormBank(b.name); return bn && (n.indexOf(bn)===0 || nStripped.indexOf(bn)===0 || n.indexOf(bn)>=0);})
                  .sort((a,b)=>finNormBank(b.name).length-finNormBank(a.name).length);
  return cands[0]||null;
}
/* Keeps a saved/imported bank name selectable even if it is no longer in
   the master list (otherwise editing an old record silently blanked the field). */
function finSetBankValue(name){
  const sel=document.getElementById('fin-bank'); if(!sel) return;
  const raw=String(name||'');
  const hit=finMatchBank(raw);
  const v=hit?String(hit.name):raw.replace(/\s+/g,' ').trim();
  if(v && !Array.from(sel.options).some(o=>o.value===v)){
    const o=document.createElement('option'); o.value=v; o.textContent=v+' (not in Bank Accounts)'; sel.appendChild(o);
  }
  sel.value=v; finShowBankBal();
}
function finShowBankBal(){
  const sel=document.getElementById('fin-bank'), out=document.getElementById('fin-bank-bal');
  if(!out) return;
  if(!sel||!sel.value){ out.textContent='Balance: —'; out.style.color='#6b7280'; return; }
  const b=finMatchBank(sel.value);
  if(!b){ out.textContent='Balance: not found — this account is not in Bank Accounts'; out.style.color='#b45309'; return; }
  const bal=parseFloat(b.bal||0)||0;
  out.textContent='Balance: '+f(bal)+(b.acno?' · A/C '+b.acno:'');
  out.style.color=bal<0?'#b91c1c':'#15803d';
}
function openFinModal(id){
  ensureFin(); finFillDatalists();
  const S=DB.finSettings;
  const badge=document.getElementById('finStatusBadge');
  if(typeof id==='number'){
    const r=(DB.cityFinance||[]).find(x=>x.id===id);
    if(!r){ toast('Financing record not found','e'); return; }
    finSet('fin-edit-id',r.id); finSet('fin-txid',r.txId||'');
    const ts=document.getElementById('fin-txsel'); if(ts) ts.value=r.txId||'';
    finSet('fin-date',r.date); finSet('fin-inv',r.inv); finSet('fin-prsgrn',r.prsGrn);
    finSet('fin-invdate',r.invoiceDate); finSet('fin-party',r.party);
    finSet('fin-total',r.invoiceTotal||0); finSet('fin-advpct',r.advPct||0);
    finSet('fin-advpaid',r.advPaid||0); finSet('fin-advdate',r.advDate);
    finSet('fin-feepct',r.feePct||0); finSet('fin-fee',r.fee||0);
    finSet('fin-holdback',r.holdback||0); finSetBankValue(r.bank||'');
    finSet('fin-paiddate',r.buyerPaidDate); finSet('fin-ratepct',r.ratePct||0);
    finSet('fin-days',r.days||0); finSet('fin-interest',r.interest||0);
    finSet('fin-charges',r.charges||0); finSet('fin-net',r.net||0);
    finSet('fin-status',r.status||'Funded'); finSet('fin-alert',r.alertNote||''); finSet('fin-notes',r.notes||'');
    if(badge){ badge.textContent=r.status||'Funded'; badge.className='badge '+(r.status==='Settled'?'b-green':r.status==='Cancelled'?'b-gray':'b-blue'); }
  } else {
    finSet('fin-edit-id',''); finSet('fin-txid','');
    const ts=document.getElementById('fin-txsel'); if(ts) ts.value='';
    ['fin-inv','fin-prsgrn','fin-party','fin-alert','fin-notes','fin-invdate','fin-advdate','fin-paiddate'].forEach(x=>finSet(x,''));
    finSetBankValue('');
    finSet('fin-date',todayStr());
    finSet('fin-total',0); finSet('fin-advpct',S.advPct||0); finSet('fin-feepct',S.feePct||0); finSet('fin-ratepct',S.ratePct||0);
    ['fin-advpaid','fin-fee','fin-holdback','fin-days','fin-interest','fin-charges','fin-net'].forEach(x=>finSet(x,0));
    finSet('fin-status','Funded');
    if(badge){ badge.textContent='New'; badge.className='badge b-gray'; }
  }
  openModal('mFin');
}
function finPickTx(txId){
  if(!txId) { finSet('fin-txid',''); return; }
  const t=(DB.tx||[]).find(x=>x.id===parseInt(txId));
  if(!t) return;
  finSet('fin-txid',t.id);
  if(t.inv) finSet('fin-inv',t.inv);
  if(t.date) finSet('fin-invdate',t.date);
  if(t.party) finSet('fin-party',t.party);
  if(t.amt) finSet('fin-total',t.amt);
  finAutoCalc();
}

// ── CALCULATION ENGINE (all outputs editable afterwards) ─
function finAutoCalc(force){
  const total=finN('fin-total');
  const advPct=finN('fin-advpct');
  const feePct=finN('fin-feepct');
  const adv=Math.round(total*advPct)/100;
  finSet('fin-advpaid',adv.toFixed(2));
  finSet('fin-fee',(Math.round(total*feePct)/100).toFixed(2));
  finSet('fin-holdback',(total-adv).toFixed(2));
  if(force) toast('Drawdown figures recalculated','s');
}
function finCalcSettle(force){
  const base=finV('fin-advdate')||finV('fin-date');
  const pay=finV('fin-paiddate');
  if(!base||!pay){ if(force) toast('Set drawdown date and buyer paid date first','e'); return; }
  const days=Math.max(0,Math.round((new Date(pay)-new Date(base))/86400000));
  finSet('fin-days',days);
  finCalcFromDays();
  if(force) toast('Settlement calculated — every figure below is editable','s');
}
function finCalcFromDays(){
  const days=finN('fin-days');
  const rate=finN('fin-ratepct')/100;
  const holdback=finN('fin-holdback');
  const interest=Math.round(holdback*rate*days/365*100)/100;
  finSet('fin-interest',interest.toFixed(2));
  finSumCharges();
}
function finSumCharges(){
  const charges=Math.round((finN('fin-fee')+finN('fin-interest'))*100)/100;
  finSet('fin-charges',charges.toFixed(2));
  finNetOnly();
}
function finNetOnly(){
  finSet('fin-net',(Math.round((finN('fin-holdback')-finN('fin-charges'))*100)/100).toFixed(2));
}

// ── SAVE / DELETE / CANCEL / SETTLE ─────────────────────
function saveFin(){
  ensureFin();
  const date=finV('fin-date'), total=finN('fin-total');
  if(!date){ toast('Drawdown date is required','e'); return; }
  if(total<=0){ toast('Total invoice must be greater than zero','e'); return; }
  const rec={
    txId: parseInt(finV('fin-txid'))||null,
    date, inv:finV('fin-inv'), prsGrn:finV('fin-prsgrn'),
    invoiceDate:finV('fin-invdate'), party:finV('fin-party'),
    invoiceTotal:total, advPct:finN('fin-advpct'), advPaid:finN('fin-advpaid'),
    advDate:finV('fin-advdate'), feePct:finN('fin-feepct'), fee:finN('fin-fee'),
    holdback:finN('fin-holdback'), bank:finV('fin-bank'),
    buyerPaidDate:finV('fin-paiddate'), ratePct:finN('fin-ratepct'),
    days:finN('fin-days'), interest:finN('fin-interest'),
    charges:finN('fin-charges'), net:finN('fin-net'),
    status:finV('fin-status')||'Funded',
    alertNote:finV('fin-alert'), notes:finV('fin-notes'),
    updatedAt:new Date().toISOString()
  };
  const editId=parseInt(finV('fin-edit-id'))||0;
  // FIX 4: Helper to update bank balance for City Bank Finance
  function finAdjBank(name, delta){
    if(!name || !delta) return;
    const b=(DB.banks||[]).find(b=>b.name===name);
    if(b){ b.bal=(parseFloat(b.bal)||0)+delta; }
  }
  if(editId){
    const idx=DB.cityFinance.findIndex(r=>r.id===editId);
    if(idx>=0){
      const oldRec=DB.cityFinance[idx];
      if(oldRec.status==='Funded'&&oldRec.bank&&oldRec.advPaid) finAdjBank(oldRec.bank,-(parseFloat(oldRec.advPaid)||0));
      else if(oldRec.status==='Settled'&&oldRec.bank&&oldRec.net) finAdjBank(oldRec.bank,-(parseFloat(oldRec.net)||0));
      rec.id=editId; rec.createdAt=oldRec.createdAt; DB.cityFinance[idx]=rec;
      if(rec.status==='Funded'&&rec.bank&&rec.advPaid) finAdjBank(rec.bank,parseFloat(rec.advPaid)||0);
      else if(rec.status==='Settled'&&rec.bank&&rec.net) finAdjBank(rec.bank,parseFloat(rec.net)||0);
    } else {
      rec.id=DB.nid.fin++; rec.createdAt=rec.updatedAt; DB.cityFinance.push(rec);
      if(rec.status==='Funded'&&rec.bank&&rec.advPaid) finAdjBank(rec.bank,parseFloat(rec.advPaid)||0);
    }
    toast('Financing record updated!','s');
finAudit('UPDATE','Updated financing #'+rec.id+' ('+(rec.party||'')+')');
  } else {
    rec.id=DB.nid.fin++; rec.createdAt=rec.updatedAt;
    DB.cityFinance.push(rec);
    if(rec.status==='Funded'&&rec.bank&&rec.advPaid){
      finAdjBank(rec.bank,parseFloat(rec.advPaid)||0);
      toast('Drawdown saved — ৳'+parseFloat(rec.advPaid).toLocaleString('en-IN',{minimumFractionDigits:2})+' credited to '+rec.bank,'s');
    } else {
      toast('Drawdown saved — status: '+rec.status,'s');
    }
finAudit('CREATE','New drawdown #'+rec.id+' '+finFmt(rec.advPaid)+' ('+(rec.party||'')+')');
  }
  saveDB(); closeModal('mFin'); renderCityFinance();
  try{ renderDash(); }catch(e){}
}
// FIX 5: global bank reversal helper for financing records
function finBankAdj(name, delta){
  if(!name || !delta) return;
  const b=(DB.banks||[]).find(x=>x.name===name);
  if(b){ b.bal=(parseFloat(b.bal)||0)+delta; }
}
function finBankAmount(r){
  if(!r) return 0;
  if(r.status==='Funded') return parseFloat(r.advPaid)||0;
  if(r.status==='Settled') return parseFloat(r.net)||0;
  return 0;
}
async function delFin(id){
  ensureFin();
  const r=(DB.cityFinance||[]).find(x=>x.id===id);
  if(!r) return;
  if(!await __confirm('Delete this financing record?\nIt will be moved to the Trash Bin.')) return;
  if(!DB.trash) DB.trash=[];
  DB.trash.unshift({...r,_deletedAt:new Date().toISOString(),_type:'cityFinance'});
  DB.cityFinance=(DB.cityFinance||[]).filter(x=>x.id!==id);
  // FIX 5: reverse the bank effect of this record on delete
  const revAmt=finBankAmount(r);
  if(r.bank&&revAmt){ finBankAdj(r.bank,-revAmt); }
  saveDB(); renderCityFinance();
  try{ renderDash(); }catch(e){}
  finAudit('DELETE','Deleted financing #'+id+(revAmt?(' — reversed '+finFmt(revAmt)+' from '+r.bank):''));
  toast(revAmt?('Moved to Trash Bin — '+finFmt(revAmt)+' reversed from '+r.bank):'Moved to Trash Bin','e');
}
async function cancelFin(id){
  ensureFin();
  const r=(DB.cityFinance||[]).find(x=>x.id===id);
  if(!r||r.status!=='Funded'){ toast('Only funded records can be cancelled','e'); return; }
  if(!await __confirm('Cancel this drawdown? It stays in the list marked Cancelled.')) return;
  // FIX 5: reverse the advance credited to the bank when cancelling
  const revAmt=finBankAmount(r);
  if(r.bank&&revAmt){ finBankAdj(r.bank,-revAmt); }
  r.status='Cancelled'; r.updatedAt=new Date().toISOString();
  saveDB(); renderCityFinance();
  try{ renderDash(); }catch(e){}
  finAudit('UPDATE','Cancelled drawdown #'+id+(revAmt?(' — reversed '+finFmt(revAmt)+' from '+r.bank):''));
  toast(revAmt?('Drawdown cancelled — '+finFmt(revAmt)+' reversed from '+r.bank):'Drawdown cancelled','s');
}
function quickSettleFin(id){
  ensureFin();
  const r=(DB.cityFinance||[]).find(x=>x.id===id);
  if(!r){ toast('Record not found','e'); return; }
  const pay=prompt('Buyer / customer payment date (YYYY-MM-DD):', todayStr());
  if(pay===null) return;
  if(!/^\d{4}-\d{2}-\d{2}$/.test(pay)){ toast('Invalid date format, use YYYY-MM-DD','e'); return; }
  openFinModal(id);
  finSet('fin-paiddate',pay);
  if(!finN('fin-ratepct')) finSet('fin-ratepct',DB.finSettings.ratePct||0);
  finCalcSettle();
  finSet('fin-status','Settled');
  const badge=document.getElementById('finStatusBadge');
  if(badge){ badge.textContent='Settled (unsaved)'; badge.className='badge b-green'; }
  toast('Calculated — review the editable figures, then click 💾 Save Financing','s');
}

// ── GET FINANCE (from transactions) ──────────────────────
function getFinanceFromTx(txId){
  ensureFin();
  const t=(DB.tx||[]).find(x=>x.id===txId);
  if(!t){ toast('Transaction not found','e'); return; }
  nav('cityfinance');
  const existing=(DB.cityFinance||[]).filter(r=>r.txId===txId&&r.status!=='Cancelled').sort((a,b)=>b.id-a.id)[0];
  if(existing){
    openFinModal(existing.id);
    toast('This transaction already has financing #'+existing.id+' — opened for update','s');
    return;
  }
  openFinModal();
  finSet('fin-txid',txId);
  const ts=document.getElementById('fin-txsel'); if(ts) ts.value=String(txId);
  finSet('fin-inv',t.inv||''); finSet('fin-invdate',t.date||'');
  finSet('fin-party',t.party||''); finSet('fin-total',txAmt(t));
  finSet('fin-advdate',todayStr());
  finAutoCalc();
  toast('Get Finance: figures auto-filled from transaction #'+txId+' — everything is editable','s');
}
function getFinanceFromModal(){
  const editId=parseInt((document.getElementById('tx-edit-id')||{}).value)||0;
  if(!editId){ toast('Save the transaction first, then click Get Finance','e'); return; }
  closeModal('mTx');
  getFinanceFromTx(editId);
}

