// ── EXPORT / IMPORT / TEMPLATE ──────────────────────────
const FIN_CSV_HEAD=['ID','Drawdown Date','Invoice No','PRS/GRN No','Invoice Date','Party','Total Invoice','Advance %','Advance Paid','Advance Date','Fee %','Upfront Fee','Holdback','Bank Account','Buyer Paid Date','Rate % p.a.','Days','Interest','Total Charges','Net Released','Status','Alert Note','Notes','Linked Txn ID'];
function exportFinCSV(){
  ensureFin();
  if((DB.cityFinance||[]).length===0){ toast('No financing records to export','e'); return; }
  let csv=csvRow(FIN_CSV_HEAD);
  (DB.cityFinance||[]).forEach(r=>{
    csv+=csvRow([r.id,r.date||'',r.inv||'',r.prsGrn||'',r.invoiceDate||'',r.party||'',r.invoiceTotal||0,r.advPct||0,r.advPaid||0,r.advDate||'',r.feePct||0,r.fee||0,r.holdback||0,r.bank||'',r.buyerPaidDate||'',r.ratePct||0,r.days||0,r.interest||0,r.charges||0,r.net||0,r.status||'',r.alertNote||'',r.notes||'',r.txId||'']);
  });
  dlCSV('city_bank_finance_'+todayStr()+'.csv',csv);
  finAudit('EXPORT','Exported '+(DB.cityFinance||[]).length+' records to CSV');
  toast('Exported '+(DB.cityFinance||[]).length+' records','s');
}
function finTemplateCSV(){
  let csv=csvRow(FIN_CSV_HEAD);
  csv+=csvRow(['','2026-07-15','INV-0001','PRS-2026-001','2026-07-10','Example Buyer Ltd',1000000,85,850000,'2026-07-15',0.5,5000,150000,'City Bank CD A/C','',9,0,0,0,0,'Funded','','Sample row — delete before import','']);
  dlCSV('city_bank_finance_template.csv',csv);
}
function finParseCSV(text){
  const rows=[]; let row=[],cur='',inQ=false;
  for(let i=0;i<text.length;i++){
    const c=text[i];
    if(inQ){
      if(c==='"'){ if(text[i+1]==='"'){cur+='"';i++;} else inQ=false; }
      else cur+=c;
    } else {
      if(c==='"') inQ=true;
      else if(c===','){ row.push(cur); cur=''; }
      else if(c==='\n'||c==='\r'){ if(c==='\r'&&text[i+1]==='\n')i++; row.push(cur); rows.push(row); row=[]; cur=''; }
      else cur+=c;
    }
  }
  if(cur!==''||row.length){ row.push(cur); rows.push(row); }
  return rows.filter(r=>r.some(c=>String(c).trim()!==''));
}
function importFinCSV(input){
  const file=input.files&&input.files[0];
  if(!file) return;
  const reader=new FileReader();
  reader.onload=function(e){
    try{
      ensureFin();
      let text=e.target.result; if(text.charCodeAt(0)===0xFEFF) text=text.slice(1);
      const rows=finParseCSV(text);
      if(rows.length<2){ toast('CSV has no data rows','e'); return; }
      let imported=0;
      for(let i=1;i<rows.length;i++){
        const c=rows[i]; if(c.length<7) continue;
        const total=parseFloat(c[6])||0; if(total<=0&&!c[1]) continue;
        DB.cityFinance.push({
          id:DB.nid.fin++, txId:parseInt(c[23])||null,
          date:c[1]||'', inv:c[2]||'', prsGrn:c[3]||'', invoiceDate:c[4]||'', party:c[5]||'',
          invoiceTotal:total, advPct:parseFloat(c[7])||0, advPaid:parseFloat(c[8])||0, advDate:c[9]||'',
          feePct:parseFloat(c[10])||0, fee:parseFloat(c[11])||0, holdback:parseFloat(c[12])||0, bank:c[13]||'',
          buyerPaidDate:c[14]||'', ratePct:parseFloat(c[15])||0, days:parseInt(c[16])||0,
          interest:parseFloat(c[17])||0, charges:parseFloat(c[18])||0, net:parseFloat(c[19])||0,
          status:(c[20]||'Funded'), alertNote:c[21]||'', notes:c[22]||'',
          createdAt:new Date().toISOString(), updatedAt:new Date().toISOString()
        });
        imported++;
      }
      saveDB(); renderCityFinance();
      finAudit('CREATE','Imported '+imported+' financing records from CSV');
      toast('Imported '+imported+' financing records','s');
    }catch(err){ toast('Import failed: '+err.message,'e'); }
    input.value='';
  };
  reader.readAsText(file);
}

// ── PRINTING (company letterhead via existing print system) ─
function buildFinVoucherHTML(r){
  const od=finIsOverdue(r);
  const days=r.status==='Settled'?(r.days||0):finDaysUsed(r);
  const boxes=sumBoxes([
    {label:'Total Invoice',value:finFmt(r.invoiceTotal)},
    {label:'Advance ('+(r.advPct||0)+'%)',value:finFmt(r.advPaid)},
    {label:'Holdback',value:finFmt(r.holdback)},
    {label:'Total Charges',value:finFmt(r.charges)},
    {label:'Net Released',value:finFmt(r.net)}
  ]);
  const tr=(l,v)=>`<tr><td style="padding:6px 10px;border:1px solid #e5e7eb;background:#f8fafc;font-weight:600;width:38%;">${l}</td><td style="padding:6px 10px;border:1px solid #e5e7eb;">${v}</td></tr>`;
  return boxes+`
  <table style="width:100%;border-collapse:collapse;font-size:12px;margin-top:12px;">
    ${tr('Financing ID','CBF-'+String(r.id).padStart(4,'0')+(r.txId?' (Linked Transaction #'+r.txId+')':''))}
    ${tr('Status',(r.status||'Funded')+(od?' — ⚠ OVERDUE':''))}
    ${tr('Party / Buyer',r.party||'—')}
    ${tr('Invoice No / Date',(r.inv||'—')+' / '+(r.invoiceDate||'—'))}
    ${tr('PRS / GRN No',r.prsGrn||'—')}
    ${tr('Drawdown Date',r.date||'—')}
    ${tr('Advance ('+(r.advPct||0)+'%) Paid by Bank',finFmt(r.advPaid)+(r.advDate?' on '+r.advDate:''))}
    ${tr('Received In',r.bank||'—')}
    ${tr('Upfront Fee ('+(r.feePct||0)+'%)',finFmt(r.fee))}
    ${tr('Holdback ('+(100-(r.advPct||0)).toFixed(2).replace(/\.00$/,'')+'%)',finFmt(r.holdback))}
    ${tr('Buyer Payment Date',r.buyerPaidDate||'— (not yet paid)')}
    ${tr('Days Money Used',days+' days'+(r.buyerPaidDate?'':' (running)'))}
    ${tr('Interest Rate',(r.ratePct||0)+'% per annum (holdback × rate × days ÷ 365)')}
    ${tr('Bank Interest',finFmt(r.interest))}
    ${tr('Total Charges (Fee + Interest)','<strong style="color:#991b1b;">'+finFmt(r.charges)+'</strong>')}
    ${tr('Net Holdback Released','<strong style="color:#16a34a;">'+finFmt(r.net)+'</strong>')}
    ${r.alertNote?tr('Alert Note',r.alertNote):''}
    ${r.notes?tr('Notes',r.notes):''}
  </table>`;
}
function printFinVoucher(id){
  ensureFin();
  const r=(DB.cityFinance||[]).find(x=>x.id===id);
  if(!r){ toast('Record not found','e'); return; }
  openPrintModal('City Bank Financing Voucher','CBF-'+String(r.id).padStart(4,'0'),buildFinVoucherHTML(r),r.party||'');
  finAudit('PRINT','Printed financing voucher #'+id);
}
function printFinFromModal(){
  const editId=parseInt(finV('fin-edit-id'))||0;
  if(!editId){ toast('Save the financing record first, then print','e'); return; }
  printFinVoucher(editId);
}
function printAllFinance(){
  ensureFin();
  let rows=[...DB.cityFinance];
  if(finF.search) rows=rows.filter(r=>['party','inv','prsGrn','status','notes','alertNote','bank'].some(k=>String(r[k]||'').toLowerCase().includes(finF.search)));
  if(finF.status==='Overdue') rows=rows.filter(r=>finIsOverdue(r));
  else if(finF.status) rows=rows.filter(r=>r.status===finF.status);
  if(finF.dateFrom) rows=rows.filter(r=>(r.date||'')>=finF.dateFrom);
  if(finF.dateTo)   rows=rows.filter(r=>(r.date||'')<=finF.dateTo);
  if(rows.length===0){ toast('Nothing to print','e'); return; }
  const sum=(k)=>rows.reduce((s,r)=>s+(parseFloat(r[k])||0),0);
  const boxes=sumBoxes([
    {label:'Records',value:rows.length},
    {label:'Total Invoices',value:finFmt(sum('invoiceTotal'))},
    {label:'Advance Taken',value:finFmt(sum('advPaid'))},
    {label:'Charges',value:finFmt(sum('charges'))},
    {label:'Net Released',value:finFmt(sum('net'))}
  ]);
  const body=rows.map((r,i)=>`<tr style="border-bottom:1px solid #eee;">
    <td style="padding:5px 6px;font-size:10px;color:#888;">${i+1}</td>
    <td style="padding:5px 6px;">${r.date||'—'}</td>
    <td style="padding:5px 6px;font-size:10px;">${r.inv||'—'}</td>
    <td style="padding:5px 6px;">${escHTML(r.party ||'—')}</td>
    <td style="padding:5px 6px;text-align:right;">${pn(r.invoiceTotal||0)}</td>
    <td style="padding:5px 6px;text-align:right;color:#1e40af;">${pn(r.advPaid||0)}</td>
    <td style="padding:5px 6px;text-align:right;color:#b91c1c;">${pn(r.holdback||0)}</td>
    <td style="padding:5px 6px;">${r.buyerPaidDate||'—'}</td>
    <td style="padding:5px 6px;text-align:center;">${r.status==='Settled'?(r.days||0):finDaysUsed(r)||'—'}</td>
    <td style="padding:5px 6px;text-align:right;">${pn(r.interest||0)}</td>
    <td style="padding:5px 6px;text-align:right;color:#991b1b;">${pn(r.charges||0)}</td>
    <td style="padding:5px 6px;text-align:right;color:#16a34a;font-weight:700;">${pn(r.net||0)}</td>
    <td style="padding:5px 6px;font-size:10px;">${r.status||''}${finIsOverdue(r)?' ⚠':''}</td>
  </tr>`).join('');
  const html=boxes+`<table style="width:100%;border-collapse:collapse;font-size:11px;margin-top:12px;">
    <thead><tr style="background:#1a3c8f;color:#fff;">
      <th style="padding:6px;">#</th><th style="padding:6px;">Drawdown</th><th style="padding:6px;">Invoice</th><th style="padding:6px;">Party</th>
      <th style="padding:6px;text-align:right;">Total Inv</th><th style="padding:6px;text-align:right;">Advance</th><th style="padding:6px;text-align:right;">Holdback</th>
      <th style="padding:6px;">Buyer Paid</th><th style="padding:6px;">Days</th><th style="padding:6px;text-align:right;">Interest</th>
      <th style="padding:6px;text-align:right;">Charges</th><th style="padding:6px;text-align:right;">Net Rel.</th><th style="padding:6px;">Status</th>
    </tr></thead><tbody>${body}</tbody>
    <tfoot><tr style="background:#f1f5f9;font-weight:700;">
      <td colspan="4" style="padding:6px;">TOTAL (${rows.length})</td>
      <td style="padding:6px;text-align:right;">${pn(sum('invoiceTotal'))}</td>
      <td style="padding:6px;text-align:right;">${pn(sum('advPaid'))}</td>
      <td style="padding:6px;text-align:right;">${pn(sum('holdback'))}</td>
      <td></td><td></td>
      <td style="padding:6px;text-align:right;">${pn(sum('interest'))}</td>
      <td style="padding:6px;text-align:right;">${pn(sum('charges'))}</td>
      <td style="padding:6px;text-align:right;">${pn(sum('net'))}</td><td></td>
    </tr></tfoot></table>`;
  openPrintModal('City Bank Financing Statement','CBF-STMT-'+todayStr(),html,'Factory Finance');
  finAudit('PRINT','Printed financing statement ('+rows.length+' records)');
}

// ── PRINT FIX: keep the letterhead print modal directly under <body> so no
//    ancestor style can ever blank the print output ─────────────────────────
(function(){
  function hoist(){
    const pm=document.getElementById('print-modal');
    if(pm && pm.parentElement!==document.body) document.body.appendChild(pm);
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',hoist);
  else hoist();
})();

