<script nonce="<?php echo $cspNonceAttr; ?>">
// Add ID aliases for email modal elements
document.addEventListener('DOMContentLoaded', function(){
  function addAlias(existingId, aliasId){
    const el=document.getElementById(existingId);
    if(el&&!document.getElementById(aliasId)){
      el.id=el.id; // keep original
      // Create a proxy getter
      Object.defineProperty(document,'_alias_'+aliasId,{value:el,configurable:true});
    }
  }
  // Override getElementById to support aliases
  const _origGetById=document.getElementById.bind(document);
  document.getElementById=function(id){
    const el=_origGetById(id);
    if(el) return el;
    // Try aliases
    const aliases={
      'em-template':'email-template','em-subject':'email-subject',
      'em-body':'email-body','em-to':'email-to',
      'em-report-addr':'email-to','report-email':'email-to',
      'er-reportEmail':'email-to','email-report-addr':'email-to',
      'dl-agents':'tx-agentA','prod-search':'pr-search-input',
      'pr-search':'pr-search-input'
    };
    if(aliases[id]) return _origGetById(aliases[id]);
    return null;
  };
});
</script>
