<script nonce="<?php echo $cspNonceAttr; ?>">
/* ── Sidebar handlers (added by static-scan fix v4) ──
   Previously referenced from inline onclick/oninput but never defined,
   which produced silent ReferenceErrors on every sidebar interaction. */
(function(){
  window.toggleNavSection = function(headerEl){
    var section = headerEl && headerEl.closest ? headerEl.closest('.nav-section') : null;
    if(!section) return;
    var collapsed = section.classList.toggle('collapsed');
    var body = section.querySelector('.nav-section-body');
    if(body) body.style.display = collapsed ? 'none' : '';
    var chev = headerEl.querySelector('.nav-section-chevron');
    if(chev) chev.textContent = collapsed ? '\u25B8' : '\u25BE';
  };

  window.filterNavItems = function(q){
    var query = String(q||'').trim().toLowerCase();
    var clear = document.getElementById('navSearchClear');
    if(clear) clear.style.display = query ? '' : 'none';
    var noRes = document.getElementById('navSearchNoResults');
    var matches = 0;
    var sections = document.querySelectorAll('.nav-section');
    for(var i=0;i<sections.length;i++){
      var section = sections[i], sectionHas = 0;
      var items = section.querySelectorAll('.nav-item');
      for(var j=0;j<items.length;j++){
        var it = items[j];
        // Respect access control here too — search must never re-reveal a page
        // the current user isn't permitted to see (previously it did, since this
        // only checked text and ignored permissions entirely).
        var km = /nav\('([\w-]+)'\)/.exec(it.getAttribute('onclick')||'');
        var permitted = !km || typeof window.canAccessPage!=='function' || window.canAccessPage(km[1]);
        var textHit = !query || it.textContent.toLowerCase().indexOf(query) >= 0;
        var hit = permitted && textHit;
        it.style.display = hit ? '' : 'none';
        if(hit) sectionHas++;
      }
      section.style.display = (!query || sectionHas) ? '' : 'none';
      matches += sectionHas;
      if(query && sectionHas){
        section.classList.remove('collapsed');
        var body = section.querySelector('.nav-section-body');
        if(body) body.style.display = '';
        var chev = section.querySelector('.nav-section-chevron');
        if(chev) chev.textContent = '\u25BE';
      }
    }
    if(noRes) noRes.style.display = (query && matches===0) ? 'block' : 'none';
  };

  window.clearNavSearch = function(){
    var inp = document.getElementById('navSearchInput');
    if(inp) inp.value = '';
    window.filterNavItems('');
    if(inp) inp.focus();
  };

  window.toggleSidebarCollapse = function(){
    var sidebar = document.querySelector('.sidebar') ||
                  document.getElementById('sidebar') ||
                  document.querySelector('aside');
    if(!sidebar) return;
    // Was toggling classes ('collapsed' on the nav, 'sidebar-collapsed' on body)
    // that the icon-only-rail CSS doesn't key off at all — the real width/spacing
    // rules (13608-13624 and the compact-professional block) all target
    // ".sidebar.icon-collapsed". Toggling the old classes either did nothing
    // visually or slid the whole rail off-canvas without reflowing the layout.
    var collapsed = sidebar.classList.toggle('icon-collapsed');
    var btn = document.getElementById('sidebarCollapseBtn');
    var icon = btn && btn.querySelector('.sidebar-collapse-icon');
    if(icon) icon.textContent = collapsed ? '\u00BB' : '\u00AB';
    if(btn) btn.title = collapsed ? 'Expand menu' : 'Collapse menu';
  };
})();
</script>
