/* ═══════════════════════════════════════════════════════════
   GLOBAL MOBILE RESPONSIVE FIX — v2 Power Pack
   Fixes 45 pages with overflow/fixed-width issues
   ═══════════════════════════════════════════════════════════ */
@media (max-width: 768px) {
  /* Tables scroll horizontally on mobile */
  table { display: block; overflow-x: auto; -webkit-overflow-scrolling: touch; width: 100%; }
  
  /* Fix fixed-width containers */
  [style*="min-width:600px"], [style*="min-width: 600px"],
  [style*="min-width:700px"], [style*="min-width: 700px"],
  [style*="min-width:800px"], [style*="min-width: 800px"],
  [style*="min-width:900px"], [style*="min-width: 900px"] {
    min-width: 0 !important; width: 100% !important;
  }
  
  /* Grid columns collapse to 1 on small screens */
  [style*="grid-template-columns:repeat(3"],
  [style*="grid-template-columns: repeat(3"],
  [style*="grid-template-columns:repeat(4"],
  [style*="grid-template-columns: repeat(4"],
  [style*="grid-template-columns:repeat(5"],
  [style*="grid-template-columns: repeat(5"] {
    grid-template-columns: 1fr 1fr !important;
  }
  
  /* 2-col grids collapse to 1 on very small screens */
  .chart-grid, .sum-card { width: 100% !important; }
  /* Grid tracks default to a min-content floor, which let card padding/text
     push .chart-grid wider than the screen (confirmed horizontal overflow
     on Balance Sheet at 360px). minmax(0,...) lets tracks actually shrink. */
  .chart-grid { grid-template-columns: minmax(0,1fr) minmax(0,1fr) !important; }

  /* The floating Quick Access button (⚡) was fixed at bottom:24px, which sits
     underneath the mobile bottom nav bar (60px tall) and overlaps the other
     floating + button — confirmed both were rendering on top of each other.
     Push it up clear of both. */
  #quick-access-fab { bottom: 144px !important; }
  
  /* Sidebar hidden on mobile — toggle via hamburger */
  .sidebar { transform: translateX(-100%); transition: transform 0.3s ease; position: fixed !important; z-index: 999; height: var(--app-vh,100vh); }
  .sidebar.mobile-open { transform: translateX(0); }
  body.sidebar-collapsed .sidebar { transform: translateX(-100%); }
  
  /* Main content full width on mobile */
  .main { margin-left: 0 !important; width: 100% !important; }
  
  /* Topbar adjustments */
  .topbar { padding: 8px 12px !important; }
  
  /* Cards full width */
  .table-card, .chart-card, .sum-card { margin: 6px 0 !important; border-radius: 8px !important; }
  
  /* Buttons wrap on mobile */
  .table-actions { flex-wrap: wrap !important; gap: 4px !important; }
  .btn { font-size: 11px !important; padding: 6px 10px !important; }
  
  /* Modal full screen on mobile */
  .modal-content, [class*="modal"] > div { 
    width: 95vw !important; max-width: 95vw !important; 
    max-height: 90vh !important; overflow-y: auto !important;
    margin: 5vh auto !important;
  }
  
  /* Input fields full width */
  input[type="text"], input[type="number"], input[type="date"], 
  input[type="email"], select, textarea {
    width: 100% !important; box-sizing: border-box !important;
  }
  
  /* Trial balance 2-col → 1-col on mobile */
  #trial-balance-section [style*="grid-template-columns:1fr 1fr"] {
    grid-template-columns: 1fr !important;
  }
  
  /* Report links 4-col → 2-col */
  #tb-report-links { grid-template-columns: 1fr 1fr !important; }
  
  /* Health cards 4-col → 2-col */
  #tb-health-cards { grid-template-columns: 1fr 1fr !important; }
  
  /* Page padding */
  .page { padding: 10px !important; }
  
  /* Font size adjustments */
  h2 { font-size: 16px !important; }
  .table-title { font-size: 13px !important; }
}

@media (max-width: 480px) {
  [style*="grid-template-columns:1fr 1fr"],
  [style*="grid-template-columns: 1fr 1fr"] {
    grid-template-columns: 1fr !important;
  }
  #tb-report-links { grid-template-columns: 1fr 1fr !important; }
  .topbar-search { display: none !important; }
}

/* Dark mode support */
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --bg-primary: #1e293b;
    --bg-secondary: #0f172a;
    --text-primary: #f1f5f9;
