#erp-loader {
  position: fixed;
  inset: 0;
  z-index: 99999;
  background: linear-gradient(135deg, #0a2d1c 0%, #0f3d26 50%, #16a34a 100%);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  font-family: 'Segoe UI', Arial, sans-serif;
  transition: opacity 0.6s ease, visibility 0.6s ease;
}
#erp-loader.hidden {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}
.loader-logo {
  font-size: 64px;
  margin-bottom: 16px;
  animation: loader-bounce 1.2s ease-in-out infinite;
}
@keyframes loader-bounce {
  0%, 100% { transform: translateY(0) scale(1); }
  50%       { transform: translateY(-12px) scale(1.08); }
}
.loader-title {
  font-size: 22px;
  font-weight: 900;
  color: #fff;
  margin-bottom: 4px;
  letter-spacing: 0.5px;
}
.loader-subtitle {
  font-size: 12px;
  color: rgba(255,255,255,0.65);
  margin-bottom: 32px;
}
.loader-bar-wrap {
  width: 280px;
  background: rgba(255,255,255,0.15);
  border-radius: 50px;
  height: 8px;
  overflow: hidden;
  margin-bottom: 12px;
}
.loader-bar {
  height: 100%;
  width: 0%;
  background: linear-gradient(90deg, #4ade80, #86efac);
  border-radius: 50px;
  transition: width 0.3s ease;
  box-shadow: 0 0 12px rgba(74,222,128,0.6);
}
.loader-status {
  font-size: 11px;
  color: rgba(255,255,255,0.7);
  margin-bottom: 28px;
  min-height: 16px;
  text-align: center;
}
.loader-steps {
  display: flex;
  flex-direction: column;
  gap: 6px;
  width: 280px;
}
.loader-step {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 11px;
  color: rgba(255,255,255,0.5);
  transition: color 0.3s;
}
.loader-step.done   { color: #4ade80; }
.loader-step.active { color: #fff; }
.loader-step-icon {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: rgba(255,255,255,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
  flex-shrink: 0;
  transition: background 0.3s;
}
.loader-step.done   .loader-step-icon { background: #16a34a; }
.loader-step.active .loader-step-icon { background: rgba(255,255,255,0.3); animation: loader-pulse 0.8s ease infinite; }
@keyframes loader-pulse {
  0%, 100% { opacity: 1; }
  50%       { opacity: 0.4; }
}
.loader-version {
  position: absolute;
  bottom: 20px;
  font-size: 10px;
  color: rgba(255,255,255,0.3);
}
/* Spinner ring */
.loader-ring {
  width: 56px;
  height: 56px;
  border: 4px solid rgba(255,255,255,0.15);
  border-top-color: #4ade80;
  border-radius: 50%;
  animation: loader-spin 0.9s linear infinite;
  margin-bottom: 20px;
}
@keyframes loader-spin {
  to { transform: rotate(360deg); }
}

