<!-- FIX (2026-08-28, structural audit): a stray closing-HEAD-tag plus a
     stray opening-BODY-tag used to sit right here — leftover from an
     earlier patch that pasted in this whole meta/link/style block (PWA
     tags, favicon, and the glass-panel-theme STYLE block above) from what
     was once its own separate mini-document. The one real HEAD/BODY pair
     is already up at the top of this file; this extra pair had no
     matching partner of its own, so it was invalid markup — silently
     tolerated by browsers (a stray head-close is simply ignored once the
     real head already closed, and a stray second body-open is ignored
     once a body is already open), which is why nothing visibly broke, but
     it left a genuine structural error sitting in the file. Removed here;
     nothing else on this page changed. -->

<script nonce="<?php echo $cspNonceAttr; ?>">
/* ═══════════════════════════════════════════════════════════
   GLOBAL UTILITY FUNCTIONS — Safety net
   Ensures all helper functions are available globally
   ═══════════════════════════════════════════════════════════ */

// pf() — format number with Bengali locale (no ৳ symbol)
if(typeof window.pf === 'undefined')
  window.pf = function(v){ return (parseFloat(v)||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2}); };

// pf2() — alias for pf
if(typeof window.pf2 === 'undefined')
  window.pf2 = window.pf;

// fmt() — compact number format (K/L/Cr)
if(typeof window.fmt === 'undefined')
  window.fmt = function(v){
    v = parseFloat(v)||0;
    if(Math.abs(v)>=10000000) return (v/10000000).toFixed(2)+'Cr';
    if(Math.abs(v)>=100000)   return (v/100000).toFixed(2)+'L';
    if(Math.abs(v)>=1000)     return (v/1000).toFixed(1)+'K';
    return v.toFixed(2);
  };

// esc() — escape HTML special chars
if(typeof window.esc === 'undefined')
  window.esc = function(s){ return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); };

// setV() — set input value by element ID
if(typeof window.setV === 'undefined')
  window.setV = function(id, val){ var el=document.getElementById(id); if(el) el.value = val||''; };

// sum() — sum array of objects by key
if(typeof window.sum === 'undefined')
  window.sum = function(arr, key){ return (arr||[]).reduce(function(s,o){ return s+(parseFloat(o[key])||0); }, 0); };

// tr() — table row helper
if(typeof window.tr === 'undefined')
  window.tr = function(cells, style){ return '<tr'+(style?' style="'+style+'"':'')+'>'+cells.map(function(c){ return '<td>'+c+'</td>'; }).join('')+'</tr>'; };

// say() — speech synthesis shortcut
if(typeof window.say === 'undefined')
  window.say = function(text){ if(window.speechSynthesis){ var u=new SpeechSynthesisUtterance(text); speechSynthesis.speak(u); } };

// pnParse() — parse number safely (renamed from pn to avoid collision with
// the `const pn` formatter at line ~29271, which shadows any bare pn() call)
if(typeof window.pnParse === 'undefined')
  window.pnParse = function(v){ return parseFloat(String(v||'').replace(/,/g,''))||0; };

// n() — format integer with commas
if(typeof window.n === 'undefined')
  window.n = function(v){ return (parseInt(v)||0).toLocaleString('en-IN'); };

// TODAY() — get today's date string
if(typeof window.TODAY === 'undefined')
  window.TODAY = function(){ return new Date().toISOString().split('T')[0]; };

// MONTH() — get current month string
if(typeof window.MONTH === 'undefined')
  window.MONTH = function(){ return new Date().toISOString().substring(0,7); };

// clamp() — clamp number between min and max
if(typeof window.clamp === 'undefined')
  window.clamp = function(v, mn, mx){ return Math.max(mn, Math.min(mx, v)); };

// toast() safety — if not defined
if(typeof window.toast === 'undefined')
  window.toast = function(msg, type){ console.log('[Toast]', msg); };

// nav() safety — if not defined
if(typeof window.nav === 'undefined')
  window.nav = function(page){ console.log('[Nav]', page); };

// ensureDivIn() safety
if(typeof window.ensureDivIn === 'undefined')
  window.ensureDivIn = function(parentId, childId){
    var parent = document.getElementById(parentId);
    if(!parent) return null;
    var child = document.getElementById(childId);
    if(!child){ child=document.createElement('div'); child.id=childId; parent.appendChild(child); }
    return child;
  };

// closeModalById() — VULN-11 follow-up: replaces the inline
// document.getElementById('X').style.display='none' one-liners so they can
// be migrated from data-x-click="..." to data-x-click="closeModalById('X')".
if(typeof window.closeModalById === 'undefined')
  window.closeModalById = function(id){
    var el = document.getElementById(id);
    if(el) el.style.display = 'none';
  };

// mkChart() safety — if Chart.js not loaded
if(typeof window.mkChart === 'undefined')
  window.mkChart = function(id){ console.warn('[Chart] mkChart called but Chart.js not ready for:', id); };

console.info('[Global Utils] All utility functions registered globally');
</script>
