<script nonce="<?php echo $cspNonceAttr; ?>">

// ── Safety: ensure pf() is always global ──
if(typeof window.pf === 'undefined'){
  window.pf  = function(v){ return (parseFloat(v)||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2}); };
  window.pf2 = window.pf;
}

/* Loading screen controller */
(function(){
  var bar     = document.getElementById('loader-bar');
  var status  = document.getElementById('loader-status');
  var loader  = document.getElementById('erp-loader');
  var _pct    = 0;

  function setStep(id, state){
    var el = document.getElementById('lstep-'+id);
    if(!el) return;
    el.className = 'loader-step ' + state;
    el.querySelector('.loader-step-icon').textContent = state==='done' ? '✅' : state==='active' ? '⏳' : '○';
  }

  function setProgress(pct, msg){
    _pct = pct;
    if(bar)    bar.style.width = pct + '%';
    if(status) status.textContent = msg || '';
  }

  // Step 1: CSS loaded (we're already here)
  setStep('css', 'done');
  setStep('js', 'active');
  setProgress(14, 'Loading JavaScript modules...');

  // Step 2: JS parsing done (DOMContentLoaded)
  document.addEventListener('DOMContentLoaded', function(){
    setStep('js', 'done');
    setStep('chartjs', 'active');
    setProgress(28, 'Initializing Chart.js...');

    setTimeout(function(){
      // Step 3: Chart.js
      var chartOk = typeof Chart !== 'undefined';
      setStep('chartjs', 'done');
      setStep('db', 'active');
      setProgress(42, 'Loading database from server...');

      setTimeout(function(){
        // Step 4: DB
        var dbSize = 0;
        try{ dbSize = (window.DB ? JSON.stringify(window.DB).length : 0); }catch(e){}
        setStep('db', 'done');
        setStep('ui', 'active');
        setProgress(57, 'Building UI components (' + (dbSize>0?(dbSize/1024).toFixed(0)+' KB':'fresh start') + ')...');

        setTimeout(function(){
          // Step 5: UI
          setStep('ui', 'done');
          setStep('data', 'active');
          setProgress(72, 'Preparing reports & analytics...');

          setTimeout(function(){
            // Step 6: Data
            setStep('data', 'done');
            setStep('ready', 'active');
            setProgress(90, 'Almost ready...');

            setTimeout(function(){
              // Step 7: Ready
              setStep('ready', 'done');
              setProgress(100, '✅ System ready!');

              setTimeout(function(){
                // Hide loader
                if(loader){
                  loader.classList.add('hidden');
                  setTimeout(function(){ loader.style.display='none'; }, 700);
                }
              }, 400);
            }, 300);
          }, 400);
        }, 350);
      }, 300);
    }, 200);
  });

  // Fallback: hide after 6 seconds no matter what
  setTimeout(function(){
    if(loader && !loader.classList.contains('hidden')){
      setProgress(100, '✅ Ready!');
      loader.classList.add('hidden');
      setTimeout(function(){ loader.style.display='none'; }, 700);
    }
  }, 6000);
})();
</script>
