<script nonce="<?php echo $cspNonceAttr; ?>">
/* ═══════════════════════════════════════════════════════════
   TECHNOLOGY UPGRADE PACK — v3
   Adds: IndexedDB backup, Share API, Vibration feedback,
   Fullscreen toggle, Dark Mode auto-detect, 
   Intersection Observer lazy-render, Mobile hamburger fix,
   Keyboard shortcuts, Network status indicator
   ═══════════════════════════════════════════════════════════ */

// ── 1. IndexedDB for large data backup ──
(function initIndexedDB(){
  if(!window.indexedDB) return;
  const req = indexedDB.open('AyanERP_IDB', 1);
  req.onupgradeneeded = e => {
    const db = e.target.result;
    if(!db.objectStoreNames.contains('snapshots'))
      db.createObjectStore('snapshots', {keyPath:'id', autoIncrement:true});
  };
  req.onsuccess = e => {
    window._idb = e.target.result;
    console.info('[IDB] IndexedDB ready — large backup storage available');
  };
  // Save snapshot to IDB
  window.saveIDBSnapshot = function(){
    if(!window._idb) return;
    const tx = window._idb.transaction('snapshots','readwrite');
    tx.objectStore('snapshots').add({data: JSON.stringify(DB), ts: Date.now()});
    localStorage.setItem('ayan_last_backup', Date.now().toString());
    if(typeof toast==='function') toast('💾 Backup saved to IndexedDB','s');
  };
  // Auto-snapshot every 30 min
  setInterval(()=>{ if(window.saveIDBSnapshot) window.saveIDBSnapshot(); }, 30*60*1000);
})();

// ── 2. Web Share API ──
window.shareReport = function(title, text){
  if(navigator.share){
    navigator.share({title: title||'ERP Report', text: text||'Shared from Ayan Agro ERP', url: window.location.href})
      .catch(()=>{});
  } else {
    if(navigator.clipboard) navigator.clipboard.writeText(text||window.location.href);
    if(typeof toast==='function') toast('📋 Link copied to clipboard','s');
  }
};

// ── 3. Vibration feedback for mobile actions ──
window.vibrate = function(pattern){
  if(navigator.vibrate) navigator.vibrate(pattern||[50]);
};
// Add vibration to save/delete actions
document.addEventListener('click', function(e){
  const btn = e.target.closest('button');
  if(!btn) return;
  const txt = (btn.textContent||'').toLowerCase();
  if(txt.includes('save')||txt.includes('add')||txt.includes('submit')) navigator.vibrate&&navigator.vibrate([30]);
  if(txt.includes('delete')||txt.includes('remove')) navigator.vibrate&&navigator.vibrate([50,30,50]);
}, {passive:true});

// ── 4. Fullscreen toggle ──
window.toggleFullscreen = function(){
  if(!document.fullscreenElement){
    document.documentElement.requestFullscreen&&document.documentElement.requestFullscreen();
  } else {
    document.exitFullscreen&&document.exitFullscreen();
  }
};

// ── 5. Dark Mode auto-detect & persistence ──
(function initDarkMode(){
  const saved = localStorage.getItem('ayan_theme');
  const prefersDark = window.matchMedia&&window.matchMedia('(prefers-color-scheme:dark)').matches;
  const theme = saved || (prefersDark?'dark':'light');
  if(theme==='dark') document.documentElement.setAttribute('data-theme','dark');
  // Listen for system changes
  window.matchMedia&&window.matchMedia('(prefers-color-scheme:dark)').addEventListener('change',e=>{
    if(!localStorage.getItem('ayan_theme')){
      document.documentElement.setAttribute('data-theme', e.matches?'dark':'light');
    }
  });
})();

// ── 6. Intersection Observer — lazy render pages ──
(function initLazyRender(){
  if(!window.IntersectionObserver) return;
  const observer = new IntersectionObserver((entries)=>{
    entries.forEach(entry=>{
      if(entry.isIntersecting){
        const el = entry.target;
        if(el.dataset.lazyRender){
          try{ window[el.dataset.lazyRender]&&window[el.dataset.lazyRender](); }catch(e){}
          delete el.dataset.lazyRender;
          observer.unobserve(el);
        }
      }
    });
  },{threshold:0.1});
  window._lazyObserver = observer;
})();

// ── 7. Network status indicator ──
(function initNetworkStatus(){
  const showStatus = (online) => {
    let bar = document.getElementById('network-status-bar');
    if(!bar){
      bar = document.createElement('div');
      bar.id = 'network-status-bar';
      bar.style.cssText = 'position:fixed;bottom:0;left:0;right:0;z-index:99999;text-align:center;font-size:12px;font-weight:700;padding:4px;transition:all 0.3s;';
      document.body.appendChild(bar);
    }
    if(online){
      bar.style.background='#16a34a'; bar.style.color='#fff';
      bar.textContent='✅ Online — data synced';
      setTimeout(()=>{ bar.style.display='none'; }, 3000);
    } else {
      bar.style.display='block'; bar.style.background='#dc2626'; bar.style.color='#fff';
      bar.textContent='⚠️ Offline — working locally, data safe';
    }
  };
  window.addEventListener('online',  ()=>showStatus(true));
  window.addEventListener('offline', ()=>showStatus(false));
  if(!navigator.onLine) showStatus(false);
})();

// ── 8. Keyboard shortcuts ──
document.addEventListener('keydown', function(e){
  if(e.ctrlKey||e.metaKey){
    switch(e.key){
      case 'd': e.preventDefault(); typeof nav==='function'&&nav('dashboard'); break;
      case 't': e.preventDefault(); typeof nav==='function'&&nav('transactions'); break;
      case 'r': e.preventDefault(); typeof nav==='function'&&nav('reports'); break;
      case 'b': e.preventDefault(); typeof nav==='function'&&nav('balancesheet'); break;
      case 'p': e.preventDefault(); typeof nav==='function'&&nav('profitloss'); break;
      case 's': e.preventDefault(); typeof nav==='function'&&nav('settings'); break;
      case 'h': e.preventDefault(); typeof nav==='function'&&nav('healthcheck'); break;
      case 'f': e.preventDefault(); window.toggleFullscreen&&window.toggleFullscreen(); break;
    }
  }
  // ESC closes modals
  if(e.key==='Escape'){
    document.querySelectorAll('.overlay[style*="flex"],.overlay[style*="block"]').forEach(o=>{
      if(o.id && typeof closeModal==='function') closeModal(o.id);
    });
  }
});

// ── 9. Mobile hamburger sidebar fix ──
(function fixMobileHamburger(){
  document.addEventListener('DOMContentLoaded', function(){
    const sidebar = document.querySelector('.sidebar')||document.getElementById('sidebar');
    if(!sidebar) return;
    // Add overlay for mobile sidebar close
    let overlay = document.getElementById('mobile-sidebar-overlay');
    if(!overlay){
      overlay = document.createElement('div');
      overlay.id = 'mobile-sidebar-overlay';
      overlay.style.cssText = 'display:none;position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:998;';
      overlay.onclick = ()=>{ sidebar.classList.remove('mobile-open'); overlay.style.display='none'; };
      document.body.appendChild(overlay);
    }
    // Patch toggleSidebarCollapse for mobile
    const orig = window.toggleSidebarCollapse;
    window.toggleSidebarCollapse = function(){
      if(window.innerWidth<=768){
        sidebar.classList.toggle('mobile-open');
        overlay.style.display = sidebar.classList.contains('mobile-open')?'block':'none';
      } else {
        if(orig) orig();
      }
    };
  });
})();

// ── 10. Performance: Virtual scroll hint for large tables ──
window.applyVirtualScroll = function(tableId, rowHeight){
  rowHeight = rowHeight||40;
  const table = document.getElementById(tableId);
  if(!table) return;
  const rows = table.querySelectorAll('tbody tr');
  if(rows.length < 100) return; // Only for large tables
  const container = table.closest('[style*="overflow"]')||table.parentElement;
  if(container) container.style.maxHeight = (rowHeight*20)+'px';
  if(container) container.style.overflowY = 'auto';
};

// ── 11. Crypto hash for data integrity ──
window.hashData = async function(data){
  if(!window.crypto||!window.crypto.subtle) return null;
  const enc = new TextEncoder().encode(typeof data==='string'?data:JSON.stringify(data));
  const buf = await crypto.subtle.digest('SHA-256', enc);
  return Array.from(new Uint8Array(buf)).map(b=>b.toString(16).padStart(2,'0')).join('');
};

// ── 12. Speech API — read out alerts ──
window.speakAlert = function(text){
  if(!window.speechSynthesis) return;
  const utt = new SpeechSynthesisUtterance(text);
  utt.lang = 'en-US'; utt.rate = 0.9;
  speechSynthesis.speak(utt);
};

// ── 13. Battery API — warn on low battery ──
(function initBattery(){
  if(!navigator.getBattery) return;
  navigator.getBattery().then(bat=>{
    const check = ()=>{ if(bat.level<0.15&&!bat.charging && typeof toast==='function') toast('🔋 Low battery ('+Math.round(bat.level*100)+'%) — save your work!','w'); };
    bat.addEventListener('levelchange', check);
    check();
  }).catch(()=>{});
})();

// ── 14. Add "Share" & "Fullscreen" buttons to topbar ──
document.addEventListener('DOMContentLoaded', function(){
  const topbar = document.querySelector('.topbar');
  if(!topbar) return;
  // Add fullscreen button if not present
  if(!document.getElementById('btn-fullscreen')){
    const btn = document.createElement('button');
    btn.id = 'btn-fullscreen';
    btn.title = 'Toggle Fullscreen (Ctrl+F)';
    btn.style.cssText = 'background:none;border:none;font-size:16px;cursor:pointer;padding:4px 8px;border-radius:6px;';
    btn.innerHTML = '⛶';
    btn.onclick = window.toggleFullscreen;
    topbar.appendChild(btn);
  }
});

console.info('[ERP v3] Technology Upgrade Pack loaded — IndexedDB, Share API, Vibration, Fullscreen, Dark Mode, Network Status, Keyboard Shortcuts, Mobile Fix, Virtual Scroll, Crypto Hash, Speech API, Battery API');
</script>
