<script nonce="<?php echo $cspNonceAttr; ?>">
/* ═══════════════════════════════════════════════════════════
   ADVANCED FEATURES PACK — Batch 1
   Cash Flow | Budget vs Actual | Break-even | Depreciation
   P&L Monthly Chart | VAT Auto-calc | Credit Limit Check
   Recurring Tx | Auto Reminder | Bank CSV Import
   QR Code | PDF Export | Audit Trail | Encryption
   Employee Attendance | Leave Management | Multi-currency
   ═══════════════════════════════════════════════════════════ */

// ── 1. CASH FLOW STATEMENT ──────────────────────────────────
function renderCashFlow(){
  const el = document.getElementById('pg-cashflow') || (() => {
    const d = document.createElement('div');
    d.id = 'pg-cashflow'; d.className = 'page'; d.style.display = 'none';
    (document.querySelector('.main')||document.body).appendChild(d);
    return d;
  })();

  const txs = DB.tx||[];
  const f = v => '৳'+Math.abs(v||0).toLocaleString('en-IN');
  const months = [];
  const now = new Date();
  for(let i=5;i>=0;i--){
    const d = new Date(now.getFullYear(), now.getMonth()-i, 1);
    months.push(d.toISOString().substring(0,7));
  }

  /* FIX: this page used to carry its own hard-coded type lists, so every type
     added elsewhere (Werhouse Purchase, Sales Return, Payment Refund, Purchase
     Advance, Sale Return...) silently fell out of the statement. Classification
     now derives from the canonical shared sets plus the money-movement types,
     and anything unrecognised is reported so nothing is dropped in silence. */
  const norm = t => (window.normTxType ? window.normTxType(t) : String(t||'').trim());
  const MONEY_IN  = new Set(['Sales Receipt','Cash Received','Sales Advance','Other Income',
                             'Interest Income','Purchase Return','Supplier Refund','Payment Refund',
                             'Loan Received','Capital Injection']);
  const MONEY_OUT = new Set(['Purchase Payment','Purchase Advance','Sales Return','Sale Return',
                             'Customer Refund','Loan Repayment','Drawings','Salary Advance']);
  function cashDir(t){
    const ty = norm(t.type);
    if(MONEY_IN.has(ty))  return 'in';
    if(MONEY_OUT.has(ty)) return 'out';
    if(typeof isRevenueTx === 'function' && isRevenueTx(t)) return 'in';
    if(window.PURCHASE_TX_TYPES && window.PURCHASE_TX_TYPES.has(ty)) return 'out';
    if(window.EXPENSE_TX_TYPES && window.EXPENSE_TX_TYPES.has(ty))   return 'out';
    return null;                       // journal / transfer / unknown — not cash
  }

  const rows = months.map(m => {
    const inMonth = txs.filter(t=>t.date&&String(t.date).startsWith(m));
    const inflow  = inMonth.filter(t=>cashDir(t)==='in').reduce((s,t)=>s+txAmt(t),0);
    const outflow = inMonth.filter(t=>cashDir(t)==='out').reduce((s,t)=>s+txAmt(t),0);
    const net = inflow - outflow;
    return {month:m, inflow, outflow, net};
  });

  const totalIn  = rows.reduce((s,r)=>s+r.inflow,0);
  const totalOut = rows.reduce((s,r)=>s+r.outflow,0);
  const totalNet = totalIn - totalOut;

  el.innerHTML = `
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:18px;">
      <div>
        <h2 style="font-size:20px;font-weight:900;color:#0f3d26;margin:0;">💧 Cash Flow Statement</h2>
        <p style="font-size:12px;color:#6b7280;margin:2px 0 0;">Last 6 months — Inflow vs Outflow vs Net</p>
      </div>
      <button data-x-click="renderCashFlow()" style="padding:8px 16px;background:#16a34a;color:#fff;border:none;border-radius:7px;font-size:12px;font-weight:700;cursor:pointer;">🔄 Refresh</button>
    </div>

    <!-- Summary Cards -->
    <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:18px;">
      <div data-x-click="openCashFlowRange('${months[0]}','${months[months.length-1]}')" style="cursor:pointer;background:#f0fdf4;border:1px solid #bbf7d0;border-radius:10px;padding:16px;text-align:center;" title="Click to see all inflow/outflow transactions">
        <div style="font-size:11px;color:#6b7280;margin-bottom:4px;">Total Inflow</div>
        <div style="font-size:20px;font-weight:900;color:#16a34a;">${f(totalIn)}</div>
      </div>
      <div data-x-click="openCashFlowRange('${months[0]}','${months[months.length-1]}')" style="cursor:pointer;background:#fef2f2;border:1px solid #fecaca;border-radius:10px;padding:16px;text-align:center;" title="Click to see all inflow/outflow transactions">
        <div style="font-size:11px;color:#6b7280;margin-bottom:4px;">Total Outflow</div>
        <div style="font-size:20px;font-weight:900;color:#dc2626;">${f(totalOut)}</div>
      </div>
      <div data-x-click="openCashFlowRange('${months[0]}','${months[months.length-1]}')" style="cursor:pointer;background:${totalNet>=0?'#f0fdf4':'#fef2f2'};border:1px solid ${totalNet>=0?'#bbf7d0':'#fecaca'};border-radius:10px;padding:16px;text-align:center;" title="Click to see all inflow/outflow transactions">
        <div style="font-size:11px;color:#6b7280;margin-bottom:4px;">Net Cash Flow</div>
        <div style="font-size:20px;font-weight:900;color:${totalNet>=0?'#16a34a':'#dc2626'};">${totalNet>=0?'+':''}${f(totalNet)}</div>
      </div>
    </div>

    <!-- Monthly Table -->
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;margin-bottom:16px;">
      <table style="width:100%;border-collapse:collapse;">
        <thead>
          <tr style="background:#0f3d26;color:#fff;">
            <th style="padding:12px 16px;text-align:left;font-size:12px;">Month</th>
            <th style="padding:12px 16px;text-align:right;font-size:12px;">💚 Inflow</th>
            <th style="padding:12px 16px;text-align:right;font-size:12px;">❤️ Outflow</th>
            <th style="padding:12px 16px;text-align:right;font-size:12px;">Net</th>
            <th style="padding:12px 16px;text-align:center;font-size:12px;">Status</th>
          </tr>
        </thead>
        <tbody>
          ${rows.map((r,i)=>`
            <tr data-x-click="openCashFlowMonth('${r.month}')" style="border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};cursor:pointer;" title="Click to see this month's transactions">
              <td style="padding:10px 16px;font-size:12px;font-weight:700;">${r.month} →</td>
              <td style="padding:10px 16px;text-align:right;font-size:12px;color:#16a34a;">${f(r.inflow)}</td>
              <td style="padding:10px 16px;text-align:right;font-size:12px;color:#dc2626;">${f(r.outflow)}</td>
              <td style="padding:10px 16px;text-align:right;font-size:12px;font-weight:700;color:${r.net>=0?'#16a34a':'#dc2626'};">${r.net>=0?'+':''}${f(r.net)}</td>
              <td style="padding:10px 16px;text-align:center;font-size:11px;">${r.net>=0?'✅ Positive':'❌ Negative'}</td>
            </tr>`).join('')}
          <tr data-x-click="openCashFlowRange('${months[0]}','${months[months.length-1]}')" style="background:#f0fdf4;font-weight:900;cursor:pointer;" title="Click to see all 6 months' transactions">
            <td style="padding:12px 16px;font-size:13px;">TOTAL →</td>
            <td style="padding:12px 16px;text-align:right;font-size:13px;color:#16a34a;">${f(totalIn)}</td>
            <td style="padding:12px 16px;text-align:right;font-size:13px;color:#dc2626;">${f(totalOut)}</td>
            <td style="padding:12px 16px;text-align:right;font-size:13px;color:${totalNet>=0?'#16a34a':'#dc2626'};">${totalNet>=0?'+':''}${f(totalNet)}</td>
            <td style="padding:12px 16px;text-align:center;">${totalNet>=0?'✅':'❌'}</td>
          </tr>
        </tbody>
      </table>
    </div>

    <!-- Visual Bar Chart -->
    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:16px;">
      <div style="font-size:13px;font-weight:800;color:#0f3d26;margin-bottom:12px;">📊 Cash Flow Chart</div>
      <canvas id="cashflow-chart" height="120"></canvas>
    </div>
  `;

  // Draw chart
  setTimeout(()=>{
    mkChart('cashflow-chart','bar',
      months,
      [
        {label:'Inflow',  data:rows.map(r=>r.inflow),  backgroundColor:'#4ade80', borderRadius:4},
        {label:'Outflow', data:rows.map(r=>r.outflow), backgroundColor:'#f87171', borderRadius:4},
        {label:'Net',     data:rows.map(r=>r.net),     backgroundColor:rows.map(r=>r.net>=0?'#3b82f6':'#f97316'), borderRadius:4, type:'line'},
      ],
      {plugins:{legend:{display:true}},scales:{y:{ticks:{callback:v=>'৳'+(v/1000).toFixed(0)+'K'}}}}
    );
  },100);
}

// Clicking a month in the Cash Flow table opens the full Transaction Sheet
// filtered to that month — real rows you can edit, delete, print or export,
// not just a number.
function openCashFlowMonth(monthStr){
  nav('txsheet');
  setTimeout(function(){
    var from=monthStr+'-01';
    var d=new Date(monthStr+'-01T00:00:00');
    var to=new Date(d.getFullYear(), d.getMonth()+1, 0).toISOString().substring(0,10);
    var fEl=document.getElementById('tsheet-from'), tEl=document.getElementById('tsheet-to');
    if(fEl) fEl.value=from;
    if(tEl) tEl.value=to;
    if(typeof filterTxSheet==='function') filterTxSheet();
  },80);
}
function openCashFlowRange(fromMonth,toMonth){
  nav('txsheet');
  setTimeout(function(){
    var d2=new Date(toMonth+'-01T00:00:00');
    var to=new Date(d2.getFullYear(), d2.getMonth()+1, 0).toISOString().substring(0,10);
    var fEl=document.getElementById('tsheet-from'), tEl=document.getElementById('tsheet-to');
    if(fEl) fEl.value=fromMonth+'-01';
    if(tEl) tEl.value=to;
    if(typeof filterTxSheet==='function') filterTxSheet();
  },80);
}

// ── 2. BUDGET vs ACTUAL ─────────────────────────────────────
window.DB_BUDGET = window.DB_BUDGET || {};

function renderBudgetVsActual(){
  const el = document.getElementById('pg-budget') || (() => {
    const d = document.createElement('div');
    d.id = 'pg-budget'; d.className = 'page'; d.style.display = 'none';
    (document.querySelector('.main')||document.body).appendChild(d);
    return d;
  })();

  const txs = DB.tx||[];
  /* FIX: budgets used to be a single flat object, so August's targets also
     showed for every other month. They are now keyed by month, and the month
     is selectable. Legacy flat budgets are migrated to the current month. */
  const thisMonth = window.BUDGET_MONTH || new Date().toISOString().substring(0,7);
  window.BUDGET_MONTH = thisMonth;
  const f = v => '৳'+Math.abs(v||0).toLocaleString('en-IN');
  DB.budget = DB.budget || {};
  const legacyKeys = ['sales','purchase','salary','rent','transport','other'];
  if(legacyKeys.some(k=>typeof DB.budget[k] === 'number')){
    const moved = {};
    legacyKeys.forEach(k=>{ if(typeof DB.budget[k]==='number'){ moved[k]=DB.budget[k]; delete DB.budget[k]; } });
    DB.budget[new Date().toISOString().substring(0,7)] = moved;
  }
  const budget = DB.budget[thisMonth] || {};

  const categories = [
    {key:'sales',    label:'Sales Revenue',    icon:'💰', actual: txs.filter(t=>t.date&&t.date.startsWith(thisMonth)&&(typeof isRevenueTx==='function'?isRevenueTx(t):['Sale','Warehouse Sale','Customer Sale'].includes(t.type))).reduce((s,t)=>s+txAmt(t),0), isIncome:true},
    {key:'purchase', label:'Purchases',         icon:'🛒', actual: txs.filter(t=>t.date&&t.date.startsWith(thisMonth)&&isCogsTx(t)).reduce((s,t)=>s+txAmt(t),0)},
    {key:'salary',   label:'Salary',            icon:'👤', actual: txs.filter(t=>t.date&&t.date.startsWith(thisMonth)&&t.type==='Salary Payment').reduce((s,t)=>s+txAmt(t),0)},
    {key:'rent',     label:'Office Rent',       icon:'🏢', actual: txs.filter(t=>t.date&&t.date.startsWith(thisMonth)&&t.type==='Office Rent').reduce((s,t)=>s+txAmt(t),0)},
    {key:'transport',label:'Transport',         icon:'🚛', actual: txs.filter(t=>t.date&&t.date.startsWith(thisMonth)&&['Transport Cost','Fuel Expense','Loading Charge','Unloading Charge'].includes(t.type)).reduce((s,t)=>s+txAmt(t),0)},
    {key:'other',    label:'Other Expenses',    icon:'📋', actual: txs.filter(t=>t.date&&t.date.startsWith(thisMonth)&&['Other Expense','Maintenance Cost','Repair Expense','Stationery Purchase'].includes(t.type)).reduce((s,t)=>s+txAmt(t),0)},
  ];

  el.innerHTML = `
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:18px;">
      <div>
        <h2 style="font-size:20px;font-weight:900;color:#0f3d26;margin:0;">🎯 Budget vs Actual</h2>
        <p style="font-size:12px;color:#6b7280;margin:2px 0 0;">Set budgets and track performance</p>
      </div>
      <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;">
      <input type="month" id="budget-month" value="${thisMonth}" data-x-change="xBudgetMonthChange(this.value)"
        style="padding:7px 10px;border:1px solid #d1d5db;border-radius:7px;font-size:12px;" />
      <button data-x-click="saveBudget()" style="padding:8px 16px;background:#16a34a;color:#fff;border:none;border-radius:7px;font-size:12px;font-weight:700;cursor:pointer;">💾 Save Budget</button>
      </div>
    </div>

    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
      <table style="width:100%;border-collapse:collapse;">
        <thead>
          <tr style="background:#0f3d26;color:#fff;">
            <th style="padding:12px 16px;text-align:left;font-size:12px;">Category</th>
            <th style="padding:12px 16px;text-align:right;font-size:12px;">Budget (৳)</th>
            <th style="padding:12px 16px;text-align:right;font-size:12px;">Actual (৳)</th>
            <th style="padding:12px 16px;text-align:right;font-size:12px;">Variance</th>
            <th style="padding:12px 16px;text-align:center;font-size:12px;">Progress</th>
          </tr>
        </thead>
        <tbody>
          ${categories.map(cat=>{
            const bud = budget[cat.key]||0;
            const pct = bud>0?Math.min(150,Math.round(cat.actual/bud*100)):0;
            const over = cat.actual > bud && bud > 0;
            const variance = cat.isIncome ? cat.actual - bud : bud - cat.actual;
            return `<tr style="border-bottom:1px solid #f3f4f6;">
              <td data-x-click="openPLDrill('${thisMonth}-01','${thisMonth}-31')" style="cursor:pointer;padding:10px 16px;font-size:12px;" title="Click to see this month's transactions">${cat.icon} ${cat.label} →</td>
              <td style="padding:10px 16px;text-align:right;">
                <input type="number" id="bud-${cat.key}" value="${bud}" data-x-change="saveBudget()"
                  style="width:100px;padding:4px 8px;border:1px solid #d1d5db;border-radius:4px;font-size:12px;text-align:right;"/>
              </td>
              <td style="padding:10px 16px;text-align:right;font-size:12px;font-weight:700;">${f(cat.actual)}</td>
              <td style="padding:10px 16px;text-align:right;font-size:12px;font-weight:700;color:${variance>=0?'#16a34a':'#dc2626'};">${variance>=0?'+':''}${f(variance)}</td>
              <td style="padding:10px 16px;">
                <div style="background:#f3f4f6;border-radius:4px;height:8px;overflow:hidden;">
                  <div style="height:100%;width:${Math.min(100,pct)}%;background:${over?'#ef4444':'#16a34a'};border-radius:4px;"></div>
                </div>
                <div style="font-size:10px;text-align:center;color:#6b7280;margin-top:2px;">${pct}%</div>
              </td>
            </tr>`;
          }).join('')}
        </tbody>
      </table>
    </div>
    <div style="margin-top:10px;font-size:11px;color:#6b7280;text-align:center;">💡 Enter budget amounts and click Save Budget to track monthly targets</div>
  `;
}

function saveBudget(){
  DB.budget = DB.budget||{};
  const m = window.BUDGET_MONTH || new Date().toISOString().substring(0,7);
  DB.budget[m] = DB.budget[m] || {};
  ['sales','purchase','salary','rent','transport','other'].forEach(k=>{
    const el = document.getElementById('bud-'+k);
    if(el) DB.budget[m][k] = parseFloat(el.value)||0;
  });
  saveDB();
  if(typeof toast==='function') toast('Budget saved for '+m, 's');
  renderBudgetVsActual();
}

// ── 3. BREAK-EVEN ANALYSIS ──────────────────────────────────
function renderBreakEven(){
  const el = document.getElementById('pg-breakeven') || (() => {
    const d = document.createElement('div');
    d.id = 'pg-breakeven'; d.className = 'page'; d.style.display = 'none';
    (document.querySelector('.main')||document.body).appendChild(d);
    return d;
  })();

  const txs = DB.tx||[];
  const f = v => '৳'+Math.abs(v||0).toLocaleString('en-IN');
  const thisMonth = new Date().toISOString().substring(0,7);

  const sales   = txs.filter(t=>t.date&&t.date.startsWith(thisMonth)&&isRevenueTx(t)).reduce((s,t)=>s+txAmt(t),0);
  const cogs    = window.computeCOGS(txs.filter(t=>t.date&&t.date.startsWith(thisMonth)));
  /* FIX: only 10 expense types were classified, so every other expense
     (rates, insurance, bank charges...) vanished from the break-even maths and
     the break-even point came out far too low. Variable costs are the listed
     volume-driven ones; EVERY other expense type is treated as fixed. */
  const VARIABLE_EXP = new Set(['Transport Cost','Loading Charge','Unloading Charge','Commission Payment','Brokerage Fee','Fuel Expense']);
  const monthExp = txs.filter(t=>t.date&&t.date.startsWith(thisMonth)&&(typeof isExpenseType==='function'?isExpenseType(t.type):false));
  const varExp   = monthExp.filter(t=>VARIABLE_EXP.has(String(t.type||'').trim())).reduce((s,t)=>s+txAmt(t),0);
  const fixedExp = monthExp.filter(t=>!VARIABLE_EXP.has(String(t.type||'').trim())).reduce((s,t)=>s+txAmt(t),0);

  const grossMargin = sales>0?(sales-cogs)/sales:0;
  const contribMargin = sales>0?(sales-cogs-varExp)/sales:0;
  const breakEvenSales = contribMargin>0?fixedExp/contribMargin:0;
  const safetyMargin = sales>0?((sales-breakEvenSales)/sales*100):0;
  const profitAtCurrent = sales - cogs - fixedExp - varExp;

  el.innerHTML = `
    <div style="margin-bottom:18px;">
      <h2 style="font-size:20px;font-weight:900;color:#0f3d26;margin:0;">📐 Break-Even Analysis</h2>
      <p style="font-size:12px;color:#6b7280;margin:2px 0 0;">Month: ${thisMonth} — How much you need to sell to cover all costs</p>
    </div>

    <div style="display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin-bottom:18px;">
      ${[
        {label:'Break-Even Sales', val:f(breakEvenSales), color:'#f59e0b', icon:'⚖️', note:'Minimum sales to cover all costs'},
        {label:'Current Sales',    val:f(sales),          color:'#16a34a', icon:'💰', note:'Actual sales this month'},
        {label:'Safety Margin',    val:safetyMargin.toFixed(1)+'%', color:safetyMargin>20?'#16a34a':safetyMargin>0?'#f59e0b':'#dc2626', icon:'🛡️', note:'How far above break-even you are'},
        {label:'Net Profit',       val:f(profitAtCurrent), color:profitAtCurrent>=0?'#16a34a':'#dc2626', icon:'📈', note:'Profit after all costs'},
      ].map(c=>`<div data-x-click="openPLDrill('${thisMonth}-01','${thisMonth}-31')" style="cursor:pointer;background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:16px;" title="Click to see this month's transactions">
        <div style="font-size:20px;margin-bottom:6px;">${c.icon}</div>
        <div style="font-size:11px;color:#6b7280;">${c.label} →</div>
        <div style="font-size:22px;font-weight:900;color:${c.color};margin:4px 0;">${c.val}</div>
        <div style="font-size:10px;color:#9ca3af;">${escHTML(c.note)}</div>
      </div>`).join('')}
    </div>

    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:16px;margin-bottom:14px;">
      <div style="font-size:13px;font-weight:800;color:#0f3d26;margin-bottom:12px;">📊 Cost Structure</div>
      ${[
        {label:'Sales Revenue',    val:sales,    color:'#16a34a'},
        {label:'Cost of Goods',    val:cogs,     color:'#ef4444'},
        {label:'Fixed Expenses',   val:fixedExp, color:'#f59e0b'},
        {label:'Variable Expenses',val:varExp,   color:'#f97316'},
        {label:'Gross Margin',     val:sales>0?grossMargin*100:0, isPercent:true, color:'#3b82f6'},
        {label:'Contribution Margin',val:sales>0?contribMargin*100:0, isPercent:true, color:'#8b5cf6'},
      ].map(r=>`<div data-x-click="openPLDrill('${thisMonth}-01','${thisMonth}-31')" style="cursor:pointer;display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid #f3f4f6;" title="Click to see this month's transactions">
        <span style="font-size:12px;color:#374151;">${r.label} →</span>
        <span style="font-size:12px;font-weight:700;color:${r.color};">${r.isPercent?r.val.toFixed(1)+'%':f(r.val)}</span>
      </div>`).join('')}
    </div>

    <div style="background:${sales>=breakEvenSales?'#f0fdf4':'#fef2f2'};border:2px solid ${sales>=breakEvenSales?'#16a34a':'#dc2626'};border-radius:10px;padding:16px;text-align:center;">
      <div style="font-size:16px;font-weight:900;color:${sales>=breakEvenSales?'#16a34a':'#dc2626'};">
        ${sales>=breakEvenSales?'✅ ABOVE BREAK-EVEN — You are profitable this month!':'❌ BELOW BREAK-EVEN — Need ৳'+Math.abs(breakEvenSales-sales).toLocaleString('en-IN')+' more in sales to break even'}
      </div>
    </div>
  `;
}

// ── 4. DEPRECIATION CALCULATOR ──────────────────────────────
function renderDepreciation(){
  const el = document.getElementById('pg-depreciation') || (() => {
    const d = document.createElement('div');
    d.id = 'pg-depreciation'; d.className = 'page'; d.style.display = 'none';
    (document.querySelector('.main')||document.body).appendChild(d);
    return d;
  })();

  const assets = DB.assets||[];
  const f = v => '৳'+Math.abs(v||0).toLocaleString('en-IN');
  const currentYear = new Date().getFullYear();

  el.innerHTML = `
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:18px;">
      <div>
        <h2 style="font-size:20px;font-weight:900;color:#0f3d26;margin:0;">📉 Depreciation Calculator</h2>
        <p style="font-size:12px;color:#6b7280;margin:2px 0 0;">Straight-line depreciation for all fixed assets</p>
      </div>
    </div>

    ${assets.length===0?'<div style="text-align:center;padding:40px;color:#6b7280;">No fixed assets found. Add assets in the Assets page first.</div>':
    `<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;margin-bottom:14px;">
      <table style="width:100%;border-collapse:collapse;">
        <thead>
          <tr style="background:#0f3d26;color:#fff;">
            <th style="padding:12px 16px;text-align:left;font-size:12px;">Asset</th>
            <th style="padding:12px 16px;text-align:right;font-size:12px;">Cost</th>
            <th style="padding:12px 16px;text-align:right;font-size:12px;">Life (yrs)</th>
            <th style="padding:12px 16px;text-align:right;font-size:12px;">Annual Dep.</th>
            <th style="padding:12px 16px;text-align:right;font-size:12px;">Monthly Dep.</th>
            <th style="padding:12px 16px;text-align:right;font-size:12px;">Book Value</th>
          </tr>
        </thead>
        <tbody>
          ${assets.map((a,i)=>{
            const cost = a.val||a.cost||0;
            const life = a.life||5;
            const annualDep = cost/life;
            const monthlyDep = annualDep/12;
            const age = a.purchaseYear?currentYear-parseInt(a.purchaseYear):0;
            const bookVal = Math.max(0, cost - annualDep*age);
            return `<tr data-x-click="nav('assets')" style="cursor:pointer;border-bottom:1px solid #f3f4f6;background:${i%2?'#f9fafb':'#fff'};" title="Click to open Fixed Assets">
              <td style="padding:10px 16px;font-size:12px;font-weight:700;">${escHTML(a.name||'Asset '+(i+1))} →</td>
              <td style="padding:10px 16px;text-align:right;font-size:12px;">${f(cost)}</td>
              <td style="padding:10px 16px;text-align:right;font-size:12px;">${life}</td>
              <td style="padding:10px 16px;text-align:right;font-size:12px;color:#f59e0b;">${f(annualDep)}</td>
              <td style="padding:10px 16px;text-align:right;font-size:12px;color:#f97316;">${f(monthlyDep)}</td>
              <td style="padding:10px 16px;text-align:right;font-size:12px;font-weight:700;color:${bookVal>cost*0.2?'#16a34a':'#dc2626'};">${f(bookVal)}</td>
            </tr>`;
          }).join('')}
          <tr style="background:#f0fdf4;font-weight:900;">
            <td style="padding:12px 16px;font-size:13px;">TOTAL</td>
            <td style="padding:12px 16px;text-align:right;font-size:13px;">${f(assets.reduce((s,a)=>s+(a.val||a.cost||0),0))}</td>
            <td colspan="2" style="padding:12px 16px;text-align:right;font-size:13px;">Annual: ${f(assets.reduce((s,a)=>s+(a.val||a.cost||0)/(a.life||5),0))}</td>
            <td style="padding:12px 16px;text-align:right;font-size:13px;">Monthly: ${f(assets.reduce((s,a)=>s+(a.val||a.cost||0)/(a.life||5)/12,0))}</td>
            <td style="padding:12px 16px;text-align:right;font-size:13px;">${f(assets.reduce((s,a)=>{const cost=a.val||a.cost||0;const life=a.life||5;const age=a.purchaseYear?currentYear-parseInt(a.purchaseYear):0;return s+Math.max(0,cost-cost/life*age);},0))}</td>
          </tr>
        </tbody>
      </table>
    </div>
    <div style="background:#fffbeb;border:1px solid #fde68a;border-radius:8px;padding:12px;font-size:11px;color:#92400e;">
      💡 Depreciation method: Straight-Line (SLM). Set asset life years in the Assets page. Default life = 5 years.
    </div>`}
  `;
}

// ── 5. CUSTOMER CREDIT LIMIT CHECK ─────────────────────────
function checkCreditLimit(customerName, newAmount){
  const cust = (DB.customers||[]).find(c=>c.name===customerName);
  if(!cust) return {ok:true, msg:''};
  const limit = cust.creditLimit||0;
  const current = cust.bal||0;
  if(limit<=0) return {ok:true, msg:'No credit limit set'};
  const projected = current + (newAmount||0);
  if(projected > limit){
    return {ok:false, msg:`⚠️ Credit limit exceeded! Limit: ৳${limit.toLocaleString('en-IN')} | Current: ৳${current.toLocaleString('en-IN')} | After this sale: ৳${projected.toLocaleString('en-IN')}`};
  }
  const pct = Math.round(projected/limit*100);
  return {ok:true, msg:`Credit used: ${pct}% of ৳${limit.toLocaleString('en-IN')} limit`};
}

function renderCreditLimitCheck(){
  const el = document.getElementById('pg-creditcheck') || (() => {
    const d = document.createElement('div');
    d.id = 'pg-creditcheck'; d.className = 'page'; d.style.display = 'none';
    (document.querySelector('.main')||document.body).appendChild(d);
    return d;
  })();

  const customers = (DB.customers||[]).filter(c=>isCustomerParty(c));
  const f = v => '৳'+Math.abs(v||0).toLocaleString('en-IN');

  const withLimit = customers.filter(c=>(c.creditLimit||0)>0);
  const overLimit = withLimit.filter(c=>(c.bal||0)>(c.creditLimit||0));
  const nearLimit = withLimit.filter(c=>{const pct=(c.bal||0)/(c.creditLimit||1)*100;return pct>=80&&pct<=100;});

  el.innerHTML = `
    <div style="margin-bottom:18px;">
      <h2 style="font-size:20px;font-weight:900;color:#0f3d26;margin:0;">💳 Customer Credit Limit</h2>
