    <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:18px;">
      <div style="background:#eff6ff;border-radius:10px;padding:14px;text-align:center;">
        <div style="font-size:24px;font-weight:900;color:#3b82f6;">${withLimit.length}</div>
        <div style="font-size:11px;color:#6b7280;">With Credit Limit</div>
      </div>
      <div style="background:#fef2f2;border-radius:10px;padding:14px;text-align:center;">
        <div style="font-size:24px;font-weight:900;color:#dc2626;">${overLimit.length}</div>
        <div style="font-size:11px;color:#6b7280;">Over Limit 🚨</div>
      </div>
      <div style="background:#fffbeb;border-radius:10px;padding:14px;text-align:center;">
        <div style="font-size:24px;font-weight:900;color:#d97706;">${nearLimit.length}</div>
        <div style="font-size:11px;color:#6b7280;">Near Limit (≥80%) ⚠️</div>
      </div>
    </div>

    <div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">
      <table style="width:100%;border-collapse:collapse;">
        <thead>
          <tr style="background:#0f3d26;color:#fff;">
            <th style="padding:12px 16px;text-align:left;font-size:12px;">Customer</th>
            <th style="padding:12px 16px;text-align:right;font-size:12px;">Credit Limit</th>
            <th style="padding:12px 16px;text-align:right;font-size:12px;">Balance Due</th>
            <th style="padding:12px 16px;text-align:right;font-size:12px;">Available</th>
            <th style="padding:12px 16px;text-align:center;font-size:12px;">Usage</th>
            <th style="padding:12px 16px;text-align:center;font-size:12px;">Status</th>
          </tr>
        </thead>
        <tbody>
          ${customers.sort((a,b)=>(b.bal||0)/(b.creditLimit||1)-(a.bal||0)/(a.creditLimit||1)).slice(0,30).map((c,i)=>{
            const limit = c.creditLimit||0;
            const bal = c.bal||0;
            const avail = Math.max(0, limit-bal);
            const pct = limit>0?Math.min(150,Math.round(bal/limit*100)):0;
            const status = limit<=0?'No Limit':bal>limit?'🚨 Over':pct>=80?'⚠️ Near':'✅ OK';
            const statusColor = limit<=0?'#6b7280':bal>limit?'#dc2626':pct>=80?'#d97706':'#16a34a';
            return `<tr style="border-bottom:1px solid #f3f4f6;background:${bal>limit?'#fef2f2':i%2?'#f9fafb':'#fff'};">
              <td style="padding:10px 16px;font-size:12px;font-weight:700;">${escHTML(c.name)}</td>
              <td style="padding:10px 16px;text-align:right;font-size:12px;">${limit>0?f(limit):'—'}</td>
              <td style="padding:10px 16px;text-align:right;font-size:12px;color:#dc2626;">${f(bal)}</td>
              <td style="padding:10px 16px;text-align:right;font-size:12px;color:#16a34a;">${limit>0?f(avail):'—'}</td>
              <td style="padding:10px 16px;">
                ${limit>0?`<div style="background:#f3f4f6;border-radius:4px;height:8px;overflow:hidden;">
                  <div style="height:100%;width:${Math.min(100,pct)}%;background:${bal>limit?'#ef4444':pct>=80?'#f59e0b':'#16a34a'};border-radius:4px;"></div>
                </div>
                <div style="font-size:10px;text-align:center;color:#6b7280;margin-top:2px;">${pct}%</div>`:'—'}
              </td>
              <td style="padding:10px 16px;text-align:center;font-size:11px;font-weight:700;color:${statusColor};">${status}</td>
            </tr>`;
          }).join('')}
        </tbody>
      </table>
    </div>
  `;
}

// ── 6. RECURRING TRANSACTIONS ───────────────────────────────
function initRecurringTransactions(){
  const recurring = DB.recurring||[];
  if(!recurring.length) return;
  const today = new Date().toISOString().split('T')[0];
  let added = 0;
  recurring.forEach(r=>{
    if(!r.active||!r.nextDate) return;
    /* FIX (2026-08-24): this was a single `if`, so only ONE occurrence
       ever got added per page load no matter how many periods had
       actually elapsed — e.g. a daily entry that fell 5 days behind
       while the app was closed only caught up 1 day at a time, once per
       reload, silently losing the rest unless the page happened to be
       reloaded 5 separate times. Looping here catches up everything that
       is actually due in one pass, each dated on the day it was really
       scheduled for (not lumped onto "today"). Capped at 366 iterations
       so a bad/unrecognised frequency can never spin forever. */
    let guard = 0;
    while(r.nextDate <= today && guard++ < 366){
      const dueDate = r.nextDate;
      const newTx = {
        id: newId(),
        date: dueDate,
        type: r.type,
        party: r.party,
        amt: r.amt,
        note: (r.note||'')+'[Auto-Recurring]',
        bank: r.bank,
      };
      DB.tx = DB.tx||[];
      DB.tx.push(newTx);
      // Update next date
      const next = new Date(r.nextDate);
      if(r.frequency==='monthly') next.setMonth(next.getMonth()+1);
      else if(r.frequency==='weekly') next.setDate(next.getDate()+7);
      else if(r.frequency==='daily') next.setDate(next.getDate()+1);
      else break; // unrecognised frequency: don't loop forever on a date that never advances
      r.nextDate = next.toISOString().split('T')[0];
      added++;
    }
  });
  if(added>0){
    saveDB();
    if(typeof toast==='function') toast('🔄 '+added+' recurring transaction(s) auto-added','s');
  }
}

