<script nonce="<?php echo $cspNonceAttr; ?>">
(function(){
  'use strict';

  // ── 1. Structural fix: many .page containers were appended to .main
  //      (outside .content), so they rendered *below* the dashboard
  //      instead of inside the page area. Relocate them all.
  function homePages(){
    var content = document.querySelector('.content');
    if(!content) return;
    document.querySelectorAll('.page').forEach(function(p){
      if(!content.contains(p)) content.appendChild(p);
    });
  }
  homePages();

  // Anything created later (nav() auto-creates missing pages) gets homed too.
  if(typeof window.nav === 'function'){
    var _nav = window.nav;
    window.nav = function(page){
      var r = _nav.apply(this, arguments);
      homePages();
      try{ window.scrollTo({top:0,behavior:'instant'}); }catch(e){ window.scrollTo(0,0); }
      return r;
    };
  }

  // ── 2. Bank Accounts: clickable balance cards ──────────────
  function bankBal(b){ return parseFloat(b.bal!=null?b.bal:(b.balance||0))||0; }
  function money(n){
    return '৳'+Number(n||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});
  }

  window.openBankCard = function(name){
    if(!name) return;
    if(typeof nav==='function') nav('bankstmt');
    setTimeout(function(){
      var sel=document.getElementById('bkstmt-account');
      if(sel){
        sel.value=name;
        if(sel.value!==name){ // option not present yet — add it
          var o=document.createElement('option'); o.value=name; o.textContent=name;
          sel.appendChild(o); sel.value=name;
        }
        if(typeof renderBankStatement==='function') renderBankStatement();
      }
    },120);
  };

  // Source of truth: DB.banks when it is reachable, otherwise the rendered
  // Bank Accounts table (the app's data object is not always on window).
  function collectBanks(){
    var banks=(window.DB&&DB.banks)||null;
    if(banks&&banks.length){
      return banks.map(function(b){
        return {name:String(b.name||'Unnamed'),type:String(b.type||'Current'),
          bal:bankBal(b),acc:String(b.accno||b.no||b.accountNo||b.bank||'')};
      });
    }
    var body=document.getElementById('t-bank');
    if(!body) return [];
    return Array.prototype.map.call(body.querySelectorAll('tr'),function(tr){
      var td=tr.querySelectorAll('td');
      if(td.length<6) return null;
      var nameCell=td[1].querySelector('strong');
      var raw=(td[4].textContent||'').replace(/[^0-9.\-]/g,'');
      return {
        name:(nameCell?nameCell.textContent:td[1].textContent||'').trim(),
        type:(td[3].textContent||'Current').trim(),
        bal:parseFloat(raw)||0,
        acc:(td[5].textContent||'').trim()
      };
    }).filter(function(b){ return b&&b.name; });
  }

  window.renderBankCards = function(){
    var grid=document.getElementById('bank-card-grid');
    if(!grid) return;
    var banks=collectBanks();
    var total=banks.reduce(function(s,b){return s+b.bal;},0);
    var tot=document.getElementById('bank-cards-total');
    if(tot) tot.textContent=money(total);
    if(!banks.length){
      grid.innerHTML='<div style="grid-column:1/-1;padding:22px;text-align:center;color:#6b7280;font-size:13px;'+
        'border:1px dashed #cbd5e1;border-radius:12px;">No bank accounts yet. Click “Add Account” to create one.</div>';
      return;
    }
    grid.innerHTML=banks.map(function(b){
      var bal=b.bal;
      var cls=bal>0?'pos':bal<0?'neg':'zero';
      var accent=bal<0?'#dc2626':bal>0?'#16a34a':'#94a3b8';
      var safe=escHTML(b.name);
      var arg=escJSAttr(b.name);
      return '<button type="button" class="bank-bal-card" style="border-left-color:'+accent+';"'+
        ' data-x-click="openBankCard(\''+arg+'\')" title="Open statement for '+safe+'">'+
        '<div class="bbc-top"><div class="bbc-name">'+safe+'</div>'+
        '<div class="bbc-type">'+escHTML(b.type)+'</div></div>'+
        '<div class="bbc-bal '+cls+'">'+money(bal)+'</div>'+
        '<div class="bbc-meta"><span>'+escHTML(b.acc||'—')+'</span>'+
        '<span class="bbc-go">Statement →</span></div></button>';
    }).join('');
  };


  if(typeof window.renderBank==='function'){
    var _rb=window.renderBank;
    window.renderBank=function(){ var r=_rb.apply(this,arguments); try{ renderBankCards(); }catch(e){ console.error(e); } return r; };
  }

  // Data can also arrive from storage/sync without renderBank being wrappable
  // (its declaration may not be reachable from here). Keep the cards in sync
  // with a cheap signature check while the Banks page is visible.
  var _sig='';
  setInterval(function(){
    var pg=document.getElementById('pg-banks');
    if(!pg||!pg.classList.contains('active')) return;
    var banks=collectBanks();
    var sig=banks.length+'|'+banks.map(function(b){return b.name+':'+b.bal;}).join(',');
    if(sig===_sig) return;
    _sig=sig;
    try{ renderBankCards(); }catch(e){ console.error(e); }
  }, 2000);


  // ── 3. Order Management: never crash on rows with a missing date ──
  if(typeof window.renderOrderManagement==='function'){
    var _rom=window.renderOrderManagement;
    window.renderOrderManagement=function(){
      if(window.DB){
        if(!Array.isArray(DB.orders)) DB.orders=[];
        DB.orders.forEach(function(o){
          if(!o.orderDate) o.orderDate=o.date||o.createdAt||'';
          if(!o.deliveryStatus) o.deliveryStatus='Pending';
        });
      }
      return _rom.apply(this,arguments);
    };
  }

  // ── 4. Refresh cards whenever bank data is saved/deleted ──
  ['saveBank','delBank','editBank'].forEach(function(fn){
    if(typeof window[fn]==='function'){
      var orig=window[fn];
      window[fn]=function(){ var r=orig.apply(this,arguments); setTimeout(function(){ try{ renderBankCards(); }catch(e){} },80); return r; };
    }
  });

})();
</script>
<script nonce="<?php echo $cspNonceAttr; ?>">
/* ═══════════════════════════════════════════════════════════════
   WAREHOUSE COSTING & PROFIT MODULE
   - Warehouse Purchase → averaged (weighted, all-time) cost pool
   - Pool is sold under one fixed brand name
   - Per-bag costs (bag = 150 KG): QC (by location), Unload (by customer),
     House cost (by location), Extra cost (by location), Agent commission
   - Sale price nets out VAT (% of net sales amount)
   - Costs accrue monthly and are settled end of month via a payable ledger
   ═══════════════════════════════════════════════════════════════ */
(function(){
  const WH_PURCH_TYPES = ['Warehouse Purchase','Opening Warehouse Purchase','Werhouse Purchase','Opening Werhouse Purchase'];
  const WH_SALE_TYPES  = ['Warehouse Sale','Sale','Customer Sale'];

  function money(n){ try{ return f(n||0); }catch(e){ return (Number(n)||0).toFixed(2); } }
  /* FIX: money() prefixes ৳, so weights and bag counts on this screen were
     printed as "৳100.00 KG" and "৳0.67 bags". Quantities use qtyf(). */
  function qtyf(n){ return (Number(n)||0).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2}); }
  function esc(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
  /* FIX (audit, 2026-09-02): jq() only neutralized \ and ' for the JS-string
     context, but every call site below drops its result straight into a
     double-quoted data-x-click="..." attribute with no esc() wrap — a location/
     customer/payee name containing a literal " broke out of the attribute.
     jq() now HTML-escapes its own output too (same outer-then-inner order
     as window.escJSAttr), so every existing call site is covered without
     having to touch each one individually. */
  function jq(s){ return esc(String(s==null?'':s).replace(/\\/g,'\\\\').replace(/'/g,"\\'")); }

  function cfg(){
    DB.whCost = DB.whCost || {};
    const c = DB.whCost;
    if(c.bagKg == null)          c.bagKg = 150;
    /* FIX: the default brand was a name no product actually has — the
       product list says "Parboiled Rice Bran High Fat" while this said
       "Par Boil Rice Brand High Fat". Nothing ever matched it, so this
       screen reported ৳0.00 sales and ৳0.00 profit no matter how much was
       sold. It now snaps to the real product of that name. */
    if(c.brand == null){
      var _pl=(DB.products||DB.inventory||[]);
      var _hit=_pl.filter(function(p){
        return /par\s*boil/i.test(p.name) && /high\s*fat/i.test(p.name);
      })[0];
      c.brand = _hit ? _hit.name : 'Parboiled Rice Bran High Fat';
    } else {
      var _pl2=(DB.products||DB.inventory||[]);
      var _exact=_pl2.filter(function(p){return String(p.name).toLowerCase().trim()===String(c.brand).toLowerCase().trim();})[0];
      if(!_exact){
        var _near=_pl2.filter(function(p){ return /par\s*boil/i.test(p.name) && /high\s*fat/i.test(p.name); })[0];
        if(_near) c.brand=_near.name;
      }
    }
    if(c.vatPct == null)         c.vatPct = 5;
    if(c.agentCommPerBag == null)c.agentCommPerBag = 0;
    c.locRates  = c.locRates  || {};   // { location: {qc, house, extra} }
    c.custRates = c.custRates || {};   // { customer: {unload} }
    c.settled   = c.settled   || {};   // { "YYYY-MM|kind|payee": {date, txId} }
    return c;
  }
  window.whCfg = cfg;

  function locRate(loc){ const r = cfg().locRates[loc||''] || {}; return {qc:+r.qc||0, house:+r.house||0, extra:+r.extra||0}; }
  function custRate(cust){ const r = cfg().custRates[cust||''] || {}; return {unload:+r.unload||0}; }
  function txKg(t){ return +(t.wt||t.grosswt||t.qty||0) || 0; }
  function txBags(t){ const c=cfg(); const b=+(t.bagqty||0); if(b>0) return b; const kg=txKg(t); return c.bagKg>0 ? kg/c.bagKg : 0; }

  /* ── Averaged warehouse purchase pool ── */
  function whPool(){
    const rows = {}; let kg=0, val=0, bags=0;
    (DB.tx||[]).forEach(t=>{
      if(!WH_PURCH_TYPES.includes(t.type)) return;
      const q = txKg(t), a = +txAmt(t);
      if(q<=0) return;
      const name = t.prod || '(unnamed)';
      rows[name] = rows[name] || {qty:0, val:0, bags:0, count:0};
      rows[name].qty += q; rows[name].val += a; rows[name].bags += txBags(t); rows[name].count++;
      kg += q; val += a; bags += txBags(t);
    });
    /* FIX: the pool's bag count was derived as kg ÷ the default bag weight
       (150), so two 50 kg bags were reported as 0.67 bags. The bag counts
       entered on the purchases themselves are summed instead. */
    return { kg, val, bags, avg: kg>0 ? val/kg : 0, rows };
  }
  window.whPool = whPool;
  window.whAvgCost = function(){ return whPool().avg; };

  /* ── Per-sale costing / P&L ── */
  function saleCosting(t){
    const c = cfg(), avg = whPool().avg;
    const kg = txKg(t), bags = txBags(t);
    const gross = +txAmt(t);
    const vat = gross * (+c.vatPct||0) / 100;
    const net = gross - vat;
    const lr = locRate(t.loc), cr = custRate(t.party);
    const qc = lr.qc*bags, house = lr.house*bags, extra = lr.extra*bags;
    const unload = cr.unload*bags;
    const agentAcost = +(t.agentAcost||0), agentBcost = +(t.agentBcost||0);
    // Use the actual recorded commission from the transaction (per-agent) when present;
    // only fall back to the flat Warehouse Costing rate for older transactions that have neither.
    const hasTxAgentCost = agentAcost>0 || agentBcost>0;
    const agentComm = hasTxAgentCost ? (agentAcost+agentBcost) : (+c.agentCommPerBag||0)*bags;
    const cogs = avg*kg;
    const costs = qc+house+extra+unload+agentComm;
    return {kg, bags, gross, vat, net, avg, cogs, qc, house, extra, unload, agentAcost, agentBcost, hasTxAgentCost, agentComm, costs,
            profit: net - cogs - costs};
  }
  window.whSaleCosting = saleCosting;

  function brandSales(){
    const brand = (cfg().brand||'').toLowerCase();
    return (DB.tx||[]).filter(t=>WH_SALE_TYPES.includes(t.type) &&
      (!brand || String(t.prod||'').toLowerCase() === brand));
  }
  window.whBrandSales = brandSales;

  /* ── Monthly payable accruals ── */
  function accruals(){
    const map = {}; // month -> kind -> payee -> {bags, amt}
    brandSales().forEach(t=>{
      const m = String(t.date||'').slice(0,7); if(!m) return;
      const k = saleCosting(t);
      const add=(kind,payee,amt)=>{
        if(!(amt>0)) return;
        map[m]=map[m]||{}; map[m][kind]=map[m][kind]||{};
        const cell = map[m][kind][payee||'—'] = map[m][kind][payee||'—'] || {bags:0, amt:0};
        cell.bags += k.bags; cell.amt += amt;
      };
      add('QC Cost', t.loc, k.qc);
      add('House Cost', t.loc, k.house);
      add('Extra Cost', t.loc, k.extra);
      add('Unload Cost', t.party, k.unload);
      if(k.hasTxAgentCost){
        if(t.agentA) add('Agent Commission', t.agentA, k.agentAcost);
        if(t.agentB) add('Agent Commission', t.agentB, k.agentBcost);
        if(!t.agentA && !t.agentB) add('Agent Commission', 'Agent', k.agentComm);
      } else {
        add('Agent Commission', t.agentA || t.agentB || 'Agent', k.agentComm);
      }
    });
    return map;
  }
  window.whAccruals = accruals;

  const KIND_TX_TYPE = {'QC Cost':'Extra Cost','House Cost':'Office Expense','Extra Cost':'Extra Cost',
                        'Unload Cost':'Unload Cost','Agent Commission':'Expense'};

  window.whSettle = function(month, kind, payee, amt){
    const c = cfg(), key = month+'|'+kind+'|'+payee;
    if(c.settled[key]){ toast('Already settled','e'); return; }
    const lastDay = new Date(new Date(month+'-01T00:00:00').getFullYear(), new Date(month+'-01T00:00:00').getMonth()+1, 0)
                      .toISOString().slice(0,10);
    const type = KIND_TX_TYPE[kind] || 'Expense';
    DB.nid = DB.nid || {tx:1};
    const _isTop=(typeof window.isTopApprover==='function'&&window.isTopApprover());
    const tx = { id: nextTxId(), date: lastDay, type,
      inv: (typeof nextInvNo==='function' ? nextInvNo(type) : ''),
      party: payee, ptype: (kind==='Unload Cost'?'Customer':'Other'),
      prod: kind+' — '+cfg().brand, loc: (kind==='Unload Cost'?'':payee),
      amount: amt, amt: amt, paid: amt, due: 0,
      rem: 'Month-end settlement of '+kind+' ('+month+')',
      cat: (typeof autoCategory==='function' ? autoCategory(type) : 'expense'),
      /* MAKER-CHECKER (2026-08-29): settlements raised by an Admin used to
         approve themselves and hit the bank in the same click. */
      approvalStatus:'Pending',
      approvedBy:'',
      approvedAt:'',
      enteredBy:currentUser?.name||'', enteredRole:currentUser?.role||'',
      makerUserId:(currentUser?.id!=null?String(currentUser.id):''),
      makerUsername:currentUser?.username||'',
      makerAt:new Date().toISOString() };
    if(typeof genCode==='function') tx.code = genCode('TXN');
    (DB.tx = DB.tx||[]).push(tx); DB.transactions = DB.tx;
    /* No immediate balance posting: the settlement is Pending until it is
       approved, and approveTx() does the posting. Leaving applyTxBalance()
       here would move the bank for an entry still marked Pending, which is
       the double-count the approval gate exists to prevent. */
    c.settled[key] = {date: lastDay, txId: tx.id, amt};
    saveDB(); toast(kind+' settled for '+month+' \u2014 pending approval','s'); renderWhCosting();
  };

  window.whUnsettle = function(month, kind, payee){
    const c = cfg(), key = month+'|'+kind+'|'+payee, rec = c.settled[key];
    if(!rec) return;
    const tx = (DB.tx||[]).find(t=>t.id===rec.txId);
    if(tx){ if(typeof applyTxBalance==='function'){ try{ applyTxBalance(tx,-1); }catch(e){} }
            DB.tx = DB.tx.filter(t=>t.id!==rec.txId); DB.transactions = DB.tx; }
    delete c.settled[key]; saveDB(); toast('Settlement reversed','s'); renderWhCosting();
  };

  /* ── Rate config editors ── */
  window.whSaveConfig = function(){
    const c = cfg(), g = id => document.getElementById(id);
    c.brand = (g('wh-brand')?.value||'').trim() || c.brand;
    c.bagKg = parseFloat(g('wh-bagkg')?.value) || c.bagKg;
    c.vatPct = parseFloat(g('wh-vat')?.value); if(isNaN(c.vatPct)) c.vatPct = 0;
    c.agentCommPerBag = parseFloat(g('wh-agentcomm')?.value) || 0;
    saveDB(); toast('Costing settings saved','s'); renderWhCosting();
  };
  window.whSaveLocRate = function(loc){
    const c = cfg(), k = 'wh-lr-'+utf8ToBase64(loc).replace(/=/g,'');
    c.locRates[loc] = {
      qc:    parseFloat(document.getElementById(k+'-qc')?.value)||0,
      house: parseFloat(document.getElementById(k+'-house')?.value)||0,
      extra: parseFloat(document.getElementById(k+'-extra')?.value)||0 };
    saveDB(); toast('Rates saved for '+loc,'s'); renderWhCosting();
  };
  window.whSaveCustRate = function(cust){
    const c = cfg(), k = 'wh-cr-'+utf8ToBase64(cust).replace(/=/g,'');
    c.custRates[cust] = { unload: parseFloat(document.getElementById(k+'-unload')?.value)||0 };
    saveDB(); toast('Unload rate saved for '+cust,'s'); renderWhCosting();
  };

  function locationList(){
    const s = new Set();
    (DB.locations||[]).forEach(l=>l&&l.name&&s.add(l.name));
    (DB.tx||[]).forEach(t=>{ if(t.loc) s.add(t.loc); });
    document.querySelectorAll('#tx-loc option').forEach(o=>{ if(o.value) s.add(o.value); });
    return [...s].sort();
  }
  function customerList(){
    const s = new Set();
    (DB.customers||[]).filter(c=>!c.type||c.type==='Customer'||c.type==='Both').forEach(c=>s.add(c.name));
    brandSales().forEach(t=>{ if(t.party) s.add(t.party); });
    return [...s].sort();
  }

  /* ── Page render ── */
  window.renderWhCosting = function(){
    const el = document.getElementById('pg-whcosting'); if(!el) return;
    const c = cfg(), pool = whPool(), sales = brandSales(), acc = accruals();

    const purchRows = Object.entries(pool.rows).sort((a,b)=>b[1].val-a[1].val).map(([name,r])=>`<tr>
      <td><strong>${esc(name)}</strong></td><td class="td-num">${r.count}</td>
      <td class="td-num">${qtyf(r.qty)}</td><td class="td-num">${qtyf(r.bags)}</td>
      <td class="td-num">${money(r.val)}</td>
      <td class="td-num"><strong>${(r.qty>0?r.val/r.qty:0).toFixed(2)}</strong></td></tr>`).join('');

    let T = {gross:0,vat:0,net:0,cogs:0,costs:0,profit:0,bags:0,kg:0};
    const saleRows = sales.slice().sort((a,b)=>String(b.date).localeCompare(String(a.date))).map(t=>{
      const k = saleCosting(t);
      T.gross+=k.gross; T.vat+=k.vat; T.net+=k.net; T.cogs+=k.cogs; T.costs+=k.costs; T.profit+=k.profit; T.bags+=k.bags; T.kg+=k.kg;
      return `<tr>
        <td class="fs11">${esc(t.date||'')}</td><td class="fs11">${esc(t.inv||'')}</td>
        <td>${esc(t.party||'-')}</td><td class="fs11">${esc(t.loc||'-')}</td>
        <td class="td-num">${money(k.kg)}</td><td class="td-num">${k.bags.toFixed(2)}</td>
        <td class="td-num">${money(k.gross)}</td><td class="td-num" style="color:#dc2626;">${money(k.vat)}</td>
        <td class="td-num">${money(k.net)}</td><td class="td-num">${money(k.cogs)}</td>
        <td class="td-num">${money(k.costs)}</td>
        <td class="td-num" style="font-weight:800;color:${k.profit>=0?'#16a34a':'#dc2626'};">${money(k.profit)}</td></tr>`;
    }).join('');

    const locRows = locationList().map(loc=>{
      const r = locRate(loc), k = 'wh-lr-'+utf8ToBase64(loc).replace(/=/g,'');
      return `<tr><td><strong>${esc(loc)}</strong></td>
        <td><input class="fc" id="${k}-qc" type="number" step="0.01" value="${r.qc||''}" placeholder="0.00" style="max-width:110px;"></td>
        <td><input class="fc" id="${k}-house" type="number" step="0.01" value="${r.house||''}" placeholder="0.00" style="max-width:110px;"></td>
        <td><input class="fc" id="${k}-extra" type="number" step="0.01" value="${r.extra||''}" placeholder="0.00" style="max-width:110px;"></td>
        <td><button class="btn btn-xs btn-success" data-x-click="whSaveLocRate('${jq(loc)}')">Save</button></td></tr>`;
    }).join('');

    const custRows = customerList().map(cu=>{
      const r = custRate(cu), k = 'wh-cr-'+utf8ToBase64(cu).replace(/=/g,'');
      return `<tr><td><strong>${esc(cu)}</strong></td>
        <td><input class="fc" id="${k}-unload" type="number" step="0.01" value="${r.unload||''}" placeholder="0.00" style="max-width:110px;"></td>
        <td><button class="btn btn-xs btn-success" data-x-click="whSaveCustRate('${jq(cu)}')">Save</button></td></tr>`;
    }).join('');

    const months = Object.keys(acc).sort().reverse();
    let ledgerHtml = '';
    months.forEach(m=>{
      let mTot=0, rows='';
      Object.keys(acc[m]).forEach(kind=>{
        Object.entries(acc[m][kind]).forEach(([payee,cell])=>{
          mTot += cell.amt;
          const key = m+'|'+kind+'|'+payee, rec = c.settled[key];
          rows += `<tr>
            <td>${esc(kind)}</td><td>${esc(payee)}</td>
            <td class="td-num">${cell.bags.toFixed(2)}</td>
            <td class="td-num"><strong>${money(cell.amt)}</strong></td>
            <td>${rec?`<span class="badge b-green">Paid ${esc(rec.date)}</span>`:'<span class="badge b-orange">Payable</span>'}</td>
            <td>${rec
              ? `<button class="btn btn-xs btn-danger" data-x-click="whUnsettle('${m}','${jq(kind)}','${jq(payee)}')">Reverse</button>`
              : `<button class="btn btn-xs btn-success" data-x-click="whSettle('${m}','${jq(kind)}','${jq(payee)}',${cell.amt})">Pay (month-end)</button>`}</td></tr>`;
        });
      });
      ledgerHtml += `<div class="card" style="margin-bottom:14px;">
        <h3 style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:10px;">📅 ${m} — Total accrued: ৳${money(mTot)}</h3>
        <table class="tbl"><thead><tr><th>Cost Type</th><th>Payable To</th><th class="td-num">Bags</th>
          <th class="td-num">Amount (৳)</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows}</tbody></table></div>`;
    });
    if(!ledgerHtml) ledgerHtml = '<div class="card" style="text-align:center;padding:24px;color:#9ca3af;">No per-bag costs accrued yet — set rates and record brand sales.</div>';

    el.innerHTML = `
    <div class="kpi-grid" style="margin-bottom:16px;">
      <div class="kpi-card c-teal"><div class="kpi-icon">📦</div><div class="kpi-val">${qtyf(pool.kg)}</div><div class="kpi-label">Warehouse Purchased (KG)</div></div>
      <div class="kpi-card c-orange"><div class="kpi-icon">⚖️</div><div class="kpi-val">${pool.avg.toFixed(2)}</div><div class="kpi-label">Weighted Avg Cost ৳/KG</div></div>
      <div class="kpi-card c-green"><div class="kpi-icon">💰</div><div class="kpi-val">${money(T.net)}</div><div class="kpi-label">Net Sales after VAT (${c.vatPct}%)</div></div>
      <div class="kpi-card ${T.profit>=0?'c-green':'c-red'}"><div class="kpi-icon">📈</div><div class="kpi-val">${money(T.profit)}</div><div class="kpi-label">Profit / Loss</div></div>
    </div>

    <div class="card" style="margin-bottom:16px;">
      <h3 style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:12px;">⚙️ Costing Settings</h3>
      <div class="form-grid">
        <div class="fg span2"><label class="lbl">Sale Brand Name (averaged pool is sold as)</label>
          <select class="fc" id="wh-brand">${(DB.products||DB.inventory||[]).map(p=>`<option value="${esc(p.name)}"${String(p.name)===String(c.brand)?' selected':''}>${esc(p.name)}</option>`).join('')}</select>
          <div style="font-size:10.5px;color:#9ca3af;margin-top:4px;">Everything bought as a Warehouse Purchase is pooled and sold under this product. Free text used to allow a name no product had, which is why this screen showed nothing.</div></div>
        <div class="fg"><label class="lbl">Bag Weight (KG)</label>
          <input class="fc" id="wh-bagkg" type="number" step="0.01" value="${c.bagKg}"></div>
        <div class="fg"><label class="lbl">VAT % (deducted from net sales)</label>
          <input class="fc" id="wh-vat" type="number" step="0.001" value="${c.vatPct}"></div>
        <div class="fg"><label class="lbl">Agent Commission ৳ / Bag (sales only)</label>
          <input class="fc" id="wh-agentcomm" type="number" step="0.01" value="${c.agentCommPerBag}"></div>
      </div>
      <button class="btn btn-success" style="margin-top:10px;" data-x-click="whSaveConfig()">💾 Save Settings</button>
    </div>

    <div class="card" style="margin-bottom:16px;">
      <h3 style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:12px;">🏭 Warehouse Purchase Summary → Averaged Pool</h3>
      <table class="tbl"><thead><tr><th>Purchased Product</th><th class="td-num">Entries</th><th class="td-num">Qty (KG)</th>
        <th class="td-num">Bags</th><th class="td-num">Value (৳)</th><th class="td-num">Avg ৳/KG</th></tr></thead>
      <tbody>${purchRows||'<tr><td colspan="6" style="text-align:center;color:#9ca3af;padding:16px;">No warehouse purchases yet.</td></tr>'}</tbody>
      <tfoot><tr style="background:#f0fdf4;font-weight:800;"><td>Pool total → <em>${esc(c.brand)}</em></td><td class="td-num">${sales.length?'':''}</td>
        <td class="td-num">${qtyf(pool.kg)}</td><td class="td-num">${qtyf(pool.bags)}</td>
        <td class="td-num">${money(pool.val)}</td><td class="td-num">${pool.avg.toFixed(2)}</td></tr></tfoot></table>
    </div>

    <div class="card" style="margin-bottom:16px;">
      <h3 style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:12px;">🧾 Per-Bag Rates by Location (QC · House · Extra)</h3>
      <table class="tbl"><thead><tr><th>Location</th><th>QC ৳/Bag</th><th>House ৳/Bag</th><th>Extra ৳/Bag</th><th></th></tr></thead>
      <tbody>${locRows||'<tr><td colspan="5" style="text-align:center;color:#9ca3af;padding:16px;">No locations found.</td></tr>'}</tbody></table>
    </div>

    <div class="card" style="margin-bottom:16px;">
      <h3 style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:12px;">🚚 Unload Rate by Customer</h3>
      <table class="tbl"><thead><tr><th>Customer</th><th>Unload ৳/Bag</th><th></th></tr></thead>
      <tbody>${custRows||'<tr><td colspan="3" style="text-align:center;color:#9ca3af;padding:16px;">No customers found.</td></tr>'}</tbody></table>
    </div>

    <div class="card" style="margin-bottom:16px;">
      <h3 style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:12px;">📊 Sale-wise Profit &amp; Loss — ${esc(c.brand)}</h3>
      <div style="overflow-x:auto;"><table class="tbl"><thead><tr><th>Date</th><th>Invoice</th><th>Customer</th><th>Location</th>
        <th class="td-num">KG</th><th class="td-num">Bags</th><th class="td-num">Gross</th><th class="td-num">VAT</th>
        <th class="td-num">Net</th><th class="td-num">Avg Cost</th><th class="td-num">Per-Bag Costs</th><th class="td-num">Profit/Loss</th></tr></thead>
      <tbody>${saleRows||'<tr><td colspan="12" style="text-align:center;color:#9ca3af;padding:16px;">No brand sales recorded yet.</td></tr>'}</tbody>
      <tfoot><tr style="background:#f0fdf4;font-weight:800;"><td colspan="4" style="text-align:right;">Totals:</td>
        <td class="td-num">${money(T.kg)}</td><td class="td-num">${T.bags.toFixed(2)}</td><td class="td-num">${money(T.gross)}</td>
        <td class="td-num" style="color:#dc2626;">${money(T.vat)}</td><td class="td-num">${money(T.net)}</td>
        <td class="td-num">${money(T.cogs)}</td><td class="td-num">${money(T.costs)}</td>
        <td class="td-num" style="color:${T.profit>=0?'#16a34a':'#dc2626'};">${money(T.profit)}</td></tr></tfoot></table></div>
    </div>

    <h3 style="font-size:15px;font-weight:800;color:#0f3d26;margin:0 0 10px;">📒 Month-End Cost Ledger (QC by location · Unload by customer · House &amp; Extra by location · Agent commission)</h3>
    ${ledgerHtml}`;
  };

  /* ── Wire into navigation ── */
  try{ if(typeof TITLES==='object') TITLES['whcosting'] = '🧮 Warehouse Costing & P&L'; }catch(e){}
  const _rs = window._renderSwitch;
  if(typeof _rs === 'function'){
    window._renderSwitch = function(page){
      if(page === 'whcosting'){ return renderWhCosting(); }
      return _rs.apply(this, arguments);
    };
  }
  document.addEventListener('DOMContentLoaded', function(){
    const anchor = document.querySelector('.nav-item[onclick*="prodcosting"]');
    if(anchor && !document.querySelector('.nav-item[onclick*="whcosting"]')){
      const d = document.createElement('div');
      d.className = 'nav-item';
      d.setAttribute('onclick', "nav('whcosting')");
      d.innerHTML = '<span class="nav-icon">🧮</span><span>Warehouse Costing &amp; P&amp;L</span><span class="nav-tooltip">Averaged warehouse purchase cost, per-bag costs, VAT, month-end cost ledger</span>';
      anchor.parentNode.insertBefore(d, anchor.nextSibling);
    }
  });
})();
</script>
<!-- ══════════════════════════════════════════════════════════════
     v15 MODULE — (A) Business Balance Equation  (B) Unified Access Control
     Appended module: self-contained, no edits to earlier code.
     ══════════════════════════════════════════════════════════════ -->
<script nonce="<?php echo $cspNonceAttr; ?>">
(function(){
  'use strict';
  var _DB = function(){ try{ return (typeof DB!=='undefined'&&DB)?DB:(window.DB||{}); }catch(e){ return window.DB||{}; } };
  var _CU = function(){ try{ return (typeof currentUser!=='undefined'&&currentUser)?currentUser:(window.currentUser||null); }catch(e){ return window.currentUser||null; } };
  var N = function(v){ v = parseFloat(v); return isFinite(v) ? v : 0; };
  var money = function(v){
    var s = (Math.round(Math.abs(N(v))*100)/100).toLocaleString('en-IN',{maximumFractionDigits:2});
    return (N(v)<0?'-':'')+'৳'+s;
  };
  var SALE_T  = ['Sale','Sales','Sales Invoice','Customer Sale','Warehouse Sale','Other Income','Interest Income'];
  var PURCH_T = ['Purchase','Warehouse Purchase','Supplier Purchase'];
  var SALE_RET_T  = ['Sales Return','Sale Return'];
  var PURCH_RET_T = ['Purchase Return','Supplier Refund'];
  // Expenses are now a WHITELIST. Previously every unrecognised transaction type
  // (receipts, payments, returns, opening entries, stock movements) silently
  // became an "expense" and destroyed the balance.
  var EXP_T = (function(){
    try{ if(window.EXPENSE_TX_TYPES) return Array.from(window.EXPENSE_TX_TYPES); }catch(e){}
    return ['Salary Payment','Office Rent','Electricity Bill','Internet Bill','Telephone Bill',
            'Fuel Expense','Transport Cost','Loading Charge','Unloading Charge','Commission Payment',
            'Brokerage Fee','Legal Fee','Audit Fee','Insurance Premium','Tax Payment','Government Fee',
            'License Fee','Maintenance Cost','Repair Expense','Stationery Purchase','Other Expense',
            'Interest Expense','Bank Charge'];
  })();

  function txs(){ return (_DB().tx || _DB().transactions) || []; }
  function amt(t){ return N(t.amt !== undefined ? t.amt : t.amount); }
  function parties(type){ return (_DB().customers||[]).filter(function(c){ return (c.type||'Customer')===type; }); }
  function pbal(c){ return N(c.balance !== undefined ? c.balance : c.bal); }

  // ── A. THE BALANCE EQUATION ────────────────────────────────
  // Owner's rule: I have no capital of my own. Everything the business
  // holds (money in, money out) must net to zero on both sides.
  //
  //   WHAT THE BUSINESS OWES        =        WHAT THE BUSINESS HOLDS
  //   Partner funds                          Customer receivables
  // + Net profit                           + Bank / cash balances
  // + Supplier payables                    + Stock @ average purchase price
  // + Customer advances received           + Advances paid to suppliers
  //                                        + Fixed assets
  function landedExtras(t){
    // QC, unloading, agent and other handling costs belong to the landed cost
    // of the received stock, so they must be part of the inventory value.
    return N(t.qc)+N(t.unload)+N(t.othercost)+N(t.othercost2)+N(t.agentAcost)+N(t.agentBcost)+N(t.truckrent);
  }
  function avgPurchaseRate(name){
    var q=0, v=0;
    txs().forEach(function(t){
      if(PURCH_T.indexOf(t.type)<0) return;
      if((t.prod||t.product||'') !== name) return;
      var qq = N(t.qty);
      if(qq<=0) return;
      q += qq;
      v += (amt(t) || qq*N(t.rate)) + landedExtras(t);
    });
    if(q>0) return v/q;
    var p = (_DB().products||[]).find(function(x){ return x.name===name; }) || {};
    return N(p.avgRate || p.avgCost || p.rate || p.purchaseRate);
  }

  // Pure money / stock movements: they change WHERE value sits, never how much
  // the business owns, so they must never hit the profit calculation.
  var MONEY_MOVE_T = ['Sales Receipt','Sales Advance','Purchase Payment','Purchase Advance',
    'Cash Payment','Cash Receipt','Bank Deposit','Bank Withdrawal','Journal','Transfer',
    'Inter-Account Transfer','Partner Capital','Partner Withdrawal','Stock Adjustment',
    'Opening Balance','Opening Stock','Opening Warehouse Purchase','Warehouse Transfer',
    'Raw Material Issue','Finished Goods Entry','Manufacturing Consumption','Manufacturing Output',
    'Employee Advance','Employee Loan'];

  // Unpaid handling bills (agent commission, QC, unload, other cost) are real
  // liabilities — the sample balance sheet lists them under Source of Fund.
  function accruedDues(){
    var D=_DB(), t=0;
    ((D.agentLedger)||[]).forEach(function(a){ var b=N(a.bal); if(b>0) t+=b; });
    ((D.dues)||[]).forEach(function(d){ t+=N(d.amount!==undefined?d.amount:d.amt); });
    return t;
  }

  function balanceModel(){
    var D = _DB();
    var totalSales = 0, totalExp = 0, unknownRows = [];
    txs().forEach(function(t){
      var a = amt(t), ty = t.type||'';
      if(SALE_T.indexOf(ty)>=0) totalSales += a;
      else if(SALE_RET_T.indexOf(ty)>=0) totalSales -= a;
      else if(PURCH_RET_T.indexOf(ty)>=0) { /* returns handled inside computeCOGS fallback */ }
      else if(EXP_T.indexOf(ty)>=0) totalExp += a;
      else if(a && PURCH_T.indexOf(ty)<0 && MONEY_MOVE_T.indexOf(ty)<0 && ty) unknownRows.push(ty);
    });
    // COGS = cost of goods actually SOLD (not all purchases).
    // Unsold stock is an inventory asset on the "holds" side.
    /* FIX: computeCOGS only costs goods that were SOLD, so stock written off
       as wastage or removed by a stock adjustment left the assets but never
       reduced profit — the two sides of this very screen then disagreed by
       the value written off. The Profit & Loss page already uses the fuller
       figure (every movement out of stock, at cost); this now uses the same
       one, so the two screens can no longer contradict each other. */
    var totalCOGS = 0;
    try{ totalCOGS = (typeof window.ayanPL==='function') ? (window.ayanPL(null,null).cogs||0) : 0; }catch(e){ totalCOGS = 0; }
    if(!totalCOGS) totalCOGS = window.computeCOGS ? window.computeCOGS(txs()) : 0;
    var netProfit = totalSales - totalCOGS - totalExp;

    var partnerFunds = ((D.partners)||[]).reduce(function(s,p){ return s + N(p.cap!==undefined?p.cap:p.capital); },0);
    var receivables  = parties('Customer').reduce(function(s,c){ var b=pbal(c); return s + (b>0?b:0); },0);
    var custCredit   = parties('Customer').reduce(function(s,c){ var b=pbal(c); return s + (b<0?-b:0); },0); // customers in credit = advance held
    var payables     = parties('Supplier').reduce(function(s,c){ var b=pbal(c); return s + (b>0?b:0); },0);
    var suppPrepaid  = parties('Supplier').reduce(function(s,c){ var b=pbal(c); return s + (b<0?-b:0); },0);
    var bank         = ((D.banks)||[]).reduce(function(s,b){ return s + N(b.bal!==undefined?b.bal:b.balance); },0);
    var assets       = ((D.assets)||[]).reduce(function(s,a){ return s + N(a.value!==undefined?a.value:(a.val!==undefined?a.val:a.cost)); },0);

    var stockRows = ((D.products)||[]).map(function(p){
      var qty = N(p.stockQty!==undefined?p.stockQty:p.qty);
      var rate = avgPurchaseRate(p.name);
      return { name:p.name, unit:p.unit||'', qty:qty, rate:rate, value:qty*rate };
    }).filter(function(r){ return r.qty!==0 || r.value!==0; });
    var stockValue = stockRows.reduce(function(s,r){ return s+r.value; },0);

    // custCredit / suppPrepaid already contain the effect of every Sales Advance
    // and Purchase Advance transaction, so the raw advance totals must NOT be
    // added again — that double counting was inflating both sides.
    var dues = accruedDues();
    var owes = [
      { k:'Partner funds (capital in the business)', v:partnerFunds },
      { k:'Net profit (Sales − COGS − Expenses)', v:netProfit },
      { k:'Supplier payables (I owe suppliers)', v:payables },
      { k:'Advances received from customers', v:custCredit },
      { k:'Unpaid bills (agent commission, QC, unload, other)', v:dues },
      { k:'Bank loans / LC outstanding', v:(typeof window.ayanLoansOutstanding==='function'?window.ayanLoansOutstanding():0) }
    ];
    var holds = [
      { k:'Customer receivables (they owe me)', v:receivables },
      { k:'Bank + cash balances', v:bank },
      { k:'Stock value @ average purchase price', v:stockValue },
      { k:'Advances paid to suppliers', v:suppPrepaid },
      { k:'Fixed assets (fixed cost)', v:assets }
    ];
    var left  = owes.reduce(function(s,r){ return s+r.v; },0);
    var right = holds.reduce(function(s,r){ return s+r.v; },0);

    return {
      owes:owes, holds:holds, left:left, right:right, diff:right-left,
      unknownTypes:Array.from(new Set(unknownRows)),
      totalSales:totalSales, totalPurch:totalPurch, totalExp:totalExp,
      netProfit:netProfit, stockRows:stockRows, stockValue:stockValue
    };
  }
  window.balanceModel = balanceModel;

  function sideTable(title, rows, total, color){
    return '<div style="background:#fff;border:1px solid #e5e7eb;border-radius:12px;overflow:hidden;">'
      + '<div style="padding:12px 16px;background:'+color+';color:#fff;font-weight:800;font-size:13px;">'+title+'</div>'
      + '<table style="width:100%;border-collapse:collapse;font-size:12.5px;">'
      + rows.map(function(r){
          return '<tr><td style="padding:10px 16px;border-bottom:1px solid #f3f4f6;color:#374151;">'+r.k+'</td>'
               + '<td style="padding:10px 16px;border-bottom:1px solid #f3f4f6;text-align:right;font-weight:700;color:'
               + (r.v<0?'#dc2626':'#111827')+';white-space:nowrap;">'+money(r.v)+'</td></tr>';
        }).join('')
      + '<tr><td style="padding:12px 16px;font-weight:800;background:#f9fafb;">TOTAL</td>'
      + '<td style="padding:12px 16px;text-align:right;font-weight:900;background:#f9fafb;color:'+color+';white-space:nowrap;">'+money(total)+'</td></tr>'
      + '</table></div>';
  }

  window.renderBalanceCheck = function(){
    var el = document.getElementById('pg-balancecheck'); if(!el) return;
    var m = balanceModel();
    var ok = Math.abs(m.diff) < 1;
    var near = !ok && Math.abs(m.diff) < Math.max(1000, Math.abs(m.right)*0.005);
    var bg = ok ? '#16a34a' : (near ? '#d97706' : '#dc2626');
    var head = ok ? '✅ Business balance is fine — both sides match'
             : (near ? '⚠️ Almost balanced — small gap to investigate'
                     : '🚨 Out of balance — the two sides do not match');

    el.innerHTML =
      '<div style="background:linear-gradient(135deg,'+bg+',#111827);color:#fff;border-radius:14px;padding:20px;margin-bottom:16px;">'
      +  '<div style="font-size:17px;font-weight:900;">'+head+'</div>'
      +  '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:10px;margin-top:14px;">'
      +   [['What I owe',m.left],['What I hold',m.right],['Difference',m.diff]].map(function(p){
            return '<div style="background:rgba(255,255,255,.15);border-radius:10px;padding:12px;text-align:center;">'
                 + '<div style="font-size:18px;font-weight:900;">'+money(p[1])+'</div>'
                 + '<div style="font-size:11px;opacity:.85;">'+p[0]+'</div></div>';
          }).join('')
      +  '</div>'
      +  '<div style="margin-top:12px;font-size:11.5px;opacity:.9;">Rule: Partner funds + Net profit + Supplier payables + Customer advances '
      +  '&nbsp;=&nbsp; Receivables + Bank/Cash + Stock @ avg purchase price + Supplier advances + Fixed assets</div>'
      + '</div>'
      + '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:16px;">'
      +   sideTable('🔻 What the business OWES (my side)', m.owes, m.left, '#7c3aed')
      +   sideTable('🔺 What the business HOLDS (their side)', m.holds, m.right, '#0369a1')
      + '</div>'
      + '<div style="background:#fff;border:1px solid #e5e7eb;border-radius:12px;margin-top:16px;overflow:hidden;">'
      +  '<div style="padding:12px 16px;font-weight:800;font-size:13px;background:#f9fafb;border-bottom:1px solid #e5e7eb;">🧮 Net profit working</div>'
      +  '<table style="width:100%;border-collapse:collapse;font-size:12.5px;">'
      +   [['Total sales (selling price)',m.totalSales],['Less: COGS (cost of goods sold)',-m.totalCOGS],
           ['Less: all expenses',-m.totalExp],['= Net profit',m.netProfit]].map(function(r,i){
            var last = i===3;
            return '<tr><td style="padding:10px 16px;border-bottom:1px solid #f3f4f6;'+(last?'font-weight:800;':'')+'">'+r[0]+'</td>'
                 + '<td style="padding:10px 16px;border-bottom:1px solid #f3f4f6;text-align:right;font-weight:'+(last?'900':'700')+';color:'+(r[1]<0?'#dc2626':'#111827')+';">'+money(r[1])+'</td></tr>';
          }).join('')
      +  '</table></div>'
      + '<div style="background:#fff;border:1px solid #e5e7eb;border-radius:12px;margin-top:16px;overflow:hidden;">'
      +  '<div style="padding:12px 16px;font-weight:800;font-size:13px;background:#f9fafb;border-bottom:1px solid #e5e7eb;">📦 Stock valued at average purchase price — '+money(m.stockValue)+'</div>'
      +  '<div style="overflow:auto;max-height:340px;"><table style="width:100%;border-collapse:collapse;font-size:12px;">'
      +   '<tr style="background:#f3f4f6;"><th style="padding:8px 12px;text-align:left;">Product</th><th style="padding:8px 12px;text-align:right;">Qty</th><th style="padding:8px 12px;text-align:right;">Avg purchase rate</th><th style="padding:8px 12px;text-align:right;">Value</th></tr>'
      +   (m.stockRows.length ? m.stockRows.map(function(r){
            return '<tr><td style="padding:8px 12px;border-bottom:1px solid #f3f4f6;">'+r.name+'</td>'
                 + '<td style="padding:8px 12px;border-bottom:1px solid #f3f4f6;text-align:right;">'+r.qty.toLocaleString('en-IN')+' '+r.unit+'</td>'
                 + '<td style="padding:8px 12px;border-bottom:1px solid #f3f4f6;text-align:right;">'+money(r.rate)+'</td>'
                 + '<td style="padding:8px 12px;border-bottom:1px solid #f3f4f6;text-align:right;font-weight:700;">'+money(r.value)+'</td></tr>';
          }).join('') : '<tr><td colspan="4" style="padding:14px;text-align:center;color:#6b7280;">No stock on hand</td></tr>')
      +  '</table></div></div>'
      + (function(){
          var tips=[];
          var unpriced=m.stockRows.filter(function(r){ return r.qty>0 && r.rate<=0; });
          if(unpriced.length) tips.push('📦 '+unpriced.length+' product(s) hold stock but have no average purchase price yet ('+unpriced.map(function(r){return r.name;}).slice(0,4).join(', ')+'). Enter their purchase rate — this alone moves the balance by the full stock value.');
          if(m.unknownTypes && m.unknownTypes.length) tips.push('\u2753 Unclassified transaction type(s) found: '+m.unknownTypes.slice(0,6).join(', ')+'. They are ignored by profit \u2014 tell me how each should behave (income, cost, expense or money movement).');
          if(m.totalSales===0 && m.totalCOGS===0) tips.push('🧾 No purchase/sale transactions recorded yet, so net profit is zero. Until entries exist, the two sides can only match by luck.');
          var untyped=(_DB().customers||[]).filter(function(c){ return !c.type; }).length;
          if(untyped) tips.push('👥 '+untyped+' party(ies) have no type set (Customer / Supplier / Partner) — their balance is counted as a customer receivable.');
          if(Math.abs(m.diff)>=1) tips.push('⚖️ Current gap of '+money(Math.abs(m.diff))+' means '+(m.diff>0?'the business holds more than it owes — usually missing partner capital, unrecorded profit or a missing payable.':'the business owes more than it holds — usually unvalued stock, a missing receivable or an unrecorded bank balance.'));
          if(!tips.length) return '';
          return '<div style="background:#fffbeb;border:1px solid #fde68a;border-radius:12px;margin-top:16px;padding:14px 16px;">'
            + '<div style="font-weight:800;font-size:13px;color:#92400e;margin-bottom:8px;">🔎 Why the two sides differ</div>'
            + tips.map(function(t){ return '<div style="font-size:12.5px;color:#374151;padding:6px 0;border-bottom:1px dashed #fde68a;">'+t+'</div>'; }).join('')
            + '</div>';
        })()
      + '<div style="margin-top:14px;display:flex;gap:8px;flex-wrap:wrap;">'
      +  '<button data-x-click="renderBalanceCheck()" style="padding:9px 16px;border:1px solid #d1d5db;background:#fff;border-radius:8px;font-size:12px;font-weight:700;cursor:pointer;">🔄 Recalculate</button>'
      +  '<button data-x-click="window.print()" style="padding:9px 16px;border:1px solid #d1d5db;background:#fff;border-radius:8px;font-size:12px;font-weight:700;cursor:pointer;">🖨 Print</button>'
      + '</div>';
  };

  // ── B. UNIFIED ACCESS CONTROL (one rule system, all options) ──
  var STAFF_DEFAULT = ['staffdash','purchentry','salesentry','dailypurchase','dailysales',
                       'inventory','products','stockadj','stockalerts','orders','profile'];

  function menuCatalog(){
    var out = [], seen = {};
    document.querySelectorAll('.nav-section').forEach(function(sec){
      var secName = (sec.querySelector('.nav-label')||{}).textContent || sec.getAttribute('data-section') || 'Other';
      var items = [];
      sec.querySelectorAll('.nav-item').forEach(function(it){
        var m = /nav\('([\w-]+)'\)/.exec(it.getAttribute('onclick')||''); if(!m) return;
        var key = m[1];
        var label = (it.querySelector('span:nth-child(2)')||{}).textContent || key;
        var id = key+'::'+label;
        if(seen[id]) return; seen[id] = 1;
        items.push({ key:key, label:label });
      });
      if(items.length) out.push({ section:secName.trim(), items:items });
    });
    return out;
  }
  window.menuCatalog = menuCatalog;

  function allKeys(){
    var k = [];
    menuCatalog().forEach(function(s){ s.items.forEach(function(i){ if(k.indexOf(i.key)<0) k.push(i.key); }); });
    return k;
  }

  function userPages(u){
    // No session/user context yet (e.g. before login state hydrates) — never lock
    // the primary menu down to almost nothing; treat as unrestricted until we
    // actually know otherwise.
    if(!u) return 'all';
    // NOTE: was previously an *exact* match (/^(admin|owner)$/i), so any role
    // string other than the literal words "admin" or "owner" (e.g. "Administrator",
    // "Store Owner", "Admin ") silently fell through to the 2-item default below.
    // Matches the substring style used by the staff/manager checks further down.
    if(u.pages === 'all' || u.permissions === 'all' || /admin|owner/i.test(u.role||'')) return 'all';
    if(Array.isArray(u.pages)) return u.pages;
    // first-time defaults by role
    if(/staff|operator/i.test(u.role||'')) return STAFF_DEFAULT.slice();
    if(/manager/i.test(u.role||'')) return allKeys().filter(function(k){ return ['users','userroles','access','adminpanel','twofactorauth','settings'].indexOf(k)<0; });
    // Unknown/unset role with no explicit pages list — default to full access
    // rather than silently hiding 98% of the menu from a real user.
    return 'all';
  }
  window.canAccessPage = function(key){
    var p = userPages(_CU());
    if(p==='all') return true;
    return p.indexOf(key)>=0 || key==='access' && false;
  };

  window.applyAccessControl = function(){
    var p = userPages(_CU());
    document.querySelectorAll('.nav-item').forEach(function(it){
      var m = /nav\('([\w-]+)'\)/.exec(it.getAttribute('onclick')||''); if(!m) return;
      var allowed = (p==='all') || p.indexOf(m[1])>=0;
      it.style.display = allowed ? '' : 'none';
    });
    document.querySelectorAll('.nav-section').forEach(function(sec){
      var any = Array.prototype.some.call(sec.querySelectorAll('.nav-item'), function(i){ return i.style.display!=='none'; });
      sec.style.display = any ? '' : 'none';
    });
    var badge = document.getElementById('acl-role-badge');
    if(badge) badge.textContent = ((_CU()&&_CU().name)||'—')+' • '+((_CU()&&_CU().role)||'—');
  };

  // gate navigation itself
  var _nav = window.nav;
  window.nav = function(page){
    if(!window.canAccessPage(page)){
      if(typeof toast==='function') toast('🔒 You do not have access to this option.','e');
      else alert('You do not have access to this option.');
      return;
    }
    return _nav.apply(this, arguments);
  };

  var _aclUserId = null;
  function aclUsers(){ return _DB().users || []; }
  function aclUser(){ return aclUsers().find(function(u){ return String(u.id)===String(_aclUserId); }) || aclUsers()[0]; }

  window.aclSelectUser = function(id){ _aclUserId = id; renderAccessControl(); };
  window.aclToggle = function(key, on){
    var u = aclUser(); if(!u) return;
    var p = userPages(u); if(p==='all') p = allKeys().slice();
    p = p.slice();
    var i = p.indexOf(key);
    if(on && i<0) p.push(key);
    if(!on && i>=0) p.splice(i,1);
    u.pages = p;
    if(u.permissions==='all') u.permissions = {};
    if(typeof saveDB==='function') saveDB();
    if(_CU() && _CU().id===u.id){ _CU().pages = p; window.currentUser = _CU(); applyAccessControl(); }
    renderAccessControl();
  };
  window.aclPreset = function(kind){
    var u = aclUser(); if(!u) return;
    if(kind==='all'){ u.pages = 'all'; u.permissions='all'; }
    else if(kind==='none') u.pages = [];
    else if(kind==='staff') u.pages = STAFF_DEFAULT.slice();
    else if(kind==='manager') u.pages = allKeys().filter(function(k){ return ['users','userroles','access','adminpanel','twofactorauth'].indexOf(k)<0; });
    if(typeof saveDB==='function') saveDB();
    if(_CU() && _CU().id===u.id){ _CU().pages = u.pages; applyAccessControl(); }
    if(typeof toast==='function') toast('✅ Access preset applied for '+u.name,'s');
    renderAccessControl();
  };
  window.aclToggleSection = function(idx, on){
    var u = aclUser(); if(!u) return;
    var cat = menuCatalog()[idx]; if(!cat) return;
    var p = userPages(u); if(p==='all') p = allKeys().slice();
    p = p.slice();
    cat.items.forEach(function(it){
      var i = p.indexOf(it.key);
      if(on && i<0) p.push(it.key);
      if(!on && i>=0) p.splice(i,1);
    });
    u.pages = p;
    if(u.permissions==='all') u.permissions = {};
    if(typeof saveDB==='function') saveDB();
    if(_CU() && _CU().id===u.id){ _CU().pages = p; window.currentUser = _CU(); applyAccessControl(); }
    renderAccessControl();
  };
  window.aclLoginAs = function(id){
    var u = aclUsers().find(function(x){ return String(x.id)===String(id); }); if(!u) return;
    try{ currentUser = u; }catch(e){} window.currentUser = u;
    try{ sessionStorage.setItem('ayan_session', JSON.stringify(u)); }catch(e){}
    applyAccessControl();
    if(typeof toast==='function') toast('👤 Now working as '+u.name+' ('+u.role+')','s');
    var d = document.getElementById('topbar-user-display');
    if(d) d.textContent = '👤 '+u.name+' ('+u.role+')';
    renderAccessControl();
  };

  window.renderAccessControl = function(){
    var el = document.getElementById('pg-access'); if(!el) return;
    var users = aclUsers();
    if(!users.length){ el.innerHTML = '<div style="padding:20px;">No users yet — add users first.</div>'; return; }
    if(_aclUserId===null) _aclUserId = (_CU()&&_CU().id) || users[0].id;
    var u = aclUser();
    var p = userPages(u);
    var cat = menuCatalog();
    var total = allKeys().length;
    var granted = p==='all' ? total : p.length;

    el.innerHTML =
      '<div style="background:linear-gradient(135deg,#0f172a,#1e3a8a);color:#fff;border-radius:14px;padding:18px;margin-bottom:14px;">'
      + '<div style="font-size:16px;font-weight:900;">🔐 Access Control — one rule for every option</div>'
      + '<div style="font-size:12px;opacity:.85;margin-top:4px;">Pick a person, then tick exactly what they may see. Everything not ticked disappears from their menu and cannot be opened.</div>'
      + '<div style="margin-top:12px;display:flex;gap:8px;flex-wrap:wrap;align-items:center;">'
      +  '<select data-x-change="aclSelectUser(this.value)" style="padding:8px 12px;border-radius:8px;border:0;font-size:13px;font-weight:700;">'
      +   users.map(function(x){ return '<option value="'+x.id+'"'+(String(x.id)===String(_aclUserId)?' selected':'')+'>'+x.name+' — '+(x.role||'')+'</option>'; }).join('')
      +  '</select>'
      +  '<span style="background:rgba(255,255,255,.18);padding:7px 12px;border-radius:8px;font-size:12px;font-weight:700;">'+granted+' / '+total+' options allowed</span>'
      +  '<button data-x-click="aclLoginAs(&quot;'+String(u.id).replace(/"/g,'&quot;')+'&quot;)" style="padding:8px 14px;border:0;border-radius:8px;background:#22c55e;color:#052e16;font-weight:800;font-size:12px;cursor:pointer;">👤 Work as this user</button>'
      + '</div></div>'
      + '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px;">'
      +  [['all','👑 Full access (Owner/Admin)'],['manager','💼 Manager'],['staff','⚙️ Staff (purchase, sales, stock, orders)'],['none','🚫 Clear all']]
          .map(function(b){ return '<button data-x-click="aclPreset(\''+b[0]+'\')" style="padding:9px 14px;border:1px solid #d1d5db;background:#fff;border-radius:8px;font-size:12px;font-weight:700;cursor:pointer;">'+b[1]+'</button>'; }).join('')
      + '</div>'
      + cat.map(function(s,idx){
          var on = s.items.filter(function(i){ return p==='all'||p.indexOf(i.key)>=0; }).length;
          return '<div style="background:#fff;border:1px solid #e5e7eb;border-radius:12px;margin-bottom:12px;overflow:hidden;">'
            + '<div style="display:flex;align-items:center;gap:10px;padding:10px 14px;background:#f9fafb;border-bottom:1px solid #e5e7eb;">'
            +  '<strong style="font-size:13px;">'+s.section+'</strong>'
            +  '<span style="font-size:11px;color:#6b7280;">'+on+'/'+s.items.length+'</span>'
            +  '<span style="margin-left:auto;display:flex;gap:6px;">'
            +   '<button data-x-click="aclToggleSection('+idx+',true)" style="padding:5px 10px;border:1px solid #d1d5db;background:#fff;border-radius:6px;font-size:11px;cursor:pointer;">Allow all</button>'
            +   '<button data-x-click="aclToggleSection('+idx+',false)" style="padding:5px 10px;border:1px solid #d1d5db;background:#fff;border-radius:6px;font-size:11px;cursor:pointer;">Block all</button>'
            +  '</span></div>'
            + '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:6px;padding:12px 14px;">'
            + s.items.map(function(i){
                var checked = (p==='all'||p.indexOf(i.key)>=0);
                return '<label style="display:flex;align-items:center;gap:8px;font-size:12px;color:#374151;cursor:pointer;padding:5px 7px;border-radius:6px;background:'+(checked?'#f0fdf4':'#fff')+';">'
                  + '<input type="checkbox" '+(checked?'checked':'')+' data-x-change="aclToggle(\''+i.key+'\',this.checked)"> '+i.label+'</label>';
              }).join('')
            + '</div></div>';
        }).join('');
  };

  // ── wire the two new pages into the app ────────────────────
  function ensurePage(key){
    var id = 'pg-'+key;
    if(document.getElementById(id)) return;
    var d = document.createElement('div');
    d.id = id; d.className = 'page'; d.style.display='none';
    (document.querySelector('.main')||document.body).appendChild(d);
  }
  function addNavItem(sectionName, key, icon, label){
    if(document.querySelector('.nav-item[onclick*="nav(\''+key+'\')"]')) return;
    var target = null;
    document.querySelectorAll('.nav-section').forEach(function(s){
      var l = s.querySelector('.nav-label');
      if(l && l.textContent.trim().toLowerCase()===sectionName.toLowerCase()) target = s;
    });
    var body = target && target.querySelector('.nav-section-body');
    if(!body) return;
    var d = document.createElement('div');
    d.className = 'nav-item';
    d.setAttribute('onclick', "nav('"+key+"')");
    d.innerHTML = '<span class="nav-icon">'+icon+'</span><span>'+label+'</span><span class="nav-tooltip">'+label+'</span>';
    body.appendChild(d);
  }

  function boot(){
    ensurePage('balancecheck'); ensurePage('access');
    addNavItem('Dashboard','balancecheck','⚖️','Balance Check');
    addNavItem('System','access','🔐','Access Control');
    try{
      if(typeof TITLES==='object'){
        TITLES['balancecheck'] = '⚖️ Business Balance Check';
        TITLES['access'] = '🔐 Access Control';
      }
    }catch(e){}
    var _render = window.render;
    window.render = function(page){
      if(page==='balancecheck') return renderBalanceCheck();
      if(page==='access') return renderAccessControl();
      return _render.apply(this, arguments);
    };
    applyAccessControl();
  }

  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded', function(){ setTimeout(boot,300); });
  else setTimeout(boot,300);
  // Safety net: addNavItem()/ensurePage() are idempotent, so re-running boot()
  // after full page load guarantees the Balance Check link appears even if an
  // earlier script on the page was still loading (slow connection, blocked
  // CDN, etc.) when the first boot() ran.
  window.addEventListener('load', function(){ setTimeout(boot,50); });
})();
</script>

<!-- ══════════════════════════════════════════════════════════════
     v16 MODULE — (A) Landed-cost stock valuation (avg + remaining-lot tax value)
                  (B) Balance equation covering EVERY party I owe / who owes me
                  (C) Multi-Unit product system + health audit
     ══════════════════════════════════════════════════════════════ -->
<script nonce="<?php echo $cspNonceAttr; ?>">
(function(){
  'use strict';
  var N=function(v){v=parseFloat(v);return isFinite(v)?v:0;};
  var money=function(v){var s=(Math.round(Math.abs(N(v))*100)/100).toLocaleString('en-IN',{maximumFractionDigits:2});return (N(v)<0?'-':'')+'৳'+s;};
  var SALE_T=['Sale','Sales','Sales Invoice','Customer Sale','Warehouse Sale','Other Income','Interest Income'];
  var PURCH_T=['Purchase','Warehouse Purchase','Supplier Purchase'];
  var EXCL=['Sale','Sales','Sales Invoice','Warehouse Sale','Other Income','Interest Income',
            'Purchase','Warehouse Purchase','Purchase Advance','Sales Advance','Sales Receipt',
            'Purchase Payment','Journal','Transfer','Inter-Account Transfer','Partner Capital',
            'Partner Withdrawal','Stock Adjustment'];
  var _dbCache=null;
  function DBx(){
    if(window.DB && Object.keys(window.DB).length) return window.DB;
    if(_dbCache) return _dbCache;
    try{ var g=(0,eval)('typeof DB!=="undefined"?DB:null'); if(g){ _dbCache=g; return g; } }catch(e){}
    return {};
  }
  window.DBx=DBx;
  function txs(){var D=DBx();return D.tx||D.transactions||[];}
  function amt(t){return N(t.amt!==undefined?t.amt:t.amount);}
  function pbal(c){return N(c.balance!==undefined?c.balance:c.bal);}
  function prods(){return DBx().products||[];}
  function pname(p){return p.name||p.product||'';}
  function pqty(p){return N(p.stockQty!==undefined?p.stockQty:(p.qty!==undefined?p.qty:p.stock));}

  /* ── A. LANDED COST: purchase value INCLUDING tax/vat/freight, minus discount ── */
  function landed(t){
    var base = amt(t) || N(t.qty)*N(t.rate);
    var extra = N(t.vatAmt)+N(t.taxAmt)+N(t.freight)+N(t.carrying)+N(t.transport)+N(t.loading);
    if(!extra && N(t.vatPct) && !t.vatIncluded) extra = base*N(t.vatPct)/100;
    return base + extra - N(t.discount);
  }
  // purchase lots, oldest first
  function lots(name){
    return txs().filter(function(t){return PURCH_T.indexOf(t.type)>=0 && (t.product||'')===name && N(t.qty)>0;})
      .sort(function(a,b){return new Date(a.date||0)-new Date(b.date||0);})
      .map(function(t){return {qty:N(t.qty), val:landed(t), type:t.type, date:t.date};});
  }
  function soldQty(name){
    return txs().reduce(function(s,t){return s+((SALE_T.indexOf(t.type)>=0&&(t.product||'')===name)?N(t.qty):0);},0);
  }
  // Owner's rule: purchases already consumed are costed at the AVERAGE rate,
  // whatever is still lying in the store is valued at its OWN landed (tax-inclusive) value.
  function valueProduct(p){
    var name=pname(p), qty=pqty(p), L=lots(name);
    var tq=0, tv=0; L.forEach(function(l){tq+=l.qty; tv+=l.val;});
    var man = N((DBx().stockRates||{})[name]);
    var invRow = (DBx().inventory||[]).find(function(iv){return (iv.product||iv.name)===name;}) || {};
    var invRate = N(invRow.rate) || (N(invRow.qty)&&N(invRow.value) ? N(invRow.value)/N(invRow.qty) : 0);
    var avg = tq>0 ? tv/tq : (man || N(p.avgRate||p.avgCost||p.rate||p.purchaseRate) || invRate);
    // walk lots from the newest backwards to cover the qty still on hand
    var need=qty, landedVal=0, i=L.length-1;
    while(need>0 && i>=0){ var take=Math.min(need,L[i].qty); landedVal += take*(L[i].qty?L[i].val/L[i].qty:0); need-=take; i--; }
    if(need>0) landedVal += need*avg;             // more stock than purchase history → fall back to avg
    return {name:name, unit:p.unit||'', qty:qty, avg:avg, rate:avg, source:(tq>0?'purchase average':(man?'entered rate':(N(p.rate)?'product rate':(invRate?'inventory value':'—')))), avgValue:qty*avg,
            value:qty>0?landedVal:qty*avg, purchasedQty:tq, soldQty:soldQty(name), hasCost:(tq>0||avg>0)};
  }
  window.stockValuation=function(){
    var rows=prods().map(valueProduct).filter(function(r){return r.qty!==0||r.value!==0;});
    var have={}; rows.forEach(function(r){have[r.name]=1;});
    (DBx().inventory||[]).forEach(function(iv){
      var nm=iv.product||iv.name||''; if(!nm||have[nm]) return;
      var p=prods().find(function(x){return pname(x)===nm;});
      var v=p?valueProduct(p):{avg:0};
      var qty=N(iv.qty), rate=N(iv.rate)||v.avg||(N(iv.value)&&qty?N(iv.value)/qty:0);
      var val=rate?qty*rate:N(iv.value);
      if(qty||val) rows.push({name:nm+' (inventory)',unit:iv.unit||'',qty:qty,avg:rate,rate:rate,source:'inventory',avgValue:qty*rate,value:val,purchasedQty:0,soldQty:0,hasCost:rate>0});
    });
    return {rows:rows,
            value:rows.reduce(function(s,r){return s+r.value;},0),
            avgValue:rows.reduce(function(s,r){return s+r.avgValue;},0)};
  };

  /* ── B. BALANCE EQUATION — every party counted, whatever his type ── */
  function allParties(){
    var D=DBx(), out=[];
    ['customers','suppliers','parties','employees','staff','expenseParties']
      .forEach(function(k){ (D[k]||[]).forEach(function(c){ if(c&&typeof c==='object') out.push(c); }); });
    var seen={};
    return out.filter(function(c){var id=(c.id||c.name)+'|'+(c.type||'');if(seen[id])return false;seen[id]=1;return true;});
  }
  function partySplit(){
    var recv=[], pay=[];
    allParties().forEach(function(c){
      var b=pbal(c), ty=(c.type||'Party');
      // For suppliers / expense parties a positive balance means I OWE him.
      var owedByMe = /supplier|vendor|expense|labour|labor|unload|develop|transport|urgent|employee|staff/i.test(ty);
      var v = owedByMe ? -b : b;
      if(v>0) recv.push({name:c.name,type:ty,v:v});
      else if(v<0) pay.push({name:c.name,type:ty,v:-v});
    });
    return {recv:recv, pay:pay,
      recvTotal:recv.reduce(function(s,r){return s+r.v;},0),
      payTotal:pay.reduce(function(s,r){return s+r.v;},0)};
  }
  // Unpaid handling bills are real liabilities (the sample sheet lists QC Bill Due,
  // Unload Bill Due, Agent Commission Due under Source of Fund).
  function accruedDues2(){
    var D=DBx(), t=0;
    ((D.agentLedger)||[]).forEach(function(a){ var b=N(a.bal); if(b>0) t+=b; });
    ((D.dues)||[]).forEach(function(d){ t+=N(d.amount!==undefined?d.amount:d.amt); });
    return t;
  }
  window.balanceModel=function(){
    var D=DBx(), sales=0,purch=0,exp=0,unknown=[];
    var RET_S=['Sales Return','Sale Return'], RET_P=['Purchase Return','Supplier Refund'];
    // Pure money / stock movements never create profit or loss — they only move
    // value between a bank, a party and the store.
    var MOVE=['Sales Receipt','Sales Advance','Purchase Payment','Purchase Advance','Cash Payment',
      'Cash Receipt','Bank Deposit','Bank Withdrawal','Journal','Transfer','Inter-Account Transfer',
      'Partner Capital','Partner Withdrawal','Stock Adjustment','Opening Balance','Opening Stock',
      'Opening Warehouse Purchase','Warehouse Transfer','Raw Material Issue','Employee Advance','Employee Loan'];
    /* FIX: 'Partner Fund' — the name the New Transaction form actually uses —
       was missing from this list while 'Partner Capital' was on it, so money
       the partners put in was charged against profit. Balance Check therefore
       reported a ৳9,989 loss where the P&L showed a ৳10.67 profit. */
    (function(){
      var extra=[];
      if(window.AYAN_NON_EXPENSE) window.AYAN_NON_EXPENSE.forEach(function(t){ extra.push(t); });
      MOVE.moveLC = MOVE.map(function(x){return String(x).toLowerCase();}).concat(extra);
    })();
    function isMove(ty){ return MOVE.moveLC.indexOf(String(ty||'').toLowerCase().trim())>=0; }
    txs().forEach(function(t){
      var a=amt(t), ty=t.type||'';
      if(SALE_T.indexOf(ty)>=0) sales+=a;
      else if(RET_S.indexOf(ty)>=0) sales-=a;
      else if(PURCH_T.indexOf(ty)>=0) { /* purchases tracked via computeCOGS */ }
      else if(RET_P.indexOf(ty)>=0) { /* returns tracked via computeCOGS */ }
      else if(isMove(ty)){ /* not profit */ }
      else if(EXCL.indexOf(ty)<0) exp+=a;               // unloading, development, urgent, salary…
    });
    // COGS = cost of goods actually SOLD (qty sold × avg purchase cost per unit).
    // Unsold stock stays on the "holds" side as inventory, not deducted from profit.
    /* FIX: computeCOGS only costs goods that were SOLD, so stock written off
       as wastage or removed by a stock adjustment left the assets but never
       reduced profit — the two sides of this very screen then disagreed by
       the value written off. The Profit & Loss page already uses the fuller
       figure (every movement out of stock, at cost); this now uses the same
       one, so the two screens can no longer contradict each other. */
    var totalCOGS = 0;
    try{ totalCOGS = (typeof window.ayanPL==='function') ? (window.ayanPL(null,null).cogs||0) : 0; }catch(e){ totalCOGS = 0; }
    if(!totalCOGS) totalCOGS = window.computeCOGS ? window.computeCOGS(txs()) : 0;
    /* Tax withheld by buyers at source — money taken off the invoice that
       never reaches you. Counted as a cost so this statement balances. */
    exp += txs().reduce(function(s,t){return s+N(t.salesTaxAmt);},0);
    exp += (typeof window.ayanTxSideCosts==='function') ? window.ayanTxSideCosts(txs()) : 0;
    /* The invoice financier's fee, interest and charges — a cost of the sale
       that no total on this screen had ever picked up. It is carried on the
       other side as part of Factory Finance until the drawdown settles, so
       adding it here keeps both columns level. */
    exp += (typeof window.ayanFinanceCharges==='function') ? window.ayanFinanceCharges(false) : 0;
    var netProfit=sales-totalCOGS-exp;
    var partnerFunds=((D.partners)||[]).reduce(function(s,p){return s+N(p.cap!==undefined?p.cap:p.capital);},0);
    var ps=partySplit();
    var bank=((D.banks)||[]).reduce(function(s,b){return s+N(b.bal!==undefined?b.bal:b.balance);},0);
    var cash=N(D.cashInHand||D.cash||(D.settings&&D.settings.cashInHand));
    var assets=((D.assets)||[]).reduce(function(s,a){return s+N(a.value!==undefined?a.value:(a.val!==undefined?a.val:a.cost));},0);
    var sv=window.stockValuation();

    var owes=[
      {k:'Partner funds (capital in the business)',v:partnerFunds},
      {k:'Net profit (Sales − COGS − All costs & expenses)',v:netProfit},
      {k:'Everyone I owe money to (suppliers, unloading, development, urgent, staff…)',v:ps.payTotal},
      {k:'Unpaid bills (agent commission, QC, unload, other)',v:accruedDues2()},
      {k:'Bank loans / LC outstanding',v:(typeof window.ayanLoansOutstanding==='function'?window.ayanLoansOutstanding():0)}
    ];
    var holds=[
      {k:'Everyone who owes me money (customers & other parties)',v:ps.recvTotal},
      {k:'Bank + cash in hand',v:bank+cash},
      {k:'Stock — sold lots at average, remaining lots at their tax-inclusive value',v:sv.value},
      {k:'Fixed assets (fixed cost)',v:assets}
    ];
    var left=owes.reduce(function(s,r){return s+r.v;},0), right=holds.reduce(function(s,r){return s+r.v;},0);
    return {owes:owes,holds:holds,left:left,right:right,diff:right-left,
            totalSales:sales,totalCOGS:totalCOGS,totalExp:exp,netProfit:netProfit,
            stockRows:sv.rows,stockValue:sv.value,stockAvgValue:sv.avgValue,parties:ps,
            unknownTypes:Array.from(new Set(unknown))};
  };

  window.setStockRate=function(name,val){
    var D=DBx(); if(!D.stockRates) D.stockRates={};
    D.stockRates[name]=N(val);
    var p=prods().find(function(x){return pname(x)===name;}); if(p) p.rate=N(val);
    if(typeof saveDB==='function') saveDB();
    if(typeof renderBalanceCheck==='function') renderBalanceCheck();
  };

  /* ── C. MULTI-UNIT PRODUCT SYSTEM ── */
  // product.units = [{unit:'Bag', factor:50, buy:2500, sell:2700}]  (factor = how many base units)
  function unitsOf(p){ return Array.isArray(p.units)?p.units:[]; }
  window.toBaseQty=function(prod,qty,unit){
    var p=typeof prod==='string'?prods().find(function(x){return pname(x)===prod;}):prod;
    if(!p||!unit||unit===(p.unit||'')) return N(qty);
    var u=unitsOf(p).find(function(x){return x.unit===unit;});
    return N(qty)*(u?N(u.factor)||1:1);
  };
  window.unitBuyRate=function(prod,unit){
    var p=typeof prod==='string'?prods().find(function(x){return pname(x)===prod;}):prod; if(!p) return 0;
    var base=valueProduct(p).avg||N(p.rate);
    if(!unit||unit===(p.unit||'')) return base;
    var u=unitsOf(p).find(function(x){return x.unit===unit;});
    return u? (N(u.buy)||base*(N(u.factor)||1)) : base;
  };
  window.unitSellRate=function(prod,unit){
    var p=typeof prod==='string'?prods().find(function(x){return pname(x)===prod;}):prod; if(!p) return 0;
    if(!unit||unit===(p.unit||'')) return N(p.sellRate||p.salePrice||p.sale||p.mrp)|| (valueProduct(p).avg*(1+N(p.margin||0)/100));
    var u=unitsOf(p).find(function(x){return x.unit===unit;});
    return u? (N(u.sell)||window.unitBuyRate(p,unit)*(1+N(p.margin||0)/100)) : 0;
  };
  // audit: is the multi-unit setup healthy? (buy price must come from what I actually paid)
  window.multiUnitAudit=function(){
    var issues=[], ok=[];
    prods().forEach(function(p){
      var name=pname(p), base=p.unit||'', us=unitsOf(p), v=valueProduct(p);
      if(!base) issues.push({name:name,msg:'No base unit set',fix:'Set a base unit (KG, Piece, Bag…)'});
      if(!us.length){ ok.push({name:name,units:[base||'—'],note:'single unit'}); }
      us.forEach(function(u){
        if(!u.unit) issues.push({name:name,msg:'A unit row has no name',fix:'Name the unit'});
        if(!(N(u.factor)>0)) issues.push({name:name,msg:'Unit "'+(u.unit||'?')+'" has no conversion factor',fix:'e.g. 1 Bag = 50 '+(base||'base')});
        if(!(N(u.buy)>0) && !(v.avg>0)) issues.push({name:name,msg:'Unit "'+(u.unit||'?')+'" has no purchase price and the product has no purchase history',fix:'Enter what you actually paid'});
        if(N(u.sell)>0 && N(u.buy)>0 && N(u.sell)<N(u.buy)) issues.push({name:name,msg:'Selling price of "'+u.unit+'" is below its purchase price',fix:'Selling rate must be ≥ '+money(u.buy)});
        var derived=v.avg*(N(u.factor)||0);
        if(N(u.buy)>0 && derived>0 && Math.abs(N(u.buy)-derived)/derived>0.25)
          issues.push({name:name,msg:'Unit "'+u.unit+'" buy rate '+money(u.buy)+' is far from the real average cost '+money(derived),fix:'Recheck the factor or the rate'});
      });
      if(us.length) ok.push({name:name,units:[base].concat(us.map(function(u){return u.unit+' ×'+N(u.factor);})),note:us.length+' extra unit(s)'});
    });
    return {issues:issues, ok:ok, products:prods().length,
            multi:prods().filter(function(p){return unitsOf(p).length;}).length};
  };

  var _muSel=null;
  window.muSelect=function(n){_muSel=n;renderMultiUnit();};
  function selProduct(){return prods().find(function(p){return pname(p)===_muSel;})||prods()[0];}
  window.muAddUnit=function(){var p=selProduct();if(!p)return;if(!Array.isArray(p.units))p.units=[];
    p.units.push({unit:'',factor:1,buy:0,sell:0});if(typeof saveDB==='function')saveDB();renderMultiUnit();};
  window.muDelUnit=function(i){var p=selProduct();if(!p||!p.units)return;p.units.splice(i,1);
    if(typeof saveDB==='function')saveDB();renderMultiUnit();};
  window.muSet=function(i,f,val){var p=selProduct();if(!p||!p.units||!p.units[i])return;
    p.units[i][f]=(f==='unit')?val:N(val);if(typeof saveDB==='function')saveDB();renderMultiUnit();};
  window.muMargin=function(val){var p=selProduct();if(!p)return;p.margin=N(val);
    (p.units||[]).forEach(function(u){u.sell=Math.round(window.unitBuyRate(p,u.unit)*(1+N(p.margin)/100)*100)/100;});
    if(typeof saveDB==='function')saveDB();renderMultiUnit();};
  window.muAutoPrice=function(){var p=selProduct();if(!p)return;var v=valueProduct(p);
    (p.units||[]).forEach(function(u){ if(!(N(u.buy)>0)&&v.avg>0) u.buy=Math.round(v.avg*(N(u.factor)||1)*100)/100;
      u.sell=Math.round(N(u.buy)*(1+N(p.margin||0)/100)*100)/100; });
    if(typeof saveDB==='function')saveDB();
    if(typeof toast==='function')toast('Prices rebuilt from what you actually paid', 's');
    renderMultiUnit();};

  window.renderMultiUnit=function(){
    var el=document.getElementById('pg-multiunit'); if(!el) return;
    var list=prods(); if(!list.length){el.innerHTML='<div style="padding:20px;">Add products first.</div>';return;}
    if(_muSel===null)_muSel=pname(list[0]);
    var p=selProduct(), v=valueProduct(p), a=window.multiUnitAudit();
    var us=unitsOf(p);
    var card=function(t,val,c){return '<div style="background:rgba(255,255,255,.15);border-radius:10px;padding:12px;text-align:center;"><div style="font-size:17px;font-weight:900;">'+val+'</div><div style="font-size:11px;opacity:.85;">'+t+'</div></div>';};
    el.innerHTML=
      '<div style="background:linear-gradient(135deg,'+(a.issues.length?'#b45309':'#047857')+',#111827);color:#fff;border-radius:14px;padding:18px;margin-bottom:14px;">'
