          return '<tr><td style="padding:6px 12px;">'+'<input value="'+(u.unit||'')+'" data-x-change="muSet('+i+',\'unit\',this.value)" style="width:110px;padding:5px;border:1px solid #d1d5db;border-radius:6px;">'+'</td>'
