  /* ── upgraded Balance Check view ── */
  var _v15bal = window.renderBalanceCheck;
  window.renderBalanceCheck=function(){
    var el=document.getElementById('pg-balancecheck'); if(!el) return;
    var m=window.balanceModel();
    var D=DBx();

    // granular figures — same data sources as the Dashboard (partyBuckets(DB.customers),
    // stockValue(DB.products)) so Balance Check never drifts from the Dashboard's numbers.
    var pb       = window.partyBuckets ? window.partyBuckets(D.customers||[]) : {custDue:0,suppDue:0,suppAdv:0};
    var custDue  = N(pb.custDue);
    var suppDue  = N(pb.suppDue);
    var suppAdv  = N(pb.suppAdv);
    var bank     = ((D.banks)||[]).reduce(function(s,b){return s+N(b.bal!==undefined?b.bal:b.balance);},0)
                 + N(D.cashInHand||D.cash||(D.settings&&D.settings.cashInHand));
    var assets   = ((D.assets)||[]).reduce(function(s,a){return s+N(a.value!==undefined?a.value:(a.val!==undefined?a.val:a.cost));},0);
    // Stock rows built from the SAME per-item helpers stockValue() uses (window.stockQtyOf /
    // window.unitCost) on D.products, so the detail table always sums to the dashboard's figure.
    var sv = (function(){
      var rows=(D.products||[]).map(function(p){
        var qty=window.stockQtyOf?window.stockQtyOf(p):N(p.stock!==undefined?p.stock:(p.qty!==undefined?p.qty:p.stockQty));
        var rate=window.unitCost?window.unitCost(p):(N(p.cost)||N(p.rate));
        return {name:p.name||p.productName||'(unnamed)',unit:p.unit||'',qty:qty,rate:rate,avg:rate,source:'product',value:qty*rate};
      }).filter(function(r){return r.qty!==0||r.value!==0;});
      var value=window.stockValue?window.stockValue(D.products):rows.reduce(function(s,r){return s+r.value;},0);
      return {rows:rows,value:value,avgValue:value};
    })();
    var stock    = sv.value;
    /* FIX: this preferred the `capital` field while every entry screen
       updates `cap`, so Balance Check reported partner capital from before
       the day's entries — ৳2,09,17,624.25 here against ৳2,09,27,624.25 on
       the Dashboard. `cap` is the live figure and is read first. */
    var partnerFunds = ((D.partners)||[]).reduce(function(s,p){return s+N(p.cap!==undefined?p.cap:p.capital);},0);
    var netProfit = m.netProfit;

    // split accrued dues into categories
    var agentCommDue=0, qcBillDue=0, unloadBillDue=0, anotherCostDue=0;
    ((D.agentLedger)||[]).forEach(function(a){ var b=N(a.bal); if(b>0) agentCommDue+=b; });
    ((D.dues)||[]).forEach(function(d){
      var nm=(d.name||d.type||'').toLowerCase();
      var amt2=N(d.amount!==undefined?d.amount:d.amt);
      if(/qc/.test(nm))               qcBillDue+=amt2;
      else if(/unload/.test(nm))      unloadBillDue+=amt2;
      else if(/agent|comm/.test(nm))  agentCommDue+=amt2;
      else                            anotherCostDue+=amt2;
    });

