       out by exactly that much. */
    var loansOut = (typeof window.ayanLoansOutstanding==='function') ? window.ayanLoansOutstanding() : 0;
    /* Money the business owes that this statement had never counted: the
       bank's invoice advance, unpaid truck rent, and unpaid handling costs. */
    var finOut   = (typeof window.ayanFinanceOutstanding==='function') ? window.ayanFinanceOutstanding() : 0;
    var transDue = (typeof window.ayanTransportDue==='function') ? window.ayanTransportDue() : 0;
    var scDue    = (typeof window.ayanSaleCostDue==='function') ? window.ayanSaleCostDue() : 0;
    var expDue   = (typeof window.ayanExpensePayable==='function') ? window.ayanExpensePayable() : 0;
    var useTotal = custDue + bank + assets + stock + suppAdv;
    var srcTotal = partnerFunds + netProfit + suppDue + agentCommDue + qcBillDue + unloadBillDue + anotherCostDue + loansOut + finOut + transDue + scDue + expDue;
    var diff     = useTotal - srcTotal;
    var ok=Math.abs(diff)<1, near=!ok&&Math.abs(diff)<Math.max(1000,Math.abs(srcTotal)*0.005);
    var statusColor=ok?'#16a34a':(near?'#d97706':'#dc2626');
    var statusText =ok?'\u2705 Business balance is fine \u2014 both sides match'
                      :(near?'\u26a0\ufe0f Almost balanced \u2014 small gap'
                            :'\ud83d\udea8 Out of balance \u2014 difference: '+money(diff));

    // table cell styles
    var BD='2px solid #222';
    var TH='padding:10px 14px;background:#e8f5e9;font-weight:800;font-size:13.5px;text-align:center;border:'+BD+';';
    var TD='padding:8px 14px;border:1px solid #bbb;font-size:13px;color:#1a1a1a;';
    var TDR='padding:8px 14px;border:1px solid #bbb;font-size:13px;text-align:right;font-weight:700;';
    var TOTT='padding:10px 14px;border:'+BD+';font-size:13px;font-weight:900;background:#f0fdf4;';
    var TOTR='padding:10px 14px;border:'+BD+';font-size:13px;font-weight:900;text-align:right;background:#c8e6c9;';

    function row(label,val,onclickFn){
      var labelHtml = onclickFn
        ? '<span data-x-click="'+onclickFn+'" style="cursor:pointer;text-decoration:underline;text-decoration-style:dotted;" title="Click to open and pay">'+label+' →</span>'
        : label;
      return '<tr><td style="'+TD+'">'+labelHtml+'</td><td style="'+TDR+'">'+money(val)+'</td></tr>';
    }

    var useTable=
      '<table style="width:100%;border-collapse:collapse;border:'+BD+';">'
      +'<tr><th colspan="2" style="'+TH+'">Use Of Fund</th></tr>'
      +row('Customer Due',custDue,"nav('customers')")
      +row('Bank',bank,"nav('banks')")
      +row('Fixed Assets',assets,"nav('assets')")
      +row('Stock',stock,"nav('inventory')")
      +row('Supplier Advance',suppAdv,"nav('suppliers')")
      +'<tr><td style="'+TOTT+'">Total</td><td style="'+TOTR+'">'+money(useTotal)+'</td></tr>'
      +'</table>';

    var srcTable=
      '<table style="width:100%;border-collapse:collapse;border:'+BD+';">'
      +'<tr><th colspan="2" style="'+TH+'">Source Of Fund</th></tr>'
      +row('Partner Fund',partnerFunds,"nav('partners')")
      +row('Net Profit',netProfit,"nav('profitloss')")
      +row('Supplier Due',suppDue,"nav('suppliers')")
      +row('Agent Commission Due',agentCommDue,"nav('agents')")
      +row('QC Bill Due',qcBillDue,"if(typeof openCostLineLedger==='function')openCostLineLedger();")
      +row('Unload Bill Due',unloadBillDue,"if(typeof openCostLineLedger==='function')openCostLineLedger();")
      +row('Another Cost Due',anotherCostDue,"if(typeof openCostLineLedger==='function')openCostLineLedger();")
      +row('Bank Loans / LC',loansOut,"nav('loans')")
      +row('Factory Finance (advance + charges)',finOut,"nav('cityfinance')")
      +row('Transport / Freight Due',transDue,"if(typeof openTransportDueLedger==='function')openTransportDueLedger();")
      +row('Sale Handling Costs Due',scDue,"if(typeof openCostLineLedger==='function')openCostLineLedger();")
      +row('Unpaid Expenses',expDue,"nav('expenseentry')")
      +'<tr><td style="'+TOTT+'">Total</td><td style="'+TOTR+'">'+money(srcTotal)+'</td></tr>'
      +'</table>';

    // net profit detail
    var profitDetail=
      '<details style="margin-top:12px;">'
      +'<summary style="cursor:pointer;font-weight:700;font-size:13px;padding:8px 14px;background:#f0fdf4;border:1px solid #bbf7d0;border-radius:8px;">\ud83e\udded Net Profit Working (click to expand)</summary>'
      +'<div style="background:#fff;border:1px solid #e5e7eb;border-radius:8px;margin-top:6px;overflow:hidden;">'
      +'<table style="width:100%;border-collapse:collapse;font-size:12.5px;">'
      +[['Total Sales',m.totalSales],['Less: COGS (goods sold)',-m.totalCOGS],['Less: All costs & expenses',-m.totalExp],['= Net Profit',m.netProfit]].map(function(r,i){
        var last=i===3;
        return '<tr><td style="padding:9px 16px;border-bottom:1px solid #f3f4f6;'+(last?'font-weight:800;background:#f0fdf4;':'')+'">'+r[0]+'</td>'
          +'<td style="padding:9px 16px;border-bottom:1px solid #f3f4f6;text-align:right;font-weight:'+(last?'900':'700')+';color:'+(r[1]<0?'#dc2626':'#111827')+';'+(last?'background:#f0fdf4;':'')+'">'+money(r[1])+'</td></tr>';
      }).join('')
      +'</table></div></details>';

    // stock detail
    var missing=sv.rows.filter(function(r){return r.qty>0&&!(r.rate>0);});
    var stockDetail=
      '<details style="margin-top:8px;">'
      +'<summary style="cursor:pointer;font-weight:700;font-size:13px;padding:8px 14px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px;">\ud83d\udce6 Stock Detail \u2014 '+money(sv.value)+'&nbsp;<span style="font-weight:500;color:#6b7280;">(avg basis: '+money(sv.avgValue)+')</span></summary>'
      +(missing.length?'<div style="background:#fff7ed;border:1px solid #fed7aa;border-radius:8px;padding:10px 14px;margin-top:6px;font-size:12.5px;color:#9a3412;"><b>'+missing.length+' item(s) have no purchase price.</b> Enter rates below to update stock value.</div>':'')
      +'<div style="background:#fff;border:1px solid #e5e7eb;border-radius:8px;margin-top:6px;overflow:auto;max-height:340px;">'
      +'<table style="width:100%;border-collapse:collapse;font-size:12px;">'
      +'<tr style="background:#f3f4f6;"><th style="padding:8px 12px;text-align:left;">Product</th><th style="padding:8px 12px;text-align:right;">Qty</th><th style="padding:8px 12px;text-align:right;">Rate</th><th style="padding:8px 12px;text-align:left;">Source</th><th style="padding:8px 12px;text-align:right;">Value</th></tr>'
      +(sv.rows.length?sv.rows.map(function(r){
        return '<tr><td style="padding:8px 12px;border-bottom:1px solid #f3f4f6;">'+r.name+'</td>'
          +'<td style="padding:8px 12px;border-bottom:1px solid #f3f4f6;text-align:right;">'+r.qty.toLocaleString('en-IN')+' '+r.unit+'</td>'
          +'<td style="padding:8px 12px;border-bottom:1px solid #f3f4f6;text-align:right;"><input value="'+(Math.round(N(r.rate)*100)/100)+'" data-x-change="setStockRate('+JSON.stringify(r.name).replace(/"/g,'&quot;')+',this.value)" style="width:90px;padding:4px;border:1px solid #d1d5db;border-radius:6px;text-align:right;"></td>'
          +'<td style="padding:8px 12px;border-bottom:1px solid #f3f4f6;color:#6b7280;">'+(r.source||'')+'</td>'
          +'<td style="padding:8px 12px;border-bottom:1px solid #f3f4f6;text-align:right;font-weight:700;">'+money(r.value)+'</td></tr>';
      }).join(''):'<tr><td colspan="5" style="padding:14px;text-align:center;color:#6b7280;">No stock on hand</td></tr>')
      +'</table></div></details>';

    /* ═══════════════════════════════════════════════════════════════
       FIX (a gap with no explanation): an opening balance typed against a
       bank, a party or a fixed asset puts money on the assets side and
       nothing at all on the funding side — that money came from somewhere,
       and the app never asked where. Change one opening bank balance and
       the statement quietly goes out by the difference, with nothing on
       screen to say why. (Editing two of them on 22 August put these books
       ৳567 apart: Another Account up ৳1,721.50, Card Account down ৳1,154.50.)

       The difference is now named, its most likely cause is spelled out,
       and there is a button that posts it to a partner's capital — which is
       the honest entry when the opening money was the partners'. The
       verdict above is left alone: the books still read as out of balance
       until you actually deal with it, rather than being quietly absorbed. */
    var gapPanel = '';
    if (Math.abs(diff) >= 0.005) {
      var _openTot = 0;
      try {
        ((D.banks)||[]).forEach(function(b){ _openTot += N(b.openingBal!==undefined?b.openingBal:b.opening); });
      } catch(e){}
      var _ptrOpts = ((D.partners)||[]).map(function(p,i){
