<script nonce="<?php echo $cspNonceAttr; ?>" id="admin-stock-reset-and-zoom">
(function(){
  /* ── 1. UI SCALE (page zoom) ───────────────────────────────────────────────
     The layout reads best at 80% on desktop, so that is the default; the user
     can switch it any time and the choice is remembered. */
  var ZOOM_KEY='rbo_ui_zoom';
  /* CSS `zoom` is a non-standard property with no support at all on Safari/
     iOS Safari (any version in real-world use on this app's devices). If we
     still wrote the compensating --app-vh height (10000/z vh) on those
     browsers, the sidebar/.main would be inflated (e.g. 125vh at the 80%
     default) with nothing actually shrinking to match — producing a large
     blank gap and broken scrolling on iPad/iPhone Safari. Feature-detect
     before applying either the zoom or its height compensation. */
  var ZOOM_SUPPORTED = !!(window.CSS && CSS.supports && CSS.supports('zoom','100%'));
  function applyZoom(z){
    if(!ZOOM_SUPPORTED){
      document.documentElement.style.zoom='';
      document.documentElement.style.setProperty('--app-vh','100vh');
      try{ localStorage.setItem(ZOOM_KEY, String(z)); }catch(e){}
      return;
    }
    document.documentElement.style.zoom = z + '%';
    /* Page zoom shrinks viewport units too, which left blank space under the
       fixed sidebar/overlays. Compensate with a zoom-aware viewport height. */
    document.documentElement.style.setProperty('--app-vh', (10000 / z) + 'vh');
    try{ localStorage.setItem(ZOOM_KEY, String(z)); }catch(e){}
    document.querySelectorAll('#ui-zoom-panel .uz-opt').forEach(function(b){
      b.classList.toggle('active', b.dataset.z === String(z));
    });
    var lbl=document.getElementById('uz-label'); if(lbl) lbl.textContent=z+'%';
  }
  function currentZoom(){
    var saved=null; try{ saved=localStorage.getItem(ZOOM_KEY); }catch(e){}
    if(saved) return parseInt(saved,10);
    return window.innerWidth>=1200 ? 80 : 100;
  }
  window.setUIZoom=function(z){ applyZoom(z); var p=document.getElementById('ui-zoom-panel'); if(p) p.style.display='none'; };
  window.toggleUIZoomPanel=function(){
    var p=document.getElementById('ui-zoom-panel'); if(!p) return;
    p.style.display = p.style.display==='block' ? 'none' : 'block';
  };

  /* ── 2. ADMIN: RESET DEMO STOCK ───────────────────────────────────────────
     Clears seeded/demo inventory rows, stock adjustments and batches, zeroes
     every product's stock field and refreshes the inventory KPIs. */
  window.resetDemoStock=async function(){
    var role = (window.currentUser && window.currentUser.role) || (typeof currentUser!=='undefined' && currentUser && currentUser.role) || 'Admin';
    if(String(role).toLowerCase()!=='admin'){
      if(typeof toast==='function') toast('Only an Admin can reset stock data','e'); else alert('Admin only');
      return;
    }
    if(!await __confirm('Reset ALL stock data to a clean baseline?\n\nThis clears inventory rows, stock adjustments and batches, and sets every product stock to 0.\nTransactions, parties and ledgers are NOT touched.')) return;
    try{
      /* FIX (dashboard showed "0 products" while the out-of-stock alert said 27):
         DB.products and DB.inventory are deliberately ONE shared array (see
         invItems()). Assigning a fresh [] here replaced the shared reference
         instead of clearing it, so DB.inventory became empty while DB.products
         kept every item - and the Inventory Value card, which reads
         DB.inventory, reported 0 products. Keep the alias; the loop below is
         what actually zeroes the stock, which is all this reset is meant to do. */
      DB.inventory = DB.products = (Array.isArray(DB.products) ? DB.products : []);
      DB.stockAdjustments = [];
      DB.batches = [];
      (DB.products||[]).forEach(function(p){
        if('stock' in p) p.stock=0;
        if('qty' in p) p.qty=0;
        if('openingStock' in p) p.openingStock=0;
        if('stockValue' in p) p.stockValue=0;
      });
      DB.dummyStockCleaned='v1';
      if(typeof saveDB==='function') saveDB();
      if(typeof addAuditEntry==='function') addAuditEntry('RESET','Inventory','Stock & inventory KPIs reset to clean baseline');
      // Reset the visible KPI immediately, then re-render the active page.
      document.querySelectorAll('[data-kpi="stock"],#kpi-stock,#kpi-stock-value').forEach(function(el){ el.textContent='৳0'; });
      try{ if(typeof render==='function' && typeof currentPage!=='undefined') render(currentPage); }catch(e){}
      try{ if(typeof renderDashboard==='function') renderDashboard(); }catch(e){}
      if(typeof toast==='function') toast('Stock reset to clean baseline ✅','s'); else alert('Stock reset');
    }catch(err){
      console.error(err);
      if(typeof toast==='function') toast('Reset failed: '+err.message,'e');
    }
  };

  /* ── 3. Inject the topbar controls ────────────────────────────────────────*/
  function inject(){
    var anchor=document.querySelector('button[data-x-click="openModal(\'mTx\')"]');
    if(!anchor || document.getElementById('ui-zoom-wrap')) return;

    var reset=document.createElement('button');
    reset.className='btn btn-sm';
    reset.id='btn-reset-stock';
    reset.title='Admin: reset demo stock & inventory KPIs';
    reset.style.cssText='background:rgba(255,255,255,.5);color:#b91c1c;border:1px solid rgba(185,28,28,.3);font-weight:700;backdrop-filter:blur(8px);';
    reset.textContent='♻️ Reset Stock';
    reset.onclick=function(){ window.resetDemoStock(); };
    anchor.parentNode.insertBefore(reset, anchor);

    var wrap=document.createElement('div');
    wrap.id='ui-zoom-wrap';
    if(!ZOOM_SUPPORTED){
      // Offering a zoom control that silently does nothing (Safari/iOS) is
      // worse than no control at all — hide it and let the page render at
      // native 100%, which the responsive breakpoints already handle.
      wrap.style.display='none';
    }
    wrap.innerHTML='<button class="uz-btn" data-x-click="toggleUIZoomPanel()" title="Page zoom">🔍 <span id="uz-label">80%</span></button>'+
      '<div id="ui-zoom-panel">'+
        '<div style="font-size:11px;font-weight:800;color:#6b7280;margin-bottom:6px;">PAGE ZOOM</div>'+
        [70,80,90,100,110,125].map(function(z){
          return '<button class="uz-opt" data-z="'+z+'" data-x-click="setUIZoom('+z+')">'+z+'%'+(z===80?' (recommended)':'')+'</button>';
        }).join('')+
      '</div>';
    anchor.parentNode.insertBefore(wrap, reset);

    applyZoom(currentZoom());

    document.addEventListener('click', function(e){
      var p=document.getElementById('ui-zoom-panel');
      if(p && p.style.display==='block' && !wrap.contains(e.target)) p.style.display='none';
    });
    // Hide the reset button for non-admins
    var role=(window.currentUser&&window.currentUser.role)||'';
    if(role && String(role).toLowerCase()!=='admin') reset.style.display='none';
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded', function(){ setTimeout(inject,300); });
  else setTimeout(inject,300);
})();
</script>


<style>
/* The login screen must never live inside .main (showLoginScreen hides .main). */
#login-screen{position:fixed !important;inset:0 !important;z-index:99999 !important;}
#login-screen .ls-card{animation-fill-mode:both !important;opacity:1 !important;}
</style>
<script nonce="<?php echo $cspNonceAttr; ?>">
/* ══════════════════════════════════════════════════════════════
   RBO ERP — AUTH + SERVER SYNC (PHP/MySQL backend)
   Replaces: DEFAULT_USERS, initLogin, doLogin, doLogout, saveDB
   Paste as the LAST <script> before </body>.
   Uses existing globals `DB` and `currentUser` (does NOT redeclare them).
   ══════════════════════════════════════════════════════════════ */
(function(){
  'use strict';

  var API_BASE    = '';                       // e.g. '/erp/' if PHP files sit in a subfolder
  var API_FILE    = (window.ERP_CONFIG && window.ERP_CONFIG.API_URL) ? window.ERP_CONFIG.API_URL : (API_BASE + 'api.php');
  var LOGIN_FILE  = (window.ERP_CONFIG && window.ERP_CONFIG.LOGIN_URL)  ? window.ERP_CONFIG.LOGIN_URL  : (API_BASE + 'login.php');
  var LOGOUT_FILE = (window.ERP_CONFIG && window.ERP_CONFIG.LOGOUT_URL) ? window.ERP_CONFIG.LOGOUT_URL : (API_BASE + 'logout.php');
  var USER_KEY    = 'rbo_user';

  var SHAPE = { users:[], tx:[], customers:[], partners:[], banks:[], assets:[], inventory:[],
                tenders:[], payroll:[], salaryHistory:[], empAdvances:[], customTemplates:[], auditLog:[] };

  // Global DB safety net (in case this block loads before the main state script)
  if(typeof window.DB === 'undefined' || !window.DB) window.DB = JSON.parse(JSON.stringify(SHAPE));
  if(typeof window.currentUser === 'undefined') window.currentUser = null;

  // Cookie-based session: no client-readable token. window.currentUser
  // (mirrored to sessionStorage) is the local "might be logged in" signal;
  // the server is the source of truth, and any 401/403 clears it.
  function jsonHeaders(extra){
    return Object.assign({ 'Accept':'application/json' }, extra || {});
  }
  function say(msg, type){ if(typeof toast === 'function') toast(msg, type); }
  function clearSession(){
    sessionStorage.removeItem(USER_KEY);
    sessionStorage.removeItem('ayan_session');
    window.currentUser = null;
  }
  function handleUnauthorized(msg){
    clearSession();
    say(msg || 'Session expired \u2014 please sign in again to save.','e');
    var errEl = document.getElementById('login-error');
    if(errEl){ errEl.textContent = msg || 'Session expired \u2014 please sign in again to save.'; errEl.style.display='block'; }
    if(typeof showLoginScreen === 'function') showLoginScreen();
    else if(typeof showApp === 'function'){ var ls=document.getElementById('login-screen'); if(ls) ls.style.display='flex'; }
  }
  /* FIX 10: a missing/expired session used to make saves fail silently.
     Now it always surfaces a visible warning and sends the user to login. */
  function requireSession(){
    if(window.currentUser) return true;
    handleUnauthorized('Not logged in \u2014 please sign in to save.');
    return false;
  }

  // ── LOGIN ────────────────────────────────────────────────────
  window.doLogin = async function(){
    var userEl = document.getElementById('login-user');
    var passEl = document.getElementById('login-pass');
    var errEl  = document.getElementById('login-error');
    var btn    = document.getElementById('ls-login-btn') || document.getElementById('login-btn');
    var username = (userEl && userEl.value || '').trim();
    var password = (passEl && passEl.value) || '';

    if(errEl){ errEl.style.display='none'; errEl.textContent=''; }
    if(!username || !password){
      if(errEl){ errEl.textContent='Please enter username and password.'; errEl.style.display='block'; }
      else say('Please enter username and password.','e');
      return;
    }
    if(btn){ btn.disabled = true; btn.dataset.old = btn.innerHTML; btn.innerHTML = 'Signing in…'; }

    try{
      var res = await fetch(LOGIN_FILE, {
        method:'POST',
        credentials:'include',                 // send/receive the PHP session cookie
        headers:{ 'Content-Type':'application/json', 'Accept':'application/json' },
        body: JSON.stringify({ username: username, password: password })
      });
      var out = await res.json().catch(function(){ return {}; });
      if(!res.ok || out.success === false){
        throw new Error(out.message || out.error || 'Invalid username or password');
      }
      // login.php returns role/name at the top level of the JSON payload.
      window.currentUser = out.user || (out.data && out.data.user) || {
        id: out.id || null,
        username: username,
        name: out.name || username,
        role: out.role || 'Operator',
        permissions: 'all'
      };
      sessionStorage.setItem(USER_KEY, JSON.stringify(window.currentUser));
      sessionStorage.setItem('ayan_session', JSON.stringify(window.currentUser)); // legacy readers

      var rb = document.getElementById('ls-remember');
      if(rb && rb.checked){
        localStorage.setItem('ayan_last_user', username);
        // Ask the proxy to keep the server session cookie alive across browser restarts.
        document.cookie = 'ayan_remember=1; path=/; max-age=' + (60*60*24*30) + '; SameSite=Lax' + (location.protocol==='https:' ? '; Secure' : '');
      } else {
        localStorage.removeItem('ayan_last_user');
        document.cookie = 'ayan_remember=; path=/; max-age=0; SameSite=Lax' + (location.protocol==='https:' ? '; Secure' : '');
      }


      await window.loadDataFromServer();
      if(typeof showApp === 'function') showApp();
      say('Welcome back, ' + (window.currentUser.name || username) + '!','s');
    }catch(err){
      clearSession();
      // FIX (2026-08-18): offline/local-storage login fallback removed —
      // this app is server-only now. A failed login always shows the real
      // server error instead of silently signing in from local storage.
      if(errEl){ errEl.textContent = err.message; errEl.style.display='block'; }
      else say(err.message,'e');

    }finally{
      if(btn){ btn.disabled = false; btn.innerHTML = btn.dataset.old || '🔐 Sign In'; }
    }
  };

  // ── LOAD ─────────────────────────────────────────────────────
  window.loadDataFromServer = async function(){
    if(!requireSession()) return false;
    try{
      var res = await fetch(API_FILE + '?action=load', { method:'GET', credentials:'include', headers: jsonHeaders() });
      if(res.status === 401 || res.status === 403){ handleUnauthorized(); return false; }
      var out = await res.json().catch(function(){ return {}; });
      if(!res.ok || out.success === false) throw new Error(out.message || out.error || 'Failed to load data');

      var data = out.data || out.db || out;
      // Merge over the existing in-memory DB so INIT defaults (products, locations…) survive
      window.DB = Object.assign({}, SHAPE, window.DB || {}, (data && typeof data === 'object') ? data : {});
      Object.keys(SHAPE).forEach(function(k){ if(!Array.isArray(window.DB[k])) window.DB[k] = SHAPE[k].slice(); });
      // Track the server's row version for optimistic-concurrency saves —
      // see ayan-final-save-authority near </body>. Harmless no-op if
      // api.php doesn't return a version field yet.
      if(typeof out.version !== 'undefined') window.__erpVersion = out.version;

      if(typeof refreshAll === 'function') refreshAll();
      else if(typeof renderAll === 'function') renderAll();
      return true;
    }catch(err){
      say('Load failed: ' + err.message,'e');
      return false;
    }
  };

  // ── SAVE (debounced, replaces localStorage saveDB) ───────────
  var _saveTimer = null, _saving = false;

  window.saveDB = function(){                       // keeps all existing call sites working
    if(!requireSession()) return false;
    clearTimeout(_saveTimer);
    _saveTimer = setTimeout(function(){ window.saveDBNow(); }, 400);
  };

  window.saveDBNow = async function(){
    if(!requireSession()) return false;
    if(_saving){ window.saveDB(); return false; }
    _saving = true;
    try{
      var res = await fetch(API_FILE + '?action=save', {
        method:'POST',
        credentials:'include',
        headers: jsonHeaders({ 'Content-Type':'application/json' }),
        body: JSON.stringify({ data: window.DB })
      });
      if(res.status === 401 || res.status === 403){ handleUnauthorized(); return false; }
      var out = await res.json().catch(function(){ return {}; });
      if(!res.ok || out.success === false) throw new Error(out.message || out.error || 'Save failed');
      if(typeof _markSaved === 'function') _markSaved();
      return true;
    }catch(err){
      // FIX (2026-08-18): local-storage save fallback removed — this app is
      // server-only. A failed save always surfaces a real error instead of
      // silently persisting to localStorage and switching USE_SERVER off.
      if(typeof _markUnsaved === 'function') _markUnsaved();
      say('Save failed: ' + err.message,'e');
      return false;
    }finally{ _saving = false; }
  };

  // ── LOGOUT ───────────────────────────────────────────────────
  window.doLogout = async function(){
    if(!await __confirm('Are you sure you want to logout?')) return;
    try{
      await fetch(LOGOUT_FILE, { method:'POST', credentials:'include', headers: jsonHeaders({ 'Content-Type':'application/json' }), body:'{}' });
    }catch(e){ /* log out locally regardless */ }
    clearSession();
    if(typeof showLoginScreen === 'function') showLoginScreen();
    say('Logged out.','s');
  };

  // ── INIT ─────────────────────────────────────────────────────
  /* Ask the server who we are. The session lives in an HttpOnly cookie, so a
     brand-new tab (which has an empty sessionStorage) can still be signed in. */
  async function restoreServerSession(){
    try{
      var res = await fetch(API_FILE + '?action=whoami', { credentials:'include', headers: jsonHeaders() });
      var out = await res.json().catch(function(){ return {}; });
      if(!res.ok || out.success === false) return null;
      var u = out.user || (out.data && out.data.user) || null;
      if(!u) return null;
      return u;
    }catch(e){ return null; }
  }

  window.initLogin = async function(){
    try{ window.currentUser = JSON.parse(sessionStorage.getItem(USER_KEY) || 'null'); }catch(e){ window.currentUser = null; }
    if(!window.currentUser){
      var restored = await restoreServerSession();
      if(restored){
        window.currentUser = restored;
        try{
          sessionStorage.setItem(USER_KEY, JSON.stringify(restored));
          sessionStorage.setItem('ayan_session', JSON.stringify(restored));
        }catch(e){}
      }
    }
    if(!window.currentUser){ if(typeof showLoginScreen === 'function') showLoginScreen(); return; }
    var ok = await window.loadDataFromServer();
    if(ok && typeof showApp === 'function') showApp();
    else if(!ok && typeof showLoginScreen === 'function') showLoginScreen();
  };


  function boot(){
    // Keep the login overlay outside the app shell so hiding the shell can't hide it
    var ls = document.getElementById('login-screen');
    if(ls && ls.parentElement !== document.body) document.body.appendChild(ls);

    var last = localStorage.getItem('ayan_last_user');
    var u = document.getElementById('login-user');
    if(last && u && !u.value) u.value = last;

    var pass = document.getElementById('login-pass');
    if(pass) pass.addEventListener('keydown', function(e){ if(e.key === 'Enter') window.doLogin(); });

    window.initLogin();

    if('serviceWorker' in navigator && location.protocol!=='file:'){
      Promise.resolve({ok:false}).then(function(r){        // FIX 7
        if(r.ok) return navigator.serviceWorker.register('sw.js');
      }).catch(function(){});
    }
  }

  if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();
})();
</script>
<script nonce="<?php echo $cspNonceAttr; ?>">
/* ═══════════════════════════════════════════════════════════════════════════
   PURCHASE ENHANCEMENT PACK
   1. Multi-product purchase rows (same supplier, same columns as single entry)
   2. Bag Type -> Jute / Plastic dropdown
   3. Multi bank-account split payment + hard balance block
   4. Correct Total Oil calculation (weight x oil% , net -> gross -> qty)
   5. Payment Refund transaction type (account + supplier, excluded from paid)
   ═══════════════════════════════════════════════════════════════════════════ */
(function(){
'use strict';
/* Bulk = sold loose, no sacks. It carries no 150 g bag tare, and its
   unloading is charged per 1000 kg instead of per bag. */
var BAG_TYPES=['Jute','Plastic','Bulk'];
var MP=[];              // multi-product rows
var PS=[];              // payment split rows
function E(id){return document.getElementById(id);}
function num(x){var n=parseFloat(x);return isNaN(n)?0:n;}
function money(n){return (num(n)).toLocaleString('en-IN',{maximumFractionDigits:2});}
function say(m,t){try{toast(m,t||'i');}catch(e){alert(m);}}
function banks(){return (window.DB&&DB.banks)||[];}
function bankBal(n){var b=banks().filter(function(x){return x.name===n;})[0];return b?num(b.bal):0;}
function fire(el){if(el){try{el.dispatchEvent(new Event('input',{bubbles:true}));}catch(e){}}}

/* ── 1. BAG TYPE DROPDOWN ─────────────────────────────────────────────── */
function bagSelectHTML(val,attrs){
  var o='<option value="">-- Bag Type --</option>'+BAG_TYPES.map(function(b){
    return '<option value="'+b+'"'+(val===b?' selected':'')+'>'+b+'</option>';}).join('');
  return '<select '+(attrs||'')+'>'+o+'</select>';
}
function upgradeBagType(){
  var inp=E('tx-bagtype');
  if(!inp||inp.tagName==='SELECT') return;
  var sel=document.createElement('select');
  sel.id='tx-bagtype'; sel.className=inp.className||'fc';
  sel.setAttribute('style',inp.getAttribute('style')||'');
  sel.innerHTML='<option value="">-- Bag Type --</option>'+BAG_TYPES.map(function(b){return '<option>'+b+'</option>';}).join('');
  inp.parentNode.replaceChild(sel,inp);
}

/* ── 2. MULTI-PRODUCT ROWS ────────────────────────────────────────────── */
function mpRow(){return {prod:'',bagtype:'',bagqty:0,qty:0,grosswt:0,wt:0,rate:0,amount:0,oilPct:0,totalOil:0,moisturePct:0,proteinPct:0,fiberPct:0,ashPct:0,ffaPct:0};}
function mpWeight(r){return num(r.wt)||num(r.grosswt)||num(r.qty);}
function mpCalc(r){
  var w=mpWeight(r);
  r.amount=+(w*num(r.rate)).toFixed(2);
  r.totalOil=+(w*num(r.oilPct)/100).toFixed(2);
}
function mpOn(){var c=E('mp-toggle');return !!(c&&c.checked);}
function ensureMPUI(){
  var anchor=E('tx-prod');
  if(!anchor||E('mp-wrap')) return;
  var grid=anchor.parentNode&&anchor.parentNode.parentNode;
  if(!grid) return;
  var w=document.createElement('div');
  w.id='mp-wrap';
  w.style.cssText='grid-column:1/-1;margin-top:6px;border-top:2px dashed #16a34a;padding-top:10px;';
  w.innerHTML=
   '<label style="display:flex;align-items:center;gap:8px;font-size:12px;font-weight:800;color:#0f3d26;cursor:pointer;">'+
   '<input type="checkbox" id="mp-toggle"> 📦 Multiple Products (same supplier)</label>'+
   '<div id="mp-body" style="display:none;margin-top:10px;overflow-x:auto;">'+
   '<table id="mp-table" style="width:100%;border-collapse:collapse;font-size:11px;min-width:1320px;"></table>'+
   '<button type="button" id="mp-add" style="margin-top:8px;background:#16a34a;color:#fff;border:0;border-radius:6px;padding:6px 12px;font-size:11px;font-weight:700;cursor:pointer;">+ Add Product</button>'+
   '<div id="mp-tot" style="margin-top:8px;font-size:11px;font-weight:700;color:#0f3d26;"></div></div>';
  grid.parentNode.insertBefore(w,grid.nextSibling);
  E('mp-toggle').addEventListener('change',function(){
    E('mp-body').style.display=this.checked?'':'none';
    if(this.checked&&!MP.length){MP=[mpRow(),mpRow()];}
    lockMain(this.checked); renderMP();
  });
  E('mp-add').addEventListener('click',function(){MP.push(mpRow());renderMP();});
  renderMP();
}
function lockMain(on){
  ['tx-prod','tx-bagtype','tx-bagqty','tx-qty','tx-grosswt','tx-wt','tx-rate','tx-amt','tx-oilpct','tx-totaloil',
   'tx-moisture','tx-protein','tx-fiber','tx-ash','tx-ffa']
  .forEach(function(id){var el=E(id);if(!el)return;
    el.readOnly=!!on; if(el.tagName==='SELECT') el.disabled=!!on;
    el.style.background=on?'#f3f4f6':'';
    el.title=on?'Auto-filled from the multiple product rows':'';
  });
}
function renderMP(){
  var t=E('mp-table'); if(!t) return;
  var head='<thead><tr style="background:#ecfdf5;">'+
    ['#','Product','Bag Type','Bag Qty','Qty (KG/Ltr)','Gross Wt','Net Wt','Rate','Amount','Oil %','Total Oil','Moisture %','Protein %','Fiber %','Ash %','FFA %','']
    .map(function(h){return '<th style="padding:5px 6px;border:1px solid #d1fae5;font-size:10px;text-align:left;">'+h+'</th>';}).join('')+'</tr></thead>';
  var body=MP.map(function(r,i){ mpCalc(r);
    function inp(k,extra){return '<input type="number" step="0.01" min="0" value="'+(num(r[k])||'')+'" data-mp="'+i+'" data-k="'+k+'" class="erp-grid-input" style="max-width:92px;'+(extra||'')+'">';}
    return '<tr>'+
      '<td style="padding:4px 6px;border:1px solid #eef2f7;color:#9ca3af;">'+(i+1)+'</td>'+
      '<td style="padding:4px 6px;border:1px solid #eef2f7;"><input type="text" list="dl-prod" value="'+(r.prod||'')+'" data-mp="'+i+'" data-k="prod" class="erp-grid-input" style="min-width:130px;"></td>'+
      '<td style="padding:4px 6px;border:1px solid #eef2f7;">'+bagSelectHTML(r.bagtype,'data-mp="'+i+'" data-k="bagtype" class="erp-grid-input" style="min-width:95px;"')+'</td>'+
      '<td style="padding:4px 6px;border:1px solid #eef2f7;">'+inp('bagqty')+'</td>'+
      '<td style="padding:4px 6px;border:1px solid #eef2f7;">'+inp('qty')+'</td>'+
      '<td style="padding:4px 6px;border:1px solid #eef2f7;">'+inp('grosswt')+'</td>'+
      '<td style="padding:4px 6px;border:1px solid #eef2f7;">'+inp('wt')+'</td>'+
      '<td style="padding:4px 6px;border:1px solid #eef2f7;">'+inp('rate')+'</td>'+
      '<td style="padding:4px 6px;border:1px solid #eef2f7;text-align:right;font-weight:700;color:#0f3d26;">'+money(r.amount)+'</td>'+
      '<td style="padding:4px 6px;border:1px solid #eef2f7;">'+inp('oilPct')+'</td>'+
      '<td style="padding:4px 6px;border:1px solid #eef2f7;text-align:right;font-weight:700;color:#b45309;">'+money(r.totalOil)+'</td>'+
      '<td style="padding:4px 6px;border:1px solid #eef2f7;">'+inp('moisturePct')+'</td>'+
      '<td style="padding:4px 6px;border:1px solid #eef2f7;">'+inp('proteinPct')+'</td>'+
      '<td style="padding:4px 6px;border:1px solid #eef2f7;">'+inp('fiberPct')+'</td>'+
      '<td style="padding:4px 6px;border:1px solid #eef2f7;">'+inp('ashPct')+'</td>'+
      '<td style="padding:4px 6px;border:1px solid #eef2f7;">'+inp('ffaPct')+'</td>'+
      '<td style="padding:4px 6px;border:1px solid #eef2f7;"><button type="button" data-mpdel="'+i+'" style="background:#fee2e2;color:#b91c1c;border:0;border-radius:4px;padding:3px 7px;cursor:pointer;">✕</button></td>'+
    '</tr>';}).join('');
  t.innerHTML=head+'<tbody>'+body+'</tbody>';
  Array.prototype.forEach.call(t.querySelectorAll('[data-mp]'),function(el){
    el.addEventListener('input',onMPInput); el.addEventListener('change',onMPInput);
    el.addEventListener('keydown',onMPKeydown);
  });
  Array.prototype.forEach.call(t.querySelectorAll('[data-mpdel]'),function(b){
    b.addEventListener('click',function(){MP.splice(+b.getAttribute('data-mpdel'),1);renderMP();});
  });
  syncMPTotals();
}
/* FIX (UI/UX redesign blueprint item #3 — "Keyboard-Driven Excel Matrix"):
   the Multiple Products grid could only be worked with a mouse — every new
   row meant reaching for it again. Arrow keys now move focus cell-to-cell
   like a spreadsheet (Up/Down within a column, Left/Right within a row,
   wrapping to the next/previous row at the row edges), and Enter behaves
   like Down. Left/Right on a text field only jumps once the caret is
   already at that end, so normal text editing/selection still works. */
var MP_COL_ORDER=['prod','bagtype','bagqty','qty','grosswt','wt','rate','oilPct','moisturePct','proteinPct','fiberPct','ashPct','ffaPct'];
function mpFocusCell(row,col){
  var el=document.querySelector('#mp-table [data-mp="'+row+'"][data-k="'+col+'"]');
  if(el){ el.focus(); if(el.select && el.type!=='select-one') el.select(); return true; }
  return false;
}
function onMPKeydown(e){
  var key=e.key;
  if(key!=='ArrowUp'&&key!=='ArrowDown'&&key!=='ArrowLeft'&&key!=='ArrowRight'&&key!=='Enter') return;
  var el=e.target, row=+el.getAttribute('data-mp'), col=el.getAttribute('data-k');
  var ci=MP_COL_ORDER.indexOf(col);
  if(ci<0) return;
  var isText=(el.tagName==='INPUT'&&el.type==='text');
  if(key==='ArrowLeft'&&isText&&el.selectionStart>0) return; // still editing inside the text
  if(key==='ArrowRight'&&isText&&el.selectionEnd<el.value.length) return;
  if(key==='ArrowUp'){ if(mpFocusCell(row-1,col)) e.preventDefault(); }
  else if(key==='ArrowDown'||key==='Enter'){
    e.preventDefault();
    if(!mpFocusCell(row+1,col)){
      // Excel-style "tab to add a row": Down/Enter on the last row adds a
      // fresh one and lands you straight in it, instead of doing nothing.
      MP.push(mpRow()); renderMP();
      setTimeout(function(){ mpFocusCell(row+1,col); },0);
    }
  }
  else if(key==='ArrowLeft'){
    if(ci>0) mpFocusCell(row,MP_COL_ORDER[ci-1]);
    else if(row>0) mpFocusCell(row-1,MP_COL_ORDER[MP_COL_ORDER.length-1]);
    e.preventDefault();
  } else if(key==='ArrowRight'){
    if(ci<MP_COL_ORDER.length-1) mpFocusCell(row,MP_COL_ORDER[ci+1]);
    else mpFocusCell(row+1,MP_COL_ORDER[0]);
    e.preventDefault();
  }
}
function onMPInput(e){
  var i=+e.target.getAttribute('data-mp'), k=e.target.getAttribute('data-k');
  if(!MP[i]) return;
  MP[i][k]=(k==='prod'||k==='bagtype')?e.target.value:num(e.target.value);
  mpCalc(MP[i]);
  // live update the computed cells without losing focus
  var row=e.target.closest('tr');
  if(row){ row.cells[8].textContent=money(MP[i].amount); row.cells[10].textContent=money(MP[i].totalOil); }
  syncMPTotals();
}
function mpTotals(){
  var T={bagqty:0,qty:0,grosswt:0,wt:0,amount:0,totalOil:0,weight:0,
    moistureWeight:0,proteinWeight:0,fiberWeight:0,ashWeight:0,ffaWeight:0};
  MP.forEach(function(r){ mpCalc(r); var rw=mpWeight(r);
    T.bagqty+=num(r.bagqty); T.qty+=num(r.qty); T.grosswt+=num(r.grosswt); T.wt+=num(r.wt);
    T.amount+=num(r.amount); T.totalOil+=num(r.totalOil); T.weight+=rw;
    T.moistureWeight+=rw*num(r.moisturePct); T.proteinWeight+=rw*num(r.proteinPct);
    T.fiberWeight+=rw*num(r.fiberPct); T.ashWeight+=rw*num(r.ashPct); T.ffaWeight+=rw*num(r.ffaPct);
  });
  T.rate=T.weight?+(T.amount/T.weight).toFixed(2):0;
  T.oilPct=T.weight?+(T.totalOil/T.weight*100).toFixed(2):0;
  ['moisture','protein','fiber','ash','ffa'].forEach(function(k){T[k+'Pct']=T.weight?+(T[k+'Weight']/T.weight).toFixed(2):0;});
  return T;
}
function syncMPTotals(){
  if(!mpOn()) return;
  var T=mpTotals();
  var names=MP.map(function(r){return r.prod;}).filter(Boolean).join(' + ');
  var types=MP.map(function(r){return r.bagtype;}).filter(Boolean);
  function setv(id,val){var el=E(id); if(el){el.value=val;}}
  setv('tx-prod',names);
  /* Mixed bag types across the lines can't be shown as one value — leave it
     blank rather than picking one and applying its rules to the whole entry. */
  var bt=E('tx-bagtype');
  if(bt){ var uniq=types.filter(function(v,i){return types.indexOf(v)===i;}); bt.value=(uniq.length>1)?'':(uniq[0]||''); }
  setv('tx-bagqty',T.bagqty||'');
  setv('tx-qty',T.qty||'');
  setv('tx-grosswt',T.grosswt||'');
  setv('tx-wt',T.wt||'');
  setv('tx-rate',T.rate||'');
  setv('tx-amt',T.amount?T.amount.toFixed(2):'');
  setv('tx-oilpct',T.oilPct||'');
  setv('tx-totaloil',T.totalOil?T.totalOil.toFixed(3):'');
  setv('tx-moisture',T.moisturePct||''); setv('tx-protein',T.proteinPct||'');
  setv('tx-fiber',T.fiberPct||''); setv('tx-ash',T.ashPct||''); setv('tx-ffa',T.ffaPct||'');
  try{calcSalesTax();}catch(e){}
  try{calcDue();}catch(e){}
  var tot=E('mp-tot');
  if(tot) tot.innerHTML='Products: '+MP.length+' &nbsp;|&nbsp; Bags: '+money(T.bagqty)+
    ' &nbsp;|&nbsp; Weight: '+money(T.weight)+' KG &nbsp;|&nbsp; Avg Rate: ৳'+money(T.rate)+
    ' &nbsp;|&nbsp; Total: ৳'+money(T.amount)+' &nbsp;|&nbsp; Total Oil: '+money(T.totalOil)+
    ' KG (avg '+T.oilPct+'%)';
  renderPS();
}

/* ── 3. TOTAL OIL FIX ─────────────────────────────────────────────────── */
window.calcTotalOil=function(){
  var oil=E('tx-totaloil'); if(!oil) return;
  var net=num(E('tx-wt')&&E('tx-wt').value), gross=num(E('tx-grosswt')&&E('tx-grosswt').value), qty=num(E('tx-qty')&&E('tx-qty').value);
  var w=net||gross||qty, pct=num(E('tx-oilpct')&&E('tx-oilpct').value), hint=E('tx-totaloil-hint');
  if(!w||!pct){ if(!mpOn()) oil.value=''; if(hint) hint.textContent=''; return; }
  var total=w*pct/100;
  oil.value=total.toFixed(3);
  if(hint) hint.textContent=(net?'Net':gross?'Gross':'Qty')+' Wt '+w.toFixed(2)+' × '+pct+'% = '+total.toFixed(3)+' KG';
};

/* ── 4. MULTI ACCOUNT SPLIT PAYMENT ───────────────────────────────────── */
function psOn(){var c=E('ps-toggle');return !!(c&&c.checked);}
function payTypeAmount(){
  var type=(E('tx-type')&&E('tx-type').value||'').toLowerCase();
  var deductByAmount=['supplier payment','purchase payment','advance to supplier','purchase advance','payment refund'];
  if(deductByAmount.indexOf(type)>=0) return num(E('tx-amt')&&E('tx-amt').value);
  // BUGFIX: this always read tx-paid, even for Sale / Customer Sale /
  // Warehouse Sale / receipt-style types where the money coming IN is
  // recorded in tx-recv, not tx-paid. Split-payment validation (psValidate)
  // compares this figure against the sum of the bank-split rows, so on a
  // sale it was comparing the split total to ৳0 (tx-paid, always blank on a
  // sale) and rejecting every "Receive from multiple bank accounts" split
  // no matter how correctly it was filled in. Use whichever of the two the
  // form actually has a value in, preferring tx-recv for receiving types.
  var receiveTypes=['sale','customer sale','warehouse sale','sales receipt','sales advance',
    'advance from customer','customer collection','customer payment received','customer due'];
  var paid=num(E('tx-paid')&&E('tx-paid').value), recv=num(E('tx-recv')&&E('tx-recv').value);
  if(receiveTypes.indexOf(type)>=0) return recv||paid;
  return paid||recv;
}
function accOptions(sel){
  return '<option value="">-- Select Account --</option>'+banks().map(function(b){
    return '<option value="'+b.name+'"'+(sel===b.name?' selected':'')+'>'+b.name+' (৳'+money(b.bal)+')</option>';
  }).join('');
}
// Public hook: refresh every split-payment / refund bank <select> so newly
// added or renamed bank accounts (and updated balances) show up immediately,
// without requiring the payment-split UI to be closed and reopened.
window.refreshSplitBankDropdowns=function(){
  try{
    if(E('ps-rows')) renderPS();
    var rf=E('tx-refund-acc');
    if(rf){ var cur=rf.value; rf.innerHTML=accOptions(cur); }
  }catch(e){}
};
function ensurePSUI(){
  var acc=E('tx-acc');
  if(!acc||E('ps-wrap')) return;
  var host=acc.parentNode;
  var w=document.createElement('div');
  w.id='ps-wrap';
  w.style.cssText='grid-column:1/-1;margin-top:8px;border-top:2px dashed #2563eb;padding-top:10px;';
  w.innerHTML=
   '<div style="display:flex;flex-wrap:wrap;gap:12px;align-items:center;">'+
   '<label style="display:flex;align-items:center;gap:8px;font-size:12px;font-weight:800;color:#1e3a8a;cursor:pointer;">'+
   '<input type="checkbox" id="ps-toggle"> 🏦 Pay from multiple bank accounts (split)</label>'+
   '<button type="button" id="ps-newacc" style="background:#eff6ff;color:#1d4ed8;border:1px solid #bfdbfe;border-radius:6px;padding:5px 10px;font-size:11px;font-weight:700;cursor:pointer;">+ Add Bank Account</button>'+
   '</div>'+
   '<div id="pssplit-body" style="display:none;margin-top:10px;">'+
   '<div id="ps-rows"></div>'+
   '<button type="button" id="ps-add" style="margin-top:8px;background:#2563eb;color:#fff;border:0;border-radius:6px;padding:6px 12px;font-size:11px;font-weight:700;cursor:pointer;">+ Add Account Line</button>'+
   '<div id="ps-sum" style="margin-top:8px;font-size:11px;font-weight:700;"></div></div>';
  host.parentNode.insertBefore(w,host.nextSibling);
  E('ps-toggle').addEventListener('change',function(){
    E('pssplit-body').style.display=this.checked?'':'none';
    if(this.checked&&!PS.length) PS=[{acc:'',amt:0},{acc:'',amt:0}];
    var a=E('tx-acc'); if(a){a.disabled=this.checked;a.style.background=this.checked?'#f3f4f6':'';}
    renderPS();
  });
  E('ps-add').addEventListener('click',function(){PS.push({acc:'',amt:0});renderPS();});
  E('ps-newacc').addEventListener('click',addBankAccountQuick);
  renderPS();
}
function addBankAccountQuick(){
  var name=prompt('New bank / cash account name:');
  if(!name) return;
  name=name.trim(); if(!name) return;
  if(banks().some(function(b){return b.name===name;})){say('That account already exists','e');return;}
  var bal=num(prompt('Opening balance for "'+name+'" (৳):','0'));
  if(!window.DB.banks) DB.banks=[];
  /* FIX (2026-08-20): openingBal must be set too, not just bal — the
     boot-time drift repair (see ayan-v2-enhancements' recomputeBalances)
     only trusts openingBal as the starting point and silently overwrites
     bal from openingBal + transaction history on every reload. An account
     created with only bal set would have its starting money reset to 0 the
     next time the app loads. */
  DB.banks.push({id:newId(),name:name,bankName:'',type:'Current',accountNo:'',branch:'',bal:bal,openingBal:bal});
  try{saveDB();}catch(e){}
  try{if(typeof renderBanks==='function')renderBanks();}catch(e){}
  ['tx-acc','tx-acc2','tx-refund-acc'].forEach(function(id){
    var s=E(id); if(s&&s.tagName==='SELECT'){var cur=s.value;s.innerHTML=accOptions(cur);}
  });
  renderPS();
  say('Account "'+name+'" added','s');
}
// BUGFIX: renderPS() below wires every split-payment row input to this
// handler via addEventListener, but the function was never defined — every
// keystroke in a "Pay from multiple bank accounts" row threw
// "onPSInput is not defined" in the console, PS[] was never updated, the
// split total stayed stuck at ৳0, and psValidate() then always rejected the
// save ("Split total ৳0 does not match..."). This is why multi-bank split
// payments looked available in the UI but could never actually be saved.
function onPSInput(e){
  var i=+e.target.getAttribute('data-ps'), k=e.target.getAttribute('data-k');
  if(!PS[i]) return;
  PS[i][k]=(k==='acc')?e.target.value:num(e.target.value);
  renderPS();
}
function renderPS(){
  var host=E('ps-rows'); if(!host) return;
  host.innerHTML=PS.map(function(r,i){
    var avail=bankBal(r.acc), short=r.acc&&num(r.amt)>avail;
    return '<div style="display:flex;gap:8px;align-items:center;margin-bottom:6px;flex-wrap:wrap;">'+
      '<select data-ps="'+i+'" data-k="acc" style="flex:1;min-width:180px;padding:6px 8px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;">'+accOptions(r.acc)+'</select>'+
      '<input type="number" step="0.01" min="0" data-ps="'+i+'" data-k="amt" value="'+(num(r.amt)||'')+'" placeholder="Amount ৳" style="width:130px;padding:6px 8px;border:1px solid '+(short?'#dc2626':'#d1d5db')+';border-radius:6px;font-size:12px;">'+
      '<span style="font-size:11px;font-weight:700;color:'+(short?'#dc2626':'#16a34a')+';">'+(r.acc?(short?'⛔ Only ৳'+money(avail)+' available':'✔ Available ৳'+money(avail)):'')+'</span>'+
      '<button type="button" data-psdel="'+i+'" style="background:#fee2e2;color:#b91c1c;border:0;border-radius:4px;padding:4px 8px;cursor:pointer;">✕</button>'+
    '</div>';}).join('');
  Array.prototype.forEach.call(host.querySelectorAll('[data-ps]'),function(el){
    el.addEventListener('input',onPSInput); el.addEventListener('change',onPSInput);
  });
  Array.prototype.forEach.call(host.querySelectorAll('[data-psdel]'),function(b){
    b.addEventListener('click',function(){PS.splice(+b.getAttribute('data-psdel'),1);renderPS();});
  });
  var need=payTypeAmount(), got=PS.reduce(function(s,r){return s+num(r.amt);},0);
  var sum=E('ps-sum');
  if(sum) sum.innerHTML='Split total: <span style="color:'+(Math.abs(got-need)<0.01?'#16a34a':'#dc2626')+';">৳'+money(got)+
    '</span> / Payment amount: ৳'+money(need)+(Math.abs(got-need)<0.01?' ✔ matched':' — must match before saving');
}
function psValidate(){
  if(!psOn()) return {ok:true};
  var need=payTypeAmount();
  var total=0, byAcc={};
  for(var i=0;i<PS.length;i++){
    var r=PS[i], a=num(r.amt);
    if(!r.acc&&!a) continue;
    if(!r.acc) return {ok:false,msg:'Select an account for every payment line.'};
    if(a<=0) return {ok:false,msg:'Enter an amount for account "'+r.acc+'".'};
    byAcc[r.acc]=(byAcc[r.acc]||0)+a; total+=a;
  }
  if(!total) return {ok:false,msg:'Add at least one account with an amount.'};
  for(var k in byAcc){
    if(byAcc[k]>bankBal(k)+0.001)
      return {ok:false,msg:'⛔ "'+k+'" has only ৳'+money(bankBal(k))+' — cannot pay ৳'+money(byAcc[k])+' from it.'};
  }
  if(Math.abs(total-need)>0.01)
    return {ok:false,msg:'Split total ৳'+money(total)+' does not match the payment amount ৳'+money(need)+'.'};
  return {ok:true,rows:PS.filter(function(r){return r.acc&&num(r.amt)>0;}).map(function(r){return {acc:r.acc,amt:num(r.amt)};})};
}
function singleAccValidate(){
  if(psOn()) return {ok:true};
  var need=payTypeAmount(), acc=(E('tx-acc')&&E('tx-acc').value||'').trim();
  var type=(E('tx-type')&&E('tx-type').value||'').toLowerCase();
  /* FIX (money-in): this guard exists to stop money being paid OUT of an
     account that does not hold it. It used to run on every type except
     'payment refund', so receiving money was blocked as well — a Bank
     Deposit, Partner Fund, Customer Collection, Bkash Receive or Opening
     Bank Balance into an empty account was refused with "has only ৳0",
     which meant a new account could never be funded at all. Incoming
     money is now exempt, via the shared AYAN_MONEY_IN list. */
  if(window.AYAN_MONEY_IN && window.AYAN_MONEY_IN.has(type)) return {ok:true};
  if(type==='payment refund') return {ok:true};   // refund adds money in
  if(!need||!acc) return {ok:true};
  if(need>bankBal(acc)+0.001)
    return {ok:false,msg:'⛔ "'+acc+'" has only ৳'+money(bankBal(acc))+'. Payment of ৳'+money(need)+
      ' cannot be taken from this account — tick "Pay from multiple bank accounts" to split it.'};
  return {ok:true};
}

/* ── 5. PAYMENT REFUND ────────────────────────────────────────────────── */
function addRefundType(){
  Array.prototype.forEach.call(document.querySelectorAll('select#tx-type, select[id="tx-type"]'),function(sel){
    if(Array.prototype.some.call(sel.options,function(o){return o.value==='Payment Refund';})) return;
    var grp=Array.prototype.filter.call(sel.querySelectorAll('optgroup'),function(g){return /Purchase/.test(g.label);})[0];
    var o=document.createElement('option'); o.value='Payment Refund'; o.textContent='Payment Refund';
    (grp||sel).appendChild(o);
  });
}
function ensureRefundUI(){
  var acc=E('tx-acc');
  if(!acc||E('rf-wrap')) return;
  var host=E('ps-wrap')||acc.parentNode;
  var w=document.createElement('div');
  w.id='rf-wrap';
  w.style.cssText='grid-column:1/-1;display:none;margin-top:10px;border:2px solid #f59e0b;background:#fffbeb;border-radius:10px;padding:12px;';
  w.innerHTML=
   '<div style="font-size:12px;font-weight:800;color:#92400e;margin-bottom:10px;">↩️ Payment Refund Details</div>'+
   '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:10px;">'+
   '<div><label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Refund Received In Account *</label>'+
   '<select id="tx-refund-acc" style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;"></select></div>'+
   '<div><label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Refund Amount (৳) *</label>'+
   '<input type="number" min="0" step="0.01" id="tx-refund-amt" placeholder="0.00" style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;"></div>'+
   '<div style="grid-column:span 2;"><label style="font-size:11px;font-weight:700;color:#374151;display:block;margin-bottom:4px;">Against Supplier Payment *</label>'+
   '<select id="tx-refund-ref" style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;"></select>'+
   '<div style="font-size:10px;color:#92400e;margin-top:4px;">The selected payment is excluded from the supplier\'s paid total by the refunded amount.</div></div>'+
   '</div>';
  host.parentNode.insertBefore(w,host.nextSibling);
  E('tx-refund-acc').innerHTML=accOptions('');
  E('tx-refund-amt').addEventListener('input',function(){
    var a=E('tx-amt'); if(a){a.value=num(this.value)?num(this.value).toFixed(2):'';fire(a);}
  });
  var pty=E('tx-party'); if(pty){pty.addEventListener('change',fillRefundRefs);pty.addEventListener('input',fillRefundRefs);}
}
function fillRefundRefs(){
  var sel=E('tx-refund-ref'); if(!sel) return;
  var party=(E('tx-party')&&E('tx-party').value||'').trim();
  var PAY=['Supplier Payment','Purchase Payment','Advance to Supplier','Purchase Advance'];
  var list=((window.DB&&DB.tx)||[]).filter(function(t){
    return t.party===party && PAY.indexOf(t.type)>=0;
  }).sort(function(a,b){return (b.date||'').localeCompare(a.date||'');});
  var cur=sel.value;
  sel.innerHTML='<option value="">-- Select the payment being refunded --</option>'+list.map(function(t){
    var already=num(t.refundedAmt);
    return '<option value="'+t.id+'"'+(String(t.id)===cur?' selected':'')+'>'+(t.date||'')+' · '+t.type+' · ৳'+money(t.amount||t.amt)+
      (already?' (already refunded ৳'+money(already)+')':'')+(t.inv?' · '+t.inv:'')+'</option>';
  }).join('');
}
function toggleRefundUI(){
  var w=E('rf-wrap'); if(!w) return;
  var isRefund=((E('tx-type')&&E('tx-type').value)||'')==='Payment Refund';
  w.style.display=isRefund?'':'none';
  if(isRefund){ fillRefundRefs(); E('tx-refund-acc').innerHTML=accOptions(E('tx-refund-acc').value); }
}
function refundValidate(){
  if(((E('tx-type')&&E('tx-type').value)||'')!=='Payment Refund') return {ok:true};
  var acc=E('tx-refund-acc')&&E('tx-refund-acc').value;
  var amt=num(E('tx-refund-amt')&&E('tx-refund-amt').value);
  var ref=E('tx-refund-ref')&&E('tx-refund-ref').value;
  if(!acc) return {ok:false,msg:'Select the account where the refund was received.'};
  if(amt<=0) return {ok:false,msg:'Enter the refund amount.'};
  if(!ref) return {ok:false,msg:'Select which supplier payment is being refunded.'};
  var src=((window.DB&&DB.tx)||[]).filter(function(t){return String(t.id)===String(ref);})[0];
  if(src){
    var paid=num(src.amount||src.amt), done=num(src.refundedAmt);
    if(amt>paid-done+0.001) return {ok:false,msg:'Refund ৳'+money(amt)+' is more than the un-refunded part of that payment (৳'+money(paid-done)+').'};
  }
  return {ok:true,data:{refundAcc:acc,refundAmt:amt,refundRefId:parseInt(ref,10)}};
}

/* ── HOOKS ────────────────────────────────────────────────────────────── */
var origSaveTx=window.saveTx;
window.saveTx=function(){
  if(mpOn()){
    var rows=MP.filter(function(r){return r.prod||mpWeight(r)||num(r.rate);});
    if(rows.length<2){say('Add at least 2 products, or turn off Multiple Products','e');return;}
    for(var i=0;i<rows.length;i++){
      if(!rows[i].prod){say('Product name missing on line '+(i+1),'e');return;}
      if(!rows[i].bagtype){say('Select a bag type (Jute, Plastic or Bulk) on line '+(i+1),'e');return;}
    }
    MP=rows; syncMPTotals();
  }
  var rf=refundValidate(); if(!rf.ok){say(rf.msg,'e');return;}
  if(rf.data){ var a=E('tx-amt'); if(a&&!num(a.value)) a.value=rf.data.refundAmt.toFixed(2); }
  var s=singleAccValidate(); if(!s.ok){say(s.msg,'e');return;}
  var p=psValidate(); if(!p.ok){say(p.msg,'e');return;}
  window.__txExtras={
    items: mpOn()?MP.map(function(r){return {prod:r.prod,bagtype:r.bagtype,bagqty:num(r.bagqty),qty:num(r.qty),
      grosswt:num(r.grosswt),wt:num(r.wt),rate:num(r.rate),amount:num(r.amount),oilPct:num(r.oilPct),totalOil:num(r.totalOil),
      moisturePct:num(r.moisturePct),proteinPct:num(r.proteinPct),fiberPct:num(r.fiberPct),ashPct:num(r.ashPct),ffaPct:num(r.ffaPct)};}):null,
    payAccounts: p.rows||null,
    refund: rf.data||null
  };
  return origSaveTx.apply(this,arguments);
};

var origExec=window._executeSaveTx;
window._executeSaveTx=function(tx,editId){
  var x=window.__txExtras||{};
  if(x.items){ tx.items=x.items; tx.multiProduct=true; }
  if(x.payAccounts){ tx.payAccounts=x.payAccounts; tx.acc=x.payAccounts[0].acc; tx.splitPayment=true; }
  if(x.refund){
    tx.refundAcc=x.refund.refundAcc; tx.refundAmt=x.refund.refundAmt;
    tx.refundRefId=x.refund.refundRefId; tx.acc=x.refund.refundAcc;
    tx.amount=tx.amt=x.refund.refundAmt;
  }
  window.__txExtras=null;
  var out=origExec.apply(this,arguments);
  // link refund back to the original payment so paid totals exclude it
  recomputeRefunds();
  try{saveDB();}catch(e){}
  return out;
};

function recomputeRefunds(){
  var txs=(window.DB&&DB.tx)||[];
  txs.forEach(function(t){ if(t.refundedAmt) t.refundedAmt=0; });
  txs.forEach(function(t){
    if(t.type!=='Payment Refund'||!t.refundRefId) return;
    var src=txs.filter(function(x){return x.id===t.refundRefId;})[0];
    if(src) src.refundedAmt=num(src.refundedAmt)+num(t.refundAmt||t.amount);
  });
}

var origApply=window.applyTxBalance;
window.applyTxBalance=function(tx,dir){
  var type=(tx.type||'').toLowerCase();
  function adjBank(name,delta){
    if(!name) return;
    var b=((window.DB&&DB.banks)||[]).filter(function(x){return x.name===name;})[0];
    if(b) b.bal=num(b.bal)+delta;
  }
  function adjParty(name,delta){
    if(!name) return;
    var c=((window.DB&&DB.customers)||[]).filter(function(x){return x.name===name;})[0];
    if(c) c.bal=num(c.bal)+delta;
  }
  if(type==='payment refund'){
    var amt=num(tx.refundAmt||tx.amount)*dir;
    adjBank(tx.refundAcc||tx.acc,amt);      // money back into our account
    adjParty(tx.party,-amt);                // supplier due restored
    return;
  }
  if(tx.payAccounts&&tx.payAccounts.length){
    var banks=(window.DB&&DB.banks)||[];
    var probeName='__SPLIT_PROBE__'+Date.now()+'_'+Math.random();
    var probe={name:probeName,bal:0,__probe:true};
    banks.push(probe);
    var clone={}; for(var k in tx) clone[k]=tx[k];
    clone.acc=probeName;                     // route single-account effect to probe
    var r;
    try{ r=origApply.call(this,clone,dir); }
    finally{
      var delta=num(probe.bal);              // signed: +in / -out for this tx type
      var i=banks.indexOf(probe); if(i>-1) banks.splice(i,1);
      var rows=tx.payAccounts.filter(function(p){return p&&p.acc;});
      var total=0; rows.forEach(function(p){ total+=Math.abs(num(p.amt)); });
      if(delta!==0&&rows.length){
        if(total>0){
          var used=0;
          rows.forEach(function(p,idx){
            var part=(idx===rows.length-1)?(delta-used):(delta*Math.abs(num(p.amt))/total);
            used+=part;
            adjBank(p.acc,part);             // same direction as the tx type
          });
        }else{
          rows.forEach(function(p){ adjBank(p.acc,delta/rows.length); });
        }
      }
    }
    return r;
  }
  return origApply.apply(this,arguments);
};

var origValidateBal=window.validateBankBalance;
window.validateBankBalance=function(tx){
  if((tx.type||'').toLowerCase()==='payment refund') return {valid:true};
  if(tx.payAccounts&&tx.payAccounts.length){
    // Does this tx type deduct from the bank at all? Probe with a zero-balance account.
    var probe={}; for(var k in tx) probe[k]=tx[k];
    delete probe.payAccounts;
    probe.acc='__VAL_PROBE__';
    var banks=(window.DB&&DB.banks)||[];
    banks.push({name:'__VAL_PROBE__',bal:0});
    var res;
    try{ res=origValidateBal.call(this,probe); }
    finally{
      for(var j=banks.length-1;j>=0;j--) if(banks[j].name==='__VAL_PROBE__') banks.splice(j,1);
    }
    if(res&&res.valid===false){
      // outgoing: every split account must cover its own share
      var rows=(tx.payAccounts||[]).filter(function(p){return p&&p.acc;});
      for(var i=0;i<rows.length;i++){
        var need=Math.abs(num(rows[i].amt));
        if(need<=0) continue;
        var chk=(typeof window.checkBankBalance==='function')?window.checkBankBalance(rows[i].acc,need):{ok:true};
        if(chk&&chk.ok===false) return {valid:false,acc:rows[i].acc,required:need,available:chk.bal};
      }
    }
    return {valid:true};
  }
  return origValidateBal.apply(this,arguments);
};

var origEdit=window.editTx;
if(origEdit) window.editTx=function(id){
  var r=origEdit.apply(this,arguments);
  setTimeout(function(){
    var tx=((window.DB&&DB.tx)||[]).filter(function(t){return t.id===id;})[0];
    mount();
    if(!tx) return;
    if(tx.items&&tx.items.length){
      MP=tx.items.map(function(r){var o=mpRow();for(var k in r)o[k]=r[k];return o;});
      var c=E('mp-toggle'); if(c&&!c.checked){c.checked=true;c.dispatchEvent(new Event('change'));}
    }
    if(tx.payAccounts&&tx.payAccounts.length){
      PS=tx.payAccounts.map(function(p){return {acc:p.acc,amt:p.amt};});
      var c2=E('ps-toggle'); if(c2&&!c2.checked){c2.checked=true;c2.dispatchEvent(new Event('change'));}
    }
    if(tx.type==='Payment Refund'){
      toggleRefundUI();
      if(E('tx-refund-acc')) E('tx-refund-acc').innerHTML=accOptions(tx.refundAcc||tx.acc);
      if(E('tx-refund-amt')) E('tx-refund-amt').value=tx.refundAmt||tx.amount||'';
      fillRefundRefs();
      if(E('tx-refund-ref')) E('tx-refund-ref').value=tx.refundRefId||'';
    }
  },60);
  return r;
};

/* ── MOUNT / RESET ────────────────────────────────────────────────────── */
function mount(){
  if(!E('tx-type')) return;
  addRefundType();
  upgradeBagType();
  ensureMPUI();
  ensurePSUI();
  ensureRefundUI();
  var acc=E('tx-acc');
  if(acc&&acc.tagName==='SELECT'&&!acc.dataset.psBound){
    acc.dataset.psBound='1';
  }
  var t=E('tx-type');
  if(t&&!t.dataset.rfBound){ t.dataset.rfBound='1'; t.addEventListener('change',function(){toggleRefundUI();renderPS();}); }
  ['tx-amt','tx-paid'].forEach(function(id){
    var el=E(id);
    if(el&&!el.dataset.psBound){ el.dataset.psBound='1'; el.addEventListener('input',renderPS); }
  });
  toggleRefundUI();
}
window.resetPurchaseEnhancements=function(){
  MP=[]; PS=[];
  var m=E('mp-toggle'); if(m&&m.checked){m.checked=false;m.dispatchEvent(new Event('change'));}
  var p=E('ps-toggle'); if(p&&p.checked){p.checked=false;p.dispatchEvent(new Event('change'));}
  lockMain(false);
  var r=E('rf-wrap'); if(r) r.style.display='none';
};
['openTxModal','newTx','openTx','txNew'].forEach(function(fn){
  if(typeof window[fn]==='function'){
    var o=window[fn];
    window[fn]=function(){var res=o.apply(this,arguments);setTimeout(function(){window.resetPurchaseEnhancements();mount();},50);return res;};
  }
});
if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',function(){setTimeout(mount,300);});
else setTimeout(mount,300);
window._erpWatch(mount);   // FIX 8: DOM-mutation driven instead of a 1.5s poll
})();
</script>

<!-- ═══════════════════════════════════════════════════════════════
     UI POLISH — Brightness + Click Feedback
     Purely additive: brighter hover glow on buttons/cards/nav, and
     a satisfying ripple animation on click for every clickable
     element. Uses one delegated listener, so it works on anything
     rendered dynamically too — nothing else in the app needed to
     change.
     ═══════════════════════════════════════════════════════════════ -->
<style>
/* Brighter hover glow — layers on top of existing hover rules,
   doesn't replace them. */
.btn:hover, button.btn:hover{filter:brightness(1.12) saturate(1.15);box-shadow:0 6px 18px rgba(22,163,74,.28);}
.kpi-card:hover, .adv-kpi:hover, .card:hover{filter:brightness(1.03);}
.nav-item:hover{filter:brightness(1.15);}
.adv-kpi{position:relative;overflow:hidden;}

/* Click ripple */
.ui-ripple{
  position:absolute; border-radius:50%; pointer-events:none;
  background:rgba(255,255,255,.55);
  transform:scale(0); opacity:.9;
  animation:ui-ripple-anim .5s ease-out forwards;
}
[data-theme="dark"] .ui-ripple{ background:rgba(255,255,255,.25); }
@keyframes ui-ripple-anim{
  to{ transform:scale(2.6); opacity:0; }
}
/* Elements this applies to need relative positioning + clipped overflow
   so the ripple stays inside the shape it was clicked on. */
.btn, button.btn, .kpi-card, .adv-kpi, .nav-item, .kpi-card *, .adv-kpi * { position:relative; }
.btn, button.btn, .kpi-card, .adv-kpi, .nav-item { overflow:hidden; }
</style>
<script nonce="<?php echo $cspNonceAttr; ?>">
(function(){
  'use strict';
  var RIPPLE_SELECTOR = '.btn, button.btn, .kpi-card, .adv-kpi, .nav-item';
  document.addEventListener('click', function(e){
    var target = e.target.closest ? e.target.closest(RIPPLE_SELECTOR) : null;
    if(!target) return;
    var rect = target.getBoundingClientRect();
    var size = Math.max(rect.width, rect.height);
    var span = document.createElement('span');
    span.className = 'ui-ripple';
    span.style.width = span.style.height = size + 'px';
    span.style.left = (e.clientX - rect.left - size/2) + 'px';
    span.style.top = (e.clientY - rect.top - size/2) + 'px';
    target.appendChild(span);
    span.addEventListener('animationend', function(){ span.remove(); });
    // Safety cleanup in case animationend doesn't fire (e.g. element removed mid-click)
    setTimeout(function(){ if(span.parentNode) span.remove(); }, 700);
  }, true);
})();
</script>


