/* ── Sidebar refinement ─────────────────────────────────────────────────── */
.sidebar{
  background:linear-gradient(180deg,rgba(255,255,255,.72) 0%,rgba(214,247,226,.62) 42%,rgba(163,235,192,.60) 100%) !important;
  backdrop-filter:saturate(200%) blur(34px) !important;
