  box-shadow:0 8px 18px -12px rgba(11,31,20,.5), inset 0 1px 0 rgba(255,255,255,.9) !important;
}
.nav-item.active::before{
  content:"";position:absolute;left:-4px;top:50%;transform:translateY(-50%);
  width:3px;height:56%;border-radius:3px;background:var(--g-brand);
}
.nav-label{color:var(--g-brand-deep) !important;opacity:.62 !important;font-size:9.5px !important;letter-spacing:.14em !important;}
.nav-badge{background:rgba(15,157,82,.14) !important;color:var(--g-brand-deep) !important;font-weight:700 !important;}
.nav-search-input{background:rgba(255,255,255,.66) !important;border:1px solid var(--g-hair) !important;border-radius:10px !important;color:var(--g-ink) !important;}

/* ── Buttons ────────────────────────────────────────────────────────────── */
.btn{
  border-radius:11px !important;font-weight:600 !important;letter-spacing:-.01em !important;
  border:1px solid transparent !important;
  transition:transform .18s cubic-bezier(.22,1,.36,1), box-shadow .22s, filter .2s, background .2s !important;
}
.btn:hover{transform:translateY(-1px);}
.btn:active{transform:translateY(0) scale(.985);}
.btn-primary{
  background:linear-gradient(180deg,#22b56a,#0f9d52) !important;color:#fff !important;
  box-shadow:0 8px 20px -10px rgba(15,157,82,.85), inset 0 1px 0 rgba(255,255,255,.35) !important;
}
.btn-primary:hover{filter:brightness(1.05);background:linear-gradient(180deg,#28c274,#12a959) !important;}
.btn-success{background:linear-gradient(180deg,#2fbf74,#12924f) !important;color:#fff !important;box-shadow:0 8px 20px -10px rgba(18,146,79,.8), inset 0 1px 0 rgba(255,255,255,.35) !important;}
.btn-danger{background:linear-gradient(180deg,#f2564f,#d93a35) !important;color:#fff !important;box-shadow:0 8px 20px -10px rgba(217,58,53,.8), inset 0 1px 0 rgba(255,255,255,.3) !important;}
.btn-warning{background:linear-gradient(180deg,#f0a92c,#d68b14) !important;color:#fff !important;box-shadow:0 8px 20px -10px rgba(214,139,20,.8), inset 0 1px 0 rgba(255,255,255,.3) !important;}
.btn-outline,.btn-ghost,.btn-icon{
  background:rgba(255,255,255,.62) !important;
  backdrop-filter:blur(14px) saturate(180%) !important;
  border:1px solid var(--g-hair) !important;color:var(--g-ink) !important;
  box-shadow:0 6px 16px -12px rgba(11,31,20,.5) !important;
}
.btn-outline:hover,.btn-ghost:hover,.btn-icon:hover{background:rgba(255,255,255,.86) !important;color:var(--g-brand-deep) !important;}

/* ── Tables ─────────────────────────────────────────────────────────────── */
.table-card{overflow:hidden !important;}
.table-header{
  background:#f8fafc !important;
  border-bottom:1px solid var(--g-line) !important;
}
.table-title,.chart-title{font-weight:650 !important;letter-spacing:-.02em !important;color:var(--g-ink) !important;}
.tbl{border-collapse:separate !important;border-spacing:0 !important;}
.tbl th{
  background:#eefcf3 !important;
  color:var(--g-ink-soft) !important;font-size:10.5px !important;font-weight:650 !important;
  letter-spacing:.07em !important;text-transform:uppercase !important;
  border-bottom:1px solid var(--g-line) !important;position:sticky;top:0;z-index:2;
}
.tbl td{border-bottom:1px solid rgba(15,23,42,.10) !important;color:var(--g-ink) !important;}
.tbl tbody tr{transition:background .16s ease !important;}
.tbl tbody tr:hover{background:#f1f5f9 !important;}
.td-num{font-variant-numeric:tabular-nums;font-feature-settings:"tnum";}

/* ── Badges / chips ─────────────────────────────────────────────────────── */
.badge{
  border-radius:999px !important;font-weight:600 !important;font-size:10.5px !important;
  letter-spacing:.01em !important;border:1px solid var(--g-hair) !important;
  backdrop-filter:blur(8px) !important;
}

/* ── Forms ──────────────────────────────────────────────────────────────── */
input,select,textarea,.fc,.um-input{
  border-radius:11px !important;
  background:rgba(255,255,255,.72) !important;
  border:1px solid var(--g-hair) !important;
  color:var(--g-ink) !important;
  transition:border-color .18s, box-shadow .18s, background .18s !important;
}
input:focus,select:focus,textarea:focus,.fc:focus,.um-input:focus{
  outline:none !important;background:rgba(255,255,255,.94) !important;
  border-color:rgba(15,157,82,.6) !important;
  box-shadow:0 0 0 4px rgba(15,157,82,.16) !important;
}
.lbl,.um-label,.fg > label{color:var(--g-ink-soft) !important;font-weight:600 !important;font-size:11.5px !important;letter-spacing:.01em !important;}
.form-section{padding-block:14px;}
.form-section-title{color:var(--g-brand-deep) !important;font-weight:650 !important;letter-spacing:.04em !important;}

/* ── Modals ─────────────────────────────────────────────────────────────── */
.overlay{
  background:rgba(11,31,20,.32) !important;
  backdrop-filter:blur(14px) saturate(150%) !important;
}
.modal{
  background:rgba(255,255,255,.82) !important;
  backdrop-filter:saturate(200%) blur(40px) !important;
  border:1px solid rgba(255,255,255,.8) !important;
  border-radius:22px !important;
  box-shadow:0 40px 100px -30px rgba(11,31,20,.5), inset 0 1px 0 rgba(255,255,255,.9) !important;
  animation:gGlassIn .38s cubic-bezier(.22,1,.36,1) both;
}
@keyframes gGlassIn{from{opacity:0;transform:translateY(14px) scale(.975);}to{opacity:1;transform:none;}}
.modal-header{
  background:rgba(255,255,255,.5) !important;backdrop-filter:blur(12px) !important;
  border-bottom:1px solid var(--g-line) !important;
}
.modal-title{font-weight:680 !important;letter-spacing:-.02em !important;color:var(--g-ink) !important;}
.modal-close{border-radius:999px !important;background:rgba(11,31,20,.06) !important;color:var(--g-ink-soft) !important;border:none !important;transition:background .18s,color .18s !important;}
.modal-close:hover{background:rgba(242,86,79,.14) !important;color:#d93a35 !important;}

/* ── Page header & misc ─────────────────────────────────────────────────── */
.page-header{border-bottom:1px solid var(--g-line) !important;}
.page-header h1,.page-header h2{letter-spacing:-.028em !important;font-weight:700 !important;color:var(--g-ink) !important;}
.text-muted{color:var(--g-ink-soft) !important;}
hr{border:none;border-top:1px solid var(--g-line);}

/* Bottom nav (mobile) */
.bottom-nav,.pb-btn{backdrop-filter:saturate(200%) blur(28px) !important;}
.bottom-nav{background:rgba(255,255,255,.72) !important;border-top:1px solid var(--g-hair) !important;}

/* Scrollbars */
*::-webkit-scrollbar{width:9px;height:9px;}
*::-webkit-scrollbar-thumb{background:rgba(11,31,20,.18);border-radius:99px;border:2px solid transparent;background-clip:content-box;}
*::-webkit-scrollbar-thumb:hover{background:rgba(15,157,82,.45);background-clip:content-box;}
*::-webkit-scrollbar-track{background:transparent;}

/* Page transition */
.page.active{animation:gPageIn .42s cubic-bezier(.22,1,.36,1) both;}
@keyframes gPageIn{from{opacity:0;transform:translateY(8px);}to{opacity:1;transform:none;}}

@media (prefers-reduced-motion:reduce){
  *{animation-duration:.01ms !important;transition-duration:.01ms !important;}
}
@media print{
  body{background:#fff !important;}
  .card,.kpi-card,.table-card,.chart-card{backdrop-filter:none !important;background:#fff !important;box-shadow:none !important;}
}
</style>

<style id="apple-glass-final-b">
/* ── KPI tiles: tinted liquid glass instead of loud solid gradients ─────── */
.kpi-card.c-blue,.kpi-card.c-green,.kpi-card.c-purple,.kpi-card.c-orange,
