<script nonce="<?php echo $cspNonceAttr; ?>">
/* Keep the glass layer last so late script-injected themes can't override it. */
(function(){
  function lift(){
    ['apple-glass-final-2026','apple-glass-final-b','lux-kpi-v2'].forEach(function(id){
      var el=document.getElementById(id);
      if(el && el.parentNode!==document.body || (el && el!==document.body.lastElementChild)){
        try{ document.body.appendChild(el); }catch(e){}
      }
    });
  }
  var SURFACE=/(^|[\s,>+~])\.(card|kpi-card|adv-kpi|chart-card|table-card|panel|modal|overlay|topbar|page-header|table-header|form-section|tbl|content|page|widget|tile|surface|box)\b/;
  function unblock(){
    var mine={'apple-glass-final-2026':1,'apple-glass-final-b':1,'lux-kpi-v2':1};
    [].forEach.call(document.querySelectorAll('style,link'),function(node){
      if(node.id && mine[node.id]) return;
      var sh=node.sheet; if(!sh) return;
      try{
        [].forEach.call(sh.cssRules,function(r){
          if(!r.selectorText || !r.style) return;
          var sel=r.selectorText;
          if(/(^|,)\s*(nav|aside\.nav)\s*(,|$)/.test(sel) && /\.sidebar/.test(sel)){
            ['background','background-image','background-color','color','box-shadow','border'].forEach(function(p){ r.style.removeProperty(p); });
            return;
          }
          if(SURFACE.test(sel)){
            ['background','background-image','background-color','box-shadow','border','border-color','backdrop-filter','color'].forEach(function(p){ r.style.removeProperty(p); });
          }
        });
      }catch(e){}
    });
  }
  var _lift0=lift; lift=function(){ _lift0(); unblock(); };
  if(document.readyState!=='loading') lift(); else document.addEventListener('DOMContentLoaded',lift);
  window.addEventListener('load',lift);
  [300,1200,3000].forEach(function(t){ setTimeout(lift,t); });
})();
</script>


