<script nonce="<?php echo $cspNonceAttr; ?>">
/* ══════════════════════════════════════════════════════════════
   FINAL MERGE APPENDIX (from gemini-code fragment)
   Only non-conflicting additions. The existing server-auth layer
   (doLogin / doLogout / saveDB / loadDB) is left untouched.
   ══════════════════════════════════════════════════════════════ */
(function(){
  // ── Ensure every DB collection exists (safe defaults) ──
  window.initializeDBDefaults = function(){
    if(typeof DB === 'undefined' || !DB) return;
    ['tx','users','customers','partners','banks','inventory','auditLog','tenders',
     'assets','products','employees','agents','agentLedger','orders','expenses',
     'payroll','salaryHistory','empAdvances','leaves','attendance','recurring',
     'notifications','customTemplates'].forEach(function(k){ if(!DB[k]) DB[k] = []; });
    if(!DB.settings) DB.settings = {};
    if(!DB.nid) DB.nid = {};
  };
  try{ window.initializeDBDefaults(); }catch(e){}
  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', function(){ try{ window.initializeDBDefaults(); }catch(e){} });
  }

  // ── Escape closes any open .modal (overlays already handled) ──
  document.addEventListener('keydown', function(e){
    if(e.key !== 'Escape') return;
    document.querySelectorAll('.modal').forEach(function(m){
      m.classList.remove('open');
      if(m.style) m.style.display = 'none';
    });
  });

  // ── Audit-log renderer for the User Management activity panel ──
  window.renderActivityFeed = function(){
    var wrap = document.getElementById('um-activity-body');
    if(!wrap) return;
    var logs = (typeof DB !== 'undefined' && DB.auditLog) ? DB.auditLog : [];
    if(!logs.length){
      wrap.innerHTML = '<div style="text-align:center;padding:30px;color:#9ca3af;">No activity recorded yet.</div>';
      return;
    }
    var colors = {CREATE:'#16a34a',UPDATE:'#2563eb',DELETE:'#dc2626',LOGIN:'#0891b2',
                  SECURITY:'#ea580c',EXPORT:'#7c3aed',IMPORT:'#d97706'};
    wrap.innerHTML = logs.slice(0,50).map(function(log){
      var c = colors[log.action] || '#6b7280';
      var time = log.timestamp ? new Date(log.timestamp).toLocaleString('en-BD') : '';
      return '<div style="display:flex;align-items:flex-start;gap:12px;padding:10px 0;border-bottom:1px solid #f3f4f6;">'
        + '<div style="padding:4px 8px;border-radius:6px;font-size:10px;font-weight:800;color:'+c+';background:'+c+'1a;min-width:60px;text-align:center;">'+(log.action||'')+'</div>'
        + '<div style="flex:1;"><div style="font-size:12px;color:#111827;">'+(log.details||log.description||'')+'</div>'
        + '<div style="font-size:10px;color:#6b7280;margin-top:2px;">'+(log.module||'')+' • By '+(log.user||'System')+'</div></div>'
        + '<div style="font-size:10px;color:#9ca3af;">'+time+'</div></div>';
    }).join('');
  };
})();
</script>

<script nonce="<?php echo $cspNonceAttr; ?>">
/* ── Persistence → UI sync ──────────────────────────────────────────────
   saveDB() only persists DB; call sites that forgot to re-render left the
   Transactions / Payroll / Inventory / VAT / Bank Reconciliation views showing
   stale numbers. Wrap saveDB once and re-render the active page (plus the
   always-visible dashboard widgets) after every save. */
(function(){
  var _origSave = window.saveDB;
  var _timer = null, _refreshing = false;

  function refreshUI(){
    if(_refreshing) return;
    _refreshing = true;
    try{
      var pg = window.__navCurrent
        || (document.querySelector('.page.active') || {}).id?.replace(/^pg-/,'')
        || null;
      if(pg && typeof render === 'function') render(pg);
      ['updateSaveIndicator','renderNotifBell','renderAlertsBadge','renderActivityFeed']
        .forEach(function(fn){ if(typeof window[fn] === 'function'){ try{ window[fn](); }catch(e){} } });
    }catch(e){
      console.error('post-save UI refresh failed:', e);
    }finally{
      _refreshing = false;
    }
  }

  window.refreshCurrentPage = refreshUI;

  window.saveDB = function(){
    var out = (typeof _origSave === 'function') ? _origSave.apply(this, arguments) : undefined;
    if(!_refreshing){                 // never re-enter while a render is running
      clearTimeout(_timer);
      _timer = setTimeout(refreshUI, 120);
    }
    return out;
  };
})();
</script>

<style id="ux-polish-layer">
/* ═══════════════════════════════════════════════════════════════════════
   GLOBAL UI/UX POLISH LAYER  (loaded last — refines every page/module)
   Fixes cramped tables, misaligned buttons, broken grids, inconsistent
   typography and spacing, and makes every page fluid on mobile.
   ═══════════════════════════════════════════════════════════════════════ */
:root{
  --ux-radius:12px;
  --ux-border:#e5e7eb;
  --ux-ink:#111827;
  --ux-muted:#6b7280;
  --ux-brand:#0f3d26;
  --ux-brand-2:#16a34a;
  --ux-shadow:0 1px 2px rgba(16,24,40,.04),0 8px 24px -12px rgba(16,24,40,.12);
}
*,*::before,*::after{box-sizing:border-box;}
body{-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility;}
img,canvas,svg,video{max-width:100%;}

/* ── Cards & sections: comfortable padding, clean borders, soft shadow ── */
.card,.panel,.box,.stat-card,.kpi,.widget,.form-section{
  border-radius:var(--ux-radius);
  box-shadow:var(--ux-shadow);
}
.card,.panel,.box,.widget{padding:16px 18px;}
.form-section{padding:14px 16px;border:1px solid var(--ux-border);background:#fff;margin-bottom:14px;}
.form-section-title{font-size:13px;font-weight:800;color:var(--ux-brand);letter-spacing:.2px;margin-bottom:12px;padding-bottom:8px;border-bottom:1px solid #eef2f7;}

/* ── Page headers: never collide with their action buttons ── */
.page-header{
  display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;
  gap:12px;margin-bottom:18px;
}
.page-header>div{min-width:0;}
.page-header h2{font-size:20px;line-height:1.25;font-weight:800;color:var(--ux-brand);margin:0 0 2px;}
.page-header p{font-size:12.5px;color:var(--ux-muted);margin:0;}

/* ── Typography scale consistency ── */
h3{font-size:15px;} h4{font-size:14px;} h5{font-size:13px;}
label,.lbl{font-size:11.5px;font-weight:700;color:#374151;letter-spacing:.15px;}

/* ── Form controls: uniform height, focus ring, no cramped inputs ── */
.fc,input:not([type=checkbox]):not([type=radio]),select,textarea{
  font-size:13px;line-height:1.4;border-radius:8px;
}
.fc,input:not([type=checkbox]):not([type=radio]),select{min-height:38px;}
.fc:focus,input:focus,select:focus,textarea:focus{
  outline:none;border-color:var(--ux-brand-2);
  box-shadow:0 0 0 3px rgba(22,163,74,.14);
}
.fg{min-width:0;}
.form-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:12px 14px;align-items:end;}
.form-grid .span2{grid-column:span 2;}

/* ── Buttons: aligned, tappable, consistent ── */
.btn,button{
  border-radius:8px;font-size:13px;font-weight:700;cursor:pointer;
  display:inline-flex;align-items:center;justify-content:center;gap:6px;
  min-height:38px;padding:8px 16px;white-space:nowrap;
  transition:filter .15s ease,transform .05s ease,box-shadow .15s ease;
}
.btn:hover,button:hover{filter:brightness(1.05);}
.btn:active,button:active{transform:translateY(1px);}
.btn:focus-visible,button:focus-visible{outline:2px solid var(--ux-brand-2);outline-offset:2px;}
.btn-row,.actions,.toolbar,.filters,.filter-bar{display:flex;flex-wrap:wrap;align-items:center;gap:10px;}

/* ── Tables: breathing room, sticky heads, horizontal scroll instead of squeeze ── */
.table-wrap,.tbl-wrap,.table-responsive{width:100%;overflow-x:auto;-webkit-overflow-scrolling:touch;border-radius:var(--ux-radius);}
table{border-collapse:collapse;width:100%;font-size:12.5px;}
table th{
  padding:10px 12px;text-align:left;font-size:11.5px;font-weight:800;
  letter-spacing:.3px;text-transform:none;white-space:nowrap;
}
table td{padding:9px 12px;vertical-align:middle;border-bottom:1px solid #f1f5f9;}
table tbody tr:hover{background:#f8fafc;}
table td.num,table th.num,table td[align=right],table th[align=right]{text-align:right;font-variant-numeric:tabular-nums;}

/* ── Modals: scrollable, centered, never taller than the viewport ── */
.modal,.modal-overlay{padding:16px;}
.modal-box,.modal-content,.modal-card{
  border-radius:14px;max-height:92vh;overflow-y:auto;
  box-shadow:0 24px 64px -24px rgba(16,24,40,.45);
}

/* ── Empty states & muted helper text ── */
.empty,.no-data{padding:28px 16px;text-align:center;color:var(--ux-muted);font-size:13px;}

/* ── Scrollbars (desktop) ── */
@media (min-width:1024px){
  ::-webkit-scrollbar{width:10px;height:10px;}
  ::-webkit-scrollbar-thumb{background:#cbd5e1;border-radius:8px;border:2px solid transparent;background-clip:content-box;}
  ::-webkit-scrollbar-thumb:hover{background:#94a3b8;background-clip:content-box;}
}

/* ── Responsive: tablet ── */
@media (max-width:1024px){
  .form-grid{grid-template-columns:repeat(auto-fill,minmax(180px,1fr));}
  .page-header h2{font-size:18px;}
}

/* ── Responsive: mobile ── */
@media (max-width:720px){
  .card,.panel,.box,.widget{padding:13px 14px;}
  .form-grid{grid-template-columns:1fr;}
  .form-grid .span2,.form-grid .span3{grid-column:span 1;}
  .page-header{align-items:flex-start;flex-direction:column;}
  .page-header .btn,.page-header button{width:100%;}
  .btn-row .btn,.actions .btn,.toolbar .btn{flex:1 1 46%;}
  table{font-size:12px;}
  table th,table td{padding:8px 10px;}
  /* any grid/flex row of stat cards collapses cleanly instead of overflowing */
  [style*="grid-template-columns"]{grid-template-columns:1fr !important;}
  [style*="display:flex"]{flex-wrap:wrap;}
}
@media (max-width:420px){
  .page-header h2{font-size:17px;}
  table th,table td{padding:7px 9px;}
}
@media print{
  .no-print,#sidebar,.sidebar,.topbar,nav{display:none !important;}
  .card,.panel{box-shadow:none;border:1px solid #ddd;}
}
</style>

<script nonce="<?php echo $cspNonceAttr; ?>">
/* ═══════════════════════════════════════════════════════════════════════
   SUPPLIER PAYMENT REFUND MODULE
   Type: "Supplier Refund"
   Inputs: Supplier (party), Bank Account, Refund Amount, Notes
   Accounting: + Bank account ledger (deposit)   − Supplier ledger (payable)
   Saved into DB.tx through the one canonical transaction pipeline, then
   saveDB() fires so every dashboard, ledger and report updates instantly.
   ═══════════════════════════════════════════════════════════════════════ */
(function(){
'use strict';
var TYPE='Supplier Refund';
function E(id){return document.getElementById(id);}
function num(x){var n=parseFloat(x);return isNaN(n)?0:n;}
function money(n){return num(n).toLocaleString('en-IN',{maximumFractionDigits:2});}
function say(m,t){try{toast(m,t||'i');}catch(e){alert(m);}}
function fire(el){if(!el)return;try{el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new Event('change',{bubbles:true}));}catch(e){}}
function isRefund(){return ((E('tx-type')&&E('tx-type').value)||'')===TYPE;}

/* ── 1. Register the type everywhere it can be selected ────────────────── */
function registerType(){
  try{
    window.DB=window.DB||{};
    DB.masterData=DB.masterData||{};
    if(Array.isArray(DB.masterData.txnTypes)&&DB.masterData.txnTypes.indexOf(TYPE)<0)
      DB.masterData.txnTypes.push(TYPE);
  }catch(e){}
  Array.prototype.forEach.call(document.querySelectorAll('select#tx-type,select[id="tx-type"],select[data-txtype]'),function(sel){
    var has=Array.prototype.some.call(sel.options,function(o){return o.value===TYPE||o.textContent.trim()===TYPE;});
    if(has) return;
    var grp=Array.prototype.filter.call(sel.querySelectorAll('optgroup'),function(g){return /Purchase|Supplier/i.test(g.label);})[0];
    var o=document.createElement('option'); o.value=TYPE; o.textContent=TYPE;
    (grp||sel).appendChild(o);
  });
}

/* ── 2. Option lists ──────────────────────────────────────────────────── */
function bankOptions(sel){
  var list=((window.DB&&DB.banks)||[]).map(function(b){return b.name;}).filter(Boolean);
  return '<option value="">-- Select Bank Account --</option>'+list.map(function(n){
    var b=((window.DB&&DB.banks)||[]).filter(function(x){return x.name===n;})[0]||{};
    return '<option value="'+n+'"'+(n===sel?' selected':'')+'>'+n+' (৳'+money(b.bal)+')</option>';
  }).join('');
}
function supplierList(){
  return ((window.DB&&DB.customers)||[]).filter(function(c){
    var t=(c.type||c.ptype||'').toLowerCase();
    return !t||t.indexOf('supplier')>=0||t.indexOf('both')>=0;
  }).map(function(c){return c.name;}).filter(Boolean);
}
function refillLists(){
  var a=E('sr-acc'); if(a) a.innerHTML=bankOptions(a.value);
  var dl=E('sr-dl-supplier');
  if(dl) dl.innerHTML=supplierList().map(function(n){return '<option value="'+String(n).replace(/"/g,'&quot;')+'"></option>';}).join('');
  showDue();
}
function supplierDue(name){
  if(!name) return null;
  try{ if(typeof getSupplierBalance==='function') return getSupplierBalance(name); }catch(e){}
  var c=((window.DB&&DB.customers)||[]).filter(function(x){return x.name===name;})[0];
  return c?num(c.bal):null;
}
function showDue(){
  var box=E('sr-due'); if(!box) return;
  var name=(E('sr-party')&&E('sr-party').value||'').trim();
  if(!name){box.textContent='';return;}
  var bal=supplierDue(name);
  if(bal===null){box.textContent='';return;}
  box.innerHTML=bal<0
    ? 'Current payable to <b>'+name+'</b>: ৳'+money(Math.abs(bal))+' — this refund will reduce it.'
    : 'Current balance for <b>'+name+'</b>: ৳'+money(bal)+' (advance/receivable).';
}

/* ── 3. Panel inside the one canonical transaction modal ──────────────── */
function ensureUI(){
  if(E('sr-wrap')) return;
  var anchor=E('rf-wrap')||E('ps-wrap')||(E('tx-acc')&&E('tx-acc').closest?E('tx-acc').closest('.form-section'):null)||(E('tx-type')&&E('tx-type').closest?E('tx-type').closest('.form-section'):null);
  if(!anchor||!anchor.parentNode) return;
  var w=document.createElement('div');
  w.id='sr-wrap';
  w.className='form-section';
  w.style.cssText='display:none;border:2px solid #f59e0b;background:#fffbeb;';
  w.innerHTML=
   '<div class="form-section-title" style="color:#92400e;border-bottom-color:#fde68a;">↩️ Supplier Payment Refund</div>'+
   '<div class="form-grid">'+
     '<div class="fg span2"><label class="lbl">Supplier Name *</label>'+
       '<input class="fc" id="sr-party" list="sr-dl-supplier" placeholder="Type or select supplier..." autocomplete="off">'+
       '<datalist id="sr-dl-supplier"></datalist>'+
       '<div id="sr-due" style="font-size:11px;color:#92400e;margin-top:5px;"></div></div>'+
     '<div class="fg"><label class="lbl">Bank Account Name *</label>'+
       '<select class="fc" id="sr-acc"></select></div>'+
     '<div class="fg"><label class="lbl">Refund Amount (৳) *</label>'+
       '<input class="fc" id="sr-amt" type="number" min="0" step="0.01" placeholder="0.00"></div>'+
     '<div class="fg span2"><label class="lbl">Notes</label>'+
       '<textarea class="fc" id="sr-notes" rows="2" placeholder="Reason / reference for the refund..." style="min-height:56px;resize:vertical;"></textarea></div>'+
   '</div>'+
   '<div style="margin-top:10px;font-size:11px;color:#92400e;background:#fef3c7;border-radius:8px;padding:9px 11px;line-height:1.55;">'+
     '📌 On save: the amount is <b>deposited into the selected bank account ledger</b> and <b>deducted from the selected supplier ledger</b> (reducing their payable/due). Dashboards and reports refresh automatically.'+
   '</div>';
  anchor.parentNode.insertBefore(w,anchor.nextSibling);

  E('sr-party').addEventListener('input',function(){sync();showDue();});
  E('sr-party').addEventListener('change',function(){sync();showDue();});
  E('sr-acc').addEventListener('change',sync);
  E('sr-amt').addEventListener('input',sync);
  E('sr-notes').addEventListener('input',sync);
  refillLists();
}

/* keep the canonical fields authoritative so every existing save path works */
function sync(){
  if(!isRefund()) return;
  var party=(E('sr-party')&&E('sr-party').value||'').trim();
  var acc=(E('sr-acc')&&E('sr-acc').value||'').trim();
  var amt=num(E('sr-amt')&&E('sr-amt').value);
  var notes=(E('sr-notes')&&E('sr-notes').value||'').trim();
  if(E('tx-party')&&party){E('tx-party').value=party;}
  if(E('tx-ptype')) E('tx-ptype').value='Supplier';
  if(E('tx-acc')&&acc) E('tx-acc').value=acc;
  if(E('tx-amt')){E('tx-amt').value=amt?amt.toFixed(2):'';fire(E('tx-amt'));}
  if(E('tx-mode')&&!E('tx-mode').value) E('tx-mode').value='Bank';
  if(E('tx-rem')&&notes) E('tx-rem').value=notes;
}

function toggle(){
  ensureUI();
  var w=E('sr-wrap'); if(!w) return;
  var on=isRefund();
  w.style.display=on?'':'none';
  ['txsec-product','txsec-transport','mp-wrap','ps-wrap'].forEach(function(id){
    var el=E(id); if(el&&on) el.style.display='none';
  });
  if(on){
    refillLists();
    if(E('tx-ptype')) E('tx-ptype').value='Supplier';
    if(!E('sr-party').value&&E('tx-party')) E('sr-party').value=E('tx-party').value||'';
    if(!E('sr-acc').value&&E('tx-acc')&&E('tx-acc').value) E('sr-acc').value=E('tx-acc').value;
    showDue(); sync();
  }
}
function clearPanel(){
  ['sr-party','sr-acc','sr-amt','sr-notes'].forEach(function(id){var el=E(id);if(el)el.value='';});
  var d=E('sr-due'); if(d) d.textContent='';
}

/* ── 4. Validation + save hook (outermost, so it runs first) ──────────── */
function validate(){
  if(!isRefund()) return {ok:true};
  sync();
  var party=(E('sr-party')&&E('sr-party').value||'').trim();
  var acc=(E('sr-acc')&&E('sr-acc').value||'').trim();
  var amt=num(E('sr-amt')&&E('sr-amt').value);
  if(!party) return {ok:false,msg:'Select the supplier who refunded the payment.'};
  if(!acc)   return {ok:false,msg:'Select the bank account where the refund was received.'};
  if(amt<=0) return {ok:false,msg:'Enter the refund amount (৳).'};
  return {ok:true,data:{party:party,acc:acc,amt:amt,notes:(E('sr-notes')&&E('sr-notes').value||'').trim()}};
}

var _prevSaveTx=window.saveTx;
window.saveTx=function(){
  if(isRefund()){
    var v=validate();
    if(!v.ok){say(v.msg,'e');return;}
    window.__srRefund=v.data;
  }
  return (typeof _prevSaveTx==='function')?_prevSaveTx.apply(this,arguments):undefined;
};

var _prevExec=window._executeSaveTx;
window._executeSaveTx=function(tx,editId){
  var d=window.__srRefund;
  if(d&&(tx.type===TYPE)){
    tx.party=d.party; tx.ptype='Supplier';
    tx.acc=d.acc; tx.bank=d.acc; tx.mode=tx.mode||'Bank';
    tx.amount=tx.amt=d.amt;
    tx.refundAmt=d.amt; tx.refundAcc=d.acc;
    tx.rem=d.notes||tx.rem||''; tx.notes=tx.rem;
    tx.cat='Transfer';
  }
  window.__srRefund=null;
  var out=(typeof _prevExec==='function')?_prevExec.apply(this,arguments):undefined;
  if(d){ clearPanel(); try{saveDB();}catch(e){} }
  return out;
};

/* ── 5. Automated accounting: bank deposit + supplier payable reduction ── */
var _prevApply=window.applyTxBalance;
window.applyTxBalance=function(tx,dir){
  if((tx&&(tx.type||''))===TYPE){
    var amt=num(tx.refundAmt||tx.amount||tx.amt)*dir;
    var b=((window.DB&&DB.banks)||[]).filter(function(x){return x.name===(tx.refundAcc||tx.acc);})[0];
    if(b) b.bal=num(b.bal)+amt;                 // deposit into bank ledger
    var c=((window.DB&&DB.customers)||[]).filter(function(x){return x.name===tx.party;})[0];
    if(c) c.bal=num(c.bal)+amt;                 // reduce supplier payable/due
    return;
  }
  return (typeof _prevApply==='function')?_prevApply.apply(this,arguments):undefined;
};

var _prevValBal=window.validateBankBalance;
window.validateBankBalance=function(tx){
  if(tx&&(tx.type||'')===TYPE) return {valid:true};   // money coming in
  return (typeof _prevValBal==='function')?_prevValBal.apply(this,arguments):{valid:true};
};

/* refund rows must read as bank-in / supplier-debit in every ledger view */
if(typeof window.SUPPLIER_DEBIT_TYPES!=='undefined'&&Array.isArray(window.SUPPLIER_DEBIT_TYPES)
