<script nonce="<?php echo $cspNonceAttr; ?>">
/* ═══════════════════════════════════════════════════════════════════════
   TOPBAR HEIGHT SYNC — the topbar now wraps onto a second row instead of
   clipping/hiding action buttons (e.g. "New Transaction") at narrow desktop
   widths or high browser zoom. Since it's position:fixed, .main's offset
   must track its REAL rendered height at all times, so content never slides
   underneath a taller, wrapped topbar. ResizeObserver reacts to width
   changes, zoom changes and button-set changes alike — no guessed values.
   ═══════════════════════════════════════════════════════════════════════ */
(function(){
'use strict';
function sync(){
  var tb=document.querySelector('.topbar');
  if(!tb) return;
  var h=tb.offsetHeight||56;
  document.documentElement.style.setProperty('--topbar-h',h+'px');
}
function boot(){
  sync();
  var tb=document.querySelector('.topbar');
  if(tb&&window.ResizeObserver){
    new ResizeObserver(sync).observe(tb);
  }
  window.addEventListener('resize',sync);
  window.addEventListener('orientationchange',sync);
}
if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',boot);
else boot();
window.addEventListener('load',sync);
})();
</script>

<script nonce="<?php echo $cspNonceAttr; ?>">
/* ═══════════════════════════════════════════════════════════════════════
   RESPONSIVE / LAYOUT NORMALISER
   Runs after every page render: wraps wide tables in a scroll container so
   they are never cramped, and normalises stat-card grids on small screens.
   ═══════════════════════════════════════════════════════════════════════ */
(function(){
'use strict';
function normalise(root){
  var scope=root||document;
  Array.prototype.forEach.call(scope.querySelectorAll('table'),function(t){
    var p=t.parentNode;
    if(!p||p.classList&&p.classList.contains('table-wrap')) return;
    if(t.closest&&t.closest('.table-wrap')) return;
    var w=document.createElement('div');
    w.className='table-wrap';
    p.insertBefore(w,t); w.appendChild(t);
  });
}
window.__uxNormalise=normalise;
var _r=window.render;
if(typeof _r==='function'){
  window.render=function(){
    var out=_r.apply(this,arguments);
    try{ setTimeout(function(){normalise();},0); }catch(e){}
    return out;
  };
}
if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',function(){normalise();});
else normalise();
})();
</script>

