/* Any wide table becomes a horizontally scrollable, momentum-scrolling panel */
.ayan-scrollx{width:100%;max-width:100%;overflow-x:auto;overflow-y:visible;
  -webkit-overflow-scrolling:touch;scrollbar-width:thin;
  background:linear-gradient(90deg,#fff 30%,rgba(255,255,255,0)),
             linear-gradient(90deg,rgba(255,255,255,0),#fff 70%) 100% 0,
             radial-gradient(farthest-side at 0 50%,rgba(15,61,38,.16),transparent),
             radial-gradient(farthest-side at 100% 50%,rgba(15,61,38,.16),transparent) 100% 0;
  background-repeat:no-repeat;background-size:36px 100%,36px 100%,14px 100%,14px 100%;
  background-attachment:local,local,scroll,scroll;}
.ayan-scrollx>table{min-width:640px;}
