  background-clip:text;color:transparent;}

@page{size:A4;margin:12mm 10mm 16mm;}

#print-area .lh-head,#print-area .print-header,#print-area .letterhead{
  border-radius:10px !important;
  box-shadow:0 10px 22px -12px rgba(6,40,24,.55), inset 0 1px 0 rgba(255,255,255,.28) !important;}
#print-area table,#print-area .print-table{width:100% !important;table-layout:fixed !important;
  border-collapse:collapse !important;font-size:10.5px !important;word-break:break-word !important;}
#print-area .print-table th,#print-area .print-table td{padding:5px 6px !important;overflow-wrap:anywhere !important;}
/* FIX (same 1,000,000px runaway as the @media print rule below, but this
   one hits the on-screen Print Preview modal too, before you ever get to
   Ctrl+P): every table gets auto-wrapped in a `.ux-xscroll` scroll div
   (see wrapTables()), whose `min-width:max-content` fights the
   `table-layout:fixed;width:100% !important` above and makes Chromium fall
   back to an enormous intrinsic width inside #print-area specifically — so
   every printable document, previewed or printed, showed row labels with
   every ৳ figure silently rendered a million pixels off to the right. */
#print-area .ux-xscroll{overflow:visible !important;max-width:none !important;width:auto !important;}
#print-area .ux-xscroll>table{min-width:0 !important;}
@media print{
  html,body{background:#fff!important;}
  *{-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important;}
  .sidebar,.topbar,.bottom-nav,.fab-btn,.fab-item,.fab-label,.mobile-overlay,
  .sidebar-overlay,.toast,.sync-toast,.print-toolbar,.swipe-hint,.theme-toggle-btn,
  .hamburger,.mobile-menu-btn,.nav-search-wrap{display:none!important;}
  #print-area{width:auto!important;box-shadow:none!important;padding:0!important;}
  #print-area .ayan-lh3d{box-shadow:none!important;border:1px solid #0f3d26;}
  /* Table integrity across pages */
  table{page-break-inside:auto;border-collapse:collapse!important;}
  thead{display:table-header-group;}
  tfoot{display:table-footer-group;}
  tr,.sum-box,.print-sig-col,.card{page-break-inside:avoid;}
  .print-table th,.print-table td{border:1px solid #cfd8d2!important;}
  .print-table tr:nth-child(even) td{background:#f4fbf6!important;}
  .print-sigfooter{page-break-inside:avoid;margin-top:18mm;}
  .ayan-page-foot{position:fixed;bottom:0;left:0;right:0;font-size:9px;color:#4b5563;
    border-top:1px solid #bbf7d0;padding-top:3px;display:flex;justify-content:space-between;}
  a[href]::after{content:"";}
  .ayan-noprint{display:none!important;}
  /* FIX (numbers pushed a million pixels off the page): every table in the
     app — print documents included — gets auto-wrapped in a `.ux-xscroll`
     div so wide tables can scroll horizontally on screen (see wrapTables()).
     That wrapper's own `min-width:max-content` on the table, combined with
     this stylesheet's `table-layout:fixed;width:100% !important` on print
     tables, is a combination Chromium can't resolve inside a scrolling
     container and falls back to an enormous intrinsic width — observed at
     exactly 1,000,000px. The table (and every ৳ figure in its second
     column) was still being drawn, just a million pixels to the right of
     the page: on screen this read as a "blank" report with only row
     labels visible; on paper it would print blank pages of nothing (or a
     single sheet with only left-edge labels) with every amount silently
     lost off the right margin. A scroll affordance means nothing on paper
     anyway, so the wrapper is neutralised for print: it stops scrolling
     and stops forcing its child table to size itself against that
     indeterminate width, letting the table lay out normally at the page's
     actual width instead. */
  .ux-xscroll{overflow:visible!important;max-width:none!important;width:auto!important;}
  .ux-xscroll>table{min-width:0!important;}
}
</style>

<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-fix-runtime">
(function(){
  "use strict";
  var W=window;
  function num(v){var n=parseFloat(v);return isNaN(n)?0:n;}
  function D(){return W.DB||{};}
  function low(s){return String(s||'').trim().toLowerCase();}
  function posted(t){var s=low(t&&t.status);if(t&&t.approvalStatus==='Pending')return false;return s!=='rejected'&&s!=='void'&&s!=='cancelled'&&s!=='draft';}


  /* ═══ 0. STANDALONE / OFFLINE MODE ══════════════════════════════
     The server login layer required login.php + api.php. Opened as a
     plain file (no PHP host) login died with "Failed to fetch" and
     nothing could be saved. The app now detects that and runs fully
     offline on local storage, with the server path untouched when a
     backend really is present.                                      */
  var LS_KEY='rbo_v4', SESS='ayan_session';
  var _serverOK=null;
  function probeServer(){
    if(_serverOK!==null) return Promise.resolve(_serverOK);
    /* Opened straight from disk (file://) there is no origin to fetch from —
       skip the probe instead of logging a scheme error on every load. */
    if(location.protocol==='file:'){ _serverOK=false; return Promise.resolve(false); }
    /* Server sync disabled (no PHP backend deployed): skip the probe so the
       app doesn't fire a failing api.php request on every load. */
    if(window.ERP_CONFIG && window.ERP_CONFIG.USE_SERVER===false){ _serverOK=false; window.ERP_SERVER_MODE=false; return Promise.resolve(false); }
    /* NIMCHIP: MySQL backend detection. api.php?action=ping answers with JSON
       when the PHP files are deployed; anything else means run offline. */
    var pingUrl = (window.ERP_CONFIG && window.ERP_CONFIG.API_URL) ? (window.ERP_CONFIG.API_URL + '?action=ping') : 'api.php?action=ping';
    var pingFetch = fetch(pingUrl,{method:'GET',credentials:'include',headers:{'Accept':'application/json'}});
    return Promise.race([
      pingFetch
        .then(function(r){ return r.ok ? r.json().catch(function(){return null;}) : null; })
        .then(function(j){ return !!(j && j.success); })
        .catch(function(){ return false; }),
      new Promise(function(res){setTimeout(function(){res(false);},4000);})
    ]).then(function(ok){
      _serverOK=ok;
      try{ window.ERP_SERVER_MODE = ok; }catch(e){}
      return ok;
    });
  }
  function localSave(){                 // FIX 3: quota-safe, IndexedDB-mirrored
    return (typeof W._erpLocalSave==='function') ? W._erpLocalSave() : (function(){
      try{localStorage.setItem(LS_KEY,JSON.stringify(W.DB));
          if(typeof W._markSaved==='function')W._markSaved();return true;}
      catch(e){
        if(typeof W.toast==='function')W.toast('Local save failed: '+e.message+' (storage may be full — export a backup)','e');
        return false;}
    })();
  }
  function localLoad(){
    try{var s=localStorage.getItem(LS_KEY);if(!s)return false;
        var d=JSON.parse(s);if(d&&typeof d==='object'){
          Object.keys(d).forEach(function(k){W.DB[k]=d[k];});}
        return true;}catch(e){return false;}
  }
  /* FIX I (removed default credentials): this used to insert a user
     'admin' / 'admin123' with full Admin rights, in plain text, and
     re-created it automatically whenever the user list was empty.
     Accounts now live in the cloud auth system, so there is no built-in
     password to guess and no local user list to tamper with. */
  function seedAdmin(){ /* intentionally empty */ }
  /* SECURITY (2026-09-02): offline login is permanently disabled.
     It authenticated against DB.users in localStorage, which any user can
     edit from DevTools — including their own role — so both the password
     check and every permission check became client-authoritative. There is
     no safe way to keep it: the server session is the only authority. */
  function offlineLogin(){ return null; }
  function offlineLogin_DISABLED(username,password){
    localLoad();seedAdmin();
    var u=(W.DB.users||[]).filter(function(x){
      return String(x.username||'').toLowerCase()===username.toLowerCase()
          && ((typeof W._erpPwOK==='function') ? W._erpPwOK(x,password)   // FIX 5: hashed password check
                                               : String(x.password||'')===password)
          && String(x.status||'Active').toLowerCase()!=='inactive';})[0];
    if(!u) return null;
    u.lastLogin=new Date().toISOString();u.loginCount=(u.loginCount||0)+1;
    W.currentUser=u;
    try{sessionStorage.setItem(SESS,JSON.stringify(u));sessionStorage.setItem('rbo_user',JSON.stringify(u));}catch(e){}
    localSave();
    return u;
  }
  W.ayanOfflineLogin=offlineLogin;

  function enableOffline(){
    /* SECURITY (2026-09-02): never swap in the local-storage auth path.
       A failed server probe now surfaces a real error instead of silently
       downgrading authentication to an editable localStorage check. */
    try{
      if(W.toast) W.toast('Server unreachable — offline mode is disabled for security. Please reconnect and try again.','e');
      var _e=document.getElementById('login-error');
      if(_e){ _e.textContent='Cannot reach the server. Offline sign-in is disabled.'; _e.style.display='block'; }
    }catch(e){}
    return false;
  }
  function enableOffline_DISABLED(){
    /* Keep the settings UI and the server-sync gate in agreement with reality. */
    try{ W.ERP_CONFIG=W.ERP_CONFIG||{}; W.ERP_CONFIG.USE_SERVER=false; W.ERP_SERVER_MODE=false; }catch(e){}
    W.saveDB=function(){return localSave();};
    W.saveDBNow=function(){return Promise.resolve(localSave());};
