      try{rb&&rb.checked?localStorage.setItem('ayan_last_user',un):localStorage.removeItem('ayan_last_user');}catch(e){}
      try{(W.showApp||function(){})();}catch(e){}
      try{(W.refreshAll||W.renderAll||function(){})();}catch(e){}
