      setTimeout(function(){try{wrapTables();}catch(e){}},300);
    };
    W.doLogout=async function(){
      if(!await __confirm('Are you sure you want to logout?'))return;
      localSave();
      try{sessionStorage.removeItem(SESS);sessionStorage.removeItem('rbo_user');}catch(e){}
      W.currentUser=null;
      try{(W.showLoginScreen||function(){})();}catch(e){}
    };
    W.initLogin=function(){
      localLoad();seedAdmin();
      var s=null;try{s=JSON.parse(sessionStorage.getItem(SESS)||'null');}catch(e){}
      if(s){W.currentUser=s;try{(W.showApp||function(){})();(W.refreshAll||W.renderAll||function(){})();}catch(e){}}
      else{try{(W.showLoginScreen||function(){})();}catch(e){}}
      return Promise.resolve(true);
    };
    W.addEventListener('beforeunload',function(){try{localSave();}catch(e){}});
  }
  probeServer();
  // FIX (2026-08-18): no longer calls enableOffline() here — this app is
  // server-only. doLogin/saveDB/loadDataFromServer always use login.php /
  // api.php; if the server truly is unreachable, calls fail with a real,
  // visible error instead of silently switching to local-storage mode.

  /* ═══ 1. DERIVED BALANCES ═══════════════════════════════════════
     Party / bank / partner balances were stored as running totals and
     drifted on every import, restore or out-of-band edit. They are now
     recomputable from the transaction history at any time.          */
  /* FIX (2026-08-20): several type names the New Transaction dropdown itself
     offers — 'Customer Sale' (a canonical revenue type everywhere else in
     the app), 'Customer Collection', 'Customer Payment Received', 'Advance
     from Customer', 'Advance to Supplier', 'Supplier Advance', 'Supplier
     Refund' — were absent from SIGN entirely. That's not just "no effect":
     an unmapped type still falls through to the bank chain's final catch-all
     below, which treats anything unrecognized as an outgoing expense and
     SUBTRACTS it from the bank — so a customer payment collected under
     'Customer Collection' would have been deducted from the bank balance on
     the next boot's automatic drift-repair, the exact opposite of what
     happened. Every one of these is now mapped the same as its already-
     correct sibling (applyTxBalance(), the live save-path engine, mirrors
     this exactly). 'Customer Due' / 'Supplier Due' record a receivable/
     payable with no money changing hands, so they're handled separately
     below rather than through the bank chain at all. */
  var SIGN={ // [party delta per amount, bank delta per settled amount]
    'sale':1,'warehouse sale':1,'customer sale':1,
    'sales receipt':-1,'customer collection':-1,'customer payment received':-1,
    'sales advance':-1,'advance from customer':-1,'sales return':-1,
    'customer due':1,'supplier due':-1,
    'purchase':-1,'warehouse purchase':-1,'supplier purchase':-1,
    'purchase payment':1,'supplier payment':1,
    'purchase advance':1,'advance to supplier':1,'supplier advance':1,
    'purchase return':1,'supplier refund':1,
    /* FIX (save and reload disagreed): applyTxBalance() moves the party
       balance for these seven types when the entry is saved, but this table
       — the one the boot-time rebuild uses — did not list them, so the next
       page load quietly put the party back where it had been. Receiving
       ৳5,000 by bKash from an agent moved his balance at save time and
       un-moved it on reload. Both sides now use the same signs. */
    'bkash receive':-1,'bkash receive from agent':-1,'bkash deposit':-1,
    'cash received':-1,'cash payment':1,
    'employee advance':1,'employee loan':1
  };
  function recomputeBalances(opts){
    var db=D(); if(!db||!db.tx) return null;
    var parties={},banks={},drift=[];
    (db.customers||[]).forEach(function(c){parties[c.name]=0;});
    (db.banks||[]).forEach(function(b){banks[b.name]=0;});
    (db.openingBalances||[]).forEach(function(o){
      if(o.party) parties[o.party]=(parties[o.party]||0)+num(o.amount||o.amt);
    });
    (db.banks||[]).forEach(function(b){banks[b.name]=num(b.openingBal||b.opening||0);});
    /* FIX (2026-08-20): type.indexOf('purchase')===0 only matches strings that
       literally START with "purchase" — so it silently missed 'warehouse
       purchase' and 'supplier purchase' (both start with a different word),
       even though SIGN above and applyTxBalance() elsewhere both treat all
       three as the same purchase transaction. That gap meant a Warehouse/
       Supplier Purchase that was paid (in full or in part) never got its
       `paid` amount credited back against the supplier's payable here, so
       every boot's automatic drift-repair (see BOOT below) overwrote the
       correct, already-paid balance with one that looked fully unpaid —
       and did the same to the bank side (deducting the whole `amt` instead
       of just what was actually paid). isPurchType() now matches on the
       same three type strings everywhere, typo included. */
    function isPurchType(t){ return t==='purchase'||t==='warehouse purchase'||t==='supplier purchase'||t==='werhouse purchase'; }
    function isSaleType_(t){ return t==='sale'||t==='warehouse sale'||t==='customer sale'; }
    function isReceiptType(t){ return t==='sales receipt'||t==='customer collection'||t==='customer payment received'||t==='sales advance'||t==='advance from customer'; }
    /* FIX (production consuming cash it never touched): Raw Material Issue,
       Finished Goods Entry and their siblings are pure stock movements —
       raw material moving into production, finished goods coming out of it
       — with no cash or bank leg at all; applyTxBalance() at save time
       correctly leaves them alone. This rebuild had no branch for them
       either, so they fell through to the generic "everything else is an
       expense" catch-all below and silently pulled their full amount out of
       whichever account the form happened to default `acc` to (typically
       "Cash In Hand") on every boot — a production entry with no money
       involved still drained the cash account it was never supposed to
       touch. They're excluded from bank adjustment here now, matching
       applyTxBalance(). */
    function isNoMoneyType(t){
      return t==='customer due'||t==='supplier due'
          || t==='raw material issue'||t==='finished goods entry'
          || t==='manufacturing consumption'||t==='manufacturing output'
          || t==='production input'||t==='production output'
          || t==='stock in'||t==='stock out'||t==='warehouse transfer'
          || t==='opening stock';
    } // party/stock-only, never touches a bank
    (db.tx||[]).filter(posted).forEach(function(t){
      var type=low(t.type),amt=num(t.amount||t.amt),paid=num(t.paid),recv=num(t.recv),
          p=String(t.party||'').trim(),acc=String(t.acc||'').trim(),acc2=String(t.acc2||'').trim(),
          s=SIGN[type.replace('werhouse','warehouse')];
      /* FIX (money received saved as zero): see applyTxBalance. Money-in rows
         whose figure sits in `recv` because the form hid the Amount box are
         read from `recv` here too, so this rebuild and the save path agree. */
      if(!amt && window.AYAN_MONEY_IN_AMT && window.AYAN_MONEY_IN_AMT.has(type)) amt=recv;
      if(p&&s!==undefined) parties[p]=(parties[p]||0)+s*amt;
      if(p&&isSaleType_(type)&&recv) parties[p]-=recv;
      /* FIX (withholding tax): the 0.5% the buyer deducts at source is not
         collectable from them — clear it from the receivable here too, or
         this rebuild puts the phantom due straight back on every reload. */
      if(p&&isSaleType_(type)&&num(t.salesTaxAmt)) parties[p]-=num(t.salesTaxAmt);
      if(p&&isPurchType(type)&&paid) parties[p]+=paid;
      if(acc && !isNoMoneyType(type)){
        if(isSaleType_(type)) banks[acc]=(banks[acc]||0)+recv;
        else if(isReceiptType(type)) banks[acc]=(banks[acc]||0)+amt;
        else if(type==='sales return') banks[acc]=(banks[acc]||0)-amt;
        /* FIX (Fixed Assets over/under-counted on rebuild): 'asset sale' sat
           in the generic AYAN_MONEY_IN_AMT list below, which credits the
           full invoice `amt` — but a part-received Asset Sale only actually
           puts `recv` in the bank, same gap Purchase/Sale had. 'fixed asset
           purchase' wasn't in ANY list, so it fell to the catch-all at the
           bottom and had the FULL invoice amount pulled out of the bank
           even when only part of it was paid. Both now mirror what
           applyTxBalance() does at save time, so a boot-time rebuild can
           never quietly undo the save-time figure. */
        else if(type==='fixed asset purchase') banks[acc]=(banks[acc]||0)-paid;
        else if(type==='asset sale') banks[acc]=(banks[acc]||0)+recv;
        /* FIX: this fell back to the whole invoice amount when `paid` was
           blank, while the save path deducts only what was actually paid.
           A Warehouse Purchase entered with an account chosen but the Paid
           box left empty therefore took nothing from the bank when saved,
           and the full amount out of it on the next page load — money
           leaving an account with no entry behind it. Only what is recorded
           as paid moves, here and at save time alike. */
        else if(isPurchType(type)) banks[acc]=(banks[acc]||0)-paid;
        else if(type==='purchase payment'||type==='purchase advance'||type==='advance to supplier'||type==='supplier advance') banks[acc]=(banks[acc]||0)-amt;
        else if(type==='purchase return'||type==='supplier refund') banks[acc]=(banks[acc]||0)+amt;
        /* FIX (Post Opening Entry silently undone by Fix Balances / dedupe):
           this rebuild had no branch for 'journal entry' at all, so a Dr
           <bank> / Cr <equity> opening entry — exactly what "📒 Post Opening
           Entry" and "Post All Opening Entries" post — fell through to the
           generic catch-all below and was SUBTRACTED from the debited bank on
           every boot-time rebuild or 🛠 Fix Balances click, instead of ADDED —
           exactly backwards, and by double the intended amount versus the
           live save-time engine (ayanBankMove(), which already gets this
           right: Dr side is money in, Cr side is money out). A freshly
           unlinked-cleared bank account would silently go unlinked again
           (and short by 2× the opening figure) the next time balances were
           rebuilt. Mirrors ayanBankMove() so the two engines can't disagree. */
        else if(type==='journal entry') banks[acc]=(banks[acc]||0)+amt;
        /* FIX (money-in): the catch-all below assumed every remaining type
           was money leaving the account. It therefore SUBTRACTED every
           Partner Fund, Partner Capital, Bank Deposit, Cash Received,
           Bkash Receive, Opening Bank Balance, Other Income and Asset Sale
           on every page load — a ৳10,000 partner fund added at save time
           came back as ৳10,000 paid out, a ৳20,000 swing on one entry.
           Incoming types are now credited, matching applyTxBalance(). */
        else if(window.AYAN_MONEY_IN_AMT && window.AYAN_MONEY_IN_AMT.has(type)) banks[acc]=(banks[acc]||0)+amt;
        else banks[acc]=(banks[acc]||0)-amt; // expenses, salaries, transfers out
      }
      /* FIX: on a transfer the money leaves `acc` and arrives in `acc2`;
         the arriving side was never credited. */
      if(acc2&&(type==='bank transfer'||type==='inter transfer'||type==='inter bank transfer'||type==='inter-account transfer'||type==='transfer (internal)'||type==='bkash transfer'))
        banks[acc2]=(banks[acc2]||0)+amt;
      /* FIX: see the 'journal entry' fix above — the credit side of a
         Journal Entry (acc2) is money leaving that account, same as
         ayanBankMove(). Only applies when acc2 is itself a bank name
         (e.g. a bank-to-bank journal); an equity/capital account name
         here simply isn't tracked in `banks`, so nothing happens to it. */
      else if(acc2&&type==='journal entry') banks[acc2]=(banks[acc2]||0)-amt;
      else if(acc2&&num(t.paid2)) banks[acc2]=(banks[acc2]||0)-num(t.paid2);
    });
    /* FIX (Factory Finance): a funded drawdown credits a bank account, but
       it lives in DB.cityFinance and not in DB.tx, so this rebuild wiped
       the credit on every page load — the drawdown record survived while
       the money it put in the bank silently vanished. */
    (db.cityFinance||[]).forEach(function(r){
      if(!r||!r.bank) return;
      var famt = r.status==='Funded' ? num(r.advPaid)
               : r.status==='Settled' ? num(r.net) : 0;
      if(famt) banks[r.bank]=(banks[r.bank]||0)+famt;
    });
    (db.customers||[]).forEach(function(c){
      var d=+(parties[c.name]||0).toFixed(2);
      if(Math.abs(num(c.bal)-d)>0.5) drift.push({kind:'Party',name:c.name,stored:num(c.bal),derived:d});
      /* FIX (duplicate fields): a party carries both `bal` and `balance`,
         a bank both `bal` and `balance`. Only `bal` was ever written, so
         screens reading the other name kept showing pre-transaction
         figures. Both copies are now kept in step. */
      if(opts&&opts.apply){ c.bal=d; if(c.balance!==undefined) c.balance=d; }
    });
    (db.banks||[]).forEach(function(b){
      var d=+(banks[b.name]||0).toFixed(2);
      if(Math.abs(num(b.bal)-d)>0.5) drift.push({kind:'Bank',name:b.name,stored:num(b.bal),derived:d});
      if(opts&&opts.apply){ b.bal=d; if(b.balance!==undefined) b.balance=d; }
    });
    if(opts&&opts.apply&&typeof W.saveDB==='function'){try{W.saveDB();}catch(e){}}
    return {parties:parties,banks:banks,drift:drift};
  }
  W.recomputeBalances=recomputeBalances;
  W.fixBalances=function(){
    var r=recomputeBalances({apply:true});
    var n=r?r.drift.length:0;
    if(typeof W.toast==='function') W.toast(n?('Rebuilt '+n+' balance(s) from transaction history'):'All balances already reconciled','s');
    ['renderCust','renderBanks','renderDash','renderTx'].forEach(function(f){try{W[f]&&W[f]();}catch(e){}});
    return r;
  };

  /* ═══ 2. FULL STOCK MOVEMENT ENGINE ═════════════════════════════
     Old stock only counted Purchase / Warehouse Purchase / Opening in
     and Sale / Warehouse Sale out — ignoring returns, adjustments,
     wastage, production and transfers, and ignoring location entirely.
     Now every movement type is captured, per product AND per location,
     with weighted-average costing and real COGS.                    */
  var IN_T=['purchase','warehouse purchase','supplier purchase','opening balance','opening stock',
            'production output','stock in'];
  var IN_AT_COST_T=['sales return'];   // stored amount is the REVENUE value being reversed, not cost — see stockPosition()
  var OUT_T=['sale','warehouse sale','purchase return','production input','stock out'];
  function stockLedger(){
    var db=D(),rows=[];
    /* FIX (Trial Balance mismatch — opening stock invisible to Warehouse
       Stock Value): opening quantity/rate are saved onto the product record
       itself (p.openingStock / p.rate) by the Opening Balances page, not as
       a transaction — but this ledger, and therefore stockPosition() and
       the Trial Balance's "Warehouse Stock Value", only ever read db.tx.
       A product with opening stock but zero transactions posted against it
       so far (e.g. Parboiled Rice Bran High Fat: 54,665 units @ ৳28.17 =
       ৳15,39,913.05) was counted as ৳0 stock — exactly the size of the
       Left-more-than-Right gap on the Trial Balance. Seeded here as the
       first IN movement per product, dated '' (sorts before every real
       date) so weighted-average costing still starts from the right base. */
    (db.products||[]).forEach(function(p){
      var oq=num(p.openingStock);
      if(!oq) return;
      var rate=(typeof W.unitCost==='function')?W.unitCost(p):(num(p.cost)||num(p.rate));
      rows.push({date:'',prod:p.name,loc:'Unassigned',dir:1,qty:oq,value:oq*rate,src:'Opening Stock',ref:'Opening Balance'});
    });
    (db.tx||[]).filter(posted).forEach(function(t){
      var type=low(t.type);
      /* BLENDED WAREHOUSE POOL: bran bought into the warehouse loses its
         individual identity — it is mixed and sold under one brand. Its
         quantity and value are therefore booked to that brand, which makes
         the brand's own weighted average exactly the pooled average, so
         COGS, stock value and profit all come out right without any screen
         needing a special rule. Ordinary Purchases are untouched and stay
         costed per product. */
      var pooled=(typeof W.ayanIsWarehousePurchase==='function'&&typeof W.ayanPoolBrand==='function'
                   &&W.ayanIsWarehousePurchase(t.type))?(W.ayanPoolBrand()||null):null;
      /* FIX (Multiple Products lines vanished into one fake combined-name
         row): a "Multiple Products" transaction (mp-toggle in the New
         Transaction form) stores its real lines in t.items[] and only keeps
         a human-readable "Product A + Product B" string in the top-level
         t.prod field, for display. This function used to read ONLY that
         top-level field and amount, so the whole purchase/sale was booked
         as one movement of a product that doesn't actually exist in the
         product master — invisible to Product P&L and COGS matching by
         name for every real product actually involved, and left a
         synthetic "A + B" line cluttering Stock Movement with the full
         combined quantity/value. Each line in items[] is now its own
         movement, using the same Net-Weight-then-Gross-then-Qty rule as a
         single-line transaction. Pooled Warehouse Purchases still collapse
         every line into the one blended brand, exactly as a single-line
         entry of the same type already did. */
      var lines;
      if(Array.isArray(t.items)&&t.items.length){
        lines=t.items.map(function(it){
          return {qty:num(it.wt)||num(it.grosswt)||num(it.qty),
                   value:num(it.amount||it.amt),
                   prod:pooled||it.prod};
        });
      }else{
        if(!t.prod) return;
        /* FIX: gross weight was ignored here while the stock counter used it,
           so a purchase entered with Gross Weight but no Net Weight counted
           towards the stock number and not towards its value or its cost. */
        /* FIX: the amount is worked out from Net Weight first, then Gross,
           then Qty — but stock was read the other way round, Qty first. Edit a
           transaction's weight and the money changed while the stock did not,
           because the two were reading different boxes. Both use one rule now:
           Net Weight, then Gross Weight, then Quantity. */
        lines=[{qty:num(t.wt)||num(t.grosswt)||num(t.qty), value:num(t.amount||t.amt), prod:pooled||t.prod}];
      }
      lines.forEach(function(ln){
        var qty=ln.qty; if(!qty) return;
        var prod=ln.prod;
        if(IN_T.indexOf(type)>=0) rows.push({date:t.date,prod:prod,loc:t.loc||'Unassigned',dir:1,qty:qty,value:ln.value,src:t.type,ref:t.inv||t.code||''});
        /* FIX: a Sales Return's `amount` is the customer refund/revenue value
           being reversed (see the P&L 'Less: Sales Returns' deduction) — it is
           NOT the product's cost. Feeding it into inventory value as-is skewed
           the weighted-average cost for every later sale of the product. It's
           valued at the CURRENT average cost instead, in stockPosition(). */
        else if(IN_AT_COST_T.indexOf(type)>=0) rows.push({date:t.date,prod:prod,loc:t.loc||'Unassigned',dir:1,qty:qty,value:0,valueAtCost:true,src:t.type,ref:t.inv||t.code||''});
        else if(OUT_T.indexOf(type)>=0) rows.push({date:t.date,prod:prod,loc:t.loc||'Unassigned',dir:-1,qty:qty,value:0,src:t.type,ref:t.inv||t.code||''});
      });
    });
    /* FIX: this read DB.stockAdj and a.prod, while the Stock Adjustment
       screen saves into DB.stockAdjustments under a.product — so every
       adjustment was invisible here. Stock quantity dropped but nothing was
       ever costed, leaving the books out by the value written off. It also
       took the direction from the sign of the quantity, though the screen
       stores a positive quantity with an "add"/"remove"/"set" type, so even
       a removal would have been counted as stock coming in. */
    [].concat(db.stockAdj||[], db.stockAdjustments||[]).forEach(function(a){
      var q=num(a.qty!=null?a.qty:a.adjQty); if(!q) return;
      var nm=a.prod||a.product; if(!nm) return;
      var t=String(a.adjType||a.type||'').toLowerCase();
      var dir = t==='remove' ? -1 : t==='add' ? 1 : (q>0?1:-1);
      rows.push({date:a.date,prod:nm,loc:a.loc||a.location||'Unassigned',dir:dir,qty:Math.abs(q),
                 value:num(a.value),valueAtCost:dir>0&&!num(a.value),src:'Stock Adjustment',ref:a.reason||''});
    });
    (db.wastage||[]).forEach(function(w){
      var q=num(w.qty);if(!q||!w.prod)return;
      rows.push({date:w.date,prod:w.prod,loc:w.loc||w.location||'Unassigned',dir:-1,qty:Math.abs(q),value:0,src:'Wastage',ref:w.reason||''});
    });
    (db.production||db.productionLogs||[]).forEach(function(p){
      if(p.rawMaterial&&num(p.rawQty)) rows.push({date:p.date,prod:p.rawMaterial,loc:p.loc||'Unassigned',dir:-1,qty:num(p.rawQty),value:0,src:'Production Input',ref:p.batch||''});
      if(p.product&&num(p.outQty||p.qty)) rows.push({date:p.date,prod:p.product,loc:p.loc||'Unassigned',dir:1,qty:num(p.outQty||p.qty),value:num(p.cost),src:'Production Output',ref:p.batch||''});
    });
    (db.transfers||db.interTransfers||[]).forEach(function(x){
      if(!x.prod||!num(x.qty))return;
      rows.push({date:x.date,prod:x.prod,loc:x.from||'Unassigned',dir:-1,qty:num(x.qty),value:0,src:'Transfer Out',ref:x.to||''});
      rows.push({date:x.date,prod:x.prod,loc:x.to||'Unassigned',dir:1,qty:num(x.qty),value:0,src:'Transfer In',ref:x.from||''});
    });
    rows.sort(function(a,b){return String(a.date||'').localeCompare(String(b.date||''));});
    return rows;
  }
  function stockPosition(upto){
    var rows=stockLedger(),byProd={},cogs=0;
    rows.forEach(function(r){
      if(upto&&String(r.date||'')>upto) return;
      var p=byProd[r.prod]||(byProd[r.prod]={prod:r.prod,qty:0,value:0,avg:0,inQty:0,outQty:0,cogs:0,locs:{}});
      var L=p.locs[r.loc]||(p.locs[r.loc]=0);
      if(r.dir>0){
        /* Sales Return: value the returned units at the CURRENT weighted-
           average cost (falls back to 0 if nothing has ever been costed in
           yet — e.g. a return recorded before any purchase). This keeps the
           average cost itself unaffected by the return, matching how
           Purchase Return (an OUT) already uses the existing average rather
           than any stored transaction amount. */
        var inVal = r.valueAtCost ? (p.avg*r.qty) : r.value;
        p.inQty+=r.qty;p.qty+=r.qty;p.value+=inVal;p.locs[r.loc]=L+r.qty;
        /* FIX: goods a customer sends back are no longer sold, so their cost
           has to come back out of cost of sales. The revenue was already
           reversed; leaving the cost behind understated profit by exactly
           what the returned goods cost — ৳4,000 on this ৳6,000 return. */
        if(r.valueAtCost){ p.cogs-=inVal; cogs-=inVal; }
      }else{
        var cost=p.avg*r.qty;
        /* FIX: goods sent BACK to a supplier were counted as cost of goods
           sold. They were never sold — the stock leaves and the supplier's
           balance is credited, so nothing belongs in COGS. Counting it there
           wiped out real profit: a ৳4,000 purchase return turned an ৳8,000
           gross profit into ৳0 and left the balance sheet out by the same
           amount. Wastage and stock write-offs DO stay in COGS, because that
           value really is gone. */
        var noCogs = /purchase return|supplier refund/i.test(String(r.src||''));
        p.outQty+=r.qty;p.qty-=r.qty;p.value-=cost;p.locs[r.loc]=L-r.qty;
        if(!noCogs){ p.cogs+=cost; cogs+=cost; }
      }
      /* FIX: previously, once qty dropped to <=0 (selling before the
         matching purchase was entered, or genuine overselling), inventory
         value was hard-clamped to 0 and avg cost was frozen at its last
         value instead of following qty/value. That silently zeroed out the
         cost of oversold units and never let the deficit unwind correctly
         once a purchase arrived. Letting value go negative alongside qty
         keeps avg = value/qty mathematically consistent (a deficit of -20
         units at avg cost 10 is value -200, so avg is still 10) and the
         shortfall blends back to a sensible average as soon as stock is
         purchased in. The one unavoidable case: the very first movement for
         a product being a sale with no purchase or avg cost yet — there is
         no cost basis to draw on, so that portion is costed at 0 until a
         purchase establishes one, same as before. A persistently negative
         "Warehouse Stock Value" for a product is a legitimate, intentional
         signal that it's been oversold/entered out of order — not a bug to
         hide by clamping. */
      p.avg = p.qty!==0 ? p.value/p.qty : p.avg;
    });
    return {items:Object.values(byProd),cogs:cogs,rows:rows};
  }
  W.stockLedger=stockLedger;W.stockPosition=stockPosition;

  function money(n){try{return (W.pf?W.pf(n):Number(n||0).toLocaleString(undefined,{maximumFractionDigits:2}));}catch(e){return Number(n||0).toFixed(2);}}
  W.renderStockSummary=function(){
    var wrap=document.getElementById('stk-summary-body'); if(!wrap) return;
    var pos=stockPosition(),items=pos.items.sort(function(a,b){return b.qty-a.qty;});
    var totQty=0,totVal=0;
    var body=items.map(function(p){
      totQty+=p.qty;totVal+=Math.max(0,p.value);
      var col=p.qty<=0?'#dc2626':p.qty<=100?'#d97706':'#16a34a';
      var locs=Object.keys(p.locs).filter(function(k){return Math.abs(p.locs[k])>0.001;})
        .map(function(k){return k+': '+money(p.locs[k]);}).join(' · ')||'—';
      var pools=(typeof productPoolBreakdown==='function')?productPoolBreakdown(p.prod):{};
      var poolsLine=Object.keys(pools).map(function(k){return k+': '+money(pools[k]);}).join(' · ');
      return '<tr style="border-bottom:1px solid #f3f4f6;">'+
        '<td style="padding:9px 12px;font-weight:700;">'+p.prod+
          '<div style="font-size:10px;color:#6b7280;font-weight:500;margin-top:2px;">🗺️ '+locs+'</div>'+
          (poolsLine?'<div style="font-size:10px;color:#1e40af;font-weight:500;margin-top:2px;">🏭 '+poolsLine+'</div>':'')+
        '</td>'+
        '<td style="padding:9px 12px;text-align:right;color:#16a34a;font-weight:700;">'+money(p.inQty)+'</td>'+
        '<td style="padding:9px 12px;text-align:right;color:#dc2626;font-weight:700;">'+money(p.outQty)+'</td>'+
        '<td style="padding:9px 12px;text-align:right;font-weight:800;color:'+col+';">'+money(p.qty)+'</td>'+
        '<td style="padding:9px 12px;text-align:right;">'+money(p.avg)+'</td>'+
        '<td style="padding:9px 12px;text-align:right;font-weight:700;">৳'+money(Math.max(0,p.value))+'</td></tr>';
    }).join('');
    wrap.innerHTML='<div class="ayan-scrollx"><table style="width:100%;border-collapse:collapse;font-size:12px;">'+
      '<thead><tr style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;">'+
      '<th style="padding:10px 12px;text-align:left;">Product / Location</th>'+
      '<th style="padding:10px 12px;text-align:right;">Total In</th>'+
      '<th style="padding:10px 12px;text-align:right;">Total Out</th>'+
      '<th style="padding:10px 12px;text-align:right;">Net Stock</th>'+
      '<th style="padding:10px 12px;text-align:right;">Avg Cost</th>'+
      '<th style="padding:10px 12px;text-align:right;">Stock Value (৳)</th></tr></thead><tbody>'+
      (body||'<tr><td colspan="6" style="text-align:center;padding:20px;color:#9ca3af;">No stock movements recorded.</td></tr>')+
      '</tbody><tfoot><tr style="background:#f0fdf4;font-weight:800;border-top:2px solid #16a34a;">'+
      '<td style="padding:10px 12px;">Totals ('+items.length+' products)</td><td colspan="2"></td>'+
      '<td style="padding:10px 12px;text-align:right;">'+money(totQty)+'</td><td></td>'+
      '<td style="padding:10px 12px;text-align:right;">৳'+money(totVal)+'</td></tr></tfoot></table></div>'+
      '<div style="font-size:11px;color:#6b7280;margin-top:8px;">Includes purchases, sales, returns, stock adjustments, wastage, production and inter-location transfers. Valuation: weighted average cost. 🗺️ = sale/purchase district; 🏭 = physical warehouse pool (Main Godown, Factory Yard, Depot, etc.), moved via Warehouse Transfer.</div>';
  };

  /* ═══ 3. PROFIT & LOSS ON REAL COGS ═════════════════════════════
     Purchases are no longer treated as cost of sales, and expenses are
     detected dynamically instead of from a hard-coded whitelist.     */
  /* FIX: anything absent from this list was booked as an operating
     expense. A ৳10,000 Partner Fund — the owners putting capital in —
     was therefore charged against the month's profit, turning a ৳10.67
     gross profit into a ৳9,989.33 loss. Capital, transfers, receipts and
     opening balances are movements of money, not trading costs, and are
     now all excluded through the shared AYAN_NON_EXPENSE list. */
  var NON_EXP=['sale','warehouse sale','sales receipt','sales advance','sales return',
    'purchase','warehouse purchase','supplier purchase','purchase payment','purchase advance',
    'purchase return','supplier payment','opening balance','opening stock','transfer',
    'inter transfer','loan received','loan repayment','capital investment','drawings',
    'production output','production input','stock in','stock out'];
  if(W.AYAN_NON_EXPENSE) W.AYAN_NON_EXPENSE.forEach(function(t){ if(NON_EXP.indexOf(t)<0) NON_EXP.push(t); });
  W.ayanPL=function(from,to){
    var db=D(),tx=(db.tx||[]).filter(posted).filter(function(t){
      var d=String(t.date||'');return (!from||d>=from)&&(!to||d<=to);});
    var sum=function(f){return tx.filter(f).reduce(function(s,t){return s+num(t.amount||t.amt);},0);};
    var sales=sum(function(t){return low(t.type)==='sale'||low(t.type)==='warehouse sale';});
    var salesRet=sum(function(t){return low(t.type)==='sales return';});
    var openPos=from?stockPosition(from).cogs:0;
    var cogs=Math.max(0,stockPosition(to).cogs-openPos);
    var expMap={};
    tx.forEach(function(t){var ty=String(t.type||'Other');
      if(NON_EXP.indexOf(low(ty))>=0) return;
      expMap[ty]=(expMap[ty]||0)+num(t.amount||t.amt);});
    /* FIX: the 0.5% the buyer withholds at source never appeared anywhere.
       It is taken off the receivable — correctly, you will never collect it —
       but with nothing recorded against it the books went out by 0.5% of
       every credit sale. It is a cost of making the sale, so it is shown as
       one, and both sides tie again. */
    var _wht=tx.reduce(function(s,t){return s+num(t.salesTaxAmt);},0);
    if(_wht) expMap['Tax deducted at source']=(expMap['Tax deducted at source']||0)+_wht;
    /* Truck rent and the agent / QC / unloading / other costs recorded on
       each transaction. They were never taken off profit at all. */
    var _side=(typeof W.ayanTxSideCosts==='function')?W.ayanTxSideCosts(tx):0;
    if(_side) expMap['Transport & handling']=(expMap['Transport & handling']||0)+_side;
    /* The fee, interest and charges the invoice financier takes. A real cost
       of the sale; it was in nobody's total before. */
    var _fin=(typeof W.ayanFinanceCharges==='function')?W.ayanFinanceCharges(false):0;
    if(_fin) expMap['Finance charges']=(expMap['Finance charges']||0)+_fin;
    var totalExp=Object.keys(expMap).reduce(function(s,k){return s+expMap[k];},0);
    var netSales=sales-salesRet, gross=netSales-cogs;
    return {tx:tx,sales:sales,salesRet:salesRet,netSales:netSales,cogs:cogs,
            grossProfit:gross,expenses:expMap,totalExp:totalExp,netProfit:gross-totalExp};
  };
  var _pl=W.renderProfitLoss;
  if(typeof _pl==='function'){
    W.renderProfitLoss=function(){
      try{_pl.apply(this,arguments);}catch(e){}
      try{
        var el=document.getElementById('pg-profitloss'); if(!el) return;
        var r=W.plRange?W.plRange():[null,null], p=W.ayanPL(r[0],r[1]);
        /* FIX: a fresh card was appended every time the page was opened, so
           after four visits the screen showed four Profit & Loss tables. */
        var old=document.getElementById('ayan-pl-corrected'); if(old) old.remove();
        var box=document.createElement('div');
        box.id='ayan-pl-corrected';
        box.className='card';box.style.cssText='max-width:700px;margin:14px auto 0;';
        box.innerHTML='<h3 style="margin:0 0 4px;">🧾 Cost-of-Sales Corrected View</h3>'+
          '<div style="font-size:11px;color:#6b7280;margin-bottom:10px;">Gross profit below uses weighted-average COGS on goods actually sold, not total purchases.</div>'+
          '<div class="ayan-scrollx"><table style="width:100%;border-collapse:collapse;font-size:13px;">'+
          [['Net Sales',p.netSales],['Cost of Goods Sold',-p.cogs],['Gross Profit',p.grossProfit],
           ['Operating Expenses',-p.totalExp],['Net Profit / (Loss)',p.netProfit]].map(function(x,i){
            var strong=i===2||i===4;
            return '<tr style="'+(strong?'background:#f0fdf4;font-weight:800;':'')+'"><td style="padding:9px 12px;border-bottom:1px solid #f0f0f0;">'+x[0]+
              '</td><td style="padding:9px 12px;text-align:right;border-bottom:1px solid #f0f0f0;color:'+(x[1]<0?'#dc2626':'#166534')+';">'+money(x[1])+'</td></tr>';}).join('')+
          '</table></div>';
        el.appendChild(box);
      }catch(e){}
    };
  }

  /* ═══ 4. APPROVAL GATE ══════════════════════════════════════════
     Transactions above the approval threshold are marked Pending and
     excluded from balances and reports until approved.               */
  var _exec=W._executeSaveTx;
  if(typeof _exec==='function'){
    W._executeSaveTx=function(tx,editId){
      try{
        var db=D(),limit=num((db.settings||{}).approvalLimit);
        if(limit>0&&num(tx.amount)>=limit&&!tx.approved&&!(W.isAdminOrOwner&&W.isAdminOrOwner())){
          tx.status='Pending';tx.approved=false;
          (db.pendingApprovals=db.pendingApprovals||[]).push({id:tx.id,amount:num(tx.amount),party:tx.party,date:tx.date});
        }
      }catch(e){}
      return _exec.apply(this,arguments);
    };
  }
  var _appr=W.approveTransaction;
  if(typeof _appr==='function'){
    W.approveTransaction=function(id){
      var r=_appr.apply(this,arguments);
      try{D().pendingApprovals=(D().pendingApprovals||[]).filter(function(a){return a.id!==id;});
          recomputeBalances({apply:true});}catch(e){}
      return r;
    };
  }

  /* ═══ 5. GORGEOUS PRINTING ══════════════════════════════════════ */
  function company(){
    var s=D().settings||{},b=D().branding||{};
    return {name:b.companyName||s.companyName||'AYAN AGRO INTERNATIONAL LIMITED',
            tagline:b.tagline||s.tagline||'Agro Commodities · Milling · Distribution',
            addr:b.address||s.address||'',phone:b.phone||s.phone||'',email:b.email||s.email||'',
            logo:b.logo||s.logo||'🌾'};
  }
  function dressPrintArea(){
    var pa=document.getElementById('print-area'); if(!pa) return;
    /* FIX (2026-08-25, duplicate letterhead on every printed document): this
       check was meant to skip injecting a second header when #print-area
       already carries its own, but the real letterhead template (built
       right into #print-modal, see .lh-wrap below) never matched any of
       .lh-head/.print-header/.letterhead/.doc-letterhead — those class
       names belong to an older template that no longer exists in this
       file. So hasOwnHead was always false, and this function stacked its
       own "AYAN AGRO INTERNATIONAL LIMITED" header on top of the real one
       on every single voucher, invoice, challan, receipt and report —
       exactly the doubled header seen on every printout. Added .lh-wrap so
       it actually recognizes the letterhead that's really there. */
    var hasOwnHead = !!pa.querySelector('.lh-head,.print-header,.letterhead,.doc-letterhead,.lh-wrap');
    if(!hasOwnHead && !pa.querySelector('.ayan-lh3d')){
      var c=company(),h=document.createElement('div');
      h.className='ayan-lh3d';
      h.innerHTML='<div class="ayan-lh3d-row"><div class="ayan-seal">'+
        (String(c.logo).indexOf('http')===0?'<img src="'+c.logo+'" alt="" style="width:100%;height:100%;object-fit:contain;border-radius:12px;">':c.logo)+
        '</div><div><div class="ayan-lh3d-name">'+c.name+'</div><div class="ayan-lh3d-tag">'+c.tagline+'</div></div>'+
        '<div class="ayan-lh3d-contact">'+[c.addr,c.phone,c.email].filter(Boolean).join('<br>')+'</div></div>';
      var rule=document.createElement('div');rule.className='ayan-rule';
      pa.insertBefore(rule,pa.firstChild);pa.insertBefore(h,pa.firstChild);
    }
    if(!pa.querySelector('.ayan-wm')){
      var wm=document.createElement('div');wm.className='ayan-wm';wm.textContent=company().name.split(' ')[0];
      pa.appendChild(wm);
    }
    /* FIX (same duplicate-detection bug as the header above): #print-area's
       real template already ends in a .print-sigfooter block with its own
       "computer-generated document" line (see openPrintModal). Only add
       this second footer when that one is genuinely missing. */
    if(!pa.querySelector('.ayan-page-foot') && !pa.querySelector('.print-sigfooter')){
      var f=document.createElement('div');f.className='ayan-page-foot';f.setAttribute('style','display:flex;justify-content:space-between;gap:16px;align-items:center;font-size:10px;color:#557;margin-top:8px;padding-top:6px;border-top:1px dashed #cfd8d2;');
      f.innerHTML='<span>'+company().name+'</span><span>Printed '+new Date().toLocaleString()+'</span>';
      pa.appendChild(f);
    }
    pa.querySelectorAll('table').forEach(function(t){if(!t.className)t.className='print-table';});
  }
  W.ayanDressPrint=dressPrintArea;
  W.addEventListener('beforeprint',dressPrintArea);
  ['openPrintModal','showPrintModal','doPrint','printDoc'].forEach(function(fn){
    var orig=W[fn];
    if(typeof orig==='function') W[fn]=function(){var r=orig.apply(this,arguments);setTimeout(dressPrintArea,60);return r;};
  });

  /* ═══ 6. RESPONSIVE TABLE WRAPPING (runtime) ════════════════════ */
  function wrapTables(root){
    (root||document).querySelectorAll('table').forEach(function(t){
      if(t.closest('.ayan-scrollx')||t.closest('#print-area')) return;
      /* PERF: the newer .ayan-tscroll system (sticky header + frozen column)
         already wraps this table — don't nest a second wrapper around it. */
      if(t.closest('.ayan-tscroll')) return;
      var w=document.createElement('div');w.className='ayan-scrollx';
      t.parentNode.insertBefore(w,t);w.appendChild(t);
    });
  }
  W.ayanWrapTables=wrapTables;
  var _nav=W.nav;
  if(typeof _nav==='function'){
    W.nav=function(){var r=_nav.apply(this,arguments);setTimeout(function(){try{wrapTables();}catch(e){}},80);return r;};
  }
  var pending=null;
  try{
    new MutationObserver(function(){clearTimeout(pending);pending=setTimeout(function(){try{wrapTables();}catch(e){}},250);})
      .observe(document.body,{childList:true,subtree:true});
  }catch(e){}

  /* ═══ 7. BOOT ═══════════════════════════════════════════════════ */
  function boot(){
    try{wrapTables();}catch(e){}
    try{
      var r=recomputeBalances({apply:false});
      if(r&&r.drift.length){
        console.warn('[AYAN] '+r.drift.length+' balance(s) drifted from transaction history:',r.drift);
        recomputeBalances({apply:true});
      }
    }catch(e){}
    try{W.renderStockSummary&&document.getElementById('stk-summary-body')&&W.renderStockSummary();}catch(e){}
    var vp=document.querySelector('meta[name=viewport]');
    if(vp) vp.setAttribute('content','width=device-width, initial-scale=1.0, viewport-fit=cover');
  }
  if(document.readyState==='complete') setTimeout(boot,400);
  else W.addEventListener('load',function(){setTimeout(boot,400);});
})();
</script>
<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-paydate-automation">
/* Delivery date + payment date automation.
   - Delivery date defaults to the transaction date (editable — change it
     whenever the actual delivery day differs).
   - Payment terms: net 15 for B&R B, CRB O and With Bran Husk; net 7 for
     every other product.
   - Matching runs every Monday and Wednesday (payment advice day); money
     lands the next day — Tuesday for Monday matching, Thursday for
     Wednesday matching. The due date is rolled forward to the first
     Monday/Wednesday on or after it, and payment is the following day. */
(function(){
  "use strict";
  var W = window;
  var NET15 = [/b\s*&\s*r\s*b/i, /\bcrb\s*o/i, /bran\s*husk/i];
  W.AYAN_PAY_TERMS = { net15Patterns: NET15, defaultNetDays: 7, net15Days: 15 };

  function netDays(prod){
    var p = String(prod||'');
    for(var i=0;i<NET15.length;i++){ if(NET15[i].test(p)) return W.AYAN_PAY_TERMS.net15Days; }
    return W.AYAN_PAY_TERMS.defaultNetDays;
  }
  function iso(d){
    return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
  }
  function toDate(s){
    var k = (typeof W._dk==='function') ? W._dk(s) : s;
    if(!k) return null;
    var d = new Date(k+'T00:00:00');
    return isNaN(d) ? null : d;
  }
  /* first Monday(1) / Wednesday(3) on or after the due date = advice day */
  function adviceFrom(due){
    var d = new Date(due.getTime());
    for(var i=0;i<8;i++){
      var w = d.getDay();
      if(w===1 || w===3) return d;
      d.setDate(d.getDate()+1);
    }
    return d;
  }
  function schedule(baseDate, prod){
    var b = toDate(baseDate);
    if(!b) return null;
    var due = new Date(b.getTime());
    due.setDate(due.getDate()+netDays(prod));
    var adv = adviceFrom(due);
    var pay = new Date(adv.getTime());
    pay.setDate(pay.getDate()+1);           // Mon advice -> Tue, Wed advice -> Thu
    return { netDays:netDays(prod), dueDate:iso(due), adviceDate:iso(adv), payDate:iso(pay) };
  }
  W.ayanPaymentSchedule = schedule;

  function el(id){ return document.getElementById(id); }
  function isAuto(node){ return node && node.dataset.ayanManual !== '1'; }

  function syncTxDates(force){
    var dateEl = el('tx-date'), delEl = el('tx-deliverydate'), payEl = el('tx-paydate'), prodEl = el('tx-prod');
    if(!dateEl) return;
    var txDate = dateEl.value;
    if(!txDate) return;
    if(delEl && (force || !delEl.value || isAuto(delEl))){
      if(!delEl.value || isAuto(delEl)) delEl.value = txDate;   // same day by default, still editable
    }
    var base = (delEl && delEl.value) ? delEl.value : txDate;
    var s = schedule(base, prodEl ? prodEl.value : '');
    if(payEl && s && (force || !payEl.value || isAuto(payEl))){
      payEl.value = s.payDate;
      payEl.title = 'Net '+s.netDays+' → due '+s.dueDate+', advice '+s.adviceDate+', payment '+s.payDate;
    }
  }
  W.ayanSyncTxDates = syncTxDates;

  function markManual(e){ if(e && e.isTrusted && e.target) e.target.dataset.ayanManual = '1'; }

  function wire(){
    ['tx-deliverydate','tx-paydate'].forEach(function(id){
      var n = el(id);
      if(n && !n.dataset.ayanWired){ n.dataset.ayanWired='1'; n.addEventListener('change', markManual); }
    });
    ['tx-date','tx-prod','tx-type'].forEach(function(id){
      var n = el(id);
      if(n && !n.dataset.ayanWired2){
        n.dataset.ayanWired2='1';
        n.addEventListener('change', function(){ syncTxDates(false); });
        n.addEventListener('input',  function(){ syncTxDates(false); });
      }
    });
  }
  document.addEventListener('DOMContentLoaded', wire);
  wire();
  window._erpWatch(wire);   // FIX 8

  /* Reset the manual flags whenever the transaction modal is (re)opened, then
     pre-fill both dates. */
  var origOpen = W.openModal;
  if(typeof origOpen === 'function'){
    W.openModal = function(id){
      var r = origOpen.apply(this, arguments);
      if(id === 'mTx'){
        ['tx-deliverydate','tx-paydate'].forEach(function(f){ var n=el(f); if(n) delete n.dataset.ayanManual; });
        wire();
        setTimeout(function(){ syncTxDates(false); }, 30);
      }
      return r;
    };
  }

  /* Make sure a saved transaction always carries the dates + terms, even when
     the form was submitted without touching them. */
  var origSave = W.saveTx;
  if(typeof origSave === 'function'){
    W.saveTx = function(){
      syncTxDates(false);
      return origSave.apply(this, arguments);
    };
  }
  var origExec = W._executeSaveTx;
  if(typeof origExec === 'function'){
    W._executeSaveTx = function(tx, editId){
      try{
        if(tx && typeof tx === 'object'){
          if(!tx.deliverydate && tx.date) tx.deliverydate = (typeof W._dk==='function') ? W._dk(tx.date) : tx.date;
          var s = schedule(tx.deliverydate || tx.date, tx.prod);
          if(s){
            tx.paymentNetDays = s.netDays;
            tx.paymentDueDate = s.dueDate;
            tx.payAdviceDate  = s.adviceDate;
            if(!tx.paydate) tx.paydate = s.payDate;
          }
        }
      }catch(e){}
      return origExec.apply(this, arguments);
    };
  }
})();
</script>
<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-payment-cycle">
/* ═══════════════════════════════════════════════════════════════════════
   PAYMENT MATURITY CYCLE ENGINE
   Business rule: payment "advice" is issued every Monday & Wednesday, and
   funds move out the next day — i.e. anything that matures (its due date
   falls) on or before Monday is paid Tuesday; anything maturing after
   Monday but on or before Wednesday is paid Thursday. Net terms: 15 days
   for B&R B / CRB O / With Bran Husk, 7 days for everything else.
   Exposes window.ayanPaymentSchedule(baseDate, product) for the rest of
   the app (payment-advice report, dashboard "Next Payment" KPI, etc).
   ═══════════════════════════════════════════════════════════════════════ */
(function(){
  "use strict";
  var W = window;
  var NET15_PRODUCTS = ['b&r b', 'crb o', 'with bran husk'];

  function dk(v){ try{ return (typeof W._dk === 'function') ? W._dk(v) : v; }catch(e){ return v; } }

  function netDaysForProduct(prod){
    var p = String(prod || '').trim().toLowerCase();
    if(!p) return 7;
    for(var i = 0; i < NET15_PRODUCTS.length; i++){
      if(p === NET15_PRODUCTS[i] || p.indexOf(NET15_PRODUCTS[i]) >= 0) return 15;
    }
    return 7;
  }

  // Given any date, roll forward (inclusive) to the next Monday-or-Wednesday
  // "advice" day, following the up-to-Monday→Tuesday / up-to-Wednesday→Thursday
  // maturity cycle, and return both the advice day and the payment day.
  function nextAdviceAndPayDay(d){
    var dow = d.getDay(); // 0=Sun..6=Sat
    var advice = new Date(d.getTime());
    var toWed = (3 - dow + 7) % 7;
    var toMon = (1 - dow + 7) % 7;
    if(dow === 2 || dow === 3){
      // Tuesday or Wednesday → next Wednesday cutoff → paid Thursday
      advice.setDate(advice.getDate() + toWed);
    } else {
      // Thursday, Friday, Saturday, Sunday or Monday → next Monday cutoff → paid Tuesday
      advice.setDate(advice.getDate() + toMon);
    }
    var pay = new Date(advice.getTime());
    pay.setDate(pay.getDate() + 1);
    return { advice: advice, pay: pay };
  }

  W.ayanPaymentSchedule = function(baseDate, product){
    var baseKey = dk(baseDate);
    if(!baseKey) return null;
    var base = new Date(baseKey + 'T00:00:00');
    if(isNaN(base)) return null;
    var netDays = netDaysForProduct(product);
    var due = new Date(base.getTime());
    due.setDate(due.getDate() + netDays);
    var ap = nextAdviceAndPayDay(due);
    return {
      netDays: netDays,
      dueDate: dk(due),
      adviceDate: dk(ap.advice),
      payDate: dk(ap.pay)
    };
  };

  // Aggregates all outstanding (unpaid) purchase-side amounts into their
  // maturity-cycle payment date, and returns the nearest upcoming payment
  // (or, if everything is already overdue, the most urgent overdue one).
  W.computeNextPaymentByCycle = function(){
    var d = (W.DB || {});
    var txs = Array.isArray(d.tx) ? d.tx : [];
    var todayKey = dk(new Date());
    var groups = {}; // payDate -> {amount, count}
    txs.forEach(function(t){
      var type = String(t.type || '');
      var isPurchase = (typeof W.isCogsTx === 'function') ? W.isCogsTx(t) : /purchase/i.test(type);
      if(!isPurchase) return;
      var amount = (typeof W.txAmt === 'function') ? W.txAmt(t) : (parseFloat(t.amt != null ? t.amt : t.amount) || 0);
      var paid = parseFloat(t.paid) || 0;
      var due = (t.due != null && t.due !== '') ? parseFloat(t.due) : (amount - paid);
      if(!(due > 0)) return; // fully settled — nothing left to pay
      var base = t.deliverydate || t.date;
      var s = W.ayanPaymentSchedule(base, t.prod);
      var payDate = s ? s.payDate : null;
      if(!payDate) return;
      if(!groups[payDate]) groups[payDate] = { amount: 0, count: 0 };
      groups[payDate].amount += due;
      groups[payDate].count += 1;
    });
    var dates = Object.keys(groups).sort();
    if(!dates.length) return null;
    var upcoming = dates.filter(function(dt){ return dt >= todayKey; });
    var chosen = upcoming.length ? upcoming[0] : dates[dates.length - 1];
    return {
      date: chosen,
      amount: groups[chosen].amount,
      count: groups[chosen].count,
      overdue: chosen < todayKey,
      allDates: dates.map(function(dt){ return { date: dt, amount: groups[dt].amount, count: groups[dt].count }; })
    };
  };
})();
</script>
<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-pay-report">
/* Payment advice / due report + delivery-vs-transaction mismatch review. */
(function(){
  "use strict";
  var W=window, D=document;
  function db(){ try{ return (typeof DB!=='undefined'&&DB)?DB:(W.DB||{}); }catch(e){ return W.DB||{}; } }
  function txs(){ var d=db(); return Array.isArray(d.tx)?d.tx:[]; }
  function dk(v){ try{ return (typeof W._dk==='function')?W._dk(v):v; }catch(e){ return v; } }
  function money(n){ try{ return (typeof W.f==='function')?W.f(n):('৳'+(parseFloat(n)||0).toFixed(2)); }catch(e){ return String(n||0); } }
  function esc(s){ return String(s==null?'':s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];}); }
  function today(){ var d=new Date(); d.setHours(0,0,0,0); return d; }
  function parse(s){ var k=dk(s); if(!k) return null; var d=new Date(k+'T00:00:00'); return isNaN(d)?null:d; }
  function fmt(s){ var d=parse(s); if(!d) return '-'; return d.toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}); }
  function dow(s){ var d=parse(s); return d?['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][d.getDay()]:''; }
  function amt(t){ return parseFloat(t.netAmt||t.amount||t.amt)||0; }

  function sched(t){
    var base=t.deliverydate||t.date;
    var s=(typeof W.ayanPaymentSchedule==='function')?W.ayanPaymentSchedule(base,t.prod):null;
    return {
      netDays: t.paymentNetDays || (s?s.netDays:null),
      dueDate: t.paymentDueDate || (s?s.dueDate:null),
      adviceDate: t.payAdviceDate || (s?s.adviceDate:null),
      payDate: dk(t.paydate) || (s?s.payDate:null)
    };
  }
  /* ---------- panel shell ---------- */
  function ensureUI(){
    if(D.getElementById('ayanPayBtn')) return;
    var css=D.createElement('style');
    css.textContent=[
      /* FIX (2026-08-24, extended from the mobile-only version below): a
         "Payments" pill 18 characters wide, opaque, fixed at right:16px,
         was confirmed sitting directly on top of the Balance Sheet's own
         NET WORTH figure on an ordinary 1440px desktop window — not just
         on a phone. Same family of bug as #v2-launcher above (independent
         floating widgets with no awareness of the page underneath); same
         fix in spirit — shrink it to a small icon-only circle at rest, on
         every screen size, so it can no longer blot out a whole line of
         real numbers. It still opens the full "Payments" panel on click;
         only the resting button shrank. */
      '#ayanPayBtn{position:fixed;right:16px;bottom:160px;z-index:99998;border:0;border-radius:50%;',
      'width:44px;height:44px;padding:0;display:flex;align-items:center;justify-content:center;',
      'font:600 18px system-ui,sans-serif;color:#fff;background:linear-gradient(135deg,#16a34a,#0f3d26);cursor:pointer;',
      'box-shadow:0 6px 20px rgba(0,0,0,.28)}',
      '@media (max-width:480px){#ayanPayBtn{left:14px;right:auto;bottom:80px;}',
      '#ayanPayPanel{left:8px;right:8px;bottom:128px;width:auto;}}',
      '#ayanPayPanel{position:fixed;right:16px;bottom:208px;width:min(780px,94vw);max-height:74vh;z-index:99999;display:none;',
      'flex-direction:column;background:#fff;color:#0f172a;border:1px solid #d1d5db;border-radius:14px;overflow:hidden;',
      'box-shadow:0 18px 50px rgba(0,0,0,.28);font:13px system-ui,sans-serif}',
      '#ayanPayPanel.open{display:flex}',
      '#ayanPayPanel header{display:flex;align-items:center;gap:8px;padding:10px 12px;background:#f1f5f9;border-bottom:1px solid #e2e8f0}',
      '#ayanPayPanel header b{flex:1;font-size:13px;color:#0f172a}',
      '#ayanPayPanel .tabbtn{background:#e2e8f0;border:0;color:#334155;padding:6px 12px;border-radius:8px;cursor:pointer;font:600 12px system-ui}',
      '#ayanPayPanel .tabbtn.on{background:#16a34a;color:#fff}',
      '#ayanPayBody{overflow:auto;padding:10px 12px;background:#fff}',
      '#ayanPayBody table{width:100%;border-collapse:collapse;font-size:11.5px;table-layout:fixed}',
      '#ayanPayBody tr{background:transparent!important}',
      '#ayanPayBody th{background:#fff!important;color:#64748b!important;text-align:left;font-weight:600;padding:6px;border-bottom:1px solid #e2e8f0;white-space:nowrap}',
      '#ayanPayBody td{background:transparent!important;color:#0f172a!important;padding:6px;border-bottom:1px solid #f1f5f9;word-break:break-word;white-space:normal}',
      '#ayanPayBody tr.grp td{background:#ecfdf5!important;color:#065f46!important;font-weight:700}',
      '#ayanPayBody .warn,#ayanPayBody td.warn{color:#b45309!important}',
      '#ayanPayBody .ayanmuted{color:#64748b!important}',
      '#ayanPayBody button.fix{background:#16a34a;border:0;color:#fff!important;border-radius:6px;padding:3px 8px;cursor:pointer;font-size:11px}',
      'tr.ayan-datemismatch>td{background:rgba(251,191,36,.18)!important}'
    ].join('');
    D.head.appendChild(css);

    var btn=D.createElement('button');
    btn.id='ayanPayBtn'; btn.type='button'; btn.textContent='💳'; btn.title='Payment schedule';
    btn.onclick=function(){ var p=D.getElementById('ayanPayPanel'); p.classList.toggle('open'); if(p.classList.contains('open')) render(); };
    D.body.appendChild(btn);

    var p=D.createElement('div');
    p.id='ayanPayPanel';
    p.innerHTML='<header><b>Payment schedule</b>'+
      '<button class="tabbtn on" data-tab="due">Advice &amp; payments</button>'+
      '<button class="tabbtn" data-tab="mis">Date mismatches</button>'+
      '<button class="tabbtn" data-tab="close">✕</button></header><div id="ayanPayBody"></div>';
    D.body.appendChild(p);
    p.querySelectorAll('.tabbtn').forEach(function(b){
      b.onclick=function(){
        if(b.dataset.tab==='close'){ p.classList.remove('open'); return; }
        p.querySelectorAll('.tabbtn').forEach(function(x){ x.classList.remove('on'); });
        b.classList.add('on'); W._ayanPayTab=b.dataset.tab; render();
      };
    });
  }

  /* ---------- tab 1: advice & payment report ---------- */
  function renderDue(){
    var t0=today(), rows=[];
    txs().forEach(function(t){
      var s=sched(t);
      if(!s.payDate) return;
      rows.push({t:t,s:s});
    });
    rows.sort(function(a,b){ return (a.s.payDate<b.s.payDate)?-1:(a.s.payDate>b.s.payDate?1:0); });
    var upcoming=rows.filter(function(r){ var d=parse(r.s.payDate); return d && d>=t0; });
    var overdue =rows.filter(function(r){ var d=parse(r.s.payDate); return d && d<t0; });
    var html='';
    function table(list,title,muted){
      if(!list.length) return '';
      var total=list.reduce(function(a,r){ return a+amt(r.t); },0);
      var h='<div style="margin:6px 0 4px;font-weight:700;'+(muted?'color:#b45309':'color:#065f46')+'">'+title+
        ' <span class="ayanmuted">('+list.length+' entries · '+money(total)+')</span></div>'+
        '<table><thead><tr><th>Payment date</th><th>Advice</th><th>Party</th><th>Product</th><th>Invoice</th><th>Terms</th><th style="text-align:right">Amount</th></tr></thead><tbody>';
      var last=null, grpTotal=0, buf='';
      list.forEach(function(r){
        if(r.s.payDate!==last){
          if(last) h+=buf;
          last=r.s.payDate;
          h+='<tr class="grp"><td colspan="6" style="font-weight:700">'+fmt(last)+' ('+dow(last)+')</td><td style="font-weight:700;text-align:right">'+
             money(list.filter(function(x){return x.s.payDate===last;}).reduce(function(a,x){return a+amt(x.t);},0))+'</td></tr>';
          buf='';
        }
        h+='<tr><td>'+fmt(r.s.payDate)+'</td><td>'+fmt(r.s.adviceDate)+' <span class="ayanmuted">('+dow(r.s.adviceDate)+')</span></td>'+
           '<td>'+esc(r.t.party||'-')+'</td><td>'+esc(r.t.prod||'-')+'</td><td>'+esc(r.t.inv||'-')+'</td>'+
           '<td>Net '+(r.s.netDays||'-')+'<span class="ayanmuted"> · due '+fmt(r.s.dueDate)+'</span></td>'+
           '<td style="text-align:right">'+money(amt(r.t))+'</td></tr>';
      });
      return h+'</tbody></table>';
    }
    html+=table(overdue,'Past / overdue payment dates',true);
    html+=table(upcoming,'Upcoming advice &amp; payments',false);
    if(!html) html='<div class="ayanmuted">No transactions with a payment date yet.</div>';
    html='<div class="ayanmuted" style="margin-bottom:8px">Advice is issued Monday &amp; Wednesday; money lands the next day (Tue / Thu). Net 15 for B&amp;R B, CRB O and With Bran Husk — net 7 for everything else.</div>'+html;
    return html;
  }

  /* ---------- tab 2: delivery vs transaction date mismatches ---------- */
  function mismatches(){
    return txs().filter(function(t){
      var a=dk(t.date), b=dk(t.deliverydate);
      return a && b && a!==b;
    });
  }
  function renderMis(){
    var list=mismatches();
    if(!list.length) return '<div class="ayanmuted">Every delivery date matches its transaction date.</div>';
    var h='<div class="ayanmuted" style="margin-bottom:8px">Delivery date differs from the transaction date on '+list.length+
      ' entr'+(list.length===1?'y':'ies')+'. Keep it if the delivery really happened on another day, or align it in one click.</div>'+
      '<table><thead><tr><th>Invoice</th><th>Party</th><th>Product</th><th>Transaction</th><th>Delivery</th><th>Gap</th><th></th></tr></thead><tbody>';
    list.forEach(function(t){
      var a=parse(t.date), b=parse(t.deliverydate);
      var gap=(a&&b)?Math.round((b-a)/86400000):0;
      h+='<tr><td>'+esc(t.inv||'-')+'</td><td>'+esc(t.party||'-')+'</td><td>'+esc(t.prod||'-')+'</td>'+
         '<td>'+fmt(t.date)+'</td><td class="warn">'+fmt(t.deliverydate)+'</td>'+
         '<td class="warn">'+(gap>0?'+':'')+gap+'d</td>'+
         '<td><button class="fix" data-id="'+esc(t.id)+'">Align</button></td></tr>';
    });
    return h+'</tbody></table>';
  }

  function align(id){
    var t=txs().filter(function(x){ return String(x.id)===String(id); })[0];
    if(!t) return;
    t.deliverydate=dk(t.date);
    var s=(typeof W.ayanPaymentSchedule==='function')?W.ayanPaymentSchedule(t.deliverydate,t.prod):null;
    if(s){ t.paymentNetDays=s.netDays; t.paymentDueDate=s.dueDate; t.payAdviceDate=s.adviceDate; t.paydate=s.payDate; }
    try{ if(typeof W.saveDB==='function') W.saveDB(); }catch(e){}
    try{ if(typeof W.renderTx==='function') W.renderTx(); }catch(e){}
    try{ if(typeof W.toast==='function') W.toast('Delivery date aligned','s'); }catch(e){}
    render();
  }

  function render(){
    ensureUI();
    var body=D.getElementById('ayanPayBody'); if(!body) return;
    var tab=W._ayanPayTab||'due';
    body.innerHTML=(tab==='mis')?renderMis():renderDue();
    body.querySelectorAll('button.fix').forEach(function(b){ b.onclick=function(){ align(b.dataset.id); }; });
  }
  W.ayanPayReport=render;

  /* ---------- highlight mismatching rows in the transactions table ---------- */
  function flagRows(){
    var set={}; mismatches().forEach(function(t){ set[dk(t.date)+'|'+dk(t.deliverydate)]=1; });
    D.querySelectorAll('table tbody tr').forEach(function(tr){
      var tds=tr.children; if(tds.length<8) return;
      var a=dk((tds[5].textContent||'').trim()), b=dk((tds[6].textContent||'').trim());
      if(a&&b&&a!==b&&set[a+'|'+b]){ tr.classList.add('ayan-datemismatch'); tr.title='Delivery date differs from the transaction date'; }
      else tr.classList.remove('ayan-datemismatch');
    });
  }
  function boot(){ ensureUI(); flagRows(); }
  D.addEventListener('DOMContentLoaded', boot);
  if(D.body) boot();
  window._erpWatch(flagRows);   // FIX 8
})();
</script>
<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-fix-pack">
/* ═══════════════════════════════════════════════════════════════════════
   AYAN ERP — FIX PACK
   FIX 3  Quota-safe storage: auto-trims, mirrors to IndexedDB, never fails silently
   FIX 5  Passwords stored as salted SHA-256 hashes instead of plaintext
   FIX 6  Stored data is stripped of HTML tags (the app renders it via innerHTML)
   ═══════════════════════════════════════════════════════════════════════ */
(function(){
  "use strict";
  var W=window, LS_KEY='rbo_v4';

  /* ── FIX 6: HTML-tag stripping ────────────────────────────────────────
     ~580 places render record data through innerHTML, so a party/product name
     containing markup would be injected into reports and print views. Values
     are cleaned once, on the way into storage. Keys holding intentional markup
     are skipped. */
  var HTML_KEYS={customTemplates:1,html:1,template:1,body:1,signature:1,logo:1,logoData:1,letterhead:1};
  function clean(str){
    return String(str)
      .replace(/<\s*\/?\s*(script|iframe|object|embed|style|link|meta|svg|img|form|input)\b[^>]*>/gi,'')
      .replace(/\son[a-z]+\s*=\s*("[^"]*"|'[^']*'|[^\s>]+)/gi,'')
      .replace(/javascript:/gi,'');
  }
  function sanitize(node,key,depth){
    if(depth>8||node==null) return node;
    if(typeof node==='string') return (node.indexOf('<')<0&&node.indexOf('javascript:')<0)?node:clean(node);
    if(Array.isArray(node)){ for(var i=0;i<node.length;i++) node[i]=sanitize(node[i],key,depth+1); return node; }
    if(typeof node==='object'){
      for(var k in node){ if(!Object.prototype.hasOwnProperty.call(node,k)) continue;
        if(HTML_KEYS[k]) continue;
        node[k]=sanitize(node[k],k,depth+1); }
    }
    return node;
  }
  W._erpSanitizeDB=function(){ try{ sanitize(W.DB,null,0); }catch(e){} };

  /* ── FIX 5: password hashing ──────────────────────────────────────────
     Plaintext passwords used to sit in localStorage in the clear. They are now
     salted SHA-256 hashes. Legacy plaintext records still log in once and are
     upgraded to a hash on that login, so nobody is locked out. */
  function sha256(msg){
    function rr(n,x){return (x>>>n)|(x<<(32-n));}
    var K=[0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
      0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
      0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
      0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
      0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
      0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
      0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
      0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
    var H=[0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
    var bytes=Array.from(new TextEncoder().encode(String(msg))),i;
    var bitLen=bytes.length*8; bytes.push(0x80);
    while(bytes.length%64!==56) bytes.push(0);
    for(i=7;i>=0;i--) bytes.push((i<4)?((bitLen/Math.pow(2,i*8))&0xff):0);
    for(var b=0;b<bytes.length;b+=64){
      var w=new Array(64),t;
      for(t=0;t<16;t++) w[t]=(bytes[b+t*4]<<24)|(bytes[b+t*4+1]<<16)|(bytes[b+t*4+2]<<8)|bytes[b+t*4+3];
      for(t=16;t<64;t++){
        var s0=rr(7,w[t-15])^rr(18,w[t-15])^(w[t-15]>>>3),
            s1=rr(17,w[t-2])^rr(19,w[t-2])^(w[t-2]>>>10);
        w[t]=(w[t-16]+s0+w[t-7]+s1)|0;
      }
      var a=H[0],c=H[1],d=H[2],e=H[3],f=H[4],g=H[5],h=H[6],l=H[7];
      for(t=0;t<64;t++){
        var S1=rr(6,f)^rr(11,f)^rr(25,f), ch=(f&g)^(~f&h),
            t1=(l+S1+ch+K[t]+w[t])|0,
            S0=rr(2,a)^rr(13,a)^rr(22,a), maj=(a&c)^(a&d)^(c&d),
            t2=(S0+maj)|0;
        l=h;h=g;g=f;f=(e+t1)|0;e=d;d=c;c=a;a=(t1+t2)|0;
      }
      H[0]=(H[0]+a)|0;H[1]=(H[1]+c)|0;H[2]=(H[2]+d)|0;H[3]=(H[3]+e)|0;
      H[4]=(H[4]+f)|0;H[5]=(H[5]+g)|0;H[6]=(H[6]+h)|0;H[7]=(H[7]+l)|0;
    }
    return H.map(function(x){return ('00000000'+(x>>>0).toString(16)).slice(-8);}).join('');
  }
  function salt(){
    var d=W.DB||{};
    if(!d.pwSalt){
      var r=''; try{ var a=new Uint8Array(16); crypto.getRandomValues(a);
        r=Array.prototype.map.call(a,function(x){return ('0'+x.toString(16)).slice(-2);}).join('');
      }catch(e){ r=String(Date.now())+Math.random(); }
      d.pwSalt=r;
    }
    return d.pwSalt;
  }
  /* SECURITY (2026-09-02): a single SHA-256 round is far too cheap for
     offline cracking. Hashes are now stretched over 20k iterations and
     tagged 'v2$'. Legacy one-round hashes still verify once and are
     re-hashed to v2 on that login, so nobody is locked out.
     pwLen (the plaintext password length) is no longer stored — it handed
     an attacker a free filter on any cracking attempt. */
  var _PW_ROUNDS = 20000;
  function _hashLegacy(pw){ return sha256(salt()+':'+String(pw==null?'':pw)); }
  W._erpHashPw=function(pw){
    var h = _hashLegacy(pw), sl = salt();
    for(var i=0;i<_PW_ROUNDS;i++) h = sha256(sl+':'+h+':'+i);
    return 'v2$'+h;
  };
  function _pwEq(a,b){                       // length-independent compare
    a=String(a); b=String(b);
    if(a.length!==b.length) return false;
    var d=0; for(var i=0;i<a.length;i++) d|=a.charCodeAt(i)^b.charCodeAt(i);
    return d===0;
  }
  W._erpPwOK=function(user,pw){
    if(!user) return false;
    if(user.pwLen!=null) delete user.pwLen;   // scrub the legacy length leak
    if(user.pwHash){
      if(String(user.pwHash).indexOf('v2$')===0) return _pwEq(user.pwHash, W._erpHashPw(pw));
      if(_pwEq(user.pwHash, _hashLegacy(pw))){ user.pwHash=W._erpHashPw(pw); return true; }  // upgrade
      return false;
    }
    if(user.password!=null && String(user.password)===String(pw)){   // legacy plaintext
      user.pwHash=W._erpHashPw(pw); delete user.password;
      return true;
    }
    return false;
  };
  W._erpHashSweep=function(){                 // converts any newly written plaintext
    try{
      (W.DB&&W.DB.users||[]).forEach(function(u){
        if(u&&u.password!=null&&u.password!==''){
          u.pwHash=W._erpHashPw(u.password); delete u.pwLen; delete u.password;
        }
      });
    }catch(e){}
  };

  /* ── FIX 3: quota-safe local persistence ──────────────────────────────
     Everything used to go into one localStorage key with a ~5MB ceiling; once
     it filled up every save failed. Now: try, and on quota overflow shed the
     audit log / notifications and retry, mirror every save into IndexedDB, and
     tell the user to export a backup only when both really fail. */
  var idb=null, idbTried=false;
  function openIDB(){
    if(idbTried) return Promise.resolve(idb);
    idbTried=true;
    return new Promise(function(res){
      try{
        var rq=indexedDB.open('ayan_erp_store',1);
        rq.onupgradeneeded=function(){ rq.result.createObjectStore('kv'); };
        rq.onsuccess=function(){ idb=rq.result; res(idb); };
        rq.onerror=function(){ res(null); };
      }catch(e){ res(null); }
    });
  }
  function mirrorIDB(json){
    openIDB().then(function(db){
      if(!db) return;
      try{ db.transaction('kv','readwrite').objectStore('kv').put(json,LS_KEY); }catch(e){}
    });
  }
  W._erpLoadIDB=function(){                   // recovery helper: window._erpLoadIDB()
    return openIDB().then(function(db){
      if(!db) return null;
      return new Promise(function(res){
        var rq=db.transaction('kv','readonly').objectStore('kv').get(LS_KEY);
        rq.onsuccess=function(){ res(rq.result||null); }; rq.onerror=function(){ res(null); };
      });
    });
  };
  function isQuota(e){
    return e&&(e.name==='QuotaExceededError'||e.name==='NS_ERROR_DOM_QUOTA_REACHED'||e.code===22||e.code===1014);
  }
  /* PERF: this used to deep-clone the whole DB (JSON.parse(JSON.stringify(DB)))
     on every single save, which froze the tab on large databases. Only the
     users array needs scrubbing, so we shallow-copy the root and clone just
     that one array. Nothing else is mutated. */
  function scrubbedDB(){
    var src = W.DB, clone = {};
    try{
      for(var k in src){ if(Object.prototype.hasOwnProperty.call(src,k)) clone[k]=src[k]; }
    }catch(e){ return src; }
    if(Array.isArray(src.users)){
      clone.users = src.users.map(function(u){
        if(u && typeof u === 'object'){
          var c = {}, kk;
          for(kk in u){ if(Object.prototype.hasOwnProperty.call(u,kk)) c[kk]=u[kk]; }
          delete c.password; delete c.pass; delete c.plainPassword;
          return c;
        }
        return u;
      });
    }
    return clone;
  }

  /* PERF: the deep HTML sanitise walks every record and runs regexes on every
     string. Running it on each keystroke-triggered save is what made saving
     hang. It is idempotent, so throttling it to once every few seconds keeps
     the exact same protection with none of the freeze. */
  var _lastSanitize = 0;
  function maybeSanitize(){
    var now = Date.now();
    if(now - _lastSanitize < 4000) return;
    _lastSanitize = now;
    try{ W._erpSanitizeDB(); }catch(e){}
  }

  W._erpLocalSave=function(){
    try{ W._erpHashSweep(); maybeSanitize(); }catch(e){}
    var safeDB, json;
    try{ safeDB = scrubbedDB(); json=JSON.stringify(safeDB); }catch(e){ return false; }
    try{
      localStorage.setItem(LS_KEY,json);
      mirrorIDB(json);
      if(typeof W._markSaved==='function') W._markSaved();
      return true;
    }catch(e){
      if(isQuota(e)){
        mirrorIDB(json);                                   // full copy is safe in IndexedDB
        try{
          var d=safeDB;
          if(Array.isArray(d.auditLog)&&d.auditLog.length>500) d.auditLog=d.auditLog.slice(-500);
          if(Array.isArray(d.notifications)&&d.notifications.length>100) d.notifications=d.notifications.slice(-100);
          if(Array.isArray(d.activityFeed)&&d.activityFeed.length>200) d.activityFeed=d.activityFeed.slice(-200);
          localStorage.setItem(LS_KEY,JSON.stringify(d));
          if(typeof W._markSaved==='function') W._markSaved();
          if(!W.__erpTrimWarned){ W.__erpTrimWarned=true;
            if(W.toast) W.toast('Storage was full — old audit-log entries were trimmed. Please export a backup.','w'); }
          return true;
        }catch(e2){}
      }
      if(typeof W._markUnsaved==='function') W._markUnsaved();
      if(W.toast) W.toast('Local save failed: '+e.message+' — export a backup now (a copy was kept in IndexedDB).','e');
      else alert('Local save failed — please export a backup.');
      return false;
    }
  };

  /* Route the app's own saveDB through the hardened layer whenever it is the
     localStorage path, and keep the transactions/tx alias alive after loads. */
  var origSave=W.saveDB;
  W.saveDB=function(){
    try{ W._erpTxAlias&&W._erpTxAlias(); W._erpHashSweep(); W._erpSanitizeDB(); }catch(e){}
    return (typeof origSave==='function')?origSave.apply(this,arguments):W._erpLocalSave();
  };
  var origLoad=W.loadDataFromServer;
  if(typeof origLoad==='function'){
    W.loadDataFromServer=function(){
      var r=origLoad.apply(this,arguments);
      try{ Promise.resolve(r).then(function(){ W._erpTxAlias&&W._erpTxAlias(); }); }catch(e){}
      return r;
    };
  }
  try{ W._erpTxAlias&&W._erpTxAlias(); W._erpHashSweep(); }catch(e){}
  console.info('[ERP Fix Pack] storage hardening, password hashing, HTML sanitising and DOM watchers active');
})();
</script>

<script nonce="<?php echo $cspNonceAttr; ?>" id="erp-durable-save-v4">
/* ═══════════════════════════════════════════════════════════════════════
   FIX 11 — DURABLE, VERIFIED SAVES  (data-loss fix)
   Why records could vanish:
     • saveDB() was owned by the PHP/server layer. With no api.php deployed
       (or before the offline probe finished) requireSession() found no token,
       showed the login screen and RETURNED WITHOUT WRITING ANYTHING —
       every record entered in that window was dropped from memory on reload.
     • Nothing ever verified that a write actually landed, so a blocked or
       full storage looked identical to a successful save.
   Now: every saveDB() writes locally FIRST, verifies the write by reading it
   back and comparing record counts, mirrors to IndexedDB, and only then tries
   the server. If storage is genuinely unavailable the user gets a loud,
   persistent banner instead of silent loss, and data is recovered from
   IndexedDB automatically on the next load.
   ═══════════════════════════════════════════════════════════════════════ */
(function(){
  "use strict";
  var W = window, LS_KEY = 'rbo_v4';
  var COUNT_KEYS = ['tx','cityFinance','customers','banks','invoices','challans','cheques','loans','inventory','employees'];

  function counts(d){
    var o = {};
    COUNT_KEYS.forEach(function(k){ if(Array.isArray(d && d[k])) o[k] = d[k].length; });
    return o;
  }

  function banner(msg){
    var el = document.getElementById('erp-storage-banner');
    if(!el){
      el = document.createElement('div');
      el.id = 'erp-storage-banner';
      el.style.cssText = 'position:fixed;left:0;right:0;top:0;z-index:99999;background:#b91c1c;color:#fff;'
        + 'font:700 13px/1.45 system-ui,sans-serif;padding:10px 14px;text-align:center;box-shadow:0 2px 10px rgba(0,0,0,.25);';
      document.body.appendChild(el);
    }
    el.innerHTML = '⚠️ ' + msg
      + ' <button data-x-click="try{exportBackup&&exportBackup()}catch(e){try{__erpEmergencyExport()}catch(_){}}" '
      + 'style="margin-left:10px;background:#fff;color:#b91c1c;border:0;border-radius:6px;padding:4px 10px;font-weight:800;cursor:pointer;">⬇ Export backup now</button>';
    el.style.display = 'block';
  }
  function clearBanner(){
    var el = document.getElementById('erp-storage-banner');
    if(el) el.style.display = 'none';
  }

  W.__erpEmergencyExport = function(){
    try{
      var a = document.createElement('a');
      a.href = URL.createObjectURL(new Blob([JSON.stringify(W.DB, null, 2)], {type:'application/json'}));
      a.download = 'ayan-erp-backup-' + new Date().toISOString().slice(0,19).replace(/[:T]/g,'-') + '.json';
      a.click();
    }catch(e){ alert('Export failed: ' + e.message); }
  };

  /* ── write + verify ─────────────────────────────────────────────────── */
  /* PERF: verification used to re-read AND re-parse the entire stored JSON on
     every save — a second full pass over megabytes of data that locked the UI.
     The write itself already throws when storage is unavailable, so a deep
     read-back is only needed occasionally (and on the very first save) to
     detect private-mode / blocked-storage browsers. */
  var _lastDeepVerify = 0;
  /* FIX (duplicate fields, belt and braces): banks and parties carry the
     same figure under two names (bal/balance, cap/capital) and different
     code paths update different ones — Factory Finance, for instance, only
     ever touched `bal`. Screens reading the other name then showed a stale
     figure. Whatever wrote last, the copies are squared up here, once, on
     the way to storage. */
  function syncAliasFields(){
    try{
      var fin = function(v){ var n=parseFloat(v); return isFinite(n)?n:null; };
      (W.DB.banks||[]).forEach(function(b){ var v=fin(b&&b.bal); if(b&&b.balance!==undefined&&v!==null) b.balance=v; });
      (W.DB.customers||[]).forEach(function(c){ var v=fin(c&&c.bal); if(c&&c.balance!==undefined&&v!==null) c.balance=v; });
      (W.DB.partners||[]).forEach(function(p){ var v=fin(p&&p.cap); if(p&&p.capital!==undefined&&v!==null) p.capital=v; });
    }catch(e){}
  }
  /* FIX (2026-08-27, "server is the boss, browser is backup"): this used to
     be the ONLY thing that decided whether a save counted as successful —
     clearBanner()/_markSaved() ran the moment localStorage.setItem()
     returned, whether or not the change had gone anywhere near the server.
     hasServerSession()/syncServer() below already existed and pushed to the
     real database, but only as a fire-and-forget "best-effort" call whose
     result nobody looked at — so two browsers (say, an Admin's and the
     person who entered the record) could each believe their own local copy
     was "saved" while disagreeing with each other and with the database.
     localFirstSave() is now purely a typing safety-net: it still writes
     locally first so nothing is lost to a mid-edit refresh or a momentary
     network blip, but it no longer marks anything as durably saved by
     itself. When there IS a server session, applyServerResult() (below,
     called after every save actually reaches — or fails to reach — the
     server) is the only thing allowed to clear the banner or mark the
     record saved. Local-only/offline deployments (no server configured)
     still fall back to treating a verified local write as "saved", exactly
     as before — nothing changes for that case. */
  function localFirstSave(){
    syncAliasFields();
    var wrote = false;
    if(typeof W._erpLocalSave === 'function'){
      try{ wrote = W._erpLocalSave() !== false; }catch(e){ wrote = false; }
    }
    if(!wrote){
      try{ localStorage.setItem(LS_KEY, JSON.stringify(W.DB)); wrote = true; }catch(e){ wrote = false; }
    }
    var verified = wrote;
    var now = Date.now();
    if(wrote && (!_lastDeepVerify || now - _lastDeepVerify > 30000)){
      _lastDeepVerify = now;
      var saved = null;
      try{
        var s = localStorage.getItem(LS_KEY);
        if(s){ saved = JSON.parse(s); }
      }catch(e){}
      if(saved){
        var want = counts(W.DB), got = counts(saved);
        verified = Object.keys(want).every(function(k){ return (got[k] || 0) >= want[k]; });
      }else{
        verified = false;
      }
    }
    /* Only let the LOCAL write claim "saved" when there's no server to be
       authoritative instead (a standalone/offline deployment). With a real
       server session, this stays silent either way — applyServerResult()
       (called once the actual database write below has been attempted) is
       what marks it saved or unsaved from here on. */
    if(!hasServerSession()){
      if(verified){
        W.__erpLastVerifiedSave = new Date();
        clearBanner();
        if(typeof W._markSaved === 'function'){ try{ W._markSaved(); }catch(e){} }
      }else{
        if(typeof W._markUnsaved === 'function'){ try{ W._markUnsaved(); }catch(e){} }
        banner('This browser is not storing your data (private mode, blocked storage or full storage). '
             + 'Nothing you enter will survive a refresh — download this file and open it directly, or export a backup.');
      }
    }else if(!verified){
      // Server exists, but even the local typing safety-net failed — worth
      // knowing about even though the save is still headed to the server.
      banner('This browser can’t keep a local safety copy of what you type (private mode, blocked or full storage). '
           + 'Your save still goes straight to the server, but a change made right before a refresh could be lost if the server request hasn’t completed yet.');
    }
    return verified;
  }
  W.__erpSaveCheck = function(){
    var s = null; try{ s = JSON.parse(localStorage.getItem(LS_KEY) || 'null'); }catch(e){}
    return { memory: counts(W.DB), stored: s ? counts(s) : null, lastVerifiedSave: W.__erpLastVerifiedSave || null };
  };

  /* ── own saveDB permanently, whatever later scripts assign ──────────── */
  var inner = W.saveDB, innerNow = W.saveDBNow;
  function hasServerSession(){
    /* FIX: this used to look for sessionStorage 'rbo_token'. The auth layer is
       cookie-based (HttpOnly ERPSESSID) and never writes that key, so the
       server sync branch below was dead code and NOTHING was ever pushed to
       MySQL. Trust the same signals the auth layer actually maintains. */
    try{
      if(W.ERP_CONFIG && W.ERP_CONFIG.USE_SERVER === false) return false;
      if(W.currentUser) return true;
      return !!(sessionStorage.getItem('rbo_user') || sessionStorage.getItem('ayan_session'));
    }catch(e){ return !!W.currentUser; }
  }
  /* PERF: saveDB() is called many times in a row while a single form is being
     submitted (once per line item, per recalculation, per render hook). Each
     call serialised the whole database, so the tab appeared to hang. Writes are
     now coalesced: the first call writes immediately, further calls inside the
     burst are merged into one trailing write. saveDBNow(), page hide and
     beforeunload always flush synchronously, so nothing can be lost. */
  var _pending = null, _lastWrite = 0, BURST_MS = 400, _lastCounts = null;
  /* Drives the visible "saved" state from the SERVER outcome, not the local
     write — see the FIX comment above localFirstSave(). serverOk is null
     when there's no server session (offline/standalone use), in which case
     localFirstSave() above has already set the saved/unsaved state itself
     and this is a no-op. */
  function applyServerResult(serverOk){
    if(serverOk === null) return;
    if(serverOk){
      W.__erpLastVerifiedSave = new Date();
      clearBanner();
      if(typeof W._markSaved === 'function'){ try{ W._markSaved(); }catch(e){} }
    }else{
      if(typeof W._markUnsaved === 'function'){ try{ W._markUnsaved(); }catch(e){} }
      banner('Your last change has not reached the server yet — check your connection. '
           + 'It is kept safely in this browser for now, but will not appear anywhere else, or survive switching devices, until it syncs.');
    }
  }
  function flushPending(){
    if(_pending){ clearTimeout(_pending); _pending = null; }
    _lastWrite = Date.now();
    _lastCounts = counts(W.DB);
    var localOk = localFirstSave();
    var serverPromise = syncServer(innerNow, W, []).then(function(serverOk){
      applyServerResult(serverOk);
      return serverOk;             // pass the real true/false/null through — applyServerResult() itself returns nothing
    });
    return { localOk: localOk, serverPromise: serverPromise };
  }
  /* FIX (data loss): coalescing deferred the write by up to 400 ms. A
     payment entered and followed by a quick reload was therefore still in
     memory only and came back missing. A save that changes how many
     records exist — a new transaction, drawdown, invoice or cheque — is
     now always written straight away; only repeat saves that change no
     record count (renders, recalculations) are still coalesced. */
  function countsChanged(){
    if(!_lastCounts) return true;
    var now = counts(W.DB);
    return Object.keys(now).some(function(k){ return now[k] !== _lastCounts[k]; })
        || Object.keys(_lastCounts).some(function(k){ return now[k] !== _lastCounts[k]; });
  }
  W.__erpFlushSave = flushPending;

  /* FIX (2026-08-27): used to call fn.apply(ctx,args) and throw the result
     away ("best-effort server sync") — a promise rejection from the fetch
     inside inner/innerNow wasn't even caught, since try/catch only guards
     synchronous throws. Now genuinely awaits the server call and resolves
     to true/false so applyServerResult() can trust it: true = the database
     has this change, false = it doesn't yet (offline, expired session,
     server error — the person needs to know), null = there's no server to
     ask (offline/standalone use), in which case the local write above is
     already the whole story. */
  function syncServer(fn, ctx, args){
    if(!hasServerSession() || typeof fn !== 'function') return Promise.resolve(null);
    return Promise.resolve().then(function(){ return fn.apply(ctx, args); })
      .then(function(r){ return r !== false; })
      .catch(function(e){ try{ console.warn('[server sync]', (e&&e.message)||e); }catch(_){} return false; });
  }

  function wrapper(){
    var now = Date.now();
    var ok;
    if(now - _lastWrite > BURST_MS || countsChanged()){
      ok = flushPending().localOk;              // never lose the local write
    }else{
      ok = !!W.__erpLastVerifiedSave;
      if(_pending) clearTimeout(_pending);
      _pending = setTimeout(function(){ _pending = null; flushPending(); }, BURST_MS);
      if(typeof W._markUnsaved === 'function'){ try{ W._markUnsaved(); }catch(e){} }
    }
    return ok;
  }
  function wrapperNow(){
    var f = flushPending();
    return f.serverPromise.then(function(serverOk){
      return serverOk === null ? f.localOk : serverOk;   // server outcome wins when there is one
    });
  }
  try{
    Object.defineProperty(W, 'saveDB', {
      configurable: true,
      get: function(){ return wrapper; },
      set: function(v){ inner = v; }          // later layers become the sync target, not the owner
    });
    Object.defineProperty(W, 'saveDBNow', {
      configurable: true,
      get: function(){ return wrapperNow; },
      set: function(v){ innerNow = v; }
    });
  }catch(e){ W.saveDB = wrapper; W.saveDBNow = wrapperNow; }

  /* ── recover from IndexedDB when localStorage came back empty ───────── */
  function recoverIfEmpty(){
    var s = null; try{ s = localStorage.getItem(LS_KEY); }catch(e){}
    var live = counts(W.DB), liveTotal = Object.keys(live).reduce(function(a,k){ return a + live[k]; }, 0);
    if(s && liveTotal) return;
    if(typeof W._erpLoadIDB !== 'function') return;
    W._erpLoadIDB().then(function(json){
      if(!json) return;
      var d; try{ d = JSON.parse(json); }catch(e){ return; }
      var idbTotal = Object.keys(counts(d)).reduce(function(a,k){ return a + counts(d)[k]; }, 0);
      if(idbTotal <= liveTotal) return;
      Object.keys(d).forEach(function(k){ W.DB[k] = d[k]; });
      try{ W._erpTxAlias && W._erpTxAlias(); }catch(e){}
      try{ localStorage.setItem(LS_KEY, json); }catch(e){}
      try{ (W.refreshAll || W.renderAll || function(){})(); }catch(e){}
      if(W.toast) W.toast('Recovered your data from the local backup copy (' + idbTotal + ' records).','s');
    });
  }

  /* flush on exit — covers closing the tab mid-edit */
  W.addEventListener('beforeunload', function(){ try{ flushPending(); }catch(e){} });
  W.addEventListener('pagehide', function(){ try{ flushPending(); }catch(e){} });
  W.addEventListener('visibilitychange', function(){ if(document.hidden){ try{ flushPending(); }catch(e){} } });

  if(document.readyState === 'complete') setTimeout(recoverIfEmpty, 1200);
  else W.addEventListener('load', function(){ setTimeout(recoverIfEmpty, 1200); });

  console.info('[ERP Fix 11] durable verified saves active — window.__erpSaveCheck() reports memory vs stored counts');
})();
</script>
<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-fix-v7-normalize">
/* v7: backfill field aliases on already-saved transactions so older records show
   up in the product / account based dashboard cards too. Runs once per load. */
(function(){
  "use strict";
  function run(){
    try{
      var D = window.DB; if(!D || !Array.isArray(D.tx)) return;
      var changed = false;
      D.tx.forEach(function(t){
        if(!t) return;
        if(!t.product && t.prod){ t.product = t.prod; changed = true; }
        if(!t.prod && t.product){ t.prod = t.product; changed = true; }
        if(!t.account && t.acc){ t.account = t.acc; changed = true; }
        if(!t.acc && t.account){ t.acc = t.account; changed = true; }
        if(t.amt == null && t.amount != null){ t.amt = t.amount; changed = true; }
        if(t.amount == null && t.amt != null){ t.amount = t.amt; changed = true; }
      });
      if(changed && typeof window.save === 'function'){ try{ window.save(); }catch(e){} }
    }catch(e){}
  }
  if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', function(){ setTimeout(run, 400); });
  else setTimeout(run, 400);
})();
</script>
<style id="erp-print-polish-v8">
@media print{
  /* Hide app chrome so any page prints as a clean report */
  .sidebar, #sidebar, .topbar, #topbar, .navbar, .bottom-nav, .fab,
  .no-print, .noprint, button:not(.print-keep), .toast, .toast-wrap,
  #erp-storage-banner, #erp-backup-reminder, #erp-safety-fab { display:none !important; }
  body{ background:#fff !important; }
  .page:not(.active){ display:none !important; }
  .card, .box, .panel{ box-shadow:none !important; break-inside:avoid; }
  table{ width:100% !important; border-collapse:collapse !important; }
  thead{ display:table-header-group; }
  tfoot{ display:table-footer-group; }
  tr, .row-item{ break-inside:avoid; page-break-inside:avoid; }
  h1,h2,h3,h4{ break-after:avoid; page-break-after:avoid; }
  a[href]:after{ content:"" !important; }
  @page{ size:A4; margin:12mm; }
}
