<script nonce="<?php echo $cspNonceAttr; ?>" id="erp-data-safety-v8">
/* ═══════════════════════════════════════════════════════════════════════
   V8 — DATA SAFETY: rolling restore points, backup reminder, safe restore
   • Automatic snapshots (every 10 min, on tab hide/close, before any restore
     or reset) kept in IndexedDB — last 12 retained, oldest dropped.
   • Any snapshot can be restored with one tap; the current state is snapped
     first, so a restore is always undoable.
   • Reminder bar when the last exported file is older than 7 days.
   ═══════════════════════════════════════════════════════════════════════ */
(function(){
  "use strict";
  var W=window, D=document, DB_NAME='ayan_safety', STORE='snaps', KEEP=12;
  var LAST_EXPORT='ayan_last_backup';

  function idb(){
    return new Promise(function(res){
      try{
        var rq=indexedDB.open(DB_NAME,1);
        rq.onupgradeneeded=function(){
          var db=rq.result;
          if(!db.objectStoreNames.contains(STORE)) db.createObjectStore(STORE,{keyPath:'id'});
        };
        rq.onsuccess=function(){ res(rq.result); };
        rq.onerror=function(){ res(null); };
      }catch(e){ res(null); }
    });
  }
  function tx(mode){
    return idb().then(function(db){ return db? db.transaction(STORE,mode).objectStore(STORE) : null; });
  }
  function counts(d){
    var keys=['tx','customers','suppliers','invoices','inventory','employees','banks','cheques'], n=0;
    keys.forEach(function(k){ if(Array.isArray(d&&d[k])) n+=d[k].length; });
    return n;
  }

  W.erpSnapshot=function(label){
    if(!W.DB) return Promise.resolve(false);
    var json;
    try{ json=JSON.stringify(W.DB); }catch(e){ return Promise.resolve(false); }
    var rec={ id:newId(), at:new Date().toISOString(), label:label||'auto', records:counts(W.DB), size:json.length, json:json };
    return tx('readwrite').then(function(st){
      if(!st) return false;
      try{ st.put(rec); }catch(e){ return false; }
      return W.erpListSnapshots().then(function(list){
        if(list.length<=KEEP) return true;
        return tx('readwrite').then(function(s2){
          list.slice(KEEP).forEach(function(r){ try{ s2.delete(r.id); }catch(e){} });
          return true;
        });
      });
    });
  };

  W.erpListSnapshots=function(){
    return tx('readonly').then(function(st){
      if(!st) return [];
      return new Promise(function(res){
        var rq=st.getAll();
        rq.onsuccess=function(){
          var l=(rq.result||[]).sort(function(a,b){ return b.id-a.id; });
          res(l);
        };
        rq.onerror=function(){ res([]); };
      });
    });
  };

  function applyData(d){
    Object.keys(d).forEach(function(k){ W.DB[k]=d[k]; });
    try{ W._erpTxAlias&&W._erpTxAlias(); }catch(e){}
    try{ (typeof saveDB==='function')&&saveDB(); }catch(e){}
    try{ (W.refreshAll||W.renderAll||W.render||function(){})(); }catch(e){}
  }

  W.erpRestoreSnapshot=async function(id){
    var list=await W.erpListSnapshots();
    var rec=list.filter(function(r){ return r.id===id; })[0];
    if(!rec){ (W.toast||alert)('Restore point not found'); return; }
    var msg='Restore data from '+new Date(rec.at).toLocaleString('en-BD')+' ('+rec.records+' records)?\n'
          + 'Your current data is snapshotted first, so this can be undone.';
    var ok = W.__confirm ? await W.__confirm(msg) : confirm(msg);
    if(!ok) return;
    await W.erpSnapshot('before-restore');
    var d; try{ d=JSON.parse(rec.json); }catch(e){ (W.toast||alert)('Restore point is unreadable'); return; }
    applyData(d);
    try{ W.logAudit&&W.logAudit('RESTORE','Data Safety','Restored snapshot '+rec.at); }catch(e){}
    (W.toast||alert)('Restored '+rec.records+' records from '+new Date(rec.at).toLocaleString('en-BD'), 's');
    W.erpCloseSafety&&W.erpCloseSafety();
  };

  W.erpDownloadSnapshot=async function(id){
    var list=await W.erpListSnapshots();
    var rec=list.filter(function(r){ return r.id===id; })[0];
    if(!rec) return;
    var a=D.createElement('a');
    a.href=URL.createObjectURL(new Blob([rec.json],{type:'application/json'}));
    a.download='AyanAgro_RestorePoint_'+rec.at.slice(0,19).replace(/[:T]/g,'-')+'.json';
    a.click();
  };

  /* export that also records the reminder timestamp */
  W.erpExportBackup=function(){
    if(!W.DB) return;
    var json;
    try{ json=JSON.stringify({version:'8.0',date:new Date().toISOString(),records:counts(W.DB),DB:W.DB},null,2); }
    catch(e){ (W.toast||alert)('Export failed: '+e.message); return; }
    var a=D.createElement('a');
    a.href=URL.createObjectURL(new Blob([json],{type:'application/json'}));
    a.download='AyanAgro_Backup_'+new Date().toISOString().slice(0,19).replace(/[:T]/g,'-')+'.json';
    a.click();
    try{ localStorage.setItem(LAST_EXPORT, Date.now().toString()); }catch(e){}
    try{ W.DB.lastBackup=new Date().toISOString().split('T')[0]; saveDB&&saveDB(); }catch(e){}
    hideReminder();
    (W.toast||alert)('Backup file downloaded ('+counts(W.DB)+' records)','s');
  };

  /* import with validation + pre-import snapshot */
  W.erpImportBackup=function(){
    var inp=D.createElement('input'); inp.type='file'; inp.accept='.json';
    inp.onchange=function(e){
      var f=e.target.files[0]; if(!f) return;
      var fr=new FileReader();
      fr.onload=async function(ev){
        var raw; try{ raw=__ayanSafeJSONParse(ev.target.result); }catch(err){ (W.toast||alert)('That file is not valid JSON','e'); return; }
        var d = raw && raw.DB ? raw.DB : raw;
        if(!d || typeof d!=='object' || (!Array.isArray(d.tx) && !Array.isArray(d.customers))){
          (W.toast||alert)('This does not look like an Ayan Agro backup file','e'); return;
        }
        var msg='Import backup?\n\nFile: '+(raw.date? new Date(raw.date).toLocaleString('en-BD'):f.name)
              + '\nRecords in file: '+counts(d)
              + '\nRecords now: '+counts(W.DB)
              + '\n\nCurrent data is snapshotted first, so you can undo this.';
        var ok = W.__confirm ? await W.__confirm(msg) : confirm(msg);
        if(!ok) return;
        await W.erpSnapshot('before-import');
        applyData(d);
        try{ W.logAudit&&W.logAudit('RESTORE','Data Safety','Imported backup file '+f.name); }catch(e){}
        (W.toast||alert)('Imported '+counts(d)+' records','s');
        W.erpCloseSafety&&W.erpCloseSafety();
      };
      fr.readAsText(f);
    };
    inp.click();
  };

  /* ── reminder bar ─────────────────────────────────────────────────── */
  function daysSinceExport(){
    var t=0; try{ t=parseInt(localStorage.getItem(LAST_EXPORT)||'0',10); }catch(e){}
    if(!t) return null;
    return Math.floor((Date.now()-t)/86400000);
  }
  function hideReminder(){ var el=D.getElementById('erp-backup-reminder'); if(el) el.remove(); }
  function showReminder(){
    if(D.getElementById('erp-backup-reminder')) return;
    if(!counts(W.DB)) return;
    var d=daysSinceExport();
    if(d!==null && d<7) return;
    var bar=D.createElement('div'); bar.id='erp-backup-reminder';
    bar.innerHTML='<span>💾 '+(d===null?'You have never downloaded a backup file.':'Last backup was '+d+' days ago.')
      +' Your data lives in this browser only.</span>'
      +'<button style="background:#fff;color:#92400e;" data-x-click="erpExportBackup()">Download backup</button>'
      +'<button style="background:rgba(255,255,255,.25);color:#fff;" data-x-click="this.parentNode.remove()">Later</button>';
    D.body.appendChild(bar);
  }
  /* FIX: this bar is full-width, position:fixed, bottom:0 — appearing and
     disappearing at moments none of the floating action buttons (the
     v2-launcher stack, ayanPayBtn, the AI FAB, etc.) know anything about,
     so on a narrow window (bar text wraps to two lines) or a short viewport
     it can briefly sit on top of the lowest one or two of them. Rather
     than hardcode a guess at the bar's height, measure it live and expose
     it as a CSS variable; the two lowest floating buttons (the only ones
     close enough to ever be reached) add it to their normal bottom offset
     via calc(), and it goes back to 0 automatically the moment the bar is
     removed — however it gets removed (Later, hideReminder(), logout). */
  (function(){
    function syncReminderOffset(){
      var bar=D.getElementById('erp-backup-reminder');
      var h=bar?Math.ceil(bar.getBoundingClientRect().height):0;
      D.documentElement.style.setProperty('--erp-reminder-h',h+'px');
    }
    syncReminderOffset();
    try{ new MutationObserver(syncReminderOffset).observe(D.body,{childList:true}); }catch(e){}
    W.addEventListener('resize',syncReminderOffset);
  })();

  /* ── restore-point panel ──────────────────────────────────────────── */
  W.erpCloseSafety=function(){ var el=D.querySelector('.erp-sf-bd'); if(el) el.remove(); };
  W.erpOpenSafety=async function(){
    W.erpCloseSafety();
    var list=await W.erpListSnapshots();
    var d=daysSinceExport();
    var bd=D.createElement('div'); bd.className='erp-sf-bd';
    bd.onclick=function(e){ if(e.target===bd) W.erpCloseSafety(); };
    bd.innerHTML='<div class="erp-sf"><h4>🛡️ Data Safety</h4><div class="erp-sf-body">'
      + '<div style="font-size:12.5px;color:#475569;">Records now: <b>'+counts(W.DB)+'</b><br/>'
      + 'Last downloaded backup: <b>'+(d===null?'never':(d===0?'today':d+' days ago'))+'</b></div>'
      + '<h5>Backup file</h5><div class="erp-sf-btns">'
      + '<button data-x-click="erpExportBackup()">⬇ Download backup</button>'
      + '<button class="alt" data-x-click="erpImportBackup()">⬆ Restore from file</button>'
      + '<button class="gray" data-x-click="erpSnapshot(\'manual\').then(function(){erpOpenSafety()})">＋ Restore point now</button>'
      + '</div>'
      + '<h5>Restore points ('+list.length+')</h5>'
      + (list.length? list.map(function(r){
          return '<div class="erp-sf-row"><span>'+new Date(r.at).toLocaleString('en-BD')
               + '<br/><span style="color:#64748b;font-size:11px;">'+r.records+' records · '+r.label+'</span></span>'
               + '<span style="display:flex;gap:6px;">'
               + '<button style="border:0;border-radius:6px;padding:6px 10px;font-weight:700;font-size:11.5px;cursor:pointer;background:#0f3d26;color:#fff;" data-x-click="erpRestoreSnapshot('+r.id+')">Restore</button>'
               + '<button style="border:0;border-radius:6px;padding:6px 10px;font-weight:700;font-size:11.5px;cursor:pointer;background:#e2e8f0;" data-x-click="erpDownloadSnapshot('+r.id+')">⬇</button>'
               + '</span></div>';
        }).join('')
        : '<div style="font-size:12.5px;color:#64748b;">No restore points yet — one is taken automatically every 10 minutes and whenever you leave the app.</div>')
      + '<div class="erp-sf-btns" style="margin-top:14px;"><button class="gray" data-x-click="erpCloseSafety()">Close</button></div>'
      + '</div></div>';
    D.body.appendChild(bd);
  };

  /* ── wire up ──────────────────────────────────────────────────────── */
  function boot(){
    if(!D.getElementById('erp-safety-fab')){
      var b=D.createElement('button');
      b.id='erp-safety-fab'; b.title='Data safety — backups & restore points';
      b.textContent='🛡️'; b.onclick=W.erpOpenSafety;
      D.body.appendChild(b);
    }
    /* keep the shield and reminder hidden while the login screen is up */
    function loggedIn(){
      var lg=D.getElementById('loginScreen')||D.getElementById('login-screen')||D.querySelector('.login-screen');
      if(lg && getComputedStyle(lg).display!=='none') return false;
      return true;
    }
    setInterval(function(){
      var fab=D.getElementById('erp-safety-fab'); if(!fab) return;
      var on=loggedIn();
      fab.style.display = on? 'block':'none';
      if(!on){ var rm=D.getElementById('erp-backup-reminder'); if(rm) rm.remove(); }
    }, 4000);
    W.erpSnapshot('startup');
    setInterval(function(){ W.erpSnapshot('auto'); }, 10*60*1000);
    D.addEventListener('visibilitychange', function(){ if(D.hidden) W.erpSnapshot('tab-hidden'); });
    W.addEventListener('beforeunload', function(){ try{ W.erpSnapshot('exit'); }catch(e){} });
    setTimeout(showReminder, 4000);

    /* snapshot before destructive flows and route legacy buttons here */
    ['resetPayments','resetAllData','factoryReset'].forEach(function(fn){
      if(typeof W[fn]==='function'){
        var o=W[fn];
        W[fn]=function(){ try{ W.erpSnapshot('before-'+fn); }catch(e){} return o.apply(this,arguments); };
      }
    });
    ['backupData','exportFullBackup','exportBackup','manualGDriveBackup'].forEach(function(fn){
      if(typeof W[fn]==='function'){
        var o=W[fn];
        W[fn]=function(){ try{ localStorage.setItem(LAST_EXPORT, Date.now().toString()); }catch(e){} hideReminder(); return o.apply(this,arguments); };
      }
    });
    ['restoreData','restoreJSON'].forEach(function(fn){
      if(typeof W[fn]==='function'){
        var o=W[fn];
        W[fn]=function(){ try{ W.erpSnapshot('before-'+fn); }catch(e){} return o.apply(this,arguments); };
      }
    });
  }
  if(D.readyState==='loading') D.addEventListener('DOMContentLoaded', function(){ setTimeout(boot,600); });
  else setTimeout(boot,600);
})();
</script>

<script nonce="<?php echo $cspNonceAttr; ?>" id="erp-report-print-v8">
/* ═══════════════════════════════════════════════════════════════════════
   V8 — REPORTS & PRINTING
   • Every remaining bare window.print() in a report context now routes
     through the letterhead engine, so reports carry the company header,
     document number, printed-by line and page footer.
   • Adds a keyboard shortcut (Ctrl/Cmd+P) that prints the OPEN page on the
     letterhead instead of the raw app screen.
   ═══════════════════════════════════════════════════════════════════════ */
(function(){
  "use strict";
  var W=window, D=document;

  function activePageId(){
    var el=D.querySelector('.page.active')||D.querySelector('.page[style*="display:block"]');
    return el? el.id : null;
  }
  function titleOf(id){
    var el=D.getElementById(id);
    var h=el&&el.querySelector('h1,h2,.page-title');
    var t=h? h.textContent.trim() : (id||'').replace(/^pg-/,'').replace(/[-_]/g,' ');
    return t.replace(/\s+/g,' ').slice(0,60) || 'Report';
  }

  /* letterhead print of whatever page is open */
  W.erpPrintOpenPage=function(){
    var id=activePageId();
    if(!id){ (W.toast||alert)('Open a page first, then print.','e'); return; }
    if(typeof W.printPageViaLetterhead==='function') W.printPageViaLetterhead(id, titleOf(id));
    else W.print();
  };

  function boot(){
    /* ledger printing was a bare window.print() — give it the letterhead */
    W.printLedger=function(page){
      var id = page && D.getElementById('pg-'+page) ? 'pg-'+page : activePageId();
      if(id && typeof W.printPageViaLetterhead==='function') W.printPageViaLetterhead(id, titleOf(id));
      else W.print();
      try{ W.logAudit&&W.logAudit('PRINT','Ledger','Printed '+(page||id)); }catch(e){}
    };

    /* generic page printer used by the toolbar */
    W.printCurrentPage=W.erpPrintOpenPage;

    /* Ctrl/Cmd+P → letterhead report instead of raw screen */
    D.addEventListener('keydown', function(e){
      if((e.ctrlKey||e.metaKey) && (e.key==='p'||e.key==='P')){
        if(D.getElementById('print-modal') && D.getElementById('print-modal').classList.contains('open')) return;
        e.preventDefault();
        W.erpPrintOpenPage();
      }
    });
  }
  if(D.readyState==='loading') D.addEventListener('DOMContentLoaded', function(){ setTimeout(boot,700); });
  else setTimeout(boot,700);
})();
</script>


<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-stock-sync">
/* FIX 10 — INVENTORY STOCK NEVER UPDATED FROM TRANSACTIONS.
   Root cause: saveTx()/_executeSaveTx()/delTx() only touched DB.tx and party
   balances. Product stock lived in a separate hand-typed field (p.stock/p.qty)
   that nothing ever recalculated, so a Warehouse Purchase of 40,000 KG still
   showed "0" in Inventory. This block makes stock a DERIVED value:
       stock = openingStock + purchases + returns-in + adjustments - sales
   and re-derives it before every save/render. */
(function(){
  "use strict";
  var IN_TYPES  = ['purchase','supplier purchase','warehouse purchase','werhouse purchase',
                   'opening stock','opening werhouse purchase','sales return',
                   'finished goods entry','manufacturing output','stock in'];
  var OUT_TYPES = ['sale','customer sale','warehouse sale','purchase return',
                   'raw material issue','manufacturing consumption','stock out'];

  function key(n){ return String(n==null?'':n).trim().toLowerCase(); }
  function num(v){ var n=parseFloat(v); return isNaN(n)?0:n; }
  // Quantity priority: qty -> net weight -> gross weight (KG based ERP)
  /* Same order as smartCalcAmount() and stockLedger(): you pay for the net
     weight, so that is what comes into stock. */
  function txQty(t){ return num(t.wt)||num(t.grosswt)||num(t.qty)||0; }

  function syncStock(){
    if(typeof DB!=='object'||!DB) return;
    var prods=DB.products||[];
    if(!prods.length) return;

    // one-time migration: whatever was typed manually becomes opening stock
    prods.forEach(function(p){
      if(p.openingStock==null) p.openingStock=num(p.stock!=null?p.stock:p.qty);
    });

    var map={};
    prods.forEach(function(p){ map[key(p.name)]={qty:num(p.openingStock),cost:0,costQty:0}; });

    (DB.tx||[]).forEach(function(t){
      var ty=key(t.type);
      // BUGFIX: a "Multiple Products" transaction (see the New Transaction
      // modal's 📦 checkbox) stores its real per-product lines in t.items,
      // while t.prod/t.qty only hold a blended display summary (e.g.
      // "Rice + Wheat" / a summed quantity). This function used to key off
      // that blended t.prod directly, which never matches a real product
      // name, so every multi-product purchase/sale was silently invisible
      // to this recompute — and because this recompute is authoritative
      // (it overwrites p.stock on nearly every render/save), it kept
      // erasing whatever a single-product-aware stock update had just
      // applied. Explode into the real per-item lines when present; a
      // normal single-product transaction still produces exactly one line,
      // identical to the old behaviour.
      var lines=(t.items&&t.items.length) ? t.items : [t];
      lines.forEach(function(line){
        /* Warehouse purchases add to the blended brand, not to the bran
           they were bought as — see stockLedger() above. */
        var pname=(typeof window.ayanStockProduct==='function')
          ? window.ayanStockProduct({type:t.type,prod:(line.prod||line.product)})
          : (line.prod||line.product);
        var k=key(pname); if(!k||!map[k]) return;
        var q=txQty(line);
        if(!q) return;
        if(IN_TYPES.indexOf(ty)>-1){
          map[k].qty+=q;
          /* FIX: a Sales Return's amount is what the CUSTOMER was refunded —
             the selling price, not the cost. Averaging it in pushed the cost
             of a ৳40/kg product up to ৳41.82 and overstated the stock value.
             Only what was actually bought sets the average cost. */
          if(/return/i.test(ty)){ map[k].__skipCost=true; }
          var amt=num(line.amount!=null?line.amount:line.amt);
          if(amt>0 && !map[k].__skipCost){ map[k].cost+=amt; map[k].costQty+=q; }
          map[k].__skipCost=false;
        } else if(OUT_TYPES.indexOf(ty)>-1){
          map[k].qty-=q;
        }
      });
    });

    /* Stock adjustments live under two different names depending on which
       screen wrote them — read both rather than silently ignoring half. */
    [].concat(DB.stockAdjustments||[], DB.stockAdj||[]).forEach(function(a){
      var k=key(a.product||a.prod); if(!k||!map[k]) return;
      var q=num(a.qty!=null?a.qty:a.adjQty);
      var t=String(a.adjType||a.type||'').toLowerCase();
      if(t==='add') map[k].qty+=q;
      else if(t==='remove') map[k].qty-=q;
      else if(t) map[k].qty=q;
      else map[k].qty+=q;              // signed quantity, no type given
    });

    /* FIX: stock here is derived as opening + purchases − sales and rebuilt
       on every save, so the quantity that Wastage/Damage knocked off by hand
       was put straight back — damaged goods stayed on the books for ever and
       were never costed as a loss. Wastage is now one of the movements. */
    (DB.wastage||[]).forEach(function(w){
      var k=key(w.prod||w.product); if(!k||!map[k]) return;
      map[k].qty-=Math.abs(num(w.qty));
    });

    prods.forEach(function(p){
      var m=map[key(p.name)]; if(!m) return;
      p.stock=Math.round(m.qty*1000)/1000;
      p.qty=p.stock;
      // average purchase cost, so Stock Value / Cost Value stop showing 0.00
      if(m.costQty>0) p.cost=Math.round(m.cost/m.costQty*100)/100;
      if(!num(p.rate)) p.rate=num(p.cost);
    });
  }
  window.syncStock=syncStock;

  function wrap(name,before){
    var orig=window[name];
    if(typeof orig!=='function'||orig.__stockWrapped) return;
    var fn=function(){ try{ before&&before.apply(null,arguments); }catch(e){ console.warn('syncStock',e); }
                       return orig.apply(this,arguments); };
    fn.__stockWrapped=true; window[name]=fn;
  }

  function install(){
    ['renderProd','renderProducts','renderDash','renderTx','renderStockAdj',
     'renderInventoryKPIs','saveDB','recalculateBalances'].forEach(function(n){ wrap(n,syncStock); });

    // manual edit of the Stock field = new opening stock, not final stock
    var origSaveProd=window.saveProd;
    if(typeof origSaveProd==='function'&&!origSaveProd.__stockWrapped){
      var sp=function(){
        var nameEl=document.getElementById('pr-name'), stkEl=document.getElementById('pr-stock');
        var nm=nameEl?nameEl.value.trim():'', op=stkEl?num(stkEl.value):0;
        var r=origSaveProd.apply(this,arguments);
        var p=(DB.products||[]).filter(function(x){return key(x.name)===key(nm);})[0];
        if(p){ p.openingStock=op; syncStock(); try{renderProd(DB.products);}catch(e){} }
        return r;
      };
      sp.__stockWrapped=true; window.saveProd=sp;
    }

    // after a transaction is saved / deleted, refresh inventory immediately
    ['_executeSaveTx','delTx'].forEach(function(n){
      var orig=window[n];
      if(typeof orig!=='function'||orig.__stockWrapped) return;
      var fn=function(){
        var r=orig.apply(this,arguments);
        Promise.resolve(r).then(function(){
          syncStock();
          try{ if(typeof saveDB==='function') saveDB(); }catch(e){}
          try{ renderProd(DB.products); }catch(e){}
          try{ if(typeof renderProducts==='function') renderProducts(); }catch(e){}
        });
        return r;
      };
      fn.__stockWrapped=true; window[n]=fn;
    });

    syncStock();
    try{ if(typeof renderProd==='function') renderProd(DB.products); }catch(e){}
  }

  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',function(){setTimeout(install,300);});
  else setTimeout(install,300);
})();
</script>

<script nonce="<?php echo $cspNonceAttr; ?>">
/* ══ NIMCHIP: first-run import of browser data into MySQL ══════════════
   Runs once per device after a successful server login. If the database is
   still empty and this browser holds records, they are pushed to the server.
   The local copy is left untouched as a safety net.                      */
(function(){
  'use strict';
  var W=window, TOKEN_KEY='rbo_token', LS_KEY='rbo_v4', FLAG='nimchip_migrated';
  function tok(){ try{ return sessionStorage.getItem(TOKEN_KEY)||''; }catch(e){ return ''; } }
  function say(m,t){ try{ if(typeof W.toast==='function') W.toast(m,t); }catch(e){} }
  function countRows(o){
    var n=0; if(!o||typeof o!=='object') return 0;
    Object.keys(o).forEach(function(k){ if(k!=='users'&&Array.isArray(o[k])) n+=o[k].length; });
    return n;
  }
  async function importOnce(){
    if(!W.ERP_SERVER_MODE) return;
    try{ if(localStorage.getItem(FLAG)) return; }catch(e){}
    /* api.php uses a PHP cookie session, not a bearer token. Requiring a
       token here meant the import never ran at all. */
    if(!W.currentUser) return;
    var head={ 'Accept':'application/json' };
    var server=null;
    try{
      var r=await fetch(API_FILE + '?action=load',{ credentials:'include', headers:head });
      if(!r.ok) return;
      var j=await r.json();
      if(!j || j.success === false) return;
      server=j.data||{};
    }catch(e){ return; }
    if(countRows(server)>0){ try{ localStorage.setItem(FLAG,'server-has-data'); }catch(e){} return; }

    var local=null;
    try{ local=JSON.parse(localStorage.getItem(LS_KEY)||'null'); }catch(e){}
    var rows=countRows(local);
    if(!local||!rows){ try{ localStorage.setItem(FLAG,'nothing-to-import'); }catch(e){} return; }

    say('Importing '+rows+' records from this browser into the database\u2026','i');
    try{
      /* api.php implements only load/save/whoami/ping/chat — 'migrate'
         returned 400 Unknown action. The whole-app blob save does the job. */
      var res=await fetch(API_FILE + '?action=save',{
        method:'POST',
        credentials:'include',
        headers:Object.assign({'Content-Type':'application/json'},head),
        body:JSON.stringify({ data: local })
      });
      var out=await res.json().catch(function(){ return {}; });
      if(res.ok && out.success !== false){
        try{ localStorage.setItem(FLAG, out.skipped?'server-has-data':'imported-'+Date.now()); }catch(e){}
        if(!out.skipped){
          say('Import complete \u2014 '+rows+' records are now stored in MySQL.','s');
          if(typeof W.loadDataFromServer==='function') await W.loadDataFromServer();
        }
      }else{
        say('Import failed: '+(out.message||res.status),'e');
      }
    }catch(e){ say('Import failed: '+e.message,'e'); }
  }

  function hook(){
    if(typeof W.loadDataFromServer!=='function'){ setTimeout(hook,300); return; }
    if(W._nimchipHooked) return; W._nimchipHooked=true;
    var orig=W.loadDataFromServer;
    W.loadDataFromServer=async function(){
      var ok=await orig.apply(this,arguments);
      if(ok && !W._nimchipImporting){ W._nimchipImporting=true; try{ await importOnce(); }finally{ W._nimchipImporting=false; } }
      return ok;
    };
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',hook);
  else hook();
})();
</script>

<!-- ══════════════════════════════════════════════════════════════
     MOBILE FIX LAYER (login + all modals) — appended last so it wins
     ══════════════════════════════════════════════════════════════ -->
<style id="ayan-mobile-login-modal-fix">
/* ── LOGIN: was position:fixed + overflow:hidden + vertically centered.
   On a phone the on-screen keyboard shrinks the visual viewport, so the card
   was centred inside the shrunken area and the Sign In button got clipped and
   became untappable. Now the overlay scrolls and aligns to the top. ── */
#login-screen{
  overflow-y:auto !important;
  -webkit-overflow-scrolling:touch;
  align-items:flex-start !important;
  padding:max(16px, env(safe-area-inset-top)) 12px calc(24px + env(safe-area-inset-bottom)) !important;
}
#login-screen .ls-card{ margin:auto !important;width:100% !important;max-width:400px !important; }
#login-screen .ls-shape{pointer-events:none;}
@media (max-width:640px){
  /* iOS auto-zooms any input under 16px, which shifted the form off-screen. */
  #login-screen .ls-field{font-size:16px !important;padding:13px 14px !important;}
  #login-screen .ls-btn{padding:15px !important;font-size:16px !important;min-height:50px;}
  #login-screen .ls-card > div:first-child{padding:20px 20px 16px !important;}
  #login-screen .ls-card > div:last-child{padding:18px 18px 22px !important;}
  #login-screen .ls-eye{width:40px;height:40px;display:flex;align-items:center;justify-content:center;right:2px;}
}
@supports (height:100dvh){ #login-screen{min-height:100dvh;} }

/* ── MODALS: z-index 500 sat *below* the mobile bottom nav / FABs (2000),
   so on a phone the nav bar and floating buttons covered the modal and its
   Save button. Also made them scroll-safe and keyboard-safe. ── */
.overlay,.modal-overlay{z-index:100000 !important;}
#mCardCrud{z-index:99999 !important;}
.overlay.open{
  align-items:flex-start !important;
  overflow-y:auto !important;-webkit-overflow-scrolling:touch;
  padding:max(12px, env(safe-area-inset-top)) 12px calc(20px + env(safe-area-inset-bottom)) !important;
}
.overlay.open > .modal,.overlay.open > .modal-box,.overlay.open > .modal-content{
  /* margin:auto inside a scrollable flex container pushes the top of a tall
     modal above the scroll origin, making its header unreachable. */
  margin:0 auto !important;
  max-height:calc(100dvh - 24px) !important;
  overflow-y:auto !important;
  position:relative !important;
}
/* Overlay was being offset below the topbar on phones, so its own scroll area
   was shorter than the screen; pin it to the full viewport. */
.overlay.open{top:0 !important;left:0 !important;right:0 !important;bottom:0 !important;
  width:100% !important;height:100% !important;}
@supports (height:100dvh){ .overlay.open{height:100dvh !important;} }

/* ── The second modal family: ~40 dialogs declared inline as
   `position:fixed;inset:0;align-items:center` with z-index 1000/2000. They had
   no scrolling at all, so on a phone anything taller than the screen (and the
   Save button with it) was unreachable, and the bottom nav / FAB sat on top. ── */
div[id$="-modal"]{
  z-index:100000 !important;
  overflow-y:auto !important;-webkit-overflow-scrolling:touch;
  align-items:flex-start !important;
  padding:max(12px, env(safe-area-inset-top)) 12px calc(20px + env(safe-area-inset-bottom)) !important;
}
div[id$="-modal"] > *{
  margin:0 auto !important;max-height:calc(100dvh - 24px) !important;overflow-y:auto !important;
  width:100% !important;
}
@media (max-width:640px){
  /* Dialog bodies were wider than the phone: fixed-width grids and inputs
     spilled past the right edge, hiding half of every field. */
  .overlay.open .modal,div[id$="-modal"] > *{padding-left:14px !important;padding-right:14px !important;}
  .overlay.open .modal *,div[id$="-modal"] *{max-width:100% !important;box-sizing:border-box !important;}
  .overlay.open .modal .form-grid,div[id$="-modal"] .form-grid,
  .overlay.open .modal .grid,div[id$="-modal"] .grid{grid-template-columns:1fr !important;}
  div[id$="-modal"] > *{max-width:100% !important;}
  /* A4 print preview keeps its page width; let it pan sideways instead of
     bleeding off the screen. */
  #print-modal{overflow-x:auto !important;}
  #print-modal > *{width:auto !important;max-width:none !important;}
  div[id$="-modal"] input,div[id$="-modal"] select,div[id$="-modal"] textarea{font-size:16px !important;min-height:44px;}
  div[id$="-modal"] button{min-height:44px;}
  div[id$="-modal"] table{display:block;overflow-x:auto;}
}
body.ayan-modal-open{overflow:hidden !important;}
body.ayan-modal-open #bottom-nav,
body.ayan-modal-open #fab,
body.ayan-modal-open .fab,
body.ayan-modal-open .fab-group{display:none !important;}
@media (max-width:640px){
  .overlay.open > .modal,.overlay.open .modal{padding:16px !important;border-radius:14px !important;}
  .modal-title{font-size:15px !important;}
  .modal-close{width:40px !important;height:40px !important;font-size:22px !important;flex:0 0 40px;}
  .modal input,.modal select,.modal textarea,
  .overlay input,.overlay select,.overlay textarea{font-size:16px !important;min-height:44px;}
  .modal button,.overlay button{min-height:44px;}
  .modal table{display:block;overflow-x:auto;-webkit-overflow-scrolling:touch;}
}
</style>
<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-mobile-login-modal-fix-js">
(function(){
  "use strict";
  var W=window,D=document;

  /* ── 1. LOGIN RACE ────────────────────────────────────────────────
     Backend detection (api.php?action=ping) resolves asynchronously and only
     then swaps doLogin() for the offline version. Tapping Sign In before that
     — normal on a phone, where the probe waits on a slow network — ran the
     server login against a login.php that isn't deployed and reported
     "Invalid username or password". Sign In now waits for detection. */
  var ready=false;
  function markReady(){ ready=true; var b=D.getElementById('ls-login-btn'); if(b) b.disabled=false; }
  var t0=Date.now();
  (function poll(){
    if(W.ERP_SERVER_MODE!==undefined || Date.now()-t0>4500){ markReady(); return; }
    setTimeout(poll,150);
  })();

  function realLogin(){
    var fn=W.doLogin;
    if(typeof fn==='function' && fn!==guardedLogin) return fn();
    return undefined;
  }
  function guardedLogin(){
    var btn=D.getElementById('ls-login-btn'), err=D.getElementById('login-error');
    if(!ready){
      if(btn){ btn.disabled=true; btn.innerHTML='<span class="ls-spinner"></span>Connecting…'; }
      if(err) err.style.display='none';
      var wait=setInterval(function(){
        if(!ready) return;
        clearInterval(wait);
        if(btn){ btn.disabled=false; btn.innerHTML='🔐 Sign In'; }
        realLogin();
      },120);
      return;
    }
    return realLogin();
  }

  function wireLogin(){
    var btn=D.getElementById('ls-login-btn');
    if(btn && !btn.dataset.ayanWired){
      btn.dataset.ayanWired='1';
      btn.removeAttribute('onclick');
      btn.type='button';
      btn.addEventListener('click',function(e){ e.preventDefault(); guardedLogin(); });
    }
    var pass=D.getElementById('login-pass'), user=D.getElementById('login-user');
    [user,pass].forEach(function(el){
      if(!el||el.dataset.ayanWired) return;
      el.dataset.ayanWired='1';
      el.addEventListener('keydown',function(e){
        if(e.key!=='Enter') return;
        e.preventDefault();
        if(el===user && pass){ pass.focus(); return; }
        guardedLogin();
      });
      /* Keyboard opening on a phone used to leave the focused field hidden
         behind it; scroll it into view once the keyboard has settled. */
      el.addEventListener('focus',function(){
        setTimeout(function(){ try{ el.scrollIntoView({block:'center',behavior:'smooth'}); }catch(_){} },320);
      });
    });
    if(pass) pass.setAttribute('autocomplete','current-password');
    if(user){ user.setAttribute('autocapitalize','none'); user.setAttribute('autocorrect','off'); }
  }

  /* ── 2. MODALS ────────────────────────────────────────────────────
     Every modal now: locks background scroll, closes on backdrop tap and
     Escape, hides the bottom nav / FABs while open, and opens scrolled to
     its own top. */
  var MODAL_SEL='.overlay, div[id$="-modal"]';
  function isOpen(o){ return o.classList.contains('open') || getComputedStyle(o).display==='flex'; }
  function syncBodyLock(){
    var open=[].slice.call(D.querySelectorAll(MODAL_SEL)).some(isOpen);
    D.body.classList.toggle('ayan-modal-open',open);
  }
  function topOverlay(){
    var list=[].slice.call(D.querySelectorAll(MODAL_SEL)).filter(isOpen);
    return list[list.length-1]||null;
  }
  function closeOverlay(o){
    if(!o) return;
    if(typeof W.closeModal==='function' && o.id){ try{ W.closeModal(o.id); }catch(_){} }
    o.classList.remove('open');
    if(getComputedStyle(o).display!=='none') o.style.display='none';
    syncBodyLock();
  }
  var mo=new MutationObserver(function(muts){
    syncBodyLock();
    muts.forEach(function(m){
      var o=m.target;
      if(!o.matches||!o.matches(MODAL_SEL)||!isOpen(o)) return;
      o.scrollTop=0;
      var box=o.querySelector('.modal,.modal-box,.modal-content')||o.firstElementChild;
      if(box) box.scrollTop=0;
    });
  });
  function wireModals(){
    [].slice.call(D.querySelectorAll(MODAL_SEL)).forEach(function(o){
      if(o.dataset.ayanBackdrop) return;
      o.dataset.ayanBackdrop='1';
      mo.observe(o,{attributes:true,attributeFilter:['class','style']});
      // BUGFIX (2026-08-24): same double-click-closes-the-modal-it-just-
      // opened issue as the other backdrop-click handler near openModal()
      // — this is a SECOND, independent listener doing the same job (see
      // that fix for the full explanation). Needs the identical 400ms
      // just-opened guard, keyed off the same data-openedAt stamp, or a
      // fast double-click / hard click still closes the modal via this
      // handler even with the other one fixed.
      o.addEventListener('click',function(e){
        if(e.target!==o) return;
        var openedAt=+(o.dataset.openedAt||0);
        if(openedAt && (Date.now()-openedAt)<400) return;
        closeOverlay(o);
      });
    });
    syncBodyLock();
  }

  function boot(){
    wireLogin();
    wireModals();
    W.ayanGuardedLogin=guardedLogin;
  }
  if(D.readyState==='loading') D.addEventListener('DOMContentLoaded',boot); else boot();
  D.addEventListener('keydown',function(e){
    if(e.key==='Escape'){ var o=topOverlay(); if(o) closeOverlay(o); }
  });
  // Overlays injected later (dynamic modals) get the same treatment.
  (function(){var _mq=null,_busy=false;new MutationObserver(function(){ if(_busy)return; clearTimeout(_mq); _mq=setTimeout(function(){_busy=true;try{wireModals();}finally{setTimeout(function(){_busy=false;},0);}},250); }).observe(D.documentElement,{childList:true,subtree:true});})();
  setTimeout(boot,1200);
})();
</script>

<style id="ayan-mobile-tables">
/* ============================================================================
   MOBILE TABLES & REPORTS
   Problem: on phones every table was set to `display:block;overflow-x:auto`.
   That drops the table layout box, so column widths stop lining up between
   thead and tbody, sticky headers cannot stick, and the row label scrolls out
   of sight - you slide sideways into a wall of numbers with no idea which row
   you are on. Fix: keep a real table and put the scrolling on a wrapper, then
   freeze the header row and the first (label) column, and pin totals.
   ========================================================================== */
.ayan-tscroll{
  overflow-x:auto;overflow-y:visible;-webkit-overflow-scrolling:touch;
  overscroll-behavior-x:contain;max-width:100%;
  scrollbar-width:thin;
}
.ayan-tscroll::-webkit-scrollbar{height:8px;}
.ayan-tscroll::-webkit-scrollbar-thumb{background:rgba(22,163,74,.35);border-radius:8px;}

@media (max-width:900px){
  /* Undo the display:block override so columns align again.
     border-collapse:collapse makes Chrome ignore position:sticky on cells, so
     the frozen first column silently did nothing until we switch to separate
     borders with zero spacing (visually identical, 1px hairlines via box-shadow). */
  .ayan-tscroll table{display:table !important;width:auto !important;min-width:100% !important;
    border-collapse:separate !important;border-spacing:0 !important;
    /* an inherited `overflow:hidden` on <table> made the table itself the
       nearest clipping ancestor, so sticky cells had nothing to stick to */
    overflow:visible !important;}

  /* Sticky header row */
  .ayan-tscroll table > thead > tr > th{
    position:sticky !important;top:0 !important;z-index:3 !important;
    background:#eafaf0 !important;backdrop-filter:none !important;
    color:#063e1c !important;white-space:nowrap !important;
    box-shadow:inset 0 -1px 0 rgba(6,62,28,.18) !important;
  }
  /* Frozen first column keeps the row label visible while panning */
  .ayan-tscroll table > tbody > tr > td:first-child,
  .ayan-tscroll table > tfoot > tr > td:first-child{
    position:sticky !important;left:0 !important;z-index:2 !important;
    background:#fff !important;
    box-shadow:1px 0 0 rgba(6,62,28,.12), 6px 0 8px -8px rgba(11,31,20,.35) !important;
    max-width:44vw;overflow:hidden;text-overflow:ellipsis;
  }
  .ayan-tscroll table > thead > tr > th:first-child{
    left:0 !important;z-index:4 !important;background:#eafaf0 !important;
    box-shadow:1px 0 0 rgba(6,62,28,.12), inset 0 -1px 0 rgba(6,62,28,.18) !important;
  }
  /* Totals row stays in view at the bottom of the panel */
  .ayan-tscroll table > tfoot > tr > td,
  .ayan-tscroll table > tfoot > tr > th,
  .ayan-tscroll table > tbody > tr.total-row > td,
  .ayan-tscroll table > tbody > tr.totals > td{
    position:sticky;bottom:0;z-index:2;
    background:#f4fbf6 !important;font-weight:700 !important;
    box-shadow:inset 0 1px 0 rgba(6,62,28,.18) !important;
  }
  /* Money columns read better right-aligned and unwrapped */
  .ayan-tscroll td.num,.ayan-tscroll td.amt,.ayan-tscroll td.right,
  .ayan-tscroll th.num,.ayan-tscroll th.amt,.ayan-tscroll th.right,
  .ayan-tscroll td[data-num],.ayan-tscroll td[align=right],.ayan-tscroll th[align=right]{
    text-align:right !important;white-space:nowrap !important;font-variant-numeric:tabular-nums;
  }
  .ayan-tscroll table td,.ayan-tscroll table th{font-size:12px !important;padding:8px 9px !important;}

  /* Edge fade + hint so it is obvious the panel pans sideways */
    /* Long tables scroll inside their own panel, which is what gives the sticky
     header something to stick to and keeps the page itself short. */
  .ayan-tscroll.ayan-tall{max-height:70dvh;overflow-y:auto;}
  .ayan-tscroll.ayan-can-scroll{position:relative;}
  .ayan-tscroll.ayan-can-scroll::after{
    content:"";position:absolute;top:0;right:0;width:22px;height:100%;
    pointer-events:none;background:linear-gradient(90deg,rgba(255,255,255,0),rgba(255,255,255,.92));
  }
  .ayan-tscroll.ayan-scrolled::after{opacity:0;transition:opacity .2s;}
  .ayan-thint{
    font-size:11px;font-weight:600;color:#0b6b3a;opacity:.75;
    margin:0 0 4px;display:flex;align-items:center;gap:4px;
  }
}
@media (min-width:901px){ .ayan-thint{display:none !important;} }
</style>
<script nonce="<?php echo $cspNonceAttr; ?>">
/* Wrap every table in a scroll panel so the sticky header/first column above
   have a scroll container to stick inside. Runs on load and again whenever a
   page re-renders its rows (most tables are built by innerHTML). */
(function(){
  var D=document;
  function skip(t){
    if(t.closest('.ayan-tscroll')) return true;
    if(t.closest('#print-area,#print-modal')) return true; /* printing keeps full width */
    if(t.getAttribute('data-ayan-nowrap')==='1') return true;
    /* PERF: an older .ayan-scrollx wrapper (still used by a couple of hardcoded
       report templates) already gives these tables horizontal scroll. Wrapping
       them again here just adds a redundant nested container and extra work on
       every scan — skip them instead of double-wrapping. */
    if(t.closest('.ayan-scrollx')) return true;
    return false;
  }
  function wrap(t){
    if(skip(t)) return;
    var w=D.createElement('div');
    w.className='ayan-tscroll';
    t.parentNode.insertBefore(w,t);
    w.appendChild(t);
    var hint=D.createElement('div');
    hint.className='ayan-thint';
    hint.textContent='\u2190 swipe to see more columns \u2192';
    hint.style.display='none';
    w.parentNode.insertBefore(hint,w);
    w.__hint=hint;
    w.addEventListener('scroll',function(){
      if(w.scrollLeft>4) w.classList.add('ayan-scrolled');
    },{passive:true});
    measure(w);
  }
  function measure(w){
    var rows=w.querySelectorAll('tbody tr').length;
    w.classList.toggle('ayan-tall',rows>12);
    var over=w.scrollWidth-w.clientWidth>8;
    w.classList.toggle('ayan-can-scroll',over);
    if(w.__hint) w.__hint.style.display=(over&&innerWidth<=900)?'flex':'none';
  }
  function scan(){
    var t=D.querySelectorAll('table');
    for(var i=0;i<t.length;i++) wrap(t[i]);
    var ws=D.querySelectorAll('.ayan-tscroll');
    for(var j=0;j<ws.length;j++) measure(ws[j]);
  }
  var q=null;
  function schedule(){ clearTimeout(q); q=setTimeout(scan,120); }
  if(D.readyState==='loading') D.addEventListener('DOMContentLoaded',scan); else scan();
  addEventListener('resize',schedule);
  new MutationObserver(function(muts){
    for(var i=0;i<muts.length;i++){
      var a=muts[i].addedNodes;
      for(var k=0;k<a.length;k++){
        var n=a[k];
        if(n.nodeType===1&&(n.tagName==='TABLE'||(n.querySelector&&n.querySelector('table')))){ schedule(); return; }
      }
    }
  }).observe(D.documentElement,{childList:true,subtree:true});
})();
</script>

<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-perf-savedb-coalesce">
/* CONSOLIDATED: this used to install a second Object.defineProperty lock on
   window.saveDB on top of erp-durable-save-v4's. Because ayan-fix-save-hang
   (further below) later did a plain `window.saveDB = ...` assignment, it hit
   THIS layer's setter instead of erp-durable-save-v4's — and this layer's own
   escape hatch pointed back into erp-durable-save-v4's wrapper, while
   fix-save-hang's internal fallback pointed back into THIS layer's getter.
   The two layers ended up calling each other in a perpetual microtask/idle-
   callback loop that never reached the actual write, so interactive saves
   were silently never persisted (data only survived via the separate
   beforeunload/pagehide/visibilitychange listeners registered directly by
   erp-durable-save-v4). erp-durable-save-v4's wrapper() already coalesces
   bursts within BURST_MS (400ms), so this layer was redundant as well as
   unsafe. Removed — erp-durable-save-v4 is now the single owner of
   window.saveDB / window.saveDBNow. See also ayan-fix-save-hang below. */
</script>
<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-fix-missing-pages">
/* FIX: the sidebar had "Wastage / Damage" and "Loan / LC Tracker" items and both
   render functions existed, but the #pg-wastage / #pg-loans containers were never
   in the markup - nav() bailed out with "That section isn't available yet" and two
   whole features were unreachable. Create the containers before first navigation. */
(function(){
  "use strict";
  function ensureFixPage(key){
    if(document.getElementById('pg-'+key)) return;
    var d=document.createElement('div');
    d.id='pg-'+key; d.className='page'; d.style.display='none';
    // Anchor next to a real page: the document contains more than one ".main"
    // and the first match is a hidden one, which left the new page 0x0.
    var ref=document.getElementById('pg-dashboard')||document.querySelector('.page');
    var host=(ref&&ref.parentElement)||document.querySelector('.content')||document.body;
    host.appendChild(d);
  }
  function bootFixPages(){ ensureFixPage('wastage'); ensureFixPage('loans'); }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',bootFixPages);
  else bootFixPages();
})();
</script>

<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-v2-enhancements">
/* ═══════════════════════════════════════════════════════════════════════════
   AYAN ERP — ENHANCEMENT PACK v2  (purely additive, zero regression)
   1. "Due" payment mode on every transaction form
   2. Transport type selector + Vehicle/Van ID
   3. Transport / freight rent DUE ledger (payable liability tracking)
   4. Permanent server + MySQL sync configuration UI
   All existing functions are wrapped, never replaced.
   ═══════════════════════════════════════════════════════════════════════════ */
(function () {
  'use strict';
  var W = window;

  /* ── helpers ───────────────────────────────────────────────────────── */
  function E(id) { return document.getElementById(id); }
  function num(v) { var n = parseFloat(v); return isNaN(n) ? 0 : n; }
  function say(m, t) { try { if (typeof W.toast === 'function') return W.toast(m, t || 'i'); } catch (e) {} try { console.log(m); } catch (e) {} }
  function money(n) { return '\u09F3' + num(n).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
  function esc(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
  function DBx() { if (!W.DB || typeof W.DB !== 'object') W.DB = {}; return W.DB; }
  function persist() { try { if (typeof W.saveDB === 'function') W.saveDB(); } catch (e) { console.warn('saveDB', e); } }

  /* ══════════════════════════════════════════════════════════════════════
     1. "DUE" PAYMENT MODE
     ══════════════════════════════════════════════════════════════════════ */
  var DUE_MODE = 'Due';

  W.isDueMode = function (tx) {
    return String((tx && tx.mode) || '').trim().toLowerCase() === 'due';
  };

  /* Transfer types move money between two own accounts — "Due" is meaningless
     there, so they are never neutralised. */
  var TRANSFER_TYPES = ['bank transfer', 'inter transfer', 'bkash transfer'];

  /* Expense-style types that normally just debit a bank/cash account. On Due
     they must instead build up a payable against the party. */
  var EXPENSE_DUE_TYPES = ['office rent', 'electricity bill', 'internet bill', 'telephone bill',
    'fuel expense', 'transport cost', 'loading charge', 'unloading charge',
    'commission payment', 'brokerage fee', 'legal fee', 'audit fee',
    'insurance premium', 'tax payment', 'government fee', 'license fee',
    'maintenance cost', 'repair expense', 'stationery purchase',
    'other expense', 'interest expense', 'tender payment', 'tender advance',
    'tender cost', 'staff salary', 'utility bill', 'office expense',
    'extra cost', 'unload cost', 'expense', 'expense payment',
    'salary payment', 'fixed asset purchase'];

  /* Inject a "Due" option into every payment-mode <select> in the document. */
  function upgradePaymentModeSelects(root) {
    var sels = (root || document).querySelectorAll('select');
    Array.prototype.forEach.call(sels, function (sel) {
      if (sel.dataset && sel.dataset.dueMode === '1') return;
      var texts = Array.prototype.map.call(sel.options, function (o) {
        return String(o.textContent || o.value || '').trim().toLowerCase();
      });
      var looksLikeMode = texts.indexOf('cash') >= 0 && (texts.indexOf('bank') >= 0 || texts.indexOf('bkash') >= 0 || texts.indexOf('cheque') >= 0);
      if (!looksLikeMode) return;
      if (sel.dataset) sel.dataset.dueMode = '1';
      if (texts.indexOf('due') < 0) {
        var opt = document.createElement('option');
        opt.value = DUE_MODE;
        opt.textContent = DUE_MODE + ' (Credit \u2014 no cash/bank movement)';
        sel.appendChild(opt);
      }
      sel.addEventListener('change', function () { reflectDueMode(sel); });
      reflectDueMode(sel);
    });
  }

  /* Visual + functional feedback when Due is picked on the main tx form. */
  function reflectDueMode(sel) {
    var on = String(sel.value || '').trim().toLowerCase() === 'due';
    sel.style.borderColor = on ? '#f59e0b' : '';
    sel.style.background = on ? '#fffbeb' : '';
    if (sel.id !== 'tx-mode') return;
    var acc = E('tx-acc');
    if (acc) {
      acc.disabled = on;
      acc.style.opacity = on ? '.5' : '';
      if (on) acc.value = '';
    }
    var paid = E('tx-paid'), recv = E('tx-recv');
    if (on) {
      if (paid) { paid.value = ''; paid.readOnly = true; paid.style.background = '#f3f4f6'; }
      if (recv) { recv.value = ''; recv.readOnly = true; recv.style.background = '#f3f4f6'; }
      try { if (typeof W.smartCalcDue === 'function') W.smartCalcDue(); } catch (e) {}
    } else {
      if (paid) { paid.readOnly = false; paid.style.background = ''; }
      if (recv) { recv.readOnly = false; recv.style.background = ''; }
    }
    var note = E('tx-due-mode-note');
    if (!note && sel.parentNode) {
      note = document.createElement('div');
      note.id = 'tx-due-mode-note';
      note.style.cssText = 'font-size:10.5px;font-weight:700;color:#b45309;margin-top:4px;display:none;';
      note.textContent = '\u26A0\uFE0F Credit transaction \u2014 nothing is deducted from cash/bank; the full amount goes to the party ledger.';
      sel.parentNode.appendChild(note);
    }
    if (note) note.style.display = on ? '' : 'none';
  }

  /* -- balance engine wrapper ------------------------------------------- */
  function adjPartyBal(name, delta) {
    if (!name || !delta) return;
    var c = (DBx().customers || []).filter(function (x) { return x.name === name; })[0];
    if (c) c.bal = num(c.bal) + delta;
  }

  function wrapBalanceEngine() {
    if (typeof W.applyTxBalance !== 'function' || W.applyTxBalance.__dueWrapped) return false;
    var orig = W.applyTxBalance;
    var wrapped = function (tx, dir) {
      if (!tx || !W.isDueMode(tx)) return orig.call(this, tx, dir);
      var type = String(tx.type || '').trim().toLowerCase();
      if (TRANSFER_TYPES.indexOf(type) >= 0) return orig.call(this, tx, dir);

      /* Neutralised clone: no bank/cash account, nothing paid or received.
         The original engine then books the FULL amount to the party ledger. */
      var clone = Object.assign({}, tx);
      clone.acc = ''; clone.account = ''; clone.acc2 = '';
      clone.paid = 0; clone.recv = 0;
      var out = orig.call(this, clone, dir);

      /* Expense-style types have no party leg in the base engine — add the
         payable manually so the liability is not lost. */
      if (EXPENSE_DUE_TYPES.indexOf(type) >= 0 && tx.party) {
        adjPartyBal(String(tx.party).trim(), -(num(tx.amount || tx.amt) * dir));
      }
      return out;
    };
    wrapped.__dueWrapped = true;
    W.applyTxBalance = wrapped;

    if (typeof W.validateBankBalance === 'function' && !W.validateBankBalance.__dueWrapped) {
      var vOrig = W.validateBankBalance;
      var vWrapped = function (tx) {
        if (tx && W.isDueMode(tx) && TRANSFER_TYPES.indexOf(String(tx.type || '').toLowerCase()) < 0) {
          return { valid: true };   // credit sale/purchase never touches a bank
        }
        return vOrig.call(this, tx);
      };
      vWrapped.__dueWrapped = true;
      W.validateBankBalance = vWrapped;
    }
    return true;
  }

  /* ══════════════════════════════════════════════════════════════════════
     2 + 3. TRANSPORT TYPE / VEHICLE ID  &  FREIGHT DUE LEDGER
     ══════════════════════════════════════════════════════════════════════ */
  function transportDues() {
    var d = DBx();
    if (!Array.isArray(d.transportDues)) d.transportDues = [];
    return d.transportDues;
  }

  function vehiclePlaceholder() {
    var sel = E('tx-transporttype'), inp = E('tx-truck'), lbl = E('tx-vehicle-lbl');
    if (!sel || !inp) return;
    var t = sel.value || '';
    var show = !!t;
    var wrap = inp.parentNode;
    if (wrap) wrap.style.display = show ? '' : 'none';
    if (lbl) lbl.textContent = (t || 'Vehicle') + ' ID';
    inp.placeholder = t ? (t + ' registration / ID (e.g. DHK-METRO-TA-11-1234)') : 'Vehicle registration / ID';
    ['tx-truckrent', 'tx-paid2', 'tx-due2', 'tx-acc2'].forEach(function (id) {
      var el = E(id); if (el && el.parentNode) el.parentNode.style.display = show ? '' : 'none';
    });
  }

  /* Due transport rent = rent - paid (auto, never negative). */
  function calcTransportDue() {
    var rent = num(E('tx-truckrent') && E('tx-truckrent').value);
    var paid = num(E('tx-paid2') && E('tx-paid2').value);
    var due = Math.max(0, +(rent - paid).toFixed(2));
    var el = E('tx-due2');
    if (el) {
      el.value = due ? due : '';
      el.readOnly = true;
      el.style.background = due > 0 ? '#fffbeb' : '#f9fafb';
      el.style.borderColor = due > 0 ? '#f59e0b' : '';
    }
    // Bank/account dropdown for transport rent stays enabled and visible
    // once a Transport Type is selected, regardless of whether "Paid
    // Transport Rent" has a value yet — it was previously disabled +
    // greyed out here, which made it look broken/missing.
    var acc2 = E('tx-acc2');
    if (acc2) { acc2.disabled = false; acc2.style.opacity = ''; }
    return due;
  }
  W.calcTransportDue = calcTransportDue;

  function bindTransportInputs() {
    var sel = E('tx-transporttype');
    if (sel && !sel.__bound) {
      sel.__bound = 1;
      sel.addEventListener('change', function () { vehiclePlaceholder(); calcTransportDue(); });
      vehiclePlaceholder();
    }
    ['tx-truckrent', 'tx-paid2'].forEach(function (id) {
      var el = E(id);
      if (el && !el.__bound) { el.__bound = 1; el.addEventListener('input', calcTransportDue); }
    });
  }

  /* Upsert the freight-due ledger row for a saved transaction. */
  function syncTransportDue(tx) {
    var list = transportDues();
    var i = -1;
    for (var k = 0; k < list.length; k++) { if (list[k].txId === tx.id) { i = k; break; } }
    var rent = num(tx.truckrent), paid = num(tx.paid2);
    var due = Math.max(0, +(rent - paid).toFixed(2));

    if (rent <= 0) { if (i >= 0) list.splice(i, 1); return; }

    var settled = i >= 0 ? num(list[i].settled) : 0;
    var outstanding = Math.max(0, +(due - settled).toFixed(2));
    var row = {
      id: i >= 0 ? list[i].id : ('TRD-' + Date.now() + '-' + Math.floor(Math.random() * 1000)),
      txId: tx.id,
      date: tx.date || '',
      inv: tx.inv || '',
      txType: tx.type || '',
      party: tx.party || '',
      transportType: tx.transportType || 'Truck',
      vehicle: tx.truck || tx.vehicleId || '',
      rent: rent,
      paid: paid,
      due: due,
      settled: settled,
      outstanding: outstanding,
      status: outstanding <= 0 ? 'Settled' : (paid > 0 || settled > 0 ? 'Partial' : 'Unpaid'),
      payments: i >= 0 ? (list[i].payments || []) : [],
      createdAt: i >= 0 ? list[i].createdAt : new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };
    if (i >= 0) list[i] = row; else list.push(row);
  }

  W.transportDueTotal = function () {
    return transportDues().reduce(function (s, r) { return s + num(r.outstanding); }, 0);
  };

  /* Settle (fully or partially) an outstanding freight due. */
  W.settleTransportDue = function (id, amount, accName) {
    var row = transportDues().filter(function (r) { return r.id === id; })[0];
    if (!row) { say('Freight due record not found', 'e'); return false; }
    var amt = num(amount);
    if (amt <= 0 || amt > num(row.outstanding) + 0.001) { say('Enter an amount between 0 and ' + money(row.outstanding), 'e'); return false; }
    if (accName) {
      var b = (DBx().banks || []).filter(function (x) { return x.name === accName; })[0];
      if (b) b.bal = num(b.bal) - amt;
    }
    row.settled = +(num(row.settled) + amt).toFixed(2);
    row.outstanding = Math.max(0, +(num(row.due) - row.settled).toFixed(2));
    row.status = row.outstanding <= 0 ? 'Settled' : 'Partial';
    row.updatedAt = new Date().toISOString();
    (row.payments = row.payments || []).push({ date: new Date().toISOString().slice(0, 10), amount: amt, account: accName || 'Cash' });
    persist();
    try { if (typeof W.logAudit === 'function') W.logAudit('UPDATE', 'Transport Due', 'Settled ' + money(amt) + ' for ' + (row.vehicle || row.transportType)); } catch (e) {}
    say('Freight payment of ' + money(amt) + ' recorded', 's');
    renderTransportDueLedger();
    return true;
  };

  W.promptSettleTransportDue = function (id) {
    var row = transportDues().filter(function (r) { return r.id === id; })[0];
    if (!row) return;
    var amt = prompt('Freight payment amount (outstanding ' + money(row.outstanding) + '):', row.outstanding);
    if (amt === null) return;
    var accs = (DBx().banks || []).map(function (b) { return b.name; });
    var acc = accs.length ? prompt('Pay from account (' + accs.join(' / ') + ')\nLeave blank for cash-in-hand:', accs[0] || '') : '';
    W.settleTransportDue(id, amt, acc || '');
  };

  /* ── Delete a freight due row ── */
  W.deleteTransportDue = function (id) {
    var list = transportDues();
    var i = list.findIndex(function (r) { return r.id === id; });
    if (i < 0) { say('Record not found', 'e'); return; }
    var row = list[i];
    list.splice(i, 1);
    persist();
    try { if (typeof W.logAudit === 'function') W.logAudit('DELETE', 'Transport Due', 'Removed freight due ' + money(row.rent) + ' — ' + (row.vehicle || row.transportType || '')); } catch (e) {}
    say('Freight due record removed', 's');
    renderTransportDueLedger();
  };

  W.promptDeleteTransportDue = async function (id) {
    var row = transportDues().filter(function (r) { return r.id === id; })[0];
    if (!row) return;
    var msg = 'Delete this freight due record (' + money(row.rent) + ' for ' + (row.vehicle || row.transportType || 'this vehicle') + ')? This cannot be undone.';
    var ok;
    try { ok = W.__confirm ? await W.__confirm(msg) : confirm(msg); } catch (e) { ok = confirm(msg); }
    if (!ok) return;
    W.deleteTransportDue(id);
  };

  /* ── Edit a freight due row (adjust rent amount and vehicle/type) ── */
  W.editTransportDue = function (id) {
    var row = transportDues().filter(function (r) { return r.id === id; })[0];
    if (!row) return;
    var newVehicle = prompt('Vehicle / Truck ID:', row.vehicle || '');
    if (newVehicle === null) return;
    var newType = prompt('Transport type (e.g. Truck, Covered Van):', row.transportType || 'Truck');
    if (newType === null) return;
    var newRent = prompt('Total freight rent (৳):', row.rent);
    if (newRent === null) return;
    newRent = parseFloat(newRent) || 0;
    if (newRent <= 0) { say('Rent must be greater than 0', 'e'); return; }
    var prevSettled = num(row.settled) + num(row.paid);
    row.vehicle = newVehicle.trim() || row.vehicle;
    row.transportType = newType.trim() || row.transportType;
    row.rent = newRent;
    row.due = newRent;
    row.outstanding = Math.max(0, +(newRent - prevSettled).toFixed(2));
    row.status = row.outstanding <= 0 ? 'Settled' : (prevSettled > 0 ? 'Partial' : 'Pending');
    row.updatedAt = new Date().toISOString();
    persist();
    try { if (typeof W.logAudit === 'function') W.logAudit('UPDATE', 'Transport Due', 'Edited freight due — ' + (row.vehicle || row.transportType) + ', rent ' + money(newRent)); } catch (e) {}
    say('Freight due updated', 's');
    renderTransportDueLedger();
  };

  /* ── Freight due ledger UI ── */
  function renderTransportDueLedger() {
    var body = E('trd-body');
    if (!body) return;
    var rows = transportDues().slice().sort(function (a, b) { return String(b.date || '').localeCompare(String(a.date || '')); });
    var filter = (E('trd-filter') && E('trd-filter').value) || 'open';
    if (filter === 'open') rows = rows.filter(function (r) { return num(r.outstanding) > 0; });
    else if (filter === 'settled') rows = rows.filter(function (r) { return num(r.outstanding) <= 0; });

    var totRent = rows.reduce(function (s, r) { return s + num(r.rent); }, 0);
    var totOut = rows.reduce(function (s, r) { return s + num(r.outstanding); }, 0);

    E('trd-kpi').innerHTML =
      '<div style="flex:1;background:#f0fdf4;border:1.5px solid #bbf7d0;border-radius:10px;padding:12px;">' +
      '<div style="font-size:10px;font-weight:800;color:#166534;text-transform:uppercase;">Total Freight</div>' +
      '<div style="font-size:18px;font-weight:900;color:#0f3d26;">' + money(totRent) + '</div></div>' +
      '<div style="flex:1;background:#fffbeb;border:1.5px solid #fde68a;border-radius:10px;padding:12px;">' +
      '<div style="font-size:10px;font-weight:800;color:#b45309;text-transform:uppercase;">Outstanding Payable</div>' +
      '<div style="font-size:18px;font-weight:900;color:#b45309;">' + money(totOut) + '</div></div>' +
      '<div style="flex:1;background:#eff6ff;border:1.5px solid #bfdbfe;border-radius:10px;padding:12px;">' +
      '<div style="font-size:10px;font-weight:800;color:#1d4ed8;text-transform:uppercase;">Records</div>' +
      '<div style="font-size:18px;font-weight:900;color:#1d4ed8;">' + rows.length + '</div></div>';

    var totPaid = rows.reduce(function (s, r) { return s + num(r.paid) + num(r.settled); }, 0);

    if (!rows.length) {
      body.innerHTML = '<tr><td colspan="11" style="padding:26px;text-align:center;color:#9ca3af;font-size:12px;">No freight/transport dues recorded.</td></tr>';
      return;
    }
    body.innerHTML = rows.map(function (r, i) {
      var color = r.status === 'Settled' ? '#16a34a' : r.status === 'Partial' ? '#d97706' : '#dc2626';
      return '<tr style="border-bottom:1px solid #f1f5f9;">' +
        '<td style="padding:7px 9px;color:#94a3b8;">' + (i + 1) + '</td>' +
        '<td style="padding:7px 9px;">' + esc(r.date) + '</td>' +
        '<td style="padding:7px 9px;font-weight:700;">' + esc(r.transportType) + '</td>' +
        '<td style="padding:7px 9px;">' + esc(r.vehicle || '\u2014') + '</td>' +
        '<td style="padding:7px 9px;">' + esc(r.party || '\u2014') + '</td>' +
        '<td style="padding:7px 9px;font-size:10.5px;color:#64748b;">' + esc(r.txType) + (r.inv ? ' \u2022 ' + esc(r.inv) : '') + '</td>' +
        '<td style="padding:7px 9px;text-align:right;">' + money(r.rent) + '</td>' +
        '<td style="padding:7px 9px;text-align:right;color:#16a34a;">' + money(num(r.paid) + num(r.settled)) + '</td>' +
        '<td style="padding:7px 9px;text-align:right;font-weight:800;color:' + color + ';">' + money(r.outstanding) + '</td>' +
        '<td style="padding:7px 9px;white-space:nowrap;">' +
        '<span style="background:' + color + ';color:#fff;border-radius:4px;padding:2px 7px;font-size:10px;font-weight:800;">' + esc(r.status) + '</span>' +
        (num(r.outstanding) > 0 ? ' <button data-x-click="promptSettleTransportDue(\'' + r.id + '\')" style="background:#16a34a;color:#fff;border:0;border-radius:5px;padding:3px 9px;font-size:10px;font-weight:800;cursor:pointer;">Pay</button>' : '') +
        '</td>' +
        '<td style="padding:7px 9px;white-space:nowrap;">' +
        '<button data-x-click="editTransportDue(\'' + r.id + '\')" title="Edit" style="background:#eff6ff;color:#1d4ed8;border:1px solid #bfdbfe;border-radius:5px;padding:3px 8px;font-size:10px;font-weight:800;cursor:pointer;">✏️</button>' +
        ' <button data-x-click="promptDeleteTransportDue(\'' + r.id + '\')" title="Delete" style="background:#fee2e2;color:#dc2626;border:1px solid #fecaca;border-radius:5px;padding:3px 8px;font-size:10px;font-weight:800;cursor:pointer;">🗑️</button>' +
        '</td></tr>';
    }).join('') +
    '<tr style="background:#f0fdf4;font-weight:900;border-top:2px solid #bbf7d0;">' +
    '<td colspan="6" style="padding:9px;font-size:12px;color:#0f3d26;">TOTAL (' + rows.length + ' records)</td>' +
    '<td style="padding:9px;text-align:right;color:#0f3d26;">' + money(totRent) + '</td>' +
    '<td style="padding:9px;text-align:right;color:#16a34a;">' + money(totPaid) + '</td>' +
    '<td style="padding:9px;text-align:right;color:#b45309;">' + money(totOut) + '</td>' +
    '<td colspan="2"></td></tr>';
  }
  W.renderTransportDueLedger = renderTransportDueLedger;

  W.openTransportDueLedger = function () {
    var m = E('trd-modal');
    if (!m) {
      m = document.createElement('div');
      m.id = 'trd-modal';
      m.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:9500;display:flex;align-items:center;justify-content:center;padding:16px;';
      m.innerHTML =
        '<div style="background:#fff;border-radius:14px;width:100%;max-width:1080px;max-height:88vh;overflow:auto;box-shadow:0 20px 50px rgba(0,0,0,.35);">' +
        '<div style="display:flex;align-items:center;justify-content:space-between;padding:16px 20px;border-bottom:2px solid #16a34a;position:sticky;top:0;background:#fff;">' +
        '<div style="font-size:16px;font-weight:900;color:#0f3d26;">\uD83D\uDE9B Transport / Freight Due Ledger</div>' +
        '<div style="display:flex;gap:8px;align-items:center;">' +
        '<select id="trd-filter" data-x-change="renderTransportDueLedger()" style="padding:6px 10px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;">' +
        '<option value="open">Outstanding only</option><option value="all">All records</option><option value="settled">Settled</option></select>' +
        '<button data-x-click="document.getElementById(\'trd-modal\').style.display=\'none\'" style="background:#e5e7eb;border:0;border-radius:6px;padding:6px 12px;font-weight:800;cursor:pointer;">\u2715</button>' +
        '</div></div>' +
        '<div id="trd-kpi" style="display:flex;gap:10px;padding:14px 20px;"></div>' +
        '<div style="padding:0 20px 20px;overflow-x:auto;">' +
        '<table style="width:100%;border-collapse:collapse;font-size:11.5px;min-width:900px;">' +
        '<thead><tr style="background:#f0fdf4;color:#0f3d26;text-align:left;">' +
        '<th style="padding:9px;">#</th><th style="padding:9px;">Date</th><th style="padding:9px;">Transport</th>' +
        '<th style="padding:9px;">Vehicle ID</th><th style="padding:9px;">Party</th><th style="padding:9px;">Reference</th>' +
        '<th style="padding:9px;text-align:right;">Rent</th><th style="padding:9px;text-align:right;">Paid</th>' +
        '<th style="padding:9px;text-align:right;">Outstanding</th><th style="padding:9px;">Status</th>' +
        '</tr></thead><tbody id="trd-body"></tbody></table></div></div>';
      document.body.appendChild(m);
    }
    m.style.display = 'flex';
    renderTransportDueLedger();
  };

  /* Backfill: any legacy transaction that already carried truck rent. */
  function backfillTransportDues() {
    var list = transportDues();
    if (list.__backfilled) return;
    var known = {};
    list.forEach(function (r) { known[r.txId] = 1; });
    (DBx().tx || []).forEach(function (t) {
      if (num(t.truckrent) > 0 && !known[t.id]) syncTransportDue(t);
    });
    try { Object.defineProperty(list, '__backfilled', { value: 1, enumerable: false }); } catch (e) {}
  }

  /* -- save-pipeline wrapper -------------------------------------------- */
  function wrapSavePipeline() {
    if (typeof W._executeSaveTx !== 'function' || W._executeSaveTx.__v2Wrapped) return false;
    var orig = W._executeSaveTx;
    var wrapped = function (tx, editId) {
      try {
        var sel = E('tx-transporttype');
        if (sel && document.getElementById('mTx')) {
          if (sel.value) tx.transportType = sel.value;
          else if (tx.truck) tx.transportType = tx.transportType || 'Truck';
        }
        if (tx.truck) {
          tx.transportType = tx.transportType || 'Truck';
          tx.vehicleId = tx.truck;
        }
        if (num(tx.truckrent) > 0) {
          tx.due2 = Math.max(0, +(num(tx.truckrent) - num(tx.paid2)).toFixed(2)) || null;
          tx.transportDue = num(tx.due2);
        }
        if (W.isDueMode(tx)) { tx.isCredit = true; tx.paid = null; tx.recv = null; tx.acc = ''; tx.account = ''; }
      } catch (e) { console.warn('v2 enrich', e); }

      var out = orig.call(this, tx, editId);
      try { syncTransportDue(tx); persist(); renderTransportDueLedger(); } catch (e) { console.warn('v2 freight', e); }
      return out;
    };
    wrapped.__v2Wrapped = true;
    W._executeSaveTx = wrapped;

    if (typeof W.delTx === 'function' && !W.delTx.__v2Wrapped) {
      var dOrig = W.delTx;
      var dWrapped = async function (id) {
        var r = await dOrig.call(this, id);
        try {
          var l = transportDues();
          for (var i = l.length - 1; i >= 0; i--) if (l[i].txId === id) l.splice(i, 1);
          persist(); renderTransportDueLedger();
        } catch (e) {}
        return r;
      };
      dWrapped.__v2Wrapped = true;
      W.delTx = dWrapped;
    }
    return true;
  }

  /* ══════════════════════════════════════════════════════════════════════
     4. PERMANENT SERVER / MySQL SYNC SETTINGS
     ══════════════════════════════════════════════════════════════════════ */
  W.testErpServer = function () {
    var url = (E('sync-url') && E('sync-url').value || '').trim() || 'api.php';
    var out = E('sync-result');
    if (out) { out.style.color = '#6b7280'; out.textContent = 'Contacting ' + url + ' \u2026'; }
    var ping = url + (url.indexOf('?') >= 0 ? '&' : '?') + 'action=ping';
    return fetch(ping, { method: 'GET', headers: { Accept: 'application/json' } })
      .then(function (r) { return r.json().catch(function () { return null; }); })
      .then(function (j) {
        var ok = !!(j && (j.success || j.ok || j.pong));
        if (out) {
          out.style.color = ok ? '#16a34a' : '#dc2626';
          out.textContent = ok
            ? '\u2705 Connected \u2014 MySQL backend reachable. Data will sync for every browser and user.'
            : '\u274C No valid JSON response. Check that api.php, db.php and config.php are uploaded to this path in cPanel.';
        }
        return ok;
      })
      .catch(function (e) {
        if (out) { out.style.color = '#dc2626'; out.textContent = '\u274C ' + e.message + ' \u2014 endpoint unreachable (check path / HTTPS / CORS).'; }
        return false;
      });
  };

  W.saveErpServerSettings = function () {
    var url = (E('sync-url') && E('sync-url').value || '').trim() || 'api.php';
    W.setErpApiUrl(url);
    say('Server sync settings saved \u2014 reloading to apply\u2026', 's');
    setTimeout(function () { location.reload(); }, 900);
  };

  W.openServerSyncSettings = function () {
    var m = E('sync-modal');
    if (!m) {
      m = document.createElement('div');
      m.id = 'sync-modal';
      m.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:9600;display:flex;align-items:center;justify-content:center;padding:16px;';
      m.innerHTML =
        '<div style="background:#fff;border-radius:14px;width:100%;max-width:560px;box-shadow:0 20px 50px rgba(0,0,0,.35);">' +
        '<div style="display:flex;align-items:center;justify-content:space-between;padding:16px 20px;border-bottom:2px solid #1d4ed8;">' +
        '<div style="font-size:16px;font-weight:900;color:#1e3a8a;">\uD83D\uDDA5\uFE0F Server &amp; Database Sync</div>' +
        '<button data-x-click="document.getElementById(\'sync-modal\').style.display=\'none\'" style="background:#e5e7eb;border:0;border-radius:6px;padding:6px 12px;font-weight:800;cursor:pointer;">\u2715</button></div>' +
        '<div style="padding:18px 20px;font-size:12.5px;color:#374151;">' +
        '<p style="margin:0 0 12px;">Point the ERP at the <strong>api.php</strong> you uploaded in cPanel. Every browser and user then reads and writes the same MySQL database. This app is server-only \u2014 there is no offline / local-only mode.</p>' +
        '<label style="font-size:11px;font-weight:800;color:#374151;">API endpoint URL</label>' +
        '<input id="sync-url" style="width:100%;padding:9px;border:1px solid #d1d5db;border-radius:7px;font-size:12.5px;margin:5px 0 12px;box-sizing:border-box;" placeholder="api.php or https://yourdomain.com/erp/api.php">' +
        '<div style="font-size:10.5px;color:#6b7280;margin-bottom:12px;">Same folder \u2192 <code>api.php</code> \u2002\u2022\u2002 Subfolder \u2192 <code>/erp/api.php</code> \u2002\u2022\u2002 Other domain \u2192 full https URL (needs CORS).</div>' +
        '<div style="display:flex;gap:8px;">' +
        '<button data-x-click="testErpServer()" style="flex:1;background:#1d4ed8;color:#fff;border:0;border-radius:8px;padding:10px;font-weight:800;cursor:pointer;">\uD83D\uDD0C Test connection</button>' +
        '<button data-x-click="saveErpServerSettings()" style="flex:1;background:#16a34a;color:#fff;border:0;border-radius:8px;padding:10px;font-weight:800;cursor:pointer;">\uD83D\uDCBE Save &amp; reload</button></div>' +
        '<div id="sync-result" style="margin-top:12px;font-size:11.5px;min-height:18px;"></div>' +
        '<div id="sync-state" style="margin-top:10px;font-size:11px;color:#6b7280;"></div>' +
        '</div></div>';
      document.body.appendChild(m);
    }
    m.style.display = 'flex';
    E('sync-url').value = (W.ERP_CONFIG && W.ERP_CONFIG.API_URL) || 'api.php';
    E('sync-state').textContent = 'Current mode: ' + (W.ERP_SERVER_MODE ? 'ONLINE \u2014 syncing with MySQL' : 'Connecting\u2026');
  };

  /* ── Floating launcher (freight ledger + sync settings) ─────────────── */
  function mountLauncher() {
    if (E('v2-launcher')) return;
    var d = document.createElement('div');
    d.id = 'v2-launcher';
    d.className = 'ayan-noprint';
    d.style.cssText = 'position:fixed;right:16px;bottom:16px;z-index:9000;display:flex;flex-direction:column;gap:8px;';
    d.innerHTML =
      '<button id="v2-trd-btn" data-x-click="openTransportDueLedger()" title="Transport / Freight Due Ledger" ' +
      'style="background:#0f3d26;color:#fff;border:0;border-radius:22px;padding:9px 15px;font-size:12px;font-weight:800;cursor:pointer;box-shadow:0 6px 18px rgba(0,0,0,.25);">' +
      '\uD83D\uDE9B Freight Due <span id="v2-trd-badge" style="background:#f59e0b;border-radius:10px;padding:1px 7px;margin-left:5px;">0</span></button>' +
      '<button data-x-click="openServerSyncSettings()" title="Server &amp; Database Sync" ' +
      'style="background:#1d4ed8;color:#fff;border:0;border-radius:22px;padding:9px 15px;font-size:12px;font-weight:800;cursor:pointer;box-shadow:0 6px 18px rgba(0,0,0,.25);">' +
      '\uD83D\uDDA5\uFE0F Sync <span id="v2-sync-dot" style="display:inline-block;width:8px;height:8px;border-radius:50%;background:#9ca3af;margin-left:5px;"></span></button>';
    document.body.appendChild(d);
  }

  function refreshLauncher() {
    var badge = E('v2-trd-badge');
    if (badge) {
      var t = W.transportDueTotal();
      badge.textContent = t > 0 ? money(t).replace('\u09F3', '') : '0';
      badge.style.background = t > 0 ? '#dc2626' : '#16a34a';
    }
    var dot = E('v2-sync-dot');
    if (dot) dot.style.background = W.ERP_SERVER_MODE ? '#22c55e' : '#f59e0b';
  }

  /* ── boot ───────────────────────────────────────────────────────────── */
  function tick() {
    try { upgradePaymentModeSelects(document); } catch (e) {}
    try { wrapBalanceEngine(); } catch (e) {}
    try { wrapSavePipeline(); } catch (e) {}
    try { bindTransportInputs(); } catch (e) {}
    try { refreshLauncher(); } catch (e) {}
  }

  function boot() {
    mountLauncher();
    try { backfillTransportDues(); } catch (e) {}
    tick();
    setInterval(tick, 6000);          // safety net only; the observer below covers dynamic forms/modals
    try {
      (function(){var _tq=null,_tb=false;new MutationObserver(function () { if(_tb)return; clearTimeout(_tq); _tq=setTimeout(function(){_tb=true;try{tick();}finally{setTimeout(function(){_tb=false;},0);}},300); })
        .observe(document.body, { childList: true, subtree: true });})();
    } catch (e) {}
    console.log('%cAYAN ERP v2 enhancements ready', 'color:#16a34a;font-weight:700',
      '\u2014 Due mode, transport tracking, freight-due ledger, server sync');
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();
})();

</script>
<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-sale-cost-dues">
/* ═══════════════════════════════════════════════════════════════════════════
   SALE COST DUES — Agent / QC / Unload / Other cost payable ledger
   (2026-08-20, requested: "I have to pay [QC] at the end of the month")

   Agent commission, QC and Unload costs on a Sale are recorded for the
   profit calculation the moment the sale is saved, but nothing about saving
   a sale ever pays the agent/QC person/unloader — that happens separately,
   often much later (end of month, per the request this was built for). Until
   now there was nowhere to see what's still owed to them or mark it paid.
   This mirrors the existing Transport/Freight Due ledger exactly: one row
   per transaction that carries any of these costs, kept in sync automatically
   whenever that transaction is saved or deleted, with its own "Pay" action
   that can optionally deduct the payment from a real bank account (or just
   record it as cash paid out, if left blank). Purely additive — wraps
   _executeSaveTx/delTx the same layered way the freight ledger already does,
   without touching either function directly. ═══════════════════════════════════════════════════════════════════════════ */
(function () {
  'use strict';
  var W = window;
  function E(id) { return document.getElementById(id); }
  function num(v) { var n = parseFloat(v); return isNaN(n) ? 0 : n; }
  function say(m, t) { try { if (typeof W.toast === 'function') return W.toast(m, t || 'i'); } catch (e) {} }
  function money(n) { return '৳' + num(n).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
  function esc(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
  function DBx() { if (!W.DB || typeof W.DB !== 'object') W.DB = {}; return W.DB; }
  function persist() { try { if (typeof W.saveDB === 'function') W.saveDB(); } catch (e) {} }

  function saleCostDues() {
    var d = DBx();
    if (!Array.isArray(d.saleCostDues)) d.saleCostDues = [];
    return d.saleCostDues;
  }

  function costTotal(tx) {
    return num(tx.agentAcost) + num(tx.agentBcost) + num(tx.qc) + num(tx.unload) + num(tx.othercost) + num(tx.othercost2);
  }

  /* Upsert the cost-due ledger row for a saved Sale transaction. */
  function syncSaleCostDue(tx) {
    if (!tx || !(typeof W.isSaleType === 'function' && W.isSaleType(tx.type))) return;
    var list = saleCostDues();
    var i = -1;
    for (var k = 0; k < list.length; k++) { if (list[k].txId === tx.id) { i = k; break; } }
    var total = +costTotal(tx).toFixed(2);
    if (total <= 0) { if (i >= 0) list.splice(i, 1); return; }

    var settled = i >= 0 ? num(list[i].settled) : 0;
    var outstanding = Math.max(0, +(total - settled).toFixed(2));
    var row = {
      id: i >= 0 ? list[i].id : ('SCD-' + Date.now() + '-' + Math.floor(Math.random() * 1000)),
      txId: tx.id,
      date: tx.date || '',
      inv: tx.inv || '',
      txType: tx.type || '',
      party: tx.party || '',
      loc: tx.loc || '',
      agentA: tx.agentA || '', agentAcost: num(tx.agentAcost),
      agentB: tx.agentB || '', agentBcost: num(tx.agentBcost),
      qcperson: tx.qcperson || '', qc: num(tx.qc),
      unloadperson: tx.unloadperson || '', unload: num(tx.unload),
      otherperson: tx.otherperson || '', othercost: num(tx.othercost),
      otherperson2: tx.otherperson2 || '', othercost2: num(tx.othercost2),
      total: total,
      settled: settled,
      outstanding: outstanding,
      status: outstanding <= 0 ? 'Settled' : (settled > 0 ? 'Partial' : 'Unpaid'),
      payments: i >= 0 ? (list[i].payments || []) : [],
      createdAt: i >= 0 ? list[i].createdAt : new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };
    if (i >= 0) list[i] = row; else list.push(row);
  }

  W.saleCostDueTotal = function () {
    return saleCostDues().reduce(function (s, r) { return s + num(r.outstanding); }, 0);
  };

  W.settleSaleCostDue = function (id, amount, accName) {
    var row = saleCostDues().filter(function (r) { return r.id === id; })[0];
    if (!row) { say('Cost-due record not found', 'e'); return false; }
    var amt = num(amount);
    if (amt <= 0 || amt > num(row.outstanding) + 0.001) { say('Enter an amount between 0 and ' + money(row.outstanding), 'e'); return false; }
    if (accName) {
      var b = (DBx().banks || []).filter(function (x) { return x.name === accName; })[0];
      if (b) b.bal = num(b.bal) - amt;
    }
    row.settled = +(num(row.settled) + amt).toFixed(2);
    row.outstanding = Math.max(0, +(num(row.total) - row.settled).toFixed(2));
    row.status = row.outstanding <= 0 ? 'Settled' : 'Partial';
    row.updatedAt = new Date().toISOString();
    (row.payments = row.payments || []).push({ date: new Date().toISOString().slice(0, 10), amount: amt, account: accName || 'Cash' });
    persist();
    try { if (typeof W.logAudit === 'function') W.logAudit('UPDATE', 'Sale Cost Due', 'Settled ' + money(amt) + ' for ' + (row.qcperson || row.agentA || row.unloadperson || row.party || '')); } catch (e) {}
    say('Cost payment of ' + money(amt) + ' recorded', 's');
    renderSaleCostDueLedger();
    return true;
  };

  W.promptSettleSaleCostDue = function (id) {
    var row = saleCostDues().filter(function (r) { return r.id === id; })[0];
    if (!row) return;
    var amt = prompt('Payment amount (outstanding ' + money(row.outstanding) + '):', row.outstanding);
    if (amt === null) return;
    var accs = (DBx().banks || []).map(function (b) { return b.name; });
    var acc = accs.length ? prompt('Pay from account (' + accs.join(' / ') + ')\nLeave blank for cash-in-hand:', accs[0] || '') : '';
    W.settleSaleCostDue(id, amt, acc || '');
  };

  function renderSaleCostDueLedger() {
    var body = E('scd-body');
    if (!body) return;
    var rows = saleCostDues().slice().sort(function (a, b) { return String(b.date || '').localeCompare(String(a.date || '')); });
    var filter = (E('scd-filter') && E('scd-filter').value) || 'open';
    if (filter === 'open') rows = rows.filter(function (r) { return num(r.outstanding) > 0; });
    else if (filter === 'settled') rows = rows.filter(function (r) { return num(r.outstanding) <= 0; });

    var totCost = rows.reduce(function (s, r) { return s + num(r.total); }, 0);
    var totOut = rows.reduce(function (s, r) { return s + num(r.outstanding); }, 0);

    E('scd-kpi').innerHTML =
      '<div style="flex:1;background:#f0fdf4;border:1.5px solid #bbf7d0;border-radius:10px;padding:12px;">' +
      '<div style="font-size:10px;font-weight:800;color:#166534;text-transform:uppercase;">Total Sale Costs</div>' +
      '<div style="font-size:18px;font-weight:900;color:#0f3d26;">' + money(totCost) + '</div></div>' +
      '<div style="flex:1;background:#fffbeb;border:1.5px solid #fde68a;border-radius:10px;padding:12px;">' +
      '<div style="font-size:10px;font-weight:800;color:#b45309;text-transform:uppercase;">Outstanding Payable</div>' +
      '<div style="font-size:18px;font-weight:900;color:#b45309;">' + money(totOut) + '</div></div>' +
      '<div style="flex:1;background:#eff6ff;border:1.5px solid #bfdbfe;border-radius:10px;padding:12px;">' +
      '<div style="font-size:10px;font-weight:800;color:#1d4ed8;text-transform:uppercase;">Records</div>' +
      '<div style="font-size:18px;font-weight:900;color:#1d4ed8;">' + rows.length + '</div></div>';

    if (!rows.length) {
      body.innerHTML = '<tr><td colspan="12" style="padding:26px;text-align:center;color:#9ca3af;font-size:12px;">No agent/QC/unload costs recorded yet.</td></tr>';
      return;
    }
    body.innerHTML = rows.map(function (r, i) {
      var color = r.status === 'Settled' ? '#16a34a' : r.status === 'Partial' ? '#d97706' : '#dc2626';
      var who = [r.agentA, r.qcperson, r.unloadperson, r.otherperson, r.otherperson2].filter(Boolean).join(' / ') || '—';
      return '<tr style="border-bottom:1px solid #f1f5f9;">' +
        '<td style="padding:7px 9px;color:#94a3b8;">' + (i + 1) + '</td>' +
        '<td style="padding:7px 9px;">' + esc(r.date) + '</td>' +
        '<td style="padding:7px 9px;">' + esc(r.party || '—') + '</td>' +
        '<td style="padding:7px 9px;">' + esc(r.loc || '—') + '</td>' +
        '<td style="padding:7px 9px;font-size:10.5px;color:#64748b;">' + esc(who) + '</td>' +
        '<td style="padding:7px 9px;text-align:right;">' + money(r.agentAcost + r.agentBcost) + '</td>' +
        '<td style="padding:7px 9px;text-align:right;">' + money(r.qc) + '</td>' +
        '<td style="padding:7px 9px;text-align:right;">' + money(r.unload) + '</td>' +
        '<td style="padding:7px 9px;text-align:right;">' + money(r.othercost + r.othercost2) + '</td>' +
        '<td style="padding:7px 9px;text-align:right;font-weight:700;">' + money(r.total) + '</td>' +
        '<td style="padding:7px 9px;text-align:right;font-weight:800;color:' + color + ';">' + money(r.outstanding) + '</td>' +
        '<td style="padding:7px 9px;white-space:nowrap;">' +
        '<span style="background:' + color + ';color:#fff;border-radius:4px;padding:2px 7px;font-size:10px;font-weight:800;">' + esc(r.status) + '</span>' +
        (num(r.outstanding) > 0 ? ' <button data-x-click="openCostLineLedger(\'agentA\')" title="Pay Agent A/B, QC, Unload and Other separately in the Cost Ledgers" style="background:#7c3aed;color:#fff;border:0;border-radius:5px;padding:3px 9px;font-size:10px;font-weight:800;cursor:pointer;">Pay in Cost Ledgers \u2192</button>' : '') +
        '</td></tr>';
    }).join('');
  }
  W.renderSaleCostDueLedger = renderSaleCostDueLedger;

  W.openSaleCostDueLedger = function () {
    var m = E('scd-modal');
    if (!m) {
      m = document.createElement('div');
      m.id = 'scd-modal';
      m.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:9500;display:flex;align-items:center;justify-content:center;padding:16px;';
      m.innerHTML =
        '<div style="background:#fff;border-radius:14px;width:100%;max-width:1150px;max-height:88vh;overflow:auto;box-shadow:0 20px 50px rgba(0,0,0,.35);">' +
        '<div style="display:flex;align-items:center;justify-content:space-between;padding:16px 20px;border-bottom:2px solid #16a34a;position:sticky;top:0;background:#fff;">' +
        '<div style="font-size:16px;font-weight:900;color:#0f3d26;">👷 Agent / QC / Unload Due Ledger</div>' +
        '<div style="display:flex;gap:8px;align-items:center;">' +
        '<select id="scd-filter" data-x-change="renderSaleCostDueLedger()" style="padding:6px 10px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;">' +
        '<option value="open">Outstanding only</option><option value="all">All records</option><option value="settled">Settled</option></select>' +
        '<button data-x-click="document.getElementById(\'scd-modal\').style.display=\'none\'" style="background:#e5e7eb;border:0;border-radius:6px;padding:6px 12px;font-weight:800;cursor:pointer;">✕</button>' +
        '</div></div>' +
        '<div id="scd-kpi" style="display:flex;gap:10px;padding:14px 20px;"></div>' +
        '<div style="padding:0 20px 20px;overflow-x:auto;">' +
        '<table style="width:100%;border-collapse:collapse;font-size:11.5px;min-width:980px;">' +
        '<thead><tr style="background:#f0fdf4;color:#0f3d26;text-align:left;">' +
        '<th style="padding:9px;">#</th><th style="padding:9px;">Date</th><th style="padding:9px;">Party</th>' +
        '<th style="padding:9px;">Location</th><th style="padding:9px;">Who</th>' +
        '<th style="padding:9px;text-align:right;">Agent</th><th style="padding:9px;text-align:right;">QC</th>' +
        '<th style="padding:9px;text-align:right;">Unload</th><th style="padding:9px;text-align:right;">Other</th><th style="padding:9px;text-align:right;">Total</th>' +
        '<th style="padding:9px;text-align:right;">Outstanding</th><th style="padding:9px;">Status</th>' +
        '</tr></thead><tbody id="scd-body"></tbody></table></div></div>';
      document.body.appendChild(m);
    }
    m.style.display = 'flex';
    renderSaleCostDueLedger();
  };

  /* Backfill: any already-saved Sale that carries agent/QC/unload cost. */
  function backfillSaleCostDues() {
    var list = saleCostDues();
    if (list.__backfilled) return;
    var known = {};
    list.forEach(function (r) { known[r.txId] = 1; });
    (DBx().tx || []).forEach(function (t) {
      if (costTotal(t) > 0 && !known[t.id]) syncSaleCostDue(t);
    });
    try { Object.defineProperty(list, '__backfilled', { value: 1, enumerable: false }); } catch (e) {}
    persist();
  }

  function wrapSavePipeline() {
    if (typeof W._executeSaveTx !== 'function' || W._executeSaveTx.__scdWrapped) return false;
    var orig = W._executeSaveTx;
    var wrapped = function (tx, editId) {
      var out = orig.call(this, tx, editId);
      try { syncSaleCostDue(tx); persist(); renderSaleCostDueLedger(); refreshLauncherBadge(); } catch (e) { console.warn('scd sync', e); }
      return out;
    };
    wrapped.__scdWrapped = true;
    W._executeSaveTx = wrapped;

    if (typeof W.delTx === 'function' && !W.delTx.__scdWrapped) {
      var dOrig = W.delTx;
      var dWrapped = async function (id) {
        var r = await dOrig.call(this, id);
        try {
          var l = saleCostDues();
          for (var i = l.length - 1; i >= 0; i--) if (l[i].txId === id) l.splice(i, 1);
          persist(); renderSaleCostDueLedger(); refreshLauncherBadge();
        } catch (e) {}
        return r;
      };
      dWrapped.__scdWrapped = true;
      W.delTx = dWrapped;
    }
    return true;
  }

  function mountLauncherButton() {
    var launcher = E('v2-launcher');
    if (!launcher || E('v2-scd-btn')) return;
    var btn = document.createElement('button');
    btn.id = 'v2-scd-btn';
    btn.title = 'Agent / QC / Unload Due Ledger';
    btn.setAttribute('onclick', 'openSaleCostDueLedger()');
    btn.style.cssText = 'background:#7c3aed;color:#fff;border:0;border-radius:22px;padding:9px 15px;font-size:12px;font-weight:800;cursor:pointer;box-shadow:0 6px 18px rgba(0,0,0,.25);';
    btn.innerHTML = '👷 Cost Dues <span id="v2-scd-badge" style="background:#f59e0b;border-radius:10px;padding:1px 7px;margin-left:5px;">0</span>';
    launcher.appendChild(btn);
  }
  function refreshLauncherBadge() {
    var badge = E('v2-scd-badge');
    if (badge) {
      var t = W.saleCostDueTotal();
      badge.textContent = t > 0 ? money(t).replace('৳', '') : '0';
      badge.style.background = t > 0 ? '#dc2626' : '#16a34a';
    }
  }

  function tick() {
    try { wrapSavePipeline(); } catch (e) {}
    try { mountLauncherButton(); } catch (e) {}
    try { refreshLauncherBadge(); } catch (e) {}
  }
  function boot() {
    try { backfillSaleCostDues(); } catch (e) {}
    tick();
    setInterval(tick, 6000);
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();
})();
</script>
<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-cost-lines">
/* ═══════════════════════════════════════════════════════════════════════════
   GRANULAR COST LEDGERS — Agent A / Agent B / QC / Unload / Other, each
   payable on its own, all grouped by Customer (the way the owner
   actually pays them).
   The old "Sale Handling Costs Due" ledger (ayan-batchserial-physicalcount
   script, above) lumps all five into one all-or-nothing total per
   transaction, so you could never pay just Agent A while QC and Unload
   stayed open. This is the same money, split into its own line per
   category so each can be settled independently. To avoid ever paying the
   same cost twice, this ledger becomes the one source of truth: the totals
   used by the dashboard, launcher badge and Trial Balance now come from
   here, and the old lumped ledger's Pay button is turned into a read-only
   summary pointing here.
   ═══════════════════════════════════════════════════════════════════════════ */
(function () {
  'use strict';
  var W = window;
  function DBx() { return W.DB || (W.DB = {}); }
  function E(id) { return document.getElementById(id); }
  function num(v) { var n = parseFloat(v); return isFinite(n) ? n : 0; }
  function money(v) { return '৳' + num(v).toLocaleString('en-BD', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
  function say(msg, type) { try { if (typeof W.toast === 'function') W.toast(msg, type); else if (type === 'e') alert(msg); } catch (e) {} }
  function persist() { try { if (typeof W.saveDB === 'function') W.saveDB(); else if (typeof W.persist === 'function') W.persist(); } catch (e) {} }

  var CATS = [
    { key: 'agentA', label: 'Agent A', field: 'agentAcost', person: 'agentA', group: 'party', groupLabel: 'Customer' },
    { key: 'agentB', label: 'Agent B', field: 'agentBcost', person: 'agentB', group: 'party', groupLabel: 'Customer' },
    { key: 'qc', label: 'QC', field: 'qc', person: 'qcperson', group: 'party', groupLabel: 'Customer' },
    { key: 'unload', label: 'Unload', field: 'unload', person: 'unloadperson', group: 'party', groupLabel: 'Customer' },
    { key: 'other', label: 'Other', field: 'othercost', person: 'otherperson', group: 'party', groupLabel: 'Customer' },
    { key: 'other2', label: 'Another 2', field: 'othercost2', person: 'otherperson2', group: 'party', groupLabel: 'Customer' }
  ];
  function catOf(key) { return CATS.filter(function (c) { return c.key === key; })[0]; }

  function costLines() {
    var d = DBx();
    if (!Array.isArray(d.costLines)) d.costLines = [];
    return d.costLines;
  }

  /* Upsert up to 5 line items (one per non-zero category) for a saved Sale. */
  function syncCostLines(tx) {
    if (!tx || !(typeof W.isSaleType === 'function' && W.isSaleType(tx.type))) return;
    var list = costLines();
    CATS.forEach(function (c) {
      var amt = +num(tx[c.field]).toFixed(2);
      var id = 'CL-' + tx.id + '-' + c.key;
      var i = -1;
      for (var k = 0; k < list.length; k++) { if (list[k].id === id) { i = k; break; } }
      if (amt <= 0) { if (i >= 0) list.splice(i, 1); return; }
      var settled = i >= 0 ? num(list[i].settled) : 0;
      var outstanding = Math.max(0, +(amt - settled).toFixed(2));
      var row = {
        id: id,
        txId: tx.id,
        cat: c.key,
        date: tx.date || '',
        inv: tx.inv || '',
        party: tx.party || '',
        loc: tx.loc || '',
        groupKey: (c.group === 'party' ? (tx.party || 'Unassigned') : (tx.loc || 'Unassigned')),
        person: tx[c.person] || '',
        amount: amt,
        settled: settled,
        outstanding: outstanding,
        status: outstanding <= 0 ? 'Settled' : (settled > 0 ? 'Partial' : 'Unpaid'),
        payments: i >= 0 ? (list[i].payments || []) : [],
        createdAt: i >= 0 ? list[i].createdAt : new Date().toISOString(),
        updatedAt: new Date().toISOString()
      };
      if (i >= 0) list[i] = row; else list.push(row);
    });
  }

  /* Total outstanding for one category, or all of them if omitted — this is
     now the real, single-source figure (dashboard KPI, launcher badge, and
     the Trial Balance's "Sale Handling Costs Due" line all read this). */
  W.costLineTotal = function (catKey) {
    return costLines().filter(function (r) { return !catKey || r.cat === catKey; })
      .reduce(function (s, r) { return s + num(r.outstanding); }, 0);
  };
  // Supersede the old lumped total everywhere it's read from, so nothing can
  // be paid twice: the dashboard KPI, Trial Balance liability line, and
  // launcher badge all now reflect this granular ledger.
  W.ayanSaleCostDue = function () { return W.costLineTotal(); };
  W.saleCostDueTotal = function () { return W.costLineTotal(); };

  W.settleCostLine = function (id, amount, accName) {
    var row = costLines().filter(function (r) { return r.id === id; })[0];
    if (!row) { say('Cost line not found', 'e'); return false; }
    var amt = num(amount);
    if (amt <= 0 || amt > num(row.outstanding) + 0.001) { say('Enter an amount between 0 and ' + money(row.outstanding), 'e'); return false; }
    if (accName) {
      var b = (DBx().banks || []).filter(function (x) { return x.name === accName; })[0];
      if (b) b.bal = num(b.bal) - amt;
    }
    row.settled = +(num(row.settled) + amt).toFixed(2);
    row.outstanding = Math.max(0, +(row.amount - row.settled).toFixed(2));
    row.status = row.outstanding <= 0 ? 'Settled' : 'Partial';
    row.updatedAt = new Date().toISOString();
    (row.payments = row.payments || []).push({ date: new Date().toISOString().slice(0, 10), amount: amt, account: accName || 'Cash' });
    persist();
    try { if (typeof W.logAudit === 'function') W.logAudit('UPDATE', 'Cost Line (' + catOf(row.cat).label + ')', 'Settled ' + money(amt) + ' for ' + (row.person || row.party || '')); } catch (e) {}
    say(catOf(row.cat).label + ' payment of ' + money(amt) + ' recorded', 's');
    renderCostLineLedger();
    refreshCostLineBadge();
    return true;
  };

  W.promptSettleCostLine = function (id) {
    var row = costLines().filter(function (r) { return r.id === id; })[0];
    if (!row) return;
    var amt = prompt(catOf(row.cat).label + ' payment amount (outstanding ' + money(row.outstanding) + '):', row.outstanding);
    if (amt === null) return;
    var accs = (DBx().banks || []).map(function (b) { return b.name; });
    var acc = accs.length ? prompt('Pay from account (' + accs.join(' / ') + ')\nLeave blank for cash-in-hand:', accs[0] || '') : '';
    W.settleCostLine(id, amt, acc || '');
  };

  /* Direct removal of a single cost line from the ledger — e.g. it was
     created in error, or the owner has decided to waive it. This only
     removes the tracked ledger row; it does not touch the originating
     Sale, so if that Sale is later re-saved with the same cost field
     still set, syncCostLines() will recreate the line. Deleting the
     Sale itself removes its cost lines for good (see the delTx wrapper
     in wrapSavePipeline, below). */
  W.deleteCostLine = function (id) {
    var list = costLines();
    var i = -1;
    for (var k = 0; k < list.length; k++) { if (list[k].id === id) { i = k; break; } }
    if (i < 0) { say('Cost line not found', 'e'); return false; }
    var row = list[i];
    var label = catOf(row.cat).label;
    list.splice(i, 1);
    persist();
    try { if (typeof W.logAudit === 'function') W.logAudit('DELETE', 'Cost Line (' + label + ')', 'Removed ' + money(row.outstanding) + ' outstanding for ' + (row.person || row.party || '')); } catch (e) {}
    say(label + ' cost line removed', 's');
    renderCostLineLedger();
    refreshCostLineBadge();
    return true;
  };

  W.promptDeleteCostLine = async function (id) {
    var row = costLines().filter(function (r) { return r.id === id; })[0];
    if (!row) return;
    var label = catOf(row.cat).label;
    var msg = 'Delete this ' + label + ' cost line for ' + (row.party || row.person || 'this record') +
      ' (' + money(row.outstanding) + ' outstanding)? This cannot be undone.';
    var ok;
    try { ok = W.__confirm ? await W.__confirm(msg) : confirm(msg); } catch (e) { ok = confirm(msg); }
    if (!ok) return;
    W.deleteCostLine(id);
  };

  /* ── Tabbed, grouped ledger UI ── */
  W.selectCostLineCat = function (key) {
    E('cl-modal').setAttribute('data-cat', key);
    CATS.forEach(function (c) {
      var t = E('cl-tab-' + c.key);
      if (t) t.style.cssText = (c.key === key)
        ? 'background:#0f3d26;color:#fff;border:0;border-radius:7px;padding:7px 13px;font-size:11.5px;font-weight:800;cursor:pointer;'
        : 'background:#f1f5f9;color:#374151;border:0;border-radius:7px;padding:7px 13px;font-size:11.5px;font-weight:800;cursor:pointer;';
    });
    renderCostLineLedger();
  };

  function renderCostLineLedger() {
    var modal = E('cl-modal');
    var body = E('cl-body-modal');
    if (!body || !modal) return;
    var catKey = modal.getAttribute('data-cat') || 'agentA';
    var c = catOf(catKey);
    var filter = (E('cl-filter') && E('cl-filter').value) || 'open';
    var rows = costLines().filter(function (r) { return r.cat === catKey; });
    if (filter === 'open') rows = rows.filter(function (r) { return num(r.outstanding) > 0; });
    else if (filter === 'settled') rows = rows.filter(function (r) { return num(r.outstanding) <= 0; });

    // Group by Customer (all five categories now use the same key)
    var groups = {};
    rows.forEach(function (r) { (groups[r.groupKey] = groups[r.groupKey] || []).push(r); });
    var groupNames = Object.keys(groups).sort();

    var totAmt = rows.reduce(function (s, r) { return s + num(r.amount); }, 0);
    var totOut = rows.reduce(function (s, r) { return s + num(r.outstanding); }, 0);
    E('cl-kpi').innerHTML =
      '<div style="flex:1;background:#f0fdf4;border:1.5px solid #bbf7d0;border-radius:10px;padding:12px;">' +
      '<div style="font-size:10px;font-weight:800;color:#166534;text-transform:uppercase;">' + c.label + ' Total</div>' +
      '<div style="font-size:18px;font-weight:900;color:#0f3d26;">' + money(totAmt) + '</div></div>' +
      '<div style="flex:1;background:#fffbeb;border:1.5px solid #fde68a;border-radius:10px;padding:12px;">' +
      '<div style="font-size:10px;font-weight:800;color:#b45309;text-transform:uppercase;">Outstanding</div>' +
      '<div style="font-size:18px;font-weight:900;color:#b45309;">' + money(totOut) + '</div></div>' +
      '<div style="flex:1;background:#eff6ff;border:1.5px solid #bfdbfe;border-radius:10px;padding:12px;">' +
      '<div style="font-size:10px;font-weight:800;color:#1d4ed8;text-transform:uppercase;">Grouped by ' + c.groupLabel + '</div>' +
      '<div style="font-size:18px;font-weight:900;color:#1d4ed8;">' + groupNames.length + '</div></div>';

    if (!rows.length) {
      body.innerHTML = '<div style="padding:26px;text-align:center;color:#9ca3af;font-size:12px;">No ' + c.label + ' cost lines recorded.</div>';
      return;
    }
    body.innerHTML = groupNames.map(function (g) {
      var grows = groups[g].slice().sort(function (a, b) { return String(b.date || '').localeCompare(String(a.date || '')); });
      var gOut = grows.reduce(function (s, r) { return s + num(r.outstanding); }, 0);
      return '<div style="margin-bottom:16px;">' +
        '<div style="display:flex;justify-content:space-between;align-items:center;background:#f8fafc;border-radius:8px;padding:7px 12px;margin-bottom:6px;">' +
        '<div style="font-weight:900;color:#0f3d26;font-size:12.5px;">' + c.groupLabel + ': ' + (g || 'Unassigned') + '</div>' +
        '<div style="font-weight:800;font-size:11.5px;color:' + (gOut > 0 ? '#b45309' : '#16a34a') + ';">Outstanding: ' + money(gOut) + '</div></div>' +
        '<table style="width:100%;border-collapse:collapse;font-size:11.5px;min-width:760px;">' +
        '<thead><tr style="background:#f0fdf4;color:#0f3d26;text-align:left;">' +
        '<th style="padding:7px 9px;">Date</th><th style="padding:7px 9px;">Invoice</th><th style="padding:7px 9px;">Party</th>' +
        '<th style="padding:7px 9px;">Who</th><th style="padding:7px 9px;text-align:right;">Amount</th>' +
        '<th style="padding:7px 9px;text-align:right;">Paid</th><th style="padding:7px 9px;text-align:right;">Outstanding</th>' +
        '<th style="padding:7px 9px;">Status</th></tr></thead><tbody>' +
        grows.map(function (r) {
          var color = r.status === 'Settled' ? '#16a34a' : r.status === 'Partial' ? '#d97706' : '#dc2626';
          return '<tr style="border-bottom:1px solid #f1f5f9;">' +
            '<td style="padding:7px 9px;">' + (r.date || '') + '</td>' +
            '<td style="padding:7px 9px;">' + (r.inv || '\u2014') + '</td>' +
            '<td style="padding:7px 9px;">' + (r.party || '\u2014') + '</td>' +
            '<td style="padding:7px 9px;color:#64748b;">' + (r.person || '\u2014') + '</td>' +
            '<td style="padding:7px 9px;text-align:right;">' + money(r.amount) + '</td>' +
            '<td style="padding:7px 9px;text-align:right;color:#16a34a;">' + money(r.settled) + '</td>' +
            '<td style="padding:7px 9px;text-align:right;font-weight:800;color:' + color + ';">' + money(r.outstanding) + '</td>' +
            '<td style="padding:7px 9px;white-space:nowrap;">' +
            '<span style="background:' + color + ';color:#fff;border-radius:4px;padding:2px 7px;font-size:10px;font-weight:800;">' + r.status + '</span>' +
            (r.outstanding > 0 ? ' <button data-x-click="promptSettleCostLine(\'' + r.id + '\')" style="background:#16a34a;color:#fff;border:0;border-radius:5px;padding:3px 9px;font-size:10px;font-weight:800;cursor:pointer;">Pay</button>' : '') +
            ' <button data-x-click="promptDeleteCostLine(\'' + r.id + '\')" title="Delete this cost line" style="background:#fee2e2;color:#dc2626;border:1px solid #fecaca;border-radius:5px;padding:3px 8px;font-size:10px;font-weight:800;cursor:pointer;margin-left:4px;">🗑️</button>' +
            '</td></tr>';
        }).join('') +
        '</tbody></table></div>';
    }).join('');
  }
  W.renderCostLineLedger = renderCostLineLedger;

  W.openCostLineLedger = function (initialCat) {
    var m = E('cl-modal');
    if (!m) {
      m = document.createElement('div');
      m.id = 'cl-modal';
      m.setAttribute('data-cat', initialCat || 'agentA');
      m.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:9500;display:flex;align-items:center;justify-content:center;padding:16px;';
      m.innerHTML =
        '<div style="background:#fff;border-radius:14px;width:100%;max-width:1150px;max-height:88vh;overflow:auto;box-shadow:0 20px 50px rgba(0,0,0,.35);">' +
        '<div style="display:flex;align-items:center;justify-content:space-between;padding:16px 20px;border-bottom:2px solid #16a34a;position:sticky;top:0;background:#fff;flex-wrap:wrap;gap:10px;">' +
        '<div style="font-size:16px;font-weight:900;color:#0f3d26;">💸 Cost Ledgers \u2014 pay each one separately</div>' +
        '<div style="display:flex;gap:8px;align-items:center;">' +
        '<select id="cl-filter" data-x-change="renderCostLineLedger()" style="padding:6px 10px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;">' +
        '<option value="open">Outstanding only</option><option value="all">All records</option><option value="settled">Settled</option></select>' +
        '<button data-x-click="document.getElementById(\'cl-modal\').style.display=\'none\'" style="background:#e5e7eb;border:0;border-radius:6px;padding:6px 12px;font-weight:800;cursor:pointer;">\u2715</button>' +
        '</div></div>' +
        '<div style="display:flex;gap:6px;padding:12px 20px 0;flex-wrap:wrap;">' +
        CATS.map(function (c) {
          return '<button id="cl-tab-' + c.key + '" data-x-click="selectCostLineCat(\'' + c.key + '\')" style="background:#f1f5f9;color:#374151;border:0;border-radius:7px;padding:7px 13px;font-size:11.5px;font-weight:800;cursor:pointer;">' + c.label + ' (by ' + c.groupLabel + ')</button>';
        }).join('') +
        '</div>' +
        '<div id="cl-kpi" style="display:flex;gap:10px;padding:14px 20px;"></div>' +
        '<div id="cl-body-modal" style="padding:0 20px 20px;overflow-x:auto;"></div></div>';
      document.body.appendChild(m);
    }
    m.style.display = 'flex';
    W.selectCostLineCat(initialCat || m.getAttribute('data-cat') || 'agentA');
  };

  /* Backfill: any already-saved Sale that carries these costs. */
  function backfillCostLines() {
    var list = costLines();
    if (list.__backfilled) return;
    var known = {};
    list.forEach(function (r) { known[r.txId + '_' + r.cat] = 1; });
    (DBx().tx || []).forEach(function (t) {
      CATS.forEach(function (c) {
        if (num(t[c.field]) > 0 && !known[t.id + '_' + c.key]) syncCostLines(t);
      });
    });
    try { Object.defineProperty(list, '__backfilled', { value: 1, enumerable: false }); } catch (e) {}
    persist();
  }

  function wrapSavePipeline() {
    if (typeof W._executeSaveTx !== 'function' || W._executeSaveTx.__clWrapped) return false;
    var orig = W._executeSaveTx;
    var wrapped = function (tx, editId) {
      var out = orig.call(this, tx, editId);
      try { syncCostLines(tx); persist(); renderCostLineLedger(); refreshCostLineBadge(); } catch (e) { console.warn('costline sync', e); }
      return out;
    };
    wrapped.__clWrapped = true;
    W._executeSaveTx = wrapped;

    if (typeof W.delTx === 'function' && !W.delTx.__clWrapped) {
      var dOrig = W.delTx;
      var dWrapped = async function (id) {
        var r = await dOrig.call(this, id);
        try {
          var l = costLines();
          for (var i = l.length - 1; i >= 0; i--) if (l[i].txId === id) l.splice(i, 1);
          persist(); renderCostLineLedger(); refreshCostLineBadge();
        } catch (e) {}
        return r;
      };
      dWrapped.__clWrapped = true;
      W.delTx = dWrapped;
    }
    return true;
  }

  function mountLauncherButton() {
    var launcher = E('v2-launcher');
    if (!launcher || E('v2-cl-btn')) return;
    var btn = document.createElement('button');
    btn.id = 'v2-cl-btn';
    btn.title = 'Agent A / Agent B / QC (by Location) \u00b7 Unload (by Customer) \u00b7 Other (by Location)';
    btn.setAttribute('onclick', "openCostLineLedger('agentA')");
    btn.style.cssText = 'background:#7c3aed;color:#fff;border:0;border-radius:22px;padding:9px 15px;font-size:12px;font-weight:800;cursor:pointer;box-shadow:0 6px 18px rgba(0,0,0,.25);';
    btn.innerHTML = '💸 Cost Ledgers <span id="v2-cl-badge" style="background:#f59e0b;border-radius:10px;padding:1px 7px;margin-left:5px;">0</span>';
    launcher.appendChild(btn);
    // The old lumped "Cost Dues" launcher button (v2-scd-btn) now points here
    // too, since it shows the same total and this is where it's actually paid.
    var old = E('v2-scd-btn');
    if (old) old.setAttribute('onclick', "openCostLineLedger('agentA')");
  }
  function refreshCostLineBadge() {
    var badge = E('v2-cl-badge');
    var t = W.costLineTotal();
    if (badge) {
      badge.textContent = t > 0 ? money(t).replace('৳', '') : '0';
      badge.style.background = t > 0 ? '#dc2626' : '#16a34a';
    }
    var navBadge = E('nb-costline');
    if (navBadge) navBadge.textContent = t > 0 ? money(t).replace('৳', '') : '0';
  }

  function tick() {
    try { wrapSavePipeline(); } catch (e) {}
    try { mountLauncherButton(); } catch (e) {}
    try { refreshCostLineBadge(); } catch (e) {}
  }
  function boot() {
    try { backfillCostLines(); } catch (e) {}
    tick();
    setInterval(tick, 6000);
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();
})();
</script>
<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-factory-finance">
/* ═══════════════════════════════════════════════════════════════════════════
   FACTORY FINANCE — City Bank invoice discounting (2026-08-20, as described)

   How it actually works, per the owner: after goods are delivered and a Sale
   invoice exists, the invoice is submitted to City Bank. City Bank advances
   85% of the invoice value into a chosen account immediately, keeping a
   0.05% fee out of that advance. The customer still owes the FULL invoice —
   City Bank is lending against it, not buying it — so when the customer
   eventually pays the full amount (to settle the facility), City Bank keeps
   13.10% p.a. interest on the advanced amount for however many days it was
   outstanding, and remits whatever's left of the held-back 15% to the
   business. This is a general facility — usable against any customer's
   invoice, not tied to one company name.

   Modelled as its own ledger (DB.factoryFinance), same shape as Transport
   Dues / Sale Cost Dues: nothing about a normal Sale changes. Submitting to
   Factory Finance is a separate, explicit action:
     - On submit: bank += (invoice × advance% − fee); customer balance is
       UNTOUCHED (they still owe the full invoice — the money that just
       landed is a loan against it, not their payment).
     - On settle (customer's payment finally arrives): interest is computed
       from days elapsed × 13.10%/365 on the advanced amount (editable);
       bank += (invoice × (1−advance%) − interest) — the held-back 15% minus
       the finance charge; customer balance -= full invoice (this is the
       point their debt is actually cleared, because this is genuinely when
       they paid).
   Every rate (advance %, fee %, interest % p.a.) is editable per submission,
   defaulting to 85 / 0.05 / 13.10 — your real numbers — but this isn't
   hardcoded to only ever be those three numbers if terms change later.
   ═══════════════════════════════════════════════════════════════════════════ */
(function () {
  'use strict';
  var W = window;
  function E(id) { return document.getElementById(id); }
  function num(v) { var n = parseFloat(v); return isNaN(n) ? 0 : n; }
  function say(m, t) { try { if (typeof W.toast === 'function') return W.toast(m, t || 'i'); } catch (e) {} }
  function money(n) { return '৳' + num(n).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
  function esc(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
  function DBx() { if (!W.DB || typeof W.DB !== 'object') W.DB = {}; return W.DB; }
  function persist() { try { if (typeof W.saveDB === 'function') W.saveDB(); } catch (e) {} }
  function today() { return new Date().toISOString().slice(0, 10); }
  function daysBetween(a, b) { var d = (new Date(b) - new Date(a)) / 86400000; return isFinite(d) ? Math.max(0, Math.round(d)) : 0; }

  function factoryFinances() {
    var d = DBx();
    if (!Array.isArray(d.factoryFinance)) d.factoryFinance = [];
    return d.factoryFinance;
  }

  function adjBank(name, delta) {
    if (!name) return;
    var b = (DBx().banks || []).filter(function (x) { return x.name === name; })[0];
    if (b) b.bal = num(b.bal) + delta;
  }
  function adjParty(name, delta) {
    if (!name) return;
    var c = (DBx().customers || []).filter(function (x) { return x.name === name; })[0];
    if (c) c.bal = num(c.bal) + delta;
  }

  /* Submit an invoice for discounting. txId is optional (links back to the
     originating Sale for reference only — nothing about the Sale itself is
     touched). Returns the created record. */
  W.submitFactoryFinance = function (party, invoiceAmt, bankName, opts) {
    opts = opts || {};
    invoiceAmt = num(invoiceAmt);
    if (!party) { say('Customer/party name required', 'e'); return null; }
    if (invoiceAmt <= 0) { say('Invoice amount must be > 0', 'e'); return null; }
    if (!bankName) { say('Choose which account receives the advance', 'e'); return null; }
    var advPct = opts.advPct != null ? num(opts.advPct) : 85;
    var feePct = opts.feePct != null ? num(opts.feePct) : 0.05;
    var intRate = opts.intRate != null ? num(opts.intRate) : 13.10;
    var advanceAmt = +(invoiceAmt * advPct / 100).toFixed(2);
    var fee = +(invoiceAmt * feePct / 100).toFixed(2);
    var netAdvance = +(advanceAmt - fee).toFixed(2);
    var row = {
      id: 'FF-' + Date.now() + '-' + Math.floor(Math.random() * 1000),
      txId: opts.txId || null,
      inv: opts.inv || '',
      party: party,
      date: opts.date || today(),
      bank: bankName,
      invoiceAmt: invoiceAmt,
      advPct: advPct, feePct: feePct, intRate: intRate,
      advanceAmt: advanceAmt, fee: fee, netAdvance: netAdvance,
      holdback: +(invoiceAmt - advanceAmt).toFixed(2),
      status: 'Outstanding',
      settledDate: null, days: null, interest: null, finalRemit: null,
      createdAt: new Date().toISOString(), updatedAt: new Date().toISOString()
    };
    factoryFinances().push(row);
    adjBank(bankName, netAdvance);   // customer balance is deliberately NOT touched here — see header note
    persist();
    try { if (typeof W.logAudit === 'function') W.logAudit('CREATE', 'Factory Finance', 'Submitted ' + money(invoiceAmt) + ' invoice for ' + party + ' — advanced ' + money(netAdvance) + ' to ' + bankName); } catch (e) {}
    say('Factory Finance: ' + money(netAdvance) + ' advanced into ' + bankName, 's');
    renderFactoryFinanceLedger(); refreshFFBadge();
    return row;
  };

  /* Settle a facility once the customer has actually paid in full.
     interestOverride lets you type the bank's exact charged interest instead
     of trusting the day-count formula, if they ever differ. */
  W.settleFactoryFinance = function (id, settleDate, interestOverride) {
    var row = factoryFinances().filter(function (r) { return r.id === id; })[0];
    if (!row) { say('Facility record not found', 'e'); return false; }
    if (row.status === 'Settled') { say('Already settled', 'e'); return false; }
    settleDate = settleDate || today();
    var days = daysBetween(row.date, settleDate);
    var interest = interestOverride != null && interestOverride !== ''
      ? num(interestOverride)
      : +(row.advanceAmt * (row.intRate / 100) * (days / 365)).toFixed(2);
    var finalRemit = +(row.holdback - interest).toFixed(2);

    row.status = 'Settled';
    row.settledDate = settleDate;
    row.days = days;
    row.interest = interest;
    row.finalRemit = finalRemit;
    row.updatedAt = new Date().toISOString();

    adjBank(row.bank, finalRemit);           // held-back 15% minus interest lands now
    adjParty(row.party, -row.invoiceAmt);    // customer's full invoice is cleared — this is when they actually paid

    persist();
    try { if (typeof W.logAudit === 'function') W.logAudit('UPDATE', 'Factory Finance', 'Settled ' + row.party + ' invoice ' + money(row.invoiceAmt) + ' — ' + days + ' days, interest ' + money(interest) + ', remitted ' + money(finalRemit)); } catch (e) {}
    say('Facility settled — ' + money(finalRemit) + ' remitted, ' + money(interest) + ' interest over ' + days + ' days', 's');
    renderFactoryFinanceLedger(); refreshFFBadge();
    return true;
  };

  W.factoryFinanceOutstanding = function () {
    return factoryFinances().filter(function (r) { return r.status !== 'Settled'; })
      .reduce(function (s, r) { return s + num(r.advanceAmt); }, 0);
  };

  /* ── Quick-entry prompts (mirrors promptSettleTransportDue's style) ── */
  W.promptSubmitFactoryFinance = function () {
    var party = prompt('Customer / company name on the invoice (e.g. from a Sale you already recorded):');
    if (!party) return;
    var invoiceAmt = prompt('Full invoice amount (৳):', '0');
    if (invoiceAmt === null) return;
    var banks = (DBx().banks || []).map(function (b) { return b.name; });
    var bank = prompt('Advance goes into which account?\n(' + banks.join(' / ') + ')', 'City MESARS KARIMA ENTERPRISE');
    if (bank === null) return;
    var advPct = prompt('Advance % (City Bank normally advances this much upfront):', '85');
    if (advPct === null) return;
    var feePct = prompt('Upfront fee % (deducted from the advance):', '0.05');
    if (feePct === null) return;
    var intRate = prompt('Interest rate % per annum (charged on the advance until settled):', '13.10');
    if (intRate === null) return;
    W.submitFactoryFinance(party, invoiceAmt, bank, { advPct: advPct, feePct: feePct, intRate: intRate });
  };

  W.promptSettleFactoryFinance = function (id) {
    var row = factoryFinances().filter(function (r) { return r.id === id; })[0];
    if (!row) return;
    var d = prompt('Settlement date (customer paid in full) — YYYY-MM-DD:', today());
    if (d === null) return;
    var days = daysBetween(row.date, d);
    var estInterest = +(row.advanceAmt * (row.intRate / 100) * (days / 365)).toFixed(2);
    var interest = prompt('Interest for ' + days + ' day(s) at ' + row.intRate + '% p.a. — estimated ' + money(estInterest) + '.\nPress OK to use this, or type the exact figure from City Bank\'s statement:', estInterest);
    if (interest === null) return;
    W.settleFactoryFinance(id, d, interest);
  };

  /* ── Ledger UI ── */
  function renderFactoryFinanceLedger() {
    var body = E('ff-body');
    if (!body) return;
    var rows = factoryFinances().slice().sort(function (a, b) { return String(b.date || '').localeCompare(String(a.date || '')); });
    var filter = (E('ff-filter') && E('ff-filter').value) || 'open';
    if (filter === 'open') rows = rows.filter(function (r) { return r.status !== 'Settled'; });
    else if (filter === 'settled') rows = rows.filter(function (r) { return r.status === 'Settled'; });

    var totAdvanced = rows.reduce(function (s, r) { return s + num(r.advanceAmt); }, 0);
    var totOutstanding = rows.filter(function (r) { return r.status !== 'Settled'; }).reduce(function (s, r) { return s + num(r.advanceAmt); }, 0);
    var totInterest = rows.reduce(function (s, r) { return s + num(r.interest); }, 0);

    E('ff-kpi').innerHTML =
      '<div style="flex:1;background:#eff6ff;border:1.5px solid #bfdbfe;border-radius:10px;padding:12px;">' +
      '<div style="font-size:10px;font-weight:800;color:#1d4ed8;text-transform:uppercase;">Total Advanced</div>' +
      '<div style="font-size:18px;font-weight:900;color:#1e3a8a;">' + money(totAdvanced) + '</div></div>' +
      '<div style="flex:1;background:#fffbeb;border:1.5px solid #fde68a;border-radius:10px;padding:12px;">' +
      '<div style="font-size:10px;font-weight:800;color:#b45309;text-transform:uppercase;">Outstanding Facility</div>' +
      '<div style="font-size:18px;font-weight:900;color:#b45309;">' + money(totOutstanding) + '</div></div>' +
      '<div style="flex:1;background:#fef2f2;border:1.5px solid #fecaca;border-radius:10px;padding:12px;">' +
      '<div style="font-size:10px;font-weight:800;color:#dc2626;text-transform:uppercase;">Interest Paid</div>' +
      '<div style="font-size:18px;font-weight:900;color:#dc2626;">' + money(totInterest) + '</div></div>';

    if (!rows.length) {
      body.innerHTML = '<tr><td colspan="10" style="padding:26px;text-align:center;color:#9ca3af;font-size:12px;">No Factory Finance submissions yet.</td></tr>';
      return;
    }
    body.innerHTML = rows.map(function (r, i) {
      var color = r.status === 'Settled' ? '#16a34a' : '#d97706';
      return '<tr style="border-bottom:1px solid #f1f5f9;">' +
        '<td style="padding:7px 9px;color:#94a3b8;">' + (i + 1) + '</td>' +
        '<td style="padding:7px 9px;">' + esc(r.date) + '</td>' +
        '<td style="padding:7px 9px;">' + esc(r.party) + '</td>' +
        '<td style="padding:7px 9px;">' + esc(r.bank) + '</td>' +
        '<td style="padding:7px 9px;text-align:right;">' + money(r.invoiceAmt) + '</td>' +
        '<td style="padding:7px 9px;text-align:right;color:#1d4ed8;font-weight:700;">' + money(r.netAdvance) + '</td>' +
        '<td style="padding:7px 9px;text-align:right;">' + money(r.holdback) + '</td>' +
        '<td style="padding:7px 9px;text-align:right;color:#dc2626;">' + (r.interest != null ? money(r.interest) : '—') + '</td>' +
        '<td style="padding:7px 9px;text-align:right;font-weight:700;">' + (r.finalRemit != null ? money(r.finalRemit) : '—') + '</td>' +
        '<td style="padding:7px 9px;white-space:nowrap;">' +
        '<span style="background:' + color + ';color:#fff;border-radius:4px;padding:2px 7px;font-size:10px;font-weight:800;">' + esc(r.status) + '</span>' +
        (r.status !== 'Settled' ? ' <button data-x-click="promptSettleFactoryFinance(\'' + r.id + '\')" style="background:#16a34a;color:#fff;border:0;border-radius:5px;padding:3px 9px;font-size:10px;font-weight:800;cursor:pointer;">Settle</button>' : '') +
        '</td></tr>';
    }).join('');
  }
  W.renderFactoryFinanceLedger = renderFactoryFinanceLedger;

  W.openFactoryFinanceLedger = function () {
    var m = E('ff-modal');
    if (!m) {
      m = document.createElement('div');
      m.id = 'ff-modal';
      m.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:9500;display:flex;align-items:center;justify-content:center;padding:16px;';
      m.innerHTML =
        '<div style="background:#fff;border-radius:14px;width:100%;max-width:1180px;max-height:88vh;overflow:auto;box-shadow:0 20px 50px rgba(0,0,0,.35);">' +
        '<div style="display:flex;align-items:center;justify-content:space-between;padding:16px 20px;border-bottom:2px solid #1d4ed8;position:sticky;top:0;background:#fff;">' +
        '<div style="font-size:16px;font-weight:900;color:#1e3a8a;">🏭 Factory Finance (City Bank)</div>' +
        '<div style="display:flex;gap:8px;align-items:center;">' +
        '<select id="ff-filter" data-x-change="renderFactoryFinanceLedger()" style="padding:6px 10px;border:1px solid #d1d5db;border-radius:6px;font-size:12px;">' +
        '<option value="open">Outstanding only</option><option value="all">All records</option><option value="settled">Settled</option></select>' +
        '<button data-x-click="promptSubmitFactoryFinance()" style="background:#1d4ed8;color:#fff;border:0;border-radius:6px;padding:7px 14px;font-size:12px;font-weight:800;cursor:pointer;">➕ Submit Invoice</button>' +
        '<button data-x-click="document.getElementById(\'ff-modal\').style.display=\'none\'" style="background:#e5e7eb;border:0;border-radius:6px;padding:6px 12px;font-weight:800;cursor:pointer;">✕</button>' +
        '</div></div>' +
        '<div id="ff-kpi" style="display:flex;gap:10px;padding:14px 20px;"></div>' +
        '<div style="padding:0 20px 8px;font-size:11px;color:#6b7280;">Invoice amount owed by the customer stays on their balance until they actually pay and the facility is settled — the advance you get now is a loan against the invoice, not the customer\'s payment.</div>' +
        '<div style="padding:0 20px 20px;overflow-x:auto;">' +
        '<table style="width:100%;border-collapse:collapse;font-size:11.5px;min-width:1020px;">' +
        '<thead><tr style="background:#eff6ff;color:#1e3a8a;text-align:left;">' +
        '<th style="padding:9px;">#</th><th style="padding:9px;">Date</th><th style="padding:9px;">Customer</th>' +
        '<th style="padding:9px;">Bank</th><th style="padding:9px;text-align:right;">Invoice</th>' +
        '<th style="padding:9px;text-align:right;">Advanced (net)</th><th style="padding:9px;text-align:right;">Held Back</th>' +
        '<th style="padding:9px;text-align:right;">Interest</th><th style="padding:9px;text-align:right;">Final Remit</th>' +
        '<th style="padding:9px;">Status</th>' +
        '</tr></thead><tbody id="ff-body"></tbody></table></div></div>';
      document.body.appendChild(m);
    }
    m.style.display = 'flex';
    renderFactoryFinanceLedger();
  };

  function mountLauncherButton() {
    var launcher = E('v2-launcher');
    if (!launcher || E('v2-ff-btn')) return;
    var btn = document.createElement('button');
    btn.id = 'v2-ff-btn';
    btn.title = 'Factory Finance (City Bank)';
    btn.setAttribute('onclick', 'openFactoryFinanceLedger()');
    btn.style.cssText = 'background:#1d4ed8;color:#fff;border:0;border-radius:22px;padding:9px 15px;font-size:12px;font-weight:800;cursor:pointer;box-shadow:0 6px 18px rgba(0,0,0,.25);';
    btn.innerHTML = '🏭 Factory Finance <span id="v2-ff-badge" style="background:#f59e0b;border-radius:10px;padding:1px 7px;margin-left:5px;">0</span>';
    launcher.appendChild(btn);
  }
  function refreshFFBadge() {
    var badge = E('v2-ff-badge');
    if (badge) {
      var t = W.factoryFinanceOutstanding();
      badge.textContent = t > 0 ? money(t).replace('৳', '') : '0';
      badge.style.background = t > 0 ? '#dc2626' : '#16a34a';
    }
  }

  function tick() {
    try { mountLauncherButton(); } catch (e) {}
    try { refreshFFBadge(); } catch (e) {}
  }
  function boot() { tick(); setInterval(tick, 6000); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();
})();
</script>
<style id="qt-agro-style">
/* ═══ Quotations — AgroBiz visual design (scoped to .qt-agro so it never
   leaks into the rest of the ERP's global .btn/.tbl/table/.modal styles) ═══ */
.qt-agro{
  --qa-dg:#1b5e20;--qa-mg:#2e7d32;--qa-lg:#4caf50;--qa-pg:#e8f5e9;
  --qa-blue:#1565c0;--qa-yellow:#f9a825;--qa-orange:#e65100;--qa-teal:#00695c;--qa-red:#c62828;
  --qa-border:#e0e0e0;--qa-shadow:0 2px 12px rgba(0,0,0,.10);--qa-radius:8px;
  font-family:'Segoe UI',Arial,sans-serif;font-size:13px;color:#1a1a1a;
}
.qt-agro *{box-sizing:border-box;}
.qt-agro .qa-header{background:linear-gradient(90deg,#1b5e20,#2e7d32 70%,#388e3c);color:#fff;
  padding:12px 16px;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px;
  border-radius:var(--qa-radius) var(--qa-radius) 0 0;margin:-26px -26px 14px;}
.qt-agro .qa-header-left{display:flex;align-items:center;gap:10px;}
.qt-agro .qa-header-icon{width:36px;height:36px;background:rgba(255,255,255,.15);border-radius:6px;
  display:flex;align-items:center;justify-content:center;font-size:20px;}
.qt-agro .qa-header h2{font-size:16px;font-weight:700;margin:0;}
.qt-agro .qa-header-sub{font-size:11px;opacity:.8;margin-top:1px;}
.qt-agro .qa-header-actions{display:flex;gap:8px;flex-wrap:wrap;}
.qt-agro .qa-btn{padding:7px 14px;border-radius:5px;border:none;cursor:pointer;font-size:12px;
  font-weight:600;display:inline-flex;align-items:center;gap:5px;transition:all .15s;white-space:nowrap;}
.qt-agro .qa-btn-outline{background:rgba(255,255,255,.14);color:#fff;border:1px solid rgba(255,255,255,.4);}
.qt-agro .qa-btn-outline:hover{background:rgba(255,255,255,.24);}
.qt-agro .qa-btn-white{background:#fff;color:var(--qa-mg);}
.qt-agro .qa-btn-white:hover{background:#f1f8e9;}
.qt-agro .qa-btn-sm{padding:5px 11px;border-radius:5px;border:1px solid #ddd;background:#fff;
  font-size:11.5px;color:#555;font-weight:600;display:inline-flex;align-items:center;gap:4px;cursor:pointer;}
.qt-agro .qa-btn-sm:hover{background:#f1f8e9;border-color:#a5d6a7;color:#2e7d32;}
.qt-agro .qa-btn-sm.primary{background:#2e7d32;color:#fff;border-color:#2e7d32;}
.qt-agro .qa-btn-sm.primary:hover{background:#1b5e20;}
.qt-agro .qa-btn-sm.danger{background:#fff;color:#c62828;border-color:#ef9a9a;}
.qt-agro .qa-btn-sm.danger:hover{background:#ffebee;}
.qt-agro .qa-btn-sm.teal{background:#00695c;color:#fff;border-color:#00695c;}
.qt-agro .qa-btn-sm.teal:hover{background:#004d40;}
.qt-agro .qa-btn-sm.info{background:#1565c0;color:#fff;border-color:#1565c0;}
.qt-agro .qa-btn-sm.info:hover{background:#0d47a1;}
.qt-agro .qa-metrics{display:flex;gap:10px;margin-bottom:14px;flex-wrap:wrap;}
.qt-agro .qa-metric{flex:1;min-width:120px;background:#fff;border-radius:var(--qa-radius);
  padding:10px 12px;box-shadow:var(--qa-shadow);border-left:5px solid #ccc;}
.qt-agro .qa-metric.blue{border-left-color:var(--qa-blue);}
.qt-agro .qa-metric.green{border-left-color:var(--qa-mg);}
.qt-agro .qa-metric.yellow{border-left-color:var(--qa-yellow);}
.qt-agro .qa-metric.teal{border-left-color:var(--qa-teal);}
.qt-agro .qa-metric.red{border-left-color:var(--qa-red);}
.qt-agro .qa-metric-label{font-size:10px;color:#888;text-transform:uppercase;letter-spacing:.5px;
  font-weight:600;margin-bottom:2px;}
.qt-agro .qa-metric-value{font-size:19px;font-weight:800;line-height:1;color:#1a1a1a;}
.qt-agro .qa-card{background:#fff;border-radius:var(--qa-radius);box-shadow:var(--qa-shadow);
  overflow:hidden;margin-bottom:14px;}
.qt-agro .qa-card-head{background:linear-gradient(90deg,#1b5e20,#2e7d32);color:#fff;padding:9px 14px;
  font-size:13px;font-weight:700;display:flex;align-items:center;justify-content:space-between;}
.qt-agro .qa-badge{background:rgba(255,255,255,.2);border-radius:10px;padding:2px 8px;font-size:11px;font-weight:600;}
.qt-agro .qa-toolbar{display:flex;align-items:center;justify-content:space-between;padding:9px 12px;
  border-bottom:1px solid #f0f0f0;background:#fafafa;flex-wrap:wrap;gap:8px;}
.qt-agro .qa-search{display:flex;align-items:center;gap:6px;background:#fff;border:1.5px solid #ddd;
  border-radius:20px;padding:5px 12px;font-size:12px;color:#888;min-width:220px;}
.qt-agro .qa-search:focus-within{border-color:var(--qa-mg);}
.qt-agro .qa-search input{border:none;outline:none;background:transparent;font-size:12px;color:#333;width:100%;}
.qt-agro .qa-filter{padding:5px 9px;border:1.5px solid #ddd;border-radius:6px;font-size:12px;
  color:#555;background:#fff;cursor:pointer;outline:none;}
.qt-agro .qa-table-wrap{overflow-x:auto;max-height:50vh;overflow-y:auto;}
.qt-agro table.qa-table{width:100%;border-collapse:collapse;font-size:12.5px;}
.qt-agro table.qa-table thead th{background:#2e7d32;color:#fff;padding:9px 10px;text-align:center;
  font-weight:700;border-right:1px solid rgba(255,255,255,.15);white-space:nowrap;font-size:11.5px;
  position:sticky;top:0;}
.qt-agro table.qa-table tbody td{padding:7px 10px;border-bottom:1px solid #f0f0f0;
  border-right:1px solid #f5f5f5;text-align:center;}
.qt-agro table.qa-table tbody tr:hover td{background:#f1f8e9!important;}
.qt-agro table.qa-table tbody tr:nth-child(even) td{background:#fafafa;}
.qt-agro .qa-td-left{text-align:left!important;font-weight:500;}
.qt-agro .qa-td-num{font-family:'Courier New',monospace;font-size:12px;}
.qt-agro .qa-td-sl{text-align:center!important;font-weight:700;color:#6b7280;}
.qt-agro .qa-rate-chip{display:inline-block;background:#e8f5e9;color:#1b5e20;border-radius:14px;
  padding:2px 10px;font-weight:800;font-size:12.5px;border:1.5px solid #a5d6a7;}
.qt-agro .qa-status{display:inline-block;border-radius:10px;padding:2px 9px;font-size:11px;font-weight:700;}
.qt-agro .qa-status-Draft{background:#fff8e1;color:#f57f17;}
.qt-agro .qa-status-Sent{background:#e3f2fd;color:#1565c0;}
.qt-agro .qa-status-Accepted{background:#e8f5e9;color:#2e7d32;}
.qt-agro .qa-status-Rejected{background:#ffebee;color:#c62828;}
.qt-agro .qa-status-Expired{background:#f5f5f5;color:#757575;}
.qt-agro .qa-table-info{padding:7px 14px;font-size:11px;color:#888;background:#fafafa;border-top:1px solid #f0f0f0;}
.qt-agro .qa-form-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px 14px;padding:14px;}
.qt-agro .qa-fg{display:flex;flex-direction:column;gap:4px;}
.qt-agro .qa-fg.full{grid-column:1/-1;}
.qt-agro .qa-lbl{font-size:11px;font-weight:700;color:#555;text-transform:uppercase;letter-spacing:.3px;}
.qt-agro .qa-fc{padding:7px 10px;border:1.5px solid #ddd;border-radius:6px;font-size:12.5px;outline:none;}
.qt-agro .qa-fc:focus{border-color:var(--qa-mg);box-shadow:0 0 0 3px rgba(46,125,50,.12);}
.qt-agro .qa-items-wrap{padding:0 14px 14px;}
.qt-agro .qa-totals{padding:0 14px 14px;display:flex;justify-content:flex-end;}
.qt-agro .qa-totals-box{min-width:280px;background:var(--qa-pg);border:1.5px solid #a5d6a7;
  border-radius:var(--qa-radius);padding:10px 14px;}
.qt-agro .qa-totals-row{display:flex;justify-content:space-between;padding:3px 0;font-size:12.5px;}
.qt-agro .qa-totals-row.grand{border-top:2px solid #a5d6a7;margin-top:4px;padding-top:7px;
  font-weight:800;font-size:14px;color:var(--qa-dg);}
.qt-agro .qa-footer-actions{display:flex;justify-content:space-between;padding:14px;
  border-top:1px solid #f0f0f0;flex-wrap:wrap;gap:8px;}
@media(max-width:640px){.qt-agro .qa-form-grid{grid-template-columns:1fr;}}

/* ── Trial Balance — Left vs Right (reuses the .qt-agro design system) ── */
.qt-agro .qa-tb-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:14px;}
.qt-agro .qa-tb-side .qa-card-head{background:linear-gradient(90deg,#1b5e20,#2e7d32);}
.qt-agro .qa-tb-side.blue .qa-card-head{background:linear-gradient(90deg,#1e40af,#1565c0);}
.qt-agro .qa-tb-side.green .qa-card-head{background:linear-gradient(90deg,#15803d,#2e7d32);}
.qt-agro .qa-tb-rows{padding:10px 14px;}
.qt-agro .qa-tb-row{padding:7px 0;border-bottom:1px solid #f3f4f6;}
.qt-agro .qa-tb-row-main{display:flex;justify-content:space-between;align-items:center;}
.qt-agro .qa-tb-row-label{font-size:12px;color:#374151;}
.qt-agro .qa-tb-row-val{font-size:12px;font-weight:700;color:#1a1a1a;}
.qt-agro .qa-tb-row.neg .qa-tb-row-val{color:var(--qa-red);}
.qt-agro .qa-tb-row-detail{font-size:10px;color:#6b7280;margin-top:2px;padding-left:22px;}
.qt-agro .qa-tb-total{padding:12px 16px;font-size:14px;font-weight:900;display:flex;justify-content:space-between;border-top:2px solid #a5d6a7;}
.qt-agro .qa-tb-total.blue{background:#dbeafe;color:#1e40af;border-top-color:#1565c0;}
.qt-agro .qa-tb-total.green{background:#dcfce7;color:#15803d;border-top-color:#2e7d32;}
.qt-agro .qa-banner{border-radius:10px;padding:14px 18px;margin-bottom:14px;font-size:13px;font-weight:700;}
.qt-agro .qa-banner.success{background:#e8f5e9;border:2px solid var(--qa-mg);color:var(--qa-dg);}
.qt-agro .qa-banner.error{background:#ffebee;border:2px solid var(--qa-red);color:#991b1b;}
.qt-agro .qa-diff-box .qa-card-head{display:none;}
.qt-agro .qa-diff-title{padding:14px 16px 0;font-size:13px;font-weight:800;color:var(--qa-red);}
.qt-agro .qa-diff-detail{padding:8px 16px 0;font-size:12px;color:#374151;line-height:1.8;}
.qt-agro .qa-diff-action{margin:10px 16px 16px;padding:10px 14px;background:#fef2f2;border-radius:8px;font-size:12px;color:#991b1b;}
.qt-agro .qa-report-links{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;padding:14px;}
.qt-agro .qa-report-link{padding:8px 6px;background:var(--qa-pg);border:1px solid #bbf7d0;border-radius:8px;
  font-size:11px;font-weight:600;color:var(--qa-dg);cursor:pointer;text-align:center;}
.qt-agro .qa-report-link:hover{background:#c8e6c9;}
.qt-agro .qa-health-widget{background:linear-gradient(135deg,#0f3d26,var(--qa-mg));border-radius:var(--qa-radius);padding:18px;color:#fff;}
.qt-agro .qa-health-title{font-size:13px;font-weight:800;margin-bottom:12px;}
.qt-agro .qa-health-cards{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;}
.qt-agro .qa-health-card{background:rgba(255,255,255,.15);border-radius:10px;padding:12px;text-align:center;}
.qt-agro .qa-health-card .qa-health-icon{font-size:20px;}
.qt-agro .qa-health-card .qa-health-val{font-size:13px;font-weight:800;margin:4px 0;}
.qt-agro .qa-health-card .qa-health-label{font-size:10px;opacity:.8;}
@media(max-width:900px){.qt-agro .qa-report-links,.qt-agro .qa-health-cards{grid-template-columns:repeat(2,1fr);}}
@media(max-width:640px){.qt-agro .qa-tb-grid{grid-template-columns:1fr;}}
</style>

