<script nonce="<?php echo $cspNonceAttr; ?>" id="quotations-module">
(function(){
  "use strict";
  var W = window;
  var API_BASE = (W.ERP_CONFIG && W.ERP_CONFIG.API_URL) ? W.ERP_CONFIG.API_URL.replace(/api\.php.*/, '') : '';
  var QT_URL   = API_BASE + 'quotations.php';

  function hdrs(extra){ return Object.assign({ 'Accept':'application/json' }, extra || {}); }

  /* These modules live in separate PHP files (quotations.php, ledger.php,
     fixed_assets.php) that are NOT part of api.php. If a file was never
     uploaded, the host answers 404 with an HTML error page — the old helper
     then threw a bare "Request failed" (or nothing at all, because several
     callers swallow the error), so the screen just stayed empty. Every
     failure now produces a plain-language message and a visible toast. */
  var MODULE_LABELS = {
    'quotations.php'   : 'Quotations',
    'ledger.php'       : 'Ledger',
    'fixed_assets.php' : 'Fixed Assets'
  };
  function moduleFile(url){
    var m = String(url).split('?')[0].split('/').pop();
    return MODULE_LABELS[m] ? m : '';
  }
  function moduleName(url){
    var f = moduleFile(url);
    return f ? MODULE_LABELS[f] : 'This module';
  }
  var _apiWarned = {};
  /* Errors raised by apiCall have already shown a toast; showErr() must not
     stack a second, less specific toast on top of it. */
  function showErr(e, prefix){
    var msg = (e && e.message) || 'Unknown error';
    try{ console.warn('[' + prefix + '] ' + msg); }catch(_){}
    if(e && e.notified) return;                 // apiCall already toasted this
    try{ if(typeof W.toast === 'function') W.toast(prefix + ': ' + msg, 'e'); }catch(_){}
  }
  function fail(url, msg){
    notify(url, msg);
    var err = new Error(msg);
    err.notified = true;
    return err;
  }
  function notify(url, msg){
    var f = moduleFile(url) || url;
    if(_apiWarned[f + msg]) return;      // don't spam the same toast on every poll
    _apiWarned[f + msg] = true;
    setTimeout(function(){ delete _apiWarned[f + msg]; }, 15000);
    try{ if(typeof W.toast === 'function') W.toast(msg, 'e'); }catch(e){}
    try{ console.warn('[' + (moduleFile(url) || 'api') + '] ' + msg); }catch(e){}
  }
  function friendlyMessage(url, status, out, rawText){
    var name = moduleName(url), file = moduleFile(url) || 'the server file';
    var serverMsg = (out && (out.error || out.message)) || '';
    if(status === 0)   return name + ' is unreachable — check your internet connection and try again.';
    if(status === 404) return name + ' is not installed on the server (' + file + ' is missing). Please ask your administrator to upload it.';
    if(status === 401 || status === 403) return 'Your session has expired — please sign in again to use ' + name + '.';
    if(status === 405) return name + ' rejected this request (' + file + ' may be an older version). Please ask your administrator to update it.';
    if(status === 413) return 'That ' + name + ' record is too large for the server to accept.';
    if(status === 429) return name + ' is busy right now — please wait a moment and try again.';
    if(status >= 500)  return name + ' hit a server error (' + status + ')' + (serverMsg ? ': ' + serverMsg : '') + '. Please try again, or contact your administrator.';
    if(status >= 400)  return serverMsg || (name + ' could not complete that request (error ' + status + ').');
    // 2xx but the body was not JSON — almost always an HTML error/redirect page.
    if(rawText === null) return serverMsg || (name + ' could not complete that request.');
    return name + ' returned an unexpected response — ' + file + ' may be missing or misconfigured on the server.';
  }
  async function apiCall(url, init){
    var res, raw;
    try{
      res = await fetch(url, init);
    }catch(netErr){
      throw fail(url, friendlyMessage(url, 0, null, ''));
    }
    raw = await res.text().catch(function(){ return ''; });
    var out = null;
    try{ out = raw ? JSON.parse(raw) : {}; }catch(e){ out = null; }
    if(!res.ok || out === null){
      throw fail(url, friendlyMessage(url, res.ok ? 200 : res.status, out, out === null ? raw : null));
    }
    if(out.success === false){
      throw fail(url, out.error || out.message || (moduleName(url) + ' could not complete that request.'));
    }
    return out;
  }
  async function apiGet(url){
    return apiCall(url, { method:'GET', credentials:'include', headers: hdrs() });
  }
  async function apiPost(url, body){
    return apiCall(url, { method:'POST', credentials:'include', headers: hdrs({'Content-Type':'application/json'}), body: JSON.stringify(body) });
  }

  var QT = { list: [] };  // module-local state only — never touches window.DB

  function money(n){ return '৳' + Number(n||0).toLocaleString('en-BD', {minimumFractionDigits:2, maximumFractionDigits:2}); }

  W.openQuotations = function(){
    document.getElementById('mQuotations').style.display = 'flex';
    populateQtProductList();
    QTBackToList();
    QTSearch();
  };
  W.closeQuotations = function(){
    document.getElementById('mQuotations').style.display = 'none';
  };

  function updateMetrics(list){
    var counts = { Draft:0, Sent:0, Accepted:0, Rejected:0, Expired:0 };
    list.forEach(function(r){ if(counts.hasOwnProperty(r.status)) counts[r.status]++; });
    var set = function(id, val){ var el = document.getElementById(id); if(el) el.textContent = val; };
    set('qt-m-total', list.length);
    set('qt-m-draft', counts.Draft);
    set('qt-m-sent', counts.Sent);
    set('qt-m-accepted', counts.Accepted);
    set('qt-m-rejected', counts.Rejected + counts.Expired);
    set('qt-count-badge', list.length);
    set('qt-table-info', list.length + (list.length === 1 ? ' quotation' : ' quotations'));
  }

  W.QTSearch = async function(){
    var q = (document.getElementById('qt-search')||{}).value || '';
    var statusFilter = (document.getElementById('qt-status-filter')||{}).value || '';
    try{
      var out = await apiGet(QT_URL + '?action=list&q=' + encodeURIComponent(q) + '&limit=200');
      QT.list = out.data || [];
      var filtered = statusFilter ? QT.list.filter(function(r){ return r.status === statusFilter; }) : QT.list;
      updateMetrics(QT.list);
      document.getElementById('qt-rows').innerHTML = filtered.map(function(r){
        return '<tr>' +
          '<td class="qa-td-left">'+esc(r.quoteNo)+'</td>' +
          '<td>'+esc(r.date)+'</td>' +
          '<td class="qa-td-left">'+esc(r.clientName||'')+'</td>' +
          '<td class="qa-td-left">'+esc(r.subject||'')+'</td>' +
          '<td class="qa-td-num"><span class="qa-rate-chip">'+money(r.total)+'</span></td>' +
          '<td><span class="qa-status qa-status-'+esc(r.status)+'">'+esc(r.status)+'</span></td>' +
          '<td><button class="qa-btn-sm info" data-x-click="QTEdit('+r.id+')">✏️ Edit</button> ' +
          '<button class="qa-btn-sm danger" data-x-click="QTDelete('+r.id+')">🗑</button></td></tr>';
      }).join('') || '<tr><td colspan="7">No quotations found.</td></tr>';
    }catch(e){
      showErr(e, 'Quotations could not be loaded');
      var rows = document.getElementById('qt-rows');
      if(rows) rows.innerHTML = '<tr><td colspan="7">' + esc((e && e.message) || 'Could not load quotations.') + '</td></tr>';
    }
  };

  function esc(str){ return String(str==null?'':str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }

  /* Cost = Total Weight × Rate. Oil Content follows the same convention as
     the reference rate sheet (Total Weight × Oil %, not divided by 100) so
     that a Sub Total row can recover the correct weighted-average Oil % by
     dividing the summed Oil Content column by the summed Weight column. */
  function itemCost(it){ return (parseFloat(it.weight)||0) * (parseFloat(it.rate)||0); }
  function itemOilContent(it){ return (parseFloat(it.weight)||0) * (parseFloat(it.oilPct)||0); }

  function populateQtProductList(){
    var dl = document.getElementById('qt-product-list');
    if(!dl) return;
    var products = (W.DB && DB.masterData && DB.masterData.products) || W.MASTER && MASTER.products || [];
    dl.innerHTML = products.map(function(p){ return '<option value="'+esc(p)+'"></option>'; }).join('');
  }

  function itemRowHTML(it){
    it = it || { product:'', bags:0, weight:0, rate:0, oilPct:0 };
    return '<tr>' +
      '<td class="qa-td-sl qa-td-num"></td>' +
      '<td><input class="qa-fc qt-it-product" type="text" list="qt-product-list" value="'+esc(it.product||'')+'" data-x-input="QTRecalc()"/></td>' +
      '<td><input class="qa-fc qt-it-bags" type="number" step="1" min="0" value="'+(it.bags||0)+'" style="width:80px;" data-x-input="QTRecalc()"/></td>' +
      '<td><input class="qa-fc qt-it-weight" type="number" step="0.01" min="0" value="'+(it.weight||0)+'" style="width:100px;" data-x-input="QTRecalc()"/></td>' +
      '<td><input class="qa-fc qt-it-rate" type="number" step="0.01" min="0" value="'+(it.rate||0)+'" style="width:90px;" data-x-input="QTRecalc()"/></td>' +
      '<td class="qa-td-num qt-it-cost">'+itemCost(it).toFixed(2)+'</td>' +
      '<td><input class="qa-fc qt-it-oilpct" type="number" step="0.01" min="0" value="'+(it.oilPct||0)+'" style="width:70px;" data-x-input="QTRecalc()"/></td>' +
      '<td class="qa-td-num qt-it-oilcontent">'+itemOilContent(it).toFixed(2)+'</td>' +
      '<td><button class="qa-btn-sm danger" data-x-click="QTRemoveItemRow(this)">🗑</button></td>' +
    '</tr>';
  }
  W.QTAddItemRow = function(row){
    document.getElementById('qt-items').insertAdjacentHTML('beforeend', itemRowHTML(row));
    populateQtProductList();
    QTRecalc();
  };
  W.QTRemoveItemRow = function(btn){
    var tr = btn.closest('tr');
    if(tr) tr.remove();
    QTRecalc();
  };

  /* Recomputes each line's Cost/Oil Content cells, renumbers the SL column,
     rolls the sheet up into a Sub Total row, then applies Discount/VAT on
     top of that to produce the Grand Total row — called on every keystroke
     in the items table and the discount/VAT fields. */
  W.QTRecalc = function(){
    var bagsSum = 0, weightSum = 0, costSum = 0, oilContentSum = 0, sl = 0;
    Array.prototype.forEach.call(document.querySelectorAll('#qt-items tr'), function(tr){
      sl++;
      var slCell = tr.querySelector('.qa-td-sl'); if(slCell) slCell.textContent = sl;
      var bags = parseFloat(tr.querySelector('.qt-it-bags').value) || 0;
      var weight = parseFloat(tr.querySelector('.qt-it-weight').value) || 0;
      var rate = parseFloat(tr.querySelector('.qt-it-rate').value) || 0;
      var oilPct = parseFloat(tr.querySelector('.qt-it-oilpct').value) || 0;
      var cost = weight * rate;
      var oilContent = weight * oilPct;
      var costCell = tr.querySelector('.qt-it-cost'); if(costCell) costCell.textContent = cost.toFixed(2);
      var oilCell = tr.querySelector('.qt-it-oilcontent'); if(oilCell) oilCell.textContent = oilContent.toFixed(2);
      bagsSum += bags; weightSum += weight; costSum += cost; oilContentSum += oilContent;
    });
    var avgRate = weightSum > 0 ? costSum / weightSum : 0;
    var avgOilContent = weightSum > 0 ? oilContentSum / weightSum : 0;
    var discount = parseFloat((document.getElementById('qt-discount')||{}).value) || 0;
    var vat = parseFloat((document.getElementById('qt-vat')||{}).value) || 0;
    var grandCost = Math.max(0, costSum - discount + vat);
    var set = function(id, val){ var el = document.getElementById(id); if(el) el.textContent = val; };
    set('qt-st-bags', bagsSum);
    set('qt-st-weight', weightSum.toFixed(2));
    set('qt-st-rate', avgRate.toFixed(3));
    set('qt-st-cost', costSum.toFixed(2));
    set('qt-st-oilcontent', avgOilContent.toFixed(2));
    set('qt-gt-bags', bagsSum);
    set('qt-gt-weight', weightSum.toFixed(2));
    set('qt-gt-rate', avgRate.toFixed(3));
    set('qt-gt-cost', grandCost.toFixed(2));
    set('qt-gt-oilcontent', avgOilContent.toFixed(2));
    set('qt-t-subtotal', costSum.toFixed(2));
    set('qt-t-grand', money(grandCost));
  };

  W.QTNew = async function(){
    document.getElementById('qt-id').value = '0';
    ['no','valid','cname','ccompany','cphone','cemail','caddr','subject','terms','note'].forEach(function(k){
      var el = document.getElementById('qt-' + k); if(el) el.value = '';
    });
    document.getElementById('qt-date').value = new Date().toISOString().slice(0,10);
    document.getElementById('qt-status').value = 'Draft';
    document.getElementById('qt-discount').value = '0';
    document.getElementById('qt-vat').value = '0';
    document.getElementById('qt-items').innerHTML = '';
    QTAddItemRow();
    try{ var out = await apiGet(QT_URL + '?action=next_no'); document.getElementById('qt-no').value = out.quoteNo; }
    catch(e){ try{ console.warn('[quotations.php] next number unavailable: ' + ((e && e.message) || e)); }catch(_){} }
    document.getElementById('qt-list-view').style.display = 'none';
    document.getElementById('qt-edit-view').style.display = 'block';
  };

  W.QTEdit = async function(id){
    try{
      var out = await apiGet(QT_URL + '?action=get&id=' + id);
      var q = out.data;
      document.getElementById('qt-id').value = q.id;
      document.getElementById('qt-no').value = q.quoteNo;
      document.getElementById('qt-date').value = q.date;
      document.getElementById('qt-valid').value = q.validUntil || '';
      document.getElementById('qt-status').value = q.status;
      document.getElementById('qt-cname').value = q.clientName || '';
      document.getElementById('qt-ccompany').value = q.clientCompany || '';
      document.getElementById('qt-cphone').value = q.clientPhone || '';
      document.getElementById('qt-cemail').value = q.clientEmail || '';
      document.getElementById('qt-caddr').value = q.clientAddress || '';
      document.getElementById('qt-subject').value = q.subject || '';
      document.getElementById('qt-discount').value = q.discount || 0;
      document.getElementById('qt-vat').value = q.vat || 0;
      document.getElementById('qt-terms').value = q.terms || '';
      document.getElementById('qt-note').value = q.note || '';
      document.getElementById('qt-items').innerHTML = '';
      (q.items || []).forEach(function(it){ QTAddItemRow(it); });
      if(!q.items || !q.items.length) QTAddItemRow();
      QTRecalc();
      document.getElementById('qt-list-view').style.display = 'none';
      document.getElementById('qt-edit-view').style.display = 'block';
    }catch(e){ showErr(e, 'Quotation could not be opened'); }
  };

  W.QTBackToList = function(){
    document.getElementById('qt-edit-view').style.display = 'none';
    document.getElementById('qt-list-view').style.display = 'block';
  };

  function collectQuotation(){
    var items = Array.prototype.map.call(document.querySelectorAll('#qt-items tr'), function(tr){
      var weight = parseFloat(tr.querySelector('.qt-it-weight').value) || 0;
      var rate = parseFloat(tr.querySelector('.qt-it-rate').value) || 0;
      var oilPct = parseFloat(tr.querySelector('.qt-it-oilpct').value) || 0;
      return {
        product: tr.querySelector('.qt-it-product').value,
        bags: parseFloat(tr.querySelector('.qt-it-bags').value) || 0,
        weight: weight,
        rate: rate,
        cost: weight * rate,
        oilPct: oilPct,
        oilContent: weight * oilPct
      };
    }).filter(function(it){ return it.product.trim() !== ''; });

    return {
      id: parseInt(document.getElementById('qt-id').value) || 0,
      quoteNo: document.getElementById('qt-no').value,
      date: document.getElementById('qt-date').value,
      validUntil: document.getElementById('qt-valid').value || null,
      status: document.getElementById('qt-status').value,
      clientName: document.getElementById('qt-cname').value,
      clientCompany: document.getElementById('qt-ccompany').value,
      clientPhone: document.getElementById('qt-cphone').value,
      clientEmail: document.getElementById('qt-cemail').value,
      clientAddress: document.getElementById('qt-caddr').value,
      subject: document.getElementById('qt-subject').value,
      discount: parseFloat(document.getElementById('qt-discount').value) || 0,
      vat: parseFloat(document.getElementById('qt-vat').value) || 0,
      terms: document.getElementById('qt-terms').value,
      note: document.getElementById('qt-note').value,
      items: items
    };
  }

  W.QTSave = async function(){
    var quotation = collectQuotation();
    if(!quotation.clientName.trim()){ if(typeof toast==='function') toast('Client name is required.','e'); return; }
    if(!quotation.items.length){ if(typeof toast==='function') toast('Add at least one line item.','e'); return; }
    var _badItem = quotation.items.find(function(it){ return !(it.weight>0) || !(it.rate>0); });
    if(_badItem){ if(typeof toast==='function') toast('⚠️ Every line item needs a Total Weight and Rate greater than 0.','e'); return; }
    try{
      await apiPost(QT_URL + '?action=save', { quotation: quotation });
      if(typeof toast === 'function') toast('Quotation saved.', 's');
      QTBackToList();
      QTSearch();
    }catch(e){ showErr(e, 'Quotation could not be saved'); }
  };

  W.QTDelete = async function(id){
    if(!await __confirm('Delete this quotation?')) return;
    try{
      await apiPost(QT_URL + '?action=delete', { id: id });
      QTSearch();
    }catch(e){ showErr(e, 'Quotation could not be deleted'); }
  };

  /* Builds a clean, letterhead-style printable version of the quotation
     currently open in the edit form and sends it to the browser's print
     dialog (Save as PDF works the same way) in a separate window so the
     ERP chrome itself never ends up on the page. */
  W.QTPrint = function(){
    var q = collectQuotation();
    var bagsSum = q.items.reduce(function(s, it){ return s + it.bags; }, 0);
    var weightSum = q.items.reduce(function(s, it){ return s + it.weight; }, 0);
    var subtotal = q.items.reduce(function(s, it){ return s + it.cost; }, 0);
    var oilContentSum = q.items.reduce(function(s, it){ return s + it.oilContent; }, 0);
    var avgRate = weightSum > 0 ? subtotal / weightSum : 0;
    var avgOilContent = weightSum > 0 ? oilContentSum / weightSum : 0;
    var grand = Math.max(0, subtotal - q.discount + q.vat);
    var rowsHtml = q.items.map(function(it, i){
      return '<tr><td>'+(i+1)+'</td><td style="text-align:left;">'+esc(it.product)+'</td>' +
        '<td>'+Number(it.bags).toLocaleString('en-BD')+'</td><td>'+Number(it.weight).toLocaleString('en-BD')+'</td>' +
        '<td>'+Number(it.rate).toFixed(2)+'</td><td>'+it.cost.toFixed(2)+'</td>' +
        '<td>'+Number(it.oilPct).toFixed(2)+'</td><td>'+it.oilContent.toFixed(2)+'</td></tr>';
    }).join('');
    var footHtml =
      '<tr style="font-weight:700;background:#f0fdf4;"><td colspan="2" style="text-align:left;">Sub Total</td>' +
        '<td>'+Number(bagsSum).toLocaleString('en-BD')+'</td><td>'+Number(weightSum).toLocaleString('en-BD')+'</td>' +
        '<td>'+avgRate.toFixed(3)+'</td><td>'+subtotal.toFixed(2)+'</td><td></td><td>'+avgOilContent.toFixed(2)+'</td></tr>' +
      '<tr style="font-weight:800;background:#dcfce7;"><td colspan="2" style="text-align:left;">Grand Total</td>' +
        '<td>'+Number(bagsSum).toLocaleString('en-BD')+'</td><td>'+Number(weightSum).toLocaleString('en-BD')+'</td>' +
        '<td>'+avgRate.toFixed(3)+'</td><td>'+grand.toFixed(2)+'</td><td></td><td>'+avgOilContent.toFixed(2)+'</td></tr>';
    var html = '<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Quotation '+esc(q.quoteNo)+'</title>' +
      '<style>' +
      'body{font-family:Arial,sans-serif;color:#1a1a1a;padding:30px;}' +
      '.qp-head{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:3px solid #1b5e20;padding-bottom:14px;margin-bottom:18px;}' +
      '.qp-company{font-size:20px;font-weight:800;color:#1b5e20;}' +
      '.qp-company-sub{font-size:11px;color:#666;margin-top:2px;}' +
      '.qp-title{font-size:22px;font-weight:800;color:#1b5e20;text-align:right;}' +
      '.qp-meta{font-size:12px;color:#444;text-align:right;margin-top:4px;}' +
      '.qp-section{margin-bottom:14px;}' +
      '.qp-label{font-size:10px;text-transform:uppercase;letter-spacing:.5px;color:#888;font-weight:700;}' +
      'table{width:100%;border-collapse:collapse;margin-top:8px;font-size:12.5px;}' +
      'th{background:#2e7d32;color:#fff;padding:8px;text-align:center;}' +
      'td{padding:7px 8px;border-bottom:1px solid #e0e0e0;text-align:center;}' +
      '.qp-totals{width:280px;margin-left:auto;margin-top:10px;font-size:13px;}' +
      '.qp-totals div{display:flex;justify-content:space-between;padding:3px 0;}' +
      '.qp-totals .grand{border-top:2px solid #1b5e20;margin-top:6px;padding-top:8px;font-weight:800;font-size:15px;color:#1b5e20;}' +
      '.qp-footer{margin-top:26px;font-size:11px;color:#666;}' +
      '@media print{@page{size:A4;margin:14mm;}}' +
      '</style></head><body>' +
      '<div class="qp-head">' +
        '<div><div class="qp-company">Ayan Agro International Ltd</div><div class="qp-company-sub">Barishal, Bangladesh</div></div>' +
        '<div><div class="qp-title">QUOTATION</div><div class="qp-meta">No: '+esc(q.quoteNo)+'<br>Date: '+esc(q.date)+(q.validUntil?'<br>Valid Until: '+esc(q.validUntil):'')+'</div></div>' +
      '</div>' +
      '<div class="qp-section"><div class="qp-label">To</div>' +
        '<div style="font-weight:700;">'+esc(q.clientName)+(q.clientCompany?' — '+esc(q.clientCompany):'')+'</div>' +
        (q.clientAddress?'<div>'+esc(q.clientAddress)+'</div>':'') +
        (q.clientPhone?'<div>Phone: '+esc(q.clientPhone)+'</div>':'') +
        (q.clientEmail?'<div>Email: '+esc(q.clientEmail)+'</div>':'') +
      '</div>' +
      (q.subject?'<div class="qp-section"><div class="qp-label">Subject</div><div>'+esc(q.subject)+'</div></div>':'') +
      '<table><thead><tr><th>SL</th><th>Product Name</th><th>No. of Bags</th><th>Total Weight (KG)</th><th>Rate (৳/KG)</th><th>Total Cost (৳)</th><th>Oil %</th><th>Oil Content (KG)</th></tr></thead>' +
      '<tbody>'+(rowsHtml || '<tr><td colspan="8">No items</td></tr>')+footHtml+'</tbody></table>' +
      '<div class="qp-totals">' +
        '<div><span>Subtotal</span><span>'+subtotal.toFixed(2)+'</span></div>' +
        '<div><span>Discount</span><span>-'+Number(q.discount).toFixed(2)+'</span></div>' +
        '<div><span>VAT</span><span>+'+Number(q.vat).toFixed(2)+'</span></div>' +
        '<div class="grand"><span>Grand Total</span><span>৳'+grand.toFixed(2)+'</span></div>' +
      '</div>' +
      (q.terms?'<div class="qp-section"><div class="qp-label">Terms</div><div>'+esc(q.terms)+'</div></div>':'') +
      (q.note?'<div class="qp-section"><div class="qp-label">Note</div><div>'+esc(q.note)+'</div></div>':'') +
      '<div class="qp-footer">Status: '+esc(q.status)+' · Generated from AyanERP</div>' +
      '</body></html>';
    var win = window.open('', '_blank');
    if(!win){ if(typeof toast==='function') toast('Please allow pop-ups to print the quotation.', 'e'); return; }
    win.document.open(); win.document.write(html); win.document.close();
    // `onload` on a document.write()-populated window is unreliable across
    // browsers (some fire it before this handler attaches), so fall back to
    // a short timeout as well — printedAlready guards against firing twice.
    var printedAlready = false;
    var doPrint = function(){ if(printedAlready) return; printedAlready = true; try{ win.focus(); win.print(); }catch(e){} };
    win.onload = doPrint;
    setTimeout(doPrint, 300);
  };
})();
</script>

<script nonce="<?php echo $cspNonceAttr; ?>" id="ledger-and-assets-bridge">
(function(){
  "use strict";
  var W = window;
  var API_BASE   = (W.ERP_CONFIG && W.ERP_CONFIG.API_URL) ? W.ERP_CONFIG.API_URL.replace(/api\.php.*/, '') : '';
  var LEDGER_URL = API_BASE + 'ledger.php';
  var ASSET_URL  = API_BASE + 'fixed_assets.php';

  function hdrs(extra){ return Object.assign({ 'Accept':'application/json' }, extra || {}); }

  /* These modules live in separate PHP files (quotations.php, ledger.php,
     fixed_assets.php) that are NOT part of api.php. If a file was never
     uploaded, the host answers 404 with an HTML error page — the old helper
     then threw a bare "Request failed" (or nothing at all, because several
     callers swallow the error), so the screen just stayed empty. Every
     failure now produces a plain-language message and a visible toast. */
  var MODULE_LABELS = {
    'quotations.php'   : 'Quotations',
    'ledger.php'       : 'Ledger',
    'fixed_assets.php' : 'Fixed Assets'
  };
  function moduleFile(url){
    var m = String(url).split('?')[0].split('/').pop();
    return MODULE_LABELS[m] ? m : '';
  }
  function moduleName(url){
    var f = moduleFile(url);
    return f ? MODULE_LABELS[f] : 'This module';
  }
  var _apiWarned = {};
  /* Errors raised by apiCall have already shown a toast; showErr() must not
     stack a second, less specific toast on top of it. */
  function showErr(e, prefix){
    var msg = (e && e.message) || 'Unknown error';
    try{ console.warn('[' + prefix + '] ' + msg); }catch(_){}
    if(e && e.notified) return;                 // apiCall already toasted this
    try{ if(typeof W.toast === 'function') W.toast(prefix + ': ' + msg, 'e'); }catch(_){}
  }
  function fail(url, msg){
    notify(url, msg);
    var err = new Error(msg);
    err.notified = true;
    return err;
  }
  function notify(url, msg){
    var f = moduleFile(url) || url;
    if(_apiWarned[f + msg]) return;      // don't spam the same toast on every poll
    _apiWarned[f + msg] = true;
    setTimeout(function(){ delete _apiWarned[f + msg]; }, 15000);
    try{ if(typeof W.toast === 'function') W.toast(msg, 'e'); }catch(e){}
    try{ console.warn('[' + (moduleFile(url) || 'api') + '] ' + msg); }catch(e){}
  }
  function friendlyMessage(url, status, out, rawText){
    var name = moduleName(url), file = moduleFile(url) || 'the server file';
    var serverMsg = (out && (out.error || out.message)) || '';
    if(status === 0)   return name + ' is unreachable — check your internet connection and try again.';
    if(status === 404) return name + ' is not installed on the server (' + file + ' is missing). Please ask your administrator to upload it.';
    if(status === 401 || status === 403) return 'Your session has expired — please sign in again to use ' + name + '.';
    if(status === 405) return name + ' rejected this request (' + file + ' may be an older version). Please ask your administrator to update it.';
    if(status === 413) return 'That ' + name + ' record is too large for the server to accept.';
    if(status === 429) return name + ' is busy right now — please wait a moment and try again.';
    if(status >= 500)  return name + ' hit a server error (' + status + ')' + (serverMsg ? ': ' + serverMsg : '') + '. Please try again, or contact your administrator.';
    if(status >= 400)  return serverMsg || (name + ' could not complete that request (error ' + status + ').');
    // 2xx but the body was not JSON — almost always an HTML error/redirect page.
    if(rawText === null) return serverMsg || (name + ' could not complete that request.');
    return name + ' returned an unexpected response — ' + file + ' may be missing or misconfigured on the server.';
  }
  async function apiCall(url, init){
    var res, raw;
    try{
      res = await fetch(url, init);
    }catch(netErr){
      throw fail(url, friendlyMessage(url, 0, null, ''));
    }
    raw = await res.text().catch(function(){ return ''; });
    var out = null;
    try{ out = raw ? JSON.parse(raw) : {}; }catch(e){ out = null; }
    if(!res.ok || out === null){
      throw fail(url, friendlyMessage(url, res.ok ? 200 : res.status, out, out === null ? raw : null));
    }
    if(out.success === false){
      throw fail(url, out.error || out.message || (moduleName(url) + ' could not complete that request.'));
    }
    return out;
  }
  async function apiGet(url){
    return apiCall(url, { method:'GET', credentials:'include', headers: hdrs() });
  }
  async function apiPost(url, body){
    return apiCall(url, { method:'POST', credentials:'include', headers: hdrs({'Content-Type':'application/json'}), body: JSON.stringify(body) });
  }

  /* ───────── FIXED ASSETS: CRUD wired to existing UI (non-destructive wraps) ───────── */
  function toFrontendAsset(r){
    return {
      id: r.id, name: r.name, cat: r.category || '',
      val: Number(r.cost) || 0, dep: Number(r.depRate) || 0,     // cost/rate map onto existing a.val/a.dep
      date: r.purchaseDate || '', location: r.location || '',
      _code: r.code || '', _method: r.method || 'SL',
      _salvage: Number(r.salvage) || 0, _lifeYears: Number(r.lifeYears) || 0,
      _status: r.status || 'Active'
    };
  }
  function toServerAsset(a){
    return {
      id: a.id || 0, code: a._code || '', name: a.name, category: a.cat || '',
      location: a.location || '', purchaseDate: a.date || null,
      cost: Number(a.val) || 0, salvage: a._salvage || 0, depRate: Number(a.dep) || 0,
      lifeYears: a._lifeYears || 0, method: a._method || 'SL', accumDep: 0,
      status: a._status || 'Active'
    };
  }

  W.loadAssetsFromServer = async function(){
    try{
      /* DATA LOSS FIX: with no server deployed, the built-in offline backend
         answers fixed_assets.php with {success:true, data:[], mode:'local'} —
         a perfectly valid empty list. This took that at face value and did
         DB.assets = [], wiping every fixed asset at every page load and then
         saving the empty list back over the real one. That is how the
         \u09f322,27,936 of machinery and vehicles in this file disappeared
         from the balance sheet. The server may only replace the local list
         when there really is a server, and never with nothing. */
      var offline = (W.ERP_SERVER_MODE === false)
                 || (W.ERP_CONFIG && W.ERP_CONFIG.USE_SERVER === false);
      if(offline) return false;
      var out = await apiGet(ASSET_URL + '?action=list');
      if(!Array.isArray(out.data)) return false;
      if(out.mode === 'local') return false;
      if(!out.data.length && (W.DB.assets||[]).length) return false;
      W.DB.assets = out.data.map(toFrontendAsset);
      if(typeof renderAsset === 'function') renderAsset(W.DB.assets);
      return true;
    }catch(e){ try{ console.warn('[fixed_assets.php] load failed: ' + ((e && e.message) || e)); }catch(_){} return false; }
  };
  W.saveAssetToServer = async function(assetData){
    try{
      var out = await apiPost(ASSET_URL + '?action=save', { asset: toServerAsset(assetData) });
      if(out.data){ assetData.id = out.data.id; assetData._code = out.data.code; }
    }catch(e){
      try{ console.warn('[fixed_assets.php] save failed: ' + ((e && e.message) || e)); }catch(_){}
      if(!e || !e.notified){ try{ if(typeof W.toast === 'function') W.toast('Asset saved locally — server sync failed: ' + ((e && e.message) || 'unknown error'), 'w'); }catch(_){} }
    }
  };
  W.deleteAssetFromServer = async function(id){
    try{ await apiPost(ASSET_URL + '?action=delete', { id: id }); }
    catch(e){ showErr(e, 'Asset was removed here but not on the server'); }
  };

  var _origSaveAsset = W.saveAsset;
  if(typeof _origSaveAsset === 'function'){
    W.saveAsset = function(){
      var editId = parseInt((document.getElementById('a-edit-id')||{}).value) || 0;
      var result = _origSaveAsset.apply(this, arguments);
      var a = editId
        ? (W.DB.assets||[]).find(function(x){ return x.id===editId; })
        : (W.DB.assets||[])[(W.DB.assets||[]).length - 1];
      if(a) W.saveAssetToServer(a);
      return result;
    };
  }
  var _origDelAsset = W.delAsset;
  if(typeof _origDelAsset === 'function'){
    W.delAsset = async function(id){
      var before = (W.DB.assets||[]).some(function(x){ return x.id===id; });
      await _origDelAsset.apply(this, arguments);
      var after = (W.DB.assets||[]).some(function(x){ return x.id===id; });
      if(before && !after) W.deleteAssetFromServer(id);
    };
  }
  var _origLoadData = W.loadDataFromServer;
  if(typeof _origLoadData === 'function'){
    W.loadDataFromServer = async function(){
      var r = await _origLoadData.apply(this, arguments);
      if(r){ try{ await W.loadAssetsFromServer(); }catch(e){ try{ console.warn('[fixed_assets.php] refresh failed: ' + ((e && e.message) || e)); }catch(_){} } }
      return r;
    };
  }

  /* ───────── GENERAL LEDGER: fetch layer + standalone UI ───────── */
  W.Ledger = {
    list:      function(f){ return apiGet(LEDGER_URL + '?action=list&' + new URLSearchParams(f||{}).toString()); },
    statement: function(f){ return apiGet(LEDGER_URL + '?action=statement&' + new URLSearchParams(f||{}).toString()); },
    summary:   function(f){ return apiGet(LEDGER_URL + '?action=summary&' + new URLSearchParams(f||{}).toString()); },
    trial:     function(asOf){ return apiGet(LEDGER_URL + '?action=trial' + (asOf ? '&as_of=' + asOf : '')); },
    parties:   function(){ return apiGet(LEDGER_URL + '?action=parties'); },
    save:      function(entry){ return apiPost(LEDGER_URL + '?action=save', { entry: entry }); },
    remove:    function(id){ return apiPost(LEDGER_URL + '?action=delete', { id: id }); }
  };

  /* FIX (2026-08-27, workflow audit): this whole General Ledger UI sent and
     read field names (party/account/narration/voucherNo, plus a Voucher
     Type and Category field with no backing column at all) that never
     matched what ledger.php's save/list actions actually read and return
     (partyName/accountType/description/refNo — see erp_ledger's real
     columns). The practical effect: GLSaveEntry() never sent 'partyName',
     so ledger.php's "Party name is required" check fired on every single
     save, no matter what the user typed — this feature could not save a
     single entry. And even if it had, GLFilter()'s row renderer read
     r.party/r.account/r.narration/r.voucherNo, none of which exist on the
     response (it returns r.partyName/r.accountType/r.description/r.refNo),
     so the table would have shown blank Party/Account/Narration columns
     for every row. Voucher Type and Category are dropped below since
     erp_ledger has no columns to hold them (they were never saved either);
     "Voucher No" is renamed to "Reference No" to match the reference_no
     column it actually maps to. Required-field marker moved from Account
     to Party to match what the server actually requires. */
  function glOverlayHTML(){
    return '<div class="overlay" id="mGenLedger" style="display:none;"><div class="modal modal-lg">' +
      '<div class="modal-title">📒 General Ledger <span class="modal-close" data-x-click="closeGeneralLedger()">✕</span></div>' +
