          '<div class="fg"><label class="lbl">Credit</label><input class="fc" id="gl-e-credit" type="number" min="0" step="0.01"/></div>' +
          '<div class="fg full"><label class="lbl">Narration</label><input class="fc" id="gl-e-narration" type="text"/></div>' +
        '</div>' +
        '<div class="form-actions">' +
          '<button class="btn btn-ghost" data-x-click="document.getElementById(\'gl-form\').style.display=\'none\'">Cancel</button>' +
          '<button class="btn btn-success" data-x-click="GLSaveEntry()">💾 Save Entry</button>' +
        '</div>' +
      '</div>' +
      '<div style="overflow-x:auto;max-height:50vh;overflow-y:auto;"><table class="tbl">' +
        '<thead><tr><th>Date</th><th>Ref No</th><th>Party</th><th>Account</th><th>Narration</th><th>Debit</th><th>Credit</th><th></th></tr></thead>' +
