  function glEnsureDOM(){
    if(document.getElementById('mGenLedger')) return;
    var wrap = document.createElement('div');
    wrap.innerHTML = glOverlayHTML();
    document.body.appendChild(wrap.firstChild);
  }
  W.openGeneralLedger = function(){ glEnsureDOM(); document.getElementById('mGenLedger').style.display = 'flex'; GLFilter(); };
  W.closeGeneralLedger = function(){ var el = document.getElementById('mGenLedger'); if(el) el.style.display = 'none'; };

  W.GLFilter = async function(){
    var f = {};
    ['party','account','from','to'].forEach(function(k){
      var el = document.getElementById('gl-f-' + k); if(el && el.value) f[k] = el.value;
    });
    try{
      var out = await W.Ledger.list(f);
      document.getElementById('gl-rows').innerHTML = (out.data||[]).map(function(r){
        return '<tr><td>'+r.date+'</td><td>'+(r.refNo||'')+'</td><td>'+(r.partyName||'')+'</td><td>'+(r.accountType||'')+'</td>' +
          '<td>'+(r.description||'')+'</td><td class="td-num">'+Number(r.debit||0).toFixed(2)+'</td><td class="td-num">'+Number(r.credit||0).toFixed(2)+'</td>' +
          '<td><button class="btn btn-danger btn-xs" data-x-click="GLDelete('+r.id+')">🗑</button></td></tr>';
      }).join('') || '<tr><td colspan="8">No entries.</td></tr>';
      var totalDebit = (out.data||[]).reduce(function(s,r){ return s + (Number(r.debit)||0); }, 0);
      var totalCredit = (out.data||[]).reduce(function(s,r){ return s + (Number(r.credit)||0); }, 0);
      document.getElementById('gl-totals').textContent =
        'Total Debit: ' + totalDebit.toFixed(2) + '   |   Total Credit: ' + totalCredit.toFixed(2);
    }catch(e){
      showErr(e, 'Ledger could not be loaded');
      var glRows = document.getElementById('gl-rows');
      if(glRows) glRows.innerHTML = '<tr><td colspan="8">' + ((e && e.message) || 'Could not load ledger entries.') + '</td></tr>';
      var glT = document.getElementById('gl-totals');
      if(glT) glT.textContent = '';
