  };
  W.GLNewEntry = function(){
    document.getElementById('gl-e-id').value = '0';
    ['date','refNo','party','account','narration'].forEach(function(k){
      var el = document.getElementById('gl-e-' + k); if(el) el.value = '';
    });
    document.getElementById('gl-e-debit').value = '';
    document.getElementById('gl-e-credit').value = '';
    document.getElementById('gl-form').style.display = 'block';
