  W.GLSaveEntry = async function(){
    var entry = {
      id: parseInt(document.getElementById('gl-e-id').value) || 0,
      date: document.getElementById('gl-e-date').value,
      refNo: document.getElementById('gl-e-refNo').value,
      partyName: document.getElementById('gl-e-party').value,
      accountType: document.getElementById('gl-e-account').value,
      description: document.getElementById('gl-e-narration').value,
      debit: parseFloat(document.getElementById('gl-e-debit').value) || 0,
      credit: parseFloat(document.getElementById('gl-e-credit').value) || 0
    };
    if(!entry.date || !entry.partyName){ if(typeof toast==='function') toast('Date and Party are required.','e'); return; }
    try{
      await W.Ledger.save(entry);
      document.getElementById('gl-form').style.display = 'none';
      if(typeof toast === 'function') toast('Ledger entry saved.', 's');
      GLFilter();
    }catch(e){ showErr(e, 'Ledger entry could not be saved'); }
  };
  W.GLDelete = async function(id){
    if(!await __confirm('Delete this ledger entry?')) return;
    try{ await W.Ledger.remove(id); GLFilter(); }
    catch(e){ showErr(e, 'Ledger entry could not be deleted'); }
  };
})();
</script>
<!-- ══════════════════════════════════════════════════════════════════════
     ADD-ON PACK v3 — (1) sharded IndexedDB persistence  (2) fast tables
     100% additive. No existing function, table, math or module is altered.
     ═════════════════════════════════════════════════════════════════════ -->
<script nonce="<?php echo $cspNonceAttr; ?>">
(function(){
  'use strict';
  var W = window, LS_KEY = 'rbo_v4', DBN = 'erp_shards', VER = 1;
  if (W.__erpShardPack) return; W.__erpShardPack = true;

  /* ── 1. Sharded, incremental persistence ──────────────────────────────
     The existing pipeline stringifies the WHOLE database on every save.
     Here we keep that pipeline intact but make it run rarely: each save
     writes only the top-level collections that actually changed into
     IndexedDB (structured clone, async, off the critical path), and the
     full localStorage snapshot is refreshed at most every 15s — plus
     always on flush / tab-hide / unload, which the app already triggers. */

  var idb = null, idbFail = false;
  function open(){
    return new Promise(function(res){
      if (idb) return res(idb);
      if (idbFail || !W.indexedDB) return res(null);
      try{
        var rq = indexedDB.open(DBN, VER);
        rq.onupgradeneeded = function(){
          var d = rq.result;
          if(!d.objectStoreNames.contains('shards')) d.createObjectStore('shards');
          if(!d.objectStoreNames.contains('meta'))   d.createObjectStore('meta');
        };
        rq.onsuccess = function(){ idb = rq.result; res(idb); };
        rq.onerror   = function(){ idbFail = true; res(null); };
      }catch(e){ idbFail = true; res(null); }
    });
  }

  /* Cheap change fingerprint — never touches or reshapes the data. */
  function fp(v){
    try{
      if (Array.isArray(v)){
        var n = v.length, last = n ? v[n-1] : null, s = 'a' + n;
        if (last && typeof last === 'object'){
          s += ':' + (last.id || last.code || last.no || '') + ':' +
               (last.updatedAt || last.date || last.ts || '');
        }
        // sample a few interior rows so in-place edits are caught too
        for (var i = 0; i < n; i += Math.max(1, Math.floor(n/12))){
          var r = v[i];
          if (r && typeof r === 'object') s += '|' + (r.updatedAt || r.total || r.amount || r.qty || '');
        }
        return s;
      }
      if (v && typeof v === 'object') return 'o' + Object.keys(v).length + ':' + JSON.stringify(v).length;
      return 's' + String(v);
    }catch(e){ return 'x' + Math.random(); }
  }

  var lastFp = {};
  function shardSave(){
    /* NOTE ON DURABILITY: 'users' is intentionally excluded below, so it only
       gets persisted via the full localStorage snapshot (origLocalSave, at
       most every SNAP_MS=15s, plus on every flush point — pagehide,
       beforeunload, hidden tab). Every OTHER collection is additionally
       mirrored into IndexedDB on nearly every change via this shard path, so
       it survives a hard crash / power loss up to the moment of the crash.
       'users' does not get that extra safety net — a change to users (new
       user, password reset, role/permission change) made in the up-to-15s
       window before an abrupt crash (not a clean tab close, which is still
       covered by the flush listeners) will not be recoverable from
       IndexedDB. This is a deliberate trade-off, not an oversight: it keeps
       password hashes and permissions out of the extra, longer-lived,
       harder-to-purge IndexedDB copy. Do not "fix" this by removing the
       exclusion without also reviewing whether IndexedDB is an acceptable
       place for credentials to live in this deployment. */
    var src = W.DB; if (!src || typeof src !== 'object') return;
    var dirty = [], k;
    for (k in src){
      if (!Object.prototype.hasOwnProperty.call(src, k)) continue;
      if (k === 'users') continue;                 // credentials never leave the hardened path
      var f = fp(src[k]);
      if (lastFp[k] !== f){ lastFp[k] = f; dirty.push(k); }
    }
    if (!dirty.length) return;
    open().then(function(d){
      if (!d) return;
      try{
        var tx = d.transaction(['shards','meta'], 'readwrite'),
            st = tx.objectStore('shards');
        dirty.forEach(function(key){
          try{ st.put(src[key], key); }catch(e){}   // structured clone, no JSON pass
        });
        tx.objectStore('meta').put({ at: Date.now(), keys: Object.keys(src) }, 'stamp');
      }catch(e){}
    });
  }

  /* Recovery helpers (manual, never automatic — data is only ever added). */
  W._erpShardRead = function(){
    return open().then(function(d){
      if (!d) return null;
      return new Promise(function(res){
        var out = {}, tx = d.transaction(['shards','meta'], 'readonly'),
            st = tx.objectStore('shards'), rq = st.openCursor();
        rq.onsuccess = function(){
          var c = rq.result;
          if (c){ out[c.key] = c.value; c.continue(); }
        };
        var mrq = tx.objectStore('meta').get('stamp');
        tx.oncomplete = function(){ res({ data: out, meta: mrq.result || null }); };
        tx.onerror = function(){ res(null); };
      });
    });
  };
  W._erpShardRestore = function(){
    return W._erpShardRead().then(function(r){
      if (!r || !r.data) { alert('No IndexedDB shards found.'); return false; }
      var n = 0, k;
      for (k in r.data){ if (k !== 'users'){ W.DB[k] = r.data[k]; n++; } }   // 'users' was never written here — see shardSave()
      try{ W._erpFlushSnapshot(true); }catch(e){}
      try{ W.location.reload(); }catch(e){}
      return n;
    });
  };

  /* Throttle the heavy full snapshot; keep it exact on every flush point. */
  var origLocalSave = W._erpLocalSave, lastSnapshot = 0, SNAP_MS = 15000, pending = false;

  W._erpFlushSnapshot = function(force){
    if (typeof origLocalSave !== 'function') return false;
    lastSnapshot = Date.now(); pending = false;
    try{ return origLocalSave.apply(W, []); }catch(e){ return false; }
  };

  if (typeof origLocalSave === 'function'){
    W._erpLocalSave = function(){
      shardSave();                                   // always: cheap + async
      var now = Date.now();
      if (now - lastSnapshot >= SNAP_MS || !lastSnapshot){
        return W._erpFlushSnapshot(true);            // periodic exact snapshot
      }
      pending = true;
      if (typeof W._markSaved === 'function'){ try{ W._markSaved(); }catch(e){} }
      return true;                                   // data is safe in IndexedDB
    };
  }
  function flushNow(){ if (pending) W._erpFlushSnapshot(true); }
  W.addEventListener('pagehide', flushNow);
  W.addEventListener('beforeunload', flushNow);
  document.addEventListener('visibilitychange', function(){
    if (document.visibilityState === 'hidden') flushNow();
  });
  setInterval(flushNow, 20000);

  /* ── 2. Fast large tables ─────────────────────────────────────────────
     Rows stay in the DOM (so every existing selector, filter, edit and
     export keeps working byte-for-byte); the browser simply skips
     rendering the ones that are off-screen. */
  try{
    var st = document.createElement('style');
    st.textContent =
      '.erp-fastrows > tr{content-visibility:auto;contain-intrinsic-size:auto 38px;}' +
      '@media print{.erp-fastrows > tr{content-visibility:visible;}}';
    document.head.appendChild(st);
  }catch(e){}

  var THRESHOLD = 120, scan = null;
  function tuneTables(){
    var bodies = document.getElementsByTagName('tbody');
    for (var i = 0; i < bodies.length; i++){
      var b = bodies[i], big = b.children.length >= THRESHOLD,
          on = b.classList.contains('erp-fastrows');
      if (big && !on) b.classList.add('erp-fastrows');
      else if (!big && on) b.classList.remove('erp-fastrows');
    }
  }
  function schedule(){
    if (scan) return;
    scan = setTimeout(function(){ scan = null; try{ tuneTables(); }catch(e){} }, 250);
  }
  try{
    new MutationObserver(schedule).observe(document.body, { childList:true, subtree:true });
  }catch(e){}
  schedule();

  console.info('[ERP Add-on v3] sharded IndexedDB persistence + fast table rendering active');
})();
</script>

<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-fix-save-hang">
/* CONSOLIDATED: this used to do a second, PLAIN `window.saveDB = ...`
   reassignment here. Since ayan-perf-savedb-coalesce (above) had already
   locked window.saveDB behind its own Object.defineProperty getter/setter,
   this plain assignment was routed into THAT layer's setter — which in turn
   pointed back into erp-durable-save-v4's wrapper. But this script's own
   internal fallback ("realSave = W.saveDB") had captured the coalesce
   layer's getter *before* overwriting it, so once its idle-scheduled timer
   fired it called back into the coalesce layer, which rescheduled a call
   back into this layer, forever — an infinite microtask/idle-callback loop
   that never reached erp-durable-save-v4's actual write. In practice this
   meant saveDB() calls during normal interactive use never persisted
   anything; the app only survived because erp-durable-save-v4 also
   registers its own direct beforeunload/pagehide/visibilitychange
   listeners that call the real write function without going through
   window.saveDB at all.

   erp-durable-save-v4 already coalesces bursts within its own 400ms window,
   runs the verified write, and flushes on tab hide/unload, so this whole
   layer (plus its own full-DB JSON.stringify() "cheap" length check, which
   defeated its own purpose by re-serializing the entire DB on every call)
   has been removed. erp-durable-save-v4 is the single remaining owner of
   window.saveDB / window.saveDBNow. */
</script>
<!-- ==========================================================================
     AYAN AGRO ERP :: cloud accounts + per-record database sync
     --------------------------------------------------------------------
     Replaces browser-only storage (localStorage 'rbo_v4' + IndexedDB mirrors)
     and the local username/password list with:
       * real accounts, verified by the server, and
       * a cloud database that stores every transaction/customer/bank/etc as
         its own row, so two people editing different records at the same time
         no longer overwrite each other.
     Browser storage is kept ONLY as an offline cache; the cloud is the
     source of truth. This block loads last on purpose so its save/load
     implementation is the one that wins over the earlier patch layers.
     ========================================================================== -->
<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-supabase-loader">
/* PATCH: the cloud client used to die permanently when the single CDN copy of
   supabase-js was blocked or slow, showing "Could not reach the cloud service".
   Try several mirrors, and expose a retry hook the banner can call. */
(function(){
  var SRC = [
    'https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.58.0/dist/umd/supabase.js',
    'https://unpkg.com/@supabase/supabase-js@2.58.0/dist/umd/supabase.js',
    'https://cdn.skypack.dev/pin/@supabase/supabase-js@v2.58.0/mode=raw/dist/umd/supabase.js'
  ];
  function has(){ return !!(window.supabase && window.supabase.createClient); }
  function load(url){
    return new Promise(function(res){
      var s = document.createElement('script');
      s.src = url; s.async = true;
      s.onload = function(){ res(has()); };
      s.onerror = function(){ res(false); };
      document.head.appendChild(s);
    });
  }
  window.__ensureSupabaseLib = async function(){
    if (has()) return true;
    for (var i = 0; i < SRC.length; i++){
      try { if (await load(SRC[i])) return true; } catch(e){}
    }
    return has();
  };
})();
</script>
