    if (kind === 'e') console.error('[cloud]', msg); else console.log('[cloud]', msg);
  }

  function setBanner(text, colour) {
    var el = document.getElementById('erp-cloud-banner');
    if (!text) { if (el) el.remove(); return; }
    if (!el) {
      el = document.createElement('div');
      el.id = 'erp-cloud-banner';
      el.style.cssText = 'position:fixed;left:0;right:0;bottom:0;z-index:99999;padding:8px 14px;' +
