        var val = (d.data && Object.prototype.hasOwnProperty.call(d.data, 'v')) ? d.data.v : d.data;
        W.DB[d.key] = val;
        dsnap[d.key] = JSON.stringify(val);
      });
      lastDocs = dsnap;

      cacheLocally();
      if (!silent) {
        try { (W.refreshAll || W.renderAll || function () {})(); } catch (e) {}
      }
      return true;
    } catch (e) {
      toast('Could not load from the cloud: ' + (e.message || e), 'e');
      return false;
    }
  }

  // ------------------------------------------------------------------ push
  async function pushAll(force) {
    if (!sb || !orgId) return false;
    if (!canWrite()) return false;
    if (pushing) { dirty = true; return false; }
    pushing = true;

    try {
      var cols = collections();
      var upserts = [], deletions = {};

      cols.lists.forEach(function (coll) {
        var list = W.DB[coll] || [];
        var prev = lastSnapshot[coll] || {};
        var seen = {};
        list.forEach(function (rec, i) {
          if (!isPlainRecord(rec)) return;
          var rid = recordId(rec, coll, i);
          seen[rid] = 1;
          var json = JSON.stringify(rec);
          if (force || prev[rid] !== json) {
            upserts.push({ org_id: orgId, collection: coll, rec_id: rid, data: rec, ord: i, updated_by: myUserId });
          }
        });
        Object.keys(prev).forEach(function (rid) {
          if (!seen[rid]) (deletions[coll] = deletions[coll] || []).push(rid);
        });
      });

      var docUpserts = [];
      cols.docs.forEach(function (key) {
        var json = JSON.stringify(W.DB[key]);
        if (force || lastDocs[key] !== json) {
          docUpserts.push({ org_id: orgId, key: key, data: { v: W.DB[key] }, updated_by: myUserId });
        }
      });

      for (var i = 0; i < upserts.length; i += CHUNK) {
        var slice = upserts.slice(i, i + CHUNK);
        var r = await sb.from('erp_records').upsert(slice, { onConflict: 'org_id,collection,rec_id' });
        if (r.error) throw r.error;
      }

      for (var j = 0; j < docUpserts.length; j += CHUNK) {
        var d = await sb.from('erp_docs').upsert(docUpserts.slice(j, j + CHUNK), { onConflict: 'org_id,key' });
        if (d.error) throw d.error;
      }

      var delColls = Object.keys(deletions);
      for (var k = 0; k < delColls.length; k++) {
        var coll = delColls[k], ids = deletions[coll];
        for (var m = 0; m < ids.length; m += CHUNK) {
          var dr = await sb.from('erp_records').delete()
            .eq('collection', coll).in('rec_id', ids.slice(m, m + CHUNK));
          if (dr.error) throw dr.error;
        }
      }

      // Only record the new baseline once the server has accepted everything,
      // so a failed push is retried instead of being silently forgotten.
      var snap = {};
      cols.lists.forEach(function (coll) {
        var mm = {};
        (W.DB[coll] || []).forEach(function (rec, i) {
          if (!isPlainRecord(rec)) return;
          mm[recordId(rec, coll, i)] = JSON.stringify(rec);
        });
        snap[coll] = mm;
      });
      lastSnapshot = snap;
      lastDocs = {};
      cols.docs.forEach(function (key) { lastDocs[key] = JSON.stringify(W.DB[key]); });

      setBanner('');
      if (typeof W._markSaved === 'function') { try { W._markSaved(); } catch (e) {} }
      return true;
    } catch (e) {
      setBanner('Not saved to the cloud \u2014 ' + (e.message || e) + '. Your work is still on this device.', '#b91c1c');
      return false;
    } finally {
      pushing = false;
      if (dirty) { dirty = false; schedulePush(); }
    }
  }

  function schedulePush() {
    if (!canWrite()) return;
    clearTimeout(pushTimer);
    pushTimer = setTimeout(function () { pushAll(false); }, PUSH_DEBOUNCE);
  }

  // Offline cache only. The cloud is authoritative.
  function cacheLocally() {
    try {
      if (typeof W._erpLocalSave === 'function') return W._erpLocalSave();
      localStorage.setItem('rbo_v4', JSON.stringify(W.DB));
    } catch (e) { if(W.reportSilentError) W.reportSilentError('save', e.message, 'cacheLocally'); /* quota: the cloud copy is the one that matters */ }
  }

  // ------------------------------------------------------------- realtime
  function subscribe() {
    try {
      sb.channel('erp-live')
        .on('postgres_changes', { event: '*', schema: 'public', table: 'erp_records' }, onRemoteChange)
        .on('postgres_changes', { event: '*', schema: 'public', table: 'erp_docs' }, onRemoteChange)
        .subscribe();
    } catch (e) { /* realtime is a convenience, not a requirement */ }
  }

  var remoteTimer = null;
  function onRemoteChange(payload) {
    var by = payload && payload.new && payload.new.updated_by;
    if (by && by === myUserId) return;         // our own write echoing back
    clearTimeout(remoteTimer);
    remoteTimer = setTimeout(function () { pullAll(false); }, 700);
  }

  // ------------------------------------------------------------------ auth
  function loginError(msg) {
    var el = document.getElementById('login-error');
    if (el) { el.textContent = msg; el.style.display = 'block'; }
    else toast(msg, 'e');
    var btn = document.getElementById('ls-login-btn');
    if (btn) btn.disabled = false;
  }

  function creds() {
    var u = document.getElementById('login-user');
    var p = document.getElementById('login-pass');
    return { email: (u && u.value || '').trim(), pass: (p && p.value) || '' };
  }

  W.doLogin = async function () {
    var c = creds();
    var err = document.getElementById('login-error');
    if (err) { err.style.display = 'none'; err.textContent = ''; }
    if (!c.email || !c.pass) return loginError('Please enter your email and password.');
    var btn = document.getElementById('ls-login-btn');
    if (btn) btn.disabled = true;

    var res = await sb.auth.signInWithPassword({ email: c.email, password: c.pass });
    if (res.error) return loginError(res.error.message || 'Sign in failed.');
    await afterSignIn();
  };

  W.erpSignUp = async function () {
    var c = creds();
    if (!c.email || !c.pass) return loginError('Enter the email and password you want to use, then press Create an account.');
    if (c.pass.length < 8) return loginError('Choose a password of at least 8 characters.');
    var res = await sb.auth.signUp({
      email: c.email,
      password: c.pass,
      options: { emailRedirectTo: window.location.href }
    });
    if (res.error) return loginError(res.error.message || 'Could not create the account.');
    if (res.data && res.data.session) return afterSignIn();
    loginError('Account created. Check ' + c.email + ' for the confirmation link, then sign in.');
  };

  W.erpResetPassword = async function () {
    var c = creds();
    if (!c.email) return loginError('Enter your email address first, then choose Forgot password.');
    var res = await sb.auth.resetPasswordForEmail(c.email, { redirectTo: window.location.href });
    if (res.error) return loginError(res.error.message);
    loginError('Password reset link sent to ' + c.email + '.');
  };
  W.lsShowHint = W.erpResetPassword;

  W.erpChangePassword = async function () {
    var pw = prompt('Enter your new password (at least 8 characters):');
    if (!pw) return;
    if (pw.length < 8) return toast('Password must be at least 8 characters.', 'e');
    var res = await sb.auth.updateUser({ password: pw });
    if (res.error) return toast(res.error.message, 'e');
    toast('Password updated.', 's');
  };

  W.doLogout = async function () {
    try { if (canWrite()) await pushAll(false); } catch (e) {}
    try { await sb.auth.signOut(); } catch (e) {}
    W.currentUser = null; orgId = null; myRole = null; myUserId = null;
    lastSnapshot = {}; lastDocs = {};
    try { sessionStorage.clear(); } catch (e) {}
    location.reload();
  };

  // Map the cloud role onto the role vocabulary the existing screens use.
  function appRole(role) {
    if (role === 'owner') return 'Owner';
    if (role === 'admin') return 'Admin';
    if (role === 'manager') return 'Manager';
    return 'Viewer';
  }

  async function afterSignIn() {
    var u = (await sb.auth.getUser()).data.user;
    if (!u) return loginError('Sign in did not complete. Please try again.');
    myUserId = u.id;

    var j = await sb.rpc('join_or_create_org');
    if (j.error) return loginError('Could not open your company workspace: ' + j.error.message);
    var row = Array.isArray(j.data) ? j.data[0] : j.data;
    orgId = row.org_id;
    myRole = row.role;

    W.currentUser = {
      id: u.id,
      email: u.email,
      name: (u.user_metadata && u.user_metadata.full_name) || u.email,
      username: u.email,
      role: appRole(myRole),
      permissions: (myRole === 'owner' || myRole === 'admin') ? 'all' : {},
      status: 'Active'
    };
    try { sessionStorage.setItem('rbo_user', JSON.stringify(W.currentUser)); } catch (e) {}

    try { (W.showApp || function () {})(); } catch (e) {}
    await pullAll(false);
    subscribe();

    if (!canWrite()) {
      setBanner('You have view-only access. Ask an owner or admin to give you edit rights.', '#334155');
      toast('Signed in with view-only access.', 'i');
    } else {
      toast('Welcome, ' + W.currentUser.name, 's');
    }
  }

  // ------------------------------------------------- take over save / load
  // NOTE: this used to fully replace window.saveDB/saveDBNow, which silently
  // dropped two things earlier patches relied on: the data-safety pass
  // (_erpTxAlias / _erpHashSweep / _erpSanitizeDB, from erp-data-safety-v8)
  // and the post-save UI refresh (from admin-stock-reset-and-zoom). Both are
  // now run explicitly on every save so cloud sync doesn't regress them.
  var _refreshTimer = null;
  function scheduleUiRefresh() {
    clearTimeout(_refreshTimer);
    _refreshTimer = setTimeout(function () {
      try { (W.refreshCurrentPage || W.refreshAll || W.renderAll || function () {})(); } catch (e) {}
    }, 120);
  }
  function runPostSaveHooks() {
    try { W._erpTxAlias && W._erpTxAlias(); } catch (e) {}
    try { W._erpHashSweep && W._erpHashSweep(); } catch (e) {}
    try { W._erpSanitizeDB && W._erpSanitizeDB(); } catch (e) {}
    scheduleUiRefresh();
  }

  function installStorageOverrides() {
    W.saveDB = function () {
      runPostSaveHooks();
      cacheLocally();
      if (!canWrite()) {
        toast('You have view-only access, so this change was not saved.', 'e');
        return false;
      }
      schedulePush();
      return true;
    };

    W.saveDBNow = async function () {
      runPostSaveHooks();
      cacheLocally();
      if (!canWrite()) return false;
      clearTimeout(pushTimer);
      return pushAll(false);
    };

    W.loadDataFromServer = function () { return pullAll(false); };
    W.initLogin = function () { return Promise.resolve(true); };

    // Never lose the last few seconds of work on tab close.
    var flush = function () {
      if (!orgId || !canWrite()) return;
      cacheLocally();
      clearTimeout(pushTimer);
      pushAll(false);
    };
    W.addEventListener('pagehide', flush);
    W.addEventListener('beforeunload', flush);
    document.addEventListener('visibilitychange', function () {
      if (document.hidden) flush();
    });

    // Periodic safety net in case a screen mutates DB without calling saveDB().
    setInterval(function () { if (orgId && canWrite()) pushAll(false); }, 30000);
  }

  // ------------------------------------------------------------------ boot
  async function boot() {
    if (!W.supabase || !W.supabase.createClient) {
      setBanner('Connecting to the cloud service\u2026', '#334155');
      var libOk = false;
      try { libOk = W.__ensureSupabaseLib ? await W.__ensureSupabaseLib() : false; } catch (e) { libOk = false; }
      if (!libOk) {
        setBanner('Could not reach the cloud service. Tap here to retry.', '#b91c1c');
        var b = document.getElementById('erp-cloud-banner');
        if (b) { b.style.cursor = 'pointer'; b.onclick = function () { b.onclick = null; boot(); }; }
        return;
      }
      setBanner('', null);
    }

    sb = W.supabase.createClient(CLOUD_URL, CLOUD_KEY, {
      auth: { persistSession: true, autoRefreshToken: true, storageKey: 'ayan-erp-auth' },
      global: {
        // The publishable key is not a JWT, so it must travel as `apikey`
        // only; left in the Authorization header PostgREST rejects it.
        fetch: function (input, init) {
          init = init || {};
          var h = new Headers(init.headers || {});
          if (h.get('Authorization') === 'Bearer ' + CLOUD_KEY) h.delete('Authorization');
          h.set('apikey', CLOUD_KEY);
          init.headers = h;
          return fetch(input, init);
        }
      }
    });

    installStorageOverrides();

    var note = document.getElementById('ls-cloud-note');
    if (note) note.textContent = 'Secure cloud sign-in';

    var sess = (await sb.auth.getSession()).data.session;
    if (sess) {
      await afterSignIn();
    } else {
      try { (W.showLoginScreen || function () {})(); } catch (e) {}
      var ls = document.getElementById('login-screen');
      if (ls) ls.style.display = 'flex';
    }

    sb.auth.onAuthStateChange(function (event) {
      if (event === 'SIGNED_OUT') { W.currentUser = null; }
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function () { setTimeout(boot, 0); });
  } else {
    setTimeout(boot, 0);
  }
})();
</script>

<script nonce="<?php echo $cspNonceAttr; ?>" id="claude-review-balance-sheet-fixes">
/* ═══════════════════════════════════════════════════════════════════════
   PATCH — Balance Sheet / Trial Balance correctness fixes.
   Additive only, like every other ayan-fix-* layer: nothing above this
   block is edited, everything here wraps the previous implementation and
   falls back to it. Loads last on purpose.

   Fixes 4 issues found during review:
     1. applyTxStock() was reading a stale local INV_IN_TYPES/INV_OUT_TYPES
        array (missing Manufacturing Output/Consumption, Raw Material Issue,
        Finished Goods Entry, Opening Balance) instead of the canonical
        window.INV_IN_TYPES/OUT_TYPES Sets — those Sets had also been
        silently overwritten by that same stray array, breaking
        renderLowStockAlerts()/renderStockSummary() (they call .has() on
        what had become a plain Array).
     2. applyTxBalance() had no branch at all for 'Customer Sale' / 'Warehouse
        Sale' — both count as revenue (REVENUE_TX_TYPES) but never touched a
        customer balance or bank balance, guaranteeing a Trial Balance
        mismatch whenever either type was used.
     3. Cash-mode Sale/Purchase transactions (Payment Mode = "Cash", the
        default) had nowhere to post to — no "Cash" bank account exists, so
        the money vanished from both Bank Balance and Cash in Hand. A
        virtual "Cash In Hand" account is introduced and wired in.
     4. Sales Return / Purchase Return were invisible to sumRevenue/sumCogs/
        computeCOGS, so returned goods never reduced booked profit.
   ═══════════════════════════════════════════════════════════════════════ */
(function(){
  'use strict';

  // ── FIX 1: restore + actually use the canonical stock-type Sets ───────
  // Re-declare them (they were clobbered further up the document by a
  // plain lowercase Array with the same names) and rewrite applyTxStock to
  // read through window.isStockIn/isStockOut (which already normalise the
  // 'Werhouse' typo) instead of its own stale local list.
  window.INV_IN_TYPES = new Set(['Purchase','Supplier Purchase','Warehouse Purchase',
    'Opening Balance','Opening Stock','Sales Return','Finished Goods Entry',
    'Manufacturing Output','Stock In']);
  window.INV_OUT_TYPES = new Set(['Sale','Customer Sale','Warehouse Sale',
    'Purchase Return','Raw Material Issue','Manufacturing Consumption',
    'Wastage','Stock Out']);

  window.applyTxStock = function(tx, dir){
    if(!tx) return;
    var isIn  = (typeof window.isStockIn==='function')  && window.isStockIn(tx);
    var isOut = (typeof window.isStockOut==='function') && window.isStockOut(tx);
    if(!isIn && !isOut) return;
    var name = tx.prod || tx.product;
    if(!name) return;
    var item = (typeof invFind==='function') ? invFind(name) : null;
    if(!item){                                   // auto-create so stock is never lost
      var list = (typeof invItems==='function') ? invItems() : (DB.products = DB.products||[]);
      item = {id:(DB.nid && DB.nid.pr ? DB.nid.pr++ : Date.now()), name:String(name),
              category:'General', cat:'General', unit:'KG', rate:0, cost:0,
              stock:0, qty:0, stockQty:0, minStock:0, openingStock:0};
      list.push(item);
    }
    var qty = (typeof invTxQty==='function') ? invTxQty(tx) : (parseFloat(tx.qty)||0);
    if(!qty) return;
    var delta = (isIn ? qty : -qty) * dir;
    var before = parseFloat(item.stock)||0;
    var rate = parseFloat(tx.rate) || (qty ? (parseFloat(tx.amt||tx.amount)||0)/qty : 0);
    if(isIn && dir>0 && rate>0){
      var newQty = before + qty;
      if(newQty>0) item.cost = ((before*(parseFloat(item.cost)||0)) + (qty*rate)) / newQty;
      if(!item.rate) item.rate = rate;
    }
    if(typeof invSetQty==='function') invSetQty(item, before + delta);
    else { item.stock = item.qty = item.stockQty = before + delta; }
  };

  // ── FIX 2: applyTxBalance — add the missing Customer Sale / Warehouse
  // Sale branch. Everything else falls through to whatever was already
  // installed (Payment Refund, Supplier Refund, the base chain, etc). ──
  var _prevApplyBal_sale = window.applyTxBalance;
  window.applyTxBalance = function(tx, dir){
    var type = String((tx && tx.type) || '').trim().toLowerCase();
    if(type === 'customer sale' || type === 'warehouse sale'){
      var amt   = (parseFloat(tx.amount)||0) * dir;
      var recv  = (parseFloat(tx.recv)||0)   * dir;
      var party = (tx.party||'').trim();
      var acc   = (tx.acc||'').trim();
      var c = ((window.DB && DB.customers)||[]).filter(function(x){return x.name===party;})[0];
      if(c){ c.bal=(parseFloat(c.bal)||0)+amt; if(recv) c.bal-=recv; }
      if(recv && acc){
        var b = ((window.DB && DB.banks)||[]).filter(function(x){return x.name===acc;})[0];
        if(b) b.bal=(parseFloat(b.bal)||0)+recv;
      }
      return;
    }
    return (typeof _prevApplyBal_sale==='function') ? _prevApplyBal_sale.apply(this, arguments) : undefined;
  };

  // ── FIX 3: Cash-mode transactions need somewhere to post to ───────────
  // Payment Mode "Cash" (the default) has no matching bank account, so the
  // money never reached Bank Balance or Cash in Hand. Give it a real,
  // virtual "Cash In Hand" account and default tx.acc to it whenever the
  // form left the account blank. This wraps (and runs before) FIX 2 above,
  // so a cash-mode Customer/Warehouse Sale gets the default account too.
  var CASH_ACCOUNT_NAME = 'Cash In Hand';
  function ensureCashAccount(){
    var b = ((window.DB && DB.banks)||[]).filter(function(x){return x.name===CASH_ACCOUNT_NAME;})[0];
    if(!b){
      b = {id:(DB.nid && DB.nid.b ? DB.nid.b++ : Date.now()), name:CASH_ACCOUNT_NAME,
           bal:0, balance:0, type:'Cash', accNo:'', isCashAccount:true};
      (DB.banks = DB.banks||[]).push(b);
    }
    return b;
  }
  try{ ensureCashAccount(); }catch(e){}

  var _prevApplyBal_cash = window.applyTxBalance;
  window.applyTxBalance = function(tx, dir){
    if(tx && String(tx.mode||'').trim().toLowerCase()==='cash' && !String(tx.acc||'').trim()){
      ensureCashAccount();
      tx.acc = CASH_ACCOUNT_NAME;
    }
    return (typeof _prevApplyBal_cash==='function') ? _prevApplyBal_cash.apply(this, arguments) : undefined;
  };

  // computePosition(): fold the virtual cash account into "Cash in Hand"
  // instead of "Bank Balance", and keep it additive to any legacy manual
  // 'Cash Received'/'Cash Payment' entries already in the data.
  var _prevComputePosition = window.computePosition;
  window.computePosition = function(){
    var P = (typeof _prevComputePosition==='function') ? _prevComputePosition.apply(this, arguments) : {};
    try{
      var cashAcct = ((window.DB && DB.banks)||[]).filter(function(b){return b.isCashAccount;})[0];
      var cashBal  = cashAcct ? (parseFloat(cashAcct.bal)||0) : 0;
      var newCashInHand   = (P.cashInHand||0) + cashBal;
      var newBankBalance  = (P.bankBalance||0) - cashBal;
      (P.rightItems||[]).forEach(function(item){
        if(item.label==='Bank Balance')  item.val = newBankBalance;
        if(item.label==='Cash in Hand')  item.val = newCashInHand;
      });
      P.bankBalance = newBankBalance;
      P.cashInHand  = newCashInHand;
      P.totalRight  = (P.rightItems||[]).reduce(function(a,i){return a+i.val;},0);
      P.totalAssets = P.totalRight;
      P.netWorth    = P.totalRight - P.liabilities;
    }catch(e){}
    return P;
  };

  // ── FIX 4: Sales Return / Purchase Return must reduce booked profit ───
  // sumRevenue/sumCogs feed the dashboard KPI cards; computeCOGS feeds the
  // Balance Sheet's Net Profit. None of the three previously looked at
  // return transactions at all.
  var _prevSumRevenue = window.sumRevenue;
  window.sumRevenue = function(list){
    var base = (typeof _prevSumRevenue==='function') ? _prevSumRevenue.apply(this, arguments) : 0;
    var returns = (list||[]).filter(function(t){ return window.normTxType(t&&t.type)==='Sales Return'; })
                             .reduce(function(a,t){ return a + window.txAmt(t); }, 0);
    return base - returns;
  };
  var _prevSumCogs = window.sumCogs;
  window.sumCogs = function(list){
    var base = (typeof _prevSumCogs==='function') ? _prevSumCogs.apply(this, arguments) : 0;
    var returns = (list||[]).filter(function(t){ return window.normTxType(t&&t.type)==='Purchase Return'; })
                             .reduce(function(a,t){ return a + window.txAmt(t); }, 0);
    return base - returns;
  };
  var _prevComputeCOGS = window.computeCOGS;
  window.computeCOGS = function(txList){
    var base = (typeof _prevComputeCOGS==='function') ? _prevComputeCOGS.apply(this, arguments) : 0;
    var returns = (txList||[]).filter(function(t){ return window.normTxType(t&&t.type)==='Purchase Return'; })
                               .reduce(function(a,t){ return a + window.txAmt(t); }, 0);
    return Math.max(0, base - returns);
    /* NOTE: this corrects the total only. cogsByProduct()'s per-product
       breakdown (used by product-level P&L reports) still doesn't reduce
       for Purchase Return per product — a deeper fix if those reports
       matter to you. */
  };

  console.info('[Claude review patch] Balance Sheet fixes active: stock types restored, Customer/Warehouse Sale wired into balances, Cash-mode transactions post to a virtual "Cash In Hand" account, Sales/Purchase Return now reduce profit.');
})();
</script>

<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-fix-orders-v5">
/* ═══════════════════════════════════════════════════════════════════════
   PATCH — Order Management: real admin/owner control + linked dropdowns.
   Additive layer, loads last. Inventory screens are deliberately untouched.
     1. Role detection no longer depends on a stale local `currentUser`
        (the cloud layer writes window.currentUser / sessionStorage.rbo_user),
        so Owner and Admin actually get the full-control fields and the
        delete button back.
     2. Order modal fields B/C/D/Company Location/Truck are now real
        dropdowns that cascade: customer -> product -> load location, and
        truck -> driver mobile, with rate auto-filled from history.
        "Other (type manually)" keeps free text possible.
   ═══════════════════════════════════════════════════════════════════════ */
(function () {
  'use strict';
  var W = window;

  // ── 1. Role helpers ────────────────────────────────────────────────────
  function activeUser() {
    if (W.currentUser) return W.currentUser;
    try { return JSON.parse(sessionStorage.getItem('rbo_user') || 'null'); } catch (e) { return null; }
  }
  W.currentRole = function () { return String((activeUser() || {}).role || 'Viewer').toLowerCase(); };
  W.isAdminOrOwner = function () {
    var r = W.currentRole();
    return r === 'admin' || r === 'owner' || r === 'manager' || r === 'administrator';
  };
  W.isOwnerRole = function () { return W.currentRole() === 'owner'; };
  W.canEditOrder = function () { return W.isAdminOrOwner(); };
  W.canDeleteOrder = function () { return W.isAdminOrOwner(); };

  // ── 2. Linked dropdowns ────────────────────────────────────────────────
  var OTHER = '__other__';

  function uniq(list) {
    var seen = {}, out = [];
    (list || []).forEach(function (v) {
      v = (v == null ? '' : String(v)).trim();
      if (!v || seen[v.toLowerCase()]) return;
      seen[v.toLowerCase()] = 1; out.push(v);
    });
    return out.sort(function (a, b) { return a.localeCompare(b); });
  }
  function orders() { return (W.DB && W.DB.orders) || []; }
  function customerOptions() {
    var parties = ((W.DB && W.DB.customers) || []).filter(function (c) {
      return typeof W.isCustomerParty === 'function' ? W.isCustomerParty(c) : true;
    }).map(function (c) { return c.name; });
    return uniq(parties.concat(orders().map(function (o) { return o.customerName; })));
  }
  /* Products come from the product master + this customer's own order
     history — deliberately NOT from the inventory/stock list. */
  function productOptions(customer) {
    var hist = orders().filter(function (o) { return !customer || o.customerName === customer; })
      .map(function (o) { return o.productName; });
    if (customer && uniq(hist).length) return uniq(hist);
    return uniq(((W.DB && W.DB.products) || []).map(function (p) { return p.name; })
      .concat(orders().map(function (o) { return o.productName; })));
  }
  function loadLocOptions(customer, product) {
    var scoped = orders().filter(function (o) {
      return (!product || o.productName === product) && (!customer || o.customerName === customer);
    }).map(function (o) { return o.loadLocation; });
    if (uniq(scoped).length) return uniq(scoped);
    return uniq(orders().map(function (o) { return o.loadLocation; }));
  }
  function companyLocOptions(customer) {
    var scoped = orders().filter(function (o) { return !customer || o.customerName === customer; })
      .map(function (o) { return o.companyLocation; });
    if (uniq(scoped).length) return uniq(scoped);
    return uniq(orders().map(function (o) { return o.companyLocation; }));
  }
  function truckOptions() { return uniq(orders().map(function (o) { return o.truckId; })); }
  function lastOrder(match) {
    var list = orders().filter(match).slice().sort(function (a, b) {
      return String(b.orderDate || '').localeCompare(String(a.orderDate || ''));
    });
    return list[0] || null;
  }

  function styleOf(el) { return el.getAttribute('style') || ''; }

  function toSelect(id, options, value, onChange) {
    var el = document.getElementById(id);
    if (!el) return null;
    var disabled = el.disabled;
    var style = styleOf(el);
    var current = value != null ? value : el.value;
    var sel = document.createElement('select');
    sel.id = id;
    sel.setAttribute('style', style);
    sel.disabled = disabled;
    var opts = options.slice();
    if (current && opts.indexOf(current) === -1) opts.unshift(current);
    sel.innerHTML = '<option value="">— select —</option>' +
      opts.map(function (o) {
        return '<option value="' + String(o).replace(/"/g, '&quot;') + '">' + o + '</option>';
      }).join('') +
      '<option value="' + OTHER + '">➕ Other (type manually)…</option>';
    sel.value = current || '';
    sel.addEventListener('change', function () {
      if (sel.value === OTHER) { toText(id, style, disabled, onChange); return; }
      if (onChange) onChange(sel.value);
    });
    el.parentNode.replaceChild(sel, el);
    return sel;
  }

  function toText(id, style, disabled, onChange) {
    var el = document.getElementById(id);
    if (!el) return;
    var inp = document.createElement('input');
    inp.type = 'text';
    inp.id = id;
    inp.setAttribute('style', style || styleOf(el));
    inp.disabled = !!disabled;
    inp.placeholder = 'Type a new value';
    inp.addEventListener('change', function () { if (onChange) onChange(inp.value.trim()); });
    el.parentNode.replaceChild(inp, el);
    inp.focus();
  }

  function val(id) { var e = document.getElementById(id); return e ? String(e.value || '').trim() : ''; }
  function setVal(id, v) { var e = document.getElementById(id); if (e && v != null) e.value = v; }

  function rebuildProduct() {
    var cust = val('ord-customer');
    toSelect('ord-product', productOptions(cust), val('ord-product'), onProduct);
    rebuildCompanyLoc();
    rebuildLoadLoc();
  }
  function rebuildLoadLoc() {
    toSelect('ord-load-loc', loadLocOptions(val('ord-customer'), val('ord-product')), val('ord-load-loc'), null);
  }
  function rebuildCompanyLoc() {
    var e = document.getElementById('ord-company-loc');
    if (!e) return;
    toSelect('ord-company-loc', companyLocOptions(val('ord-customer')), val('ord-company-loc'), null);
  }
  function onCustomer() {
    rebuildProduct();
    var prev = lastOrder(function (o) { return o.customerName === val('ord-customer'); });
    if (prev && !val('ord-company-loc')) setVal('ord-company-loc', prev.companyLocation || '');
  }
  function onProduct(v) {
    rebuildLoadLoc();
    var prev = lastOrder(function (o) {
      return o.productName === v && (!val('ord-customer') || o.customerName === val('ord-customer'));
    }) || lastOrder(function (o) { return o.productName === v; });
    if (prev) {
      if (!val('ord-rate') && prev.rate) setVal('ord-rate', prev.rate);
      if (!val('ord-load-loc') && prev.loadLocation) setVal('ord-load-loc', prev.loadLocation);
      if (typeof W.calcOrderTotal === 'function') { try { W.calcOrderTotal(); } catch (e) {} }
    }
  }
  function onTruck(v) {
    var prev = lastOrder(function (o) { return o.truckId === v && o.driverMobile; });
    if (prev) setVal('ord-driver-mobile', prev.driverMobile);
  }

  function upgradeModal() {
    if (!document.getElementById('ord-customer')) return;
    toSelect('ord-customer', customerOptions(), null, onCustomer);
    toSelect('ord-product', productOptions(val('ord-customer')), null, onProduct);
    toSelect('ord-load-loc', loadLocOptions(val('ord-customer'), val('ord-product')), null, null);
    rebuildCompanyLoc();
    toSelect('ord-truck-id', truckOptions(), null, onTruck);
  }

  function wrap(name, after) {
    var fn = W[name];
    if (typeof fn !== 'function' || fn.__ordWrapped) return;
    var next = function () {
      var r = fn.apply(this, arguments);
      try { setTimeout(after, 0); } catch (e) {}
      return r;
    };
    next.__ordWrapped = true;
    W[name] = next;
  }

  function install() {
    wrap('openOrderModal', upgradeModal);
    wrap('editOrder', upgradeModal);
  }
  install();
  // Re-apply if a later layer replaces the functions.
  setTimeout(install, 1500);

  // Keep the order screen honest about the signed-in role.
  if (typeof W.renderOrderManagement === 'function' && !W.renderOrderManagement.__roleAware) {
    var rom = W.renderOrderManagement;
    var wrapped = function () { return rom.apply(this, arguments); };
    wrapped.__roleAware = true;
    W.renderOrderManagement = wrapped;
  }
})();
</script>
<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-linked-dropdowns-v6">
/* ═══════════════════════════════════════════════════════════════════════
   PATCH — Linked dropdowns beyond Order Management.
   Transaction modal (Purchase/Sale/Expense), Payment Entry and Payment
   Voucher now cascade like the order modal: party -> product list ->
   rate / bag type / oil % from that party's own history, truck ->
   transport rent + type, payee -> mode / account / purpose.
   Every option comes from transaction history and the party/product
   masters — inventory stock lists are deliberately untouched.
   Free typing keeps working (all fields stay datalist inputs).
   ═══════════════════════════════════════════════════════════════════════ */
(function () {
  'use strict';
  var W = window;

  function DBx() { return W.DB || {}; }
  function txs() { return DBx().tx || []; }
  function uniq(list) {
    var seen = {}, out = [];
    (list || []).forEach(function (v) {
      v = (v == null ? '' : String(v)).trim();
      if (!v || seen[v.toLowerCase()]) return;
      seen[v.toLowerCase()] = 1; out.push(v);
    });
    return out.sort(function (a, b) { return a.localeCompare(b); });
  }
  function el(id) { return document.getElementById(id); }
  function val(id) { var e = el(id); return e ? String(e.value || '').trim() : ''; }
  function isEmpty(id) { var v = val(id); return !v || v === '0'; }
  function setIfEmpty(id, v) {
    if (v == null || v === '' || !isEmpty(id)) return;
    var e = el(id); if (!e) return;
    if (e.tagName === 'SELECT') {
      var has = Array.prototype.some.call(e.options, function (o) { return o.value === String(v); });
      if (!has) { var op = document.createElement('option'); op.value = String(v); op.textContent = String(v); e.appendChild(op); }
    }
    e.value = v;
    try {
      e.dispatchEvent(new Event('input', { bubbles: true }));
      e.dispatchEvent(new Event('change', { bubbles: true }));
    } catch (err) {}
  }
  function ensureList(inputId, listId, options) {
    var inp = el(inputId);
    if (!inp || inp.tagName !== 'INPUT') return;
    var dl = el(listId);
    if (!dl) {
      dl = document.createElement('datalist');
      dl.id = listId;
      (inp.parentNode || document.body).appendChild(dl);
    }
    inp.setAttribute('list', listId);
    dl.innerHTML = options.map(function (o) {
      return '<option value="' + String(o).replace(/"/g, '&quot;') + '"></option>';
    }).join('');
  }
  function last(match) {
    var l = txs().filter(match).slice().sort(function (a, b) {
      return String(a.date || '').localeCompare(String(b.date || ''));
    });
    return l[l.length - 1] || null;
  }

  function partyNames() {
    return uniq((DBx().parties || []).map(function (p) { return p.name; })
      .concat((DBx().customers || []).map(function (c) { return c.name; }))
      .concat(txs().map(function (t) { return t.party; })));
  }
  function productsFor(party) {
    var hist = uniq(txs().filter(function (t) { return !party || t.party === party; })
      .map(function (t) { return t.prod || t.product; }));
    if (party && hist.length) return hist;
    return uniq((DBx().products || []).map(function (p) { return p.name; })
      .concat(txs().map(function (t) { return t.prod || t.product; })));
  }
  function trucksFor(party) {
    var scoped = uniq(txs().filter(function (t) { return !party || t.party === party; })
      .map(function (t) { return t.truck; }));
    return scoped.length ? scoped : uniq(txs().map(function (t) { return t.truck; }));
  }

  function onTxParty() {
    var party = val('tx-party');
    ensureList('tx-prod', 'dl-prod', productsFor(party));
    ensureList('tx-truck', 'dl-tx-truck', trucksFor(party));
    var prev = last(function (t) { return t.party === party; });
    if (prev) {
      setIfEmpty('tx-loc', prev.loc);
      setIfEmpty('tx-ptype', prev.ptype);
    }
  }
  function onTxProd() {
    var party = val('tx-party'), prod = val('tx-prod');
    if (!prod) return;
    var prev = last(function (t) { return (t.prod || t.product) === prod && (!party || t.party === party); })
      || last(function (t) { return (t.prod || t.product) === prod; });
    if (!prev) return;
    setIfEmpty('tx-rate', prev.rate);
    setIfEmpty('tx-bagtype', prev.bagtype);
    setIfEmpty('tx-oilpct', prev.oilPct);
    try { if (typeof W.smartCalcAmount === 'function') W.smartCalcAmount(); } catch (e) {}
  }
  function onTxTruck() {
    var truck = val('tx-truck');
    if (!truck) return;
    var prev = last(function (t) { return t.truck === truck; });
    if (!prev) return;
    setIfEmpty('tx-truckrent', prev.truckrent);
    setIfEmpty('tx-transporttype', prev.transporttype);
  }
  function onPaymentParty(prefix) {
    var party = val(prefix + '-party');
    if (!party) return;
    var prev = last(function (t) { return t.party === party; });
    if (!prev) return;
    if (prefix === 'pye') {
      setIfEmpty('pye-mode', prev.mode);
      setIfEmpty('pye-bank', prev.bank || prev.acc);
    } else {
      setIfEmpty('pv-bank', prev.bank || prev.acc);
      setIfEmpty('pv-purpose', prev.note || prev.purpose);
    }
  }

  function refreshLists() {
    ensureList('tx-party', 'dl-party', partyNames());
    ensureList('tx-prod', 'dl-prod', productsFor(val('tx-party')));
    ensureList('tx-truck', 'dl-tx-truck', trucksFor(val('tx-party')));
    ensureList('tx-bagtype', 'dl-tx-bagtype', uniq(txs().map(function (t) { return t.bagtype; })));
    ensureList('pye-party', 'dl-pye-party', partyNames());
    ensureList('pv-party', 'pv-party-list', partyNames());
  }

  document.addEventListener('change', function (ev) {
    var t = ev.target; if (!t || !t.id) return;
    if (t.id === 'tx-party') { onTxParty(); onTxProd(); }
    else if (t.id === 'tx-prod') onTxProd();
    else if (t.id === 'tx-truck') onTxTruck();
    else if (t.id === 'pye-party') onPaymentParty('pye');
    else if (t.id === 'pv-party') onPaymentParty('pv');
  }, true);

  document.addEventListener('focusin', function (ev) {
    var t = ev.target;
    if (t && t.id && /^(tx-|pye-|pv-)/.test(t.id)) refreshLists();
  }, true);

  setTimeout(refreshLists, 800);
  console.info('[Linked dropdowns v6] Transaction, payment entry and voucher forms are cascading.');
})();
</script>

<style id="ayan-ai-style">
#ayan-ai-fab{position:fixed;right:18px;bottom:calc(86px + var(--erp-reminder-h,0px));z-index:99998;width:54px;height:54px;border-radius:50%;
  border:none;cursor:pointer;font-size:22px;color:#fff;background:linear-gradient(145deg,#0f7a45,#0b5c34);
  box-shadow:0 10px 24px -8px rgba(6,40,24,.6);}
#ayan-ai-panel{position:fixed;right:18px;bottom:150px;z-index:99999;width:min(380px,calc(100vw - 36px));
  max-height:min(70vh,560px);display:none;flex-direction:column;background:#fff;border:1px solid #d6e6dc;
  border-radius:14px;overflow:hidden;box-shadow:0 24px 50px -18px rgba(6,40,24,.5);font-size:13px;}
#ayan-ai-panel header{background:linear-gradient(145deg,#0f7a45,#0b5c34);color:#fff;padding:10px 12px;
  font-weight:800;display:flex;align-items:center;justify-content:space-between;}
#ayan-ai-panel header button{background:transparent;border:none;color:#fff;font-size:18px;cursor:pointer;}
#ayan-ai-log{flex:1;overflow:auto;padding:12px;background:#f7fbf8;}
.ayan-ai-msg{margin-bottom:10px;line-height:1.5;white-space:pre-wrap;word-break:break-word;}
.ayan-ai-msg b{display:block;font-size:11px;color:#0b5c34;margin-bottom:2px;}
.ayan-ai-msg.me{text-align:right;color:#134e33;}
.ayan-ai-msg table{width:100%;border-collapse:collapse;margin-top:6px;font-size:11px;background:#fff;}
.ayan-ai-msg th,.ayan-ai-msg td{border:1px solid #d6e6dc;padding:4px 6px;text-align:left;}
.ayan-ai-msg th{background:#eaf5ee;}
#ayan-ai-form{display:flex;gap:6px;padding:10px;border-top:1px solid #e3efe7;background:#fff;}
#ayan-ai-input{flex:1;padding:8px 10px;border:1px solid #cfe0d6;border-radius:8px;font:inherit;}
#ayan-ai-send{padding:8px 14px;border:none;border-radius:8px;background:#0f7a45;color:#fff;font-weight:700;cursor:pointer;}
#ayan-ai-send[disabled]{opacity:.6;cursor:default;}
@media print{#ayan-ai-fab,#ayan-ai-panel{display:none !important;}}
</style>
<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-ai-assistant">
/* AI assistant — talks to api.php?action=chat, which returns
   { success, reply, table, isBugReport, timestamp }. */
(function(){
  'use strict';
  var W = window;
  function apiFile(){
    return (W.ERP_CONFIG && W.ERP_CONFIG.API_URL) ? W.ERP_CONFIG.API_URL : 'api.php';
  }
  function esc(v){
    return String(v == null ? '' : v).replace(/[&<>"']/g, function(c){
      return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];
    });
  }
  function el(id){ return document.getElementById(id); }

  function build(){
    if(el('ayan-ai-fab')) return;
    var fab = document.createElement('button');
    fab.id = 'ayan-ai-fab'; fab.type = 'button';
    fab.title = 'AI Assistant'; fab.textContent = '🤖';
    var panel = document.createElement('div');
    panel.id = 'ayan-ai-panel';
    panel.innerHTML =
      '<header><span>🤖 AI Assistant</span><button type="button" id="ayan-ai-close" aria-label="Close">×</button></header>' +
      '<div id="ayan-ai-log"><div class="ayan-ai-msg"><b>Assistant</b>Ask me about your sales, stock, parties or expenses.</div></div>' +
      '<form id="ayan-ai-form"><input id="ayan-ai-input" autocomplete="off" placeholder="Ask a question…" />' +
      '<button id="ayan-ai-send" type="submit">Send</button></form>';
    document.body.appendChild(fab);
    document.body.appendChild(panel);

    fab.onclick = function(){
      panel.style.display = (panel.style.display === 'flex') ? 'none' : 'flex';
      if(panel.style.display === 'flex') el('ayan-ai-input').focus();
    };
    el('ayan-ai-close').onclick = function(){ panel.style.display = 'none'; };
    el('ayan-ai-form').onsubmit = function(e){ e.preventDefault(); send(); };
  }

  function add(who, html, cls){
    var log = el('ayan-ai-log');
    var d = document.createElement('div');
    d.className = 'ayan-ai-msg' + (cls ? ' ' + cls : '');
    d.innerHTML = '<b>' + esc(who) + '</b>' + html;
    log.appendChild(d);
    log.scrollTop = log.scrollHeight;
    return d;
  }

  function tableHtml(rows){
    if(!rows || !rows.length || typeof rows[0] !== 'object') return '';
    var cols = [];
    rows.forEach(function(r){
      Object.keys(r || {}).forEach(function(k){ if(cols.indexOf(k) === -1) cols.push(k); });
    });
    return '<table><thead><tr>' + cols.map(function(c){ return '<th>' + esc(c) + '</th>'; }).join('') +
      '</tr></thead><tbody>' + rows.map(function(r){
        return '<tr>' + cols.map(function(c){ return '<td>' + esc(r ? r[c] : '') + '</td>'; }).join('') + '</tr>';
      }).join('') + '</tbody></table>';
  }

  // Running conversation memory sent back to api.php each turn, so the AI
  // remembers earlier questions in the same session instead of answering
  // each message cold.
  var history = [];

  async function send(){
    var input = el('ayan-ai-input'), btn = el('ayan-ai-send');
    var msg = (input.value || '').trim();
    if(!msg) return;
    input.value = '';
    add('You', esc(msg), 'me');
    btn.disabled = true;
    var pending = add('Assistant', 'Thinking…');
    try{
      var res = await fetch(apiFile() + '?action=chat', {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
        body: JSON.stringify({ message: msg, history: history })
      });
      var out = await res.json().catch(function(){ return {}; });
      if(res.status === 401 || res.status === 403){
        pending.innerHTML = '<b>Assistant</b>Session expired — please sign in again.';
        return;
      }
      if(!res.ok || out.success === false){
        throw new Error(out.message || out.error || ('Request failed (' + res.status + ')'));
      }
      var replyText = out.reply || 'No answer returned.';
      pending.innerHTML = '<b>Assistant</b>' + esc(replyText) + tableHtml(out.table);
      history.push({ role: 'user', text: msg });
      history.push({ role: 'model', text: replyText });
    }catch(err){
      pending.innerHTML = '<b>Assistant</b>⚠️ ' + esc(err.message || 'AI request failed.');
    }finally{
      btn.disabled = false;
      input.focus();
    }
  }

  if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', build);
  else build();
})();
</script>
<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-module-selfcheck">
/* STARTUP SELF-CHECK: the optional server modules (quotations.php, ledger.php,
   fixed_assets.php) live in separate PHP files next to api.php. When one was
   never uploaded, the only sign used to be a failure at the moment you opened
   the screen. This probes them once at startup and shows a single banner that
   names exactly which files to install. */
(function(){
  "use strict";
  var W = window, D = document;
  var MODULES = [
    { file: 'quotations.php',   label: 'Quotations' },
    { file: 'ledger.php',       label: 'General Ledger' },
    { file: 'fixed_assets.php', label: 'Fixed Assets' }
  ];
  var DISMISS_KEY = 'erp_modcheck_dismissed';

  function apiBase(){
    var u = (W.ERP_CONFIG && W.ERP_CONFIG.API_URL) ? String(W.ERP_CONFIG.API_URL) : '';
    return u ? u.replace(/api\.php.*/, '') : '';
  }

  /* Returns 'ok' (file answered), 'missing' (404/410) or 'unknown' (network /
     server error we should not blame on a missing upload). */
  async function probe(file){
    var url = apiBase() + file + '?action=ping&_=' + Date.now();
    var res;
    try{
      res = await fetch(url, { method:'HEAD', credentials:'include', headers:{ 'Accept':'application/json' } });
      if(res.status === 405 || res.status === 501){   // host blocks HEAD on PHP
        res = await fetch(url, { method:'GET', credentials:'include', headers:{ 'Accept':'application/json' } });
      }
    }catch(e){
      return 'unknown';
    }
    if(res.status === 404 || res.status === 410) return 'missing';
    if(res.status >= 500) return 'unknown';
    return 'ok';
  }

  function render(missing){
    var old = D.getElementById('ayan-modcheck-banner');
    if(old) old.parentNode.removeChild(old);
    if(!missing.length) return;

    var files = missing.map(function(m){ return m.file; }).join(', ');
    var names = missing.map(function(m){ return m.label; }).join(', ');
    var bar = D.createElement('div');
    bar.id = 'ayan-modcheck-banner';
    bar.setAttribute('role', 'alert');
    bar.style.cssText = 'position:fixed;top:0;left:0;right:0;z-index:100000;background:#7c2d12;color:#fff;' +
      'font-size:13px;line-height:1.5;padding:10px 14px;display:flex;gap:12px;align-items:flex-start;' +
      'justify-content:center;flex-wrap:wrap;box-shadow:0 2px 8px rgba(0,0,0,.25);';
    bar.innerHTML =
      '<div style="max-width:900px">' +
        '<b>' + (missing.length > 1 ? 'Some modules are not installed' : names + ' is not installed') + '</b> — ' +
        names + (missing.length > 1 ? ' will not load' : ' will not load') + '. ' +
        'Ask your administrator to upload <b>' + files + '</b> to the same folder as <b>api.php</b> on the server.' +
      '</div>' +
      '<div style="display:flex;gap:8px">' +
        '<button type="button" id="ayan-modcheck-retry" style="cursor:pointer;border:1px solid rgba(255,255,255,.6);' +
          'background:transparent;color:#fff;border-radius:6px;padding:4px 10px;font-size:12px;font-weight:700">Re-check</button>' +
        '<button type="button" id="ayan-modcheck-hide" style="cursor:pointer;border:1px solid rgba(255,255,255,.6);' +
          'background:transparent;color:#fff;border-radius:6px;padding:4px 10px;font-size:12px">Dismiss</button>' +
      '</div>';
    D.body.appendChild(bar);
    D.getElementById('ayan-modcheck-retry').onclick = function(){ run(true); };
    D.getElementById('ayan-modcheck-hide').onclick = function(){
      try{ sessionStorage.setItem(DISMISS_KEY, '1'); }catch(e){}
      bar.parentNode.removeChild(bar);
    };
    try{ console.warn('[module check] missing on server: ' + files); }catch(e){}
  }

  async function run(force){
    if(!force){
      try{ if(sessionStorage.getItem(DISMISS_KEY) === '1') return []; }catch(e){}
    }
    var results = await Promise.all(MODULES.map(async function(m){
      return { file: m.file, label: m.label, state: await probe(m.file) };
    }));
    var missing = results.filter(function(r){ return r.state === 'missing'; });
    W.ERP_MODULE_STATUS = results.reduce(function(acc, r){ acc[r.file] = r.state; return acc; }, {});
    if(force){
      try{ sessionStorage.removeItem(DISMISS_KEY); }catch(e){}
      if(!missing.length && typeof W.toast === 'function') W.toast('All modules are installed on the server.', 's');
    }
    render(missing);
    return missing;
  }

  W.checkServerModules = function(){ return run(true); };

  function start(){ setTimeout(function(){ run(false); }, 1200); }
  if(D.readyState === 'loading') D.addEventListener('DOMContentLoaded', start);
  else start();
})();
</script>
<script nonce="<?php echo $cspNonceAttr; ?>" id="claude-feat-fiscalyear">
/* ═══════════════════════════════════════════════════════════════════════
   FEATURE — Fiscal Year Closing (previously Missing)
   Additive patch: locks transactions on/before a chosen date, snapshots
   closing balances, and rolls them forward as opening balances for the
   next period. Does not alter any existing function's behaviour when no
   year has been closed yet (isDateLocked() returns false until then).
   ═══════════════════════════════════════════════════════════════════════ */
(function(){
  'use strict';
  var W = window;

  function fyLockDate(){ return (W.DB && DB.settings && DB.settings.fyLockDate) || null; }
  W.isDateLocked = function(dateStr){
    var lock = fyLockDate();
    if(!lock || !dateStr) return false;
    return String(dateStr) <= String(lock);
  };

  // ── Guard: block edits/deletes to locked transactions ──
  var _prevSaveTx = W.saveTx;
  W.saveTx = function(){
    var date = (typeof v==='function') ? v('tx-date') : (document.getElementById('tx-date')||{}).value;
    if(W.isDateLocked(date)){
      if(typeof toast==='function') toast('🔒 '+date+' falls inside a closed fiscal year (locked through '+fyLockDate()+'). Reopen the year first to edit this date.','e');
      else alert('This date is inside a closed, locked fiscal year.');
      return;
    }
    var editId = parseInt((document.getElementById('tx-edit-id')||{}).value)||0;
    if(editId){
      var existing = ((W.DB&&DB.tx)||[]).find(function(t){return t.id===editId;});
      if(existing && W.isDateLocked(existing.date)){
        if(typeof toast==='function') toast('🔒 This transaction is inside a closed fiscal year and cannot be edited.','e');
        return;
      }
    }
    var batchNo = (typeof v==='function') ? v('tx-batchno') : '';
    var serialNo = (typeof v==='function') ? v('tx-serialno') : '';
    var result = _prevSaveTx.apply(this, arguments);
    try{
      if(batchNo || serialNo){
        var targetId = editId || ((DB.nid && DB.nid.tx) ? DB.nid.tx - 1 : null);
        var tx = targetId!=null ? (DB.tx||[]).find(function(t){return t.id===targetId;}) : null;
        if(tx){
          if(batchNo) tx.batchNo = batchNo;
          if(serialNo) tx.serialNo = serialNo;
          saveDB();
        }
      }
    }catch(e){ console.error('[batch/serial capture]', e); }
    return result;
  };

  var _prevDelTx = W.delTx;
  W.delTx = async function(id){
    var tx = ((W.DB&&DB.tx)||[]).find(function(t){return t.id===id;});
    if(tx && W.isDateLocked(tx.date)){
      if(typeof toast==='function') toast('🔒 Cannot delete — this transaction is inside a closed fiscal year.','e');
      return;
    }
    return _prevDelTx.apply(this, arguments);
  };

  // ── Core: close / reopen a fiscal year ──
  W.closeFiscalYear = function(yearEndDateStr, opts){
    opts = opts||{};
    DB.fiscalYearClosings = DB.fiscalYearClosings||[];
    var already = DB.fiscalYearClosings.find(function(c){return c.lockDate===yearEndDateStr;});
    if(already){ if(typeof toast==='function') toast('This exact date is already a closing point.','e'); return null; }

    var P = (typeof computePosition==='function') ? computePosition() : null;

    var snapshot = {
      customers: (DB.customers||[]).map(function(c){ return {name:c.name, type:c.type, bal:c.bal||0}; }),
      banks: (DB.banks||[]).map(function(b){ return {name:b.name, bal:b.bal||0}; }),
      partners: (DB.partners||[]).map(function(p){ return {name:p.name, cap:p.cap||0}; }),
      products: (DB.products||[]).map(function(p){
        var qty = (typeof W.stockQtyOf==='function') ? W.stockQtyOf(p) : (p.stockQty||0);
        var cost = (typeof W.unitCost==='function') ? W.unitCost(p) : (p.cost||0);
        return {name:p.name, qty:qty, cost:cost};
      }),
      netProfit: P ? P.netProfit : null,
      totalLeft: P ? P.totalLeft : null,
      totalRight: P ? P.totalRight : null
    };

    var closing = {
      id: (typeof newId==='function') ? newId() : Date.now(),
      year: opts.year || (new Date(yearEndDateStr)).getFullYear(),
      lockDate: yearEndDateStr,
      closedDate: new Date().toISOString(),
      closedBy: (W.currentUser && W.currentUser.name) || 'System',
      snapshot: snapshot,
      balanced: P ? Math.abs(P.totalLeft-P.totalRight)<1 : null
    };
    DB.fiscalYearClosings.push(closing);
    DB.settings = DB.settings||{};
    DB.settings.fyLockDate = yearEndDateStr;

    // Roll customer/supplier balances forward as opening balances for the next day
    var nextDate = new Date(yearEndDateStr+'T00:00:00');
    nextDate.setDate(nextDate.getDate()+1);
    var nextDateStr = nextDate.toISOString().split('T')[0];
    DB.openingBalances = DB.openingBalances||[];
    snapshot.customers.forEach(function(c){
      if(!c.bal) return;
      DB.openingBalances.push({party:c.name, amount:c.bal, date:nextDateStr,
        note:'Opening balance — rolled forward from fiscal year close on '+closing.lockDate});
    });

    saveDB();
    if(typeof logAudit==='function') logAudit('FISCAL YEAR CLOSE','Accounting',
      'Closed fiscal year through '+yearEndDateStr+(closing.balanced?' (Trial Balance matched)':' (⚠ Trial Balance mismatch at close time)'));
    if(typeof toast==='function') toast('✅ Fiscal year closed through '+yearEndDateStr,'s');
    return closing;
  };

  W.reopenFiscalYear = function(closingId){
    DB.fiscalYearClosings = DB.fiscalYearClosings||[];
    var idx = DB.fiscalYearClosings.findIndex(function(c){return c.id===closingId;});
    if(idx<0) return;
    var c = DB.fiscalYearClosings[idx];
    DB.fiscalYearClosings.splice(idx,1);
    var remaining = DB.fiscalYearClosings.slice().sort(function(a,b){return a.lockDate<b.lockDate?1:-1;});
    DB.settings = DB.settings||{};
    DB.settings.fyLockDate = remaining.length ? remaining[0].lockDate : null;
    saveDB();
    if(typeof logAudit==='function') logAudit('FISCAL YEAR REOPEN','Accounting','Reopened fiscal year that had been locked through '+c.lockDate);
    if(typeof toast==='function') toast('🔓 Fiscal year reopened — transactions on or before '+c.lockDate+' are editable again.','s');
  };

  // ── Page render ──
  W.renderFiscalYearClose = function(){
    var el = document.getElementById('pg-fiscalyearclose');
    if(!el) return;
    var closings = (DB.fiscalYearClosings||[]).slice().sort(function(a,b){return a.lockDate<b.lockDate?1:-1;});
    var lock = fyLockDate();
    var P = (typeof computePosition==='function') ? computePosition() : {totalLeft:0,totalRight:0};
    var balanced = Math.abs((P.totalLeft||0)-(P.totalRight||0))<1;
    el.innerHTML =
      '<div style="padding:20px;max-width:920px;">' +
      '<h2 style="font-size:20px;font-weight:800;color:#0f3d26;margin:0 0 4px;">🔒 Fiscal Year Closing</h2>' +
      '<div style="font-size:12px;color:#6b7280;margin-bottom:16px;">Lock every transaction dated on or before a cut-off date and roll party balances forward as opening balances for the next period.</div>' +
      '<div style="background:'+(balanced?'#f0fdf4':'#fef2f2')+';border:1.5px solid '+(balanced?'#86efac':'#fecaca')+';border-radius:10px;padding:14px;margin-bottom:16px;">' +
        '<div style="font-weight:700;color:'+(balanced?'#15803d':'#991b1b')+';font-size:13px;">'+(balanced?'✅ Trial Balance is currently matched':'⚠️ Trial Balance is currently mismatched — closing now will lock in the imbalance. Consider fixing it first (see Balance Sheet page for suspect accounts).')+'</div>' +
        '<div style="font-size:11px;color:#6b7280;margin-top:4px;">Left: ৳'+((P.totalLeft||0).toLocaleString('en-IN'))+' &nbsp;·&nbsp; Right: ৳'+((P.totalRight||0).toLocaleString('en-IN'))+'</div>' +
      '</div>' +
      '<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:16px;margin-bottom:20px;">' +
        '<div style="font-weight:700;font-size:13px;margin-bottom:8px;">Close a Fiscal Year</div>' +
        (lock?('<div style="font-size:12px;color:#dc2626;margin-bottom:8px;">Currently locked through <strong>'+lock+'</strong>. Pick a later date to close the next period.</div>'):'') +
        '<div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;">' +
          '<label style="font-size:12px;color:#374151;">Close through:</label>' +
          '<input type="date" id="fyc-end-date" style="padding:8px 12px;border:1.5px solid #d1d5db;border-radius:8px;font-size:13px;"/>' +
          '<button data-x-click="fycConfirmClose()" style="padding:8px 16px;background:#dc2626;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:12px;">🔒 Close Year</button>' +
        '</div>' +
        '<div style="font-size:11px;color:#9ca3af;margin-top:8px;">Locked transactions can no longer be edited or deleted through the normal forms until the year is reopened.</div>' +
      '</div>' +
      '<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:16px;">' +
        '<div style="font-weight:700;font-size:13px;margin-bottom:10px;">Closing History</div>' +
        (closings.length===0 ? '<div style="font-size:12px;color:#9ca3af;">No fiscal years closed yet.</div>' :
        ('<table style="width:100%;border-collapse:collapse;font-size:12px;">' +
          '<tr style="text-align:left;color:#6b7280;border-bottom:1px solid #e5e7eb;"><th style="padding:6px;">Locked Through</th><th>Closed On</th><th>By</th><th>Trial Balance</th><th></th></tr>' +
          closings.map(function(c){ return '<tr style="border-bottom:1px solid #f3f4f6;">' +
            '<td style="padding:6px;font-weight:700;">'+c.lockDate+'</td>' +
            '<td>'+(new Date(c.closedDate)).toLocaleDateString()+'</td>' +
            '<td>'+c.closedBy+'</td>' +
            '<td>'+(c.balanced?'✅ Matched':'⚠️ Mismatched')+'</td>' +
            '<td><button data-x-click="fycReopen('+JSON.stringify(c.id)+')" style="padding:4px 10px;background:#f3f4f6;border:1px solid #d1d5db;border-radius:6px;font-size:11px;cursor:pointer;">🔓 Reopen</button></td>' +
          '</tr>'; }).join('') +
        '</table>')) +
      '</div></div>';
  };

  W.fycConfirmClose = async function(){
    var d = (document.getElementById('fyc-end-date')||{}).value;
    if(!d){ toast('Pick a closing date first','e'); return; }
    var lock = fyLockDate();
    if(lock && d<=lock){ toast('Must be after the current lock date ('+lock+')','e'); return; }
    var ok = (typeof __confirm==='function') ? await __confirm('Close the fiscal year through '+d+'? Every transaction on or before this date will be locked.') : confirm('Close the fiscal year through '+d+'?');
    if(!ok) return;
    W.closeFiscalYear(d);
    W.renderFiscalYearClose();
  };

  W.fycReopen = async function(id){
    var ok = (typeof __confirm==='function') ? await __confirm('Reopen this fiscal year? Its locked transactions become editable again.') : confirm('Reopen this fiscal year?');
    if(!ok) return;
    W.reopenFiscalYear(id);
    W.renderFiscalYearClose();
  };

  console.info('[Claude] Fiscal Year Closing feature loaded.');
})();
</script>

<script nonce="<?php echo $cspNonceAttr; ?>" id="claude-feat-trialbalance-diagnostics">
/* ═══════════════════════════════════════════════════════════════════════
   FEATURE — Trial Balance mismatch diagnostics ("suggest specific accounts
   causing imbalance") + Balance Sheet "Net Worth" trend chart.
   Both are additive: wraps renderBS() and appends after the original runs.
   ═══════════════════════════════════════════════════════════════════════ */
(function(){
  'use strict';
  var W = window;

  function diagnoseImbalance(P){
    // Reuse the Position snapshot renderBS() just computed (same render pass)
    // instead of recomputing the whole Trial Balance a second time.
    if(!P) P = window.__ayanLastBSPosition || ((typeof computePosition==='function') ? computePosition() : null);
    if(!P) return [];
    var diff = P.totalLeft - P.totalRight;
    if(Math.abs(diff) < 1) return [];

    var suspects = [];
    var knownTypes = {};
    ['INV_IN_TYPES','INV_OUT_TYPES','EXPENSE_TX_TYPES','OTHER_INCOME_TX_TYPES'].forEach(function(g){
      try{ (W[g]||new Set()).forEach(function(t){ knownTypes[t]=true; }); }catch(e){}
    });
    ['Sale','Customer Sale','Warehouse Sale','Purchase','Supplier Purchase','Cash Received','Cash Payment','Journal Entry'].forEach(function(t){ knownTypes[t]=true; });
    /* FIX (false positives): types like "Bkash Receive" or "Customer
       Collection" are legitimate money movements — they correctly post to
       a bank/party balance and deliberately never touch revenue, expense,
       or stock. They were being flagged as "unclassified" even though
       nothing about them is actually missing from any total. This is the
       same recognized-type list applyTxBalance() already uses to move
       money correctly, so anything on it is known-safe here too. */
    ['Sales Receipt','Customer Collection','Customer Payment Received','Sales Advance','Advance from Customer',
     'Sales Return','Customer Due','Supplier Due','Purchase Payment','Supplier Payment','Purchase Advance',
     'Advance to Supplier','Supplier Advance','Purchase Return','Supplier Refund','Bank Deposit','Bank Withdrawal',
     'Bank Transfer','Inter Transfer','Inter Bank Transfer','Inter-Account Transfer','Transfer (Internal)','Transfer',
     'Bank Charge','Bkash Deposit','Bkash Receive','Bkash Receive from Agent','Bkash Withdrawal','Bkash Cash Out',
     'Bkash Payment Paid','Bkash Transfer','Partner Capital','Partner Fund','Opening Partner Fund',
     'Partner Withdrawal','Partner Profit Share','Employee Advance','Employee Loan','Opening Balance',
     'Opening Bank Balance','Fixed Asset Purchase','Asset Sale','Other Income','Interest Income'
    ].forEach(function(t){ knownTypes[t]=true; });

    var unclassified = {};
    (DB.tx||[]).forEach(function(t){
      var ty = (typeof W.normTxType==='function') ? W.normTxType(t.type) : t.type;
      if(ty && !knownTypes[ty]) unclassified[ty] = (unclassified[ty]||0) + 1;
    });
    Object.keys(unclassified).forEach(function(ty){
      suspects.push('Transaction type "'+ty+'" ('+unclassified[ty]+' record'+(unclassified[ty]>1?'s':'')+') is not mapped to any revenue, expense or stock category — its amount may be missing from the totals.');
    });

    (DB.products||[]).forEach(function(p){
      var q = (typeof W.stockQtyOf==='function') ? W.stockQtyOf(p) : (p.stockQty||0);
      if(q<0) suspects.push('Product "'+p.name+'" shows negative stock ('+q+') — check purchase/sale quantities for this item.');
    });

    var txParties = {};
    (DB.tx||[]).forEach(function(t){ if(t.party) txParties[String(t.party).toLowerCase()]=true; });
    /* FIX (false positives): a party's balance can legitimately come from
       DB.openingBalances instead of a DB.tx row — that's exactly how Sorna,
       Progati, Majumder Agro Tech, and Sobus's balances are recorded here.
       Checking DB.tx alone made every opening-balance-only party look like
       an "unrecorded" figure when it was fully accounted for. */
    (DB.openingBalances||[]).forEach(function(o){ if(o.party) txParties[String(o.party).toLowerCase()]=true; });
    (DB.customers||[]).forEach(function(c){
      if((c.bal||0)!==0 && !txParties[String(c.name||'').toLowerCase()]){
        suspects.push('Party "'+c.name+'" carries a balance of ৳'+Math.abs(c.bal).toLocaleString('en-IN')+' with no matching transactions — likely an unrecorded/duplicated opening balance.');
      }
    });

    var txBanks = {};
    (DB.tx||[]).forEach(function(t){ var b=t.bank||t.acc; if(b) txBanks[String(b).toLowerCase()]=true; });
    (DB.banks||[]).forEach(function(b){
      if((b.bal||0)!==0 && !txBanks[String(b.name||'').toLowerCase()]){
        suspects.push('Bank account "'+b.name+'" carries a balance of ৳'+Math.abs(b.bal).toLocaleString('en-IN')+' with no linked transactions.');
      }
    });

    /* FIX (2026-08-25): Partner Capital is added to the Left side in full,
       unconditionally, the same way Bank Balance is added to the Right
       side in full — but only banks were ever cross-checked against
       DB.tx. A partner's capital figure typed or adjusted directly (no
       matching "Partner Capital"/"Partner Fund"/"Opening Partner Fund"
       transaction moving that money into an actual bank/cash account)
       inflates Left with nothing on Right to match it — the same failure
       mode as an unlinked bank balance, just on the opposite side, and
       one this function never checked for. Unlike the bank case this is
       NOT auto-added anywhere in computePosition(): whether that money
       genuinely exists is exactly what needs verifying by a human before
       any total is adjusted for it, so this only surfaces it. */
    var partnerTxTypes = {'partner capital':true,'partner fund':true,'opening partner fund':true};
    var txPartners = {};
    (DB.tx||[]).forEach(function(t){
      var ty = String((t&&t.type)||'').trim().toLowerCase();
      if(t.party && partnerTxTypes[ty]) txPartners[String(t.party).toLowerCase()]=true;
    });
    (DB.partners||[]).forEach(function(p){
      if((p.cap||0)!==0 && !txPartners[String(p.name||'').toLowerCase()]){
        suspects.push('Partner "'+p.name+'" carries capital of ৳'+Math.abs(p.cap).toLocaleString('en-IN')+' with no linked "Partner Capital" transaction — verify that money actually moved into a bank/cash account, and record it as one if so.');
      }
    });

    /* FIX: a Fixed Asset is added to the Right side in full, unconditionally
       — the same treatment as Bank Balance — but was never cross-checked
       against DB.tx either. An asset entered directly in the register with
       no linked "Fixed Asset Purchase"/"Opening Fixed Asset" transaction
       inflates Right with nothing on Left funding it. */
    var assetTxTypes = {'fixed asset purchase':true,'opening fixed asset':true};
    var txAssetNames = {};
    (DB.tx||[]).forEach(function(t){
      var ty = String((t&&t.type)||'').trim().toLowerCase();
      if(assetTxTypes[ty]){
        if(t.party) txAssetNames[String(t.party).toLowerCase()]=true;
        if(t.assetName) txAssetNames[String(t.assetName).toLowerCase()]=true;
      }
    });
    (DB.assets||[]).forEach(function(a){
      var nm = a.name||a.assetName||'';
      if((a.val||0)!==0 && nm && !txAssetNames[String(nm).toLowerCase()]){
        suspects.push('Fixed asset "'+nm+'" carries a value of ৳'+Math.abs(a.val).toLocaleString('en-IN')+' with no linked purchase transaction — verify how it was funded.');
      }
    });

    return suspects;
  }

  function buildMonthlyNetWorthTrend(){
    var txs = (DB.tx||[]).filter(function(t){return t.date;}).slice().sort(function(a,b){return a.date<b.date?-1:1;});
    if(!txs.length) return {labels:[], values:[]};
    var firstMonth = txs[0].date.slice(0,7);
    var lastMonth = new Date().toISOString().slice(0,7);
    var months = [];
    var cur = firstMonth;
    while(cur <= lastMonth && months.length < 36){
      months.push(cur);
      var d = new Date(cur+'-01T00:00:00'); d.setMonth(d.getMonth()+1);
      cur = d.toISOString().slice(0,7);
    }
    // Starting net worth = partner capital only (before any transactions)
    var startingCapital = (DB.partners||[]).reduce(function(a,p){return a+(p.cap||0);},0);
    var running = startingCapital;
    var values = [], labels = [];
    months.forEach(function(m){
      var monthTxs = txs.filter(function(t){return t.date.slice(0,7)===m;});
      var sales = (typeof W.sumRevenue==='function') ? W.sumRevenue(monthTxs) : 0;
      var otherInc = (W.OTHER_INCOME_TX_TYPES ? monthTxs.filter(function(t){return W.OTHER_INCOME_TX_TYPES.has((typeof W.normTxType==='function'?W.normTxType(t.type):t.type));}).reduce(function(a,t){return a+(typeof W.txAmt==='function'?W.txAmt(t):(t.amt||0));},0) : 0);
      var cogs = (typeof W.computeCOGS==='function') ? W.computeCOGS(monthTxs) : 0;
      var exp = (W.EXPENSE_TX_TYPES ? monthTxs.filter(function(t){return W.EXPENSE_TX_TYPES.has((typeof W.normTxType==='function'?W.normTxType(t.type):t.type));}).reduce(function(a,t){return a+(typeof W.txAmt==='function'?W.txAmt(t):(t.amt||0));},0) : 0);
      var monthProfit = sales + otherInc - cogs - exp;
      running += monthProfit;
      labels.push(m);
      values.push(Math.round(running));
    });
    return {labels:labels, values:values};
  }

  var _prevRenderBS = W.renderBS;
  W.renderBS = function(){
    var r = _prevRenderBS.apply(this, arguments);
    try{
      var diffAction = document.getElementById('tb-diff-action');
      if(diffAction){
        var suspects = diagnoseImbalance(window.__ayanLastBSPosition);
        if(suspects.length){
          diffAction.innerHTML += '<div style="margin-top:10px;padding-top:10px;border-top:1px dashed #fca5a5;">' +
            '<strong>🔎 Likely accounts causing the mismatch:</strong>' +
            '<ul style="margin:6px 0 0 18px;padding:0;">' +
            suspects.slice(0,8).map(function(s){return '<li style="margin-bottom:4px;">'+s+'</li>';}).join('') +
            '</ul></div>';
        }
      }
    }catch(e){ console.error('[trial balance diagnostics]', e); }

    try{
      if(typeof Chart!=='undefined' && document.getElementById('cNetWorthTrend')){
        var trend = buildMonthlyNetWorthTrend();
        var canvas = document.getElementById('cNetWorthTrend');
        if(W.__netWorthChartInstance){ try{ W.__netWorthChartInstance.destroy(); }catch(e){} }
        W.__netWorthChartInstance = new Chart(canvas, {
          type:'line',
          data:{ labels: trend.labels, datasets:[{ label:'Net Worth (cumulative retained profit)', data: trend.values,
            borderColor:'#16a34a', backgroundColor:'rgba(22,163,74,.12)', fill:true, tension:.3, pointRadius:2 }] },
          options:{ plugins:{legend:{display:false}}, scales:{ y:{ ticks:{ callback:function(v){ return '৳'+(v/100000).toFixed(1)+'L'; } } } } }
        });
      }
    }catch(e){ console.error('[net worth trend chart]', e); }

    return r;
  };

  console.info('[Claude] Trial Balance diagnostics + Net Worth trend chart loaded.');
})();
</script>

<script nonce="<?php echo $cspNonceAttr; ?>" id="claude-feat-valuation">
/* ═══════════════════════════════════════════════════════════════════════
   FEATURE — Inventory Valuation Method (FIFO / LIFO / Weighted Average)
   Additive: wraps window.cogsByProduct so every screen that already calls
   computeCOGS() (P&L, Balance Sheet, dashboards, product P&L, etc.)
   automatically recalculates using whichever method is chosen in Settings,
   with Weighted Average remaining the default (unchanged) behaviour.

   FEATURE — Multi-currency exchange rates editable in Settings, applied
   everywhere currencyConvert()/formatCurrency() are used.
   ═══════════════════════════════════════════════════════════════════════ */
(function(){
  'use strict';
  var W = window;

  // ── FIFO / LIFO costing engine ──
  W.computeCOGS_LayeredMethod = function(txList, method){
    var txs = (txList||[]).filter(function(t){return t && t.date;});
    var byProduct = {};
    txs.forEach(function(t){
      var k = W.txProduct(t) || 'Unknown';
      if(!byProduct[k]) byProduct[k] = {purchases:[], sales:[]};
      if(W.isCogsTx(t)){
        byProduct[k].purchases.push({date:t.date, qty:W.txQty(t), amt:W.txAmt(t)});
      } else if(W.isRevenueTx(t)){
        byProduct[k].sales.push({date:t.date, qty:W.txQty(t), amt:W.txAmt(t)});
      }
    });

    var map = {};
    Object.keys(byProduct).forEach(function(k){
      var data = byProduct[k];
      var layers = data.purchases
        .filter(function(p){ return p.qty > 0; })
        .map(function(p){ return {date:p.date, qtyRemaining:p.qty, cost: p.amt/p.qty}; })
        .sort(function(a,b){ return a.date<b.date?-1:(a.date>b.date?1:0); });
      if(method==='LIFO') layers.reverse();

      var totalSoldQty  = data.sales.reduce(function(s,x){return s+x.qty;},0);
      var totalSaleAmt  = data.sales.reduce(function(s,x){return s+x.amt;},0);
      var totalPurchQty = data.purchases.reduce(function(s,x){return s+x.qty;},0);
      var totalPurchAmt = data.purchases.reduce(function(s,x){return s+x.amt;},0);

      var remaining = totalSoldQty, cogs = 0;
      for(var i=0; i<layers.length && remaining>0.0001; i++){
        var take = Math.min(layers[i].qtyRemaining, remaining);
        cogs += take * layers[i].cost;
        remaining -= take;
      }
      // Sold more than tracked purchase history (e.g. legacy opening stock):
      // fall back to the same "never exceed total purchase amount" cap the
      // original weighted-average logic used, so this never overstates COGS.
      if(remaining > 0.0001 && totalPurchQty>0){
        var avgCost = totalPurchAmt/totalPurchQty;
        cogs += remaining*avgCost;
      }
      cogs = Math.min(cogs, totalSaleAmt>0 ? Math.max(cogs, Math.min(totalPurchAmt, cogs)) : cogs);
      cogs = Math.min(cogs, totalPurchAmt||cogs);

      map[k] = {
        purchAmt: totalPurchAmt, purchQty: totalPurchQty,
        soldQty: totalSoldQty, saleAmt: totalSaleAmt,
        avgCost: totalPurchQty>0 ? totalPurchAmt/totalPurchQty : 0,
        cogs: cogs
      };
    });
    return map;
  };

  var _prevCogsByProduct = W.cogsByProduct;
  W.cogsByProduct = function(txList){
    var method = (W.DB && DB.settings && DB.settings.valuationMethod) || 'WAC';
    if(method==='FIFO' || method==='LIFO'){
      try{ return W.computeCOGS_LayeredMethod(txList, method); }
      catch(e){ console.error('[valuation] FIFO/LIFO costing failed, falling back to Weighted Average', e); }
    }
    return _prevCogsByProduct.apply(this, arguments);
  };

  // ── Editable exchange rates: DB.settings.exchangeRates overrides the
  //    hardcoded EXCHANGE_RATES table wherever currencyConvert() is used ──
  var _prevCurrencyConvert = W.currencyConvert;
  W.currencyConvert = function(amount, from, to){
    var custom = (W.DB && DB.settings && DB.settings.exchangeRates) || null;
    if(custom){
      from = from||'BDT'; to = to||'BDT';
      var rates = Object.assign({}, W.EXCHANGE_RATES||{}, custom);
      var inBDT = amount * (rates[from]||1);
      return inBDT / (rates[to]||1);
    }
    return _prevCurrencyConvert.apply(this, arguments);
  };

  // ── Settings panel: valuation method + exchange rates ──
  var _prevRenderSettings = W.renderSettings;
  W.renderSettings = function(){
    var r = _prevRenderSettings.apply(this, arguments);
    try{
      var body = document.getElementById('settings-body');
      if(!body || document.getElementById('claude-valuation-card')) return r;
      var s = DB.settings||{};
      var method = s.valuationMethod || 'WAC';
      var rates = Object.assign({}, W.EXCHANGE_RATES||{}, s.exchangeRates||{});
      var card = document.createElement('div');
      card.id = 'claude-valuation-card';
      card.style.cssText = 'background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;margin-top:16px;';
      card.innerHTML =
        '<div style="background:linear-gradient(90deg,#0f3d26,#16a34a);color:#fff;padding:12px 16px;font-weight:700;font-size:13px;">🧮 Inventory Valuation & Currency</div>' +
        '<div style="padding:16px;">' +
          '<label style="font-size:11px;font-weight:600;color:#374151;display:block;margin-bottom:4px;">Inventory Valuation Method</label>' +
          '<select id="claude-valuation-method" style="width:100%;padding:7px 10px;border:1px solid #d1d5db;border-radius:5px;font-size:12px;margin-bottom:6px;">' +
            ['WAC','FIFO','LIFO'].map(function(m){ return '<option value="'+m+'"'+(m===method?' selected':'')+'>'+
              (m==='WAC'?'Weighted Average Cost (default)':m==='FIFO'?'FIFO — First In, First Out':'LIFO — Last In, First Out')+'</option>'; }).join('') +
          '</select>' +
          '<div style="font-size:10.5px;color:#9ca3af;margin-bottom:14px;">Changing this recalculates COGS on every report that reads computeCOGS() — Profit & Loss, Balance Sheet, product-level profit, dashboards.</div>' +
          '<label style="font-size:11px;font-weight:600;color:#374151;display:block;margin-bottom:4px;">Exchange Rates (per 1 BDT)</label>' +
          '<div id="claude-fx-rows" style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:8px;">' +
            Object.keys(rates).filter(function(c){return c!=='BDT';}).map(function(c){
              return '<div style="display:flex;align-items:center;gap:6px;">' +
                '<span style="font-size:12px;font-weight:600;width:44px;">'+c+'</span>' +
                '<input type="number" step="0.01" class="claude-fx-input" data-cur="'+c+'" value="'+rates[c]+'" style="flex:1;padding:6px 8px;border:1px solid #d1d5db;border-radius:5px;font-size:12px;"/>' +
              '</div>';
            }).join('') +
          '</div>' +
          '<button data-x-click="claudeSaveValuationSettings()" style="width:100%;padding:9px;background:#16a34a;color:#fff;border:none;border-radius:7px;font-size:12px;font-weight:700;cursor:pointer;">💾 Save Valuation & Currency Settings</button>' +
        '</div>';
      body.appendChild(card);
    }catch(e){ console.error('[valuation settings panel]', e); }
    return r;
  };

  W.claudeSaveValuationSettings = function(){
    DB.settings = DB.settings||{};
    var methodEl = document.getElementById('claude-valuation-method');
    if(methodEl) DB.settings.valuationMethod = methodEl.value;
    var rates = {};
    document.querySelectorAll('.claude-fx-input').forEach(function(inp){
      rates[inp.getAttribute('data-cur')] = parseFloat(inp.value)||1;
    });
    DB.settings.exchangeRates = rates;
    saveDB();
    if(typeof logAudit==='function') logAudit('SETTINGS','Valuation','Updated inventory valuation method to '+DB.settings.valuationMethod+' and exchange rates.');
    if(typeof toast==='function') toast('✅ Valuation & currency settings saved','s');
    try{
      // Refresh any currently-open report that depends on COGS/currency
      if(document.getElementById('pg-balancesheet') && document.getElementById('pg-balancesheet').classList.contains('active')) renderBS();
      if(document.getElementById('pg-reports') && document.getElementById('pg-reports').classList.contains('active')) renderPL();
    }catch(e){}
  };

  console.info('[Claude] Inventory valuation (FIFO/LIFO/WAC) + editable exchange rates loaded.');
})();
</script>

<script nonce="<?php echo $cspNonceAttr; ?>" id="claude-feat-batchserial-physicalcount">
/* ═══════════════════════════════════════════════════════════════════════
   FEATURE — Batch / Serial Number Tracking (previously Missing/stub)
   Product master gets an optional batchTracking flag; the transaction form
   already captures Batch No / Serial No (see claude-feat-fiscalyear patch,
   which stores tx.batchNo / tx.serialNo). This page turns that into a real
   batch register: enable tracking per product, and see remaining quantity
   per batch (purchased minus sold/adjusted for that exact batch number).

   FEATURE — Physical Count / Cycle Counting (previously Missing)
   Generates a count sheet from current book stock, lets the user enter
   counted quantities, and posts the variance as real stock adjustments
   using the existing DB.stockAdjustments mechanism (saveStockAdj's data
   model), so it plugs into all reports/audit trail that already exist.
   ═══════════════════════════════════════════════════════════════════════ */
(function(){
  'use strict';
  var W = window;

  // ── Batch/Serial: toggle tracking per product ──
  W.claudeToggleBatchTracking = function(productName, on){
    var item = (typeof invFind==='function') ? invFind(productName) : null;
    if(!item) return;
    item.batchTracking = !!on;
    saveDB();
    if(typeof logAudit==='function') logAudit('SETTINGS','Batch Tracking',(on?'Enabled':'Disabled')+' batch/serial tracking for '+productName);
    W.renderBatchSerial();
  };

  function batchRegisterForProduct(productName){
    var txs = (DB.tx||[]).filter(function(t){
      return (t.prod||t.product) && String(t.prod||t.product).trim().toLowerCase()===String(productName).trim().toLowerCase() && (t.batchNo||t.serialNo);
    });
    var byBatch = {};
    txs.forEach(function(t){
      var key = t.batchNo || t.serialNo;
      if(!byBatch[key]) byBatch[key] = {batch:key, serial:t.serialNo||null, inQty:0, outQty:0, firstDate:t.date, lastDate:t.date};
      var qty = W.txQty(t);
      if(W.isCogsTx(t)) byBatch[key].inQty += qty;
      else if(W.isRevenueTx(t)) byBatch[key].outQty += qty;
      if(t.date < byBatch[key].firstDate) byBatch[key].firstDate = t.date;
      if(t.date > byBatch[key].lastDate) byBatch[key].lastDate = t.date;
    });
    return Object.keys(byBatch).map(function(k){
      var b = byBatch[k];
      b.remaining = Math.max(0, b.inQty - b.outQty);
      return b;
    }).sort(function(a,b){ return a.firstDate<b.firstDate?1:-1; });
  }

  W.renderBatchSerial = function(){
    var el = document.getElementById('pg-batchserial');
    if(!el) return;
    var products = (typeof invItems==='function') ? invItems() : (DB.products||[]);
    var selected = el.getAttribute('data-selected-product') || (products[0]&&products[0].name) || '';

    var html = '<div style="padding:20px;">' +
      '<h2 style="font-size:20px;font-weight:800;color:#0f3d26;margin:0 0 4px;">🔖 Batch / Serial Tracking</h2>' +
      '<div style="font-size:12px;color:#6b7280;margin-bottom:16px;">Enable per product, then capture a Batch No or Serial No on the Batch No / Serial No fields when entering purchases and sales for that product.</div>' +
      '<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:14px;margin-bottom:16px;">' +
      '<table style="width:100%;border-collapse:collapse;font-size:12px;">' +
        '<tr style="text-align:left;color:#6b7280;border-bottom:1px solid #e5e7eb;"><th style="padding:6px;">Product</th><th>Tracking Enabled</th><th>Active Batches</th></tr>' +
        products.map(function(p){
          var reg = batchRegisterForProduct(p.name);
          var activeBatches = reg.filter(function(b){return b.remaining>0.001;}).length;
          return '<tr style="border-bottom:1px solid #f3f4f6;cursor:pointer;" data-x-click="claudeShowBatchDetail('+JSON.stringify(p.name)+')">' +
            '<td style="padding:6px;font-weight:600;">'+p.name+'</td>' +
            '<td><input type="checkbox" data-x-click="xBatchTrackingToggle('+JSON.stringify(p.name)+',this)" '+(p.batchTracking?'checked':'')+'/></td>' +
            '<td>'+activeBatches+'</td>' +
          '</tr>';
        }).join('') +
      '</table></div>' +
      '<div id="claude-batch-detail" style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:14px;"></div>' +
      '</div>';
    el.innerHTML = html;
    if(selected) W.claudeShowBatchDetail(selected);
  };

  W.claudeShowBatchDetail = function(productName){
    var el = document.getElementById('pg-batchserial');
    if(el) el.setAttribute('data-selected-product', productName);
    var detail = document.getElementById('claude-batch-detail');
    if(!detail) return;
    var reg = batchRegisterForProduct(productName);
    detail.innerHTML = '<div style="font-weight:700;font-size:13px;margin-bottom:10px;">📦 Batches — '+productName+'</div>' +
      (reg.length===0 ? '<div style="font-size:12px;color:#9ca3af;">No batch/serial numbers recorded yet for this product. Enter one in the Batch No / Serial No field next time you save a purchase or sale for it.</div>' :
      '<table style="width:100%;border-collapse:collapse;font-size:12px;">' +
        '<tr style="text-align:left;color:#6b7280;border-bottom:1px solid #e5e7eb;"><th style="padding:6px;">Batch/Serial</th><th>Received</th><th>Sold/Used</th><th>Remaining</th><th>First Seen</th><th>Last Seen</th></tr>' +
        reg.map(function(b){ return '<tr style="border-bottom:1px solid #f3f4f6;'+(b.remaining<=0.001?'color:#9ca3af;':'')+'">' +
          '<td style="padding:6px;font-weight:600;">'+b.batch+'</td>' +
          '<td>'+b.inQty+'</td><td>'+b.outQty+'</td>' +
          '<td style="font-weight:700;'+(b.remaining>0?'color:#16a34a;':'')+'">'+b.remaining+'</td>' +
          '<td>'+b.firstDate+'</td><td>'+b.lastDate+'</td>' +
        '</tr>'; }).join('') +
      '</table>');
  };

  // ── Physical Count / Cycle Counting ──
  W.renderPhysicalCount = function(){
    var el = document.getElementById('pg-physicalcount');
    if(!el) return;
    var products = (typeof invItems==='function') ? invItems() : (DB.products||[]);
    el.innerHTML = '<div style="padding:20px;">' +
      '<h2 style="font-size:20px;font-weight:800;color:#0f3d26;margin:0 0 4px;">🧮 Physical Count</h2>' +
      '<div style="font-size:12px;color:#6b7280;margin-bottom:16px;">Generate a count sheet from book stock, enter what you actually counted, then post the variance as stock adjustments in one click.</div>' +
      '<div style="display:flex;gap:10px;margin-bottom:14px;">' +
        '<button data-x-click="claudeGenerateCountSheet()" style="padding:8px 16px;background:#2563eb;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:12px;">📋 Generate Count Sheet</button>' +
        '<button data-x-click="claudePostCountVariances()" style="padding:8px 16px;background:#16a34a;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:12px;">✅ Post Variances as Stock Adjustments</button>' +
      '</div>' +
      '<div id="claude-count-sheet-wrap" style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:14px;"><div style="font-size:12px;color:#9ca3af;">Click "Generate Count Sheet" to start.</div></div>' +
      '</div>';
  };

  W.claudeGenerateCountSheet = function(){
    var products = (typeof invItems==='function') ? invItems() : (DB.products||[]);
    var wrap = document.getElementById('claude-count-sheet-wrap');
    if(!wrap) return;
    wrap.innerHTML = '<table style="width:100%;border-collapse:collapse;font-size:12px;">' +
      '<tr style="text-align:left;color:#6b7280;border-bottom:1px solid #e5e7eb;"><th style="padding:6px;">Product</th><th>Book Qty</th><th>Counted Qty</th><th>Variance</th></tr>' +
      products.map(function(p){
        var bookQty = W.stockQtyOf ? W.stockQtyOf(p) : (p.stockQty||0);
        return '<tr style="border-bottom:1px solid #f3f4f6;" data-product="'+p.name.replace(/"/g,'&quot;')+'" data-book="'+bookQty+'">' +
          '<td style="padding:6px;font-weight:600;">'+p.name+'</td>' +
          '<td>'+bookQty+'</td>' +
          '<td><input type="number" step="0.01" class="claude-count-input" placeholder="Enter count" style="width:110px;padding:5px 8px;border:1px solid #d1d5db;border-radius:5px;font-size:12px;" data-x-input="claudeUpdateVarianceCell(this)"/></td>' +
          '<td class="claude-variance-cell" style="font-weight:700;">—</td>' +
        '</tr>';
      }).join('') +
      '</table>';
  };

  W.claudeUpdateVarianceCell = function(input){
    var row = input.closest('tr');
    var book = parseFloat(row.getAttribute('data-book'))||0;
    var counted = parseFloat(input.value);
    var cell = row.querySelector('.claude-variance-cell');
    if(isNaN(counted)){ cell.textContent = '—'; cell.style.color=''; return; }
    var diff = counted - book;
    cell.textContent = (diff>0?'+':'')+diff;
    cell.style.color = diff===0 ? '#6b7280' : (diff>0 ? '#16a34a' : '#dc2626');
  };

  W.claudePostCountVariances = async function(){
    var rows = Array.prototype.slice.call(document.querySelectorAll('#claude-count-sheet-wrap tr[data-product]'));
    var toPost = [];
    rows.forEach(function(row){
      var input = row.querySelector('.claude-count-input');
      if(!input || input.value==='') return;
      var book = parseFloat(row.getAttribute('data-book'))||0;
      var counted = parseFloat(input.value);
      if(isNaN(counted) || counted===book) return;
      toPost.push({product: row.getAttribute('data-product'), book:book, counted:counted, diff: counted-book});
    });
    if(!toPost.length){ toast('No variances entered — nothing to post.','w'); return; }
    var ok = (typeof __confirm==='function') ? await __confirm('Post '+toPost.length+' stock adjustment(s) from this physical count?') : confirm('Post '+toPost.length+' stock adjustment(s)?');
    if(!ok) return;

    DB.stockAdjustments = DB.stockAdjustments||[];
    var today = new Date().toISOString().split('T')[0];
    toPost.forEach(function(v){
      DB.stockAdjustments.unshift({
        id: newId(), date: today, product: v.product,
        qty: Math.abs(v.diff), adjType: v.diff>0 ? 'add' : 'remove',
        reason: 'Physical Count', notes: 'Book: '+v.book+' → Counted: '+v.counted,
        createdAt: new Date().toISOString()
      });
      var item = (typeof invFind==='function') ? invFind(v.product) : null;
      if(item) invSetQty(item, v.counted);
    });
    saveDB();
    if(typeof logAudit==='function') logAudit('STOCK','Physical Count','Posted '+toPost.length+' variance adjustment(s) from physical count');
    toast('✅ '+toPost.length+' variance(s) posted as stock adjustments','s');
    try{ renderStockAdj(); }catch(e){}
    W.claudeGenerateCountSheet();
  };

  console.info('[Claude] Batch/Serial Tracking + Physical Count modules loaded.');
})();
</script>

<script nonce="<?php echo $cspNonceAttr; ?>" id="claude-feat-bank-automatch">
/* ═══════════════════════════════════════════════════════════════════════
   FEATURE — Bank Reconciliation Auto-Match (previously manual only)
   Parses an uploaded bank statement CSV (same column-detection logic as
   the existing importBankCSV) but, instead of blindly inserting every row
   as a new transaction, first searches DB.tx for a likely existing match
   by amount (± tolerance) and date (± a few days window), so genuinely
   new items get imported and already-recorded ones get skipped instead
   of duplicated.
   ═══════════════════════════════════════════════════════════════════════ */
(function(){
  'use strict';
  var W = window;

  function parseBankCSV(csvText){
    var lines = csvText.trim().split(/\r?\n/);
    if(lines.length<2) return [];
    var headers = lines[0].split(',').map(function(h){ return h.trim().toLowerCase().replace(/['"]/g,''); });
    var dateIdx   = headers.findIndex(function(h){ return h.includes('date'); });
    var descIdx   = headers.findIndex(function(h){ return h.includes('desc')||h.includes('narr')||h.includes('particular'); });
    var debitIdx  = headers.findIndex(function(h){ return h.includes('debit')||h.includes('withdraw'); });
    var creditIdx = headers.findIndex(function(h){ return h.includes('credit')||h.includes('deposit'); });
    var amtIdx    = headers.findIndex(function(h){ return h==='amount'||h==='amt'; });

    var rows = [];
    for(var i=1;i<lines.length;i++){
      var cols = lines[i].split(',').map(function(c){ return c.trim().replace(/['"]/g,''); });
      if(cols.length<2) continue;
      var date = dateIdx>=0 ? cols[dateIdx] : '';
      var desc = descIdx>=0 ? cols[descIdx] : 'Bank Transaction';
      var debit  = debitIdx>=0 ? (parseFloat((cols[debitIdx]||'').replace(/,/g,''))||0) : 0;
      var credit = creditIdx>=0 ? (parseFloat((cols[creditIdx]||'').replace(/,/g,''))||0) : 0;
      var amt    = amtIdx>=0 ? (parseFloat((cols[amtIdx]||'').replace(/,/g,''))||0) : 0;
      var finalAmt = debit>0?debit:(credit>0?credit:Math.abs(amt));
      if(!date || !finalAmt) continue;
      rows.push({rowIndex:i, date:date, desc:desc, amt:finalAmt, isCredit: credit>0||amt>0});
    }
    return rows;
  }

  function daysBetween(d1, d2){
    var a = new Date(d1+'T00:00:00'), b = new Date(d2+'T00:00:00');
    if(isNaN(a) || isNaN(b)) return 999;
    return Math.abs((a-b)/86400000);
  }

  function findBestMatch(bankRow, existingTxs){
    var best = null, bestScore = -1;
    existingTxs.forEach(function(t){
      var amt = W.txAmt(t);
      if(!amt || !t.date) return;
      var amtDiff = Math.abs(amt - bankRow.amt);
      var amtTolerance = Math.max(1, bankRow.amt*0.01); // exact-ish, allow 1% or ৳1 for rounding
      if(amtDiff > amtTolerance) return;
      var dayDiff = daysBetween(bankRow.date, t.date);
      if(dayDiff > 5) return; // outside matching window
      // Score: closer date and closer amount = higher score
      var score = (1 - dayDiff/5) * 0.6 + (1 - amtDiff/amtTolerance) * 0.4;
      if(score > bestScore){ bestScore = score; best = t; }
    });
    return best ? {tx:best, score:bestScore} : null;
  }

  W.autoMatchRunSuggestions = function(){
    var fileInput = document.getElementById('am-csv-file');
    var bankName = (document.getElementById('am-bank-name')||{}).value || 'Bank';
    var resultsEl = document.getElementById('am-results');
    if(!fileInput || !fileInput.files || !fileInput.files[0]){
      toast('Choose a CSV file first','e'); return;
    }
    var reader = new FileReader();
    reader.onload = function(e){
      var rows = parseBankCSV(e.target.result);
      if(!rows.length){ resultsEl.innerHTML = '<div style="font-size:12px;color:#dc2626;">No valid rows found — check the CSV has Date and Amount/Debit/Credit columns.</div>'; return; }
      var existingTxs = (DB.tx||[]).filter(function(t){ return t.date; });
      var matched = 0;
      var rowsHtml = rows.map(function(row, idx){
        var match = findBestMatch(row, existingTxs);
        if(match) matched++;
        return '<tr data-idx="'+idx+'" data-date="'+row.date+'" data-desc="'+row.desc.replace(/"/g,'&quot;')+'" data-amt="'+row.amt+'" data-credit="'+row.isCredit+'" style="border-bottom:1px solid #f3f4f6;">' +
          '<td style="padding:6px;">'+row.date+'</td>' +
          '<td>'+row.desc+'</td>' +
          '<td>৳'+row.amt.toLocaleString('en-IN')+'</td>' +
          '<td>'+(match ? ('<span style="color:#16a34a;font-weight:700;">✅ Likely match</span><br><span style="font-size:10px;color:#6b7280;">'+match.tx.date+' · '+(match.tx.party||match.tx.type||'')+' · ৳'+W.txAmt(match.tx).toLocaleString('en-IN')+'</span>') : '<span style="color:#d97706;font-weight:700;">🆕 No match found</span>') + '</td>' +
          '<td><label style="font-size:11px;"><input type="checkbox" class="am-row-import" '+(match?'':'checked')+'/> Import as new</label></td>' +
        '</tr>';
      }).join('');
      resultsEl.innerHTML =
        '<div style="font-size:12px;margin-bottom:8px;">Found <strong>'+rows.length+'</strong> statement line(s) — <strong>'+matched+'</strong> already appear to be recorded, <strong>'+(rows.length-matched)+'</strong> look new.</div>' +
        '<div style="max-height:340px;overflow:auto;border:1px solid #e5e7eb;border-radius:8px;">' +
        '<table style="width:100%;border-collapse:collapse;font-size:11.5px;">' +
        '<tr style="text-align:left;color:#6b7280;background:#f9fafb;position:sticky;top:0;"><th style="padding:6px;">Date</th><th>Description</th><th>Amount</th><th>System Match</th><th>Action</th></tr>' +
        rowsHtml + '</table></div>' +
        '<button data-x-click="autoMatchConfirmImport('+JSON.stringify(bankName)+')" style="margin-top:10px;padding:8px 16px;background:#16a34a;color:#fff;border:none;border-radius:8px;font-weight:700;cursor:pointer;font-size:12px;">✅ Import Checked Rows Only</button>';
    };
    reader.readAsText(fileInput.files[0]);
  };

  W.autoMatchConfirmImport = async function(bankName){
    var rows = document.querySelectorAll('#am-results tr[data-idx]');
    var toImport = [];
    rows.forEach(function(row){
      var cb = row.querySelector('.am-row-import');
      if(cb && cb.checked){
        toImport.push({
          date: row.getAttribute('data-date'),
          desc: row.getAttribute('data-desc'),
          amt: parseFloat(row.getAttribute('data-amt')),
          isCredit: row.getAttribute('data-credit')==='true'
        });
      }
    });
    if(!toImport.length){ toast('No rows checked for import.','w'); return; }
    var ok = (typeof __confirm==='function') ? await __confirm('Import '+toImport.length+' new bank transaction(s)?') : confirm('Import '+toImport.length+' transaction(s)?');
    if(!ok) return;
    DB.tx = DB.tx||[];
    toImport.forEach(function(row){
      DB.tx.push({
        id: newId(), date: row.date,
        type: row.isCredit ? 'Cash Received' : 'Bank Charge',
        party: row.desc, amt: row.amt, bank: bankName||'Bank',
        note: '[Auto-Match Import]', reconciled: true
      });
    });
    saveDB();
    if(typeof logAudit==='function') logAudit('BANK RECONCILIATION','Auto-Match','Imported '+toImport.length+' unmatched bank statement line(s) as new transactions');
    toast('✅ '+toImport.length+' transaction(s) imported','s');
    document.getElementById('am-results').innerHTML = '<div style="font-size:12px;color:#16a34a;">Import complete.</div>';
  };

  console.info('[Claude] Bank Reconciliation auto-match loaded.');
})();
</script>

<script nonce="<?php echo $cspNonceAttr; ?>" id="claude-feat-encryption">
/* ═══════════════════════════════════════════════════════════════════════
   FEATURE — AES-256 encryption for sensitive data at rest
   (Replaces the earlier XOR cipher, which the codebase's own comment
   already flagged as providing no real protection — see the note at
   the top of this file near "Client-side data encryption was removed".)

   IMPORTANT HONESTY NOTE, kept both here and in the Settings UI:
   This is a pure front-end app with no server to hold a secret key.
   AES-256 here means the ciphertext is no longer trivially reversible
   like XOR was, and a plaintext National ID no longer sits in the open
   inside exported JSON backups / localStorage — but the passphrase is
   still typed and held in THIS browser tab, so it is obfuscation of
   data-at-rest, not a substitute for real server-side key management.
   Anyone who can run JS in this page (e.g. via browser devtools) can
   still recover the passphrase from memory while it's set.

   Scope: encrypts the employee National ID (nid) field, which is the
   most sensitive personal field currently stored (DB.employees[].nid).
   ═══════════════════════════════════════════════════════════════════════ */
(function(){
  'use strict';
  var W = window;
  var _sessionPassphrase = null; // never persisted to DB/localStorage

  function cryptoReady(){ return typeof CryptoJS !== 'undefined'; }

  W.claudeEncryptField = function(plainText, passphrase){
    if(!cryptoReady() || !plainText || !passphrase) return plainText;
    try{ return 'AES256:' + CryptoJS.AES.encrypt(String(plainText), passphrase).toString(); }
    catch(e){ console.error('[encryption] encrypt failed', e); return plainText; }
  };
  W.claudeDecryptField = function(cipherText, passphrase){
    if(!cryptoReady() || !cipherText || !passphrase) return null;
    if(String(cipherText).indexOf('AES256:')!==0) return cipherText; // not encrypted
    try{
      var bytes = CryptoJS.AES.decrypt(cipherText.slice(7), passphrase);
      var out = bytes.toString(CryptoJS.enc.Utf8);
      return out || null; // empty string means wrong passphrase
    }catch(e){ return null; }
  };

  // ── Wrap saveEmployee: encrypt the NID right after the record is created ──
  var _prevSaveEmployee = W.saveEmployee;
  W.saveEmployee = function(){
    var before = (DB.employees||[]).length;
    var r = _prevSaveEmployee.apply(this, arguments);
    try{
      var enabled = DB.settings && DB.settings.encryptionEnabled;
      if(enabled && _sessionPassphrase && DB.employees && DB.employees.length > before){
        var emp = DB.employees[DB.employees.length-1];
        if(emp.nid && String(emp.nid).indexOf('AES256:')!==0){
          emp._nidPlainLen = String(emp.nid).length; // harmless metadata, no PII
          emp.nid = W.claudeEncryptField(emp.nid, _sessionPassphrase);
          saveDB();
        }
      }
    }catch(e){ console.error('[encryption] post-save hook failed', e); }
    return r;
  };

  // ── Bulk-encrypt any existing plaintext NIDs (run once from Settings) ──
  W.claudeEncryptAllEmployeeNIDs = function(){
    if(!_sessionPassphrase){ toast('Set a passphrase first.','e'); return; }
    if(!cryptoReady()){ toast('Encryption library did not load — check your internet connection.','e'); return; }
    var count = 0;
    (DB.employees||[]).forEach(function(emp){
      if(emp.nid && String(emp.nid).indexOf('AES256:')!==0){
        emp.nid = W.claudeEncryptField(emp.nid, _sessionPassphrase);
        count++;
      }
    });
    if(count){ saveDB(); if(typeof logAudit==='function') logAudit('SECURITY','Encryption','AES-256 encrypted '+count+' employee NID field(s) at rest.'); }
    toast(count ? ('🔐 Encrypted '+count+' NID field(s)') : 'No plaintext NIDs found to encrypt.', 's');
  };

  W.claudeRevealEmployeeNID = function(){
    var sel = document.getElementById('claude-reveal-emp-select');
    var pass = document.getElementById('claude-reveal-passphrase');
    var out = document.getElementById('claude-reveal-output');
    if(!sel || !sel.value){ toast('Pick an employee first','e'); return; }
    var emp = (DB.employees||[]).find(function(e){ return String(e.id)===sel.value; });
    if(!emp){ toast('Employee not found','e'); return; }
    if(!emp.nid || String(emp.nid).indexOf('AES256:')!==0){
      out.textContent = 'NID (not encrypted): ' + (emp.nid||'—');
      return;
    }
    var val = W.claudeDecryptField(emp.nid, pass.value);
    out.textContent = val ? ('NID: ' + val) : '❌ Wrong passphrase or corrupted value.';
  };

  // ── Settings panel: enable/disable, set session passphrase, bulk-encrypt, reveal ──
  var _prevRenderSettings2 = W.renderSettings;
  W.renderSettings = function(){
    var r = _prevRenderSettings2.apply(this, arguments);
    try{
      var body = document.getElementById('settings-body');
      if(!body || document.getElementById('claude-encryption-card')) return r;
      var s = DB.settings||{};
      var employees = DB.employees||[];
      var card = document.createElement('div');
      card.id = 'claude-encryption-card';
      card.style.cssText = 'background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;margin-top:16px;';
      card.innerHTML =
        '<div style="background:linear-gradient(90deg,#7c2d12,#b91c1c);color:#fff;padding:12px 16px;font-weight:700;font-size:13px;">🔐 Data Encryption (AES-256)</div>' +
        '<div style="padding:16px;">' +
          '<label style="display:flex;align-items:center;gap:8px;font-size:12px;font-weight:600;color:#374151;margin-bottom:10px;">' +
            '<input type="checkbox" id="claude-enc-enabled" '+(s.encryptionEnabled?'checked':'')+' data-x-change="xSetEncryptionEnabled" data-value-src="checked"/> Enable encryption of newly-saved employee National ID numbers' +
          '</label>' +
          '<div style="font-size:10.5px;color:#9ca3af;margin-bottom:12px;">⚠️ This app runs entirely in your browser with no server-side key vault. The passphrase below is kept only in this tab\'s memory for this session and is never saved — you must re-enter it each time you reopen the app. This protects data sitting in exported backups / localStorage from casual viewing; it is not equivalent to server-managed encryption.</div>' +
          '<div style="display:flex;gap:8px;margin-bottom:10px;">' +
            '<input type="password" id="claude-session-passphrase" placeholder="Session passphrase (not saved)" style="flex:1;padding:7px 10px;border:1px solid #d1d5db;border-radius:5px;font-size:12px;"/>' +
            '<button data-x-click="claudeSetSessionPassphrase()" style="padding:7px 14px;background:#374151;color:#fff;border:none;border-radius:5px;font-size:12px;cursor:pointer;">Set for Session</button>' +
          '</div>' +
          '<button data-x-click="claudeEncryptAllEmployeeNIDs()" style="width:100%;padding:8px;background:#b91c1c;color:#fff;border:none;border-radius:7px;font-size:12px;font-weight:700;cursor:pointer;margin-bottom:14px;">🔐 Encrypt All Existing Plaintext NIDs Now</button>' +
          '<div style="border-top:1px dashed #e5e7eb;padding-top:12px;">' +
            '<div style="font-size:11px;font-weight:600;color:#374151;margin-bottom:6px;">Reveal an employee\'s NID (requires session passphrase)</div>' +
            '<div style="display:flex;gap:8px;margin-bottom:6px;">' +
              '<select id="claude-reveal-emp-select" style="flex:1;padding:6px;border:1px solid #d1d5db;border-radius:5px;font-size:12px;">' +
                '<option value="">Select employee...</option>' +
                employees.map(function(e){ return '<option value="'+e.id+'">'+e.name+'</option>'; }).join('') +
              '</select>' +
              '<input type="password" id="claude-reveal-passphrase" placeholder="Passphrase" style="width:140px;padding:6px;border:1px solid #d1d5db;border-radius:5px;font-size:12px;"/>' +
              '<button data-x-click="claudeRevealEmployeeNID()" style="padding:6px 12px;background:#2563eb;color:#fff;border:none;border-radius:5px;font-size:12px;cursor:pointer;">Reveal</button>' +
            '</div>' +
            '<div id="claude-reveal-output" style="font-size:12px;font-weight:600;color:#111827;"></div>' +
          '</div>' +
        '</div>';
      body.appendChild(card);
    }catch(e){ console.error('[encryption settings panel]', e); }
    return r;
  };

  W.claudeSetSessionPassphrase = function(){
    var el = document.getElementById('claude-session-passphrase');
    if(!el || !el.value){ toast('Type a passphrase first','e'); return; }
    _sessionPassphrase = el.value;
    el.value = '';
    el.placeholder = '•••• set for this session ••••';
    toast('🔓 Passphrase set for this session (not saved to disk)','s');
  };

  console.info('[Claude] AES-256 field encryption loaded (XOR cipher fully retired).');
})();
</script>


<script nonce="<?php echo $cspNonceAttr; ?>" id="erp-txcache-v1">
/* ═══════════════════════════════════════════════════════════════════════
   IMPROVEMENT #1 — PERFORMANCE & SCALABILITY : TxCache
   ---------------------------------------------------------------------
   Every screen used to re-scan DB.tx with .filter().reduce() on each
   render (dashboard, charts, P&L, ledgers, party lists...). With 10k+
   rows that is dozens of full passes per paint.

   TxCache pre-computes, ONCE per data change:
     • grand totals  : revenue, cogs, expenses, otherIncome, count
     • by party      : sales / purchases / payments / net balance
     • by product    : qty & amount bought / sold, avg cost, COGS
     • by month      : revenue / cogs / expense buckets (YYYY-MM)
     • by type       : amount + count per transaction type

   It also MEMOISES the canonical aggregate helpers (sumRevenue, sumCogs,
   computeCOGS, cogsByProduct, partyBuckets, stockValue), so all existing
   call sites across the app become O(1) cache lookups without touching
   their code. Cache is invalidated automatically on saveDB() and by a
   cheap data-signature check on every read.

   Public API (also on APP.cache):
     TxCache.totals()        TxCache.byParty(name)   TxCache.byProduct(p)
     TxCache.byMonth(ym)     TxCache.byType(t)       TxCache.range(a,b)
     TxCache.rebuild()       TxCache.invalidate()    TxCache.stats()
   ═══════════════════════════════════════════════════════════════════════ */
(function(){
  "use strict";
  var W = window;

  function txs(){ var d = W.DB || {}; return (d.tx && d.tx.length ? d.tx : (d.transactions || d.tx || [])) || []; }
  function parties(){ var d = W.DB || {}; return d.parties || d.customers || []; }
  function amt(t){ return W.txAmt ? W.txAmt(t) : (parseFloat(t && (t.amt != null ? t.amt : t.amount)) || 0); }
  function qty(t){ return W.txQty ? W.txQty(t) : (parseFloat(t && t.qty) || 0); }
  function prod(t){ return (W.txProduct ? W.txProduct(t) : String((t && t.product) || '')) || 'Unknown'; }
  function party(t){ return String((t && (t.party || t.customer || t.supplier || t.name)) || '').trim(); }
  function isRev(t){ return W.isRevenueTx ? W.isRevenueTx(t) : false; }
  function isCogs(t){ return W.isCogsTx ? W.isCogsTx(t) : false; }
  function isExp(t){
    var s = W.EXPENSE_TX_TYPES, ty = W.normTxType ? W.normTxType(t && t.type) : String((t && t.type) || '');
    return !!(s && s.has && s.has(ty));
  }
  function isOther(t){
    var s = W.OTHER_INCOME_TX_TYPES, ty = W.normTxType ? W.normTxType(t && t.type) : String((t && t.type) || '');
    return !!(s && s.has && s.has(ty));
  }
  /** Normalise any stored date to YYYY-MM-DD (empty string when unparseable). */
  function isoDate(t){
    var d = (t && (t.date || t.dt || t.createdAt)) || '';
    if (!d) return '';
    var s = String(d);
    if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0,10);
    var p = new Date(s);
    return isNaN(p) ? '' : p.toISOString().slice(0,10);
  }

  function emptyAgg(){
    return { revenue:0, cogs:0, expense:0, otherIncome:0, count:0,
             saleQty:0, purchQty:0, purchAmt:0, payments:0 };
  }

  var C = {
    version: 0,          /* bumps on every rebuild - memo key */
    sig: null,
    built: false,
    buildMs: 0,
    totals: emptyAgg(),
    party: Object.create(null),
    product: Object.create(null),
    month: Object.create(null),
    type: Object.create(null),
    sorted: []           /* [{d:'YYYY-MM-DD', t:txRow}] ascending, for range() */
  };

  /** Cheap fingerprint of the transaction set - detects adds/removes/replaces. */
  function signature(){
    var list = txs(), n = list.length;
    if (!n) return '0';
    var a = list[0], b = list[n-1], m = list[n>>1];
    return n + '|' + (a && (a.id || a.date)) + '|' + (m && (m.id || m.date)) + '|' +
           (b && (b.id || b.date)) + '|' + (b && (b.amt != null ? b.amt : b.amount)) + '|' + (W.__txCacheDirty ? 1 : 0);
  }

  function bucket(map, key){ return map[key] || (map[key] = emptyAgg()); }

  /**
   * Rebuild every index from DB.tx in a single pass.
   * @returns {object} the cache object (chainable).
   */
  function rebuild(){
    var t0 = (W.performance && performance.now) ? performance.now() : Date.now();
    var list = txs();
    C.totals  = emptyAgg();
    C.party   = Object.create(null);
    C.product = Object.create(null);
    C.month   = Object.create(null);
    C.type    = Object.create(null);
    C.sorted  = [];

    for (var i = 0; i < list.length; i++){
      var t = list[i]; if (!t) continue;
      var a = amt(t), q = qty(t), d = isoDate(t), ym = d ? d.slice(0,7) : 'unknown';
      var rev = isRev(t), cog = isCogs(t), exp = isExp(t), oth = isOther(t);
      var pb = bucket(C.party, party(t) || 'Unknown');
      var rb = bucket(C.product, prod(t));
      var mb = bucket(C.month, ym);
      var tb = bucket(C.type, W.normTxType ? W.normTxType(t.type) : String(t.type || ''));

      var targets = [C.totals, pb, rb, mb, tb];
      for (var j = 0; j < targets.length; j++){
        var o = targets[j];
        o.count++;
        if (rev){ o.revenue += a; o.saleQty += q; }
        else if (cog){ o.purchAmt += a; o.purchQty += q; }
        else if (exp){ o.expense += a; }
        else if (oth){ o.otherIncome += a; }
        else { o.payments += a; }
      }
      C.sorted.push({ d: d, t: t });
    }
    C.sorted.sort(function(x, y){ return x.d < y.d ? -1 : x.d > y.d ? 1 : 0; });

    /* per-product average cost + COGS, then roll COGS up */
    var totalCogs = 0;
    Object.keys(C.product).forEach(function(k){
      var r = C.product[k];
      r.avgCost = r.purchQty > 0 ? r.purchAmt / r.purchQty : 0;
      if (r.purchQty > 0)          r.cogs = Math.min(r.saleQty * r.avgCost, r.purchAmt);
      else if (r.revenue > 0 && r.purchAmt > 0) r.cogs = Math.min(r.purchAmt, r.revenue);
      else                         r.cogs = 0;
      totalCogs += r.cogs;
    });
    C.totals.cogs = totalCogs;
    C.totals.grossProfit = C.totals.revenue - totalCogs;
    C.totals.netProfit   = C.totals.grossProfit + C.totals.otherIncome - C.totals.expense;

    C.sig = signature();
    C.built = true;
    C.version++;
    C.buildMs = ((W.performance && performance.now) ? performance.now() : Date.now()) - t0;
    W.__txCacheDirty = false;
    return C;
  }

  /** Rebuild only when the underlying data changed. */
  function fresh(){
    if (!C.built || W.__txCacheDirty || C.sig !== signature()) rebuild();
    return C;
  }

  var TxCache = {
    get version(){ return fresh().version; },
    /** @returns {object} grand totals incl. grossProfit / netProfit. */
    totals: function(){ return fresh().totals; },
    /** @param {string} name @returns {object} aggregate for one party. */
    byParty: function(name){ return fresh().party[String(name || '').trim()] || emptyAgg(); },
    /** @param {string} p @returns {object} aggregate + avgCost/cogs for one product. */
    byProduct: function(p){ return fresh().product[String(p || '').trim()] || emptyAgg(); },
    /** @param {string} ym 'YYYY-MM' */
    byMonth: function(ym){ return fresh().month[ym] || emptyAgg(); },
    /** @param {string} type transaction type */
    byType: function(type){ return fresh().type[String(type || '')] || emptyAgg(); },
    /** All product aggregates keyed by product name. */
    products: function(){ return fresh().product; },
    /** All month aggregates keyed by YYYY-MM. */
    months: function(){ return fresh().month; },
    /** All party aggregates keyed by party name. */
    partiesMap: function(){ return fresh().party; },
    /**
     * Transactions between two ISO dates (inclusive), using the pre-sorted index.
     * @param {string} from YYYY-MM-DD @param {string} to YYYY-MM-DD
     */
    range: function(from, to){
      var s = fresh().sorted, out = [];
      var a = from || '0000-01-01', b = to || '9999-12-31';
      for (var i = 0; i < s.length; i++){
        if (s[i].d && s[i].d >= a && s[i].d <= b) out.push(s[i].t);
      }
      return out;
    },
    /** Totals for an arbitrary date range (computed from the range slice). */
    rangeTotals: function(from, to){
      var list = TxCache.range(from, to), o = emptyAgg();
      list.forEach(function(t){
        var a = amt(t); o.count++;
        if (isRev(t)) o.revenue += a;
        else if (isCogs(t)) o.purchAmt += a;
        else if (isExp(t)) o.expense += a;
        else if (isOther(t)) o.otherIncome += a;
        else o.payments += a;
      });
      o.cogs = W.computeCOGS ? W.computeCOGS(list) : 0;
      o.grossProfit = o.revenue - o.cogs;
      o.netProfit = o.grossProfit + o.otherIncome - o.expense;
      return o;
    },
    /** Party balances derived from the party master (single-bucket rule). */
    balances: function(){ return W.partyBuckets ? W.partyBuckets(parties()) : null; },
    /** Force a full recompute now. */
    rebuild: rebuild,
    /** Mark the cache stale; next read rebuilds. */
    invalidate: function(){ W.__txCacheDirty = true; C.built = false; },
    /** Diagnostics: row count, index sizes, last build time in ms. */
    stats: function(){
      var c = fresh();
      return { rows: c.totals.count, parties: Object.keys(c.party).length,
               products: Object.keys(c.product).length, months: Object.keys(c.month).length,
               version: c.version, lastBuildMs: Math.round(c.buildMs * 100) / 100 };
    }
  };
  W.TxCache = TxCache;

  /* ── memoise the canonical helpers so existing call sites get cache speed ── */
  function memoise(name){
    var orig = W[name];
    if (typeof orig !== 'function' || orig.__memoised) return;
    var store = (typeof WeakMap === 'function') ? new WeakMap() : null;
    var wrapped = function(list){
      if (!store || !list || typeof list !== 'object') return orig.apply(this, arguments);
      var ver = fresh().version;
      var hit = store.get(list);
      if (hit && hit.ver === ver && hit.len === list.length) return hit.val;
      var val = orig.apply(this, arguments);
      store.set(list, { ver: ver, len: list.length, val: val });
      return val;
    };
    wrapped.__memoised = true;
    wrapped.__orig = orig;
    W[name] = wrapped;
  }
  ['sumRevenue','sumCogs','computeCOGS','cogsByProduct','partyBuckets','stockValue'].forEach(memoise);

  /* ── automatic invalidation on every save ────────────────────────────── */
  try{
    var prevSave = W.saveDB, prevSaveNow = W.saveDBNow;
    Object.defineProperty(W, 'saveDB', {
      configurable: true,
      writable: true,
      value: function(){ TxCache.invalidate(); return (typeof prevSave === 'function') ? prevSave.apply(this, arguments) : undefined; }
    });
    if (typeof prevSaveNow === 'function'){
      Object.defineProperty(W, 'saveDBNow', {
        configurable: true,
        writable: true,
        value: function(){ TxCache.invalidate(); return prevSaveNow.apply(this, arguments); }
      });
    }
  }catch(e){ console.warn('[TxCache] could not hook saveDB:', e && e.message); }

  /* invalidate after any server/IDB load too */
  ['loadDataFromServer','loadDB','syncFromServer'].forEach(function(fn){
    var f = W[fn];
    if (typeof f !== 'function' || f.__txCacheHooked) return;
    var g = function(){
      var r = f.apply(this, arguments);
      try{ Promise.resolve(r).then(function(){ TxCache.invalidate(); }); }catch(e){ TxCache.invalidate(); }
      return r;
    };
    g.__txCacheHooked = true;
    W[fn] = g;
  });

  /* ── single public surface ───────────────────────────────────────────── */
  W.APP = W.APP || {};
  W.APP.cache = TxCache;

  try{ rebuild(); }catch(e){ console.warn('[TxCache] initial build failed:', e && e.message); }
  console.info('[TxCache] ready', TxCache.stats());
})();
</script>

<style id="erp-ux-polish-v1">
/* ═══════════════════════════════════════════════════════════════════════
   IMPROVEMENT #2 — UX (MOBILE & DESKTOP)
   1. Modals never exceed the viewport and scroll internally (90dvh).
   2. Tables inside modals scroll horizontally instead of overflowing.
   3. Table headers are truly sticky while the body scrolls.
   4. Sidebar search highlights matches with <mark>.
   5. Floating "Back to Top" button after 300px of scroll.
   ═══════════════════════════════════════════════════════════════════════ */

/* ── 1. modal sizing / internal scroll ─────────────────────────────── */
.modal, .modal-content, .m-box, .dialog, [role="dialog"]{
  max-height: 90vh;              /* fallback for older engines */
  max-height: 90dvh;             /* dynamic vh: excludes mobile URL bar */
  overflow-y: auto;
  overscroll-behavior: contain;  /* stop scroll chaining to the page behind */
  -webkit-overflow-scrolling: touch;
}
/* sticky modal chrome so the title/close stay reachable while scrolling */
.modal > .modal-title, .modal > .modal-header, .dialog > .dialog-header{
  position: sticky; top: 0; z-index: 12;
  background: inherit;
  backdrop-filter: blur(14px) saturate(180%);
  -webkit-backdrop-filter: blur(14px) saturate(180%);
}
.modal > .modal-title{ background: var(--white, #fff); }

/* ── 2. horizontal scroll for nested tables ────────────────────────── */
.ux-xscroll{
  overflow-x: auto; overflow-y: visible;
  -webkit-overflow-scrolling: touch;
  max-width: 100%;
  scrollbar-width: thin;
}
.ux-xscroll > table{ min-width: max-content; }
.ux-xscroll::-webkit-scrollbar{ height: 8px; }
.ux-xscroll::-webkit-scrollbar-thumb{ background: rgba(15,23,42,.22); border-radius: 999px; }

/* ── 3. truly sticky table headers ─────────────────────────────────── */
table thead th, .table thead th, .tbl thead th{
  position: sticky !important;
  top: 0 !important;
  z-index: 5 !important;
}
/* second header row (grouped headers) sits under the first */
table thead tr:nth-child(2) th{ top: 32px !important; z-index: 4 !important; }
/* opaque fallback so rows never bleed through the frosted header */
table thead th::after{
  content:""; position:absolute; inset:0; z-index:-1;
  background: linear-gradient(135deg, rgba(74,222,128,.94) 0%, rgba(22,163,74,.94) 100%);
}
[data-theme="dark"] table thead th::after{
  background: linear-gradient(135deg, rgba(21,94,49,.97) 0%, rgba(12,61,32,.97) 100%);
}

/* ── 4. search highlight ───────────────────────────────────────────── */
mark.nav-hit, .ux-hit{
  background: #fde68a; color: #713f12;
  padding: 0 2px; border-radius: 3px; font-weight: 800;
}
[data-theme="dark"] mark.nav-hit, [data-theme="dark"] .ux-hit{
  background: #a16207; color: #fffbeb;
}

/* ── 5. back to top ────────────────────────────────────────────────── */
#uxBackToTop{
  position: fixed;
  right: max(18px, env(safe-area-inset-right));
  bottom: calc(88px + env(safe-area-inset-bottom));
  width: 46px; height: 46px; border: 0; border-radius: 50%;
  display: grid; place-items: center;
  font-size: 19px; line-height: 1; cursor: pointer;
  color: #fff;
  background: linear-gradient(135deg, #22c55e, #15803d);
  box-shadow: 0 12px 26px -8px rgba(21,128,61,.55), 0 4px 10px rgba(2,6,23,.2);
  opacity: 0; visibility: hidden; transform: translateY(14px) scale(.9);
  transition: opacity .22s, transform .22s, visibility .22s;
  z-index: 9000;
}
#uxBackToTop.show{ opacity: 1; visibility: visible; transform: none; }
/* keep the button above (and clear of) bottom banners like the backup reminder */
#uxBackToTop{ z-index: 2147479500; bottom: calc(88px + var(--ux-btt-lift, 0px) + env(safe-area-inset-bottom)); }
#uxBackToTop:hover{ transform: translateY(-2px) scale(1.06); }
@media (min-width: 900px){ #uxBackToTop{ bottom: 26px; } }
@media print{ #uxBackToTop{ display: none !important; } }
</style>

<script nonce="<?php echo $cspNonceAttr; ?>" id="erp-ux-polish-v1-js">
(function(){
  "use strict";
  var W = window, D = document;

  /* ── wrap wide tables (mainly inside modals) in a horizontal scroller ── */
  /**
   * Wrap any table that is not already inside a scroll container.
   * @param {Element} [root=document] subtree to process
   */
  function wrapTables(root){
    var scope = root && root.querySelectorAll ? root : D;
    var tables = scope.querySelectorAll('table');
    for (var i = 0; i < tables.length; i++){
      var t = tables[i], p = t.parentElement;
      if (!p || p.classList.contains('ux-xscroll') || p.classList.contains('tbl-scroll')) continue;
      if (t.closest('.ux-xscroll, .tbl-scroll, .table-wrap')) continue;
      var w = D.createElement('div');
      w.className = 'ux-xscroll';
      p.insertBefore(w, t);
      w.appendChild(t);
    }
  }
  W.uxWrapTables = wrapTables;

  var wrapTimer = null;
  function scheduleWrap(){
    if (wrapTimer) return;
    wrapTimer = setTimeout(function(){ wrapTimer = null; try{ wrapTables(D); }catch(e){} }, 250);
  }

  /* ── <mark> highlighting for the sidebar search ─────────────────────── */
  /** Remove every previously injected <mark> inside el. */
  function unmark(el){
    var marks = el.querySelectorAll('mark.nav-hit');
    for (var i = 0; i < marks.length; i++){
      var m = marks[i], p = m.parentNode;
      if (!p) continue;
      p.replaceChild(D.createTextNode(m.textContent), m);
      p.normalize();
    }
  }
  /**
   * Wrap every case-insensitive occurrence of query in el's text nodes.
   * Works on text nodes only, so icons, onclick handlers and markup survive.
   */
  function markText(el, query){
    if (!query) return;
    var q = query.toLowerCase();
    var walker = D.createTreeWalker(el, NodeFilter.SHOW_TEXT, null);
    var nodes = [], n;
    while ((n = walker.nextNode())) nodes.push(n);
    nodes.forEach(function(node){
      var text = node.nodeValue, lower = text.toLowerCase(), idx = lower.indexOf(q);
      if (idx < 0 || !node.parentNode || node.parentNode.tagName === 'MARK') return;
      var frag = D.createDocumentFragment(), pos = 0;
      while (idx >= 0){
        if (idx > pos) frag.appendChild(D.createTextNode(text.slice(pos, idx)));
        var mk = D.createElement('mark');
        mk.className = 'nav-hit';
        mk.textContent = text.slice(idx, idx + q.length);
        frag.appendChild(mk);
        pos = idx + q.length;
        idx = lower.indexOf(q, pos);
      }
      if (pos < text.length) frag.appendChild(D.createTextNode(text.slice(pos)));
      node.parentNode.replaceChild(frag, node);
    });
  }

  var origFilter = W.filterNavItems;
  /**
   * Sidebar search with match highlighting (delegates filtering to the
   * original implementation so permissions/collapse logic stay intact).
   * @param {string} q search text
   */
  W.filterNavItems = function(q){
    var r = (typeof origFilter === 'function') ? origFilter.apply(this, arguments) : undefined;
    try{
      var query = String(q || '').trim();
      var items = D.querySelectorAll('.nav-item');
      for (var i = 0; i < items.length; i++){
        unmark(items[i]);
        if (query && items[i].style.display !== 'none') markText(items[i], query);
      }
    }catch(e){ console.warn('[UX] highlight failed:', e && e.message); }
    return r;
  };

  /* ── back to top ────────────────────────────────────────────────────── */
  function scrollTop(){
    var y = W.pageYOffset || D.documentElement.scrollTop || D.body.scrollTop || 0;
    return y;
  }
  function initBackToTop(){
    if (D.getElementById('uxBackToTop')) return;
    var btn = D.createElement('button');
    btn.id = 'uxBackToTop';
    btn.type = 'button';
    btn.title = 'Back to top';
    btn.setAttribute('aria-label', 'Back to top');
    btn.innerHTML = '↑';
    btn.onclick = function(){
      try{ W.scrollTo({ top: 0, behavior: 'smooth' }); }catch(e){ W.scrollTo(0, 0); }
      D.documentElement.scrollTop = 0; D.body.scrollTop = 0;
      if (W.navigator && navigator.vibrate) { try{ navigator.vibrate(8); }catch(e){} }
    };
    D.body.appendChild(btn);

    var ticking = false;
    function update(){
      ticking = false;
      btn.classList.toggle('show', scrollTop() > 300);
      /* lift the button until nothing else (banners, FABs) covers it */
      try{
        if (!btn.classList.contains('show')) return;
        var lift = parseInt(D.documentElement.style.getPropertyValue('--ux-btt-lift')) || 0;
        for (var pass = 0; pass < 6; pass++){
          var r = btn.getBoundingClientRect();
          var hit = D.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2);
          if (!hit || hit === btn || btn.contains(hit)) break;
          lift += 58;
          D.documentElement.style.setProperty('--ux-btt-lift', lift + 'px');
          btn.getBoundingClientRect();
        }
      }catch(e){}
    }
    function onScroll(){
      if (ticking) return;
      ticking = true;
      requestAnimationFrame(update);
    }
    W.addEventListener('scroll', onScroll, { passive: true });
    setInterval(update, 2000);
    D.addEventListener('scroll', onScroll, { passive: true, capture: true });
    update();
  }

  function boot(){
    initBackToTop();
    wrapTables(D);
    /* re-wrap tables rendered later (modals, re-renders) */
    try{
      new MutationObserver(function(muts){
        for (var i = 0; i < muts.length; i++){
          if (muts[i].addedNodes && muts[i].addedNodes.length){ scheduleWrap(); return; }
        }
      }).observe(D.body, { childList: true, subtree: true });
    }catch(e){}
    console.info('[UX polish] modal scroll, sticky headers, nav highlight and back-to-top active');
  }

  if (D.readyState === 'loading') D.addEventListener('DOMContentLoaded', boot);
  else boot();
})();
</script>


<style id="erp-data-integrity-v1">
/* ═══════════════════════════════════════════════════════════════════════
   IMPROVEMENT #3 — DATA INTEGRITY & VALIDATION
   1. Numeric fields reject negatives / junk before they reach the DB.
   2. saveTx / saveProd / payment saves are guarded (required fields,
      duplicate invoice, absurd dates, NaN money) without touching the
      original save logic.
   3. Double-submit lock: one click = one record.
   4. window.erpIntegrityCheck() audits the whole DB and reports problems.
   ═══════════════════════════════════════════════════════════════════════ */
.di-invalid{
  border-color:#dc2626 !important;
  box-shadow:0 0 0 3px rgba(220,38,38,.16) !important;
  background:#fef2f2 !important;
}
.di-msg{
  display:block; margin-top:4px; font-size:11px; font-weight:700; color:#b91c1c;
}
[data-theme="dark"] .di-invalid{ background:#3f1d1d !important; }
[data-theme="dark"] .di-msg{ color:#fca5a5; }
#di-report{
  position:fixed; inset:auto 12px 12px 12px; max-width:640px; margin:0 auto;
  max-height:60vh; overflow:auto; z-index:2147479600;
  background:#fff; color:#0f172a; border:1px solid #e2e8f0; border-radius:14px;
  box-shadow:0 24px 60px -20px rgba(2,6,23,.45); padding:16px 18px; font-size:13px;
}
#di-report h4{ margin:0 0 8px; font-size:14px; font-weight:800; }
#di-report ul{ margin:0; padding-left:18px; }
#di-report li{ margin:3px 0; }
#di-report .di-close{
  position:absolute; top:10px; right:12px; border:0; background:transparent;
  font-size:18px; cursor:pointer; color:#64748b;
}
[data-theme="dark"] #di-report{ background:#0f172a; color:#e2e8f0; border-color:#1e293b; }
@media print{ #di-report{ display:none !important; } }
</style>

<script nonce="<?php echo $cspNonceAttr; ?>" id="erp-data-integrity-v1-js">
(function(){
  "use strict";
  var W = window, D = document;

  /* ── helpers ──────────────────────────────────────────────────────── */
  function say(msg, kind){
    try{ if (typeof W.toast === 'function') return W.toast(msg, kind || 'e'); }catch(e){}
    console.warn('[integrity]', msg);
  }
  function el(id){ return D.getElementById(id); }
  function num(id){
    var e = el(id); if (!e) return null;
    var raw = String(e.value == null ? '' : e.value).trim();
    if (raw === '') return null;
    var n = Number(raw);
    return isFinite(n) ? n : NaN;
  }
  function str(id){ var e = el(id); return e ? String(e.value || '').trim() : ''; }
  function markBad(id, msg){
    var e = el(id); if (!e) return;
    e.classList.add('di-invalid');
    var next = e.nextElementSibling;
    if (!next || !next.classList || !next.classList.contains('di-msg')){
      next = D.createElement('small');
      next.className = 'di-msg';
      e.parentNode && e.parentNode.insertBefore(next, e.nextSibling);
    }
    next.textContent = msg;
  }
  function clearBad(scopeIds){
    scopeIds.forEach(function(id){
      var e = el(id); if (!e) return;
      e.classList.remove('di-invalid');
      var n = e.nextElementSibling;
      if (n && n.classList && n.classList.contains('di-msg')) n.parentNode.removeChild(n);
    });
  }

  /* ── 1. live numeric hardening ────────────────────────────────────── */
  var NEG_OK = /(due|diff|adjust|balance|profit|change)/i;   /* may legitimately go negative */
  function isNumericField(inp){
    if (!inp || inp.tagName !== 'INPUT') return false;
    if (inp.type === 'number') return true;
    return /(amt|amount|qty|rate|wt|cost|paid|recv|price|pct|salary|advance)/i.test(inp.id || '');
  }
  D.addEventListener('input', function(ev){
    var t = ev.target;
    if (!isNumericField(t)) return;
    var raw = String(t.value || '');
    if (raw === '') { t.classList.remove('di-invalid'); return; }
    var cleaned = raw.replace(/[^0-9.\-]/g, '');
    if (!NEG_OK.test(t.id || '')) cleaned = cleaned.replace(/-/g, '');
    /* keep only the first dot */
    var firstDot = cleaned.indexOf('.');
    if (firstDot > -1) cleaned = cleaned.slice(0, firstDot + 1) + cleaned.slice(firstDot + 1).replace(/\./g, '');
    if (cleaned !== raw){
      var pos = t.selectionStart;
      t.value = cleaned;
      try{ t.setSelectionRange(Math.max(0, pos - (raw.length - cleaned.length)), Math.max(0, pos - (raw.length - cleaned.length))); }catch(e){}
    }
    t.classList.toggle('di-invalid', cleaned !== '' && !isFinite(Number(cleaned)));
  }, true);

  /* ── 2. double-submit lock ────────────────────────────────────────── */
  var lastCall = {};
  function locked(key){
    var now = Date.now();
    if (lastCall[key] && now - lastCall[key] < 1200) return true;
    lastCall[key] = now;
    return false;
  }

  /* ── 3. validation rules ──────────────────────────────────────────── */
  var TX_IDS = ['tx-date','tx-type','tx-party','tx-amt','tx-qty','tx-rate','tx-wt','tx-inv','tx-paid','tx-recv'];
  var PARTY_TYPES = /(sale|purchase|payment|receipt|return)/i;

  function validateTxForm(){
    clearBad(TX_IDS);
    var errs = [], warns = [];
    var date = str('tx-date'), type = str('tx-type');

    if (!date){ errs.push('Date is required'); markBad('tx-date', 'Required'); }
    if (!type){ errs.push('Type is required'); markBad('tx-type', 'Required'); }

    if (date){
      var d = new Date(date + 'T00:00:00');
      if (isNaN(d.getTime())){ errs.push('Date is not a valid date'); markBad('tx-date','Invalid date'); }
      else {
        var today = new Date(); today.setHours(23,59,59,999);
        var tomorrowPlus = new Date(today.getTime() + 86400000);
        if (d > tomorrowPlus) warns.push('Date is in the future (' + date + ')');
        if (d.getFullYear() < 2000) warns.push('Date looks wrong (' + date + ')');
      }
    }

    ['tx-amt','tx-qty','tx-rate','tx-wt','tx-paid','tx-recv','tx-bagqty','tx-grosswt','tx-truckrent'].forEach(function(id){
      if (!el(id)) return;
      var n = num(id);
      if (n === null) return;
      if (isNaN(n)){ errs.push(id.replace('tx-','') + ' is not a number'); markBad(id, 'Not a number'); return; }
      if (n < 0){ errs.push(id.replace('tx-','') + ' cannot be negative'); markBad(id, 'Cannot be negative'); }
      if (Math.abs(n) > 1e12){ errs.push(id.replace('tx-','') + ' is unrealistically large'); markBad(id, 'Value too large'); }
    });

    if (type && PARTY_TYPES.test(type) && el('tx-party') && !str('tx-party')){
      warns.push('No party selected for a ' + type + ' entry');
    }

    /* duplicate invoice number within the same type */
    var inv = str('tx-inv');
    var editId = parseInt((el('tx-edit-id') || {}).value, 10) || 0;
    if (inv){
      var dup = (W.DB && Array.isArray(DB.tx) ? DB.tx : []).filter(function(t){
        return t && t.id !== editId && String(t.inv || '').trim() === inv && String(t.type || '') === type;
      });
      if (dup.length) warns.push('Invoice "' + inv + '" already exists for type ' + type);
    }

    /* qty x rate should be close to amount when all three are present */
    var q = num('tx-qty'), r = num('tx-rate'), a = num('tx-amt');
    if (q && r && a && isFinite(q) && isFinite(r) && isFinite(a)){
      var expect = q * r;
      if (expect > 0 && Math.abs(expect - a) / expect > 0.02){
        warns.push('Amount ' + a.toLocaleString() + ' does not match qty x rate (' + Math.round(expect).toLocaleString() + ')');
      }
    }
    return { errs: errs, warns: warns };
  }

  /* BUGFIX: guard() used to detect "already guarded" purely by checking
     orig.__diWrapped on whatever window[name] happens to be right now. That
     works the FIRST time, but applyGuards() is deliberately called again
     later (boot(), then +1500ms, then +5000ms — see the comment above
     boot()) to re-catch functions other patches replace. Several other
     patches in this file *also* wrap _executeSaveTx on their own delayed
     timer (e.g. the stock-sync installer, `setTimeout(install,300)`), and
     their wrapper does not carry the __diWrapped marker forward. So the
     later applyGuards() call saw a "fresh-looking" function, wrapped it a
     SECOND time, and the two guard layers ended up sharing the same
     time-based double-submit lock (lastCall['execSaveTx']) — the outer
     layer sets the lock, then immediately calls into the inner layer,
     which sees that same lock as "already used within 1200ms" and bails
     out silently. Net effect: every transaction saved more than ~1.5s
     after the page loaded (i.e. virtually always) was silently discarded
     — nothing was pushed to DB.tx, with no visible error to the user.
     Fix: remember which names we've *ever* guarded, independent of
     whatever window[name] currently points to, so a name is only ever
     wrapped by this guard once for the life of the page. */
  var _diGuardedNames = {};
  function guard(name, validator, lockKey){
    var orig = W[name];
    if (typeof orig !== 'function') return;
    if (orig.__diWrapped || _diGuardedNames[name]) return;   /* already guarded */
    _diGuardedNames[name] = true;
    W[name] = function(){
      if (locked(lockKey || name)){ console.info('[integrity] duplicate submit ignored:', name); return; }
      var res;
      try{ res = validator ? validator() : { errs: [], warns: [] }; }
      catch(e){ console.warn('[integrity] validator failed', e); res = { errs: [], warns: [] }; }
      if (res.errs && res.errs.length){
        say('Cannot save — ' + res.errs[0], 'e');
        delete lastCall[lockKey || name];
        return;
      }
      if (res.warns && res.warns.length){
        var ok = W.confirm('Please double-check:\n\n• ' + res.warns.join('\n• ') + '\n\nSave anyway?');
        if (!ok){ delete lastCall[lockKey || name]; return; }
      }
      return orig.apply(this, arguments);
    };
    W[name].__diWrapped = true;
  }

  function validateProdForm(){
    var errs = [], warns = [];
    ['prod-qty','prod-rate','prod-price','prod-stock','prod-open'].forEach(function(id){
      if (!el(id)) return;
      var n = num(id);
      if (n === null) return;
      if (isNaN(n)){ errs.push(id + ' is not a number'); markBad(id, 'Not a number'); }
      else if (n < 0){ errs.push(id + ' cannot be negative'); markBad(id, 'Cannot be negative'); }
    });
    return { errs: errs, warns: warns };
  }

  /* ── 4. whole-database audit ──────────────────────────────────────── */
  function integrityCheck(opts){
    var silent = opts && opts.silent;
    var db = W.DB || {};
    var tx = Array.isArray(db.tx) ? db.tx : [];
    var issues = [];
    var ids = Object.create(null), invs = Object.create(null);
    var badMoney = 0, badDate = 0, negative = 0, dupId = 0, dupInv = 0, noType = 0;

    tx.forEach(function(t){
      if (!t) return;
      var amt = Number(t.amount != null ? t.amount : t.amt);
      if (t.amount != null && !isFinite(amt)) badMoney++;
      if (isFinite(amt) && amt < 0) negative++;
      if (!t.type) noType++;
      if (t.date && isNaN(new Date(t.date + 'T00:00:00').getTime())) badDate++;
      if (t.id != null){ if (ids[t.id]) dupId++; else ids[t.id] = 1; }
      var key = String(t.type || '') + '|' + String(t.inv || '').trim();
      if (String(t.inv || '').trim()){ if (invs[key]) dupInv++; else invs[key] = 1; }
    });

    if (badMoney) issues.push(badMoney + ' transaction(s) with a non-numeric amount');
    if (negative) issues.push(negative + ' transaction(s) with a negative amount');
    if (badDate)  issues.push(badDate + ' transaction(s) with an invalid date');
    if (dupId)    issues.push(dupId + ' duplicate transaction id(s)');
    if (dupInv)   issues.push(dupInv + ' duplicate invoice number(s)');
    if (noType)   issues.push(noType + ' transaction(s) with no type');

    /* orphan references */
    var partyNames = {}, productNames = {};
    (db.parties || []).forEach(function(p){ if (p && p.name) partyNames[String(p.name).trim()] = 1; });
    (db.products || []).forEach(function(p){ if (p && p.name) productNames[String(p.name).trim()] = 1; });
    if (Object.keys(partyNames).length){
      var orphanParty = tx.filter(function(t){ var n = t && String(t.party || '').trim(); return n && !partyNames[n]; }).length;
      if (orphanParty) issues.push(orphanParty + ' transaction(s) reference a party that no longer exists');
    }
    if (Object.keys(productNames).length){
      var orphanProd = tx.filter(function(t){
        if (t && Array.isArray(t.items) && t.items.length){
          return t.items.some(function(it){
            var n = it && String(it.prod || it.product || '').trim();
            return n && !productNames[n];
          });
        }
        var n = t && String(t.prod || '').trim();
        return n && !productNames[n];
      }).length;
      if (orphanProd) issues.push(orphanProd + ' transaction(s) reference a product that no longer exists');
    }

    var result = { checked: tx.length, issues: issues, clean: issues.length === 0 };
    if (!silent) showReport(result);
    return result;
  }

  function showReport(res){
    var old = el('di-report'); if (old) old.parentNode.removeChild(old);
    var box = D.createElement('div');
    box.id = 'di-report';
    box.innerHTML = '<button class="di-close" type="button" aria-label="Close">×</button>' +
      '<h4>' + (res.clean ? '✅ Data integrity: all clean' : '⚠️ Data integrity: ' + res.issues.length + ' issue(s)') + '</h4>' +
      '<div style="font-size:12px;opacity:.75;margin-bottom:6px;">' + res.checked + ' transaction(s) checked</div>' +
      (res.issues.length ? '<ul><li>' + res.issues.join('</li><li>') + '</li></ul>' : '');
    box.querySelector('.di-close').onclick = function(){ box.parentNode && box.parentNode.removeChild(box); };
    D.body.appendChild(box);
    setTimeout(function(){ if (box.parentNode && res.clean) box.parentNode.removeChild(box); }, 6000);
  }
  W.erpIntegrityCheck = integrityCheck;

  function applyGuards(){
    guard('saveTx', validateTxForm, 'saveTx');
    guard('_executeSaveTx', null, 'execSaveTx');
    guard('saveProd', validateProdForm, 'saveProd');
    guard('savePaymentEntry', null, 'savePaymentEntry');
    guard('savePaymentVoucherOnly', null, 'savePaymentVoucherOnly');
  }

  function boot(){
    applyGuards();
    /* other feature blocks re-wrap some saves inside their own timers, which
       would drop our guard — re-apply (idempotently) shortly after load. */
    setTimeout(applyGuards, 1500);
    setTimeout(applyGuards, 5000);
    setTimeout(function(){
      try{
        var r = integrityCheck({ silent: true });
        if (!r.clean) console.warn('[integrity] startup audit:', r.issues);
        else console.info('[integrity] startup audit clean —', r.checked, 'transactions');
      }catch(e){ console.warn('[integrity] audit failed', e); }
    }, 4000);
    console.info('[Data integrity] input hardening, save guards and window.erpIntegrityCheck() active');
  }
  if (D.readyState === 'loading') D.addEventListener('DOMContentLoaded', boot);
  else boot();
})();
</script>

