<!-- ═══════════════════════════════════════════════════════════════════════
     NAV COMPACT STYLE — injected last so it wins specificity wars.
     Goal: shrink the 150+ item sidebar to something usable without
     touching any HTML, IDs, onclick handlers or page logic.
     ═══════════════════════════════════════════════════════════════════════ -->
<style id="nav-compact-style">

/* ── Section headers: tighter, smaller label ── */
.nav-label {
  font-size: 8.5px !important;
  letter-spacing: 1px !important;
  padding: 7px 14px 2px !important;
  opacity: .75 !important;
}
.nav-section-header {
  padding: 0 !important;
}

/* ── Nav items: reduce height & font ── */
.nav-item {
  padding: 5px 12px !important;
  font-size: 11.5px !important;
  gap: 7px !important;
  min-height: unset !important;
  line-height: 1.3 !important;
}
.nav-icon {
  font-size: 13px !important;
  width: 18px !important;
  text-align: center;
  flex-shrink: 0;
}

/* ── Sub-group labels ── */
.nav-sublabel {
  font-size: 8px !important;
  padding: 5px 12px 2px !important;
  letter-spacing: .8px !important;
  opacity: .6 !important;
}

/* ── Section gaps ── */
.nav-section {
  padding: 1px 0 !important;
}

/* ── "More Modules" items: they have no inner <span> structure
      so just normalise padding ── */
.nav-section[data-section="more"] .nav-item {
  padding: 4px 12px !important;
  font-size: 11.5px !important;
}

/* ── Active item stays readable ── */
.nav-item.active {
  padding: 6px 12px !important;
  font-size: 12px !important;
  font-weight: 700 !important;
}

/* ── Icon-collapsed rail stays the same ── */
.sidebar.icon-collapsed .nav-item {
  padding: 9px !important;
}

/* ── Mobile: restore comfortable touch targets ── */
@media (max-width: 768px) {
  .nav-item { padding: 8px 14px !important; font-size: 13px !important; }
  .nav-label { font-size: 9px !important; padding: 8px 14px 3px !important; }
}
</style>

<script nonce="<?php echo $cspNonceAttr; ?>" id="nav-compact-init">
/* Sections are pre-collapsed in HTML. This script only handles
   auto-expanding the correct section when a nav() call makes an
   item active. Wraps window.nav once it's available. */
(function compactNavInit() {
  function expandActiveSection() {
    var active = document.querySelector('.nav-item.active');
    if (!active) return;
    var section = active.closest('.nav-section');
    if (section && section.classList.contains('collapsed')) {
      section.classList.remove('collapsed');
      var body = section.querySelector('.nav-section-body');
      if (body) body.style.display = '';
      var chev = section.querySelector('.nav-section-chevron');
      if (chev) chev.textContent = '\u25BE';
    }
  }

  function hookNav() {
    if (typeof window.nav !== 'function') return;
    var _orig = window.nav;
    window.nav = function(page) {
      _orig.apply(this, arguments);
      setTimeout(expandActiveSection, 80);
    };
  }

  // Hook nav() as soon as DOM is ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function() {
      setTimeout(hookNav, 600);
      setTimeout(expandActiveSection, 700);
    });
  } else {
    setTimeout(hookNav, 600);
    setTimeout(expandActiveSection, 700);
  }
})();
</script>

<script nonce="<?php echo $cspNonceAttr; ?>" id="fix-multiproduct-stock">
/* ═══════════════════════════════════════════════════════════════════════
   BUGFIX — Multi-Product purchases/sales silently skipped real inventory.
   The "📦 Multiple Products (same supplier)" checkbox in New Transaction
   (added earlier in this file) saves the whole invoice as ONE transaction
   with tx.items = [{prod,qty,rate,amount,...}, ...], and it syncs a
   *combined* summary into tx.prod (e.g. "Rice + Wheat") / tx.qty (summed)
   for display. But applyTxStock() only ever knew about a single tx.prod /
   tx.qty pair, so a multi-item purchase tried to move stock for one product
   literally named "Rice + Wheat" (auto-creating a bogus phantom product)
   instead of crediting Rice and Wheat individually — real stock for every
   product on a multi-item invoice never moved.
   Fix: when tx.items is present, run the exact same per-transaction stock
   logic once per real item (same product-lookup/avg-cost math, just fed
   that item's own prod/qty/rate/amount) instead of the blended summary.
   ═══════════════════════════════════════════════════════════════════════ */
(function(){
  'use strict';
  var _prevApplyStock = window.applyTxStock;
  if(typeof _prevApplyStock !== 'function') return;
  window.applyTxStock = function(tx, dir){
    if(tx && Array.isArray(tx.items) && tx.items.length){
      tx.items.forEach(function(item){
        var line = {};
        for(var k in tx){ line[k]=tx[k]; }
        line.prod = line.product = item.prod;
        line.qty = item.qty; line.wt = item.wt; line.grosswt = item.grosswt;
        line.bagqty = item.bagqty;
        line.rate = item.rate;
        line.amt = line.amount = item.amount;
        _prevApplyStock(line, dir);
      });
      return;
    }
    return _prevApplyStock.apply(this, arguments);
  };
})();
</script>

<script nonce="<?php echo $cspNonceAttr; ?>" id="always-dropdown-nav">
/* ═══════════════════════════════════════════════════════════════════════
   Sidebar: back to the app's original responsive behaviour — always
   visible/fixed on the left on a normal-width screen, and only a
   hamburger dropdown/drawer on narrow (mobile-width) screens. An earlier
   version of this patch made the dropdown the permanent behaviour at
   every screen size; that's been undone per request, keeping only the
   genuine bugfix below (the dropdown drawer, when it IS open on a small
   screen, no longer covers the topbar/hamburger button that closes it).
   Scoped to the same <=600px breakpoint the app's own native mobile
   drawer CSS already uses (see the plain "@media(max-width:600px)" rule
   earlier in this file that sets `.sidebar.mobile-open{left:0}`), so
   desktop/tablet sizes are completely unaffected.
   ═══════════════════════════════════════════════════════════════════════ */
</script>
<style id="always-dropdown-nav-css">
@media (max-width:600px){
  /* Topbar (and the hamburger button inside it) must stack ABOVE the
     dropdown sidebar, not below it — otherwise, once open, the sidebar's
     own header visually covers the very button used to close it again
     (z-index alone doesn't fix this across separate stacking contexts;
     the topbar's own z-index has to beat the sidebar's). The sidebar
     starts below the topbar (top offset = topbar height) instead of at
     the very top of the screen, so opening it never hides the
     topbar/hamburger in the first place. */
  .topbar{left:0 !important;right:0 !important;z-index:1001 !important;}
  .sidebar{
    position:fixed !important;
    top:var(--topbar-h,56px) !important;
    left:-270px !important;
    width:270px !important;
    max-width:88vw !important;
    height:calc(var(--app-vh,100vh) - var(--topbar-h,56px)) !important;
    transition:left .25s ease !important;
    z-index:1000 !important;
    box-shadow:none;
  }
  .sidebar.mobile-open{
    left:0 !important;
    box-shadow:4px 0 28px rgba(15,23,42,.28) !important;
  }
  #sidebarOverlay{z-index:999 !important;top:var(--topbar-h,56px) !important;}
  #sidebarOverlay.active{display:block !important;}
}
@media print{
  .sidebar{transform:none !important;}
}
</style>

<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-business-rules">
/* ═══════════════════════════════════════════════════════════════════════
   BUSINESS RULES — every trading rule in one editable place
   ═══════════════════════════════════════════════════════════════════════
   The bag tare, the unloading basis, the per-KG sale costs, the withholding
   tax rate and the standard bag weight used to be constants written into
   the code — 0.15 kg here, ৳3 a bag there, 0.5% somewhere else. Changing how
   the business works meant editing the file. They are settings now: this
   module owns them, every calculation reads them from here, and the panel it
   adds to Cost Calculation and to Settings edits them.

   Bag types are a list you control, not a fixed Jute/Plastic/Bulk choice.
   Add "Drum" or "Jumbo Bag" with its own tare and unloading basis and it
   appears in the Bag Type dropdown on every entry form straight away.
   ═══════════════════════════════════════════════════════════════════════ */
(function(){
'use strict';
var W=window;
function N(v){var n=parseFloat(v);return isFinite(n)?n:0;}
function esc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}

var DEFAULTS={
  bagTypes:[
    {name:'Jute',    tareKg:0.7,  unloadBasis:'bag', unloadRate:3},
    {name:'Plastic', tareKg:0.15, unloadBasis:'bag', unloadRate:3},
    {name:'Bulk',    tareKg:0,    unloadBasis:'ton', unloadRate:50}
  ],
  bagWeightKg:50,
  saleCost:{agentA:0.25,agentB:0.30,qc:0.10,other:0.50,other2:0},
  salesTaxPct:0.05,   /* FIX: 0.5% was a placeholder. The real rate deducted at source is 0.05%. */
  salesTaxEnabled:true,
  paymentNetDays:7,
  /* Purchase side. Every figure starts at zero / off, so the app behaves
     exactly as before until a rule is actually entered. */
  purchase:{
    applyBagTare:false,   // take the sacks' weight off the purchase too
    moisturePct:0,        // % of weight cut for moisture or quality
    rateCutPerKg:0,       // ৳ off the price per KG instead of off the weight
    autoUnload:false,     // fill unloading from the bag type on purchases
    labourPerKg:0,        // ৳/KG labour paid at the mill
    commissionPerKg:0     // ৳/KG broker commission
  }
};

function rules(){
  var D=W.DB||(W.DB={});
  if(!D.rules||typeof D.rules!=='object') D.rules={};
  var r=D.rules;
  if(!Array.isArray(r.bagTypes)||!r.bagTypes.length){
    r.bagTypes=DEFAULTS.bagTypes.map(function(b){return {name:b.name,tareKg:b.tareKg,unloadBasis:b.unloadBasis,unloadRate:b.unloadRate};});
  }
  r.bagTypes.forEach(function(b){
    b.name=String(b.name||'').trim();
    b.tareKg=N(b.tareKg);
    b.unloadBasis=(b.unloadBasis==='ton')?'ton':'bag';
    b.unloadRate=N(b.unloadRate);
  });
  /* FIX (bag tare rule): Jute bags used to carry no tare by default (0 g),
     which was wrong — Jute, like Plastic, has its own sack weight and the
     bank deducts it the same way: Plastic 150 g/bag, Jute 700 g/bag. This
     runs once per install to correct any Jute entry still sitting at the
     old 0 default; it never re-applies after that, so a deliberate manual
     change to Jute's tare later (including back to 0) is respected. */
  if(!r._migJuteTare700){
    r.bagTypes.forEach(function(b){
      if(b.name.toLowerCase()==='jute' && b.tareKg===0) b.tareKg=0.7;
    });
    r._migJuteTare700=true;
  }
  if(r.bagWeightKg==null)    r.bagWeightKg=DEFAULTS.bagWeightKg;
  if(!r.saleCost)            r.saleCost={};
  ['agentA','agentB','qc','other','other2'].forEach(function(k){
    if(r.saleCost[k]==null) r.saleCost[k]=(D.costRates&&D.costRates[k]!=null)?N(D.costRates[k]):DEFAULTS.saleCost[k];
  });
  if(r.salesTaxPct==null)    r.salesTaxPct=N((D.settings||{}).salesTaxRate)||DEFAULTS.salesTaxPct;
  if(r.salesTaxEnabled==null)r.salesTaxEnabled=DEFAULTS.salesTaxEnabled;
  if(r.paymentNetDays==null) r.paymentNetDays=DEFAULTS.paymentNetDays;
  if(!r.purchase||typeof r.purchase!=='object') r.purchase={};
  Object.keys(DEFAULTS.purchase).forEach(function(k){
    if(r.purchase[k]==null) r.purchase[k]=DEFAULTS.purchase[k];
  });
  r.purchase.applyBagTare=!!r.purchase.applyBagTare;
  r.purchase.autoUnload=!!r.purchase.autoUnload;
  ['moisturePct','rateCutPerKg','labourPerKg','commissionPerKg'].forEach(function(k){
    r.purchase[k]=N(r.purchase[k]);
  });
  mirror();
  return r;
}
/* Older code reads DB.costRates and DB.settings directly, so the rules are
   copied back into those names on every read — one master, no drift. */
function mirror(){
  var D=W.DB, r=D.rules;
  if(!D.costRates) D.costRates={};
  ['agentA','agentB','qc','other','other2'].forEach(function(k){ D.costRates[k]=N(r.saleCost[k]); });
  var bagged=r.bagTypes.filter(function(b){return b.unloadBasis==='bag';})[0];
  D.costRates.unload=bagged?N(bagged.unloadRate):N(D.costRates.unload);
  var bulk=r.bagTypes.filter(function(b){return b.unloadBasis==='ton';})[0];
  D.costRates.unloadBulk=bulk?N(bulk.unloadRate):50;
  D.costRates.tare={};
  r.bagTypes.forEach(function(b){ if(b.name) D.costRates.tare[b.name]=N(b.tareKg); });
  if(!D.settings) D.settings={};
  D.settings.salesTaxRate=N(r.salesTaxPct);
  D.settings.salesTaxEnabled=!!r.salesTaxEnabled;
}
function findType(name){
  var t=String(name||'').trim().toLowerCase();
  if(!t) return null;
  return rules().bagTypes.filter(function(b){return String(b.name).toLowerCase()===t;})[0]||null;
}
W.ayanRules=rules;
W.ayanBagTypes=function(){ return rules().bagTypes.map(function(b){return b.name;}).filter(Boolean); };
W.ayanBagRules=function(){ rules(); return W.DB.costRates; };
W.ayanIsBulk=function(name){ var b=findType(name); return !!b && b.unloadBasis==='ton'; };
W.ayanBagTareKg=function(name){ var b=findType(name); return b?N(b.tareKg):0; };
W.ayanUnloadCost=function(name,bags,kg){
  var b=findType(name);
  if(!b) return N(bags)*N((W.DB.costRates||{}).unload);
  return b.unloadBasis==='ton' ? (N(kg)/1000)*N(b.unloadRate) : N(bags)*N(b.unloadRate);
};
W.ayanPurchaseRules=function(){ return rules().purchase; };
/* ── BLENDED WAREHOUSE POOL ───────────────────────────────────────────
   Bran bought into the warehouse is mixed and sold under one brand name,
   so once it goes into the pool it stops being DORB or Auto Bran. Stock and
   cost are booked to the brand; ordinary Purchases keep their own identity
   and their own average. The brand is whatever is set as "Sale Brand Name"
   in Warehouse Costing, and it must be a real product or the sales can
   never match it. */
/* Money still owed on bank loans, LC margins and overdrafts recorded in the
   Loan / LC Tracker. The tracker held them as a note to itself: take a
   ৳5,00,000 loan, bank it, and the balance sheet went out by exactly that —
   the cash arrived with nothing owing against it. */
/* Costs and liabilities the balance sheet was blind to.

   Three of them, all visible in a live file: a Factory Finance drawdown puts
   the bank's money in your account and is owed back, but appeared nowhere as
   a liability; truck rent and the per-bag sale costs (agent, QC, unloading,
   other) are real costs that were never taken off profit, and the unpaid
   part of them is money you owe. Between them they left a ৳842.45 hole in a
   file with only two transactions in it. */
W.ayanTransportDue=function(){
  try{ return (W.DB.transportDues||[]).reduce(function(s,d){ return s+(parseFloat(d.outstanding!=null?d.outstanding:d.due)||0); },0); }catch(e){ return 0; }
};
W.ayanSaleCostDue=function(){
  /* Superseded by the granular Cost Ledgers (ayan-cost-lines): Agent A,
     Agent B, QC, Unload and Other are now tracked and paid as separate
     lines instead of one lumped total, so this reads from there. */
  try{ if(typeof W.costLineTotal==='function') return W.costLineTotal(); }catch(e){}
  try{ return (W.DB.saleCostDues||[]).reduce(function(s,d){ return s+(parseFloat(d.outstanding)||0); },0); }catch(e){ return 0; }
};
/* FIX (an expense you have not paid yet went nowhere): recording rent, a
   salary or a bill as "not paid yet" takes it off profit straight away —
   correctly, you have incurred it — but nothing on the other side of the
   books carried what you now owe for it. Every unpaid expense therefore threw
   the statement out by its own amount: a ৳12,000 rent left unpaid put the two
   columns ৳12,000 apart with nothing to show why. It is a creditor until it
   is paid, and it now appears as one. */
W.ayanExpensePayable=function(){
  try{
    return (W.DB.tx||[]).reduce(function(s,t){
      if(!t) return s;
      var isExp = (typeof W.ayanExpenseTxs==='function')
        ? (String(t.cat||'')==='Expense' || (W.EXPENSE_TX_TYPES && W.EXPENSE_TX_TYPES.has(String(t.type||''))))
        : false;
      if(!isExp) return s;
      var d=parseFloat(t.due)||0;
      return d>0 ? s+d : s;
    },0);
  }catch(e){ return 0; }
};
/* FIX (the financier's fee was charged to nobody): a Factory Finance
   drawdown records a fee, interest and charges on the invoice — ৳0.50 on the
   22-Aug drawdown — but nothing anywhere read them. They were not taken off
   profit, not held as a liability and not taken out of any bank, so the cost
   of financing an invoice was invisible and the two sides of the books were
   out by exactly that amount as soon as you worked profit out properly.

   The charge is an expense the moment the drawdown is funded (see ayanPL),
   and while the drawdown is still outstanding it is money owed to the
   financier — it comes out of the held-back balance at settlement, which is
   why `net` is holdback less fee, interest and charges. So: an expense on
   every row, and a liability only while the row is unsettled. Both states
   balance. */
W.ayanFinanceCharges=function(onlyFunded){
  try{
    /* FIX (double-counted finance charges): 'charges' is already fee+interest
       — that's exactly how the City Finance settle screen computes it
       ("Total Charges = Fee + Interest"). Adding fee and interest again on
       top of charges counted the same taka twice, inflating both this
       expense line and (via ayanPL) understating Net Profit by the same
       amount. */
    return (W.DB.cityFinance||[]).reduce(function(s,r){
      if(onlyFunded && String(r.status)!=='Funded') return s;
      return s + (parseFloat(r.charges)||0);
    },0);
  }catch(e){ return 0; }
};
W.ayanFinanceOutstanding=function(){
  try{
    return (W.DB.cityFinance||[]).reduce(function(s,r){
      return s + (String(r.status)==='Funded' ? (parseFloat(r.advPaid)||0) : 0);
    },0) + W.ayanFinanceCharges(true);
  }catch(e){ return 0; }
};
/* Truck rent and the per-bag handling costs carried on the transactions
   themselves — paid or not, they are costs of doing the business. */
W.ayanTxSideCosts=function(list){
  try{
    return (list||W.DB.tx||[]).reduce(function(s,t){
      return s + (parseFloat(t.truckrent)||0)
               + (parseFloat(t.agentAcost)||0) + (parseFloat(t.agentBcost)||0)
               + (parseFloat(t.qc)||0) + (parseFloat(t.unload)||0) + (parseFloat(t.othercost)||0) + (parseFloat(t.othercost2)||0);
    },0);
  }catch(e){ return 0; }
};
W.ayanLoansOutstanding=function(){
  try{
    return (W.DB.loans||[]).reduce(function(sum,l){
      if(String(l.status||'').toLowerCase()==='closed') return sum;
      var out=(parseFloat(l.principal!=null?l.principal:l.amount)||0)-(parseFloat(l.paid)||0);
      return sum+(out>0?out:0);
    },0);
  }catch(e){ return 0; }
};
W.ayanIsWarehousePurchase=function(t){
  return ['warehouse purchase','werhouse purchase','opening warehouse purchase','opening werhouse purchase']
    .indexOf(String(t||'').toLowerCase().trim())>=0;
};
W.ayanPoolBrand=function(){
  try{
    if(!W.DB.whCost) W.DB.whCost={};
    var list=(W.DB.products||W.DB.inventory||[]);
    var b=W.DB.whCost.brand||'';
    /* Settled here rather than only when the Warehouse Costing screen is
       opened — the stock and cost engines need it on every page load. */
    if(!b){
      var seed=list.filter(function(p){ return /par\s*boil/i.test(p.name) && /high\s*fat/i.test(p.name); })[0];
      b=seed?seed.name:'';
      if(b) W.DB.whCost.brand=b;
    }
    if(!b) return '';
    var hit=list.filter(function(p){return String(p.name).toLowerCase().trim()===String(b).toLowerCase().trim();})[0];
    if(hit && hit.name!==W.DB.whCost.brand) W.DB.whCost.brand=hit.name;
    return hit?hit.name:b;
  }catch(e){ return ''; }
};
W.ayanStockProduct=function(t){
  try{
    if(!W.ayanIsWarehousePurchase(t&&t.type)) return t&&t.prod;
    var brand=W.ayanPoolBrand();
    return brand||(t&&t.prod);
  }catch(e){ return t&&t.prod; }
};
W.ayanIsPurchaseType=function(t){
  return ['purchase','warehouse purchase','supplier purchase','werhouse purchase']
    .indexOf(String(t||'').toLowerCase().trim())>=0;
};
W.ayanUnloadLabel=function(name){
  var b=findType(name);
  if(!b) return 'Bag×'+N((W.DB.costRates||{}).unload);
  return b.unloadBasis==='ton' ? ('1000KG×'+N(b.unloadRate)) : ('Bag×'+N(b.unloadRate));
};

/* ── Bag Type dropdowns follow the list ──────────────────────────────── */
W.ayanSyncBagTypeSelects=function(){
  var names=W.ayanBagTypes();
  document.querySelectorAll('select#tx-bagtype, select[data-bagtype]').forEach(function(sel){
    var keep=sel.value;
    sel.innerHTML='<option value="">-- Bag Type --</option>'+names.map(function(n){
      return '<option value="'+esc(n)+'">'+esc(n)+'</option>';}).join('');
    if(keep && names.indexOf(keep)<0){
      sel.insertAdjacentHTML('beforeend','<option value="'+esc(keep)+'">'+esc(keep)+'</option>');
    }
    sel.value=keep;
  });
};

/* ── The editor ──────────────────────────────────────────────────────── */
function panelHTML(){
  var r=rules();
  var row=function(b,i){
    return '<tr>'
      +'<td style="padding:6px 8px;"><input class="fc" data-br="name" data-i="'+i+'" value="'+esc(b.name)+'" style="min-width:110px;"/></td>'
      +'<td style="padding:6px 8px;"><input class="fc" data-br="tareKg" data-i="'+i+'" type="number" step="0.001" min="0" value="'+N(b.tareKg)+'" style="width:100px;text-align:right;"/></td>'
      +'<td style="padding:6px 8px;"><select class="fc" data-br="unloadBasis" data-i="'+i+'" style="min-width:130px;">'
        +'<option value="bag"'+(b.unloadBasis==='bag'?' selected':'')+'>Per bag</option>'
        +'<option value="ton"'+(b.unloadBasis==='ton'?' selected':'')+'>Per 1000 KG</option></select></td>'
      +'<td style="padding:6px 8px;"><input class="fc" data-br="unloadRate" data-i="'+i+'" type="number" step="0.01" min="0" value="'+N(b.unloadRate)+'" style="width:110px;text-align:right;"/></td>'
      +'<td style="padding:6px 8px;text-align:center;"><button class="btn btn-xs btn-danger" data-brdel="'+i+'" title="Remove">🗑</button></td>'
      +'</tr>';
  };
  var num=function(label,id,val,step,hint){
    return '<div><label style="font-size:11px;color:#6b7280;font-weight:700;display:block;margin-bottom:3px;">'+label+'</label>'
      +'<input class="fc" id="'+id+'" type="number" step="'+(step||'0.01')+'" min="0" value="'+val+'" style="text-align:right;"/>'
      +(hint?'<div style="font-size:10px;color:#9ca3af;margin-top:3px;">'+hint+'</div>':'')+'</div>';
  };
  return ''
  +'<div class="card" id="ayan-br-card" style="margin-top:16px;">'
  +'<div style="font-size:15px;font-weight:800;color:#0f3d26;margin-bottom:4px;">⚙️ Business Rules</div>'
  +'<div style="font-size:11.5px;color:#6b7280;margin-bottom:14px;">Everything the sale and purchase forms calculate from. Change it here and every entry from now on follows the new rule.</div>'

  +'<div style="font-size:13px;font-weight:800;color:#0f3d26;margin:14px 0 6px;">Bag types</div>'
  +'<div style="font-size:11px;color:#6b7280;margin-bottom:8px;">Tare is the weight of the empty sack, deducted from the weight you bill. Bulk is sold loose — set its tare to 0 and charge unloading per 1000 KG.</div>'
  +'<div style="overflow-x:auto;"><table class="tbl" style="width:100%;border-collapse:collapse;font-size:12.5px;">'
  +'<thead><tr style="background:#f0fdf4;"><th style="padding:7px 8px;text-align:left;">Bag type</th>'
  +'<th style="padding:7px 8px;text-align:right;">Tare (KG/bag)</th>'
  +'<th style="padding:7px 8px;text-align:left;">Unloading charged</th>'
  +'<th style="padding:7px 8px;text-align:right;">Rate (৳)</th><th style="padding:7px 8px;"></th></tr></thead>'
  +'<tbody id="ayan-br-rows">'+r.bagTypes.map(row).join('')+'</tbody></table></div>'
  +'<button class="btn btn-xs" id="ayan-br-add" style="margin-top:8px;">➕ Add bag type</button>'

  +'<div style="font-size:13px;font-weight:800;color:#0f3d26;margin:18px 0 8px;">Sale costs</div>'
  +'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;">'
  + num('Agent A (৳/KG)','br-agentA',N(r.saleCost.agentA))
  + num('Agent B (৳/KG)','br-agentB',N(r.saleCost.agentB))
  + num('QC (৳/KG)','br-qc',N(r.saleCost.qc))
  + num('Other (৳/KG)','br-other',N(r.saleCost.other))
  + num('Another 2 (৳/KG)','br-other2',N(r.saleCost.other2))
  +'</div>'

  +'<div style="font-size:13px;font-weight:800;color:#0f3d26;margin:18px 0 8px;">Tax &amp; terms</div>'
  +'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;">'
  + num('Withholding tax (%)','br-tax',N(r.salesTaxPct),'0.01','Deducted at source by the buyer')
  + num('Standard bag weight (KG)','br-bagkg',N(r.bagWeightKg),'0.01','Used where a weight is not entered')
  + num('Payment terms (days)','br-netdays',N(r.paymentNetDays),'1','Due date on a credit sale or purchase')
  +'<div><label style="font-size:11px;color:#6b7280;font-weight:700;display:block;margin-bottom:3px;">Deduct withholding tax</label>'
  +'<select class="fc" id="br-taxon"><option value="1"'+(r.salesTaxEnabled?' selected':'')+'>Yes — on every sale</option>'
  +'<option value="0"'+(!r.salesTaxEnabled?' selected':'')+'>No</option></select></div>'
  +'</div>'

  +'<div style="font-size:13px;font-weight:800;color:#0f3d26;margin:18px 0 6px;">VAT</div>'
  +'<div style="font-size:11px;color:#6b7280;margin-bottom:8px;">These rates drive the VAT report and the VAT deducted in Warehouse Costing. They used to reset to 15% every time the app was opened.</div>'
  +'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px;">'
  + num('VAT on sales (%)','br-vat-sales',N(r.vatSalesPct!=null?r.vatSalesPct:15))
  + num('VAT on purchases (%)','br-vat-purch',N(r.vatPurchPct!=null?r.vatPurchPct:15))
  +'<div><label style="font-size:11px;color:#6b7280;font-weight:700;display:block;margin-bottom:3px;">Do your prices include VAT?</label>'
  +'<select class="fc" id="br-vat-incl"><option value="0"'+(!r.vatInclusive?' selected':'')+'>No \u2014 VAT is added on top</option>'
  +'<option value="1"'+(r.vatInclusive?' selected':'')+'>Yes \u2014 VAT is inside the price</option></select>'
  +'<div style="font-size:10px;color:#9ca3af;margin-top:3px;">Set 0% if your goods are VAT exempt</div></div>'
  +'</div>'

  +'<div style="font-size:13px;font-weight:800;color:#0f3d26;margin:18px 0 6px;">Purchase deductions</div>'
  +'<div style="font-size:11px;color:#6b7280;margin-bottom:8px;">What comes off when goods arrive. All zero means nothing is deducted \u2014 the amount stays weight \u00d7 rate, exactly as now.</div>'
  +'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px;">'
  +'<div><label style="font-size:11px;color:#6b7280;font-weight:700;display:block;margin-bottom:3px;">Deduct bag tare on purchase</label>'
  +'<select class="fc" id="br-p-tare"><option value="0"'+(!r.purchase.applyBagTare?' selected':'')+'>No</option>'
  +'<option value="1"'+(r.purchase.applyBagTare?' selected':'')+'>Yes \u2014 same tare as the bag type</option></select></div>'
  + num('Moisture / quality cut (%)','br-p-moist',N(r.purchase.moisturePct),'0.01','% of the weighed quantity')
  + num('Rate cut (\u09f3/KG)','br-p-ratecut',N(r.purchase.rateCutPerKg),'0.01','Taken off the price instead of the weight')
  +'</div>'
  +'<div style="font-size:13px;font-weight:800;color:#0f3d26;margin:18px 0 6px;">Purchase costs</div>'
  +'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:12px;">'
  +'<div><label style="font-size:11px;color:#6b7280;font-weight:700;display:block;margin-bottom:3px;">Auto-fill unloading</label>'
  +'<select class="fc" id="br-p-unload"><option value="0"'+(!r.purchase.autoUnload?' selected':'')+'>No</option>'
  +'<option value="1"'+(r.purchase.autoUnload?' selected':'')+'>Yes \u2014 use the bag type\u2019s rate</option></select></div>'
  + num('Labour (\u09f3/KG)','br-p-labour',N(r.purchase.labourPerKg))
  + num('Commission (\u09f3/KG)','br-p-comm',N(r.purchase.commissionPerKg))
  +'</div>'

  +'<div style="display:flex;gap:8px;align-items:center;margin-top:16px;flex-wrap:wrap;">'
  +'<button class="btn btn-success" id="ayan-br-save">💾 Save business rules</button>'
  +'<span id="ayan-br-msg" style="font-size:12px;color:#16a34a;font-weight:700;"></span></div>'
  +'</div>';
}

/* Scoped to one card: the panel is shown on more than one page, and reading
   the whole document instead picked up every copy and duplicated the list. */
function readPanel(card){
  card=card||document.querySelector('#ayan-br-card');
  if(!card) return;
  var r=rules(), list=[];
  card.querySelectorAll('#ayan-br-rows tr').forEach(function(tr){
    var g=function(k){var el=tr.querySelector('[data-br="'+k+'"]');return el?el.value:'';};
    var nm=String(g('name')||'').trim();
    if(!nm) return;
    list.push({name:nm,tareKg:N(g('tareKg')),unloadBasis:(g('unloadBasis')==='ton'?'ton':'bag'),unloadRate:N(g('unloadRate'))});
  });
  if(list.length) r.bagTypes=list;
  var v=function(id){var el=card.querySelector('#'+id);return el?el.value:null;};
  if(v('br-agentA')!==null) r.saleCost.agentA=N(v('br-agentA'));
  if(v('br-agentB')!==null) r.saleCost.agentB=N(v('br-agentB'));
  if(v('br-qc')!==null)     r.saleCost.qc=N(v('br-qc'));
  if(v('br-other')!==null)  r.saleCost.other=N(v('br-other'));
  if(v('br-other2')!==null) r.saleCost.other2=N(v('br-other2'));
  if(v('br-tax')!==null){   r.salesTaxPct=N(v('br-tax'));
                            try{ window.DB.taxRateUserSet=true; }catch(e){} }
  if(v('br-bagkg')!==null)  r.bagWeightKg=N(v('br-bagkg'));
  if(v('br-netdays')!==null)r.paymentNetDays=N(v('br-netdays'));
  if(v('br-taxon')!==null)  r.salesTaxEnabled=v('br-taxon')==='1';
  if(v('br-vat-sales')!==null) r.vatSalesPct=N(v('br-vat-sales'));
  if(v('br-vat-purch')!==null) r.vatPurchPct=N(v('br-vat-purch'));
  if(v('br-vat-incl')!==null)  r.vatInclusive=v('br-vat-incl')==='1';
  try{ if(typeof W.ayanVatRules==='function') W.ayanVatRules(); }catch(e){}
  if(v('br-p-tare')!==null)    r.purchase.applyBagTare=v('br-p-tare')==='1';
  if(v('br-p-moist')!==null)   r.purchase.moisturePct=N(v('br-p-moist'));
  if(v('br-p-ratecut')!==null) r.purchase.rateCutPerKg=N(v('br-p-ratecut'));
  if(v('br-p-unload')!==null)  r.purchase.autoUnload=v('br-p-unload')==='1';
  if(v('br-p-labour')!==null)  r.purchase.labourPerKg=N(v('br-p-labour'));
  if(v('br-p-comm')!==null)    r.purchase.commissionPerKg=N(v('br-p-comm'));
  mirror();
  try{ if(W.DB.whCost) W.DB.whCost.bagKg=N(r.bagWeightKg); }catch(e){}
  if(typeof W.saveDBNow==='function') W.saveDBNow(); else if(typeof W.saveDB==='function') W.saveDB();
  W.ayanSyncBagTypeSelects();
}

function wire(host){
  var card=host.querySelector('#ayan-br-card');
  if(!card) return;
  var add=card.querySelector('#ayan-br-add');
  if(add) add.onclick=function(){
    readPanel(card);
    rules().bagTypes.push({name:'',tareKg:0,unloadBasis:'bag',unloadRate:N((W.DB.costRates||{}).unload)});
    redraw(host);
  };
  card.querySelectorAll('[data-brdel]').forEach(function(b){
    b.onclick=function(){
      readPanel(card);
      var i=parseInt(b.getAttribute('data-brdel'),10);
      var r=rules();
      if(r.bagTypes.length<=1){ try{W.toast('Keep at least one bag type','e');}catch(e){} return; }
      r.bagTypes.splice(i,1);
      redraw(host);
    };
  });
  var save=card.querySelector('#ayan-br-save');
  if(save) save.onclick=function(){
    readPanel(card);
    var m=card.querySelector('#ayan-br-msg');
    if(m){ m.textContent='✓ Saved — new entries use these rules'; setTimeout(function(){m.textContent='';},4000); }
    try{ W.toast('Business rules saved','s'); }catch(e){}
  };
}
function redraw(host){
  attach(host.id);
}
/* Only ever one panel in the document, so its ids stay unique. */
function attach(pageId){
  var host=document.getElementById(pageId);
  if(!host) return;
  document.querySelectorAll('#ayan-br-card').forEach(function(c){ c.remove(); });
  host.insertAdjacentHTML('beforeend',panelHTML());
  wire(host);
}
W.ayanAttachRulesPanel=attach;

/* Show it on Cost Calculation and on Settings, after their own content. */
function hook(name,pageId){
  var orig=W[name];
  if(typeof orig!=='function') return;
  W[name]=function(){
    var out;
    try{ out=orig.apply(this,arguments); }catch(e){}
    try{ attach(pageId); }catch(e){}
    return out;
  };
}
function boot(){
  rules();
  hook('renderCostCalc','pg-costcalc');
  hook('renderSettings','pg-settings');
  W.ayanSyncBagTypeSelects();
}
if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',function(){setTimeout(boot,400);});
else setTimeout(boot,400);
})();
</script>

<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-opening-balance">
/* ═══════════════════════════════════════════════════════════════════════
   OPENING BALANCES — rebuilt so the screen actually does something
   ═══════════════════════════════════════════════════════════════════════
   What was wrong with it:
     · The Customer and Supplier lists read DB.parties, a list this app does
       not keep — so both sections always said "No items configured yet" and
       a party's opening balance could never be entered at all.
     · Every box was drawn from DB.openingBalance, an object that is always
       empty, so a bank holding ৳1,50,575.38 and a partner with ৳1.24 crore
       of capital both showed blank.
     · "Save All" read elements with a class the boxes do not have, wrote
       into DB.openingBal — a store nothing else reads — and then said
       "saved successfully". Nothing was ever saved and no balance moved.

   Now it reads the live figures, writes to the stores the rest of the app
   actually uses (bank.openingBal, DB.openingBalances, partner.cap,
   DB.assets, product.openingStock, DB.cashInHand), and shows both sides of
   the balance with the difference updating as you type.
   ═══════════════════════════════════════════════════════════════════════ */
(function(){
'use strict';
var W=window;
function N(v){var n=parseFloat(v);return isFinite(n)?n:0;}
function esc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function fmt(v){return (N(v)<0?'-':'')+'৳'+Math.abs(N(v)).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});}
function slug(s){return String(s||'').replace(/[^a-z0-9]/gi,'_');}

/* ── One-time recovery of the wiped fixed assets ──────────────────────
   Every page load in offline mode used to erase DB.assets (see the fix in
   the fixed_assets.php loader) and then save the empty list back over the
   real one. A browser that ran the old build has an empty asset list on
   disk, with the real ones surviving only in this file's own seed data.
   This puts them back once, and only when the list is completely empty, so
   assets deleted on purpose are never resurrected. */
(function restoreAssets(){
  function go(){
    try{
      var Dx=W.DB; if(!Dx) return;
      if(Dx.assetsRestoredV1) return;
      if(Array.isArray(Dx.assets) && Dx.assets.length){ Dx.assetsRestoredV1=true; return; }
      if(typeof INIT==='undefined' || !INIT || !Array.isArray(INIT.assets) || !INIT.assets.length) return;
      Dx.assets=JSON.parse(JSON.stringify(INIT.assets));
      Dx.assetsRestoredV1=true;
      if(typeof W.saveDB==='function') W.saveDB();
      try{ console.info('[Ayan ERP] restored '+Dx.assets.length+' fixed assets wiped by the offline asset loader'); }catch(e){}
    }catch(e){}
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',function(){setTimeout(go,900);});
  else setTimeout(go,900);
})();
function D(){return W.DB||{};}

function custList(){ return (D().customers||[]).filter(function(c){return (c.type||'Customer')==='Customer'||c.type==='Both';}); }
function suppList(){ return (D().customers||[]).filter(function(c){return c.type==='Supplier'||c.type==='Both';}); }
function prodList(){ var p=D().products||[]; return p.length?p:(D().inventory||[]); }
function openingOf(name){
  var hit=(D().openingBalances||[]).filter(function(o){return String(o.party||'')===String(name);})[0];
  return hit?N(hit.amount!==undefined?hit.amount:hit.amt):null;
}
var ASSET_NAMES=['Car / Vehicle','Motorcycle','Warehouse Security','Equipment & Machinery','Other Fixed Assets'];
function assetRows(){
  var have=(D().assets||[]).map(function(a){return {name:a.name||'Asset',val:N(a.val!==undefined?a.val:(a.value!==undefined?a.value:a.cost))};});
  ASSET_NAMES.forEach(function(n){ if(!have.some(function(h){return h.name===n;})) have.push({name:n,val:0}); });
  return have;
}

function box(id,label,val,extra){
  return '<div style="display:flex;align-items:center;gap:10px;margin-bottom:7px;">'
    +'<label style="font-size:11.5px;color:#374151;flex:1;min-width:0;">'+esc(label)+'</label>'
    +'<input class="ayan-ob" type="number" step="0.01" id="'+id+'" value="'+(val?N(val):'')+'" placeholder="0.00" '
    +(extra||'')+' style="width:140px;padding:6px 8px;border:1px solid #d1d5db;border-radius:5px;font-size:12px;text-align:right;"/></div>';
}
function section(title,color,inner,note){
  return '<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;">'
    +'<div style="background:'+color+'11;border-left:4px solid '+color+';padding:9px 14px;font-weight:700;font-size:12.5px;color:'+color+';">'+title+'</div>'
    +(note?'<div style="padding:8px 14px 0;font-size:10.5px;color:#9ca3af;">'+note+'</div>':'')
    +'<div style="padding:11px 14px;max-height:340px;overflow-y:auto;">'+inner+'</div></div>';
}

W.renderOpeningBalance=function(){
  var pg=document.getElementById('pg-openingbalance');
  if(!pg) return;

  var banks=(D().banks||[]).map(function(b){
    return box('aob-bank-'+slug(b.name), b.name, (b.openingBal!=null?N(b.openingBal):N(b.bal)), 'data-grp="bank"');
  }).join('');

  var custs=custList().map(function(c){
    var v=openingOf(c.name); if(v===null) v=N(c.bal);
    return box('aob-cust-'+slug(c.name), c.name, v, 'data-grp="cust"');
  }).join('')||'<div style="color:#9ca3af;font-size:12px;">No customers yet.</div>';

  var supps=suppList().map(function(s){
    var v=openingOf(s.name); if(v===null) v=N(s.bal);
    /* Stored sign: below zero means we owe them. Shown the way it is spoken:
       a positive figure is what you owe, a negative one is money paid ahead. */
    return box('aob-supp-'+slug(s.name), s.name, -v, 'data-grp="supp"');
  }).join('')||'<div style="color:#9ca3af;font-size:12px;">No suppliers yet.</div>';

  var partners=(D().partners||[]).map(function(p){
    return box('aob-part-'+slug(p.name), p.name, N(p.cap!==undefined?p.cap:p.capital), 'data-grp="part"');
  }).join('')||'<div style="color:#9ca3af;font-size:12px;">No partners yet.</div>';

  var assets=assetRows().map(function(a){
    return box('aob-asset-'+slug(a.name), a.name, a.val, 'data-grp="asset"');
  }).join('');

  var stock='<div style="display:flex;gap:8px;font-size:10px;color:#9ca3af;font-weight:700;text-transform:uppercase;margin-bottom:5px;">'
    +'<span style="flex:1;">Product</span><span style="width:96px;text-align:right;">Qty</span><span style="width:96px;text-align:right;">Rate ৳</span></div>'
    + prodList().map(function(p){
      var s=slug(p.name);
      return '<div style="display:flex;align-items:center;gap:8px;margin-bottom:6px;">'
        +'<label style="font-size:11.5px;color:#374151;flex:1;min-width:0;">'+esc(p.name)+' <span style="color:#9ca3af;">('+esc(p.unit||'')+')</span></label>'
        +'<input class="ayan-ob" data-grp="stockqty" data-prod="'+esc(p.name)+'" type="number" step="0.01" id="aob-sq-'+s+'" value="'+(N(p.openingStock)?N(p.openingStock):'')+'" placeholder="0" style="width:96px;padding:6px 8px;border:1px solid #d1d5db;border-radius:5px;font-size:12px;text-align:right;"/>'
        +'<input class="ayan-ob" data-grp="stockrate" data-prod="'+esc(p.name)+'" type="number" step="0.01" id="aob-sr-'+s+'" value="'+(N(p.rate)?N(p.rate):'')+'" placeholder="0.00" style="width:96px;padding:6px 8px;border:1px solid #d1d5db;border-radius:5px;font-size:12px;text-align:right;"/>'
        +'</div>';
    }).join('');

  pg.innerHTML=''
  +'<div style="padding:18px 20px 40px;">'
  +'<div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;margin-bottom:6px;">'
  +'<div><div style="font-size:17px;font-weight:800;color:#0f3d26;">🏁 Opening Balances</div>'
  +'<div style="font-size:11.5px;color:#6b7280;margin-top:2px;">What the business owned and owed on the day you started using this system. Everything else is built on top of these figures.</div></div>'
  +'<button class="btn btn-success" id="aob-save">💾 Save opening balances</button></div>'

  +'<div id="aob-recon" style="margin:14px 0 18px;"></div>'

  +'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(330px,1fr));gap:14px;">'
  + section('💵 Cash in hand','#16a34a', box('aob-cash','Hand cash',N(D().cashInHand||D().cash||(D().settings||{}).cashInHand),'data-grp="cash"'),
      'Cash in the drawer only — bank and bKash balances go below.')
  + section('🏦 Bank &amp; mobile accounts','#2563eb', banks, 'The balance on your statement on the starting date.')
  + section('👥 Customers owe you','#7c3aed', custs, 'Money customers still owed you on that date.')
  + section('🏭 Suppliers','#dc2626', supps, 'Positive = you owe them. Negative = you had already paid ahead.')
  + section('🤝 Partner capital','#f59e0b', partners, 'What each partner has put into the business.')
  + section('🏗️ Fixed assets','#ea580c', assets, 'Machinery, vehicles, deposits — at their value on that date.')
  + section('📦 Opening stock','#0891b2', stock, 'Quantity held and the cost rate it was bought at.')
  +'</div>'
  +'<div style="margin-top:16px;display:flex;gap:10px;align-items:center;flex-wrap:wrap;">'
  +'<button class="btn btn-success" id="aob-save2">💾 Save opening balances</button>'
  +'<span id="aob-msg" style="font-size:12px;font-weight:700;color:#16a34a;"></span></div>'
  +'</div>';

  pg.querySelectorAll('.ayan-ob').forEach(function(el){ el.addEventListener('input', recon); });
  var s1=pg.querySelector('#aob-save'), s2=pg.querySelector('#aob-save2');
  if(s1) s1.onclick=save; if(s2) s2.onclick=save;
  recon();
};

function readAll(){
  var pg=document.getElementById('pg-openingbalance'), out={bank:{},cust:{},supp:{},part:{},asset:{},stock:{},cash:0};
  if(!pg) return out;
  out.cash=N((pg.querySelector('#aob-cash')||{}).value);
  (D().banks||[]).forEach(function(b){var el=pg.querySelector('#aob-bank-'+slug(b.name)); if(el) out.bank[b.name]=N(el.value);});
  custList().forEach(function(c){var el=pg.querySelector('#aob-cust-'+slug(c.name)); if(el) out.cust[c.name]=N(el.value);});
  suppList().forEach(function(s){var el=pg.querySelector('#aob-supp-'+slug(s.name)); if(el) out.supp[s.name]=N(el.value);});
  (D().partners||[]).forEach(function(p){var el=pg.querySelector('#aob-part-'+slug(p.name)); if(el) out.part[p.name]=N(el.value);});
  assetRows().forEach(function(a){var el=pg.querySelector('#aob-asset-'+slug(a.name)); if(el) out.asset[a.name]=N(el.value);});
  prodList().forEach(function(p){
    var q=pg.querySelector('#aob-sq-'+slug(p.name)), r=pg.querySelector('#aob-sr-'+slug(p.name));
    if(q||r) out.stock[p.name]={qty:N(q&&q.value), rate:N(r&&r.value)};
  });
  return out;
}

function totals(v){
  var sum=function(o){var t=0;for(var k in o)t+=N(o[k]);return t;};
  var suppOwed=0, suppAdv=0;
  for(var k in v.supp){ var x=N(v.supp[k]); if(x>0) suppOwed+=x; else suppAdv+=-x; }
  var stockVal=0; for(var p in v.stock) stockVal+=N(v.stock[p].qty)*N(v.stock[p].rate);
  var sources=sum(v.part)+suppOwed;
  var uses=v.cash+sum(v.bank)+sum(v.cust)+suppAdv+sum(v.asset)+stockVal;
  return {sources:sources,uses:uses,diff:sources-uses,suppOwed:suppOwed,suppAdv:suppAdv,
          stockVal:stockVal,bank:sum(v.bank),cust:sum(v.cust),part:sum(v.part),asset:sum(v.asset)};
}

function recon(){
  var host=document.getElementById('aob-recon');
  if(!host) return;
  var t=totals(readAll()), ok=Math.abs(t.diff)<0.01;
  var line=function(l,x){return '<div style="display:flex;justify-content:space-between;gap:16px;padding:4px 0;font-size:12.5px;"><span style="color:#6b7280;">'+l+'</span><span style="font-family:ui-monospace,monospace;font-weight:700;">'+fmt(x)+'</span></div>';};
  host.innerHTML=''
  +'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:14px;">'
  +'<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:12px 16px;">'
  +'<div style="font-size:11px;font-weight:800;color:#f59e0b;text-transform:uppercase;letter-spacing:.06em;margin-bottom:6px;">Where the money came from</div>'
  +line('Partner capital',t.part)+line('Owed to suppliers',t.suppOwed)
  +'<div style="border-top:1px solid #e5e7eb;margin-top:6px;padding-top:6px;display:flex;justify-content:space-between;font-weight:800;font-size:13px;"><span>Total</span><span style="font-family:ui-monospace,monospace;">'+fmt(t.sources)+'</span></div></div>'
  +'<div style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;padding:12px 16px;">'
  +'<div style="font-size:11px;font-weight:800;color:#2563eb;text-transform:uppercase;letter-spacing:.06em;margin-bottom:6px;">Where it is now</div>'
  +line('Cash in hand',t.cash===undefined?0:readAll().cash)+line('Bank &amp; mobile',t.bank)+line('Customers owe you',t.cust)
  +line('Paid ahead to suppliers',t.suppAdv)+line('Fixed assets',t.asset)+line('Stock',t.stockVal)
  +'<div style="border-top:1px solid #e5e7eb;margin-top:6px;padding-top:6px;display:flex;justify-content:space-between;font-weight:800;font-size:13px;"><span>Total</span><span style="font-family:ui-monospace,monospace;">'+fmt(t.uses)+'</span></div></div>'
  +'<div style="background:'+(ok?'#f0fdf4':'#fef2f2')+';border:1px solid '+(ok?'#86efac':'#fecaca')+';border-radius:10px;padding:12px 16px;display:flex;flex-direction:column;justify-content:center;">'
  +'<div style="font-size:11px;font-weight:800;color:'+(ok?'#166534':'#b91c1c')+';text-transform:uppercase;letter-spacing:.06em;">'+(ok?'Balanced':'Difference')+'</div>'
  +'<div style="font-size:24px;font-weight:900;font-family:ui-monospace,monospace;color:'+(ok?'#166534':'#b91c1c')+';margin:4px 0;">'+(ok?'✓':fmt(Math.abs(t.diff)))+'</div>'
  +'<div style="font-size:11.5px;color:'+(ok?'#166534':'#b91c1c')+';line-height:1.45;">'
  +(ok?'Both sides agree — your balance sheet will tie.'
      :(t.diff>0?'Capital is higher than what is recorded. '+fmt(Math.abs(t.diff))+' of assets are missing — usually stock, machinery or cash that was never entered.'
                :'Assets are higher than the capital recorded. Either partner capital is understated, or something here is counted twice.'))
  +'</div></div></div>';
}

function save(){
  var v=readAll(), t=totals(v), D0=D();
  D0.cashInHand=v.cash;
  /* Banks: openingBal is the figure the boot-time rebuild starts each
     account from, so it is the one that must be written. */
  (D0.banks||[]).forEach(function(b){ if(v.bank[b.name]!==undefined){ b.openingBal=v.bank[b.name]; } });
  /* Parties: DB.openingBalances is the live store the rebuild reads. */
  var keep=(D0.openingBalances||[]).filter(function(o){
    return v.cust[o.party]===undefined && v.supp[o.party]===undefined;
  });
  var today=(D0.tx&&D0.tx[0]&&D0.tx[0].date)||new Date().toISOString().slice(0,10);
  Object.keys(v.cust).forEach(function(n){ if(v.cust[n]) keep.push({party:n,amount:v.cust[n],date:today,note:'Opening balance'}); });
  Object.keys(v.supp).forEach(function(n){ if(v.supp[n]) keep.push({party:n,amount:-v.supp[n],date:today,note:'Opening balance'}); });
  D0.openingBalances=keep;
  (D0.partners||[]).forEach(function(p){ if(v.part[p.name]!==undefined){ p.cap=v.part[p.name]; p.capital=v.part[p.name]; } });
  D0.assets=Object.keys(v.asset).filter(function(n){return v.asset[n];}).map(function(n,i){
    return {id:i+1,name:n,val:v.asset[n],value:v.asset[n],cost:v.asset[n],date:today,qty:1};
  });
  /* Stock is derived as openingStock + purchases − sales, so the opening
     quantity is what gets stored, not the current stock. */
  [D0.products||[], D0.inventory||[]].forEach(function(list){
    list.forEach(function(p){
      var s=v.stock[p.name];
      if(!s) return;
      p.openingStock=s.qty;
      if(s.rate) p.rate=s.rate;
    });
  });
  try{ if(typeof W.recomputeBalances==='function') W.recomputeBalances({apply:true}); }catch(e){}
  try{ if(typeof W.syncStock==='function') W.syncStock(); }catch(e){}
  if(typeof W.saveDBNow==='function') W.saveDBNow(); else if(typeof W.saveDB==='function') W.saveDB();
  try{ if(typeof W.logAudit==='function') W.logAudit('UPDATE','Opening Balance','Opening balances saved — difference '+fmt(t.diff)); }catch(e){}
  var m=document.getElementById('aob-msg');
  if(m){ m.textContent=Math.abs(t.diff)<0.01?'✓ Saved and balanced':'✓ Saved — still '+fmt(Math.abs(t.diff))+' out'; setTimeout(function(){m.textContent='';},6000); }
  try{ W.toast('Opening balances saved','s'); }catch(e){}
  W.renderOpeningBalance();
}
W.saveOpeningBalances=save;
})();
</script>

<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-vat-rules">
/* ═══════════════════════════════════════════════════════════════════════
   VAT — rates that stay put, and VAT-inclusive pricing
   ═══════════════════════════════════════════════════════════════════════
   What was wrong:
     · "VAT Rate on Sales" and "VAT Rate on Purchases" were written into the
       page as the literal 15 and saved nowhere. Set them to 5, reload, and
       they were 15 again — so the VAT report was computed at 15% every time
       the app was opened, whatever you had told it.
     · VAT was always ADDED on top of the transaction amount. If your prices
       already include VAT, the correct figure is amount × rate ÷ (100+rate),
       not amount × rate — on a ৳20 sale at 15% that is ৳2.61, not ৳3.00.
     · Warehouse Costing deducts its own VAT % (5) from net sales while this
       screen used 15, so the two disagreed about the same sale.
   All three now come from one saved setting, editable in Business Rules.
   ═══════════════════════════════════════════════════════════════════════ */
(function(){
'use strict';
var W=window;
function N(v){var n=parseFloat(v);return isFinite(n)?n:0;}

function vat(){
  var r=(typeof W.ayanRules==='function')?W.ayanRules():((W.DB&&W.DB.rules)||{});
  if(r.vatSalesPct==null) r.vatSalesPct=N((W.DB.settings||{}).vatRate)||15;
  if(r.vatPurchPct==null) r.vatPurchPct=r.vatSalesPct;
  if(r.vatInclusive==null) r.vatInclusive=false;
  try{
    if(!W.DB.settings) W.DB.settings={};
    W.DB.settings.vatRate=N(r.vatSalesPct);
    /* Warehouse Costing reads its own vatPct — keep it on the same figure so
       the two screens can never quote different VAT on one sale. Created
       here if it does not exist yet, because that screen's own defaults
       (5%) would otherwise contradict this setting the first time it opens. */
    if(!W.DB.whCost) W.DB.whCost={};
    W.DB.whCost.vatPct=N(r.vatSalesPct);
  }catch(e){}
  return r;
}
W.ayanVatRules=vat;
/* VAT included in the price is extracted from it, not added to it. */
W.ayanVatEffective=function(pct){
  var r=vat();
  return r.vatInclusive ? (N(pct)/(100+N(pct)))*100 : N(pct);
};

function applyToInputs(){
  var r=vat();
  var s=document.getElementById('vat-rate-sales'), p=document.getElementById('vat-rate-purch');
  /* These two inputs also carry a static data-x-change="renderVATReport()" attribute
     from the page markup. That inline handler is registered before this one and
     so used to fire first on every edit, calling the (wrapped) renderVATReport,
     which re-synced the field from the still-unchanged saved rate and stomped
     the value the user had just typed — before our own listener below ever got
     to read it. Result: typing a new VAT rate and tabbing out silently reverted
     it. Clearing the inline handler here removes that race; this listener now
     owns persisting the new value and re-rendering the report with it. */
  if(s && s.dataset.ayanBound!=='1'){
    s.dataset.ayanBound='1';
    s.onchange=null;
    s.addEventListener('change',function(){
      vat().vatSalesPct=N(s.value); persist();
      if(typeof W.renderVATReport==='function') W.renderVATReport();
    });
  }
  if(p && p.dataset.ayanBound!=='1'){
    p.dataset.ayanBound='1';
    p.onchange=null;
    p.addEventListener('change',function(){
      vat().vatPurchPct=N(p.value); persist();
      if(typeof W.renderVATReport==='function') W.renderVATReport();
    });
  }
  if(s) s.value=N(r.vatSalesPct);
  if(p) p.value=N(r.vatPurchPct);
}
function persist(){
  vat();
  if(typeof W.saveDBNow==='function') W.saveDBNow(); else if(typeof W.saveDB==='function') W.saveDB();
}

/* The report itself is left alone; it is simply given the right rate to
   work with, and told what it is looking at. */
function hookReport(){
  var orig=W.renderVATReport;
  if(typeof orig!=='function'){ setTimeout(hookReport,400); return; }
  if(orig.__ayanVat) return;
  var wrapped=function(){
    applyToInputs();
    var r=vat();
    var s=document.getElementById('vat-rate-sales'), p=document.getElementById('vat-rate-purch');
    var shownS=s?s.value:null, shownP=p?p.value:null;
    if(r.vatInclusive){
      if(s) s.value=W.ayanVatEffective(r.vatSalesPct);
      if(p) p.value=W.ayanVatEffective(r.vatPurchPct);
    }
    var out;
    try{ out=orig.apply(this,arguments); }
    finally{
      if(s&&shownS!=null) s.value=shownS;
      if(p&&shownP!=null) p.value=shownP;
    }
    note(r);
    return out;
  };
  wrapped.__ayanVat=true;
  W.renderVATReport=wrapped;
}
function note(r){
  try{
    var cards=document.getElementById('vat-summary-cards');
    if(!cards||!cards.parentNode) return;
    var old=document.getElementById('ayan-vat-note'); if(old) old.remove();
    var d=document.createElement('div');
    d.id='ayan-vat-note';
    d.style.cssText='font-size:11.5px;color:#6b7280;margin:-6px 0 14px;line-height:1.5;';
    d.innerHTML= r.vatInclusive
      ? 'Prices <b>include</b> VAT — the figures above are the VAT taken out of each amount ('+N(r.vatSalesPct)+'% ÷ '+(100+N(r.vatSalesPct))+'). Change this in Business Rules.'
      : 'Prices <b>exclude</b> VAT — the figures above are '+N(r.vatSalesPct)+'% added on top of each amount. Change this in Business Rules.';
    cards.parentNode.insertBefore(d, cards.nextSibling);
  }catch(e){}
}

/* Editing VAT on the Warehouse Costing screen updates the same setting,
   so neither screen silently overrides the other. */
function hookWhSave(){
  var orig=W.whSaveConfig;
  if(typeof orig!=='function'){ setTimeout(hookWhSave,600); return; }
  if(orig.__ayanVat) return;
  var wrapped=function(){
    var out=orig.apply(this,arguments);
    try{
      var v=parseFloat((document.getElementById('wh-vat')||{}).value);
      if(isFinite(v)){ vat().vatSalesPct=v; persist(); }
    }catch(e){}
    return out;
  };
  wrapped.__ayanVat=true;
  W.whSaveConfig=wrapped;
}
function boot(){ vat(); hookReport(); hookWhSave(); }
if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',function(){setTimeout(boot,700);});
else setTimeout(boot,700);
})();
</script>

<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-expense-heads">
/* ═══════════════════════════════════════════════════════════════════════
   EXPENSES — pay against a head, and see the total
   ═══════════════════════════════════════════════════════════════════════
   The old screen had a "New Expense" button that opened the full multi-
   product transaction form — the same form used for buying bran, with a
   product, bag type, weights and oil percentage on it — and no way to say
   what the money was actually for. There was no list of expense heads and
   no total.

   This is a plain register. Record what you spent and what it was for; put
   a warehouse against it if it belongs to one; leave it unpaid and settle
   it later; correct it if you got it wrong. The head list is yours to edit,
   and the total is the same figure the Profit & Loss calls Operating
   Expenses — click it for the whole breakdown.
   ═══════════════════════════════════════════════════════════════════════ */
(function(){
'use strict';
var W=window;
function N(v){var n=parseFloat(v);return isFinite(n)?n:0;}
function esc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function money(v){return '৳'+Math.abs(N(v)).toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2});}
function today(){ return new Date().toISOString().slice(0,10); }

/* The Expenses group in the New Transaction form offers these eight types.
   Four of them - Utility Bill, Office Expense, Unload Cost, Extra Cost -
   were in neither DEFAULT_HEADS nor EXPENSE_TX_TYPES, and did not start
   with the word "expense", so isExpenseTx() said no: money recorded under
   them simply never appeared on the Expenses screen. They are part of the
   head list now, so the transaction form and this module offer and
   recognise exactly the same set.
   FIX (2026-09-12): 'Production Cost' (Production group, not Expenses group)
   had the identical problem for the same reason and is added alongside them
   — see the window.EXPENSE_TX_TYPES fix near the top of the file for the
   full account of where else this same six-type gap was closed. */
var TX_EXPENSE_TYPES=['Expense','Staff Salary','Utility Bill','Office Expense',
  'Transport Cost','Unload Cost','Extra Cost','Expense Payment','Production Cost'];
W.TX_EXPENSE_TYPES=TX_EXPENSE_TYPES;

var DEFAULT_HEADS=['Expense','Staff Salary','Utility Bill','Office Expense','Unload Cost','Extra Cost','Expense Payment','Production Cost',
  'Office Rent','Warehouse Rent','Electricity Bill','Internet Bill',
  'Telephone Bill','Fuel Expense','Transport Cost','Loading Charge','Unloading Charge',
  'Commission Payment','Legal Fee','Audit Fee','Insurance Premium','Tax Payment','Government Fee',
  'License Fee','Maintenance Cost','Repair Expense','Stationery Purchase','Entertainment',
  'Mobile / Recharge','Bank Charge','Other Expense'];

/* FIX (custom heads were invisible to the accounts): the rest of the app
   decides "is this an expense?" from window.EXPENSE_TX_TYPES - a fixed Set
   written once at boot - and works out the bank movement from a fixed array
   inside applyTxBalance(). A head you add yourself is in neither, so before
   this an expense booked against your own head left the bank untouched
   until the next page load (when the rebuild's catch-all finally took it
   out), and never appeared in the P&L, the dashboard or the monthly chart
   at all. Every head, built-in or yours, is now registered in both places. */
function registerHeads(list){
  try{
    if(!(W.EXPENSE_TX_TYPES instanceof Set)) W.EXPENSE_TX_TYPES=new Set(W.EXPENSE_TX_TYPES||[]);
    list.forEach(function(h){ W.EXPENSE_TX_TYPES.add(h); });
  }catch(e){}
}
function heads(){
  var D=W.DB||(W.DB={});
  if(!Array.isArray(D.expenseHeads)||!D.expenseHeads.length) D.expenseHeads=DEFAULT_HEADS.slice();
  /* Warehouse Rent is entered by hand rather than charged automatically from
     the per-location rates, so make sure the head is there to enter it against
     even on a file whose head list was saved before it existed. */
  if(D.expenseHeads.indexOf('Warehouse Rent')<0) D.expenseHeads.splice(2,0,'Warehouse Rent');
  /* Same for the eight types the transaction form offers: a file whose head
     list was saved before this change would still be missing them, and an
     expense recorded from the transaction form would land on a head that
     this screen cannot show. Topped up in place, existing heads untouched. */
  TX_EXPENSE_TYPES.forEach(function(t,i){
    if(D.expenseHeads.indexOf(t)<0) D.expenseHeads.splice(i,0,t);
  });
  D.expenseHeads=D.expenseHeads.map(function(h){return String(h||'').trim();}).filter(Boolean);
  registerHeads(D.expenseHeads);
  return D.expenseHeads;
}
W.ayanExpenseHeads=heads;

/* Heads the built-in money engine already knows how to post. Anything else
   is routed through 'Other Expense', which has identical bank behaviour, so
   a head you invent moves money exactly like one that shipped with the app. */
var KNOWN_LC=['office rent','electricity bill','internet bill','telephone bill',
  'fuel expense','transport cost','loading charge','unloading charge',
  'commission payment','brokerage fee','legal fee','audit fee',
  'insurance premium','tax payment','government fee','license fee',
  'maintenance cost','repair expense','stationery purchase',
  'other expense','interest expense','tender payment','tender advance',
  'tender cost','staff salary','utility bill','office expense',
  'extra cost','unload cost','expense','expense payment',
  'salary payment','bank charge','production cost'];
(function(){
  function wrap(){
    var base=W.applyTxBalance;
    if(typeof base!=='function'||base.__ayanExpWrapped) return true;
    var f=function(tx,dir){
      try{
        var ty=String(tx&&tx.type||'').trim();
        if(ty && KNOWN_LC.indexOf(ty.toLowerCase())<0 && heads().indexOf(ty)>=0){
          var clone={}; for(var k in tx) clone[k]=tx[k];
          clone.type='Other Expense';
          return base.call(this,clone,dir);
        }
      }catch(e){}
      return base.apply(this,arguments);
    };
    f.__ayanExpWrapped=true;
    W.applyTxBalance=f;
    return true;
  }
  if(!wrap()){
    var tries=0, iv=setInterval(function(){ if(wrap()||++tries>40) clearInterval(iv); },250);
  }
})();

function isExpenseTx(t){
  var ty=String(t&&t.type||'').trim();
  if(!ty) return false;
  /* Checked first and explicitly: these are the types the New Transaction
     form actually offers, and four of them used to fall through every test
     below and disappear from this screen. */
  if(TX_EXPENSE_TYPES.indexOf(ty)>=0) return true;
  if(heads().indexOf(ty)>=0) return true;
  try{ if(W.EXPENSE_TX_TYPES && W.EXPENSE_TX_TYPES.has(ty)) return true; }catch(e){}
  return /^expense/i.test(ty)||ty==='Expense Payment';
}
W.ayanExpenseTxs=function(){ return (W.DB.tx||[]).filter(isExpenseTx); };

/* ═══════════════════════════════════════════════════════════════════
   ONE EXPENSE FEATURE, REACHED TWO WAYS

   Expenses has a screen of its own — head, who was paid, warehouse,
   paid/unpaid status, its own register and totals. Choosing "Expense"
   in the New Transaction form used to leave you in the generic
   transaction form instead, which has none of that. Picking any of the
   eight expense types now takes you to the Expenses screen, and carries
   across whatever was already typed so nothing is lost.
   ═══════════════════════════════════════════════════════════════════ */
W.ayanExpenseFromTx=function(head){
  var g=function(id){ var e=document.getElementById(id); return e?String(e.value||'').trim():''; };
  var carry={ date:g('tx-date'), payee:g('tx-party'), loc:g('tx-loc'),
              amt:g('tx-amt')||g('tx-paid'), mode:g('tx-mode'), acc:g('tx-acc'), note:g('tx-rem') };

  try{ if(typeof closeModal==='function') closeModal('mTx'); }catch(e){}
  try{ if(typeof nav==='function') nav('expenseentry'); }catch(e){}

  /* After nav() has drawn the screen, fill the form from what was typed.
     A head that is not in the list yet is added, so a choice is never
     silently dropped. */
  setTimeout(function(){
    try{
      if(head){
        var hs=heads();
        if(hs.indexOf(head)<0){ hs.push(head); try{ if(typeof W.saveDB==='function') W.saveDB(); }catch(e){} W.renderExpenseEntry(); }
      }
      var set=function(id,v){ var e=document.getElementById(id); if(e && v) e.value=v; };
      set('axp-head',  head);
      set('axp-date',  carry.date);
      set('axp-payee', carry.payee);
      set('axp-loc',   carry.loc);
      set('axp-amt',   carry.amt);
      set('axp-mode',  carry.mode);
      set('axp-acc',   carry.acc);
      set('axp-note',  carry.note);
      var f=document.getElementById('ayan-exp-form'); if(f) f.scrollIntoView({behavior:'smooth',block:'center'});
      var amt=document.getElementById('axp-amt'); if(amt && !amt.value) amt.focus();
      if(typeof W.toast==='function') W.toast('Expenses — recording "'+head+'" here', 'i');
    }catch(e){}
  }, 260);
};

/* Wired with addEventListener rather than by editing the tx-type onchange
   attribute, so every handler already listed there keeps running. */
(function(){
  function wire(){
    var sel=document.getElementById('tx-type');
    if(!sel || sel.dataset.ayanExpRoute==='1') return;
    sel.dataset.ayanExpRoute='1';
    sel.addEventListener('change', function(){
      var v=String(sel.value||'').trim();
      if(TX_EXPENSE_TYPES.indexOf(v)<0) return;
      sel.value='';                       // leave the transaction form clean
      W.ayanExpenseFromTx(v);
    });
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',wire);
  else wire();
  /* The form is re-rendered by several screens, so re-wire when it returns. */
  try{ new MutationObserver(wire).observe(document.documentElement,{childList:true,subtree:true}); }catch(e){}
})();

/* FIX (the total was not the total): this card counted only money entered on
   this screen against an expense head. Everything else the Profit & Loss
   treats as an expense — truck rent, the agent / QC / unloading / other costs
   carried on each purchase and sale, the tax the buyer withholds at source,
   the invoice financier's fee — was left out, so the "Total Expenses" here
   and the "Operating Expenses" on the P&L were two different numbers for the
   same thing. The total below is now the P&L's own figure and the breakdown
   lists every line behind it, marking the ones that come from transactions
   rather than from this screen. */
function plExpenses(from,to){
  try{
    if(typeof W.ayanPL==='function'){
      var p=W.ayanPL(from||null,to||null);
      if(p && p.expenses) return {map:p.expenses, total:N(p.totalExp)};
    }
  }catch(e){}
  var l=W.ayanExpenseTxs().filter(function(t){var d=String(t.date||'');return (!from||d>=from)&&(!to||d<=to);});
  var m={}; l.forEach(function(t){var k=String(t.type||'Other Expense'); m[k]=(m[k]||0)+N(t.amount!=null?t.amount:t.amt);});
  return {map:m, total:Object.keys(m).reduce(function(s,k){return s+m[k];},0)};
}
var DERIVED={'Transport & handling':'from purchase & sale entries',
             'Tax deducted at source':'withheld by buyers',
             'Finance charges':'factory finance fee & interest'};

W.ayanToggleExpenseBreakdown=function(){
  var el=document.getElementById('ayan-exp-breakdown');
  if(!el) return;
  var open=el.style.display!=='none';
  el.style.display=open?'none':'';
  var hint=document.getElementById('ayan-exp-hint');
  if(hint) hint.textContent=open?'click to see the breakdown':'click to hide the breakdown';
};

/* ── the form ─────────────────────────────────────────────────────────── */
var editingId=null;   // null = recording a new one

function formValues(){
  var g=function(id){var e=document.getElementById(id);return e?String(e.value||'').trim():'';};
  return {date:g('axp-date'), head:g('axp-head'), payee:g('axp-payee'), loc:g('axp-loc'),
          amt:N(g('axp-amt')), mode:g('axp-mode'), acc:g('axp-acc'), note:g('axp-note')};
}
function clearForm(){
  editingId=null;
  ['axp-amt','axp-payee','axp-note'].forEach(function(id){var e=document.getElementById(id);if(e)e.value='';});
}

W.ayanCancelExpenseEdit=function(){ clearForm(); W.renderExpenseEntry(); };

W.ayanEditExpense=function(id){
  var t=(W.DB.tx||[]).filter(function(x){return String(x.id)===String(id);})[0];
  if(!t){ try{W.toast('That entry is gone','w');}catch(e){} return; }
  editingId=t.id;
  W.renderExpenseEntry();
  var set=function(id,v){var e=document.getElementById(id); if(e){ e.value=(v==null?'':v); }};
  set('axp-date',t.date); set('axp-head',t.type); set('axp-payee',t.party);
  set('axp-loc',t.loc); set('axp-amt',t.amount!=null?t.amount:t.amt);
  set('axp-mode', N(t.due)>0 ? 'Due' : (t.mode||'Bank'));
  set('axp-acc',t.acc); set('axp-note',t.rem||t.note);
  try{ document.getElementById('ayan-exp-form').scrollIntoView({behavior:'smooth',block:'center'}); }catch(e){}
};

W.ayanSaveExpense=function(){
  var f=formValues();
  if(!f.date){ try{W.toast('Pick a date','e');}catch(e){} return; }
  if(!f.head){ try{W.toast('Choose what the expense is for','e');}catch(e){} return; }
  if(!(f.amt>0)){ try{W.toast('Enter an amount','e');}catch(e){} return; }
  if(f.mode!=='Due' && !f.acc){ try{W.toast('Choose the account it was paid from','e');}catch(e){} return; }

  var list=(W.DB.tx=W.DB.tx||[]);
  var old=editingId!=null ? list.filter(function(x){return String(x.id)===String(editingId);})[0] : null;

  /* FIX (editing had to be done by deleting and re-typing): correcting an
     amount now reverses what the original entry did to the account before
     applying the new figure, so a ৳9,000 rent corrected to ৳8,000 moves the
     bank by ৳1,000 and not by ৳8,000 on top of the ৳9,000 already taken. */
  if(old && old.approvalStatus!=='Pending'){ try{ if(typeof W.applyTxBalance==='function') W.applyTxBalance(old,-1); }catch(e){} }

  var _isTop=(typeof W.isTopApprover==='function'&&W.isTopApprover());
  var tx = old || {
    id:(typeof W.newId==='function')?W.newId():Date.now(),
    inv:'EXP-'+String(Date.now()).slice(-6),
    createdAt:new Date().toISOString()
  };
  tx.date=f.date; tx.type=f.head; tx.cat='Expense';
  tx.party=f.payee||f.head; tx.ptype='Other';
  tx.loc=f.loc||'';
  tx.amount=f.amt; tx.amt=f.amt;
  tx.paid=(f.mode==='Due')?null:f.amt;
  tx.due =(f.mode==='Due')?f.amt:null;
  tx.mode=f.mode||'Cash';
  tx.acc =(f.mode==='Due')?'':f.acc;
  tx.account=tx.acc;
  tx.rem=f.note; tx.note=f.note;
  /* FIX (unapproved expense entries moved the bank instantly): a Manager's
     expense used to hit the bank the moment it was saved. Now only Admin/
     Owner entries post right away; a Manager/Staff entry is held Pending
     — visible immediately, but the bank balance doesn't move until
     approveTx() runs. Re-saving as Admin/Owner (editing an existing entry)
     approves it in the same step. */
  /* MAKER-CHECKER (2026-08-29): an Admin's expense approved itself on save,
     and re-saving someone else's Pending expense as Admin approved it as a
     side effect of editing — an approval nobody clicked Approve for. A new
     expense is always Pending; an edit keeps whatever status it already had,
     so editing an approved row does not silently un-approve it either. */
  tx.approvalStatus=(old&&old.approvalStatus==='Approved')?'Approved':'Pending';
  if(tx.approvalStatus!=='Approved'){ tx.approvedBy=''; tx.approvedAt=''; }
  tx.enteredBy=tx.enteredBy||W.currentUser?.name||''; tx.enteredRole=tx.enteredRole||W.currentUser?.role||'';
  if(!old && typeof W.MakerChecker!=='undefined') W.MakerChecker.stamp(tx);
  if(!old) list.unshift(tx);

  if(tx.approvalStatus!=='Pending'){ try{ if(typeof W.applyTxBalance==='function') W.applyTxBalance(tx,1); }catch(e){} }
  if(typeof W.saveDBNow==='function') W.saveDBNow(); else if(typeof W.saveDB==='function') W.saveDB();
  try{ if(typeof W.logAudit==='function') W.logAudit(old?'UPDATE':'CREATE','Expense',f.head+' '+money(f.amt)+(f.loc?' · '+f.loc:'')); }catch(e){}
  try{ W.toast(old?'Expense updated':'Expense recorded','s'); }catch(e){}
  clearForm();
  W.renderExpenseEntry();
  try{ if(typeof W.renderDash==='function') W.renderDash(); }catch(e){}
};

/* FIX (an unpaid expense was a dead end): you could record one as "not paid
   yet", and then there was nothing on the screen that could ever settle it —
   the only way out was to delete it and enter it again as paid, which loses
   the date you actually incurred it. */
W.ayanPayExpense=function(id){
  var t=(W.DB.tx||[]).filter(function(x){return String(x.id)===String(id);})[0];
  if(!t||!(N(t.due)>0)) return;
  var accs=(W.DB.banks||[]).map(function(b){return b.name;});
  if(!accs.length){ try{W.toast('Add a bank or cash account first','w');}catch(e){} return; }
  var box=document.getElementById('ayan-exp-pay');
  if(!box) return;
  box.style.display='';
  box.innerHTML='<div style="background:#f0fdf4;border:1px solid #bbf7d0;border-radius:10px;padding:12px 14px;margin-bottom:14px;">'
    +'<div style="font-weight:800;font-size:13px;color:#0f3d26;margin-bottom:8px;">Pay '+esc(t.type)+' — '+money(t.due)+'</div>'
    +'<div style="display:flex;gap:10px;flex-wrap:wrap;align-items:flex-end;">'
    +'<div><label class="lbl">Date paid</label><input class="fc" id="axp-pay-date" type="date" value="'+today()+'"></div>'
    +'<div><label class="lbl">From account</label><select class="fc" id="axp-pay-acc">'
      +accs.map(function(a){return '<option value="'+esc(a)+'">'+esc(a)+'</option>';}).join('')+'</select></div>'
    +'<div><label class="lbl">Paid by</label><select class="fc" id="axp-pay-mode">'
      +'<option value="Bank">Bank</option><option value="Cash">Cash</option><option value="Bkash">Bkash</option><option value="Cheque">Cheque</option></select></div>'
    +'<button class="btn btn-success" data-x-click="ayanConfirmPayExpense('+JSON.stringify(String(t.id))+')">✅ Confirm payment</button>'
    +'<button class="btn btn-xs" data-x-click="document.getElementById(\'ayan-exp-pay\').style.display=\'none\'">Cancel</button>'
    +'</div></div>';
  try{ box.scrollIntoView({behavior:'smooth',block:'center'}); }catch(e){}
};
W.ayanConfirmPayExpense=function(id){
  var t=(W.DB.tx||[]).filter(function(x){return String(x.id)===String(id);})[0];
  if(!t||!(N(t.due)>0)) return;
  var g=function(i){var e=document.getElementById(i);return e?String(e.value||'').trim():'';};
  var acc=g('axp-pay-acc'), mode=g('axp-pay-mode')||'Bank', dt=g('axp-pay-date')||today();
  if(!acc){ try{W.toast('Choose the account','e');}catch(e){} return; }
  try{ if(typeof W.applyTxBalance==='function') W.applyTxBalance(t,-1); }catch(e){}
  t.paid=N(t.amount!=null?t.amount:t.amt); t.due=null;
  t.mode=mode; t.acc=acc; t.account=acc; t.paidDate=dt;
  try{ if(typeof W.applyTxBalance==='function') W.applyTxBalance(t,1); }catch(e){}
  if(typeof W.saveDBNow==='function') W.saveDBNow(); else if(typeof W.saveDB==='function') W.saveDB();
  try{ if(typeof W.logAudit==='function') W.logAudit('UPDATE','Expense','Paid '+t.type+' '+money(t.paid)+' from '+acc); }catch(e){}
  var box=document.getElementById('ayan-exp-pay'); if(box) box.style.display='none';
  try{ W.toast('Marked as paid','s'); }catch(e){}
  W.renderExpenseEntry();
};

W.ayanAddExpenseHead=async function(){
  var name=null;
  try{ name = (typeof W.__prompt==='function') ? await W.__prompt('New expense head') : prompt('New expense head'); }
  catch(e){ name = prompt('New expense head'); }
  name=String(name||'').trim();
  if(!name) return;
  var list=heads();
  if(list.map(function(x){return x.toLowerCase();}).indexOf(name.toLowerCase())>=0){
    try{W.toast('That head already exists','w');}catch(e){} return;
  }
  list.push(name);
  if(typeof W.saveDBNow==='function') W.saveDBNow(); else if(typeof W.saveDB==='function') W.saveDB();
  W.renderExpenseEntry();
  try{W.toast('Added "'+name+'"','s');}catch(e){}
};

/* A head you added by mistake can be taken back out, but only while nothing
   has been booked against it — removing one that is in use would leave those
   transactions pointing at a head that no longer exists. */
W.ayanRemoveExpenseHead=async function(name){
  var used=W.ayanExpenseTxs().filter(function(t){return String(t.type||'')===name;}).length;
  if(used){ try{W.toast('"'+name+'" is used by '+used+' entr'+(used===1?'y':'ies') +' — it cannot be removed','w');}catch(e){} return; }
  var ok=true;
  try{ ok = (typeof W.__confirm==='function') ? await W.__confirm('Remove the expense head "'+name+'"?') : confirm('Remove "'+name+'"?'); }catch(e){}
  if(!ok) return;
  var list=heads();
  var i=list.indexOf(name);
  if(i<0) return;
  list.splice(i,1);
  if(typeof W.saveDBNow==='function') W.saveDBNow(); else if(typeof W.saveDB==='function') W.saveDB();
  W.renderExpenseEntry();
  try{W.toast('Removed "'+name+'"','s');}catch(e){}
};

W.ayanToggleHeadList=function(){
  var el=document.getElementById('ayan-exp-headlist');
  if(el) el.style.display = el.style.display==='none' ? '' : 'none';
};

/* ── the register filter ──────────────────────────────────────────────── */
var flt={from:'',to:'',head:'',loc:'',status:''};
W.ayanExpenseFilter=function(){
  var g=function(i){var e=document.getElementById(i);return e?String(e.value||'').trim():'';};
  flt={from:g('axf-from'),to:g('axf-to'),head:g('axf-head'),loc:g('axf-loc'),status:g('axf-status')};
  W.renderExpenseEntry();
};
W.ayanExpenseFilterClear=function(){ flt={from:'',to:'',head:'',loc:'',status:''}; W.renderExpenseEntry(); };
function applyFilter(list){
  return list.filter(function(t){
    var d=String(t.date||'');
    if(flt.from && d<flt.from) return false;
    if(flt.to   && d>flt.to)   return false;
    if(flt.head && String(t.type||'')!==flt.head) return false;
    if(flt.loc  && String(t.loc||'')!==flt.loc)   return false;
    if(flt.status==='unpaid' && !(N(t.due)>0))    return false;
    if(flt.status==='paid'   &&  (N(t.due)>0))    return false;
    return true;
  });
}
W.ayanExportExpenses=function(){
  var rows=applyFilter(W.ayanExpenseTxs()).slice().sort(function(a,b){return String(a.date||'').localeCompare(String(b.date||''));});
  var head=['Date','Head','Paid to','Warehouse','Amount','Paid by','Account','Status','Note'];
  var q=function(v){ v=String(v==null?'':v); return '"'+v.replace(/"/g,'""')+'"'; };
  var csv=[head.map(q).join(',')].concat(rows.map(function(t){
    return [t.date,t.type,t.party,t.loc,N(t.amount!=null?t.amount:t.amt).toFixed(2),
            t.mode,(t.acc?bankNameToDisplay(t.acc):''),(N(t.due)>0?'Unpaid':'Paid'),(t.rem||'')].map(q).join(',');
  })).join('\n');
  try{
    var a=document.createElement('a');
    a.href=URL.createObjectURL(new Blob(['﻿'+csv],{type:'text/csv;charset=utf-8;'}));
    a.download='expenses-'+today()+'.csv';
    document.body.appendChild(a); a.click(); a.remove();
    W.toast('Exported '+rows.length+' row(s)','s');
  }catch(e){ try{W.toast('Export failed','e');}catch(_){} }
};

W.renderExpenseEntry=function(){
  var el=document.getElementById('pg-expenseentry');
  if(!el) return;
  var list=W.ayanExpenseTxs();
  var all=plExpenses(null,null);
  var total=all.total;
  var month=new Date().toISOString().slice(0,7);
  var mTotal=plExpenses(month+'-01',month+'-31').total;
  var unpaid=list.filter(function(t){return N(t.due)>0;}).reduce(function(s,t){return s+N(t.due);},0);
  try{
    unpaid += (typeof W.ayanTransportDue==='function'?W.ayanTransportDue():0)
            + (typeof W.ayanSaleCostDue==='function'?W.ayanSaleCostDue():0);
  }catch(e){}
  var rows=Object.keys(all.map).map(function(k){return {head:k,total:all.map[k]};})
             .filter(function(r){return r.total;})
             .sort(function(a,b){return b.total-a.total;});

  var banks=(W.DB.banks||[]).map(function(b){return '<option value="'+esc(b.name)+'">'+esc(b.name)+' ('+money(b.bal)+')</option>';}).join('');
  var headOpts=heads().map(function(h){return '<option value="'+esc(h)+'">'+esc(h)+'</option>';}).join('');
  var locs=(W.DB.locations||[]).map(function(l){return String(l&&l.name||l||'').trim();}).filter(Boolean);
  var locOpts='<option value="">— none —</option>'+locs.map(function(l){return '<option value="'+esc(l)+'">'+esc(l)+'</option>';}).join('');
  var editing = editingId!=null;
  var shown = applyFilter(list).slice().sort(function(a,b){return String(b.date||'').localeCompare(String(a.date||''));});
  var shownTotal = shown.reduce(function(s,t){return s+N(t.amount!=null?t.amount:t.amt);},0);
  var filtered = !!(flt.from||flt.to||flt.head||flt.loc||flt.status);

  el.innerHTML=''
  +'<div class="page-header"><h2>💸 Expenses</h2><p>What you spent, and what it was for</p></div>'

  +'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:12px;margin-bottom:16px;">'
  +'<div data-x-click="ayanToggleExpenseBreakdown()" style="cursor:pointer;background:linear-gradient(135deg,#dc2626,#b91c1c);color:#fff;border-radius:12px;padding:16px 18px;box-shadow:0 8px 20px -10px rgba(185,28,28,.6);">'
  +'<div style="font-size:22px;">💸</div>'
  +'<div style="font-size:24px;font-weight:900;line-height:1.15;margin-top:2px;">'+money(total)+'</div>'
  +'<div style="font-size:11px;opacity:.9;font-weight:700;text-transform:uppercase;letter-spacing:.04em;">Total Expenses</div>'
  +'<div id="ayan-exp-hint" style="font-size:10.5px;opacity:.85;margin-top:3px;">click to see the breakdown</div></div>'
  +'<div style="background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:16px 18px;">'
  +'<div style="font-size:22px;">📅</div><div style="font-size:22px;font-weight:900;color:#b45309;">'+money(mTotal)+'</div>'
  +'<div style="font-size:11px;color:#6b7280;font-weight:700;">THIS MONTH</div></div>'
  +'<div style="background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:16px 18px;">'
  +'<div style="font-size:22px;">⏳</div><div style="font-size:22px;font-weight:900;color:'+(unpaid>0?'#dc2626':'#16a34a')+';">'+money(unpaid)+'</div>'
  +'<div style="font-size:11px;color:#6b7280;font-weight:700;">STILL TO PAY</div>'
  +'<div style="font-size:10px;color:#9ca3af;margin-top:2px;">unpaid expenses + freight + handling</div></div>'
  +'<div style="background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:16px 18px;">'
  +'<div style="font-size:22px;">🗂️</div><div style="font-size:22px;font-weight:900;color:#0f3d26;">'+rows.length+'</div>'
  +'<div style="font-size:11px;color:#6b7280;font-weight:700;">HEADS USED</div></div>'
  +'</div>'

  +'<div id="ayan-exp-breakdown" style="display:none;margin-bottom:16px;" class="card">'
  +'<h3 style="font-size:14px;font-weight:800;color:#0f3d26;margin-bottom:10px;">Where it went</h3>'
  +(rows.length
    ? '<div style="overflow-x:auto;"><table class="tbl" style="width:100%;border-collapse:collapse;font-size:13px;">'
      +'<thead><tr style="background:#fef2f2;"><th style="padding:8px 12px;text-align:left;">Expense head</th>'
      +'<th style="padding:8px 12px;text-align:right;">Amount</th><th style="padding:8px 12px;text-align:right;">Share</th></tr></thead><tbody>'
      +rows.map(function(r){
        var pct=total>0?(r.total/total*100):0;
        var note=DERIVED[r.head];
        return '<tr><td style="padding:8px 12px;">'+esc(r.head)
          +(note?'<span style="color:#9ca3af;font-size:11px;"> · '+esc(note)+'</span>':'')+'</td>'
          +'<td style="padding:8px 12px;text-align:right;font-weight:700;">'+money(r.total)+'</td>'
          +'<td style="padding:8px 12px;text-align:right;color:#6b7280;">'+pct.toFixed(1)+'%</td></tr>';}).join('')
      +'</tbody></table></div>'
    : '<div style="color:#9ca3af;font-size:13px;">Nothing spent yet.</div>')
  +'<div style="font-size:11.5px;color:#6b7280;margin-top:9px;">This is the same total the Profit &amp; Loss shows as Operating Expenses. Greyed notes mark costs that come from your purchase and sale entries — change those on the transaction, not here.</div>'
  +'</div>'

  +'<div id="ayan-exp-pay" style="display:none;"></div>'

  +'<div class="card" id="ayan-exp-form" style="margin-bottom:16px;'+(editing?'border:2px solid #f59e0b;':'')+'">'
