  +'<div style="font-size:11.5px;color:#6b7280;margin-bottom:8px;">These are the things you can spend money on. Add your own; remove any that nothing has been booked against.</div>'
  +'<div style="display:flex;flex-wrap:wrap;gap:6px;">'
  +heads().map(function(h){
      var used=list.filter(function(t){return String(t.type||'')===h;}).length;
      return '<span style="display:inline-flex;align-items:center;gap:6px;background:#fff;border:1px solid #e5e7eb;border-radius:999px;padding:4px 6px 4px 11px;font-size:12px;">'
        +esc(h)+(used?'<span style="color:#9ca3af;font-size:10.5px;">'+used+'</span>':'')
        +'<button title="Remove" data-x-click="ayanRemoveExpenseHead('+JSON.stringify(h).replace(/"/g,'&quot;')+')" style="border:none;background:'+(used?'#f3f4f6':'#fee2e2')+';color:'+(used?'#9ca3af':'#b91c1c')+';border-radius:999px;width:18px;height:18px;line-height:1;cursor:'+(used?'not-allowed':'pointer')+';font-size:12px;">×</button></span>';
    }).join('')
  +'</div></div>'
  +'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px;">'
  +'<div><label class="lbl">Date *</label><input class="fc" id="axp-date" type="date" value="'+today()+'"></div>'
  +'<div><label class="lbl">What is it for? *</label><select class="fc" id="axp-head">'+headOpts+'</select></div>'
  +'<div><label class="lbl">Paid to</label><input class="fc" id="axp-payee" type="text" placeholder="Name (optional)"></div>'
  +'<div><label class="lbl">Warehouse / place</label><select class="fc" id="axp-loc">'+locOpts+'</select></div>'
  +'<div><label class="lbl">Amount (৳) *</label><input class="fc" id="axp-amt" type="number" step="0.01" min="0" placeholder="0.00" style="text-align:right;"></div>'
  +'<div><label class="lbl">Paid by</label><select class="fc" id="axp-mode">'
  +'<option value="Bank">Bank</option><option value="Cash">Cash</option><option value="Bkash">Bkash</option><option value="Cheque">Cheque</option><option value="Due">Not paid yet</option></select></div>'
  +'<div><label class="lbl">From account</label><select class="fc" id="axp-acc"><option value="">-- Select account --</option>'+banks+'</select></div>'
  +'<div style="grid-column:1/-1;"><label class="lbl">Note</label><input class="fc" id="axp-note" type="text" placeholder="Which month, which warehouse, anything worth remembering"></div>'
  +'</div>'
  +'<div style="display:flex;gap:8px;margin-top:12px;flex-wrap:wrap;">'
  +'<button class="btn btn-success" data-x-click="ayanSaveExpense()">💾 '+(editing?'Save the correction':'Save expense')+'</button>'
  +(editing?'<button class="btn" data-x-click="ayanCancelExpenseEdit()">Cancel</button>':'')
  +'</div></div>'

  +'<div class="card">'
  +'<div style="display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:10px;">'
  +'<h3 style="font-size:14px;font-weight:800;color:#0f3d26;margin:0;">Expense register'
    +(filtered?' <span style="font-weight:600;color:#6b7280;font-size:12px;">— '+shown.length+' of '+list.length+', '+money(shownTotal)+'</span>'
              :' <span style="font-weight:600;color:#6b7280;font-size:12px;">('+list.length+')</span>')+'</h3>'
  +'<button class="btn btn-xs" data-x-click="ayanExportExpenses()">⬇️ Export CSV</button></div>'
  +'<div style="display:flex;gap:8px;flex-wrap:wrap;align-items:flex-end;margin-bottom:12px;background:#f9fafb;border:1px solid #e5e7eb;border-radius:10px;padding:10px 12px;">'
  +'<div><label class="lbl">From</label><input class="fc" id="axf-from" type="date" value="'+esc(flt.from)+'" style="min-width:140px;"></div>'
  +'<div><label class="lbl">To</label><input class="fc" id="axf-to" type="date" value="'+esc(flt.to)+'" style="min-width:140px;"></div>'
  +'<div><label class="lbl">Head</label><select class="fc" id="axf-head"><option value="">All</option>'
    +heads().map(function(h){return '<option value="'+esc(h)+'"'+(flt.head===h?' selected':'')+'>'+esc(h)+'</option>';}).join('')+'</select></div>'
  +'<div><label class="lbl">Warehouse</label><select class="fc" id="axf-loc"><option value="">All</option>'
    +locs.map(function(l){return '<option value="'+esc(l)+'"'+(flt.loc===l?' selected':'')+'>'+esc(l)+'</option>';}).join('')+'</select></div>'
  +'<div><label class="lbl">Status</label><select class="fc" id="axf-status"><option value="">All</option>'
    +'<option value="unpaid"'+(flt.status==='unpaid'?' selected':'')+'>Unpaid</option>'
    +'<option value="paid"'+(flt.status==='paid'?' selected':'')+'>Paid</option></select></div>'
  +'<button class="btn btn-xs" data-x-click="ayanExpenseFilter()">🔍 Show</button>'
  +'<button class="btn btn-xs" data-x-click="ayanExpenseFilterClear()">Clear</button>'
  +'</div>'
  +(shown.length
    ? '<div style="overflow-x:auto;"><table class="tbl" style="width:100%;border-collapse:collapse;font-size:12.5px;">'
      +'<thead><tr style="background:#f9fafb;"><th style="padding:8px 10px;text-align:left;">Date</th>'
      +'<th style="padding:8px 10px;text-align:left;">Head</th><th style="padding:8px 10px;text-align:left;">Paid to</th>'
      +'<th style="padding:8px 10px;text-align:left;">Warehouse</th>'
      +'<th style="padding:8px 10px;text-align:right;">Amount</th><th style="padding:8px 10px;text-align:left;">Paid by</th>'
      +'<th style="padding:8px 10px;text-align:left;">Account</th><th style="padding:8px 10px;text-align:right;">Actions</th></tr></thead><tbody>'
      +shown.slice(0,300).map(function(t){
        var due=N(t.due)>0;
        var jid=JSON.stringify(String(t.id));
        return '<tr'+(due?' style="background:#fffbeb;"':'')+'><td style="padding:7px 10px;color:#6b7280;">'+esc(t.date||'')+'</td>'
          +'<td style="padding:7px 10px;font-weight:600;">'+esc(t.type||'')+'</td>'
          +'<td style="padding:7px 10px;">'+esc(t.party||'—')+'</td>'
          +'<td style="padding:7px 10px;color:#6b7280;">'+esc(t.loc||'—')+'</td>'
          +'<td style="padding:7px 10px;text-align:right;font-weight:700;color:#dc2626;">'+money(t.amount!=null?t.amount:t.amt)+'</td>'
          +'<td style="padding:7px 10px;">'+(due?'<span style="color:#b45309;font-weight:700;">Not paid</span>':esc(t.mode||'—'))+'</td>'
          +'<td style="padding:7px 10px;color:#6b7280;">'+esc(t.acc?bankNameToDisplay(t.acc):'—')+'</td>'
          +'<td style="padding:7px 10px;text-align:right;white-space:nowrap;">'
            +(due?'<button class="btn btn-success btn-xs" title="Record the payment" data-x-click="ayanPayExpense('+jid+')">💵 Pay</button> ':'')
            +'<button class="btn btn-xs" title="Correct this entry" data-x-click="ayanEditExpense('+jid+')">✏️</button> '
            +'<button class="btn btn-danger btn-xs" title="Delete" data-x-click="delTx('+JSON.stringify(t.id)+')">🗑</button>'
          +'</td></tr>';}).join('')
      +'</tbody></table></div>'
      +(shown.length>300?'<div style="font-size:11.5px;color:#9ca3af;margin-top:8px;">Showing the first 300 of '+shown.length+' — narrow the dates to see the rest.</div>':'')
    : '<div style="text-align:center;padding:26px;color:#9ca3af;">'+(filtered?'Nothing matches that filter.':'No expenses recorded yet.')+'</div>')
  +'</div>';
};
})();
</script>

<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-user-seed">
/* ═══════════════════════════════════════════════════════════════════════
   THE FOUR ACCOUNTS
   ═══════════════════════════════════════════════════════════════════════
   admin    / Ayan@01     Admin    — everything
   rafiq    / Rafiq@01    Owner    — everything
   ramim    / Ramim@01    Manager  — everything except user, access and
                                     admin settings screens
   toufick  / Toufick@01  Staff    — entry screens, stock and orders

   Passwords are hashed with this file's own salt the first time it opens,
   and the plain text is never stored. Seeding runs once — after that the
   accounts are yours to change on the Users screen and this will not put
   them back.
   ═══════════════════════════════════════════════════════════════════════ */
(function(){
'use strict';
var W=window;
var SEED_KEY='usersSeeded_v20260822';
var PEOPLE=[
  {username:'admin',   pw:'Ayan@01',    name:'Ayan',            role:'Admin',   dept:'Management', email:'admin@ayanagro.com'},
  {username:'rafiq',   pw:'Rafiq@01',   name:'Md. Rafiqul Islam',role:'Owner',  dept:'Management', email:'rafiq@ayanagro.com'},
  {username:'ramim',   pw:'Ramim@01',   name:'Ramim',           role:'Manager', dept:'Operations', email:'ramim@ayanagro.com'},
  {username:'toufick', pw:'Toufick@01', name:'Toufick',         role:'Staff',   dept:'Warehouse',  email:'toufick@ayanagro.com'}
];

/* Written out here rather than read from UM_ROLE_PERMS, so that a user gets
   the rights their role is meant to carry even if this script runs before the
   table exists. Falling back to 'all' would hand a storekeeper the delete
   button on every screen. */
var ROLE_RIGHTS={
  Owner:  {modules:['dashboard','transactions','reports','parties','inventory','finance','payroll','admin','export','import','communications','tender','assets','banks'],
           actions:['view','add','edit','delete','print','approve','export']},
  Admin:  {modules:['dashboard','transactions','reports','parties','inventory','finance','payroll','admin','export','import','communications','tender','assets','banks'],
           actions:['view','add','edit','delete','print','approve','export']},
  Manager:{modules:['dashboard','transactions','reports','parties','inventory','finance','tender','assets','banks'],
           actions:['view','add','edit','print','export']},
  Staff:  {modules:['dashboard','transactions','parties','inventory'],
           actions:['view','add','edit','print']}
};
function permsFor(role){
  if(role==='Admin'||role==='Owner') return 'all';
  var r=ROLE_RIGHTS[role]||ROLE_RIGHTS.Staff;
  var o={};
  r.actions.forEach(function(a){o[a]=true;});
  r.modules.forEach(function(m){o[m]=true;});
  return o;
}

function setPassword(u,pw){
  if(typeof W._erpHashPw==='function'){
    u.pwHash=W._erpHashPw(pw); delete u.pwLen; delete u.password;
  }else{
    /* hashing helper not up yet — leave it in plain text for _erpHashSweep()
       to convert a moment later, exactly as the app already does for users
       typed in on the Users screen. */
    u.password=pw; delete u.pwLen;
  }
}

function seed(){
  var D=W.DB;
  if(!D || typeof W.saveDB!=='function') return false;
  if(D[SEED_KEY]) return true;
  if(typeof W._erpHashPw!=='function') return false;   // wait for the hasher
  D.users=Array.isArray(D.users)?D.users:[];
  PEOPLE.forEach(function(p){
    var u=D.users.filter(function(x){
      return String(x&&x.username||'').toLowerCase()===p.username;
    })[0];
    if(!u){
      u={id:(typeof W.newId==='function')?W.newId():('u-'+p.username),
         createdAt:new Date().toISOString(), lastLogin:null, loginCount:0, notes:''};
      D.users.push(u);
    }
    u.username=p.username;
    u.name=u.name||p.name;
    u.email=u.email||p.email;
    u.dept=u.dept||p.dept;
    u.role=p.role;
    u.status='Active';
    u.canPrint=true;
    u.permissions=permsFor(p.role);
    if(p.role==='Admin'||p.role==='Owner') u.pages='all'; else delete u.pages;
    setPassword(u,p.pw);
  });
  D[SEED_KEY]=true;
  try{ if(typeof W._erpHashSweep==='function') W._erpHashSweep(); }catch(e){}
  try{ W.saveDB(); }catch(e){}
  try{ if(typeof W.umRender==='function') W.umRender(); }catch(e){}
  return true;
}
W.ayanSeedUsers=function(){ 
  try{ if(W.DB) delete W.DB.usersSeeded_v20260822; }catch(e){}
  var ok=seed();
  try{ W.toast(ok?'The four accounts are set':'Not ready yet — try again in a moment', ok?'s':'w'); }catch(e){}
  return ok;
};

var tries=0;
var iv=setInterval(function(){ if(seed()||++tries>60) clearInterval(iv); }, 300);
if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',seed); else seed();
})();
</script>

<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-tax-rate-migration">
/* ═══════════════════════════════════════════════════════════════════════
   THE REAL WITHHOLDING RATE IS 0.05%, NOT 0.5%
   ═══════════════════════════════════════════════════════════════════════
   0.5% was a placeholder that had been sitting in the settings, in the
   business rules and as the fallback in four separate places in the code.
   The real rate the buyer deducts at source is 0.05% — a tenth of what was
   configured, so every sale was raising ten times too much withheld tax.

   This runs once: the placeholder 0.5 becomes 0.05 wherever it is still
   sitting untouched. Set any other figure on the Settings or Business Rules
   screen and it is left exactly as you set it.

   Old sale records also stored the Settings rate rather than the rate the
   tax on them actually worked out to, so an invoice could read "0.5%" beside
   a figure that was nothing of the sort. Each one is put back in step with
   its own tax amount. No money moves — only the percentage printed on the
   record, which nothing calculates from.
   ═══════════════════════════════════════════════════════════════════════ */
(function(){
'use strict';
var W=window, FLAG='taxRateFixedTo005_v1', REAL=0.05, PLACEHOLDER=0.5;
function N(v){var n=parseFloat(v);return isFinite(n)?n:null;}
function Nz(v){var n=parseFloat(v);return isFinite(n)?n:0;}

/* FIX (an invoice and the customer's ledger disagreeing by a few paisa): a
   sale keeps its outstanding figure in `due`, worked out at the moment it was
   entered. Change the tax on it afterwards and the amount, the tax and the
   net all move — but `due` stays where it was, so the invoice list says the
   customer still owes ৳996.95 while their ledger correctly says ৳997, for
   ever. Rows with no part payment against them and a gap under one taka are
   put back in step; anything larger is a real balance and is left alone.
   Runs on its own, not behind the tax-rate flag, because a file that has
   already had its rate corrected can still be carrying these. */
function repairDues(){
  var D=W.DB, fixed=0;
  if(!D||!D.tx) return 0;
  D.tx.forEach(function(t){
    if(!t||t.due==null) return;
    if(Nz(t.paid)!==0||Nz(t.recv)!==0) return;
    var amt=Nz(t.amount!=null?t.amount:t.amt), tax=Nz(t.salesTaxAmt);
    var net=(t.netAmt!=null)?Nz(t.netAmt):(amt-tax);
    var gap=Nz(t.due)-net;
    if(net>0 && gap!==0 && Math.abs(gap)<1){ t.due=net; fixed++; }
  });
  return fixed;
}
W.ayanRepairDues=repairDues;
function run(){
  var D=W.DB;
  if(!D||typeof W.saveDB!=='function') return false;
  /* Deliberately keyed off the value, not off a once-only flag: restoring an
     older backup brings the 0.5 placeholder straight back with it, and a flag
     set on a previous load would let it stand. The one thing that stops this
     is you having chosen a rate yourself on the Settings or Business Rules
     screen — that sets taxRateUserSet and is never overridden, 0.5 included. */
  /* Deliberately not behind a "done once" marker. A marker set while the app
     is still holding its start-up data survives the merge when the real books
     arrive from the server a moment later, so the repair would be skipped on
     the very file that needs it. The pass only touches rows that are out of
     step and leaves them matching, so running it every time costs nothing. */
  var nFixed=repairDues();
  if(nFixed){
    try{ if(typeof W.logAudit==='function')
      W.logAudit('UPDATE','Transactions',nFixed+' stale outstanding figure(s) put back in step with their invoice'); }catch(e){}
    try{ W.saveDB(); }catch(e){}
  }
  if(D.taxRateUserSet) return true;
  if(D[FLAG] && N(D.settings&&D.settings.salesTaxRate)!==PLACEHOLDER
             && N(D.rules&&D.rules.salesTaxPct)!==PLACEHOLDER) return true;
  var changed=[];
  D.settings=D.settings||{};
  if(N(D.settings.salesTaxRate)===PLACEHOLDER){ D.settings.salesTaxRate=REAL; changed.push('settings'); }
  if(N(D.settings.salesTaxRate)===null){ D.settings.salesTaxRate=REAL; }
  D.rules=D.rules||{};
  if(N(D.rules.salesTaxPct)===PLACEHOLDER){ D.rules.salesTaxPct=REAL; changed.push('business rules'); }
  if(N(D.rules.salesTaxPct)===null){ D.rules.salesTaxPct=REAL; }
  var fixedRows=0, fixedDue=0;
  (D.tx||[]).forEach(function(t){
    if(!t) return;
    var tax=N(t.salesTaxAmt), amt=N(t.amount!=null?t.amount:t.amt);
    if(tax>0 && amt>0){
      var eff=parseFloat((tax/amt*100).toFixed(4));
      if(N(t.salesTaxRate)!==eff){ t.salesTaxRate=eff; fixedRows++; }
    }
  });
  fixedDue = repairDues();
  D[FLAG]=true;
  try{ W.saveDB(); }catch(e){}
  if(changed.length||fixedRows||fixedDue){
    try{
      if(typeof W.logAudit==='function')
        W.logAudit('SETTINGS','Tax','Withholding rate corrected to '+REAL+'%'
          +(changed.length?' ('+changed.join(', ')+')':'')
          +(fixedRows?'; '+fixedRows+' sale record(s) re-stamped with their own rate':'')
          +(fixedDue?'; '+fixedDue+' stale outstanding figure(s) corrected':''));
    }catch(e){}
  }
  return true;
}
W.ayanFixTaxRate=run;
var tries=0, iv=setInterval(function(){ if(run()||++tries>60) clearInterval(iv); },300);
if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',run); else run();

/* And again whenever a fresh copy of the books arrives from the server —
   that data has not been through any of this and may carry stale figures. */
(function(){
  var tries2=0, iv2=setInterval(function(){
    if(typeof W.loadDataFromServer==='function'){
      clearInterval(iv2);
      var orig=W.loadDataFromServer;
      if(orig.__ayanDueWrapped) return;
      var f=function(){
        var r=orig.apply(this,arguments);
        try{ Promise.resolve(r).then(function(){
          var n=repairDues();
          if(n){ try{ W.saveDB && W.saveDB(); }catch(e){} }
        }); }catch(e){}
        return r;
      };
      f.__ayanDueWrapped=true;
      W.loadDataFromServer=f;
    } else if(++tries2>60) clearInterval(iv2);
  },300);
})();
})();
</script>
<script nonce="<?php echo $cspNonceAttr; ?>" id="claude-fix-costline-groupkey-migration">
/* FIX (Cost Line report still showing old dues under Location): Agent A,
   Agent B, QC and Other used to group by Location; the category rule was
   changed so all five (Agent A, Agent B, QC, Unload, Other) group by
   Customer instead. Each costLines row keeps its own groupKey baked in at
   the moment it was saved, so that change only takes effect for cost lines
   created or re-saved from now on — every row already sitting in the data
   keeps its old, Location-based groupKey until this runs once. This puts
   every existing row back in step with the current rule. Only DB.costLines
   is touched — DB.users, transactions, and account balances are untouched. */
(function(){
'use strict';
var W=window, FLAG='costLineGroupKeyFixed_v1';
function run(){
  var D=W.DB;
  if(!D||typeof W.saveDB!=='function') return false;
  if(D[FLAG]) return true;
  var fixed=0;
  (D.costLines||[]).forEach(function(r){
    if(!r) return;
    var want = r.party || 'Unassigned';
    if(r.groupKey!==want){ r.groupKey=want; fixed++; }
  });
  D[FLAG]=true;
  if(fixed){
    try{ if(typeof W.logAudit==='function')
      W.logAudit('UPDATE','Cost Lines',fixed+' cost line(s) re-grouped from Location to Customer to match the current category rule'); }catch(e){}
  }
  try{ W.saveDB(); }catch(e){}
  return true;
}
W.ayanFixCostLineGroupKey=run;
var tries=0, iv=setInterval(function(){ if(run()||++tries>60) clearInterval(iv); },300);
if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',run); else run();

/* And again whenever a fresh copy of the books arrives from the server. */
(function(){
  var tries2=0, iv2=setInterval(function(){
    if(typeof W.loadDataFromServer==='function'){
      clearInterval(iv2);
      var orig=W.loadDataFromServer;
      if(orig.__ayanCostGroupWrapped) return;
      var f=function(){
        var r=orig.apply(this,arguments);
        try{ Promise.resolve(r).then(function(){
          var D=W.DB;
          if(D){ D[FLAG]=false; run(); }
        }); }catch(e){}
        return r;
      };
      f.__ayanCostGroupWrapped=true;
      W.loadDataFromServer=f;
    } else if(++tries2>60) clearInterval(iv2);
  },300);
})();
})();
</script>
<script nonce="<?php echo $cspNonceAttr; ?>" id="claude-fix-asset-register-backfill">
/* FIX (Fixed Assets Trial Balance mismatch, part 3 - backfill): any Fixed
   Asset Purchase / Asset Sale saved BEFORE applyAssetRegister existed (every
   one already in this file's demo data, plus anyone's existing books) never
   got its register line created in the first place - the reversal logic in
   applyAssetRegister only ever runs at the moment a transaction is saved,
   edited or deleted, so it can't retroactively fix rows already sitting in
   DB.tx. This runs once per load: any Fixed Asset Purchase / Asset Sale that
   doesn't yet have a DB.assets row tagged with its own tx id gets one
   created now, via the exact same function real-time saves use, so old and
   new entries end up booked identically. Safe to run every load - a
   transaction that already has its srcTxId line is skipped, so nothing is
   ever double-booked. */
(function(){
  'use strict';
  var W=window, tries=0;
  function run(){
    if(!W.DB || !Array.isArray(W.DB.tx) || typeof W.applyAssetRegister!=='function') return false;
    var DB=W.DB;
    DB.assets = DB.assets||[];
    var have = {};
    DB.assets.forEach(function(a){ if(a && a.srcTxId!=null) have[a.srcTxId]=true; });
    var fixed=0;
    DB.tx.forEach(function(t){
      if(!t) return;
      var type=String(t.type||'').trim();
      if(type!=='Fixed Asset Purchase' && type!=='Asset Sale') return;
      if(t.approvalStatus==='Pending') return;
      if(have[t.id]) return;
      W.applyAssetRegister(t, 1);
      fixed++;
    });
    if(fixed){
      try{ if(typeof W.logAudit==='function') W.logAudit('UPDATE','Fixed Assets', fixed+' Fixed Asset Purchase/Asset Sale transaction(s) backfilled into the asset register'); }catch(e){}
      try{ W.saveDB(); }catch(e){}
      try{ if(typeof W.renderBS==='function') W.renderBS(); }catch(e){}
      try{ if(typeof W.renderDash==='function') W.renderDash(); }catch(e){}
    }
    return true;
  }
  var iv=setInterval(function(){ if(run()||++tries>60) clearInterval(iv); },300);
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',run); else run();
  var tries2=0, iv2=setInterval(function(){
    if(typeof W.loadDataFromServer==='function'){
      clearInterval(iv2);
      var orig=W.loadDataFromServer;
      if(orig.__ayanAssetBackfillWrapped) return;
      var f=function(){
        var r=orig.apply(this,arguments);
        try{ Promise.resolve(r).then(function(){ run(); }); }catch(e){}
        return r;
      };
      f.__ayanAssetBackfillWrapped=true;
      W.loadDataFromServer=f;
    } else if(++tries2>60) clearInterval(iv2);
  },300);
})();
</script>
<script nonce="<?php echo $cspNonceAttr; ?>" id="claude-fix-v2-launcher-toggle">
/* FIX (floating quick-action stack burying page content — every screen
   size): see the CSS comment above #v2-launcher. Five independently
   -added floating buttons (Freight Due, Sync, Payments, Cost Dues/Ledgers,
   Factory Finance) stack in the same fixed bottom-right corner; confirmed
   sitting directly on top of real numbers on both a phone (Balance Sheet)
   and an ordinary 1440px desktop window (Balance Sheet totals, Dashboard
   Business Health panel). The CSS hides the individual buttons unless
   #v2-launcher carries a "v2-open" class; this adds the one small
   circular toggle that flips it, so all five stay reachable with one
   click instead of permanently covering the page underneath, on any
   device. */
(function(){
  'use strict';
  var W = window, D = document, tries = 0;
  function mount(){
    var launcher = D.getElementById('v2-launcher');
    if(!launcher) return false;
    if(D.getElementById('v2-launcher-toggle')) return true;
    var btn = D.createElement('button');
    btn.id = 'v2-launcher-toggle';
    btn.className = 'ayan-noprint';
    btn.type = 'button';
    btn.title = 'Quick actions';
    btn.textContent = '⚡';
    btn.onclick = function(){
      var open = launcher.classList.toggle('v2-open');
      btn.textContent = open ? '✕' : '⚡';
    };
    D.body.appendChild(btn);
    return true;
  }
  var iv = setInterval(function(){ if(mount() || ++tries > 60) clearInterval(iv); }, 300);
  if(D.readyState === 'loading') D.addEventListener('DOMContentLoaded', mount); else mount();
})();
</script>
<script nonce="<?php echo $cspNonceAttr; ?>" id="claude-fix-db-parties-alias">
/* FIX (DB.parties silently empty in the only mode this app actually runs
   in): loadDB() — the OFFLINE/localStorage loader — sets up DB.parties as
   a live computed view of DB.customers + DB.partners, via a getter, right
   after loading. Dozens of screens across the app are written against that
   unified DB.parties shape: Parties Hub, party reminders, WhatsApp/SMS
   integration, CSV export, several dashboards, and (until the fix earlier
   today) the printed Balance Sheet. The problem: this app is server-only —
   loadDB() is never called — and loadDataFromServer() builds the live DB
   object with a plain `Object.assign({}, SHAPE, window.DB, data)`, which
   produces a brand-new plain object with no getter on it at all. Every one
   of those DB.parties reads has therefore always seen an empty array in
   real, normal use of this app, even though DB.customers and DB.partners
   themselves hold real data throughout. Confirmed directly: after a normal
   login with 40 real customers and 3 real partners on file, window.DB.
   parties.length was 0. This re-applies the same getter (plus the
   DB.bankAccounts and DB.transactions aliases loadDB() also sets up) to
   the DB object every time loadDataFromServer() replaces it — the one
   thing that has to happen for a getter to survive Object.assign building
   a fresh object out from under it each load. */
(function(){
  'use strict';
  var W = window, tries = 0;

  function applyAliases(){
    var DB = W.DB;
    if(!DB || typeof DB !== 'object') return false;
    try{
      if(!Object.getOwnPropertyDescriptor(DB,'parties') || !Object.getOwnPropertyDescriptor(DB,'parties').get){
        Object.defineProperty(DB, 'parties', {
          get(){ return [
            ...(DB.customers||[]),
            ...(DB.partners||[]).map(function(p){ return Object.assign({}, p, {type:'Partner'}); })
          ]; },
          configurable: true
        });
      }
      if(!Object.getOwnPropertyDescriptor(DB,'transactions') || !Object.getOwnPropertyDescriptor(DB,'transactions').get){
        Object.defineProperty(DB, 'transactions', {
          get(){ return DB.tx||[]; },
          set(v){ DB.tx=v; },
          configurable: true
        });
      }
      if(!DB.bankAccounts || DB.bankAccounts !== DB.banks) DB.bankAccounts = DB.banks;
    }catch(e){ console.error('[DB.parties alias]', e); }
    return true;
  }

  function wrapLoader(){
    var orig = W.loadDataFromServer;
    if(typeof orig !== 'function' || orig.__ayanPartiesWrapped) return false;
    var f = function(){
      var r = orig.apply(this, arguments);
      try{ Promise.resolve(r).then(applyAliases); }catch(e){ applyAliases(); }
      return r;
    };
    f.__ayanPartiesWrapped = true;
    W.loadDataFromServer = f;
    return true;
  }

  var iv = setInterval(function(){
    var wrapped = wrapLoader();
    applyAliases(); // covers DB already populated by the time this script runs
    if((wrapped && DB_ready()) || ++tries > 60) clearInterval(iv);
    function DB_ready(){ return !!(W.DB && Array.isArray(W.DB.customers)); }
  }, 300);
})();
</script>

<script nonce="<?php echo $cspNonceAttr; ?>" id="claude-feature-grand-totals">
/* FEATURE (Qty/Amount grand total on every page): rather than hand-editing
   every one of this app's 200+ render functions, this watches the page and
   automatically appends a "Grand Total" row to any table that has a Qty
   and/or Amount column -- on every page, including ones added later. It
   never changes what a table's own rows show; it only adds a summary row
   under tables that don't already have one of their own.

   How it decides:
   - A column counts as Qty if its header contains "Qty" or "Quantity"
     (whole word, case-insensitive) -- e.g. "Sending Qty", "Received Qty".
   - A column counts as Amount if its header contains "Amount" or "Amt"
     (whole word, case-insensitive) -- e.g. "Total Amount", "Paid Amount",
     "Due Amount" each get their own grand total.
   - Currency symbols, commas, and parentheses-as-negative are handled when
     reading and re-printing numbers, so the total looks like the numbers
     above it.
   - Tables with 0 or 1 data row are skipped (nothing meaningful to total).
   - Rows that already read "Total" / "Subtotal" / "Grand Total" in their
     first cell are excluded from the sum so nothing gets counted twice.
   - Re-runs after every page navigation and on any content change (search,
     filter, edit, pagination), always replacing its own previous row rather
     than stacking duplicates. It never touches a totals row that isn't its
     own (recognised by a data-ayan-grandtotal marker), so it will not
     interfere with any report that already builds its own total line. */
(function(){
'use strict';
var W = window;
var MARK = 'data-ayan-grandtotal';

/* Pages/sections that must never get an auto grand-total row, however their
   markup changes later. Add more container selectors here on request. */
var EXCLUDE_SELECTORS = [
  '#trial-balance-section'   // Trial Balance — left/right must match exactly;
                              // an added total row could be misread as part
                              // of that balance.
];
function isExcluded(table){
  for(var i=0;i<EXCLUDE_SELECTORS.length;i++){
    if(table.closest && table.closest(EXCLUDE_SELECTORS[i])) return true;
  }
  return false;
}

function parseNum(txt){
  if(txt==null) return null;
  var s = String(txt).trim();
  if(s===''||s==='-'||s==='\u2014'||s==='--'||s==='N/A') return null;
  var neg = false;
  if(/^\(.*\)$/.test(s)){ neg = true; s = s.slice(1,-1); }
  if(/^-/.test(s.trim())) neg = true;
  s = s.replace(/[^\d.\-]/g,'');
  if(s===''||s==='-'||s==='.') return null;
  var n = parseFloat(s);
  if(!isFinite(n)) return null;
  return neg ? -Math.abs(n) : n;
}

function fmtLike(sample, value){
  var s = sample||'';
  var curMatch = s.match(/[\u09F3$\u20B9\u00A3\u20AC]/);
  var decimals = /\.\d/.test(s) ? 2 : 0;
  var out = Math.abs(value).toLocaleString('en-US',{minimumFractionDigits:decimals,maximumFractionDigits:decimals});
  if(value<0) out = '(' + out + ')';
  if(curMatch) out = curMatch[0] + out;
  return out;
}

function headerText(cell){ return (cell && cell.textContent || '').replace(/\s+/g,' ').trim(); }
function isQtyHeader(t){ return /\b(qty|quantity)\b/i.test(t); }
function isAmtHeader(t){ return /\b(amount|amt)\b/i.test(t); }
function isTotalRowLabel(t){ return /\b(grand\s*total|sub\s*-?\s*total|^total$)\b/i.test((t||'').trim()); }

function processTable(table){
  try{
    if(!table || !table.rows || table.rows.length < 2) return;
    if(isExcluded(table)) return;
    var headerRow = (table.tHead && table.tHead.rows.length)
      ? table.tHead.rows[table.tHead.rows.length-1]
      : table.rows[0];
    if(!headerRow || !headerRow.cells || !headerRow.cells.length) return;

    var targets = [];
    for(var i=0;i<headerRow.cells.length;i++){
      var t = headerText(headerRow.cells[i]);
      if(!t) continue;
      if(isQtyHeader(t)) targets.push({idx:i, kind:'qty'});
      else if(isAmtHeader(t)) targets.push({idx:i, kind:'amt'});
    }
    if(!targets.length) return;

    var bodyRows = [];
    if(table.tBodies && table.tBodies.length){
      for(var b=0;b<table.tBodies.length;b++){
        for(var r=0;r<table.tBodies[b].rows.length;r++) bodyRows.push(table.tBodies[b].rows[r]);
      }
    } else {
      for(var r2=0;r2<table.rows.length;r2++){ if(table.rows[r2]!==headerRow) bodyRows.push(table.rows[r2]); }
    }
    var dataRows = bodyRows.filter(function(row){
      if(row.hasAttribute && row.hasAttribute(MARK)) return false;
      var c0 = row.cells && row.cells[0] ? headerText(row.cells[0]) : '';
      return !isTotalRowLabel(c0);
    });
    if(dataRows.length < 2) return;

    var sums = {}, samples = {};
    targets.forEach(function(t){ sums[t.idx]=0; samples[t.idx]=''; });
    var any=false;
    dataRows.forEach(function(row){
      targets.forEach(function(t){
        var cell = row.cells[t.idx];
        if(!cell) return;
        var raw = cell.textContent||'';
        var n = parseNum(raw);
        if(n!=null){ sums[t.idx]+=n; any=true; if(!samples[t.idx]) samples[t.idx]=raw.trim(); }
      });
    });
    if(!any) return;

    var old = table.querySelector('tfoot['+MARK+']');
    if(old && old.parentNode) old.parentNode.removeChild(old);

    var colCount = headerRow.cells.length;
    var tfoot = document.createElement('tfoot');
    tfoot.setAttribute(MARK,'1');
    var tr = document.createElement('tr');
    tr.setAttribute(MARK,'1');
    tr.style.fontWeight='800';
    tr.style.borderTop='2px solid #94a3b8';
    tr.style.background='rgba(37,99,235,0.07)';

    var firstIdx = targets.reduce(function(m,t){ return Math.min(m,t.idx); },colCount);
    if(firstIdx>0){
      var labelTd=document.createElement('td');
      labelTd.textContent='Grand Total';
      labelTd.colSpan=firstIdx;
      labelTd.style.textAlign='left';
      labelTd.style.padding='8px 10px';
      tr.appendChild(labelTd);
    }
    for(var c=firstIdx;c<colCount;c++){
      var td=document.createElement('td');
      td.style.padding='8px 10px';
      var target = targets.filter(function(t){return t.idx===c;})[0];
      if(target){
        td.textContent = fmtLike(samples[target.idx], sums[target.idx]);
        td.style.textAlign='right';
      } else if(firstIdx===0 && c===0){
        td.textContent='Grand Total';
        td.style.textAlign='left';
      }
      tr.appendChild(td);
    }
    tfoot.appendChild(tr);
    table.appendChild(tfoot);
  }catch(e){ /* never let a bad table block the rest of the page */ }
}

function scan(root){
  if(!root) return;
  var tables = (root.querySelectorAll ? root.querySelectorAll('table') : []);
  for(var i=0;i<tables.length;i++) processTable(tables[i]);
}
W.ayanAddGrandTotals = scan;

/* Run after every page navigation. */
if(typeof W.render==='function' && !W.render.__ayanGTWrapped){
  var origRender = W.render;
  var wrapped = function(page){
    var out = origRender.apply(this, arguments);
    try{
      var key = (W.PAGE_ALIASES && W.PAGE_ALIASES[page]) || page;
      var el = document.getElementById('pg-'+key);
      setTimeout(function(){ scan(el || document); }, 0);
    }catch(e){}
    return out;
  };
  wrapped.__ayanGTWrapped = true;
  W.render = wrapped;
}

/* Safety net for content that updates without a full nav() -- search
   filters, inline edits, pagination -- debounced and self-quiet so our own
   tfoot insert never triggers another pass. */
(function(){
  var mainEl = document.querySelector('.main') || document.body;
  var timer = null, observer = null;
  function isOwnMutation(mutations){
    for(var i=0;i<mutations.length;i++){
      var m = mutations[i];
      var added = m.addedNodes || [];
      if(added.length===0) return false;
      for(var j=0;j<added.length;j++){
        var n = added[j];
        var own = (n.nodeType===1 && n.hasAttribute && (n.hasAttribute(MARK) ||
          (n.tagName==='TFOOT' && n.querySelector && n.querySelector('['+MARK+']'))));
        if(!own) return false;
      }
    }
    return true;
  }
  observer = new MutationObserver(function(mutations){
    if(isOwnMutation(mutations)) return;
    clearTimeout(timer);
    timer = setTimeout(function(){
      observer.disconnect();
      scan(mainEl);
      observer.observe(mainEl, {childList:true, subtree:true});
    }, 200);
  });
  observer.observe(mainEl, {childList:true, subtree:true});
})();

if(document.readyState==='loading'){
  document.addEventListener('DOMContentLoaded', function(){ scan(document); });
} else {
  scan(document);
}
})();
</script>

<!-- ═══════════════════════════════════════════════════════════════════════════
     AYAN AGRO ERP — UI/UX AUDIT & REFACTOR LAYER  (audit pass, 2026-08-24)

     Additive only. This block appends CSS and behaviour at the very end of the
     document so it wins the cascade without editing, deleting or rewriting a
     single line of existing markup, state management, calculation code or
     persistence logic. Every legacy element it supersedes is kept in the DOM
     (nodes are MOVED, never cloned or re-created) so all original onclick
     handlers, ids and closures continue to work exactly as before.

     Covers the four requested areas:
       1. Layout / z-index / navigation repairs
       2. Transaction entry grid + full-screen drawer + keyboard matrix
       3. Input cleanliness (no native spinners, clean borders, cell padding)
       4. Professional A4 document printing standard
     ══════════════════════════════════════════════════════════════════════ -->
<style id="ayan-audit-2026">

/* ─────────────────────────────────────────────────────────────────────────
   1a. FLOATING ACTION BUTTONS → ONE COLLAPSIBLE SPEED DIAL
   Four independent fixed-position stacks had accumulated in the bottom-right
   corner (#fab + #fab-menu, #v2-launcher + #v2-launcher-toggle,
   #quick-access-fab + #fab-menu-qa, and the pay button), each added by a
   different patch, each unaware of the others. Together they covered the
   Sales / Profit / Dues KPI tiles and the Business Health panel on both
   desktop and phone. They are now consolidated into a single collapsible
   Speed Dial: collapsed to one 52px trigger by default, capped height,
   internally scrollable, every action one click away.
   The legacy stacks are only hidden once the speed dial has actually been
   built (body.ayan-sd-ready), so a JS failure can never hide the actions.
   ───────────────────────────────────────────────────────────────────────── */
#ayan-sd{
  position:fixed; right:16px;
  bottom:calc(18px + var(--erp-reminder-h,0px) + env(safe-area-inset-bottom));
  z-index:9500; display:flex; flex-direction:column;
  align-items:flex-end; gap:10px;
}
#ayan-sd-panel{
  display:none; flex-direction:column; align-items:stretch; gap:6px;
  width:min(268px,80vw);
  max-height:min(58vh,430px); overflow-y:auto; overscroll-behavior:contain;
  background:#fff; border:1px solid #cbd5e1; border-radius:14px;
  padding:8px; box-shadow:0 18px 44px rgba(15,23,42,.24);
}
#ayan-sd.open #ayan-sd-panel{ display:flex; }
#ayan-sd-head{
  font-size:10px; font-weight:800; letter-spacing:.12em; text-transform:uppercase;
  color:#64748b; padding:2px 6px 6px; border-bottom:1px solid #e2e8f0; margin-bottom:2px;
}
/* neutralise the inline fixed-position / pill styling the moved buttons carry */
#ayan-sd-panel > *,
#ayan-sd-panel button{
  position:static !important; inset:auto !important; margin:0 !important;
  width:100% !important; max-width:100% !important;
  white-space:normal !important; text-align:left !important;
  justify-content:flex-start !important;
}
#ayan-sd-panel button{
  border-radius:10px !important; font-size:12px !important;
  padding:9px 12px !important; box-shadow:none !important;
  min-height:38px; display:flex !important; align-items:center; gap:8px;
}
#ayan-sd-panel button:hover{ filter:brightness(1.07); transform:none !important; }
#ayan-sd-panel .fab-item{ display:flex; align-items:center; gap:8px; }
#ayan-sd-panel .fab-item .fab-label{
  background:transparent !important; color:#0f172a !important;
  font-size:12px !important; padding:0 !important; order:2; flex:1;
}
#ayan-sd-panel .fab-item .fab-btn{
  width:32px !important; height:32px !important; min-height:32px;
  flex:0 0 32px; border-radius:50% !important; order:1;
  justify-content:center !important; padding:0 !important;
}
#ayan-sd-toggle{
  width:52px; height:52px; border-radius:50%; border:0; cursor:pointer;
  background:linear-gradient(135deg,#16a34a,#0f3d26); color:#fff;
  font-size:22px; line-height:1; display:flex; align-items:center; justify-content:center;
  box-shadow:0 8px 22px rgba(15,61,38,.38); transition:transform .18s;
}
#ayan-sd-toggle:hover{ transform:scale(1.06); }
#ayan-sd.open #ayan-sd-toggle{ background:#0f172a; }
body.ayan-sd-ready #fab,
body.ayan-sd-ready #fab-menu,
body.ayan-sd-ready #v2-launcher,
body.ayan-sd-ready #v2-launcher-toggle,
body.ayan-sd-ready #quick-access-fab,
body.ayan-sd-ready #fab-menu-qa{ display:none !important; }
/* the dial never floats over the login screen or the print sheet */
body.ayan-login-open #ayan-sd{ display:none !important; }
/* keep the dial clear of the mobile bottom nav */
@media (max-width:768px){
  #ayan-sd{ bottom:calc(74px + var(--erp-reminder-h,0px) + env(safe-area-inset-bottom)); right:12px; }
}

/* ─────────────────────────────────────────────────────────────────────────
   1b. SIDE NAVIGATION CLIPPING
   With several nav sections expanded the menu grew past the viewport and the
   last items were unreachable. The rail is now hard-capped to the viewport
   height and only the nav list scrolls, so the logo and search stay pinned.
   ───────────────────────────────────────────────────────────────────────── */
.sidebar{ max-height:var(--app-vh,100vh) !important; }
.nav-scroll, #navScroll{
  overflow-y:auto !important; max-height:100%;
  overscroll-behavior:contain; -webkit-overflow-scrolling:touch;
  padding-bottom:28px;
}
@media (max-width:768px){
  .sidebar{ overflow-y:auto !important; }
}

/* ─────────────────────────────────────────────────────────────────────────
   2a. ENTRY MODALS → FULL-SCREEN SLIDE-OVER DRAWERS
   #mTx was already converted in an earlier pass; the other grid-heavy entry
   forms (Finance, Quotations, General Ledger) had the same cramped 900px
   popup problem and now share the same drawer treatment. Below 769px the
   existing bottom-sheet rules already handle it, so they are left alone.
   ───────────────────────────────────────────────────────────────────────── */
@media (min-width:769px){
  #mFin.overlay, #mGenLedger.overlay{
    align-items:stretch !important; justify-content:flex-end !important; padding:0 !important;
  }
  #mFin .modal, #mGenLedger .modal{
    width:min(1040px,96vw) !important; max-width:min(1040px,96vw) !important;
    height:100vh !important; max-height:100vh !important;
    border-radius:0 !important; margin:0 !important;
    animation:erpSlideIn .28s cubic-bezier(.22,1,.36,1) both !important;
  }
  /* Quotations: centered full-screen modal, not a side drawer */
  #mQuotations.overlay{
    align-items:center !important; justify-content:center !important; padding:16px !important;
  }
  #mQuotations .modal{
    width:min(1100px,98vw) !important; max-width:min(1100px,98vw) !important;
    height:auto !important; max-height:94vh !important;
    border-radius:14px !important; margin:0 auto !important;
    overflow-y:auto !important;
  }
}

/* ─────────────────────────────────────────────────────────────────────────
   2b/3. INPUT CLEANLINESS
   Native number spinners are removed everywhere (they stole cell width and
   invited accidental scroll-wheel edits), numeric/text fields get a single
   high-contrast 1px #cbd5e1 border, and grid cells get real padding.
   Checkboxes and radios are excluded so they keep their native look.
   ───────────────────────────────────────────────────────────────────────── */
input[type=number]{ -moz-appearance:textfield; appearance:textfield; }
input[type=number]::-webkit-outer-spin-button,
input[type=number]::-webkit-inner-spin-button{
  -webkit-appearance:none; appearance:none; margin:0;
}
table input:not([type=checkbox]):not([type=radio]),
table select, table textarea,
.modal input:not([type=checkbox]):not([type=radio]),
.modal select, .modal textarea{
  border:1px solid #cbd5e1; border-radius:8px; padding:7px 9px;
  background:#fff; color:#1a202c;
}
table input:not([type=checkbox]):not([type=radio]):focus,
table select:focus,
.modal input:not([type=checkbox]):not([type=radio]):focus,
.modal select:focus, .modal textarea:focus{
  outline:none; border-color:#16a34a; box-shadow:0 0 0 3px rgba(22,163,74,.16);
}
.table-wrap td, .table-wrap th,
.modal table td, .modal table th{ padding:8px 10px; }
/* right-aligned tabular figures wherever a cell is marked numeric */
td.num, th.num, .num{ text-align:right; font-variant-numeric:tabular-nums; }
/* the cell that currently owns keyboard focus in the entry grid */
tr:focus-within > td{ background:rgba(22,163,74,.05); }

/* ─────────────────────────────────────────────────────────────────────────
   4. PROFESSIONAL PRINT STANDARD (global, not only body.print-page-mode)
   App chrome — sidebar, topbar, bottom nav, speed dial, search boxes,
   toolbars, toasts, buttons inside toolbars — never reaches paper again.
   ───────────────────────────────────────────────────────────────────────── */
@media print{
  @page{ size:A4; margin:12mm 12mm 16mm; }
  .sidebar, .topbar, #bottom-nav, .hamburger, .mobile-menu-btn,
  #ayan-sd, #fab, #fab-menu, #v2-launcher, #v2-launcher-toggle,
  #quick-access-fab, #fab-menu-qa,
  .sidebar-overlay, #sidebarOverlay, #mobile-overlay,
  .nav-search-wrap, .print-toolbar, .pb-bar, .pbm-overlay,
  #autosave-progress, #save-indicator, .toast, .sync-toast,
  #erp-backup-reminder, #erp-storage-banner, #erp-safety-fab, #ayan-ai-fab,
  .no-print{ display:none !important; }
  .main{ margin-left:0 !important; padding:0 !important; }
  body{ background:#fff !important; }

  /* zebra-striped itemised tables with right-aligned currency */
  #print-area table, .ayan-doc table{ width:100%; border-collapse:collapse; }
  #print-area table tbody tr:nth-child(even),
  .ayan-doc table tbody tr:nth-child(even){
    background:#f1f5f9 !important;
    -webkit-print-color-adjust:exact; print-color-adjust:exact;
  }
  #print-area table td, #print-area table th,
  .ayan-doc table td, .ayan-doc table th{
    border:1px solid #94a3b8; padding:5px 7px; font-size:11px;
  }
  #print-area table thead th, .ayan-doc table thead th{
    background:#e2e8f0 !important; text-align:left; font-weight:800;
    -webkit-print-color-adjust:exact; print-color-adjust:exact;
  }
  #print-area .num, .ayan-doc .num{ text-align:right; }
  #print-area thead, .ayan-doc thead{ display:table-header-group; }
  #print-area tr, .ayan-doc tr{ page-break-inside:avoid; }
  .ayan-doc-sigrow, .print-sigfooter{ page-break-inside:avoid; }
}

/* ─────────────────────────────────────────────────────────────────────────
   4b. A4 DOCUMENT ANATOMY (used by ayanPrintDoc(), screen + paper)
   ───────────────────────────────────────────────────────────────────────── */
.ayan-doc{
  font-family:'Segoe UI',system-ui,sans-serif; color:#0f172a; font-size:12px;
  width:186mm; margin:0 auto; position:relative;
}
.ayan-doc-head{ display:flex; justify-content:space-between; align-items:flex-start;
  gap:14px; border-bottom:2.5px solid #0f3d26; padding-bottom:8px; }
.ayan-doc-co{ font-size:16px; font-weight:800; color:#0f3d26; letter-spacing:.2px; }
.ayan-doc-sub{ font-size:10.5px; color:#475569; margin-top:2px; line-height:1.5; }
.ayan-doc-title{ text-align:center; font-size:14px; font-weight:800; letter-spacing:.16em;
  text-transform:uppercase; margin:10px 0 8px; color:#0f3d26; }
.ayan-doc-meta{ display:grid; grid-template-columns:1fr 1fr; gap:2px 18px;
  border:1px solid #94a3b8; padding:7px 9px; margin-bottom:10px; }
.ayan-doc-meta div{ display:flex; justify-content:space-between; gap:10px; font-size:11px;
  padding:2px 0; border-bottom:1px dotted #cbd5e1; }
.ayan-doc-meta div span:first-child{ color:#475569; font-weight:600; }
.ayan-doc-meta div span:last-child{ font-weight:700; }
.ayan-doc-words{ border:1px solid #94a3b8; padding:6px 9px; margin:10px 0 14px;
  font-size:11.5px; background:#f8fafc; }
.ayan-doc-words b{ color:#0f3d26; }
.ayan-doc-sigrow{ display:grid; grid-template-columns:repeat(3,1fr); gap:24px; margin-top:26px; }
.ayan-doc-sig{ text-align:center; font-size:10.5px; }
.ayan-doc-sig .line{ border-top:1px solid #0f172a; margin-bottom:5px; padding-top:0; }
.ayan-doc-sig .role{ font-weight:700; }
.ayan-doc-sig .hint{ color:#64748b; }
.ayan-doc-footer{ margin-top:18px; border-top:1px solid #cbd5e1; padding-top:5px;
  font-size:9.5px; color:#64748b; display:flex; justify-content:space-between; gap:12px; }
</style>

<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-audit-2026-js">
(function(){
  'use strict';

  /* ═════════════════════════════════════════════════════════════════════
     1. SPEED DIAL CONSOLIDATION
     The existing floating buttons are MOVED (appendChild on live nodes),
     never re-created, so their original inline onclick handlers, ids and
     closures survive untouched.
     ═══════════════════════════════════════════════════════════════════ */
  var SOURCES = [
    { sel:'#fab-menu',       take:'children' },   // legacy mobile FAB menu
    { sel:'#fab-menu-qa',    take:'children' },   // Quick Access (⚡) menu
    { sel:'#v2-launcher',    take:'buttons'  },   // Freight/Sync/Cost/Factory pills
    { sel:'#ayanPayBtn',     take:'self'     }    // standalone pay button
  ];

  function buildSpeedDial(){
    if(document.getElementById('ayan-sd')) return;
    var wrap = document.createElement('div');
    wrap.id = 'ayan-sd';
    wrap.innerHTML =
      '<div id="ayan-sd-panel" role="menu" aria-label="Quick actions">' +
        '<div id="ayan-sd-head">Quick actions</div>' +
      '</div>' +
      '<button id="ayan-sd-toggle" type="button" aria-expanded="false" ' +
        'aria-label="Quick actions" title="Quick actions">\u26A1</button>';
    document.body.appendChild(wrap);

    var panel  = wrap.querySelector('#ayan-sd-panel');
    var toggle = wrap.querySelector('#ayan-sd-toggle');
    var moved  = 0;

    SOURCES.forEach(function(src){
      var host = document.querySelector(src.sel);
      if(!host) return;
      var nodes = src.take === 'self'     ? [host]
                : src.take === 'buttons'  ? Array.prototype.slice.call(host.querySelectorAll(':scope > button'))
                                          : Array.prototype.slice.call(host.children);
      nodes.forEach(function(n){
        if(n.id === 'ayan-sd-toggle' || n.id === 'v2-launcher-toggle') return;
        n.style.display = '';          // legacy code may have left it hidden
        panel.appendChild(n);          // live move — handlers preserved
        moved++;
      });
    });

    if(!moved){ wrap.remove(); return; } // nothing to consolidate: leave as-is
    document.body.classList.add('ayan-sd-ready');

    function setOpen(open){
      wrap.classList.toggle('open', open);
      toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
      toggle.textContent = open ? '\u2715' : '\u26A1';
    }
    toggle.addEventListener('click', function(e){
      e.stopPropagation();
      setOpen(!wrap.classList.contains('open'));
    });
    // any action inside the panel closes it
    panel.addEventListener('click', function(e){
      if(e.target.closest('button')) setOpen(false);
    });
    document.addEventListener('click', function(e){
      if(!e.target.closest('#ayan-sd')) setOpen(false);
    });
    document.addEventListener('keydown', function(e){
      if(e.key === 'Escape') setOpen(false);
    });
  }

  /* ═════════════════════════════════════════════════════════════════════
     2. KEYBOARD MATRIX NAVIGATION for table-based entry grids
     Arrow keys walk the grid, Enter steps down (and never submits a form
     implicitly), Tab keeps its native behaviour. Left/Right only jump cell
     when the caret is already at the edge of the text, so normal typing and
     in-field editing are unaffected. Any field that opts out with
     data-no-grid-nav is skipped.
     ═══════════════════════════════════════════════════════════════════ */
  var FOCUSABLE = 'input:not([type=hidden]):not([disabled]):not([readonly]),select:not([disabled]),textarea:not([disabled])';

  function cellIndex(td){ return Array.prototype.indexOf.call(td.parentNode.children, td); }

  function focusIn(td){
    if(!td) return false;
    var f = td.querySelector(FOCUSABLE);
    if(!f) return false;
    f.focus();
    if(f.select && f.type !== 'checkbox' && f.type !== 'radio' && f.tagName !== 'SELECT'){
      try{ f.select(); }catch(_){}
    }
    return true;
  }

  function step(row, dir, col){
    var r = row;
    while(true){
      r = dir > 0 ? r.nextElementSibling : r.previousElementSibling;
      if(!r) return false;
      if(r.tagName !== 'TR') continue;
      var cells = r.children, i;
      // same column first, then the nearest focusable cell to its right
      for(i = col; i < cells.length; i++){ if(focusIn(cells[i])) return true; }
      for(i = col - 1; i >= 0; i--){ if(focusIn(cells[i])) return true; }
    }
  }

  function sideways(td, dir){
    var cells = td.parentNode.children;
    var i = cellIndex(td) + dir;
    while(i >= 0 && i < cells.length){
      if(focusIn(cells[i])) return true;
      i += dir;
    }
    return false;
  }

  document.addEventListener('keydown', function(e){
    var el = e.target;
    if(!el || !el.matches || !el.matches(FOCUSABLE)) return;
    if(el.hasAttribute('data-no-grid-nav')) return;
    var td = el.closest('td,th');
    var tr = td && td.closest('tr');
    if(!td || !tr) return;                       // only inside table grids
    if(el.tagName === 'SELECT' && (e.key === 'ArrowUp' || e.key === 'ArrowDown')) return; // let selects change value
    var isText = el.tagName !== 'SELECT' && typeof el.selectionStart === 'number';

    switch(e.key){
      case 'ArrowDown':
        if(step(tr, 1, cellIndex(td))) e.preventDefault();
        break;
      case 'ArrowUp':
        if(step(tr, -1, cellIndex(td))) e.preventDefault();
        break;
      case 'ArrowRight':
        if(isText && el.selectionEnd < (el.value || '').length) return;
        if(sideways(td, 1)) e.preventDefault();
        break;
      case 'ArrowLeft':
        if(isText && el.selectionStart > 0) return;
        if(sideways(td, -1)) e.preventDefault();
        break;
      case 'Enter':
        if(el.tagName === 'TEXTAREA') return;
        e.preventDefault();                       // never implicit-submit a grid row
        if(!step(tr, 1, cellIndex(td))) el.blur();
        break;
    }
  }, true);

  /* stop the scroll wheel silently editing a focused number field */
  document.addEventListener('wheel', function(e){
    var el = document.activeElement;
    if(el && el.type === 'number' && el === e.target) el.blur();
  }, { passive:true });

  /* ═════════════════════════════════════════════════════════════════════
     3. PRINT HELPERS
     ═══════════════════════════════════════════════════════════════════ */
  function money(n){
    n = Number(n || 0);
    return n.toLocaleString('en-US', { minimumFractionDigits:2, maximumFractionDigits:2 });
  }

  /* Amount in words — reuses the app's existing numberToWords() when present
     so wording stays identical to the vouchers already in circulation. */
  function amountInWords(amt){
    amt = Number(amt || 0);
    var whole = Math.floor(Math.abs(amt));
    var paisa = Math.round((Math.abs(amt) - whole) * 100);
    var w = (typeof window.numberToWords === 'function')
      ? window.numberToWords(whole)
      : String(whole);
    var out = (amt < 0 ? 'Minus ' : '') + w + ' Taka';
    if(paisa > 0){
      out += ' and ' + ((typeof window.numberToWords === 'function') ? window.numberToWords(paisa) : paisa) + ' Paisa';
    }
    return (out + ' Only').replace(/\s+/g, ' ').trim();
  }
  window.ayanAmountInWords = amountInWords;

  var COMPANY = {
    name:'AYAN AGRO INTERNATIONAL LIMITED',
    concern:'Concern: M S Karima Enterprise',
    address:'Head Office: Dhaka, Bangladesh',
    phone:'01725-219158, 01711-404063',
    email:'admin@ayanagro.com',
    web:'www.ayanagro.com',
    tin:'TIN: 123456789012',
    bin:'BIN: 000123456-0101',
    lic:'Trade License: TRAD/DNCC/123456/2024'
  };

  function esc(s){
    return (window.escHTML ? window.escHTML(s) : String(s == null ? '' : s));
  }

  /**
   * ayanPrintDoc(cfg) — renders a standards-compliant A4 document and opens
   * the print dialog. Purely presentational: it reads values you pass in and
   * writes nothing back to DB / localStorage.
   *
   * cfg = {
   *   title:  'SALES INVOICE',
   *   meta:   { 'Invoice No':'INV-1201', 'Date':'24-08-2026', 'Customer':'ACME' },
   *   columns:[ {label:'Description'}, {label:'Qty',num:true}, {label:'Amount',num:true} ],
   *   rows:   [ ['Rice Bran Oil 5L', '20', '12,500.00'] ],
   *   totals: [ ['Sub Total','12,500.00'], ['VAT 5%','625.00'], ['Grand Total','13,125.00'] ],
   *   amount: 13125,               // drives "Amount in Words"
   *   note:   'Terms: payment due in 15 days.'
   * }
   */
  function ayanPrintDoc(cfg){
    cfg = cfg || {};
    var cols = cfg.columns || [];
    var rows = cfg.rows || [];
    var metaKeys = Object.keys(cfg.meta || {});

    var head =
      '<div class="ayan-doc-head">' +
        '<div><div class="ayan-doc-co">' + esc(COMPANY.name) + '</div>' +
        '<div class="ayan-doc-sub">' + esc(COMPANY.concern) + '<br>' + esc(COMPANY.address) +
        '<br>' + esc(COMPANY.lic) + ' &nbsp;|&nbsp; ' + esc(COMPANY.tin) + ' &nbsp;|&nbsp; ' + esc(COMPANY.bin) + '</div></div>' +
        '<div class="ayan-doc-sub" style="text-align:right;">' + esc(COMPANY.phone) +
        '<br>' + esc(COMPANY.email) + '<br>' + esc(COMPANY.web) + '</div>' +
      '</div>' +
      '<div class="ayan-doc-title">' + esc(cfg.title || 'DOCUMENT') + '</div>';

    var meta = metaKeys.length
      ? '<div class="ayan-doc-meta">' + metaKeys.map(function(k){
          return '<div><span>' + esc(k) + '</span><span>' + esc(cfg.meta[k]) + '</span></div>';
        }).join('') + '</div>'
      : '';

    var table = cols.length
      ? '<table><thead><tr><th style="width:34px" class="num">#</th>' +
          cols.map(function(c){ return '<th class="' + (c.num ? 'num' : '') + '">' + esc(c.label) + '</th>'; }).join('') +
        '</tr></thead><tbody>' +
          rows.map(function(r, i){
            return '<tr><td class="num">' + (i + 1) + '</td>' +
              r.map(function(v, ci){
                return '<td class="' + ((cols[ci] && cols[ci].num) ? 'num' : '') + '">' + esc(v) + '</td>';
              }).join('') + '</tr>';
          }).join('') +
        '</tbody>' +
        ((cfg.totals || []).length
          ? '<tfoot>' + cfg.totals.map(function(t){
              return '<tr><td colspan="' + cols.length + '" class="num" style="font-weight:700;">' + esc(t[0]) + '</td>' +
                     '<td class="num" style="font-weight:800;">' + esc(t[1]) + '</td></tr>';
            }).join('') + '</tfoot>'
          : '') +
        '</table>'
      : '';

    var words = (cfg.amount != null)
      ? '<div class="ayan-doc-words"><b>Amount in Words:</b> ' + esc(amountInWords(cfg.amount)) + '</div>'
      : '';

    var sigs =
      '<div class="ayan-doc-sigrow">' +
        [['Prepared By','Accounts'],['Checked By','Manager'],['Authorized Officer','Director']]
          .map(function(s){
            return '<div class="ayan-doc-sig"><div class="line"></div>' +
                   '<div class="role">' + s[0] + '</div><div class="hint">' + s[1] + '</div></div>';
          }).join('') +
      '</div>';

    var printed = new Date().toLocaleString('en-GB');
    var footer =
      (cfg.note ? '<div class="ayan-doc-sub" style="margin-top:14px;">' + esc(cfg.note) + '</div>' : '') +
      '<div class="ayan-doc-footer">' +
        '<span>Computer generated document \u2014 no manual signature required for system copy.</span>' +
        /* NOTE: real page numbers ("Page 2 of 3") need CSS @page margin-box
           counters, which Chromium's print engine doesn't render — showing
           "Page" with nothing after it looked broken, so this only prints
           what every browser can actually fill in: the timestamp. */
        '<span>Printed: ' + esc(printed) + '</span>' +
      '</div>';

    var css = document.getElementById('ayan-audit-2026');
    var w = window.open('', '_blank', 'width=980,height=760');
    if(!w){ alert('Please allow pop-ups to print this document.'); return; }
    w.document.write(
      '<!DOCTYPE html><html><head><meta charset="utf-8"><title>' + esc(cfg.title || 'Document') + '</title>' +
      '<style>' + (css ? css.textContent : '') +
      'body{margin:0;padding:12mm;background:#fff;}' +
      '@page{size:A4;margin:12mm 12mm 16mm;}' +
      /* page numbers where the engine supports @page margin boxes; the browser
         print dialog supplies them everywhere else */
      '@page{@bottom-right{content:"Page " counter(page) " of " counter(pages);font-size:9px;color:#64748b;}}' +
      '</style></head><body><div class="ayan-doc">' +
      head + meta + table + words + sigs + footer +
      '</div></body></html>'
    );
    w.document.close();
    w.focus();
    setTimeout(function(){ try{ w.print(); }catch(_){} }, 320);
  }
  window.ayanPrintDoc = ayanPrintDoc;
  window.ayanMoney = money;

  /* ═════════════════════════════════════════════════════════════════════
     BOOT
     ═══════════════════════════════════════════════════════════════════ */
  /* keep the dial out of the way whenever the login overlay is visible */
  function watchLogin(){
    var ls = document.getElementById('login-screen');
    if(!ls) return;
    var sync = function(){
      var open = getComputedStyle(ls).display !== 'none';
      document.body.classList.toggle('ayan-login-open', open);
    };
    sync();
    new MutationObserver(sync).observe(ls, { attributes:true, attributeFilter:['style','class'] });
  }

  function boot(){
    try{ buildSpeedDial(); }catch(err){ console.warn('[audit] speed dial skipped:', err); }
    try{ watchLogin(); }catch(err){ console.warn('[audit] login watch skipped:', err); }
  }
  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', function(){ setTimeout(boot, 400); });
  }else{
    setTimeout(boot, 400);
  }
})();
</script>

<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-go-to-sales">
/* ═══════════════════════════════════════════════════════════════════════
   AYAN ERP — "➡️ Go to Sales" (direct dispatch / drop-ship handoff)

   WHAT IT DOES
   Adds one button to the bottom of the Transaction form. When the form is
   a Purchase, pressing it:
       1. saves the purchase exactly as "💾 Save Transaction" would
          (same approval gating, same balance check, same stock posting),
       2. re-opens the form as a fresh SALE, already carrying the goods
          over — product, bag type, bag qty, qty, gross and net weight,
          location, challan, truck,
       3. leaves Customer, Rate and Amount blank for you to fill,
       4. pre-fills an EDITABLE "Cost / KG" box with the landed cost of
          that purchase, and shows a live deal margin beside it.

   MULTIPLE PRODUCTS (same supplier) — 2026-08-30
   If the purchase was entered with "📦 Multiple Products (same supplier)"
   checked, every product line carries across too: the Sale opens with the
   same checkbox on and the same rows (product, bag type, bag qty, qty,
   gross/net weight), Rate left blank on each line for your selling price.
   This is driven purely through the existing grid's own DOM controls
   (its checkbox, "+ Add Product" button, and cell inputs) — it does not
   read or write the Purchase Enhancement Pack's internal row array, so it
   cannot get out of step with it.

   WHAT IT DOES NOT TOUCH
   Every existing sales rule still runs untouched — sales tax, net payable,
   weight loss, bag tare, agent A/B, QC and unload auto-fill. This file
   never calculates them itself; it fills the fields and then calls the
   app's own functions.

   The Cost / KG figure is stored on the sale as tx.costRate / tx.costAmt
   for deal-level reporting ONLY. It is deliberately NOT fed into
   computeCOGS() / netProfitOf(), because those already derive cost of
   goods from the purchase rows — feeding it in as well would count the
   same cost twice in the P&L.

   INSTALL: paste this whole block as the LAST <script> before </body>.
   ═══════════════════════════════════════════════════════════════════ */
(function () {
  'use strict';

  /* ── small helpers ─────────────────────────────────────────────── */
  function $(id) { return document.getElementById(id); }
  function val(id) { var e = $(id); return e ? String(e.value == null ? '' : e.value) : ''; }
  function num(id) { var e = $(id); return e ? (parseFloat(e.value) || 0) : 0; }
  function setV(id, v) { var e = $(id); if (e) e.value = (v == null ? '' : v); }
  function say(m, k) { try { toast(m, k || 'i'); } catch (e) { console.log('[GoToSales]', m); } }
  function call(fn) { try { if (typeof window[fn] === 'function') window[fn].apply(null, [].slice.call(arguments, 1)); } catch (e) { console.warn('[GoToSales]', fn, e); } }

  function isPurchType(t) {
    if (typeof window.ayanIsPurchaseType === 'function') return !!window.ayanIsPurchaseType(t);
    return ['purchase', 'supplier purchase', 'warehouse purchase', 'werhouse purchase']
      .indexOf(String(t || '').trim().toLowerCase()) >= 0;
  }
  function isSaleT(t) {
    if (typeof window.isSaleType === 'function') return !!window.isSaleType(t);
    return ['sale', 'customer sale', 'warehouse sale']
      .indexOf(String(t || '').trim().toLowerCase()) >= 0;
  }
  /* the weight the whole form works off, same precedence the app uses */
  function formKg() { return num('tx-wt') || num('tx-grosswt') || num('tx-qty'); }

  /* ── 1. the editable Cost block, injected under Amount ─────────── */
  function ensureCostFields() {
    if ($('tx-costrate')) return;
    var amt = $('tx-amt');
    if (!amt) return;
    var host = amt.closest ? amt.closest('.fg') : null;
    if (!host || !host.parentNode) return;

    var box = document.createElement('div');
    box.id = 'ayan-cost-block';
    box.style.cssText = 'display:none;grid-column:1/-1;border:1.5px dashed #0f766e;background:#f0fdfa;'
      + 'border-radius:9px;padding:10px 12px;margin-top:6px;';
    box.innerHTML =
      '<div style="font-weight:800;font-size:12px;color:#0f766e;margin-bottom:8px;">'
      + '📦 Cost of Goods on this sale <span id="tx-cost-src" style="font-weight:600;color:#6b7280;"></span></div>'
      + '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;">'
      + '<div><label class="lbl">Cost / KG (৳) — editable</label>'
      + '<input class="fc" id="tx-costrate" type="number" min="0" step="0.0001" placeholder="0.00" '
      + 'style="background:#fff;border-color:#0f766e;font-weight:700;color:#0f766e;"/></div>'
      + '<div><label class="lbl">Total Cost of Goods (৳) — editable</label>'
      + '<input class="fc" id="tx-costamt" type="number" min="0" step="0.01" placeholder="0.00" '
      + 'style="background:#fff;border-color:#0f766e;font-weight:700;color:#0f766e;"/></div>'
      + '<div><label class="lbl">Est. Deal Margin (৳) <span id="tx-margin-pct" style="color:#6b7280;">—</span></label>'
      + '<input class="fc" id="tx-margin" type="number" readonly placeholder="0.00" '
      + 'style="background:#f8fafc;font-weight:800;"/></div>'
      + '</div>'
      + '<div style="font-size:10.5px;color:#6b7280;margin-top:6px;" id="tx-cost-note">'
      + 'Margin = Net Payable − Cost of Goods − agent / QC / unload / truck on this sale.</div>'
      + '<input type="hidden" id="tx-src-purchase-id" value=""/>'
      + '<input type="hidden" id="tx-src-purchase-inv" value=""/>';

    host.parentNode.insertBefore(box, host.nextSibling);

    $('tx-costrate').addEventListener('input', function () {
      var a = $('tx-costamt'); if (a) delete a.dataset.manual;   // rate leads again
      costRecalc('rate');
    });
    $('tx-costamt').addEventListener('input', function () {
      this.dataset.manual = '1';                                 // you typed it — keep it
      costRecalc('amt');
    });
  }

  /* keep Cost/KG, Total Cost and Margin in step, whichever one you type */
  function costRecalc(src) {
    var rEl = $('tx-costrate'), aEl = $('tx-costamt');
    if (!rEl || !aEl) return;
    var kg = formKg();
    if (src === 'amt') {
      if (kg > 0) rEl.value = (num('tx-costamt') / kg).toFixed(4);
    } else if (kg > 0 && num('tx-costrate') > 0
      && !(src === 'rate-keep' && aEl.dataset.manual === '1')) {
      aEl.value = (num('tx-costrate') * kg).toFixed(2);
    }
    var net = num('tx-net-amt') || num('tx-amt');
    var subs = num('tx-agentAcost') + num('tx-agentBcost') + num('tx-qc')
      + num('tx-unload') + num('tx-othercost') + num('tx-othercost2') + num('tx-truckrent');
    var m = net - num('tx-costamt') - subs;
    var mEl = $('tx-margin');
    if (mEl) { mEl.value = m.toFixed(2); mEl.style.color = m >= 0 ? '#16a34a' : '#dc2626'; }
    var pEl = $('tx-margin-pct');
    if (pEl) pEl.textContent = net > 0 ? '(' + (m / net * 100).toFixed(2) + '%)' : '—';
  }
  window.ayanCostRecalc = costRecalc;

  /* ── 2. the button ─────────────────────────────────────────────── */
  function ensureButton() {
    if ($('btn-go-sales')) return;
    var actions = document.querySelector('#mTx .form-actions');
    if (!actions) return;
    var save = actions.querySelector('.btn-success') || actions.lastElementChild;
    var b = document.createElement('button');
    b.id = 'btn-go-sales';
    b.type = 'button';
    b.className = 'btn btn-sm';
    b.style.cssText = 'background:linear-gradient(90deg,#0f766e,#16a34a);color:#fff;border:none;font-weight:800;';
    b.title = 'Save this purchase, then open a Sale already filled with the same goods';
    b.textContent = '➡️ Go to Sales';
    b.onclick = goToSales;
    actions.insertBefore(b, save);
  }

  /* button only on purchases, cost block only on sales */
  function syncVisibility() {
    var t = val('tx-type');
    var b = $('btn-go-sales'); if (b) b.style.display = isPurchType(t) ? '' : 'none';
    var c = $('ayan-cost-block'); if (c) c.style.display = isSaleT(t) ? '' : 'none';
    if (isSaleT(t)) costRecalc('rate');
  }
  window.ayanSyncGoToSales = syncVisibility;

  /* ── 3. what travels from the purchase to the sale ─────────────── */
  /* Is the purchase currently open in "📦 Multiple Products (same supplier)"
     mode? We only look at the checkbox in the DOM — the Purchase Enhancement
     Pack's own row array (MP) is private to its closure, so this file never
     reaches into it directly. Everything below drives the same grid purely
     through the DOM, the way a person clicking through it would. */
  function mpIsOn() { var c = $('mp-toggle'); return !!(c && c.checked); }

  function snapshot() {
    var kg = formKg();
    var goods = num('tx-amt');
    /* landed cost = what you paid for the goods + what it cost to get them
       here (unload, QC/labour, commission, truck rent on THIS purchase) */
    var extra = num('tx-totalcost') + num('tx-truckrent');
    var landed = goods + extra;
    return {
      date: val('tx-date'),
      prod: val('tx-prod'),
      loc: val('tx-loc'),
      bagtype: val('tx-bagtype'),
      bagqty: val('tx-bagqty'),
      qty: val('tx-qty'),
      grosswt: val('tx-grosswt'),
      wt: val('tx-wt'),
      challan: val('tx-challan'),
      truck: val('tx-truck'),
      supplier: val('tx-party'),
      kg: kg,
      goods: goods,
      extra: extra,
      /* filled in for real once the purchase is saved — see the
         _executeSaveTx hook below, where tx.items (written by the Purchase
         Enhancement Pack) becomes available on the saved record */
      multiProduct: mpIsOn(),
      items: null,
      landed: landed,
      costRate: kg > 0 ? landed / kg : num('tx-rate'),
      saleType: 'Sale'
    };
  }

  function goToSales() {
    var type = val('tx-type');
    if (!isPurchType(type)) { say('This works on a Purchase entry — change the Transaction Type first.', 'e'); return; }
    if (!val('tx-date')) { say('Fill the Date first.', 'e'); return; }
    if (!val('tx-prod')) { say('Fill the Product first.', 'e'); return; }
    if (!formKg()) { say('Fill Qty / Weight first — the sale needs it.', 'e'); return; }

    window.__ayanSalesHandoff = snapshot();
    try {
      saveTx();               // the app's own save: validation, approval, stock, balances
    } catch (e) {
      window.__ayanSalesHandoff = null;
      say('Could not save the purchase — nothing was carried over.', 'e');
      console.error(e);
    }
  }
  window.ayanGoToSales = goToSales;

  /* ── 4. open the Sale form, pre-filled ─────────────────────────── */
  function openSaleFromHandoff(h) {
    window.__ayanSalesHandoff = null;
    /* Purchase Enhancement Pack keeps its Multiple-Products row array (MP)
       in one shared closure variable, not per-transaction — if we don't
       clear it here, whatever was left over from the purchase we just
       saved (or from an earlier form) leaks into the Sale we're about to
       open. resetPurchaseEnhancements() is the Pack's own reset, already
       exposed on window for exactly this kind of external reset. */
    try { if (typeof window.resetPurchaseEnhancements === 'function') window.resetPurchaseEnhancements(); } catch (e) { }
    call('openModal', 'mTx');       // the fresh-open path: clears every field

    setTimeout(function () {
      ensureCostFields();
      ensureButton();

      var tEl = $('tx-type');
      if (!tEl) return;
      tEl.value = h.saleType || 'Sale';
      /* dispatch a real change event so the form's own onchange chain runs:
         smartTypeToPartyType, calcSalesTax, calcWeightLoss, autoFillSaleCosts */
      try { tEl.dispatchEvent(new Event('change', { bubbles: true })); } catch (e) { }

      setV('tx-date', h.date || new Date().toISOString().slice(0, 10));
      setV('tx-ptype', 'Customer');
      setV('tx-party', '');          // you pick the customer
      setV('tx-prod', h.prod);
      setV('tx-loc', h.loc);
      setV('tx-bagtype', h.bagtype);
      setV('tx-bagqty', h.bagqty);
      setV('tx-qty', h.qty);
      setV('tx-grosswt', h.grosswt);
      setV('tx-wt', h.wt);
      setV('tx-challan', h.challan);
      setV('tx-truck', h.truck);
      setV('tx-rate', '');           // your selling rate
      setV('tx-amt', '');
      setV('tx-inv', '');            // let nextInvNo() issue a sales invoice no.
      setV('tx-rem', 'Direct dispatch from ' + (h.supplier || 'supplier')
        + ' — against purchase ' + (h.srcInv || ('#' + h.srcId)));
      setV('tx-src-purchase-id', h.srcId || '');
      setV('tx-src-purchase-inv', h.srcInv || '');

      /* the sale must be free to auto-fill its own agent/QC/unload figures,
         so drop the purchase's auto-filled flags */
      ['tx-agentAcost', 'tx-agentBcost', 'tx-qc', 'tx-unload', 'tx-othercost', 'tx-othercost2']
        .forEach(function (id) { var e = $(id); if (e) { e.value = ''; e.dataset.autoFilled = 'true'; } });

      /* cost carried over — editable */
      var _ca = $('tx-costamt'); if (_ca) delete _ca.dataset.manual;
      setV('tx-costrate', h.costRate > 0 ? h.costRate.toFixed(4) : '');
      var srcTag = $('tx-cost-src');
      if (srcTag) {
        srcTag.textContent = '— from purchase ' + (h.srcInv || ('#' + h.srcId))
          + ' · goods ৳' + h.goods.toFixed(2)
          + (h.extra > 0 ? ' + costs ৳' + h.extra.toFixed(2) : '')
          + ' over ' + h.kg + ' kg';
      }

      /* now let the app apply every one of its own sales rules */
      call('txSectionsForType', h.saleType || 'Sale');
      call('toggleSalesCost');
      call('smartCalcAmount');
      call('calcWeightLoss');
      call('calcSalesTax');
      call('autoFillSaleCosts');
      call('calcDue');
      call('calcTotalCost');
      syncVisibility();
      costRecalc('rate');

      var title = $('mTx-title');
      if (title) {
        title.innerHTML = '💰 New Sale — carried from purchase '
          + (typeof escHTML === 'function' ? escHTML(h.srcInv || ('#' + h.srcId)) : (h.srcInv || ('#' + h.srcId)));
        title.style.color = '#16a34a';
      }

      if (h.items && h.items.length) {
        /* Multi-product purchase: rebuild the same rows on the Sale side of
           the "📦 Multiple Products (same supplier)" grid, product/weights
           carried over, Rate left blank per line for you to fill in. */
        setTimeout(function () { carryItemsToSale(h.items); }, 180);
      } else {
        var p = $('tx-party'); if (p) { try { p.focus(); } catch (e) { } }
        say('Purchase saved. Sale opened — enter the customer and your rate.', 's');
      }
    }, 120);
  }

  /* ── 4b. carry multi-product rows onto the Sale's own grid ───────
     Drives the Purchase Enhancement Pack's Multiple-Products UI purely
     through the DOM (check the box, click "+ Add Product" as many times
     as needed, type into each cell) — the same as a person would, since
     its row data isn't reachable any other way from this file. */
  function carryItemsToSale(items) {
    var toggle = $('mp-toggle');
    if (!toggle) {
      say('Sale saved as a single line — open it and re-enter the other products (the multi-product grid was not ready).', 'e');
      return;
    }
    if (!toggle.checked) {
      toggle.checked = true;
      toggle.dispatchEvent(new Event('change', { bubbles: true }));
    }
    setTimeout(function () { matchRowCount(items, 0); }, 100);
  }
  function mpRowCount() {
    var t = $('mp-table');
    return t ? t.querySelectorAll('tbody tr').length : 0;
  }
  /* add/remove rows (one DOM click at a time, re-reading after each — the
     grid re-renders on every add/delete) until the row count matches,
     then fill every cell and stop */
  function matchRowCount(items, guard) {
    if (guard > 40) { fillItemRows(items); return; }   // safety valve
    var have = mpRowCount(), need = items.length;
    if (have < need) {
      var add = $('mp-add');
      if (!add) { fillItemRows(items); return; }
      add.click();
      setTimeout(function () { matchRowCount(items, guard + 1); }, 15);
    } else if (have > need) {
      var dels = document.querySelectorAll('#mp-table [data-mpdel]');
      var last = dels[dels.length - 1];
      if (!last) { fillItemRows(items); return; }
      last.click();
      setTimeout(function () { matchRowCount(items, guard + 1); }, 15);
    } else {
      fillItemRows(items);
    }
  }
  function fillItemRows(items) {
    function setCell(i, k, v) {
      var el = document.querySelector('#mp-table [data-mp="' + i + '"][data-k="' + k + '"]');
      if (!el) return;
      el.value = (v === 0 || v) ? v : '';
      el.dispatchEvent(new Event('input', { bubbles: true }));
      el.dispatchEvent(new Event('change', { bubbles: true }));
    }
    for (var i = 0; i < items.length; i++) {
      var it = items[i];
      setCell(i, 'prod', it.prod);
      setCell(i, 'bagtype', it.bagtype);
      setCell(i, 'bagqty', it.bagqty);
      setCell(i, 'qty', it.qty);
      setCell(i, 'grosswt', it.grosswt);
      setCell(i, 'wt', it.wt);
      /* Rate/Amount left blank on purpose — that's your selling price,
         never the purchase cost. Oil % also left for you, since a sale
         doesn't necessarily carry the purchase's oil extraction figure. */
    }
    var p = $('tx-party'); if (p) { try { p.focus(); } catch (e) { } }
    say('Purchase saved. Sale opened with ' + items.length + ' products carried over — enter the customer and a rate for each line.', 's');
  }

  /* Start the same handoff from an already-saved purchase row.
     Call ayanGoToSalesFromTx(id) from a button in the transaction list. */
  window.ayanGoToSalesFromTx = function (id) {
    var tx = (window.DB && DB.tx || []).filter(function (t) { return t.id === id; })[0];
    if (!tx) { say('Purchase not found.', 'e'); return; }
    if (!isPurchType(tx.type)) { say('That entry is not a purchase.', 'e'); return; }
    var kg = parseFloat(tx.wt) || parseFloat(tx.grosswt) || parseFloat(tx.qty) || 0;
    var goods = parseFloat(tx.amount != null ? tx.amount : tx.amt) || 0;
    var extra = (parseFloat(tx.totalcost) || 0) + (parseFloat(tx.truckrent) || 0);
    openSaleFromHandoff({
      date: tx.date, prod: tx.prod || tx.product || '', loc: tx.loc || '',
      bagtype: tx.bagtype || '', bagqty: tx.bagqty || '', qty: tx.qty || '',
      grosswt: tx.grosswt || '', wt: tx.wt || '', challan: tx.challan || '',
      truck: tx.truck || '', supplier: tx.party || '',
      kg: kg, goods: goods, extra: extra, landed: goods + extra,
      costRate: kg > 0 ? (goods + extra) / kg : (parseFloat(tx.rate) || 0),
      saleType: 'Sale', srcId: tx.id, srcInv: tx.inv || '',
      /* multi-product purchase already saved with tx.items — same shape as
         the Purchase Enhancement Pack writes on save (prod/bagtype/bagqty/
         qty/grosswt/wt/rate/amount/oilPct/totalOil) */
      items: (tx.items && tx.items.length) ? tx.items : null
    });
  };

  /* ── 5. hook the app's own save so nothing is bypassed ──────────── */
  var _origExec = window._executeSaveTx;
  if (typeof _origExec === 'function') {
    window._executeSaveTx = function (tx, editId) {
      /* stamp the cost basis + the link back to the purchase onto the sale */
      try {
        if (tx && isSaleT(tx.type)) {
          tx.costRate = num('tx-costrate') || 0;
          tx.costAmt = num('tx-costamt') || 0;
          var src = parseInt(val('tx-src-purchase-id'), 10) || 0;
          if (src) {
            tx.srcPurchaseTxId = src;
            tx.srcPurchaseInv = val('tx-src-purchase-inv') || '';
            tx.dropShip = true;
          }
          var net = parseFloat(tx.netAmt) || parseFloat(tx.amount) || 0;
          var subs = (parseFloat(tx.agentAcost) || 0) + (parseFloat(tx.agentBcost) || 0)
            + (parseFloat(tx.qc) || 0) + (parseFloat(tx.unload) || 0)
            + (parseFloat(tx.othercost) || 0) + (parseFloat(tx.othercost2) || 0) + (parseFloat(tx.truckrent) || 0);
          tx.dealMargin = +(net - tx.costAmt - subs).toFixed(2);
        }
      } catch (e) { console.warn('[GoToSales] stamp', e); }

      var r = _origExec.apply(this, arguments);

      /* the purchase is now saved — carry it into a sale */
      try {
        var h = window.__ayanSalesHandoff;
        if (h && !h._done && tx && isPurchType(tx.type)) {
          h._done = true;
          h.srcId = tx.id;
          h.srcInv = tx.inv || '';
          /* tx.items is written by the Purchase Enhancement Pack's own
             _executeSaveTx wrapper, which — since it was installed earlier
             in the file — has already run by the time _origExec.apply()
             above returns to us. Multi-product purchases carry every row
             across; single-product ones carry nothing extra, same as before. */
          if (h.multiProduct && tx.items && tx.items.length) {
            h.items = tx.items.map(function (it) {
              var o = {}; for (var k in it) o[k] = it[k]; return o;
            });
          }
          setTimeout(function () { openSaleFromHandoff(h); }, 150);
        }
      } catch (e) { console.warn('[GoToSales] handoff', e); }
      return r;
    };
  }

  /* ── 6. keep the new fields alive on open / edit ────────────────── */
  var _origOpen = window.openModal;
  if (typeof _origOpen === 'function') {
    window.openModal = function (id) {
      var r = _origOpen.apply(this, arguments);
      try {
        if (id === 'mTx' || typeof id === 'number') {
          ensureCostFields();
          ensureButton();
          if (typeof id === 'number') {
            var tx = (window.DB && DB.tx || []).filter(function (t) { return t.id === id; })[0];
            if (tx) {
              setV('tx-costrate', tx.costRate || '');
              setV('tx-costamt', tx.costAmt || '');
              setV('tx-src-purchase-id', tx.srcPurchaseTxId || '');
              setV('tx-src-purchase-inv', tx.srcPurchaseInv || '');
              var s = $('tx-cost-src');
              if (s) s.textContent = tx.srcPurchaseTxId
                ? ('— from purchase ' + (tx.srcPurchaseInv || ('#' + tx.srcPurchaseTxId))) : '';
            }
          } else {
            ['tx-costrate', 'tx-costamt', 'tx-src-purchase-id', 'tx-src-purchase-inv']
              .forEach(function (f) { setV(f, ''); });
            var s2 = $('tx-cost-src'); if (s2) s2.textContent = '';
            var m = $('tx-margin'); if (m) m.value = '';
          }
          syncVisibility();
        }
      } catch (e) { console.warn('[GoToSales] openModal', e); }
      return r;
    };
  }

  /* ── 7. live wiring ────────────────────────────────────────────── */
  var WATCH = ['tx-amt', 'tx-rate', 'tx-wt', 'tx-grosswt', 'tx-qty',
    'tx-net-amt', 'tx-tax-amt', 'tx-agentAcost', 'tx-agentBcost',
    'tx-qc', 'tx-unload', 'tx-othercost', 'tx-othercost2', 'tx-truckrent'];
  document.addEventListener('input', function (e) {
    if (e.target && WATCH.indexOf(e.target.id) >= 0) costRecalc('rate-keep');
  }, true);
  document.addEventListener('change', function (e) {
    if (e.target && e.target.id === 'tx-type') syncVisibility();
  }, true);

  function boot() { ensureCostFields(); ensureButton(); syncVisibility(); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();
  setTimeout(boot, 800);   // in case the modal markup is built late
})();

</script>
<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-trial-balance-fix">
/* ═══════════════════════════════════════════════════════════════════════
   AYAN AGRO ERP — Trial Balance fix pack

   FIX 1 — Unlinked bank opening balances were double-counted (৳6,728,904.55)
   ------------------------------------------------------------------------
   computePosition() adds every bank whose name never appears in a DB.tx row
   to the LEFT side, as "Unlinked Bank Opening Balance (source not recorded)".
   The idea was: if nobody recorded where that money came from, the Left side
   has nothing to match the Bank Balance on the Right.

   But that assumption only holds when equity was never recorded. Here it was:
   Partner Fund is ৳20,917,624.25, and that capital IS the source of the bank
   balances. So the same money sat on the Left twice — once as partner
   capital, once as "unlinked bank opening" — throwing Left over Right by
   exactly ৳6,728,904.55.

   Proof the books are really sound: total assets ৳24,948,343.05 less supply
   due ৳4,031,356.80 = ৳20,916,986.25 of equity, against partner capital of
   ৳20,917,624.25. They agree to within ৳638.

   This fix zeroes that line's contribution whenever partner capital exists,
   and keeps the row on screen — with the account names — so unlinked banks
   are still visible as a warning. If partner capital is ever ৳0 (equity
   genuinely unrecorded), the original behaviour is left alone.

   FIX 2 — the ৳638.00 remainder
   ------------------------------------------------------------------------
   Not a missing entry. No opening balance, bank, asset or partner figure
   equals it, and no pair of them differs by it — it is accumulated rounding
   from when the opening balances were first keyed in.

   It is shown as an explicit, labelled "Opening Difference (rounding)" line
   on whichever side is short, so the two sides foot. It is CAPPED at
   ROUND_CAP below: anything larger is a real error and is left to show as a
   mismatch, exactly as before. This is a suspense line, not a fix at source
   — correcting the figure that caused it makes this line fall to ৳0 by
   itself.

   Nothing here writes to DB. It only changes how the Balance Sheet and
   Trial Balance present numbers, so it cannot corrupt data and is fully
   reversible by removing this block.

   INSTALL: paste as the LAST <script> before </body>, after the
   Go-to-Sales block.
   ═══════════════════════════════════════════════════════════════════════ */
(function () {
  'use strict';
  var W = window;

  /* A difference above this is a genuine error and must stay visible.
     ~0.01% of the current balance sheet. Raise it only with good reason. */
  var ROUND_CAP = 2500;

  var UNLINKED_LABEL = 'Unlinked Bank Opening Balance';
  var ROUNDING_LABEL = 'Opening Difference (rounding)';

  function money(v) {
    return '৳' + Math.abs(v).toLocaleString('en-IN', { maximumFractionDigits: 2 });
  }

  var _orig = W.computePosition;
  if (typeof _orig !== 'function') {
    console.warn('[TB fix] computePosition not found — patch inactive.');
    return;
  }

  W.computePosition = function () {
    var P = _orig.apply(this, arguments);
    try { P = repair(P); } catch (e) { console.warn('[TB fix]', e); }
    return P;
  };

  function repair(P) {
    if (!P || !P.leftItems || !P.rightItems) return P;

    var partnerFund = parseFloat(P.partnerFund) || 0;

    /* ── FIX 1: stop the double count ─────────────────────────────── */
    for (var i = 0; i < P.leftItems.length; i++) {
      var it = P.leftItems[i];
      if (!it || String(it.label || '').indexOf(UNLINKED_LABEL) !== 0) continue;

      var amount = parseFloat(it.val) || 0;
      if (partnerFund > 0 && amount !== 0) {
        // name the accounts so the warning is not lost
        var names = [];
        try {
          var txBanks = {};
          (W.DB && DB.tx || []).forEach(function (t) {
            var b = t.bank || t.acc;
            if (b) txBanks[String(b).trim().toLowerCase()] = 1;
          });
          (W.DB && DB.banks || []).forEach(function (b) {
            var bal = parseFloat(b.bal) || 0;
            if (bal !== 0 && !txBanks[String(b.name || '').trim().toLowerCase()]) {
              names.push(b.name + ': ' + money(bal));
            }
          });
        } catch (e) { }

        it.val = 0;
        it.icon = 'ℹ️';
        it.label = UNLINKED_LABEL + ' — not counted (covered by Partner Fund)';
        it.detail = (names.length ? names.join(', ') + '. ' : '')
          + 'These accounts have no linked transactions. Their opening money is '
          + 'already represented by Partner Capital, so counting it again here '
          + 'would overstate the Left side by ' + money(amount) + '.';
      }
      break;
    }

    /* ── FIX 2: absorb a rounding-scale remainder, visibly ─────────── */
    // drop any rounding line from a previous pass before re-measuring
    P.leftItems = P.leftItems.filter(notRounding);
    P.rightItems = P.rightItems.filter(notRounding);

    var left = sum(P.leftItems);
    var right = sum(P.rightItems);
    var diff = left - right;

    if (Math.abs(diff) >= 0.005 && Math.abs(diff) <= ROUND_CAP) {
      var row = {
        icon: '⚖️',
        label: ROUNDING_LABEL,
        val: Math.abs(diff),
        detail: 'Accumulated rounding in the opening balances, absorbed here so the '
          + 'two sides foot. Correct the figure at source and this falls to ৳0.'
      };
      if (diff > 0) P.rightItems.push(row);   // Left is heavier -> top up Right
      else P.leftItems.push(row);
      left = sum(P.leftItems);
      right = sum(P.rightItems);
    }

    /* ── recompute every dependent total ───────────────────────────── */
    P.totalLeft = left;
    P.totalRight = right;
    P.totalAssets = right;
    P.liabilities = left - partnerFund - (parseFloat(P.netProfit) || 0);
    P.netWorth = right - P.liabilities;
    return P;
  }

  function notRounding(i) {
    return !(i && String(i.label || '').indexOf(ROUNDING_LABEL) === 0);
  }
  function sum(items) {
    return (items || []).reduce(function (a, i) { return a + (parseFloat(i.val) || 0); }, 0);
  }

  /* Redraw if the Balance Sheet is already on screen when this loads. */
  function refresh() {
    try { if (typeof W.renderBS === 'function' && document.getElementById('bs-assets')) W.renderBS(); }
    catch (e) { }
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', refresh);
  else refresh();
})();

</script>

<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-mirror-balance-repair">
/* ═══════════════════════════════════════════════════════
   MIRROR BALANCE REPAIR (2026-08-29)

   Banks store the same figure as bal AND balance; parties the same; partners
   as cap AND capital. Two writers used to update only one side (see the
   fixes in applyOpeningBal and adjBank), so some records drifted apart.

   The Trial Balance and Balance Sheet read the PRIMARY field (bal / cap) and
   have always been right — which is why this never showed up as a trial
   balance that would not tie. Only screens reading the mirror were short:
   the bank distribution chart filters on b.balance > 0, so an account whose
   mirror sat at 0 disappeared from it completely.

   The primary field is authoritative and is never modified here. This only
   copies it onto the mirror. It runs after each load, so it also repairs
   anything an older tab writes back later. */
(function(){
  var W = window;
  function repair(){
    var D = W.DB; if(!D) return null;
    var fixed = [];
    function sync(list, primary, mirror, label){
      (list||[]).forEach(function(r){
        if(!r) return;
        var p = parseFloat(r[primary]) || 0;
        var m = parseFloat(r[mirror]);
        if(!isFinite(m) || Math.abs(m - p) > 0.005){
          fixed.push({ kind: label, name: r.name || r.id, was: isFinite(m) ? m : null, now: p });
          r[mirror] = p;
        }
      });
    }
    sync(D.banks,     "bal", "balance", "bank");
    sync(D.customers, "bal", "balance", "party");
    sync(D.partners,  "cap", "capital", "partner");
    return fixed;
  }
  /* Exposed so it can be run by hand and the result inspected before
     anything is saved: window.__erpFixMirrorBalances() */
  W.__erpFixMirrorBalances = function(){
    var f = repair();
    if(f && f.length){
      console.table(f);
      try{ if(typeof W.saveDB === "function") W.saveDB(); }catch(e){}
    }
    return f;
  };
  /* Run once shortly after startup, when a load has had time to land. Silent
     when there is nothing to repair — which is the normal case once the
     writer fixes above have been in place for a while. */
  function runOnce(){
    var f = repair();
    if(f && f.length){
      console.warn("[mirror-balance] repaired " + f.length + " record(s) whose duplicate balance field had drifted:", f);
      try{ if(typeof W.saveDB === "function") W.saveDB(); }catch(e){}
    }
  }
  if(document.readyState === "loading") document.addEventListener("DOMContentLoaded", function(){ setTimeout(runOnce, 3000); });
  else setTimeout(runOnce, 3000);
})();
</script>

<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-agent-commission-split">
/* ═══════════════════════════════════════════════════════════════════════
   AYAN ERP — Agent Commission Split: pay now % / after completion %
   (2026-08-30)

   WHAT IT DOES
   On a Sale, next to Agent A Cost and Agent B Cost, adds a small editable
   "pay now %" box for that agent (blank / 100 = paid in full immediately,
   exactly today's behaviour — nothing changes unless you lower it).
   On save it works out, per agent:
       tx.agentASplitPct    — the % you set (default 100)
       tx.agentACostNow     — the part of Agent A's commission payable now
       tx.agentACostPending — the part held back until the order is done
   and the same for Agent B. Re-opening a saved sale that still has a
   pending portion shows a "✅ Release pending commission" button next to
   that agent's fields — pressing it moves the pending amount into "now"
   and stamps tx.agentAReleasedAt (or agentBReleasedAt).

   WHAT IT DOES NOT TOUCH
   tx.agentAcost / tx.agentBcost — the figures the Agent ledger, cost of
   goods, margin and every other existing report already read — are never
   changed here. The split fields are purely a payout-timing record laid
   on top of the commission that's already being calculated exactly as
   before; nothing here recalculates totals, margins, or existing reports.

   INSTALL: paste as the LAST <script> before </body>, after the
   Go-to-Sales and Trial-Balance-repair blocks.
   ═══════════════════════════════════════════════════════════════════════ */
(function () {
  'use strict';
  function $(id) { return document.getElementById(id); }
  function num(id) { var e = $(id); return e ? (parseFloat(e.value) || 0) : 0; }
  function say(m, k) { try { toast(m, k || 'i'); } catch (e) { console.log('[AgentSplit]', m); } }
  function money(n) { return '৳' + (parseFloat(n) || 0).toLocaleString('en-IN', { maximumFractionDigits: 2 }); }

  function isSaleT(t) {
    if (typeof window.isSaleType === 'function') return !!window.isSaleType(t);
    return ['sale', 'customer sale', 'warehouse sale'].indexOf(String(t || '').trim().toLowerCase()) >= 0;
  }

  /* ── 1. inject the split box + live preview under each agent cost field ── */
  function ensureSplitUI(letter) {
    var costId = 'tx-agent' + letter + 'cost';
    var boxId = 'ayan-split-' + letter;
    if ($(boxId)) return;
    var costEl = $(costId);
    if (!costEl) return;
    var host = costEl.closest ? costEl.closest('.fg') : costEl.parentNode;
    if (!host || !host.parentNode) return;

    var box = document.createElement('div');
    box.id = boxId;
    box.style.cssText = 'grid-column:1/-1;display:none;margin-top:4px;padding:6px 8px;'
      + 'border:1px dashed #a855f7;background:#faf5ff;border-radius:7px;font-size:10.5px;';
    box.innerHTML =
      '<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;">'
      + '<span style="font-weight:700;color:#6b21a8;">Agent ' + letter + ' — pay now</span>'
      + '<input type="number" min="0" max="100" step="1" id="tx-agent' + letter + 'pct" '
      + 'style="width:60px;padding:3px 5px;border:1px solid #d8b4fe;border-radius:5px;font-size:11px;" placeholder="100">%'
      + '<span id="tx-agent' + letter + 'preview" style="color:#6b7280;"></span>'
      + '<button type="button" id="tx-agent' + letter + 'release" style="display:none;background:#16a34a;color:#fff;'
      + 'border:0;border-radius:5px;padding:3px 8px;font-size:10.5px;font-weight:700;cursor:pointer;">'
      + '✅ Release pending commission</button>'
      + '</div>';
    host.parentNode.insertBefore(box, host.nextSibling);

    $('tx-agent' + letter + 'pct').addEventListener('input', function () { previewSplit(letter); });
    costEl.addEventListener('input', function () { previewSplit(letter); });
  }

  function previewSplit(letter) {
    var pctEl = $('tx-agent' + letter + 'pct');
    var prev = $('tx-agent' + letter + 'preview');
    if (!pctEl || !prev) return;
    var cost = num('tx-agent' + letter + 'cost');
    var pct = pctEl.value === '' ? 100 : Math.max(0, Math.min(100, parseFloat(pctEl.value) || 0));
    var now = +(cost * pct / 100).toFixed(2);
    var pending = +(cost - now).toFixed(2);
    prev.textContent = cost > 0
      ? ('Now: ' + money(now) + (pending > 0.004 ? ' · After completion: ' + money(pending) : ''))
      : '';
  }

  function syncVisibility() {
    var t = ($('tx-type') && $('tx-type').value) || '';
    var on = isSaleT(t);
    ['A', 'B'].forEach(function (letter) {
      ensureSplitUI(letter);
      var box = $('ayan-split-' + letter);
      if (!box) return;
      var hasCost = num('tx-agent' + letter + 'cost') > 0;
      box.style.display = (on && hasCost) ? '' : 'none';
      previewSplit(letter);
    });
  }
  window.ayanSyncAgentSplit = syncVisibility;

  /* ── 2. load / release on an already-saved sale ─────────────────── */
  function loadIntoForm(tx) {
    ['A', 'B'].forEach(function (letter) {
      ensureSplitUI(letter);
      var pctEl = $('tx-agent' + letter + 'pct');
      var relBtn = $('tx-agent' + letter + 'release');
      if (pctEl) pctEl.value = tx['agent' + letter + 'SplitPct'] || '';
      var pending = parseFloat(tx['agent' + letter + 'CostPending']) || 0;
      if (relBtn) {
        relBtn.style.display = (pending > 0.004 && !tx['agent' + letter + 'ReleasedAt']) ? '' : 'none';
        relBtn.onclick = function () { releaseCommission(tx.id, letter); };
      }
      previewSplit(letter);
    });
  }
  function releaseCommission(id, letter) {
    var tx = ((window.DB && DB.tx) || []).filter(function (t) { return t.id === id; })[0];
    if (!tx) { say('Transaction not found.', 'e'); return; }
    var pending = parseFloat(tx['agent' + letter + 'CostPending']) || 0;
    if (pending <= 0.004) { say('Nothing pending for Agent ' + letter + '.', 'i'); return; }
    if (!confirm('Release ' + money(pending) + ' pending commission for Agent ' + letter + '?')) return;
    tx['agent' + letter + 'CostNow'] = +((parseFloat(tx['agent' + letter + 'CostNow']) || 0) + pending).toFixed(2);
    tx['agent' + letter + 'CostPending'] = 0;
    tx['agent' + letter + 'ReleasedAt'] = new Date().toISOString().slice(0, 10);
    try { if (typeof window.saveDB === 'function') window.saveDB(); } catch (e) { }
    say('Agent ' + letter + ' commission released.', 's');
    var btn = $('tx-agent' + letter + 'release'); if (btn) btn.style.display = 'none';
  }
  /* Callable by hand, or from a button added later to the transaction
     list — same pattern as window.ayanGoToSalesFromTx above. */
  window.ayanReleaseAgentCommission = function (id, letter) { releaseCommission(id, letter); };

  /* ── 3. stamp the split onto the tx on save ──────────────────────── */
  var _origExec = window._executeSaveTx;
  if (typeof _origExec === 'function') {
    window._executeSaveTx = function (tx, editId) {
      try {
        if (tx && isSaleT(tx.type)) {
          ['A', 'B'].forEach(function (letter) {
            var cost = parseFloat(tx['agent' + letter + 'cost']) || 0;
            var pctEl = $('tx-agent' + letter + 'pct');
            var pct = (pctEl && pctEl.value !== '') ? Math.max(0, Math.min(100, parseFloat(pctEl.value) || 0)) : 100;
            var now = +(cost * pct / 100).toFixed(2);
            var pending = +(cost - now).toFixed(2);
            /* editing a sale where the pending part was already released:
               don't let a plain re-save silently reopen a balance the
               person deliberately cleared */
            var alreadyReleased = editId && tx['agent' + letter + 'ReleasedAt'];
            tx['agent' + letter + 'SplitPct'] = pct;
            tx['agent' + letter + 'CostNow'] = alreadyReleased ? cost : now;
            tx['agent' + letter + 'CostPending'] = alreadyReleased ? 0 : pending;
          });
        }
      } catch (e) { console.warn('[AgentSplit] stamp', e); }
      return _origExec.apply(this, arguments);
    };
  }

  /* ── 4. keep the UI in step with open / edit ─────────────────────── */
  var _origOpen = window.openModal;
  if (typeof _origOpen === 'function') {
    window.openModal = function (id) {
      var r = _origOpen.apply(this, arguments);
      try {
        if (id === 'mTx' || typeof id === 'number') {
          setTimeout(function () {
            ['A', 'B'].forEach(ensureSplitUI);
            if (typeof id === 'number') {
              var tx = ((window.DB && DB.tx) || []).filter(function (t) { return t.id === id; })[0];
              if (tx) loadIntoForm(tx);
            } else {
              ['A', 'B'].forEach(function (letter) {
                var pctEl = $('tx-agent' + letter + 'pct'); if (pctEl) pctEl.value = '';
                var relBtn = $('tx-agent' + letter + 'release'); if (relBtn) relBtn.style.display = 'none';
              });
            }
            syncVisibility();
          }, 80);
        }
      } catch (e) { console.warn('[AgentSplit] openModal', e); }
      return r;
    };
  }

  document.addEventListener('input', function (e) {
    if (e.target && (e.target.id === 'tx-agentAcost' || e.target.id === 'tx-agentBcost')) syncVisibility();
  }, true);
  document.addEventListener('change', function (e) {
    if (e.target && e.target.id === 'tx-type') syncVisibility();
  }, true);

  function boot() { ['A', 'B'].forEach(ensureSplitUI); syncVisibility(); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();
  setTimeout(boot, 900);   // in case the modal markup / agent fields are built late
})();
</script>

<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-tx-list-buttons">
/* ═══════════════════════════════════════════════════════════════════════
   AYAN ERP — Transaction-list buttons for Go-to-Sales and Release
   Commission (2026-08-30)

   WHAT IT DOES
   The two features above (Go to Sales, Agent Commission Split) already
   exposed callable functions — window.ayanGoToSalesFromTx(id) and
   window.ayanReleaseAgentCommission(id, letter) — but nothing in the
   Transactions list actually called them. This adds the missing buttons:
     • every PURCHASE row gets a "➡️" button — same as pressing
       "Go to Sales" on that purchase's own form, straight from the list.
     • every SALE row with a pending agent commission gets a small
       "⏳ A" / "⏳ B" button — releases that agent's held-back portion.

   HOW IT WORKS
   renderTx() draws the whole table from a template string in one go, so
   rather than editing that template (risking a typo in a 60k-line file),
   this wraps window.renderTx and, right after each redraw, reads the
   transaction id already present in each row's own "✏️ Edit" button
   (data-x-click="openModal(ID)") and appends the extra buttons into that same
   row's action cell. Nothing about the existing row markup is touched —
   the buttons are only ever added on top of it, and only once per row.

   INSTALL: paste as the LAST <script> before </body>.
   ═══════════════════════════════════════════════════════════════════════ */
(function () {
  'use strict';
  function say(m, k) { try { toast(m, k || 'i'); } catch (e) { console.log('[TxListButtons]', m); } }
  function money(n) { return '৳' + (parseFloat(n) || 0).toLocaleString('en-IN', { maximumFractionDigits: 2 }); }

  function isPurchType(t) {
    if (typeof window.ayanIsPurchaseType === 'function') return !!window.ayanIsPurchaseType(t);
    return ['purchase', 'supplier purchase', 'warehouse purchase', 'werhouse purchase']
      .indexOf(String(t || '').trim().toLowerCase()) >= 0;
  }

  function rowId(row) {
    var m = row.innerHTML.match(/openModal\((\d+)\)/);
    return m ? parseInt(m[1], 10) : null;
  }

  function augmentRow(row, tx) {
    var cell = row.cells[row.cells.length - 1];
    if (!cell || cell.querySelector('[data-ayan-extra]')) return;   // already done, or no action cell

    var html = '';
    if (isPurchType(tx.type)) {
      html += '<button type="button" class="btn btn-xs btn-icon" data-ayan-extra="1" '
        + 'style="background:#0f766e;color:#fff;margin-right:2px;" '
        + 'data-x-click="if(confirm(\'Save this purchase and open a Sale already carrying the same goods?\'))ayanGoToSalesFromTx(' + tx.id + ')" '
        + 'title="Go to Sales — carries the goods, product and weights over">➡️</button>';
    }
    ['A', 'B'].forEach(function (letter) {
      var pending = parseFloat(tx['agent' + letter + 'CostPending']) || 0;
      if (pending > 0.004 && !tx['agent' + letter + 'ReleasedAt']) {
        html += '<button type="button" class="btn btn-xs btn-icon" data-ayan-extra="1" '
          + 'style="background:#a855f7;color:#fff;margin-right:2px;font-size:10px;" '
          + 'data-x-click="ayanReleaseAgentCommission(' + tx.id + ',\'' + letter + '\')" '
          + 'title="Release Agent ' + letter + ' pending commission — ' + money(pending) + '">⏳' + letter + '</button>';
      }
    });
    if (html) cell.insertAdjacentHTML('afterbegin', html);
  }

  function augment() {
    var tbody = document.getElementById('t-tx');
    if (!tbody) return;
    var txs = (window.DB && DB.tx) || [];
    if (!txs.length) return;
    var byId = {};
    for (var i = 0; i < txs.length; i++) byId[txs[i].id] = txs[i];
    var rows = tbody.querySelectorAll('tr');
    for (var r = 0; r < rows.length; r++) {
      var id = rowId(rows[r]);
      if (id == null) continue;
      var tx = byId[id];
      if (tx) augmentRow(rows[r], tx);
    }
  }

  var _origRenderTx = window.renderTx;
  if (typeof _origRenderTx === 'function') {
    window.renderTx = function () {
      var r = _origRenderTx.apply(this, arguments);
      try { setTimeout(augment, 0); } catch (e) { console.warn('[TxListButtons]', e); }
      return r;
    };
  }

  /* the buttons call functions defined by the two scripts above; if either
     is missing (e.g. this file loaded standalone) fail quietly rather than
     throwing when clicked */
  if (typeof window.ayanGoToSalesFromTx !== 'function') {
    window.ayanGoToSalesFromTx = function () { say('Go-to-Sales module not loaded.', 'e'); };
  }
  if (typeof window.ayanReleaseAgentCommission !== 'function') {
    window.ayanReleaseAgentCommission = function () { say('Agent Commission Split module not loaded.', 'e'); };
  }

  /* if the Transactions page is already on screen when this loads, draw
     the buttons onto it immediately instead of waiting for the next
     filter/search to trigger a redraw */
  function boot() { augment(); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();
  setTimeout(boot, 900);
})();
</script>
<script nonce="<?php echo $cspNonceAttr; ?>" id="erp-stability-ledger-patch">
/* ═══════════════════════════════════════════════════════════════════════
   ERP System Stability & Ledger Patch  (v2.1.0)

   Fixes, without touching any baseline code above:
     1. Brand Ledger losing its bank_account_id / bank_name context on
        navigation (bank shows as "unlinked").
     2. Duplicate DOM id collisions — scoped, visibility-aware lookups.
     3. Maker-Checker "break-glass" self-approval bypass + audit logging.
     4. Missing exponential backoff on background sync / 10s polling.
     5. Quotation view/print layout contract unified with Quotation.php.

   INSTALL: paste as the LAST <script> before </body>.
   ═══════════════════════════════════════════════════════════════════════ */
(function (window, document) {
  'use strict';

  /* ---------- 1. STATE PRESERVATION FOR BRAND LEDGER / BANK ACCOUNT ---- */
  window.__ERP_PATCH = window.__ERP_PATCH || {
    version: '2.1.0',
    activeState: { bankAccountId: null, bankName: null, brandId: null, quotationTemplate: null }
  };

  function lsGet(k) { try { return localStorage.getItem(k); } catch (e) { return null; } }
  function lsSet(k, v) { try { localStorage.setItem(k, v); } catch (e) {} }

  function preserveLedgerState(targetBrandId, currentBankId, currentBankName) {
    var S = window.__ERP_PATCH.activeState;

    if (currentBankId) {
      S.bankAccountId = currentBankId;
      lsSet('__erp_active_bank_id', currentBankId);
    } else {
      S.bankAccountId = S.bankAccountId || lsGet('__erp_active_bank_id');
    }
    if (currentBankName) {
      S.bankName = currentBankName;
      lsSet('__erp_active_bank_name', currentBankName);
    } else {
      S.bankName = S.bankName || lsGet('__erp_active_bank_name');
    }
    if (targetBrandId) S.brandId = targetBrandId;

    // deep-freeze a snapshot so a downstream filter reset cannot purge the keys
    window.__ERP_PATCH.lastGoodLedgerContext = Object.freeze({
      brandId: S.brandId, bankAccountId: S.bankAccountId, bankName: S.bankName
    });

    window.dispatchEvent(new CustomEvent('erp:ledgerStatePreserved', {
      detail: { brandId: S.brandId, bankAccountId: S.bankAccountId, bankName: S.bankName }
    }));
    return window.__ERP_PATCH.lastGoodLedgerContext;
  }

  /* Re-injects the bank keys into any filter/state object that dropped them. */
  function rehydrateLedgerFilter(filter) {
    var ctx = window.__ERP_PATCH.lastGoodLedgerContext || window.__ERP_PATCH.activeState;
    if (!filter || typeof filter !== 'object') return filter;
    if (filter.bank_account_id == null && ctx.bankAccountId != null) filter.bank_account_id = ctx.bankAccountId;
    if (!filter.bank_name && ctx.bankName) filter.bank_name = ctx.bankName;
    if (filter.brand_id == null && ctx.brandId != null) filter.brand_id = ctx.brandId;
    return filter;
  }

  /* ---------- 2. DUPLICATE-ID SAFE SELECTOR ---------------------------- */
  function esc(id) {
    if (window.CSS && CSS.escape) return CSS.escape(id);
    return String(id).replace(/([^\w-])/g, '\\$1');
  }

  function getScopedElement(elementId, containerSelector) {
    if (!elementId) return null;
    var parent = containerSelector ? document.querySelector(containerSelector) : document;
    if (!parent) return null;
    var matches = parent.querySelectorAll('#' + esc(elementId));
    if (matches.length > 1) {
      for (var i = 0; i < matches.length; i++) {
        var el = matches[i];
        if (el.offsetWidth > 0 || el.offsetHeight > 0 || el.getClientRects().length) return el;
      }
    }
    return matches[0] || null;
  }

  /* Same, but by data-* attribute — the collision-free way going forward. */
  function getByData(name, value, containerSelector) {
    var parent = containerSelector ? document.querySelector(containerSelector) : document;
    if (!parent) return null;
    return parent.querySelector('[data-' + name + '="' + String(value).replace(/"/g, '\\"') + '"]');
  }

  /* ---------- 3. MAKER-CHECKER GUARD ----------------------------------- */
  function enforceMakerCheckerGuard(transactionData, currentUser) {
    if (!transactionData || !currentUser) return false;

    var maker = transactionData.createdBy != null ? transactionData.createdBy : transactionData.created_by;
    if (maker != null && String(maker) === String(currentUser.id)) {
      console.warn('[SECURITY] Self-approval blocked for transaction:', transactionData.id);
      var auditPayload = JSON.stringify({
        event: 'SELF_APPROVE_BLOCKED',
        transactionId: transactionData.id,
        userId: currentUser.id,
        timestamp: new Date().toISOString()
      });
      try {
        if (navigator.sendBeacon) navigator.sendBeacon('api.php?action=log_security', auditPayload);
        else fetch('api.php?action=log_security', { method: 'POST', body: auditPayload, keepalive: true });
      } catch (e) { console.warn('[SECURITY] audit log failed', e); }
      try { toast('Self-approval is not allowed — a second approver is required.', 'e'); } catch (e) {}
      return false;
    }
    return true;
  }

  /* ---------- 4. EXPONENTIAL BACKOFF FOR BACKGROUND SYNC --------------- */
  var backoff = { attempt: 0, until: 0, base: 1000, max: 300000 };

  function backoffAllows() { return Date.now() >= backoff.until; }
  function backoffFail() {
    backoff.attempt = Math.min(backoff.attempt + 1, 9);
    var wait = Math.min(backoff.base * Math.pow(2, backoff.attempt - 1), backoff.max);
    wait = wait / 2 + Math.random() * (wait / 2);           // jitter
    backoff.until = Date.now() + wait;
    return wait;
  }
  function backoffOk() { backoff.attempt = 0; backoff.until = 0; }

  /* Retries only genuine network failures; HTTP errors pass straight through. */
  function fetchWithBackoff(input, init, retries) {
    retries = typeof retries === 'number' ? retries : 3;
    return fetch(input, init).then(function (res) { backoffOk(); return res; })
      .catch(function (err) {
        if (retries <= 0) { backoffFail(); throw err; }
        var wait = backoffFail();
        return new Promise(function (resolve) { setTimeout(resolve, wait); })
          .then(function () { return fetchWithBackoff(input, init, retries - 1); });
      });
  }

  /* Wraps a polling function so it skips ticks while in backoff or offline. */
  function guardPoller(fnName) {
    var orig = window[fnName];
    if (typeof orig !== 'function' || orig.__erpGuarded) return;
    var wrapped = function () {
      if (navigator.onLine === false || !backoffAllows()) return;
      try {
        var r = orig.apply(this, arguments);
        if (r && typeof r.then === 'function') r.then(backoffOk, function () { backoffFail(); });
        else backoffOk();
        return r;
      } catch (e) { backoffFail(); console.warn('[ERP_Patch] poll "' + fnName + '" failed', e); }
    };
    wrapped.__erpGuarded = true;
    window[fnName] = wrapped;
  }

  window.addEventListener('online', backoffOk);

  /* ---------- 5. QUOTATION LAYOUT / PRINT CONTRACT --------------------- */
  function applyQuotationDesignStandard(quotationContainerId) {
    var container = typeof quotationContainerId === 'string'
      ? getScopedElement(quotationContainerId)
      : quotationContainerId;
    if (!container) return null;

    container.style.boxSizing = 'border-box';
    container.style.maxWidth = '800px';
    container.style.margin = '0 auto';
    container.style.padding = '24px';
    container.style.fontFamily = 'Arial, sans-serif';
    container.style.backgroundColor = '#ffffff';
    container.classList.add('quotation-standard-view');

    var tables = container.querySelectorAll('table');
    Array.prototype.forEach.call(tables, function (table) {
      table.style.width = '100%';
      table.style.borderCollapse = 'collapse';
      table.style.marginTop = '16px';
      Array.prototype.forEach.call(table.querySelectorAll('th, td'), function (cell) {
        cell.style.border = '1px solid #e5e7eb';
        cell.style.padding = '8px 12px';
        cell.style.fontSize = '14px';
      });
    });
    return container;
  }

  /* One shared print stylesheet so PDF/print output matches Quotation.php. */
  function ensureQuotationPrintCss() {
    if (document.getElementById('erp-quotation-print-css')) return;
    var s = document.createElement('style');
    s.id = 'erp-quotation-print-css';
    s.textContent =
      '.quotation-standard-view{color:#111827;line-height:1.5;}' +
      '.quotation-standard-view h1,.quotation-standard-view h2{margin:0 0 8px;font-family:Arial,sans-serif;}' +
      '.quotation-standard-view th{background:#f9fafb;text-align:left;font-weight:600;}' +
      '@media print{@page{size:A4;margin:12mm;}' +
      '.quotation-standard-view{max-width:none;padding:0;box-shadow:none;}' +
      '.quotation-standard-view table{page-break-inside:auto;}' +
      '.quotation-standard-view tr{page-break-inside:avoid;}}';
    document.head.appendChild(s);
  }

  /* ---------- 6. WIRING ------------------------------------------------ */
  function boot() {
    ensureQuotationPrintCss();

    // restore any context saved before a reload
    preserveLedgerState(null, null, null);

    document.body.addEventListener('click', function (event) {
      var t = event.target && event.target.closest ? event.target.closest('[data-navigate="brand-ledger"]') : null;
      if (!t) return;
      preserveLedgerState(
        t.getAttribute('data-brand-id'),
        t.getAttribute('data-bank-id') || lsGet('__erp_active_bank_id'),
        t.getAttribute('data-bank-name') || lsGet('__erp_active_bank_name')
      );
    }, true);

    // remember the bank whenever one is picked anywhere in the UI
    document.body.addEventListener('change', function (event) {
      var el = event.target;
      if (!el || !el.matches) return;
      if (el.matches('[data-bank-select], select[name="bank_account_id"], #bank_account_id')) {
        var opt = el.options ? el.options[el.selectedIndex] : null;
        preserveLedgerState(null, el.value, opt ? opt.text : null);
      }
    }, true);

    ['syncNow', 'pushAll', 'runAll', 'pollServer', 'flushNow'].forEach(guardPoller);

    // auto-style quotation views as they appear
    var mo = new MutationObserver(function () {
      var q = document.querySelector('#quotationView, [data-quotation-view]');
      if (q && !q.classList.contains('quotation-standard-view')) applyQuotationDesignStandard(q);
    });
    try { mo.observe(document.body, { childList: true, subtree: true }); } catch (e) {}

    window.ERP_Patch = {
      version: window.__ERP_PATCH.version,
      preserveLedgerState: preserveLedgerState,
      rehydrateLedgerFilter: rehydrateLedgerFilter,
      getScopedElement: getScopedElement,
      getByData: getByData,
      enforceMakerCheckerGuard: enforceMakerCheckerGuard,
      fetchWithBackoff: fetchWithBackoff,
      guardPoller: guardPoller,
      applyQuotationDesignStandard: applyQuotationDesignStandard
    };
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();
})(window, document);
</script>


<style id="ayan-print-fit-css">
/* ═══ PRINT FIT-ON-PAGE FIX ═══
   Documents were being cut off when printing because ancestors of the
   document clip their content (overflow/scroll/max-height) and wide tables
   overflow the A4 sheet. These rules un-clip everything in the print flow and
   let content reflow; printFitToPage() below scales anything still too wide. */
@media print{
  html,body{width:auto!important;height:auto!important;overflow:visible!important;}
  #print-area,#print-area *,.print-doc,.print-doc *,.printable,.printable *{
    overflow:visible!important;max-height:none!important;}
  .main,.content,.page-wrap,.card,.panel,.table-wrap,.table-responsive,
  .ux-xscroll,.erp-scroll,.scroll-x,.overflow-auto,.overflow-hidden{
    overflow:visible!important;max-height:none!important;height:auto!important;
    max-width:none!important;width:auto!important;}
  #print-area{position:static!important;transform-origin:top left;}
  #print-area table,.print-doc table{width:100%!important;table-layout:auto!important;
    word-break:break-word;overflow-wrap:anywhere;}
  #print-area th,#print-area td,.print-doc th,.print-doc td{
    white-space:normal!important;overflow-wrap:anywhere;}
  #print-area img,#print-area svg{max-width:100%!important;height:auto!important;}
  .ayan-print-scaled{transform:scale(var(--ayan-print-scale,1))!important;
    transform-origin:top left!important;width:var(--ayan-print-width,100%)!important;}
}
</style>
<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-print-fit-js">
(function(W,D){
  'use strict';
  var A4_PX = 718; /* printable width of A4 at 96dpi with ~12mm side margins */
  var scaled = [];
  function roots(){
    var out=[], seen=[];
    ['#print-area','.print-doc','.printable','#printArea'].forEach(function(sel){
      Array.prototype.forEach.call(D.querySelectorAll(sel),function(el){
        if(seen.indexOf(el)<0 && (el.id==='print-area' || el.offsetParent!==null)){seen.push(el);out.push(el);}
      });
    });
    return out;
  }
  function fit(){
    reset();
    roots().forEach(function(el){
      var need = Math.max(el.scrollWidth, el.getBoundingClientRect().width);
      if(!need) return;
      if(need > A4_PX + 2){
        var s = Math.max(0.45, A4_PX/need);
        el.style.setProperty('--ayan-print-scale', s);
        el.style.setProperty('--ayan-print-width', need+'px');
        el.classList.add('ayan-print-scaled');
        scaled.push(el);
      }
    });
  }
  function reset(){
    scaled.forEach(function(el){
      el.classList.remove('ayan-print-scaled');
      el.style.removeProperty('--ayan-print-scale');
      el.style.removeProperty('--ayan-print-width');
    });
    scaled = [];
  }
  /* make lazily-rendered / virtualised rows visible before printing */
  function unhide(){
    Array.prototype.forEach.call(D.querySelectorAll('.erp-fastrows,[style*="content-visibility"]'),function(el){
      el.style.contentVisibility='visible';
    });
  }
  W.addEventListener('beforeprint',function(){try{unhide();fit();}catch(e){}});
  W.addEventListener('afterprint',function(){try{reset();}catch(e){}});
  if(W.matchMedia){
    try{ W.matchMedia('print').addEventListener('change',function(m){ m.matches?fit():reset(); }); }catch(e){}
  }
  W.printFitToPage=function(){try{unhide();fit();}catch(e){} W.print(); setTimeout(reset,600);};
})(window,document);
</script>


<!-- ═══ AUTO-FIT DOCUMENTS TO SCREEN (temporary, until print section is improved) ═══
     Scales the A4 letterhead document (#print-area) down so it always fits the
     on-screen preview modal width. Print output is unaffected (zoom reset at print). -->
<script nonce="<?php echo $cspNonceAttr; ?>">
(function(){
  var MODAL_PAD = 40; /* matches #print-modal padding: 20px each side */
  function pa(){ return document.getElementById('print-area'); }
  function pm(){ return document.getElementById('print-modal'); }
  function fit(){
    var a = pa(), m = pm();
    if(!a || !m) return;
    if(!m.classList.contains('open')){ a.style.zoom=''; return; }
    /* measure natural (unzoomed) width */
    var prev = a.style.zoom; a.style.zoom = '';
    var w = a.offsetWidth || 794;
    a.style.zoom = prev;
    var avail = m.clientWidth - MODAL_PAD;
    var scale = Math.min(1, avail / w);
    a.style.zoom = scale < 0.999 ? scale : '';
    a.style.margin = '0 auto';
  }
  window.addEventListener('resize', fit);
  /* refit when the modal opens/closes or the document content changes */
  document.addEventListener('DOMContentLoaded', function(){
    var m = pm(), a = pa();
    if(m) new MutationObserver(fit).observe(m, {attributes:true, attributeFilter:['class']});
    if(a) new MutationObserver(fit).observe(a, {childList:true, subtree:true});
    fit();
  });
  /* never let the on-screen zoom leak into printouts */
  window.addEventListener('beforeprint', function(){ var a=pa(); if(a){ a.dataset.fitZoom=a.style.zoom; a.style.zoom=''; } });
  window.addEventListener('afterprint',  function(){ var a=pa(); if(a){ a.style.zoom=a.dataset.fitZoom||''; } });
})();
</script>

<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-hardening">
/* ═══════════════════════════════════════════════════════════════════════
   AYAN ERP — SECURITY HARDENING PACK (2026-09-02)
   #5.1 brute-force lockout actually enforced on the login flow
   #6.a uploaded-file size and extension validation on every file input
   #6.b prototype-pollution-safe JSON parsing for imports / restores
   #6.c CSV export cells neutralised against spreadsheet formula injection
   ═══════════════════════════════════════════════════════════════════════ */
(function(){
  "use strict";
  var W = window, D = document;

  /* ── #6.b safe JSON ─────────────────────────────────────────────────
     Backups are parsed straight into DB (Object.assign / window.DB = data).
     A crafted file with a "__proto__" key would otherwise write onto
     Object.prototype and poison every object in the app. */
  var BAD_KEYS = { '__proto__':1, 'constructor':1, 'prototype':1 };
  W.__ayanSafeJSONParse = function(text){
    return JSON.parse(text, function(k, v){
      if (BAD_KEYS[k]) return undefined;
      return v;
    });
  };
  W.__ayanScrubProto = function(obj, depth){
    depth = depth || 0;
    if (!obj || typeof obj !== 'object' || depth > 12) return obj;
    for (var k in obj){
      if (!Object.prototype.hasOwnProperty.call(obj, k)) continue;
      if (BAD_KEYS[k]) { try{ delete obj[k]; }catch(e){} continue; }
      W.__ayanScrubProto(obj[k], depth + 1);
    }
    return obj;
  };

  /* ── #6.c CSV formula injection ──────────────────────────────────────
     Exported ledgers are opened in Excel/Sheets. A party name such as
     =HYPERLINK(...) or +cmd|'/c calc'!A0 is executed by the spreadsheet on
     open. Leading formula triggers get a quote prefix. */
  W.__csvCell = function(v){
    var t = (v === null || v === undefined) ? '' : String(v);
    if (/^[=+\-@\t\r]/.test(t)) t = "'" + t;
    return '"' + t.replace(/"/g, '""') + '"';
  };

  /* ── #6.a upload validation ──────────────────────────────────────────
     No import path checked size or type: a multi-hundred-MB or wrong-type
     file froze the tab inside FileReader before any handler ran. Validated
     here in the capture phase so a bad file never reaches the onchange
     handler. */
  var MAX_MB = 25;
  D.addEventListener('change', function(ev){
    var el = ev.target;
    if (!el || el.tagName !== 'INPUT' || el.type !== 'file') return;
    var files = el.files || [];
    if (!files.length) return;
    var accept = (el.getAttribute('accept') || '').split(',')
      .map(function(x){ return x.trim().toLowerCase(); })
      .filter(function(x){ return x.charAt(0) === '.'; });
    for (var i = 0; i < files.length; i++){
      var f = files[i], name = String(f.name || '').toLowerCase();
      if (f.size > MAX_MB * 1024 * 1024){
        alert('❌ "' + f.name + '" is ' + (f.size / 1048576).toFixed(1) +
              ' MB. Maximum import size is ' + MAX_MB + ' MB.');
        el.value = ''; ev.stopPropagation(); ev.preventDefault(); return;
      }
      if (f.size === 0){
        alert('❌ "' + f.name + '" is empty.');
        el.value = ''; ev.stopPropagation(); ev.preventDefault(); return;
      }
      if (accept.length){
        var ok = accept.some(function(ext){ return name.slice(-ext.length) === ext; });
        if (!ok){
          alert('❌ "' + f.name + '" is not a supported file type. Expected: ' + accept.join(', '));
          el.value = ''; ev.stopPropagation(); ev.preventDefault(); return;
        }
      }
    }
  }, true);

  /* ── #5.1 brute-force lockout ────────────────────────────────────────
     _loginAttempts / _MAX_ATTEMPTS / _lockoutUntil and the ls-lockout-warn
     element existed but nothing ever read or incremented them, so the login
     form accepted unlimited guesses at machine speed. The counters are now
     driven by the real login flow and survive a page reload. */
  var MAX_ATTEMPTS = 5, LOCKOUT_MS = 5 * 60 * 1000, STORE = 'ayan_login_guard';

  function state(){
    try{
      var raw = localStorage.getItem(STORE);
      var st = raw ? JSON.parse(raw) : null;
      if (st && typeof st === 'object') return { n: +st.n || 0, until: +st.until || 0 };
    }catch(e){}
    return { n: 0, until: 0 };
  }
  function save(st){
    try{ localStorage.setItem(STORE, JSON.stringify(st)); }catch(e){}
    try{ W._loginAttempts = st.n; W._lockoutUntil = st.until; }catch(e){}
  }
  function show(msg){
    var warn = D.getElementById('ls-lockout-warn');
    var err  = D.getElementById('login-error');
    if (warn){ warn.textContent = msg; warn.style.display = 'block'; }
    else if (err){ err.textContent = msg; err.style.display = 'block'; }
    else if (typeof W.toast === 'function') W.toast(msg, 'e');
  }
  function clearWarn(){
    var warn = D.getElementById('ls-lockout-warn');
    if (warn) warn.style.display = 'none';
  }
  function setBtn(disabled){
    var btn = D.getElementById('ls-login-btn') || D.getElementById('login-btn');
    if (btn) btn.disabled = !!disabled;
  }
  function locked(){
    var st = state(), left = st.until - Date.now();
    if (left <= 0){
      if (st.until){ save({ n: 0, until: 0 }); clearWarn(); setBtn(false); }
      return 0;
    }
    return left;
  }
  function tick(){
    var left = locked();
    if (!left) return;
    var m = Math.floor(left / 60000), sec = Math.ceil((left % 60000) / 1000);
    show('🔒 Too many failed attempts. Try again in ' + (m ? m + 'm ' : '') + sec + 's.');
    setBtn(true);
    setTimeout(tick, 1000);
  }

  W.__ayanLoginGuardReset = function(){ save({ n: 0, until: 0 }); clearWarn(); setBtn(false); };

  function install(){
    var orig = W.doLogin;
    if (typeof orig !== 'function' || orig.__guarded) return typeof orig === 'function';
    var guarded = async function(){
      var left = locked();
      if (left){ tick(); return; }
      clearWarn();
      var before = W.currentUser;
      var out;
      try{ out = await orig.apply(this, arguments); }
      catch(e){ /* the original already reports the error */ }
      if (W.currentUser && W.currentUser !== before){
        W.__ayanLoginGuardReset();
        return out;
      }
      var st = state();
      st.n = (st.n || 0) + 1;
      if (st.n >= MAX_ATTEMPTS){ st.until = Date.now() + LOCKOUT_MS; st.n = MAX_ATTEMPTS; }
      save(st);
      if (st.until > Date.now()) tick();
      else show('Invalid credentials — ' + (MAX_ATTEMPTS - st.n) + ' attempt(s) left before a 5 minute lockout.');
      return out;
    };
    guarded.__guarded = true;
    W.doLogin = guarded;
    return true;
  }

  var tries = 0;
  (function waitForLogin(){
    if (install() || ++tries > 100) { tick(); return; }
    setTimeout(waitForLogin, 100);
  })();
})();
</script>

<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-bulk-select">
/* ═══════════════════════════════════════════════════════════════════════
   AYAN ERP — Bulk Transaction Selection (2026-09-02)

   WHAT IT DOES
   Adds a checkbox column to the Transactions list so you can:
     • Select individual rows, or tick "Select All" in the header.
     • See a sticky toolbar appear at the top of the table showing how
       many rows are selected and the combined total amount.
     • Bulk-delete all selected rows with one confirmation (same logic
       as the per-row delTx(), so balances, stock, trash and audit log
       are all handled correctly).
     • Bulk-approve selected Pending rows (calls approveTx() on each).
     • Clear the selection with the "✖ Clear" button.

   HOW IT WORKS
   This wraps window.renderTx (same pattern as ayan-tx-list-buttons) and
   after each redraw:
     1. Prepends a <th> checkbox cell to the sticky header row.
     2. Prepends a <td> checkbox cell to every data row, carrying the
        transaction ID in a data-txid attribute.
     3. Injects a toolbar div above the table (hidden when nothing is
        selected, visible otherwise).
   All event listeners are attached via event delegation on the tbody so
   they survive re-renders automatically.

   Selection state (_bulkSelected: Set of tx IDs) is preserved across
   Show-More loads — only rows that disappear from the DOM are removed
   from the set automatically on the next render.

   INSTALL: paste as the LAST <script> before </body>.
   ═══════════════════════════════════════════════════════════════════════ */
(function () {
  'use strict';

  /* ── helpers ─────────────────────────────────────────────────────────── */
  var TOOLBAR_ID   = 'ayan-bulk-toolbar';
  var CB_HEAD_ID   = 'ayan-bulk-cb-head';
  var GREEN        = '#16a34a';
  var RED          = '#dc2626';
  var AMBER        = '#b45309';

  var _selected = new Set();   // Set<number>  (tx.id values)

  function money(n) {
    return '৳' + (parseFloat(n) || 0).toLocaleString('en-IN', { maximumFractionDigits: 2 });
  }
  function say(m, k) {
    try { toast(m, k || 'i'); } catch (e) { console.log('[BulkSelect]', m); }
  }
  function confirm2(msg) {
    try { return window.__confirm ? window.__confirm(msg) : Promise.resolve(window.confirm(msg)); }
    catch (e) { return Promise.resolve(window.confirm(msg)); }
  }

  /* ── toolbar ─────────────────────────────────────────────────────────── */
  function ensureToolbar() {
    if (document.getElementById(TOOLBAR_ID)) return;
    var tbl = document.querySelector('table:has(#t-tx)') ||
              (document.getElementById('t-tx') || {}).closest('table');
    if (!tbl) return;
    var wrap = tbl.parentNode;
    var bar = document.createElement('div');
    bar.id = TOOLBAR_ID;
    bar.style.cssText = [
      'display:none', 'align-items:center', 'gap:10px', 'flex-wrap:wrap',
      'padding:10px 14px', 'margin-bottom:6px',
      'background:#fefce8', 'border:1.5px solid #fde68a', 'border-radius:8px',
      'font-size:13px', 'font-weight:600', 'color:#92400e'
    ].join(';');
    bar.innerHTML =
      '<span id="ayan-bulk-info"></span>' +
      '<button id="ayan-bulk-del" style="padding:5px 14px;background:'+RED+';color:#fff;border:none;border-radius:6px;cursor:pointer;font-weight:700;font-size:12px;">🗑 Delete Selected</button>' +
      '<button id="ayan-bulk-approve" style="padding:5px 14px;background:'+GREEN+';color:#fff;border:none;border-radius:6px;cursor:pointer;font-weight:700;font-size:12px;">✅ Approve Selected</button>' +
      '<button id="ayan-bulk-clear" style="padding:5px 14px;background:#6b7280;color:#fff;border:none;border-radius:6px;cursor:pointer;font-weight:700;font-size:12px;">✖ Clear</button>';
    wrap.insertBefore(bar, tbl);

    document.getElementById('ayan-bulk-del').addEventListener('click', doBulkDelete);
    document.getElementById('ayan-bulk-approve').addEventListener('click', doBulkApprove);
    document.getElementById('ayan-bulk-clear').addEventListener('click', function () {
      _selected.clear(); refresh();
    });
  }

  function updateToolbar() {
    var bar  = document.getElementById(TOOLBAR_ID);
    if (!bar) return;
    var n    = _selected.size;
    bar.style.display = n > 0 ? 'flex' : 'none';
    if (!n) return;

    var txs  = (window.DB && DB.tx) || [];
    var total = 0;
    txs.forEach(function (t) { if (_selected.has(t.id)) total += (typeof txAmt === 'function' ? txAmt(t) : 0); });
    var pendingCount = txs.filter(function (t) { return _selected.has(t.id) && t.approvalStatus === 'Pending'; }).length;

    document.getElementById('ayan-bulk-info').textContent =
      n + ' row' + (n > 1 ? 's' : '') + ' selected | Total: ' + money(total);
    document.getElementById('ayan-bulk-approve').style.display = pendingCount > 0 ? '' : 'none';
  }

  /* ── checkbox header ─────────────────────────────────────────────────── */
  function injectHeaderCheckbox() {
    if (document.getElementById(CB_HEAD_ID)) return;
    var thead = document.querySelector('#t-tx')
      ? document.querySelector('#t-tx').closest('table').querySelector('thead tr')
      : null;
    if (!thead) return;
    if (thead.querySelector('#' + CB_HEAD_ID)) return;
    var th = document.createElement('th');
    th.id = CB_HEAD_ID;
    th.style.cssText = 'padding:8px 10px;text-align:center;width:32px;';
    th.innerHTML = '<input type="checkbox" id="ayan-bulk-all" title="Select all visible rows" style="cursor:pointer;width:15px;height:15px;">';
    thead.insertBefore(th, thead.firstChild);

    document.getElementById('ayan-bulk-all').addEventListener('change', function () {
      var checked = this.checked;
      var rows = document.querySelectorAll('#t-tx [data-txid]');
      rows.forEach(function (cb) {
        cb.checked = checked;
        var id = parseInt(cb.getAttribute('data-txid'), 10);
        if (checked) _selected.add(id); else _selected.delete(id);
      });
      updateToolbar();
    });
  }

  /* ── inject row checkboxes ───────────────────────────────────────────── */
  function injectRowCheckboxes() {
    var tbody = document.getElementById('t-tx');
    if (!tbody) return;
    var rows  = tbody.querySelectorAll('tr');
    var inDom = new Set();

    rows.forEach(function (row) {
      /* find tx id from any existing onclick — openModal(ID) or delTx(ID) */
      var m = row.innerHTML.match(/openModal\((\d+)\)|delTx\((\d+)\)/);
      if (!m) return;
      var id = parseInt(m[1] || m[2], 10);
      if (!id) return;
      inDom.add(id);

      /* skip if we already added the checkbox cell to this row */
      if (row.querySelector('[data-txid]')) return;

      var td = document.createElement('td');
      td.style.cssText = 'padding:6px 10px;text-align:center;vertical-align:middle;';
      var cb = document.createElement('input');
      cb.type = 'checkbox';
      cb.setAttribute('data-txid', id);
      cb.checked = _selected.has(id);
      cb.style.cssText = 'cursor:pointer;width:15px;height:15px;';
      cb.addEventListener('change', function () {
        if (this.checked) _selected.add(id); else _selected.delete(id);
        syncHeaderCheckbox();
        updateToolbar();
      });
      td.appendChild(cb);
      row.insertBefore(td, row.firstChild);
    });

    /* prune selections for rows no longer in DOM */
    var toRemove = [];
    _selected.forEach(function (id) { if (!inDom.has(id)) toRemove.push(id); });
    toRemove.forEach(function (id) { _selected.delete(id); });

    syncHeaderCheckbox();
    updateToolbar();
  }

  function syncHeaderCheckbox() {
    var allCb = document.getElementById('ayan-bulk-all');
    if (!allCb) return;
    var rowCbs = document.querySelectorAll('#t-tx [data-txid]');
    if (!rowCbs.length) { allCb.checked = false; allCb.indeterminate = false; return; }
    var checkedCount = Array.prototype.filter.call(rowCbs, function (c) { return c.checked; }).length;
    allCb.checked      = checkedCount === rowCbs.length;
    allCb.indeterminate = checkedCount > 0 && checkedCount < rowCbs.length;
  }

  /* ── main refresh (called after every renderTx) ──────────────────────── */
  function refresh() {
    ensureToolbar();
    injectHeaderCheckbox();
    injectRowCheckboxes();
  }

  /* ── bulk delete ─────────────────────────────────────────────────────── */
  async function doBulkDelete() {
    if (!_selected.size) return;
    var n = _selected.size;
    var ok = await confirm2('Delete ' + n + ' selected transaction' + (n > 1 ? 's' : '') + '? This will reverse all their balance effects.');
    if (!ok) return;

    /* collect ids first (delTx mutates DB.tx so iterate a copy) */
    var ids = Array.from(_selected);
    var deleted = 0;
    for (var i = 0; i < ids.length; i++) {
      try {
        /* call the existing delTx but bypass its own confirm */
        var id = ids[i];
        var tx = (DB.tx || []).find(function (t) { return t.id === id; });
        if (!tx) continue;

        /* replicate delTx logic without triggering its own confirm dialog */
        if (tx.approvalStatus !== 'Pending') {
          try { applyTxBalance(tx, -1); } catch (e) {}
          try { applyTxStock(tx, -1); }   catch (e) {}
          try { applyAssetRegister(tx, -1); } catch (e) {}
        }
        var linked = (DB.tx || []).find(function (t) { return t.linkedSaleTxId === id && t.autoGenerated === 'weightLoss'; });
        if (linked && linked.approvalStatus !== 'Pending') { try { applyTxBalance(linked, -1); } catch (e) {} }
        if (!DB.trash) DB.trash = [];
        DB.trash.unshift(Object.assign({}, tx, { _type: 'transaction', _deletedAt: new Date().toISOString() }));
        if (linked) DB.trash.unshift(Object.assign({}, linked, { _type: 'transaction', _deletedAt: new Date().toISOString() }));
        DB.tx = (DB.tx || []).filter(function (t) { return t.id !== id && t !== linked; });
        DB.transactions = DB.tx;
        try { logAudit('DELETE', 'Transaction', 'Bulk-deleted transaction ID ' + id); } catch (e) {}
        deleted++;
      } catch (e) { console.error('[BulkSelect] delTx error for id', ids[i], e); }
    }

    _selected.clear();
    try { saveDB(); } catch (e) {}
    try { if (typeof _scheduleAutoSave === 'function') _scheduleAutoSave(); } catch (e) {}
    try { renderTx(); } catch (e) {}
    try { renderDash(); } catch (e) {}
    say(deleted + ' transaction' + (deleted > 1 ? 's' : '') + ' deleted.', 's');
  }

  /* ── bulk approve ────────────────────────────────────────────────────── */
  async function doBulkApprove() {
    var pendingIds = [];
    var txs = (window.DB && DB.tx) || [];
    txs.forEach(function (t) {
      if (_selected.has(t.id) && t.approvalStatus === 'Pending') pendingIds.push(t.id);
    });
    if (!pendingIds.length) { say('No pending transactions selected.', 'w'); return; }
    var n  = pendingIds.length;
    var ok = await confirm2('Approve ' + n + ' pending transaction' + (n > 1 ? 's' : '') + '? This will post them to the ledger.');
    if (!ok) return;

    for (var i = 0; i < pendingIds.length; i++) {
      try { await approveTx(pendingIds[i]); } catch (e) { console.error('[BulkSelect] approveTx error', pendingIds[i], e); }
    }
    _selected.clear();
    try { renderTx(); } catch (e) {}
    say(n + ' transaction' + (n > 1 ? 's' : '') + ' approved.', 's');
  }

  /* ── wrap renderTx ───────────────────────────────────────────────────── */
  var _origRenderTx = window.renderTx;
  if (typeof _origRenderTx === 'function') {
    window.renderTx = function () {
      /* clear stale header checkbox so injectHeaderCheckbox() re-creates it */
      var oldHead = document.getElementById(CB_HEAD_ID);
      if (oldHead) oldHead.remove();
      var r = _origRenderTx.apply(this, arguments);
      setTimeout(refresh, 0);
      return r;
    };
  }

  /* ── boot ────────────────────────────────────────────────────────────── */
  function boot() { refresh(); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();
  setTimeout(boot, 1000);   /* catch late-loading pages */
})();
</script>

<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-tx-advanced-filters">
/* ═══════════════════════════════════════════════════════════════════════
   AYAN ERP — Advanced Transaction Filters (2026-09-02)

   WHAT IT DOES
   Adds five more user-friendly filters to the Transactions page, next to
   the existing Type / Mode / Party Type / Date filters:
     • Approval Status  — All / Pending / Approved
     • Account          — every bank/mobile-wallet account actually used
                           in DB.tx, shown by its display name
     • Amount range     — min / max amount (৳), matches on |amount|
     • Due only         — checkbox, shows only rows with an outstanding due
     • Quick date chips — Today / This Week / This Month / This Year,
                           one click fills the existing From/To date inputs
   A small "🧹 Reset All" button clears everything (old filters included).

   HOW IT WORKS
   The existing txF object / renderTx() filtering (search, type, mode,
   partyType, dateFrom, dateTo) is left completely untouched. This module
   keeps its own filter state and wraps window.renderTx exactly like
   ayan-bulk-select does: it pre-filters the array by the NEW criteria and
   hands the (smaller) result to the original renderTx, which then applies
   its own filters on top. Because every filter is an AND condition, the
   combined result is correct regardless of which module runs first.

   The controls themselves are injected once into the page's existing
   <div class="filter-bar"> (found by walking up from #txDateFrom, so it
   never accidentally matches the Partner-Ledger or Cheque filter bars
   elsewhere in the app) — no HTML template edits required.

   INSTALL: paste as the LAST <script> before </body> (after
   ayan-bulk-select, so bulk-select's checkbox column still lines up with
   whatever rows this module lets through).
   ═══════════════════════════════════════════════════════════════════════ */
(function () {
  'use strict';

  var ROW_ID = 'ayan-adv-filter-row';
  var _f = { status: '', acc: '', amtMin: '', amtMax: '', dueOnly: false };

  function bar() {
    var anchor = document.getElementById('txDateFrom');
    return anchor ? anchor.closest('.filter-bar') : null;
  }

  /* ── build the option list of accounts actually seen in DB.tx ────────── */
  function accountOptions() {
    var seen = {}; // display-name -> raw acc value (first one wins)
    (window.DB && DB.tx || []).forEach(function (t) {
      if (!t.acc) return;
      var disp;
      try { disp = bankNameToDisplay(t.acc); } catch (e) { disp = t.acc; }
      if (!seen[disp]) seen[disp] = t.acc;
    });
    return Object.keys(seen).sort().map(function (disp) {
      return { value: seen[disp], label: disp };
    });
  }

  /* ── inject the extra controls once ───────────────────────────────────── */
  function injectRow() {
    if (document.getElementById(ROW_ID)) { refreshAccountOptions(); return; }
    var wrap = bar();
    if (!wrap) return;

    var row = document.createElement('div');
    row.id = ROW_ID;
    row.className = 'filter-bar';
    row.style.cssText = 'margin-top:-4px;';
    row.innerHTML =
      '<select class="fsel" id="ayan-f-status">' +
        '<option value="">All Statuses</option>' +
        '<option value="Pending">⏳ Pending</option>' +
        '<option value="Approved">✅ Approved</option>' +
      '</select>' +
      '<select class="fsel" id="ayan-f-acc"><option value="">All Accounts</option></select>' +
      '<input class="fsel" id="ayan-f-amtmin" type="number" placeholder="Min ৳" style="width:90px;padding:4px 8px;">' +
      '<input class="fsel" id="ayan-f-amtmax" type="number" placeholder="Max ৳" style="width:90px;padding:4px 8px;">' +
      '<label style="display:flex;align-items:center;gap:5px;font-size:12px;color:var(--gray-500);cursor:pointer;">' +
        '<input type="checkbox" id="ayan-f-dueonly" style="cursor:pointer;">Due only</label>' +
      '<span style="width:1px;background:#e5e7eb;align-self:stretch;"></span>' +
      '<button class="btn btn-sm" style="background:#eef2ff;color:#3730a3;font-size:11px;" data-preset="today">Today</button>' +
      '<button class="btn btn-sm" style="background:#eef2ff;color:#3730a3;font-size:11px;" data-preset="week">This Week</button>' +
      '<button class="btn btn-sm" style="background:#eef2ff;color:#3730a3;font-size:11px;" data-preset="month">This Month</button>' +
      '<button class="btn btn-sm" style="background:#eef2ff;color:#3730a3;font-size:11px;" data-preset="year">This Year</button>' +
      '<button class="btn btn-sm" id="ayan-f-reset" style="background:#e2e8f0;color:#4a5568;font-size:11px;">🧹 Reset All</button>';
    wrap.parentNode.insertBefore(row, wrap.nextSibling);

    document.getElementById('ayan-f-status').addEventListener('change', function () { _f.status = this.value; apply(); });
    document.getElementById('ayan-f-acc').addEventListener('change', function () { _f.acc = this.value; apply(); });
    document.getElementById('ayan-f-amtmin').addEventListener('input', function () { _f.amtMin = this.value; apply(); });
    document.getElementById('ayan-f-amtmax').addEventListener('input', function () { _f.amtMax = this.value; apply(); });
    document.getElementById('ayan-f-dueonly').addEventListener('change', function () { _f.dueOnly = this.checked; apply(); });
    document.getElementById('ayan-f-reset').addEventListener('click', resetAll);
    row.querySelectorAll('[data-preset]').forEach(function (btn) {
      btn.addEventListener('click', function () { applyDatePreset(this.getAttribute('data-preset')); });
    });

    refreshAccountOptions();
  }

  function refreshAccountOptions() {
    var sel = document.getElementById('ayan-f-acc');
    if (!sel) return;
    var current = sel.value;
    var opts = accountOptions();
    sel.innerHTML = '<option value="">All Accounts</option>' +
      opts.map(function (o) {
        return '<option value="' + String(o.value).replace(/"/g, '&quot;') + '">' + escHTML(o.label) + '</option>';
      }).join('');
    if (current && opts.some(function (o) { return o.value === current; })) sel.value = current;
  }

  /* ── date presets: fill the EXISTING txDateFrom/txDateTo + txF ───────── */
  function pad2(n) { return n < 10 ? '0' + n : '' + n; }
  function ymd(d) { return d.getFullYear() + '-' + pad2(d.getMonth() + 1) + '-' + pad2(d.getDate()); }

  function applyDatePreset(kind) {
    var now = new Date(), from, to = new Date();
    if (kind === 'today') { from = new Date(); }
    else if (kind === 'week') {
      from = new Date(now);
      var dow = (from.getDay() + 6) % 7; // Monday-start week
      from.setDate(from.getDate() - dow);
    } else if (kind === 'month') { from = new Date(now.getFullYear(), now.getMonth(), 1); }
    else if (kind === 'year') { from = new Date(now.getFullYear(), 0, 1); }
    else return;

    var fromStr = ymd(from), toStr = ymd(to);
    var dfEl = document.getElementById('txDateFrom');
    var dtEl = document.getElementById('txDateTo');
    if (dfEl) dfEl.value = fromStr;
    if (dtEl) dtEl.value = toStr;
    if (typeof txF !== 'undefined') { txF.dateFrom = fromStr; txF.dateTo = toStr; }
    apply();
  }

  function resetAll() {
    _f = { status: '', acc: '', amtMin: '', amtMax: '', dueOnly: false };
    var ids = ['ayan-f-status', 'ayan-f-acc', 'ayan-f-amtmin', 'ayan-f-amtmax'];
    ids.forEach(function (id) { var el = document.getElementById(id); if (el) el.value = ''; });
    var due = document.getElementById('ayan-f-dueonly'); if (due) due.checked = false;
    try { if (typeof clearTxDates === 'function') clearTxDates(); } catch (e) {}
    apply();
  }

  /* ── the actual pre-filter, applied before the original renderTx ─────── */
  function filterTxs(list) {
    var out = list;
    if (_f.status) out = out.filter(function (t) {
      return _f.status === 'Pending' ? t.approvalStatus === 'Pending' : t.approvalStatus !== 'Pending';
    });
    if (_f.acc) out = out.filter(function (t) { return t.acc === _f.acc; });
    if (_f.amtMin !== '' && !isNaN(parseFloat(_f.amtMin))) {
      var lo = parseFloat(_f.amtMin);
      out = out.filter(function (t) { return Math.abs(typeof txAmt === 'function' ? txAmt(t) : 0) >= lo; });
    }
    if (_f.amtMax !== '' && !isNaN(parseFloat(_f.amtMax))) {
      var hi = parseFloat(_f.amtMax);
      out = out.filter(function (t) { return Math.abs(typeof txAmt === 'function' ? txAmt(t) : 0) <= hi; });
    }
    if (_f.dueOnly) out = out.filter(function (t) { return (parseFloat(t.due) || 0) > 0; });
    return out;
  }

  function apply() {
    if (typeof txResetPaging === 'function') txResetPaging();
    try { renderTx(); } catch (e) { console.error('[AdvFilters]', e); }
  }

  /* ── wrap renderTx: filter first, let the original do the rest ───────── */
  var _origRenderTx3 = window.renderTx;
  if (typeof _origRenderTx3 === 'function') {
    window.renderTx = function (data) {
      var base = data || (window.DB && DB.tx) || [];
      var r = _origRenderTx3.call(this, filterTxs(base));
      setTimeout(injectRow, 0);
      return r;
    };
  }

  /* ── boot ──────────────────────────────────────────────────────────── */
  function boot() { injectRow(); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();
  setTimeout(boot, 1000);
})();
</script>

<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-universal-bulk">
/* ═══════════════════════════════════════════════════════════════════════
   UNIVERSAL BULK SELECTION  —  every list page, one engine
   ───────────────────────────────────────────────────────────────────────
   Rather than hand-editing 47 separate tables, this attaches itself to any
   table that renders rows with a per-row delete button. It injects a
   checkbox column + master "select all" header, and drives a floating
   action bar (Delete / Export CSV / Print / Clear).

   Bulk delete simply replays each selected row's OWN delete handler, so
   every module keeps its existing reversal logic (balances, stock, trash
   bin, audit log). Per-row confirm dialogs and toasts are muted for the
   duration and replaced with a single summary.
   ═══════════════════════════════════════════════════════════════════════ */
(function () {
  'use strict';
  var DEL_RE  = /\b(?:del|delete|remove)[A-Za-z_]*\s*\(/i;
  var MARK    = 'data-bulk-ready';
  var active  = null;   // table the current selection belongs to
  var observer = null;

  /* PATCH VULN-01-followup — literal-reference replay, no eval/new Function.
     Bulk delete used to hand each row's `data-x-click="fn(args)"` string straight
     to `new Function(...)`, which the hardened CSP (script-src without
     'unsafe-eval') now blocks outright — every bulk delete would silently
     fail post-deploy. This parses the handler string into a function path
     plus a list of literal arguments (numbers/strings/bool/null/simple
     array-or-object literals) and invokes the real function object directly.
     It intentionally refuses anything that isn't a literal argument rather
     than falling back to eval — onclick handlers in this app are always
     generated with literal values baked in, so that's the entire domain. */
  function parseLiteral(tok) {
    tok = tok.trim();
    if (tok === '') throw new Error('empty argument');
    if (tok === 'true') return true;
    if (tok === 'false') return false;
    if (tok === 'null') return null;
    if (tok === 'undefined') return undefined;
    if (/^-?\d+(?:\.\d+)?(?:e-?\d+)?$/i.test(tok)) return Number(tok);
    if ((tok[0] === '"' && tok[tok.length - 1] === '"') ||
        (tok[0] === "'" && tok[tok.length - 1] === "'")) {
      var q = tok[0], body = tok.slice(1, -1), out = '';
      for (var i = 0; i < body.length; i++) {
        if (body[i] === '\\' && i + 1 < body.length) {
          var n = body[++i];
          out += (n === 'n') ? '\n' : (n === 't') ? '\t' :
                 (n === q || n === '\\') ? n : n;
        } else out += body[i];
      }
      return out;
    }
    if ((tok[0] === '[' && tok[tok.length - 1] === ']') ||
        (tok[0] === '{' && tok[tok.length - 1] === '}')) {
      try { return JSON.parse(tok.replace(/'/g, '"')); } catch (e) { /* fall through */ }
    }
    throw new Error('unsupported literal in handler args: ' + tok);
  }
  function parseArgList(src) {
    src = src.trim();
    if (!src) return [];
    var args = [], depth = 0, cur = '', inStr = null;
    for (var i = 0; i < src.length; i++) {
      var c = src[i];
      if (inStr) {
        cur += c;
        if (c === '\\' && i + 1 < src.length) { cur += src[++i]; continue; }
        if (c === inStr) inStr = null;
        continue;
      }
      if (c === '"' || c === "'") { inStr = c; cur += c; continue; }
      if (c === '(' || c === '[' || c === '{') { depth++; cur += c; continue; }
      if (c === ')' || c === ']' || c === '}') { depth--; cur += c; continue; }
      if (c === ',' && depth === 0) { args.push(cur); cur = ''; continue; }
      cur += c;
    }
    if (cur.trim() !== '') args.push(cur);
    return args.map(parseLiteral);
  }
  function callExprSafely(expr) {
    var s = String(expr).trim().replace(/^return\s+/, '').replace(/;+\s*$/, '');
    var m = /^([A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*)\s*\(([\s\S]*)\)$/.exec(s);
    if (!m) throw new Error('unrecognized handler expression: ' + expr);
    var path = m[1].split('.');
    var args = parseArgList(m[2]);
    var ctx = window, fn = window;
    for (var i = 0; i < path.length; i++) {
      if (fn == null) throw new Error('handler not found: ' + m[1]);
      if (i > 0) ctx = ctx[path[i - 1]];
      fn = fn[path[i]];
    }
    if (typeof fn !== 'function') throw new Error('not a function: ' + m[1]);
    return fn.apply(path.length > 1 ? ctx : window, args);
  }

  /* ── styles ────────────────────────────────────────────────────────── */
  var css = document.createElement('style');
  css.textContent =
    '.bulk-col{width:34px;text-align:center;padding:4px 6px!important;}' +
    '.bulk-col input{width:15px;height:15px;cursor:pointer;vertical-align:middle;accent-color:#2563eb;}' +
    'tr.bulk-on{background:#dbeafe!important;}' +
    'tr.bulk-on td{background:transparent!important;}' +
    '#bulkBar{position:fixed;left:50%;transform:translateX(-50%) translateY(160%);bottom:74px;z-index:99999;' +
      'display:flex;align-items:center;gap:8px;background:#0f172a;color:#fff;padding:9px 14px;' +
      'border-radius:11px;box-shadow:0 10px 34px rgba(0,0,0,.34);font:600 12px Inter,Segoe UI,system-ui,sans-serif;' +
      'transition:transform .18s ease;max-width:94vw;flex-wrap:wrap;}' +
    '#bulkBar.show{transform:translateX(-50%) translateY(0);}' +
    '#bulkBar b{background:#2563eb;border-radius:20px;padding:2px 9px;font-size:11px;}' +
    '#bulkBar button{border:0;border-radius:7px;padding:6px 11px;font:700 11px inherit;cursor:pointer;background:#334155;color:#fff;}' +
    '#bulkBar button:hover{filter:brightness(1.22);}' +
    '#bulkBar .bb-del{background:#dc2626;}#bulkBar .bb-csv{background:#16a34a;}#bulkBar .bb-prn{background:#f59e0b;color:#111;}' +
    '@media print{.bulk-col,#bulkBar{display:none!important;}}';
  document.head.appendChild(css);

  /* ── floating action bar ───────────────────────────────────────────── */
  var bar, lbl;
  function buildBar() {
    if (bar) return;
    bar = document.createElement('div');
    bar.id = 'bulkBar';
    bar.innerHTML = '<b id="bulkCount">0</b><span>selected</span>' +
      '<button class="bb-del">🗑 Delete</button>' +
      '<button class="bb-csv">⤓ Export CSV</button>' +
      '<button class="bb-prn">🖨 Print</button>' +
      '<button class="bb-clr">✕ Clear</button>';
    document.body.appendChild(bar);
    lbl = bar.querySelector('#bulkCount');
    bar.querySelector('.bb-del').onclick = bulkDelete;
    bar.querySelector('.bb-csv').onclick = bulkCsv;
    bar.querySelector('.bb-prn').onclick = bulkPrint;
    bar.querySelector('.bb-clr').onclick = function () { clearSel(); };
  }

  function boxes(t) { return t ? [].slice.call(t.querySelectorAll('tbody .bulk-col input')) : []; }
  function chosen(t) { return boxes(t).filter(function (b) { return b.checked; }); }

  function refresh() {
    buildBar();
    var n = active ? chosen(active).length : 0;
    lbl.textContent = n;
    bar.classList.toggle('show', n > 0);
    if (active) {
      var all = boxes(active), master = active.querySelector('thead .bulk-col input');
      if (master) {
        master.checked = all.length > 0 && n === all.length;
        master.indeterminate = n > 0 && n < all.length;
      }
    }
  }

  function clearSel() {
    if (active) {
      boxes(active).forEach(function (b) { b.checked = false; b.closest('tr').classList.remove('bulk-on'); });
      var m = active.querySelector('thead .bulk-col input');
      if (m) { m.checked = false; m.indeterminate = false; }
    }
    refresh();
  }

  /* ── attach checkboxes to one table ────────────────────────────────── */
  function enhance(t) {
    if (t.hasAttribute(MARK)) return;
    var tb = t.tBodies[0], head = t.tHead;
    if (!tb || !head) return;
    var rows = [].slice.call(tb.rows).filter(function (r) { return r.cells.length > 1; });
    if (!rows.length) return;
    // only tables whose rows expose their own delete action
    var deletable = rows.filter(function (r) { return !!delExpr(r); });
    if (!deletable.length) return;
    /* Some screens (Transactions, Contacts, Users, Products) already ship a
       hand-built select-all. Leave those completely alone rather than
       stacking a second checkbox column on top of them. */
    if (t.querySelector('input[type=checkbox]')) { t.setAttribute(MARK, 'own'); return; }

    t.setAttribute(MARK, '1');

    var hr = head.rows[head.rows.length - 1];
    if (hr && !hr.querySelector('.bulk-col')) {
      var th = document.createElement('th');
      th.className = 'bulk-col';
      th.innerHTML = '<input type="checkbox" title="Select all">';
      hr.insertBefore(th, hr.cells[0]);
      th.firstChild.onclick = function (e) {
        e.stopPropagation();
        active = t;
        var on = this.checked;
        boxes(t).forEach(function (b) { b.checked = on; b.closest('tr').classList.toggle('bulk-on', on); });
        refresh();
      };
      // header rows above the last one need their span widened
      for (var i = 0; i < head.rows.length - 1; i++) {
        var c0 = head.rows[i].cells[0];
        if (c0) c0.colSpan = (c0.colSpan || 1) + 1;
      }
    }

    [].slice.call(tb.rows).forEach(function (r) {
      if (r.querySelector('.bulk-col')) return;
      if (r.cells.length === 1 && r.cells[0].colSpan > 1) { r.cells[0].colSpan++; return; } // "no records" row
      var td = document.createElement('td');
      td.className = 'bulk-col';
      if (delExpr(r)) {
        td.innerHTML = '<input type="checkbox">';
        td.firstChild.onclick = function (e) {
          e.stopPropagation();
          if (active !== t) { clearSel(); active = t; }
          r.classList.toggle('bulk-on', this.checked);
          refresh();
        };
      }
      r.insertBefore(td, r.cells[0]);
    });

    // keep footer totals aligned
    if (t.tFoot) [].slice.call(t.tFoot.rows).forEach(function (r) {
      if (r.cells[0]) r.cells[0].colSpan = (r.cells[0].colSpan || 1) + 1;
    });
  }

  function delExpr(row) {
    /* FIX (2026-09-09): this only ever checked the legacy data-x-click="..."
       attribute. The app was migrated to data-x-click="..." for every
       button (CSP hardening — see ayan-universal-bulk's own header
       comment), so this matched zero rows on every screen and the whole
       engine silently did nothing anywhere. Checking both keeps any
       future onclick-based button working too. */
    var els = row.querySelectorAll('[onclick],[data-x-click]');
    for (var i = 0; i < els.length; i++) {
      var a = els[i].getAttribute('onclick') || els[i].getAttribute('data-x-click') || '';
      if (DEL_RE.test(a)) return a;
    }
    return null;
  }

  /* ── bulk delete: replay each row's own handler, dialogs muted ─────── */
  async function bulkDelete() {
    var sel = chosen(active);
    if (!sel.length) return;
    var ask = window.__confirm || window.confirm;
    var ok = await ask.call(window, 'Delete ' + sel.length + ' selected record(s)? Each item\'s normal reversal rules apply and it goes to the Trash Bin where supported.');
    if (!ok) return;

    var exprs = sel.map(function (b) { return delExpr(b.closest('tr')); }).filter(Boolean);
    var oC = window.__confirm, oW = window.confirm, oT = window.toast;
    window.__confirm = function () { return Promise.resolve(true); };
    window.confirm = function () { return true; };
    window.toast = function () {};
    var done = 0, failed = 0;
    for (var i = 0; i < exprs.length; i++) {
      try { await Promise.resolve(callExprSafely(exprs[i])); done++; }
      catch (e) { failed++; console.error('[bulk]', exprs[i], e); }
    }
    window.__confirm = oC; window.confirm = oW; window.toast = oT;
    active = null; refresh();
    if (typeof oT === 'function') oT(done + ' deleted' + (failed ? ', ' + failed + ' failed' : ''), failed ? 'e' : 's');
    scan();
  }

  /* ── shared: selected rows as a plain matrix ───────────────────────── */
  function matrix() {
    var head = [].slice.call(active.tHead.rows[active.tHead.rows.length - 1].cells);
    var skip = {};
    head.forEach(function (c, i) { if (c.classList.contains('bulk-col')) skip[i] = 1; });
    var lastIdx = head.length - 1;
    if (/action/i.test(head[lastIdx] ? head[lastIdx].textContent : '')) skip[lastIdx] = 1;
    var cols = head.map(function (c, i) { return skip[i] ? null : c.innerText.trim(); }).filter(function (x) { return x !== null; });
    var body = chosen(active).map(function (b) {
      return [].slice.call(b.closest('tr').cells)
        .map(function (c, i) { return skip[i] ? null : c.innerText.trim().replace(/\s+/g, ' '); })
        .filter(function (x) { return x !== null; });
    });
    return { cols: cols, body: body };
  }

  function bulkCsv() {
    if (!chosen(active).length) return;
    var m = matrix();
    var q = function (v) { return '"' + String(v == null ? '' : v).replace(/"/g, '""') + '"'; };
    var csv = '\uFEFF' + [m.cols].concat(m.body).map(function (r) { return r.map(q).join(','); }).join('\r\n');
    var url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8;' }));
    var a = document.createElement('a');
    a.href = url;
    a.download = 'selected-' + new Date().toISOString().slice(0, 10) + '.csv';
    a.click();
    setTimeout(function () { URL.revokeObjectURL(url); }, 1500);
    if (typeof toast === 'function') toast(m.body.length + ' row(s) exported', 's');
  }

  function bulkPrint() {
    if (!chosen(active).length) return;
    var m = matrix();
    var esc = function (s) { return String(s == null ? '' : s).replace(/[&<>]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]; }); };
    var co = '';
    try { co = (typeof prtCo === 'function' ? prtCo().name : '') || ''; } catch (e) {}
    var w = window.open('', '_blank');
    if (!w) { if (typeof toast === 'function') toast('Allow pop-ups to print', 'e'); return; }
    w.document.write('<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Selected Records</title><style>' +
      '@page{size:A4 landscape;margin:12mm}body{font:12px Inter,Segoe UI,system-ui,sans-serif;color:#111}' +
      'h2{margin:0 0 2px}.sub{color:#666;font-size:11px;margin-bottom:12px}' +
      'table{width:100%;border-collapse:collapse}th,td{border:1px solid #cbd5e1;padding:6px 8px;text-align:left;font-size:11px}' +
      'thead{background:#0f172a;color:#fff}tr{page-break-inside:avoid}thead{display:table-header-group}' +
      '</style></head><body><h2>' + esc(co || 'Selected Records') + '</h2>' +
      '<div class="sub">' + m.body.length + ' selected record(s) &middot; ' + new Date().toLocaleString() + '</div><table><thead><tr>' +
      m.cols.map(function (c) { return '<th>' + esc(c) + '</th>'; }).join('') + '</tr></thead><tbody>' +
      m.body.map(function (r) { return '<tr>' + r.map(function (c) { return '<td>' + esc(c) + '</td>'; }).join('') + '</tr>'; }).join('') +
      '</tbody></table></body></html>');
    w.document.close();
    setTimeout(function () { w.focus(); w.print(); }, 320);
  }

  /* ── scan the document, re-running after every render ──────────────── */
  var pending = null;
  function scan() {
    if (observer) observer.disconnect();
    try {
      /* Enhance every table, visible or not. Screens are rendered into
         hidden containers and revealed afterwards, so a visibility filter
         here skips a table once and never revisits it. */
      [].slice.call(document.querySelectorAll('table')).forEach(function (t) {
        try { enhance(t); } catch (e) { console.error('[bulk] enhance', e); }
      });
      if (active && !document.body.contains(active)) { active = null; }
      refresh();
    } finally {
      if (observer) observer.observe(document.body, { childList: true, subtree: true });
    }
  }
  function queue() { clearTimeout(pending); pending = setTimeout(scan, 120); }

  function boot() {
    buildBar();
    observer = new MutationObserver(queue);
    observer.observe(document.body, { childList: true, subtree: true });
    scan();
    if (typeof window.nav === 'function') {
      var oNav = window.nav;
      window.nav = function () { active = null; var r = oNav.apply(this, arguments); queue(); return r; };
    }
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();
  setTimeout(scan, 1200);
  setInterval(scan, 4000);   // safety net for renders that bypass nav()

  window.AyanBulk = { scan: scan, clear: clearSel };
})();
</script>

<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-final-save-authority">
/* \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550
   FINAL, SOLE AUTHORITY FOR saveDB / saveDBNow \u2014 SERVER-VERIFIED SAVES
   ---------------------------------------------------------------------
   Paste as the LAST <script> in <body> (it is). Earlier layers in this
   file \u2014 FIX 3's localStorage+IndexedDB "quota-safe" mirror,
   erp-durable-save-v4's burst-coalescing/local-first wrapper, and
   TxCache's cache-invalidation wrapper \u2014 each took a turn owning
   window.saveDB / saveDBNow, and some of them wrote to the browser FIRST
   and treated that write as "saved" before the server ever confirmed
   it. The 2026-09-02 "server-only storage guard" (top of <head>) already
   makes those browser writes volatile (they vanish on refresh), so they
   can no longer resurrect stale data \u2014 but it doesn't change what those
   layers report to the user as "saved", and their defineProperty
   accessors still hand ownership back and forth (see the comments near
   "TxCache" and "erp-durable-save-v4" for that history).

   This script ends the hand-off: it becomes the permanent, final
   accessor for saveDB/saveDBNow, with configurable:true so it can still
   be intentionally replaced by a later paste, but any OTHER later plain
   assignment (window.saveDB = ...) is captured harmlessly by the setter
   below and never used \u2014 the getter always returns THIS implementation.
   A save only counts as successful once this fetch to api.php actually
   resolves with success:true.

   Deliberately NOT applied to window.loadDataFromServer: that function
   already has three legitimate, working post-load fixups chained onto
   it further up this file \u2014 due-repair, asset-register backfill, and
   (most load-bearing) the DB.parties/transactions/bankAccounts alias
   ("claude-fix-db-parties-alias"). Locking loadDataFromServer here would
   silently discard that entire chain. The one thing load needed \u2014
   capturing the server's version number for the optimistic-concurrency
   check below \u2014 was added as a small patch directly inside the
   existing loadDataFromServer (search window.__erpVersion).

   SERVER CONTRACT (same save endpoint as before; version check is
   additive/optional):
     POST api.php?action=save   body: { baseVersion: <int|null>, data }
       -> success:      { success: true, version: <int> }        (200)
       -> lost the race: { success: false, conflict: true,
                            version: <int current server version> } (409)
   If api.php doesn't track a version column yet, baseVersion is simply
   ignored server-side and everything above still works \u2014 conflict
   detection just won't trigger until api.php adds that check (see the
   original save-load contract note this file already documents).
   \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 */
(function () {
  'use strict';
  var W = window;

  function apiUrl() {
    return (W.ERP_CONFIG && W.ERP_CONFIG.API_URL) ? W.ERP_CONFIG.API_URL : 'api.php';
  }
  function csrfHeaders(extra) {
    return Object.assign({ 'Accept': 'application/json' }, extra || {});
  }
  function say(msg, type) { try { if (typeof W.toast === 'function') W.toast(msg, type); } catch (e) {} }
  function requireSession() {
    if (W.currentUser) return true;
    say('Not logged in \u2014 please sign in to save.', 'e');
    try { if (typeof W.showLoginScreen === 'function') W.showLoginScreen(); } catch (e) {}
    return false;
  }
  function handleAuthFailure() {
    try {
      sessionStorage.removeItem('rbo_user');
      sessionStorage.removeItem('ayan_session');
    } catch (e) {}
    W.currentUser = null;
    say('Session expired \u2014 please sign in again.', 'e');
    try { if (typeof W.showLoginScreen === 'function') W.showLoginScreen(); } catch (e) {}
  }
  function invalidateCaches() {
    // TxCache memoises financial roll-ups (sumRevenue, cogsByProduct,
    // partyBuckets\u2026) off a dirty flag it normally sets by wrapping
    // saveDB. That wrapper is superseded below, so poke it directly so
    // reports don't go stale.
    try { if (W.TxCache && typeof W.TxCache.invalidate === 'function') W.TxCache.invalidate(); } catch (e) {}
  }

  // ── SAVE: always a real round trip, verified by the server ───────────
  var _saveTimer = null, _saving = false, _queuedWhileSaving = false;

  async function realSaveNow() {
    if (!requireSession()) return false;
    if (_saving) { _queuedWhileSaving = true; return false; }
    _saving = true;
    try {
      var res = await fetch(apiUrl() + '?action=save', {
        method: 'POST',
        credentials: 'include',
        headers: csrfHeaders({ 'Content-Type': 'application/json' }),
        body: JSON.stringify({ baseVersion: W.__erpVersion, data: W.DB })
      });
      if (res.status === 401 || res.status === 403) { handleAuthFailure(); return false; }

      var out = await res.json().catch(function () { return {}; });

      if (res.status === 409 || out.conflict === true) {
        // Someone else's save landed first. Overwriting now would silently
        // discard their work, so refuse and make the user reconcile.
        if (typeof out.version !== 'undefined') W.__erpVersion = out.version;
        say('Someone else saved more recent changes. Reload to see them before continuing.', 'e');
        try { if (typeof W._markUnsaved === 'function') W._markUnsaved(); } catch (e) {}
        return false;
      }
      if (!res.ok || out.success === false) throw new Error(out.message || out.error || 'Save failed');

      if (typeof out.version !== 'undefined') W.__erpVersion = out.version;
      invalidateCaches();
      try { if (typeof W._markSaved === 'function') W._markSaved(); } catch (e) {}
      return true;
    } catch (err) {
      try { if (typeof W._markUnsaved === 'function') W._markUnsaved(); } catch (e) {}
      say('Save failed: ' + err.message, 'e');
      return false;
    } finally {
      _saving = false;
      if (_queuedWhileSaving) { _queuedWhileSaving = false; realSaveNow(); }
    }
  }

  function debouncedSave() {
    if (!requireSession()) return false;
    clearTimeout(_saveTimer);
    _saveTimer = setTimeout(realSaveNow, 400);
    return true;
  }

  /* PATCH REC-02 — flushOnExit re-entrancy guard.
     pagehide, beforeunload, and visibilitychange can all fire in sequence
     during a single tab-close on some browsers, causing three concurrent
     keepalive fetches with identical payloads. _flushed prevents all but the
     first. It is reset when the tab becomes visible again so that a subsequent
     hide (e.g. switching tabs) still flushes correctly. */
  var _flushed = false;

  function flushOnExit() {
    if (_flushed || !W.currentUser) return;
    _flushed = true;                         // REC-02: one flush per hide event
    clearTimeout(_saveTimer);
    try {
      var body = JSON.stringify({ baseVersion: W.__erpVersion, data: W.DB });

      // sendBeacon() silently drops payloads over ~64KB (no error, no
      // retry) — which reproduces the exact "vanishes on exit" bug this
      // file exists to
      // prevent. fetch(..., {keepalive:true}) survives page unload too,
      // but *does* support headers and has a much higher size ceiling,
      // so it is now the only path — sendBeacon is not used at all.
      fetch(apiUrl() + '?action=save', {
        method: 'POST',
        credentials: 'include',
        keepalive: true,
        headers: csrfHeaders({ 'Content-Type': 'application/json' }),
        body: body
      }).catch(function () {});
    } catch (e) {}
  }

  W.addEventListener('pagehide', flushOnExit);
  W.addEventListener('beforeunload', flushOnExit);
  document.addEventListener('visibilitychange', function () {
    if (document.hidden) {
      flushOnExit();
    } else {
      _flushed = false;  // REC-02: reset guard when tab becomes visible again
    }
  });

  // ── Seize permanent ownership of saveDB / saveDBNow ONLY ──────────────
  // loadDataFromServer is intentionally left alone \u2014 see header comment.
  var _discardedLater; // intentionally unused; documents intent
  Object.defineProperty(W, 'saveDB', {
    configurable: true,
    get: function () { return debouncedSave; },
    set: function (v) { _discardedLater = v; }
  });
  Object.defineProperty(W, 'saveDBNow', {
    configurable: true,
    get: function () { return realSaveNow; },
    set: function (v) { _discardedLater = v; }
  });

  console.info('[ayan-final-save-authority] active \u2014 saveDB/saveDBNow are now the sole api.php-backed implementations.');
})();
</script>


