<!-- 1. PRINT FIX PACK (Multi-product support & safe print lifecycle scaling) -->
<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-print-fix-pack">
(function() {
  'use strict';
  console.log('[ayan-print-fix-pack] Initializing print engine enhancements...');

  // Multi-item normalizer for transactions
  function getTxItems(tx) {
    if (!tx) return [];
    if (Array.isArray(tx.items) && tx.items.length > 0) return tx.items;
    if (Array.isArray(tx.products) && tx.products.length > 0) return tx.products;
    var singleName = tx.prod || tx.product || tx.item || tx.productName || tx.product_name || 'N/A';
    var singleQty = Number(tx.qty || tx.quantity || tx.bag || tx.bags || 0);
    var singleRate = Number(tx.rate || tx.unit_price || tx.price || 0);
    var singleTotal = Number(tx.total || tx.amount || (singleQty * singleRate) || 0);
    return [{
      name: singleName,
      qty: singleQty,
      rate: singleRate,
      total: singleTotal,
      unit: tx.unit || 'Bag'
    }];
  }

  // Safe Print Scaling using beforeprint/afterprint lifecycle
  var origPrintFitToPage = window.printFitToPage;
  window.printFitToPage = function(targetSelector) {
    var el = document.querySelector(targetSelector || '#print-area') || document.getElementById('print-modal');
    if (!el) {
      if (typeof origPrintFitToPage === 'function') origPrintFitToPage(targetSelector);
      return;
    }
    var origTransform = el.style.transform;
    var origTransformOrigin = el.style.transformOrigin;
    var origWidth = el.style.width;

    var elWidth = el.scrollWidth || el.offsetWidth;
    var printableWidth = 750; // standard printable content width px
    if (elWidth > printableWidth) {
      var scale = printableWidth / elWidth;
      el.style.transformOrigin = 'top left';
      el.style.transform = 'scale(' + scale + ')';
      el.style.width = (100 / scale) + '%';
    }

    var cleanup = function() {
      el.style.transform = origTransform || '';
      el.style.transformOrigin = origTransformOrigin || '';
      el.style.width = origWidth || '';
      window.removeEventListener('afterprint', cleanup);
    };
    window.addEventListener('afterprint', cleanup);
  };

  // Wrap printSalesInvoice
  var origPrintSalesInvoice = window.printSalesInvoice;
  window.printSalesInvoice = function(txOrId) {
    var tx = typeof txOrId === 'object' ? txOrId : (window.DB && window.DB.txs ? window.DB.txs.find(function(t){ return String(t.id) === String(txOrId); }) : null);
    if (!tx && typeof origPrintSalesInvoice === 'function') {
      return origPrintSalesInvoice(txOrId);
    }
    if (tx) {
      tx._renderedItems = getTxItems(tx);
    }
    if (typeof origPrintSalesInvoice === 'function') {
      var res = origPrintSalesInvoice(tx || txOrId);
      renderMultiProductTableInModal('#print-area, #print-modal', tx);
      return res;
    }
  };

  // Wrap printPurchaseOrder
  var origPrintPurchaseOrder = window.printPurchaseOrder;
  window.printPurchaseOrder = function(txOrId) {
    var tx = typeof txOrId === 'object' ? txOrId : (window.DB && window.DB.txs ? window.DB.txs.find(function(t){ return String(t.id) === String(txOrId); }) : null);
    if (tx) {
      tx._renderedItems = getTxItems(tx);
    }
    if (typeof origPrintPurchaseOrder === 'function') {
      var res = origPrintPurchaseOrder(tx || txOrId);
      renderMultiProductTableInModal('#print-area, #print-modal', tx);
      return res;
    }
  };

  // Wrap printVoucher
  var origPrintVoucher = window.printVoucher;
  window.printVoucher = function(txOrId) {
    var tx = typeof txOrId === 'object' ? txOrId : (window.DB && window.DB.txs ? window.DB.txs.find(function(t){ return String(t.id) === String(txOrId); }) : null);
    if (tx) {
      tx._renderedItems = getTxItems(tx);
    }
    if (typeof origPrintVoucher === 'function') {
      var res = origPrintVoucher(tx || txOrId);
      renderMultiProductTableInModal('#print-area, #print-modal', tx);
      return res;
    }
  };

  function renderMultiProductTableInModal(modalSelector, tx) {
    if (!tx || !tx._renderedItems || tx._renderedItems.length <= 1) return;
    var container = document.querySelector(modalSelector);
    if (!container) return;
    var tbody = container.querySelector('table tbody');
    if (!tbody) return;

    var rowsHtml = '';
    var totalAmount = 0;
    var totalQty = 0;
    tx._renderedItems.forEach(function(item, idx) {
      var amt = item.total || (item.qty * item.rate) || 0;
      totalAmount += amt;
      totalQty += (item.qty || 0);
      rowsHtml += '<tr>' +
        '<td style="padding:6px; border:1px solid #ddd; text-align:center;">' + (idx + 1) + '</td>' +
        '<td style="padding:6px; border:1px solid #ddd;">' + (item.name || item.product || 'N/A') + '</td>' +
        '<td style="padding:6px; border:1px solid #ddd; text-align:right;">' + (item.qty || 0) + ' ' + (item.unit || '') + '</td>' +
        '<td style="padding:6px; border:1px solid #ddd; text-align:right;">' + (item.rate || 0).toLocaleString() + '</td>' +
        '<td style="padding:6px; border:1px solid #ddd; text-align:right;">' + amt.toLocaleString() + '</td>' +
      '</tr>';
    });

    tbody.innerHTML = rowsHtml;
  }
})();
</script>

<!-- 2. PARTY CLEANUP PACK (Data normalization for Customers, Suppliers, Partners) -->
<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-party-cleanup-pack">
(function() {
  'use strict';
  console.log('[ayan-party-cleanup-pack] Initializing canonical party normalizer...');

  var CANONICAL_CUSTOMERS = [
    'Karima', 'Suborna', 'Sorna', 'Saven',
    'Desh', 'Progati', 'Rashid Oil', 'Local'
  ];

  var CANONICAL_PARTNERS = [
    'Md. Rafiqul Islam', 'Mr. Soleman', 'Mst. Sathi'
  ];

  function normalizeName(n) {
    return String(n || '').trim().toLowerCase();
  }

  function matchesAny(name, list) {
    var norm = normalizeName(name);
    return list.some(function(item) {
      return normalizeName(item) === norm;
    });
  }

  function findCanonicalMatch(name, list) {
    var norm = normalizeName(name);
    for (var i = 0; i < list.length; i++) {
      if (normalizeName(list[i]) === norm) return list[i];
    }
    return name;
  }

  window.normalizePartyClassifications = function(opts) {
    opts = opts || {};
    if (!window.DB) return { success: false, reason: 'No DB available' };

    var customers = Array.isArray(window.DB.customers) ? window.DB.customers : [];
    var suppliers = Array.isArray(window.DB.suppliers) ? window.DB.suppliers : [];
    var partners = Array.isArray(window.DB.partners) ? window.DB.partners : [];

    var allParties = [];
    var seenMap = {};

    function addParty(p, fallbackType) {
      if (!p || !p.name) return;
      var key = normalizeName(p.name);
      if (!seenMap[key]) {
        seenMap[key] = Object.assign({}, p, { type: p.type || fallbackType });
        allParties.push(seenMap[key]);
      } else {
        if (p.balance !== undefined && seenMap[key].balance === undefined) {
          seenMap[key].balance = p.balance;
        }
        if (p.phone && !seenMap[key].phone) seenMap[key].phone = p.phone;
      }
    }

    customers.forEach(function(c) { addParty(c, 'Customer'); });
    suppliers.forEach(function(s) { addParty(s, 'Supplier'); });
    partners.forEach(function(pt) { addParty(pt, 'Partner'); });

    var newCustomers = [];
    var newSuppliers = [];
    var newPartners = [];

    allParties.forEach(function(party) {
      var name = party.name;
      if (matchesAny(name, CANONICAL_CUSTOMERS)) {
        party.type = 'Customer';
        party.name = findCanonicalMatch(name, CANONICAL_CUSTOMERS);
        newCustomers.push(party);
      } else if (matchesAny(name, CANONICAL_PARTNERS)) {
        party.type = 'Partner';
        party.name = findCanonicalMatch(name, CANONICAL_PARTNERS);
        newPartners.push(party);
      } else {
        party.type = 'Supplier';
        newSuppliers.push(party);
      }
    });

    // Ensure all 8 canonical customers exist
    CANONICAL_CUSTOMERS.forEach(function(reqName) {
      if (!matchesAny(reqName, newCustomers)) {
        newCustomers.push({ id: 'c_' + Date.now() + '_' + Math.floor(Math.random()*1000), name: reqName, type: 'Customer', balance: 0 });
      }
    });

    // Ensure all 3 canonical partners exist
    CANONICAL_PARTNERS.forEach(function(reqName) {
      if (!matchesAny(reqName, newPartners)) {
        newPartners.push({ id: 'pt_' + Date.now() + '_' + Math.floor(Math.random()*1000), name: reqName, type: 'Partner', balance: 0 });
      }
    });

    window.DB.customers = newCustomers;
    window.DB.suppliers = newSuppliers;
    window.DB.partners = newPartners;

    if (typeof window.rebuildPartiesAlias === 'function') {
      window.rebuildPartiesAlias();
    }

    console.log('[ayan-party-cleanup-pack] Normalization complete. Customers:', newCustomers.length, 'Partners:', newPartners.length, 'Suppliers:', newSuppliers.length);

    if (opts.save && typeof window.saveDB === 'function') {
      window.saveDB();
    }

    if (typeof window.renderPartyTable === 'function') {
      window.renderPartyTable();
    }

    return {
      success: true,
      counts: {
        customers: newCustomers.length,
        partners: newPartners.length,
        suppliers: newSuppliers.length
      }
    };
  };

  // Hook into loadDataFromServer
  var origLoadData = window.loadDataFromServer;
  window.loadDataFromServer = function() {
    var p = typeof origLoadData === 'function' ? origLoadData.apply(this, arguments) : null;
    if (p && typeof p.then === 'function') {
      return p.then(function(res) {
        window.normalizePartyClassifications({ save: false });
        return res;
      });
    } else {
      window.normalizePartyClassifications({ save: false });
      return p;
    }
  };

  // Run initial check on ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', function() {
      setTimeout(function() { window.normalizePartyClassifications({ save: false }); }, 500);
    });
  } else {
    setTimeout(function() { window.normalizePartyClassifications({ save: false }); }, 500);
  }
})();
</script>

<!-- 3. UX PARTIES STAGE 1 (Dedicated Sidebar Sections & Details View) -->
<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-ux-parties-stage1">
(function() {
  'use strict';
  console.log('[ayan-ux-parties-stage1] Initializing dedicated party navigation & details...');

  window.openPartySection = function(type, action) {
    if (typeof window.showPage === 'function') {
      window.showPage('pg-customers');
    }
    if (typeof window.setPartyTab === 'function') {
      window.setPartyTab(type);
    }
    if (action === 'quick-add') {
      setTimeout(function() {
        if (typeof window.openPartyPanel === 'function') {
          window.openPartyPanel(type);
        } else {
          var btn = document.querySelector('#cust-add-btn, [onclick*="openPartyPanel"]');
          if (btn) btn.click();
        }
      }, 100);
    }
    if (window.AyanBulk && typeof window.AyanBulk.scan === 'function') {
      setTimeout(function() { window.AyanBulk.scan(); }, 300);
    }
  };

  window.openPartyDetails = function(partyName) {
    if (!partyName || !window.DB) return;
    var all = (window.DB.parties || []).concat(window.DB.customers || []).concat(window.DB.suppliers || []).concat(window.DB.partners || []);
    var party = all.find(function(p) { return p && p.name === partyName; }) || { name: partyName, type: 'Party', balance: 0 };

    var txs = Array.isArray(window.DB.txs) ? window.DB.txs.filter(function(t) {
      return t.party === partyName || t.customer === partyName || t.supplier === partyName || t.partyName === partyName;
    }).slice(-15).reverse() : [];

    var modalId = 'ayan-party-details-modal';
    var modal = document.getElementById(modalId);
    if (!modal) {
      modal = document.createElement('div');
      modal.id = modalId;
      modal.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.5);z-index:99999;display:flex;align-items:center;justify-content:center;padding:16px;box-sizing:border-box;';
      document.body.appendChild(modal);
    }

    var txRows = txs.map(function(t) {
      return '<tr style="border-bottom:1px solid #eee;">' +
        '<td style="padding:6px;">' + (t.date || '') + '</td>' +
        '<td style="padding:6px;"><span class="badge" style="background:#eef2ff;color:#4338ca;padding:2px 6px;border-radius:4px;font-size:11px;">' + (t.type || 'Tx') + '</span></td>' +
        '<td style="padding:6px;text-align:right;">' + (Number(t.amount || t.total || 0)).toLocaleString() + '</td>' +
      '</tr>';
    }).join('') || '<tr><td colspan="3" style="padding:12px;text-align:center;color:#888;">No recent transactions found</td></tr>';

    var balColor = (party.balance || 0) > 0 ? '#b91c1c' : ((party.balance || 0) < 0 ? '#047857' : '#374151');

    modal.innerHTML = 
      '<div style="background:#fff;border-radius:8px;max-width:550px;width:100%;max-height:90vh;overflow-y:auto;padding:20px;box-shadow:0 20px 25px -5px rgba(0,0,0,0.1);position:relative;font-family:inherit;">' +
        '<div style="display:flex;justify-content:space-between;align-items:flex-start;border-bottom:1px solid #e5e7eb;padding-bottom:12px;margin-bottom:16px;">' +
          '<div>' +
            '<h3 style="margin:0;font-size:18px;font-weight:700;color:#111827;">' + (party.name) + '</h3>' +
            '<div style="margin-top:4px;"><span style="background:#e0e7ff;color:#3730a3;font-size:12px;padding:2px 8px;border-radius:12px;font-weight:600;">' + (party.type || 'Party') + '</span> ' +
            (party.phone ? '<span style="color:#6b7280;font-size:12px;margin-left:8px;">📞 ' + party.phone + '</span>' : '') + '</div>' +
          '</div>' +
          '<button type="button" data-x-click="document.getElementById(\'' + modalId + '\').style.display=\'none\'" style="background:none;border:none;font-size:20px;cursor:pointer;color:#9ca3af;line-height:1;">&times;</button>' +
        '</div>' +
        '<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:16px;background:#f9fafb;padding:12px;border-radius:6px;">' +
          '<div><div style="font-size:12px;color:#6b7280;">Current Balance</div><div style="font-size:18px;font-weight:700;color:' + balColor + ';">৳ ' + (Number(party.balance || 0)).toLocaleString() + '</div></div>' +
          '<div><div style="font-size:12px;color:#6b7280;">Party ID</div><div style="font-size:14px;font-weight:600;color:#374151;">' + (party.id || 'N/A') + '</div></div>' +
        '</div>' +
        '<h4 style="margin:0 0 8px 0;font-size:14px;font-weight:600;color:#374151;">Recent Transactions</h4>' +
        '<div style="max-height:220px;overflow-y:auto;border:1px solid #e5e7eb;border-radius:6px;">' +
          '<table style="width:100%;border-collapse:collapse;font-size:12px;text-align:left;">' +
            '<thead style="background:#f3f4f6;position:sticky;top:0;">' +
              '<tr><th style="padding:6px;">Date</th><th style="padding:6px;">Type</th><th style="padding:6px;text-align:right;">Amount (৳)</th></tr>' +
            '</thead>' +
            '<tbody>' + txRows + '</tbody>' +
          '</table>' +
        '</div>' +
        '<div style="margin-top:16px;text-align:right;">' +
          '<button type="button" data-x-click="document.getElementById(\'' + modalId + '\').style.display=\'none\'" style="padding:6px 14px;border-radius:6px;border:1px solid #d1d5db;background:#fff;cursor:pointer;font-size:13px;">Close</button>' +
        '</div>' +
      '</div>';

    modal.style.display = 'flex';
  };

  function injectPartyNav() {
    var sidebar = document.querySelector('.sidebar, nav, #sidebar, .main-nav');
    if (!sidebar) return;
    if (document.getElementById('ayan-dedicated-party-nav')) return;

    var navHtml = document.createElement('div');
    navHtml.id = 'ayan-dedicated-party-nav';
    navHtml.innerHTML = 
      '<div style="margin:10px 0;border-top:1px solid rgba(255,255,255,0.1);padding-top:8px;">' +
        '<div style="padding:4px 12px;font-size:11px;text-transform:uppercase;letter-spacing:0.05em;color:#94a3b8;font-weight:700;">Party Management</div>' +
        '<div style="display:flex;flex-direction:column;gap:2px;padding:0 8px;">' +
          '<button type="button" data-x-click="window.openPartySection(\'Customer\')" class="nav-item-btn" style="display:flex;align-items:center;gap:8px;padding:7px 10px;background:none;border:none;color:#e2e8f0;font-size:13px;cursor:pointer;border-radius:6px;text-align:left;width:100%;">' +
            '<span>👥</span> <span>Customers</span>' +
          '</button>' +
          '<button type="button" data-x-click="window.openPartySection(\'Supplier\')" class="nav-item-btn" style="display:flex;align-items:center;gap:8px;padding:7px 10px;background:none;border:none;color:#e2e8f0;font-size:13px;cursor:pointer;border-radius:6px;text-align:left;width:100%;">' +
            '<span>🏭</span> <span>Suppliers</span>' +
          '</button>' +
          '<button type="button" data-x-click="window.openPartySection(\'Partner\')" class="nav-item-btn" style="display:flex;align-items:center;gap:8px;padding:7px 10px;background:none;border:none;color:#e2e8f0;font-size:13px;cursor:pointer;border-radius:6px;text-align:left;width:100%;">' +
            '<span>🤝</span> <span>Partners</span>' +
          '</button>' +
        '</div>' +
      '</div>';

    var targetSection = sidebar.querySelector('.nav-section, [data-nav-section="parties"]') || sidebar.firstChild;
    if (targetSection && targetSection.parentNode) {
      targetSection.parentNode.insertBefore(navHtml, targetSection.nextSibling);
    } else {
      sidebar.appendChild(navHtml);
    }
  }

  // Row click delegation for party details
  document.addEventListener('click', function(e) {
    var tr = e.target.closest('#t-cust tr, .party-table tbody tr');
    if (!tr) return;
    if (e.target.closest('button, input, select, a, .action-btn')) return;
    var nameCell = tr.querySelector('td.cust-name, td:nth-child(2)');
    if (nameCell && nameCell.textContent) {
      var name = nameCell.textContent.trim().replace(/^👤|👥|🏭|🤝\s*/, '');
      if (name) window.openPartyDetails(name);
    }
  });

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', injectPartyNav);
  } else {
    injectPartyNav();
  }
})();
</script>

<!-- 4. UX PARTIES STAGE 2 (Responsive Breakpoints, Filter Chips & Universal Bulk Sync) -->
<style id="ayan-ux-parties-stage2-css">
@media (max-width: 768px) {
  #pg-customers .page-header {
    flex-direction: column !important;
    align-items: stretch !important;
    gap: 8px !important;
  }
  #pg-customers .party-tab-bar, #pg-customers .nav-tabs {
    display: flex !important;
    overflow-x: auto !important;
    white-space: nowrap !important;
    -webkit-overflow-scrolling: touch;
    padding-bottom: 4px;
  }
  #pg-customers .kpi-cards, #pg-customers .stats-grid {
    grid-template-columns: 1fr 1fr !important;
    gap: 8px !important;
  }
  #pg-customers .table-responsive {
    overflow-x: auto !important;
    -webkit-overflow-scrolling: touch;
  }
  #pg-customers table th:nth-child(4),
  #pg-customers table td:nth-child(4),
  #pg-customers table th:nth-child(5),
  #pg-customers table td:nth-child(5) {
    display: none;
  }
  .ayan-filter-chips {
    display: flex;
    gap: 6px;
    overflow-x: auto;
    padding: 6px 0;
  }
  .ayan-filter-chip {
    padding: 4px 10px;
    border-radius: 16px;
    font-size: 12px;
    background: #f1f5f9;
    border: 1px solid #cbd5e1;
    cursor: pointer;
    white-space: nowrap;
  }
  .ayan-filter-chip.active {
    background: #3b82f6;
    color: #fff;
    border-color: #2563eb;
  }
}
</style>

<script nonce="<?php echo $cspNonceAttr; ?>" id="ayan-ux-parties-stage2">
(function() {
  'use strict';
  console.log('[ayan-ux-parties-stage2] Initializing responsive filters & universal bulk hooks...');

  function injectFilterChips() {
    var host = document.querySelector('#pg-customers .party-controls, #pg-customers .filter-bar, #pg-customers .page-actions');
    if (!host || document.getElementById('ayan-party-filter-chips')) return;

    var container = document.createElement('div');
    container.id = 'ayan-party-filter-chips';
    container.className = 'ayan-filter-chips';
    container.style.cssText = 'display:flex;gap:6px;margin:8px 0;flex-wrap:wrap;';

    var filters = [
      { label: 'All', value: 'all' },
      { label: 'Has Due', value: 'due' },
      { label: 'Advance', value: 'advance' },
      { label: 'Zero Balance', value: 'zero' }
    ];

    filters.forEach(function(f, idx) {
      var btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'ayan-filter-chip' + (idx === 0 ? ' active' : '');
      btn.textContent = f.label;
      btn.onclick = function() {
        container.querySelectorAll('.ayan-filter-chip').forEach(function(el) { el.classList.remove('active'); });
        btn.classList.add('active');
        applyPartyBalanceFilter(f.value);
      };
      container.appendChild(btn);
    });

    host.appendChild(container);
  }

  function applyPartyBalanceFilter(filterType) {
    var select = document.querySelector('#cust-bal-filter, select[name="balanceFilter"]');
    if (select) {
      select.value = filterType;
      select.dispatchEvent(new Event('change'));
    } else {
      var rows = document.querySelectorAll('#t-cust tbody tr, .party-table tbody tr');
      rows.forEach(function(row) {
        var balText = row.querySelector('td.cust-bal, td:nth-child(3)');
        if (!balText) return;
        var bal = parseFloat(balText.textContent.replace(/[^0-9.-]/g, '')) || 0;
        var show = true;
        if (filterType === 'due') show = bal > 0;
        else if (filterType === 'advance') show = bal < 0;
        else if (filterType === 'zero') show = bal === 0;
        row.style.display = show ? '' : 'none';
      });
    }

    if (window.AyanBulk && typeof window.AyanBulk.scan === 'function') {
      window.AyanBulk.scan();
    }
  }

  // Hook into setPartyTab to keep bulk selection refreshed
  var origSetPartyTab = window.setPartyTab;
  if (typeof origSetPartyTab === 'function') {
    window.setPartyTab = function(type) {
      var res = origSetPartyTab.apply(this, arguments);
      setTimeout(function() {
        if (window.AyanBulk && typeof window.AyanBulk.scan === 'function') {
          window.AyanBulk.scan();
        }
      }, 150);
      return res;
    };
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', injectFilterChips);
  } else {
    injectFilterChips();
  }
})();
</script>


